local Text_AvgDialog = readonly({
  AvgDialog_100303_Content_1 = {
    Text = "Huff... huff... Não, não é isso... algo ainda parece estranho..."
  },
  AvgDialog_100303_Content_10 = {
    Text = "Por que está bem na minha frente, ainda assim não consigo encontrar..."
  },
  AvgDialog_100303_Content_11 = {
    Text = "Não se preocupe, Pikman. Como a Musa já lhe disse, a resposta deve estar muito próxima de você. Pense bem, o que mais você pode ter esquecido."
  },
  AvgDialog_100303_Content_12 = {
    Text = "Antes disso, levante-se... Sss..."
  },
  AvgDialog_100303_Content_13 = {
    Text = "Você rapidamente retirou a mão que queria usar para ajudá-lo a se levantar. Seu corpo ardente parecia estar fluindo como se estivesse cheio de magma."
  },
  AvgDialog_100303_Content_14 = {
    Text = "Como esperado, é Thais causando problemas novamente..."
  },
  AvgDialog_100303_Content_15 = {
    Text = "Thais... Ah! Certo! Como eu não pensei nisso! Como eu pude ignorar!!"
  },
  AvgDialog_100303_Content_16 = {
    Text = "Ele se levantou de repente, seus olhos que quase queimavam você o encarando fixamente."
  },
  AvgDialog_100303_Content_17 = {
    Text = "O desejo mais louco... Isso mesmo! Eu entendi, eu entendi..."
  },
  AvgDialog_100303_Content_18 = {
    Text = "Ele estava tão empolgado que esqueceu até de se levantar, usando as mãos e os pés para rastejar até você."
  },
  AvgDialog_100303_Content_19 = {
    Text = "Guardião, você pode ser meu modelo mais uma vez? Só uma vez! Apenas uma vez!"
  },
  AvgDialog_100303_Content_2 = {Text = "Pickman?"},
  AvgDialog_100303_Content_20 = {
    Text = "Eu sei o que você quer fazer, de jeito nenhum..."
  },
  AvgDialog_100303_Content_21 = {
    Text = "Os olhos vermelhos de Pickman, cheios de ansiedade e súplica, brilhavam levemente sob a luz escura. As palavras de recusa não conseguiam mais sair."
  },
  AvgDialog_100303_Content_22 = {
    Text = "... Tudo bem. Se for apenas ser modelo, eu ainda posso sentar naquele sofá?"
  },
  AvgDialog_100303_Content_23 = {
    Text = "Não, não, não, Guardião! Como você pode criar uma pintura como esta no estúdio?!"
  },
  AvgDialog_100303_Content_24 = {Text = "..."},
  AvgDialog_100303_Content_25 = {
    Text = "É isso... o mundo na sua pintura?"
  },
  AvgDialog_100303_Content_26 = {
    Text = "Isso mesmo! É o ritual do carnaval dos ghouls!"
  },
  AvgDialog_100303_Content_27 = {
    Text = "Eu o criei, mas nunca o terminei. Ele carece de um par de protagonistas em seu centro. Eles representam os desejos mais primitivos e selvagens deste universo, os desejos que eu esqueci..."
  },
  AvgDialog_100303_Content_28 = {
    Text = "Até agora, não encontrei um modelo suficiente para me tornar o protagonista..."
  },
  AvgDialog_100303_Content_29 = {
    Text = "Pikman ainda mantém a posição de joelhos, arrastando os joelhos em sua direção."
  },
  AvgDialog_100303_Content_3 = {
    Text = "O ateliê sombrio de Pikman está mais desordenado do que nunca, com inúmeros papéis de couro preenchidos com cores e linhas espalhados desordenadamente por todos os cantos do estúdio, como se tivesse acabado de passar por uma estranha guerra."
  },
  AvgDialog_100303_Content_30 = {
    Text = "Por favor, Guardião... conceda-me a Musa!"
  },
  AvgDialog_100303_Content_31 = {
    Text = "Você pode me pedir qualquer coisa! Uma vez, só uma vez! Por favor, me leve para completar esta pintura..."
  },
  AvgDialog_100303_Content_32 = {
    Text = "Sem hesitar por muito tempo, você suspirou levemente e se aproximou dele."
  },
  AvgDialog_100303_Content_33 = {
    Text = "Ele levantou a cabeça, arregalando os olhos para você. Eram olhos que pertenciam a uma besta ou a um animal de estimação, gananciosos, desejosos, obedientes e leais. Ele estava implorando, implorando por uma ordem que o levasse à musa."
  },
  AvgDialog_100303_Content_34 = {
    Text = "Posso fazer qualquer coisa... Então, preciso pensar bem..."
  },
  AvgDialog_100303_Content_35 = {
    Text = "Sua mão repousa suavemente no rosto de Pickman. A respiração ardente e o corpo se tornam submissos. Não se sabe se você está domando-o ou se ele está derretendo você."
  },
  AvgDialog_100303_Content_36 = {
    Text = "As vozes dos ghouls começaram a desaparecer, enquanto os sons rudes e primitivos deste par de protagonistas preenchiam todo o mundo da imagem."
  },
  AvgDialog_100303_Content_37 = {
    Text = "Essa é a voz da Musa."
  },
  AvgDialog_100303_Content_4 = {
    Text = "Ele, com roupas desordenadas, estava de joelhos, esfregando freneticamente em uma folha em branco, quase rasgando o papel. A tinta respingada cobria seu corpo, como um devoto realizando um ritual primitivo."
  },
  AvgDialog_100303_Content_5 = {
    Text = "O que está acontecendo..."
  },
  AvgDialog_100303_Content_6 = {
    Text = "Eu ouvi, Guardião! Ouvi a voz da Musa chamando! Bem no meu ouvido!"
  },
  AvgDialog_100303_Content_7 = {
    Text = "Meus olhos, minhas mãos, meu coração, cada célula do meu corpo treme ao som disso!"
  },
  AvgDialog_100303_Content_8 = {
    Text = "Falta apenas um passo! Estou a um passo da maior arte!"
  },
  AvgDialog_100303_Content_9 = {
    Text = "Mas eu não consigo encontrar... massacre, conquista, glutonaria, ganância, gastar em excesso, vazio... Eu tracei toda a loucura, mas ainda não a encontrei..."
  },
  AvgDialog_100588_Content_1 = {
    Text = "Uma figura escura aparece gradualmente diante de você."
  },
  AvgDialog_100588_Content_2 = {
    Text = "[Ataque]???"
  },
  AvgDialog_100588_Content_3 = {
    Text = "Você causou 677 pontos de dano! Você acha que já causou um total de 27.188 pontos de dano a Ele. \n Todos causaram um total de 14.636.643.707 pontos de dano a Ele, mas Ele ainda não caiu."
  },
  AvgDialog_100588_Content_4 = {
    Text = "[Continuar]"
  },
  AvgDialog_100588_Content_5 = {
    Text = "Você sente que já esteve aqui antes…\n Sob o olhar da sombra, sua consciência vai se tornando gradualmente turva."
  },
  AvgDialog_100588_Content_6 = {Text = "[sono]"},
  AvgDialog_100629_Content_1 = {
    Text = "Em pouco tempo, este mundo não será mais atormentado pela corrosão, a humanidade se desenvolverá rapidamente, e depois a Universidade de Mythag interceptará um trem sob as estrelas..."
  },
  AvgDialog_10120_Content_1 = {
    Text = "Proteja seu dispositivo de comando e cuidado com a contaminação por Dissolução.\nIsso será essencial na batalha que se aproxima."
  },
  AvgDialog_10120_Content_2 = {
    Text = "Mantenha pressionado o <Yellow:Command Card> e arraste-o para a <Yellow:Central Command Zone> para emitir um comando de ação para mim."
  },
  AvgDialog_10121_Content_1 = {
    Text = "<Yellow:Prata>? Não esperava encontrá-la aqui..."
  },
  AvgDialog_10121_Content_2 = {
    Text = "Forje Chaves Pratas, conecte Despertadores e forneça energia espiritual...\nTudo em Mythag gira em torno de <Yellow:Silver>."
  },
  AvgDialog_10121_Content_3 = {
    Text = "Até mesmo uma pequena quantidade de <Yellow:Prata> possui um valor extraordinário para a pesquisa de Mythag.\nTente coletá-las todas."
  },
  AvgDialog_10122_Content_1 = {
    Text = "Prolongar isso é desvantajoso; devemos trazer isso a uma conclusão rápida."
  },
  AvgDialog_10122_Content_2 = {
    Text = "Aqui está a <Yellow:\"Espada da Rainha\"> com a qual tenho praticado desde a infância.\nVamos acabar com isso neste golpe!"
  },
  AvgDialog_10123_Content_1 = {
    Text = "Você passa pela pequena porta sob a torre do relógio e entra em um corredor oculto e fechado."
  },
  AvgDialog_10123_Content_10 = {Text = "..."},
  AvgDialog_10123_Content_11 = {
    Text = "A porta se abre lentamente, revelando pela primeira vez a cena do lugar proibido"
  },
  AvgDialog_10123_Content_13 = {
    Text = "Sua metade inferior submersa em lodo negro, a escuridão devoradora acentua sua radiante pureza, tornando-a imaculadamente branca."
  },
  AvgDialog_10123_Content_14 = {
    Text = "Em um estado de atordoamento, a figura desumana diante de você se sobrepõe sutilmente à silhueta da jovem que você viu na Tumba da Chave."
  },
  AvgDialog_10123_Content_15 = {
    Text = "Não tem rosto, mas você sente uma certa compaixão em sua postura."
  },
  AvgDialog_10123_Content_16 = {
    Text = "Supremo, Puro, Bom, Belo."
  },
  AvgDialog_10123_Content_17 = {
    Text = "<Shake:Você... chegou...>"
  },
  AvgDialog_10123_Content_18 = {
    Text = "O monstro branco emitiu um som rouco, parte rugido, parte gemido."
  },
  AvgDialog_10123_Content_19 = {
    Text = "Não é uma linguagem humana, mas você compreende o significado de suas palavras."
  },
  AvgDialog_10123_Content_2 = {
    Text = "Doll lidera o caminho à frente, seus passos ecoando vazios na superfície metálica."
  },
  AvgDialog_10123_Content_20 = {
    Text = "Tudo à sua frente de repente se torna borrado. Você pisca, e um líquido quente escorre por sua bochecha."
  },
  AvgDialog_10123_Content_21 = {
    Text = "É uma lágrima? Mas por quê? O que está fazendo seu peito se apertar e seus olhos ardendo?"
  },
  AvgDialog_10123_Content_22 = {
    Text = "......<Yellow:Tawil>?"
  },
  AvgDialog_10123_Content_23 = {
    Text = "As palavras que a Boneca murmura fazem a expressão de Ramona mudar."
  },
  AvgDialog_10123_Content_24 = {
    Text = "Tawil? A que é uma das fundadoras, a Despertadora Tawil?"
  },
  AvgDialog_10123_Content_25 = {
    Text = "Você também se lembra.\nEm <Blue:\"A História de Mythag\">, este nome aparece ao lado de outros dois"
  },
  AvgDialog_10123_Content_26 = {
    Text = "Em Alluvium 90, <Blue:Ward Phillips>, <Blue:Klararksh> e <Blue:Tawil> fundaram <Blue:Mythag College>."
  },
  AvgDialog_10123_Content_27 = {
    Text = "Isso é exatamente onde você está agora, o predecessor de <Blue:Universidade Mythag (Mythag University)>."
  },
  AvgDialog_10123_Content_28 = {Text = "Guardião."},
  AvgDialog_10123_Content_29 = {
    Text = "Estou aqui."
  },
  AvgDialog_10123_Content_3 = {
    Text = "É a primeira vez que aprendi que há uma passagem secreta sob a torre do relógio..."
  },
  AvgDialog_10123_Content_30 = {
    Text = "O fato de que você está aqui sem ser expulso por Tawil mostra que seu destino agora está inextricavelmente ligado ao futuro de Mythag."
  },
  AvgDialog_10123_Content_31 = {
    Text = "Então, você está qualificado para ouvir as informações que estou prestes a compartilhar."
  },
  AvgDialog_10123_Content_32 = {
    Text = "Este é o segredo mais profundo da Universidade Mythag.\nTawil—o fundador da Universidade Mythag—não é nem humano nem um Despertador."
  },
  AvgDialog_10123_Content_33 = {
    Text = "Ele é um ser de outra dimensão. Inicialmente, ele era apenas um sussurro ouvido pelo primeiro diretor, Phillips."
  },
  AvgDialog_10123_Content_34 = {
    Text = "Contrariamente à percepção de que \"Tawil é um Despertador\", a técnica de extração de Prata e <Yellow:Despertar os falecidos que ressoam com a Vontade Superior> surgiu sob sua orientação."
  },
  AvgDialog_10123_Content_35 = {
    Text = "Tawil profetizou a chegada da Dissolução e o futuro da Destruição do mundo, transmitindo a \"Verdade\" inicial, e adormeceu após o estabelecimento do Colégio Mythag."
  },
  AvgDialog_10123_Content_36 = {
    Text = "De acordo com o Sr. Phillips, Tawil escolheu uma forma de existência \"inexistente\" para evitar \"ser observado\"."
  },
  AvgDialog_10123_Content_37 = {
    Text = "Somente quando \"Variáveis\" aparecerem Ele renascerá na forma de \"Despertar\" —"
  },
  AvgDialog_10123_Content_38 = {Text = "Olhe!"},
  AvgDialog_10123_Content_39 = {
    Text = "Como se prenunciando a chegada de algum tabu e clãs, \"Tawil\" soltou um grito agudo que estourou tímpanos."
  },
  AvgDialog_10123_Content_4 = {
    Text = "Se todos sabem sobre isso, suponho que não possa ser chamado de passagem secreta.\nA passagem está ligada ao <Yellow:Black Pool>, a fundação de Mythag."
  },
  AvgDialog_10123_Content_40 = {
    Text = "Com um tremor semelhante a um filhote rompendo a casca, seis enormes asas prateadas se desdobraram de Seu corpo."
  },
  AvgDialog_10123_Content_41 = {
    Text = "As pontas das asas gotejam gotas prateadas, que caem no poço negro com um suave tilintar."
  },
  AvgDialog_10123_Content_42 = {
    Text = "Assim que o líquido prateado se funde na Poça Negra, ondas surgem e Corpos Dissolutos distorcidos aparecem."
  },
  AvgDialog_10123_Content_43 = {
    Text = "Os monstros deformados desafiam as leis físicas ao explodirem da piscina negra. Alguns correm em sua direção, enquanto outros se dirigem à praça do relógio"
  },
  AvgDialog_10123_Content_44 = {
    Text = "<Shake:Finalmente... encontrei... você...>"
  },
  AvgDialog_10123_Content_45 = {
    Text = "Pare-o! Somente parando-o podemos cortar a fonte dos monstros!"
  },
  AvgDialog_10123_Content_5 = {
    Text = "Sem o <Yellow:giant Silver> chamado <Yellow:Core> no fundo da Poça Negra, confiar apenas em fracas almas humanas para sustentar os Despertadores atrasaria a tecnologia do Despertador de Mythag por décadas."
  },
  AvgDialog_10123_Content_6 = {
    Text = "Então, não permitir que Despertadores sem Link deixem o Mythag é também uma preocupação de que podemos cair na loucura?"
  },
  AvgDialog_10123_Content_7 = {
    Text = "Não totalmente.\nSe ao menos todos os Despertadores fossem tão fáceis de lidar quanto você, Ogier."
  },
  AvgDialog_10123_Content_8 = {
    Text = "Certo, chegamos."
  },
  AvgDialog_10123_Content_9 = {
    Text = "Enquanto ela falava, a Boneca pressionou um botão discreto na parede lateral do corredor.\nCom um ding, a porta se abriu, e você entrou no espaço estreito e mal iluminado."
  },
  AvgDialog_10124_Content_1 = {
    Text = "Parece que você encontrou seu Estado. O próximo comando é seu, Guardião!"
  },
  AvgDialog_10125_Content_1 = {
    Text = "Ufa. Desculpe, não há tempo para você se adaptar a tudo isso adequadamente."
  },
  AvgDialog_10125_Content_10 = {
    Text = "Ramona parece aterrorizada; você nunca a viu tão perturbada."
  },
  AvgDialog_10125_Content_11 = {
    Text = "A garota, bombardeada com perguntas, fala com a voz trêmula, sua exaustão evidente."
  },
  AvgDialog_10125_Content_12 = {
    Text = "Você a reconhece. Ela é a Professora Boneca, conhecida por ser difícil de se comunicar, e pertence ao <Blue:Instituto de Pesquisa do Despertar>. Em outras palavras, ela é uma não-combatente."
  },
  AvgDialog_10125_Content_13 = {
    Text = "Obviamente. Achou que eu vim aqui para um passeio tranquilo?"
  },
  AvgDialog_10125_Content_14 = {
    Text = "Ela fecha os olhos, recompondo-se rapidamente."
  },
  AvgDialog_10125_Content_15 = {
    Text = "O Cofre de Chaves foi atacado? Este lugar está próximo à porta dos fundos; apresse-se e saia."
  },
  AvgDialog_10125_Content_16 = {
    Text = "Podemos ajudar! %player% pode Linkar todos nós e então comandar—"
  },
  AvgDialog_10125_Content_17 = {
    Text = "Ramona.\nEssas são nossas responsabilidades, %player% é apenas um novato que acaba de terminar a escola preparatória."
  },
  AvgDialog_10125_Content_18 = {
    Text = "%player% já se vinculou a mim, e eu sei que {Male=he,Female=she} está à altura da tarefa. Eu acredito em {Male=him,Female=her}!"
  },
  AvgDialog_10125_Content_19 = {
    Text = "Doll examina você atentamente, depois se vira para Ramona com uma expressão severa."
  },
  AvgDialog_10125_Content_2 = {
    Text = "Esses Mutantes chegaram à Keygrave antes do alarme soar. A <Blue:Barreira de Névoa> ao redor de Misaq deve ter caído."
  },
  AvgDialog_10125_Content_20 = {
    Text = "Se não me falha a memória, a cerimônia de juramento foi interrompida. {Male=He,Female=She} ainda não recebeu a Chave de prata de {Male=his,Female=her}, correto?"
  },
  AvgDialog_10125_Content_21 = {
    Text = "Próximo, entraremos na Zona Proibida de Mythag. A entrada não autorizada é uma ofensa grave, e eu pensei que você estivesse ciente disso, já que cresceu aqui."
  },
  AvgDialog_10125_Content_22 = {
    Text = "É uma emergência! Não temos escolha, certo? Além disso, %player% não é um calouro qualquer. {Male=He's,Female=She's} nosso único Guardião."
  },
  AvgDialog_10125_Content_23 = {
    Text = "Você não se lembra da <Yellow:Explosão de Akutê> de um ano atrás? Se não fosse por {Male=him,Female=her} ter vinculado sozinho todos os Corpos Despertos naquela época, eu não estaria aqui tendo esta discussão com você agora."
  },
  AvgDialog_10125_Content_24 = {
    Text = "A garota de cabelo rosa não responde e, em vez disso, se vira para você."
  },
  AvgDialog_10125_Content_25 = {
    Text = "Eu sei que você vislumbrou o que existe além da <Yellow:Porta>; mas a realidade, seja a fundação de Misaq ou o destino do mundo, pode não ser como você idealiza."
  },
  AvgDialog_10125_Content_26 = {
    Text = "Enfrentamos um fenômeno que destrói a própria existência material. Uma vez que você é contaminado por <Yellow:Dissolução>, tudo sobre você desaparecerá."
  },
  AvgDialog_10125_Content_27 = {
    Text = "O nome que você gravou na lápide durante a cerimônia de juramento também se dissolverá em uma poça de lama negra, esquecido por todos."
  },
  AvgDialog_10125_Content_28 = {
    Text = "Responda-me. Você está realmente pronta para isso?"
  },
  AvgDialog_10125_Content_29 = {
    Text = "O olhar gélido de Doll encontra o seu, sua voz inexpressiva."
  },
  AvgDialog_10125_Content_3 = {
    Text = "Informamos <Blue:William, o companheiro mais velho> sobre a cerimônia de hoje, mas nenhum reforço veio em nosso auxílio. O sino... devemos nos reagrupar e <Yellow:eliminar a fonte da anomalia>!"
  },
  AvgDialog_10125_Content_30 = {
    Text = "Seu rosto não revela nada, mas no fundo de suas pupilas gélidas, você vislumbra um fogo ardente."
  },
  AvgDialog_10125_Content_31 = {
    Text = "Sua resposta é—"
  },
  AvgDialog_10125_Content_32 = {
    Text = "Minha lápide agora faz parte da Keygrave."
  },
  AvgDialog_10125_Content_33 = {
    Text = "Você é membro da Misaq. Talvez já fosse desde Akutê."
  },
  AvgDialog_10125_Content_34 = {
    Text = "Há coisas que só eu posso realizar."
  },
  AvgDialog_10125_Content_35 = {
    Text = "A decisão pode ser precipitada, mas alguém pode realmente estar preparado para tudo na vida?"
  },
  AvgDialog_10125_Content_36 = {Text = "Bom."},
  AvgDialog_10125_Content_37 = {
    Text = "Pela autoridade do 6º Diretor da Misaq, <Blue:Oliver Elsie>, eu confiro a você a Chave de prata K-0617."
  },
  AvgDialog_10125_Content_39 = {
    Text = "Doll retira a Chave de prata de um estojo ornamentado, colocando-a sobre seu peito. Ela brilha suavemente, inundando você com uma vaga sensação de familiaridade."
  },
  AvgDialog_10125_Content_4 = {Text = "É...?!"},
  AvgDialog_10125_Content_40 = {
    Text = "De agora em diante, você se ergue como Guardião entre a miríade de estudantes e acadêmicos da Misaq."
  },
  AvgDialog_10125_Content_41 = {Text = "..."},
  AvgDialog_10125_Content_42 = {
    Text = "Agora, estabeleça um vínculo comigo."
  },
  AvgDialog_10125_Content_43 = {
    Text = "Você ativa cautelosamente a chave de prata.\nA luz prateada pisca, e o vínculo espiritual conecta seus sentidos com os de Doll como milhares de fios invisíveis."
  },
  AvgDialog_10125_Content_44 = {
    Text = "Como se uma corrente elétrica conectasse com um \"estalo\", incontáveis mensagens de luz e sombra inundaram sua mente.\nAbalado por palpitações intensas, você mal consegue ficar em pé."
  },
  AvgDialog_10125_Content_45 = {
    Text = "Doll, você..."
  },
  AvgDialog_10125_Content_46 = {
    Text = "Você chegou bem a tempo, Guardião.\nTanto Ogier quanto eu estamos no nosso limite."
  },
  AvgDialog_10125_Content_47 = {
    Text = "Você fica aqui e descansa. Ramona e eu iremos nos juntar à batalha para apoiar Ogier."
  },
  AvgDialog_10125_Content_48 = {
    Text = "Calma. Mesmo que seu espírito consiga aguentar, as lesões de Ramona não são adequadas para uma batalha imediata."
  },
  AvgDialog_10125_Content_49 = {
    Text = "A criança pode aguentar por um tempo. Siga-me primeiro."
  },
  AvgDialog_10125_Content_6 = {
    Text = "Na periferia da sua visão, um jovem loiro ergue um enorme escudo negro, mal conseguindo se defender do ataque de uma espadachim que empunha duas lâminas."
  },
  AvgDialog_10125_Content_7 = {
    Text = "Ele protege uma garota de cabelo rosa atrás de si, cada ataque deflectido o empurrando mais um passo para trás."
  },
  AvgDialog_10125_Content_8 = {
    Text = "Espere... aquele que está lançando o ataque... é <Yellow:Despertador> Lotan?!"
  },
  AvgDialog_10125_Content_9 = {
    Text = "Doll? A <Blue:Torre do Relógio> foi comprometida?!"
  },
  AvgDialog_10126_Content_1 = {
    Text = "Quando a Vida cai para 0, o Poder espiritual lutará para sustentar o instrumento na detecção contínua do <Yellow:Domain>. Para garantir a segurança do pessoal de combate, o instrumento o puxará forçosamente para fora da batalha."
  },
  AvgDialog_10126_Content_2 = {
    Text = "A situação é urgente. Ajustei a saída de potência do dispositivo com base nos sinais vitais saudáveis do Guardião e uma carga completa de Aliemus."
  },
  AvgDialog_10126_Content_3 = {
    Text = "Esse método é extremamente perigoso, mas não temos escolha a não ser correr o risco. Agora, use Exaltar para acabar com esta batalha!"
  },
  AvgDialog_10127_Content_1 = {
    Text = "Que calor... a conexão é perfeita. O seu espírito e a sua força vital nunca brilharam tanto."
  },
  AvgDialog_10127_Content_2 = {
    Text = "Você não pode cair facilmente, <Yellow:o único e inigualável no mundo> Guardião.\nEstamos contando com você para investigar e documentar toda a história apagada pela Dissolução."
  },
  AvgDialog_10127_Content_3 = {
    Text = "A preocupação nos olhos dela desvanece enquanto Ramona oferece um meio sorriso reconfortante."
  },
  AvgDialog_10127_Content_4 = {
    Text = "O som da chuva fina preenche o mundo."
  },
  AvgDialog_10127_Content_5 = {
    Text = "<Red:Desassossego, Dor, Sufocação> preencheram meu peito quando uma gota de chuva caiu."
  },
  AvgDialog_10127_Content_7 = {Text = "Ramona!"},
  AvgDialog_10127_Content_9 = {
    Text = "A campainha toca."
  },
  AvgDialog_10128_Content_1 = {
    Text = "Cuidado, o oponente entrou em uma forte postura ofensiva!"
  },
  AvgDialog_10128_Content_2 = {
    Text = "Do que você tem medo? Eu ainda estou aqui.\nGuardião, deixe-me realizar <Yellow:\"Cirurgia Externa\">."
  },
  AvgDialog_10129_Content_1 = {
    Text = "Ativar a Chave de Prata, %player%."
  },
  AvgDialog_10129_Content_2 = {
    Text = "A Chave Prata pisca, e uma visão fugaz aparece de repente, fundindo-se gradualmente com a realidade diante dos olhos."
  },
  AvgDialog_10129_Content_3 = {
    Text = "Tontura, pensamentos turvos, uma sirene a gritar na cabeça, e a voz da Boneca começou a desvanecer..."
  },
  AvgDialog_10129_Content_4 = {
    Text = "Você luta para acalmar sua mente, discernindo as informações fornecidas pela Boneca entre o falatório caótico."
  },
  AvgDialog_10129_Content_5 = {
    Text = "Vê? À sua frente está o Domínio—uma área especial formada pela <Yellow:Dimensão do Sonho> e <Yellow:Dimensão da Realidade>."
  },
  AvgDialog_10129_Content_6 = {
    Text = "Mythag projetou parte de <Blue:Junção> no Domínio para estabilizar as mentes cada vez mais insanas dos Investigadores e curar os Despertadores."
  },
  AvgDialog_10129_Content_7 = {
    Text = "No entanto, a interferência humana tem efeitos limitados no domínio, então não podemos garantir a posição de <Blue:Junction>. Tudo depende da sua adaptabilidade."
  },
  AvgDialog_10129_Content_8 = {
    Text = "Vá até a <Blue:Junção> mais próxima e ajude a curar as feridas de Ramona."
  },
  AvgDialog_10130_Content_10 = {
    Text = "Enquanto nossos nomes estiverem gravados no monumento, nossa existência não será apagada por @2."
  },
  AvgDialog_10130_Content_11 = {
    Text = "Uma voz suave entrelaçada com gritos distorcidos ecoa em sua mente."
  },
  AvgDialog_10130_Content_12 = {
    Text = "Eu serei seu assistente, acompanhando-o até o final deste caminho... <Yellow:Que a Chave Prata ilumine seu caminho.>"
  },
  AvgDialog_10130_Content_13 = {
    Text = "Você está bem, %player%? Está um pouco pálido(a). Devemos passar pela enfermaria?"
  },
  AvgDialog_10130_Content_14 = {
    Text = "A voz dela, nítida, trouxe clareza à mente, e a tontura gradualmente diminuiu."
  },
  AvgDialog_10130_Content_15 = {
    Text = "Não se preocupe, apenas um pouco tonto, mas agora está melhor."
  },
  AvgDialog_10130_Content_16 = {
    Text = "Hmm, só para ficar seguro, vamos permanecer conectados.\nComo seu assistente e parceiro, é meu dever sempre verificar seu Estado."
  },
  AvgDialog_10130_Content_17 = {
    Text = "Agora? Aqui fora?"
  },
  AvgDialog_10130_Content_18 = {
    Text = "Talvez seja um pouco mais cedo do que o planejado, mas não deve importar, certo?"
  },
  AvgDialog_10130_Content_19 = {
    Text = "Além disso, estive ansiosa por este dia há mais de um ano."
  },
  AvgDialog_10130_Content_2 = {
    Text = "Bem-vindo à Universidade Mythag, %player%."
  },
  AvgDialog_10130_Content_21 = {
    Text = "Gotas de chuva escorrem para dentro das suas luvas, umedecendo as pontas dos seus dedos. Uma corrente tênue penetra o tecido, fluindo secretamente entre a sua pele e a dela."
  },
  AvgDialog_10130_Content_22 = {
    Text = "Emoções inexplicáveis percorrem os seus nervos—alegria, excitação, inquietação e..."
  },
  AvgDialog_10130_Content_23 = {
    Text = "...<Yellow:Esperança>."
  },
  AvgDialog_10130_Content_3 = {
    Text = "Ou melhor... bem-vindo, você oficialmente entrou no lado oculto do mundo."
  },
  AvgDialog_10130_Content_4 = {
    Text = "Estou de volta."
  },
  AvgDialog_10130_Content_5 = {
    Text = "Sua entrada é o que todos estavam esperando. Em dois dias, William nos designará uma <Yellow:Clades Investigação Tarefa>."
  },
  AvgDialog_10130_Content_6 = {
    Text = "Ele não vai ter piedade de você, um Guardião que aparece uma vez a cada século."
  },
  AvgDialog_10130_Content_7 = {
    Text = "Espero que sua missão de campo @1 não dependa tanto de mim, o <Blue:> como um curso de cálculo."
  },
  AvgDialog_10130_Content_8 = {
    Text = "Nunca pensei que eu assistiria ao meu próprio funeral."
  },
  AvgDialog_10130_Content_9 = {
    Text = "Abrace a morte, para que não a temamos mais."
  },
  AvgDialog_10131_Content_1 = {
    Text = "Agora, Ogier e eu estamos entrando na batalha."
  },
  AvgDialog_10131_Content_2 = {
    Text = "Sinto através do link que sua condição e a do Ogier não são ainda suficientes para"
  },
  AvgDialog_10131_Content_3 = {
    Text = "Está tudo bem, Guardião.\nOs cavaleiros existem para proteger todos, e Ogier pode resistir!"
  },
  AvgDialog_10131_Content_4 = {
    Text = "Não se preocupe. Com você aqui para estabilizar nossas mentes, não perderemos o controle e podemos tirar o máximo de Aliemus."
  },
  AvgDialog_10131_Content_5 = {
    Text = "Enquanto eu reunir Aliemus suficiente, poderei recuperar meu Estado."
  },
  AvgDialog_10131_Content_6 = {
    Text = "Não hesite mais, Guardião.\nSe conseguiremos romper o cerco depende do seu comando."
  },
  AvgDialog_10131_Content_7 = {
    Text = "Deixe-me testemunhar por mim mesmo o valor deste prodígio no qual Misaq aposta o seu futuro!"
  },
  AvgDialog_10132_Content_1 = {
    Text = "Hmph, você acha que pode destruir este planeta?"
  },
  AvgDialog_10132_Content_2 = {
    Text = "Longe de ser o suficiente! Venha, não importa quanto mais houver!"
  },
  AvgDialog_10133_Content_1 = {
    Text = "É... acabou...?"
  },
  AvgDialog_10133_Content_10 = {
    Text = "Ela estendeu a mão e tocou levemente a Chave Prata em seu peito"
  },
  AvgDialog_10133_Content_11 = {
    Text = "A Chave de Prata pisca uma resposta tênue."
  },
  AvgDialog_10133_Content_12 = {
    Text = "Você é a variável, a resposta tanto para o começo quanto para o fim."
  },
  AvgDialog_10133_Content_13 = {
    Text = "Espero que você seja o ponto de virada..."
  },
  AvgDialog_10133_Content_15 = {
    Text = "Monstros brancos de seis asas, uma mulher com uma expressão indiferente, monstros de lama espalhando-se em um ataque, formas sombrias e distorcidas de Despertadores..."
  },
  AvgDialog_10133_Content_16 = {
    Text = "Eles se transformaram em uma poça de água negra e então desapareceram sem deixar vestígios."
  },
  AvgDialog_10133_Content_17 = {
    Text = "Ignorando os chamados de Ramona e Doll, você olha para cima enquanto segura a chave prata, olhando para a \"porta\" que leva de volta a \"Tawil.\""
  },
  AvgDialog_10133_Content_18 = {
    Text = "Você se lembra claramente do rosto que acabou de ver.\nA expressão indiferente, os contornos das sobrancelhas e olhos, e a curva dos lábios se assemelham a Ramona—"
  },
  AvgDialog_10133_Content_19 = {
    Text = "—Exatamente a mesma."
  },
  AvgDialog_10133_Content_2 = {
    Text = "\"Tawil\" permanece em pé, mas não mais com a mesma compostura."
  },
  AvgDialog_10133_Content_20 = {
    Text = "Dois dias depois\n\nTúmulo da Chave"
  },
  AvgDialog_10133_Content_21 = {
    Text = "...A Universidade Mythag é uma pioneira na luta contra a Dissolução, servindo como uma linha de defesa crucial para o futuro da humanidade."
  },
  AvgDialog_10133_Content_22 = {
    Text = "Por 300 anos, a Universidade Mythag pagou um alto preço para proteger a paz da humanidade da Dissolução."
  },
  AvgDialog_10133_Content_23 = {
    Text = "Este cemitério é nosso local de descanso preparado, e também a determinação dos professores e alunos de Mythag em sacrificar suas vidas pela sobrevivência da humanidade."
  },
  AvgDialog_10133_Content_24 = {
    Text = "O discurso continuou. Czort fechou os olhos e suspirou, a névoa branca de sua respiração se dissipando na chuva."
  },
  AvgDialog_10133_Content_25 = {
    Text = "...Acredito que, entre todos os novos alunos, ninguém pode compreender o peso dessas palavras melhor do que você."
  },
  AvgDialog_10133_Content_26 = {
    Text = "Nos últimos 300 anos, anomalias como Pratas e Mutantes de Dissolução apareceram ocasionalmente no Poço Negro, mas uma mutação dessa magnitude é sem precedentes."
  },
  AvgDialog_10133_Content_27 = {
    Text = "Muitos nunca voltaram."
  },
  AvgDialog_10133_Content_28 = {
    Text = "A oradora é Czort, a Reitora interina das Ciências da Vida Mythag. Rumores dizem que ela pode ver seres de outro mundo e foi a aluna favorita do ex-reitor."
  },
  AvgDialog_10133_Content_29 = {
    Text = "Eventos relacionados à Dissolução sempre trazem surpresas, loucura e morte. Esta é uma experiência inevitável em nosso caminho."
  },
  AvgDialog_10133_Content_3 = {
    Text = "Antes que qualquer outra pessoa pudesse reagir, de repente espalhou suas asas prateadas e atacou Ramona."
  },
  AvgDialog_10133_Content_30 = {
    Text = "Você entende o significado por trás das palavras de Czort.\nNão há ninguém sob a lápide à sua frente."
  },
  AvgDialog_10133_Content_31 = {
    Text = "Lodo negro flui lentamente sobre a lápide."
  },
  AvgDialog_10133_Content_32 = {Text = "..."},
  AvgDialog_10133_Content_33 = {
    Text = "Depois da cerimônia, o Nobre Dexter o convidou para seu escritório."
  },
  AvgDialog_10133_Content_34 = {
    Text = "O nome \"Dexter\" é familiar para você; é o sobrenome de Ramona.\nEste \"Nobre Dexter\" é seu professor e também o pai adotivo de Ramona."
  },
  AvgDialog_10133_Content_35 = {
    Text = "Eu vi esta parte no relatório, e preciso te pedir um favor."
  },
  AvgDialog_10133_Content_36 = {
    Text = "Sobre a aparência de Tawil... você poderia, por favor, manter isso em segredo de Ramona?"
  },
  AvgDialog_10133_Content_37 = {Text = "Por que?"},
  AvgDialog_10133_Content_38 = {
    Text = "Como devo colocar isso... a causalidade por trás disso é bastante complexa e difícil de explicar brevemente."
  },
  AvgDialog_10133_Content_39 = {
    Text = "No entanto, eu a farei saber mais cedo ou mais tarde, apenas não neste momento."
  },
  AvgDialog_10133_Content_4 = {
    Text = "O tempo parece ter chegado a um impasse."
  },
  AvgDialog_10133_Content_40 = {
    Text = "Isto não se deve a considerações de confidencialidade de Mythag, mas a um pedido de um pai para proteger sua filha."
  },
  AvgDialog_10133_Content_41 = {
    Text = "Por favor, nos dê um tempo, ok?"
  },
  AvgDialog_10133_Content_42 = {
    Text = "Mesmo que você deseje saber a verdade, você ainda acena com a cabeça em concordância."
  },
  AvgDialog_10133_Content_43 = {
    Text = "Obrigado pela sua compreensão.\nFalando nisso, um lote de uísque blend real acaba de chegar recentemente. Consegui fazer alguém reservar secretamente duas garrafas."
  },
  AvgDialog_10133_Content_44 = {
    Text = "Aqui, leve isso e convide Ramona para experimentar o sabor da vida adulta — considere isso seu ritual de iniciação exclusivo, que tal?"
  },
  AvgDialog_10133_Content_45 = {
    Text = "Estou com medo de que é inapropriado, Nobre Dexter.\nA Dissolução não vai parar de se espalhar enquanto descansamos."
  },
  AvgDialog_10133_Content_46 = {
    Text = "Oh não, William encontrou o caminho aqui.\nReceio que não posso te salvar agora, pequeno."
  },
  AvgDialog_10133_Content_47 = {
    Text = "O dossiê foi organizado. Você pode se preparar para o dever agora, novo Guardião."
  },
  AvgDialog_10133_Content_48 = {
    Text = "Que a Chave de prata ilumine o meu caminho."
  },
  AvgDialog_10133_Content_5 = {
    Text = "Você correu na sua máxima velocidade, mal conseguindo proteger Ramona."
  },
  AvgDialog_10133_Content_6 = {
    Text = "O monstro branco olha diretamente para você."
  },
  AvgDialog_10133_Content_7 = {
    Text = "Ele te observa silenciosamente com seu corpo pálido e sem rosto."
  },
  AvgDialog_10133_Content_9 = {
    Text = "Diante de você aparece o rosto de uma mulher com uma expressão indiferente."
  },
  AvgDialog_10134_Content_1 = {
    Text = "Ei, você! Acelere e me deixe liberar <Yellow:\"Lâmina da Desafiança\">."
  },
  AvgDialog_10134_Content_2 = {
    Text = "Espere, Guardião.\nPrimeiro, libere \"Golpe\", acendendo a sede de sangue de Lotan, o que pode reduzir o consumo de Aritmética de <Yellow:\"Lâmina da Desobediência\">."
  },
  AvgDialog_10134_Content_3 = {
    Text = "A combinação certa de comandos pode dobrar a eficácia de nossos ataques.\nAs táticas estão escondidas dentro dos comandos, Guardião. Pense cuidadosamente."
  },
  AvgDialog_10135_Content_1 = {
    Text = "Cuidado, não se aproxime mais! Meu escudo está prestes a quebrar!"
  },
  AvgDialog_10135_Content_10 = {
    Text = "Você sabe, ninguém mais pode fazer isso a não ser eu."
  },
  AvgDialog_10135_Content_11 = {
    Text = "Quando me louvam, é \"uma vez por século\", mas quando uma verdadeira crise chega, sou tratado como um vaso. Isso não é justo."
  },
  AvgDialog_10135_Content_12 = {
    Text = "Alguns riscos devem ser enfrentados."
  },
  AvgDialog_10135_Content_13 = {
    Text = "Não temos escolha. Muitas pessoas aqui perderam o controle. Se não resistirmos, seremos consumidos pela loucura."
  },
  AvgDialog_10135_Content_14 = {
    Text = "Além disso, nós dois sozinhos não conseguimos romper o cerco na torre do relógio.\nPrecisamos de ajuda. Precisamos do poder para controlar os Despertadores."
  },
  AvgDialog_10135_Content_15 = {
    Text = "Ramona, me apoie."
  },
  AvgDialog_10135_Content_16 = {
    Text = "Desde que você está tão determinada... como sua \"parceira\", não tenho mais razão para te impedir."
  },
  AvgDialog_10135_Content_17 = {
    Text = "Ramona, sempre pronta para a batalha!"
  },
  AvgDialog_10135_Content_2 = {
    Text = "Com um \"clang,\" as espadas gêmeas de Lotan quebraram o gigante escudo formado por lodo negro mais uma vez."
  },
  AvgDialog_10135_Content_3 = {
    Text = "Não é suficiente, não é suficiente! Agite a tempestade! Dê-me uma batalha emocionante!"
  },
  AvgDialog_10135_Content_4 = {
    Text = "O Despertar nomeado Lotan brandiu suas lâminas gêmeas, atacando implacavelmente Ogier. A força pura de seus ataques revelou uma dura realidade—ela havia perdido completamente o controle."
  },
  AvgDialog_10135_Content_5 = {
    Text = "Dada a situação, só podemos..."
  },
  AvgDialog_10135_Content_6 = {
    Text = "Ramona, ajude-me a dominar Lotan!"
  },
  AvgDialog_10135_Content_7 = {
    Text = "Você não pode estar pensando em..."
  },
  AvgDialog_10135_Content_8 = {
    Text = "Eu vou Linká-la!"
  },
  AvgDialog_10135_Content_9 = {
    Text = "Não brinque, a perda de controle de um Despertador ressoa com o Investigador através do Link, até você—"
  },
  AvgDialog_10136_Content_1 = {
    Text = "Este é... o orgulhoso <Yellow:\"Lâmina da Desafiação\"> de Lotan, capaz de lançar múltiplos ataques instantaneamente!"
  },
  AvgDialog_10136_Content_2 = {
    Text = "Para contra-atacar este movimento... use <Yellow:\"Análise Ofensiva\"> para evitar pontos fracos críticos. Isso é mais seguro."
  },
  AvgDialog_10137_Content_1 = {
    Text = "Você não pode me deter! ...Humanos sem vergonha..."
  },
  AvgDialog_10137_Content_2 = {
    Text = "Você toca a recém-adquirida Chave de Prata, sentindo uma leve vibração que o urge a completar a Ressonância com Lotan."
  },
  AvgDialog_10137_Content_4 = {
    Text = "<Shake:Se ao menos eu soubesse... Nunca teria concordado com um pacto com você...>"
  },
  AvgDialog_10137_Content_5 = {
    Text = "Ramona se aproximou de Lotan e estendeu a mão."
  },
  AvgDialog_10137_Content_6 = {
    Text = "Eu sei, quando você foi despertado, Mythag prometeu lutar ao seu lado... Batalhar até o fim deste planeta."
  },
  AvgDialog_10137_Content_7 = {
    Text = "Nunca tivemos a intenção de quebrar nossa promessa. Durante os últimos 300 anos e nos próximos 300 anos, continuaremos a carregar este fardo."
  },
  AvgDialog_10137_Content_8 = {
    Text = "Lotan, a intensa batalha que você estava esperando está bem diante de seus olhos."
  },
  AvgDialog_10138_Content_1 = {
    Text = "Fique alerta, está prestes a atacar. Esse dano pode ser fatal para mim agora."
  },
  AvgDialog_10138_Content_2 = {
    Text = "Confie que você fará a escolha certa. Para a ação deste turno, escolha <Yellow:\"Defesa\">."
  },
  AvgDialog_10139_Content_1 = {
    Text = "Obrigado, Guardião. Você me salvou mais uma vez.\nSe não fosse por este Link, eu estaria provavelmente em grave perigo agora."
  },
  AvgDialog_10139_Content_2 = {
    Text = "Agora não é hora de falar sobre isso—"
  },
  AvgDialog_10139_Content_3 = {
    Text = "Enquanto você fala, a anomalia negro-jetá se espalha ao seu redor.\nGritos ecoam continuamente enquanto seus colegas da aula de ontem se transformam em lodo negro um por um."
  },
  AvgDialog_10139_Content_4 = {
    Text = "Eu compartilhei a <Yellow:intenção> do inimigo detectada pela Chave Prata através do link. Cuidado, ele está prestes a atacar!"
  },
  AvgDialog_10140_Content_1 = {
    Text = "Você sente o Aliemus flowing através de mim, Guardião?\nGraças à sua supressão com o poder espiritual, isso não me levaria à Loucura como Lotan."
  },
  AvgDialog_10140_Content_2 = {
    Text = "No entanto, agora pode ser útil para nós."
  },
  AvgDialog_10140_Content_3 = {
    Text = "Olhe na direção de onde flui Aliemus... Sim, olhe para o <Blue:canto superior esquerdo> do dispositivo de comando."
  },
  AvgDialog_10140_Content_4 = {
    Text = "Liberte Exaltar e abrace minha <Yellow:\"Dedução Mundus\">! \nDurante a batalha contra a Dissolução, <Yellow:apenas uma resposta racional à ofensiva pode garantir a maior chance de sobrevivência>."
  },
  AvgDialog_10141_Content_1 = {
    Text = "Droga, Lotan está prestes a liberar <Yellow:Exaltar>... Com apenas esses comandos..."
  },
  AvgDialog_10141_Content_2 = {
    Text = "A Chave de Prata conecta-se com seu espírito, ressoando de forma exclusiva com suas fortes percepções e memórias, gerando um poder distinto."
  },
  AvgDialog_10141_Content_3 = {
    Text = "Olhe para o <Blue:canto inferior esquerdo> do dispositivo de comando! A chave de prata está totalmente carregada e o <Yellow:grupo> está pronto."
  },
  AvgDialog_10141_Content_4 = {
    Text = "Aperte a Chave de Prata, cante o texto secreto... libere <Yellow:Posse>, e me dê mais espaço tático!"
  },
  AvgDialog_10142_Content_2 = {
    Text = "Não se distraia durante uma cerimônia tão importante, <Yellow:Guardião>, você receberá a Chave de Prata a seguir."
  },
  AvgDialog_10142_Content_3 = {
    Text = "Erija sua lápide para provar nossa determinação em lutar <Yellow:contra Dissolução>—uma tradição de Mythag, marcando o fim do pré-estudo e tornando-se Investigadores oficiais."
  },
  AvgDialog_10142_Content_4 = {
    Text = "Se você está pronto, grave seu nome na lápide."
  },
  AvgDialog_116003_Content_1 = {
    Text = "À medida que a pintura do seu homem-árvore se desintegra, tudo ao seu redor também derrete na distorção."
  },
  AvgDialog_116003_Content_10 = {
    Text = "Mas eu não quero que isso seja apenas um sonho."
  },
  AvgDialog_116003_Content_11 = {
    Text = "Eu quero voltar para Missaga, quero vê-los novamente."
  },
  AvgDialog_116003_Content_12 = {
    Text = "…resposta esperada."
  },
  AvgDialog_116003_Content_13 = {
    Text = "Mas desta vez, depois que você demonstrou sua determinação, eu finalmente posso ficar tranquilo."
  },
  AvgDialog_116003_Content_14 = {
    Text = "%player%, sua vontade é mais resistente e poderosa do que eu imaginava... o suficiente para enfrentar Ele e o caos e a loucura deste mundo."
  },
  AvgDialog_116003_Content_15 = {
    Text = "Você balança a cabeça, olhando para Clementine no sonho lindo que está prestes a se despedaçar completamente."
  },
  AvgDialog_116003_Content_16 = {
    Text = "Não, você está errado, a vontade de uma pessoa tem limites."
  },
  AvgDialog_116003_Content_17 = {
    Text = "Eu consegui aguentar até agora porque cada pessoa em Misaq me apoia."
  },
  AvgDialog_116003_Content_18 = {
    Text = "\"Esse mundo\" foi construído por eles para você, e você, com decisão, transformará esse sonho em realidade neste mundo."
  },
  AvgDialog_116003_Content_19 = {
    Text = "Ao ouvir suas palavras e ver sua expressão séria, Clementine sorriu, mostrando um sorriso relaxado."
  },
  AvgDialog_116003_Content_2 = {
    Text = "Você quebrou seu próprio sonho com suas próprias mãos."
  },
  AvgDialog_116003_Content_20 = {
    Text = "Sim, você ainda tem \"eles\", além de Tawil... e eu."
  },
  AvgDialog_116003_Content_21 = {
    Text = "Exatamente. Eu nunca estive sozinho."
  },
  AvgDialog_116003_Content_22 = {
    Text = "No cenário que continuamente se funde, veio um grito agudo, que era a resposta de Tawil às suas palavras.\nEla sempre esteve lá."
  },
  AvgDialog_116003_Content_23 = {
    Text = "Então, agora, %player%, o seu belo sonho realmente acabou."
  },
  AvgDialog_116003_Content_24 = {
    Text = "Como agradecimento pela sua colaboração neste tratamento, eu te dou um pequeno presente, espero que você goste."
  },
  AvgDialog_116003_Content_25 = {
    Text = "Com as últimas palavras de Clementine, o sonho se despedaçou completamente —"
  },
  AvgDialog_116003_Content_26 = {
    Text = "O céu com o sol negro pairando aparece diante de você, trazendo uma névoa cinzenta e a crueldade deste mundo."
  },
  AvgDialog_116003_Content_27 = {
    Text = "E sua palma, repousa silenciosamente uma foto. \n Uma foto capturada em \"um belo sonho falso\", que não deveria existir na cruel realidade."
  },
  AvgDialog_116003_Content_28 = {
    Text = "À beira-mar, vôlei, festa, a única coisa diferente da memória é Ramona."
  },
  AvgDialog_116003_Content_29 = {
    Text = "Um rosto familiar sorri serenamente, como se tivesse atravessado o tempo e o espaço, olhando para você. \n Parece estar bem diante de você."
  },
  AvgDialog_116003_Content_3 = {
    Text = "Desde que decidi contar com a força deles para construir este sonho, eu soube que este dia finalmente chegaria."
  },
  AvgDialog_116003_Content_30 = {
    Text = "<Small:Ramona……>"
  },
  AvgDialog_116003_Content_31 = {
    Text = "Você coloca a mão sobre a foto, com emoção e confusão surgindo ao mesmo tempo."
  },
  AvgDialog_116003_Content_32 = {
    Text = "<Shake:Por que é a Ramona...?>"
  },
  AvgDialog_116003_Content_33 = {
    Text = "Suas dúvidas não recebem resposta. \n No mundo envolto em névoa cinza, apenas o silencioso sol negro permanece inalterado."
  },
  AvgDialog_116003_Content_34 = {
    Text = "De qualquer forma…"
  },
  AvgDialog_116003_Content_35 = {
    Text = "Você coloca a foto sobre o peito, no local do coração, e fecha os olhos."
  },
  AvgDialog_116003_Content_36 = {
    Text = "De qualquer forma, eu não estou sozinho."
  },
  AvgDialog_116003_Content_37 = {
    Text = "Em seguida, você abriu os olhos e olhou para aquele sol negro suspenso, caminhando firmemente em sua direção."
  },
  AvgDialog_116003_Content_38 = {
    Text = "Este mundo ainda está desmoronando, vigiado por um terror indescritível, à beira do colapso, mas..."
  },
  AvgDialog_116003_Content_39 = {
    Text = "<Big:Você acabará encontrando uma maneira de salvá-lo>"
  },
  AvgDialog_116003_Content_4 = {
    Text = "Eu apenas não esperava que chegasse tão rápido, nem que você fosse tão decidido."
  },
  AvgDialog_116003_Content_5 = {
    Text = "Na verdade... eu hesitei e também evitei. Quando estava à beira-mar."
  },
  AvgDialog_116003_Content_6 = {
    Text = "Então, por que não continuar afundando nisso? É que aqui não é bonito o suficiente, não é feliz o suficiente?"
  },
  AvgDialog_116003_Content_7 = {
    Text = "Você ficou em silêncio, lembrando-se da sua pintura do homem árvore."
  },
  AvgDialog_116003_Content_8 = {
    Text = "É inegável, isso realmente é um lindo sonho. Mas…"
  },
  AvgDialog_116003_Content_9 = {
    Text = "Gradualmente, as cenas na sua mente não são mais pinturas, mas sim a verdadeira Misaq, a verdadeira Doll, Ramona, Lotan e Ogier."
  },
  AvgDialog_117499_Content_1 = {
    Text = "<Shake:Demais...>"
  },
  AvgDialog_117499_Content_2 = {
    Text = "Sob o céu escuro, a tempestade de cardumes parece interminável. Você olha ao redor, e em um canto está pendurada uma escada de metal enferrujada; você a segue e sobe cautelosamente para a plataforma de segundo andar."
  },
  AvgDialog_117499_Content_3 = {
    Text = "Aqui podemos nos esconder por um tempo."
  },
  AvgDialog_117499_Content_4 = {
    Text = "Uma atmosfera de engano, acompanhada de um som de atrito que faz seus dentes doerem, capturou sua atenção."
  },
  AvgDialog_117499_Content_5 = {
    Text = "Espere, aquilo lá é..."
  },
  AvgDialog_117500_Content_1 = {Text = "Grilhões"},
  AvgDialog_117500_Content_10 = {Text = "..."},
  AvgDialog_117500_Content_100 = {
    Text = "Murphy balançou a cabeça desanimada, seus olhos sem vida procurando vazio pelo seu local.\nEla se virou para você, apertando os lábios rachados devido à falta de sangue, forçando um sorriso pálido."
  },
  AvgDialog_117500_Content_101 = {
    Text = "Você veio... Eu pensei... que nunca mais iria te ver..."
  },
  AvgDialog_117500_Content_102 = {
    Text = "O casco do navio inclinou-se abruptamente, e a maré salgada e gelada inundou a cabine."
  },
  AvgDialog_117500_Content_103 = {
    Text = "O que aconteceu?!"
  },
  AvgDialog_117500_Content_104 = {
    Text = "O navio encalhou?"
  },
  AvgDialog_117500_Content_105 = {
    Text = "Impossível, o casco do Navio Paradis está muito profundo, mesmo que o porão encalhe e comece a vazar, não é possível que em tão pouco tempo as águas cheguem ao convés superior..."
  },
  AvgDialog_117500_Content_106 = {
    Text = "A menos que…"
  },
  AvgDialog_117500_Content_107 = {
    Text = "William correu em direção à janela, e a cena diante dele era como o mais absurdo dos delírios. O Navio Paradis afundava a uma velocidade incrível."
  },
  AvgDialog_117500_Content_108 = {
    Text = "Parece que uma baleia gigante está puxando o pequeno barco, com uma força imensa e irresistível, arrastando o Navio Paradis rapidamente em direção ao fundo do mar."
  },
  AvgDialog_117500_Content_109 = {Text = "Ah—"},
  AvgDialog_117500_Content_11 = {
    Text = "Você abre os olhos novamente. Macio, quente, como se já tivesse visto."
  },
  AvgDialog_117500_Content_110 = {
    Text = "Sob a intensa vibração, a corrente que penetrava a palma de Murphy se quebrou de repente."
  },
  AvgDialog_117500_Content_111 = {
    Text = "Uma palma macia e pegajosa toca suas costas da mão, enquanto ela suporta a dor da penetração em sua palma, segurando suavemente sua mão e olhando em seus olhos."
  },
  AvgDialog_117500_Content_112 = {
    Text = "Ela murmurou, suas palavras carregavam o cheiro metálico de ferrugem, não se sabia se por causa da água do mar ou do sangue."
  },
  AvgDialog_117500_Content_113 = {
    Text = "Salve-me... se for você, com certeza pode..."
  },
  AvgDialog_117500_Content_114 = {
    Text = "As últimas palavras, afundaram na escuridão junto com a água do mar que inundava a cabine."
  },
  AvgDialog_117500_Content_12 = {
    Text = "<Small:Ts, nós realmente vamos ficar aqui esperando esse cara acordar?>"
  },
  AvgDialog_117500_Content_13 = {
    Text = "<Small:Goliath, não pode questionar a ordem da Mãe Divina.>"
  },
  AvgDialog_117500_Content_14 = {
    Text = "<Small:Seja mais discreto, Senhor Goliath, esta manhã, a Mãe Divina chamou a Mãe para dar uma longa lição...>"
  },
  AvgDialog_117500_Content_15 = {
    Text = "Uma disputa em voz baixa vem de fora da cortina."
  },
  AvgDialog_117500_Content_16 = {
    Text = "*Tosse, tosse...*"
  },
  AvgDialog_117500_Content_17 = {
    Text = "Você acordou? Todos estão esperando por você."
  },
  AvgDialog_117500_Content_18 = {
    Text = "Faros levantou a cortina de seda."
  },
  AvgDialog_117500_Content_19 = {
    Text = "Eu... fui salvo novamente?"
  },
  AvgDialog_117500_Content_2 = {
    Text = "……Aranhas?"
  },
  AvgDialog_117500_Content_20 = {
    Text = "Aquele que sobreviveu à grande calamidade. Não temos a obrigação de responder a todas as suas perguntas."
  },
  AvgDialog_117500_Content_21 = {
    Text = "Por ordem da Mãe Divina, os Marchadores de mares já aguardam há muito o seu Despertar."
  },
  AvgDialog_117500_Content_22 = {
    Text = "Este é o suco de limão que a Mãe Divina me ordenou que espremesse. Beba com gratidão, humano."
  },
  AvgDialog_117500_Content_23 = {
    Text = "Uma vez que Ele já está seguro, eu voltarei ao meu posto de navegação. O Reino Divino está me chamando."
  },
  AvgDialog_117500_Content_24 = {Text = "..."},
  AvgDialog_117500_Content_25 = {Text = "..."},
  AvgDialog_117500_Content_26 = {
    Text = "É um evento real ou um pesadelo do momento em que estou submerso na água...?"
  },
  AvgDialog_117500_Content_27 = {
    Text = "(É necessário encontrar uma maneira de verificar isso.)"
  },
  AvgDialog_117500_Content_28 = {
    Text = "Se não me engano, a última pessoa que vi foi..."
  },
  AvgDialog_117500_Content_29 = {
    Text = "Você pisou no convés."
  },
  AvgDialog_117500_Content_3 = {
    Text = "Uma pequena aranha de cor roxa escura olha fixamente para você. Ao ver que você acordou, ela levantou as patas dianteiras e acenou para você."
  },
  AvgDialog_117500_Content_30 = {
    Text = "<Shake:Ei——William, o companheiro mais velho——>"
  },
  AvgDialog_117500_Content_31 = {
    Text = "<Shake:Não se esconda——eu sei que você está aqui——>"
  },
  AvgDialog_117500_Content_32 = {
    Text = "No convés, só há o som tranquilo das ondas, e seu grito se dispersa na névoa da manhã."
  },
  AvgDialog_117500_Content_33 = {
    Text = "(Deixe pra lá, afinal, foi apenas meu sonho...)"
  },
  AvgDialog_117500_Content_34 = {Text = "Uau!"},
  AvgDialog_117500_Content_35 = {
    Text = "O convés sob seus pés revela uma porta que se abre de repente, e você cai com um baque em uma escuridão total."
  },
  AvgDialog_117500_Content_36 = {
    Text = "Um punhado de palha aliviou o impacto da sua queda."
  },
  AvgDialog_117500_Content_37 = {
    Text = "Há quanto tempo, Guardião do Segredo."
  },
  AvgDialog_117500_Content_38 = {
    Text = "Você me conhece... você é o companheiro mais velho William do mundo original..."
  },
  AvgDialog_117500_Content_39 = {
    Text = "William ignorou seu tom surpreso e, em vez disso, franziu a testa."
  },
  AvgDialog_117500_Content_4 = {
    Text = "Camadas de tule e veludo empilhadas sobre o convés enferrujado. A mulher segurando a roda de fiar olha fixamente para você."
  },
  AvgDialog_117500_Content_40 = {
    Text = "Não me lembro de ter ensinado você a agir de forma tão ostentosa no quartel-general do inimigo em Missaga."
  },
  AvgDialog_117500_Content_41 = {
    Text = "Mesmo o decano Czort, conhecido por sua ousadia, provavelmente não apoiaria sua escolha."
  },
  AvgDialog_117500_Content_42 = {
    Text = "O cheiro familiar do pinho, a postura ereta familiar, o tom severo familiar."
  },
  AvgDialog_117500_Content_43 = {
    Text = "William, o companheiro mais velho..."
  },
  AvgDialog_117500_Content_44 = {
    Text = "Antes de resolver a questão crucial, eu não pretendia aparecer diante de você."
  },
  AvgDialog_117500_Content_45 = {
    Text = "Mas sua imprudência me obrigou a mudar de estratégia."
  },
  AvgDialog_117500_Content_46 = {
    Text = "Você sabe que eu sempre estive te perseguindo?"
  },
  AvgDialog_117500_Content_47 = {
    Text = "William não respondeu a essa pergunta, apenas lhe lançou um olhar afiado que parecia dizer \"Você me acha um idiota?\"."
  },
  AvgDialog_117500_Content_48 = {
    Text = "Já estamos no mesmo navio, provavelmente não podemos evitar. Melhor eu esclarecer a situação diretamente, para evitar complicações desnecessárias."
  },
  AvgDialog_117500_Content_49 = {
    Text = "Antes disso, você poderia compartilhar as informações que possui?"
  },
  AvgDialog_117500_Content_5 = {
    Text = "Desta vez, ela não suspirou, nem falou, apenas ficou em silêncio."
  },
  AvgDialog_117500_Content_50 = {Text = "..."},
  AvgDialog_117500_Content_51 = {Text = "..."},
  AvgDialog_117500_Content_52 = {
    Text = "Desde que fui transformado em um cérebro de Doll: Inferno, aprisionado no Sanatório de Clementine, passando pelas paisagens da Necrópole, até o \"pesadelo\" que vivi a bordo do Navio Paradis."
  },
  AvgDialog_117500_Content_53 = {
    Text = "Você compartilhará suas experiências ao longo do caminho, enquanto William vira a cabeça e ouve atentamente, acenando de vez em quando para mostrar que está concentrado."
  },
  AvgDialog_117500_Content_54 = {
    Text = "Ao falar sobre o William quando era criança, você hesitou por um momento, mas William apenas levantou a mão para sinalizar que você poderia continuar."
  },
  AvgDialog_117500_Content_55 = {
    Text = "As informações que você forneceu são muito úteis."
  },
  AvgDialog_117500_Content_56 = {
    Text = "William, o companheiro mais velho, você pode me dizer agora o que exatamente está perseguindo?"
  },
  AvgDialog_117500_Content_57 = {
    Text = "William pondera por um momento."
  },
  AvgDialog_117500_Content_58 = {
    Text = "Deixe-me pensar por onde devo começar."
  },
  AvgDialog_117500_Content_59 = {
    Text = "Desde que caí neste mundo, tenho explorado duas questões: por que eu vim parar aqui e como posso voltar para o meu mundo original?"
  },
  AvgDialog_117500_Content_6 = {
    Text = "Por que, eu claramente me lembro de ter sido atacado por incontáveis Marchadores de mares, e então..."
  },
  AvgDialog_117500_Content_60 = {
    Text = "William retirou solenemente uma chave de prata que guardava perto do peito, e em seu olhar havia um traço de nostalgia."
  },
  AvgDialog_117500_Content_61 = {
    Text = "Esta Chave de Prata foi restaurada por mim, vinda do meu ex-parceiro Fengor... Sempre dizem que sou o investigador mais lendário de Misaq, mas para mim, isso é apenas porque ele faleceu jovem."
  },
  AvgDialog_117500_Content_62 = {
    Text = "Só caí na real neste dimensão que ele apenas tinha um discernimento mais precoce sobre a essência do mundo e lutava como um pioneiro na linha de frente contra a dissolução."
  },
  AvgDialog_117500_Content_63 = {
    Text = "Ele já rastreou o segredo da conexão entre dois mundos e deixou uma pista crucial — uma estátua de marfim."
  },
  AvgDialog_117500_Content_64 = {
    Text = "Como sempre, ele sempre está um passo à minha frente."
  },
  AvgDialog_117500_Content_65 = {
    Text = "William ficou com uma expressão sombria, balançou a cabeça e guardou a chave de prata de volta em seu peito."
  },
  AvgDialog_117500_Content_66 = {
    Text = "…Você já viu a estátua de marfim que está nas mãos de Miryam ou Murphy?"
  },
  AvgDialog_117500_Content_67 = {
    Text = "Você acena com a cabeça."
  },
  AvgDialog_117500_Content_68 = {
    Text = "Se tudo se desenvolver como da última vez, em cima do convés, Murphy está realizando um ritual com esta estátua."
  },
  AvgDialog_117500_Content_69 = {
    Text = "Aquela estátua de marfim parece ter uma conexão intrincada com a essência deste mundo."
  },
  AvgDialog_117500_Content_7 = {
    Text = "Você sente seus membros. Embora a dor fantasma ainda exista, não há uma única cicatriz em sua pele, e a grande batalha que você experienciou antes do desmaio parece nunca ter acontecido."
  },
  AvgDialog_117500_Content_70 = {
    Text = "Então, para voltar, provavelmente precisamos obter a estátua de marfim e fazer a análise e o estudo dela."
  },
  AvgDialog_117500_Content_71 = {
    Text = "Depois que o ritual terminar, a estátua de marfim deve voltar para o quarto de Murphy..."
  },
  AvgDialog_117500_Content_72 = {
    Text = "Dentro está muito silencioso, teoricamente todos não estão aqui dentro..."
  },
  AvgDialog_117500_Content_73 = {
    Text = "Cuidado é o melhor, devemos evitar conflitos desnecessários sempre que possível."
  },
  AvgDialog_117500_Content_74 = {
    Text = "Certo, então vamos dar uma espiada primeiro."
  },
  AvgDialog_117500_Content_75 = {
    Text = "Você empurra cuidadosamente a porta do quarto."
  },
  AvgDialog_117500_Content_76 = {Text = "..."},
  AvgDialog_117500_Content_77 = {
    Text = "Uma corrente de ar com um cheiro estranho flui para suas narinas, e você percebe que involuntariamente respirou fundo."
  },
  AvgDialog_117500_Content_78 = {
    Text = "Qual é o problema?"
  },
  AvgDialog_117500_Content_79 = {Text = "Voz."},
  AvgDialog_117500_Content_8 = {
    Text = "Isso é... um pesadelo?"
  },
  AvgDialog_117500_Content_80 = {
    Text = "Finalmente, apareceu um som no quarto silencioso."
  },
  AvgDialog_117500_Content_81 = {
    Text = "Som de gotas d'água."
  },
  AvgDialog_117500_Content_82 = {
    Text = "Tic, tic, o som das gotas d'água caindo na pequena poça que acabou de se formar."
  },
  AvgDialog_117500_Content_83 = {
    Text = [[
Oito correntes de ferro esticadas se estendem dos membros de Murphy, prendendo-a firmemente. 
 Seu peito foi aberto com um enorme buraco sanguinolento.]]
  },
  AvgDialog_117500_Content_84 = {
    Text = "O sangue escorre pela ferida chocante, pingando na poça de sangue que se forma lentamente, que é a origem do som de tique-taque que ecoa em seus ouvidos."
  },
  AvgDialog_117500_Content_85 = {Text = "Murphy…!"},
  AvgDialog_117500_Content_86 = {
    Text = "Você chegou tarde demais."
  },
  AvgDialog_117500_Content_87 = {
    Text = "O coração parece ser agarrado com força por uma mão invisível, aquela dor familiar e asfixiante, acompanhada de fragmentos de memórias, perfura profundamente."
  },
  AvgDialog_117500_Content_88 = {
    Text = "A luz ofuscante fere seus olhos, causando lágrimas incontroláveis."
  },
  AvgDialog_117500_Content_89 = {
    Text = "Conforme o líquido turvo se esvai, seus olhos finalmente voltam a focar na garota."
  },
  AvgDialog_117500_Content_9 = {
    Text = "A mulher acena silenciosamente com a cabeça, sua silhueta se dissolve na névoa difusa."
  },
  AvgDialog_117500_Content_90 = {
    Text = "Com uma lâmina cravada fundo em seu peito, a garota banhada pelo luar abre os olhos."
  },
  AvgDialog_117500_Content_91 = {
    Text = "A lua cheia, símbolo da morte, paira próxima, mas nenhum traço de medo se mostra em seu rosto jovem."
  },
  AvgDialog_117500_Content_92 = {
    Text = "Eu consegui... Eu realmente consegui."
  },
  AvgDialog_117500_Content_93 = {
    Text = "Eu... perfurei... Não nascerá..."
  },
  AvgDialog_117500_Content_94 = {
    Text = "Agora, eu posso..."
  },
  AvgDialog_117500_Content_95 = {
    Text = "A mão dela segurando a faca cai fracamente, enquanto um líquido espesso, viscoso e carmesim escuro escorre pela lâmina, pingando entre seus dedos até o mar."
  },
  AvgDialog_117500_Content_96 = {
    Text = "*Tosse, tosse...*"
  },
  AvgDialog_117500_Content_97 = {
    Text = "Você é... a pessoa do sonho..."
  },
  AvgDialog_117500_Content_98 = {
    Text = "Não fale ainda! Eu vou te ajudar..."
  },
  AvgDialog_117500_Content_99 = {
    Text = "Sua tentativa ansiosa não teve resultado, as correntes emitiram um gemido sutil com o tremor doloroso de Murphy."
  },
  AvgDialog_117501_Content_10 = {
    Text = "Por que a Mãe Divina faz tal pergunta?"
  },
  AvgDialog_117501_Content_11 = {
    Text = "Na noite passada, eu tive um sonho."
  },
  AvgDialog_117501_Content_12 = {
    Text = "No sonho, eu usei aquele punhal cerimonial..."
  },
  AvgDialog_117501_Content_13 = {
    Text = "Ela levantou a mão e apontou para o punhal que Miryam nunca se separava. \n A lâmina brilhava intensamente, emanando um brilho fantasmagórico como veneno."
  },
  AvgDialog_117501_Content_14 = {
    Text = "perfurou seu próprio peito."
  },
  AvgDialog_117501_Content_15 = {
    Text = "\"Ele não nascerá...\""
  },
  AvgDialog_117501_Content_16 = {
    Text = "Murphy murmurou para si mesma, passando os dedos suavemente pela cicatriz ensanguentada em seu peito."
  },
  AvgDialog_117501_Content_17 = {
    Text = "É um pesadelo ilusório."
  },
  AvgDialog_117501_Content_18 = {
    Text = "Miryam se aproxima, ajoelha-se diante do joelho de Murphy e acaricia suavemente as costas de sua mão para confortá-la."
  },
  AvgDialog_117501_Content_19 = {
    Text = "Fique tranquilo, o desejo do Marchador de mares foi realizado, Ele existe, Ele já chegou a este mundo."
  },
  AvgDialog_117501_Content_2 = {
    Text = "sussurro do sonho"
  },
  AvgDialog_117501_Content_20 = {
    Text = "E você e eu finalmente chegaremos ao Reino Divino, compartilhando a glória divina diante do Seu trono."
  },
  AvgDialog_117501_Content_21 = {
    Text = "Suas palavras são como orações diante do altar, repletas de reverência e devoção."
  },
  AvgDialog_117501_Content_22 = {
    Text = "E se não conseguirmos chegar ao Reino Divino? Quero dizer, e se..."
  },
  AvgDialog_117501_Content_23 = {
    Text = "Miryam imediatamente interrompeu a hesitante pergunta de Murphy."
  },
  AvgDialog_117501_Content_24 = {
    Text = "A profecia do Rei Deus nunca transmitiu tais assuntos. \n O próximo momento da posição normal será amanhã, Seu sangue certamente nos guiará até a terra prometida."
  },
  AvgDialog_117501_Content_25 = {
    Text = "Murphy franziu a testa."
  },
  AvgDialog_117501_Content_26 = {
    Text = "Vou descansar, Miryam, você também deve voltar e descansar."
  },
  AvgDialog_117501_Content_27 = {
    Text = "Eu vou rezar à Mãe Divina até o amanhecer, pedindo-lhe uma noite de descanso."
  },
  AvgDialog_117501_Content_28 = {
    Text = "Murphy não respondeu, seu olhar profundo seguiu a silhueta de Miryam até o som do rangido da porta se fechar."
  },
  AvgDialog_117501_Content_29 = {
    Text = "Ela se virou deprimida em direção ao altar nas sombras, fechou os olhos e fez uma oração."
  },
  AvgDialog_117501_Content_3 = {
    Text = "Ó, Mãe Divina, você está aqui olhando para a lanterna novamente."
  },
  AvgDialog_117501_Content_30 = {
    Text = "Amanhã, o Dia da Posição Normal..."
  },
  AvgDialog_117501_Content_31 = {
    Text = "O estranho objeto no altar não deu a ela nenhuma resposta, silencioso como um fóssil sob a camada de gelo.\n Murphy decidiu abrir os olhos."
  },
  AvgDialog_117501_Content_32 = {
    Text = "Para a continuidade deste sonho..."
  },
  AvgDialog_117501_Content_33 = {
    Text = "Ela estendeu os braços finos cobertos por um pesado véu negro, levantando alto o punhal ritual——"
  },
  AvgDialog_117501_Content_34 = {
    Text = "Sob a luz da vela, a sombra do punhal cravou-se violentamente no manto adormecido sobre o altar."
  },
  AvgDialog_117501_Content_35 = {
    Text = "Um som de puf ecoou, seguido pelo som estranho da carne e sangue viscosos sendo penetrados.\n Um líquido negro e pegajoso começou a se espalhar, umedecendo os marcantes runas de Marchador de mares no manto de veludo."
  },
  AvgDialog_117501_Content_36 = {
    Text = "Mais uma noite escura está prestes a chegar..."
  },
  AvgDialog_117501_Content_37 = {
    Text = "Ela soltou um suspiro, fechou os olhos, mas o que a atingiu não foi a escuridão sem fim, mas sim o sonho de ontem."
  },
  AvgDialog_117501_Content_38 = {Text = "..."},
  AvgDialog_117501_Content_39 = {
    Text = "(Aquele momento em que algo perfurou meu peito, a pessoa que apareceu ao meu lado...)"
  },
  AvgDialog_117501_Content_4 = {
    Text = "Descanse cedo, amanhã é o Dia da Posição Normal, e você ainda precisa guiar o Marchador de Mares com o Sangue Sagrado."
  },
  AvgDialog_117501_Content_40 = {
    Text = "(Parece que nunca vi, mas é um pouco nostálgico...)"
  },
  AvgDialog_117501_Content_41 = {
    Text = "……Aranhas?"
  },
  AvgDialog_117501_Content_42 = {
    Text = "Uma pequena aranha de cor roxa escura está te encarando no mastro. Ao te ver acordar, ela levantou as patas dianteiras e te cumprimentou."
  },
  AvgDialog_117501_Content_43 = {
    Text = "No sonho, parece que ouvi uma canção..."
  },
  AvgDialog_117501_Content_44 = {
    Text = "Uma voz etérea e suave, como a canção de uma sereia recitando poesias, ressoa incessantemente em seus ouvidos."
  },
  AvgDialog_117501_Content_45 = {
    Text = "Filhos da tragédia, o tecido do destino já foi tecido, e vocês certamente começarão a jornada que lhes é destinada."
  },
  AvgDialog_117501_Content_46 = {
    Text = "E você, convidado de outro mundo——"
  },
  AvgDialog_117501_Content_47 = {
    Text = "No momento do retorno da posição correta das estrelas, por favor, marque o fim do ciclo trágico."
  },
  AvgDialog_117501_Content_48 = {
    Text = "Acompanhada de um longo suspiro, a fantasma da mulher desapareceu."
  },
  AvgDialog_117501_Content_49 = {Text = "?!"},
  AvgDialog_117501_Content_5 = {
    Text = "Murphy olhava fixamente para a chama pulsante da lanterna, o véu negro balançando com seus movimentos, projetando uma sombra parecida com um cortina na parede da cabine."
  },
  AvgDialog_117501_Content_50 = {
    Text = "Depois que a sensação de medo momentânea se dissipou, você finalmente se acalmou e começou a observar o ambiente ao seu redor."
  },
  AvgDialog_117501_Content_51 = {
    Text = "Onde estou...?"
  },
  AvgDialog_117501_Content_52 = {
    Text = "Colchão macio. Um espaço tranquilo coberto por um véu negro. O aroma de sálvia e incenso flutua levemente no ar."
  },
  AvgDialog_117501_Content_53 = {
    Text = "Antes… Eu…"
  },
  AvgDialog_117501_Content_54 = {
    Text = "Doll! Você consegue receber o sinal? Doll?"
  },
  AvgDialog_117501_Content_55 = {
    Text = "Não grite, você está incomodando meu receptor de ondas sonoras."
  },
  AvgDialog_117501_Content_56 = {
    Text = "Eu alcancei o navio em que William embarcou, segundo o pescador! Mas ele entrou na tempestade!"
  },
  AvgDialog_117501_Content_57 = {
    Text = "A próxima frase é…"
  },
  AvgDialog_117501_Content_58 = {
    Text = "Vou entrar e perseguir!"
  },
  AvgDialog_117501_Content_59 = {
    Text = "Com esse seu pequeno barco de pesca? Correr para a fossa das Ilhas Bermudas? Você não tem medo de virar lá dentro?"
  },
  AvgDialog_117501_Content_6 = {
    Text = "Miryam, você sonhou?"
  },
  AvgDialog_117501_Content_60 = {
    Text = "Não podemos perder mais pistas, esta é a única informação real e válida que encontramos nos últimos meses!"
  },
  AvgDialog_117501_Content_61 = {
    Text = "Que a Chave de Prata ilumine o seu caminho!"
  },
  AvgDialog_117501_Content_62 = {
    Text = "Do outro lado da comunicação, não veio a frase que você deveria ter ouvido: \"Que a Chave de Prata nos guie\", mas sim o som do chiado da conexão interrompida."
  },
  AvgDialog_117501_Content_63 = {
    Text = "O que te aguarda são ondas gigantescas de mil pés de altura, seguidas pela escuridão sem fim que as engole——"
  },
  AvgDialog_117501_Content_64 = {
    Text = "Três meses atrás, seguindo as notícias sobre o misterioso homem loiro que partiu do porto de Innsmouth, você seguiu o rastro de William."
  },
  AvgDialog_117501_Content_65 = {
    Text = "Recentemente, você finalmente avistou a bandeira dos pescadores descrita por eles na linha do horizonte, mas uma tempestade repentina levou sua direção."
  },
  AvgDialog_117501_Content_66 = {
    Text = "Ao abrir os olhos novamente, é essa a cena que se apresenta diante de você."
  },
  AvgDialog_117501_Content_67 = {
    Text = "Você acordou? Todo mundo está esperando por você."
  },
  AvgDialog_117501_Content_68 = {
    Text = "O véu negro foi levantado levemente, seguido por uma voz feminina familiar e estranha."
  },
  AvgDialog_117501_Content_69 = {
    Text = "Pessoal…? Quem…?"
  },
  AvgDialog_117501_Content_7 = {
    Text = "Claro que sim. Em milhões de sonhos, a grande Lemúria emerge do Mar Profundo, reproduzindo-se sob a luz do sol."
  },
  AvgDialog_117501_Content_70 = {
    Text = "Quatro rostos familiares cercam estranhamente a sua cama."
  },
  AvgDialog_117501_Content_71 = {
    Text = "Por ordem da Mãe Divina, o Marchador de Mares já aguarda a sua Despertar há muito tempo. Venha, beba este remédio que a Mãe Divina preparou para você."
  },
  AvgDialog_117501_Content_72 = {
    Text = "Caecus apresentou um copo de vidro esculpido com precisão, o líquido turvo de um amarelo brilhante era inquietante."
  },
  AvgDialog_117501_Content_73 = {
    Text = "O que tem aqui dentro...?"
  },
  AvgDialog_117501_Content_74 = {
    Text = "Aquele que sobreviveu a grandes dificuldades, não pergunte mais nada."
  },
  AvgDialog_117501_Content_75 = {
    Text = "Foi a Mãe Divina que me mandou espremê-lo. Beba com gratidão, humano."
  },
  AvgDialog_117501_Content_76 = {
    Text = "Diante de todos, você cuidadosamente deu um pequeno gole."
  },
  AvgDialog_117501_Content_77 = {
    Text = "Puf — Tão azedo — ! É suco de limão puro?!"
  },
  AvgDialog_117501_Content_78 = {
    Text = "Você se sentou abruptamente, com as sobrancelhas franzidas de dor."
  },
  AvgDialog_117501_Content_79 = {
    Text = "Uma vez que Ele já está seguro, eu quero ir ao convés para receber a inspiração. O Reino Divino está me chamando."
  },
  AvgDialog_117501_Content_8 = {
    Text = "A luz eterna se semeia nos mares distantes, indicando um novo rumo para você e para mim."
  },
  AvgDialog_117501_Content_80 = {
    Text = "(Esse mundo e eu, com certeza, um de nós já enlouqueceu…)"
  },
  AvgDialog_117501_Content_81 = {
    Text = "Hum... aqui é?..."
  },
  AvgDialog_117501_Content_82 = {
    Text = "O navio Paradis, o único e mais importante \"paraíso\" no mar dos Marchadores de mares."
  },
  AvgDialog_117501_Content_83 = {
    Text = "Estamos navegando em direção ao eterno Reino Divino, Lemuria."
  },
  AvgDialog_117501_Content_9 = {
    Text = "Miryam respondeu quase intuitivamente, e a dúvida que se seguiu revelou uma incredulidade difícil de disfarçar."
  },
  AvgDialog_117502_Content_1 = {Text = "..."},
  AvgDialog_117502_Content_10 = {
    Text = "Na última luz antes que o campo de visão mergulhe na escuridão absoluta, você vê uma sombra passar rapidamente."
  },
  AvgDialog_117502_Content_11 = {
    Text = "Uma cabeleira dourada brilhante, com um braço mecânico preciso que pisca com um brilho metálico."
  },
  AvgDialog_117502_Content_12 = {
    Text = "William… companheiro mais velho…"
  },
  AvgDialog_117502_Content_2 = {Text = "..."},
  AvgDialog_117502_Content_3 = {
    Text = "Quanto tempo você lutou entre o cheiro forte do cardume?"
  },
  AvgDialog_117502_Content_4 = {
    Text = "Uma hora? Um dia? Ou um tempo que não pode ser contado?"
  },
  AvgDialog_117502_Content_5 = {
    Text = "(O festival é o momento em que os Marchadores de mares se mobilizam coletivamente, invadir neste momento... é realmente uma decisão impulsiva e errada.)"
  },
  AvgDialog_117502_Content_6 = {
    Text = "A sensação escorregadia já se tornou tão habitual que está dormente, e o muco fétido não é mais um incômodo para as narinas congestionadas."
  },
  AvgDialog_117502_Content_7 = {
    Text = "(se puder vir mais uma vez... que pena...)"
  },
  AvgDialog_117502_Content_8 = {
    Text = "Você se esforça para levantar a chave de prata, o núcleo que brilhava no passado começou a tremer.\n Você está instável e cospe um pouco de sangue."
  },
  AvgDialog_117502_Content_9 = {
    Text = "(Estou... no meu limite... Desculpa... não consegui escapar...)"
  },
  AvgDialog_117503_Content_1 = {
    Text = "Um viajante"
  },
  AvgDialog_117503_Content_10 = {
    Text = "O coração de repente começou a tocar a batida agitada, e você abriu a boca instintivamente, pois já conhecia o dono do rosto por trás do véu negro."
  },
  AvgDialog_117503_Content_100 = {
    Text = "Os cardumes romperam a restrição da superfície do líquido, lutando e se contorcendo no ar grudento, desabando ao seu lado em uma chuva fétida e pegajosa."
  },
  AvgDialog_117503_Content_101 = {
    Text = "Acompanhado por um som arrepiante, o corpo meio podre salta inutilmente sobre o convés, e a slime podre onde colide exala um fedor intenso e sufocante."
  },
  AvgDialog_117503_Content_102 = {
    Text = "Os tentáculos finos e frágeis rasgam o abdômen pálido, subindo em direção a você—"
  },
  AvgDialog_117503_Content_11 = {
    Text = "<Shake:Murphy...>"
  },
  AvgDialog_117503_Content_12 = {
    Text = "Através das fendas da gaze, sua pele pálida e azulada era exposta, branca como os restos de uma criatura flutuante à beira da desintegração."
  },
  AvgDialog_117503_Content_13 = {
    Text = "Audacioso! Como você se atreve a chamar pelo nome da Mãe Divina!"
  },
  AvgDialog_117503_Content_14 = {
    Text = "Nenhum problema, Caecus, {Male=ele,Female=ela} é um convidado do Paraíso e também se juntará à nossa grande jornada."
  },
  AvgDialog_117503_Content_15 = {
    Text = "Cinco olhos fixam-se em você, fazendo com que todas as palavras que você queria vomitar fiquem retidas em seu estômago."
  },
  AvgDialog_117503_Content_16 = {
    Text = "…Murphy, posso falar com você a sós?"
  },
  AvgDialog_117503_Content_17 = {Text = "..."},
  AvgDialog_117503_Content_18 = {Text = "..."},
  AvgDialog_117503_Content_19 = {Text = "Murphy..."},
  AvgDialog_117503_Content_2 = {
    Text = "A menina que conversa com você está sentada na beira da sua cama, um véu de chiffon preto e nebuloso cobre seu rosto."
  },
  AvgDialog_117503_Content_20 = {
    Text = "Se você ainda não organizou suas palavras, eu tenho uma pergunta para fazer."
  },
  AvgDialog_117503_Content_21 = {
    Text = "Por que você veio ao Paraíso? Pelo que eu sei, para se aproximar do Paraíso, é preciso primeiro entrar na tempestade."
  },
  AvgDialog_117503_Content_22 = {
    Text = "Estar disposto a correr esse risco, você deve ter algo a ganhar."
  },
  AvgDialog_117503_Content_23 = {
    Text = "Então, vocês já viram um homem que é meio cabeça mais alto que eu, com cabelo loiro?"
  },
  AvgDialog_117503_Content_24 = {
    Text = "Murphy lançou um olhar para você e soltou uma risada desdenhosa."
  },
  AvgDialog_117503_Content_25 = {
    Text = "Com a sua altura, deve haver muitas pessoas assim na tripulação."
  },
  AvgDialog_117503_Content_26 = {
    Text = "Não, você pode reconhecê-lo de imediato... Ele tem um braço mecânico, é muito bonito e exala um leve perfume de pinho."
  },
  AvgDialog_117503_Content_27 = {
    Text = "……então posso confirmar, nunca vi. \n Aqueles tripulantes sempre exalam um cheiro de peixe sujo e fedido."
  },
  AvgDialog_117503_Content_28 = {
    Text = "Então, Murphy, há uma coisa crucial."
  },
  AvgDialog_117503_Content_29 = {Text = "Sim?"},
  AvgDialog_117503_Content_3 = {
    Text = "(Uma voz tão familiar... quem é...?)"
  },
  AvgDialog_117503_Content_30 = {
    Text = "Você quer escapar comigo?"
  },
  AvgDialog_117503_Content_31 = {Text = "Haa?!"},
  AvgDialog_117503_Content_32 = {
    Text = "Murphy ficou surpresa com suas palavras, e logo a raiva subiu em suas bochechas.\n Ela lutou para controlar suas emoções e soltou uma risada sarcástica."
  },
  AvgDialog_117503_Content_33 = {
    Text = "Escapar, o que significa?"
  },
  AvgDialog_117503_Content_34 = {
    Text = "Significado literal, vamos encontrar uma maneira de sair deste navio e escapar do controle dos Marchadores de mares."
  },
  AvgDialog_117503_Content_35 = {
    Text = "Por que eu deveria fugir com você?"
  },
  AvgDialog_117503_Content_36 = {
    Text = "Porque você não gosta da vida aqui."
  },
  AvgDialog_117503_Content_37 = {
    Text = "Você não gosta da doutrina fictícia de Miryam, não gosta da adoração hipócrita dos fiéis e não se interessa por aquelas glórias ilusórias."
  },
  AvgDialog_117503_Content_38 = {
    Text = "A cabeça de Murphy foi baixando gradualmente."
  },
  AvgDialog_117503_Content_39 = {
    Text = "Vendo que ela estava em silêncio, você rapidamente jogou mais lenha na fogueira."
  },
  AvgDialog_117503_Content_4 = {
    Text = "Você se esforça para levantar o tronco com os braços doloridos, tentando entender a situação ao seu redor."
  },
  AvgDialog_117503_Content_40 = {
    Text = "Em outro mundo, eu te vi, eu te conheço, nós passamos por situações semelhantes, e você finalmente conseguiu escapar da caverna do demônio..."
  },
  AvgDialog_117503_Content_41 = {Text = "Hmph..."},
  AvgDialog_117503_Content_42 = {
    Text = "Errado, errado! Você está completamente errado!"
  },
  AvgDialog_117503_Content_43 = {Text = "Murphy...?"},
  AvgDialog_117503_Content_44 = {
    Text = "A reação de Murphy superou totalmente suas expectativas, ela começou a rir."
  },
  AvgDialog_117503_Content_45 = {
    Text = "A risada foi se tornando cada vez mais insana, até que no quarto ecoava apenas seu riso excessivamente indulgente."
  },
  AvgDialog_117503_Content_46 = {
    Text = "Depois de um tempo, ela pareceu finalmente cansar-se de rir, e a risada cessou abruptamente. \n Ela levantou a cabeça e olhou para você com raiva."
  },
  AvgDialog_117503_Content_47 = {
    Text = "O embrião divino se concebe em meu peito, eu, a mãe divina e honrada, amada por todos, por que devo obedecer a vocês, meros mortais, e \"fugir\"?"
  },
  AvgDialog_117503_Content_48 = {
    Text = "Mas, quando o Deus nascer, você morrerá..."
  },
  AvgDialog_117503_Content_49 = {
    Text = "Não há necessidade de esperar, pessoas tontas."
  },
  AvgDialog_117503_Content_5 = {
    Text = "Idiota, não se mexa."
  },
  AvgDialog_117503_Content_50 = {
    Text = "Murphy apresentou um manto de forma irregular, que originalmente era a parte da cabeça de um bebê, contendo um aglomerado de carne e sangue gelatinoso de cor azul-púrpura que parecia familiar."
  },
  AvgDialog_117503_Content_51 = {
    Text = "Criança Santa?!!"
  },
  AvgDialog_117503_Content_52 = {
    Text = "A partir do contorno, você reconhece que é o pseudo-Deus deformado que a Cerimônia de Nascimento do Sona-Nyl tenta invocar."
  },
  AvgDialog_117503_Content_53 = {
    Text = "Neste mundo, a Criança Santa já nasceu? Mas, por que ela é... tão pequena?!"
  },
  AvgDialog_117503_Content_54 = {
    Text = "Por que é tão pequeno... é realmente uma pergunta ridícula."
  },
  AvgDialog_117503_Content_55 = {
    Text = "Se continuar tão pequeno, não se tornará um balão de hidrogênio inflado pela força colossal, drenando gananciosamente a energia da matriz, preenchendo, expandindo e pressionando meu peito sem poupança..."
  },
  AvgDialog_117503_Content_56 = {
    Text = "Então, no momento em que o corpo materno morre, colapsa, se despedaça, se torna cinzas..."
  },
  AvgDialog_117503_Content_57 = {
    Text = "Você já viu, este é o Criança Santa que eu dei à luz."
  },
  AvgDialog_117503_Content_58 = {
    Text = "Você chama isso de deus?"
  },
  AvgDialog_117503_Content_59 = {
    Text = "E daí? Alguém já viu a aparência do deus no momento de seu nascimento, como falam os marinheiros?"
  },
  AvgDialog_117503_Content_6 = {
    Text = "A menina levantou-se impacientemente, o véu negro balançando inquieto."
  },
  AvgDialog_117503_Content_60 = {
    Text = "Quem pode afirmar que esta carne e sangue fétidos em nossas mãos não são o verdadeiro \"deus\"?"
  },
  AvgDialog_117503_Content_61 = {
    Text = "A voz de questionamento ecoa como um trovão em sua mente."
  },
  AvgDialog_117503_Content_62 = {
    Text = "Eu não sou a Murphy que você conhece, eu sou a Mãe Divina dos Marchadores de Mares, sou a única que compartilha seu sangue."
  },
  AvgDialog_117503_Content_63 = {
    Text = "Quanto a você... não me faça me arrepender de tê-lo trazido para o Paraíso. \n Agora, deixe-me em paz, saia deste quarto com suas ideias ridículas."
  },
  AvgDialog_117503_Content_64 = {
    Text = "Você vagueia a bordo do Navio Paradis, seguindo as memórias do passado, enquanto os pequenos marinheiros peixe-homem correm apressados, ignorando você."
  },
  AvgDialog_117503_Content_65 = {
    Text = "Até que, ao lado da sala de energia, você viu duas figuras familiares."
  },
  AvgDialog_117503_Content_66 = {
    Text = "Garoto, seja generoso, venha atacar!"
  },
  AvgDialog_117503_Content_67 = {Text = "Sim!"},
  AvgDialog_117503_Content_68 = {Text = "Ding—!"},
  AvgDialog_117503_Content_69 = {
    Text = "Ainda foi bloqueado... Droga, a esse ritmo, quando conseguirei ajudar o Senhor Goliath a conquistar..."
  },
  AvgDialog_117503_Content_7 = {
    Text = "O Navio Paradis já viu muitos pacientes sensíveis ao ambiente oceânico, antes de se adaptarem ao \"Paraíso\", não abalem drasticamente sua espiritualidade."
  },
  AvgDialog_117503_Content_70 = {
    Text = "Calma, garoto, os muros têm ouvidos. Se alguém descobrir, nem você nem eu conseguiremos escapar."
  },
  AvgDialog_117503_Content_71 = {
    Text = "Senhor Goliath, você disse que nossas linhagens vêm dos fortes, devemos temer nada..."
  },
  AvgDialog_117503_Content_72 = {
    Text = "Seu moleque, até os fortes têm seus momentos de depender dos outros. Neste navio, temos que fingir que ouvimos aquelas loucas."
  },
  AvgDialog_117503_Content_73 = {Text = "Mas..."},
  AvgDialog_117503_Content_74 = {
    Text = "Menos conversa, alguém está vindo."
  },
  AvgDialog_117503_Content_75 = {
    Text = "A figura do gigante saiu da sombra da sala de energia, e o rangido da lâmina serrilhada arrastando-se pelo chão quase sobrepôs o rugido do casco do navio."
  },
  AvgDialog_117503_Content_76 = {
    Text = "Nos encontramos de novo, pequeno."
  },
  AvgDialog_117503_Content_77 = {
    Text = "Goliath... como eu cheguei neste navio?"
  },
  AvgDialog_117503_Content_78 = {
    Text = "Deveria perguntar a si mesmo, o território de Miryam não recebe viajantes comuns, quanto mais um barco que aparece de repente."
  },
  AvgDialog_117503_Content_79 = {
    Text = "Não sei que tipo de sorte você tem, mas a garotinha virou do avesso há alguns dias, de qualquer forma, não podemos tocá-lo."
  },
  AvgDialog_117503_Content_8 = {
    Text = "Você se depara com um par de olhos vermelhos que parecem familiares."
  },
  AvgDialog_117503_Content_80 = {
    Text = "Caso contrário, aquela mulher provavelmente vai te pegar para refinar núcleos de prata, afinal, em um mundo onde as pessoas já estão extintas, os núcleos de prata podem ser considerados como algo que se usa e se perde."
  },
  AvgDialog_117503_Content_81 = {
    Text = "E quanto à sua posição? O Goliath que eu conheço não é um fraco que se deixa manipular."
  },
  AvgDialog_117503_Content_82 = {
    Text = "Pequeno, você acabou de embarcar neste navio, há muitas coisas que você ainda não sabe."
  },
  AvgDialog_117503_Content_83 = {
    Text = "Você só precisa lembrar de uma coisa: aquela mulher louca agora está completamente submissa à Mãe Divina. Tudo neste navio é decidido por aquela garotinha."
  },
  AvgDialog_117503_Content_84 = {
    Text = "Não tente ir contra a vontade dela — pelo menos, não deixe que ela descubra."
  },
  AvgDialog_117503_Content_85 = {
    Text = "O resto, eu te contarei quando tivermos a sorte de nos encontrar em outro lugar."
  },
  AvgDialog_117503_Content_86 = {
    Text = "Eu preciso pensar bem... Vamos para o convés sentir a brisa do mar."
  },
  AvgDialog_117503_Content_87 = {
    Text = "Você está sozinho na proa do barco, olhando para longe."
  },
  AvgDialog_117503_Content_88 = {
    Text = "A superfície do mar está envolta em uma névoa branca e suave, enquanto o cruzeiro navega, quebrando o barulho das ondas e o som das máquinas de forma suave e estável."
  },
  AvgDialog_117503_Content_89 = {
    Text = "Você respira fundo o vento do mar misturado com o cheiro salgado e forte, tentando organizar seus pensamentos confusos."
  },
  AvgDialog_117503_Content_9 = {
    Text = "——Tum tum, tum tum——"
  },
  AvgDialog_117503_Content_90 = {
    Text = "Eu segui o barco de William em direção à tempestade, sofri um acidente e fui resgatado pelo Marchador de mares..."
  },
  AvgDialog_117503_Content_91 = {
    Text = "A Criança Santa já nasceu, Murphy se tornou a Mãe Santa dos Marchadores de mares, Miryam está coletando o Núcleo de prata, e Goliath está tramando algo nas sombras..."
  },
  AvgDialog_117503_Content_92 = {
    Text = "<Shake:Clack——>"
  },
  AvgDialog_117503_Content_93 = {
    Text = "Ei, que som é esse?"
  },
  AvgDialog_117503_Content_94 = {
    Text = "Você se virou em busca da origem do som, mas o convés estava silencioso, sem ver uma alma."
  },
  AvgDialog_117503_Content_95 = {
    Text = "(É uma ilusão?)"
  },
  AvgDialog_117503_Content_96 = {
    Text = "<Shake:Pat pat pat——>"
  },
  AvgDialog_117503_Content_97 = {Text = "Huh?!"},
  AvgDialog_117503_Content_98 = {
    Text = "Nas profundezas da água, muitos corpos pequenos se espalham densamente na superfície do mar, o brilho turvo flutuante evoca a imagem de erupções cutâneas humanas."
  },
  AvgDialog_117503_Content_99 = {
    Text = "Esses... são... peixes?"
  },
  AvgDialog_117504_Content_1 = {
    Text = "Cerimônia de Pilotagem"
  },
  AvgDialog_117504_Content_10 = {
    Text = "Estou me preparando para o ritual de navegação com Faros, e os seres espirituais naturalmente se reúnem, tornando-se o alimento do ritual."
  },
  AvgDialog_117504_Content_100 = {
    Text = "Aquela voz te chama——"
  },
  AvgDialog_117504_Content_101 = {
    Text = "<Italic:<Red:Salve-me>>"
  },
  AvgDialog_117504_Content_102 = {
    Text = "Um impulso incontrolável fez você saltar do mastro."
  },
  AvgDialog_117504_Content_103 = {
    Text = "Você deve segurar a mão dela e liberá-la deste ritual sangrento."
  },
  AvgDialog_117504_Content_104 = {
    Text = "Murphy, não continue com o ritual! Você vai morrer! Venha comigo e escape!"
  },
  AvgDialog_117504_Content_105 = {
    Text = "Você está louco? Ousou profanar a Mãe Divina!"
  },
  AvgDialog_117504_Content_106 = {
    Text = "Não sou o Murphy que você conhece, eu já fiz a minha escolha!"
  },
  AvgDialog_117504_Content_107 = {
    Text = "Embora você não seja o Murphy que conheço, já vi muitos corpos despertos da origem - Ramona: Desgastada, Helot: Catena, Doll: Inferno…"
  },
  AvgDialog_117504_Content_108 = {
    Text = "Eles caíram na loucura apenas porque passaram por mais infortúnios no caminho. Os encontros não mudarão a essência de seus corações."
  },
  AvgDialog_117504_Content_109 = {
    Text = "Não se prenda mais ao caminho errado, venha fugir comigo!"
  },
  AvgDialog_117504_Content_11 = {
    Text = "Cerimônia de pilotagem?"
  },
  AvgDialog_117504_Content_110 = {
    Text = "Fugir...? Para onde podemos escapar agora?"
  },
  AvgDialog_117504_Content_111 = {
    Text = "Aqui já é o mundo mais perfeito, qualquer tentativa de fuga apenas cairá em um ciclo de queda mais profunda e desesperadora."
  },
  AvgDialog_117504_Content_112 = {
    Text = "Olhe para trás, as ondas gigantescas atrás de você."
  },
  AvgDialog_117504_Content_113 = {
    Text = "Acompanhado pela fervura intensa da superfície do mar, milhares de Marchadores de mares e serpentes aquáticas cercaram a pálida Estátua de marfim, elevando-se com uma sensação de opressão infinita."
  },
  AvgDialog_117504_Content_114 = {
    Text = "Mãe Divina... peço desculpas, não posso mais seguir suas instruções, não consigo mais tolerar essa tolice de profanar os deuses."
  },
  AvgDialog_117504_Content_115 = {
    Text = "Miryam ajoelha na proa do barco, oferecendo uma cerimônia de sacrifício em direção à linha do horizonte do mar."
  },
  AvgDialog_117504_Content_116 = {
    Text = "Ó Senhor, pessoas de fé sincera. Os profanadores que tentam interromper o ritual já apareceram."
  },
  AvgDialog_117504_Content_117 = {
    Text = "Por favor, puna os ousados irreverentes que se atreverem a ofender a Mãe Divina."
  },
  AvgDialog_117504_Content_118 = {
    Text = "Eles pisaram em uma escada invisível formada pelas ondas do mar, com passos escorregadios e estranhos, subindo silenciosamente para o convés do cruzeiro."
  },
  AvgDialog_117504_Content_119 = {
    Text = "<Big:<Shake:Vá, morda-os, despedaça-os!!>>"
  },
  AvgDialog_117504_Content_12 = {
    Text = "A Mãe Divina nos guiará até a Lemúria flutuante."
  },
  AvgDialog_117504_Content_13 = {
    Text = "Vendo você com uma expressão confusa, a expressão de Miryam tornou-se extraordinariamente suave."
  },
  AvgDialog_117504_Content_14 = {
    Text = "Você deve ter muitas dúvidas, não se preocupe, por ordem da Mãe Divina, eu irei responder uma a uma."
  },
  AvgDialog_117504_Content_15 = {
    Text = "……Para ser sincero, sua mudança de atitude já é surpreendente o suficiente."
  },
  AvgDialog_117504_Content_16 = {
    Text = "Ao relembrar o passado, o conflito entre você e os marinheiros é completamente desnecessário."
  },
  AvgDialog_117504_Content_17 = {
    Text = "Como é possível, eu já vi com meus próprios olhos os Marchadores de mares realizando rituais malignos..."
  },
  AvgDialog_117504_Content_18 = {
    Text = "Foi um mal-entendido. Os Marchadores de mares realizam rituais secretos para coletar a energia que mantém este navio navegando."
  },
  AvgDialog_117504_Content_19 = {
    Text = "Neste momento em que a maioria da humanidade se transformou em cinzas, os núcleos de prata acumulados são suficientes para satisfazer nossas necessidades."
  },
  AvgDialog_117504_Content_2 = {
    Text = "No meio do cheiro forte de peixe, a mulher de manto roxo franziu a testa e se virou para Faros ao lado."
  },
  AvgDialog_117504_Content_20 = {
    Text = "Por isso, os Marchadores de Mares foram até a Necrópole para coletar Prata dos falecidos. Infelizmente, nosso plano acabou conflitando com os apetites de Doresain, o Rei da Necrópole."
  },
  AvgDialog_117504_Content_21 = {
    Text = "De acordo com o nosso conhecimento sobre a Universidade de Misag, vocês também usam o Núcleo de prata refinado como fonte de energia, não é?"
  },
  AvgDialog_117504_Content_22 = {
    Text = "A chave de prata em seu peito é feita com o processo de núcleo de prata."
  },
  AvgDialog_117504_Content_23 = {
    Text = "Você não consegue reconhecer de imediato, mas também não tem forças para refutar, apenas muda de assunto."
  },
  AvgDialog_117504_Content_24 = {
    Text = "Miryam... qual é o seu objetivo com os Marchadores de mares?"
  },
  AvgDialog_117504_Content_25 = {
    Text = "Naturalmente, reconstruir o Reino Divino e revitalizar Lemúria."
  },
  AvgDialog_117504_Content_26 = {
    Text = "Neste momento em que nosso Senhor já chegou, nada é mais importante do que o retorno ao Reino Divino e a restauração da grandiosidade de Lemúria."
  },
  AvgDialog_117504_Content_27 = {
    Text = "Você se refere à chegada de… Tulu?"
  },
  AvgDialog_117504_Content_28 = {
    Text = "Seu espírito ainda está em um estado de meio sonho, meio acordado, mas Ele cumprirá Sua promessa e nos guiará de volta ao Reino Divino."
  },
  AvgDialog_117504_Content_29 = {
    Text = "Lemúria... onde está?"
  },
  AvgDialog_117504_Content_3 = {
    Text = "Cole a espiritualidade aqui."
  },
  AvgDialog_117504_Content_30 = {
    Text = "Acima dos céus, abaixo do mar. O oráculo não revelou mais."
  },
  AvgDialog_117504_Content_31 = {
    Text = "Após dizer essa senha, Miryam caiu em silêncio."
  },
  AvgDialog_117504_Content_32 = {
    Text = "Faros, que havia reunido todos os núcleos de prata, parou ao lado de Miryam, segurando uma caixa de madeira cheia de pérolas de prata."
  },
  AvgDialog_117504_Content_33 = {
    Text = "Faros, por que você se juntou aos Marchadores de mares?"
  },
  AvgDialog_117504_Content_34 = {
    Text = "Isso ainda precisa ser perguntado? Porque o reino do mar está ali. O reino do mar está me chamando."
  },
  AvgDialog_117504_Content_35 = {
    Text = "Onde quer que eu vá, posso ouvir a Sua voz chamando, como o surge contínuo das marés dia após dia."
  },
  AvgDialog_117504_Content_36 = {
    Text = "Ela olhava para o horizonte, suas palavras eram apenas um nada."
  },
  AvgDialog_117504_Content_37 = {
    Text = "Parece que hoje será um bom dia. Olha, o sol está prestes a sair."
  },
  AvgDialog_117504_Content_38 = {Text = "sol…"},
  AvgDialog_117504_Content_39 = {
    Text = "Você segue o olhar dela e olha para—"
  },
  AvgDialog_117504_Content_4 = {
    Text = "Sim, Grande Sacerdote."
  },
  AvgDialog_117504_Content_40 = {
    Text = "Rumble, rumble. O som do seu coração quase estoura seus tímpanos."
  },
  AvgDialog_117504_Content_41 = {
    Text = "<Shake:Espere, onde está o... sol?>"
  },
  AvgDialog_117504_Content_42 = {
    Text = "Sol? O sol não está bem ali?"
  },
  AvgDialog_117504_Content_43 = {
    Text = "Não, não, não é esse sol!"
  },
  AvgDialog_117504_Content_44 = {
    Text = "No nível do mar, ergue-se um sol que você deveria almejar, irradiando luz suavemente através da névoa fina."
  },
  AvgDialog_117504_Content_45 = {
    Text = "Não é este sol? Qual outro sol há?"
  },
  AvgDialog_117504_Content_46 = {
    Text = "A luz quente parece emitir um calor anormal, fazendo você perder a razão, sua garganta seca, e as palavras que saem de sua boca são difíceis de entender."
  },
  AvgDialog_117504_Content_47 = {
    Text = "Deve ser um sol negro e sem luz!"
  },
  AvgDialog_117504_Content_48 = {
    Text = "Nunca ouvi falar ou vi um sol negro..."
  },
  AvgDialog_117504_Content_49 = {
    Text = "Faros, qual é o ano este ano?"
  },
  AvgDialog_117504_Content_5 = {
    Text = "Faros estava de joelhos no chão, recolhendo os restos fétidos um a um."
  },
  AvgDialog_117504_Content_50 = {
    Text = "Ano 1920. Há algo errado?"
  },
  AvgDialog_117504_Content_51 = {
    Text = "Não é a Era Aluvião... eu realmente estou em um novo mundo..."
  },
  AvgDialog_117504_Content_52 = {
    Text = "Não se distraia, a Mãe Divina chegou."
  },
  AvgDialog_117504_Content_53 = {
    Text = "Como convidado aprovado pela Mãe Divina, eu lhe concederei a permissão para assistir à mais grandiosa cerimônia de pilotagem."
  },
  AvgDialog_117504_Content_54 = {
    Text = "Mas não se afaste deste lugar, ou eu terei que decapitar o profanador e expô-lo ao público."
  },
  AvgDialog_117504_Content_55 = {
    Text = "Um pequeno grupo de cor preto e roxo vem da parte traseira do cruzeiro, seus passos se movem de forma estranha e sincronizada, rastejando em direção ao convés sob seus pés."
  },
  AvgDialog_117504_Content_56 = {
    Text = "A menina à frente vestia um vestido branco pálido e sem vida, segurando um fardo volumoso nos braços, seu olhar sob o véu negro era confuso e indistinto."
  },
  AvgDialog_117504_Content_57 = {Text = "..."},
  AvgDialog_117504_Content_58 = {
    Text = "A fila rapidamente se posicionou na proa do navio, cada peça preta parecia já estar familiarizada com seu ponto de queda."
  },
  AvgDialog_117504_Content_59 = {
    Text = "Um par de pés descalços entrou no estreito caminho deixado para ela entre os grupos, enquanto atrás dela, inúmeras pequenas partículas prateadas caíam suavemente."
  },
  AvgDialog_117504_Content_6 = {
    Text = "Ela emitiu uma luz suave de sua testa, e alguns segundos depois, apenas restos prateados do cardume permaneceram."
  },
  AvgDialog_117504_Content_60 = {
    Text = "Agradecemos à Mãe Professora pela doação do sangue umbilical! Com certeza, iremos engolir o fogo espiritual, beber a oração de sangue, e milhares de almas devotas se transformarão em faróis!"
  },
  AvgDialog_117504_Content_61 = {
    Text = "Os monstros rastejam no chão, disputando as pérolas prateadas no chão."
  },
  AvgDialog_117504_Content_62 = {
    Text = "……Miryam……"
  },
  AvgDialog_117504_Content_63 = {
    Text = "Miryam se inclinou humildemente ao chão, com as mãos levantando um prato prateado de veludo negro, no centro do qual estava um punhal brilhante."
  },
  AvgDialog_117504_Content_64 = {
    Text = "Respeitada Mãe Divina, por favor, guie o sangue do Rei Divino, oriente os Marchadores de Mares perdidos e aponte-nos a localização de Lemúria."
  },
  AvgDialog_117504_Content_65 = {
    Text = "A menina pegou o punhal."
  },
  AvgDialog_117504_Content_66 = {
    Text = "Querido Rei Divino..."
  },
  AvgDialog_117504_Content_67 = {
    Text = "O punhal mergulha no manto, uma gota de sangue viscoso parece ter consciência própria, flutuando e se condensando."
  },
  AvgDialog_117504_Content_68 = {
    Text = "<Change>Eu sigo o caminho do sangue divino."
  },
  AvgDialog_117504_Content_69 = {
    Text = "Todos os crentes se ajoelharam no chão, com as mãos levantadas para o céu, e cortaram o pulso esquerdo coberto de escamas com uma fina faca."
  },
  AvgDialog_117504_Content_7 = {
    Text = "Miryam... esses peixes voadores... foram você e Faros que os invocaram?"
  },
  AvgDialog_117504_Content_70 = {
    Text = "Incontáveis filamentos prateados enrolam-se em torno das gotas de sangue, espalhando-se a partir dos pulsos de uma centena de fiéis, seguindo uma trajetória inefável em direção ao mesmo ponto."
  },
  AvgDialog_117504_Content_71 = {
    Text = "<Change>Com o espírito de todas as coisas como sacrifício."
  },
  AvgDialog_117504_Content_72 = {
    Text = "Gotas de sangue negro giram, se condensam e saltam para dentro de uma estátua de marfim leitosa, infiltrando-se em uma rede fina de veias sanguíneas."
  },
  AvgDialog_117504_Content_73 = {
    Text = "A estátua de marfim parece ter sido ativada com vida, voando sobre a besta de aço, caindo diretamente no oceano silencioso."
  },
  AvgDialog_117504_Content_74 = {
    Text = "<Change>Por favor, rasgue a ilusão do abismo marinho e nos guie diretamente ao seu reino."
  },
  AvgDialog_117504_Content_75 = {
    Text = "Num instante, o céu e o mar tremiam, todo o vasto oceano rugia, emitindo um lamento como o de uma besta prestes a dar à luz."
  },
  AvgDialog_117504_Content_76 = {
    Text = "As ondas dançam loucamente, lamentando-se, formando uma parede de ondas tremulantes."
  },
  AvgDialog_117504_Content_77 = {
    Text = "Mãe Divina, a quantidade de materiais parece estar um pouco insuficiente..."
  },
  AvgDialog_117504_Content_78 = {
    Text = "Sem problemas."
  },
  AvgDialog_117504_Content_79 = {
    Text = "A menina levantou o véu e se virou para os seres que estavam de joelhos."
  },
  AvgDialog_117504_Content_8 = {
    Text = "Miryam parece ter notado sua presença apenas agora, inclinando levemente a cabeça na sua direção."
  },
  AvgDialog_117504_Content_80 = {
    Text = "Por favor, que a Mãe Divina conceda Sangue Sagrado!"
  },
  AvgDialog_117504_Content_81 = {
    Text = "<Big:<Shake:Por favor, Mãe Divina, conceda-me sangue sagrado!>>"
  },
  AvgDialog_117504_Content_82 = {
    Text = "O clamor aumentava a cada instante, e no meio dos gritos, os dedos da menina se estenderam em direção ao seu peito."
  },
  AvgDialog_117504_Content_83 = {
    Text = "Suas unhas eram afiadas como lâminas, rasgando o peito ao longo da cicatriz roxa, revelando o único coração restante."
  },
  AvgDialog_117504_Content_84 = {
    Text = "<Shake:Capture, hunt! Se eu oferecer carne e sangue da Mãe Divina, você certamente forjará para mim a escada reversa que conecta ao Reino Divino!>"
  },
  AvgDialog_117504_Content_85 = {
    Text = "Os fiéis se precipitaram. Suas nadadeiras e garras monstruosas se estendiam impacientes em direção ao corpo frágil da Mãe Divina."
  },
  AvgDialog_117504_Content_86 = {
    Text = "Eles sugam seu sangue e devoram sua carne. Fios vermelhos proliferam intensamente, correndo para o Mar Profundo."
  },
  AvgDialog_117504_Content_87 = {
    Text = "Carmesim prolifera freneticamente a partir do ponto de queda da estátua, enquanto as ondas se solidificam em milhões de corais de sangue."
  },
  AvgDialog_117504_Content_88 = {
    Text = "O ritual terminou! Saia!"
  },
  AvgDialog_117504_Content_89 = {
    Text = "Ela pisou sobre o corpo do Marchador de mares que estava à frente da menina, envolveu o corpo de Murphy com uma pesada túnica negra. Sob a túnica, o sangue ainda escorria lentamente."
  },
  AvgDialog_117504_Content_9 = {
    Text = "Você não deveria estar na sala de estar da Mãe Divina? Por que..."
  },
  AvgDialog_117504_Content_90 = {
    Text = "Lemúria! Lemúria! O sangue da Mãe Divina já revelou o caminho de Lemúria!"
  },
  AvgDialog_117504_Content_91 = {
    Text = "Entre milhares de veias de sangue, você vislumbra um fio prateado anômalo. Esse fio prateado surge do seu peito e se estende para cima, se estendendo..."
  },
  AvgDialog_117504_Content_92 = {
    Text = "Até além do céu, em algum lugar desconhecido."
  },
  AvgDialog_117504_Content_93 = {
    Text = "A menina pareceu perceber a existência daquela linha prateada, ela levantou a cabeça e olhou, suas pupilas tremeram de repente, e seu olhar assustado perfurou o lugar onde você estava."
  },
  AvgDialog_117504_Content_94 = {Text = "..."},
  AvgDialog_117504_Content_95 = {
    Text = "No instante em que os olhares se encontram, uma força invisível e imensa puxa você, desconsiderando toda a sua resistência, fazendo você cair diretamente em uma ilusão aterrorizante, como um pesadelo."
  },
  AvgDialog_117504_Content_96 = {
    Text = "…esse é o sol negro que você já viu, não limpo."
  },
  AvgDialog_117504_Content_97 = {
    Text = "Som de tambor?"
  },
  AvgDialog_117504_Content_98 = {
    Text = "Não, isso é o som dos batimentos cardíacos."
  },
  AvgDialog_117504_Content_99 = {
    Text = "longa, ofegante, à beira da morte, que há muito desapareceu nos tempos antigos, mas que ressurgiu após um longo sonho..."
  },
  AvgDialog_118123_Content_1 = {
    Text = "Cavaleiro do Vento"
  },
  AvgDialog_118123_Content_10 = {
    Text = "Foi com essa expectativa que dei uma chance a esse cara."
  },
  AvgDialog_118123_Content_11 = {
    Text = "(E o resultado ainda é, não serve para nada...)"
  },
  AvgDialog_118123_Content_12 = {
    Text = "Como eu pensei... eu realmente preciso dar uma mão."
  },
  AvgDialog_118123_Content_13 = {
    Text = "Correndo como uma mosca sem cabeça! Para onde você está indo afinal!"
  },
  AvgDialog_118123_Content_14 = {
    Text = "Como o companheiro mais velho William disse agora há pouco, o bote salva-vidas do convés para o porão!"
  },
  AvgDialog_118123_Content_15 = {
    Text = "O campo de visão do convés é tão amplo, vejo que você quer se oferecer para alimentar os peixe-homens!"
  },
  AvgDialog_118123_Content_16 = {
    Text = "Na última reencarnação, quem foi alimentar os homens-peixe foi você mesmo!"
  },
  AvgDialog_118123_Content_17 = {
    Text = "Droga, não ouse discutir com a Mãe Divina! Agora, corra para a cabine, lá há uma estrutura que leva ao compartimento de emergência!"
  },
  AvgDialog_118123_Content_18 = {
    Text = "Ainda me solte, meu cabelo já está todo bagunçado, parecendo um ninho de passarinho!"
  },
  AvgDialog_118123_Content_19 = {
    Text = "Você é uma refém importante para mim, não é hora de se preocupar com a imagem! Então, por favor, Mãe Divina, aguente mais um pouco!"
  },
  AvgDialog_118123_Content_2 = {
    Text = "Você salta, sentindo o vento cortante rasgar suas bochechas, e então a corda na sua cintura se aperta de repente, interrompendo a queda."
  },
  AvgDialog_118123_Content_20 = {
    Text = "<Shake:Cuidado, os perseguidores de Miryam estão se aproximando!>"
  },
  AvgDialog_118123_Content_3 = {
    Text = "Ei! O que você está fazendo?!"
  },
  AvgDialog_118123_Content_4 = {
    Text = "Você saca uma faca pequena, corta a corda e cai no chão."
  },
  AvgDialog_118123_Content_5 = {
    Text = "Você vai correr assim, me carregando? Eles vão nos alcançar em breve, certo!"
  },
  AvgDialog_118123_Content_6 = {
    Text = "Ah, isso é tão idiota!"
  },
  AvgDialog_118123_Content_7 = {
    Text = "O que eu estava pensando, a ponto de ter uma pequena esperança por esse idiota."
  },
  AvgDialog_118123_Content_8 = {
    Text = "Esta fuga de {Male=ele,Female=ela} é mais imprudente do que todas as que fiz no passado."
  },
  AvgDialog_118123_Content_9 = {
    Text = "Se este mundo também existe <Amarelo:%player%>, a direção da história seria diferente?"
  },
  AvgDialog_118124_Content_1 = {
    Text = "Você puxou a cortina e amarrou Murphy, que estava com garras à mostra."
  },
  AvgDialog_118124_Content_10 = {
    Text = "Se você observar atentamente nós três, saberá que a princesa é outra pessoa."
  },
  AvgDialog_118124_Content_11 = {
    Text = "William amarrou firmemente a corda em suas cinturas e na de Murphy."
  },
  AvgDialog_118124_Content_12 = {
    Text = "Cuidado para cuidar bem da princesa, não a perca! No compartimento inferior do navio há botes salva-vidas, vamos nos reunir lá!"
  },
  AvgDialog_118124_Content_13 = {
    Text = "Três, dois, um, pule!"
  },
  AvgDialog_118124_Content_2 = {
    Text = "Resolvido! Não se mexa, cuidado para não se machucar!"
  },
  AvgDialog_118124_Content_3 = {
    Text = "Que saco! Se continuar assim, vou te morder!"
  },
  AvgDialog_118124_Content_4 = {
    Text = "Ainda assim, não agir de forma afetada é mais parecido com você, Murphy."
  },
  AvgDialog_118124_Content_5 = {
    Text = "Menos conversa! A culpa de humilhar a Mãe Divina será cobrada quando eu recuperar minha liberdade!"
  },
  AvgDialog_118124_Content_6 = {
    Text = "No entanto, os passos do lado de fora não estão ficando cada vez mais intensos?"
  },
  AvgDialog_118124_Content_7 = {
    Text = "Os passos abafados se uniram em um mar, enquanto corpos baixos e robustos continuavam a colidir contra a porta da sala, produzindo um som surdo de bang bang."
  },
  AvgDialog_118124_Content_8 = {
    Text = "Vamos, quebremos a janela e saíamos! Pegue isso e pule para o convés!"
  },
  AvgDialog_118124_Content_9 = {
    Text = "Amarrando lençóis... ? William, você parece uma princesa fugitiva de um conto de fadas."
  },
  AvgDialog_118125_Content_1 = {
    Text = "Princesa da Torre"
  },
  AvgDialog_118125_Content_10 = {
    Text = "Você observa atentamente, há duas linhas de fio quebradas, e ainda restam quatro voltas de fio na roda de fiar."
  },
  AvgDialog_118125_Content_11 = {
    Text = "Eu ainda tenho quatro chances... certo?"
  },
  AvgDialog_118125_Content_12 = {
    Text = "Ela assentiu e depois balançou a cabeça."
  },
  AvgDialog_118125_Content_13 = {
    Text = "Eu ouvi sua voz, você não é mudo... você não tem permissão para dizer nada...?"
  },
  AvgDialog_118125_Content_14 = {
    Text = "Ela abriu a boca, mas só o silêncio eterno saiu."
  },
  AvgDialog_118125_Content_15 = {
    Text = "Ela olhou para o céu distante, e você seguiu o olhar dela em direção ao horizonte."
  },
  AvgDialog_118125_Content_16 = {
    Text = "Lá havia apenas um sol negro mergulhado na água."
  },
  AvgDialog_118125_Content_17 = {
    Text = "Cof, cof...!"
  },
  AvgDialog_118125_Content_18 = {
    Text = "Você acorda de repente da cama, tossindo e ofegante devido à dor de estar se afogando."
  },
  AvgDialog_118125_Content_19 = {
    Text = "Mais uma vez... o ciclo..."
  },
  AvgDialog_118125_Content_2 = {
    Text = "O vento do mar é salgado e cheiroso, trazendo um gosto amargo que não se vai quando entra na boca."
  },
  AvgDialog_118125_Content_20 = {
    Text = "As pessoas do Reino do Mar, algumas surpresas, outras indiferentes, algumas com preocupações reais e outras falsas, estão agora separadas de você por barreiras pesadas, e na sua mente apenas a imagem de Murphy antes do fim da última reencarnação permanece."
  },
  AvgDialog_118125_Content_21 = {
    Text = "Socorro... Se for você, com certeza pode..."
  },
  AvgDialog_118125_Content_22 = {
    Text = "Então a escuridão consumiu tudo, transformando-se em uma dúvida persistente na mente."
  },
  AvgDialog_118125_Content_23 = {
    Text = "De qualquer forma, você precisa se encontrar com William primeiro."
  },
  AvgDialog_118125_Content_24 = {
    Text = "Goliath e Miryam caminhavam por um corredor vazio, os passos à frente e atrás ecoavam."
  },
  AvgDialog_118125_Content_25 = {
    Text = "Passando pela pintura da Virgem Maria em estilo barroco, pequenas lanternas substituindo os apliques de bronze e um grupo de quartos silenciosos e desabitados."
  },
  AvgDialog_118125_Content_26 = {
    Text = "Eles não se tocaram, não disseram nada, e a atmosfera tensa pairava entre os dois."
  },
  AvgDialog_118125_Content_27 = {
    Text = "Miryam parou na porta da cabine do capitão e virou-se para abrir a porta."
  },
  AvgDialog_118125_Content_28 = {
    Text = "Goliath deu alguns passos e parou atrás dela."
  },
  AvgDialog_118125_Content_29 = {
    Text = "Ei, Miryam. Aquela garotinha está te enganando."
  },
  AvgDialog_118125_Content_3 = {Text = "..."},
  AvgDialog_118125_Content_30 = {
    Text = "O que você tem? A essa hora, você deveria estar vigiando a cabine, certo?"
  },
  AvgDialog_118125_Content_31 = {
    Text = "Se a mulher que mantém a sala de energia tiver qualquer desvio, eu só perguntarei a você."
  },
  AvgDialog_118125_Content_32 = {
    Text = "Pare de falar bobagens, aquele Caecus está observando, e aqueles idiotas da tripulação não causarão nenhuma agitação."
  },
  AvgDialog_118125_Content_33 = {
    Text = "A única questão é que aquela garotinha está te enganando."
  },
  AvgDialog_118125_Content_34 = {
    Text = "Filisteu, falar mal da Mãe Divina não é o seu costume."
  },
  AvgDialog_118125_Content_35 = {
    Text = "Você sabe que este navio nunca chegará a essa tal Lemúria, não sabe?"
  },
  AvgDialog_118125_Content_36 = {
    Text = "…Goliath."
  },
  AvgDialog_118125_Content_37 = {
    Text = "Você é apenas meu cão de caça. Enquanto eu não lhe der a ordem de brandir a lâmina contra algum inimigo, não há espaço para você falar à toa aqui."
  },
  AvgDialog_118125_Content_38 = {
    Text = "Antes de atracar, você só precisa cuidar dos marinheiros a bordo para mim, não deixe que eles interfiram no sono da Mãe Divina."
  },
  AvgDialog_118125_Content_39 = {
    Text = "Se há algo que você precisa saber…"
  },
  AvgDialog_118125_Content_4 = {
    Text = "A mulher segurando a roca olha para você com tristeza."
  },
  AvgDialog_118125_Content_40 = {
    Text = "<Shake:Se este navio tem a menor chance de chegar a Lemuria, é por causa do brilho da Mãe Divina.>"
  },
  AvgDialog_118125_Content_41 = {
    Text = "Tsc, mulher maldita e teimosa..."
  },
  AvgDialog_118125_Content_42 = {
    Text = "Já disse tanto coisas boas quanto ruins."
  },
  AvgDialog_118125_Content_43 = {
    Text = "Então, não me culpe pelo que acontecer a seguir."
  },
  AvgDialog_118125_Content_44 = {
    Text = "Caecus, execute o plano."
  },
  AvgDialog_118125_Content_45 = {Text = "Aqui!"},
  AvgDialog_118125_Content_46 = {
    Text = "Antes que o ritual termine, tome o controle principal do navio."
  },
  AvgDialog_118125_Content_47 = {
    Text = "Você anda pelo convés, tentando encontrar pistas que possam levar ao esconderijo de William."
  },
  AvgDialog_118125_Content_48 = {
    Text = "Se não me engano, é aqui neste lugar…"
  },
  AvgDialog_118125_Content_49 = {
    Text = "Você levanta a tampa da porta ao longo da fenda no convés e, mordendo os lábios, pula para baixo."
  },
  AvgDialog_118125_Content_5 = {
    Text = "Você tem algo a me dizer?"
  },
  AvgDialog_118125_Content_50 = {
    Text = "<Shake:Pu, phew...>"
  },
  AvgDialog_118125_Content_51 = {
    Text = "Você tossiu a gramínea que colocou na boca, arrependendo-se de ter escolhido o método de queda de frente."
  },
  AvgDialog_118125_Content_52 = {
    Text = "William, o companheiro mais velho, não se esconda, eu sei que você está aqui!"
  },
  AvgDialog_118125_Content_53 = {
    Text = "Depois de um tempo, ouviram-se alguns sons sussurrantes atrás da pilha de capim."
  },
  AvgDialog_118125_Content_54 = {
    Text = "Isso não faz sentido."
  },
  AvgDialog_118125_Content_55 = {
    Text = "…se você tivesse a habilidade de me localizar com tanta precisão, já teria me alcançado nas ruas de Londres."
  },
  AvgDialog_118125_Content_56 = {
    Text = "Vamos conversar… O que você passou depois de embarcar neste navio?"
  },
  AvgDialog_118125_Content_57 = {Text = "..."},
  AvgDialog_118125_Content_58 = {
    Text = "Você descreveu a história do ciclo em poucas palavras."
  },
  AvgDialog_118125_Content_59 = {
    Text = "Desculpe, não teremos tempo quando o ritual começar. \n William, o companheiro mais velho, precisamos desativar a emboscada na sala de estar do Murphy antes disso."
  },
  AvgDialog_118125_Content_6 = {
    Text = "A mulher acenou com a cabeça."
  },
  AvgDialog_118125_Content_60 = {
    Text = "Vá, por este caminho, aqui não há vigilância."
  },
  AvgDialog_118125_Content_61 = {
    Text = "Você quer dizer que Goliath está tramando uma rebelião e eu preciso me esconder com você."
  },
  AvgDialog_118125_Content_62 = {
    Text = "E tudo isso é porque você passou pela experiência de retrocesso no tempo, por isso sabe disso?"
  },
  AvgDialog_118125_Content_63 = {
    Text = "Muito absurdo, muito sem sentido... a menos que minha mente tenha perdido o controle...<Shake:Umm...>"
  },
  AvgDialog_118125_Content_64 = {
    Text = "Desculpe, não há espaço para a sua teimosia aqui."
  },
  AvgDialog_118125_Content_65 = {
    Text = "Sênior William!"
  },
  AvgDialog_118125_Content_66 = {
    Text = "Fique tranquilo, eu suspeitava que não seria tão fácil, já isolei os sons do exterior da sala de estar."
  },
  AvgDialog_118125_Content_67 = {
    Text = "Levem-na embora primeiro!"
  },
  AvgDialog_118125_Content_7 = {
    Text = "Isso tem a ver com o ciclo?"
  },
  AvgDialog_118125_Content_8 = {
    Text = "A mulher balança a cabeça, as pontas dos dedos acariciando o fio da roca, girando no sentido horário por uma volta, parando no ponto de origem."
  },
  AvgDialog_118125_Content_9 = {
    Text = "Com a rotação do fuso, o fio inicial se desfez e quebrou."
  },
  AvgDialog_118699_Content_1 = {
    Text = "Nosso desejo"
  },
  AvgDialog_118699_Content_10 = {
    Text = "Mais força espiritual intensa...? Entendi, vou enviar uma notificação a todos os Corpos Despertos."
  },
  AvgDialog_118699_Content_11 = {
    Text = "No campo de treinamento ao anoitecer, Ogier terminou seu treinamento diário habitual, sem nenhuma redução em relação ao passado."
  },
  AvgDialog_118699_Content_12 = {
    Text = "Hoje, quebrei um pouco mais do recorde passado…"
  },
  AvgDialog_118699_Content_13 = {
    Text = "Secando o suor que escorria, com a pesada lança apoiada no chão, Ogier olhou para trás e não viu mais a figura sorridente que lhe enviava encorajamento, apenas sua própria sombra solitária se arrastando no chão."
  },
  AvgDialog_118699_Content_14 = {
    Text = "A espada afiada de Lotan lançou para o alto duas armas convencionais do investigador na sombra, encerrando mais uma batalha que durou apenas um minuto."
  },
  AvgDialog_118699_Content_15 = {
    Text = "O que está acontecendo com os novos alunos de hoje em dia? A qualidade deles está muito baixa, vamos lá!"
  },
  AvgDialog_118699_Content_16 = {
    Text = "Antes que ela pudesse levantar a espada para continuar a intimidar, os dois novos nascidos à sua frente já começaram a juntar as mãos e implorar por misericórdia."
  },
  AvgDialog_118699_Content_17 = {
    Text = "Tsc, entediante…"
  },
  AvgDialog_118699_Content_18 = {
    Text = "Lembrando-se de um sujeito que poderia proporcionar-lhe uma luta emocionante, Lotan suspirou ao olhar para o pôr do sol e se virou, entediada, para ir embora."
  },
  AvgDialog_118699_Content_19 = {
    Text = "Aigis cortou um pedaço de linha solta, cuidadosamente desenrolou o suéter recém-tricotado, alisou-o e, em seguida, na ponta dos pés, colocou-o no armário cheio de tecidos."
  },
  AvgDialog_118699_Content_2 = {
    Text = [[
Mundo de Cardas
Agora]]
  },
  AvgDialog_118699_Content_20 = {
    Text = "Aigis está tecendo cada vez mais estilos, como padrões de trançado, losangos, ondulados, flores pequenas e animais."
  },
  AvgDialog_118699_Content_21 = {
    Text = "Grande {Male=Sr. Guardião,Female=Srta. Guardiã}, que tipo você gostaria..."
  },
  AvgDialog_118699_Content_22 = {
    Text = "O inteligente ratinho cinza passou pelo buraco da porta e colocou fielmente um anel brilhante na mão do parceiro."
  },
  AvgDialog_118699_Content_23 = {
    Text = "Hmm, bom trabalho, Marrom."
  },
  AvgDialog_118699_Content_24 = {
    Text = "O ratinho olhou para seu companheiro, que, entediado, deu um bocejo e jogou o anel descuidadamente em uma caixa de madeira aberta ao lado, onde as \"coleções\" bagunçadas já estavam transbordando."
  },
  AvgDialog_118699_Content_25 = {Text = "Chirp..."},
  AvgDialog_118699_Content_26 = {
    Text = "Aquela pessoa não vem ao dormitório há muito tempo para vasculhar o baú deles, obrigando o líder a devolver os itens um por um, mas por que, mesmo assim, o líder ainda está triste?"
  },
  AvgDialog_118699_Content_27 = {
    Text = "A menina obediente senta-se de maneira adequada à frente da mesa, abrindo mais um livro de histórias."
  },
  AvgDialog_118699_Content_28 = {
    Text = "No canto da mesa, já havia uma alta pilha de livros infantis lidos, e no caderno da menina, ela anotava as ideias de histórias que surgiam."
  },
  AvgDialog_118699_Content_29 = {
    Text = "Ao pensar em empolgação, o rosto sereno da menina revelou um leve sorriso, enquanto seus pés balançavam suavemente embaixo da mesa."
  },
  AvgDialog_118699_Content_3 = {
    Text = "O túnel difuso ainda não formado foi destruído pela corrosão do terror que apareceu de repente, e o corpo de Ramona soltou um gemido abafado, recuperando a consciência sob a convocação urgente do equipamento."
  },
  AvgDialog_118699_Content_30 = {
    Text = "Essa história, com certeza, todos vão gostar…"
  },
  AvgDialog_118699_Content_31 = {
    Text = "O lápis fazia barulho enquanto registrava as fantasias inocentes. Mas logo a menina parou de escrever e ficou olhando para fora da janela com um olhar vazio."
  },
  AvgDialog_118699_Content_32 = {
    Text = "Mas quando o grande {Male=Sr. Guardião,Female=Srta. Guardiã} poderá voltar a levar Lily para filmar?"
  },
  AvgDialog_118699_Content_33 = {Text = "..."},
  AvgDialog_118699_Content_34 = {
    Text = "O guerreiro derramou a bolsa de vinho sobre a terra na frente da lápide."
  },
  AvgDialog_118699_Content_35 = {
    Text = "Depois de beber o restante de meio jarro de vinho, o guerreiro partiu em silêncio, restando apenas uma coroa de louros pendurada silenciosamente sobre a lápide."
  },
  AvgDialog_118699_Content_36 = {
    Text = "Na deslumbrante toalha de veludo, o chá da tarde da dama continua a ser tão farto como sempre."
  },
  AvgDialog_118699_Content_37 = {
    Text = "O barulho contido de talheres contra pratos trouxe o rico bolo de creme à boca."
  },
  AvgDialog_118699_Content_38 = {
    Text = "Durante o desfrute excessivamente silencioso, a dama olhou silenciosamente para a cadeira vazia à sua frente, aquela louça destinada àquela pessoa."
  },
  AvgDialog_118699_Content_39 = {
    Text = "Deixar o mestre sozinho aqui é realmente uma serva incompetente..."
  },
  AvgDialog_118699_Content_4 = {
    Text = "Ramona! Pollux! Como vocês estão?"
  },
  AvgDialog_118699_Content_40 = {
    Text = "Em um dormitório vazio deixado de propósito, a mobília limpa e nova parece desabitada, apenas uma muda de árvore recém-brotada está colocada na frente da janela."
  },
  AvgDialog_118699_Content_41 = {
    Text = "Em momentos extremamente raros, alguém pode ver atrás daquela janela uma mulher de pele dourada apoiada no peitoril, envolvendo delicadamente aquele vaso de muda."
  },
  AvgDialog_118699_Content_42 = {
    Text = "Mesmo agora, com as atividades do clube gradualmente ressuscitando e se tornando ativas, ninguém se atreve a perturbar esta sala de música pertencente ao mestre intérprete."
  },
  AvgDialog_118699_Content_43 = {Text = "..."},
  AvgDialog_118699_Content_44 = {
    Text = "As cortinas foram levemente levantadas pelo vento da noite, Hameln estava em frente ao piano, olhando na direção do campanário."
  },
  AvgDialog_118699_Content_45 = {
    Text = "Diante das teclas que um dia tocaram juntas, não há ninguém, apenas o som da flauta, repetido dia após dia, flutua suavemente sob a luz da lua, sem ninguém a ouvir."
  },
  AvgDialog_118699_Content_46 = {
    Text = "Nas profundezas da piscina negra, o prisioneiro da eterna solidão atrás da porta agora tem um companheiro adormecido."
  },
  AvgDialog_118699_Content_47 = {
    Text = "Aqueles olhos de compaixão abriram-se em silêncio, observando a alma flutuando no corpo distante."
  },
  AvgDialog_118699_Content_48 = {
    Text = "No laboratório do departamento de pesquisa, Ramona, que ainda está treinando sua força mental dia e noite, já está com a roupa de treino encharcada de suor."
  },
  AvgDialog_118699_Content_49 = {
    Text = "Dôl observou aquela figura lutadora, silenciosamente bebeu mais uma xícara de café forte, abriu uma nova página do relatório de experimento e continuou ajustando os dados do equipamento."
  },
  AvgDialog_118699_Content_5 = {
    Text = "Cof... Estou bem, a interrupção foi bem na hora."
  },
  AvgDialog_118699_Content_50 = {
    Text = "<Small:Ah, o café do Winkle realmente está um pouco forte...>"
  },
  AvgDialog_118699_Content_51 = {
    Text = "Na comunicação que ela acabou de liberar, brilha uma notificação enviada a todos os Corpos Despertos."
  },
  AvgDialog_118699_Content_52 = {
    Text = "Todos os Corpos Despertos no campus olharam ao mesmo tempo para o comunicador que de repente tocou, olhando para o nome que esperaram tanto tempo."
  },
  AvgDialog_118699_Content_53 = {
    Text = "A todos os Corpos Despertos: \n\nNo passado recente, ainda estávamos lutando contra a catástrofe negra que devora tudo. Até hoje, na lápide do Keygrave, estão gravados inúmeros nomes embaçados, assim como o nome do Guardião que nos trouxe a paz final. \nEle era nosso amigo, camarada, o estudante que mais faltou nas aulas de Misaq, muitos eram amigos próximos, nosso Guia único e o herói que salvou a todos nós."
  },
  AvgDialog_118699_Content_54 = {
    Text = "Após a perda de {Male=ele,Female=ela}, Misaq perdeu uma cor intensa. Embora todos estejam igualmente tristes, o departamento de pesquisa não abandonou a mínima esperança e continua a buscar vestígios da consciência do Guardião. \n Antes de confirmar o sucesso, eu não queria trazer esperanças desconhecidas a vocês, apenas aumentando a dor da longa espera. Mas agora, já verificamos que é possível encontrar <Amarelo:%player%> e em breve iniciaremos a tentativa final."
  },
  AvgDialog_118699_Content_55 = {
    Text = "Esta batalha para receber {Male=ele,Female=ela} de volta precisa de vocês, precisa de todos nós juntos, transformando a saudade que sentimos por {Male=ele,Female=ela} em um marco para encontrá-lo.\nEu, em nome de Misaq, convido sinceramente todos vocês a se unirem antes de chegarmos à Piscina Negra, assim como na última batalha, para lutar lado a lado novamente por <Amarelo:%player%>. \n\nSeu companheiro Doll"
  },
  AvgDialog_118699_Content_56 = {
    Text = [[
Mundo Cardas
Dia do Acordo]]
  },
  AvgDialog_118699_Content_57 = {
    Text = "Sob a torre do relógio, diante da piscina negra em silêncio, estava cheia de multidão tranquila."
  },
  AvgDialog_118699_Content_58 = {
    Text = "Depois que Doll explicou o princípio da travessia dimensional, os Corpos Despertos, que originalmente estavam barulhentos querendo ir juntos, ficaram em silêncio ao lado do dispositivo de ressonância espiritual."
  },
  AvgDialog_118699_Content_59 = {
    Text = "Devido às características espirituais do espaço dimensional, quanto mais corpos espirituais aparecem juntos, mais atenção será atraída por entidades de alto nível, e o Guardião do Segredo que resiste desse lado terá um trabalho ainda mais árduo."
  },
  AvgDialog_118699_Content_6 = {
    Text = "Por que... eu claramente ouvi a voz de {Male=his,Female=her} agora mesmo. Por que não consigo encontrar {Male=him,Female=her}?"
  },
  AvgDialog_118699_Content_60 = {
    Text = "Diante da multidão, Ramona segurava um buquê de rosas murchas, olhando silenciosamente para a piscina negra, enquanto na palma da outra mão, apertava com firmeza a chave de prata de número 0617."
  },
  AvgDialog_118699_Content_61 = {
    Text = "Os instrumentos estão prontos para iniciar, todos concentrem-se."
  },
  AvgDialog_118699_Content_62 = {
    Text = "As garras pressionaram o botão, uma onda de vibrações espirituais se espalhou como ondas na água, unindo as consciências de todos em fios, tecendo uma enorme rede de conexões."
  },
  AvgDialog_118699_Content_63 = {
    Text = "Ramona abriu a palma da mão solenemente, a chave de prata subiu lentamente sob uma gravidade estranha, flutuando no centro de uma rede invisível, brilhando com uma luz que respirava."
  },
  AvgDialog_118699_Content_64 = {
    Text = "Todos olham para a chave, orando em silêncio."
  },
  AvgDialog_118699_Content_65 = {
    Text = "Esta escola, as pessoas aqui, todos precisam de você. Independentemente de um ano, dois anos, dez anos... Basta que a pesquisa ainda faça sentido, nós certamente o receberemos de volta."
  },
  AvgDialog_118699_Content_66 = {
    Text = "Mestre, eu já consegui aguentar 40 segundos sem o link, agora posso proteger melhor o senhor, realmente gostaria que você visse os resultados do meu treinamento..."
  },
  AvgDialog_118699_Content_67 = {
    Text = "Não há mais novos nascidos em Misaq tão resistentes quanto você. Quando poderei experimentar outra vez uma batalha sob seu comando?"
  },
  AvgDialog_118699_Content_68 = {
    Text = "Aigis tem sido muito obediente e comendo bem, eu teci muitos e muitos cachecóis, chapéus, luvas e vários tipos de suéteres para o grande {Male=Sr. Guardião,Female=Srta. Guardiã}, ele vai gostar?"
  },
  AvgDialog_118699_Content_69 = {
    Text = "Cara do Oeste, você ainda não aprendeu todos os segredos de sobrevivência do Leste que prometi te ensinar, já recebi a taxa de matrícula, volte logo, não deixe a reputação comercial deste ladrão ser prejudicada..."
  },
  AvgDialog_118699_Content_7 = {
    Text = "De fato, \"Coração Santo\" só consegue perceber a localização geral de {Male=dele,Female=dela}, mas não consegue encontrar coordenadas mais detalhadas."
  },
  AvgDialog_118699_Content_70 = {
    Text = "Guardião {Male=senhor,Female=senhora}, eu acredito que pessoas bondosas sempre têm a proteção da sorte, e pessoas como você certamente terão um final feliz."
  },
  AvgDialog_118699_Content_71 = {
    Text = "Grande {Male=Sr. Guardião,Female=Srta. Guardiã}, Lily já pode ler muitos livros de histórias. Quando você voltar, podemos fazer um filme sobre o grande {Male=Sr. Guardião,Female=Srta. Guardiã} e Lily?"
  },
  AvgDialog_118699_Content_72 = {
    Text = "O guerreiro triunfante deve voltar para {Male=a sua, Female=a sua} terra natal."
  },
  AvgDialog_118699_Content_73 = {
    Text = "Volte logo, idiota servo, você me deve tantas tardes de chá, tem que compensar tudo direitinho!"
  },
  AvgDialog_118699_Content_74 = {
    Text = "Você já me perguntou qual era o meu desejo... agora eu finalmente tenho o meu desejo, que é que você possa voltar em segurança."
  },
  AvgDialog_118699_Content_75 = {
    Text = "A mudinha que não cumpre promessas, no novo mundo que você me prometeu, não pode ficar sem você..."
  },
  AvgDialog_118699_Content_76 = {
    Text = "Nosso clã não abandonará nenhum membro isolado."
  },
  AvgDialog_118699_Content_77 = {
    Text = "Meu som de flauta, sempre aguardando por você."
  },
  AvgDialog_118699_Content_78 = {
    Text = "Todos os corpos despertos murmuram aquele nome familiar, e ondas de poder mental fluem como vagalumes para a chave de prata flutuante, que brilha gradualmente no centro como estrelas."
  },
  AvgDialog_118699_Content_79 = {
    Text = "Pollux e Castor trocaram um olhar e acenaram um para o outro. O corpo de Castor se transformou instantaneamente em um feixe de luz e se fundiu ao peito de Pollux."
  },
  AvgDialog_118699_Content_8 = {
    Text = "Mas o forte desejo da Srta. Ramona no último momento tornou os sentimentos do \"Coração Santo\" em relação a <Amarelo:%player%> mais claros."
  },
  AvgDialog_118699_Content_80 = {
    Text = "Um brilho verdejante fluía dentro do coração sagrado; atrás de Pólux, um par de magníficas asas azul-escuras se abriu de repente. Ele estendeu o dedo e o coração sagrado começou a brilhar em resposta à luz da chave de prata."
  },
  AvgDialog_118699_Content_81 = {
    Text = "Senhorita Ramona."
  },
  AvgDialog_118699_Content_82 = {
    Text = "Encarando o olhar sério de Pollux, Ramona apertou a rosa que começava a brilhar em suas mãos, que era o sinal combinado com o Guardião."
  },
  AvgDialog_118699_Content_83 = {
    Text = "A energia mental, que foi treinada milhares de vezes, foi gradualmente se condensando seguindo as diretrizes familiares. Ela levantou a cabeça e fixou o olhar na chave de prata, colocando sua voz interior junto com todos no centro da chave."
  },
  AvgDialog_118699_Content_84 = {
    Text = "(<Amarelo:%player%, espere por mim, já vou te buscar para casa.)"
  },
  AvgDialog_118699_Content_9 = {
    Text = "Se reunir mais poder espiritual direcionado a <Yellow:%player%>, talvez possamos detectar a localização de %player% com mais precisão."
  },
  AvgDialog_118700_Content_1 = {
    Text = "Um instante de abraço"
  },
  AvgDialog_118700_Content_10 = {
    Text = "O barulho ao redor desapareceu. Em sua mente, Ramona olhou para aquele eu distante."
  },
  AvgDialog_118700_Content_11 = {
    Text = "Sua força é mais poderosa do que a minha... talvez, esta missão deva ser sua, para que seja mais segura..."
  },
  AvgDialog_118700_Content_12 = {
    Text = "Sentindo o que Ramona pensava, Ramona: Desgastada balançou a cabeça, levantou os olhos cobertos e olhou silenciosamente para aquele abismo."
  },
  AvgDialog_118700_Content_13 = {
    Text = "Eu apenas vim me despedir, nesta longa jornada dimensional, não há diferença entre você e eu, quanto mais..."
  },
  AvgDialog_118700_Content_14 = {
    Text = "Você é o {Male=seu,Female=sua} parceiro, este é o destino de vocês, não pertence a mim."
  },
  AvgDialog_118700_Content_15 = {
    Text = "Vá, traga de volta {Male=ele,Female=ela}, \"Ramona\"."
  },
  AvgDialog_118700_Content_16 = {
    Text = "Ramona segurou a mão da rosa com força, e após um tempo, ela acenou solemnemente com a cabeça, sentando-se na máquina de separação mental sob o olhar de outra versão de si mesma."
  },
  AvgDialog_118700_Content_17 = {
    Text = "Os olhos físicos estavam cerrados, enquanto outro par de olhos se abria lentamente. Uma alma densa se separou do corpo, envolvida por um brilho etéreo e branco, como uma névoa, emanando do \"Coração Santo\" de Pólux."
  },
  AvgDialog_118700_Content_18 = {
    Text = "Sob os olhares de dezenas de pessoas, Ramona se virou e olhou nos olhos de cada um de seus companheiros, carregando aquelas pesadas esperanças."
  },
  AvgDialog_118700_Content_19 = {
    Text = "Sob a orientação da saudade, ela se virou e saltou para dentro do enorme vórtice. A entrada, semelhante à porta do inferno, rapidamente consumiu a frágil alma."
  },
  AvgDialog_118700_Content_2 = {
    Text = "Anjos elevados descem a luz sagrada, esperando levar as almas perdidas ao lado de Deus."
  },
  AvgDialog_118700_Content_3 = {
    Text = "Doll e Ramona trocaram um olhar e ativaram um enorme dispositivo que quase cobria metade da piscina negra. Em meio à violenta agitação da água, o enorme redemoinho desabou, formando um abismo que parecia devorar tudo."
  },
  AvgDialog_118700_Content_4 = {
    Text = "Aquilo é..."
  },
  AvgDialog_118700_Content_5 = {
    Text = "A imponente água do lago parece fluir para outro mundo, dentro do vórtice sem fundo, a existência do mundo começa a se tornar borrada."
  },
  AvgDialog_118700_Content_6 = {
    Text = "A borda deste mundo, a entrada para o espaço dimensional."
  },
  AvgDialog_118700_Content_7 = {
    Text = "Atrás do abismo, {Male=Ele,Female=Ela} está esperando por você."
  },
  AvgDialog_118700_Content_8 = {
    Text = "Ramona acenou com a cabeça. Antes de entrar no abismo, ela de repente parou, olhando para a multidão."
  },
  AvgDialog_118700_Content_9 = {
    Text = "Uma figura do nada, em pé silenciosamente atrás da multidão que ora. Era uma presença escondida em sua consciência, visível apenas para ela."
  },
  AvgDialog_118701_Content_1 = {Text = "Esperando"},
  AvgDialog_118701_Content_10 = {
    Text = "A névoa se condensa e se dissipa, uma visitante habitual de Misaq aparece na entrada da piscina negra, parando silenciosamente ao lado da marionete, contemplando a figura que está sentada em frente à \"porta\"."
  },
  AvgDialog_118701_Content_11 = {
    Text = "O contato prolongado com a água do lago não é muito bom para a saúde, você não vai impedi-la um pouco?"
  },
  AvgDialog_118701_Content_12 = {
    Text = "Eu dei a ela um dispositivo de proteção básico, além disso, eu consigo tratar os ferimentos físicos, mas as feridas psicológicas não são tão fáceis de curar."
  },
  AvgDialog_118701_Content_13 = {
    Text = "O professor racional suspirou e virou a cabeça, curioso."
  },
  AvgDialog_118701_Content_14 = {
    Text = "Você raramente está disposto a vir aqui, o que você trouxe desta vez?"
  },
  AvgDialog_118701_Content_15 = {
    Text = "Ah, uma boa notícia que pode curar sua alma."
  },
  AvgDialog_118701_Content_16 = {
    Text = "Parceiro, graças aos seus feitos, recentemente as fissuras de fusão no mundo diminuíram bastante."
  },
  AvgDialog_118701_Content_17 = {
    Text = "Os investigadores da escola tornaram-se mais relaxados, todos só precisam assistir às aulas e fazer exames todos os dias, a Misaq está cada vez mais parecida com uma universidade comum."
  },
  AvgDialog_118701_Content_18 = {
    Text = "Alguém sugeriu construir uma estátua para você, bem ao lado do diretor Ward, e a escola ainda está considerando."
  },
  AvgDialog_118701_Content_19 = {
    Text = "Eu fiz uma sugestão não apoiada, você claramente ainda está aqui, por que quer ser transformado em uma estátua como o diretor."
  },
  AvgDialog_118701_Content_2 = {
    Text = "Mundo Cardas\nAntes do funeral do Guardião do Segredo"
  },
  AvgDialog_118701_Content_20 = {
    Text = "Além disso, quando você voltar e ver seu eu gigante ao lado do diretor, com certeza ficará tão envergonhado que não conseguirá dizer uma palavra."
  },
  AvgDialog_118701_Content_21 = {
    Text = "Sua expressão é tão tranquila, não posso acreditar... Você deve estar perdido em outro mundo, esquecendo como voltar..."
  },
  AvgDialog_118701_Content_22 = {
    Text = "Você está certo, {Male=ele,Female=ela} realmente entrou em outras dimensões, uma dimensão muito distante."
  },
  AvgDialog_118701_Content_23 = {
    Text = "Ao ouvir a voz repentina de Daffodil atrás dela, Ramona levantou-se quase descontrolada, quase não conseguindo se conter de agarrar o braço da proprietária da loja."
  },
  AvgDialog_118701_Content_24 = {
    Text = "O que você disse? Você encontrou {Male=ele,Female=ela}? Dimensão... Eu me lembro de que você pode atravessar dimensões!"
  },
  AvgDialog_118701_Content_25 = {
    Text = "Como posso trazer de volta {Male=ele,Female=ela}? Eu posso pagar qualquer preço!"
  },
  AvgDialog_118701_Content_26 = {
    Text = "Depois de implorar com dificuldade para conter a emoção, Ramona finalmente notou o rosto sério da Doll ao seu lado."
  },
  AvgDialog_118701_Content_27 = {
    Text = "…Por que?"
  },
  AvgDialog_118701_Content_28 = {
    Text = "Embora sua determinação seja comovente, lamento, mas essa é uma dimensão que não está conectada a este mundo, e além disso, não tenho como levar o Guardião do Segredo a atravessar o espaço dimensional desconhecido."
  },
  AvgDialog_118701_Content_29 = {
    Text = "Se não for possível encontrar uma rota definida, vagar aleatoriamente nas correntes dimensionais, só há um resultado: estar perdido."
  },
  AvgDialog_118701_Content_3 = {
    Text = "Com um zumbido indicando que a detecção foi concluída, vários instrumentos mostraram novamente resultados sem resposta. Doll balançou a mão em silêncio, e os pesquisadores se entreolharam, começando a desmontar os equipamentos em um entendimento mútuo."
  },
  AvgDialog_118701_Content_30 = {
    Text = "Com a tecnologia atual de Misaq, isso também não é possível."
  },
  AvgDialog_118701_Content_31 = {
    Text = "O que significa... Tentamos por tanto tempo e finalmente temos notícias de {Male=ele,Female=ela}, você realmente vai deixar {Male=ele,Female=ela} sozinho e desamparado?!"
  },
  AvgDialog_118701_Content_32 = {
    Text = "A técnica de atravessar dimensões, talvez eu possa discutir com o professor Doll, como um presente gratuito para os velhos clientes."
  },
  AvgDialog_118701_Content_33 = {
    Text = "Mas para recuperar <Amarelo:%player%>, o mais difícil é como encontrar o caminho para aquele mundo, mesmo na minha coleção, não há tal tesouro que transcenda o universo."
  },
  AvgDialog_118701_Content_34 = {
    Text = "Vou fazer com que o departamento de pesquisa comece a se dedicar totalmente ao estudo da dimensão a partir de hoje."
  },
  AvgDialog_118701_Content_35 = {
    Text = "Entre dimensões, às vezes nunca haverá interseções, e não pode ser encontrado apenas por meio da exaustão."
  },
  AvgDialog_118701_Content_36 = {
    Text = "O que vocês vão enfrentar pode ser uma tentativa tão longa que não conseguem ver esperança."
  },
  AvgDialog_118701_Content_37 = {
    Text = "Nós não vamos desistir."
  },
  AvgDialog_118701_Content_38 = {Text = "..."},
  AvgDialog_118701_Content_39 = {
    Text = "Eu sei, não importa quanto tempo leve, eu vou esperar {Male=ele,Female=ela}."
  },
  AvgDialog_118701_Content_4 = {
    Text = "Por que guardar os instrumentos? Vamos tentar novamente, com certeza ainda há métodos de teste que não pensamos..."
  },
  AvgDialog_118701_Content_40 = {
    Text = "Cardas\nDez meses após o funeral do Guardião\nPiscina Negra"
  },
  AvgDialog_118701_Content_41 = {
    Text = "Os passos ecoaram através das portas trancadas, adentrando as ondas viscosas, enquanto a silenciosa água negra recebia o segundo visitante do dia."
  },
  AvgDialog_118701_Content_42 = {
    Text = "Eu sabia que você estava aqui de novo."
  },
  AvgDialog_118701_Content_43 = {
    Text = "O interlocutor do professor não respondeu, a figura imóvel sempre voltada para a \"Porta\", como uma escultura que observa à distância."
  },
  AvgDialog_118701_Content_44 = {
    Text = "Hoje mais uma sugestão de alguém foi enviada para mim, esta é a sua sétima vez recusando a designação de um parceiro para a missão. Você insiste em realizar a investigação em dupla sozinho, não é."
  },
  AvgDialog_118701_Content_45 = {Text = "..."},
  AvgDialog_118701_Content_46 = {
    Text = "Não tem problema, não estou aqui para criticar ou mandar você, muito menos para aconselhá-lo, embora a Sylvia tenha dito que sua avaliação psicológica realmente apresentou alguns problemas."
  },
  AvgDialog_118701_Content_47 = {
    Text = "Mas quantas pessoas nesta universidade estão realmente sem problemas?"
  },
  AvgDialog_118701_Content_48 = {
    Text = "As garras rosa pararam ao lado da escultura, olhando juntas para a figura adormecida."
  },
  AvgDialog_118701_Content_49 = {
    Text = "Há alguma missão especial que você precisa que eu execute?"
  },
  AvgDialog_118701_Content_5 = {
    Text = "O número de detecções e faixas já é suficiente, seu curso de uso do medidor de núcleo de prata é nota máxima, não se engane mais, Ramona."
  },
  AvgDialog_118701_Content_50 = {
    Text = "A estátua que havia perdido a reação finalmente falou, com um tom tão calmo quanto uma máquina."
  },
  AvgDialog_118701_Content_51 = {Text = "Tem."},
  AvgDialog_118701_Content_52 = {
    Text = "Requisitos da missão?"
  },
  AvgDialog_118701_Content_53 = {
    Text = "Preciso que você vá a um lugar muito perigoso e busque seu parceiro."
  },
  AvgDialog_118701_Content_54 = {
    Text = "Não preciso…"
  },
  AvgDialog_118701_Content_55 = {
    Text = "Aquela pessoa anterior."
  },
  AvgDialog_118701_Content_56 = {
    Text = "Ramona virou a cabeça rapidamente, fixando os olhos inorgânicos da marionete."
  },
  AvgDialog_118701_Content_57 = {
    Text = "Esta missão é uma aposta e tem um nível de perigo sem precedentes; temo que o apoio externo da escola não possa acompanhar você..."
  },
  AvgDialog_118701_Content_58 = {
    Text = "O departamento de pesquisa tem resultados? Quando?"
  },
  AvgDialog_118701_Content_59 = {
    Text = "Boneca sorriu e entregou o relatório de pesquisa recém-saído do forno à outra pessoa."
  },
  AvgDialog_118701_Content_6 = {
    Text = "Isto é meramente uma casca vazia, sem sinais de vida. A consciência do Guardião... pode já ter se dissipado."
  },
  AvgDialog_118701_Content_60 = {
    Text = "Desde que Daffodil nos contou sobre o Guardião do Segredo, o departamento de pesquisa já tentou todas as técnicas disponíveis, e não esperávamos que a última brecha estivesse no Corpo Desperto."
  },
  AvgDialog_118701_Content_61 = {
    Text = "Descobrimos que o \"Coração Santo\" de Pollux pode atrair aquela existência, originalmente a fabricação do \"Coração Santo\" pela Igreja da Lanterna era para criar almas puras e espalhar o Sangue divino."
  },
  AvgDialog_118701_Content_62 = {
    Text = "Finalmente, sacrifique o Filho Santo para invocar a chamada terra inocente."
  },
  AvgDialog_118701_Content_63 = {
    Text = "Na verdade, o princípio é atrair a atenção de Uma, a fim de espalhar a Dissolução. Após um tratamento direcionado, o \"Coração Santo\" pode muito provavelmente nos indicar a localização do Guardião."
  },
  AvgDialog_118701_Content_64 = {
    Text = "A instituição planeja enviar uma consciência com grande poder espiritual para o espaço dimensional, seguindo a orientação do \"Coração Santo\" para atravessar dimensões e estabelecer um túnel que conecta os dois mundos."
  },
  AvgDialog_118701_Content_65 = {
    Text = "Se todos os dados de teste avançarem sem problemas, em menos de um mês, poderemos começar a tentar."
  },
  AvgDialog_118701_Content_66 = {
    Text = "A seguir, sua tarefa incluirá uma parte sobre o treinamento de força mental, espero que você... não seja excessivamente diligente para evitar danos ao cérebro."
  },
  AvgDialog_118701_Content_67 = {
    Text = "Cardas\nUm ano após o funeral do Guardião\nPiscina Negra"
  },
  AvgDialog_118701_Content_68 = {
    Text = "O separador espiritual em funcionamento rápido emitiu um alerta vermelho insuportável, e a boneca que estava observando de perto imediatamente pressionou o botão de parada."
  },
  AvgDialog_118701_Content_69 = {
    Text = "A porta do compartimento com o usuário se abriu instantaneamente, e Ramona, já exausta, moveu um dedo, sendo rapidamente ajudada a sair por dois pesquisadores."
  },
  AvgDialog_118701_Content_7 = {
    Text = "A cruel sentença finalmente saiu da boca da boneca. Ao ver as lágrimas escorrendo dos olhos atônitos de Ramona, o professor, acostumado ao sacrifício, também fechou os olhos com pesar."
  },
  AvgDialog_118701_Content_70 = {
    Text = "Apoie-a, entre rapidamente no líquido de resfriamento mental!"
  },
  AvgDialog_118701_Content_71 = {
    Text = "A água do tanque verde-claro submergiu seu peito, a temperatura de Ramona, que antes estava alta como uma febre, finalmente diminuiu, e aqueles olhos que antes eram racionais, agora pareciam paranoicos, lentamente se abriram."
  },
  AvgDialog_118701_Content_72 = {
    Text = "Mesmo que depois de amanhã seja a data da sua primeira tentativa oficial, você não pode arriscar seu corpo assim."
  },
  AvgDialog_118701_Content_73 = {
    Text = "Não tem problema, eu consigo suportar..."
  },
  AvgDialog_118701_Content_74 = {
    Text = "Pollux, que havia saído de um dos instrumentos ao lado, também se aproximou silenciosamente dos dois, interrompendo as instruções adicionais de Doll."
  },
  AvgDialog_118701_Content_75 = {
    Text = "Posso entender a dor de perder alguém importante, o ódio por si mesmo por se sentir impotente... Fique tranquila, Srta. Ramona."
  },
  AvgDialog_118701_Content_76 = {
    Text = "Agora o \"Coração Santo\" já pode sentir a Invocação daquela luz brilhante. Eu e Castor faremos o nosso melhor para recuperar o benfeitor junto com você."
  },
  AvgDialog_118701_Content_8 = {
    Text = "Prepare-se para o funeral de <Amarelo:%player%>, e a carta de testamento... você a lerá para {Masculino=ele, Feminino=ela}."
  },
  AvgDialog_118701_Content_9 = {
    Text = "Mundo Cardas\nTrês meses após o funeral do Guardião do Segredo"
  },
  AvgDialog_118702_Content_1 = {
    Text = "Mensagem do Distante"
  },
  AvgDialog_118702_Content_10 = {
    Text = "Você agita as mãos como uma pessoa cega, esforçando-se para dar passos, como um viajante que atravessa a água, avançando e buscando na escuridão pegajosa."
  },
  AvgDialog_118702_Content_100 = {
    Text = "Aqui não há temperatura escaldante, apenas uma escuridão viscosa e interminável. Ao avançar, o ir e vir começa a se tornar confuso, como se a existência também se transformasse em nada."
  },
  AvgDialog_118702_Content_101 = {
    Text = "Continue em frente, não olhe para trás."
  },
  AvgDialog_118702_Content_102 = {
    Text = "Você confia naquela voz, esforçando-se para esvaziar a mente e continuar avançando, até que uma onda de cores hipnóticas te faça cair em uma forte tontura."
  },
  AvgDialog_118702_Content_103 = {
    Text = "…Isso é!"
  },
  AvgDialog_118702_Content_104 = {
    Text = "Além de estar no Mar de Princípios de Daffodil, esta é a primeira vez que você está fora do cosmos olhando para o mundo."
  },
  AvgDialog_118702_Content_105 = {
    Text = "Como se estivesse entrando em um mundo microscópico através de um microscópio, uma substância gelatinosa no espaço, inúmeras linhas ondulantes, formas estranhas de corpos espirituais, galáxias distantes brilhando..."
  },
  AvgDialog_118702_Content_106 = {
    Text = "e a fronteira do mundo sem fim."
  },
  AvgDialog_118702_Content_107 = {
    Text = "Se não houver âncoras mentais suficientes, você rapidamente se perderá em um espaço tão caótico e infinito, mas em seu coração não há muito medo."
  },
  AvgDialog_118702_Content_108 = {
    Text = "Está pronto? Depois que você começar a se conectar, eu farei o possível para causar algum alvoroço para atraí-lo. O restante, será sua batalha."
  },
  AvgDialog_118702_Content_109 = {
    Text = "Você segurou com força a chave de prata em seu peito, estendendo solenemente e com carinho os tentáculos de sua mente em direção à rosa desabrochada em sua mão."
  },
  AvgDialog_118702_Content_11 = {
    Text = "Finalmente... te encontrei! Nós @3... através do túnel @2..."
  },
  AvgDialog_118702_Content_110 = {
    Text = "Vamos começar."
  },
  AvgDialog_118702_Content_111 = {
    Text = "Uma grandiosa onda de poder espiritual explode de forma estrondosa no espaço dimensional, e nos limites da percepção de seus tentáculos espirituais, uma fenda abruptamente aparece, rasgando o espaço."
  },
  AvgDialog_118702_Content_112 = {
    Text = "Uma pupila imensa apareceu de repente atrás da fenda, como o olho de um gigante que se abre subitamente."
  },
  AvgDialog_118702_Content_12 = {
    Text = "Você não consegue ver a figura dela, apenas ouve sons desconexos. A pessoa que você conhece também está emocionada, expressando a alegria do reencontro após tanto tempo."
  },
  AvgDialog_118702_Content_13 = {
    Text = "Você pode sentir que uma corda real os conecta, e parece que basta seguir essa corda para encontrar o caminho de volta para casa."
  },
  AvgDialog_118702_Content_14 = {
    Text = "Enquanto você avança continuamente seguindo a corda, um som de estilhaçamento repentinamente ecoa, fazendo todo o espaço tremer sob uma grande vibração."
  },
  AvgDialog_118702_Content_15 = {
    Text = "Há alguma coisa atacando @2, o Sagrado Coração não está aguentando mais!"
  },
  AvgDialog_118702_Content_16 = {
    Text = "Ramona, desconecte o link!"
  },
  AvgDialog_118702_Content_17 = {Text = "Mas!"},
  AvgDialog_118702_Content_18 = {
    Text = "Guardião, vá procurar Daffodil! Não vamos desistir —"
  },
  AvgDialog_118702_Content_19 = {
    Text = "Toda a luz desapareceu. À distância, uma enorme entidade desconhecida mudou de direção e gradualmente se escondeu no caos do vazio."
  },
  AvgDialog_118702_Content_2 = {
    Text = "Guardião@2... Guardião..."
  },
  AvgDialog_118702_Content_20 = {
    Text = "Um som nauseante e úmido de dilaceração se ergue no ar. Enormes patas de aranha irrompem pelos corpos dos oficiais e dos transeuntes, espirrando sangue espesso com cheiro de ferro por todo você."
  },
  AvgDialog_118702_Content_21 = {
    Text = "Você se senta abruptamente na cama, ainda no quarto da base Doll: Inferno, com aquelas paredes de tijolos vermelho-escuro familiares e um leve cheiro de desinfetante."
  },
  AvgDialog_118702_Content_22 = {
    Text = "Você me pergunta o que está acontecendo? Desde quando meu campo de pesquisa se expandiu para a análise dos sonhos? Você não deveria procurar a Clementine para isso?"
  },
  AvgDialog_118702_Content_23 = {
    Text = "Mas você está certo, considerando a sua particularidade mental, também inclino-me a acreditar que isso não é uma ilusão sua, ou um simples sonho."
  },
  AvgDialog_118702_Content_24 = {
    Text = "Quanto ao mistério da verdade, não sou eu no sonho que já te disse?"
  },
  AvgDialog_118702_Content_25 = {
    Text = "Um núcleo de prata que você havia roubado foi retirado por Fusão·Boneca e lançado dentro do Dispositivo de Despertar, enquanto uma névoa púrpura se elevava ao som do zumbido mecânico."
  },
  AvgDialog_118702_Content_26 = {
    Text = "Ah, nos encontramos de novo, meus velhos clientes?"
  },
  AvgDialog_118702_Content_27 = {
    Text = "Daffodil! Eu……"
  },
  AvgDialog_118702_Content_28 = {
    Text = "Shh, não precisa falar, um mercador competente naturalmente pode entender o que o cliente deseja."
  },
  AvgDialog_118702_Content_29 = {
    Text = "Eu realmente já vi seus amigos."
  },
  AvgDialog_118702_Content_3 = {
    Text = "Você parece estar encoberto e coberto por um enorme pano de palco, camadas de veludo espesso pressionando sobre você, tornando-o invisível e imóvel."
  },
  AvgDialog_118702_Content_30 = {Text = "?!"},
  AvgDialog_118702_Content_31 = {
    Text = "Vendo sua expressão de choque, Fusão·Doll revirou os olhos."
  },
  AvgDialog_118702_Content_32 = {
    Text = "Eu pensei que, com a sua inteligência, você deveria ser capaz de perceber a chave do poder dela."
  },
  AvgDialog_118702_Content_33 = {
    Text = "A chave do poder…?"
  },
  AvgDialog_118702_Content_34 = {
    Text = "Você se lembra daquele mar cinza cheio de cabeças."
  },
  AvgDialog_118702_Content_35 = {
    Text = "Dimensão espaço? Você está dizendo que Daffodil pode transitar entre diferentes mundos... elas são a mesma pessoa?"
  },
  AvgDialog_118702_Content_36 = {
    Text = "Está muito perto, criança inteligente, eu aqui e eu lá, de fato, somos a mesma \"existência\", mas você esqueceu que não somos humanos."
  },
  AvgDialog_118702_Content_37 = {
    Text = "Daffodil arqueou os olhos com aprovação e virou o pulso, sacudindo o cachimbo."
  },
  AvgDialog_118702_Content_38 = {
    Text = "Nós somos apenas rostos que emergem na superfície do mar, aquela vasta mar de névoa cinza que flui entre as fendas de todas as dimensões é a nossa essência."
  },
  AvgDialog_118702_Content_39 = {
    Text = "Assim, conseguimos nos conectar espiritualmente, mas não somos a mesma \"pessoa\"."
  },
  AvgDialog_118702_Content_4 = {
    Text = "Em um sonho escuro e vazio, uma voz abafada se espalha como ondas na água, desaparecendo rapidamente."
  },
  AvgDialog_118702_Content_40 = {
    Text = "Ou seja, você pode viajar entre diferentes mundos através do Mar de Princípios? No sonho de agora há pouco, Doll me pediu para te encontrar, o que significa que você agora tem uma maneira de me levar de volta para aquele mundo?"
  },
  AvgDialog_118702_Content_41 = {
    Text = "Não fique apressado, eu já disse que mesmo eu não consigo atravessar dimensionalmente entre dois mundos com facilidade."
  },
  AvgDialog_118702_Content_42 = {
    Text = "Se eu realmente tivesse esse método, por que eu o preservaria de forma tão mesquinha até agora?"
  },
  AvgDialog_118702_Content_43 = {
    Text = "Você ficou paralisado, abaixando lentamente a cabeça."
  },
  AvgDialog_118702_Content_44 = {
    Text = "Mas desta vez, foram seus amigos corajosos que encontraram uma nova maneira."
  },
  AvgDialog_118702_Content_45 = {
    Text = "Você levantou a cabeça abruptamente, seus olhos brilharam novamente. Isso provocou uma risadinha de Daffodil e um desprezo de Melt·Dor."
  },
  AvgDialog_118702_Content_46 = {
    Text = "Desde a última vez que nos encontramos neste mundo, eu lhes contei a sua mensagem."
  },
  AvgDialog_118702_Content_47 = {
    Text = "Após descobrir a singularidade desta dimensão, Doll tem trabalhado dia e noite com os pesquisadores de Misaq, tentando localizar este mundo. Recentemente, eles encontraram um método para conectar duas dimensões."
  },
  AvgDialog_118702_Content_48 = {
    Text = "O que você acabou de sentir é o resultado da conexão bem-sucedida deles."
  },
  AvgDialog_118702_Content_49 = {
    Text = "Então não foi um sonho? Aquele link espiritual é real?!"
  },
  AvgDialog_118702_Content_5 = {
    Text = "Quem? Alguém está me chamando? Que voz familiar..."
  },
  AvgDialog_118702_Content_50 = {
    Text = "Sim, mas a destruição repentina da conexão também é real. Você deve ter notado aquela pessoa que chegou de repente."
  },
  AvgDialog_118702_Content_51 = {
    Text = "Viajar entre dimensões é extremamente perigoso. Mesmo que eu possa ajudar vocês a se livrarem do rastreamento do cão, há muitas entidades de alto nível no espaço dimensional."
  },
  AvgDialog_118702_Content_52 = {
    Text = "Eles geralmente têm seus próprios domínios, assim como os imperadores dominam seus países."
  },
  AvgDialog_118702_Content_53 = {
    Text = "Talvez você pudesse evitar cuidadosamente de várias maneiras, mas, infelizmente, o oponente que está de olho no túnel é aquele que você mais conhece."
  },
  AvgDialog_118702_Content_54 = {
    Text = "A sensação mais familiar... ser observado, Toguwaibo? Ele acordou?!"
  },
  AvgDialog_118702_Content_55 = {
    Text = "Não precisa ficar tão tenso, os resultados que você trouxe com seu sacrifício não vão desaparecer tão facilmente. Ele ainda está preso em seu sono."
  },
  AvgDialog_118702_Content_56 = {
    Text = "No entanto, Ele é Ele. Seu \"Coração Santo\" e Pollux são tão brilhantes que, mesmo em sono, seu subconsciente percebeu vocês."
  },
  AvgDialog_118702_Content_57 = {
    Text = "A expressão de Daffodil tornou-se incomumente séria, enquanto você permanecia em silêncio, relembrando aquela batalha que sacrificou tudo."
  },
  AvgDialog_118702_Content_58 = {
    Text = "Felizmente, o barulho desta vez da travessia dimensional é muito menor do que o provocado por Juliette da última vez. O olhar projetado de sua subconsciente não destruiu o mundo inteiro."
  },
  AvgDialog_118702_Content_59 = {
    Text = "Mesmo assim, tal força não pode ser suportada pelo Corpo Desperto que veio te guiar. Portanto, para construir um link de dimensão completo, aqueles do outro lado não conseguirão fazer isso sozinhos."
  },
  AvgDialog_118702_Content_6 = {
    Text = "Guardião... parceiro!"
  },
  AvgDialog_118702_Content_60 = {
    Text = "Preciso de você, <Amarelo:%player%>, para atrair a atenção Dele aqui e repelir Ele, protegendo-os em outro mundo e abrindo o túnel entre os dois mundos."
  },
  AvgDialog_118702_Content_61 = {
    Text = "O olhar de Toguwaibo... é Ele novamente..."
  },
  AvgDialog_118702_Content_62 = {
    Text = "Aquela batalha foi tão distante, tão distante quanto algo que aconteceu em uma vida passada."
  },
  AvgDialog_118702_Content_63 = {
    Text = "Aquela batalha foi tão próxima, tão próxima que você pode facilmente se lembrar de cada detalhe dela."
  },
  AvgDialog_118702_Content_64 = {
    Text = "cada ferida aguda, cada vitória brutal, cada tremor de medo, cada grito de desespero à beira da morte…"
  },
  AvgDialog_118702_Content_65 = {
    Text = "Encarar os deuses consumiu toda a sua coragem e vida. Ao se lembrar daqueles olhares que estavam acima das regras, sua voz começou a tremer incontrolavelmente."
  },
  AvgDialog_118702_Content_66 = {
    Text = "Mesmo a projeção do olhar do subconsciente, sua força provavelmente não é algo que eu possa bloquear..."
  },
  AvgDialog_118702_Content_67 = {
    Text = "Atualmente, não consigo invocar completamente o poder das três substâncias e não tenho a ajuda de companheiros de outras dimensões. Quero detê-Lo..."
  },
  AvgDialog_118702_Content_68 = {
    Text = "O que aconteceu, nosso valente Guardião do Segredo, você está com medo?"
  },
  AvgDialog_118702_Content_69 = {
    Text = "Você cerrou os punhos, balançou a cabeça e olhou seriamente para Daffodil."
  },
  AvgDialog_118702_Content_7 = {Text = "Ramona?!"},
  AvgDialog_118702_Content_70 = {
    Text = "Basta que eu consiga voltar, nenhum tipo de medo pode me deter. Eu apenas estou preocupado, preocupado que minhas habilidades atuais não sejam suficientes."
  },
  AvgDialog_118702_Content_71 = {
    Text = "Se eu falhar, Ele até corre o risco de ser re-despertado... Um desastre assim é insuportável para qualquer um."
  },
  AvgDialog_118702_Content_72 = {
    Text = "Muito bom. Parece que nosso Guardião do Segredo ainda não perdeu a coragem de enfrentar os deuses."
  },
  AvgDialog_118702_Content_73 = {
    Text = "Fique tranquilo, <Amarelo:%player%>. Desta vez, eu também vou te ajudar a abrir o intervalo entre as diferentes dimensões e dispersar o poder Dele por diferentes dimensões."
  },
  AvgDialog_118702_Content_74 = {
    Text = "Na última vez, os Guardiões do Segredo de outras Dimensões lutaram lado a lado com você, e desta vez, eles também estarão lutando da mesma maneira, em lugares que você não pode ver."
  },
  AvgDialog_118702_Content_75 = {
    Text = "Sério?! Com isso, nós, com certeza, teremos a capacidade de detê-Lo novamente!"
  },
  AvgDialog_118702_Content_76 = {
    Text = "Mesmo assim, uma batalha desse nível pode destruir todo o mundo aqui por causa Dele. Exceto <Amarelo:%player%>, os sobreviventes deste mundo não têm a capacidade de enfrentá-lo."
  },
  AvgDialog_118702_Content_77 = {
    Text = "Isso mesmo, portanto, esta batalha precisa acontecer no espaço dimensional, e para que <Yellow:%player%> permaneça por um longo tempo no espaço dimensional, também precisamos da ajuda de um gênio."
  },
  AvgDialog_118702_Content_78 = {
    Text = "Por favor! Fusão - Boneca!"
  },
  AvgDialog_118702_Content_79 = {
    Text = "…hum, um ou dois estão bem organizados."
  },
  AvgDialog_118702_Content_8 = {
    Text = "Com a revelação daquele nome, uma barreira invisível foi instantaneamente quebrada, uma conexão íntima e calorosa atravessou inúmeros tempos e espaços, transformando-se em um fio branco que se aproximou do seu peito."
  },
  AvgDialog_118702_Content_80 = {
    Text = "Deixe pra lá, quem mandou eu prometer que ajudaria você a voltar para casa? A promessa para o cachorro eu cumprirei."
  },
  AvgDialog_118702_Content_81 = {Text = "Obrigado!"},
  AvgDialog_118702_Content_82 = {
    Text = "Não precisa me agradecer apressadamente. Para deixar claro, só posso permitir que sua consciência permaneça no espaço da dimensão e garantir que você possa ser trazido de volta a este mundo sempre que possível."
  },
  AvgDialog_118702_Content_83 = {
    Text = "Quanto à sua batalha com aquela pessoa, ainda há a possibilidade de derrota e até mesmo morte."
  },
  AvgDialog_118702_Content_84 = {
    Text = "Eu não sou otimista em relação a esse plano impulsivo. Mesmo assim, você ainda escolhe correr esse grande risco para apostar em um resultado desconhecido?"
  },
  AvgDialog_118702_Content_85 = {
    Text = "Estou disposto, eles assumiram os mesmos riscos por mim, não tenho razão para não responder a eles. De qualquer forma, mesmo que estejamos em dois mundos diferentes, ainda estamos lutando lado a lado, como antes."
  },
  AvgDialog_118702_Content_86 = {
    Text = "Fusão·Doll acenou com a cabeça sem surpresa, e Daffodil olhou para você com um sorriso, como se nunca tivesse considerado a possibilidade de você recuar."
  },
  AvgDialog_118702_Content_87 = {
    Text = "Entendi, esse tipo de juramento tão meloso deve ser reservado para seus bons companheiros de batalha. Eu preciso de um tempo para me preparar, quanto a como combinar o momento de início da ação, suponho que você já tenha um método?"
  },
  AvgDialog_118702_Content_88 = {
    Text = "Diante da pergunta de Fusão·Boneca, Daffodil virou o olhar para você."
  },
  AvgDialog_118702_Content_89 = {
    Text = "Claro, seu parceiro me pediu para lhe entregar um presente."
  },
  AvgDialog_118702_Content_9 = {
    Text = "Isso é... uma ligação espiritual?! Ramona, é você? Onde você está?"
  },
  AvgDialog_118702_Content_90 = {
    Text = "Uma rosa, que você não sabe de onde foi retirada, foi oferecida à sua frente, envolta em fumaça."
  },
  AvgDialog_118702_Content_91 = {
    Text = "Isto é... a flor que a Ramona me deu...?!!"
  },
  AvgDialog_118702_Content_92 = {
    Text = "Lamento, ainda não tenho a capacidade de projetar objetos reais através de dimensões."
  },
  AvgDialog_118702_Content_93 = {
    Text = "No entanto, em cada um desses dois dimensões, cada coisa terá seu correspondente."
  },
  AvgDialog_118702_Content_94 = {
    Text = "A rosa correspondente é aquela que Ramona te deu naquele dimensão."
  },
  AvgDialog_118702_Content_95 = {
    Text = "Eu já fiz um pequeno tratamento nesta flor, quando você estiver pronto, conecte-se espiritualmente a esta flor, as pessoas do outro lado receberão a mensagem."
  },
  AvgDialog_118702_Content_96 = {
    Text = "Ela disse que, quando vocês se encontrarem, ela vai prender esta flor em seu peito."
  },
  AvgDialog_118702_Content_97 = {Text = "..."},
  AvgDialog_118702_Content_98 = {
    Text = "Você soube pela primeira vez que o portal usado por Fusão - Boneca para deixar o mundo é o sol que já desapareceu acima de sua cabeça."
  },
  AvgDialog_118702_Content_99 = {
    Text = "O buraco negro do sol é como uma ferida que o mundo não consegue curar, e quando sua consciência lentamente entra nele, é como se você estivesse se arrastando para dentro do vasto peito de um gigante."
  },
  AvgDialog_118703_Content_1 = {
    Text = "Dedo curvado"
  },
  AvgDialog_118703_Content_10 = {
    Text = "Um grito agudo, que não pertence a nenhum ser ou dimensão, ecoa diretamente das profundezas da consciência, quase rasgando seu cérebro."
  },
  AvgDialog_118703_Content_100 = {
    Text = "Hum — minha cabeça... dói tanto..."
  },
  AvgDialog_118703_Content_101 = {
    Text = "Os instrumentos conectados estão quase totalmente danificados, você ainda conseguiu voltar vivo, é um verdadeiro milagre."
  },
  AvgDialog_118703_Content_102 = {
    Text = "No entanto, este lugar já viu muitos milagres. Talvez para a piscina negra, a probabilidade em si seja um erro."
  },
  AvgDialog_118703_Content_103 = {
    Text = "Muito bem, Ramona. Não faça isso novamente da próxima vez."
  },
  AvgDialog_118703_Content_104 = {
    Text = "Pode ficar tranquilo, professora Doll... Eu sei o que estou fazendo."
  },
  AvgDialog_118703_Content_105 = {
    Text = "Para %player%, poder vê-lo novamente pode ser mais importante do que muitas coisas."
  },
  AvgDialog_118703_Content_106 = {
    Text = "A única pena é que {Male=ele,Female=ela} você não conseguiu ouvir a última frase."
  },
  AvgDialog_118703_Content_107 = {
    Text = "Não, Senhora Daffodil. {Male=suas,Female=suas} palavras, eu já ouvi..."
  },
  AvgDialog_118703_Content_108 = {
    Text = "Ramona levantou-se fraca, sorrindo, e foi até aquele buraco negro que estava desaparecendo."
  },
  AvgDialog_118703_Content_109 = {
    Text = "O abismo colapsa em seus olhos, de um gigantesco devorador de tudo, a uma porta que isola dimensões, até uma fenda de nada, até desaparecer completamente."
  },
  AvgDialog_118703_Content_11 = {
    Text = "Você cai de joelhos, segurando firmemente os próprios ouvidos, sentindo o sangue escorrendo incontrolavelmente de suas órbitas..."
  },
  AvgDialog_118703_Content_110 = {
    Text = "A mão de Ramona passou suavemente pelo lugar onde o abismo já existiu, acariciando aquele corpo cheio de feridas."
  },
  AvgDialog_118703_Content_111 = {
    Text = "Ela sorriu, como se visse o futuro próximo, com o dono do corpo à sua frente, como um dia incrivelmente comum de Misaq."
  },
  AvgDialog_118703_Content_112 = {
    Text = "Ouvi, Guardião... nós definitivamente conseguiremos."
  },
  AvgDialog_118703_Content_113 = {
    Text = "Estou à sua espera, %player%."
  },
  AvgDialog_118703_Content_12 = {
    Text = "<Shake:Hu... Hu...>"
  },
  AvgDialog_118703_Content_13 = {
    Text = "Parece que... acabou?"
  },
  AvgDialog_118703_Content_14 = {
    Text = "O grito agudo desapareceu sem que você percebesse. Você levanta a cabeça. Na frágil dimensão ilusória, já não há mais aquela aura aterrorizante que provoca arrepios."
  },
  AvgDialog_118703_Content_15 = {
    Text = "Você venceu. O subconsciente Dele está desconectado daqui, e o último grande olho já se dissipou na dimensão."
  },
  AvgDialog_118703_Content_16 = {
    Text = "Você luta para estabilizar sua mente exausta, quase inconscientemente se virando."
  },
  AvgDialog_118703_Content_17 = {Text = "crack"},
  AvgDialog_118703_Content_18 = {
    Text = "Um som ilusório de cristal se quebrando chega aos seus ouvidos, e o que você vê é um túnel de dimensão rachado como uma teia de aranha, com Ramona, seu corpo espiritual, começando a piscar como uma velha televisão."
  },
  AvgDialog_118703_Content_19 = {
    Text = "<Big:<Shake:Ramona!!!>>"
  },
  AvgDialog_118703_Content_2 = {
    Text = "Falta... só mais um pouco...!"
  },
  AvgDialog_118703_Content_20 = {
    Text = "Seu corpo, que já estava exausto, parecia se curar em um instante. Você não se importou mais com nada e voou até ela, tremendo enquanto segurava aquelas mãos."
  },
  AvgDialog_118703_Content_21 = {
    Text = "Eu, eu estou bem…"
  },
  AvgDialog_118703_Content_22 = {
    Text = "Sua parceira sorri como de costume, segurando sua mão mais firmemente, parece que nada aconteceu e continua com os planos originais."
  },
  AvgDialog_118703_Content_23 = {
    Text = "Você já o derrotou, venha, venha comigo, eu vou levá-lo de volta."
  },
  AvgDialog_118703_Content_24 = {
    Text = "Ela te puxava, como fazia normalmente durante as missões.\n Apenas, uma voz mais racional soou quase de forma fria."
  },
  AvgDialog_118703_Content_25 = {
    Text = "Ramona, o túnel dimensional foi destruído por Ele, seu corpo espiritual não consegue suportar a carga de manter o túnel. Se continuar assim, você só caminhará em direção à morte cerebral."
  },
  AvgDialog_118703_Content_26 = {
    Text = "Esta missão de resgate já... falhou. Você precisa voltar imediatamente, eu vou ativar o modo de convocação do separador para trazer seu espírito de volta ao corpo."
  },
  AvgDialog_118703_Content_27 = {
    Text = "<Big:Não vou embora!>"
  },
  AvgDialog_118703_Content_28 = {
    Text = "Você viu pela primeira vez essa pessoa que sempre foi tão calma perder a compostura e gritar. Ela pareceu mexer as narinas por um momento e logo lhe mostrou um sorriso mais natural."
  },
  AvgDialog_118703_Content_29 = {
    Text = "Estou bem, <Amarelo:%player%>, recentemente fiz muitos treinos, meu poder espiritual já aumentou, Doll não entende meu verdadeiro limite."
  },
  AvgDialog_118703_Content_3 = {
    Text = "Quando seu espírito está à beira da exaustão, os olhos divinos também começam a tremer devido à fraqueza."
  },
  AvgDialog_118703_Content_30 = {
    Text = "Não desista, vamos tentar mais uma vez, apenas um pouco, tudo bem?"
  },
  AvgDialog_118703_Content_31 = {
    Text = "Ela está implorando por você."
  },
  AvgDialog_118703_Content_32 = {Text = "..."},
  AvgDialog_118703_Content_33 = {
    Text = "Você não consegue falar."
  },
  AvgDialog_118703_Content_34 = {
    Text = "Por que se preocupar tanto? Deixe-me capturar seu espírito neste mundo e colocá-lo no corpo de autômato que eu criei com tanto cuidado, assim ela poderá estar ao lado de <Amarelo:%player%> novamente."
  },
  AvgDialog_118703_Content_35 = {
    Text = "Fusão·Doll, que estava assistindo ao espetáculo com grande alegria, também entrou no canal de comunicação, soltando uma risada divertida."
  },
  AvgDialog_118703_Content_36 = {
    Text = "Nenhum. Você sabe que nem todo mundo pode, como o Guardião, se desconectar da existência física por longos períodos, caso contrário, não precisaríamos lidar com uma cabeça cheia de pensamentos cor-de-rosa todos os dias."
  },
  AvgDialog_118703_Content_37 = {
    Text = "Não se preocupe, Ramona. Na próxima vez, quando você estiver descansada, eu vou esperar por você para me buscar."
  },
  AvgDialog_118703_Content_38 = {
    Text = "Você olha para a figura transparente que parece estar prestes a se dissipar, sorrindo levemente, escondendo todos os seus desejos de saudade."
  },
  AvgDialog_118703_Content_39 = {
    Text = "Não é tão simples assim, essa \"rota\" já foi descoberta por Ele, da próxima vez que usar, apenas atrairá um olhar mais intenso."
  },
  AvgDialog_118703_Content_4 = {
    Text = "Este é o campo de batalha da vontade. Você, como uma besta à beira da morte, esgota toda a sua força, extraindo a última gota de poder do mundo espiritual seco."
  },
  AvgDialog_118703_Content_40 = {
    Text = "Fusão·Boneca não hesitou em estourar suas fantasias, enquanto a outra Doll permaneceu em silêncio."
  },
  AvgDialog_118703_Content_41 = {
    Text = "<Shake:Chegamos até aqui, desta vez, agora, eu quero te levar de volta.>"
  },
  AvgDialog_118703_Content_42 = {
    Text = "Ramona começou a tremer as mãos também. Você respirou fundo lentamente e, tentando parecer à vontade, deu um leve tapa na mão dela."
  },
  AvgDialog_118703_Content_43 = {
    Text = "Ramona, você se lembra do nosso primeiro encontro?"
  },
  AvgDialog_118703_Content_44 = {
    Text = "Ramona acenou com a cabeça, depois balançou a cabeça, olhando para você com um olhar quase suplicante. Você teve que fechar os olhos e, com firmeza, continuar a falar."
  },
  AvgDialog_118703_Content_45 = {
    Text = "Foi realmente uma catástrofe aterrorizante. Após a grande explosão, eu só me lembro vagamente de tudo ao meu redor se transformar em escombros com um estrondo ensurdecedor. Quando abri os olhos, pensei que já tinha chegado ao paraíso."
  },
  AvgDialog_118703_Content_46 = {
    Text = "A luz ofuscante do sol entra pelas pedras escavadas, e então sua mão se estende na minha frente."
  },
  AvgDialog_118703_Content_47 = {
    Text = "Naquele momento, eu estava pensando, será que a roupa de anjo é tão estranha? Uma uniforme tão antiquado, não imaginei que logo esse tipo de uniforme estaria em mim."
  },
  AvgDialog_118703_Content_48 = {
    Text = "Ramona queria dizer algo, mas foi interrompida por você, que começou a tagarelar incessantemente como um velho imerso em lembranças."
  },
  AvgDialog_118703_Content_49 = {
    Text = "Depois que vocês me tiraram, eu sempre considerei você a pessoa mais bondosa, mas ao chegar em Misaq, percebi que fui vítima de uma grande fraude."
  },
  AvgDialog_118703_Content_5 = {
    Text = "Você levanta a chave de prata com as mãos trêmulas."
  },
  AvgDialog_118703_Content_50 = {
    Text = "Quando comecei a ler na pré-escola, você disse que era meu parceiro e que me ajudaria a resolver todos os problemas da vida e dos estudos. Eu acreditei."
  },
  AvgDialog_118703_Content_51 = {
    Text = "Na verdade, você realmente resolveu meu problema, usando a abordagem que ataca a raiz do problema — <Shake:Resolva-me>."
  },
  AvgDialog_118703_Content_52 = {
    Text = "O chamado parceiro, na verdade, é o maior supervisor. Naquele ano, na turma preparatória, quem me controlava mais rigidamente era você."
  },
  AvgDialog_118703_Content_53 = {
    Text = "Não só preciso cuidar de você enquanto somos colegas de classe, mas também durante o tempo de dever de casa, e às vezes, após o treino físico, nem mesmo posso comer um prato de peixe frito com batatas fritas. É realmente odioso."
  },
  AvgDialog_118703_Content_54 = {
    Text = "A expressão silenciosa e triste de Ramona se quebrou por um instante, e os cantos de sua boca não puderam deixar de se curvar."
  },
  AvgDialog_118703_Content_55 = {
    Text = "Mas, meu querido parceiro, você também é a pessoa que mais cuida de mim."
  },
  AvgDialog_118703_Content_56 = {
    Text = "A língua universal do Leo que não consigo falar, a pressão do exame que me faz colapsar, as tarefas que não consigo escrever... Em todos os momentos difíceis, você pode procurar o parceiro versátil."
  },
  AvgDialog_118703_Content_57 = {
    Text = "Ainda me lembro da primeira vez que vi o estudante que sacrificou-se na missão, não conseguindo dormir à noite, fui secretamente bater à sua porta."
  },
  AvgDialog_118703_Content_58 = {
    Text = "Então, você me puxou e correu até o topo da torre do relógio. Eu subi para o telhado com dificuldade, e nós nos sentamos lado a lado, olhando as estrelas."
  },
  AvgDialog_118703_Content_59 = {
    Text = "Você e eu conversamos por muito, muito tempo, sobre muitas, muitas coisas. Foi a primeira vez que soube que você também não sabe como é sua mãe e sua infância."
  },
  AvgDialog_118703_Content_6 = {
    Text = "É o fim…! —"
  },
  AvgDialog_118703_Content_60 = {
    Text = "Meu coração, que sempre foi um pouco solitário e um pouco confuso, de repente caiu assim."
  },
  AvgDialog_118703_Content_61 = {
    Text = "Eu acho que, embora eu não tenha família, talvez esta seja a única pessoa no mundo que me trata tão bem e se parece tanto comigo, como se fosse da família."
  },
  AvgDialog_118703_Content_62 = {
    Text = "Eu juro que vou fazer um pacto com você, prometo que no futuro vou fazer os deveres de casa com seriedade, prestar atenção nas aulas e cumprir as tarefas."
  },
  AvgDialog_118703_Content_63 = {
    Text = "Desde então, passei a considerar Misaq como meu verdadeiro lar, e assim, em missão após missão, conheci tantos Corpos Despertos, conheci um novo membro da família após o outro."
  },
  AvgDialog_118703_Content_64 = {
    Text = "<Yellow:%player%>......"
  },
  AvgDialog_118703_Content_65 = {
    Text = "Então, obrigado, obrigado a vocês por me buscarem, minha família."
  },
  AvgDialog_118703_Content_66 = {
    Text = "Eu sei que vocês tentaram por muito, muito tempo e gastaram muito, muito esforço."
  },
  AvgDialog_118703_Content_67 = {
    Text = "Então venha comigo, eu com certeza posso te levar de volta."
  },
  AvgDialog_118703_Content_68 = {
    Text = "Olhando para as lágrimas escorrendo do canto do olho de Ramona, você ainda sorri, mas um líquido quente também escorre descontroladamente pela sua bochecha."
  },
  AvgDialog_118703_Content_69 = {
    Text = "Você olha para a figura dela, que se torna ilusória e piscante devido ao limite de sua força mental, e balança a cabeça suavemente."
  },
  AvgDialog_118703_Content_7 = {
    Text = "Uma luz prateada ofuscante se abre em suas mãos, iluminando toda a dimensão ilusória."
  },
  AvgDialog_118703_Content_70 = {
    Text = "Vamos parar por aqui, Ramona."
  },
  AvgDialog_118703_Content_71 = {
    Text = "Não, não..."
  },
  AvgDialog_118703_Content_72 = {
    Text = "Ramona parecia já pressentir algo, ela balançava a cabeça desesperadamente, segurando firmemente seu corpo espiritual com aquelas mãos desfocadas."
  },
  AvgDialog_118703_Content_73 = {
    Text = "Eu prometo a você, com certeza voltarei..."
  },
  AvgDialog_118703_Content_74 = {
    Text = "Eu prometo a você que nós definitivamente nos encontraremos novamente."
  },
  AvgDialog_118703_Content_75 = {
    Text = "Você suavemente retirou a mão daquela palma familiar, liberando-a."
  },
  AvgDialog_118703_Content_76 = {
    Text = "Doll do outro lado da comunicação recebeu o sinal, a sensação familiar de separação do equipamento invadiu a mente de Ramona, e ela sabia que estava indo embora."
  },
  AvgDialog_118703_Content_77 = {
    Text = "\"Com certeza\", \"absolutamente\", como as palavras que você disse quando entrou pela primeira vez na porta... na verdade, você mesmo não acredita, certo?"
  },
  AvgDialog_118703_Content_78 = {
    Text = "Você é realmente uma pessoa cruel..."
  },
  AvgDialog_118703_Content_79 = {
    Text = "Ramona, eu..."
  },
  AvgDialog_118703_Content_8 = {
    Text = "<Shake:Hmm@2@4@3!!!——>"
  },
  AvgDialog_118703_Content_80 = {
    Text = "Código do investigador… O que foi prometido, deve ser cumprido."
  },
  AvgDialog_118703_Content_81 = {
    Text = "Eu acredito em você. Mesmo que você não acredite em si mesmo, mesmo que você me engane inúmeras vezes, eu ainda acredito em você."
  },
  AvgDialog_118703_Content_82 = {
    Text = "Nos olhos de Ramona, em seu rosto onde o choro e o riso se entrelaçam, suas pupilas fixam em você, como se quisessem gravar seu rosto na memória."
  },
  AvgDialog_118703_Content_83 = {
    Text = "No último momento em que o corpo espiritual foi chamado de volta ao corpo, ela estendeu a mão para você com todas as suas forças."
  },
  AvgDialog_118703_Content_84 = {
    Text = "Como naquele momento há muito tempo sob o céu estrelado à noite, ela estendeu o dedo mínimo e suavemente tocou a ponta do seu dedo."
  },
  AvgDialog_118703_Content_85 = {
    Text = "Você com certeza vai conseguir, não é?"
  },
  AvgDialog_118703_Content_86 = {
    Text = "Não esperei pela sua resposta. No instante seguinte, aquela silhueta ilusória se desintegra junto com o túnel dimensional, transformando-se em pontos de luz que lentamente desaparecem, sem deixar vestígios."
  },
  AvgDialog_118703_Content_87 = {Text = "..."},
  AvgDialog_118703_Content_88 = {Text = "..."},
  AvgDialog_118703_Content_89 = {
    Text = "Respiração normal. Frequência cardíaca normal. A intensidade mental está abaixo do alerta... Está se recuperando."
  },
  AvgDialog_118703_Content_9 = {Text = "Ah—"},
  AvgDialog_118703_Content_90 = {
    Text = "Sobreviver após ter sua força mental espremida dessa forma, a vida do cachorro realmente é valiosa."
  },
  AvgDialog_118703_Content_91 = {
    Text = "Assisti a um grande espetáculo. Infelizmente, não vi os deuses que vocês convocaram destruírem este mundo, o final não foi emocionante o suficiente."
  },
  AvgDialog_118703_Content_92 = {
    Text = "Relaxe... Eu prometi que O impediria em outro espaço. Uma promessa que não pode ser cumprida... Não haverá uma segunda vez."
  },
  AvgDialog_118703_Content_93 = {
    Text = "Essas palavras, é melhor guardá-las para dizer a ela pessoalmente quando voltarmos."
  },
  AvgDialog_118703_Content_94 = {
    Text = "Já que trilhei este caminho com vocês, quero ver até onde vocês podem chegar."
  },
  AvgDialog_118703_Content_95 = {
    Text = "Depois de descansar bem, continue a jornada, cachorro."
  },
  AvgDialog_118703_Content_96 = {
    Text = "Você sente o resíduo de calor deixado pelos dedos, apertando lentamente o dedo mindinho que estava entrelaçado com o dela, pressionando-o contra o peito."
  },
  AvgDialog_118703_Content_97 = {
    Text = "Em direção ao vasto e solitário espaço dimensional, em direção àquela figura distante que já desapareceu, você murmura suavemente, falando sobre a promessa que certamente cumprirá."
  },
  AvgDialog_118703_Content_98 = {
    Text = "Embora você não possa ouvir agora... Eu vou conseguir. Espere por mim, Ramona!"
  },
  AvgDialog_118703_Content_99 = {Text = "..."},
  AvgDialog_118944_Content_1 = {
    Text = "Cortando o último Peixe-homem deformado, você avança em direção à menina no canto, lutando e recuando ao mesmo tempo."
  },
  AvgDialog_118944_Content_10 = {
    Text = "William tentou abrir a porta que levava ao porão, mas não importava o quanto ele se esforçasse, a escotilha não se mexia."
  },
  AvgDialog_118944_Content_11 = {
    Text = "Não, a porta já está selada na parte inferior!"
  },
  AvgDialog_118944_Content_12 = {
    Text = "O casco emitiu um gemido arrepiante, enquanto, sob as ondas gigantescas que se acumulavam, começou a se virar com dificuldade e determinação, avançando em direção a águas mais escuras e a tempestades mais intensas."
  },
  AvgDialog_118944_Content_13 = {
    Text = "Miryam abriu os braços, abraçando essa direção de destruição, com um sorriso quase maternal surgindo em seu rosto."
  },
  AvgDialog_118944_Content_14 = {
    Text = "O ritual está prestes a terminar!"
  },
  AvgDialog_118944_Content_15 = {
    Text = "Você chegou a uma resposta?"
  },
  AvgDialog_118944_Content_16 = {
    Text = "Na luta entre a tempestade e o caos, ninguém consegue identificar a posição de todos..."
  },
  AvgDialog_118944_Content_17 = {
    Text = "Basta ter mais um barquinho..."
  },
  AvgDialog_118944_Content_18 = {
    Text = "Incontáveis pistas iluminam sua mente..."
  },
  AvgDialog_118944_Content_19 = {
    Text = "Guarda da sala de estar."
  },
  AvgDialog_118944_Content_2 = {
    Text = "Murphy, venha comigo!"
  },
  AvgDialog_118944_Content_20 = {
    Text = "Cerimônia de pilotagem no convés."
  },
  AvgDialog_118944_Content_21 = {
    Text = "A explosão da sala de energia."
  },
  AvgDialog_118944_Content_22 = {
    Text = "Bote salva-vidas do porão inferior."
  },
  AvgDialog_118944_Content_23 = {
    Text = "Pontos de luz se conectam, entrelaçam e se estendem... até finalmente se reunirem em uma rota de fuga coesa e clara."
  },
  AvgDialog_118944_Content_24 = {
    Text = "William acenou com a cabeça."
  },
  AvgDialog_118944_Content_25 = {
    Text = "Uma vez que você já obteve a resposta, o objetivo deste ciclo já está basicamente cumprido, não há motivo para se lamentar."
  },
  AvgDialog_118944_Content_26 = {
    Text = "De acordo com a regra que você mencionou, o navio vai começar a afundar."
  },
  AvgDialog_118944_Content_27 = {
    Text = "Você está pronto?"
  },
  AvgDialog_118944_Content_28 = {
    Text = "A maré já engoliu seus peitos, você segurou suavemente a chave de prata em seu peito e sussurrou palavras de despedida."
  },
  AvgDialog_118944_Content_29 = {
    Text = "Até o próximo ciclo nos encontramos."
  },
  AvgDialog_118944_Content_3 = {
    Text = "Ela estremeceu como se assustada, com o olhar desfocado se esforçando para se fixar em seu rosto."
  },
  AvgDialog_118944_Content_30 = {
    Text = "Que a Chave de prata ilumine o meu caminho."
  },
  AvgDialog_118944_Content_4 = {
    Text = "Não, não faz sentido, tudo é ilusão... seja avançar ou recuar, tudo..."
  },
  AvgDialog_118944_Content_5 = {
    Text = "Basta que ainda não tenha chegado o último momento, não desista de tentar! Mesmo que nesta vez eu falhe novamente, eu vou segurar sua mão mais uma vez!"
  },
  AvgDialog_118944_Content_6 = {Text = "..."},
  AvgDialog_118944_Content_7 = {
    Text = "Murphy te observa com um olhar atordoado."
  },
  AvgDialog_118944_Content_8 = {
    Text = "Você segurou o pulso dela com uma força suave, mas inabalável, puxando-a para longe daquele canto desesperador."
  },
  AvgDialog_118944_Content_9 = {
    Text = "William, o companheiro mais velho, há um caminho de fuga?"
  },
  AvgDialog_118945_Content_1 = {
    Text = "Garotinho, você pegou leve na luta."
  },
  AvgDialog_118945_Content_10 = {
    Text = "Algumas pessoas cometem más ações para buscar sua própria sobrevivência no fim do caminho."
  },
  AvgDialog_118945_Content_11 = {
    Text = "Algumas pessoas filtram os outros com suas próprias ideias, a fim de construir o novo mundo ideal que desejam."
  },
  AvgDialog_118945_Content_12 = {
    Text = "Há também pessoas que, puramente por diversão, podem causar grandes reviravoltas e criar uma infinidade de problemas."
  },
  AvgDialog_118945_Content_13 = {
    Text = "Você espera, você aguarda a resposta dela. Pois você já viu o caminho que ela tomou em um sonho distante."
  },
  AvgDialog_118945_Content_14 = {
    Text = "A Miryam, que agora está em loucura, foi uma menina que, em meio a desastres, se dedicou à missão do sacerdote para proteger sua única família."
  },
  AvgDialog_118945_Content_15 = {
    Text = "Miryam não respondeu diretamente à sua pergunta. Ela uniu as palmas das mãos e orou em direção ao distante horizonte do mar."
  },
  AvgDialog_118945_Content_16 = {
    Text = "\"Aqueles que são devotos, o Senhor cuidará...\""
  },
  AvgDialog_118945_Content_17 = {
    Text = "\"Para todos os que desejam, meu Senhor concederá.\""
  },
  AvgDialog_118945_Content_18 = {
    Text = "Parece ter recebido a aprovação do mar, ela abriu levemente os olhos roxos e negros, perdidos."
  },
  AvgDialog_118945_Content_19 = {
    Text = "Eu venho para o renascimento do Reino Divino, para que a glória dos deuses se reproduza no mundo."
  },
  AvgDialog_118945_Content_2 = {
    Text = "Para mim, esta conversa com Miryam é muito mais crucial do que uma vitória."
  },
  AvgDialog_118945_Content_20 = {
    Text = "Então, quando Lemúria ressurgir, que tipo de mundo você espera ver?"
  },
  AvgDialog_118945_Content_21 = {
    Text = "\"No longo sonho dos deuses, nós compartilhamos a paz e a felicidade eternas.\""
  },
  AvgDialog_118945_Content_22 = {
    Text = "O renascimento da era de Lemúria, como lhe foi ensinado em vida."
  },
  AvgDialog_118945_Content_23 = {
    Text = "Você nunca viu um império tão grandioso, você realmente sabe como construí-lo?"
  },
  AvgDialog_118945_Content_24 = {
    Text = "\"A vontade divina indicará o caminho para Lemuria aos fiéis.\""
  },
  AvgDialog_118945_Content_25 = {
    Text = "Você, deste mundo, realmente não é diferente do que eu conheço."
  },
  AvgDialog_118945_Content_26 = {
    Text = "Então, neste momento em que o deus já nasceu, por que você ainda segura Murphy com firmeza?"
  },
  AvgDialog_118945_Content_3 = {
    Text = "Basta você conseguir fazer Miryam hesitar um pouco, o domínio revelará suas fendas, seu \"núcleo\" oculto..."
  },
  AvgDialog_118945_Content_4 = {
    Text = "Vocês têm esperança de acabar completamente com este teimoso sonho artificial."
  },
  AvgDialog_118945_Content_5 = {
    Text = "Por favor, explique suas intenções."
  },
  AvgDialog_118945_Content_6 = {
    Text = "Estou aqui com uma pergunta."
  },
  AvgDialog_118945_Content_7 = {
    Text = "Miryam, por que você quer reviver o Reino Divino?"
  },
  AvgDialog_118945_Content_8 = {
    Text = "Você levantou uma questão muito interessante."
  },
  AvgDialog_118945_Content_9 = {
    Text = "Conheci muitas pessoas na minha jornada contra a dissolução."
  },
  AvgDialog_118946_Content_1 = {
    Text = "Voo e Liberdade"
  },
  AvgDialog_118946_Content_10 = {
    Text = "Ela levantou os dedos pálidos e girou a roca novamente."
  },
  AvgDialog_118946_Content_100 = {
    Text = "Até a escuridão engolir o mundo."
  },
  AvgDialog_118946_Content_11 = {
    Text = "Embora eu ainda não saiba seu nome, por favor, me abençoe, estranho."
  },
  AvgDialog_118946_Content_12 = {
    Text = "Um bando de aves voa passando, levantando ondas de penas brancas.\nApós a maré recuar, a mulher também desapareceu."
  },
  AvgDialog_118946_Content_13 = {
    Text = "Você fez um resumo rápido do planejamento geral para William."
  },
  AvgDialog_118946_Content_14 = {
    Text = "Parece um plano de caos para vencer."
  },
  AvgDialog_118946_Content_15 = {
    Text = "A cerimônia terminou, a rebelião estourou, e foi o momento mais frágil de toda a igreja dos Marchadores de Mares."
  },
  AvgDialog_118946_Content_16 = {
    Text = "De acordo com as pistas fornecidas por Faros, talvez só precisemos obter a estátua de marfim para escapar do domínio."
  },
  AvgDialog_118946_Content_17 = {
    Text = "Levar Murphy, não é um pouco complicado demais?"
  },
  AvgDialog_118946_Content_18 = {
    Text = "William, o companheiro mais velho, foi você quem me disse que os eventos no domínio podem afetar o mundo real fora do domínio."
  },
  AvgDialog_118946_Content_19 = {
    Text = "Já que é assim, não posso ficar de braços cruzados em relação à Murphy..."
  },
  AvgDialog_118946_Content_2 = {
    Text = "Mais um ciclo."
  },
  AvgDialog_118946_Content_20 = {
    Text = "Goliath pretende tomar o barco, ele não se importará com a fuga de Murphy; Miryam, cansada de lidar com Goliath, também está sem forças para perseguir."
  },
  AvgDialog_118946_Content_21 = {
    Text = "Esta é uma oportunidade incrível."
  },
  AvgDialog_118946_Content_22 = {
    Text = "William fechou os olhos e empurrou os óculos, parecendo dar um suspiro de resignação."
  },
  AvgDialog_118946_Content_23 = {
    Text = "Estou ouvindo você."
  },
  AvgDialog_118946_Content_24 = {
    Text = "Assim como na rodada anterior, você e William estão emboscados na plataforma do mastro."
  },
  AvgDialog_118946_Content_25 = {
    Text = "Aproveitando que Goliath iniciou a rebelião, você pulou e agarrou o pulso de Murphy."
  },
  AvgDialog_118946_Content_26 = {
    Text = "Rápido, venha comigo, pule do barco!"
  },
  AvgDialog_118946_Content_27 = {
    Text = "Você está louco? Por que você ainda voltou? Não conseguimos escapar, não seria melhor deixar tudo continuar tranquilamente?"
  },
  AvgDialog_118946_Content_28 = {
    Text = "Murphy tentou se soltar de você, mas sua insistência não podia ser recusada. Um círculo vermelho claro apareceu em seu pulso."
  },
  AvgDialog_118946_Content_29 = {
    Text = "Murphy, a estabilidade que você queria já não existe mais."
  },
  AvgDialog_118946_Content_3 = {
    Text = "As aves no mar circulam acima da mulher, seu canto triste parece uma canção."
  },
  AvgDialog_118946_Content_30 = {
    Text = "Goliath e Caecus planejam tomar o barco, Faros conspira pelo poder da estátua de marfim, e todo o marchador de mares já está em frangalhos."
  },
  AvgDialog_118946_Content_31 = {
    Text = "Acredite em mim, acredite em mim mais uma vez. Eu definitivamente irei te levar a escapar."
  },
  AvgDialog_118946_Content_32 = {
    Text = "Escapar, e depois?"
  },
  AvgDialog_118946_Content_33 = {
    Text = "Então, encontraremos uma maneira de voltar para Misaq, e você será parte de Misaq junto com todos."
  },
  AvgDialog_118946_Content_34 = {
    Text = "Eles costumam dizer que meus sonhos são premonitórios, em sonhos distantes, eu já vi tais visões…"
  },
  AvgDialog_118946_Content_35 = {
    Text = "Você sente que a força de resistência diminuiu um pouco."
  },
  AvgDialog_118946_Content_36 = {
    Text = "Vamos, venha comigo, para o lado direito da amurada... Três, dois, um, pule!"
  },
  AvgDialog_118946_Content_37 = {
    Text = "Splash, splash."
  },
  AvgDialog_118946_Content_38 = {
    Text = "Dois peixes livres saltando de volta para o seu leal mar, com as mãos ainda firmemente entrelaçadas."
  },
  AvgDialog_118946_Content_39 = {
    Text = "A luz do sol entra do mar, iluminando seus cabelos flutuantes e o véu nas águas cristalinas.\nOs olhos cor-de-rosa olham para você, como um sonho silencioso."
  },
  AvgDialog_118946_Content_4 = {
    Text = "Relaxe, desta vez nossa preparação está impecável."
  },
  AvgDialog_118946_Content_40 = {
    Text = "Vocês estão livres."
  },
  AvgDialog_118946_Content_41 = {Text = "Splash—"},
  AvgDialog_118946_Content_42 = {
    Text = "Uma remo perfurou a água cristalina à sua frente."
  },
  AvgDialog_118946_Content_43 = {
    Text = "Você acena com a cabeça para Murphy, e os dois se agarram ao remo do barco."
  },
  AvgDialog_118946_Content_44 = {
    Text = "Pegou firme?"
  },
  AvgDialog_118946_Content_45 = {
    Text = "Ele os puxou para fora da água, e você se apoiou na borda do barco para subir."
  },
  AvgDialog_118946_Content_46 = {
    Text = "Ei, venha me ajudar!"
  },
  AvgDialog_118946_Content_47 = {
    Text = "O que houve, você não consegue subir sozinho?"
  },
  AvgDialog_118946_Content_48 = {
    Text = "Menos conversa, ainda não decidi punir você por fazer a Mãe Divina cair na água!"
  },
  AvgDialog_118946_Content_49 = {
    Text = "Você puxou suavemente o ombro de Murphy que flutuava, levantando-a da superfície da água com a força exata."
  },
  AvgDialog_118946_Content_5 = {
    Text = "Sabemos que o navio irá naufragar após a cerimônia de pilotagem; sabemos que a estátua de marfim possui o poder de manipular os sonhos."
  },
  AvgDialog_118946_Content_50 = {Text = "Ufa—"},
  AvgDialog_118946_Content_51 = {
    Text = "Certo, agora podemos conversar direito. Para onde vamos?"
  },
  AvgDialog_118946_Content_52 = {
    Text = "Aproveitando a confusão entre Goliath e Miryam, nós três juntos navegamos este barco, saindo dos limites do Domínio."
  },
  AvgDialog_118946_Content_53 = {
    Text = "Então, juntos, encontrem o caminho de volta ao mundo original, você e o seu eu daquele mundo se encontram, disputando bolinhos na cantina todos os dias..."
  },
  AvgDialog_118946_Content_54 = {
    Text = "Puf, essa será uma longa jornada."
  },
  AvgDialog_118946_Content_55 = {
    Text = "Já que é assim, então me conte direito... sobre aquele lugar chamado Misaq."
  },
  AvgDialog_118946_Content_56 = {Text = "..."},
  AvgDialog_118946_Content_57 = {Text = "..."},
  AvgDialog_118946_Content_58 = {
    Text = "E depois, e depois?"
  },
  AvgDialog_118946_Content_59 = {
    Text = "Então, Ramona descobriu o vinho que Lorde Dexter escondia no canto de sua estante. Para esconder aquelas garrafas, ele havia escavado algumas páginas internas dos livros."
  },
  AvgDialog_118946_Content_6 = {
    Text = "Também sabemos que no porão há um único bote salva-vidas, basta sairmos deste cruzeiro e não estaremos mais sob a restrição de Miryam."
  },
  AvgDialog_118946_Content_60 = {
    Text = "Você percebeu de relance William com a cabeça baixa, franzindo a testa e esfregando as têmporas."
  },
  AvgDialog_118946_Content_61 = {
    Text = "Ela estava furiosa e entrou diretamente no salão da Senhora Sorel com a espada curta em punho!"
  },
  AvgDialog_118946_Content_62 = {Text = "E então?"},
  AvgDialog_118946_Content_63 = {
    Text = "Murphy segurou nervosamente a sua manga, com o estômago cheio de expectativa por histórias intrigantes."
  },
  AvgDialog_118946_Content_64 = {
    Text = "As risadas e conversas no salão de repente congelaram, todos arregalaram os olhos fixando-se neste visitante indesejado!"
  },
  AvgDialog_118946_Content_65 = {
    Text = "Exatamente, como o companheiro mais velho William agora!"
  },
  AvgDialog_118946_Content_66 = {Text = "Tem..."},
  AvgDialog_118946_Content_67 = {
    Text = "Há um assassino, há um assassino! Alguém está gritando por toda parte!"
  },
  AvgDialog_118946_Content_68 = {
    Text = "Seu sorriso congelou no rosto."
  },
  AvgDialog_118946_Content_69 = {
    Text = "Atrás de Murphy, na borda do pequeno barco, um monstro imponente, formado por milhões de cadáveres fundidos, emergiu abruptamente da superfície do mar."
  },
  AvgDialog_118946_Content_7 = {
    Text = "Nosso plano é que eu invada a cerimônia de navegação e, enquanto Murphy estiver fraca, a leve a pular no mar."
  },
  AvgDialog_118946_Content_70 = {
    Text = "<Big:......>"
  },
  AvgDialog_118946_Content_71 = {
    Text = "Ele abriu silenciosamente sua enorme boca feita de ossos e crânios se contorcendo——"
  },
  AvgDialog_118946_Content_72 = {
    Text = "<Red:Engoliu Murphy de forma brutal>"
  },
  AvgDialog_118946_Content_73 = {
    Text = "<Shake:Não... Marioneta da Maré Podre... não deveria já estar na Necrópole...>"
  },
  AvgDialog_118946_Content_74 = {
    Text = "Durante o tempo neste Domínio... Goliath ainda estava manipulando a Marioneta da Maré Podre."
  },
  AvgDialog_118946_Content_75 = {
    Text = "Seu núcleo principal está enfrentando Miryam, então enviou esta formação externa para persegui-la..."
  },
  AvgDialog_118946_Content_76 = {
    Text = "Nós... falhamos..."
  },
  AvgDialog_118946_Content_77 = {
    Text = "<Big:<Shake:...!!!>>"
  },
  AvgDialog_118946_Content_78 = {
    Text = "A criatura gigantesca que devorou Murphy ergueu sua cabeça estranha, emitindo um som de satisfação na garganta."
  },
  AvgDialog_118946_Content_79 = {
    Text = "A névoa suja se dispersa sobre o mar, o Navio Paradis já não é mais visível ao longe, apenas os picos de ossos se erguem, cobrindo o céu e a luz do sol."
  },
  AvgDialog_118946_Content_8 = {
    Text = "William, o companheiro mais velho, vai pilotar o bote salva-vidas para me buscar e a Murphy ao lado do barco. Assim que eu embarcar, vou desvendar rapidamente o mistério da estátua de marfim e sair do Domínio."
  },
  AvgDialog_118946_Content_80 = {
    Text = "Saia rápido!"
  },
  AvgDialog_118946_Content_81 = {
    Text = "William te abraçou com força, desorientado, rolando para o lado do barco, conseguindo escapar por pouco do primeiro golpe brutal da garra óssea."
  },
  AvgDialog_118946_Content_82 = {
    Text = "William, o companheiro mais velho, suas costas..."
  },
  AvgDialog_118946_Content_83 = {
    Text = "Sangue, sangue que pinga."
  },
  AvgDialog_118946_Content_84 = {
    Text = "Não se preocupe comigo, suba e corte a coluna da Marionete da Maré Podre!"
  },
  AvgDialog_118946_Content_85 = {Text = "..."},
  AvgDialog_118946_Content_86 = {
    Text = "<Big:......>"
  },
  AvgDialog_118946_Content_87 = {
    Text = "A Marioneta da Maré Podre desabou como uma torre, chuvas de ossos pálidos caíram em um oceano infinito."
  },
  AvgDialog_118946_Content_88 = {
    Text = "Como você disse... a força de Golias foi enormemente enfraquecida no domínio."
  },
  AvgDialog_118946_Content_89 = {
    Text = "Então, só conseguimos resistir..."
  },
  AvgDialog_118946_Content_9 = {
    Text = "A mulher abaixou a cabeça, com a franja fina cobrindo sua expressão."
  },
  AvgDialog_118946_Content_90 = {
    Text = "Talvez seja por causa da gravidade da lesão, você não consegue ouvir as palavras de William."
  },
  AvgDialog_118946_Content_91 = {
    Text = "Entre a maré de corpos em colapso e os ossos, não se vê a silhueta daquela menina."
  },
  AvgDialog_118946_Content_92 = {
    Text = "Murphy……Murphy!"
  },
  AvgDialog_118946_Content_93 = {
    Text = "Você corre em direção aos ossos flutuantes, escavando um por um os crânios empilhados na localização do trato digestivo."
  },
  AvgDialog_118946_Content_94 = {
    Text = "<Yellow:%player%>......"
  },
  AvgDialog_118946_Content_95 = {
    Text = "Não se pode encontrar Murphy em lugar nenhum."
  },
  AvgDialog_118946_Content_96 = {
    Text = "No centro dos ossos dispostos de forma desordenada, havia apenas um fino e leve véu negro."
  },
  AvgDialog_118946_Content_97 = {
    Text = "Você levanta suavemente aquele véu negro, uma onda de tristeza sobe ao seu coração."
  },
  AvgDialog_118946_Content_98 = {
    Text = "Eu pensei que desta vez, definitivamente conseguiria levá-la a escapar..."
  },
  AvgDialog_118946_Content_99 = {
    Text = "Você emite um soluço profundo. Depois, o choro se torna gradualmente mais alto."
  },
  AvgDialog_118947_Content_1 = {Text = "\"Paraíso\""},
  AvgDialog_118947_Content_10 = {
    Text = "Você usou uma pinça para retirar a assadeira, e Murphy imediatamente estendeu a mão ansiosamente para pegar um bolinho quente que exalava vapor."
  },
  AvgDialog_118947_Content_11 = {
    Text = "Não se apresse, está quente, está quente, está quente, está quente!"
  },
  AvgDialog_118947_Content_12 = {
    Text = "Murphy parecia totalmente relutante em soltar, queimando a mão esquerda e a direita várias vezes, finalmente esperou até que o bolo atingisse uma temperatura adequada."
  },
  AvgDialog_118947_Content_13 = {
    Text = "Prove um pouco... Parece que não preciso dizer."
  },
  AvgDialog_118947_Content_14 = {
    Text = "Antes que suas palavras chegassem ao fim, Murphy já havia mordido."
  },
  AvgDialog_118947_Content_15 = {
    Text = "Como está, é gostoso?"
  },
  AvgDialog_118947_Content_16 = {
    Text = "A receita depende totalmente da sua memória. Para atender a jovem senhora que grita de fome no meio da noite, você já usou a cozinha de Misaq várias vezes."
  },
  AvgDialog_118947_Content_17 = {
    Text = "Hum, os ingredientes são muito simples, não se comparam com os que Miryam costuma me fornecer."
  },
  AvgDialog_118947_Content_18 = {
    Text = "Murphy engoliu cuidadosamente os restos na boca e falou com seriedade."
  },
  AvgDialog_118947_Content_19 = {
    Text = "No entanto, quem diria que o talento culinário da Mãe Divina é tão incrível, capaz de transformar a podridão em algo divino."
  },
  AvgDialog_118947_Content_2 = {Text = "..."},
  AvgDialog_118947_Content_20 = {
    Text = "Quente e macio... esta é a comida mais deliciosa que já comi."
  },
  AvgDialog_118947_Content_21 = {
    Text = "Vou experimentar um pedaço também."
  },
  AvgDialog_118947_Content_22 = {
    Text = "William cuidadosamente pegou um pedaço com uma pequena faca prateada e colocou na boca."
  },
  AvgDialog_118947_Content_23 = {
    Text = "Companheiro mais velho, se não estou enganado, a faca que você usou para cortar o bolo é a mesma que foi utilizada para dissecção de Núbia?"
  },
  AvgDialog_118947_Content_24 = {
    Text = "Já foi desinfetado adequadamente. Os garfos e facas improvisados usados pelos marinheiros são realmente difíceis de usar."
  },
  AvgDialog_118947_Content_25 = {
    Text = "Se eu soubesse, deveria ter pedido dois conjuntos de talheres ao Doresain na Necrópole...\n Deixe pra lá, pensando bem, é difícil dizer o que os talheres do Doresain cortaram..."
  },
  AvgDialog_118947_Content_26 = {
    Text = "Vocês se deliciam, rindo enquanto esfregam creme nas caras uns dos outros."
  },
  AvgDialog_118947_Content_27 = {
    Text = "(Se esta é a última memória dela...)"
  },
  AvgDialog_118947_Content_28 = {Text = "Bang—"},
  AvgDialog_118947_Content_29 = {
    Text = "Um grande estrondo quebrou a rara tranquilidade, e a cozinha onde vocês estão começou a tremer violentamente de forma incontrolável."
  },
  AvgDialog_118947_Content_3 = {
    Text = "Em algumas dezenas de minutos."
  },
  AvgDialog_118947_Content_30 = {
    Text = "Que situação?!"
  },
  AvgDialog_118947_Content_31 = {
    Text = "Goliath saqueou a sala de energia, Miryam resistiu ferozmente, e houve uma explosão na sala de energia."
  },
  AvgDialog_118947_Content_32 = {
    Text = "Você respondeu de forma indiferente."
  },
  AvgDialog_118947_Content_33 = {
    Text = "Em outras palavras, o navio vai afundar."
  },
  AvgDialog_118947_Content_34 = {
    Text = "O navio vai afundar, você não tem nenhuma reação?"
  },
  AvgDialog_118947_Content_35 = {
    Text = [[
Murphy, eu preciso te contar algo.
Este navio tem que afundar.]]
  },
  AvgDialog_118947_Content_36 = {
    Text = "Eu passei por cinco ciclos, e em cada ciclo, Goliath sempre planejava o Raub de navios."
  },
  AvgDialog_118947_Content_37 = {
    Text = "Esse processo provocará uma explosão na sala de energia, e em seguida o navio será sugado para o fundo do mar por um vórtice."
  },
  AvgDialog_118947_Content_38 = {Text = "Então?"},
  AvgDialog_118947_Content_39 = {
    Text = "Tenho pensado em maneiras de impedir a destruição deste navio, e foi por isso que meu raciocínio se desvirtuou."
  },
  AvgDialog_118947_Content_4 = {
    Text = "Vocês observam o forno, a massa amassada se expandindo pouco a pouco, e seu coração ansioso também se eleva levemente junto com aquele arco fofo."
  },
  AvgDialog_118947_Content_40 = {
    Text = "Este navio deve afundar... Só assim ele poderá abrir um caminho de liberdade para você."
  },
  AvgDialog_118947_Content_41 = {Text = "Boom——"},
  AvgDialog_118947_Content_42 = {
    Text = "O casco do navio se contorceu e tremeu como se tivesse sido atingido por um raio, parecendo uma besta gigante se contorcendo descontroladamente em meio à dor explosiva."
  },
  AvgDialog_118947_Content_43 = {
    Text = "Certo, agora não precisamos de tantas explicações, venha comigo."
  },
  AvgDialog_118947_Content_44 = {
    Text = "Se demorar mais, não haverá mais tempo para nada."
  },
  AvgDialog_118947_Content_45 = {
    Text = "Você puxou Murphy e seguiu pelo caminho indicado por William."
  },
  AvgDialog_118947_Content_46 = {
    Text = "Ei, você realmente vai deixar a dama subir a escada? Usar as mãos e os pés na frente dos outros é muito embaraçoso, não é?!"
  },
  AvgDialog_118947_Content_47 = {
    Text = "Você primeiro desça e me espere, eu definitivamente não vou olhar para você."
  },
  AvgDialog_118947_Content_48 = {
    Text = "Os olhos foram se adaptando à escuridão, e no canto do porão, uma pequena embarcação estava parada sozinha."
  },
  AvgDialog_118947_Content_49 = {
    Text = "Este é o caminho de fuga que Goliath preparou para si mesmo, e nós o encontramos."
  },
  AvgDialog_118947_Content_5 = {
    Text = "O cheiro do creme de ovos e leite se espalha, as glândulas salivares percebem antes do cérebro, e a lombriga faz seu estômago roncar."
  },
  AvgDialog_118947_Content_50 = {
    Text = "Esse cara astuto destruiu quase todos os botes salva-vidas antes de iniciar a rebelião, garantindo que só ele pudesse escapar."
  },
  AvgDialog_118947_Content_51 = {
    Text = "Aqui está a chave reserva, que pedi ao William para preparar. Agora, embarque."
  },
  AvgDialog_118947_Content_52 = {
    Text = "Espere, o que você está dizendo? Eu nunca concordei em fugir com você——"
  },
  AvgDialog_118947_Content_53 = {
    Text = "Eu também não disse que embarcaria com você. Aqui há, e apenas um, bote salva-vidas. Você sobe nele sozinho e depois desembarca."
  },
  AvgDialog_118947_Content_54 = {Text = "!"},
  AvgDialog_118947_Content_55 = {
    Text = "Se nós simplesmente formos embora, Miryam não vai desistir. Um dia, a sombra dos Marchadores de mares ainda irá atrás de você."
  },
  AvgDialog_118947_Content_56 = {
    Text = "Preciso ficar aqui, garantindo que os Marchadores de mares e o Feto Sagrado afundem para sempre no Mar Profundo."
  },
  AvgDialog_118947_Content_57 = {
    Text = "Isso é algo que eles também desejam, o retorno à sua eterna terra natal e ao Reino Divino, não é?"
  },
  AvgDialog_118947_Content_58 = {Text = "Pff—"},
  AvgDialog_118947_Content_59 = {
    Text = "Murphy sorriu com lágrimas nos olhos."
  },
  AvgDialog_118947_Content_6 = {
    Text = "Os passos ansiosos e úmidos dos Marchadores de mares soavam de vez em quando pelo chão de madeira, mas a fina porta separava dois mundos, e este pequeno espaço estava repleto de uma felicidade e calor excessivamente simples, como uma ilusão."
  },
  AvgDialog_118947_Content_60 = {
    Text = "Antes de partir, eu já tinha planejado tudo."
  },
  AvgDialog_118947_Content_61 = {
    Text = "Se eu puder te enviar para escapar, então esse é o melhor final."
  },
  AvgDialog_118947_Content_62 = {
    Text = "Se não puder... pelo menos, eu já me esforcei para te devolver um dia que o Murphy que eu conheço iria gostar."
  },
  AvgDialog_118947_Content_63 = {
    Text = "Não nos conhecemos há muito tempo e meu entendimento sobre você ainda é superficial. Espero que você também goste."
  },
  AvgDialog_118947_Content_64 = {
    Text = "Murphy ficou na ponta dos pés e te deu um abraço suave."
  },
  AvgDialog_118947_Content_65 = {
    Text = "Eu lembro que você disse que viveria o ciclo repetidamente."
  },
  AvgDialog_118947_Content_66 = {
    Text = "Desta vez, não será o fim."
  },
  AvgDialog_118947_Content_67 = {
    Text = "Na próxima vez, leve-me junto para escapar, tudo bem?"
  },
  AvgDialog_118947_Content_68 = {
    Text = "<Red:Não haverá uma próxima vez.>\nA sensação ácida subiu até a ponta do seu nariz."
  },
  AvgDialog_118947_Content_69 = {
    Text = "Eu prometo a você. Nós vamos escapar juntos."
  },
  AvgDialog_118947_Content_7 = {
    Text = "Olha, a casca já mudou de cor, pode ser servido!"
  },
  AvgDialog_118947_Content_70 = {
    Text = "Nuvens escuras se acumulam, e na proa do navio, Miryam e Golias se encaram à distância."
  },
  AvgDialog_118947_Content_71 = {
    Text = "Entregue aquela garotinha e a estátua de marfim, e eu poderei lhe conceder uma morte digna, como você ameaçou uma vez."
  },
  AvgDialog_118947_Content_72 = {
    Text = "Não fiquem falando besteiras aqui, não foram vocês que roubaram a Mãe Divina e provocaram essa revolta?"
  },
  AvgDialog_118947_Content_73 = {
    Text = "Vocês não precisam mais discutir, Murphy já não está mais neste barco.\nEla já escapou das garras, longe do redemoinho."
  },
  AvgDialog_118947_Content_74 = {
    Text = "Uma sensação inexplicável de alívio surgiu no coração."
  },
  AvgDialog_118947_Content_75 = {
    Text = "Foi você quem a mandou embora? Tem um pouco de coragem."
  },
  AvgDialog_118947_Content_76 = {
    Text = "Se vocês estão prontos para uma grande batalha aqui, eu não me importaria de lucrar com isso."
  },
  AvgDialog_118947_Content_77 = {
    Text = "Quem diria que era você, esse estranho sem nome..."
  },
  AvgDialog_118947_Content_78 = {
    Text = "Achou que, com a proteção da Mãe Divina, poderia fazer o que quisesse?"
  },
  AvgDialog_118947_Content_79 = {
    Text = "Miryam, eu quero falar com você."
  },
  AvgDialog_118947_Content_8 = {
    Text = "...Tá bom!"
  },
  AvgDialog_118947_Content_80 = {
    Text = "Não é declarar a guerra de forma rude e imprudente, mas começar com uma conversa, certo?"
  },
  AvgDialog_118947_Content_81 = {
    Text = "Estou muito curioso, que tipo de pessoa imprudente você é, que recebeu a convocação da Mãe Divina e ainda consegue agir de forma imprudente e destemida até aqui."
  },
  AvgDialog_118947_Content_82 = {
    Text = "Se você pedir sinceramente uma resposta ao apóstolo de Deus, eu certamente lhe concederei a vontade divina."
  },
  AvgDialog_118947_Content_83 = {
    Text = "<Red:<Shake:Mas agora, suporte a raiva dos marinheiros!>>"
  },
  AvgDialog_118947_Content_9 = {
    Text = "O aroma de creme de ovos se espalha."
  },
  AvgDialog_118948_Content_1 = {Text = "vórtice"},
  AvgDialog_118948_Content_10 = {
    Text = "\"Com um 'estalo', o fio prateado se rompeu instantaneamente.\""
  },
  AvgDialog_118948_Content_11 = {
    Text = "Caecus não percebeu nada disso, apenas te observa com desconfiança."
  },
  AvgDialog_118948_Content_12 = {
    Text = "Amigo, o que você está dizendo, amigo?"
  },
  AvgDialog_118948_Content_13 = {
    Text = "Deve ser uma técnica enganadora! Não ouça {Male=ele,Female=ela}, Senhor Caecus!"
  },
  AvgDialog_118948_Content_14 = {
    Text = "Senha, sim, senha..."
  },
  AvgDialog_118948_Content_15 = {
    Text = "Caecus respirou fundo, como se a coragem tivesse sido reabastecida em seu corpo, e ele levantou a cabeça de repente."
  },
  AvgDialog_118948_Content_16 = {
    Text = "Eu só sei que os Marchadores de mares te acomodaram temporariamente, isso não significa que você pode entrar e sair livremente de locais críticos."
  },
  AvgDialog_118948_Content_17 = {
    Text = "Atendendo à ordem do Senhor Goliath, pessoas não autorizadas não podem entrar na sala de energia!"
  },
  AvgDialog_118948_Content_2 = {
    Text = "Olhe para lá, parece que alguém está vigiando a sala de energia."
  },
  AvgDialog_118948_Content_3 = {
    Text = "Vários corpos curvados vagavam, entre eles, um jovem de postura ereta segurava firmemente uma lança de membrana, vigilante e cauteloso com o movimento do vento ao redor."
  },
  AvgDialog_118948_Content_4 = {
    Text = "Fiquem atentos! A importante tarefa designada pelo senhor Golias não pode ter falhas..."
  },
  AvgDialog_118948_Content_5 = {Text = "Caecus!"},
  AvgDialog_118948_Content_6 = {
    Text = "Ei, você é..."
  },
  AvgDialog_118948_Content_7 = {
    Text = "Você tenta ativar a chave de prata, conectando-se à consciência dele, despertando as memórias do passado de vocês."
  },
  AvgDialog_118948_Content_8 = {
    Text = "Tentáculos de luz ilusória prateada se estendem, subindo, ao longo da superfície do corpo coberta de escamas, penetrando em sua medula espinhal…"
  },
  AvgDialog_118948_Content_9 = {
    Text = "Caecus, eu sou seu amigo, posso entrar atrás de você..."
  },
  AvgDialog_118949_Content_1 = {
    Text = "Desculpe, Senhor Golias..."
  },
  AvgDialog_118949_Content_10 = {
    Text = "Mas agora é o momento crucial do plano, e as variáveis devem ser o menor possível."
  },
  AvgDialog_118949_Content_11 = {
    Text = "Cale a boca para sempre aqui, pequeno."
  },
  AvgDialog_118949_Content_12 = {
    Text = "Senhor Goliath, eu lutarei ao seu lado!"
  },
  AvgDialog_118949_Content_13 = {
    Text = "Não precisa, com essas coisas fracas, não temos espaço aqui para nos movimentar."
  },
  AvgDialog_118949_Content_14 = {
    Text = "<Small:Mas eu...>"
  },
  AvgDialog_118949_Content_15 = {
    Text = "Caecus murmurou suavemente, mas a recente derrota na batalha o fez perceber que não tinha mais posição para continuar reclamando, então ele se calou e recuou um passo."
  },
  AvgDialog_118949_Content_16 = {
    Text = "Caecus garoto."
  },
  AvgDialog_118949_Content_17 = {Text = "Sim?"},
  AvgDialog_118949_Content_18 = {
    Text = "Goliath não se virou."
  },
  AvgDialog_118949_Content_19 = {
    Text = "Não desanime, você é a pessoa que eu escolhi. Assim que resolvermos isso, vou adicionar 500 sessões de treino para você."
  },
  AvgDialog_118949_Content_2 = {
    Text = "Hum, não precisa ficar tão nervoso."
  },
  AvgDialog_118949_Content_20 = {Text = "Ah…sim!"},
  AvgDialog_118949_Content_21 = {
    Text = "Faróis, você está pronto?"
  },
  AvgDialog_118949_Content_22 = {
    Text = "Basta que seja para construir a escada para o Reino Divino... Faros estará sempre à disposição para suas ordens."
  },
  AvgDialog_118949_Content_3 = {
    Text = "Goliath saiu lentamente com a espada em punho, a lâmina serrilhada arrastando-se pelo chão, emitindo um som agudo e estridente."
  },
  AvgDialog_118949_Content_4 = {
    Text = "Com esse barulho vocês não conseguem lidar, é realmente uma vergonha para a linhagem dos filisteus."
  },
  AvgDialog_118949_Content_5 = {
    Text = "Desculpe, eu..."
  },
  AvgDialog_118949_Content_6 = {
    Text = "Guh, senhor Goliath, não culpe o senhor Caecus, aquele cara desconhecido pode invocar monstros invisíveis!"
  },
  AvgDialog_118949_Content_7 = {
    Text = "Outro... Ei, pequeno, é você."
  },
  AvgDialog_118949_Content_8 = {
    Text = "Deixe a Necrópole de lado, aqui não é lugar para você se comportar como um selvagem."
  },
  AvgDialog_118949_Content_9 = {
    Text = "Se nos encontrássemos um pouco mais tarde, talvez pudéssemos passar um tempo sentados conversando."
  },
  AvgDialog_118950_Content_1 = {
    Text = "O céu está queimando."
  },
  AvgDialog_118950_Content_10 = {
    Text = "Uma marca de sangue vermelho se estende continuamente atrás dele, misturando-se com os veios da madeira do convés."
  },
  AvgDialog_118950_Content_11 = {
    Text = "<Red:Vá morrer, bastardo, herege!>"
  },
  AvgDialog_118950_Content_12 = {
    Text = "O sacerdote com os olhos arregalados levantou a lança que pertencia ao jovem, cravando-a de forma precisa e cruel nas costas do jovem. A ponta afiada da lança perfurou o corpo, pregando o jovem firmemente no convés."
  },
  AvgDialog_118950_Content_13 = {
    Text = "O jovem teve um espasmo e parou a um passo de distância do homem."
  },
  AvgDialog_118950_Content_14 = {
    Text = "Haha, hahahaha!"
  },
  AvgDialog_118950_Content_15 = {
    Text = "Ó Senhor, grande Senhor, você viu? Este é o Sacramento que eu e a Mãe Divina oferecemos a você!"
  },
  AvgDialog_118950_Content_16 = {
    Text = "Miryam, com o rosto coberto de sangue, olhava de longe para esta pintura do inferno, rindo de maneira arrogante para o céu, enquanto a túnica rasgada flutuava nas chamas."
  },
  AvgDialog_118950_Content_17 = {
    Text = "<Shake:Que o seu Reino Divino emerja novamente do abismo, que a sua vontade se realize em breve na Terra!>"
  },
  AvgDialog_118950_Content_18 = {
    Text = "O olhar do Grande Sacerdote percorreu seu território, passando por Faros cortado ao meio por uma lâmina gigante, passando por dois investigadores gravemente feridos e incapazes de se mover, e parou na menina envolta em um véu negro encharcado de sangue e veneno."
  },
  AvgDialog_118950_Content_19 = {
    Text = "Ó Mãe Divina, venha, venha até mim. Já sancionei todos os traidores que abandonaram a luz e os caídos que profanaram as divindades!"
  },
  AvgDialog_118950_Content_2 = {
    Text = "O mar está queimando."
  },
  AvgDialog_118950_Content_20 = {
    Text = "O casco danificado perdeu o equilíbrio devido à infiltração de água, e metade do navio já estava submersa, mas ela não percebe."
  },
  AvgDialog_118950_Content_21 = {
    Text = "<Red:<Shake:Agora cabe a nós dois herdar a imortalidade do Reino Divino, até o próximo momento da posição correta das estrelas, seu santo nome será proclamado em todo o universo!>>"
  },
  AvgDialog_118950_Content_22 = {
    Text = "Na proa inclinada como uma guilhotina, Miryam estendeu a mão manchada de sangue, olhando de cima para baixo."
  },
  AvgDialog_118950_Content_23 = {
    Text = "<Shake:Não, não é... não é...>"
  },
  AvgDialog_118950_Content_24 = {
    Text = "As pernas de Murphy cederam, e ela caiu de joelhos no chão.\n Seu corpo pequeno havia perdido completamente a graça de antes, tremendo à luz do fogo."
  },
  AvgDialog_118950_Content_25 = {
    Text = "<Shake:Desculpe, eu não deveria... eu não deveria querer escapar...>"
  },
  AvgDialog_118950_Content_26 = {
    Text = "As lágrimas rolavam, deixando marcas manchadas no convés, que eram secas pelo calor das chamas."
  },
  AvgDialog_118950_Content_27 = {
    Text = "<Red:<Shake:Eu deveria saber, este é o destino do qual não posso escapar...>>"
  },
  AvgDialog_118950_Content_28 = {
    Text = "Murphy… não é assim, Murphy, ainda há uma chance…"
  },
  AvgDialog_118950_Content_29 = {
    Text = "Você está ansioso para confortar aquela menina, mas seu corpo trai sua vontade."
  },
  AvgDialog_118950_Content_3 = {
    Text = "Não, não é assim... apenas seu campo de visão está queimando.\n A morte e o desespero cobrem esta terra sem dono sobre o mar."
  },
  AvgDialog_118950_Content_30 = {
    Text = "Uma dor intensa no tornozelo rasga cada uma de suas percepções, a lesão grave sofrida na batalha anterior o prende firmemente ao chão, tornando impossível se mover."
  },
  AvgDialog_118950_Content_31 = {Text = "Desculpe."},
  AvgDialog_118950_Content_32 = {
    Text = "Ignorando a ferida sangrando no peito, a menina levantou-se calmamente."
  },
  AvgDialog_118950_Content_33 = {
    Text = "A dor não pode mais detê-la, sem hesitação, sem ilusões e sem saudades."
  },
  AvgDialog_118950_Content_34 = {
    Text = "Atravessando montanhas de cadáveres e mares de fogo.\nEla caminhou com passos solenes, um a um em direção ao sacerdote."
  },
  AvgDialog_118950_Content_35 = {
    Text = "Não... não pode acabar aqui..."
  },
  AvgDialog_118950_Content_36 = {
    Text = "William... Senhor William...! Você ainda consegue se mover?"
  },
  AvgDialog_118950_Content_37 = {
    Text = "O que você quer... fazer?"
  },
  AvgDialog_118950_Content_38 = {
    Text = "William estava deitado em uma poça de sangue, ofegante."
  },
  AvgDialog_118950_Content_39 = {
    Text = "<Red:<Big:……mate-me, reinicie o ciclo.>>"
  },
  AvgDialog_118950_Content_4 = {
    Text = "As explosões em cadeia rasgaram a sala de energia, o convés em chamas se ergueu em distorção."
  },
  AvgDialog_118950_Content_40 = {
    Text = "Não... por quê..."
  },
  AvgDialog_118950_Content_41 = {
    Text = "Não posso deixar que este mundo se torne o fim... Não consigo aceitar um final assim..."
  },
  AvgDialog_118950_Content_42 = {
    Text = "Rápido, eu já não consigo me mexer..."
  },
  AvgDialog_118950_Content_43 = {
    Text = "O braço mecânico de William já tinha se separado do corpo, e ele mal conseguiu estender o braço que ainda podia se mover, segurando o punhal que Miryam havia jogado ao lado."
  },
  AvgDialog_118950_Content_44 = {
    Text = "Desculpe, eu não consigo te mostrar minha expressão neste momento..."
  },
  AvgDialog_118950_Content_45 = {
    Text = "Então, uma dor lancinante veio da parte de trás do lado esquerdo."
  },
  AvgDialog_118950_Content_46 = {
    Text = "Não pense!"
  },
  AvgDialog_118950_Content_47 = {
    Text = "Sacerdote, capture aquele cara vivo, não deixe {Male=ele,Female=ela} morrer!"
  },
  AvgDialog_118950_Content_48 = {
    Text = "Miryam deu a ordem e outro tridente perfurou o peito de William. Você olhou para trás, chocado, e viu apenas um cabelo loiro caindo suavemente."
  },
  AvgDialog_118950_Content_49 = {
    Text = "O sacerdote peixe-homem girou estranhamente no lugar e começou a rir de barriga cheia."
  },
  AvgDialog_118950_Content_5 = {
    Text = "Os companheiros que lutaram ao seu lado e os inimigos com quem travou batalhas mortais jazem indistintamente em meio a um lago de sangue escarlate e fervente."
  },
  AvgDialog_118950_Content_50 = {
    Text = "Guh, hehe, não importa o que você queira fazer, agora não dá para fazer!"
  },
  AvgDialog_118950_Content_51 = {
    Text = "O coração dói mais do que um corte de faca, os membros perdendo sangue estão gelados e com calafrios."
  },
  AvgDialog_118950_Content_52 = {
    Text = "<Red:você deve morrer>, você deve ir para a próxima reencarnação."
  },
  AvgDialog_118950_Content_53 = {
    Text = "<Red:<Shake:Eu... com certeza posso...>>"
  },
  AvgDialog_118950_Content_54 = {
    Text = "Use a tábua para bloquear o punhal"
  },
  AvgDialog_118950_Content_55 = {
    Text = "O punhal se infiltra lentamente em seu corpo, seguido por uma dor que penetra até a medula."
  },
  AvgDialog_118950_Content_56 = {
    Text = "Cair para trás com força"
  },
  AvgDialog_118950_Content_57 = {
    Text = "A lâmina afiada penetra em seu peito, uma sensação de vazio de consciência envolve seu campo de visão."
  },
  AvgDialog_118950_Content_58 = {
    Text = "<Shake:Murphy... William... por favor, esperem por mim na próxima reencarnação.>"
  },
  AvgDialog_118950_Content_59 = {
    Text = "<Yellow:Nós certamente... escaparemos.>"
  },
  AvgDialog_118950_Content_6 = {
    Text = "<Shake:Senhor Golias, desculpe, se eu fosse um pouco mais forte...>"
  },
  AvgDialog_118950_Content_7 = {
    Text = "O jovem gravemente ferido arrastava seu corpo em pedaços, tentando agarrar o chão áspero com os dez dedos, rastejando com dificuldade em direção ao homem adormecido."
  },
  AvgDialog_118950_Content_8 = {
    Text = "<Shake:Senhor Gulias...>"
  },
  AvgDialog_118950_Content_9 = {
    Text = "Não importa como ele o chame, o homem sem vida não se moveu nem um pouco."
  },
  AvgDialog_118951_Content_1 = {
    Text = "Então, você me enganou para me trazer aqui, afinal, o que você quer fazer?"
  },
  AvgDialog_118951_Content_10 = {
    Text = "Vamos fazer algo que não tem nada a ver com a Mãe Divina, doutrinas ou rituais."
  },
  AvgDialog_118951_Content_11 = {
    Text = "Eu sei, embora você sempre mencione essas coisas agora, o que você realmente gosta não são elas."
  },
  AvgDialog_118951_Content_12 = {
    Text = "Não diga tanto, pegue isso rápido!"
  },
  AvgDialog_118951_Content_13 = {Text = "Isso, é?"},
  AvgDialog_118951_Content_14 = {
    Text = "Misture rapidamente, em uma direção!"
  },
  AvgDialog_118951_Content_15 = {Text = "..."},
  AvgDialog_118951_Content_16 = {
    Text = "Então, adicione farinha! Fermento em pó! Um pouco de sal!"
  },
  AvgDialog_118951_Content_17 = {
    Text = "Senhor William, não fique parado! Vá ajudar a derreter a manteiga!"
  },
  AvgDialog_118951_Content_18 = {
    Text = "……Certo."
  },
  AvgDialog_118951_Content_19 = {
    Text = "William se afastou, pacientemente interpretando o assistente de cozinha atolondrado, mas diligente."
  },
  AvgDialog_118951_Content_2 = {
    Text = "Vamos deixar o William, o companheiro mais velho, fazer um truque de mágica para você!"
  },
  AvgDialog_118951_Content_20 = {
    Text = "Finalmente, vocês colocaram a massa misturada no forno."
  },
  AvgDialog_118951_Content_21 = {
    Text = "Murphy olhou fixamente para o forno, perdido em pensamentos."
  },
  AvgDialog_118951_Content_22 = {
    Text = "Lembrei-me de algumas coisas de muito, muito tempo atrás…"
  },
  AvgDialog_118951_Content_23 = {Text = "Sim?"},
  AvgDialog_118951_Content_24 = {
    Text = "Isso foi quando ainda estávamos na base na Antártida. Eu encontrei um altar em um desfiladeiro, com muitas pequenas esculturas de pedra."
  },
  AvgDialog_118951_Content_25 = {
    Text = "Eu pedi para a mamãe... Miryam me dar uma faca pequena e alguns pedaços de madeira, eu quero fazer algumas esculturas em madeira."
  },
  AvgDialog_118951_Content_26 = {
    Text = "Depois de muito tempo, ela só me deu uma faca sem fio, dizendo que estava preocupada com \"o corpo sagrado da Mãe Divina\"."
  },
  AvgDialog_118951_Content_27 = {
    Text = "Sinto que meu corpo parece não pertencer a mim, e claro, também não pertence a ela. Nós parecemos ser um tijolo daquela coisa chamada Reino Divino, abafados em nossos lugares, incapazes de nos mover um pouco."
  },
  AvgDialog_118951_Content_28 = {
    Text = "Eu vi algumas esculturas de madeira ao lado da sua cama."
  },
  AvgDialog_118951_Content_29 = {
    Text = "Hmm, eu pedi secretamente ao Golias para me ajudar a encontrar uma pedra de óleo."
  },
  AvgDialog_118951_Content_3 = {
    Text = "Tudo foi devolvido de acordo com a lista, por favor, confirme."
  },
  AvgDialog_118951_Content_30 = {
    Text = "Fiz bastante esforço para afiar a lâmina até um ponto em que pudesse cortar madeira."
  },
  AvgDialog_118951_Content_31 = {
    Text = "Eu esculpi por muitos dias, esforçando-me para reproduzir os detalhes que imaginei."
  },
  AvgDialog_118951_Content_32 = {
    Text = "Quando finalmente fiquei satisfeito, eu entreguei a Miryam…"
  },
  AvgDialog_118951_Content_33 = {
    Text = "Você sabe o que ela disse?"
  },
  AvgDialog_118951_Content_34 = {
    Text = "Miryam... ela disse que você não esculpe bem, profanação?"
  },
  AvgDialog_118951_Content_35 = {
    Text = "Você se esforça para entender a mentalidade de Miryam, dando uma suposição com cautela."
  },
  AvgDialog_118951_Content_36 = {Text = "Não."},
  AvgDialog_118951_Content_37 = {
    Text = "Ela não olhou nem uma vez, apenas disse que se eu gostasse desse tipo de estátua, ela poderia dar ordens para que os melhores artesãos me esculpessem todos os dias."
  },
  AvgDialog_118951_Content_38 = {
    Text = "Murphy riu de forma louca, uma dor indescritível e provocação transbordando de seu sorriso rígido."
  },
  AvgDialog_118951_Content_39 = {
    Text = "Sou filho dos deuses e também seu ventre; o que você deseja, basta levantar a mão para ter."
  },
  AvgDialog_118951_Content_4 = {
    Text = "William abriu um por um os vários bolsos grandes e pequenos no peito, nas costas e nos braços."
  },
  AvgDialog_118951_Content_40 = {
    Text = "Como já tenho tudo, esculpir uma escultura de madeira é, claro, uma tarefa insignificante."
  },
  AvgDialog_118951_Content_41 = {
    Text = "Ela ria, ria, e sem perceber, as lágrimas começaram a escorregar. As lágrimas inesperadas deslizavam rapidamente pelas bochechas dela, distorcidas pelo riso incontrolável."
  },
  AvgDialog_118951_Content_42 = {
    Text = "Eu vi suas obras que você colocou ao lado da cama, suas habilidades são muito boas."
  },
  AvgDialog_118951_Content_43 = {
    Text = "Bom e mau, qual é a importância disso..."
  },
  AvgDialog_118951_Content_44 = {
    Text = "Murphy, de agora em diante, você pode esculpir como quiser."
  },
  AvgDialog_118951_Content_45 = {
    Text = "Então, vamos fazer um bolinho juntos e estudar arranjos florais."
  },
  AvgDialog_118951_Content_46 = {
    Text = "Eu vou encontrar uma maneira de voltar para o meu mundo, vou apresentar a você o Murphy que eu conheço, e vocês poderão fazer tudo o que quiserem juntos, livremente."
  },
  AvgDialog_118951_Content_47 = {
    Text = "Murphy enxugou as lágrimas com as mãos, levantou a cabeça e te deu um sorriso radiante que você nunca tinha visto antes."
  },
  AvgDialog_118951_Content_48 = {
    Text = "Certo, isso é tudo que você me prometeu."
  },
  AvgDialog_118951_Content_49 = {
    Text = "Absolutamente, você não pode faltar."
  },
  AvgDialog_118951_Content_5 = {
    Text = "Agradecemos ao grande Deus da Magia, William, o companheiro mais velho, pelos ingredientes que nos roubou da cozinha."
  },
  AvgDialog_118951_Content_50 = {
    Text = "Esta é uma história que não tem nada a ver com a Mãe Divina."
  },
  AvgDialog_118951_Content_51 = {
    Text = "Mas ela parece que nunca esteve tão feliz nesta vida."
  },
  AvgDialog_118951_Content_6 = {
    Text = "Há farinha, ovos, limão, mel, açúcar, fermento em pó e manteiga."
  },
  AvgDialog_118951_Content_7 = {
    Text = "Está bem completo! Ter muitos bolsos no uniforme de marinheiro é ótimo."
  },
  AvgDialog_118951_Content_8 = {
    Text = "Ainda não entendo... por quê?"
  },
  AvgDialog_118951_Content_9 = {
    Text = "Você não quer tentar assar o bolo que você costuma comer?"
  },
  AvgDialog_118952_Content_1 = {
    Text = "Nascimento do Divino em sete dias"
  },
  AvgDialog_118952_Content_10 = {
    Text = "Eu oro a Deus por respostas."
  },
  AvgDialog_118952_Content_11 = {
    Text = "Eu pergunto sobre o futuro do Reino Divino, pergunto sobre a conexão entre Ele e eu, pergunto tudo o que quero saber e tudo o que Miryam tenta investigar."
  },
  AvgDialog_118952_Content_12 = {
    Text = "Deus ficou em silêncio."
  },
  AvgDialog_118952_Content_13 = {
    Text = "<color=#E6E6E6>O quinto dia do nascimento de Deus</color>"
  },
  AvgDialog_118952_Content_14 = {
    Text = "Miryam pergunta sobre o resultado de encontrar Deus."
  },
  AvgDialog_118952_Content_15 = {
    Text = "Em um momento de desespero, eu inventei a resposta de Deus, \"O Reino Divino está prestes a emergir\"."
  },
  AvgDialog_118952_Content_16 = {
    Text = "Ela perguntou repetidamente sobre o tempo, e eu só pude responder \"O momento da posição correta das estrelas\"."
  },
  AvgDialog_118952_Content_17 = {
    Text = "Miryam estava em êxtase, uma expressão de alegria que eu nunca havia visto antes, nem quando lhe dei a escultura de madeira, nem quando fiz a Concepção do Feto Sagrado."
  },
  AvgDialog_118952_Content_18 = {
    Text = "<color=#E1E1E1>O sexto dia do nascimento de Deus.</color>"
  },
  AvgDialog_118952_Content_19 = {
    Text = "Miryam perguntou onde ficava Lemuria, e eu só consegui responder de forma confusa, enquanto o olhar dela estava cheio de ceticismo."
  },
  AvgDialog_118952_Content_2 = {
    Text = "Primeiro dia do nascimento de Deus"
  },
  AvgDialog_118952_Content_20 = {
    Text = "Ela já viu os deuses que ainda não morreram, minha mentira pode não funcionar."
  },
  AvgDialog_118952_Content_21 = {
    Text = "<Shake:Deus, por favor, me salve, mesmo que seja uma palavra, responda à minha oração.>"
  },
  AvgDialog_118952_Content_22 = {
    Text = "<Red:O Sétimo Dia do Nascimento Divino>"
  },
  AvgDialog_118952_Content_23 = {
    Text = "Deus está morto. Deus nunca nasceu."
  },
  AvgDialog_118952_Content_24 = {
    Text = "Deitado em meu peito está apenas uma imagem hipócrita, um bloco de carne e sangue, chamado erroneamente de <Yellow:\"Deus\">."
  },
  AvgDialog_118952_Content_25 = {
    Text = "Miryam nunca amou ninguém. Nunca se importou com ninguém."
  },
  AvgDialog_118952_Content_26 = {
    Text = "Após assumir o poder da Mãe Divina, eu li todos os registros dos Marchadores de Mares."
  },
  AvgDialog_118952_Content_27 = {
    Text = "A cada sessenta anos, ao longo de milhares de anos, ocorre um momento de alinhamento das estrelas."
  },
  AvgDialog_118952_Content_28 = {
    Text = "O corpo materno sacrificado, não sou o primeiro, nem serei o último."
  },
  AvgDialog_118952_Content_29 = {
    Text = "Quero sobreviver, quero permanecer..."
  },
  AvgDialog_118952_Content_3 = {
    Text = "O embrião divino nasce dentro de um corpo carbonizado."
  },
  AvgDialog_118952_Content_30 = {
    Text = "Então, temos que matar aquele..."
  },
  AvgDialog_118952_Content_31 = {
    Text = "Eu fraco e ingênuo..."
  },
  AvgDialog_118952_Content_4 = {
    Text = "Estou exausto por ter minha espiritualidade drenada, mas os rostos de todos estão radiantes de fervor e alegria."
  },
  AvgDialog_118952_Content_5 = {
    Text = "<color=#F7F7F7>Segundo dia do nascimento de Deus</color>"
  },
  AvgDialog_118952_Content_6 = {
    Text = "Eu batizo o Feto Sagrado. Ele está com os olhos fechados, dormindo no manto."
  },
  AvgDialog_118952_Content_7 = {
    Text = "<color=#F2F2F2>O terceiro dia do nascimento divino</color>"
  },
  AvgDialog_118952_Content_8 = {
    Text = "O Feto Sagrado ainda não abriu os olhos. Eu posso sentir seu batimento cardíaco, como se estivesse pulsando diante do meu peito."
  },
  AvgDialog_118952_Content_9 = {
    Text = "<color=#F0F0F0>Quarto dia do nascimento de Deus</color>"
  },
  AvgDialog_118953_Content_1 = {
    Text = "O véu no céu balança e se agita, como se fosse uma tempestade em um pequeno mundo."
  },
  AvgDialog_118953_Content_10 = {
    Text = "O vento e as nuvens, o céu nublado e sombrio começou a mudar."
  },
  AvgDialog_118953_Content_11 = {
    Text = "sol no céu……"
  },
  AvgDialog_118953_Content_12 = {
    Text = "A falsa luz se dissipa, sob o céu distante, o véu negro que obscurece o céu flutua suavemente com a respiração."
  },
  AvgDialog_118953_Content_13 = {
    Text = "Isso é um sol negro."
  },
  AvgDialog_118953_Content_2 = {
    Text = "Uma brisa suave que passa levanta o véu negro que obscurece seu rosto, e por baixo dele, há um par de olhos lacrimejantes que já secaram."
  },
  AvgDialog_118953_Content_3 = {
    Text = "Há vulnerabilidades!"
  },
  AvgDialog_118953_Content_4 = {Text = "Oh!"},
  AvgDialog_118953_Content_6 = {
    Text = "No instante em que o céu se abalou, a lâmina serrilhada cortou decisivamente em direção à fenda ondulante."
  },
  AvgDialog_118953_Content_7 = {
    Text = "A estátua de marfim explodiu em uma intensa luz branca, como uma resistência desesperada."
  },
  AvgDialog_118953_Content_8 = {
    Text = "Após alguns segundos, a luz branca apagou-se de repente, e a estátua de marfim quebrou-se, fazendo cair uma chuva de fragmentos brancos em um raio de vinte centímetros."
  },
  AvgDialog_118953_Content_9 = {Text = "Acabou..."},
  AvgDialog_118954_Content_1 = {
    Text = "Ciclo do Tempo"
  },
  AvgDialog_118954_Content_10 = {
    Text = "Guardião..."
  },
  AvgDialog_118954_Content_11 = {Text = "Ramona!"},
  AvgDialog_118954_Content_12 = {
    Text = "Acalme-se e ouça-me."
  },
  AvgDialog_118954_Content_13 = {
    Text = "Eu vivi incontáveis saltos no tempo, retrocedendo em ciclos."
  },
  AvgDialog_118954_Content_14 = {
    Text = "Portanto, estou muito certo de que o que aconteceu com você não é \"Ciclo do Tempo\"."
  },
  AvgDialog_118954_Content_15 = {
    Text = "O tempo que você viveu ainda flui naturalmente."
  },
  AvgDialog_118954_Content_16 = {
    Text = "Não há \"Ciclo do Tempo\"…"
  },
  AvgDialog_118954_Content_17 = {
    Text = "Então, as aparições estranhas que encontro a cada despertar, o cruzeiro afundando e recomeçando, a menina que morreu ressuscitando sem nenhum dano..."
  },
  AvgDialog_118954_Content_18 = {
    Text = "Por quê afinal?"
  },
  AvgDialog_118954_Content_19 = {
    Text = "Não posso responder a você."
  },
  AvgDialog_118954_Content_2 = {
    Text = "Você percebe que está sonhando."
  },
  AvgDialog_118954_Content_20 = {
    Text = "E aquele sol no céu…"
  },
  AvgDialog_118954_Content_21 = {
    Text = "Ramona não disse mais nada. Ela também não sabia a resposta para a pergunta."
  },
  AvgDialog_118954_Content_22 = {
    Text = "A superfície da água começou a se agitar, sua sombra começou a balançar a partir da borda, eventualmente se transformando em fragmentos de memória impossíveis de serem capturados, dispersando-se nos reflexos cintilantes."
  },
  AvgDialog_118954_Content_23 = {
    Text = "Queimando. Dor. As chamas lambem cada centímetro da sua pele."
  },
  AvgDialog_118954_Content_24 = {
    Text = "As extremidades nervosas se encolhem devido à dor aguda, carbonizando-se pela desidratação.\n Você se torna muito leve, leve o suficiente para se transformar em ossos carbonizados."
  },
  AvgDialog_118954_Content_25 = {
    Text = "Você tosse violentamente."
  },
  AvgDialog_118954_Content_26 = {
    Text = "Você está acordado?"
  },
  AvgDialog_118954_Content_27 = {
    Text = "<Shake:... mais uma vez... ciclo?>"
  },
  AvgDialog_118954_Content_28 = {
    Text = "Se você já estiver recuperado, eu vou começar a preparar o ritual."
  },
  AvgDialog_118954_Content_29 = {
    Text = "Não vá, espere um momento, Murphy..."
  },
  AvgDialog_118954_Content_3 = {
    Text = "Os sonhos são a concretização dos desejos e medos internos, e o domínio dos sonhos é um conjunto de ilhas isoladas flutuando no vazio."
  },
  AvgDialog_118954_Content_30 = {
    Text = "Eles... e os outros?"
  },
  AvgDialog_118954_Content_31 = {
    Text = "Murphy respirou fundo e, em seguida, exalou longamente."
  },
  AvgDialog_118954_Content_32 = {
    Text = "Cada um tem suas próprias coisas para fazer. Descanse bem aqui."
  },
  AvgDialog_118954_Content_33 = {
    Text = "Quando chegar o próximo momento da posição correta das estrelas e este navio atingir Lemuria, tudo ficará bem."
  },
  AvgDialog_118954_Content_34 = {
    Text = "Com um rangido, a porta se fechou.\nVocê foi deixado sozinho na sala de estar."
  },
  AvgDialog_118954_Content_35 = {
    Text = "Não pode parar, você precisa agir."
  },
  AvgDialog_118954_Content_36 = {
    Text = "Depois de passar por três reencarnações, você chegou a alguma conclusão?"
  },
  AvgDialog_118954_Content_37 = {
    Text = "Uma vez que o número de reencarnações é determinado, a informação é muito mais importante do que a fuga."
  },
  AvgDialog_118954_Content_38 = {
    Text = "No primeiro ciclo, eu tive uma compreensão inicial dos Marchadores de mares; embora o terceiro ciclo tenha sido uma derrota amarga, eu consegui ter um entendimento básico sobre os movimentos dos outros a bordo."
  },
  AvgDialog_118954_Content_39 = {
    Text = "O tempo do segundo ciclo, na verdade, foi um desperdício."
  },
  AvgDialog_118954_Content_4 = {
    Text = "Em um sonho caótico, inúmeras lâminas de cores diferentes perfuram seu peito, refletindo as sombras umas das outras como bolhas."
  },
  AvgDialog_118954_Content_40 = {
    Text = "A prioridade é coletar mais informações sobre o Navio Paradis e os Marchadores de mares."
  },
  AvgDialog_118954_Content_41 = {
    Text = "Embora aquela pessoa misteriosa insinue que há um total de seis ciclos..."
  },
  AvgDialog_118954_Content_42 = {
    Text = "Mas você já considerou que, se este for o último ciclo, você pode estar desperdiçando uma oportunidade?"
  },
  AvgDialog_118954_Content_43 = {
    Text = "Se agora é o último ciclo..."
  },
  AvgDialog_118954_Content_44 = {
    Text = "Você balança a cabeça, afastando todas as suposições sombrias."
  },
  AvgDialog_118954_Content_45 = {
    Text = "No sonho que marca o início desta reencarnação, Ramona: Desgastada me forneceu uma informação: <Yellow:ela consegue perceber que o tempo em mim ainda flui sequencialmente>."
  },
  AvgDialog_118954_Content_46 = {
    Text = "E você disse que já passou por eventos cíclicos..."
  },
  AvgDialog_118954_Content_47 = {Text = "!"},
  AvgDialog_118954_Content_48 = {
    Text = "Parece que William, o companheiro mais velho, também entendeu."
  },
  AvgDialog_118954_Content_49 = {
    Text = "Aqui não é \"Ciclo do Tempo\", mas sim \"as mesmas coisas se repetindo\"..."
  },
  AvgDialog_118954_Content_5 = {
    Text = "Você precisa de um método para terminar o sonho."
  },
  AvgDialog_118954_Content_50 = {
    Text = "Em Misaq, frequentemente me vejo forçado a cair em situações semelhantes."
  },
  AvgDialog_118954_Content_51 = {
    Text = "\"Domínio Artificial\"…"
  },
  AvgDialog_118954_Content_52 = {
    Text = "Isso mesmo, aqui provavelmente é um \"domínio artificial\"."
  },
  AvgDialog_118954_Content_53 = {
    Text = "O domínio artificial é apenas um meio de informação, o nosso eu real pode estar sendo levado por ventos e tempestades, girando no ar."
  },
  AvgDialog_118954_Content_54 = {
    Text = "Como foi criado este domínio artificial? Por que o domínio continua reiniciando? Qual é o gatilho para seu término?"
  },
  AvgDialog_118954_Content_55 = {
    Text = "Sem entender tudo isso, nossas tentativas no domínio são apenas uma luta contra o muro."
  },
  AvgDialog_118954_Content_56 = {
    Text = "Racionalidade. Há trezentos anos, a racionalidade tem ajudado Misaq a combater a loucura chamada Dissolução."
  },
  AvgDialog_118954_Content_57 = {
    Text = "Acredito que William, o companheiro mais velho, também já percebeu que, nos últimos dias, o sol que estamos contemplando não é o sol negro após a dispersão da névoa, mas sim o sol genuíno do mundo normal."
  },
  AvgDialog_118954_Content_58 = {
    Text = "O tempo de nascimento do domínio é antes da chegada da névoa negra ao mundo."
  },
  AvgDialog_118954_Content_59 = {Text = "..."},
  AvgDialog_118954_Content_6 = {
    Text = "Como o tecelão do destino, devo permanecer em silêncio e não posso revelar a verdade."
  },
  AvgDialog_118954_Content_60 = {
    Text = "Eu falei algo errado? Por que está me olhando assim?"
  },
  AvgDialog_118954_Content_61 = {
    Text = "…não, eu apenas pensei de repente em quando estava em Misaq, naquela época em que saía para missões, você e Ramona sempre estavam ao meu lado, liberando ao máximo minha mente."
  },
  AvgDialog_118954_Content_62 = {
    Text = "Pensar é uma parte indispensável da investigação."
  },
  AvgDialog_118954_Content_63 = {
    Text = "Então, William, o companheiro mais velho, quem você acha que é o dono do domínio?"
  },
  AvgDialog_118954_Content_64 = {
    Text = "Com base nos princípios de formação do domínio e nas informações conhecidas, eu estimo preliminarmente que o domínio pertence a Miryam ou Faros."
  },
  AvgDialog_118954_Content_65 = {
    Text = "O <Yellow:\"núcleo\"> do Domínio é o \"Ritual de Invocação\", rastrear o paradeiro de Lemuria deve ser a obsessão do mestre do domínio."
  },
  AvgDialog_118954_Content_66 = {
    Text = "E de acordo com os registros da Sona-Nyl, o objetivo de Goliath é a força, a obsessão de Caecus é a linhagem, apenas Miryam e Faros anseiam pela glória do Reino Divino."
  },
  AvgDialog_118954_Content_67 = {
    Text = "Em seguida, localize a dona do domínio, e depois?"
  },
  AvgDialog_118954_Content_68 = {
    Text = "Quando o mestre do domínio começa a duvidar da causa do domínio, fendas aparecerão, nas quais a \"catástrofe\" se manifestará."
  },
  AvgDialog_118954_Content_69 = {
    Text = "No entanto, uma vez que se trata de um domínio artificial, a segurança do nosso corpo pode ser garantida."
  },
  AvgDialog_118954_Content_7 = {
    Text = "Portanto, eu te trouxe a pessoa que pode oferecer uma revelação."
  },
  AvgDialog_118954_Content_70 = {
    Text = "Não subestime. Sem mencionar que o domínio artificial ainda está apenas em nossas suposições…"
  },
  AvgDialog_118954_Content_71 = {
    Text = "No ano 306 da Aluvião, o Investigador Jude Blight quebrou a perna direita ao pisar em uma armadilha de caçador no interior do Domínio. Ao retornar à realidade, sua perna direita também começou a necrosar gradualmente."
  },
  AvgDialog_118954_Content_72 = {
    Text = "A forma como o domínio afeta a realidade ainda é incerta, mas ser cauteloso nunca é demais."
  },
  AvgDialog_118954_Content_73 = {Text = "Entendido."},
  AvgDialog_118954_Content_74 = {
    Text = "Depois do ritual, vou lidar com Miryam, e Faros ficará com você."
  },
  AvgDialog_118954_Content_75 = {
    Text = "Que a Chave de prata ilumine o meu caminho."
  },
  AvgDialog_118954_Content_76 = {
    Text = "O tom familiar fez você hesitar por um momento, mas logo apareceu um sorriso sincero."
  },
  AvgDialog_118954_Content_77 = {
    Text = "Que a Chave de Prata nos guie"
  },
  AvgDialog_118954_Content_78 = {
    Text = "Uma mulher sábia ocupa solitariamente um canto da cabine do capitão, a luz acima de sua cabeça pisca imperceptivelmente com a respiração."
  },
  AvgDialog_118954_Content_79 = {Text = "Faros…"},
  AvgDialog_118954_Content_8 = {
    Text = "Na reflexão ondulante do sonho, aparece uma figura ereta."
  },
  AvgDialog_118954_Content_80 = {
    Text = "No momento em que você abriu a boca, parou de repente. Você se esforçou para recordar as informações relacionadas a Faros e só então percebeu que havia poucos registros sobre ela em Misaq."
  },
  AvgDialog_118954_Content_81 = {
    Text = "Ela anseia por voltar ao Reino Divino, ela leva os viajantes para o caminho errado."
  },
  AvgDialog_118954_Content_82 = {
    Text = "Além disso, os outros arquivos estão em branco."
  },
  AvgDialog_118954_Content_83 = {
    Text = "O que houve? Pelo seu jeito, você está confuso?"
  },
  AvgDialog_118954_Content_84 = {
    Text = "Talvez... eu possa te dar algumas dicas?"
  },
  AvgDialog_118954_Content_85 = {
    Text = "Receio que..."
  },
  AvgDialog_118954_Content_86 = {
    Text = "Eu sei quem é o dono do domínio."
  },
  AvgDialog_118954_Content_9 = {
    Text = "A sombra oscila, fragmenta-se e se reúne, gradualmente se estabilizando na fria e familiar face de sua memória."
  },
  AvgDialog_118955_Content_1 = {Text = "Estranho"},
  AvgDialog_118955_Content_10 = {Text = "William..."},
  AvgDialog_118955_Content_11 = {
    Text = "Mas você não deve ficar aqui, ele passou por aqui durante inúmeras noites e dias, apenas encontrando o dono do sonho você poderá finalizar isso."
  },
  AvgDialog_118955_Content_12 = {
    Text = "No fim do navio, você encontrou uma menina."
  },
  AvgDialog_118955_Content_13 = {
    Text = "Incontáveis Marchadores de mares de manto negro estavam deitados desordenadamente ao seu redor, enquanto ela se apoiava silenciosamente no altar, segurando em suas mãos um punhado de carne em decomposição, carmesim e fedorenta."
  },
  AvgDialog_118955_Content_14 = {Text = "Murphy..."},
  AvgDialog_118955_Content_15 = {
    Text = "Como você prometeu, você chegou."
  },
  AvgDialog_118955_Content_16 = {
    Text = "O dono do domínio dos sonhos é você."
  },
  AvgDialog_118955_Content_17 = {
    Text = "Sim, tudo neste navio é um sonho. Tudo o que você vê agora é apenas a \"realidade do sonho\"."
  },
  AvgDialog_118955_Content_18 = {Text = "Por que?"},
  AvgDialog_118955_Content_19 = {
    Text = "Por que criar um domínio de sonho assim? Ou por que me tornar eu mesmo agora?"
  },
  AvgDialog_118955_Content_2 = {
    Text = "Cof, cof, hehe…"
  },
  AvgDialog_118955_Content_20 = {
    Text = "Era um dia muito distante atrás."
  },
  AvgDialog_118955_Content_21 = {
    Text = "Uma pequena figura atravessa a neve."
  },
  AvgDialog_118955_Content_22 = {
    Text = "Huff... Huff..."
  },
  AvgDialog_118955_Content_23 = {
    Text = "Desde que chegou à Antártica, Murphy adquiriu uma liberdade absurda."
  },
  AvgDialog_118955_Content_24 = {
    Text = "Ela pode ir a qualquer lugar sozinha. Mas não importa para onde vá, ao olhar ao redor, só há um campo de neve pálido."
  },
  AvgDialog_118955_Content_25 = {
    Text = "Nem mesmo vestígios de que os humanos já existiram."
  },
  AvgDialog_118955_Content_26 = {
    Text = "Eu estou... perdido?"
  },
  AvgDialog_118955_Content_27 = {
    Text = "A menina olhou para as pegadas que deixou para trás. No vasto Campo de Neve, uma linha quase reta de passos levava a algum lugar desconhecido."
  },
  AvgDialog_118955_Content_28 = {
    Text = "Não importa, desde que continue a andar para frente, sempre chegará a algum lugar."
  },
  AvgDialog_118955_Content_29 = {
    Text = "A menina contou a comida que tinha consigo, confirmando a maior distância que poderia alcançar economizando nos próximos tempos."
  },
  AvgDialog_118955_Content_3 = {
    Text = "Você tosse com força, tentando expelir a água do mar que invadiu seus pulmões."
  },
  AvgDialog_118955_Content_30 = {
    Text = "Força, Murphy. Esta é uma jornada em direção à liberdade, passar fome não é nada sério."
  },
  AvgDialog_118955_Content_31 = {Text = "..."},
  AvgDialog_118955_Content_32 = {Text = "..."},
  AvgDialog_118955_Content_33 = {
    Text = "Não dá, com essa nevasca, é impossível distinguir o caminho."
  },
  AvgDialog_118955_Content_34 = {
    Text = "Comer ração com água da neve é realmente muito intragável."
  },
  AvgDialog_118955_Content_35 = {
    Text = "Às vezes, ela se abriga em uma caverna de neve e consegue ouvir os uivos da besta. Ela nunca a viu, apenas sabe que é uma espécie de lobo branco."
  },
  AvgDialog_118955_Content_36 = {Text = "Socorro!"},
  AvgDialog_118955_Content_37 = {
    Text = "Murphy, em pânico, saiu correndo da caverna. Aqueles olhos verdes e brilhantes ficaram na caverna, sem a seguir."
  },
  AvgDialog_118955_Content_38 = {
    Text = "Neste desespero, vi uma linha de pegadas."
  },
  AvgDialog_118955_Content_39 = {
    Text = "São pegadas humanas...!"
  },
  AvgDialog_118955_Content_4 = {
    Text = "Mas não consigo tossir nada, apenas os nervos espasmados e a dor ilusória de afogamento permanecem nos pulmões."
  },
  AvgDialog_118955_Content_40 = {
    Text = "Basta haver alguém, há esperança. Eu não hesitei e fui atrás."
  },
  AvgDialog_118955_Content_41 = {Text = "..."},
  AvgDialog_118955_Content_42 = {
    Text = "Logo depois, as pegadas se tornaram duas linhas."
  },
  AvgDialog_118955_Content_43 = {
    Text = "Três Linhas."
  },
  AvgDialog_118955_Content_44 = {
    Text = "As pegadas estão se acumulando, mas o dono das pegadas continua desaparecido."
  },
  AvgDialog_118955_Content_45 = {
    Text = "Eu, exausto demais, finalmente desmaiei."
  },
  AvgDialog_118955_Content_46 = {
    Text = "Depois eu soube que, devido à diferença de comprimento entre os pés esquerdo e direito, cada pessoa tende a se desviar levemente para um determinado lado ao caminhar sem conseguir determinar a direção."
  },
  AvgDialog_118955_Content_47 = {
    Text = "Em outras palavras... naquela época, a minha trajetória a pé era um anel."
  },
  AvgDialog_118955_Content_48 = {
    Text = "Os vestígios que vejo chamados de esperança vêm do meu eu do passado, rumo a um ciclo sem fim."
  },
  AvgDialog_118955_Content_49 = {
    Text = "Por causa de uma leve e quase insignificante inclinação...\n minha vida sempre esteve presa em um ciclo vicioso."
  },
  AvgDialog_118955_Content_5 = {
    Text = "Por que... não deveria ser a última reencarnação?"
  },
  AvgDialog_118955_Content_50 = {
    Text = "O centro daquele anel é chamado de destino."
  },
  AvgDialog_118955_Content_51 = {
    Text = "Este é o ciclo que eu construí, que me aprisiona."
  },
  AvgDialog_118955_Content_52 = {Text = "Ou seja..."},
  AvgDialog_118955_Content_53 = {
    Text = "Desde o momento em que Goliath começou a preparar a rebelião, o tempo parou."
  },
  AvgDialog_118955_Content_54 = {
    Text = "Todos mergulharam em sonhos, começando um ciclo repetitivo de sonhos.\n O ciclo dos sonhos começa com o nascimento do Feto Sagrado e termina com o naufrágio do cruzeiro."
  },
  AvgDialog_118955_Content_55 = {
    Text = "Basta que Goliath não inicie a rebelião, tudo pode ficar bem como antes."
  },
  AvgDialog_118955_Content_56 = {
    Text = "Mas eu já vi Goliath na Necrópole..."
  },
  AvgDialog_118955_Content_57 = {
    Text = "Para manter o reino dos sonhos, de tempos em tempos, eu envio um grupo de pessoas para coletar energia para a estátua de marfim."
  },
  AvgDialog_118955_Content_58 = {
    Text = "Basta voltar ao domínio dos sonhos, eles esquecerão essa experiência e se tornarão cidadãos do domínio dos sonhos."
  },
  AvgDialog_118955_Content_59 = {
    Text = "Infelizmente, desde aquela vez em que você impediu que absorvêssemos energia da Necrópole, o domínio dos sonhos tem se tornado cada vez mais instável."
  },
  AvgDialog_118955_Content_6 = {
    Text = "Você olha ao redor, e o convés amplo está vazio, sem aranhas roxas e sem os crentes do Reino Marinho ao seu redor."
  },
  AvgDialog_118955_Content_60 = {
    Text = "Por que você quer que eu o encontre?"
  },
  AvgDialog_118955_Content_61 = {
    Text = "Eu originalmente te chamei, na esperança de eliminar todos os fatores instáveis, estrangulando você neste domínio dos sonhos..."
  },
  AvgDialog_118955_Content_62 = {
    Text = "Apenas antes disso, meu Núcleo de prata parecia ressoar com sua Chave de Prata, conectei-me ao seu sonho, à sua memória."
  },
  AvgDialog_118955_Content_63 = {
    Text = "Eu vi outra possibilidade em um sonho... outra versão de mim mesmo."
  },
  AvgDialog_118955_Content_64 = {
    Text = "Eu a vi competindo com os colegas na aula de escultura;"
  },
  AvgDialog_118955_Content_65 = {
    Text = "Eu a vi brigando com um gato de rua embaixo da fonte;"
  },
  AvgDialog_118955_Content_66 = {
    Text = "Eu a vi sendo convencida pelos amigos a vestir uma saia de pequena demoninha, carregando uma lanterna de abóbora e distribuindo doces de porta em porta..."
  },
  AvgDialog_118955_Content_67 = {
    Text = "No mundo onde o Feto Sagrado ainda não nasceu, ela realmente está... muito feliz."
  },
  AvgDialog_118955_Content_68 = {
    Text = "Invejável, que causa inveja."
  },
  AvgDialog_118955_Content_69 = {
    Text = "também faz querer ser."
  },
  AvgDialog_118955_Content_7 = {
    Text = "Você está fugindo por aí, procurando."
  },
  AvgDialog_118955_Content_70 = {
    Text = "<Amarelo:%player%>, até te encontrar, eu não sabia que ainda existia um modo de vida tão simples e feliz no mundo..."
  },
  AvgDialog_118955_Content_71 = {
    Text = "Não preciso da coroa de vaidade da Mãe Divina, não preciso da honra venerada por todos, não preciso enfrentar dia após dia a cara irritante dos fiéis..."
  },
  AvgDialog_118955_Content_72 = {
    Text = "Que responsabilidade, que legado, por que tantas pessoas sacrificam suas vidas por um monte de carne podre?"
  },
  AvgDialog_118955_Content_73 = {
    Text = "Você mantém o silêncio, você só pode ficar em silêncio."
  },
  AvgDialog_118955_Content_74 = {
    Text = "Murphy está negando seu passado."
  },
  AvgDialog_118955_Content_75 = {
    Text = "Tenho uma última pergunta para você."
  },
  AvgDialog_118955_Content_76 = {
    Text = "No seu mundo, você também a ensina a fazer bolinhos assim?"
  },
  AvgDialog_118955_Content_77 = {
    Text = "Nesse mundo... não sou apenas eu, haverá muitas pessoas dispostas a ajudar você, a acompanhar você em qualquer coisa que você queira fazer, mesmo que seja caprichosa."
  },
  AvgDialog_118955_Content_78 = {
    Text = "Murphy, porque você ama o mundo, ama a todos."
  },
  AvgDialog_118955_Content_79 = {
    Text = "Por sua causa, você abriu seu coração, e todos testemunharam com seus próprios olhos."
  },
  AvgDialog_118955_Content_8 = {
    Text = "Sono, sono, todos estão dormindo."
  },
  AvgDialog_118955_Content_80 = {
    Text = "Aquele coração pulsante."
  },
  AvgDialog_118955_Content_81 = {
    Text = "Murphy sorriu, com um sorriso tão brilhante quanto suas memórias passadas."
  },
  AvgDialog_118955_Content_82 = {
    Text = "Você sabia? Este navio é um sonho."
  },
  AvgDialog_118955_Content_83 = {
    Text = "Eu pensei que era um lindo sonho...\nEu sou a Mãe dos Deuses, e aquele aglomerado de carne se chama divindade."
  },
  AvgDialog_118955_Content_84 = {
    Text = "Dia após dia, vivo abraçado ao medo, temendo e sofrendo."
  },
  AvgDialog_118955_Content_85 = {
    Text = "Na verdade, este sonho não é um sonho bonito, mas um pesadelo em que estou enredado, sem nem perceber, em meio ao pânico."
  },
  AvgDialog_118955_Content_86 = {
    Text = "Então, agora, revele o véu das mentiras e deixe o sonho despertar."
  },
  AvgDialog_118955_Content_9 = {
    Text = "William está deitado no convés, seu uniforme está manchado e em péssimo estado, como se tivesse sido repetidamente espancado pela tempestade e pelo sol ardente, com graxa e sal formando um mapa manchado."
  },
  AvgDialog_118956_Content_1 = {
    Text = "Vocês recuam enquanto lutam, do compartimento de máquinas para o corredor, do corredor para o convés, até que atrás de vocês só há uma cerca entre vocês e o infinito oceano."
  },
  AvgDialog_118956_Content_10 = {
    Text = "O gigante de força descomunal deslizou rapidamente para trás sob o seu impacto, prestes a colidir violentamente com a placa do compartimento."
  },
  AvgDialog_118956_Content_11 = {
    Text = "Num piscar de olhos, ele cravou a lâmina gigante diretamente no chão, conseguindo apenas manter sua posição."
  },
  AvgDialog_118956_Content_12 = {
    Text = "Você, garoto, melhorou bastante desde a última vez que nos encontramos."
  },
  AvgDialog_118956_Content_13 = {
    Text = "Não, não é assim."
  },
  AvgDialog_118956_Content_14 = {
    Text = "Não é que você ficou mais forte, é que Goliath ficou mais fraco."
  },
  AvgDialog_118956_Content_15 = {
    Text = "Mesmo com Faros ao seu lado, a força de Goliath está muito aquém da última vez que você se encontrou com ele."
  },
  AvgDialog_118956_Content_16 = {
    Text = "Cada golpe é leve, nada semelhante à força brutal de um gigante."
  },
  AvgDialog_118956_Content_17 = {
    Text = "Goliath, desde o início da luta percebi a força não humana que existe em você... está diminuindo rapidamente."
  },
  AvgDialog_118956_Content_18 = {
    Text = "Hum, mesmo que eu fique dez vezes mais fraco, ainda não sou um oponente que você, esse garotinho, possa enfrentar."
  },
  AvgDialog_118956_Content_19 = {
    Text = "Tem a ver com a aparição de Faróis aqui?"
  },
  AvgDialog_118956_Content_2 = {
    Text = "Você realmente consegue aguentar... surpreendentemente chegou até aqui."
  },
  AvgDialog_118956_Content_20 = {
    Text = "Mais adiante, isso tem a ver com a anomalia neste navio?"
  },
  AvgDialog_118956_Content_21 = {
    Text = "Você está ansioso para executar o que chamam de arranjo por causa da sua própria fraqueza?"
  },
  AvgDialog_118956_Content_22 = {
    Text = "Hum, coisas que você não deveria saber, não importa o quanto você pergunte, não pense que vai conseguir tirar uma palavra de mim."
  },
  AvgDialog_118956_Content_23 = {
    Text = "Se nossos objetivos são os mesmos, eu não sou necessariamente uma opção que você precisa excluir."
  },
  AvgDialog_118956_Content_24 = {
    Text = "Cada um dê um passo para trás, eu não vou interferir na sua intenção de traição aos Marchadores de mares, e você também não me complique."
  },
  AvgDialog_118956_Content_25 = {
    Text = "Goliath ainda não respondeu, e duas sombras de serpentes venenosas dispararam em direção a vocês como um raio!"
  },
  AvgDialog_118956_Content_27 = {
    Text = "Vocês recuaram de repente, a sombra da serpente explodiu no convés, abrindo instantaneamente dois buracos horríveis que exalavam fumaça preta."
  },
  AvgDialog_118956_Content_28 = {
    Text = "Dois traidores sem gratidão, aqui não há espaço para vocês chegarem a um acordo."
  },
  AvgDialog_118956_Content_29 = {
    Text = "Quanto aos estrangeiros... Ao fugir, você pareceu esquecer algo crucial."
  },
  AvgDialog_118956_Content_3 = {
    Text = "No entanto, você já não tem para onde recuar."
  },
  AvgDialog_118956_Content_30 = {
    Text = "A estátua de marfim flutua nas mãos de Miryam.\nEla ora com devoção, e as palavras de profanação escorrem de sua boca como vermes."
  },
  AvgDialog_118956_Content_31 = {
    Text = "<Change>Seus corpos e almas já deveriam pertencer à sombra do abismo."
  },
  AvgDialog_118956_Content_32 = {
    Text = "Espera, Miryam, não —"
  },
  AvgDialog_118956_Content_33 = {
    Text = "Desculpe, Mãe Divina, eu devo aplicar a punição a esses profanadores em seu nome."
  },
  AvgDialog_118956_Content_34 = {
    Text = "A estátua de marfim emitiu um grito silencioso, e inúmeras linhas prateadas se espalharam, como seres vivos estranhos, parasitando o coração dos cidadãos do Reino do Mar."
  },
  AvgDialog_118956_Content_35 = {
    Text = "O que é isso... mulher louca, o que você está fazendo?!"
  },
  AvgDialog_118956_Content_36 = {
    Text = "O que estou fazendo? Naturalmente, estou concedendo a vocês a misericórdia divina, a compaixão divina e o supremo poder divino."
  },
  AvgDialog_118956_Content_37 = {
    Text = "Fios se entrelaçam firmemente, apertando-se brutalmente em um instante —"
  },
  AvgDialog_118956_Content_38 = {
    Text = "Senhor Gulias... eu sinto que não consigo respirar..."
  },
  AvgDialog_118956_Content_39 = {
    Text = "<Shake:Ah ah... Eu senti... os canais divinos... Eu toquei... a alma Dele...>"
  },
  AvgDialog_118956_Content_4 = {
    Text = "Você respira fundo, acalma-se e se prepara para enfrentar a lâmina gigante que Goliath balança novamente."
  },
  AvgDialog_118956_Content_40 = {Text = "Pah."},
  AvgDialog_118956_Content_41 = {
    Text = "O coração explode em sequência, e a imundície carmesim se espalha no convés em ondas de flores de sangue."
  },
  AvgDialog_118956_Content_42 = {
    Text = "Não importa quanto tempo passe, não se pode mudar a tolice dos descrentes."
  },
  AvgDialog_118956_Content_43 = {
    Text = "<Shake:Então, que seja com o seu sangue e espírito, forjando a escada para o Reino Divino!>"
  },
  AvgDialog_118956_Content_44 = {
    Text = "<Shake:Impeça-a... <Big:Venha comigo, impeça-a!>>"
  },
  AvgDialog_118956_Content_6 = {
    Text = "O caminho sem volta em seus olhos é, na verdade, o campo de batalha que escolhi para você."
  },
  AvgDialog_118956_Content_7 = {
    Text = "Você tem desperdiçado força, e agora, é a minha hora de contra-atacar."
  },
  AvgDialog_118956_Content_8 = {
    Text = "A luz prateada irrompeu de repente, trazendo uma força avassaladora, pressionando em direção a Goliath. \n Goliath imediatamente levantou a espada para resistir, mas era tarde demais."
  },
  AvgDialog_118957_Content_1 = {Text = "Epílogo"},
  AvgDialog_118957_Content_10 = {
    Text = "Que sonho longo."
  },
  AvgDialog_118957_Content_11 = {
    Text = "A morte, a traição, o afundamento; quanto mais você deseja reter algo, mais inevitavelmente escorrega entre os dedos."
  },
  AvgDialog_118957_Content_12 = {
    Text = "Talvez este seja o destino. Irreversível, não é necessário forçar a permanência."
  },
  AvgDialog_118957_Content_13 = {
    Text = "Solte-se logo, e talvez você encontre companheiros mais alinhados com seus ideais."
  },
  AvgDialog_118957_Content_14 = {
    Text = "Por exemplo... Misaq?"
  },
  AvgDialog_118957_Content_15 = {
    Text = "Parece que o pessoal de Misaq é muito bom em ser tolerante... ou em suavizar os temperamentos de todos."
  },
  AvgDialog_118957_Content_16 = {
    Text = "Lembro-me de uma vez em que Murphy insistiu em experimentar todos os sabores de doces e acabou com dor de dente."
  },
  AvgDialog_118957_Content_17 = {
    Text = "Sylvia finalmente fez com que Jenkin roubasse todo o estoque da dama."
  },
  AvgDialog_118957_Content_18 = {
    Text = "Pfft. E depois?"
  },
  AvgDialog_118957_Content_19 = {
    Text = "Então ela começou a fazer uma grande operação para pegar ladrões, completamente esquecendo dos doces."
  },
  AvgDialog_118957_Content_2 = {
    Text = "O Navio Paradis já atracou, e a seguir…"
  },
  AvgDialog_118957_Content_20 = {
    Text = "Mais uma vez..."
  },
  AvgDialog_118957_Content_21 = {
    Text = "Certo, até quando você quer que eu sinta inveja dela?"
  },
  AvgDialog_118957_Content_22 = {
    Text = "Quando voltarmos para Misaq, tudo isso também será seu."
  },
  AvgDialog_118957_Content_23 = {
    Text = "Então, que possamos nos encontrar um dia em Misaq."
  },
  AvgDialog_118957_Content_24 = {
    Text = "Murphy abriu as mãos em direção ao céu distante, como se quisesse tocar o sol no alto."
  },
  AvgDialog_118957_Content_25 = {
    Text = "A sombra negra e arredondada rolava entre os dedos dela."
  },
  AvgDialog_118957_Content_26 = {
    Text = "Há uma coisa que preciso te contar."
  },
  AvgDialog_118957_Content_27 = {
    Text = "O olhar de Murphy te atravessou."
  },
  AvgDialog_118957_Content_28 = {
    Text = "Este mundo já está destruído e irremediável, coberto por um desespero mais profundo do que o ciclo que experimentei."
  },
  AvgDialog_118957_Content_29 = {
    Text = "Se possível, posso tentar te levar de volta."
  },
  AvgDialog_118957_Content_3 = {
    Text = "Eles já sabem tudo sobre os deuses deste mundo, e em breve farão sua própria escolha."
  },
  AvgDialog_118957_Content_30 = {
    Text = "Mandar-me... voltar?"
  },
  AvgDialog_118957_Content_31 = {
    Text = "Você sabe como atravessar dois mundos?"
  },
  AvgDialog_118957_Content_32 = {
    Text = "Não posso dizer que sei, mas basta conhecer a essência deste mundo para compreender os nós que conectam o mundo."
  },
  AvgDialog_118957_Content_33 = {
    Text = "Este navio é um sonho, mas quando o véu da mentira se levanta..."
  },
  AvgDialog_118957_Content_34 = {
    Text = "O mundo inteiro também é o sonho de alguém, apenas este sonho é maior, mais ilusório e mais distante..."
  },
  AvgDialog_118957_Content_35 = {
    Text = "Até o sol, a lua e as estrelas são fruto de Sua imaginação, apenas os seres que se entrelaçam com Seu espírito podem..."
  },
  AvgDialog_118957_Content_36 = {
    Text = "Sol, lua e estrelas..."
  },
  AvgDialog_118957_Content_37 = {
    Text = "O véu negro tremula, formando um caminho sinuoso que se estende até o céu."
  },
  AvgDialog_118957_Content_38 = {
    Text = "Vá, volte, retorne ao mundo que pertence a você! Não se prenda a este mundo que já está morto."
  },
  AvgDialog_118957_Content_39 = {
    Text = "E você, Murphy?"
  },
  AvgDialog_118957_Content_4 = {
    Text = "Na minha opinião, Miryam e Faros devem recomeçar a navegação em busca da localização de Lemuria."
  },
  AvgDialog_118957_Content_40 = {
    Text = "Você reprimiu o impulso de imediatamente pisar no caminho de seda e se virou para perguntar a Murphy, que estava em silêncio."
  },
  AvgDialog_118957_Content_41 = {
    Text = "Ah, quem sabe? Este mundo é um mundo que já foi destruído."
  },
  AvgDialog_118957_Content_42 = {
    Text = "Aceite isso. Talvez um dia você possa sentir meu núcleo de prata naquele mundo."
  },
  AvgDialog_118957_Content_43 = {
    Text = "Uma joia feita de uma gota de sangue cai na sua mão, vinda da estranha ferida que atravessa seu peito."
  },
  AvgDialog_118957_Content_44 = {
    Text = "Naquele momento, não sei qual \"eu\" você invocou de qual época."
  },
  AvgDialog_118957_Content_45 = {
    Text = "Mas, quando você me chamar, lembre-se de como eu sou agora..."
  },
  AvgDialog_118957_Content_46 = {
    Text = "Seu nascimento é ilusório... moldar sonhos é tudo ilusão..."
  },
  AvgDialog_118957_Content_47 = {
    Text = "Então me chame de... \"<Yellow:Murphy: Fauxborn>\"!"
  },
  AvgDialog_118957_Content_48 = {
    Text = "Você caminha lentamente pelo caminho de seda, inúmeros pensamentos passam rapidamente pela sua mente."
  },
  AvgDialog_118957_Content_49 = {
    Text = "A jornada contra a dissolução, dois mundos entrelaçados por pesadelos negros, muitos rostos semelhantes ou idênticos se sobrepõem..."
  },
  AvgDialog_118957_Content_5 = {
    Text = "Goliath e Caecus provavelmente partirão, mesmo em um mundo que se torna cada vez mais desolado, eles terão suas próprias jornadas."
  },
  AvgDialog_118957_Content_50 = {
    Text = "duas bonecas…"
  },
  AvgDialog_118957_Content_51 = {
    Text = "dois Clementines…"
  },
  AvgDialog_118957_Content_52 = {
    Text = "dois Murphys..."
  },
  AvgDialog_118957_Content_53 = {
    Text = "Finalmente parou no rosto sorridente de Ramona."
  },
  AvgDialog_118957_Content_54 = {
    Text = "Eu... posso voltar?"
  },
  AvgDialog_118957_Content_55 = {
    Text = "Sonho, você descobre que está a apenas um braço de distância do sol negro, mas não sente nenhum calor."
  },
  AvgDialog_118957_Content_56 = {
    Text = "A escuridão infinita consumiu toda a luz, ansiosa para devorar você por completo."
  },
  AvgDialog_118957_Content_57 = {
    Text = "Ramona... você vai me esperar aqui depois?"
  },
  AvgDialog_118957_Content_58 = {
    Text = "Você fecha os olhos, estende suavemente os dedos e toca o túnel negro."
  },
  AvgDialog_118957_Content_59 = {
    Text = "Se possível, segure minha mão."
  },
  AvgDialog_118957_Content_6 = {
    Text = "Quanto a \"este\" Murphy..."
  },
  AvgDialog_118957_Content_60 = {
    Text = "Debaixo dos seus pés, entre mil sonhos profundos."
  },
  AvgDialog_118957_Content_61 = {
    Text = "Com o sol negro como ponto de partida, o véu negro se desfez camada por camada."
  },
  AvgDialog_118957_Content_62 = {
    Text = "Você cai do alto."
  },
  AvgDialog_118957_Content_63 = {
    Text = "<Yellow:Cair no vórtice chamado \"destino\".>"
  },
  AvgDialog_118957_Content_64 = {
    Text = "Eu vi o que aconteceu com aquela menina em um sonho profundo."
  },
  AvgDialog_118957_Content_65 = {
    Text = "Lamento que eu tenha enviado ela para longe de Lemuria no início, confiando a estátua de marfim a ela em um sonho, não era para que esse fosse o desfecho."
  },
  AvgDialog_118957_Content_66 = {
    Text = "Não deveria agradecer pela minha intermediação?"
  },
  AvgDialog_118957_Content_67 = {
    Text = "A luz da esperança deste mundo já foi aniquilada, você deve saber, certo?"
  },
  AvgDialog_118957_Content_68 = {
    Text = "A mulher que acaricia a roca não fala, apenas deixa o fio que está em suas mãos se estender sob o céu, entre todas as coisas."
  },
  AvgDialog_118957_Content_69 = {
    Text = "Basta ter uma semente."
  },
  AvgDialog_118957_Content_7 = {
    Text = "Acho que ela deve ter algo a te dizer."
  },
  AvgDialog_118957_Content_70 = {
    Text = "Não importa quanto tempo o silêncio dure, não importa em qual solo esteja, um dia, eventualmente, brotará."
  },
  AvgDialog_118957_Content_71 = {
    Text = "Quanto a mim…"
  },
  AvgDialog_118957_Content_72 = {
    Text = "A mulher abaixou os olhos."
  },
  AvgDialog_118957_Content_73 = {
    Text = "Não sou semeador, não sou cuidador, nem sou colhedor."
  },
  AvgDialog_118957_Content_74 = {
    Text = "Eu estou apenas puxando fios, seguindo a ordem do céu, retratando o Tecelão do Destino."
  },
  AvgDialog_118957_Content_75 = {
    Text = "Eu puxarei os fios da roca para extrair o solo mais adequado para ela."
  },
  AvgDialog_118957_Content_76 = {
    Text = "Vou esperar em silêncio."
  },
  AvgDialog_118957_Content_8 = {
    Text = "Você chegou?"
  },
  AvgDialog_118957_Content_9 = {Text = "Bom."},
  AvgDialog_118958_Content_1 = {Text = "núcleo"},
  AvgDialog_118958_Content_10 = {
    Text = "Eu já me uni a Goliath, mas os bárbaros que só entendem guerra e violência claramente não sabem como cumprir um contrato, muito menos podem guiar para o caminho de Lemúria."
  },
  AvgDialog_118958_Content_11 = {
    Text = "Como? Basta você acenar com a cabeça e eu revelarei a identidade do mestre do domínio para você."
  },
  AvgDialog_118958_Content_12 = {
    Text = "O coração da menina subiu à garganta."
  },
  AvgDialog_118958_Content_13 = {
    Text = "Por favor, permita-me recusar."
  },
  AvgDialog_118958_Content_14 = {
    Text = "Não posso prometer tirar a vida de alguém sem saber quem é a pessoa."
  },
  AvgDialog_118958_Content_15 = {
    Text = "Além disso, uma vez que você já fez tal pedido, o mestre do domínio claramente não está entre você, Goliath e Caecus."
  },
  AvgDialog_118958_Content_16 = {
    Text = "E você já revelou que o poder do sonho está relacionado àquela estátua de marfim."
  },
  AvgDialog_118958_Content_17 = {
    Text = "Então, a única suspeita que resta é ela..."
  },
  AvgDialog_118958_Content_18 = {
    Text = "Seu gosto para escolher o lugar de observação é realmente digno de elogios."
  },
  AvgDialog_118958_Content_19 = {
    Text = "Você puxa a corda, fazendo com que a vela do mastro esconda você e William."
  },
  AvgDialog_118958_Content_2 = {
    Text = "<Shake:Tic tic tic, tic tic tic.>"
  },
  AvgDialog_118958_Content_20 = {
    Text = "Na última cerimônia, percebi que, em comparação com o Sonanir, o Navio Paradis preservou uma estrutura de mastro relativamente antiga."
  },
  AvgDialog_118958_Content_21 = {
    Text = "Equivale a uma torre de observação, que permite ter uma visão panorâmica da situação do cerimonial de navegação."
  },
  AvgDialog_118958_Content_22 = {
    Text = "Quando a cerimônia de navegação começa, Miryam entregará a estátua de marfim a Murphy, que é a única ocasião em que podemos ter acesso à estátua de marfim."
  },
  AvgDialog_118958_Content_23 = {
    Text = "Tire a estátua e parseie, talvez possamos descobrir como desfazer o domínio."
  },
  AvgDialog_118958_Content_24 = {
    Text = "Shh, elas estão vindo."
  },
  AvgDialog_118958_Content_25 = {
    Text = "William deu um tapinha no seu ombro, sinalizando para você olhar para trás."
  },
  AvgDialog_118958_Content_26 = {
    Text = "Preste atenção na localização da estátua de marfim... essa é nossa linha de vida."
  },
  AvgDialog_118958_Content_27 = {
    Text = "Sem diferença alguma da sua memória, a cerimônia de navegação está ocorrendo de maneira ordenada."
  },
  AvgDialog_118958_Content_28 = {
    Text = "Respeitada Mãe Divina, por favor, guie o sangue do Rei Divino, oriente os Marchadores de mares perdidos e mostre-nos o caminho para Lemúria."
  },
  AvgDialog_118958_Content_29 = {
    Text = "Murphy mordeu o lábio e pegou o punhal brilhante das mãos de Miryam."
  },
  AvgDialog_118958_Content_3 = {
    Text = "A menina corre pelo corredor."
  },
  AvgDialog_118958_Content_30 = {
    Text = "Ela levantou a faca — e então não a cravou por muito tempo."
  },
  AvgDialog_118958_Content_31 = {
    Text = "Mãe Divina, você já não havia tomado uma decisão? Lemúria ainda está no fundo do abismo, aguardando sua chegada."
  },
  AvgDialog_118958_Content_32 = {
    Text = "…eu isso…"
  },
  AvgDialog_118958_Content_33 = {
    Text = "A segunda metade da frase foi engolida."
  },
  AvgDialog_118958_Content_34 = {
    Text = "Ela ergueu a estátua de marfim ensanguentada, permitindo que aquele monstro deformado drenasse sua própria essência."
  },
  AvgDialog_118958_Content_35 = {
    Text = "O rio de sangue se espalha pela amurada, seguindo para a esquerda."
  },
  AvgDialog_118958_Content_36 = {
    Text = "Vire! Timoneiro do mar, ouça o oráculo, todo o leme à esquerda!"
  },
  AvgDialog_118958_Content_37 = {
    Text = "O que respondeu a ela foi um som cortante rompendo o ar."
  },
  AvgDialog_118958_Content_38 = {
    Text = "Acho que não precisa."
  },
  AvgDialog_118958_Content_39 = {
    Text = "O arpão afiado, como os dentes afiados de um tubarão gigante, surgiu repentinamente da escuridão da noite, penetrando com precisão a garganta do timoneiro."
  },
  AvgDialog_118958_Content_4 = {
    Text = "Ao passar pela cabine do capitão, uma voz suave entrou em seus ouvidos."
  },
  AvgDialog_118958_Content_40 = {
    Text = "A lâmina pesada riscou o convés, gerando faíscas; o gigante emergiu da escuridão da noite, pisando o crânio do timoneiro e exibindo um sorriso cruel para a bruxa à sua frente."
  },
  AvgDialog_118958_Content_41 = {
    Text = "Atrás dele, os bárbaros vestidos com capas de chuva azul-acinzentadas seguram lâminas afiadas, esperando ansiosamente a ordem para o massacre."
  },
  AvgDialog_118958_Content_42 = {
    Text = "Goliath... você ainda não vai desistir?"
  },
  AvgDialog_118958_Content_43 = {
    Text = "Reúna marinheiros, crie caos... tentando quebrar a calma do Paraíso..."
  },
  AvgDialog_118958_Content_44 = {
    Text = "Sinto muito, eu não sou parte dessa tranquilidade. Desta vez, na próxima, na próxima... os filisteus nunca se contentarão em viver eternamente abaixo dos outros."
  },
  AvgDialog_118958_Content_45 = {
    Text = "Venha, filisteu!"
  },
  AvgDialog_118958_Content_46 = {
    Text = "Na voz maligna, os bárbaros vestidos com capas de óleo seguram lâminas afiadas, emergindo das sombras em grande número."
  },
  AvgDialog_118958_Content_47 = {
    Text = "Um rugido profundo treme de empolgação. Eles aguardam ansiosamente, esperando o momento de reproduzir a glória, aguardando a ordem para massacrar tudo."
  },
  AvgDialog_118958_Content_48 = {
    Text = "<Big:Mate-os!>"
  },
  AvgDialog_118958_Content_49 = {
    Text = "A canção de guerra rude rasgou o céu noturno do mar, enquanto os grupos selvagens balançavam as cordas, atingindo a multidão no convés a uma velocidade difícil de reagir."
  },
  AvgDialog_118958_Content_5 = {
    Text = "Eu sei quem é o mestre do domínio e posso levá-los a ultrapassar as fronteiras do domínio e retornar ao mundo real."
  },
  AvgDialog_118958_Content_50 = {
    Text = "Os filisteus, que viveram durante muito tempo saqueando ao longo da costa, são como tubarões que sentiram o cheiro de sangue, avançando famintos e brutais em direção à sua presa, mordendo os corpos dos inimigos com suas lâminas curvas afiadas como dentes."
  },
  AvgDialog_118958_Content_51 = {
    Text = "Meu senhor, por favor, ouça o clamor dos fiéis... Por favor, traga bênçãos ao seu povo..."
  },
  AvgDialog_118958_Content_52 = {
    Text = "Miryam abriu os braços, e a luz obscura começou a se espalhar gradualmente."
  },
  AvgDialog_118958_Content_53 = {
    Text = "Os Marchadores de Mares vestidos com estranhas capas negras não emitiram som algum, como um grupo de espíritos negros devotados, banhando-se silenciosamente na profunda bênção divina, silenciosamente cravando punhais nos peitos dos inimigos."
  },
  AvgDialog_118958_Content_54 = {
    Text = "O azul-acinzentado e o preto-púrpura, dois grupos claramente distintos lutam até a morte neste purgatório em movimento."
  },
  AvgDialog_118958_Content_55 = {
    Text = "Mate, meus parentes... aqui, reproduza a glória dos filisteus!"
  },
  AvgDialog_118958_Content_56 = {
    Text = "A lâmina gigante cortou impiedosamente a cabeça do Marchador de mares que estava à sua frente, o sangue salgado e fresco jorrando e tingindo a maior parte do rosto de Goliath de carmesim."
  },
  AvgDialog_118958_Content_57 = {
    Text = "Ele lambe o sangue de seu rosto e, iluminado pelos relâmpagos, brandiu a grande lâmina em sua mão, matando cada crença que se interpusesse à sua frente."
  },
  AvgDialog_118958_Content_58 = {
    Text = "O sangue acabou de jorrar do corpo quente, sendo instantaneamente diluído pela chuva torrencial, misturando-se com a água do mar, formando correntes carmesins e escorregadias no convés que balança violentamente."
  },
  AvgDialog_118958_Content_59 = {
    Text = "<Shake:Meu Senhor, ouvi sua ordem. Seus fiéis retornarão ao Reino Divino com você...>"
  },
  AvgDialog_118958_Content_6 = {
    Text = "A menina tentou se manter calma e aliviou os passos."
  },
  AvgDialog_118958_Content_60 = {
    Text = "Ritual, vento, massacre…"
  },
  AvgDialog_118958_Content_61 = {
    Text = "No centro desse caos, sob a sinistra estátua de marfim na proa do barco, Miryam se mantinha firme, sussurrando devotamente durante a tempestade."
  },
  AvgDialog_118958_Content_62 = {
    Text = "Ela ignora o mar de sangue e os corpos ao seu redor, o punhal passa zunindo ao seu lado, as ondas a encharcam completamente, mas ela não percebe."
  },
  AvgDialog_118958_Content_63 = {
    Text = "Que o seu oráculo nos guie, que o seu corpo nos envolva."
  },
  AvgDialog_118958_Content_64 = {
    Text = "Miryam... desista! Não podemos chegar a Lemúria!"
  },
  AvgDialog_118958_Content_65 = {
    Text = "Não... Ele me prometeu, você também ouviu Seu Oráculo, certo?"
  },
  AvgDialog_118958_Content_66 = {
    Text = "Miryam observa o horizonte com devoção."
  },
  AvgDialog_118958_Content_67 = {
    Text = "A tempestade é sua respiração, o trovão é seu tambor de guerra!"
  },
  AvgDialog_118958_Content_68 = {
    Text = "Por favor, guie este cordeiro perdido, <Big:indique a direção para o seu reino!>"
  },
  AvgDialog_118958_Content_69 = {
    Text = "Um relâmpago pálido rasgou o céu, iluminando instantaneamente seus olhos fervorosos e de devoção."
  },
  AvgDialog_118958_Content_7 = {
    Text = "Mas, minha ajuda é condicional."
  },
  AvgDialog_118958_Content_70 = {
    Text = "A menina com véu negro se encolheu silenciosamente em um canto da proa do barco, seu olhar vazio encarando desesperadamente o campo de batalha, como uma boneca de pano jogada em um monte de sucata."
  },
  AvgDialog_118958_Content_71 = {
    Text = "Vamos, desça!"
  },
  AvgDialog_118958_Content_72 = {
    Text = "Eu sou responsável por levar a estátua de marfim!"
  },
  AvgDialog_118958_Content_73 = {
    Text = "Vou aproveitar enquanto eles estão em caos e salvar Murphy!"
  },
  AvgDialog_118958_Content_8 = {
    Text = "Sua condição é...?"
  },
  AvgDialog_118958_Content_9 = {
    Text = "Mate o mestre do domínio, tome a estátua de marfim e entregue o poder do domínio a mim."
  },
  AvgDialog_118959_Content_1 = {
    Text = "Eu matei a mim mesmo, ergui a coroa. Além da liberdade, obtive tudo o que desejava."
  },
  AvgDialog_118959_Content_10 = {
    Text = "Porque você é diferente."
  },
  AvgDialog_118959_Content_11 = {
    Text = "O que eu tenho de diferente delas? Somos apenas ofertas aos seus olhos, apenas ração para essa carne podre."
  },
  AvgDialog_118959_Content_12 = {
    Text = "Murphy segurou o pedaço sujo em suas mãos, com sangue escorrendo abundantemente."
  },
  AvgDialog_118959_Content_13 = {
    Text = "Não, você é diferente delas."
  },
  AvgDialog_118959_Content_14 = {Text = "Porque..."},
  AvgDialog_118959_Content_15 = {
    Text = "Nós juntos, caminhamos juntos."
  },
  AvgDialog_118959_Content_16 = {
    Text = "Lembro do dia em que você implantou o Feto Sagrado em seu peito, você disse que queria comer churros."
  },
  AvgDialog_118959_Content_17 = {
    Text = "Você de repente percebe que está tão delicioso que não é bom para uma pessoa só, e com um pouco de timidez, divide comigo metade."
  },
  AvgDialog_118959_Content_18 = {
    Text = "Depois, o Feto Sagrado começou a crescer, você estava com febre alta incessante, tentamos de tudo para baixar a temperatura, mas no final só pudemos transportá-lo para o frigorífico na Antártica."
  },
  AvgDialog_118959_Content_19 = {
    Text = "Isso nos causou muitos problemas."
  },
  AvgDialog_118959_Content_2 = {
    Text = "Mas eu, que dei à luz a Criança Santa, não recebi a graça da profecia, não consegui guiar o caminho para Lemuria..."
  },
  AvgDialog_118959_Content_20 = {
    Text = "Mesmo em um ambiente tão difícil, você ainda mantém o dever de ser a Mãe Divina."
  },
  AvgDialog_118959_Content_21 = {
    Text = "A maioria dos sacerdotes suporta o frio intenso, acompanhando, esperando e orando no altar da Antártida."
  },
  AvgDialog_118959_Content_22 = {
    Text = "E você não decepcionou as expectativas, tornando-se o primeiro corpo a dar à luz a Criança Santa."
  },
  AvgDialog_118959_Content_23 = {
    Text = "Chegamos juntos naquele momento."
  },
  AvgDialog_118959_Content_24 = {
    Text = "Nós iremos juntos, navegar rumo ao eterno Reino Divino."
  },
  AvgDialog_118959_Content_25 = {
    Text = "Miryam caminhou lentamente e firmemente até Murphy, inclinando-se."
  },
  AvgDialog_118959_Content_26 = {
    Text = "Você é a honrada Mãe Divina, e eu desejo me prostrar eternamente aos seus pés, oferecendo minha devoção ao longo da vida."
  },
  AvgDialog_118959_Content_27 = {
    Text = "Estou disposto a te adorar eternamente, como se fosse aquela \"divindade\"."
  },
  AvgDialog_118959_Content_28 = {
    Text = "Murphy olhou para Miryam com uma expressão de surpresa."
  },
  AvgDialog_118959_Content_29 = {
    Text = "Miryam ajoelha-se parcialmente, segurando as costas da mão dela, e deposita um beijo devoto sobre ela."
  },
  AvgDialog_118959_Content_3 = {
    Text = "Então você fabricou este sonho que nunca termina…"
  },
  AvgDialog_118959_Content_30 = {
    Text = "Volte para o meu lado, tudo bem, \"Mãe Divina\"?"
  },
  AvgDialog_118959_Content_31 = {
    Text = "Murphy abaixou a cabeça. O vento estava calmo, e o pequeno universo nas fendas estava silencioso e tranquilo."
  },
  AvgDialog_118959_Content_32 = {
    Text = "Todas as suas histórias estão relacionadas ao Feto Sagrado. Todos os seus títulos estão ligados à Mãe Divina."
  },
  AvgDialog_118959_Content_33 = {
    Text = "Você ainda não entende... e nunca entenderá..."
  },
  AvgDialog_118959_Content_34 = {
    Text = "Entre os dentes, algumas palavras sussurradas escapam."
  },
  AvgDialog_118959_Content_35 = {
    Text = "Apenas você que sabe sobre orações, rituais, o reino divino, Lemúria e o nascimento da divindade..."
  },
  AvgDialog_118959_Content_36 = {
    Text = "Nunca entenderá."
  },
  AvgDialog_118959_Content_37 = {
    Text = "Tudo o que fiz, o ponto final que alcancei com esforço, esta ilusão que mantenho com dificuldade..."
  },
  AvgDialog_118959_Content_38 = {
    Text = "Apenas quero chamá-lo de uma maneira que você me trate com sinceridade..."
  },
  AvgDialog_118959_Content_39 = {Text = "Mãe..."},
  AvgDialog_118959_Content_4 = {
    Text = "Se eu não fizer isso, ela certamente vai arrancar meu coração com suas próprias mãos..."
  },
  AvgDialog_118959_Content_40 = {
    Text = "O vento forte sobre o mar encobriu o sussurro que já era vago."
  },
  AvgDialog_118959_Content_41 = {
    Text = "Que pena, que pena."
  },
  AvgDialog_118959_Content_42 = {
    Text = "Murphy enxugou as lágrimas."
  },
  AvgDialog_118959_Content_43 = {
    Text = "Todas as minhas expectativas em relação a você não passam de delírios, e o equilíbrio mantido por mentiras é apenas uma ilusão eterna."
  },
  AvgDialog_118959_Content_44 = {
    Text = "Você nunca será minha mãe."
  },
  AvgDialog_118959_Content_45 = {
    Text = "A Murphy que você conhecia já está morta há muito tempo. Sua morte veio junto com o nascimento do Deus."
  },
  AvgDialog_118959_Content_46 = {
    Text = "Em pé aqui, está um corpo desperto nascido das cinzas da vida e da luminis de prata..."
  },
  AvgDialog_118959_Content_47 = {
    Text = "Aquele que me despertou dos destroços... não, isso pode ser chamado de humano?"
  },
  AvgDialog_118959_Content_48 = {
    Text = "Meu Conector está bem diante de vocês."
  },
  AvgDialog_118959_Content_49 = {
    Text = "Ela levanta suavemente o manto, e em seu rosto, você captura uma estranha ternura, quase aterradora, que nunca viu antes."
  },
  AvgDialog_118959_Content_5 = {
    Text = "Sacrifique-me ao seu respeitável rei."
  },
  AvgDialog_118959_Content_50 = {
    Text = "Eu trouxe isso para este mundo... e isso me trouxe de volta a este mundo..."
  },
  AvgDialog_118959_Content_51 = {
    Text = "O destino desviado está entrelaçado, e o ciclo distorcido nunca termina."
  },
  AvgDialog_118959_Content_52 = {
    Text = "Um pai dá à luz filhos, e a filha gera o pai, o pai então desperta a filha..."
  },
  AvgDialog_118959_Content_53 = {
    Text = "Ninguém vem cortar este laço profundo, ninguém vem impedir a confusão da eterna ligação sanguínea."
  },
  AvgDialog_118959_Content_54 = {
    Text = "Você acha que é a primeira pessoa a ficar presa em um ciclo?"
  },
  AvgDialog_118959_Content_55 = {
    Text = "Antes disso, já entrei no ciclo inúmeras vezes, e o final de cada ciclo é um pesadelo indescritível."
  },
  AvgDialog_118959_Content_56 = {
    Text = "Porque a recusa da Lemúria resultou na penetração de Miryam no peito."
  },
  AvgDialog_118959_Content_57 = {
    Text = "Prisão com correntes por Goliath, roubo da estátua de marfim, o destino de afundar junto com o navio."
  },
  AvgDialog_118959_Content_58 = {
    Text = "Ainda no sonho, uma silhueta magra, mas forte, abre um caminho de fuga para mim."
  },
  AvgDialog_118959_Content_59 = {
    Text = "Sempre acreditei que aqueles não seriam os verdadeiros desfechos. \n Estou esperando pelo desfecho que pertence apenas a \"este eu\"."
  },
  AvgDialog_118959_Content_6 = {
    Text = "Então você disse que ela estava esperando por mim... Eu não entendo."
  },
  AvgDialog_118959_Content_60 = {
    Text = "O verdadeiro fim pode chegar."
  },
  AvgDialog_118959_Content_61 = {
    Text = "Afunde este navio."
  },
  AvgDialog_118959_Content_62 = {
    Text = "A cortina negra, como a seda vomitada pelo céu, desce do sol negro sem luz, encobrindo e isolando o navio do mundo exterior."
  },
  AvgDialog_118959_Content_63 = {
    Text = "As águas infinitas do mar subiram, enterrando todo o navio Paradis no abismo escuro e ignorante."
  },
  AvgDialog_118959_Content_64 = {
    Text = "Mais uma vez, você caiu na escuridão sem fim."
  },
  AvgDialog_118959_Content_7 = {
    Text = "<Shake:Por quê? Miryam, por quê?>"
  },
  AvgDialog_118959_Content_8 = {
    Text = "Se eu não for uma Mãe Divina qualificada, então você pode simplesmente me liberar como de costume, não é?"
  },
  AvgDialog_118959_Content_9 = {
    Text = "<Red:Desista de mim... me dê liberdade...>"
  },
  AvgDialog_118960_Content_1 = {
    Text = "Véu Eterno"
  },
  AvgDialog_118960_Content_10 = {
    Text = "Não, eu sempre pude manipular tudo no sonho, eu posso decidir o fim e o começo do ciclo, eu..."
  },
  AvgDialog_118960_Content_11 = {
    Text = "A divindade lhe concedeu o poder de sonhar, mas você está preso em sua própria obsessão, desperdiçando sua bondade."
  },
  AvgDialog_118960_Content_12 = {
    Text = "Emprestar...?"
  },
  AvgDialog_118960_Content_13 = {
    Text = "Você ainda se lembra de onde veio aquela estátua?"
  },
  AvgDialog_118960_Content_14 = {
    Text = "Estátua… a Sua criação…"
  },
  AvgDialog_118960_Content_15 = {
    Text = "Ao dar à luz... o Santo Bebê..."
  },
  AvgDialog_118960_Content_16 = {
    Text = "Não, eu nunca vi essa estátua nos sete dias após o nascimento da Criança Santa."
  },
  AvgDialog_118960_Content_17 = {
    Text = "A estátua dele... é..."
  },
  AvgDialog_118960_Content_18 = {
    Text = "Não é de admirar que eu sempre sinta que falta uma peça no quebra-cabeça da resposta completa."
  },
  AvgDialog_118960_Content_19 = {
    Text = "%player%, você ainda se lembra da nossa dedução?\nO tempo de nascimento do domínio, antes da dissolução consumir o mundo e o sol se transformar em um sol negro."
  },
  AvgDialog_118960_Content_2 = {
    Text = "<Red:Não deve acabar>"
  },
  AvgDialog_118960_Content_20 = {
    Text = "E a Cerimônia de Nascimento da Criança Santa, o Sacrifício de Murphy e a sua ressurreição ocorreram claramente após o nascimento do Sol Negro."
  },
  AvgDialog_118960_Content_21 = {
    Text = "Em outras palavras, naquela época, Murphy era apenas um humano cheio de espiritualidade, não suficiente para construir este sonho."
  },
  AvgDialog_118960_Content_22 = {
    Text = "A pessoa que detinha o poder antes disso... deveria ser..."
  },
  AvgDialog_118960_Content_23 = {
    Text = "O Rei Deus deste mundo já nasceu... não, melhor dizendo, nunca morreu."
  },
  AvgDialog_118960_Content_24 = {
    Text = "Você não pode despertar sua consciência, porque sua consciência ainda está no profundo sono do sonho."
  },
  AvgDialog_118960_Content_25 = {
    Text = "Ele não pode suportar vê-lo morrer por causa do sacrifício, então separou um fio de força para criar um sonho dentro do seu sonho."
  },
  AvgDialog_118960_Content_26 = {
    Text = "Infelizmente, você deseja muito... Assim, o sonho continua a se desintegrar e reiniciar, essa é a essência do Paraíso."
  },
  AvgDialog_118960_Content_27 = {
    Text = "Ele nasceu do seu desejo, mas não é seu escravo…"
  },
  AvgDialog_118960_Content_28 = {
    Text = "<Yellow:Então, agora, Ele vai cumprir a missão que o Criador lhe concedeu.>"
  },
  AvgDialog_118960_Content_29 = {
    Text = "O céu começou a se agitar, um véu negro cobriu o campo de visão, um enorme corpo se ergueu como um pico de montanha."
  },
  AvgDialog_118960_Content_3 = {Text = "?!"},
  AvgDialog_118960_Content_30 = {
    Text = "Não surgiu do abismo, mas sim a \"vontade\" em si que rompeu a casca da dimensão."
  },
  AvgDialog_118960_Content_31 = {
    Text = "Sob o cúpula asfixiante, Seus membros aparecem silenciosamente: pálidos, finos, com as articulações torcidas, como se fossem os ossos de um santo torturado até a deformidade."
  },
  AvgDialog_118960_Content_32 = {
    Text = "<Big:<Shake:...!!!>>"
  },
  AvgDialog_118960_Content_33 = {Text = "Murphy..."},
  AvgDialog_118960_Content_34 = {
    Text = "A silhueta daquela enorme figura é claramente a forma da menina que você conhece."
  },
  AvgDialog_118960_Content_35 = {
    Text = "<Red:Sonho... deve... continuar...>"
  },
  AvgDialog_118960_Content_4 = {
    Text = "<Red:Não pode terminar>"
  },
  AvgDialog_118960_Content_5 = {
    Text = "O céu começou a se costurar, um véu negro encobre o céu e o sol, formando um céu falso."
  },
  AvgDialog_118960_Content_6 = {
    Text = "Clic, clic, você ouve o som da roda de fiar girando novamente."
  },
  AvgDialog_118960_Content_7 = {
    Text = "Por quê? Por quê? Eu já decidi terminar este sonho..."
  },
  AvgDialog_118960_Content_8 = {
    Text = "Porque... respeitável Mãe Divina, o verdadeiro dono deste sonho não é você."
  },
  AvgDialog_118960_Content_9 = {Text = "??!!"},
  AvgDialog_118961_Content_1 = {
    Text = "Delírio de Nascimento"
  },
  AvgDialog_118961_Content_10 = {
    Text = "Surpreso? O único caminho de fuga deste navio está sob meu controle."
  },
  AvgDialog_118961_Content_11 = {
    Text = "Goliath agarrou Murphy com força, a lâmina gigante pressionando sua garganta.\nsangue escorreu do pescoço, reunindo-se na cicatriz que nunca cicatrizaria em seu peito."
  },
  AvgDialog_118961_Content_12 = {Text = "Murphy!"},
  AvgDialog_118961_Content_13 = {
    Text = "Mãe Divina!"
  },
  AvgDialog_118961_Content_14 = {
    Text = "Desculpe, ainda não consigo relaxar..."
  },
  AvgDialog_118961_Content_15 = {
    Text = "Não é que Miryam não queira soltar essa garotinha, mas sim que essa garotinha está restringindo Miryam."
  },
  AvgDialog_118961_Content_16 = {
    Text = "É ela que não quer, não está disposta, não tem coragem de deixar Miryam descobrir a verdade."
  },
  AvgDialog_118961_Content_17 = {
    Text = "Qual é a verdade que você está falando?"
  },
  AvgDialog_118961_Content_18 = {
    Text = "Ela também não sabe onde fica essa Lemúria, ela nunca viu a verdadeira aparência dos deuses."
  },
  AvgDialog_118961_Content_19 = {
    Text = "Porque ela não sabia, aquele navio só podia flutuar no mar, assim continuando a flutuar."
  },
  AvgDialog_118961_Content_2 = {
    Text = "Então, neste momento em que o deus já nasceu, por que você segura Murphy com tanta firmeza?"
  },
  AvgDialog_118961_Content_20 = {
    Text = "Não sei que tipo de truque essa menina usou para seduzir vocês dois..."
  },
  AvgDialog_118961_Content_21 = {
    Text = "Um Marchador de mares Grande Sacerdote, uma pessoa misteriosa que desceu do céu, sendo enganada por uma garotinha."
  },
  AvgDialog_118961_Content_22 = {
    Text = "Você já esqueceu quando ela fugiu?"
  },
  AvgDialog_118961_Content_23 = {Text = "Correr."},
  AvgDialog_118961_Content_24 = {
    Text = "A menina está correndo."
  },
  AvgDialog_118961_Content_25 = {
    Text = "Ela não sabe qual é o fim da jornada, nem se conseguirá escapar dos olhos da madrinha."
  },
  AvgDialog_118961_Content_26 = {
    Text = "<Shake:Ha, ha...>"
  },
  AvgDialog_118961_Content_27 = {
    Text = "Não havia ninguém à sua espera à frente, e o som dos pés de pato batendo no chão atrás dela, de forma estranha e um pouco cômica, tornava-se cada vez mais intenso."
  },
  AvgDialog_118961_Content_28 = {
    Text = "A notícia do desaparecimento da Santa já se espalhou, os Marchadores de mares estão se reunindo."
  },
  AvgDialog_118961_Content_29 = {
    Text = "Maldito, esses caras irritantes."
  },
  AvgDialog_118961_Content_3 = {
    Text = "Sua questão ressoa de forma penetrante."
  },
  AvgDialog_118961_Content_30 = {
    Text = "Atrás do brilho, a figura da capa roxa que simbolizava seu fracasso apareceu lentamente..."
  },
  AvgDialog_118961_Content_31 = {Text = "..."},
  AvgDialog_118961_Content_32 = {
    Text = "Murphy deste mundo não conseguiu escapar."
  },
  AvgDialog_118961_Content_33 = {
    Text = "Porque aquele que a enviou aos Marchadores de mares, e que de repente se arrependeu e a enviou de volta..."
  },
  AvgDialog_118961_Content_34 = {
    Text = "já desapareceu para sempre na catástrofe de dissolução da grande explosão."
  },
  AvgDialog_118961_Content_35 = {
    Text = "Essa garotinha não se tornou Mãe Divina por vontade própria, assim como eu não me tornei seu escravo por vontade própria."
  },
  AvgDialog_118961_Content_36 = {
    Text = "Todos nós estamos em busca do que queremos."
  },
  AvgDialog_118961_Content_37 = {
    Text = "<Shake:Não, eu não quero nada.>Eu... não quero nada."
  },
  AvgDialog_118961_Content_38 = {
    Text = "Você não quer nada? Não, você quer muitas coisas."
  },
  AvgDialog_118961_Content_39 = {
    Text = "Você quer desfrutar da vida privilegiada da Mãe Divina, mas não deseja assumir a obrigação de ser um guia."
  },
  AvgDialog_118961_Content_4 = {
    Text = "Apertado na mão, você quer dizer...?"
  },
  AvgDialog_118961_Content_40 = {
    Text = "Você tem medo de ser abandonado, então trata os outros como marionetes na sua vida, como brinquedos em seu chá de bonecas."
  },
  AvgDialog_118961_Content_41 = {
    Text = "A cada intervalo de tempo, você apaga a memória de todos a bordo e inicia um novo ciclo."
  },
  AvgDialog_118961_Content_42 = {
    Text = "Menina, deixe-me te dizer: não seja esperta demais, tudo que se ganha neste mundo tem um preço."
  },
  AvgDialog_118961_Content_43 = {
    Text = "Você achou que ninguém nunca descobriria suas pequenas artimanhas? Achou que com aquela estátua de marfim, você seria invencível?"
  },
  AvgDialog_118961_Content_44 = {
    Text = "Murphy apertou a estátua de marfim que segurava nas mãos."
  },
  AvgDialog_118961_Content_45 = {
    Text = "Pare de ser tolo, criança idiota."
  },
  AvgDialog_118961_Content_46 = {
    Text = "Você acha que não sei nada sobre suas ações? Eu apenas ainda não estou pronto para enfrentá-lo de frente."
  },
  AvgDialog_118961_Content_47 = {
    Text = "A cada ciclo, estou tentando mudar a forma de roubar o navio. Ameaçar você, ameaçar Miryam, explodir a sala de energia..."
  },
  AvgDialog_118961_Content_48 = {
    Text = "Depois eu descobri que, enquanto aquela maldita estátua de marfim estivesse lá, eu não teria espaço para lutar contra você."
  },
  AvgDialog_118961_Content_49 = {
    Text = "O riso desdenhoso de Goliath ecoou no convés."
  },
  AvgDialog_118961_Content_5 = {
    Text = "Foi você quem construiu este sonho, aprisionando Murphy em um ciclo de sonhos, não foi?"
  },
  AvgDialog_118961_Content_50 = {
    Text = "Até alguns meses atrás, a ação da Necrópole que foi destruída por esta pequena coisa na minha frente."
  },
  AvgDialog_118961_Content_51 = {
    Text = "Não foi possível apreender núcleos de prata suficientes, o poder divino da estátua de marfim se perdeu, e a memória do corpo desperto no navio já estava solta."
  },
  AvgDialog_118961_Content_52 = {
    Text = "Você se lembra de tudo... Eles se lembram de tudo?..."
  },
  AvgDialog_118961_Content_53 = {
    Text = "Então, William não se lembra de tudo porque ele vem de outro mundo."
  },
  AvgDialog_118961_Content_54 = {
    Text = "Outros seres espirituais não são diferentes de mim... Eles sabem que o mundo se inverte e o tempo retrocede."
  },
  AvgDialog_118961_Content_55 = {
    Text = "<Small:<Shake:Todos que você disse... inclui... ela?>>"
  },
  AvgDialog_118961_Content_56 = {
    Text = "Murphy abaixou a cabeça, sua voz tão baixa que quase desaparecia, seu olhar oscilava, sempre se desviando para a mulher ao seu lado, mas antes de tocar seu olhar, ela imediatamente se retraiu."
  },
  AvgDialog_118961_Content_57 = {
    Text = "Sua pequena garota extremamente estúpida, eu disse todos os Despertados."
  },
  AvgDialog_118961_Content_58 = {
    Text = "Isso inclui, naturalmente, aquela mulher estúpida, Miryam."
  },
  AvgDialog_118961_Content_59 = {
    Text = "Então você quer dizer..."
  },
  AvgDialog_118961_Content_6 = {
    Text = "Miryam pondera antes de falar, e uma risada profunda ecoa atrás de você."
  },
  AvgDialog_118961_Content_60 = {
    Text = "Miryam lembra-se de cada coisa que aconteceu a cada renascimento, ela está esperando por você repetidamente."
  },
  AvgDialog_118961_Content_61 = {
    Text = "Eu consigo conectar-me ao sonho daquele cara lá, eu testemunhei o fim daquele mundo. Eu suponho que Miryam também pode."
  },
  AvgDialog_118961_Content_62 = {
    Text = "<Blue:Ela sabe tudo o que você faz.> Mas em cada ciclo, ela nunca intervém. Ela apenas... espera. E espera."
  },
  AvgDialog_118961_Content_63 = {
    Text = "Goliath levantou o queixo e apontou para Miryam, que estava em silêncio ao lado."
  },
  AvgDialog_118961_Content_64 = {
    Text = "Você acha que ela está presa voluntariamente nesta fortaleza que você construiu com suas próprias mãos."
  },
  AvgDialog_118961_Content_65 = {
    Text = "Miryam respondeu em silêncio às suposições de Goliath."
  },
  AvgDialog_118961_Content_66 = {
    Text = "<Shake:Por quê? Eu não entendo por quê?>"
  },
  AvgDialog_118961_Content_67 = {
    Text = "Para você, eu não deveria ser um produto fracassado, uma ferramenta descartada?"
  },
  AvgDialog_118961_Content_68 = {
    Text = "Você não deveria me abandonar como abandonou elas?"
  },
  AvgDialog_118961_Content_7 = {
    Text = "Deixe-me contar."
  },
  AvgDialog_118961_Content_8 = {
    Text = "<Shake:porque essa garota chamada Murphy é uma mentirosa.>"
  },
  AvgDialog_118961_Content_9 = {
    Text = "A multidão liderada pelos filisteus abriu uma pequena brecha, e um marinheiro empurrou Murphy, que estava em apuros, para fora."
  },
  AvgDialog_118962_Content_1 = {
    Text = "Você fecha a porta da cabine, coloca o trinco e ouve os passos da perseguição se virarem para outra direção, então se vira para observar seu pequeno refém."
  },
  AvgDialog_118962_Content_10 = {
    Text = "Se eles não cumprirem seus deveres... onde estarão?"
  },
  AvgDialog_118962_Content_11 = {
    Text = "De acordo com o temperamento de Goliath, não deveria ser que ele estivesse se escondendo no cassino subterrâneo."
  },
  AvgDialog_118962_Content_12 = {
    Text = "Ele deve estar tramando algo em segredo..."
  },
  AvgDialog_118962_Content_13 = {
    Text = "William está de guarda no quarto de Murphy."
  },
  AvgDialog_118962_Content_14 = {
    Text = "Mesmo que eu esteja sozinho, pelo menos posso segurá-los por vinte minutos... é o suficiente..."
  },
  AvgDialog_118962_Content_15 = {
    Text = "Os passos de repente ficaram mais esparsos."
  },
  AvgDialog_118962_Content_16 = {
    Text = "Bem-vindo, Grande Sacerdote!"
  },
  AvgDialog_118962_Content_17 = {
    Text = "Grande Sacerdote, já cercamos os invasores no aposento da Mãe Divina! Apenas aguardo sua ordem..."
  },
  AvgDialog_118962_Content_18 = {
    Text = "Não precisa, a Mãe Divina não está mais aqui."
  },
  AvgDialog_118962_Content_19 = {
    Text = "(Fui descoberto?!)"
  },
  AvgDialog_118962_Content_2 = {Text = "Hmph..."},
  AvgDialog_118962_Content_20 = {
    Text = "As pessoas no quarto... que tal conversarmos?"
  },
  AvgDialog_118962_Content_21 = {
    Text = "O que você gostaria de conversar?"
  },
  AvgDialog_118962_Content_22 = {
    Text = "Nenhum de vocês ou seus amigos, desde que embarcaram, todos os marinheiros têm tratado com respeito."
  },
  AvgDialog_118962_Content_23 = {
    Text = "Vocês, no entanto, retribuíram com ingratidão, sequestrando a Mãe Divina, o que impediu a realização do crucial ritual de navegação na data prevista."
  },
  AvgDialog_118962_Content_24 = {
    Text = "Se perdermos este momento da posição correta das estrelas, precisaremos esperar mais sessenta ciclos de estrelas para realizar nosso grande desejo."
  },
  AvgDialog_118962_Content_25 = {
    Text = "Deve haver uma razão para isso, e eu gostaria de ouvir os motivos de vocês dois."
  },
  AvgDialog_118962_Content_26 = {
    Text = "Porque o Guardião do Segredo passou pelo Ciclo? Porque aquela menina já foi parte de Misaq?"
  },
  AvgDialog_118962_Content_27 = {
    Text = "William ainda não conseguia organizar sua resposta, quando um som repugnante de um movimento molhado e escorregadio surgiu atrás dele."
  },
  AvgDialog_118962_Content_28 = {
    Text = "Ele se virou abruptamente — sua pupila contraiu instantaneamente. Vários peixe-homens já haviam entupido a janela como um fluxo de lama que rompeu uma represa."
  },
  AvgDialog_118962_Content_29 = {
    Text = "Os membros distorcidos se espremem apressadamente para dentro da sala, e um líquido corporal fétido e viscoso jorra como uma cascata, imediatamente impregnando o tapete em um pântano escorregadio."
  },
  AvgDialog_118962_Content_3 = {
    Text = "Ela não sabia de onde havia tirado um pequeno espelho, mas estava cuidadosamente arrumando os cabelos bagunçados na testa."
  },
  AvgDialog_118962_Content_30 = {
    Text = "Ele era como um prego, cravado firmemente no ponto de morte onde duas ondas malignas estavam prestes a se encontrar."
  },
  AvgDialog_118962_Content_31 = {
    Text = "Como foi feito isso……"
  },
  AvgDialog_118962_Content_32 = {
    Text = "A janela do convés está a mais de dez metros de altura, e o Guardião do Segredo cortou a corda longa assim que conseguiu escapar."
  },
  AvgDialog_118962_Content_33 = {
    Text = "Como eles entraram silenciosamente pela janela, atravessando a parede lisa?"
  },
  AvgDialog_118962_Content_34 = {
    Text = "O Reino Divino nos concede a força suficiente para enfrentar desastres, esses obstáculos insignificantes não podem prender os Marchadores de mares."
  },
  AvgDialog_118962_Content_35 = {
    Text = "Criaturas marinhas... ventosas nos pés?"
  },
  AvgDialog_118962_Content_36 = {
    Text = "Além dos Marchadores de mares que estão a bordo do cruzeiro, todas as criaturas marinhas que cercam o casco do navio vieram em resposta ao chamado espiritual de nosso Senhor, sujeitando-se aos nossos comandos."
  },
  AvgDialog_118962_Content_37 = {
    Text = "Mesmo que não seja dessa forma, você deve saber que não pode enfrentar toda a igreja dos Marchadores de mares apenas com um pequeno quarto assim..."
  },
  AvgDialog_118962_Content_38 = {
    Text = "Os investigadores de Misaq não seriam tão imprudentes... Diga-me, o que mais você sabe?"
  },
  AvgDialog_118962_Content_39 = {
    Text = "<Big:<Shake:Kaboom——>>"
  },
  AvgDialog_118962_Content_4 = {
    Text = "Aquela estrutura que você mencionou... onde está?"
  },
  AvgDialog_118962_Content_40 = {
    Text = "Um estrondo metálico que faz os dentes doerem rasgou o céu, acompanhado de um tremor violento, como se o casco do navio fosse repentinamente agarrado e violentamente torcido por uma mão invisível!"
  },
  AvgDialog_118962_Content_41 = {
    Text = "O que está acontecendo?!"
  },
  AvgDialog_118962_Content_42 = {
    Text = "Alguém está forçando a mudança de direção!"
  },
  AvgDialog_118962_Content_43 = {
    Text = "Um navio de dez mil toneladas se agita como uma besta furiosa e fora de controle, contorcendo-se freneticamente nas grandes ondas do mar noturno, cada tremor violento parece querer rasgar o casco!"
  },
  AvgDialog_118962_Content_44 = {
    Text = "Sala de energia… é a sala de energia!"
  },
  AvgDialog_118962_Content_45 = {
    Text = "Goliath fez reféns e tomou a sala de energia!"
  },
  AvgDialog_118962_Content_46 = {
    Text = "Lá vem de novo..."
  },
  AvgDialog_118962_Content_47 = {
    Text = "Tremores intensos vêm em ondas."
  },
  AvgDialog_118962_Content_48 = {Text = "Murphy..."},
  AvgDialog_118962_Content_49 = {
    Text = "Eu sei, você com certeza não consegue esquecer aquele seu companheiro mais velho, certo?"
  },
  AvgDialog_118962_Content_5 = {
    Text = "Bem debaixo do assento do capitão, olha."
  },
  AvgDialog_118962_Content_50 = {
    Text = "Eu entendo, um por um, todos dizem que sou a pessoa mais importante, mas quando chega o momento da decisão, todos me abandonam facilmente."
  },
  AvgDialog_118962_Content_51 = {Text = "Eu..."},
  AvgDialog_118962_Content_52 = {
    Text = "Tá bom, tá bom, são apenas algumas reclamações inúteis disfarçadas. Nós não somos íntimos, certo?"
  },
  AvgDialog_118962_Content_53 = {
    Text = "Além disso, se a sala de energia explodir, o porão inferior também pode ser afetado."
  },
  AvgDialog_118962_Content_54 = {
    Text = "Vamos, não temos outra escolha."
  },
  AvgDialog_118962_Content_6 = {
    Text = "Ela pisou na placa de ferro embaixo dos pés."
  },
  AvgDialog_118962_Content_7 = {
    Text = "No entanto, isso é um pouco estranho…"
  },
  AvgDialog_118962_Content_8 = {
    Text = "Nesta época, Goliath e Caecus deveriam estar vigiando a sala de comando."
  },
  AvgDialog_118962_Content_9 = {
    Text = "Antes do ritual, as criaturas do fundo do mar ficarão em agitação. Precisamos evitar que o cardume frenético interfira na direção do navio..."
  },
  AvgDialog_118963_Content_1 = {
    Text = "Férias da Mãe Divina"
  },
  AvgDialog_118963_Content_10 = {
    Text = "Você quer dizer..."
  },
  AvgDialog_118963_Content_11 = {
    Text = "Sim, você ainda pode ser sua Mãe Divina. No entanto, hoje é o Férias da Mãe Divina."
  },
  AvgDialog_118963_Content_12 = {
    Text = "Você diz mentiras sem mudar a expressão."
  },
  AvgDialog_118963_Content_13 = {
    Text = "Férias da Mãe Divina?"
  },
  AvgDialog_118963_Content_14 = {
    Text = "Sim, hoje, fui encarregado de levar você para se divertir no barco por um dia."
  },
  AvgDialog_118963_Content_15 = {
    Text = "Depois de embarcar, você ainda não experimentou a verdadeira vida de tripulação, certo?"
  },
  AvgDialog_118963_Content_16 = {
    Text = "Sem possibilidade de recusa, você \"pediu\" a Murphy para sair do quarto."
  },
  AvgDialog_118963_Content_17 = {
    Text = "Nós realmente precisamos escalar um lugar assim?"
  },
  AvgDialog_118963_Content_18 = {
    Text = "Suba, só lá a visão é boa e você pode observar a situação dos Marchadores de mares em patrulha."
  },
  AvgDialog_118963_Content_19 = {
    Text = "Se você continuar devagar, será descoberto!"
  },
  AvgDialog_118963_Content_2 = {
    Text = "Você abre os olhos. O sol brilhante faz seus olhos doerem."
  },
  AvgDialog_118963_Content_20 = {
    Text = "Que confusão é essa!"
  },
  AvgDialog_118963_Content_21 = {
    Text = "Embora tenha dito isso, ela obedeceu e segurou sua mão. Você a puxou facilmente e a trouxe para o palco."
  },
  AvgDialog_118963_Content_22 = {Text = "Pfft—"},
  AvgDialog_118963_Content_23 = {
    Text = "Murphy de repente riu."
  },
  AvgDialog_118963_Content_24 = {
    Text = "O que você está rindo?"
  },
  AvgDialog_118963_Content_25 = {
    Text = "Sua maneira de escalar as cordas é igual a de um macaco!"
  },
  AvgDialog_118963_Content_26 = {
    Text = "Seu idiota, se não fosse necessário manter o volume agora, eu definitivamente bateria com força na sua testa..."
  },
  AvgDialog_118963_Content_27 = {
    Text = "Não ria! Você também não pode escapar!"
  },
  AvgDialog_118963_Content_28 = {
    Text = "Você puxou a mão de Murphy e a trouxe para perto de você."
  },
  AvgDialog_118963_Content_29 = {
    Text = "Ei, como você se atreve!"
  },
  AvgDialog_118963_Content_3 = {
    Text = "Mas você não desviou o olhar."
  },
  AvgDialog_118963_Content_30 = {Text = "Shh!"},
  AvgDialog_118963_Content_31 = {
    Text = "Vocês prenderam a respiração, enquanto uma equipe de Marchadores de mares, vestindo capas de palha velhas e sujas, balançava e atravessava o convés."
  },
  AvgDialog_118963_Content_32 = {
    Text = "Rápido, encontre logo o paradeiro da Mãe Divina! Ela deve estar neste navio!"
  },
  AvgDialog_118963_Content_33 = {
    Text = "Nós estamos bem acima deles, e eles não nos veem?"
  },
  AvgDialog_118963_Content_34 = {
    Text = "Desde a antiguidade, a patrulha não olha para cima."
  },
  AvgDialog_118963_Content_35 = {
    Text = "Relaxe, basta estarmos escondidos aqui, ninguém poderá nos descobrir."
  },
  AvgDialog_118963_Content_36 = {
    Text = "Gua, olhe para cima, tem alguém lá!"
  },
  AvgDialog_118963_Content_37 = {
    Text = "Você está sendo um pouco demais com esse bico de corvo, não acha!"
  },
  AvgDialog_118963_Content_38 = {
    Text = "Fique discreto, depois de eliminar esse pequeno grupo, vamos rapidamente para a cabine da tripulação!"
  },
  AvgDialog_118963_Content_4 = {
    Text = "Sussurrante, sussurrante, o som das aranhas se arrastando como o suave encorajamento de uma mãe."
  },
  AvgDialog_118963_Content_5 = {
    Text = "Não precisa me lembrar. Eu sei, este é o último ciclo."
  },
  AvgDialog_118963_Content_6 = {
    Text = "Você enxugou as lágrimas que escorriam do canto dos olhos e se virou na direção de onde a chamada estava prestes a vir, sem olhar para trás para confirmar a origem da canção."
  },
  AvgDialog_118963_Content_7 = {
    Text = "Porque você sabe que a mulher com o tear certamente observa você com compaixão."
  },
  AvgDialog_118963_Content_8 = {
    Text = "O que você ainda está fazendo aqui? A navegação deste navio foi restaurada, não há mais espaço para você aqui."
  },
  AvgDialog_118963_Content_9 = {
    Text = "Não importa, você é a Mãe Divina dos Marchadores de mares, também é a capitã do Navio Paradis, a senhora do Paraíso. Isso não tem a ver com eu querer te dar uma folga."
  },
  AvgDialog_119922_Content_1 = {
    Text = "Bem-vindo de volta, parceiro."
  },
  AvgDialog_119922_Content_10 = {
    Text = "Tudo bem, meu senhor, não importa quanto tempo você precise correr, Ogier estará com você. Eu só espero que..."
  },
  AvgDialog_119922_Content_11 = {
    Text = "O jovem cavaleiro olha para você seriamente, seus olhos estão cheios de sinceridade e de um pedido oculto sob essa sinceridade."
  },
  AvgDialog_119922_Content_12 = {
    Text = "Apenas espero que... da próxima vez que o senhor planejar \"descontrair\" e ficar fora por tanto tempo, por favor, leve-me com você. Ogier jurará proteger você até a morte."
  },
  AvgDialog_119922_Content_13 = {
    Text = "Ou eu também posso."
  },
  AvgDialog_119922_Content_14 = {
    Text = "Lotan também olhou para você, seus olhos normalmente expressivos estavam repletos de seriedade. Neste momento, realmente não havia vitória ou derrota, nem batalha, apenas preocupação por você."
  },
  AvgDialog_119922_Content_15 = {
    Text = "……Eu sabia que seria assim. Vocês dois, não se esqueçam do objetivo deste chá. Estamos celebrando o \"Retorno\" de %player%."
  },
  AvgDialog_119922_Content_16 = {
    Text = "Espero que, após este \"retorno\", você não saia mais."
  },
  AvgDialog_119922_Content_17 = {
    Text = "Apenas foi um passeio, não precisa ser tão sério assim... Além disso, eu já voltei, não é?"
  },
  AvgDialog_119922_Content_18 = {
    Text = "Ao ouvir suas palavras, Dôl olhou para você. Ela parecia querer dizer algo, mas acabou apenas soltando um leve suspiro."
  },
  AvgDialog_119922_Content_19 = {
    Text = "Sim, você voltou. Aqueles que procuravam por você no campus só podiam se decepcionar, e aqueles dias em que ficavam em silêncio em frente à sua porta, mas não ousavam bater, também ficaram para trás."
  },
  AvgDialog_119922_Content_2 = {
    Text = "Não se sabe quando, a praça de Misaq foi decorada para um pequeno chá, e Ramona estava ao lado de uma mesa cheia de bolinhos, geleias e chá, sorrindo enquanto estendia a mão para você."
  },
  AvgDialog_119922_Content_20 = {
    Text = "%player%, eu já disse isso inúmeras vezes e continuarei a dizer no futuro, sua existência é extremamente importante."
  },
  AvgDialog_119922_Content_21 = {
    Text = "Nenhum que seja para este mundo, ou para nós. Então…"
  },
  AvgDialog_119922_Content_22 = {
    Text = "Você espera pacientemente pela continuação de Doll, mas ela apenas fechou os olhos e não disse mais nada."
  },
  AvgDialog_119922_Content_23 = {
    Text = "Neste momento, uma mão suave, mas firme, se colocou sobre as costas da sua mão, era Ramona."
  },
  AvgDialog_119922_Content_24 = {
    Text = "Parceiro, eu sei que como Guardião, você carrega muita pressão, todos nós entendemos e compreendemos. Portanto, não vamos exigir demais."
  },
  AvgDialog_119922_Content_25 = {
    Text = "Eu apenas espero que você saiba, não importa quantas vezes você vá, não importa quanto tempo você fique longe, quando você voltar, estaremos todos aqui."
  },
  AvgDialog_119922_Content_26 = {
    Text = "Dizendo isso, a voz da garota fez uma pausa e ela lentamente sorriu para você."
  },
  AvgDialog_119922_Content_27 = {
    Text = "Mais uma vez, bem-vindo de volta, parceiro. Agora, aproveite o chá da tarde preparado especialmente para você."
  },
  AvgDialog_119922_Content_28 = {
    Text = "Exatamente. Hoje não há avaliações, nem deveres adicionais. Sua única tarefa é se divertir."
  },
  AvgDialog_119922_Content_29 = {
    Text = "Se você não se importa com cáries e o excesso de açúcar, pode comer todos esses doces. Afinal, eles também foram preparados para você."
  },
  AvgDialog_119922_Content_3 = {
    Text = "Não sei se tenho a honra de convidá-lo para o chá da tarde de retorno que preparamos para você?"
  },
  AvgDialog_119922_Content_30 = {
    Text = "Não precisa ser assim……"
  },
  AvgDialog_119922_Content_31 = {
    Text = "Embora você diga isso, ainda assim experimentou um rolo de manteiga coberto de açúcar. O sabor é exatamente como você imaginava, doce demais, mas não é desagradável."
  },
  AvgDialog_119922_Content_32 = {
    Text = "Porque, sob o olhar preocupado de todos, seu coração já encontrou satisfação. Talvez a vida seja saborear um doce tocante nesse intervalo amargo da realidade."
  },
  AvgDialog_119922_Content_4 = {
    Text = "Você acena com a cabeça, então a menina gentilmente segurou sua mão, levando-o em direção à mesa triangular cheia de pratos, onde os Corpos Despertos já estavam esperando há muito tempo."
  },
  AvgDialog_119922_Content_5 = {
    Text = "Se você me perguntar, uma luta não é mais \"emocionante\" do que uma festa do chá? Mas de fato... desta vez é um pouco diferente."
  },
  AvgDialog_119922_Content_6 = {
    Text = "Desta vez, não se trata de ganhar ou perder, não se trata de batalha. Apenas se trata de você."
  },
  AvgDialog_119922_Content_7 = {
    Text = "%player%, você é a estrela absoluta deste chá da tarde."
  },
  AvgDialog_119922_Content_8 = {
    Text = "Lotan disse, empurrando o prato cheio de rolos de manteiga com açúcar para você. \n Ao olhar apenas uma vez, você já sabia que era assustadoramente calórico."
  },
  AvgDialog_119922_Content_9 = {
    Text = "Como eu sinto que... basta comer um pedaço e preciso correr um semestre para digerir..."
  },
  AvgDialog_119923_Content_1 = {
    Text = "No pântano espiritual escuro, veio uma dor aguda que atingiu a alma, acompanhada de palavras frias."
  },
  AvgDialog_119923_Content_10 = {
    Text = "Ao lembrar da sensação de ter a cabeça aberta, seu cérebro ficou paralisado, e para se livrar dessa sensação, você mudou de assunto proativamente."
  },
  AvgDialog_119923_Content_11 = {
    Text = "Este mundo... Como está a situação agora?"
  },
  AvgDialog_119923_Content_12 = {
    Text = "Ainda é a mesma coisa. A cada momento, estamos mais perto do colapso e da destruição. Mas pelo menos há boas notícias, para você."
  },
  AvgDialog_119923_Content_13 = {
    Text = "Dizendo isso, Fusão·Doll ligou o comunicador e, em breve, uma figura familiar apareceu diante de você. Era uma comunicação de vídeo que já havia sido gravada anteriormente."
  },
  AvgDialog_119923_Content_14 = {
    Text = "Fusão - Boneca, se %player% retornar com sucesso ou tiver alguma notícia, lembre-se de me avisar. Além disso, acho que sua sugestão de implantar uma sugestão psicológica anteriormente foi muito razoável."
  },
  AvgDialog_119923_Content_15 = {
    Text = "Como psicólogo profissional, em relação a deixar %player% nessa questão, não posso ser muito indulgente com a vontade do paciente..."
  },
  AvgDialog_119923_Content_16 = {
    Text = "A comunicação parou abruptamente aqui, sendo encerrada por Fusão·Boneca. Ela deu uma leve batidinha na mesa, indicando que você deveria direcionar sua atenção para ela."
  },
  AvgDialog_119923_Content_17 = {
    Text = "As gentilezas inúteis podem parar por aqui. Liberei essas coisas Apenas para mostrar a você o que perdeu durante o tempo em que esteve \"ausente\"."
  },
  AvgDialog_119923_Content_18 = {
    Text = "O mais importante é que meu experimento ainda não acabou..."
  },
  AvgDialog_119923_Content_19 = {
    Text = "Fusão·Doll está se aproximando de você com um bisturi. Sua expressão é calma, mas esconde uma certa Loucura."
  },
  AvgDialog_119923_Content_2 = {
    Text = "Até quando você vai continuar fingindo que está dormindo? Meu adorável cachorrinho."
  },
  AvgDialog_119923_Content_20 = {
    Text = "Você, o que quer fazer?"
  },
  AvgDialog_119923_Content_21 = {
    Text = "Pretendo fixar sua mente permanentemente neste cérebro, neste corpo. Assim, você não poderá mais \"sair\"."
  },
  AvgDialog_119923_Content_22 = {
    Text = "Você recuou com medo, mas logo se recuperou, pois lembrou que ainda tinha coisas a fazer——"
  },
  AvgDialog_119923_Content_23 = {
    Text = "Fusão·Boneca, não precisa ser assim. Basta que este mundo não tenha retornado ao normal, eu não irei realmente embora."
  },
  AvgDialog_119923_Content_24 = {
    Text = "A figura segurando o bisturi parou, apenas olhando para você, como se estivesse avaliando a veracidade de suas palavras."
  },
  AvgDialog_119923_Content_25 = {
    Text = "Estou falando sério. Como Guardião, eu nunca desistirei de salvar este mundo, então não importa quanto tempo eu \"parta\", sempre voltarei."
  },
  AvgDialog_119923_Content_26 = {
    Text = "Fusão·Doll largou o bisturi. Aproveitando a oportunidade, você tocou seu peito. \n Quando seus dedos tocaram a familiar chave de prata, seu coração finalmente se acalmou."
  },
  AvgDialog_119923_Content_27 = {
    Text = "Agora, eu voltei. A investigação que foi interrompida anteriormente pode continuar."
  },
  AvgDialog_119923_Content_28 = {
    Text = "Dizendo isso, você caminhou em direção à porta. Fusão - Boneca olhou para você e também a seguiu."
  },
  AvgDialog_119923_Content_29 = {
    Text = "Parece que você entende bem a importância da sua existência para este mundo."
  },
  AvgDialog_119923_Content_3 = {
    Text = "Fusão·Boneca?"
  },
  AvgDialog_119923_Content_30 = {
    Text = "Claro, porque como Tawil disse, eu sou a variável deste mundo, o futuro deste mundo."
  },
  AvgDialog_119923_Content_31 = {
    Text = "Com suas palavras, a porta do laboratório se abre lentamente. O ar e a luz do sol do lado de fora caem suavemente sobre você, como uma recepção silenciosa, ou uma resposta."
  },
  AvgDialog_119923_Content_32 = {
    Text = "Este mundo está à sua espera, esperando pela mudança que você trará e pelo futuro que você criará."
  },
  AvgDialog_119923_Content_4 = {
    Text = "Você reconheceu a origem daquela voz e lentamente abriu os olhos. Em breve, a escuridão se dissipou e a luz apareceu —"
  },
  AvgDialog_119923_Content_5 = {
    Text = "\"Como é a sensação de deixar este mundo?\""
  },
  AvgDialog_119923_Content_6 = {
    Text = "Talvez, da próxima vez eu deva aprisionar sua \"mente\" também, assim não precisarei recuperá-la."
  },
  AvgDialog_119923_Content_7 = {
    Text = "Fusão·Doll franziu os olhos, exibindo uma expressão que parecia um sorriso, enquanto manipulava lentamente o bisturi brilhante em suas mãos."
  },
  AvgDialog_119923_Content_8 = {
    Text = "……Como eu estou aqui?"
  },
  AvgDialog_119923_Content_9 = {
    Text = "Claro, é porque sua \"mente\" saiu, o corpo perdeu a função, então eu tive que operar novamente para trazer sua \"mente\" de volta."
  },
  AvgDialog_120290_Content_1 = {
    Text = "Cálice de Carne Dourado"
  },
  AvgDialog_120290_Content_10 = {
    Text = "O portal se abre, e você cai em um abraço. Ela te levanta para a cama, colocando os cobertores ao seu redor, então se inclina e toca sua testa na sua, puxando você para perto do seu lado."
  },
  AvgDialog_120290_Content_11 = {
    Text = "Mūmā...? Mūmā!"
  },
  AvgDialog_120290_Content_12 = {
    Text = "O pai não se preocupa comigo há muito tempo. Não há ninguém em casa para me ajudar, e não há água... Minha cabeça dói tanto, e meu corpo todo dói."
  },
  AvgDialog_120290_Content_13 = {
    Text = "...O bom Nānnān da Mūmā, não chore."
  },
  AvgDialog_120290_Content_14 = {
    Text = "Não se preocupe, tudo ficará bem em breve, Mūmā promete a você."
  },
  AvgDialog_120290_Content_15 = {
    Text = "Você se afunda no cobertor quente, captando sonolentamente o aroma que gradualmente se intensifica, não mais semelhante à fragrância habitual de jasmim da sua mãe, mas como..."
  },
  AvgDialog_120290_Content_16 = {
    Text = "Como é o cheiro? Como os becos mais profundos e sinuosos de Shencheng, onde grandes flores de magnólia caem e fermentam no calor sufocante—uma estranha doçura enjoativa e doentia."
  },
  AvgDialog_120290_Content_17 = {
    Text = "Mãe, seu cheiro mudou? Está tão bom, e... também é meio estranho."
  },
  AvgDialog_120290_Content_18 = {
    Text = "A voz suave não respondeu à sua pergunta. Com seu toque delicado, a fragrância se intensificou, quase se tornando tangível."
  },
  AvgDialog_120290_Content_19 = {
    Text = "Você quer ver o rosto dela claramente, mas apenas uma névoa sem fim gira diante dos seus olhos, envolvendo-o completamente."
  },
  AvgDialog_120290_Content_2 = {
    Text = "Uma leve névoa carrega o perfume de jasmim, envolvendo seus membros e entrelaçando você em um abraço invisível e úmido."
  },
  AvgDialog_120290_Content_20 = {
    Text = "Durma, bom bebê, durma. Mamãe logo estará ao seu lado."
  },
  AvgDialog_120290_Content_21 = {
    Text = "...Eu já prometi a ela."
  },
  AvgDialog_120290_Content_22 = {
    Text = "Na escuridão, a sede ainda arranha você como a pata de um gato, e então um líquido morno e viscoso parece fluir para sua garganta a partir das suas narinas ou do canto da sua boca."
  },
  AvgDialog_120290_Content_23 = {
    Text = "Suas pálpebras ficam cada vez mais pesadas e, em meio ao perfume e murmúrios, você gradualmente perde completamente a consciência."
  },
  AvgDialog_120290_Content_24 = {
    Text = "...até que o som de passos se reúne suavemente do lado de fora da porta, despertando você do seu pesado e pulsante torpor com os sons de conversas."
  },
  AvgDialog_120290_Content_25 = {
    Text = "Oh querida, Srta. Die, todos os dias você acorda e imediatamente quer chá. É tão irritante! Você realmente acha que ainda é a dama mimada que era quando estava viva?"
  },
  AvgDialog_120290_Content_26 = {
    Text = "Mantenha a voz baixa! ... O mestre nem cuida de sua própria filha. Quantas concubinas lindas há no pátio? Olhe, ela não está correndo novamente para a Quarta Rua hoje."
  },
  AvgDialog_120290_Content_27 = {
    Text = "Apenas assista, não vai demorar. Em breve, todas as concubinas da casa estarão com os pequenos mestres e senhoras saindo..."
  },
  AvgDialog_120290_Content_28 = {
    Text = "...Meu senhor?"
  },
  AvgDialog_120290_Content_29 = {
    Text = "Você levanta a cabeça, e uma bacia de cobre ligeiramente suja sobre o suporte de madeira reflete levemente os traços delicados e jovens de uma pessoa oriental. Você pisca em confusão, e a garotinha no reflexo pisca de volta."
  },
  AvgDialog_120290_Content_3 = {
    Text = "A sonolência após a febre faz com que você não consiga resistir a se inclinar para aquela névoa..."
  },
  AvgDialog_120290_Content_30 = {
    Text = "Sua consciência gradualmente se clareia, e fragmentos sobre sua identidade emergem em sua mente."
  },
  AvgDialog_120290_Content_31 = {
    Text = "...Senhor, Ho Fong, pai... Estou na mansão da família He, sou a filha de Ho Fong, meu nome é..."
  },
  AvgDialog_120290_Content_32 = {
    Text = "Oh não, você não pode deitar no chão assim. O mestre vai me repreender se ele te ver."
  },
  AvgDialog_120290_Content_33 = {
    Text = "A porta foi de repente empurrada para abrir, interrompendo seus pensamentos enquanto alguém corria para frente e impacientemente o ajudava a se levantar."
  },
  AvgDialog_120290_Content_34 = {
    Text = "O que eu estou fazendo no chão agora? Onde está a mamãe?"
  },
  AvgDialog_120290_Content_35 = {
    Text = "Senhora? Moça, você deve estar ciente; a senhora está desaparecida há mais de um mês."
  },
  AvgDialog_120290_Content_36 = {
    Text = "Ela soltou, ao te ver parado aí em estado de atordoamento, com uma expressão de relutância no rosto."
  },
  AvgDialog_120290_Content_37 = {
    Text = "<Small:É só isso, provavelmente nem sabe o que significa sair.>"
  },
  AvgDialog_120290_Content_38 = {
    Text = "<LightGray:Sim, mamãe fez isso há mais de um mês...>"
  },
  AvgDialog_120290_Content_39 = {
    Text = "Você sonhou de novo? Suspiro. Aqui, eu trouxe um pouco de água para você."
  },
  AvgDialog_120290_Content_4 = {
    Text = "Então ele caiu direto no chão."
  },
  AvgDialog_120290_Content_40 = {
    Text = "Água... você de repente percebe que não está mais com sede; o líquido que fluiu antes, acompanhado de sua fragrância."
  },
  AvgDialog_120290_Content_41 = {
    Text = "O cheiro doce, quase em decomposição, da magnólia ainda permanece em seus dentes e narinas!\nDe repente, você volta à atenção e corre para fora."
  },
  AvgDialog_120290_Content_42 = {
    Text = "Ei, ei! Para onde você acha que está correndo, senhorita!"
  },
  AvgDialog_120290_Content_43 = {
    Text = "O festival do Extremo Oriente chegou, as luzes estão se acendendo, e as lanternas vermelhas e as luzes de néon modernas se complementam. No entanto, as pessoas que deveriam ter voltado para casa cedo neste dia estão todas fluindo na mesma direção."
  },
  AvgDialog_120290_Content_44 = {
    Text = "O ar está cheio do cheiro de pó, querosene, o cheiro gorduroso de barracas de lanche e restaurantes, e um cheiro cada vez mais forte..."
  },
  AvgDialog_120290_Content_45 = {
    Text = "Minha mamãe. É o cheiro dela. Não foi um sonho! Não foi!"
  },
  AvgDialog_120290_Content_46 = {
    Text = "Você o encontrou, a fonte daquele estranho, intenso, familiar, íntimo e terno cheiro metálico doce."
  },
  AvgDialog_120290_Content_47 = {
    Text = "A placa do Edifício de Vendas Douradas pendura-se longe acima no portão ornamentado."
  },
  AvgDialog_120290_Content_48 = {Text = "Senhor Xu!"},
  AvgDialog_120290_Content_49 = {
    Text = "Saia do caminho, Sr. Xu, você está bloqueando meu caminho, olhe para lá!"
  },
  AvgDialog_120290_Content_5 = {
    Text = "Ugh! Dói... Mūmā... Água..."
  },
  AvgDialog_120290_Content_50 = {Text = "Tsk"},
  AvgDialog_120290_Content_51 = {
    Text = "A figura na plataforma alta brincava preguiçosamente com um leque negro, metade do seu rosto escondido atrás da superfície do leque."
  },
  AvgDialog_120290_Content_52 = {
    Text = "As pessoas se empurravam, quase te sobrecarregando, com uma vaga corrente de entusiasmo e ansiedade surgindo em seus olhos, mas parecia não ter efeito sobre ela."
  },
  AvgDialog_120290_Content_53 = {
    Text = "Você encontrou a fonte daquela fragrância, ou melhor, um certo desejo e calafrio que você não conseguia compreender te cativaram. Você levantou a cabeça desesperadamente e olhou para cima."
  },
  AvgDialog_120290_Content_54 = {Text = "...yeah."},
  AvgDialog_120290_Content_55 = {
    Text = "Sentindo algo, ela baixou os olhos, e tudo o que você podia ver eram um par de olhos muito, muito bonitos."
  },
  AvgDialog_120290_Content_56 = {
    Text = "O ventilador negro moveu-se lentamente para o lado com uma elegância de parar o coração."
  },
  AvgDialog_120290_Content_57 = {
    Text = "<color=#C6C4C6>NévNÉVOANéVoA</color>\n<color=#817D81>NÉVOAnÉvOa</color><color=#B9B7B9>Ela... ISSO? ISSO...Ela... Mãe...</color>MÃEeOs OLHOS\n<color=#C6C4C6>NÉVOAnÉvOa</color><color=#B9B7B9>NÉVOA</color><color=#817D81>nÉvOaNÉVOAnÉvOaNÉVOAnÉvOaNÉVOA</color><color=#C6C4C6>NÉVOA</color> <color=#757175>NÉVOA</color>       <color=#817D81>ELAELAELAELELA</color>                         <color=#757175>nÉvOaNÉVOAnÉvOa</color><color=#C6C4C6>NÉVOANÉVOAMÃEnÉvOaNÉVOA</color> <color=#C6C4C6>nÉvOaNÉVOAnÉvOa</color>      <color=#B9B7B9>ELAELAELAELELA</color>         <color=#817D81> nÉvOaNÉVOAnÉvOa</color><color=#D7D7D7>NÉVOAnÉvOaNÉVOAnÉvOaNÉVOAnÉvOaNÉVOAnÉvOa</color> <color=#D7D7D7>NÉVOAnÉvOaNÉVOAnÉvOa</color><color=#B9B7B9>NÉvOaNÉVOA</color><color=#757175>nÉvOaNÉVOAnÉvOa</color><color=#ACAAAC>NÉVOAnÉvOaNÉVOAnÉvOaNÉVOAnÉvOaNÉVOAnÉvOaNÉVOA</color> <color=#B9B7B9>sOLHOSnÉvOaNÉVOAnÉvOa</color><color=#817D81>BELOSOLHOS</color><color=#B9B7B9>nÉvOaNÉVOAnÉvOaNÉVOAnÉvOa</color><color=#757175>BELOSOLHOS</color><color=#D7D7D7>NÉVOAnÉvOa NÉVOAnÉvOaNÉVOAnÉvOaNÉVOAnÉvOaNÉVOANÉVOAnÉvOaNÉVOAnÉvOa</color> <color=#5F5D5F>MÃESDELAMÃnÉvOa</color><color=#817D81>NÉVOAnÉvOaNÉVOAMÃEmÃ</color><color=#757175>OLHOMÃEOLHOSOLHOnÉvOaNÉVOAnÉvOa</color><color=#B9B7B9>ELAELAELAELAnÉvOaNÉVOA</color> <color=#757175>nÉvOaNÉVOAnÉvOaOLHOSBELNÉVOA</color><color=#B9B7B9>nÉvOaNÉVOAnÉvOaNÉVOAnÉvOaNÉVOAMÃESnÉvOaNÉVOAnÉvOa</color> <color=#C6C4C6>MÃESMãESMÃES</color><color=#D7D7D7>MÃMÃESMÃESDER</color><color=#ACAAAC>MÃESDERBELÍSSIMA</color>"
  },
  AvgDialog_120290_Content_58 = {
    Text = "Chorando, gritando, uivando, de repente explodem em seus ouvidos, enquanto camadas e mais camadas de pessoas avançam em sua direção!"
  },
  AvgDialog_120290_Content_59 = {
    Text = "Eu vi, eu vi, ela está olhando para mim!"
  },
  AvgDialog_120290_Content_6 = {
    Text = "Seus membros estão tão fracos que você não consegue reunir forças; a memória ainda não voltou, e você está incrivelmente sedento, pronunciando instintivamente o nome mais familiar."
  },
  AvgDialog_120290_Content_60 = {
    Text = "Ela está olhando para mim!"
  },
  AvgDialog_120290_Content_61 = {
    Text = "<Change>Tão... tão bonito!! Que rosto é esse, tão adorável, tão... extraordinário... tão aterrorizante!!!"
  },
  AvgDialog_120290_Content_62 = {
    Text = "Senhor Xu! Senhor Xu... Por favor, por favor!!"
  },
  AvgDialog_120290_Content_63 = {
    Text = "Olhe para mim!"
  },
  AvgDialog_120290_Content_64 = {
    Text = "<Shake:<Red:AAAAHHHHH!!!!>>"
  },
  AvgDialog_120290_Content_65 = {
    Text = "O homem bem vestido gritou de repente e lançou-se contra o homem de terno que estava entre ele e Xu, enquanto este olhava diretamente para a posição de Xu, até que seu globo ocular foi inesperadamente arrancado."
  },
  AvgDialog_120290_Content_66 = {
    Text = "O homem, cujos olhos foram arrancados, gritou de agonia enquanto ria maniacamente. Os cristais esféricos balançavam suavemente de suas órbitas oculares enquanto ele limpava o rosto casualmente e, com todas as suas forças, estendia a mão em direção à plataforma alta, suas veias saltando."
  },
  AvgDialog_120290_Content_67 = {
    Text = "Como se um sinal tivesse sido dado, a multidão se transforma em uma maré enlouquecida. Em meio a risos e gritos, eles avançam, desesperados para tocar o palco alto."
  },
  AvgDialog_120290_Content_68 = {
    Text = "<Mudar>Xu!! Xu!!!"
  },
  AvgDialog_120290_Content_69 = {
    Text = "<Mudar>Xu——!!!!!"
  },
  AvgDialog_120290_Content_7 = {
    Text = "Uma voz suave de zumbido se aproximou de longe, e uma figura feminina passou pela porta, familiar e calorosa. Você sentiu seu corpo inferior enfraquecer enquanto tentava se levantar..."
  },
  AvgDialog_120290_Content_70 = {
    Text = "O som agudo e penetrante está prestes a estourar seus tímpanos. A multidão empurra e se espreme, e este corpo jovem geme sob a pressão, enquanto os traços sob o leque se tornam mais claros, mas mais indistintos."
  },
  AvgDialog_120290_Content_71 = {
    Text = "No final, se tornou uma névoa semelhante a um abismo que engoliu toda a luz."
  },
  AvgDialog_120290_Content_72 = {
    Text = "E uma risada deliciosamente leve que passou pela névoa."
  },
  AvgDialog_120290_Content_73 = {
    Text = "Você está aqui, meu pequeno jasmim."
  },
  AvgDialog_120290_Content_74 = {
    Text = "Logo antes de ser engolido pela escuridão e sufocação, você vislumbra a multidão, igualmente envolvida na frenesi, abandonando toda a dignidade enquanto empurram para frente..."
  },
  AvgDialog_120290_Content_75 = {
    Text = "A figura do seu pai, que não lançou um olhar para você nem por um momento."
  },
  AvgDialog_120290_Content_8 = {
    Text = "<Shake:Creak—Yaa—>"
  },
  AvgDialog_120290_Content_9 = {
    Text = "Oh querido, coitadinho, como você acabou em um lugar como este?"
  },
  AvgDialog_120291_Content_1 = {
    Text = "Aparição repentina"
  },
  AvgDialog_120291_Content_10 = {
    Text = "Um pedaço de massa em pó e enjoativa, claramente não refinada, foi empurrado para dentro da sua boca. Assim que o bolo começou a se dissolver, sua saliva começou a fluir descontroladamente na sua boca."
  },
  AvgDialog_120291_Content_11 = {
    Text = "Você segue de perto a outra pessoa, mastigando o doce. Assim que seu estômago começa a se acalmar, uma pressão mais intensa aperta seu coração."
  },
  AvgDialog_120291_Content_12 = {
    Text = "Não fique parada aí, senhorita, entre logo, o Sr. Xu está esperando há muito tempo."
  },
  AvgDialog_120291_Content_13 = {
    Text = "Pai estava, como sempre, rodeado por muitas concubinas cujos rostos você não consegue lembrar bem. As concubinas no pátio vão e vêm, cada uma com sua própria figura e charme, vibrantes e cheias de vida."
  },
  AvgDialog_120291_Content_14 = {
    Text = "Mas agora seu olhar está extremamente confuso, fixado em apenas uma pessoa."
  },
  AvgDialog_120291_Content_15 = {
    Text = "A proprietária daqueles olhos irritantemente bonitos claramente estava desempenhando algum tipo de papel distante, mas educado, por tédio, até que seu olhar suavemente caiu sobre você."
  },
  AvgDialog_120291_Content_16 = {
    Text = "Embora eu soubesse que você desceria após a cerimônia, nunca esperei que você fosse tão encantador."
  },
  AvgDialog_120291_Content_17 = {
    Text = "Eu não deveria ter te enviado para o bordel, certo! Eu deveria ter te mantido ao meu lado. Agora tudo é sem sentido; nada importa, exceto você!"
  },
  AvgDialog_120291_Content_18 = {
    Text = "Senhor He, por favor, não seja tão formal. Podemos nos encontrar mais tarde; vim hoje para pedir desculpas."
  },
  AvgDialog_120291_Content_19 = {
    Text = "O que uma garota boba sabe? Hoje, vou preparar presentes para o bordel novamente. Se você gostar deles, mantenha-os perto e ensine pessoalmente como cuidar deles?"
  },
  AvgDialog_120291_Content_2 = {Text = "..."},
  AvgDialog_120291_Content_20 = {
    Text = "O Sr. He tem uma postura extraordinária. Se estivermos destinados a nos encontrar, com certeza me trará grande alegria."
  },
  AvgDialog_120291_Content_21 = {
    Text = "Sinto uma forte conexão com esta criança à primeira vista, apesar dos nossos conflitos anteriores... Se você e eu formos nos aproximar, ela também deve estar em paz."
  },
  AvgDialog_120291_Content_22 = {
    Text = "A mulher conhecida como Sr. Xu se aproxima de você e se inclina gentilmente."
  },
  AvgDialog_120291_Content_23 = {
    Text = "Ainda não me apresentei; meu nome é Xu. Então, o que você acha, querida jovem da família He?"
  },
  AvgDialog_120291_Content_24 = {
    Text = "Xu de alguma forma chegou na sua frente. Instintivamente, você agarra a mão da mulher que te trouxe aqui, querendo se esconder atrás dela."
  },
  AvgDialog_120291_Content_25 = {
    Text = "As pontas dos dedos dela, semelhantes a jade, seguram seu queixo, levantando-o suavemente, e você vê aqueles olhos mais uma vez.\nTão semelhantes à sua mãe, mas tão bonitos que te enchem de medo."
  },
  AvgDialog_120291_Content_26 = {
    Text = "Eu... eu..."
  },
  AvgDialog_120291_Content_27 = {
    Text = "<Shake:Todos que te viram na rua ficaram loucos. O tio de terno teve os olhos arrancados! Eu-estou com medo!>"
  },
  AvgDialog_120291_Content_28 = {
    Text = "As palavras infantis que saíram da sua boca realmente atordoaram Xu por um momento, e então ele riu tanto que quase perdeu a compostura."
  },
  AvgDialog_120291_Content_29 = {
    Text = "Que coincidência. Du Langjun, bem a tempo, você poderia me ajudar? Pequena Jasmine, dê uma olhada, é este o cavalheiro de quem estamos falando?"
  },
  AvgDialog_120291_Content_3 = {
    Text = "O choque de estar no centro de uma fúria desconhecida deveria ter destruído sua mente, ou pelo menos sua força de vontade."
  },
  AvgDialog_120291_Content_30 = {
    Text = "Seguindo o dedo dela enquanto se afasta do seu queixo, você nota que atrás das tias ciumentas, há outro homem ainda vestido naquele terno."
  },
  AvgDialog_120291_Content_31 = {
    Text = "É ele. Hum? Por que os olhos dele ainda estão lá?"
  },
  AvgDialog_120291_Content_32 = {
    Text = "Seu rosto não está mais ensanguentado, e seus olhos estão onde deveriam estar; você realmente o reconheceu."
  },
  AvgDialog_120291_Content_33 = {
    Text = "Quando a mãe ainda estava por perto, você e o pai iam a banquetes. O pai tentou falar com ele várias vezes, mas a cada vez foi recebido com rejeição e voltou em fúria."
  },
  AvgDialog_120291_Content_34 = {
    Text = "É esta a menininha que ficou assustada naquele dia? Ela realmente vale o seu esforço, me mandando até aqui para comprar comida para ela?"
  },
  AvgDialog_120291_Content_35 = {
    Text = "A família He não consegue nem gerenciar sua própria filha histérica, mas querem se intrometer nos negócios de importação e exportação de Haicheng. Que ridículo."
  },
  AvgDialog_120291_Content_36 = {
    Text = "Minha filha tem estado acamada e de mau humor desde que minha esposa faleceu, o que deve ter divertido o Sr. Du. Vou cuidar disso imediatamente..."
  },
  AvgDialog_120291_Content_37 = {
    Text = "Vendo a expressão sombria de seu pai, você ficou atordoado e paralisado no lugar, mas logo sentiu um cheiro de flor de magnólia. Você foi segurado nos braços de Xu, que o apertava e amassava descuidadamente."
  },
  AvgDialog_120291_Content_38 = {
    Text = "Du Langjun, eu já disse que gosto desta jovem da família He. Se você discutir com ela e levar as coisas a sério, eu não ficarei feliz—se eu não ficar feliz, o que você vai fazer?"
  },
  AvgDialog_120291_Content_39 = {
    Text = "Ao ouvir isso, o olhar desdenhoso do homem, que estava te examinando de cima a baixo, de repente perdeu o foco. Então, ele balançou o braço e começou a se dar tapas no rosto repetidamente."
  },
  AvgDialog_120291_Content_4 = {
    Text = "Mas essa consciência ainda é muito pequena, como uma efímera. Não, vamos simplificar ainda mais. Um paramécio, ou algum outro organismo unicelular. Você só sabe que precisa estar satisfeito, se manter aquecido e buscar benefícios enquanto evita danos."
  },
  AvgDialog_120291_Content_40 = {
    Text = "Seu rosto instantaneamente inchou, mas ele parecia não sentir a menor dor, abrindo a boca de forma entorpecida para revelar um sorriso como o de um manequim que você poderia ter visto em uma feira ocidental."
  },
  AvgDialog_120291_Content_41 = {
    Text = "Eu falei algo errado!"
  },
  AvgDialog_120291_Content_42 = {
    Text = "Eu disse algo errado, eu disse algo errado!"
  },
  AvgDialog_120291_Content_43 = {
    Text = "Com o som de um tapa, Xu alegremente tirou um saquinho de doces do bolso, pegou um pedaço e enfiou na sua boca."
  },
  AvgDialog_120291_Content_44 = {
    Text = "Que peculiar! A senhorita He gosta de dar uma olhada?"
  },
  AvgDialog_120291_Content_45 = {
    Text = "O néctar doce derrete e você olha em branco para tudo à sua frente. Finalmente, você levanta a cabeça para olhar para Xu."
  },
  AvgDialog_120291_Content_46 = {
    Text = "...Os doces de xarope de pêra do Templo do Deus Cidade, minha mãe costumava comprá-los para mim."
  },
  AvgDialog_120291_Content_47 = {
    Text = "Senhor Xu, você é a mamãe?"
  },
  AvgDialog_120291_Content_48 = {
    Text = "Xu não respondeu, apenas sorriu incessantemente, enquanto as concubinas e o pai ficaram ali parados como se estivessem encantados, em silêncio e imóveis."
  },
  AvgDialog_120291_Content_49 = {
    Text = "Du Langjun, olhe para você mesmo. Eu estava apenas fazendo um pequeno capricho. Você me atingiu tão forte que machuca meu coração."
  },
  AvgDialog_120291_Content_5 = {
    Text = "Então você é mais uma vez embalado por aquela jaula de névoa, abrindo os olhos ileso."
  },
  AvgDialog_120291_Content_50 = {
    Text = "Assim que o homem parou, as concubinas pareceram despertar de um transe, olhando para o Sr. Du, cujas bochechas tinham adquirido um tom azul-púrpura, com choque e confusão."
  },
  AvgDialog_120291_Content_51 = {
    Text = "Lembro que o Sr. He tinha algo a discutir com o Lorde Du, então tomei a liberdade de trazer este presente de visita."
  },
  AvgDialog_120291_Content_52 = {
    Text = "Jovem senhora da família He, quando discutirem assuntos, você estaria disposta a me levar para dar uma volta?"
  },
  AvgDialog_120291_Content_53 = {
    Text = "Antes de sair do quarto, você não pôde deixar de olhar para o seu pai. Seu rosto não exibia a expressão vazia e bizarra do Sr. Du e das tias, mas ele silenciosamente condescendeu com tudo."
  },
  AvgDialog_120291_Content_54 = {
    Text = "Sr. Xu, você..."
  },
  AvgDialog_120291_Content_55 = {
    Text = "Você tem muitas perguntas para fazer, não tem?"
  },
  AvgDialog_120291_Content_56 = {
    Text = "Não se apresse... meu querido bebê, meu bom bebê."
  },
  AvgDialog_120291_Content_57 = {
    Text = "Minha pequena jasmim... venha, olhe para mim."
  },
  AvgDialog_120291_Content_58 = {
    Text = "A densa escuridão pesa, e sob a lua prateada branca como os ossos, Xu move o leque, enquanto a névoa turva avança em sua direção, envolvendo-o e engolindo-o."
  },
  AvgDialog_120291_Content_59 = {
    Text = "Vague, mãe olha para você na luz quente, sorrindo suavemente enquanto se inclina com os braços abertos."
  },
  AvgDialog_120291_Content_6 = {
    Text = "O céu escureceu completamente, e as janelas de outros cômodos refletem a luz de velas distantes, enquanto passos tênues e dispersos se aproximam mais uma vez."
  },
  AvgDialog_120291_Content_60 = {
    Text = "Como uma corda que se rompe de repente, uma onda de emoção te atinge, e as lágrimas embaçam completamente sua visão. Sem hesitar, você a envolve firmemente em seu abraço."
  },
  AvgDialog_120291_Content_61 = {
    Text = "Mãe, você pode, por favor, não sair novamente."
  },
  AvgDialog_120291_Content_62 = {
    Text = "Waaah, waaahhh, minha mente está tão confusa, estou tão assustado. Sinto tanto a sua falta! Mamãe."
  },
  AvgDialog_120291_Content_63 = {
    Text = "A mulher envolve você suavemente com os braços, acariciando suavemente suas costas."
  },
  AvgDialog_120291_Content_64 = {
    Text = "Menina preciosa da mamãe, boa menina da mamãe."
  },
  AvgDialog_120291_Content_65 = {
    Text = "Meu querido bebê, meu bom bebê."
  },
  AvgDialog_120291_Content_66 = {
    Text = "O que você estaria disposto a abrir mão para estar com a mamãe para sempre?"
  },
  AvgDialog_120291_Content_67 = {
    Text = "A névoa parece envolvê-lo novamente, e você ouve o som do seu próprio murmúrio."
  },
  AvgDialog_120291_Content_68 = {
    Text = "Tudo vale... Tudo está bem."
  },
  AvgDialog_120291_Content_69 = {
    Text = "A casa inteira está disponível?"
  },
  AvgDialog_120291_Content_7 = {
    Text = "Oh querida, senhora, você me assustou até a morte. Saindo correndo para a rua em um acesso de raiva, você está tentando nos fazer morrer, pessoas comuns?"
  },
  AvgDialog_120291_Content_70 = {
    Text = "Não quero a casa, só quero a mamãe."
  },
  AvgDialog_120291_Content_71 = {
    Text = "A casa inteira, toda a cidade de Haicheng, e seu pai, tudo isso pode ser feito?"
  },
  AvgDialog_120291_Content_72 = {
    Text = "Pai... Papai..."
  },
  AvgDialog_120291_Content_73 = {
    Text = "Você se distraiu por um momento, lembrando-se repentinamente das noites em que sua mãe esperava pacientemente com você, e da mão que repousava sobre sua cabeça quando seu pai chegava em casa."
  },
  AvgDialog_120291_Content_74 = {
    Text = "Sem preocupações, ainda há muito tempo, pequena Jasmine."
  },
  AvgDialog_120291_Content_75 = {
    Text = "Você parece ser levantado por alguém, caindo em uma cama macia, onde algo ainda mais quente e terno te abraça intimamente."
  },
  AvgDialog_120291_Content_76 = {
    Text = "Já está tarde da noite, então durma. Eu estarei ao seu lado muito em breve, muito em breve."
  },
  AvgDialog_120291_Content_77 = {
    Text = "Depois que sua mãe foi embora, você sentiu uma sensação de alívio sem igual pela primeira vez, juntamente com a sonolência que se seguiu, afundando em um sonho profundo e doce."
  },
  AvgDialog_120291_Content_8 = {
    Text = "<Shake:Glug—>"
  },
  AvgDialog_120291_Content_9 = {
    Text = "...Suspiro, eu realmente sinto muito por você. Acelere e mastigue. O mestre já está esperando no hall, não me cause mais problemas, entendeu?"
  },
  AvgDialog_120296_Content_1 = {
    Text = "Oh, Meu Querido"
  },
  AvgDialog_120296_Content_10 = {
    Text = "Muito bem, guarde seus pequenos pensamentos. Não diga que estou te assustando; esta mansão não é segura. Todas as mulheres que o senhor gostava desapareceram no final."
  },
  AvgDialog_120296_Content_11 = {
    Text = "Até mesmo sua ex-esposa, sua namorada de infância, que se dizia ter falecido devido a uma doença, quem sabe que foi..."
  },
  AvgDialog_120296_Content_12 = {
    Text = "Oh não! Por que você está me empurrando!"
  },
  AvgDialog_120296_Content_13 = {
    Text = "Senhora, eu realmente... eu realmente peço desculpas. Minha irmã tende a falar descuidadamente, por favor, não ouça as bobagens dela. Nós absolutamente não queremos ofendê-la, eu imploro, por favor, não conte ao mestre."
  },
  AvgDialog_120296_Content_14 = {
    Text = "Puxada abruptamente pela irmã, a concubina com sobrancelhas bem desenhadas e maquiagem requintada voltou a si, seu rosto instantaneamente ficando pálido de medo enquanto apressadamente cobria a boca para se silenciar."
  },
  AvgDialog_120296_Content_15 = {
    Text = "Como esta casa não é segura, por que você não pensou em encontrar outro lugar?"
  },
  AvgDialog_120296_Content_16 = {
    Text = "...Onde mais podemos ir? Se pudéssemos ser valorizados como joias pela nobreza, então poderíamos realmente ir a qualquer lugar."
  },
  AvgDialog_120296_Content_17 = {
    Text = "Hehe, segurando-o como uma joia preciosa?"
  },
  AvgDialog_120296_Content_18 = {
    Text = "Xu de repente explodiu em risadas, e naquele momento, várias concubinas no corredor ouviram uma espécie de risada sussurrante mais elusiva."
  },
  AvgDialog_120296_Content_19 = {
    Text = "Seus olhares tornaram-se desfocados enquanto olhavam para cima, confusos, observando a mulher caminhar mais fundo no corredor."
  },
  AvgDialog_120296_Content_2 = {
    Text = "A recém-chegada tem alguns truques na manga."
  },
  AvgDialog_120296_Content_20 = {
    Text = "Minha pequena jasmim está dormindo; não a acordemos. Siga-me."
  },
  AvgDialog_120296_Content_21 = {
    Text = "Eu farei você entender, meu senhor, que uma pessoa nobre, assim como um objeto precioso, só é interessante quando é segurada delicadamente entre os dedos."
  },
  AvgDialog_120296_Content_22 = {
    Text = "As concubinas usavam um sorriso tolo em seus rostos, e então a névoa obscureceu seus lábios, enquanto os leques cobriam seus rostos."
  },
  AvgDialog_120296_Content_23 = {
    Text = "A fragrância rica e doce de magnólia se espalhou silenciosamente por toda a mansão."
  },
  AvgDialog_120296_Content_24 = {Text = "..."},
  AvgDialog_120296_Content_25 = {
    Text = "Depois que Xu foi trazida para a residência de He como a madrasta, você nunca mais passou fome. Todos te trataram com calor e carinho, como se você ainda fosse aquela jovem senhora de quando sua mãe estava por perto."
  },
  AvgDialog_120296_Content_26 = {
    Text = "Mas o pai nunca mais deixou seu quarto, e Xu nunca havia entrado; em vez disso, as concubinas pareciam ser atraídas por fios invisíveis, vindo e indo frequentemente do quarto de Xu."
  },
  AvgDialog_120296_Content_27 = {
    Text = "Oh querida, senhorita, você poderia ajudar, por favor? O mestre instruiu especificamente que ninguém deveria se aproximar de seu quarto."
  },
  AvgDialog_120296_Content_28 = {
    Text = "Faz tanto tempo que não vejo o pai. Vou apenas dar uma olhada à distância, prometo que não vou perturbá-lo."
  },
  AvgDialog_120296_Content_29 = {
    Text = "No entanto, antes que você pudesse se aproximar, ouviu um rosnado rouco e frenético, anormalmente excitado, vindo de dentro do quarto."
  },
  AvgDialog_120296_Content_3 = {
    Text = "Você tem uma língua afiada, mas não consegue se separar do leque que ela te deu, consegue?"
  },
  AvgDialog_120296_Content_30 = {
    Text = "Xu... meu mais querido, meu salvador, meu coração, não posso deixar você ir mais, você é meu, só pode ser meu."
  },
  AvgDialog_120296_Content_31 = {
    Text = "O sangue e os ossos deles não são nada... Não importa quanto, ah! Contanto que possa te trazer de volta, contanto que possa te trazer de volta, tudo vale a pena!"
  },
  AvgDialog_120296_Content_32 = {
    Text = "Eu entendi, eu vi! Haha, hahahaha!!!"
  },
  AvgDialog_120296_Content_33 = {
    Text = "O som escorregadio e contorcido parecia deslizar pelo chão, até que finalmente, um suspiro de algum lugar se transformou em um ofego curto e agudo, como um fole sufocado, como se algo estivesse se envolvendo ao redor, tornando difícil respirar."
  },
  AvgDialog_120296_Content_34 = {Text = "Dad!"},
  AvgDialog_120296_Content_35 = {
    Text = "Você ficou assustado com a voz morta dele e correu para empurrar a porta."
  },
  AvgDialog_120296_Content_36 = {
    Text = "Dentro, apenas He Fang estava freneticamente encostado na beira da cama, desabando sobre a roupa de cama escura, que estava úmida como se tivesse sido encharcada, assim como toda a cabine."
  },
  AvgDialog_120296_Content_37 = {
    Text = "Fragmentos quebrados de objetos e tecidos estavam horrivelmente espalhados ao redor. Ele voltou à realidade, seu rosto coberto por uma cor anormal e doentia, e pegou um travesseiro de madeira para esmagá-lo sobre você."
  },
  AvgDialog_120296_Content_38 = {
    Text = "Quem deixou você entrar!"
  },
  AvgDialog_120296_Content_39 = {
    Text = "Ninguém pode perturbar nossa solidão, saia! Vá embora!"
  },
  AvgDialog_120296_Content_4 = {
    Text = "Ge Mei é linda, tem um ótimo gosto e seus presentes são impressionantes. Você também não se abanaria de um lado para o outro, desejando poder ser como ela, com um leque no rosto?"
  },
  AvgDialog_120296_Content_40 = {
    Text = "A mulher correu atrás de você, fechando a porta rapidamente em meio ao rugido de algum lugar."
  },
  AvgDialog_120296_Content_41 = {
    Text = "Eu te disse para não perturbar meu senhor, ele ficará irritado. Não corra por aí, minha tiazinha."
  },
  AvgDialog_120296_Content_42 = {
    Text = "Pai... Pai, o que está acontecendo? Por que ele continua chamando o nome do Sr. Xu?"
  },
  AvgDialog_120296_Content_43 = {
    Text = "<Shake:O Sr. Xu claramente saiu cedo esta manhã. Com quem ele está falando? A expressão dele é tão assustadora...>"
  },
  AvgDialog_120296_Content_44 = {
    Text = "Questões que dizem respeito ao meu senhor não são para nós, humildes servos, gerenciarmos."
  },
  AvgDialog_120296_Content_45 = {
    Text = "Você tropeça em direção ao lugar que você conhece melhor, na esperança de encontrar alguém que possa ajudá-lo."
  },
  AvgDialog_120296_Content_46 = {
    Text = "O quarto da dama, agora o quarto de Xu, é também o quarto onde minha mãe uma vez ficou."
  },
  AvgDialog_120296_Content_47 = {
    Text = "A porta, que desbotou desde que a mãe saiu, agora está mais uma vez adornada com entalhes dourados, como se tivesse se tornado uma espécie de entrada, cada abertura e fechamento liberando uma fragrância sonolenta e sobrenatural."
  },
  AvgDialog_120296_Content_48 = {
    Text = "Haha, hee hee... Wuwuwuwu... Acontece que eu estava errado o tempo todo, completamente enganado!"
  },
  AvgDialog_120296_Content_49 = {
    Text = "Corte, esmague, abra-o! Apenas abra-o, ainda está fumegante, oferecido a Ele, e eles obedecerão. Eu não precisarei mais sofrer no mar de sofrimento!"
  },
  AvgDialog_120296_Content_5 = {
    Text = "Você está falando sobre mim?"
  },
  AvgDialog_120296_Content_50 = {
    Text = "<Mudar>Xu... nosso Salvador, nosso @3!"
  },
  AvgDialog_120296_Content_51 = {
    Text = "A névoa intangível preencheu todo o quarto enquanto eles levantavam reverentemente os leques que lhes foram dados no dia em que Xu entrou na casa, chorando e rindo, gradualmente se transformando em um lamento bizarro."
  },
  AvgDialog_120296_Content_52 = {
    Text = "Você não consegue entender uma palavra do que as empregadas na sala estão dizendo; seus ouvidos estão cheios de zumbido e o batimento do seu coração. Você tropeça para trás novamente, esbarrando acidentalmente na grade e fazendo barulho."
  },
  AvgDialog_120296_Content_53 = {
    Text = "...sim, há um som."
  },
  AvgDialog_120296_Content_54 = {
    Text = "<Shake:<Red:É outra oferta de sangue que pode ser apresentada?>>"
  },
  AvgDialog_120296_Content_55 = {
    Text = "As vozes deles carregam uma risada leve, e todos os gritos desapareceram, uma sensação inexplicável e arrepiante de terror invade você!"
  },
  AvgDialog_120296_Content_56 = {Text = "Run!!!!"},
  AvgDialog_120296_Content_57 = {
    Text = "Esse é o terror de ser presa, o medo que reside nas linhagens de sangue de todas as criaturas desde tempos imemoriais!"
  },
  AvgDialog_120296_Content_58 = {
    Text = "Oh? Uma simples caixa de biscoitos de borboleta, e minha Pequena Jasmim corre para os meus braços com tanta alegria?"
  },
  AvgDialog_120296_Content_59 = {
    Text = "Os braços semelhantes a jade te pegaram justo antes de você quase cair. Se você olhar através das frestas da cerca do pátio, a renomada Inspetora Huang de Haicheng está fechando a porta do carro para ela."
  },
  AvgDialog_120296_Content_6 = {
    Text = "*Exclaim Ah! Desculpe, senhora!"
  },
  AvgDialog_120296_Content_60 = {
    Text = "A caixa de doces é entregue a você, e os padrões em camadas em forma de olho no papel floral te assustam completamente. Você respira fundo, reúne sua coragem e a derruba no chão."
  },
  AvgDialog_120296_Content_61 = {
    Text = "Quem é você?! Por que está na nossa casa?! O que aconteceu com minha família, meu pai, minha tia, aqueles tios? Desde que você chegou, todos estão agindo de forma estranha..."
  },
  AvgDialog_120296_Content_62 = {
    Text = "Ops... é só uma coisinha, olha, minha pequena jasmim está até chorando."
  },
  AvgDialog_120296_Content_63 = {
    Text = "Ela não ficou brava pelo lanche que você derrubou; em vez disso, ela se abaixou carinhosamente e tocou suavemente o canto do seu olho onde as lágrimas se formaram de medo."
  },
  AvgDialog_120296_Content_64 = {
    Text = "Minha pequena jasmim, este é realmente o seu lar, um lugar onde não se pode encontrar nem uma gota de água?"
  },
  AvgDialog_120296_Content_65 = {
    Text = "Senhorita! Apenas por um momento sem prestar atenção, como você pôde... Senhora, desculpe, foi tudo minha culpa por não ter mantido um olho na jovem dama."
  },
  AvgDialog_120296_Content_66 = {
    Text = "Xu ignorou as pessoas que correram até você e te abraçou mais forte, como sempre, acariciando suas costas como se estivesse afagando um pequeno animal, com uma voz suave e gentil."
  },
  AvgDialog_120296_Content_67 = {
    Text = "Pequena jasmim, pense bem. O que está acontecendo com este assunto e o que há sobre aquele assunto? Qual é a conexão entre eles?"
  },
  AvgDialog_120296_Content_68 = {
    Text = "Desde que você se comporte bem e ouça-me obedientemente o tempo todo."
  },
  AvgDialog_120296_Content_69 = {
    Text = "Tudo pode ser seu, e todos podem se tornar seus brinquedos."
  },
  AvgDialog_120296_Content_7 = {
    Text = "Tch, que senhora? Apenas uma mulher de cabelo longo de uma livraria, do que ela tem medo? Ela realmente pode te comer."
  },
  AvgDialog_120296_Content_70 = {
    Text = "Ela acaricia suas costas até seu cabelo, e após finalmente brincar o suficiente com seu cabelo, ela solta, irradiando uma sensação de alegria."
  },
  AvgDialog_120296_Content_71 = {
    Text = "Certo. Leve minha pequena jasmim para a cama... ela precisa descansar."
  },
  AvgDialog_120296_Content_72 = {
    Text = "Você caminhou muito na névoa e, na névoa cinza, você vê uma vasta área de água escura."
  },
  AvgDialog_120296_Content_73 = {
    Text = "Incontáveis membros viscosos e retorcidos cobertos de ventosas repousam na fronteira entre a água e a névoa, enquanto uma figura suave se senta de costas para você à beira da água."
  },
  AvgDialog_120296_Content_74 = {
    Text = "Mãe? É você?"
  },
  AvgDialog_120296_Content_75 = {
    Text = "<Shake:...Errado... tudo... corra...>"
  },
  AvgDialog_120296_Content_76 = {
    Text = "Mãe, o que você está dizendo? Não consigo ouvir você claramente."
  },
  AvgDialog_120296_Content_77 = {
    Text = "Você se aproximou e de repente percebeu que ela não estava sentada à beira da água; em vez disso, a parte inferior do seu corpo havia se transformado em incontáveis tentáculos, se misturando à água cinza."
  },
  AvgDialog_120296_Content_78 = {
    Text = "<Shake:Errado. Tudo isso.>"
  },
  AvgDialog_120296_Content_79 = {
    Text = "<Shake:Ela não é... Não é...>"
  },
  AvgDialog_120296_Content_8 = {
    Text = "Olhem para vocês, parecem um monte de gatinhos fofos; é tão adorável."
  },
  AvgDialog_120296_Content_80 = {
    Text = "A mulher se virou, seu rosto familiar marcado por lágrimas cinzas, gritando e berrando para você."
  },
  AvgDialog_120296_Content_81 = {
    Text = "<Red:Ela tem o rosto da mãe dela.>"
  },
  AvgDialog_120296_Content_82 = {
    Text = "<Mudar>Ele não é! Ele não é! Ele não é! Ele não é!!"
  },
  AvgDialog_120296_Content_83 = {
    Text = "<Red:<Shake:Errado! Está tudo errado!! Nānnān!!! Corra!! RÁPIDO!! CORRA!!!>>"
  },
  AvgDialog_120296_Content_9 = {
    Text = "Não se preocupe, sou apenas novo aqui. Eu vi todos vocês conversando tão animadamente e pensei em vir aqui e compartilhar um pequeno sussurro."
  },
  AvgDialog_120297_Content_1 = {
    Text = "Sangue do Sire"
  },
  AvgDialog_120297_Content_10 = {
    Text = "Às vezes eram eles mesmos, e outras vezes eram suas esposas. Nesses momentos, o sorriso no rosto de Xu se tornava mais pronunciado. Quando eles vinham pela segunda vez, os mesmos fãs pretos que estavam no pátio apareciam em suas mãos."
  },
  AvgDialog_120297_Content_100 = {
    Text = "No entanto, o feroz e ameaçador He Fang surpreendentemente suavizou sua expressão."
  },
  AvgDialog_120297_Content_101 = {
    Text = "Você realmente acha isso?"
  },
  AvgDialog_120297_Content_102 = {
    Text = "He Lang sabe que, embora eu possua poder divino, ainda estou conectado àquele que me desperta. O que quer que He Lang me ordene fazer, eu só posso obedecer; não há possibilidade de te enganar?"
  },
  AvgDialog_120297_Content_103 = {
    Text = "Assim como no beco, você não pode falar nem se mover. Parece que essa estranha \"deusa\" está determinada a torná-lo um espectador dessa farsa."
  },
  AvgDialog_120297_Content_104 = {
    Text = "Ele se afastou alegremente, assim como naquele dia em frente ao Pavilhão Dourado, sem sequer olhar para trás."
  },
  AvgDialog_120297_Content_105 = {
    Text = "No momento em que você consegue emitir um som, você se vira e pula sobre Xu, soltando um grito semelhante ao de uma besta. Pés, punhos, dentes—apesar de saber que é inútil, você usa todos os métodos de ataque que conhece."
  },
  AvgDialog_120297_Content_106 = {
    Text = "Devolva-me, devolva-me a mamãe, devolva-me o papai!"
  },
  AvgDialog_120297_Content_107 = {
    Text = "Xu Zhi Shan fica parada, permitindo que você desabafe sem se mover. O sorriso em seus olhos faz você esquecer seu medo, deixando apenas raiva e desespero."
  },
  AvgDialog_120297_Content_108 = {
    Text = "Tudo é por sua causa; você não é uma deusa de jeito nenhum, você é um monstro!"
  },
  AvgDialog_120297_Content_109 = {
    Text = "A mulher à minha frente... acenou com a cabeça."
  },
  AvgDialog_120297_Content_11 = {
    Text = "Se esperarmos mais, nem veremos a sombra do Sr. Xu. Acelere."
  },
  AvgDialog_120297_Content_110 = {
    Text = "Isso mesmo, meu jasmimzinho, eu sou um monstro."
  },
  AvgDialog_120297_Content_111 = {
    Text = "Mas a morte da sua mãe não tem nada a ver comigo; foi ele quem matou inúmeras mulheres, incluindo ela, apenas para me invocar em troca de sua riqueza e poder."
  },
  AvgDialog_120297_Content_112 = {
    Text = "Agora há pouco, ele queria te matar. Você não quer morrer, e eu respondi a você. Se eu te abandonasse, você sem dúvida morreria, não é?"
  },
  AvgDialog_120297_Content_113 = {Text = "..."},
  AvgDialog_120297_Content_114 = {
    Text = "Você ficou sem palavras, a voz dela cheia de entusiasmo, e seus belos olhos brilhando de alegria."
  },
  AvgDialog_120297_Content_115 = {
    Text = "Agora, minha pequena jasmim, como você escolherá?"
  },
  AvgDialog_120297_Content_116 = {
    Text = "Você abriu a boca em vão, acabando apenas por olhar para ela em estado de atordoamento, o zumbido agudo em seus ouvidos mexendo com seus nervos. Ela apenas lhe deu um tapinha nas costas antes de entrar no pátio."
  },
  AvgDialog_120297_Content_117 = {
    Text = "Hehe... Em breve. Muito, muito em breve... o momento de você fazer a escolha final chegará."
  },
  AvgDialog_120297_Content_118 = {Text = "..."},
  AvgDialog_120297_Content_119 = {
    Text = "Cenas do dia se repetem em seus sonhos. Você acorda gritando no meio da noite, e a casa está estranhamente silenciosa. Ninguém responde a você, e aquela voz penetrante não existe mais."
  },
  AvgDialog_120297_Content_12 = {
    Text = "A riquixá balançou violentamente. Embora não tenha sido notado, após contorcer-se e virar, perdeu a perseguição quando o veículo entrou em um bosque de árvores."
  },
  AvgDialog_120297_Content_120 = {
    Text = "A fome corrói seu interior, e após se enroscar por um longo tempo, você finalmente se levanta e, guiado pela memória, encontra a caixa de doces quebrados. Silenciosamente, você fica sob a luz da lua e come tudo."
  },
  AvgDialog_120297_Content_121 = {
    Text = "Enquanto você adormecia novamente, voltou à beira da água cinza, onde sua mãe estendia seus braços em forma de tentáculo, alcançando você. Atrás dela, uma outra forma massiva podia ser vagamente vista."
  },
  AvgDialog_120297_Content_122 = {
    Text = "Mãe, ela ainda está aqui?"
  },
  AvgDialog_120297_Content_123 = {
    Text = "Mamãe sempre estará com você."
  },
  AvgDialog_120297_Content_124 = {
    Text = "Eu sempre estarei ao lado da minha pequena jasmim."
  },
  AvgDialog_120297_Content_125 = {
    Text = "Duas vozes soaram em seus ouvidos ao mesmo tempo, e você não fez mais perguntas. Você estava apenas muito cansado e com muito medo."
  },
  AvgDialog_120297_Content_126 = {
    Text = "Você mergulha sem hesitação, naquele abraço aterrorizante, pegajoso, mas incrivelmente macio."
  },
  AvgDialog_120297_Content_13 = {
    Text = "Você foi levado embora, e por algum motivo, seu coração batia cada vez mais rápido. A única coisa que fez você se sentir um pouco melhor foi segurar a mão da mulher com força."
  },
  AvgDialog_120297_Content_14 = {
    Text = "O céu escureceu gradualmente, e a lua subiu silenciosamente sobre as copas das árvores.\nDe repente, a mulher fez um gesto de silêncio para você."
  },
  AvgDialog_120297_Content_15 = {Text = "Shh—"},
  AvgDialog_120297_Content_16 = {
    Text = "Ao longe, a figura de Xu apareceu, a carruagem branca acelerando, enquanto o Sr. Du permanecia em silêncio ao seu lado. No canto, várias sombras longas passaram pelas árvores e foram projetadas no chão pela luz da lua."
  },
  AvgDialog_120297_Content_17 = {
    Text = "Sr. Du, Inspetor Huang, o chefe da Escola do Transporte Fluvial do Norte, e na estrada principal, oh meu, o Sr. Xu é realmente notável..."
  },
  AvgDialog_120297_Content_18 = {
    Text = "Ao longe, os rostos dos homens apareceram com um rubor anormal, muito parecido com o do pai naquele dia. Começou com murmúrios suaves, que depois se intensificaram em gritos sibilantes rápidos e excitados, quase como um cântico."
  },
  AvgDialog_120297_Content_19 = {
    Text = "<Shake:Ela... não pode... ficar...>"
  },
  AvgDialog_120297_Content_2 = {
    Text = "Todas as concubinas estão se tornando cada vez mais parecidas com Xu, e o pai não saiu mais de casa."
  },
  AvgDialog_120297_Content_20 = {
    Text = "<Shake:Matar... só então...>"
  },
  AvgDialog_120297_Content_21 = {
    Text = "<Shake:Matar... Matar... MATAR!! Mate-a—Corte-a em pedaços!!!>"
  },
  AvgDialog_120297_Content_22 = {
    Text = "<Change>Minha, minha, minha, minha, minha, minha, ela é minha!!"
  },
  AvgDialog_120297_Content_23 = {
    Text = "A luz pálida perfurou seus olhos, e só então você percebeu que atrás de cada homem se escondia uma foice, agora erguida em uníssono—"
  },
  AvgDialog_120297_Content_24 = {
    Text = "Ha—hahaha, ahhahahahahaha!!!"
  },
  AvgDialog_120297_Content_25 = {
    Text = "Os homens foram se aproximando gradualmente, e Xu de repente explodiu em risadas, como se tivesse visto a coisa mais ridícula do mundo, apontando para os rostos deles um por um com o dedo."
  },
  AvgDialog_120297_Content_26 = {
    Text = "No segundo seguinte, foices afiadas desceram em alta velocidade de todas as direções, o som surdo da carne sendo rasgada, o estalo dos ossos sendo cortados, e uma mão tão branca quanto jade foi lançada para cima."
  },
  AvgDialog_120297_Content_27 = {
    Text = "Pip, estalo."
  },
  AvgDialog_120297_Content_28 = {
    Text = "Hmm, hmm hmm hmm hmm hmm!"
  },
  AvgDialog_120297_Content_29 = {
    Text = "Você é segurado firmemente em seus braços, suas mãos cobrindo sua boca com firmeza, sufocando os gritos agonizantes que ameaçam escapar."
  },
  AvgDialog_120297_Content_3 = {
    Text = "A mãe não aparece mais em seus sonhos. Às vezes, você sonha com o rosto de Xu sob cada ventilador, e às vezes você sonha com seu pai sendo devorado por um monstro, acordando em um frio suor no final."
  },
  AvgDialog_120297_Content_30 = {
    Text = "<Change>Cabeça, pescoço, peito, braços, abdômen..."
  },
  AvgDialog_120297_Content_31 = {
    Text = "<Shake:Fure a partir do crânio, fure a partir do pescoço, fure a partir da cavidade torácica, fure a partir dos braços, fure a partir do abdômen...>"
  },
  AvgDialog_120297_Content_32 = {
    Text = "<Mudar>Fure o crânio, fure o pescoço, fure a cavidade torácica, fure..."
  },
  AvgDialog_120297_Content_33 = {
    Text = "Meu senhor..."
  },
  AvgDialog_120297_Content_34 = {
    Text = "Gentil, flirtante e doce."
  },
  AvgDialog_120297_Content_35 = {
    Text = "Tão longe, como névoa, se enrola em torno dos contornos da sua orelha e entra na sua mente."
  },
  AvgDialog_120297_Content_36 = {
    Text = "A névoa de sangue foi se aprofundando gradualmente, e uma a uma, figuras surgiram dos cadáveres, com os braços brancos como jade fluindo com lodo negro, elevados bem alto."
  },
  AvgDialog_120297_Content_37 = {
    Text = "Dói tanto, por favor, me dê um beijo—"
  },
  AvgDialog_120297_Content_38 = {
    Text = "<Mudar>Eu, @3, dou-me um beijo..."
  },
  AvgDialog_120297_Content_39 = {
    Text = "<Change>Eu, @3, dou @4 para mim!"
  },
  AvgDialog_120297_Content_4 = {
    Text = "Senhorita, por favor, pare de fazer birra. O Sr. Xu é tão bom com você, trazendo tantos alimentos frescos e brinquedos todos os dias."
  },
  AvgDialog_120297_Content_40 = {
    Text = "<Mudar>Dói tanto, por favor, me dê um beijo!"
  },
  AvgDialog_120297_Content_41 = {
    Text = "Xu... um monstro semelhante a Xu, com suas partes inferiores fundidas em corpos quebrados, com lama cobrindo todo o seu rosto, apenas o contorno de seus lábios exposto."
  },
  AvgDialog_120297_Content_42 = {
    Text = "Em cada rosto \"Xu\", havia dezenas de lábios carnudos e bonitos, semelhantes a pétalas, sugando em direção aos homens que riam loucamente como se estivessem sob um feitiço."
  },
  AvgDialog_120297_Content_43 = {
    Text = "<Mudar>Moer—Moer—"
  },
  AvgDialog_120297_Content_44 = {
    Text = "O som de crânios sendo esmagados, o som de crânios quebrando."
  },
  AvgDialog_120297_Content_45 = {
    Text = "<Change>Slurp—Glug—"
  },
  AvgDialog_120297_Content_46 = {
    Text = "Sons de sucção, sons de mastigação."
  },
  AvgDialog_120297_Content_47 = {
    Text = "Você assistiu impotente enquanto as cabeças deles se despedaçavam e depois retornavam ao estado perfeito. O \"Xu\" soltou suspiros de satisfação e se reuniu em meio aos murmúrios satisfeitos."
  },
  AvgDialog_120297_Content_48 = {
    Text = "Sr. Du, Inspetor Huang, o chefe da Escola do Norte de Transporte Fluvial..."
  },
  AvgDialog_120297_Content_49 = {
    Text = "Eles se levantaram silenciosamente, como se nada tivesse acontecido, dispersando-se atordoados, enquanto Xu já havia desaparecido sem deixar vestígios."
  },
  AvgDialog_120297_Content_5 = {
    Text = "A mulher suspirou e usou um lenço para ajudar a limpar o suor surpreso da sua testa."
  },
  AvgDialog_120297_Content_50 = {
    Text = "Aquela mão finalmente te largou, e na sufocante quietude, suas lágrimas caíram incontrolavelmente. No momento em que você se virou, suas pupilas tremeram violentamente."
  },
  AvgDialog_120297_Content_51 = {Text = "Oops!..."},
  AvgDialog_120297_Content_52 = {
    Text = "Eu tenho pensado em como ser honesto com minha pequena jasmim."
  },
  AvgDialog_120297_Content_53 = {
    Text = "Seus pupilos se contraem ao máximo, e no final, tudo o que resta é a mulher diante de você. Em um instante, seu cérebro já sobrecarregado envia um choque de dor intensa."
  },
  AvgDialog_120297_Content_54 = {
    Text = "Como ela é, a mulher com a voz cortante."
  },
  AvgDialog_120297_Content_55 = {
    Text = "Os servos em seu quarto foram dispensados há muito tempo, quando sua mãe faleceu."
  },
  AvgDialog_120297_Content_56 = {
    Text = "Ninguém nunca se importou com sua vida ou morte, e você nunca realmente viu como ela era, mas por que todos acham sua aparência tão natural?"
  },
  AvgDialog_120297_Content_57 = {
    Text = "Eu me afeiçoei àquela pele... Eu amava o cheiro de jasmim que ela carregava. Desde o começo, eu me perguntei... como seria a minha \"Pequena Jasmim\" — minha Pequena Jasmim?"
  },
  AvgDialog_120297_Content_58 = {
    Text = "Então, eu não consegui resistir a vir ver meu pequeno jasmim por muito, muito tempo."
  },
  AvgDialog_120297_Content_59 = {
    Text = "Você foge pela sua vida. Ela não te impede, apenas te observa com um sorriso por trás da porta, como se estivesse observando um pequeno gato selvagem assustado correndo."
  },
  AvgDialog_120297_Content_6 = {
    Text = "Srta., se você está realmente tão assustada, eu tenho uma ideia."
  },
  AvgDialog_120297_Content_60 = {
    Text = "Pai! Xu é um monstro, ela..."
  },
  AvgDialog_120297_Content_61 = {
    Text = "Você não consegue se lembrar há quanto tempo está correndo ou quantas curvas erradas tomou. Na expressão atônita do porteiro, você corre em direção ao quarto do seu pai, quase arrombando a porta, e agarra ansiosamente a barra das roupas do seu pai."
  },
  AvgDialog_120297_Content_62 = {
    Text = "Mas assim que o nome de Xu sai dos seus lábios, você recebe um tapa forte no rosto."
  },
  AvgDialog_120297_Content_63 = {
    Text = "Eu te disse, você precisa chamá-la<Red:\"Mãe\">."
  },
  AvgDialog_120297_Content_64 = {
    Text = "O rosto do pai estava incomumente alerta e sombrio, o caos dos últimos dias havia desaparecido completamente. Ele segurou a parte de trás do seu colarinho e te afastou de seu lado."
  },
  AvgDialog_120297_Content_65 = {
    Text = "Não, pai, ela se tornou alguém próximo de mim. Ela está interagindo com muitas pessoas e até trouxe elas—"
  },
  AvgDialog_120297_Content_66 = {
    Text = "Suficiente!"
  },
  AvgDialog_120297_Content_67 = {
    Text = "Naquela época, era Xu quem gostava de você, por isso eu o mantive em casa, mas você acabou sendo tão ingrato quanto sua mãe de vida curta."
  },
  AvgDialog_120297_Content_68 = {
    Text = "Você está bagunçando tudo, falando bobagens e falando desrespeitosamente com sua mãe! Vá para o salão e se ajoelhe como punição, e não se levante até antes da hora do galo!"
  },
  AvgDialog_120297_Content_69 = {
    Text = "Ela não é minha mãe, ela é um monstro devorador de homens!"
  },
  AvgDialog_120297_Content_7 = {
    Text = "Você tem tanto medo do Sr. Xu. Por que não apenas o segue e vê o que ele faz todos os dias? Se ele realmente for um monstro, iremos até o velho e pediremos para ele jogá-lo para fora de casa, tudo bem?"
  },
  AvgDialog_120297_Content_70 = {
    Text = "Você gritou o mais alto que pôde, e a sala caiu em um momento de silêncio. Então, você ouviu..."
  },
  AvgDialog_120297_Content_71 = {
    Text = "<Red:O riso baixo e frio do seu pai.>"
  },
  AvgDialog_120297_Content_72 = {
    Text = "<Shake:Um monstro?>"
  },
  AvgDialog_120297_Content_73 = {
    Text = "Xu, é a \"Deusa\" que eu selecionei pessoalmente como sacrifício um por um, e com minhas próprias mãos, os abri, pagando preços incontáveis e esgotando todos os meus esforços, que finalmente invoquei <Red:\"Deusa\">!"
  },
  AvgDialog_120297_Content_74 = {
    Text = "Eu tentei tantas vezes, mas essas pessoas superficiais e comuns não merecem a atenção dela. Você acha que meu coração não dói? Eu também não consigo suportar ver sua mãe."
  },
  AvgDialog_120297_Content_75 = {
    Text = "Como um estrondo, você tem dificuldade em compreender o significado das palavras de seu pai, enquanto sua consciência é completamente dominada pelo som agudo e ensurdecedor."
  },
  AvgDialog_120297_Content_76 = {
    Text = "<Shake:Você deve se sentir honrado; sua carne constitui a forma terrena da Donzela Divina.>"
  },
  AvgDialog_120297_Content_77 = {
    Text = "A voz do pai emana uma frieza assustadora, e você percebe com um calafrio que ele se posicionou ominosamente entre você e a porta, avançando em sua direção passo a passo."
  },
  AvgDialog_120297_Content_78 = {
    Text = "Uma vez que você já sabe de tudo, não pode ficar nesta casa, e eu nunca vou deixar você sair e falar demais."
  },
  AvgDialog_120297_Content_79 = {
    Text = "Antes que seu grito pudesse escapar, sua garganta foi agarrada por seu pai, cujo rosto estava preenchido com loucura, e sua visão rapidamente se tornou tingida de vermelho sangue."
  },
  AvgDialog_120297_Content_8 = {
    Text = "Levar o Sr. Xu embora?"
  },
  AvgDialog_120297_Content_80 = {
    Text = "A <Red:Deusa> desceu. A partir de agora, ela me pertencerá <Red:para sempre>. Fama, fortuna... não significam nada agora. Desde que a <Red:Deusa> esteja comigo, todo sacrifício valeu a pena!"
  },
  AvgDialog_120297_Content_81 = {
    Text = "<Shake:Mãe, me ajude...>"
  },
  AvgDialog_120297_Content_82 = {
    Text = "Eu... não quero morrer, eu quero viver, mamãe..."
  },
  AvgDialog_120297_Content_83 = {
    Text = "<Change><Shake:Eu não quero morrer, está doendo, está doendo, ESTÁ DOENDO. Mamãe, me salve, ME SALVE, ME SALVE, ME AJUDE @4!!>"
  },
  AvgDialog_120297_Content_84 = {
    Text = "Alguém, por favor, salve-me..."
  },
  AvgDialog_120297_Content_85 = {
    Text = "Ninguém responde às suas orações silenciosas."
  },
  AvgDialog_120297_Content_86 = {
    Text = "Caos. Sufocação. Dor. Tranquilidade... O cheiro familiar, doce e de peixe da magnólia."
  },
  AvgDialog_120297_Content_87 = {
    Text = "<Red:<Shake:Creeeeak—>>"
  },
  AvgDialog_120297_Content_88 = {
    Text = "Atordoado, um tentáculo negro irrompeu pela porta, balançando com imensa força e jogando-o diretamente na cama."
  },
  AvgDialog_120297_Content_89 = {
    Text = "He Lang, como você pode competir com uma criança."
  },
  AvgDialog_120297_Content_9 = {
    Text = "O som das buzinas de carros vinha do portão da frente, e todos os dias, rostos diferentes esperavam em frente à mansão da família He, todos figuras proeminentes com quem o proprietário desta propriedade havia desejado se associar um dia."
  },
  AvgDialog_120297_Content_90 = {
    Text = "Um abraço suave te envolve, o ar preenchendo novamente seus pulmões quase desinflados, enquanto você levanta suavemente sua cauda, sendo apoiado invisivelmente de algum lugar."
  },
  AvgDialog_120297_Content_91 = {
    Text = "É só que ela viu algo que não deveria. Eu não quero que ela se lembre, então, naturalmente, ela não vai."
  },
  AvgDialog_120297_Content_92 = {
    Text = "Seu tom é tão alegre e discreto como sempre, até mesmo a pressão da mão dela repousando em sua cabeça."
  },
  AvgDialog_120297_Content_93 = {
    Text = "Fora da porta, pode-se ouvir a voz de um servo reportando."
  },
  AvgDialog_120297_Content_94 = {
    Text = "Meu senhor, há vários cavalheiros esperando por você no salão da frente."
  },
  AvgDialog_120297_Content_95 = {
    Text = "O rosto de He Fang mudou drasticamente, parecendo ainda pior do que quando estava prestes a te matar agora há pouco."
  },
  AvgDialog_120297_Content_96 = {
    Text = "Qingqing, por que você começou de novo? Eu já disse que bens materiais não significam mais nada para mim; só você, apenas você deve ser minha."
  },
  AvgDialog_120297_Content_97 = {
    Text = "Desde que fui despertado por você, He Lang, os outros são apenas sombras passageiras. No entanto, ainda me lembro do grande empreendimento que você está planejando e estou disposto a contribuir com meus modestos esforços."
  },
  AvgDialog_120297_Content_98 = {
    Text = "O que eu faço é apenas buscar mais apoio enquanto estou com você, He Lang, neste mundo."
  },
  AvgDialog_120297_Content_99 = {
    Text = "Não havia claramente um traço de sinceridade nos olhos de Xu, algo que até você, como criança, poderia ver. Sem mencionar que ela acabara de expulsar impiedosamente a própria pessoa a quem havia mostrado tanta ternura."
  },
  AvgDialog_120298_Content_1 = {
    Text = "O Sem Sonhos"
  },
  AvgDialog_120298_Content_10 = {
    Text = "Quando falo com eles, seu cheiro continua perfurando minhas narinas, e só de pensar em você se aproximando de outros homens me deixa completamente louco!"
  },
  AvgDialog_120298_Content_11 = {
    Text = "Eu te disse, tudo que eu preciso é que você esteja ao meu lado. Por que você não pertence só a mim? Por que você ainda está flertando com outros homens!"
  },
  AvgDialog_120298_Content_12 = {
    Text = "Você nunca viu uma expressão tão atordoada no rosto de Xu; ela parece estar procurando uma maneira de escapar, seu olhar se movendo de forma frenética, surpreendentemente pousando em você, que está escondido atrás da janela e não notado por ninguém."
  },
  AvgDialog_120298_Content_13 = {
    Text = "Você se escondeu instintivamente sob o peitoril da janela, notando o olhar de Xu. Você olhou para trás e então seus olhos voltaram para ela."
  },
  AvgDialog_120298_Content_14 = {
    Text = "Ainda pensando em como correr? Desista. Eu sou seu <Red:Despertador>, seu poder está conectado a mim, e seu poder divino não tem efeito sobre mim."
  },
  AvgDialog_120298_Content_15 = {
    Text = "<Red:<Shake:Eu entendi completamente agora. Desde que eu te mate, só matando você... podemos realmente ficar juntos para sempre.>>"
  },
  AvgDialog_120298_Content_16 = {
    Text = "Você prende a respiração e se vira, então corre apressadamente de uma sala para outra, tentando encontrar alguém que possa detê-los."
  },
  AvgDialog_120298_Content_17 = {
    Text = "Não, não, não. A vasta residência He está vazia, nem mesmo um porteiro está à vista."
  },
  AvgDialog_120298_Content_18 = {
    Text = "Até mesmo o portão do pátio foi trancado com um pesado cadeado, e uma névoa cinza sem fundo se agita do lado de fora."
  },
  AvgDialog_120298_Content_19 = {
    Text = "Se isso continuar, o Sr. Xu acabará como a Mamãe..."
  },
  AvgDialog_120298_Content_2 = {
    Text = "No dia seguinte, antes do amanhecer, um grito frenético ecoou pelo pátio."
  },
  AvgDialog_120298_Content_20 = {
    Text = "<Shake:Você deve se esconder. Você deve permanecer escondido até que tudo acabe.>"
  },
  AvgDialog_120298_Content_21 = {
    Text = "Mas você não tem para onde ir. Você encontrou aquilo, escondeu suas mãos atrás das costas e caminhou em direção ao velho quarto da mamãe novamente."
  },
  AvgDialog_120298_Content_22 = {
    Text = "<Red:<Shake:Minha esposa... meu amor... você só pode ser minha.>>"
  },
  AvgDialog_120298_Content_23 = {
    Text = "No momento em que a brilhante foice foi levantada, você trocou olhares com Xu; os olhos dela de repente brilharam, reluzindo com um pedido."
  },
  AvgDialog_120298_Content_24 = {
    Text = "Mas então, ela balançou a cabeça sutilmente—"
  },
  AvgDialog_120298_Content_25 = {
    Text = "<Red:Fuja.>"
  },
  AvgDialog_120298_Content_26 = {
    Text = "Aqueles belos olhos se fecharam, e seu mestre está pronto para o massacre."
  },
  AvgDialog_120298_Content_27 = {Text = "..."},
  AvgDialog_120298_Content_28 = {Text = "ARGH!!"},
  AvgDialog_120298_Content_29 = {
    Text = "Você, maldito, como você se atreve!"
  },
  AvgDialog_120298_Content_3 = {
    Text = "Seu rugido é distorcido, venenoso e cheio de malícia. Você não tem tempo para pensar; um sentimento de imenso terror o obriga a correr em direção à origem do som."
  },
  AvgDialog_120298_Content_30 = {
    Text = "A foice clangrou ao cair no chão, e He Fang, com o rosto cheio de dor, segurou suas costas, onde uma pequena faca que você encontrou estava profundamente cravada em seu corpo."
  },
  AvgDialog_120298_Content_31 = {
    Text = "Em um acesso de raiva, He Fang se virou e estendeu a mão para você. De repente, você ouviu uma série de risadinhas, não apenas uma, enquanto a fonte dos sons se aglomerava densamente no compartimento."
  },
  AvgDialog_120298_Content_32 = {
    Text = "No meio dos sorrisos, uma explosão de risadas incontroláveis irrompeu. Xu, atrás de He Fang, riu tanto que se curvou, com lágrimas escorrendo pelo rosto."
  },
  AvgDialog_120298_Content_33 = {
    Text = "AHAHA! AHAHAHAHAHAHA! Pequena Jasmim... minha mais querida, amada Pequena Jasmim. Você realmente não me decepcionou—você é tão interessante quanto eu imaginava!"
  },
  AvgDialog_120298_Content_34 = {
    Text = "Mulheres em qipaos amarelos e pretos entraram em fila, seus leques dobráveis ocultando seus narizes e lábios. Cada uma delas - tinha um par de olhos muito, muito bonitos."
  },
  AvgDialog_120298_Content_35 = {
    Text = "Em um momento de puro terror, antes que seus gritos ecoassem, um abraço frio e suave já havia te envolvido."
  },
  AvgDialog_120298_Content_36 = {
    Text = "<Red:Coisa nojenta. Você não sujará os olhos da minha Pequena Jasmim.>"
  },
  AvgDialog_120298_Content_37 = {
    Text = "<Shake:Meu Senhor...>"
  },
  AvgDialog_120298_Content_38 = {
    Text = "<Shake:Meu Senhor...>"
  },
  AvgDialog_120298_Content_39 = {
    Text = "O que você está fazendo? Você enlouqueceu! Saia, todos vocês, saiam."
  },
  AvgDialog_120298_Content_4 = {
    Text = "Xu foi encurralado por Ho Fong contra a cama, com os olhos vermelhos e o cabelo despenteado, como se não tivesse dormido a noite toda."
  },
  AvgDialog_120298_Content_40 = {
    Text = "As concubinas à minha frente moveram lentamente as superfícies dos leques, revelando o mesmo rosto sob cada leque."
  },
  AvgDialog_120298_Content_41 = {
    Text = "Por que o senhor nos transformou em sacrifícios?"
  },
  AvgDialog_120298_Content_42 = {
    Text = "Por que o Senhor cortou nossos membros?"
  },
  AvgDialog_120298_Content_43 = {
    Text = "Incontáveis Xus estão alheios aos gritos de raiva trêmulos de He Fang, cercando-o de forma brincalhona no meio, enquanto fãs e foices negras formam alternadamente um círculo ao seu redor."
  },
  AvgDialog_120298_Content_44 = {
    Text = "<Mudar>Nós somos bonitos o suficiente agora?"
  },
  AvgDialog_120298_Content_45 = {
    Text = "<Mudar>Pode agora ficarmos juntos com meu senhor para sempre?"
  },
  AvgDialog_120298_Content_46 = {
    Text = "Um fantasma maciço subiu ao céu das costas de Xu, um, dois, três... incontáveis bocas com dentes de dragão surgiram da pele inchada, pingando saliva, ansiosas para escolher e devorar."
  },
  AvgDialog_120298_Content_47 = {
    Text = "Os tentáculos semelhantes a penas se estendem por todo o pátio da família He, encobrindo toda a luz e silenciando todos os sons."
  },
  AvgDialog_120298_Content_48 = {
    Text = "Sua visão está envolta em névoa, e tudo que você pode sentir é a estranha fragrância que emana de Xu e os sons estranhos e lentos de um banquete."
  },
  AvgDialog_120298_Content_49 = {Text = "..."},
  AvgDialog_120298_Content_5 = {
    Text = "Minha filha estúpida não disse uma coisa errada... Eu consigo sentir o cheiro."
  },
  AvgDialog_120298_Content_50 = {
    Text = "Após o som contínuo de sucção parar, He Fang se levantou em silêncio e caminhou para fora, ficando entre um grupo de homens que também aguardavam em silêncio."
  },
  AvgDialog_120298_Content_51 = {
    Text = "Inspetores, presidentes, presidentes de mesa... Suas esposas estão ao lado dos homens, a luz do sol nascente ofuscando você, e você vê o mesmo sorriso misterioso em seus rostos que o de Xu."
  },
  AvgDialog_120298_Content_52 = {Text = "..."},
  AvgDialog_120298_Content_53 = {
    Text = "Onde quer que você diga que seu poder está conectado a ele, agora que ele se tornou assim, você vai desaparecer?"
  },
  AvgDialog_120298_Content_54 = {
    Text = "O que é a primeira coisa que minha pequena jasmim pergunta? Verdadeiramente... estou tão emocionado."
  },
  AvgDialog_120298_Content_55 = {
    Text = "Seus dedos deslizam sobre sua testa, finalmente repousando na ponta do seu nariz."
  },
  AvgDialog_120298_Content_56 = {
    Text = "Talvez sim, talvez... não, mas você gostaria de ser meu mestre?"
  },
  AvgDialog_120298_Content_57 = {
    Text = "Xu agarrou levemente no ar, puxando um lenço de seda tão fino quanto a asa de um gafanhoto. Mergulhando o pincel prateado na tinta, ele se desdobrou diante de você."
  },
  AvgDialog_120298_Content_58 = {
    Text = "Eu lhe darei tudo o que não foi obtido, assim como o melhor do mundo."
  },
  AvgDialog_120298_Content_59 = {
    Text = "Quando minha mãe estava viva, Haicheng foi varrido por uma nova tendência, e você tinha lido livros e praticado a escrita."
  },
  AvgDialog_120298_Content_6 = {
    Text = "<Shake:<Red:Aqueles homens...>>"
  },
  AvgDialog_120298_Content_60 = {
    Text = "Xu pegou sua mão, esperando que você começasse a escrever, e você... qual era mesmo o seu nome?"
  },
  AvgDialog_120298_Content_61 = {
    Text = "O espelho de cobre salpicado com líquido vermelho fresco reflete os traços delicados e jovens de uma pessoa oriental, assemelhando-se a um aglomerado de jasmim pálido e frágil."
  },
  AvgDialog_120298_Content_62 = {
    Text = "Você piscou em confusão, e a garotinha no reflexo piscou de volta. \n Você se lembrou, o pano de seda tinha sua caligrafia infantil, e seu nome era—"
  },
  AvgDialog_120298_Content_63 = {Text = "He Fang."},
  AvgDialog_120298_Content_64 = {Text = "..."},
  AvgDialog_120298_Content_65 = {
    Text = "Então, a líder daquela sociedade secreta que mais tarde apareceu em Haicheng é uma garotinha do mesmo tamanho que Jenkins?!"
  },
  AvgDialog_120298_Content_66 = {
    Text = "Sua cabeça está doendo severamente devido aos efeitos colaterais do sonho, e você é surpreendido pela mulher que aparece silenciosamente depois que você acorda."
  },
  AvgDialog_120298_Content_67 = {
    Text = "O dormitório de Mythag realmente deveria implementar algumas medidas de segurança. Com isso em mente, você começa a pensar sobre o que poderia protegê-lo dessa mulher que nem mesmo poupa crianças."
  },
  AvgDialog_120298_Content_68 = {
    Text = "...De acordo com os registros, nas lendas do Extremo Oriente, há um antigo deus maligno conhecido como <Red:\"A Matriarca Obsidiana de Mil Fans\">. Ele se deleita em manipular os corações dos homens e se alimenta da matéria cerebral daqueles que nutrem desejos por Ele."
  },
  AvgDialog_120298_Content_69 = {
    Text = "Mesmo que você só consiga ver os olhos dela, fica claro que a mulher à sua frente está sorrindo feliz. Ela está descansando preguiçosamente o queixo na mão, e você não pode deixar de se perguntar se seu olhar poderia fazer até mesmo um esfregão parecer afetuoso."
  },
  AvgDialog_120298_Content_7 = {
    Text = "Você achou que poderia me enganar? Não se esqueça, sou eu quem pessoalmente o convocou com o <Red:\"cadáver\"> da minha esposa; como eu poderia confundir esse cheiro?"
  },
  AvgDialog_120298_Content_70 = {
    Text = "Você me entende tão bem, isso realmente me deixa muito feliz."
  },
  AvgDialog_120298_Content_71 = {
    Text = "Aquele homem tolo pôs as mãos em um pergaminho antigo, querendo me invocar para lançar feitiços de engano, matando incontáveis pessoas, e no final, até sua amada esposa, que o amava de todo coração, não foi poupada."
  },
  AvgDialog_120298_Content_72 = {
    Text = "Originalmente, foi apenas o ódio de sua esposa que me fez achar engraçado, querendo deixá-la provar de seu inimigo."
  },
  AvgDialog_120298_Content_73 = {
    Text = "Mas, naquela época, Shencheng estava cheia do fedor avassalador de decadência e malícia, me fazendo... relutante em partir."
  },
  AvgDialog_120298_Content_74 = {
    Text = "...Na verdade, você não precisa de um Linker, certo?"
  },
  AvgDialog_120298_Content_75 = {
    Text = "Li os \"registros de armazenamento de Prata.\" Você é perfeitamente capaz de completar a Cerimônia de Despertar por conta própria. Manter sua sanidade será fácil para você."
  },
  AvgDialog_120298_Content_76 = {
    Text = "Qual é o seu propósito em se conectar ativamente com He Fang em Haicheng?"
  },
  AvgDialog_120298_Content_77 = {
    Text = "Xu permaneceu em silêncio, uma leve névoa girando ao seu redor, aliviando delicadamente a pressão em sua cabeça. Ela piscou para você por trás da tela."
  },
  AvgDialog_120298_Content_78 = {
    Text = "Eu originalmente pensei que neste mundo, não havia diferença entre adultos e adultos, mas cada criança é diferente da outra."
  },
  AvgDialog_120298_Content_79 = {
    Text = "Eu a alimento com névoa e a rego com poder e desejo. Eu a amo, então por que você ainda vem me punir?"
  },
  AvgDialog_120298_Content_8 = {
    Text = "Se não fosse pela sua intimidade com eles, por que eles emitiriam um cheiro que pertence a <Red:seu aroma>?"
  },
  AvgDialog_120298_Content_80 = {
    Text = "Isso não é amor"
  },
  AvgDialog_120298_Content_81 = {Text = "..."},
  AvgDialog_120298_Content_82 = {
    Text = "Hehe, eu realmente não entendo o que é o amor humano. Eu vou oferecer os melhores presentes deste mundo: comida, brinquedos e o poder de chamar um cervo de cavalo."
  },
  AvgDialog_120298_Content_83 = {
    Text = "E claro... receberei o pagamento que desejo em troca. E no dia em que te encontrares em necessidade, minha Pequena Jasmim... como é que <Italic:tu> vais escolher?"
  },
  AvgDialog_120298_Content_84 = {
    Text = "No meu mundo dos sonhos, estou sempre disposto a esperar pela sua chegada, a qualquer momento, em qualquer lugar."
  },
  AvgDialog_120298_Content_85 = {
    Text = "Suavemente, entre as risadas delicadas e brincalhonas, a névoa se espalhou—no momento seguinte, apenas o perfume de magnólia permaneceu no dormitório."
  },
  AvgDialog_120298_Content_9 = {
    Text = "Ele riu nervosamente de repente, inclinando-se para frente e segurando o pulso de Xu que segurava o leque."
  },
  AvgDialog_120313_Content_1 = {
    Text = [[
Enquanto isso
fora do Sol Negro]]
  },
  AvgDialog_120313_Content_10 = {
    Text = "Além do mundo de bilhões de estrelas cintilantes, aquela figura luta para romper as turbulências, avançando passo a passo em sua direção."
  },
  AvgDialog_120313_Content_11 = {Text = "Ramona!!!"},
  AvgDialog_120313_Content_12 = {
    Text = "Você viu claramente o contorno dela, seu rosto, seus olhos brilhando de alegria, não era mais uma ilusão falsa, não havia mais apenas uma voz abafada."
  },
  AvgDialog_120313_Content_13 = {
    Text = "As ondas de energia conectadas pelo túnel sibilam e fazem seu cabelo flutuar, finalmente, suas pontas dos dedos se tocam e, em seguida, se abraçam fortemente."
  },
  AvgDialog_120313_Content_14 = {
    Text = "Saudade de outro mundo se transforma em um halo branco, girando e fluindo através da sua alma."
  },
  AvgDialog_120313_Content_15 = {
    Text = "<Shake:<color=#DEDEDE>Finalmente... te encontrei.</color>>"
  },
  AvgDialog_120313_Content_16 = {
    Text = "Suas cabeças se tocaram, e suas mãos a abraçaram carinhosamente em suas costas, sua voz tremia de emoção e lágrimas de alegria."
  },
  AvgDialog_120313_Content_17 = {
    Text = "Toda a fadiga, solidão e dor se dissipam neste momento, e você sabe que sua alma retornou ao seu verdadeiro lar."
  },
  AvgDialog_120313_Content_18 = {
    Text = "Viajar entre dimensões é muito perigoso, você se machucou?"
  },
  AvgDialog_120313_Content_19 = {
    Text = "Você se lembrou de algo, examinando repetidamente a alma que havia percorrido um longo caminho à sua frente, apenas para ver sua figura um pouco magra. Ramona balançou a cabeça e acariciou seu rosto."
  },
  AvgDialog_120313_Content_2 = {
    Text = "Chegada, destruição, renascimento… resistência, batalha, perseverança…"
  },
  AvgDialog_120313_Content_20 = {
    Text = "E você? Estando sozinho em um mundo desconhecido por tanto tempo, você deve ter tido muita dificuldade, não é."
  },
  AvgDialog_120313_Content_21 = {
    Text = "Seu nariz ficou ácido, você também balançou a cabeça, e, em meio aos olhares que se cruzavam, entre as lágrimas que pairavam em seus olhos, vocês sorriram ao mesmo tempo."
  },
  AvgDialog_120313_Content_22 = {
    Text = "Por que rir, como um idiota."
  },
  AvgDialog_120313_Content_23 = {
    Text = "Você também não está rindo..."
  },
  AvgDialog_120313_Content_24 = {
    Text = "No imenso felicidade, você não consegue resistir e segura a mão dela, querendo imediatamente começar o caminho de volta."
  },
  AvgDialog_120313_Content_25 = {
    Text = "Um som nauseante e úmido de dilaceração se ergue no ar. Enormes patas de aranha irrompem pelos corpos dos oficiais e dos transeuntes, espirrando sangue espesso com cheiro de ferro por todo você."
  },
  AvgDialog_120313_Content_26 = {
    Text = "De repente, você viu as pupilas dela se contraírem rapidamente, e num instante, ela se lançou sobre você, te empurrando com força para o lado."
  },
  AvgDialog_120313_Content_27 = {
    Text = "No momento em que você foi lançado para trás, viu que, no lugar onde antes estava Ramona, uma nova Fissura Dimensional se abria, e mais um olho estava se movendo e se abrindo, olhando para Ramona que ficou para trás."
  },
  AvgDialog_120313_Content_28 = {
    Text = "Num instante, o muco negro a consumiu."
  },
  AvgDialog_120313_Content_29 = {
    Text = "<Shake:<Big:Não!!!>>"
  },
  AvgDialog_120313_Content_3 = {
    Text = "Sob a intimidação da Vontade Suprema, tudo é tão familiar."
  },
  AvgDialog_120313_Content_4 = {
    Text = "Os enormes olhos pálidos na dimensão alternativa se desfazem um a um, sua mente também está lentamente se esgotando, o único que ainda te sustenta é a rosa vermelha em sua mão."
  },
  AvgDialog_120313_Content_5 = {
    Text = "Ufa... não posso cair, eles ainda estão esperando por mim..."
  },
  AvgDialog_120313_Content_6 = {
    Text = "Em um estado de transe, seu coração de repente começou a bater intensamente, e você se virou seguindo essa intuição."
  },
  AvgDialog_120313_Content_7 = {
    Text = "Parece que uma estrela cadente passou, e como se cristais de gelo se formassem, um túnel em forma de feixe de luz se estende acompanhado de um som estranho e etéreo."
  },
  AvgDialog_120313_Content_8 = {
    Text = "Uma voz que ecoou em sua memória milhares de vezes atravessa o distante espaço dimensional atrás de você, ressoando em sua mente através da conexão de seus tentáculos espirituais."
  },
  AvgDialog_120313_Content_9 = {
    Text = "<Yellow:%player%>!!!"
  },
  AvgDialog_121232_Content_1 = {
    Text = "O brilho da minha pátria já brilha diante dos meus olhos, senhor Goliath, agora deixo tudo com você..."
  },
  AvgDialog_121232_Content_2 = {
    Text = "O poder divino que flui... é um pouco semelhante àquela mulher louca."
  },
  AvgDialog_121232_Content_3 = {
    Text = "Certo, aquele pequeno ali, agora prepare-se para ver a força dos filisteus, que está acima da bênção!"
  },
  AvgDialog_121369_Content_1 = {
    Text = "No salão vazio, apenas os passos seus e de Murphy ecoam."
  },
  AvgDialog_121369_Content_10 = {
    Text = "Sem tempo para entender a situação, tentáculos frios se enrolaram em sua panturrilha, uma força colossal pressionando você a se ajoelhar."
  },
  AvgDialog_121369_Content_11 = {
    Text = "Você tenta resistir, mas a toxina paralisante penetra nos nervos, fazendo você perder a força."
  },
  AvgDialog_121369_Content_12 = {
    Text = "Murphy, o que você está fazendo?!"
  },
  AvgDialog_121369_Content_13 = {
    Text = "Não sei por quê, mas estou me sentindo muito irritado."
  },
  AvgDialog_121369_Content_14 = {
    Text = "Há fogo queimando dentro de mim, e ao ver você, ele queima ainda mais forte."
  },
  AvgDialog_121369_Content_15 = {
    Text = "(Calma, calma. Não podemos fazer nada que prejudique a majestade da Mãe Divina.)"
  },
  AvgDialog_121369_Content_16 = {
    Text = "Então... o que você realmente quer que eu faça aqui, ajoelhar-me?"
  },
  AvgDialog_121369_Content_17 = {
    Text = "Ajoelhe-se sem questionar!"
  },
  AvgDialog_121369_Content_18 = {
    Text = "O tom de Murphy parecia ainda estar cheio de raiva, e o tentáculo do polvo batia ansiosamente em sua perna. Parece que só posso contar comigo mesmo."
  },
  AvgDialog_121369_Content_19 = {
    Text = "Você força sua cabeça para cima, lutando contra a força da toxina paralisante, e toca sua bochecha ruborizada."
  },
  AvgDialog_121369_Content_2 = {
    Text = "Desde agora, você não disse nada."
  },
  AvgDialog_121369_Content_20 = {
    Text = "Murphy, você... foi interferido pela força do Rio Sagrado?"
  },
  AvgDialog_121369_Content_21 = {
    Text = "Liberar! Eu, como Mãe Divina, como posso ser influenciada por essa estupidez..."
  },
  AvgDialog_121369_Content_22 = {
    Text = "Os tentáculos do anel azul rastejam pelas suas costas, deixando uma sensação de coceira por onde passam."
  },
  AvgDialog_121369_Content_23 = {
    Text = "Fique aqui direitinho até o amanhecer."
  },
  AvgDialog_121369_Content_24 = {
    Text = "Não se mexa!"
  },
  AvgDialog_121369_Content_25 = {
    Text = "Mas você sente que a restrição do seu tentáculo está um pouco mais solta, parece que uma nuvem está te sustentando, mas quando você tenta se libertar, não permite que você se mova nem um pouco."
  },
  AvgDialog_121369_Content_26 = {
    Text = "Agradeça, você terá a honra de receber a aurora ao lado da Mãe Divina."
  },
  AvgDialog_121369_Content_27 = {
    Text = "Como retribuição…"
  },
  AvgDialog_121369_Content_28 = {
    Text = "A respiração dela paira ao seu redor. Então, um beijo suave e delicado pousa na sua testa."
  },
  AvgDialog_121369_Content_29 = {
    Text = "Você também receberá a bênção da Mãe Divina."
  },
  AvgDialog_121369_Content_3 = {
    Text = "O que aconteceu, Murphy?"
  },
  AvgDialog_121369_Content_4 = {
    Text = "Murphy não respondeu, apenas caminhou diretamente em direção ao topo da escada, onde estava o trono."
  },
  AvgDialog_121369_Content_5 = {
    Text = "Você a seguiu de perto, até que ela finalmente se sentou de lado no trono, com um olhar ligeiramente irritado que te fuzilava."
  },
  AvgDialog_121369_Content_6 = {
    Text = "Quem te permitiu ficar ao meu lado? Fique mais baixo, não me olhe de cima."
  },
  AvgDialog_121369_Content_7 = {
    Text = "Você está confuso, mas ainda assim recua dois passos, sua visão se alinhando com a da menina no trono."
  },
  AvgDialog_121369_Content_8 = {
    Text = "Ajoelhe-se."
  },
  AvgDialog_121369_Content_9 = {Text = "Ha?"},
  AvgDialog_121741_Content_1 = {
    Text = "Gigante, podridão, nada... sustentando a ilusão acima da \"cortina\" com uma fantasia absurda..."
  },
  AvgDialog_121741_Content_2 = {
    Text = "Eu, viciado no \"paraíso\", sou tão tolo e ridículo..."
  },
  AvgDialog_121741_Content_3 = {
    Text = "%player%, ajude-me a acabar com este sonho de uma vez por todas."
  },
  AvgDialog_121741_Content_4 = {
    Text = "Ajude-me a recuperar... meu destino."
  },
  AvgDialog_121742_Content_1 = {
    Text = "As correntes tremem, o olhar do monstro atrás da cortina percorre toda a embarcação, emitindo um lamento desesperado."
  },
  AvgDialog_121742_Content_10 = {
    Text = "Adeus, frágil e impotente \"ontem\"...!"
  },
  AvgDialog_121742_Content_2 = {
    Text = "Entendi… eu entendo tudo… sua saudade, as coisas que você não consegue deixar para trás…"
  },
  AvgDialog_121742_Content_3 = {
    Text = "Mas eu já tomei consciência."
  },
  AvgDialog_121742_Content_4 = {
    Text = "Murphy olhou para Ele, hesitou por um momento e, como se tivesse tomado uma decisão, lhe ofereceu um sorriso suave."
  },
  AvgDialog_121742_Content_5 = {
    Text = "Por favor, deem uma olhada... aquele coração dentro do meu peito..."
  },
  AvgDialog_121742_Content_6 = {
    Text = "Até hoje, ainda pulsa com vida."
  },
  AvgDialog_121742_Content_7 = {
    Text = "Assim como na cerimônia de navegação, Murphy abriu seu peito."
  },
  AvgDialog_121742_Content_8 = {
    Text = "Para sair daqui, para o dia em que nos encontraremos novamente em Misaq."
  },
  AvgDialog_121742_Content_9 = {
    Text = "O sangue espiritual escorre do peito de Murphy, com fios prateados entrelaçados, insistindo em rasgar o véu acima do céu."
  },
  AvgDialog_121743_Content_1 = {
    Text = "Você não sabe há quanto tempo está lutando, apenas sente seu cérebro começando a girar e seus braços se tornando pesados, enquanto aquele enorme monstro pálido e esquelético continua a brandir seus braços quebrados e renascidos sem se cansar."
  },
  AvgDialog_121743_Content_10 = {
    Text = "A promessa de William parece erguer uma barreira invisível atrás de você, e a confiança forjada ao longo dos anos faz com que a força quase exaurida surja novamente das profundezas da medula."
  },
  AvgDialog_121743_Content_11 = {
    Text = "Combinamos de voltar juntos."
  },
  AvgDialog_121743_Content_12 = {
    Text = "Que a Chave de prata ilumine o meu caminho."
  },
  AvgDialog_121743_Content_13 = {
    Text = "Que a Chave de Prata nos guie"
  },
  AvgDialog_121743_Content_2 = {
    Text = "O suor escorre da sua testa, embaçando sua visão, mas você mal consegue levantar a mão para limpar."
  },
  AvgDialog_121743_Content_3 = {Text = "Maldito..."},
  AvgDialog_121743_Content_4 = {
    Text = "%player%, aguente firme."
  },
  AvgDialog_121743_Content_5 = {
    Text = "Uma capa negro-vermelha flutua à sua frente, enquanto um braço mecânico preciso bloqueia os ataques pesados dos ossos pálidos que se aproximam."
  },
  AvgDialog_121743_Content_6 = {
    Text = "Os membros longos atacam furiosamente novamente, mas são bloqueados mais uma vez, fragmentos caem ao seu lado, levantando uma fumaça que se eleva."
  },
  AvgDialog_121743_Content_7 = {Text = "William?"},
  AvgDialog_121743_Content_8 = {
    Text = [[
Concentre-se, olhe para Ele.
Deixe suas costas comigo.]]
  },
  AvgDialog_121743_Content_9 = {
    Text = "Neste novo mundo... eu assumirei temporariamente a tarefa de seu parceiro. \n Até o dia em que retornarmos juntos a Misaq."
  },
  AvgDialog_121744_Content_1 = {
    Text = "O monstro ruge e chora, a cortina oculta se rasga, e seu corpo emerge do fundo do Mar Profundo."
  },
  AvgDialog_121744_Content_10 = {
    Text = "Não saber usar bem a força e entregar o destino nas mãos de outros não é o estilo dos filisteus."
  },
  AvgDialog_121744_Content_11 = {
    Text = "O gigante brandiu sua arma, apontando a ponta da lâmina enorme para aquele imenso bloco de carne que estava se transformando."
  },
  AvgDialog_121744_Content_12 = {
    Text = "Então, chega de conversa, prepare-se para lutar!"
  },
  AvgDialog_121744_Content_13 = {
    Text = "Somente o vencedor tem o direito de sobreviver."
  },
  AvgDialog_121744_Content_2 = {
    Text = "Droga...! Ele ainda está expandindo!"
  },
  AvgDialog_121744_Content_3 = {
    Text = "Um relâmpago rasgou o céu noturno escuro, a lâmina sanguinária acompanhada de relâmpagos roxos e negros desceu violentamente em direção aos membros pálidos e frágeis do véu."
  },
  AvgDialog_121744_Content_4 = {
    Text = "...Miryam? Goliath? Por que vocês estão aqui?"
  },
  AvgDialog_121744_Content_5 = {
    Text = "A decisão da Mãe Divina está tomada, nós devemos, como a nova Mãe Divina, cortar este pesado \"véu\" de desgraça."
  },
  AvgDialog_121744_Content_6 = {Text = "Miryam..."},
  AvgDialog_121744_Content_7 = {
    Text = "Fique tranquila, Mãe Divina. Não importa quais sejam seus planos futuros, os Marchadores de mares serão a base mais sólida e firme atrás de você."
  },
  AvgDialog_121744_Content_8 = {
    Text = "Não fique enrolando, vamos ficar de braços cruzados vendo vocês dois pequenos enfrentarem esse cara?"
  },
  AvgDialog_121744_Content_9 = {
    Text = "Uma voz familiar surgiu de repente, interrompendo as palavras de Murphy. Era Goliath e Caecus."
  },
  AvgDialog_121745_Content_1 = {
    Text = "O monstro erguido levantou a cabeça orgulhosamente, \"olhando\" para todos vocês a partir do manto sombrio."
  },
  AvgDialog_121745_Content_10 = {
    Text = "Por favor, você e aquele como eu... sejam eternamente enterrados no vasto mar profundo!"
  },
  AvgDialog_121745_Content_2 = {Text = "...!!!"},
  AvgDialog_121745_Content_3 = {
    Text = "Um certo vínculo invisível penetra verdadeiramente entre ela e Ele, inescapável, fazendo com que a menina visse suas feridas, seu soluço e até sua dúvida…"
  },
  AvgDialog_121745_Content_4 = {
    Text = "Como um bebê ferido, questionando a \"traição\" da mãe."
  },
  AvgDialog_121745_Content_5 = {
    Text = "Não me olhe, não me interrogue... Eu já tomei uma decisão. Esta é a minha última \"traição\"."
  },
  AvgDialog_121745_Content_6 = {
    Text = "Uma vez, eu fiz um desejo ao \"Paraíso\", um \"Sonho\" que eu ansiava na minha infância."
  },
  AvgDialog_121745_Content_7 = {
    Text = "Eu pensei que o \"poder\" poderia me trazer \"felicidade\", mas isso acabou sendo apenas um sonho ilusório..."
  },
  AvgDialog_121745_Content_8 = {
    Text = "Murphy sorriu enquanto enxugava as lágrimas do canto dos olhos. Ela limpou lentamente e com cuidado, até que a última marca de lágrima desapareceu completamente, então ergueu a cabeça e olhou para aquele imenso \"eu\"."
  },
  AvgDialog_121745_Content_9 = {
    Text = "Não preciso de Paraíso, não preciso enganar a mim mesmo com sonhos bonitos. Não preciso mais."
  },
  AvgDialog_121858_Content_1 = {
    Text = "De seus pés jorram milhares de monstros, e vocês os matam um a um. \n Pisando sobre milhares de cadáveres, vocês chegam aos pés da enorme silhueta."
  },
  AvgDialog_121858_Content_10 = {
    Text = "Desta vez, não permitirei que a vida de ninguém seja trocada por vitória."
  },
  AvgDialog_121858_Content_11 = {
    Text = "Prepare-se para a batalha, a \"cortina\" que acabará por murchar!"
  },
  AvgDialog_121858_Content_2 = {
    Text = "Esta é a minha vontade, a vontade do \"Paraíso\"..."
  },
  AvgDialog_121858_Content_3 = {
    Text = "\"Filho\" nunca pertenceu à \"mãe\", e após seu nascimento, Ele também desenvolveu seu próprio \"desejo\"."
  },
  AvgDialog_121858_Content_4 = {
    Text = "<Red:Sonho... deve... continuar...>"
  },
  AvgDialog_121858_Content_5 = {
    Text = "Você disse que, basta matar o controlador dos sonhos, que o poder será transferido para você..."
  },
  AvgDialog_121858_Content_6 = {
    Text = "Sim. Você já tomou consciência?"
  },
  AvgDialog_121858_Content_7 = {
    Text = "Não, ela não precisa fazer esse sacrifício."
  },
  AvgDialog_121858_Content_8 = {
    Text = "...%player%!"
  },
  AvgDialog_121858_Content_9 = {
    Text = "O \"núcleo\" do domínio, a \"catástrofe\" que se manifesta, deste tamanho, já não me lembro quantas vezes enfrentei isso."
  },
  AvgDialog_121859_Content_1 = {
    Text = "Ele exerce uma força dentro do véu... está mudando..."
  },
  AvgDialog_121859_Content_2 = {
    Text = "Abandonado, deixado de lado... Ele está em descontentamento, em raiva, em lamento..."
  },
  AvgDialog_121859_Content_3 = {
    Text = "Sua ira se derramará sobre vocês...!"
  },
  AvgDialog_121864_Content_1 = {
    Text = "É tão surpreendente? Porque o oráculo está me chamando, além do véu..."
  },
  AvgDialog_121865_Content_1 = {
    Text = "Meu sangue está incitando, e o abismo está cantando em uníssono, me fazendo um convite!"
  },
  AvgDialog_121866_Content_1 = {
    Text = "Ó divindade distante, seu devoto servidor lhe oferecerá uma pequena contribuição…"
  },
  AvgDialog_121867_Content_1 = {
    Text = "Sortudo, isso vai te mostrar a força dos filisteus!"
  },
  AvgDialog_122640_Content_1 = {
    Text = "<Shake:Boom!——>"
  },
  AvgDialog_122640_Content_2 = {
    Text = "O olhar de loucura fez toda a dimensão começar a tremer, o link de Ramona com você foi ocultado pela dissolução, desaparecendo sem deixar rastro."
  },
  AvgDialog_122640_Content_3 = {
    Text = "Você respirou fundo, forçando a reprimir a inquietação gerada pela loucura."
  },
  AvgDialog_122640_Content_4 = {
    Text = "Deixe essa loucura para você...<Big:Não deixarei que essa sua loucura machuque mais ninguém!>"
  },
  AvgDialog_122641_Content_1 = {
    Text = "...@3!! ..."
  },
  AvgDialog_122641_Content_2 = {
    Text = "Intimidação familiar. Olhar familiar. Uma dor familiar que quase rasga seu cérebro."
  },
  AvgDialog_122641_Content_3 = {
    Text = "Hoo... Nos encontramos de novo, Toguwaibo, o supremo Deus... Embora você não possa ouvir, eu preciso agradecer a você."
  },
  AvgDialog_122641_Content_4 = {
    Text = "Você já me fez morrer uma vez, e nessa morte, eu compreendi uma verdade universal..."
  },
  AvgDialog_122641_Content_5 = {
    Text = "Você aperta a Chave de prata com força, encarando o olhar projetado pela vontade Dele—e só depois perceberá que estava <Italic:sorrindo.>"
  },
  AvgDialog_122641_Content_6 = {
    Text = "Você me fez saber que, neste magnífico sonho seu, nada é imutável, nada é invencível."
  },
  AvgDialog_122641_Content_7 = {
    Text = "Para nos encontrarmos novamente, já esperamos por muito tempo... Mesmo você, não poderá bloquear nosso caminho!"
  },
  AvgDialog_122642_Content_1 = {
    Text = "...@2... @2... @1@3...!!"
  },
  AvgDialog_122642_Content_2 = {
    Text = "Um forte impacto faz com que toda a dimensão comece a se fragmentar. Você abre seus olhos vermelhos, olhando para aquele olho que se aproxima cada vez mais da realidade."
  },
  AvgDialog_122642_Content_3 = {
    Text = "Sua consciência também chegou ao limite, Toguwaibo... Agora, continue a dormir bem!"
  },
  AvgDialog_122642_Content_4 = {
    Text = "Você se revigora com a energia espiritual quase esgotada e canaliza seu último poder espiritual na chave de prata."
  },
  AvgDialog_122642_Content_5 = {
    Text = "Você segura a luz prateada como uma lâmina afiada e a crava na divindade à sua frente —"
  },
  AvgDialog_122643_Content_1 = {
    Text = "<Big:<Shake:Ramona!!!>>"
  },
  AvgDialog_122643_Content_2 = {
    Text = "A figura familiar é engolida pela dissolução trazida pelo olhar, um antigo e maligno feitiço aparece de forma tênue nesse olhar."
  },
  AvgDialog_122643_Content_3 = {
    Text = "Esses cânticos acabam por aqui...!"
  },
  AvgDialog_122644_Content_1 = {
    Text = "O mundo desmorona e se reconstrói diante de você, entes queridos morrem e renascem diante de você. Aquele olhar confuso traz todo o caos do universo para a sua mente."
  },
  AvgDialog_122644_Content_2 = {
    Text = "Desordem, confusão, perplexidade... o que seu poder traz ainda são essas coisas."
  },
  AvgDialog_122644_Content_3 = {
    Text = "Seu olhar nunca me confundiu, Toguwaibo. Foi assim no passado, e assim é agora."
  },
  AvgDialog_122644_Content_4 = {
    Text = "A luz prateada brilha. Em meio a essas ilusões intermináveis, você encontrou o caminho para confrontá-la —"
  },
  AvgDialog_122645_Content_1 = {
    Text = "Em uma dimensão distante, um ponto de luz está piscando suavemente."
  },
  AvgDialog_122645_Content_2 = {
    Text = "Isso é... o \"Coração Santo\" de Pólux?"
  },
  AvgDialog_122645_Content_3 = {
    Text = "A busca deles também já começou... Agora, eles devem estar em perigo."
  },
  AvgDialog_122645_Content_4 = {
    Text = "Eu ainda me lembro do medo que senti ao enfrentar você pela primeira vez, Toguwaibo. Desta vez, não vou deixá-los esperando!"
  },
  AvgDialog_122646_Content_1 = {
    Text = "Uma dor aguda atinge cada osso e cada centímetro de sua carne. Você suporta essa dor lancinante e sorri com dificuldade."
  },
  AvgDialog_122646_Content_2 = {
    Text = "Deuses idiotas, vocês não sabem que em seus sonhos há muitos sofrimentos que vão muito além do corpo..."
  },
  AvgDialog_122646_Content_3 = {
    Text = "Essa dor, eu não deixarei que apareça novamente!"
  },
  AvgDialog_122694_Content_1 = {
    Text = "A porta no meio do corredor já está coberta de geada branca, e a geada parece estar se espalhando."
  },
  AvgDialog_122694_Content_10 = {
    Text = "Por favor, Guardião do segredo, me abraça — só um pouquinho, só um pouco de calor é tudo que preciso~ A Fada vai lembrar da sua bondade para sempre."
  },
  AvgDialog_122694_Content_11 = {
    Text = "É a primeira vez que você vê essa pequena vigarista com uma expressão assim, mas uma desconfiança persistente mantém você parado onde está, com o hálito formando névoa branca, apenas movendo os membros para se aquecer."
  },
  AvgDialog_122694_Content_12 = {
    Text = "Já notifiquei a administração. Eles virão ajudar em breve. Fique onde está, não se mova, não faça nada."
  },
  AvgDialog_122694_Content_13 = {
    Text = "Mas eu estou me sentindo tão mal agora... O poder daquele rio me arrastou de volta àquele lugar pálido... gelado... terrível..."
  },
  AvgDialog_122694_Content_14 = {
    Text = "Sem aviso, as lágrimas de Caraboo caem direto para baixo, como se ela realmente tivesse acabado de testemunhar algo aterrorizante."
  },
  AvgDialog_122694_Content_15 = {
    Text = "Acho que não vou aguentar até a ajuda chegar, Guardião do segredo. Sinto muito... por sempre ter mentido para você antes..."
  },
  AvgDialog_122694_Content_16 = {
    Text = "Cristais de gelo se espalham com ela como centro, e ela parece indefesa, frágil, com os olhos avermelhados enquanto te encara — balançando, como se pudesse desabar a qualquer segundo."
  },
  AvgDialog_122694_Content_17 = {Text = "Caraboo!"},
  AvgDialog_122694_Content_18 = {
    Text = "No instante antes de ela tocar o chão, você se lança e a segura afinal — e no segundo seguinte, se arrepende."
  },
  AvgDialog_122694_Content_19 = {
    Text = "Aqueles braços gelados se enrolam ao seu redor com a facilidade mole de alguma criatura invertebrada, e um sopro coberto de cristais de neve escorre pelo oco do seu pescoço e pela curva do seu ouvido."
  },
  AvgDialog_122694_Content_2 = {
    Text = "Você se prepara e, lutando contra um frio tão violento que seus dentes rangem a ponto de quase morder a própria língua, empurra a porta do quarto de Caraboo."
  },
  AvgDialog_122694_Content_20 = {
    Text = "Hee hee~ Que coisa, eu sabia. %player% é mesmo um coração mole."
  },
  AvgDialog_122694_Content_21 = {
    Text = "Atrás dela, algo mais suave e ainda mais frio se envolve lenta e languidamente ao seu redor, afundando você através de camada após camada de neve profunda."
  },
  AvgDialog_122694_Content_22 = {
    Text = "Você se debate, sons abafados presos em sua garganta, e pouco antes de desmaiar completamente, você ouve aquela risadinha astuta."
  },
  AvgDialog_122694_Content_23 = {
    Text = "Tudo bem. Sua Fada será muito, muito gentil com seu cordeirinho mais precioso~"
  },
  AvgDialog_122694_Content_3 = {
    Text = "Caraboo, o que você fez aqu— sss, está congelando aqui dentro."
  },
  AvgDialog_122694_Content_4 = {
    Text = "Mas aquela figurinha ágil e travessa não aparece de forma deslumbrante para exibir sua mais nova peça, como sempre faz."
  },
  AvgDialog_122694_Content_5 = {
    Text = "Há um rubor incomum em seu rosto. Ela parece, bem, quase... digna de pena."
  },
  AvgDialog_122694_Content_6 = {
    Text = "Guardião do segredo, o que eu faço~? Estou me sentindo muito mal. Meu corpo está estranho, minha cabeça também."
  },
  AvgDialog_122694_Content_7 = {
    Text = "Estou com tanto frio. Quase morrendo de frio aqui mesmo."
  },
  AvgDialog_122694_Content_8 = {
    Text = "E também estou com tanto calor — calor suficiente para enfraquecer minhas pernas, não consigo dar um único passo."
  },
  AvgDialog_122694_Content_9 = {
    Text = "Ela morde o lábio inferior e, com os olhos marejados de lágrimas, abre os braços em sua direção — a postura de uma criança implorando para ser abraçada."
  },
  AvgDialog_122696_Content_1 = {
    Text = "No salão vazio, apenas os passos de você e Murphy ecoam."
  },
  AvgDialog_122697_Content_1 = {
    Text = "Hoje o céu escurece mais rápido do que o habitual, e está sombrio, indicando claramente que vai chover."
  },
  AvgDialog_122697_Content_10 = {
    Text = "Mouchette ergueu a cabeça, seu rosto tingido com um rubor anormal, revelando um sorriso misturado com confusão e fervor."
  },
  AvgDialog_122697_Content_11 = {
    Text = "Lute comigo, agora, imediatamente!"
  },
  AvgDialog_122697_Content_13 = {
    Text = "Antes que você possa pronunciar uma palavra, o machado dela balança. Ele roça sua bochecha com uma precisão aterrorizante, deixando para trás nada além de um assobio de ar gelado."
  },
  AvgDialog_122697_Content_14 = {
    Text = "O vento invade seu colarinho sem permissão, inundando seu peito e fazendo seu corpo se arrepiar instintivamente."
  },
  AvgDialog_122697_Content_15 = {
    Text = "Por que isso escalou para uma briga por causa de uma discordância!?"
  },
  AvgDialog_122697_Content_16 = {
    Text = "Sua pergunta foi ignorada pelo machado e seu proprietário."
  },
  AvgDialog_122697_Content_17 = {
    Text = "<Shake:Mouchette?>"
  },
  AvgDialog_122697_Content_18 = {
    Text = "Mouchette!?"
  },
  AvgDialog_122697_Content_19 = {
    Text = "Sob suas perguntas contínuas, o machado finalmente parou. Ele pressionou contra seu ombro, profundamente cravado na parede."
  },
  AvgDialog_122697_Content_2 = {
    Text = "Para evitar se molhar, você correu apressadamente em direção ao dormitório, mas uma figura bloqueou seu caminho."
  },
  AvgDialog_122697_Content_20 = {
    Text = "E o mestre do machado está bem diante de você, com o rosto ruborizado, cerrando os punhos com força e segurando seu colarinho."
  },
  AvgDialog_122697_Content_21 = {
    Text = "<Shake:Cale a boca... Está doendo... Estou sofrendo... Apenas uma luta fará isso parar...>"
  },
  AvgDialog_122697_Content_22 = {
    Text = "Os dedos que seguram sua gola continuam a exercer força, passando de uma cor carne para um tom pálido, significando a teimosia do proprietário e a recusa em ceder."
  },
  AvgDialog_122697_Content_23 = {
    Text = "Eu odeio quando os outros impõem suas ideias aos outros..."
  },
  AvgDialog_122697_Content_24 = {
    Text = "É apenas o Rio Sagrado, e você acha que ele pode me influenciar? <Shake: Você está me subestimando...>"
  },
  AvgDialog_122697_Content_25 = {
    Text = "Mouchette exalou com força enquanto falava, tentando acalmar a influência do Rio Sagrado sobre ela, mas você podia sentir o calor crescente dentro dela, o desejo errante e o conflito lutando."
  },
  AvgDialog_122697_Content_26 = {
    Text = "Percebendo as emoções de Mouchette, você não pôde deixar de suspirar, pegando a mão dela e guiando a garota a segurar o cabo do machado novamente."
  },
  AvgDialog_122697_Content_27 = {
    Text = "<Shake:O que você está fazendo?>"
  },
  AvgDialog_122697_Content_28 = {
    Text = "Você não quer lutar? Então vamos lutar."
  },
  AvgDialog_122697_Content_29 = {
    Text = "Não importa como você queira lutar, não importa por quanto tempo você queira lutar, estarei ao seu lado até o fim."
  },
  AvgDialog_122697_Content_3 = {
    Text = "Mouchette? Está algo errado?"
  },
  AvgDialog_122697_Content_30 = {Text = "..."},
  AvgDialog_122697_Content_31 = {
    Text = "Os olhos da garota de repente se arregalam, olhando para você com surpresa."
  },
  AvgDialog_122697_Content_32 = {
    Text = "Neste momento, a chuva tão planejada finalmente caiu, com gotas atingindo o rosto de Mouchette, escorregando pelo seu queixo e desaparecendo em seu colarinho, fluindo pelo seu peito."
  },
  AvgDialog_122697_Content_33 = {
    Text = "Então, mais gotas de chuva vieram, batendo furiosamente no chão, estalando nas suas bochechas e nas da menina, trazendo uma sensação de coceira."
  },
  AvgDialog_122697_Content_34 = {
    Text = "<Shake:Hahaha! Agora ESSA é a resposta que eu queria.>"
  },
  AvgDialog_122697_Content_35 = {
    Text = "As coisas estão começando a ficar interessantes, não estão?"
  },
  AvgDialog_122697_Content_36 = {
    Text = "Mouchette agarrou o cabo do machado e puxou o machado da parede, mas não o balançou novamente; em vez disso, ela olhou para você, encarando diretamente você."
  },
  AvgDialog_122697_Content_37 = {
    Text = "Normalmente, eu não luto desarmado com os outros, mas às vezes você precisa experimentar coisas novas, certo?"
  },
  AvgDialog_122697_Content_38 = {
    Text = "A vida é tão longa, e algumas coisas interessantes devem ser vivenciadas pessoalmente e gradualmente."
  },
  AvgDialog_122697_Content_39 = {
    Text = "Mouchette disse, caminhando lentamente em sua direção. E aquele machado estava quietamente encostado na parede, recebendo o batismo úmido do mundo."
  },
  AvgDialog_122697_Content_4 = {
    Text = "Ela mantém a cabeça baixa, silenciosa. Você só pode sentir sua turbulência interna pela maneira como suas articulações ficaram brancas, segurando o machado com força trêmula."
  },
  AvgDialog_122697_Content_5 = {
    Text = "<Shake:Mouchette!?>"
  },
  AvgDialog_122697_Content_6 = {
    Text = "Finalmente, a garota falou, mas sua voz carregava um toque de hesitação e incerteza."
  },
  AvgDialog_122697_Content_7 = {
    Text = "%player%, eu... eu preciso da sua ajuda..."
  },
  AvgDialog_122697_Content_8 = {
    Text = "Precisa de ajuda? Sem problemas. O que você precisa?"
  },
  AvgDialog_122697_Content_9 = {
    Text = "<Shake:Eu preciso de você...>"
  },
  AvgDialog_122700_Content_1 = {
    Text = "Bem-vindo ao meu teatro. Você chegou bem na hora, {Male=Sr., Female=Srta.} Guardião."
  },
  AvgDialog_122700_Content_10 = {
    Text = "Propagar... renascer... não me digas que tu também és—"
  },
  AvgDialog_122700_Content_11 = {
    Text = "Ah, na verdade... acabei de me lembrar que o trabalho do Professor Dor ainda não está terminado... acho que é melhor eu—"
  },
  AvgDialog_122700_Content_12 = {
    Text = "Você se virou para ir embora, mas seus passos inconscientemente o levaram adiante, até ficar diante de Arachne."
  },
  AvgDialog_122700_Content_13 = {
    Text = "Sim, eu estou sob a influência do rio... e tu estás sob o chamamento do destino. Esta noite é uma noite que pertence apenas a nós dois."
  },
  AvgDialog_122700_Content_14 = {
    Text = "Uma peça que sempre esteve destinada a ser encenada — e, finalmente, o seu protagonista predestinado chegou."
  },
  AvgDialog_122700_Content_15 = {
    Text = "A presença de Arachne já está colada ao seu ouvido, quente e sutil."
  },
  AvgDialog_122700_Content_16 = {
    Text = "O sorriso dela permanece tão sereno como sempre. Mas no fundo daqueles olhos insondáveis, algo arde: uma chama que nunca viste antes, como se pudesse consumir tudo o que toca."
  },
  AvgDialog_122700_Content_17 = {
    Text = "Não, não posso... Arachne... eu..."
  },
  AvgDialog_122700_Content_18 = {
    Text = "Não precisas de fugir, %player%. A teia teceu todas as possibilidades no seu devido lugar. Ela guiar-nos-á a ambos pela atuação desta noite."
  },
  AvgDialog_122700_Content_19 = {
    Text = "Uma teia invisível fecha-se à tua volta, drenando até ao último resquício da tua força, engolindo cada impulso de resistência."
  },
  AvgDialog_122700_Content_2 = {
    Text = "Você empurra a pesada porta do teatro, a luz da lua entra inclinada pelas altas janelas, o orvalho fresco da noite e a voz suave de Arachne no teatro fazem você acordar de repente."
  },
  AvgDialog_122700_Content_20 = {
    Text = "Os fios se esticam. Você olha para o rosto tão perto do seu, e seu coração dispara, sua respiração se acelerando."
  },
  AvgDialog_122700_Content_21 = {
    Text = "O destino dita que você nunca quis fugir. Você quis isto: <Italic:Você> quis vir aqui, quis ver esta performance até o fim, sem plateia além de vocês dois."
  },
  AvgDialog_122700_Content_22 = {
    Text = "Você... você reescreveu meu destino?!"
  },
  AvgDialog_122700_Content_23 = {
    Text = "Eu nunca reescrevi nada, {Male=Sr., Female=Srta.} Guardião. Eu apenas coloquei seu destino de volta no caminho que ele sempre deveria trilhar."
  },
  AvgDialog_122700_Content_24 = {
    Text = "Arachne... você... você pode mudar completamente o curso do destino, evitando a influência do Rio Sagrado... por que não fazer isso?"
  },
  AvgDialog_122700_Content_25 = {
    Text = "Por que eu faria?"
  },
  AvgDialog_122700_Content_26 = {
    Text = "Para uma atriz que há muito memorizou o roteiro, o inesperado é o presente mais raro que o destino já se dignou a dar..."
  },
  AvgDialog_122700_Content_27 = {
    Text = "As palavras suaves de Arachne tremulam em seu ouvido. Ela não está mais calma e distante, sua respiração treme suavemente, seu sorriso está bem perto."
  },
  AvgDialog_122700_Content_28 = {
    Text = "E por acaso... descubro que não tenho objeção a um final onde ninguém se machuca."
  },
  AvgDialog_122700_Content_29 = {
    Text = "A teia de fios é fria, flexível, agarrando-se com uma proximidade que não deixa espaço para respirar, apertando-se mais, pressionando através do tecido, contra a pele."
  },
  AvgDialog_122700_Content_3 = {
    Text = "Espera! Eu devia estar a dormir no meu dormitório. Como é que vim parar aqui... foste tu que fizeste isto?"
  },
  AvgDialog_122700_Content_30 = {
    Text = "Então quelíceras se fecham ao seu redor, e pedipalpos frios separam seus lábios, selando qualquer resistência que ainda não havia encontrado suas palavras."
  },
  AvgDialog_122700_Content_31 = {
    Text = "Os fios começam a guiar seus membros. Gentilmente, e sem apelação."
  },
  AvgDialog_122700_Content_32 = {
    Text = "Não se preocupe, Guardião. Não há necessidade de resistir ao que o destino escolheu lhe dar."
  },
  AvgDialog_122700_Content_33 = {
    Text = "Porque... isto é o que você também quer, não é?"
  },
  AvgDialog_122700_Content_34 = {
    Text = "...Isso mesmo, Arachne... isso é... o que eu quero..."
  },
  AvgDialog_122700_Content_35 = {
    Text = "Claro. Você nunca foi uma marionete do destino. Você é o Guardião do Segredo de Misaq, aquele que segura seu destino em suas próprias mãos."
  },
  AvgDialog_122700_Content_36 = {
    Text = "Isto é exatamente o que você quer. É o destino que se curva à sua vontade. É o seu corpo respondendo ao seu próprio chamado."
  },
  AvgDialog_122700_Content_37 = {
    Text = "Os fios estremeceram, como o destino deslizando um arco sobre cordas. Você estende a mão, traçando as patas de aranha balançando suavemente no ar, traçando as mãos que nunca pararam de girar o fuso, traçando as linhas daquele rosto gentil."
  },
  AvgDialog_122700_Content_38 = {
    Text = "Aquele rosto familiar. A compaixão que ele sempre carrega, a serenidade que nunca o abandona. E agora, quase imperceptivelmente, algo mais — um calor subindo à superfície, desguardado, que você nunca havia visto antes."
  },
  AvgDialog_122700_Content_39 = {
    Text = "Vamos acolher o que o destino nos trouxe, juntos... {Male=Sr., Female=Srta.} Guardião."
  },
  AvgDialog_122700_Content_4 = {
    Text = "Seguiste a tua própria vontade. Tu <Italic:quiseste> vir aqui. Já te tinhas esquecido?"
  },
  AvgDialog_122700_Content_40 = {
    Text = "Dois fios do destino se enroscam um no outro, puxando, cedendo, sem cessar. As ondulações trêmulas se espalham para fora ao longo da teia invisível, dissolvendo-se em direção a uma borda ilimitada e inalcançável."
  },
  AvgDialog_122700_Content_41 = {Text = "..."},
  AvgDialog_122700_Content_5 = {
    Text = "Ela sorri para ti. Uma pressão, como o peso do próprio destino, fecha-se à tua volta vinda de todas as direções."
  },
  AvgDialog_122700_Content_6 = {
    Text = "O mundo sempre viu o destino como um grilhão inescapável, a origem de todo o seu sofrimento."
  },
  AvgDialog_122700_Content_7 = {
    Text = "Mas tu e eu, que tocámos os fios do destino com as nossas próprias mãos, sabemos bem — ele é apenas aquilo que nós próprios escolhemos criar."
  },
  AvgDialog_122700_Content_8 = {
    Text = "Propagar, para que possamos ser destruídos. Ser destruídos, para que possamos renascer."
  },
  AvgDialog_122700_Content_9 = {
    Text = "Vezes sem conta, sem fim... É apenas isso que o destino é, não é?"
  },
  AvgDialog_122780_Content_1 = {
    Text = "Mensagem do Distante"
  },
  AvgDialog_122780_Content_2 = {
    Text = "Este é um documento de teste"
  },
  AvgDialog_122780_Content_3 = {
    Text = "Este é um documento de teste"
  },
  AvgDialog_122780_Content_4 = {
    Text = "Este é um documento de teste"
  },
  AvgDialog_122780_Content_5 = {
    Text = "Este é um documento de teste"
  },
  AvgDialog_122780_Content_6 = {
    Text = "Este é um documento de teste"
  },
  AvgDialog_122780_Content_7 = {
    Text = "Fim da declaração"
  },
  AvgDialog_123116_Content_1 = {
    Text = "O Cordeiro Perdido"
  },
  AvgDialog_123116_Content_10 = {
    Text = "Mas todos os padres que chegaram a Hawick - João, Tiago, Anderson - perderam completamente o contato em um curto período de tempo."
  },
  AvgDialog_123116_Content_11 = {
    Text = "Boas crianças... Após o Cataclismo, elas têm seguido os ensinamentos do Pai de Todos, tomando a iniciativa de ir a várias paróquias para espalhar o evangelho do Pai de Todos."
  },
  AvgDialog_123116_Content_12 = {
    Text = "Mesmo em uma grande cidade como Londres, as pessoas comuns muitas vezes lutam para cuidar de si mesmas após um desastre, e a situação em Hawick só será pior. Por que eles—"
  },
  AvgDialog_123116_Content_13 = {
    Text = "Assim como o que você fez por este mundo e pelos mundos passados, Mensageiro Pálido."
  },
  AvgDialog_123116_Content_14 = {
    Text = "Salvador juntou as mãos, sua expressão devotada e cheia de compaixão enquanto orava."
  },
  AvgDialog_123116_Content_15 = {
    Text = "Porque nossos irmãos e irmãs estão sofrendo."
  },
  AvgDialog_123116_Content_16 = {
    Text = "Erradicar o sofrimento desta terra é o dever dos Emissários do Pai de Todos; eles não podem abandonar os outros na desesperança devido à distância da jornada."
  },
  AvgDialog_123116_Content_17 = {
    Text = "...Eu entendo."
  },
  AvgDialog_123116_Content_18 = {
    Text = "Pai Salvador, eu vou ajudá-lo a encontrá-los juntos. \n Não importa se é vida ou morte."
  },
  AvgDialog_123116_Content_19 = {
    Text = "Neste momento"
  },
  AvgDialog_123116_Content_2 = {
    Text = "Howick, uma cidade remota nos arredores de Londres"
  },
  AvgDialog_123116_Content_20 = {
    Text = "Salvador, parece haver uma luz à frente..."
  },
  AvgDialog_123116_Content_21 = {
    Text = "Sua voz para abruptamente devido a uma descoberta inesperada—uma cela rudimentar aparece de repente dentro da caverna vazia."
  },
  AvgDialog_123116_Content_22 = {
    Text = "Pelo menos uma dúzia de pessoas estão trancadas dentro da jaula, cada uma parecendo desgastada, com várias tendo rostos machucados e ferimentos por todo o corpo."
  },
  AvgDialog_123116_Content_23 = {
    Text = "<Shake:Henry... está morto? Eles atiraram em Henry, atiraram em Henry até a morte...!>"
  },
  AvgDialog_123116_Content_24 = {
    Text = "A mulher segura a cabeça, murmurando para si mesma, seu olhar selvagem e tremor intenso revelando sua instabilidade."
  },
  AvgDialog_123116_Content_25 = {
    Text = "De repente, ela levanta a cabeça e nota você e todos os outros por perto."
  },
  AvgDialog_123116_Content_26 = {
    Text = "<Shake:Não, eles estão chegando, rápido, nos leve daqui!>"
  },
  AvgDialog_123116_Content_27 = {
    Text = "O movimento dela atraiu mais atenção, e um homem na jaula de repente correu em direção às barras, estendendo a mão para agarrar seu braço."
  },
  AvgDialog_123116_Content_28 = {
    Text = "Salve-me! Não quero ser uma humanidade, não quero ser sacrificado..."
  },
  AvgDialog_123116_Content_29 = {
    Text = "Ah ah ah ah — tire-nos daqui!"
  },
  AvgDialog_123116_Content_3 = {
    Text = "Se as informações fornecidas pela \"Boneca\" estiverem corretas, elas devem estar bem aqui."
  },
  AvgDialog_123116_Content_30 = {
    Text = "Cale-se todos*Silêncio*!"
  },
  AvgDialog_123116_Content_31 = {
    Text = "Um rugido alto interrompeu os gritos das vítimas, e os prisioneiros pareciam estar extraordinariamente aterrorizados pelo dono do rugido, apavorados até a loucura."
  },
  AvgDialog_123116_Content_32 = {
    Text = "O sacrifício ainda não começou, e vocês, esses porcos, já estão com pressa de morrer!?"
  },
  AvgDialog_123116_Content_33 = {
    Text = "Passos urgentes seguiram."
  },
  AvgDialog_123116_Content_34 = {
    Text = "Deve ser o culto que está aprisionando essas pessoas, %player%, nós..."
  },
  AvgDialog_123116_Content_35 = {
    Text = "Fiquem escondidos e pensem em uma maneira de resgatá-los mais tarde. Eles têm armas e, na confusão, não podemos garantir a segurança dessas pessoas."
  },
  AvgDialog_123116_Content_36 = {
    Text = "Mas o homem ainda se agarra a você com tanta força que quase quebra seu braço."
  },
  AvgDialog_123116_Content_37 = {
    Text = "Salve-nos, salve-nos primeiro! Se você não nos salvar, morra conosco!!"
  },
  AvgDialog_123116_Content_38 = {
    Text = "Os passos estão ficando mais perto, e o estado mental da outra parte claramente não consegue compreender qualquer raciocínio."
  },
  AvgDialog_123116_Content_39 = {
    Text = "Você cerrou os dentes e o nocauteou com um golpe rápido."
  },
  AvgDialog_123116_Content_4 = {
    Text = "Eu confio no seu julgamento, %player%."
  },
  AvgDialog_123116_Content_40 = {
    Text = "Hah... Hah..."
  },
  AvgDialog_123116_Content_41 = {
    Text = "Uma risada suave ecoou repentinamente do canto da cela."
  },
  AvgDialog_123116_Content_42 = {
    Text = "Você vira a cabeça instintivamente para olhar, e na jaula, uma donzela estranhamente vestida está te observando, seu leve sorriso contrastando fortemente com o ambiente caótico e louco deste momento."
  },
  AvgDialog_123116_Content_43 = {
    Text = "Que interessante! Um segundo dizendo para salvar alguém, no segundo seguinte nocauteando-os..."
  },
  AvgDialog_123116_Content_44 = {
    Text = "O estado atual de desconexão deixou você momentaneamente paralisado no lugar."
  },
  AvgDialog_123116_Content_45 = {
    Text = "Não se preocupe comigo, continue."
  },
  AvgDialog_123116_Content_46 = {
    Text = "Você não está se apressando? Os seguidores do Amanhã Estelar estarão chegando em breve."
  },
  AvgDialog_123116_Content_47 = {Text = "...?"},
  AvgDialog_123116_Content_48 = {
    Text = "O tempo é essencial, e não há espaço para conversas desnecessárias. Você não tem escolha a não ser deixar a garota para trás e se esconder com Salvador nas sombras."
  },
  AvgDialog_123116_Content_49 = {
    Text = "Em breve, dois cultistas empunhando espingardas apareceram do lado de fora da jaula. Eles ficaram de cada lado, levantando suas armas e apontando os canos para dentro da jaula prisional."
  },
  AvgDialog_123116_Content_5 = {
    Text = "Que o Pai de Todos os abençoe e os proteja das sombras, permitindo que habitem em paz."
  },
  AvgDialog_123116_Content_50 = {
    Text = "Quem estava fazendo todo esse barulho agora? Saia!"
  },
  AvgDialog_123116_Content_51 = {
    Text = "Ninguém respondeu. Os prisioneiros estavam encolhidos nos cantos, tremendo, ou olhavam em branco, entorpecidos e em silêncio.\nExceto por aquela garota estranha."
  },
  AvgDialog_123116_Content_52 = {
    Text = "Ela ainda usava um sorriso casual, observando de forma descontraída os seguidores da seita armados com armas de fogo."
  },
  AvgDialog_123116_Content_53 = {
    Text = "Esse cara é um lunático? Ele está tão relaxado mesmo com a morte iminente."
  },
  AvgDialog_123116_Content_54 = {
    Text = "Neste maldito mundo, onde estão as pessoas normais, ha! Se nós também fôssemos loucos, poderia ser muito mais fácil."
  },
  AvgDialog_123116_Content_55 = {
    Text = "Espero que este ritual tenha sucesso. Já estou realmente farto dessas névoas estranhas..."
  },
  AvgDialog_123116_Content_56 = {
    Text = "Quando começa o ritual que vocês mencionaram?"
  },
  AvgDialog_123116_Content_57 = {
    Text = "O seguidor do culto estava visivelmente atordoado."
  },
  AvgDialog_123116_Content_58 = {
    Text = "Quem você está falando, conosco?"
  },
  AvgDialog_123116_Content_59 = {
    Text = "O que mais? Pare de falar bobagens e responda à minha pergunta."
  },
  AvgDialog_123116_Content_6 = {
    Text = "Salvador abaixou a cabeça de forma devota, sussurrou uma oração e depois liderou o caminho mais fundo na caverna."
  },
  AvgDialog_123116_Content_60 = {
    Text = "O seguidor do culto estava completamente enfurecido pela garota, zombando enquanto levantava a mão e mirava a arma na perna dela."
  },
  AvgDialog_123116_Content_61 = {
    Text = "Mulher louca, tudo o que você precisa fazer é esperar obedientemente para ser sacrificada. Eu posso ver que você não tem ideia do que está acontecendo."
  },
  AvgDialog_123116_Content_62 = {Text = "Bang—"},
  AvgDialog_123116_Content_63 = {
    Text = "Uma força invisível fez com que a bala perdesse o alvo, atingindo a caverna acima e gerando uma fraca chama—"
  },
  AvgDialog_123116_Content_64 = {
    Text = "Você e Salvador emergiram da escuridão, lançando uma emboscada aos seguidores do culto."
  },
  AvgDialog_123116_Content_66 = {
    Text = "Você administrou bem seu tempo, parece que você não é tolo afinal."
  },
  AvgDialog_123116_Content_67 = {
    Text = "Obrigado por distrair os cultistas por nós, gentil senhora."
  },
  AvgDialog_123116_Content_68 = {
    Text = "Que o Pai te abençoe."
  },
  AvgDialog_123116_Content_69 = {
    Text = "Salvador desenhou o símbolo sagrado do Pai Deus no ar. \n Você confiscou todas as armas dos cultistas, ordenou que se ajoelhassem diante da jaula e começou o interrogatório."
  },
  AvgDialog_123116_Content_7 = {
    Text = "Três dias atrás"
  },
  AvgDialog_123116_Content_70 = {
    Text = "Diga, quando o ritual será realizado? Onde será realizado? O desaparecimento dos padres do Santuário de Vida tem algo a ver com vocês!?"
  },
  AvgDialog_123116_Content_71 = {
    Text = "Santuário de Vida... padre...?"
  },
  AvgDialog_123116_Content_72 = {
    Text = "Isso mesmo, John, James, Anderson, onde eles estão?"
  },
  AvgDialog_123116_Content_73 = {
    Text = "Ao ouvir isso, o seguidor do culto ficou surpreso por um momento e de repente começou a rir loucamente."
  },
  AvgDialog_123116_Content_74 = {
    Text = "<Shake:Nós nos redimiremos de acordo com a vontade do Todo-Pai! Sim, o Reino Sereno Livre da Dissolução está a caminho!>"
  },
  AvgDialog_123116_Content_75 = {
    Text = "<Shake:<Big:Desceu! Vocês, desgraçados, apodrecerão aqui enquanto o mundo cai em ruínas!>>"
  },
  AvgDialog_123116_Content_76 = {
    Text = "Então, a cerimônia está prestes a começar? <Small:Suponho que preciso me apressar.>"
  },
  AvgDialog_123116_Content_77 = {
    Text = "Aproveite o tempo... o que isso significa? Você sabe de algo?"
  },
  AvgDialog_123116_Content_78 = {
    Text = "A donzela não respondeu; ela olhou para você e Salvador, revelando um sorriso inocente e bem-comportado.\nPor alguma razão, você sentiu um toque de astúcia nele."
  },
  AvgDialog_123116_Content_79 = {
    Text = "Ah, é verdade, eu me chamo Mouchette, quanto aos seus nomes — não precisa dizer, não estou interessada."
  },
  AvgDialog_123116_Content_8 = {
    Text = "Todos os Sacerdotes enviados pela Chantry da Vida para Hawick estão desaparecidos?"
  },
  AvgDialog_123116_Content_80 = {
    Text = "Eu sei onde é a cerimônia, e posso te levar até lá, mas..."
  },
  AvgDialog_123116_Content_81 = {
    Text = "Preciso que você me faça um pequeno favor."
  },
  AvgDialog_123116_Content_82 = {
    Text = "Que favor? Espero que você possa explicar melhor."
  },
  AvgDialog_123116_Content_83 = {
    Text = "Ainda sem responder, a menina deixou apenas uma frase e saiu cantarolando em um tom intermitente."
  },
  AvgDialog_123116_Content_84 = {
    Text = "Hum☆hum! Vou resolver algumas coisas primeiro. Daqui a dez minutos, nos encontramos lá fora~"
  },
  AvgDialog_123116_Content_85 = {Text = "..."},
  AvgDialog_123116_Content_86 = {
    Text = "Isso também é bom; podemos primeiro contatar a Chantria da Vida para enviar reforços e resolver esses indivíduos que estão sofrendo."
  },
  AvgDialog_123116_Content_87 = {
    Text = "Vamos lá, só pode ser assim."
  },
  AvgDialog_123116_Content_88 = {
    Text = "Olhando na direção para onde a donzela havia partido, a crescente sensação de inquietação fez você sentir como se algo estivesse subindo pela sua coluna."
  },
  AvgDialog_123116_Content_89 = {
    Text = "Sua fonte é a sensação de desconexão que está por trás do exterior ingênuo do outro, um que é extremamente próximo da humanidade, mas glaringly falso..."
  },
  AvgDialog_123116_Content_9 = {
    Text = "Sim, após perder o contato com o Padre White, que está à frente da paróquia de Howick, o Vaticano decidiu enviar reforços."
  },
  AvgDialog_123117_Content_1 = {
    Text = "Em Prata e Sangue"
  },
  AvgDialog_123117_Content_10 = {
    Text = "... não deveria discutir isso com você."
  },
  AvgDialog_123117_Content_100 = {
    Text = "Mouchette... se você ainda estiver... apareça... por favor..."
  },
  AvgDialog_123117_Content_101 = {
    Text = "Ainda assim, o vazio permanece vazio. A garota chamada Mouchette se foi."
  },
  AvgDialog_123117_Content_102 = {Text = "..."},
  AvgDialog_123117_Content_103 = {
    Text = "Você fecha os olhos e solta um profundo suspiro. Não há mais tempo. \n Salvador ainda está lá fora, e o portão invisível ainda está lá. Você deve voltar."
  },
  AvgDialog_123117_Content_104 = {
    Text = "Desculpe, por ter trazido você a um mundo tão cruel... e sinto muito por não poder levar você de volta para casa..."
  },
  AvgDialog_123117_Content_105 = {
    Text = "No momento seguinte, você cortou o link com a Dimensão espiritual de Mouchette —"
  },
  AvgDialog_123117_Content_106 = {
    Text = "Após um breve momento de tontura, seu espírito retornou ao casulo, e tudo voltou ao ponto de partida:"
  },
  AvgDialog_123117_Content_107 = {
    Text = "O Portão Invisível ainda está fora de controle, e o machado de Mo Xia repousa tranquilamente em sua mão."
  },
  AvgDialog_123117_Content_108 = {
    Text = "<Shake:Mouchette...Eu...>"
  },
  AvgDialog_123117_Content_109 = {
    Text = "Você agarra o cabo, olhando para a garota silenciosa. Ela está ali nas ruínas de sua sanidade, esperando o golpe fatal."
  },
  AvgDialog_123117_Content_11 = {
    Text = "Você suspirou, com o rosto cheio de desânimo. Salvador observou tudo isso e não pôde deixar de sorrir levemente."
  },
  AvgDialog_123117_Content_110 = {
    Text = "Talvez seja um efeito psicológico, mas você sempre sente que aqueles olhos não perderam toda a sanidade. \nPorque você já viu aqueles olhos sorrindo antes."
  },
  AvgDialog_123117_Content_111 = {
    Text = "<Shake:Quanto tempo... você vai... apenas me encarar...?>"
  },
  AvgDialog_123117_Content_112 = {
    Text = "Mouchette! Você voltou?!"
  },
  AvgDialog_123117_Content_113 = {
    Text = "<Shake:Eu não... mas eu... ouvi... suas palavras...>"
  },
  AvgDialog_123117_Content_114 = {
    Text = "Você está certo... As coisas não deveriam ser assim... Eu não posso desistir sem nem tentar..."
  },
  AvgDialog_123117_Content_115 = {
    Text = "Mouchette usou suas últimas forças para agarrá-lo, tocando a chave de prata em seu peito."
  },
  AvgDialog_123117_Content_116 = {
    Text = "Não importa o resultado, o portão invisível desaparecerá..."
  },
  AvgDialog_123117_Content_117 = {
    Text = "Nunca... deixarei este lugar se tornar outro mundo de desastres de névoa..."
  },
  AvgDialog_123117_Content_118 = {
    Text = "Especialmente depois de saber o quanto você trabalhou duro para salvar este mundo"
  },
  AvgDialog_123117_Content_119 = {
    Text = "Então, a chave de prata no seu peito começou a funcionar automaticamente, emitindo uma luz que tingiu sua visão de branco."
  },
  AvgDialog_123117_Content_12 = {
    Text = "Mouchette, realmente é uma criança especial... apenas especial, ainda é uma boa criança."
  },
  AvgDialog_123117_Content_120 = {
    Text = "Você ouviu um grito penetrante, um lamento doloroso, a distorção de uma flauta e o som de algo se quebrando."
  },
  AvgDialog_123117_Content_121 = {
    Text = "Ou talvez, isso seja apenas as alucinações provocadas pela sua tensão, pois neste espaço de pura brancura, você perdeu o controle de seus sentidos e sua noção de tempo."
  },
  AvgDialog_123117_Content_122 = {
    Text = "Após um período desconhecido de tempo, quando todas as alucinações auditivas desaparecem, seus vários sentidos finalmente retornam —"
  },
  AvgDialog_123117_Content_123 = {
    Text = "A névoa desapareceu. O Portão se foi. Apenas o altar manchado de sangue permanece, e Salvador, observando você com olhos ocos e preocupados."
  },
  AvgDialog_123117_Content_124 = {
    Text = "Mensageiro Pálido, nós... falhamos?"
  },
  AvgDialog_123117_Content_125 = {Text = "..."},
  AvgDialog_123117_Content_126 = {
    Text = "Nesse momento, uma risada leve ecoou atrás de vocês."
  },
  AvgDialog_123117_Content_127 = {
    Text = "%player%, Salvador, o que vocês estão fazendo? A missão acabou."
  },
  AvgDialog_123117_Content_128 = {
    Text = "<Big:Mouchette—!!>"
  },
  AvgDialog_123117_Content_129 = {
    Text = "Surpreso, você grita, mas no segundo seguinte, não consegue evitar um sorriso."
  },
  AvgDialog_123117_Content_13 = {
    Text = "Bom garoto? Por favor, não use essa palavra para descrever... espera, vocês ouviram algum som?"
  },
  AvgDialog_123117_Content_130 = {
    Text = "Não precisa gritar tanto, eu consigo ouvir claramente. De qualquer forma, a emocionante batalha já acabou, o que resta é a monótona vida cotidiana."
  },
  AvgDialog_123117_Content_131 = {
    Text = "Depois de voltar, eu realmente quero uma xícara quente de Chá de Cacau com Avelã, oh... mas não tem isso aqui, então vou comer um bolinho."
  },
  AvgDialog_123117_Content_132 = {
    Text = "Podemos conversar enquanto desfrutamos de alguns bolinhos, por exemplo, quem é o Murphy, quem é a Liz, quem é a Dole e quais aventuras interessantes você teve com o Corpo Despertar?"
  },
  AvgDialog_123117_Content_133 = {
    Text = "De qualquer forma, não posso voltar, então só posso entender mais sobre este mundo."
  },
  AvgDialog_123117_Content_134 = {
    Text = "Eu acho que esse pedido %player% não vai recusar."
  },
  AvgDialog_123117_Content_135 = {
    Text = "Salvador olhou para você com um sorriso, e você também sorriu, olhando para Mouchette.\n A névoa se dissipou, e a luz do luar caiu sobre vocês, refletindo uma suave luminosidade."
  },
  AvgDialog_123117_Content_136 = {
    Text = "Você ainda tem muitas perguntas para fazer a Mouchette, mas as reprimiu no fundo do coração —"
  },
  AvgDialog_123117_Content_137 = {
    Text = "Talvez seja por causa daquela linda luz da lua, ou talvez seja por algo que você não consegue explicar, uma sensação que se assemelha a \"renascimento\", como se tivesse escapado da morte."
  },
  AvgDialog_123117_Content_138 = {
    Text = "Deixa pra lá, o relatório pode ser escrito a qualquer momento, mas celebrar a chegada de um visitante de outro mundo assim, a oportunidade de renascer no novo mundo não é algo comum."
  },
  AvgDialog_123117_Content_139 = {
    Text = "Parabéns por se tornar um Corpo Desperto, Mouchette. A partir de agora, este lugar não é apenas o nosso mundo, mas também o seu mundo..."
  },
  AvgDialog_123117_Content_14 = {
    Text = "Parece que alguém está chorando... e o choro está ficando cada vez mais alto..."
  },
  AvgDialog_123117_Content_140 = {
    Text = [[
Despertador Mouchette
Bem-vindo ao nosso mundo]]
  },
  AvgDialog_123117_Content_15 = {
    Text = "Você ouviu com atenção, mas não ouviu nada. \n Você olhou para Salvador novamente, e ele balançou a cabeça suavemente."
  },
  AvgDialog_123117_Content_16 = {
    Text = "Nesse momento, Mouchette de repente soltou um grito, se curvou e segurou as orelhas com dor."
  },
  AvgDialog_123117_Content_17 = {
    Text = "<Shake:Espere um segundo... Alguém, não, muitas pessoas, estão gritando e uivando na minha cabeça...>"
  },
  AvgDialog_123117_Content_18 = {
    Text = "Você percebe que algo está errado ao verificar a situação de Mouchette, mas só vê que ela está tremendo de dor, com as pupilas cada vez mais dilatadas."
  },
  AvgDialog_123117_Content_19 = {
    Text = "Fora de controle? Seria por causa do líquido do núcleo de prata…?"
  },
  AvgDialog_123117_Content_2 = {
    Text = "Sob o céu repleto de prata e sangue, a névoa densa ondula, a porta invisível brilha, mas elas já não parecem mais invencíveis —"
  },
  AvgDialog_123117_Content_20 = {
    Text = "Líquido do Núcleo de prata!?"
  },
  AvgDialog_123117_Content_21 = {
    Text = "Você examinou cuidadosamente as manchas de sangue em Mouchette, e em meio ao vermelho escuro, o líquido prateado fluía lentamente, infiltrando-se em seu corpo através de sua pele exposta."
  },
  AvgDialog_123117_Content_22 = {
    Text = "Mouchette veio ao nosso mundo por meio de um ritual de sacrifício, e esses líquidos do núcleo de prata foram usados como oferendas, provavelmente a considerando também como \"uma parte\" do ritual..."
  },
  AvgDialog_123117_Content_23 = {
    Text = "Não dá, o líquido do núcleo de prata aqui é demais e muito confuso, precisa ser tratado imediatamente, caso contrário, ela, como uma pessoa comum, ficará louca!"
  },
  AvgDialog_123117_Content_24 = {
    Text = "Você e Salvador imediatamente começaram a limpar o líquido prateado de Mouchette, mas já era tarde demais—"
  },
  AvgDialog_123117_Content_25 = {
    Text = "<Red:<Shake:AAAAHHH—!>>"
  },
  AvgDialog_123117_Content_26 = {
    Text = "Com um grito angustiante, as pupilas de Mouchette se dissiparam e se dividiram, seu corpo se desintegrou e distorceu, espirrando uma grande quantidade de carne e sangue, deformando-se em uma existência indescritível."
  },
  AvgDialog_123117_Content_27 = {
    Text = "Esses pedaços de carne e sangue estouram em você e Salvador, também respingam na porta invisível, criando camadas de ondulações na superfície do desconhecido e do sinistro."
  },
  AvgDialog_123117_Content_28 = {
    Text = "Algo está errado, \"porta\" está mudando..."
  },
  AvgDialog_123117_Content_29 = {
    Text = "Antes que pudesse terminar de falar, um forte impacto foi transmitido através da conexão entre a porta invisível e a Chave de Prata, fazendo com que você ficasse sem palavras instantaneamente."
  },
  AvgDialog_123117_Content_3 = {
    Text = "A Chave de Prata em sua mão emite um brilho deslumbrante e resoluto, fechando gradualmente a fenda no tempo e no espaço, enquanto elimina lentamente todas as anomalias causadas pela cerimônia."
  },
  AvgDialog_123117_Content_30 = {
    Text = "Sob trauma psicológico insuportável, você sangra pelo nariz, perde todas as forças e se ajoelha."
  },
  AvgDialog_123117_Content_31 = {
    Text = "<Red:<Shake:Matar, matar, matar! Matar todos!>>"
  },
  AvgDialog_123117_Content_32 = {
    Text = "<Red:<Shake:Hahaha! Veja este mundo queimar!>>"
  },
  AvgDialog_123117_Content_33 = {
    Text = "O machado que uma vez abriu um caminho para você está agora erguido, apontado para sua cabeça. E você está esgotado por uma estranha ligação mental, perdendo a consciência e incapaz de se mover."
  },
  AvgDialog_123117_Content_34 = {
    Text = "<Shake:Mouchette...>"
  },
  AvgDialog_123117_Content_35 = {
    Text = "Você luta para falar, mas sua voz é rouca e fraca, incapaz de despertar a sanidade de Mouchette."
  },
  AvgDialog_123117_Content_37 = {
    Text = "No final, o machado caiu pesadamente, penetrando fundo na carne—\n no último momento, Salvador se colocou na sua frente, recebendo o golpe."
  },
  AvgDialog_123117_Content_38 = {
    Text = "O sangue escorreu pelo ombro de Salvador, mas sua expressão não tinha rancor, apenas compaixão e bondade."
  },
  AvgDialog_123117_Content_39 = {
    Text = "Criança, eu sei que isso não foi de sua intenção. Você apenas se perdeu."
  },
  AvgDialog_123117_Content_4 = {
    Text = "Depois de um longo tempo, a prata e o sangue flutuantes começaram a cair, caindo no chão, caindo sobre vocês, e a densa névoa ao redor também se tornava visivelmente mais clara, encolhendo, tudo estava melhorando."
  },
  AvgDialog_123117_Content_40 = {
    Text = "<Red:<Shake:MATE! DESTRUA TUDO!>>"
  },
  AvgDialog_123117_Content_41 = {
    Text = "A loucura consumiu completamente Mouchette; neste momento, ela é movida apenas por um impulso violento de destruição e massacre."
  },
  AvgDialog_123117_Content_42 = {
    Text = "<Shake:Salvador, inútil, ela...>"
  },
  AvgDialog_123117_Content_43 = {
    Text = "Você olhou para Mouchette, que já não podia mais ser chamada de \"humana\", e sua voz estava tremendo.\n No momento anterior, ela ainda era tão viva."
  },
  AvgDialog_123117_Content_44 = {
    Text = "Não, Mensageiro Pálido. Ela apenas se perdeu."
  },
  AvgDialog_123117_Content_45 = {
    Text = "Salvador avançou, dirigindo-se em direção ao machado afiado erguido novamente por Mouchette."
  },
  AvgDialog_123117_Content_46 = {
    Text = "O sangue respingou da lâmina do machado em seu rosto, mas Salvador não mostrou sinal de medo."
  },
  AvgDialog_123117_Content_47 = {
    Text = "Desculpe, não estive lá quando o Amanhecer das Estrelas sacrificou humanos e o convocou."
  },
  AvgDialog_123117_Content_48 = {
    Text = "A gota de sangue do machado de Mouchette deslizava pela bochecha de Salvador, como uma lágrima."
  },
  AvgDialog_123117_Content_49 = {
    Text = "Salvador não limpou essa \"lágrima\", ele apenas segurou firmemente a lâmina do machado de Mouchette, ao mesmo tempo levantando a outra mão —"
  },
  AvgDialog_123117_Content_5 = {
    Text = "Em breve, a anomalia da Porta Dimensional diminuirá para o mínimo, Mouchette, essa é a melhor oportunidade para você voltar para casa."
  },
  AvgDialog_123117_Content_50 = {
    Text = "Mas neste momento, estou aqui e irei te salvar."
  },
  AvgDialog_123117_Content_51 = {
    Text = "A mão ensanguentada do Sacerdote tocou a testa da Donzela. Em um instante, uma luz brilhante e resoluta irrompeu do ponto de contato entre eles."
  },
  AvgDialog_123117_Content_52 = {
    Text = "Esse é um Sacerdote de um mundo, concedendo uma Benção ao Cordeiro de outro mundo."
  },
  AvgDialog_123117_Content_53 = {
    Text = "Com o brilho dessa luz, a dor aguda em sua cabeça desaparece rapidamente, como se alguém tivesse assumido todo o seu sofrimento..."
  },
  AvgDialog_123117_Content_54 = {
    Text = "Salvador, pare, isso envolve uma conexão de dimensão, ninguém pode suportar isso!"
  },
  AvgDialog_123117_Content_55 = {Text = "Eu sei."},
  AvgDialog_123117_Content_56 = {
    Text = "A voz de Salvador tremia e quebrava. Esse nível de vínculo era, mesmo para ele, um tormento que transcendia todos os limites."
  },
  AvgDialog_123117_Content_57 = {
    Text = "Logo, ele não pôde mais suportar e lágrimas de sangue fluíram dele."
  },
  AvgDialog_123117_Content_58 = {
    Text = "Mas eu, como executor do Pai Deus, devo dar o meu máximo."
  },
  AvgDialog_123117_Content_59 = {
    Text = "Mais lágrimas de sangue fluíam de sob a venda de Salvador, mas essa cor foi contaminada pela intensa luz da \"Bênção\", parecendo que o que escorria dos olhos de Salvador não era sangue, mas sim ouro derretido."
  },
  AvgDialog_123117_Content_6 = {
    Text = "Vou manter a energia da Chave de Prata no máximo, o suficiente para que você atravesse a Dimensão em segurança."
  },
  AvgDialog_123117_Content_60 = {
    Text = "Este ouro caiu, pingando nas costas da mão de Mouchette, despindo a casca dourada e revelando sua verdadeira cor vermelha, fundindo-se com o sangue humano que respingou em Mouchette e com o próprio sangue de Mouchette."
  },
  AvgDialog_123117_Content_61 = {
    Text = "Em nome do Pai Deus, Mouchette, eu não deixarei que você se desvie do caminho."
  },
  AvgDialog_123117_Content_62 = {
    Text = "Com esse chamado, a testa de Mouchette irrompeu em uma luz intensa, tão radiante que ofuscou completamente o sangue que cobria seu corpo e também a luz da porta invisível."
  },
  AvgDialog_123117_Content_63 = {
    Text = "Essa é a luz que Salvador derramou de sua vida."
  },
  AvgDialog_123117_Content_64 = {
    Text = "<Shake:Ugh...>"
  },
  AvgDialog_123117_Content_65 = {
    Text = "Na luz que ilumina tudo, os olhos fragmentados obtêm um momento de clareza, olhando para o dorso da própria mão com a única razão que lhes resta."
  },
  AvgDialog_123117_Content_66 = {
    Text = "Já não há mais sinais do sangue de Salvador ali, pois todo o sangue já se fundiu."
  },
  AvgDialog_123117_Content_67 = {
    Text = "O sangue da vítima e do perpetrador, o sangue do culpado e do redentor, entrelaçam-se no mesmo rio de sangue."
  },
  AvgDialog_123117_Content_68 = {
    Text = "Eu... disse..."
  },
  AvgDialog_123117_Content_69 = {
    Text = "<Shake:Eu odeio... sacrificar os outros... para me salvar...>"
  },
  AvgDialog_123117_Content_7 = {
    Text = "Se eu pudesse tomar um banho antes de atravessar, seria ótimo. Voltar todo ensanguentado, não sei se assustaria o investigador."
  },
  AvgDialog_123117_Content_70 = {
    Text = "Mo Xia empurrou Salvador para longe com o último resquício de sua sanidade e olhou para você. \n Você a viu erguer o machado com todas as suas forças, e também viu as lágrimas escorrendo pelo seu rosto."
  },
  AvgDialog_123117_Content_71 = {
    Text = "A partir de agora... não deixe ele fazer isso novamente... As pessoas que realmente merecem viver são pessoas como ele..."
  },
  AvgDialog_123117_Content_72 = {
    Text = "Por causa do ritual... o portão invisível me fez parte dele..."
  },
  AvgDialog_123117_Content_73 = {
    Text = "<Shake:Se você me matar, ele se dissipará... Aqueles pessoas... também serão libertadas...>"
  },
  AvgDialog_123117_Content_74 = {
    Text = "E... isso não é deserção... é levar o inimigo... com você..."
  },
  AvgDialog_123117_Content_75 = {
    Text = "Mouchette usou suas últimas forças para entregar o machado em suas mãos, enquanto você, ao pegá-lo, ficou paralisado no lugar."
  },
  AvgDialog_123117_Content_76 = {
    Text = "Sério... por que eu fiz... uma escolha que nem consigo entender..."
  },
  AvgDialog_123117_Content_77 = {
    Text = "Claramente, destruir o mundo é mais o meu estilo..."
  },
  AvgDialog_123117_Content_78 = {
    Text = "Mouchette estava com a voz embargada, e no momento seguinte, uma gota de lágrima caiu de seus olhos sem aviso, escorrendo pela sua machado e se despedaçando em sua palma."
  },
  AvgDialog_123117_Content_79 = {
    Text = "Em breve, aqueles olhos que derramaram lágrimas começaram a se tornar confusos, lentamente gestando a loucura.\nMouchette estava prestes a perder a razão novamente."
  },
  AvgDialog_123117_Content_8 = {
    Text = "Não precisa arrumar uma mesa e trazer alguns bolinhos para o chá da tarde?"
  },
  AvgDialog_123117_Content_80 = {
    Text = "Mensageiro Pálido, por favor, não... Eu a redimirei novamente."
  },
  AvgDialog_123117_Content_81 = {
    Text = "Salvador luta para se levantar, sua voz um apelo desesperado. Você olha para o machado, sua mente uma tempestade de dor e conflito."
  },
  AvgDialog_123117_Content_82 = {
    Text = "Não era apenas um machado; era uma confiança da vida e uma despedida."
  },
  AvgDialog_123117_Content_83 = {
    Text = "<Shake:Só me dê um momento... deve haver outra maneira... deve haver...>"
  },
  AvgDialog_123117_Content_84 = {
    Text = "De repente, um método cruel apareceu em sua mente—"
  },
  AvgDialog_123117_Content_85 = {
    Text = "Sem pensar muito, você segurou a Chave Prateada com uma mão e agarrou a mão de Mouchette com a outra, mergulhando nas profundezas turvas da consciência."
  },
  AvgDialog_123117_Content_86 = {
    Text = "Através do link da chave de prata, forçar Mouchette a se transformar de humano em Corpo Desperto é a única solução que você consegue pensar no momento."
  },
  AvgDialog_123117_Content_87 = {
    Text = "No momento em que você se imergiu na mente de Mouchette, incontáveis pontos de luz contorcendo-se e se agitando invadiram sua visão. \n Todos estavam gritando e clamando, mas nenhum deles era Mouchette."
  },
  AvgDialog_123117_Content_88 = {
    Text = "No mundo espiritual de Mouchette, não há Mouchette."
  },
  AvgDialog_123117_Content_89 = {
    Text = "Mouchette! Mouchette, onde você está..."
  },
  AvgDialog_123117_Content_9 = {
    Text = "Isso é ainda melhor. Olhando para este mundo chato e bagunçado, o bolinho deve ser ainda mais saboroso."
  },
  AvgDialog_123117_Content_90 = {
    Text = "Sem resposta. Sendo uma pessoa comum, aquele último \"pedido\" já era o limite do que ela podia fazer sob a loucura e o crash."
  },
  AvgDialog_123117_Content_91 = {
    Text = "Mouchette? Você desistiu? Sim, você costumava dizer que algumas vezes por semana não queria viver e sempre mencionava a palavra \"morrer\"..."
  },
  AvgDialog_123117_Content_92 = {
    Text = "Mas as coisas não são assim... Salvador, eu e o investigador que você sempre menciona, não queremos que isso aconteça..."
  },
  AvgDialog_123117_Content_93 = {
    Text = "Então, Mouchette, saia..."
  },
  AvgDialog_123117_Content_94 = {
    Text = "No entanto, não importa o quanto você grite ou procure, tudo ao seu redor são os uivos e gritos enlouquecidos."
  },
  AvgDialog_123117_Content_95 = {
    Text = "Mouchette \"desapareceu.\""
  },
  AvgDialog_123117_Content_96 = {
    Text = "... Na verdade, eu pensei em uma maneira..."
  },
  AvgDialog_123117_Content_97 = {
    Text = "É simplesmente usar o núcleo de prata que penetrou em seu corpo para transformá-lo, transformá-lo em um Corpo Desperto. O risco de falha é muito alto, mas é o único método que consigo pensar no momento."
  },
  AvgDialog_123117_Content_98 = {
    Text = "<Small:Eu pensei que a parte mais difícil seria o \"Despertar\", mas não imaginei que eu não conseguiria nem encontrar o seu Corpo espiritual...>"
  },
  AvgDialog_123117_Content_99 = {
    Text = "Você caiu em um longo silêncio, sentindo que cada respiração era extremamente difícil. \n Como um Guardião, você está bem ciente das consequências para as pessoas comuns quando expostas ao excesso de Prata."
  },
  AvgDialog_123118_Content_1 = {
    Text = "Na névoa densa e sem fim, os lamentos gélidos de agonia ecoam continuamente."
  },
  AvgDialog_123118_Content_10 = {
    Text = "O amor do Pai não pode salvar a todos, mas faremos o nosso melhor para estender uma mão amiga a cada vítima."
  },
  AvgDialog_123118_Content_11 = {
    Text = "<Shake:não... não ligue mais...>"
  },
  AvgDialog_123118_Content_12 = {
    Text = "Sob o peso do trauma psíquico, ela começou a sangrar incontrolavelmente pelo nariz."
  },
  AvgDialog_123118_Content_13 = {
    Text = "<Shake:Eu disse, <Big:não ligue mais...>>"
  },
  AvgDialog_123118_Content_15 = {
    Text = "Mouchette gritou de raiva, e, em sua excitação, balançou o machado para cortar aquelas névoas humanoides, mas viu a névoa se dividir em silêncio e rapidamente se reunir novamente."
  },
  AvgDialog_123118_Content_16 = {
    Text = "Inútil. Basta a névoa densa estar presente, esses monstros não desaparecerão."
  },
  AvgDialog_123118_Content_17 = {
    Text = "Então foi por isso que você nos fez \"ajudar\" a distrair os monstros, não foi?"
  },
  AvgDialog_123118_Content_18 = {
    Text = "Vocês querem acertar contas comigo agora? É preciso fazer fila, por favor, aguarde um pouco..."
  },
  AvgDialog_123118_Content_19 = {
    Text = "Mouchette limpou o sangue do nariz e continuou a balançar o machado. A sensação de lutar a deixava tão animada que ela simplesmente não conseguia parar."
  },
  AvgDialog_123118_Content_2 = {
    Text = "@2I... salvar @2..."
  },
  AvgDialog_123118_Content_20 = {
    Text = "Já que não há como recuar agora, vamos segurar essa onda primeiro!"
  },
  AvgDialog_123118_Content_21 = {
    Text = "Mouchette, seja sensata! Se continuar assim, você vai..."
  },
  AvgDialog_123118_Content_22 = {
    Text = "Vai morrer, não é?"
  },
  AvgDialog_123118_Content_23 = {
    Text = "De qualquer forma, eu tenho algumas vezes por semana em que não quero viver, justo..."
  },
  AvgDialog_123118_Content_24 = {
    Text = "As palavras de Mouchette pararam abruptamente. De repente, uma luz brilhou diante de seus olhos, e então uma sensação de calor se espalhou sobre ela, fluindo para seus membros e todo o corpo."
  },
  AvgDialog_123118_Content_25 = {
    Text = "Salvador \"Bênção\" a ela."
  },
  AvgDialog_123118_Content_26 = {
    Text = "<Shake:O que você está fazendo?!>"
  },
  AvgDialog_123118_Content_27 = {
    Text = "Mouchette não pôde deixar de dar um passo para trás.\nAquela sensação de calor era muito estranha. Não deveria estar presente nela."
  },
  AvgDialog_123118_Content_28 = {
    Text = "Nós, somos inimigos, por quê..."
  },
  AvgDialog_123118_Content_29 = {
    Text = "Eu disse que não somos inimigos."
  },
  AvgDialog_123118_Content_3 = {
    Text = "Salvar @2... @2 me..."
  },
  AvgDialog_123118_Content_30 = {
    Text = "Não ser inimigo não significa ser parceiro!"
  },
  AvgDialog_123118_Content_31 = {
    Text = "Eu não seria ingênuo o suficiente para considerar alguém que conheci apenas algumas vezes como um companheiro..."
  },
  AvgDialog_123118_Content_32 = {
    Text = "Mas já lutamos contra aqueles cultistas juntos, não é? Aqueles que lutam lado a lado são parceiros."
  },
  AvgDialog_123118_Content_33 = {
    Text = "A propósito, eu não acho que isso seja a minha teoria entediante de que eu amo as pessoas e as pessoas me amam, eu prefiro..."
  },
  AvgDialog_123118_Content_34 = {
    Text = "Eu prefiro entendê-lo como a sabedoria de sobrevivência neste mundo cruel."
  },
  AvgDialog_123118_Content_35 = {
    Text = "A radiação do Pai de Todos brilha sobre toda a terra; mesmo nas terras desoladas, irmãos e irmãs se apoiarão mutuamente."
  },
  AvgDialog_123118_Content_36 = {
    Text = "Mouchette apertou os lábios, em silêncio. Seu olhar ainda era cauteloso e desconfiado, mas, no final, essa cautela e desconfiança foram lentamente se dissipando, transformando-se em uma confusão e uma leve nostalgia."
  },
  AvgDialog_123118_Content_37 = {
    Text = "Ela moveu os lábios, como se estivesse sussurrando algo, mas devido ao volume baixo, você só ouviu vagamente as palavras \"Investigador\"."
  },
  AvgDialog_123118_Content_38 = {
    Text = "Vamos pensar sobre os mortos da próxima vez, ainda tenho pessoas para ver ao voltar."
  },
  AvgDialog_123118_Content_39 = {
    Text = "Você se refere a... Investigador?"
  },
  AvgDialog_123118_Content_4 = {
    Text = "<Shake:Pare de ligar! Por que essas névoas... estão sempre uivando?!>"
  },
  AvgDialog_123118_Content_40 = {
    Text = "Antes que Mouchette pudesse responder, uma onda de impacto invisível surgiu de repente, fazendo seus pelos se arrepiarem instantaneamente, enquanto os monstros na névoa se tornavam ainda mais frenéticos."
  },
  AvgDialog_123118_Content_41 = {
    Text = "Esse sentimento...<Shake:<Big:O ritual começou!>>"
  },
  AvgDialog_123118_Content_42 = {
    Text = "A cerimônia está começando? Mas nós claramente salvamos aqueles humanos."
  },
  AvgDialog_123118_Content_43 = {
    Text = "E, Mensageiro Pálido, não havia Sacerdotes da Capela da Vida entre os cativos agora há pouco..."
  },
  AvgDialog_123118_Content_44 = {
    Text = "As pessoas que salvamos são apenas reservas? Ou o momento do ritual é fixo, então deve ser realizado mesmo que não haja sacrifícios suficientes?"
  },
  AvgDialog_123118_Content_45 = {
    Text = "Agora não é hora de brincar de detetive."
  },
  AvgDialog_123118_Content_46 = {
    Text = "Você vai continuar tagarelando aqui ou vai vir comigo? Tome sua decisão rapidamente!"
  },
  AvgDialog_123118_Content_47 = {
    Text = "Mouchette mostrou uma expressão impaciente, se virou, de costas para você, e entrou na espessa névoa."
  },
  AvgDialog_123118_Content_48 = {Text = "Mouchette!"},
  AvgDialog_123118_Content_49 = {
    Text = "Eu sei com o que você está preocupado. Desta vez, não farei nenhuma travessura."
  },
  AvgDialog_123118_Content_5 = {
    Text = "Por causa desta névoa densa, pode não ser o \"Desastre da Névoa\" do seu mundo, e esses monstros não são os \"Objetos Antigos\" de que você fala."
  },
  AvgDialog_123118_Content_50 = {
    Text = "Mouchette balançou seu machado para dispersar a névoa humanoide que a emboscava enquanto respondia."
  },
  AvgDialog_123118_Content_51 = {
    Text = "Embora seu otimismo seja bastante problemático e algumas de suas palavras estejam cheias de idealismo irrealista que precisam ser trazidas à luz, ..."
  },
  AvgDialog_123118_Content_52 = {
    Text = "Mas sempre há algumas pessoas que insistem em salvar este mundo chato.\n<Small:Você é uma delas, e o investigador também...>"
  },
  AvgDialog_123118_Content_53 = {
    Text = "Talvez vocês se deem bem, quem sabe?"
  },
  AvgDialog_123118_Content_54 = {
    Text = "O tema se desviou um pouco... Aqueles ainda estão nos esperando..."
  },
  AvgDialog_123118_Content_55 = {
    Text = "Então por que você ainda não está correndo? Eu espero que isso acabe logo; eu quero ir para casa."
  },
  AvgDialog_123118_Content_56 = {
    Text = "Vamos, fique comigo, não fique para trás. Sou o vanguarda mais rápido da equipe de investigação do Reino da Névoa!"
  },
  AvgDialog_123118_Content_57 = {
    Text = "A silhueta de Mouchette correu para frente através da espessa névoa, e você trocou um olhar com Salvador antes de segui-la."
  },
  AvgDialog_123118_Content_6 = {
    Text = "<Shake:Eles... o que são eles?>"
  },
  AvgDialog_123118_Content_7 = {
    Text = "Mouchette não pôde deixar de cobrir os ouvidos, mas infelizmente, foi em vão."
  },
  AvgDialog_123118_Content_8 = {
    Text = "Essa dor e desespero lentamente se infiltram na carne e nos ossos do ouvinte com a névoa espessa, atingindo profundamente a alma."
  },
  AvgDialog_123118_Content_9 = {
    Text = "Posso discernir que suas almas... são os humanos sacrificados no último ritual."
  },
  AvgDialog_123119_Content_1 = {
    Text = "Entre Dimensões"
  },
  AvgDialog_123119_Content_10 = {
    Text = "Mouchette deu de ombros e apontou para a Porta Dimensional que estava constantemente exalando névoa densa, corroendo este mundo."
  },
  AvgDialog_123119_Content_100 = {
    Text = "Não, %player%, espera um pouco..."
  },
  AvgDialog_123119_Content_101 = {
    Text = "Mouchette quer impedir seu resgate. Depois de entender sobre a experiência que \"tu\" teve, ela está cheia de dúvidas e perguntas."
  },
  AvgDialog_123119_Content_102 = {
    Text = "Mas não há mais tempo. Uma sensação de puxão da alma a arrasta, teimosamente a levando para fora deste estranho mundo cheio de pontos de luz."
  },
  AvgDialog_123119_Content_103 = {
    Text = "E aquela mancha de luz que a inspirou estava ali, nem perto nem longe, emanando uma bondade suave e quente, fazendo-lhe uma última despedida."
  },
  AvgDialog_123119_Content_104 = {
    Text = "Mostre a informação @4 para @3 \"Eu\", e você poderá @2 voltar para casa @1."
  },
  AvgDialog_123119_Content_105 = {
    Text = "@2, adeus, Mouchette, @2… outra \"eu\"."
  },
  AvgDialog_123119_Content_106 = {
    Text = "Logo, aquele zumbido invisível se distorceu, se dissipou e, por fim, desapareceu completamente, levando consigo a visão, a audição e os diversos sentidos de Mouchette."
  },
  AvgDialog_123119_Content_107 = {
    Text = "Quando Mouchette recuperou a visão e a audição e voltou à realidade, ela viu novamente aquela figura familiar, aquela pessoa que ela não conseguia entender."
  },
  AvgDialog_123119_Content_108 = {
    Text = "Mouchette, saia daqui, eu e Salvador cuidaremos do resto."
  },
  AvgDialog_123119_Content_109 = {
    Text = "A Corrosão da \"Porta\" está se aprofundando, eu e o Mensageiro Pálido temos que nos preparar para o pior..."
  },
  AvgDialog_123119_Content_11 = {
    Text = "Então, eu tenho que ir, apenas eu posso ir."
  },
  AvgDialog_123119_Content_110 = {Text = "..."},
  AvgDialog_123119_Content_111 = {
    Text = "Mouchette? O que está fazendo aí parado? Saia daqui rápido."
  },
  AvgDialog_123119_Content_112 = {
    Text = "Olhando para você, emoções como raiva, fúria e compaixão se entrelaçavam no peito de Mouchette, fazendo com que ela não conseguisse dizer uma palavra."
  },
  AvgDialog_123119_Content_113 = {
    Text = "Finalmente, ela exalou com raiva, apertou os punhos e, relutante, começou a falar:"
  },
  AvgDialog_123119_Content_114 = {
    Text = "Desde o nosso primeiro encontro, eu deveria ter percebido que você é esse tipo de \"protagonista\" que é tão entusiasmado e se intromete, uma pessoa que eu nunca poderei entender."
  },
  AvgDialog_123119_Content_115 = {
    Text = "Mesmo que se passem 100 anos, eu nunca poderei entender os circuitos do seu cérebro. Então, eu desisti."
  },
  AvgDialog_123119_Content_116 = {Text = "O que?"},
  AvgDialog_123119_Content_117 = {
    Text = "Eu sei aquele valor de ondas de vibração que você mencionou, isso é outro @4@3..."
  },
  AvgDialog_123119_Content_118 = {
    Text = "Uma dor familiar a atingiu, distorcendo as palavras de Mouchette. Depois de tentar várias vezes sem conseguir expressar a realidade daquela mancha de luz, Mouchette desistiu."
  },
  AvgDialog_123119_Content_119 = {
    Text = "A menina substituiu as palavras por ações, segurando firmemente a sua mão, com uma expressão de determinação no rosto."
  },
  AvgDialog_123119_Content_12 = {
    Text = "Em suas palavras, é... oh, a sabedoria de sobrevivência neste mundo cruel."
  },
  AvgDialog_123119_Content_120 = {
    Text = "Eu vou resolver esse grande problema com você."
  },
  AvgDialog_123119_Content_121 = {
    Text = "Eu, Mouchette, a avançada mais notável do Grupo de Investigação, não vou terminar esta batalha como uma \"desertora\"."
  },
  AvgDialog_123119_Content_13 = {
    Text = "Ouvindo as palavras de Mouchette, você e Salvador não puderam evitar o silêncio, e então falaram ao mesmo tempo —"
  },
  AvgDialog_123119_Content_14 = {
    Text = "Não concordo, meu filho. O sacrifício deve ser feito por mim."
  },
  AvgDialog_123119_Content_15 = {
    Text = "Eu concordo. Eu prometo que vou te trazer de volta, ou te enviar para casa, custe o que custar."
  },
  AvgDialog_123119_Content_16 = {
    Text = "No mesmo momento, você e Salvador não puderam deixar de se olhar, expressando opiniões completamente opostas."
  },
  AvgDialog_123119_Content_17 = {
    Text = "%player%, por quê……"
  },
  AvgDialog_123119_Content_18 = {
    Text = "Então está combinado, a volta para casa fica por sua conta, %player%."
  },
  AvgDialog_123119_Content_19 = {
    Text = "Mouchette interrompe antes que você ou Salvador possam reagir, caminhando em direção ao desconhecido e ominoso Portal."
  },
  AvgDialog_123119_Content_2 = {
    Text = "Mouchette, você está dizendo que vai entrar naquela \"porta\" desconhecida...?"
  },
  AvgDialog_123119_Content_20 = {
    Text = "Você segura firmemente a chave de prata com uma mão e puxa Salvador com a outra, observando a figura de Mouchette, totalmente concentrado, sem ousar piscar."
  },
  AvgDialog_123119_Content_21 = {
    Text = "Salvador, ouça-me, talvez... Mouchette seja diferente."
  },
  AvgDialog_123119_Content_22 = {
    Text = "Esta é a porta que conecta a outra dimensão, e Mouchette vem daquela dimensão, até mesmo foi convocada pelo mesmo ritual."
  },
  AvgDialog_123119_Content_23 = {
    Text = "Mas…… e se……"
  },
  AvgDialog_123119_Content_24 = {
    Text = "Se houver alguma situação errada, eu ativarei a chave de prata e transferirei a conexão para mim."
  },
  AvgDialog_123119_Content_25 = {
    Text = "Salvador olha para os seus olhos que tentam aparentar calma, e vê você segurando com força a chave de prata, finalmente soltando um suspiro."
  },
  AvgDialog_123119_Content_26 = {
    Text = "Se for esse o caso, por favor, me deixe assumir a responsabilidade."
  },
  AvgDialog_123119_Content_27 = {
    Text = "Mensageiro Pálido, eu nunca deixarei você cair antes de mim."
  },
  AvgDialog_123119_Content_28 = {
    Text = "Sua resposta é um sorriso de compreensão."
  },
  AvgDialog_123119_Content_29 = {
    Text = "Ao mesmo tempo, Mouchette estava levantando a mão, tentando tocar aquela porta invisível."
  },
  AvgDialog_123119_Content_3 = {
    Text = "Não apenas você, até mesmo Salvador ficou surpreso."
  },
  AvgDialog_123119_Content_30 = {
    Text = "<Shake:Isso...>"
  },
  AvgDialog_123119_Content_31 = {
    Text = "No momento em que Mo Xia tocou o Portão Invisível, ele emitiu de repente uma luz brilhante, assim como antes."
  },
  AvgDialog_123119_Content_32 = {
    Text = "Ao mesmo tempo, você também ativou a Chave de Prata."
  },
  AvgDialog_123119_Content_33 = {
    Text = "A luz irrompida da Chave de Prata ressoava com o brilho da porta invisível, enquanto o céu cheio de prata e sangue parecia ser guiado por algo etéreo, fervendo e surgindo."
  },
  AvgDialog_123119_Content_34 = {
    Text = "Sob a combinação de dois, um zumbido desconhecido capaz de corroer almas ressoou, misturando-se com uma névoa densa e infinita, impactando tudo ao redor, fazendo com que todos presentes fossem envolvidos em uma espécie de deslumbramento de separação entre espírito e corpo..."
  },
  AvgDialog_123119_Content_35 = {
    Text = "O mundo@2 é vasto, como@2@1 como uma névoa densa, @3, há algo@2 se formando neste nada@3."
  },
  AvgDialog_123119_Content_36 = {
    Text = "@1apenas uma grande @4Ilusão quando @2acidental, este pequeno @2luta, se contorce @2, evolui, transformando-se na @4raça."
  },
  AvgDialog_123119_Content_37 = {
    Text = "Do escuro, ecoa o som distorcido da flauta do Caos, destruindo a vontade de Mouchette; embora seja uma melodia, ela vislumbra vagamente o terror que se esconde por trás de seu significado."
  },
  AvgDialog_123119_Content_38 = {
    Text = "Humanos, isso é uma autoidentificação de @3. Comparado ao infinito @1 universo, são @4 pequenos e efêmeros."
  },
  AvgDialog_123119_Content_39 = {
    Text = "@3 não é que @3 não tenha deixado, mas sim que flui de geração em geração @1 sangue e prata, @4 marcas de @2 @1 evidência."
  },
  AvgDialog_123119_Content_4 = {
    Text = "Isso mesmo. Eu vou entrar e te ajudar a investigar aquelas ondas de vibração."
  },
  AvgDialog_123119_Content_40 = {
    Text = "O som distorcido da flauta do Caos tornou-se cada vez mais agudo e aterrorizante, como se torturasse a alma de Mouchette. Ela não pôde mais suportar e, de repente, abriu os olhos."
  },
  AvgDialog_123119_Content_41 = {
    Text = "Depois de abrir os olhos, Mouchette não ouviu o som da flauta, nem viu algum músico. O entorno era estranho e colorido, com grandes manchas de luz a cercá-la, mantendo uma distância nem perto nem longe."
  },
  AvgDialog_123119_Content_42 = {
    Text = "Prazer em vê-la, Mouchette, \"Eu\" minha amiga."
  },
  AvgDialog_123119_Content_43 = {
    Text = "A mancha de luz emitiu um zumbido, e o mais estranho é que ela conseguiu entender completamente. \n Ou seja, naquele momento, ela também era a mancha de luz."
  },
  AvgDialog_123119_Content_44 = {
    Text = "Eu morri? Então é assim que é a sensação de estar morto..."
  },
  AvgDialog_123119_Content_45 = {
    Text = "Não, você ainda está vivo. Você apenas foi trazido para cá por mim. Há o sopro de \"Eu\" em você."
  },
  AvgDialog_123119_Content_46 = {
    Text = "Se eu não fizer isso, você sofrerá a travessia da dimensão da falha por causa de @4, porque você já foi @3."
  },
  AvgDialog_123119_Content_47 = {
    Text = "Mouchette não ouviu as últimas palavras do ponto de luz, pois no instante em que a sílaba caótica soou, sua cabeça começou a doer intensamente, quase se partindo."
  },
  AvgDialog_123119_Content_48 = {
    Text = "<Shake:Pare! Pare! Diga algo que eu possa ouvir... Se isso continuar, minha cabeça vai explodir.>"
  },
  AvgDialog_123119_Content_49 = {
    Text = "Ela parecia ter ouvido o suspiro das luzes, ou talvez não, pois inúmeras informações estranhas inundaram a mente de Mouchette, atraindo toda a sua atenção."
  },
  AvgDialog_123119_Content_5 = {
    Text = "Criança, você não entende o perigo que isso representa; o trauma da dimensão espiritual também afetará o mundo real, você..."
  },
  AvgDialog_123119_Content_50 = {
    Text = "O que é isto?"
  },
  AvgDialog_123119_Content_51 = {
    Text = "O que vocês precisam neste momento. Mostre para \"eu\", {Male=ele,Female=ela} entenderá."
  },
  AvgDialog_123119_Content_52 = {
    Text = "O que eu, seu, não consigo entender—"
  },
  AvgDialog_123119_Content_53 = {
    Text = "Espere, você é... %player%?"
  },
  AvgDialog_123119_Content_54 = {
    Text = "Isso é impossível, acabei de te ver tão cheio de vida, parece que viver mais 100 anos não será um problema."
  },
  AvgDialog_123119_Content_55 = {
    Text = "Pontos de luz zumbem, emitindo uma risada suave; Mouchette não sabe se isso pode ser chamado de \"sorriso\", pois não há alegria. Para ser preciso, não há nenhuma emoção."
  },
  AvgDialog_123119_Content_56 = {
    Text = "Você pode entender isso como \"eu\" de outra dimensão, e eu, o verdadeiro eu——"
  },
  AvgDialog_123119_Content_57 = {
    Text = "Com as palavras dos pontos de luz, uma infinidade de informações inundou a mente de Mouchette. Essas informações continuavam a se dividir e se agregar, formando imagens instáveis."
  },
  AvgDialog_123119_Content_58 = {
    Text = "A princípio, essas imagens eram abstratas e manchadas, vagas e indistintas, mas logo—"
  },
  AvgDialog_123119_Content_59 = {
    Text = "Aquelas luzes e sombras estranhas se uniram em uma figura, uma figura que ela reconheceu."
  },
  AvgDialog_123119_Content_6 = {
    Text = "Só eu sou adequado aqui. Embora eu seja um pouco simples, não sou burro."
  },
  AvgDialog_123119_Content_60 = {
    Text = "A figura familiar acorda em meio a uma explosão, olhando para este mundo com confusão."
  },
  AvgDialog_123119_Content_61 = {
    Text = "Anos depois, as pessoas se referirão a essa explosão como a \"Explosão de Akutsk.\""
  },
  AvgDialog_123119_Content_62 = {
    Text = "Em seguida, {Male=ele,Female=ela} entrou em Misaq, obteve a Chave de Prata, tornou-se o \"Guardião do Segredo\" e começou a sair em missões com os companheiros chamados de \"Corpo Desperto\", investigando este mundo estranho e aterrorizante."
  },
  AvgDialog_123119_Content_63 = {
    Text = "Assim como ela e os investigadores, o Grupo de Investigação da Névoa."
  },
  AvgDialog_123119_Content_64 = {Text = "..."},
  AvgDialog_123119_Content_65 = {
    Text = "Ao se lembrar das pessoas e do passado familiares, Mouchette suspirou nostalgicamente. E sobre a vida de %player%, ela ainda continua——"
  },
  AvgDialog_123119_Content_66 = {
    Text = "Ela viu %player% atravessando a cidade nevada, enfrentando o cão de caça que atravessa o tempo e o espaço no sanatório cheio de segredos, testemunhando a eternidade do amor familiar."
  },
  AvgDialog_123119_Content_67 = {
    Text = "Eu também segui %player% para explorar a Cité, cheia de poesia e flores, ouvindo os suspiros das chamas e lamentando a murcha das rosas."
  },
  AvgDialog_123119_Content_68 = {
    Text = "E há navios fantasmas à deriva no mar. Fé, divindades e sacrifícios—junto com %player%, ela aprendeu a entender as distorções, crueldade e loucura deste mundo."
  },
  AvgDialog_123119_Content_69 = {
    Text = "Não importa quão profunda fosse a escuridão, %player% e os Corpos Despertos nunca desistiram."
  },
  AvgDialog_123119_Content_7 = {
    Text = "Mouchette interrompeu Salvador, olhando para vocês com uma expressão séria."
  },
  AvgDialog_123119_Content_70 = {
    Text = "Assim como naquele mundo, o Desastre da Névoa, os Restos Cinzentos e os Objetos Antigos não puderam derrotá-la e o investigador, nem poderiam derrotar a Equipe de Investigação do Reino da Névoa."
  },
  AvgDialog_123119_Content_71 = {
    Text = "Isso é melhor!"
  },
  AvgDialog_123119_Content_72 = {
    Text = "Eu me pergunto como aqueles pequenos caras na névoa estão agora?"
  },
  AvgDialog_123119_Content_73 = {
    Text = "Ah, eu realmente quero ter uma xícara fumegante de chá kava com avelã!"
  },
  AvgDialog_123119_Content_74 = {
    Text = "Mouchette sorriu. \n Ela pensou que %player% lutaria ao lado dos Despertadores para sempre—"
  },
  AvgDialog_123119_Content_75 = {
    Text = "É natural, porque ela nunca pensou em deixar a Equipe de Investigação da Névoa, e esses Despertadores naturalmente não pensariam em deixar seus Guardiões."
  },
  AvgDialog_123119_Content_76 = {
    Text = "Eles lutarão e lutarão até que os problemas do mundo sejam resolvidos, ou até que sejam resolvidos pelo mundo.\nAssim como em todas as histórias."
  },
  AvgDialog_123119_Content_77 = {
    Text = "Mas este mundo é muito mais cruel do que Mouchette imaginava, muito mais do que aquele em que ela habita."
  },
  AvgDialog_123119_Content_78 = {
    Text = "<Shake:Como isso pode acontecer!!>"
  },
  AvgDialog_123119_Content_79 = {
    Text = "Então você...!?"
  },
  AvgDialog_123119_Content_8 = {
    Text = "Salvador, sua habilidade é a base para mantivermos seguros na névoa densa, e %player%, é evidente que você e sua Chave de Prata são muito importantes."
  },
  AvgDialog_123119_Content_80 = {
    Text = "Você, seu sujeito, eu não deveria esperar que você desistisse de salvar este mundo chato."
  },
  AvgDialog_123119_Content_81 = {
    Text = "Sacrifícios para salvar os outros... essas coisas..."
  },
  AvgDialog_123119_Content_82 = {
    Text = "Mouchette não consegue mais continuar, pois tanto a raiva quanto a indignação já não adiantam."
  },
  AvgDialog_123119_Content_83 = {
    Text = "%player% é de fato amigo de Mouchette, mas Mouchette é apenas uma passageira neste mundo."
  },
  AvgDialog_123119_Content_84 = {
    Text = "O que separa os dois não é apenas uma \"dimensão\", mas também dois \"mundos\" completamente diferentes."
  },
  AvgDialog_123119_Content_85 = {
    Text = "Na verdade, meu sonho é sentar-me com as pessoas que amo ao redor de uma lareira aconchegante, desperdiçando nossas vidas que não têm valor algum."
  },
  AvgDialog_123119_Content_86 = {
    Text = "A neve lá fora está caindo lentamente, ano após ano, até o dia em que morrermos de velhice. Então, na minha lápide estará escrito: {Male=ele,Female=ela} era um inútil com longa vida e feliz."
  },
  AvgDialog_123119_Content_87 = {
    Text = "Até hoje, meu sonho nunca mudou."
  },
  AvgDialog_123119_Content_88 = {
    Text = "Então realize esse sonho, e se o mundo for destruído? E daí? Que mundo entediante, mesmo que seja destruído, e daí!?"
  },
  AvgDialog_123119_Content_89 = {
    Text = "É melhor do que deixar uma eterna arrependimento, ficar preso neste maldito lugar, sozinho para sempre!"
  },
  AvgDialog_123119_Content_9 = {
    Text = "Se algo acontecer com você, ninguém poderá resolver esse problema."
  },
  AvgDialog_123119_Content_90 = {
    Text = "A luz riu levemente novamente, mas Mouchette já não conseguia discernir se havia humor naquela voz.\n Pois seu coração estava cheio de amargura."
  },
  AvgDialog_123119_Content_91 = {
    Text = "Eu também quero realizar esse sonho, quero muito, mas…"
  },
  AvgDialog_123119_Content_92 = {
    Text = "Neste mundo cruel, sempre fazemos algumas \"escolhas\", algumas escolhas que nem mesmo conseguimos entender."
  },
  AvgDialog_123119_Content_93 = {
    Text = "Talvez não seja completamente incompreensível. Embora eu não tenha tomado uma xícara fumegante de chá kava com avelã, eu tenho meus próprios favoritos."
  },
  AvgDialog_123119_Content_94 = {
    Text = "O bolinho do Murphy, a dança da Liz, até mesmo as tarefas extras que a Doll sempre designava, agora que penso, estão cheias de diversão..."
  },
  AvgDialog_123119_Content_95 = {
    Text = "Chega, não diga mais nada. Você é um caso perdido..."
  },
  AvgDialog_123119_Content_96 = {
    Text = "Mouchette! Mouchette!"
  },
  AvgDialog_123119_Content_97 = {
    Text = "De repente, uma voz soou na mente de Mouchette. E ela, imediatamente, reconheceu a pessoa."
  },
  AvgDialog_123119_Content_98 = {
    Text = "Depois de ver \" {Male=ele,Female=ela} \" lutando e fazendo sacrifícios para salvar o mundo, ela pensou que seria difícil esquecer aquela voz, aquela pessoa."
  },
  AvgDialog_123119_Content_99 = {
    Text = "Agüente firme, eu e Salvador vamos te resgatar em breve! Eu prometi."
  },
  AvgDialog_123120_Content_1 = {
    Text = "A Auto-Oferta"
  },
  AvgDialog_123120_Content_10 = {
    Text = "Pai Salvador...?"
  },
  AvgDialog_123120_Content_100 = {
    Text = "Não sei até que ponto essa coisa maldita vai se espalhar, se realmente for igual ao meu mundo..."
  },
  AvgDialog_123120_Content_101 = {
    Text = "Mouchette não continuou, mas você entendeu seu subtexto—"
  },
  AvgDialog_123120_Content_102 = {
    Text = "O desastre da névoa é uma calamidade que pode afetar um mundo inteiro."
  },
  AvgDialog_123120_Content_103 = {
    Text = "É preciso acabar com esse ritual a qualquer custo...<Shake:Salvador!>"
  },
  AvgDialog_123120_Content_104 = {
    Text = "Estou aqui. Eu certamente garantirei a segurança de vocês... e também farei com que esses perdidos obtenham a verdadeira redenção..."
  },
  AvgDialog_123120_Content_105 = {
    Text = "Em seguida, uma luz quente e suave apareceu de repente sobre Salvador, se espalhando até você e Mouchette, isolando os danos da Catástrofe de Névoa."
  },
  AvgDialog_123120_Content_106 = {
    Text = "Mouchette, para fechar esta fenda espacial, a seguir eu preciso medir e determinar as ondas de vibração da dimensão espiritual, a luta fica por sua conta."
  },
  AvgDialog_123120_Content_107 = {
    Text = "Batalha? Sem problemas. Comigo aqui, você não vai perder um fio de cabelo!"
  },
  AvgDialog_123120_Content_108 = {
    Text = "Depois de tanto tempo, finalmente posso desabafar——"
  },
  AvgDialog_123120_Content_109 = {
    Text = "Todos adoram isso, jovens e velhos!\n<Big:Tornado Brilhante☆——!!>"
  },
  AvgDialog_123120_Content_11 = {
    Text = "Salvador respirou fundo em silêncio e, em seguida, exalou pesadamente."
  },
  AvgDialog_123120_Content_111 = {
    Text = "Uma machadada voa, dispersando uma série de névoas humanoides, abrindo um breve caminho seguro para você se aproximar daquela porta desconhecida que continuamente expele névoa densa."
  },
  AvgDialog_123120_Content_112 = {
    Text = "E você, operando continuamente os instrumentos de medição, tenta capturar as ondas de vibração de diferentes dimensões."
  },
  AvgDialog_123120_Content_113 = {
    Text = "Um minuto passou em silêncio.\nDois minutos passaram em silêncio."
  },
  AvgDialog_123120_Content_114 = {
    Text = "Então vieram três minutos, cinco minutos, dez minutos..."
  },
  AvgDialog_123120_Content_115 = {
    Text = "O suor cai da sua testa, você nunca sentiu o tempo tão longo."
  },
  AvgDialog_123120_Content_116 = {
    Text = "Quanto tempo mais? Eu sempre sinto que esses monstros parecem ter ficado mais fortes, é preciso golpeá-los várias vezes para dispersá-los..."
  },
  AvgDialog_123120_Content_117 = {
    Text = "Isso é uma manifestação de outra dimensão tentando invadir e devorar nosso mundo, não é, Mensageiro Pálido?"
  },
  AvgDialog_123120_Content_118 = {
    Text = "Mais uma gota de suor caiu da sua testa, e sob a tensão, você até se esqueceu de acenar com a cabeça."
  },
  AvgDialog_123120_Content_119 = {
    Text = "Ondas de vibração... estão em constante mudança..."
  },
  AvgDialog_123120_Content_12 = {
    Text = "Não há mais necessidade de procurar, Padre White... está bem aqui."
  },
  AvgDialog_123120_Content_120 = {
    Text = "Pode ser devido à névoa densa em si, ou a interferência das almas presas na névoa... Eu preciso de tempo para investigar."
  },
  AvgDialog_123120_Content_121 = {
    Text = "Você olhou para o céu, e neste momento não consegue mais ver as \"Estrelas\".\n O mundo inteiro parece ter se reduzido a uma densa névoa, e à Porta Dimensional que continua a exalar essa névoa espessa."
  },
  AvgDialog_123120_Content_122 = {
    Text = "Mas não temos mais tempo."
  },
  AvgDialog_123120_Content_123 = {
    Text = "...Você está absolutamente certo."
  },
  AvgDialog_123120_Content_124 = {
    Text = "Você guardou o instrumento de medição e levantou a mão segurando a chave de prata."
  },
  AvgDialog_123120_Content_125 = {
    Text = "Parece que só posso arriscar tudo agora…"
  },
  AvgDialog_123120_Content_126 = {
    Text = "Mensageiro Pálido, você deseja se conectar...?"
  },
  AvgDialog_123120_Content_127 = {
    Text = "Salvador franzia a testa, olhando para você com desaprovação. E você, apenas em silêncio."
  },
  AvgDialog_123120_Content_128 = {
    Text = "Ei, ei, também há um \"convidado de outro mundo\" aqui. Você pode dizer algo que eu possa entender?"
  },
  AvgDialog_123120_Content_129 = {
    Text = "O que %player% quer dizer é... conectar aquela porta desconhecida para determinar as ondas de vibração da dimensão."
  },
  AvgDialog_123120_Content_13 = {
    Text = "O Grande Sacerdote no altar... é o Padre White."
  },
  AvgDialog_123120_Content_130 = {
    Text = "O que? Aquela coisa é muito estranha, quem sabe qual será o resultado, não faça besteira."
  },
  AvgDialog_123120_Content_131 = {
    Text = "Você segura firmemente a chave de prata e caminha em direção àquela porta de luz invisível com uma expressão pesada. Neste momento, a ação supera as palavras."
  },
  AvgDialog_123120_Content_132 = {
    Text = "Eu realmente admiro vocês que acreditam que este mundo chato ainda tem valor para ser salvo..."
  },
  AvgDialog_123120_Content_133 = {
    Text = "Inesperadamente, Mouchette estendeu a mão para te parar. Sua expressão era complexa enquanto olhava para você, como se estivesse te vendo, mas ao mesmo tempo, olhando através de você, vendo outra pessoa."
  },
  AvgDialog_123120_Content_134 = {
    Text = "No final, todos os emaranhados se transformaram em um sorriso em seu rosto, e Mouchette se esforçou para fazer sua voz soar relaxada."
  },
  AvgDialog_123120_Content_135 = {
    Text = "Deixa pra lá, quem mandou eu ser o vanguarda mais notável do Grupo de Investigação? É natural estar na frente—"
  },
  AvgDialog_123120_Content_136 = {
    Text = "Então, deixe-me ir."
  },
  AvgDialog_123120_Content_137 = {
    Text = "Mouchette olha para você, sua expressão séria e resoluta."
  },
  AvgDialog_123120_Content_138 = {
    Text = "Começando do canto da jaula, esta é a primeira vez que ela mostrou uma expressão tão séria."
  },
  AvgDialog_123120_Content_14 = {Text = "O que?!"},
  AvgDialog_123120_Content_15 = {
    Text = "Em choque, você não pôde deixar de se virar para White, vendo o ex-sacerdote da Igreja da Vida, agora o líder de um culto, falando apaixonadamente."
  },
  AvgDialog_123120_Content_16 = {
    Text = "Neste momento, fazemos uma escolha ao custo de prata e sangue, e nunca nos arrependeremos disso."
  },
  AvgDialog_123120_Content_17 = {
    Text = "Para chegar ao \"Reino da Calma Sem Sofrimento de Dissipação\", para nos redimir neste mundo em chamas —"
  },
  AvgDialog_123120_Content_18 = {
    Text = "Para ir ao \"Reino da Calma Sem Sofrimento de Dissipação\", para redimir a nós mesmos neste mundo em chamas —"
  },
  AvgDialog_123120_Content_19 = {
    Text = "Uma dúzia de crentes da Aurora Estelar jurou em uníssono—"
  },
  AvgDialog_123120_Content_2 = {
    Text = "<Shake:Este mundo está queimando, este mundo está desmoronando, este mundo está destinado à destruição.>"
  },
  AvgDialog_123120_Content_20 = {
    Text = "Uma dúzia de crentes da Aurora Estelar levantou suas adagas prateadas em uníssono—"
  },
  AvgDialog_123120_Content_21 = {Text = "Pare!"},
  AvgDialog_123120_Content_22 = {
    Text = "Em seu grito, a adaga prateada mergulha simultaneamente no coração do gado humano, penetrando fundo e agitando-se violentamente."
  },
  AvgDialog_123120_Content_23 = {
    Text = "Um sangue ofuscante jorrou do peito da vítima sacrificial, manchando o altar de vermelho."
  },
  AvgDialog_123120_Content_24 = {
    Text = "Em meio a um mar de sangue, você emerge das sombras ocultas, encarando diretamente White, confrontando a fonte de toda essa tragédia."
  },
  AvgDialog_123120_Content_25 = {
    Text = "Outro tolo ignorante vem parar o ritual do Pai de Todos?"
  },
  AvgDialog_123120_Content_26 = {
    Text = "Ha, você foi indiferente quando o Cataclismo desceu, e agora que estou prestes a levar meus irmãos e irmãs à Redempção, você se atreve a me parar—"
  },
  AvgDialog_123120_Content_27 = {
    Text = "O líder do Clube do Amanhecer das Estrelas sorriu com desdém, olhando para vocês, e então seus olhos de repente se arregalaram, paralisando-se no lugar."
  },
  AvgDialog_123120_Content_28 = {
    Text = "<Shake:Bispo Salvador!?>"
  },
  AvgDialog_123120_Content_29 = {
    Text = "A expressão de Salvador estava envolta em tristeza, e você percebeu que sob seu amplo manto, sua figura alta e esbelta na verdade estava tremendo levemente."
  },
  AvgDialog_123120_Content_3 = {
    Text = "<Shake:O único caminho para a redenção é viajar para <Yellow:\"um reino tranquilo sem a dor da dispersão\">, que está logo acima de nós, no universo onde as estrelas brilham.>"
  },
  AvgDialog_123120_Content_30 = {
    Text = "White... meu filho perdido..."
  },
  AvgDialog_123120_Content_31 = {
    Text = "Oh, entendi, a criança que Sua Excelência, o bispo, veio salvar é na verdade o líder de um culto! Que interessante!"
  },
  AvgDialog_123120_Content_32 = {Text = "Mouchette!"},
  AvgDialog_123120_Content_33 = {
    Text = "Certo, certo, não vou dizer nada. Mesmo que eu não diga nada, os fatos não vão mudar, certo?"
  },
  AvgDialog_123120_Content_34 = {
    Text = "Então, o local caiu em silêncio, com apenas o sangue da humanidade escorrendo lentamente no altar, tingindo o chão."
  },
  AvgDialog_123120_Content_35 = {
    Text = "John, James, Anderson... eles eram todos seus colegas."
  },
  AvgDialog_123120_Content_36 = {
    Text = "Como sacerdote da Igreja da Vida... você deveria entender por que eles vieram a Hawick."
  },
  AvgDialog_123120_Content_37 = {
    Text = "……Claro que entendo."
  },
  AvgDialog_123120_Content_38 = {
    Text = "Porque eu vim aqui uma vez com ideais nobres, assim como eles!"
  },
  AvgDialog_123120_Content_39 = {
    Text = "A voz de White de repente ficou agitada, olhando ansiosamente para Salvador, como uma criança em busca de reconhecimento."
  },
  AvgDialog_123120_Content_4 = {
    Text = "<Shake:<Big:Encontre-o, abrace-o, dedique-se a ele! Só então nossas vidas receberão o alvorecer eterno——>>"
  },
  AvgDialog_123120_Content_40 = {
    Text = "E eu cumpri minha promessa, encontrando a única maneira de salvar meus irmãos e irmãs."
  },
  AvgDialog_123120_Content_41 = {Text = "..."},
  AvgDialog_123120_Content_42 = {
    Text = "A morte não é o ensinamento do Pai de Todos, White. Você se desviou do caminho."
  },
  AvgDialog_123120_Content_43 = {
    Text = "<Shake:Não! Eu ainda sigo a orientação do Pai God!>"
  },
  AvgDialog_123120_Content_44 = {
    Text = "O Pai de Todos proclama: <Italic: \"Todos nós somos Seus filhos, dignos de Seu amor\">, <Italic: \"Ame uns aos outros como você ama a si mesmo\">."
  },
  AvgDialog_123120_Content_45 = {
    Text = "O Pai de Todos aconselha <Italic:\"Aqueles entre vocês que são nobres serão meus Emissários, cumprindo minha vontade de erradicar o sofrimento desta Terra.\">."
  },
  AvgDialog_123120_Content_46 = {
    Text = "……não estão erradas. Tudo isso é a vontade do Pai Deus."
  },
  AvgDialog_123120_Content_47 = {
    Text = "E eu consegui. Eu vou salvar meus irmãos e irmãs, exterminando o sofrimento que lhes foi imposto."
  },
  AvgDialog_123120_Content_48 = {
    Text = "Eu os levarei para longe desta terra de sofrimento, guiando-os em direção à aurora que brilha entre as estrelas, em direção a isso—"
  },
  AvgDialog_123120_Content_49 = {
    Text = "<Yellow:<Big:Reino da Calma Sem Sofrimento de Dissipação>>."
  },
  AvgDialog_123120_Content_5 = {
    Text = "Na caverna repleta de símbolos de profanação, o líder do Clube do Amanhecer das Estrelas estava fazendo um discurso eloquente. Com o fim de suas palavras, a humanidade foi arrastada para o centro do altar."
  },
  AvgDialog_123120_Content_50 = {
    Text = "Para chegar ao \"Reino da Calma Sem Sofrimento de Dissipação\", para nos redimir neste mundo em chamas —"
  },
  AvgDialog_123120_Content_51 = {
    Text = "Para ir ao \"Reino da Calma Sem Sofrimento de Dissipação\", para nos redimir neste mundo em chamas —"
  },
  AvgDialog_123120_Content_52 = {
    Text = "Naquele momento, um riso frio atravessou os gritos fervorosos e ordenados dos crentes como uma adaga afiada."
  },
  AvgDialog_123120_Content_53 = {
    Text = "Um reino tranquilo sem a dor da dispersão? Você está falando sobre o mundo além da porta?"
  },
  AvgDialog_123120_Content_54 = {
    Text = "Que piada. Meu mundo não é tão maravilhoso assim."
  },
  AvgDialog_123120_Content_55 = {
    Text = "Catástrofe de Névoa, Antiguidades, Cinzas, e vários monstros mutantes, e qualquer um que você encontrar seria suficiente para vocês tomarem uma panela."
  },
  AvgDialog_123120_Content_56 = {
    Text = "Então, pare de falar essas bobagens sobre redenção, vocês estão apenas sacrificando os outros para salvar suas próprias vidas."
  },
  AvgDialog_123120_Content_57 = {
    Text = "<Shake:Não é assim! Porque—>"
  },
  AvgDialog_123120_Content_58 = {
    Text = "White deu um passo à frente, aproximando-se de Mouchette, levantando com emoção o punhal prateado que segurava nas mãos."
  },
  AvgDialog_123120_Content_59 = {
    Text = "Você protege instinctivamente Mouchette, mas o golpe esperado não vem."
  },
  AvgDialog_123120_Content_6 = {
    Text = "Você está se escondendo nas sombras não muito longe, confirmando cuidadosamente o número de sacrifícios humanos."
  },
  AvgDialog_123120_Content_60 = {
    Text = "O alvo da adaga era seu mestre desde o início—"
  },
  AvgDialog_123120_Content_61 = {
    Text = "O sangue jorra do coração de White, fluindo e se misturando com o sangue da humanidade no altar carmesim."
  },
  AvgDialog_123120_Content_62 = {
    Text = "<Shake:Agora... prata e sangue são suficientes...>"
  },
  AvgDialog_123120_Content_63 = {
    Text = "Com o sussurro de White, um impacto invisível irrompeu do altar."
  },
  AvgDialog_123120_Content_64 = {
    Text = "O sangue fluindo na superfície do altar começou a se contorcer e se elevar, junto com o corpo do sacrifício flutuando no ar."
  },
  AvgDialog_123120_Content_65 = {
    Text = "<Shake:Ah ah ah — Bispo Salvador...>"
  },
  AvgDialog_123120_Content_66 = {
    Text = "<Shake:Você viu...? Eu não traí a mim mesmo... a promessa ao Pai Deus...>"
  },
  AvgDialog_123120_Content_67 = {
    Text = "White gritou, seu corpo à beira da morte se contorcendo incessantemente, a prata e o sangue dentro dele sendo extraídos por uma força invisível, desenhando padrões estranhos no céu."
  },
  AvgDialog_123120_Content_68 = {
    Text = "<Shake:Bispo, eu sei que cometi um pecado... estou disposto a arcar com os pecados, junto com os deles.>"
  },
  AvgDialog_123120_Content_69 = {
    Text = "<Shake:Mas eu nunca me arrependo... porque eu salvei meus irmãos e irmãs... nesta terra de sofrimento...>"
  },
  AvgDialog_123120_Content_7 = {
    Text = "John, James, Anderson... eles estão todos aqui."
  },
  AvgDialog_123120_Content_70 = {
    Text = "O olhar de White estava fixo em Salvador. E Salvador, o bispo que um dia se dedicou a nutrí-lo, desenhou lentamente o símbolo sagrado do Todo-Pai no ar."
  },
  AvgDialog_123120_Content_71 = {
    Text = "A mão marcada com o símbolo sagrado tremia, suprimindo o impulso de \"abençoar\". Pois Salvador sabia que a criança perdida havia feito sua própria escolha."
  },
  AvgDialog_123120_Content_72 = {
    Text = "Ainda não concordo com o que você fez, White, mas você realmente está seguindo os ensinamentos do Pai Deus. Então..."
  },
  AvgDialog_123120_Content_73 = {
    Text = "Que o Pai Deus te perdoe, que você... possa retornar ao abraço do Pai Deus... se libertar do sofrimento e obter redenção..."
  },
  AvgDialog_123120_Content_74 = {
    Text = "Salvador suspirou e fez sua última oração."
  },
  AvgDialog_123120_Content_75 = {
    Text = "Mas White não podia mais ouvir nada. \n Sua expressão oscilava entre um sorriso de felicidade e uma dor extrema, seu coração parou de bater."
  },
  AvgDialog_123120_Content_76 = {
    Text = "E então, a prata e o sangue flutuando no ar de repente começaram a se agitar, como inúmeras \"Estrelas\" ferventes, iluminando o céu noturno."
  },
  AvgDialog_123120_Content_77 = {
    Text = "Nesta luz ofuscante e grandiosa, inúmeras manchas de luz desconhecidas se reorganizam e se agregam, formando uma porta invisível cujo destino é desconhecido."
  },
  AvgDialog_123120_Content_78 = {
    Text = "É isso que chamam de \"Porta\"?"
  },
  AvgDialog_123120_Content_79 = {
    Text = "Com isso, posso retornar ao meu próprio mundo?"
  },
  AvgDialog_123120_Content_8 = {
    Text = "Então, só precisamos do Pai Branco...?"
  },
  AvgDialog_123120_Content_80 = {
    Text = "É difícil dizer. Em teoria, podemos conectar as mesmas dimensões várias vezes simulando as mesmas ondas de vibração, mas na prática, é fácil que ocorram imprevistos."
  },
  AvgDialog_123120_Content_81 = {
    Text = "Especialmente com esse tipo de ritual de sacrifício, que está cheio de muitas variáveis e pode levar a mais problemas—"
  },
  AvgDialog_123120_Content_82 = {
    Text = "Espere, não vá para lá!"
  },
  AvgDialog_123120_Content_83 = {
    Text = "Você levanta a voz para parar os seguidores da seita marchando em uníssono em direção ao portão intangível, mas eles parecem não te ouvir e continuam avançando com um passo calmo."
  },
  AvgDialog_123120_Content_84 = {
    Text = "Para ir ao \"Reino da Calma Sem Sofrimento de Dissipação\", para nos redimir neste mundo em chamas——"
  },
  AvgDialog_123120_Content_85 = {
    Text = "Para chegar ao \"Reino da Calma Sem Sofrimento de Dissipação\", para nos redimirmos neste mundo em chamas —"
  },
  AvgDialog_123120_Content_86 = {
    Text = "Finalmente, o primeiro crente levantou a mão e tocou aquela porta invisível, entrando no novo mundo que tanto desejava."
  },
  AvgDialog_123120_Content_87 = {
    Text = "<Shake:AAAAA——>"
  },
  AvgDialog_123120_Content_88 = {
    Text = "Em meio a gritos desesperados, as mãos dos fiéis que tocavam a porta de luz começaram a se distorcer e a se fundir, derretendo na luz intensa que emanava repentinamente da porta invisível."
  },
  AvgDialog_123120_Content_89 = {
    Text = "Em seguida, uma névoa densa e interminável jorrou daquela porta invisível, devorando a carne e sangue e a alma dos crentes, transformando aqueles que desejavam ir em direção às estrelas em parte das \"Estrelas\"."
  },
  AvgDialog_123120_Content_9 = {Text = "..."},
  AvgDialog_123120_Content_90 = {
    Text = "O comunicador personalizado começou a emitir novamente o som elétrico de falha, reproduzindo aquele sussurro familiar de morte iminente."
  },
  AvgDialog_123120_Content_91 = {
    Text = "@2I... salvar @2..."
  },
  AvgDialog_123120_Content_92 = {
    Text = "Salvar @2... @2 me..."
  },
  AvgDialog_123120_Content_93 = {
    Text = "Isto é... <Shake:O ritual deu errado!>"
  },
  AvgDialog_123120_Content_94 = {
    Text = "Salvador, cuidado com os monstros na névoa!"
  },
  AvgDialog_123120_Content_95 = {
    Text = "Assim que as palavras foram ditas, uma quantidade incontável de névoa em forma de humanoides se formou na densa névoa ao redor, rugindo em direção a vocês."
  },
  AvgDialog_123120_Content_96 = {
    Text = "As coisas finalmente ficaram divertidas."
  },
  AvgDialog_123120_Content_97 = {
    Text = "Mouchette —"
  },
  AvgDialog_123120_Content_98 = {
    Text = "Certo, não vou mais falar, mas preciso te lembrar que a catástrofe de névoa está se espalhando."
  },
  AvgDialog_123120_Content_99 = {
    Text = "...Mensageiro Pálido, há pouco eu ainda conseguia ver a paisagem ao redor, agora não consigo mais ver nada."
  },
  AvgDialog_123121_Content_1 = {
    Text = "Estrelas Extintas"
  },
  AvgDialog_123121_Content_10 = {
    Text = "Com sua força, você definitivamente não deveria ser aprisionado por alguns patéticos seguidores de cultos."
  },
  AvgDialog_123121_Content_11 = {
    Text = "E eu acho que ambos notamos que esta senhora perguntou várias vezes sobre a hora da cerimônia, e sua expressão... é claramente de expectativa."
  },
  AvgDialog_123121_Content_12 = {
    Text = "Ah, foi aqui que me expus... fui descuidado."
  },
  AvgDialog_123121_Content_13 = {
    Text = "Então, quem é você? O que é esse ritual? E o que você sabe?"
  },
  AvgDialog_123121_Content_14 = {
    Text = "Mouchette mostrou um sorriso desinteressado e, em vez de responder, fez uma pergunta de volta —"
  },
  AvgDialog_123121_Content_15 = {
    Text = "E vocês? Por que vieram para este lugar onde a ordem secular está completamente em colapso, restando apenas crenças entediantes?"
  },
  AvgDialog_123121_Content_16 = {
    Text = "Salvador não insistiu na ofensa à fé nas palavras de Mouchette, apenas mostrando uma expressão de pena."
  },
  AvgDialog_123121_Content_17 = {
    Text = "Eu venho para redenção."
  },
  AvgDialog_123121_Content_18 = {
    Text = "Redenção? Redenção de quem? Daquela humanidade? Desculpe-me ser direto, mas às vezes é melhor morrer de forma rápida do que viver com dor."
  },
  AvgDialog_123121_Content_19 = {
    Text = "Particularmente neste mundo... hum, excitante e divertido."
  },
  AvgDialog_123121_Content_2 = {
    Text = "Após enviar um sinal à Santa Sé da Vida, você e Salvador aguardaram do lado de fora da caverna pela estranha garota que se chama \"Mouchette.\""
  },
  AvgDialog_123121_Content_20 = {
    Text = "A bênção do Pai de Todos será espalhada para cada canto que anseia por redenção."
  },
  AvgDialog_123121_Content_21 = {
    Text = "Esses prisioneiros clamam a mim e à Igreja da Vida por ajuda em seu sofrimento, e certamente responderemos aos seus apelos."
  },
  AvgDialog_123121_Content_22 = {
    Text = "Como Executor do Pai Deus, farei o meu melhor para eliminar o sofrimento nesta Terra."
  },
  AvgDialog_123121_Content_23 = {
    Text = "Salvador baixou a cabeça, juntando as mãos em devoção e fazendo uma reverência. \n A resposta dele foi um leve riso de Mouchette."
  },
  AvgDialog_123121_Content_24 = {
    Text = "Eu suponho que vocês sejam aquelas pessoas boas no sentido mundano, que acreditam em coisas tediosas como eu amo as pessoas e as pessoas me amam, certo?"
  },
  AvgDialog_123121_Content_25 = {
    Text = "É por isso que você acreditou em mim tão facilmente e me seguiu até aqui..."
  },
  AvgDialog_123121_Content_26 = {
    Text = "É tão ingênuo que dá dor de cabeça."
  },
  AvgDialog_123121_Content_27 = {
    Text = "Você não consegue discernir se a expressão de Mouchette é de provocação ou nostalgia, enquanto uma névoa que surge do nada obscurece seu rosto."
  },
  AvgDialog_123121_Content_28 = {
    Text = "Você está errado, nós apenas não queremos interpretar maliciosamente um estranho."
  },
  AvgDialog_123121_Content_29 = {
    Text = "Ah, tanto faz, porque vocês não entendem nada..."
  },
  AvgDialog_123121_Content_3 = {
    Text = "E quando Mouchette apareceu na borda da sua visão, ela inesperadamente tinha um machado estiloso na mão."
  },
  AvgDialog_123121_Content_30 = {
    Text = "Nesse momento, um som repentino de um interruptor interrompeu as palavras de Mouchette."
  },
  AvgDialog_123121_Content_31 = {
    Text = "O comunicador detectou flutuações espirituais... A fonte é... névoa?!"
  },
  AvgDialog_123121_Content_32 = {
    Text = "Inconscientemente, aquele fio de névoa continuou a se expandir, obscurecendo não apenas a maior parte da figura de Mouchette, mas também a paisagem ao redor."
  },
  AvgDialog_123121_Content_33 = {
    Text = "Onda espiritual? Então é assim que vocês explicam a \"Catástrofe de Névoa\"..."
  },
  AvgDialog_123121_Content_34 = {
    Text = "\"Desastre da névoa\"?"
  },
  AvgDialog_123121_Content_35 = {
    Text = "Claro, este mundo em colapso não terá coisas tão interessantes, ele vem de mim—"
  },
  AvgDialog_123121_Content_36 = {
    Text = "De <Yellow:meu mundo>."
  },
  AvgDialog_123121_Content_37 = {
    Text = "Seu mundo...?"
  },
  AvgDialog_123121_Content_38 = {
    Text = "Aqueles tolos do Amanhecer das Estrelas abriram a porta proibida que não deveria ser aberta."
  },
  AvgDialog_123121_Content_39 = {
    Text = "Então o ritual falhou com um \"crack—\", deixando apenas eu, o infeliz, e as coisas emaranhadas—"
  },
  AvgDialog_123121_Content_4 = {
    Text = "Como está? Não é muito estiloso?"
  },
  AvgDialog_123121_Content_40 = {
    Text = "Só uma lembrança amigável, vocês podem começar a pensar em quando escapar agora."
  },
  AvgDialog_123121_Content_41 = {
    Text = "Eles? Escapar?"
  },
  AvgDialog_123121_Content_42 = {
    Text = "Hum☆hum, aqueles pequenos na névoa estão quase chegando——"
  },
  AvgDialog_123121_Content_43 = {
    Text = "Desejo-lhes que se divirtam."
  },
  AvgDialog_123121_Content_44 = {
    Text = "Dizendo isso, Mouchette recuou, escondendo-se na densa névoa, com sua voz se afastando cada vez mais na neblina espessa."
  },
  AvgDialog_123121_Content_45 = {
    Text = "Além disso, obrigado pela sua ajuda. Estou devendo a você, então desta vez, todos vocês precisam me dar tempo suficiente~"
  },
  AvgDialog_123121_Content_46 = {
    Text = "……Mouchette, espere!?"
  },
  AvgDialog_123121_Content_47 = {
    Text = "Você quer impedi-la, mas a névoa espessa o deixa completamente sem ideia de por onde começar a persegui-la."
  },
  AvgDialog_123121_Content_48 = {
    Text = "Você reflete por um momento, agarra a Chave de Prata, se preparando para ativar \"Rastreamento Espiritual\", quando o comunicador emite um som novamente."
  },
  AvgDialog_123121_Content_49 = {
    Text = "Esse é um som estridente de uma corrente elétrica com falha, aumentando continuamente na névoa densa que se agita, ficando cada vez mais alto e mais claro."
  },
  AvgDialog_123121_Content_50 = {
    Text = "@2I... salvar @2..."
  },
  AvgDialog_123121_Content_51 = {Text = "...?!"},
  AvgDialog_123121_Content_52 = {
    Text = "Salvador, você ouviu?"
  },
  AvgDialog_123121_Content_53 = {
    Text = "Isso parece ser... uma voz humana?"
  },
  AvgDialog_123121_Content_54 = {
    Text = "Ao ouvir isso, você pegou o comunicador e aguardou o próximo som, e o comunicador respondeu —"
  },
  AvgDialog_123121_Content_55 = {
    Text = "Um grito de desespero capaz de perfurar o tímpano, como uma lâmina afiada cravando em sua cabeça, faz com que você fique imediatamente tonto."
  },
  AvgDialog_123121_Content_56 = {
    Text = "Enquanto isso, uma quantidade incontável de névoa em forma humana surgiu da névoa densa, rugindo em direção a você e Salvador."
  },
  AvgDialog_123121_Content_57 = {Text = "Cuidado!"},
  AvgDialog_123121_Content_58 = {
    Text = "O tablete atravessa a névoa densa, dispersando os monstros formados pela névoa, mas aquele grito agudo ainda persiste, incessante, impactando sua alma."
  },
  AvgDialog_123121_Content_59 = {
    Text = "O sangue pinga incessantemente do seu nariz, espirrando no chão, mas você não consegue ver devido à tontura."
  },
  AvgDialog_123121_Content_6 = {
    Text = "Mo Xia balançou o machado algumas vezes, seus movimentos limpos e rápidos, como se essa enorme arma fosse parte dela."
  },
  AvgDialog_123121_Content_60 = {
    Text = "Sua mente parece ter se desvinculado do corpo, se expandindo continuamente em um estado invisível e caótico, sentindo a vila em que se encontra."
  },
  AvgDialog_123121_Content_61 = {
    Text = "Você sente que — a névoa densa e onipresente devora sem pudor a terra, os edifícios e qualquer vestígio de existência humana ou não humana."
  },
  AvgDialog_123121_Content_62 = {
    Text = "E nesta névoa densa e infinita, inúmeras estrelas queimam friamente em silêncio, claramente já mortas há muito tempo."
  },
  AvgDialog_123121_Content_63 = {Text = "%player%!"},
  AvgDialog_123121_Content_64 = {
    Text = "A voz de Salvador ressoa em sua mente, mas o desespero e a dor que se propagam das profundezas da alma te paralisam."
  },
  AvgDialog_123121_Content_65 = {
    Text = "@2I... salvar @2..."
  },
  AvgDialog_123121_Content_66 = {
    Text = "Salvar @2... @2 me..."
  },
  AvgDialog_123121_Content_67 = {
    Text = "Aquelas estrelas mortas trazem uma infinidade de desespero e dor, circundando você, derretendo-o teimosamente, corroendo-o, querendo puxá-lo para o Descanso Eterno."
  },
  AvgDialog_123121_Content_68 = {
    Text = "...Eu não posso simplesmente adormecer assim, Thrall..."
  },
  AvgDialog_123121_Content_69 = {
    Text = "Sal...vador... ajude-me..."
  },
  AvgDialog_123121_Content_7 = {
    Text = "Percebendo isso, você lançou uma ofensiva."
  },
  AvgDialog_123121_Content_70 = {
    Text = "Naquele momento, uma luz suave brilhou em seu mundo, como o sol mais quente, envolvendo você firmemente e dissipando toda a frieza e a sensação de morte."
  },
  AvgDialog_123121_Content_71 = {
    Text = "Essa é a radiância de Salvador."
  },
  AvgDialog_123121_Content_72 = {
    Text = "Ele ouviu seu pedido."
  },
  AvgDialog_123121_Content_73 = {
    Text = "Ele respondeu ao seu pedido."
  },
  AvgDialog_123121_Content_74 = {
    Text = "<Shake:Cof cof...>"
  },
  AvgDialog_123121_Content_75 = {
    Text = "Com a ajuda de Salvador, você finalmente saiu daquela névoa vertiginosa. Você arfou, sentindo que recuperou parte da sanidade."
  },
  AvgDialog_123121_Content_76 = {
    Text = "Salvador, você pode parar de conceder bênçãos, eu já estou muito melhor."
  },
  AvgDialog_123121_Content_77 = {
    Text = "Salvador acenou com a cabeça, dedicando-se completamente à luta contra a ameaça desconhecida na névoa."
  },
  AvgDialog_123121_Content_78 = {
    Text = "Esses monstros na névoa não morrerão. Mesmo se forem dispersos, aparecerão novamente rapidamente."
  },
  AvgDialog_123121_Content_79 = {
    Text = "Receio que enquanto essa névoa existir, esses monstros viverão para sempre."
  },
  AvgDialog_123121_Content_8 = {
    Text = "Mouchette, você se deixou capturar voluntariamente pelos seguidores de culto."
  },
  AvgDialog_123121_Content_80 = {
    Text = "Pai Salvador, você acredita... que o que Mouchette disse é verdade?"
  },
  AvgDialog_123121_Content_81 = {
    Text = "Desde o momento em que nos encontramos, o fogo da alma da Lady Mouchette permaneceu constante. Na minha opinião, ela não demonstrou nem a atitude de uma mentirosa, nem o motivo para mentir."
  },
  AvgDialog_123121_Content_82 = {
    Text = "Bem, tenho algumas hipóteses. No entanto, precisamos encontrar Mouchette primeiro."
  },
  AvgDialog_123121_Content_83 = {
    Text = "Respeito sua decisão, Mensageiro Pálido."
  },
  AvgDialog_123121_Content_84 = {
    Text = "Não se preocupe com os monstros na névoa, eu vou garantir sua segurança."
  },
  AvgDialog_123121_Content_85 = {
    Text = "Você olha gratamente para Salvador e, em seguida, move a mão em direção à chave de prata."
  },
  AvgDialog_123121_Content_86 = {
    Text = "O sangue cai novamente de suas bochechas, mas você permanece impassível, as terríveis suposições da vertigem anterior dominam toda a sua mente."
  },
  AvgDialog_123121_Content_87 = {
    Text = "@2I... salvar @2..."
  },
  AvgDialog_123121_Content_88 = {
    Text = "Salvar @2... @2 me..."
  },
  AvgDialog_123121_Content_89 = {
    Text = "Finalmente, enquanto o comunicador emitia ruído mais uma vez, você atravessou inúmeras estrelas frias e mortas e tocou o espírito de Mouchette."
  },
  AvgDialog_123121_Content_9 = {
    Text = "Hã? Você está brincando? Uma pessoa normal não se tornaria voluntariamente prisioneira de um culto, trancada em uma jaula sem comida ou água."
  },
  AvgDialog_123122_Content_1 = {
    Text = "Através do Teu Olhar"
  },
  AvgDialog_123122_Content_10 = {
    Text = "Estou ocupado agora e não tenho tempo para jogar jogos de faz de conta chatos, muito menos interesse em interpretar o papel da filha educada."
  },
  AvgDialog_123122_Content_11 = {
    Text = "Você não entende este mundo, nem sabe o verdadeiro custo e os efeitos do ritual do Amanhecer das Estrelas."
  },
  AvgDialog_123122_Content_12 = {
    Text = "Em outras palavras, os prisioneiros com quem você acabou de ser trancado são todos sacrifícios essenciais para o próximo ritual."
  },
  AvgDialog_123122_Content_13 = {
    Text = "Além disso, mesmo que o ritual seja realizado novamente, você não sabe se as portas entre os dois mundos se abrirão novamente e se você poderá retornar ao seu próprio mundo através delas."
  },
  AvgDialog_123122_Content_14 = {
    Text = "O movimento de Mouchette parou, e então ela mordeu os lábios com força."
  },
  AvgDialog_123122_Content_15 = {Text = "..."},
  AvgDialog_123122_Content_16 = {
    Text = "Criança, eu sei que você não veio a este mundo cruel por vontade própria e entendo seu desejo de voltar."
  },
  AvgDialog_123122_Content_17 = {
    Text = "Nós apenas esperamos poder te ajudar, evitando que você entre em um caminho errado."
  },
  AvgDialog_123122_Content_18 = {
    Text = "Você está dizendo que eu quero voltar para o meu próprio mundo através do ritual do Clube do Amanhecer das Estrelas, é um caminho errado?"
  },
  AvgDialog_123122_Content_19 = {
    Text = "A atitude recentemente suavizada de Mouchette parecia endurecer novamente, e seu tom estava cheio de sarcasmo afiado."
  },
  AvgDialog_123122_Content_2 = {
    Text = "Como vocês todos me encontraram?!"
  },
  AvgDialog_123122_Content_20 = {
    Text = "A névoa densa ao redor começa a agitar-se e a ondular."
  },
  AvgDialog_123122_Content_21 = {
    Text = "E o que é o caminho certo? Quem determina o que é o caminho certo? Você ou seu Deus?"
  },
  AvgDialog_123122_Content_22 = {
    Text = "A máscara finalmente caiu. Mouchette não esconde mais seu desprezo e desdém por Salvador."
  },
  AvgDialog_123122_Content_23 = {
    Text = "Que importa se você julgou certo ou errado? Vejo este mundo como ainda mais árido e desolado do que Taimuran."
  },
  AvgDialog_123122_Content_24 = {
    Text = "Onde está o \"Pai de Todos\" de quem você fala quando essas pessoas sofrem?"
  },
  AvgDialog_123122_Content_25 = {
    Text = "A névoa densa se agita cada vez mais intensamente, cobrindo o rosto de Mouchette e também a expressão de Salvador."
  },
  AvgDialog_123122_Content_26 = {
    Text = "A única coisa que você pode ouvir nesta névoa é o suspiro de Salvador e os sons estranhos que sinalizam a aproximação do perigo."
  },
  AvgDialog_123122_Content_27 = {Text = "Eu..."},
  AvgDialog_123122_Content_28 = {
    Text = "Fale à vontade, padre, já que você está sem nada para fazer."
  },
  AvgDialog_123122_Content_29 = {
    Text = "Assim que Mouchette terminou de falar, inúmeras névoas humanoides surgiram ao redor, vindo em direção a vocês."
  },
  AvgDialog_123122_Content_3 = {
    Text = "Algo deu errado com a névoa agora há pouco? Ou você também tem a habilidade de ver através da névoa como o investigador?"
  },
  AvgDialog_123122_Content_30 = {
    Text = "Mas o movimento de Mouchette foi mais rápido do que aquela névoa humanoide. Vendo que ela estava prestes a escapar, você não pôde deixar de gritar."
  },
  AvgDialog_123122_Content_31 = {
    Text = "Salvador, pare ela!"
  },
  AvgDialog_123122_Content_4 = {
    Text = "A surpresa de Mouchette não durou muito; em um instante, sua expressão se tornou calma."
  },
  AvgDialog_123122_Content_5 = {
    Text = "Você tem alguns meios de escapar dos artefatos na névoa. Mas—"
  },
  AvgDialog_123122_Content_6 = {
    Text = "<Big:<Shake:Não me atrapalhe de fazer meu trabalho!>>"
  },
  AvgDialog_123122_Content_7 = {
    Text = "Mouchette disse, segurando o machado firmemente, seu olhar cheio de vigilância e hostilidade."
  },
  AvgDialog_123122_Content_8 = {
    Text = "Mouchette, você não precisa fazer isso, não somos inimigos. Pelo menos, não agora."
  },
  AvgDialog_123122_Content_9 = {
    Text = "Mas antes de você tomar sua decisão, tenho um conselho que preciso transmitir a você."
  },
  AvgDialog_125040_Content_1 = {
    Text = "A inundação do Rio Sagrado trouxe problemas sem precedentes a Mythag. Inesperadamente, o Quarto de Xu se tornou um dos poucos lugares onde você pode buscar refúgio."
  },
  AvgDialog_125040_Content_10 = {
    Text = "Eu posso ser uma mentira, um pensamento passageiro, mas quando se trata de mim... é absolutamente entediante."
  },
  AvgDialog_125040_Content_11 = {Text = "...Uh? Xu?"},
  AvgDialog_125040_Content_12 = {Text = "Fog."},
  AvgDialog_125040_Content_13 = {
    Text = "Uma névoa fina e semelhante a uma teia envolve você em camadas."
  },
  AvgDialog_125040_Content_14 = {
    Text = "<Gray:Espera, você não estava imune? Não estávamos conversando e jogando Weiqi?! Por que vocês Corpos Despertos sempre dizem uma coisa e fazem outra?!>"
  },
  AvgDialog_125040_Content_15 = {
    Text = "Enquanto um fantasma dourado cintilante atravessa o crepúsculo, um toque semelhante a cetim envolve seus braços e costas, guiando-o a levantar o véu feito de névoa."
  },
  AvgDialog_125040_Content_16 = {
    Text = "Ah, porque eu sou realmente, realmente curioso."
  },
  AvgDialog_125040_Content_17 = {
    Text = "Quando eles me tocaram, estavam tocando um fantasma. Quando me olharam, foi através de mim, vendo o que eles \"pensavam\" ser seu amado."
  },
  AvgDialog_125040_Content_18 = {
    Text = "Mas você é diferente. Você tem a sombra de alguém? Se olhar de perto, cujo rosto você verá sob o meu leque...?"
  },
  AvgDialog_125040_Content_19 = {
    Text = "A névoa se afasta, e sob o leque, algo quente toca suavemente seu nariz. As penas no ombro da mulher caem, roçando suavemente sua pele inexplicavelmente trêmula."
  },
  AvgDialog_125040_Content_2 = {
    Text = "O Rio Sagrado não te afetou em nada?"
  },
  AvgDialog_125040_Content_20 = {
    Text = "<Gray:Ótimo. Escaldante—mais alguém afetado pelo Rio Sagrado.>"
  },
  AvgDialog_125040_Content_21 = {
    Text = "Xu, se eu não estiver enganado, o que você acabou de dizer foi \"sem distrações\" em vez disso."
  },
  AvgDialog_125040_Content_22 = {
    Text = "De fato, no Extremo Oriente, quando um monarca tem assuntos importantes a discutir com alguém, ele convida essa pessoa para entrar no cortinado, daí o termo — convidado no teatro."
  },
  AvgDialog_125040_Content_23 = {
    Text = "No entanto, para as mulheres, ser uma convidada no teatro tem outro significado."
  },
  AvgDialog_125040_Content_24 = {Text = "Toc."},
  AvgDialog_125040_Content_25 = {
    Text = "Uma gota de cera de vela caiu sobre a mesa, espalhando as peças de xadrez."
  },
  AvgDialog_125040_Content_26 = {
    Text = "A luz se apagou."
  },
  AvgDialog_125040_Content_27 = {
    Text = "Eu sempre precisei apenas ficar de lado, mas talvez você finalmente possa me ver."
  },
  AvgDialog_125040_Content_28 = {
    Text = "Só você me faz querer ficar atrás da cortina, enfrentando talvez o convidado mais importante da minha vida. Como eu poderia ter quaisquer \"distrações\"?"
  },
  AvgDialog_125040_Content_29 = {
    Text = "As algemas desaparecem, e esta divindade antiga e misteriosa claramente lhe deixou uma saída."
  },
  AvgDialog_125040_Content_3 = {
    Text = "Seja porque a fonte do poder vem dos três Aeons ou devido à minha proficiência nos caminhos do prazer, parece que não tenho distrações."
  },
  AvgDialog_125040_Content_30 = {
    Text = "E seu convite, cheio de alegria, mal audível, é difícil de distinguir entre real e falso."
  },
  AvgDialog_125040_Content_31 = {
    Text = "Eu caí no mar escuro, buscando a costa mas incapaz de encontrá-la..."
  },
  AvgDialog_125040_Content_4 = {
    Text = "Aqueles belos olhos brilhavam de alegria enquanto várias peças brancas tocavam levemente o tabuleiro de xadrez. Sua proprietária estava muito interessada em passar o tempo com este antigo jogo do Oriente."
  },
  AvgDialog_125040_Content_5 = {
    Text = "Os humanos são uma espécie estranha; eles perdem a compostura por uma alegria passageira, e uma vez que a obtêm, mostram imediatamente desinteresse."
  },
  AvgDialog_125040_Content_6 = {
    Text = "Ano após ano, eles se cansam uns dos outros. Somente ao tecer ilusões para eles, levando-os a abandonar a vida e a morte, a rasgar seus corações e arrancar seus fígados, podem eles nunca esquecer."
  },
  AvgDialog_125040_Content_7 = {
    Text = "A luz de vela tremeluzente contorna a figura da mulher sentada na cama, projetando uma silhueta tênue e sombria."
  },
  AvgDialog_125040_Content_8 = {
    Text = "O céu tinha escurecido completamente em algum momento, e ela soltou uma risada suave."
  },
  AvgDialog_125040_Content_9 = {
    Text = "Forçando boas famílias a entrarem no comércio, persuadindo @2 a retornar a uma vida virtuosa. Sou bastante bom nesse tipo de ato, tecendo uma história que é metade verdadeira e metade falsa, e então deixando-os ver esse semblante que carrega culpa ou amor não correspondido."
  },
  AvgDialog_126907_Content_1 = {
    Text = "Fogo do Passado"
  },
  AvgDialog_126907_Content_10 = {
    Text = "Então, vá em frente."
  },
  AvgDialog_126907_Content_11 = {
    Text = "Os olhos de Elsa brilhavam enquanto ela te puxava e, num piscar de olhos, começava a dança que deveria ser conduzida por você."
  },
  AvgDialog_126907_Content_12 = {
    Text = "A força dela é tão grande que quase te joga para fora, e em um instante, ela te puxa de volta com pura força."
  },
  AvgDialog_126907_Content_13 = {
    Text = "<Shake:Desculpe>,Lorde, eu vou me certificar de controlar melhor da próxima vez..."
  },
  AvgDialog_126907_Content_14 = {
    Text = "Você se sente como um pião sendo balançado, girando sem parar, e seus passos de dança, que já eram desajeitados, parecem ainda mais desajeitados."
  },
  AvgDialog_126907_Content_15 = {Text = "Pfft."},
  AvgDialog_126907_Content_16 = {
    Text = "Vendo sua vergonha, Ramona não consegue evitar um leve riso."
  },
  AvgDialog_126907_Content_17 = {
    Text = "Você encontra o olhar dela, sentindo os olhos sorridentes dela sussurrarem para você—"
  },
  AvgDialog_126907_Content_18 = {
    Text = "Lorde Dexter, hoje é a sua vez."
  },
  AvgDialog_126907_Content_19 = {Text = "..."},
  AvgDialog_126907_Content_2 = {
    Text = "Na pista de dança, um jovem e uma donzela em uniformes escolares estão girando graciosamente. A música flui como água, entrelaçando-se através de suas mãos entrelaçadas, as saias levantadas suavemente e os olhares trocados."
  },
  AvgDialog_126907_Content_20 = {
    Text = "Quando a música terminou, você apressadamente fez um beijo na mão para se despedir de seu parceiro de dança e seguiu diretamente em direção a Ramona."
  },
  AvgDialog_126907_Content_21 = {
    Text = "Lembro que você foi chamado de o professor mais elegante de todo Mythag quando se trata de dança de salão, Lorde Dexter."
  },
  AvgDialog_126907_Content_22 = {
    Text = "Você revirou sua mente, tentando reproduzir a resposta suave e astuta do Lorde Dexter."
  },
  AvgDialog_126907_Content_23 = {
    Text = "Eu acho que se uma competição \"Dançando com a Elsa\" fosse realizada, eu ainda seria o vencedor."
  },
  AvgDialog_126907_Content_24 = {
    Text = "Ramona desviou o olhar, balançando suavemente a taça de vinho em sua mão."
  },
  AvgDialog_126907_Content_25 = {
    Text = "Elsa te admira. Mesmo que essa dança não seja perfeita, pode ser considerada como a realização do desejo dela para o Festival da Primavera."
  },
  AvgDialog_126907_Content_26 = {
    Text = "Infelizmente, aquele que está dançando com ela não é o verdadeiro Lorde Dexter."
  },
  AvgDialog_126907_Content_27 = {
    Text = "O que é ainda mais infernal é que, mesmo sem o seu ato de posse, a pessoa que ela conhece não é o verdadeiro Lorde Dexter."
  },
  AvgDialog_126907_Content_28 = {
    Text = "Mas esse não é o tópico que você quer discutir."
  },
  AvgDialog_126907_Content_29 = {
    Text = "Ramona, você tem algum desejo para o Festival da Primavera?"
  },
  AvgDialog_126907_Content_3 = {
    Text = "Você percebe Ramona parada sozinha ao lado de uma pequena mesa do lado de fora da pista de dança, saboreando uma bebida misteriosa."
  },
  AvgDialog_126907_Content_30 = {
    Text = "O jogo de interpretação de papéis mudou de direção? Em vez de cumprimentar sua senhora e aquela senhora, você veio verificar sua filha adotiva?"
  },
  AvgDialog_126907_Content_31 = {
    Text = "Vejo que você não foi dançar; é porque você não tem um parceiro que goste?"
  },
  AvgDialog_126907_Content_32 = {
    Text = "Não se preocupe."
  },
  AvgDialog_126907_Content_33 = {
    Text = "Você me faria a honra de dançar com meu velho pai solitário?"
  },
  AvgDialog_126907_Content_34 = {
    Text = "Ramona fica em silêncio. Você sabe que ela está procurando razões no corredor de seus pensamentos."
  },
  AvgDialog_126907_Content_35 = {
    Text = "A pessoa que você está esperando também espera que você aceite este convite para dançar."
  },
  AvgDialog_126907_Content_36 = {
    Text = "Como você sabe?"
  },
  AvgDialog_126907_Content_37 = {Text = "Eu sei."},
  AvgDialog_126907_Content_38 = {
    Text = "Um silêncio ainda mais longo."
  },
  AvgDialog_126907_Content_39 = {
    Text = "Esqueça, eu vou confiar em você desta vez."
  },
  AvgDialog_126907_Content_4 = {
    Text = "Enquanto você pondera sobre o que dizer para iniciar a conversa, uma voz tímida soa ao seu lado."
  },
  AvgDialog_126907_Content_40 = {
    Text = "Ela entra graciosamente na pista de dança, seus dedos delicados repousando em sua palma."
  },
  AvgDialog_126907_Content_41 = {
    Text = "Vamos lá, eu ainda não dancei com você."
  },
  AvgDialog_126907_Content_42 = {Text = "..."},
  AvgDialog_126907_Content_43 = {
    Text = "Os passos de dança da Ramona são como sua personalidade—racionais, contidos, precisos e meticulosos."
  },
  AvgDialog_126907_Content_44 = {
    Text = "Você pode relaxar um pouco; parece que você está tratando a pista de dança como um campo de batalha."
  },
  AvgDialog_126907_Content_45 = {
    Text = "E você poderia ser um pouco mais sério, nobre Senhor. Desde que começou a dançar, quase pisou no meu pé três vezes."
  },
  AvgDialog_126907_Content_46 = {
    Text = "Isto não é como o Lorde Dexter, que se imergiu em círculos sociais por décadas."
  },
  AvgDialog_126907_Content_47 = {
    Text = "Talvez às vezes eu queira desempenhar um papel diferente?"
  },
  AvgDialog_126907_Content_48 = {Text = "É assim?"},
  AvgDialog_126907_Content_49 = {
    Text = "Sabe de uma coisa? Você está um pouco quieto hoje."
  },
  AvgDialog_126907_Content_5 = {
    Text = "<Shake:<Small:Lorde Dexter... posso dançar com você?>>"
  },
  AvgDialog_126907_Content_50 = {
    Text = "<LightGray:Eu pensei que tinha restaurado isso muito bem...>"
  },
  AvgDialog_126907_Content_51 = {
    Text = "É assim? Talvez seja porque o tempo está muito frio, o que faz as pessoas perderem a vontade de falar."
  },
  AvgDialog_126907_Content_52 = {
    Text = "Se fosse Lorde Dexter, ele diria: É bastante tabu flertar com sua própria filha adotiva, você sabe."
  },
  AvgDialog_126907_Content_53 = {
    Text = "<Yellow:Quem é você afinal?>"
  },
  AvgDialog_126907_Content_54 = {
    Text = "Ramona, o tempo que temos para nos encontrar é muito curto; eu não quero..."
  },
  AvgDialog_126907_Content_55 = {
    Text = "Uma leve tosse de Xu chega aos seus ouvidos."
  },
  AvgDialog_126907_Content_56 = {
    Text = "Chega disso, olhe!"
  },
  AvgDialog_126907_Content_59 = {
    Text = "Num instante, fogos de artifício dispararam no céu."
  },
  AvgDialog_126907_Content_6 = {
    Text = "Oh? Por que isso?"
  },
  AvgDialog_126907_Content_62 = {
    Text = "Flores de fogo em cascata desabrocham no topo da cabeça."
  },
  AvgDialog_126907_Content_64 = {
    Text = "Assim como no dia da Cerimônia de Concessão de Chaves, você segurou a mão de Ramona."
  },
  AvgDialog_126907_Content_66 = {
    Text = "Na expressão de espanto dela, você fechou os olhos."
  },
  AvgDialog_126907_Content_68 = {
    Text = "Em uma escuridão, inúmeras vozes de alegria e expectativa ecoam:"
  },
  AvgDialog_126907_Content_69 = {
    Text = "<Big:<Shake:\"Feliz Festa de Oração!\">>"
  },
  AvgDialog_126907_Content_7 = {
    Text = "Eles todos se recusam a dançar comigo... dizendo que acham perigoso."
  },
  AvgDialog_126907_Content_70 = {
    Text = "Feliz Festa de Oração, Ramona."
  },
  AvgDialog_126907_Content_71 = {
    Text = "A meia-noite chegou, o vento sibila, e todas as histórias que deveriam pertencer a você estão se afastando."
  },
  AvgDialog_126907_Content_72 = {
    Text = "Mas você sabe, o dia do reencontro não está mais longe."
  },
  AvgDialog_126907_Content_8 = {
    Text = "Mas não se preocupe! Vou me certificar de controlar minha força!"
  },
  AvgDialog_126907_Content_9 = {
    Text = "Seu olhar varre para cima e para baixo a pequena figura trêmula."
  },
  AvgDialog_126908_Content_1 = {
    Text = "Câmara de Sombras Constantes"
  },
  AvgDialog_126908_Content_10 = {
    Text = "Seu sorriso e forma desapareceram de maneira ambígua, dissipando-se no vento que se transformou em cinzas."
  },
  AvgDialog_126908_Content_11 = {
    Text = "Vá em frente, vá reivindicar seu saque."
  },
  AvgDialog_126908_Content_12 = {
    Text = "Atrás da névoa e das cinzas, há uma porta — levando à cabine do trem."
  },
  AvgDialog_126908_Content_13 = {
    Text = "Sem truques, sem gadgets, sem existência desnecessária."
  },
  AvgDialog_126908_Content_14 = {
    Text = "Era apenas uma porta comum, como todas as outras do mundo, cumprindo a função de \"entrada e saída\", esperando por você no final do quebra-cabeça."
  },
  AvgDialog_126908_Content_15 = {
    Text = "Você respirou fundo, segurou firmemente a Chave de Prata e empurrou o portão."
  },
  AvgDialog_126908_Content_16 = {Text = "..."},
  AvgDialog_126908_Content_17 = {
    Text = "<LightGray:Estou um pouco acostumado à ausência de mais corpos ou até mesmo de alguns membros desmembrados.>"
  },
  AvgDialog_126908_Content_18 = {Text = "Sim?"},
  AvgDialog_126908_Content_19 = {
    Text = "Uma névoa flutua do topo da mesa, desenrolando suavemente um lenço de seda que brilha suavemente, inscrevendo de forma pensativa as palavras de Londinium, que estão completamente em desacordo com seu estilo."
  },
  AvgDialog_126908_Content_2 = {
    Text = "Vagão nº 1"
  },
  AvgDialog_126908_Content_20 = {
    Text = "Caro Guardião:\n\nEspero que esta carta te encontre bem.\nAgora que você chegou aqui, deve ter descoberto o segredo deste trem—é um Domínio Artificial construído por N. A concubina neste trem agora pereceu.\nEu testemunhei todos vocês discutindo seus destinos. Winkle e Tinct, suas cidades natais há muito desapareceram; eu também tinha meus olhos voltados para Miryam, mas, ao olhar mais de perto, a Lemúria descrita por Miryam também é uma coisa do passado que não pode ser recuperada."
  },
  AvgDialog_126908_Content_21 = {
    Text = "Mas para onde eu quero voltar? Acho que provavelmente é para a verdadeira Terra dos Sonhos sem Sonhos. \n Todos eles, todos nós, há muito perdemos os lugares para os quais podemos retornar. \n Mas você, apenas você, %player%, a Universidade Mythag que você tanto deseja e valoriza ainda existe, e ainda há pessoas esperando por você retornar. \n Portanto, você deve se tornar o vencedor final deste jogo. \n\n Portanto, dedico esta vitória a você, marcando-a com a minha morte. \n Basta puxar a alavanca com sua mão, e ela o levará ao lugar onde aquelas pessoas estão esperando por você."
  },
  AvgDialog_126908_Content_22 = {
    Text = "Que você e eu possamos ter nossos desejos realizados. \n\n Xu"
  },
  AvgDialog_126908_Content_23 = {
    Text = "É uma brincadeira estranha que combina com a personalidade desagradável do cara N..."
  },
  AvgDialog_126908_Content_24 = {
    Text = "Você murmura baixinho, tentando afastar o impulso da sua mente."
  },
  AvgDialog_126908_Content_25 = {
    Text = "Mas essa tentação é simplesmente grande demais, à medida que companheiros familiares aparecem em sua mente, até que aquela figura emerge..."
  },
  AvgDialog_126908_Content_26 = {Text = "Ramona..."},
  AvgDialog_126908_Content_27 = {
    Text = "O batimento do coração preenche sua percepção, e seu corpo age antes que sua mente consiga acompanhar; você empurra a alavanca do trem."
  },
  AvgDialog_126908_Content_28 = {
    Text = "O trem de repente acelera, correndo em direção ao distante buraco negro."
  },
  AvgDialog_126908_Content_29 = {
    Text = "Segundos depois, no final do túnel a mais de cem metros de distância, um penhasco imponente apareceu abruptamente."
  },
  AvgDialog_126908_Content_3 = {
    Text = "No final da carruagem número um, uma figura graciosa com um leque cobrindo seu rosto espera silenciosamente por você."
  },
  AvgDialog_126908_Content_30 = {
    Text = "Que piada..."
  },
  AvgDialog_126908_Content_31 = {
    Text = "Você puxa ansiosamente a alavanca com força, mas parece presa e sem resposta, enquanto a parede da montanha se aproxima de você a mais de cem quilômetros por hora."
  },
  AvgDialog_126908_Content_32 = {
    Text = "<Red:Está prestes a colidir...>"
  },
  AvgDialog_126908_Content_33 = {
    Text = "Você fecha os olhos impotentemente, esperando que o momento do impacto chegue."
  },
  AvgDialog_126908_Content_34 = {
    Text = "<Shake:Tão terrível... Por que fui tão tolo a ponto de acreditar em qualquer um dos clones de N?...>"
  },
  AvgDialog_126908_Content_35 = {
    Text = "Boom——!!"
  },
  AvgDialog_126908_Content_36 = {
    Text = "No segundo seguinte ao impacto do trem, a sensação de peso zero te puxa para baixo."
  },
  AvgDialog_126908_Content_37 = {Text = "!!! Hum!!"},
  AvgDialog_126908_Content_38 = {
    Text = "Não sei há quanto tempo o tempo passou."
  },
  AvgDialog_126908_Content_39 = {Text = "..."},
  AvgDialog_126908_Content_4 = {
    Text = "Por favor, permita-me apresentar-me. Eu sou Thais neste trem, ou você também pode me chamar de o topeira do N."
  },
  AvgDialog_126908_Content_40 = {
    Text = "Aqui é? <Shake:Misaq?!>"
  },
  AvgDialog_126908_Content_41 = {
    Text = "A estrutura arquitetônica do lado de fora da janela é muito familiar. A imensa alegria faz você ignorar algumas peculiaridades, e você quase salta daquela cara cadeira."
  },
  AvgDialog_126908_Content_42 = {
    Text = "Até que você veja naturalmente um espelho que está deliberadamente e meticulosamente posicionado em um ângulo."
  },
  AvgDialog_126908_Content_43 = {
    Text = "dentro refletiu o rosto do Lorde Dexter."
  },
  AvgDialog_126908_Content_44 = {Text = "¿¿¿???"},
  AvgDialog_126908_Content_45 = {
    Text = "Você toca seu rosto com desconfiança, enquanto as pontas dos dedos de Dexter no espelho deslizam sobre suas bochechas afundadas."
  },
  AvgDialog_126908_Content_46 = {
    Text = "Oh querido, a recompensa por sobreviver à luta interna é \"retornar a Misaq\", mas não há promessa de como voltar, certo?"
  },
  AvgDialog_126908_Content_47 = {
    Text = "O limite do que posso fazer é permitir que sua consciência empreste meu avatar por um momento."
  },
  AvgDialog_126908_Content_48 = {
    Text = "Mesmo assim, esta é uma operação que viola as leis do universo. Você deve manter a inibição e não deixar ninguém descobrir que você não é o próprio Lorde Dexter~"
  },
  AvgDialog_126908_Content_49 = {
    Text = "Acho que você está prestes a dizer: \"Caso contrário\"..."
  },
  AvgDialog_126908_Content_5 = {
    Text = "Em uma vida que se estende por milhares ou até dezenas de milhares de anos, estou mais acostumado ao nome \"Xu\". É comum o suficiente, ordinário o suficiente e familiar o suficiente para ser visto como qualquer um."
  },
  AvgDialog_126908_Content_50 = {
    Text = "Caso contrário, clang clang! O sino da meia-noite soará cedo, e a carruagem de abóbora e o sapatinho de cristal voltarão a suas formas originais."
  },
  AvgDialog_126908_Content_51 = {
    Text = "Aprecie os momentos antes da meia-noite; eles são o tempo que você conquistou com as vidas de seus companheiros."
  },
  AvgDialog_126908_Content_6 = {
    Text = "Tenho muitas coisas que quero lhe dizer, mas não aqui."
  },
  AvgDialog_126908_Content_7 = {
    Text = "Se o destino permitir, que possamos nos encontrar novamente no futuro, em outro lugar."
  },
  AvgDialog_126908_Content_8 = {
    Text = "Ela levantou a mão e então esmagou o núcleo de prata que estava em sua palma."
  },
  AvgDialog_126908_Content_9 = {
    Text = "Você é o vencedor supremo, Guardião."
  },
  AvgDialog_126909_Content_1 = {
    Text = "Trem do Ano Novo"
  },
  AvgDialog_126909_Content_10 = {
    Text = "<Shake:Clang, clang, clang—>"
  },
  AvgDialog_126909_Content_11 = {
    Text = "<Shake:Hmm... tão cansado.>\nDormindo no trem, não importa quanto tempo eu durma, nunca é o suficiente."
  },
  AvgDialog_126909_Content_12 = {
    Text = "<LightGray:Parece que meu cérebro está emaranhado em uma bagunça de gosma, esquecendo algo crucial...>"
  },
  AvgDialog_126909_Content_13 = {
    Text = "<LightGray:<Shake:Esqueça, sob o pretexto de precisar de uma pausa para o Festival da Oração, eu vou voltar para o dormitório para guardar meu corpo. Mesmo que a Boneca pressione por tarefas e Ramona pressione por relatórios, eu vou resistir até o fim...>>"
  },
  AvgDialog_126909_Content_14 = {
    Text = "Oh querido, que pequeno brotinho sonolento. Você pode se apoiar no meu ombro até o trem chegar ao seu destino, tudo bem?"
  },
  AvgDialog_126909_Content_15 = {Text = "Uau?!"},
  AvgDialog_126909_Content_16 = {
    Text = "Você olha ao redor e conta o número de passageiros."
  },
  AvgDialog_126909_Content_17 = {
    Text = "Wanda girou metade de um copo de vinho tinto, abaixando a cabeça para admirar suas unhas pontudas meticulosamente polidas."
  },
  AvgDialog_126909_Content_18 = {
    Text = "Tinct segurava silenciosamente uma partitura, seus lábios finos se movendo como se estivesse praticando suavemente em sua mente."
  },
  AvgDialog_126909_Content_19 = {
    Text = "Winkle inclinou-se ao lado da pequena lâmpada fraca, seu olhar aparentemente grudado na mecha, como se tivesse medo de que uma mecha de luz escapasse."
  },
  AvgDialog_126909_Content_2 = {
    Text = "Tcharam! Senhoras e senhores na plateia, feliz Festival da Primavera! Finalmente, é a minha vez, pequeno N, de brilhar!"
  },
  AvgDialog_126909_Content_20 = {
    Text = "Miryam inclina a cabeça para trás e fecha os olhos, aparentemente alheia às mudanças ao seu redor."
  },
  AvgDialog_126909_Content_21 = {
    Text = "<LightGray:Todo mundo, a atmosfera de não perturbar uns aos outros é tão confortável...>"
  },
  AvgDialog_126909_Content_22 = {Text = "..."},
  AvgDialog_126909_Content_23 = {Text = "..."},
  AvgDialog_126909_Content_24 = {
    Text = "<LightGray:Mas este trem não está demorando demais?>"
  },
  AvgDialog_126909_Content_25 = {
    Text = "O trem especial da Mythag está configurado para passar pela barreira de névoa fora do campus; é um trem de linha curta. No entanto, como você adormeceu e depois acordou, já se passou pelo menos uma hora."
  },
  AvgDialog_126909_Content_26 = {
    Text = "Após um momento de reflexão, você se aproxima do único professor no veículo."
  },
  AvgDialog_126909_Content_27 = {
    Text = "Winkle... por que o <Yellow:trem especial de Misaq> está tão lento hoje?"
  },
  AvgDialog_126909_Content_28 = {
    Text = "Winkle pulou como um coelho assustado."
  },
  AvgDialog_126909_Content_29 = {
    Text = "Que trem especial de Mythag? Este trem não está indo para o planeta natal de @1?"
  },
  AvgDialog_126909_Content_3 = {
    Text = "Mesmo que você seja meu sósia, eu ainda preciso criticar sua artimanha desta vez por ser de baixo nível e um tanto absurda."
  },
  AvgDialog_126909_Content_30 = {
    Text = "Todos os olhos estão voltados para Winkle como um holofote."
  },
  AvgDialog_126909_Content_31 = {
    Text = "Não brinque, garotinha. Este não é o trem para Aram?"
  },
  AvgDialog_126909_Content_32 = {
    Text = "Hã, mas Aram está bem no fundo do deserto, e é impossível ter um trem aqui..."
  },
  AvgDialog_126909_Content_33 = {
    Text = "Pelo que sei, o destino final deste trem deve ser Isalaw."
  },
  AvgDialog_126909_Content_34 = {
    Text = "Isso é ainda mais absurdo. Isarau não foi destruído há muito tempo?"
  },
  AvgDialog_126909_Content_35 = {
    Text = "Falar é fácil; eu tenho os comprovantes como prova."
  },
  AvgDialog_126909_Content_36 = {
    Text = "Wanda pegou um bilhete de metal e o exibiu diante de todos."
  },
  AvgDialog_126909_Content_37 = {
    Text = "Na estação de desembarque no bilhete, o nome Isarawu está escrito em destaque."
  },
  AvgDialog_126909_Content_38 = {
    Text = "Miryam, Tinct, vocês dois..."
  },
  AvgDialog_126909_Content_39 = {
    Text = "Sem mais delongas, Sua vontade me guiará no caminho de volta a Lemúria."
  },
  AvgDialog_126909_Content_4 = {
    Text = "Ainda não é o Festival da Primavera, então precisamos oferecer ao público um entretenimento diferente, certo?"
  },
  AvgDialog_126909_Content_40 = {
    Text = "Eu... eu quero aproveitar as férias do Festival da Primavera para voltar a Wild Star e passar um tempo com minha irmã..."
  },
  AvgDialog_126909_Content_41 = {
    Text = "<LightGray:Estrela Selvagem... Tinct vagou por inúmeras eras para alcançar Kadath. Esta distância é completamente inatingível para um trem...>"
  },
  AvgDialog_126909_Content_42 = {
    Text = "Lemúria afundou no fundo do mar há mil anos."
  },
  AvgDialog_126909_Content_43 = {
    Text = "E Isaraul... foi destruído há muito tempo."
  },
  AvgDialog_126909_Content_44 = {
    Text = "Pequeno, você apontou para a paisagem por tanto tempo. Qual é o nome do planeta natal ao qual você deseja retornar, e onde ele está?"
  },
  AvgDialog_126909_Content_45 = {
    Text = "A expressão de Winkle mudou drasticamente."
  },
  AvgDialog_126909_Content_46 = {
    Text = "<Shake:Planeta natal... é o planeta natal! O nome do planeta natal... é... <Small:@1...>>"
  },
  AvgDialog_126909_Content_47 = {
    Text = "Huh? Eu devo estar ouvindo coisas; vocês nem conseguem lembrar o nome do seu planeta natal?"
  },
  AvgDialog_126909_Content_48 = {
    Text = "Todos, acalmem-se e ouçam-me."
  },
  AvgDialog_126909_Content_49 = {
    Text = "O destino de cada um soa muito irrealista. Mas cada pessoa realmente tem um bilhete para sua própria terra natal."
  },
  AvgDialog_126909_Content_5 = {
    Text = "De qualquer forma, não é um pouco inacreditável ter apenas uma cena do começo ao fim?"
  },
  AvgDialog_126909_Content_50 = {
    Text = "Portanto, o que mais precisamos encontrar é a <Yellow:equipa do trem> a bordo para reunir informações sobre este trem, em vez de nos envolvermos em discussões fúteis aqui."
  },
  AvgDialog_126909_Content_51 = {Text = "Cof, cof."},
  AvgDialog_126909_Content_52 = {
    Text = "Um barulho estranho e engraçado vem do canto."
  },
  AvgDialog_126909_Content_53 = {
    Text = "É o fim da empolgação? Eu quero assistir ao show um pouco mais~"
  },
  AvgDialog_126909_Content_54 = {
    Text = "Pequeno N?!"
  },
  AvgDialog_126909_Content_55 = {
    Text = "O que houve? Ninguém me deu as boas-vindas? Eu até preparei um grande presente para todos para o Festival da Primavera!"
  },
  AvgDialog_126909_Content_56 = {
    Text = "O verdadeiro culpado que deveria estar oculto na escuridão subiu ao centro do palco, suas intenções sinistras ficaram claras — ele deve estar tramando uma conspiração ainda maior."
  },
  AvgDialog_126909_Content_57 = {
    Text = "O que você está fazendo aqui?"
  },
  AvgDialog_126909_Content_58 = {
    Text = "Não está óbvio? Eu, que sou carinhoso, altruísta e generoso, lancei este trem expresso para casa para o Festival da Primavera, permitindo que todos que sentem falta de sua terra natal desfrutem do calor das festividades."
  },
  AvgDialog_126909_Content_59 = {
    Text = "Você não é tão bondoso assim. Agora, o que mais você está escondendo?"
  },
  AvgDialog_126909_Content_6 = {
    Text = "<Shake:Uuuh, agora não é hora de você gerenciar o teatro e lidar com aquela senhora. A equipe do projeto do evento do Festival de Oração está financeiramente apertada e só pode fornecer uma configuração de local tão árida...>"
  },
  AvgDialog_126909_Content_60 = {
    Text = "Oh, não me apresse. Deixe-me terminar de falar pouco a pouco."
  },
  AvgDialog_126909_Content_61 = {
    Text = "Muitas pessoas querem voltar para casa, mas há apenas um trem. Portanto, apenas uma pessoa pode voltar para a cidade natal que tanto deseja, certo?"
  },
  AvgDialog_126909_Content_62 = {
    Text = "Oh querido, como um N atencioso, altruísta e benevolente, devo usar os meios mais justos para determinar quem pode obter esta qualificação, certo?"
  },
  AvgDialog_126909_Content_63 = {Text = "Então..."},
  AvgDialog_126909_Content_64 = {
    Text = "<Big:Então, <Shake:<Red:Vamos começar a autodestruição!>>!>"
  },
  AvgDialog_126909_Content_65 = {
    Text = "Mate todos, e a última pessoa viva poderá decidir o destino deste trem e terá a chance de um <Yellow: passeio de um dia de volta para casa>!"
  },
  AvgDialog_126909_Content_66 = {
    Text = "Impossível! Ninguém tiraria a vida de outra pessoa por algo assim... tiraria?!"
  },
  AvgDialog_126909_Content_67 = {
    Text = "É isso mesmo, mesmo que eu sinta muita falta do Faint... Eu não posso participar de uma competição tão cruel..."
  },
  AvgDialog_126909_Content_68 = {
    Text = "Hmph, ficar aqui para desfrutar de um bom vinho e dos servos não é tão ruim. Isaraul é apenas um capítulo do meu passado."
  },
  AvgDialog_126909_Content_69 = {
    Text = "Embora seja difícil me despedir deste lugar... minhas pequenas mudas estão aqui, e os Aramitas não dependem mais de mim para liderar a tribo. Suponho que não tenho nenhuma motivação para participar deste massacre mútuo."
  },
  AvgDialog_126909_Content_7 = {
    Text = "Parece que não tenho escolha a não ser esperar e ver."
  },
  AvgDialog_126909_Content_70 = {
    Text = "Todos os olhares se concentraram na última pessoa."
  },
  AvgDialog_126909_Content_71 = {Text = "..."},
  AvgDialog_126909_Content_72 = {
    Text = "Seu olhar não a perturbou nem um pouco; Miryam permaneceu em silêncio."
  },
  AvgDialog_126909_Content_73 = {
    Text = "Você está ciente da obsessão dela, sabendo o significado e o valor da palavra Lemúria para ela."
  },
  AvgDialog_126909_Content_74 = {
    Text = "Suspiro, eu sabia que não seria tão simples..."
  },
  AvgDialog_126909_Content_75 = {
    Text = "Para evitar essa situação constrangedora, eu refinei especificamente as regras — você deve me trazer 5 falecidos para trocar pelo último ingresso."
  },
  AvgDialog_126909_Content_76 = {
    Text = "Você precisa coletar todos os sete bilhetes para começar o trem!"
  },
  AvgDialog_126909_Content_77 = {
    Text = "Em outras palavras, ninguém pode sair daqui até que reste apenas uma pessoa após o massacre no trem."
  },
  AvgDialog_126909_Content_78 = {
    Text = "Além disso, há um <Yellow:traidor> que eu plantei entre vocês, transformado do meu clone, o pequeno N em constante mudança!"
  },
  AvgDialog_126909_Content_79 = {
    Text = "Se você não fizer nada, isso vai te matar um por um! Até lá, ninguém poderá voltar!"
  },
  AvgDialog_126909_Content_8 = {
    Text = "Sem mais delongas, o Pequeno N traz para você o <Shake:mais novo e quente <Red:Festa de Oração teatro de interpretação exclusivo>>!"
  },
  AvgDialog_126909_Content_81 = {
    Text = "Assim que N terminou de falar, uma videira de repente atravessou a névoa negra."
  },
  AvgDialog_126909_Content_82 = {
    Text = "Certo, pessoal. Não ouçam as palavras enganosas desse cara."
  },
  AvgDialog_126909_Content_83 = {
    Text = "Somos seis, incluindo o Guardião mais notável de Mythag. Não conseguimos realmente escapar deste pequeno compartimento?"
  },
  AvgDialog_126909_Content_9 = {
    Text = "Aplausos e gritos estão ecoando!"
  },
  AvgDialog_126910_Content_1 = {
    Text = "Segundo morto"
  },
  AvgDialog_126910_Content_10 = {
    Text = "Não é mais urgente encontrar o assassino entre nós?"
  },
  AvgDialog_126910_Content_11 = {
    Text = "Não, eu não acho que sim... Somos tão poucos, e se cairmos na suspeita mútua, isso só vai piorar as coisas."
  },
  AvgDialog_126910_Content_12 = {
    Text = "Mais importante, precisamos garantir a segurança das pessoas restantes. Que tal ficarmos todos na carruagem 2?"
  },
  AvgDialog_126910_Content_13 = {
    Text = "Você olhou para o Winkle desgastado e acenou com a cabeça."
  },
  AvgDialog_126910_Content_14 = {
    Text = "A pequena muda tomou uma decisão, e eu certamente não vou me opor a isso."
  },
  AvgDialog_126910_Content_15 = {
    Text = "...a cada três horas, eu preciso encontrar um canto tranquilo para rezar sozinho."
  },
  AvgDialog_126910_Content_16 = {
    Text = "De jeito nenhum! Quem sabe que coisas ruins você pode fazer enquanto está rezando!"
  },
  AvgDialog_126910_Content_17 = {
    Text = "Além disso, quando todos estavam discutindo a ideia de desistir de se matar, você foi o único que não expressou sua opinião. Quem sabe se você não é um dos capangas do N?"
  },
  AvgDialog_126910_Content_18 = {
    Text = "Só há um Senhor que eu sirvo, e esse é a divindade de Lemúria."
  },
  AvgDialog_126910_Content_19 = {
    Text = "No entanto, se você proferir mais palavras blasfemas, não me importaria em aplicar a punição divina em nome do meu Senhor."
  },
  AvgDialog_126910_Content_2 = {
    Text = "Três horas depois, na carruagem"
  },
  AvgDialog_126910_Content_20 = {
    Text = "Ao ver que Miryam já desembainhou a adaga, você tenta apressadamente intervir."
  },
  AvgDialog_126910_Content_21 = {
    Text = "Atualmente, não temos evidências para acusar ninguém, Tinct... Todos estavam dormindo naquela hora."
  },
  AvgDialog_126910_Content_22 = {
    Text = "Além disso, esse chamado toupeira pode ser apenas um dos truques de N, nos atraindo a nos matarmos uns aos outros de acordo com seu plano."
  },
  AvgDialog_126910_Content_23 = {
    Text = "Como você pode dizer isso sobre mim? Boohoo, eu estava realmente tentando te lembrar de tudo—"
  },
  AvgDialog_126910_Content_24 = {
    Text = "<LightGray:Facão do Olho...>"
  },
  AvgDialog_126910_Content_25 = {
    Text = "Ok, ok, estou desaparecendo, waaah..."
  },
  AvgDialog_126910_Content_26 = {
    Text = "Com um estrondo, a figura do pequeno N desapareceu no ar."
  },
  AvgDialog_126910_Content_27 = {
    Text = "Nesse caso... Miryam, você poderia rezar sozinha no carro número 1 e não sair sem permissão?"
  },
  AvgDialog_126910_Content_28 = {
    Text = "Nós nos encontraremos na porta dos fundos do carro 1, enquanto os outros estão todos na mesma sala, então não haverá perigo."
  },
  AvgDialog_126910_Content_29 = {
    Text = "Isso não é um pouco injusto com a Miryam...?"
  },
  AvgDialog_126910_Content_3 = {
    Text = "<Shake:Glug glug glug—>"
  },
  AvgDialog_126910_Content_30 = {
    Text = "Não tenho objeções."
  },
  AvgDialog_126910_Content_31 = {
    Text = "Miryam não deu atenção ao seu obstáculo e levantou-se diretamente para sair do carro número 2, sem esquecer de se virar cuidadosamente e trancar a porta da divisória."
  },
  AvgDialog_126910_Content_32 = {
    Text = "As pessoas restantes devem conseguir relaxar agora..."
  },
  AvgDialog_126910_Content_33 = {
    Text = "Eu sempre sinto que essa questão não é tão simples assim..."
  },
  AvgDialog_126910_Content_34 = {
    Text = "Uma hora depois, na Carruagem nº 2"
  },
  AvgDialog_126910_Content_35 = {
    Text = "Hmm-hmm-hmm..."
  },
  AvgDialog_126910_Content_36 = {
    Text = "Eu estarei saindo por um tempo..."
  },
  AvgDialog_126910_Content_37 = {
    Text = "Winkle balançou em direção ao cruzamento da cabine do carro."
  },
  AvgDialog_126910_Content_38 = {
    Text = "<LightGray:Eu tomei café demais...?>"
  },
  AvgDialog_126910_Content_39 = {
    Text = "Uma hora depois, na Carruagem nº 2"
  },
  AvgDialog_126910_Content_4 = {
    Text = "Pare de beber."
  },
  AvgDialog_126910_Content_40 = {
    Text = "<LightGray:Estranho, por que Winkle ainda não voltou...>"
  },
  AvgDialog_126910_Content_41 = {
    Text = "Você está muito preocupado? Quer que eu te acompanhe para um exame?"
  },
  AvgDialog_126910_Content_42 = {Text = "Vamos."},
  AvgDialog_126910_Content_43 = {
    Text = "Uma sensação de inquietação se espalha em seu peito, os passos ocos e sombras ocupando todo o carro."
  },
  AvgDialog_126910_Content_44 = {
    Text = "Você entende aquele nome sombrio—"
  },
  AvgDialog_126910_Content_45 = {Text = "Morte."},
  AvgDialog_126910_Content_46 = {
    Text = "Você bate repetidamente na porta do banheiro, chamando o nome de Winkle, mas não há resposta."
  },
  AvgDialog_126910_Content_47 = {
    Text = "Você começa a tentar arrombar a porta."
  },
  AvgDialog_126910_Content_48 = {
    Text = "Tum, tum, tum!"
  },
  AvgDialog_126910_Content_49 = {
    Text = "O que aconteceu?"
  },
  AvgDialog_126910_Content_5 = {
    Text = "<Shake:Glug glug glug—>"
  },
  AvgDialog_126910_Content_50 = {
    Text = "Wanda também foi atraída pelo barulho incomum."
  },
  AvgDialog_126910_Content_51 = {
    Text = "Winkle está no banheiro há uma hora. Batemos na porta, mas não houve resposta."
  },
  AvgDialog_126910_Content_52 = {
    Text = "O portão também não pode ser derrubado. É estranho, um grupo de Despertadores pode convocar ventos e chuvas, e é capaz de qualquer coisa contra criaturas míticas, mas não consegue abrir uma única porta!"
  },
  AvgDialog_126910_Content_53 = {
    Text = "Você ouviu falar do novo gênero?"
  },
  AvgDialog_126910_Content_54 = {
    Text = "Falando do novo gênero, não podemos esquecer do gênero clássico."
  },
  AvgDialog_126910_Content_56 = {
    Text = "No contexto do raciocínio, obras clássicas referem-se a histórias de detetive com mistérios claros e raciocínio lógico, enquanto o novo clássico adiciona visões de mundo únicas a essa base."
  },
  AvgDialog_126910_Content_57 = {
    Text = "Ainda assim, o novo clássico deve respeitar os leitores e a justiça, e deve levantar questões dentro do escopo de configurações conhecidas para os leitores, sem permitir adições arbitrárias de elementos sobrenaturais."
  },
  AvgDialog_126910_Content_58 = {
    Text = "Em outras palavras, se você não tem a habilidade de destrancar, não pode simplesmente abrir a porta que está trancada por dentro."
  },
  AvgDialog_126910_Content_59 = {
    Text = "O Pequeno N subiu na prateleira de bagagens por um tempo, depois se escondeu atrás do encosto da cadeira, desviando de todos os espinhos e cipós enquanto terminava seu discurso prolixo."
  },
  AvgDialog_126910_Content_6 = {Text = "Winkle..."},
  AvgDialog_126910_Content_60 = {
    Text = "Então, você quer dizer... que este é um assassinato em uma sala trancada, e dentro está a cena do crime?"
  },
  AvgDialog_126910_Content_61 = {
    Text = "Quem sabe! E se Winkle fugiu com medo da punição e pulou do carro pela janela do banheiro?"
  },
  AvgDialog_126910_Content_62 = {
    Text = "Você não disse que não podemos sair do trem?"
  },
  AvgDialog_126910_Content_63 = {
    Text = "Oh querido, houve uma falha na dedução!"
  },
  AvgDialog_126910_Content_64 = {
    Text = "Antes que o verdadeiro detetive apareça, sempre deve haver um cara responsável pela dedução incorreta."
  },
  AvgDialog_126910_Content_65 = {
    Text = "Se ninguém quer assumir o papel do tolo, então deixe que eu, o grande e devotado pequeno N, o interprete!"
  },
  AvgDialog_126910_Content_66 = {
    Text = "Pare de conversar com esse cara."
  },
  AvgDialog_126910_Content_67 = {
    Text = "Embora seja um pouco indelicado... há uma pequena janela de persiana na porta do banheiro, e a estrutura é muito frágil."
  },
  AvgDialog_126910_Content_68 = {
    Text = "Wanda levantou o espinho."
  },
  AvgDialog_126910_Content_69 = {
    Text = "Range, as persianas foram retiradas."
  },
  AvgDialog_126910_Content_7 = {
    Text = "Não importa quanto café seja consumido, Tinct não voltará, certo?"
  },
  AvgDialog_126910_Content_70 = {
    Text = "Deixe o resto comigo."
  },
  AvgDialog_126910_Content_71 = {
    Text = "As vinhas se estenderam e destrancaram a porta, e você a empurrou para abrir."
  },
  AvgDialog_126910_Content_72 = {
    Text = "Sem tempo restante."
  },
  AvgDialog_126910_Content_73 = {
    Text = "Winkle encolheu-se silenciosamente no canto do banheiro."
  },
  AvgDialog_126910_Content_74 = {Text = "Winkle!"},
  AvgDialog_126910_Content_75 = {
    Text = "Você correu apressadamente até Winkle, seus lábios exudando sangue vermelho profundo, e ela já havia perdido a respiração."
  },
  AvgDialog_126910_Content_76 = {
    Text = "Para ser franco, Winkle... na época de sua partida, nem você, nem eu, nem Wanda jamais deixamos o Carro Nº 2."
  },
  AvgDialog_126910_Content_77 = {
    Text = "O único assassino... só pode ser Miryam."
  },
  AvgDialog_126910_Content_78 = {
    Text = "Meu senhor não me guiou a tomar tais ações. No entanto, se você insistir, posso proferir o julgamento em nome dos deuses."
  },
  AvgDialog_126910_Content_79 = {
    Text = "Oh não, estamos em um impasse!"
  },
  AvgDialog_126910_Content_8 = {
    Text = "<Shake:você——>"
  },
  AvgDialog_126910_Content_80 = {
    Text = "Já que estamos falando de julgamento divino, gostaria de oferecer a vocês um jeito fácil de vencer!"
  },
  AvgDialog_126910_Content_81 = {
    Text = "Agora podemos fazer uma votação, e a pessoa com mais votos será expulsa pessoalmente do trem por mim, perdendo a chance de voltar para casa!"
  },
  AvgDialog_126910_Content_82 = {
    Text = "Sem dúvida, eu convocarei Miryam."
  },
  AvgDialog_126910_Content_83 = {Text = "Thais."},
  AvgDialog_126910_Content_84 = {
    Text = "Garotinho, o que você acha? Dada a situação atual, eu também escolheria votar na Miryam."
  },
  AvgDialog_126910_Content_85 = {
    Text = "Miryam 2 votos! Thais 1 voto!"
  },
  AvgDialog_126910_Content_86 = {
    Text = "N, como calculamos o resultado se houver um empate?"
  },
  AvgDialog_126910_Content_87 = {
    Text = "Se for um empate, então é considerado que ninguém está fora~"
  },
  AvgDialog_126910_Content_88 = {
    Text = "Mas pense seriamente, agora restam apenas quatro pessoas. Se você desistir desta oportunidade, e o traidor matar mais uma pessoa, as chances de vitória aumentarão significativamente!"
  },
  AvgDialog_126910_Content_89 = {
    Text = "Eu não quero prejudicar pessoas boas. Eu voto na Thais."
  },
  AvgDialog_126910_Content_9 = {
    Text = "Isso mesmo, o que é mais crucial é encontrar uma maneira de sair do trem."
  },
  AvgDialog_126910_Content_90 = {
    Text = "Você realmente não vai reconsiderar? Esta é a única chance de votar?"
  },
  AvgDialog_126910_Content_91 = {
    Text = "Não, quanto mais você diz isso, mais sinto que fiz a escolha certa."
  },
  AvgDialog_126910_Content_92 = {
    Text = "Certo, então o resultado da votação desta rodada é: um empate, e ninguém foi eliminado~"
  },
  AvgDialog_126910_Content_93 = {
    Text = "Suspiro~ Tão decepcionado~ A pequena N precisa encontrar um canto para se acalmar. Vejo vocês mais tarde~"
  },
  AvgDialog_126911_Content_1 = {
    Text = "Início do jogo"
  },
  AvgDialog_126911_Content_10 = {
    Text = "Se você continuar divagando, eu não me importaria de usar isso para te fazer sentir novamente a sensação de ser perfurado no coração, sabe?"
  },
  AvgDialog_126911_Content_11 = {
    Text = "Wanda acariciou o espinho em sua palma."
  },
  AvgDialog_126911_Content_12 = {
    Text = "Oh querido, que declaração de partir o coração é esta."
  },
  AvgDialog_126911_Content_13 = {
    Text = "O programa da Festa de Oração que eu preparei com tanto esforço é realmente tão impopular assim? <Italic:Sniff...>"
  },
  AvgDialog_126911_Content_14 = {
    Text = "Fingindo chorar por menos de um segundo, N imediatamente abriu um sorriso radiante."
  },
  AvgDialog_126911_Content_15 = {
    Text = "Em resumo, por favor, dêem o seu máximo e lutem entre vocês! O pequeno N estará ansioso para ver suas apresentações!"
  },
  AvgDialog_126911_Content_16 = {
    Text = "\"Whoosh\", a pequena N desapareceu novamente. \n O trem voltou ao silêncio inquietante mais uma vez."
  },
  AvgDialog_126911_Content_17 = {
    Text = "O que se segue é um longo silêncio, a escuridão à frente nos trilhos parece interminável."
  },
  AvgDialog_126911_Content_18 = {
    Text = "Quanto tempo mais o trem vai viajar? Qual é o destino?"
  },
  AvgDialog_126911_Content_19 = {
    Text = "No coração das pessoas, pode não haver resposta, ou pode haver uma resposta que não pode ser dita."
  },
  AvgDialog_126911_Content_2 = {
    Text = "...Não consigo sair."
  },
  AvgDialog_126911_Content_20 = {
    Text = "Um, pessoal..."
  },
  AvgDialog_126911_Content_21 = {
    Text = "Uma voz clara quebrou o silêncio."
  },
  AvgDialog_126911_Content_22 = {
    Text = "Está bem chato ficar aqui sentado... Se ninguém se importar com a perturbação, que tal eu cantar uma música para todos?"
  },
  AvgDialog_126911_Content_23 = {
    Text = "Hmm?! Eu adoro isso! Posso pedir uma música?"
  },
  AvgDialog_126911_Content_24 = {
    Text = "Vá embora, o que isso tem a ver com você?"
  },
  AvgDialog_126911_Content_25 = {
    Text = "Como é o Festival da Primavera do Império Panlong, lembro-me de uma canção oriental que ouvi uma vez sendo interpretada pelo Coro das Sombras."
  },
  AvgDialog_126911_Content_26 = {
    Text = "Não tenho certeza se já dominei peças orientais suficientes..."
  },
  AvgDialog_126911_Content_27 = {
    Text = "O nome daquela canção é \"Flor de Jasmim\"."
  },
  AvgDialog_126911_Content_28 = {
    Text = "Oh? É realmente assim?"
  },
  AvgDialog_126911_Content_29 = {
    Text = "Que coincidência, eu também estava na plateia para aquela apresentação do Coro das Sombras."
  },
  AvgDialog_126911_Content_3 = {
    Text = "Winkle pronunciou despondentemente a conclusão."
  },
  AvgDialog_126911_Content_30 = {
    Text = "Se não me engano, eu também encontrei... na plateia."
  },
  AvgDialog_126911_Content_31 = {
    Text = "O olhar de Wanda está fixo em Miryam, enquanto Miryam apenas acena com a cabeça em silêncio."
  },
  AvgDialog_126911_Content_32 = {
    Text = "Como ninguém se opõe a isso... Vou começar a cantar."
  },
  AvgDialog_126911_Content_33 = {
    Text = "Tinct limpou a garganta."
  },
  AvgDialog_126911_Content_34 = {
    Text = "<Shake:Que flor de jasmim, que flor de jasmim♪~ Nenhuma flor em todo o jardim pode se comparar a ela♪~>"
  },
  AvgDialog_126911_Content_35 = {
    Text = "<Shake:Lá-lá-lá~ lá-lá-lá~ lá-lá-lá♪~>"
  },
  AvgDialog_126911_Content_36 = {
    Text = "Cantos etéreos e melodiosos ecoam na carruagem vazia."
  },
  AvgDialog_126911_Content_37 = {
    Text = "Sob a melodia suave, as cordas tensas em sua mente relaxam gradualmente, e você surpreendentemente sente uma leve sonolência."
  },
  AvgDialog_126911_Content_38 = {
    Text = "Acho que todos estão cansados, não é? Estou acostumado a ficar acordado, então posso vigiar todos."
  },
  AvgDialog_126911_Content_39 = {
    Text = "Você acenou com a cabeça e então mergulhou profundamente no sonho que se aproximava há muito tempo."
  },
  AvgDialog_126911_Content_4 = {
    Text = "Além da cabine, este trem consiste em três vagões. Atualmente estamos no Vagão nº 2, que é o do meio."
  },
  AvgDialog_126911_Content_40 = {Text = "..."},
  AvgDialog_126911_Content_41 = {
    Text = "Depois de muito tempo, Tinct também terminou de cantar."
  },
  AvgDialog_126911_Content_42 = {
    Text = "Todos estão dormindo, então você também deveria descansar um pouco, certo?"
  },
  AvgDialog_126911_Content_43 = {
    Text = "......É mesmo?"
  },
  AvgDialog_126911_Content_44 = {
    Text = "O que, você tem medo de que eu seja o infiltrado?"
  },
  AvgDialog_126911_Content_45 = {
    Text = "Isso não vai acontecer. É só que no passado, eu esperava o Fraco adormecer antes de ir descansar..."
  },
  AvgDialog_126911_Content_46 = {
    Text = "Então hoje, é a sua vez de descansar bem! Vá em frente, vá em frente."
  },
  AvgDialog_126911_Content_47 = {
    Text = "Sob a insistência de Winkle, Tinct também pegou um cobertor, encostou-se ao encosto da cadeira e fechou os olhos."
  },
  AvgDialog_126911_Content_48 = {
    Text = "Não é de se admirar que todos estejam dormindo; é uma atmosfera tão relaxante..."
  },
  AvgDialog_126911_Content_49 = {Text = "..."},
  AvgDialog_126911_Content_5 = {
    Text = "O vagão 1 e o vagão 3 estão ambos vazios, com todas as janelas e portas completamente trancadas, impossível de serem rompidos por meios físicos ou Tecnologia Prateada."
  },
  AvgDialog_126911_Content_50 = {Text = "..."},
  AvgDialog_126911_Content_51 = {Text = "Hmm?"},
  AvgDialog_126911_Content_52 = {
    Text = "A primeira coisa que chama sua atenção é o rosto tranquilo e sereno de Winkle enquanto ele dorme."
  },
  AvgDialog_126911_Content_53 = {
    Text = "As luzes do trem se apagaram em algum momento, e o ambiente ao redor foi engolido pela escuridão, com apenas uma luz suave brilhando através da conexão entre os vagões."
  },
  AvgDialog_126911_Content_54 = {
    Text = "Winkle... como você adormeceu...?"
  },
  AvgDialog_126911_Content_55 = {
    Text = "Winkle soltou um suspiro suave."
  },
  AvgDialog_126911_Content_56 = {
    Text = "...Hmm? Eu... adormeci?"
  },
  AvgDialog_126911_Content_57 = {
    Text = "Ei ei ei?!!! Eu adormeci!!!"
  },
  AvgDialog_126911_Content_58 = {
    Text = "A chamada de Winkle foi como uma tempestade repentina, despertando instantaneamente todos os passageiros adormecidos."
  },
  AvgDialog_126911_Content_59 = {
    Text = "As luzes de repente se acenderam, iluminando todo o carro."
  },
  AvgDialog_126911_Content_6 = {
    Text = "Eu te disse! Não há necessidade de alvoroço! Ninguém pode sair até que só reste um vencedor no carro!"
  },
  AvgDialog_126911_Content_60 = {
    Text = "Prezados passageiros, estão descansando bem no Expresso de Volta para Casa?"
  },
  AvgDialog_126911_Content_61 = {
    Text = "Após detectar que todos os passageiros entraram em estado de sono, o pequeno N preparou especialmente um ambiente silencioso e bloqueador de luz para você!"
  },
  AvgDialog_126911_Content_62 = {
    Text = "Desculpe, eu geralmente confio em beber muito café para ficar acordado..."
  },
  AvgDialog_126911_Content_63 = {
    Text = "Espere, um de nós está faltando?"
  },
  AvgDialog_126911_Content_64 = {Text = "..."},
  AvgDialog_126911_Content_65 = {
    Text = "Hã? A pequena muda está olhando para mim? Estou aqui."
  },
  AvgDialog_126911_Content_66 = {
    Text = "Então, a pessoa desaparecida é..."
  },
  AvgDialog_126911_Content_67 = {
    Text = "Todos os olhares se voltaram para o final do vagão —"
  },
  AvgDialog_126911_Content_68 = {
    Text = "Um grande buraco foi perfurado na garganta de Tinct por algum objeto afiado, e o plasma sanguíneo escorreu pelo seu pescoço gracioso como o de um cisne, encharcando a parte da frente de seu vestido."
  },
  AvgDialog_126911_Content_69 = {
    Text = "A cotovia que sangra não pode mais cantar."
  },
  AvgDialog_126911_Content_7 = {
    Text = "Por que você de novo... Não foi a Thais que...?"
  },
  AvgDialog_126911_Content_70 = {
    Text = "<Shake:Eia—!!!>"
  },
  AvgDialog_126911_Content_71 = {
    Text = "Winkle soltou um grito que rasgou o céu noturno, escorregando pela parede até o canto, envolvendo os braços em volta de si mesmo, tremendo incontrolavelmente."
  },
  AvgDialog_126911_Content_72 = {
    Text = "<Shake:Desculpe, eu não deveria ter tanta confiança em mim mesmo, eu não deveria ter feito vigília sozinho, eu não deveria ter pensado que não adormeceria sem café...>"
  },
  AvgDialog_126911_Content_73 = {
    Text = "Winkle mordia as unhas ansiosamente, lágrimas de pânico brotavam continuamente e gotejavam no carpete."
  },
  AvgDialog_126911_Content_74 = {
    Text = "Clang! O pequeno N compreensivo ouviu o quê?<Shake:As necessidades dos passageiros>!"
  },
  AvgDialog_126911_Content_75 = {
    Text = "Agora servindo nossos estimados passageiros com um serviço atencioso—<Yellow:máquina de café ilimitada>!"
  },
  AvgDialog_126911_Content_76 = {
    Text = "Enquanto você pressionar este botão vermelho, um fluxo interminável de calor americano profundo e intenso jorrará do bico!"
  },
  AvgDialog_126911_Content_77 = {
    Text = "Você avança em silêncio, levantando a mão—"
  },
  AvgDialog_126911_Content_78 = {
    Text = "Então eu esmaguei aquele pequeno N na minha frente com força, achatando-o."
  },
  AvgDialog_126911_Content_79 = {
    Text = "<Shake:Desculpa, desculpa, desculpa...>"
  },
  AvgDialog_126911_Content_8 = {
    Text = "Hmph, se fosse tão fácil morrer, eu não seria meu pequeno N!"
  },
  AvgDialog_126911_Content_80 = {
    Text = "O choro de Winkle ecoou pelo carro."
  },
  AvgDialog_126911_Content_81 = {
    Text = "Não importa como você resista, a abertura será marcada pela morte de Tinct—"
  },
  AvgDialog_126911_Content_82 = {
    Text = "O massacre mútuo começou."
  },
  AvgDialog_126911_Content_9 = {
    Text = "Então, como está todo mundo? Todos já decidiram em seus corações qual é o alvo de morte desta noite?"
  },
  AvgDialog_126912_Content_1 = {
    Text = "Golpe Oculto"
  },
  AvgDialog_126912_Content_10 = {
    Text = "Por algum motivo, você sempre sente que por trás daquele sorriso existe uma certa emoção que você ainda não descobriu."
  },
  AvgDialog_126912_Content_11 = {
    Text = "Vamos, Miryam. Estamos indo para o carro número 1."
  },
  AvgDialog_126912_Content_12 = {
    Text = "No momento em que o portão de conexão está prestes a fechar, Wanda vira a cabeça para olhar para trás."
  },
  AvgDialog_126912_Content_13 = {
    Text = "Feliz Festival da Primavera, Guardião."
  },
  AvgDialog_126912_Content_14 = {Text = "..."},
  AvgDialog_126912_Content_15 = {
    Text = "Carroça Nº 2"
  },
  AvgDialog_126912_Content_16 = {
    Text = "Depois que Wanda e Miryam saíram, apenas você e Thais permaneceram no carro."
  },
  AvgDialog_126912_Content_17 = {
    Text = "A seguir, o que devemos fazer com este raro tempo a sós, minha pequena muda?"
  },
  AvgDialog_126912_Content_18 = {
    Text = "Thais de repente se inclina com más intenções, fazendo você dar um passo para trás para manter uma distância segura."
  },
  AvgDialog_126912_Content_19 = {
    Text = "Eu posso ir apressar o relatório..."
  },
  AvgDialog_126912_Content_2 = {
    Text = "Carroça Nº 2"
  },
  AvgDialog_126912_Content_20 = {
    Text = "Já é o Festival da Primavera, então relaxe um pouco e pare de pensar no seu relatório o tempo todo."
  },
  AvgDialog_126912_Content_21 = {
    Text = "Seus braços de cor mel envolvem delicadamente seus ombros, suas respirações ambíguas se entrelaçando a você como a névoa da noite."
  },
  AvgDialog_126912_Content_22 = {Text = "Isso..."},
  AvgDialog_126912_Content_23 = {
    Text = "A expressão séria da boneca, o suspiro de Ramona e o bastão de ensino de Czort aparecem instantaneamente diante de seus olhos."
  },
  AvgDialog_126912_Content_24 = {
    Text = "Ainda não consigo fazer isso..."
  },
  AvgDialog_126912_Content_25 = {
    Text = "Você sorri de forma obsequiosa, aparentemente evitando casualmente o afeto de Thais."
  },
  AvgDialog_126912_Content_26 = {
    Text = "Certo, que tal sentarmos quietos e conversarmos por um tempo?"
  },
  AvgDialog_126912_Content_27 = {
    Text = "Diga-me, Guardião... Naquele momento fugaz em que seu olhar vacilou, em quem você estava pensando?"
  },
  AvgDialog_126912_Content_28 = {Text = "..."},
  AvgDialog_126912_Content_29 = {Text = "..."},
  AvgDialog_126912_Content_3 = {
    Text = "Em meio ao estrondo do trem, Wanda foi a primeira a quebrar o silêncio."
  },
  AvgDialog_126912_Content_30 = {
    Text = "Você não se lembra de quanto tempo está narrando, apenas que os eventos passados estão vívidos em sua mente."
  },
  AvgDialog_126912_Content_31 = {
    Text = "E então há o refeitório em Mythag, que é um lugar muito mais animado do que o laboratório."
  },
  AvgDialog_126912_Content_32 = {
    Text = "Especialmente quando os bolinhos estão disponíveis, as crianças correm para o balcão, desconsiderando completamente a elegância e a virtude da graça e modéstia de uma dama..."
  },
  AvgDialog_126912_Content_33 = {
    Text = "Alguns pequenos travessos trapaceiam fazendo com que seus amigos animais seguram os bilhetes de refeição e ocupem espaço na área de serviço, depois eles dão os bolos que roubaram para seus amigos tímidos."
  },
  AvgDialog_126912_Content_34 = {
    Text = "<Shake:E... Hã?>"
  },
  AvgDialog_126912_Content_35 = {
    Text = "Você descobre que sua voz ficou embargada, e lágrimas escorrem incontrolavelmente de seus olhos."
  },
  AvgDialog_126912_Content_36 = {
    Text = "Há mais..."
  },
  AvgDialog_126912_Content_37 = {
    Text = "As lágrimas se acumulam cada vez mais, tornando minha visão cada vez mais embaçada."
  },
  AvgDialog_126912_Content_38 = {
    Text = "<Shake:Eu realmente quero voltar para Mythag, estar com todos novamente...>"
  },
  AvgDialog_126912_Content_39 = {
    Text = "É estranho. Eu só deixei Mythag <Yellow:faz três dias> para conduzir pesquisas de campo. Não deveria ser..."
  },
  AvgDialog_126912_Content_4 = {
    Text = "Eu tenho uma sugestão."
  },
  AvgDialog_126912_Content_40 = {
    Text = "Mas a angústia da saudade faz seu nariz doer, como se uma corda esticada na sua mente estivesse prestes a romper."
  },
  AvgDialog_126912_Content_41 = {
    Text = "Não se preocupe, não se preocupe, Guardião."
  },
  AvgDialog_126912_Content_42 = {
    Text = "Você está envolto em um abraço suave. Um abraço de mãe."
  },
  AvgDialog_126912_Content_43 = {
    Text = "@2 Eu prometo a você, você retornará ao lugar que tanto deseja."
  },
  AvgDialog_126912_Content_44 = {
    Text = "As características de Thais tornaram-se embaçadas."
  },
  AvgDialog_126912_Content_45 = {
    Text = "A névoa turva envolveu vocês dois, e você se encolheu silenciosamente em seu abraço, tornando-se um ser muito pequeno."
  },
  AvgDialog_126912_Content_46 = {
    Text = "Você sente o perfume. <Yellow:O cheiro de magnólia>."
  },
  AvgDialog_126912_Content_47 = {
    Text = "<Red:A fragrância das grandes flores de magnólia.>"
  },
  AvgDialog_126912_Content_48 = {
    Text = "Você se encontra envolto neste aroma perfumado, caindo em um sono infantil que faz você esquecer todas as preocupações e medos."
  },
  AvgDialog_126912_Content_49 = {
    Text = "Antes que a consciência se apague, tudo o que você se lembra são os <Yellow:olhos dourados e anseiosos> de Mãe."
  },
  AvgDialog_126912_Content_5 = {
    Text = "Podemos nos emparelhar e ficar nos vagões 1 e 2, assim podemos cuidar um do outro."
  },
  AvgDialog_126912_Content_50 = {Text = "..."},
  AvgDialog_126912_Content_51 = {Text = "Então—"},
  AvgDialog_126912_Content_52 = {
    Text = "Um alto \"clang\" veio do carro número um."
  },
  AvgDialog_126912_Content_53 = {
    Text = "Você sabe, o jogo de massacre mútuo ainda está em andamento, e o sonho deve despertar."
  },
  AvgDialog_126912_Content_54 = {
    Text = "Vagão nº 1"
  },
  AvgDialog_126912_Content_55 = {
    Text = "No Carro Nº 1, os corpos gravemente feridos de Wanda e Miryam estavam entrelaçados, uma adaga completamente cravada no peito de Wanda, enquanto Miryam estava perfurada por inúmeras estacas."
  },
  AvgDialog_126912_Content_56 = {
    Text = "Wanda meio abriu os olhos atordoados e revelou a você e a todos intermitentemente."
  },
  AvgDialog_126912_Content_57 = {
    Text = "Eu sabia que Miryam atacaria, então eu estava pronto para um \"Contra-ataque\"..."
  },
  AvgDialog_126912_Content_58 = {
    Text = "Agora, N não tem absolutamente nenhuma maneira de alcançar sua vitória..."
  },
  AvgDialog_126912_Content_59 = {
    Text = "Vocês todos devem..."
  },
  AvgDialog_126912_Content_6 = {
    Text = "Não é perigoso para aqueles que ficam ao lado do assassino?"
  },
  AvgDialog_126912_Content_60 = {
    Text = "As últimas palavras de Wanda se apagaram. A benção em suas palavras finais também foi engolida pelo silêncio."
  },
  AvgDialog_126912_Content_61 = {
    Text = "Após um longo silêncio, Thais finalmente falou com um tremor na voz."
  },
  AvgDialog_126912_Content_62 = {
    Text = "Parece que o assassino é de fato Miryam. Ela sabia que sob a regra de guarda mútua entre os dois, ela tinha que matar Wanda primeiro; caso contrário, suas ações certamente provocariam a hostilidade dos indivíduos restantes, então ela tomou uma atitude."
  },
  AvgDialog_126912_Content_63 = {
    Text = "Wanda... precisamente porque sabe que se destaca em \"Contra-ataque\", ela tomou a iniciativa de compartilhar um quarto com a traidora Miryam."
  },
  AvgDialog_126912_Content_64 = {
    Text = "Ela trocou seu próprio sacrifício pela vitória das \"boas pessoas\"."
  },
  AvgDialog_126912_Content_65 = {
    Text = "O tom de Thais era pesado, mas impregnado de respeito.\n Tomara que pudesse vir do coração."
  },
  AvgDialog_126912_Content_66 = {
    Text = "Que pena, não é."
  },
  AvgDialog_126912_Content_67 = {
    Text = "Não... Miryam... não é N quem infiltrou nossas fileiras."
  },
  AvgDialog_126912_Content_68 = {
    Text = "<Shake:Não é ela? Então por que ela?…>"
  },
  AvgDialog_126912_Content_69 = {
    Text = "Pela vitória, pela conquista, pela \"Lemuria\" prometida por N, a Miryam que conheço realmente iria tão longe a ponto de tomar as rédeas da situação em suas próprias mãos."
  },
  AvgDialog_126912_Content_7 = {
    Text = "Mas pelo menos isso garante que N não alcançará a vitória final."
  },
  AvgDialog_126912_Content_70 = {
    Text = "Então... por que você..."
  },
  AvgDialog_126912_Content_71 = {
    Text = "O verdadeiro traidor é você. Táias, ou melhor, <Yellow:alguém fingindo ser Táias>."
  },
  AvgDialog_126912_Content_72 = {
    Text = "Talvez sua preparação tenha sido suficiente; Thais mostrou pouca surpresa, apenas olhando em seus olhos com uma postura calma e um leve sorriso."
  },
  AvgDialog_126912_Content_73 = {
    Text = "Oh? Quando você descobriu? Eu adoraria ouvir mais."
  },
  AvgDialog_126912_Content_74 = {
    Text = "Depois que Winkle... saiu, Wanda sugeriu dividir os dois compartimentos."
  },
  AvgDialog_126912_Content_75 = {
    Text = "Sério... tão cedo? Achei que os métodos que escolhi eram cautelosos o suficiente e não deixavam muita pista."
  },
  AvgDialog_126912_Content_76 = {
    Text = "As feridas penetrantes em Tinct podem ter vindo dos espinhos de Thais, dos espinhos de Wanda ou da adaga que Miryam carrega."
  },
  AvgDialog_126912_Content_77 = {
    Text = "Quanto à morte de Winkle... Thais, Wanda e Miryam têm a capacidade de infligir Veneno."
  },
  AvgDialog_126912_Content_78 = {
    Text = "Considerando a ingestão de café de Winkle, enquanto veneno for adicionado à máquina de café, a morte inevitavelmente chegará em algum momento."
  },
  AvgDialog_126912_Content_79 = {
    Text = "Então, sim, em termos dos métodos de cometer o crime, sua disguise foi muito bem-sucedida."
  },
  AvgDialog_126912_Content_8 = {
    Text = "Vou ficar de olho na Miryam. Não se preocupe, eu tenho uma carta na manga que o outro lado nunca esperaria."
  },
  AvgDialog_126912_Content_80 = {
    Text = "Então, qual é a base do seu raciocínio...?"
  },
  AvgDialog_126912_Content_81 = {
    Text = "Você já ouviu falar de um jogo de festa chamado \"Noite da Lua Sangrenta\"? A cada Lua Sangrenta, os lobisomens abrem os olhos e começam a caçar, apenas para se misturar entre as boas pessoas no dia seguinte."
  },
  AvgDialog_126912_Content_82 = {
    Text = "Para identificar os lobisomens ocultos, a chave é inferir os motivos de todos durante a fase de discussão. Os lobisomens conhecem as identidades dos jogadores bons, então suas acusações costumam ser mais confiantes."
  },
  AvgDialog_126912_Content_83 = {
    Text = "A verdadeira Thais é a rainha que esteve em dormência por mil anos em Aram. Sua verdadeira natureza é completamente oposta à sua aparência; ela age com cautela e certamente não é alguém que facilmente suspeita dos outros."
  },
  AvgDialog_126912_Content_84 = {
    Text = "Então você votou em mim, não em Miryam."
  },
  AvgDialog_126912_Content_85 = {
    Text = "Eu escolhi estar na mesma sala que o assassino."
  },
  AvgDialog_126912_Content_86 = {
    Text = "Eu estava pronto para pegá-lo em flagrante quando você atacou, mas infelizmente, as ações de Miryam foram mais rápidas do que as suas..."
  },
  AvgDialog_126912_Content_87 = {
    Text = "Antes que você completasse minha hipnose, ela já havia atacado Wanda."
  },
  AvgDialog_126912_Content_88 = {
    Text = "Maravilhoso, maravilhoso raciocínio. Realmente me impressiona."
  },
  AvgDialog_126912_Content_89 = {
    Text = "Não, não é nem de longe o suficiente... Afinal, não estou planejando desempenhar o papel de detetive nesta história de acordo com o arranjo da pequena N."
  },
  AvgDialog_126912_Content_9 = {
    Text = "Wanda semicerrou os olhos e revelou um sorriso tranquilizador."
  },
  AvgDialog_126912_Content_90 = {
    Text = "Eu teria preferido parar sua conspiração antes que o incidente ocorresse. Mas já é tarde demais."
  },
  AvgDialog_126912_Content_91 = {
    Text = "Hoje em dia, tudo o que posso fazer é pedir que você me diga... qual é realmente a sua verdadeira forma?"
  },
  AvgDialog_126912_Content_92 = {
    Text = "Uma luz prateada irrompe da Chave de Prata no seu peito, parecendo perfurar todas as ilusões e disfarces."
  },
  AvgDialog_126912_Content_93 = {
    Text = "Hehe, hehehehe~"
  },
  AvgDialog_126912_Content_94 = {
    Text = "Seu ataque parece ter atingido o ar vazio."
  },
  AvgDialog_126912_Content_95 = {
    Text = "Ela se transformou em um fio de fumaça, um fio de névoa, uma presença evasiva e indescritível."
  },
  AvgDialog_126912_Content_96 = {
    Text = "Venha, siga-me."
  },
  AvgDialog_126912_Content_97 = {
    Text = "A névoa riu suavemente, estendendo um convite ambíguo e inexplicável a você."
  },
  AvgDialog_126912_Content_98 = {
    Text = "Venha comigo para desvendar a verdade da história."
  },
  AvgDialog_128696_Content_1 = {
    Text = "BANG! BANG! BANG!"
  },
  AvgDialog_128696_Content_10 = {Text = "Nautila!"},
  AvgDialog_128696_Content_11 = {
    Text = "Mosk correu apressadamente até Nautila, deitou-se em seu peito e percebeu que Nautila estava apenas muito cansado, adormecendo profundamente."
  },
  AvgDialog_128696_Content_12 = {
    Text = "Mosk soltou um suspiro de alívio e não conseguiu conter uma gargalhada."
  },
  AvgDialog_128696_Content_13 = {
    Text = "Pff, hahahaha!"
  },
  AvgDialog_128696_Content_14 = {
    Text = "Ela levou Nautila para a cama, ignorando sua resistência e rolando com você pelo chão várias vezes."
  },
  AvgDialog_128696_Content_15 = {
    Text = "Fugir, nós não precisamos nos separar!"
  },
  AvgDialog_128696_Content_16 = {
    Text = "Esta é a primeira vez que Mosk está tão relaxada desde aquele dia, seus olhos brilhantes de esperança, enquanto seu nariz feliz esfrega suavemente o pelo macio do seu peito."
  },
  AvgDialog_128696_Content_17 = {
    Text = "Dormir... só um pouquinho... de manhã... de manhã..."
  },
  AvgDialog_128696_Content_18 = {
    Text = "Mosk, que também não fechou os olhos por vários dias, te abraça firmemente, encostando-se ao canto da cama de Nautila, e cai em um sono profundo."
  },
  AvgDialog_128696_Content_19 = {Text = "..."},
  AvgDialog_128696_Content_2 = {
    Text = "Boom——Boom Boom——Boom!"
  },
  AvgDialog_128696_Content_20 = {
    Text = "@2, Mosk, @4..."
  },
  AvgDialog_128696_Content_21 = {
    Text = "@4 quase..."
  },
  AvgDialog_128696_Content_22 = {Text = "..."},
  AvgDialog_128696_Content_23 = {
    Text = "O navio havia saído apenas por meio dia, quando, sem aviso, uma enorme tempestade se aproximou."
  },
  AvgDialog_128696_Content_24 = {
    Text = "A direção está completamente perdida, a chuva cai sem parar, não dando aos desafiantes imprudentes nenhuma oportunidade de se retratar."
  },
  AvgDialog_128696_Content_25 = {
    Text = "O leme desviava de forma estranha, não importava o que Nautila e Mosk tentassem, mesmo quase danificando-o, não havia a menor tendência de voltar ao curso correto."
  },
  AvgDialog_128696_Content_26 = {
    Text = "Como pode ser, não deveria ser assim! Não houve nenhum sinal de aviso, a pressão estava completamente normal... não havia nenhum problema até nos aproximarmos dessas águas."
  },
  AvgDialog_128696_Content_27 = {
    Text = "É só que... É como se esse vórtice tivesse conjurado o vendaval especificamente para nos armar uma armadilha."
  },
  AvgDialog_128696_Content_28 = {Text = "Armadilha?"},
  AvgDialog_128696_Content_29 = {
    Text = "Exatamente quando estávamos mais próximos do vórtice, bastava mais cinco, não, mesmo três milhas náuticas, e já teríamos saído da área de influência do vórtice."
  },
  AvgDialog_128696_Content_3 = {
    Text = "A besta de aço adormecida há muito tempo emitiu um rugido rouco, o apito soou, e, sob o som das asas das gaivotas, todo o navio parecia lentamente ganhar vida."
  },
  AvgDialog_128696_Content_30 = {
    Text = "Sua cabeça já está confusa, você tenta desesperadamente emitir algum som, o que seria..."
  },
  AvgDialog_128696_Content_31 = {
    Text = "Ah, ah——!"
  },
  AvgDialog_128696_Content_32 = {
    Text = "Você só consegue emitir um grito de confusão, não entende, elas não conseguem sentir?"
  },
  AvgDialog_128696_Content_33 = {
    Text = "(Não se aproxime do vórtice, grandalhão, não se aproxime do vórtice!)"
  },
  AvgDialog_128696_Content_34 = {
    Text = "Aquela enorme e aterrorizante presença, Ele viu Mosk."
  },
  AvgDialog_128696_Content_35 = {
    Text = "<Red:Ele não tem a intenção de deixar ninguém partir.>"
  },
  AvgDialog_128696_Content_36 = {Text = "..."},
  AvgDialog_128696_Content_37 = {
    Text = "Não tem problema, Pequena bola de carvão, Mosk, estou aqui."
  },
  AvgDialog_128696_Content_38 = {
    Text = "Sim, acredite em mim, Pequena bola de carvão, Mosk. Há uma solução, eu com certeza vou pensar em uma!"
  },
  AvgDialog_128696_Content_39 = {
    Text = "Nautila……"
  },
  AvgDialog_128696_Content_4 = {
    Text = "O motor. Última etapa..."
  },
  AvgDialog_128696_Content_40 = {
    Text = "Sou eu quem deve levar o navio embora, fui eu quem trouxe vocês até aqui, certamente consigo pensar em uma solução, com certeza conseguirei mantê-los a salvo!"
  },
  AvgDialog_128696_Content_41 = {
    Text = "<change:Faça um buraco no casco do barco nesta posição, use a água para aumentar o peso...>"
  },
  AvgDialog_128696_Content_42 = {
    Text = "<Change>Não pode... @2a energia, certo, se, Desde Que sobrecarregue um dos motores, escapar da força de atração de @1"
  },
  AvgDialog_128696_Content_43 = {
    Text = "A menina se movia rapidamente entre os compartimentos, levando você e Mosk, tentando várias maneiras, enquanto um carmesim frenético gradualmente se espalhava em seus olhos."
  },
  AvgDialog_128696_Content_44 = {
    Text = "Clang——Bang!"
  },
  AvgDialog_128696_Content_45 = {
    Text = "Náutilo……"
  },
  AvgDialog_128696_Content_46 = {
    Text = "Com a perda de força, a chave inglesa bateu na parede e então caiu pesadamente sobre o pé de Náutilo, mas ela parecia não sentir dor, murmurando que queria continuar pegando a chave inglesa."
  },
  AvgDialog_128696_Content_47 = {
    Text = "<change>É tarde demais, o redemoinho está cada vez mais perto... Por que, por que, por que, POR QUÊ!! Eu tenho que salvar vocês, eu vou... eu vou...!"
  },
  AvgDialog_128696_Content_48 = {
    Text = "Crack—Boom—!"
  },
  AvgDialog_128696_Content_49 = {
    Text = "A tempestade e os golpes finalmente superaram os limites da cabine, e após um estalo nítido de ruptura, as tábuas velhas caíram em alta velocidade do teto da Nautila——"
  },
  AvgDialog_128696_Content_5 = {
    Text = "Ótimo! Mosk, Pequena bola de carvão, conseguimos!"
  },
  AvgDialog_128696_Content_50 = {
    Text = "<Big:Nautila! Pare!>"
  },
  AvgDialog_128696_Content_51 = {
    Text = "Abrindo os olhos fechados pelo medo, o que apareceu diante de Náutilo foi uma cena inesperada."
  },
  AvgDialog_128696_Content_52 = {
    Text = "Mosk se apoiou em uma mão na parede, protegendo-se com o corpo, enquanto a outra mão sustentava todo o teto."
  },
  AvgDialog_128696_Content_53 = {Text = "Ugh..."},
  AvgDialog_128696_Content_54 = {Text = "Ha!"},
  AvgDialog_128696_Content_55 = {
    Text = "Mosk empurrou com força o teto para longe, em seguida, agarrou Nautila, que estava à beira da loucura, segurando seu rosto com as duas mãos e fixando seu olhar nela."
  },
  AvgDialog_128696_Content_56 = {
    Text = "Está tudo bem, volte, da próxima vez."
  },
  AvgDialog_128696_Content_57 = {
    Text = "Voltar… Mas…"
  },
  AvgDialog_128696_Content_58 = {
    Text = "Nautila olhou ao redor, perdida, deixando a chuva torrencial cair sobre ela."
  },
  AvgDialog_128696_Content_59 = {
    Text = "O trovão e o relâmpago envolvem a tempestade, estimulando cada nervo, como a trilha sonora incessante de um banquete demoníaco."
  },
  AvgDialog_128696_Content_6 = {
    Text = "Náutilo, depois disso, começou a consertar o casco do navio sem descanso, restando três dias para a previsão da tempestade, todas as peças essenciais estavam de volta a seus devidos lugares."
  },
  AvgDialog_128696_Content_60 = {
    Text = "A gravidade do vórtice é muito forte, não conseguimos voltar..."
  },
  AvgDialog_128696_Content_61 = {
    Text = "Mosk ignorou as palavras de Nautila e arrastou o traje de mergulho da cabine, tentando colocá-lo em Nautila de forma desordenada e confusa."
  },
  AvgDialog_128696_Content_62 = {
    Text = "Roupa de mergulho? Não, eu coloquei, e agora?"
  },
  AvgDialog_128696_Content_63 = {
    Text = "Neste momento, o casco do navio já começou a inclinar-se descontroladamente em direção ao vórtice."
  },
  AvgDialog_128696_Content_64 = {
    Text = "<Shake:Crujido—Guinch guinch—>"
  },
  AvgDialog_128696_Content_7 = {
    Text = "Desde Que eu coloque a âncora... uf... estou com tanto sono..."
  },
  AvgDialog_128696_Content_8 = {Text = "Splash."},
  AvgDialog_128696_Content_9 = {
    Text = "Piu?! Piu——? (Pessoa?! Pessoa——?)"
  },
  AvgDialog_128697_Content_1 = {
    Text = "Bom. Melhor. O melhor de todos!"
  },
  AvgDialog_128697_Content_10 = {Text = "..."},
  AvgDialog_128697_Content_11 = {Text = "*aplausos"},
  AvgDialog_128697_Content_12 = {
    Text = "Embora seja verdade que tem um pouco de poder destrutivo."
  },
  AvgDialog_128697_Content_13 = {
    Text = "Guardião! Mosk! Derrote a tarefa maligna! Incrível!"
  },
  AvgDialog_128697_Content_14 = {
    Text = "Ei... Guardião de Segredos... Pequena bola de carvão?!"
  },
  AvgDialog_128697_Content_15 = {
    Text = "A intuição bestial de Mosk percebeu instantaneamente algo diferente, e ela saltou como um animal, pulando em sua direção e te abraçando."
  },
  AvgDialog_128697_Content_16 = {
    Text = "Auh! Mosk, dor!"
  },
  AvgDialog_128697_Content_17 = {
    Text = "Ao mesmo tempo, ela também usou a boca para desferir um golpe doloroso em seu pobre nariz."
  },
  AvgDialog_128697_Content_18 = {
    Text = "gaiola, restritor, Mosk, bom! Hehe, Mosk, segurança."
  },
  AvgDialog_128697_Content_19 = {
    Text = "O dispositivo especialmente desenvolvido por Misaq controlou bem a liberação de força, e o poder de destruição máximo de Mosk agora é equivalente ao de um humano um pouco mais forte."
  },
  AvgDialog_128697_Content_2 = {
    Text = "Olá, Guardião do Segredo. Sobre o Corpo Desperto O-1841, considerando que ele acabou de despertar e apresenta ocasionalmente sinais de Fúria, além de não conseguir controlar completamente suas habilidades, recomenda-se manter um estado de cautela ao entrar em contato com ele."
  },
  AvgDialog_128697_Content_20 = {
    Text = "Amigos, depois, uma aventura muito perfeita, tem? Não tem?"
  },
  AvgDialog_128697_Content_21 = {
    Text = "Você fez um grande esforço para tirar o cão grande e agitado de cima de você. Finalmente, ela estava disposta a ficar quieta por um momento, sentando-se do outro lado da mesa, com os olhos brilhantes fixos em você."
  },
  AvgDialog_128697_Content_22 = {Text = "Hmm..."},
  AvgDialog_128697_Content_23 = {
    Text = "Na verdade..."
  },
  AvgDialog_128697_Content_24 = {
    Text = "Existe uma enorme Fissura de fusão abaixo do vórtice M- Musk; embora Nautila e eu tenhamos escapado da influência do vórtice, ambos apresentamos sinais de amnésia."
  },
  AvgDialog_128697_Content_25 = {
    Text = "Você apenas hesitou por um momento e escolheu usar \"Eu\" como o termo para se referir àquela consciência no sonho."
  },
  AvgDialog_128697_Content_26 = {
    Text = "Nautila sempre quis te encontrar depois disso. Ela fundou um grupo de aventura, mas encontrou outro desastre durante a viagem de retorno..."
  },
  AvgDialog_128697_Content_27 = {
    Text = "Ela provavelmente não se lembra mais, mas... ela fez a mesma escolha que você."
  },
  AvgDialog_128697_Content_28 = {Text = "Assim..."},
  AvgDialog_128697_Content_29 = {
    Text = "Mas, que bom."
  },
  AvgDialog_128697_Content_3 = {
    Text = "Obrigado, Erica. Mas não se preocupe, eu acho que conheço bem o meu... amigo."
  },
  AvgDialog_128697_Content_30 = {Text = "Claro"},
  AvgDialog_128697_Content_31 = {
    Text = "Claro que sim! Depois, eu e Nautila..."
  },
  AvgDialog_128697_Content_32 = {
    Text = "Enfim, até que eu e Náutilo fiquemos tão velhos que não possamos nos mover, estaremos vivendo diversas aventuras."
  },
  AvgDialog_128697_Content_33 = {
    Text = "Você se esforçou ao máximo para incorporar todas as histórias de aventura que ouviu durante sua breve vida consciente de um ano na narrativa sobre Mosk."
  },
  AvgDialog_128697_Content_34 = {
    Text = "Afinal, meu Deus, você realmente não consegue dizer nenhuma palavra cruel para esses olhos."
  },
  AvgDialog_128697_Content_35 = {
    Text = "História deLu@2, Mosk, ouvi falar."
  },
  AvgDialog_128697_Content_36 = {
    Text = "<Gray:Ferrou, esqueci que isso era leitura de curso geral...>"
  },
  AvgDialog_128697_Content_37 = {
    Text = "É suportável."
  },
  AvgDialog_128697_Content_38 = {Text = "Ei?"},
  AvgDialog_128697_Content_39 = {
    Text = "Mosk abaixou a cabeça e, como quando você era uma pequena bola de carvão, encostou o rosto em sua palma."
  },
  AvgDialog_128697_Content_4 = {
    Text = "Diferente do que a academia esperava, sua primeira conexão com esse corpo despertado de poder fúria foi extraordinariamente suave."
  },
  AvgDialog_128697_Content_40 = {
    Text = "Amigo, pequena bola de carvão, nos encontramos de novo."
  },
  AvgDialog_128697_Content_41 = {
    Text = "Pequena bola de carvão, experiência no escuro, lembre-se de Mosk, bom."
  },
  AvgDialog_128697_Content_42 = {
    Text = "Ela sorriu amplamente, lhe dando um sorriso muito, muito feliz."
  },
  AvgDialog_128697_Content_43 = {
    Text = "Embora, a pulseira, não esteja mais."
  },
  AvgDialog_128697_Content_44 = {
    Text = "Mas, nós nos reencontramos, melhor, melhor do que melhor!"
  },
  AvgDialog_128697_Content_45 = {Text = "Mosk…"},
  AvgDialog_128697_Content_46 = {Text = "Zizi?"},
  AvgDialog_128697_Content_47 = {
    Text = "??Por que apareceu uma lontra usando um chapéu de Misaq aqui?"
  },
  AvgDialog_128697_Content_48 = {
    Text = "Desculpe, Guardião do Segredo, parece que muitos estudantes gostam muito dessa lontra exótica e fizeram algumas decorações desnecessárias nela."
  },
  AvgDialog_128697_Content_49 = {
    Text = "Erica iniciará o processo de expulsão o mais rápido possível, 1, 2——"
  },
  AvgDialog_128697_Content_5 = {
    Text = "Depois deste sonho inesperado, você acha que já encontrou a resposta."
  },
  AvgDialog_128697_Content_50 = {
    Text = "Ah, lontra-marinha! Que fofa, vamos brincar com a Mosk!"
  },
  AvgDialog_128697_Content_51 = {
    Text = "Bum. Tum. Clang—"
  },
  AvgDialog_128697_Content_52 = {Text = "Bang!"},
  AvgDialog_128697_Content_53 = {Text = "Sss, Mosk!"},
  AvgDialog_128697_Content_54 = {
    Text = "Nautila acabou de entrar na sala de aula e viu seu novo amigo, correndo atrás de uma lontra usando um chapéu de Misaq, destruindo os equipamentos de ensino na sala."
  },
  AvgDialog_128697_Content_55 = {
    Text = "Guardião, por favor diga à professora Erica que eu vou consertar tudo na sala de aula!"
  },
  AvgDialog_128697_Content_56 = {
    Text = "Mosk, pare agora!"
  },
  AvgDialog_128697_Content_57 = {
    Text = "Ah——Ah!"
  },
  AvgDialog_128697_Content_58 = {Text = "Ai!!"},
  AvgDialog_128697_Content_59 = {Text = "*aplauso"},
  AvgDialog_128697_Content_6 = {
    Text = "Ela gosta de carne assada, ama o mar, é muito medrosa, detesta o frio, a escuridão e a solidão, e chora discretamente quando se depara com elas."
  },
  AvgDialog_128697_Content_60 = {
    Text = "Se eu não entendi errado, aquela lontra está dizendo \"brinque comigo\", certo... como ela se comunica com a Mosk?"
  },
  AvgDialog_128697_Content_61 = {
    Text = "Ei, não é isso, por que eu também consigo entender o lontra falando?!"
  },
  AvgDialog_128697_Content_62 = {
    Text = "Espere, assim..."
  },
  AvgDialog_128697_Content_63 = {
    Text = "Cof cof, lontra desconhecida de Misaq, agora eu vou te conceder o título de Pequena bola de carvão."
  },
  AvgDialog_128697_Content_64 = {
    Text = "Você herdará o título de Pequena bola de carvão e se tornará o grande e glorioso Pequena bola de carvão II!"
  },
  AvgDialog_128697_Content_65 = {Text = "!"},
  AvgDialog_128697_Content_66 = {
    Text = "Pequena bola de carvão, Segundo! Pequena bola de carvão, Segundo!"
  },
  AvgDialog_128697_Content_67 = {
    Text = "Tic—— (Impacto de lontra!)"
  },
  AvgDialog_128697_Content_68 = {
    Text = "Nautila——"
  },
  AvgDialog_128697_Content_69 = {
    Text = "Ótimo, está um caos completo——"
  },
  AvgDialog_128697_Content_7 = {
    Text = "À tarde, o sol de Misaq está ótimo, os raios do sol atravessam o vitral, projetando luz no rosto da menina que está brigando com o livro da aula de línguas."
  },
  AvgDialog_128697_Content_70 = {
    Text = "Então, como meu legítimo herdeiro, <Small:é seu dever solene resolver o que me desagrada, a mim, Pequena bola de carvão, a Primeira Geração...>"
  },
  AvgDialog_128697_Content_71 = {
    Text = "Você assobia de maneira descontraída, silenciosamente, silenciosamente——"
  },
  AvgDialog_128697_Content_72 = {
    Text = "Jogar sua tarefa de cálculo em direção às garras da lontra, aproveitando a confusão."
  },
  AvgDialog_128697_Content_73 = {
    Text = "Num piscar de olhos, a tarefa se transformou em papel amassado, deitado silenciosamente na pilha de papel velho."
  },
  AvgDialog_128697_Content_74 = {
    Text = "Que dia maravilhoso, não é, Náutilo, Mosk?"
  },
  AvgDialog_128697_Content_75 = {Text = "Ah—!"},
  AvgDialog_128697_Content_76 = {
    Text = "Hoje, a Misaq é muito amigável e pacífica."
  },
  AvgDialog_128697_Content_77 = {
    Text = "É algo a se alegrar, é algo a se alegrar."
  },
  AvgDialog_128697_Content_8 = {
    Text = "Mas também é muito corajosa, e ficará à frente de todas as coisas que ela odeia por seus amigos."
  },
  AvgDialog_128697_Content_9 = {
    Text = "Sss— o livro se partiu em dois na atmosfera recém-emocionante."
  },
  AvgDialog_128698_Content_1 = {
    Text = "Splish～Splash～"
  },
  AvgDialog_128698_Content_10 = {
    Text = "A energia e o combustível não são problema, mas o casco do navio é muito frágil... Mosk, há alguma maneira de contornar aquele grande vórtice? Foi perto dele que a frota anterior teve problemas."
  },
  AvgDialog_128698_Content_11 = {
    Text = "…Não consigo sair."
  },
  AvgDialog_128698_Content_12 = {
    Text = "Mosk balança a cabeça, levanta você novamente e ambos se esforçam juntos com as quatro mãos e os quatro pés."
  },
  AvgDialog_128698_Content_13 = {
    Text = "Pessoas más, pegaram Mamãe e Papai. Mosk, mordeu, levada embora. Pequena bola de carvão, no navio, encontrou."
  },
  AvgDialog_128698_Content_14 = {
    Text = "O mar, chama—— aqui, Mosk, pense em algo, não dá."
  },
  AvgDialog_128698_Content_15 = {
    Text = "Você foi trazido aqui por pessoas más e, depois de se separar de papai e mamãe, nunca mais conseguiu sair?"
  },
  AvgDialog_128698_Content_16 = {
    Text = "Ausente, papai e mamãe."
  },
  AvgDialog_128698_Content_17 = {
    Text = "Desculpe..."
  },
  AvgDialog_128698_Content_18 = {
    Text = "Certo, papai e mamãe, como, venham!"
  },
  AvgDialog_128698_Content_19 = {
    Text = "Mosk! Para onde você está me arrastando?!"
  },
  AvgDialog_128698_Content_2 = {
    Text = "Basta consertar completamente o rolamento desta parte, o leme vai..."
  },
  AvgDialog_128698_Content_20 = {Text = "..."},
  AvgDialog_128698_Content_21 = {
    Text = "Ufa... Ufa, você é um monstro?! Por que você consegue nadar tão rápido mesmo me carregando!"
  },
  AvgDialog_128698_Content_22 = {
    Text = "Ei, que lugar é este?"
  },
  AvgDialog_128698_Content_23 = {Text = "Ah—!"},
  AvgDialog_128698_Content_24 = {
    Text = "Você pulou na água com alegria, assustando os peixes ao redor."
  },
  AvgDialog_128698_Content_25 = {
    Text = "Com os gritos de alegria seu e de Mosk ao entrarem na água, ondulações surgem das profundezas, como se respondessem aos seus chamados."
  },
  AvgDialog_128698_Content_26 = {
    Text = "Mamãe, papai, igual a eles! Nautila, Mosk, igual!"
  },
  AvgDialog_128698_Content_27 = {
    Text = "Vários golfinhos brancos e bonitos emergem do fundo do mar, se agrupando ao redor de vocês, esfregando-se carinhosamente com seus focinhos e nadadeiras em você e Mosk."
  },
  AvgDialog_128698_Content_28 = {
    Text = "Elas nadam levemente ao redor de vocês, até saltando para fora da água, jorrando um pouco de fonte em direção à Nautila, como se estivessem fazendo um convite a ela."
  },
  AvgDialog_128698_Content_29 = {
    Text = "Eles são... golfinhos? Mosk, você está dizendo que seus pais são golfinhos também?"
  },
  AvgDialog_128698_Content_3 = {
    Text = "Navio usurpado?"
  },
  AvgDialog_128698_Content_30 = {
    Text = "Sim. Pequena Mosk, perdida. Golfinhos, alimentar pequena Mosk. Mosk, crescer!"
  },
  AvgDialog_128698_Content_31 = {
    Text = "Mosk, Ei, Pequena bola de carvão, Pequena bola de carvão, cresça!"
  },
  AvgDialog_128698_Content_32 = {
    Text = "Mosk riu alto, desviando-se da água que você jogou nela por raiva, e então, vocês estenderam as mãos para Nautila juntos."
  },
  AvgDialog_128698_Content_33 = {
    Text = "Acredite em mim, amigo."
  },
  AvgDialog_128698_Content_34 = {
    Text = "...Tá bom!"
  },
  AvgDialog_128698_Content_35 = {
    Text = "Nautila agarra firmemente suas mãos. Um à frente, outro atrás, você e Mosk a guiam em direção a uma caverna escondida."
  },
  AvgDialog_128698_Content_36 = {
    Text = "Após uma breve escuridão, um grupo, dois grupos... inúmeros grupos de luzes suaves e etéreas foram despertados; as águas-vivas subiram à superfície, sendo gentilmente afastadas pelo redemoinho, até que uma luz mais brilhante desceu pela cúpula."
  },
  AvgDialog_128698_Content_37 = {
    Text = "...Eu, não estou sonhando, estou?"
  },
  AvgDialog_128698_Content_38 = {
    Text = "A luz do sol penetra nas camadas de rocha, refletindo um azul profundo e raso na superfície do mar sem fundo. Os corais coloridos cortam novamente o azul, apresentando uma cena que deixa as pessoas sem palavras, junto com muitas criaturas marinhas."
  },
  AvgDialog_128698_Content_39 = {
    Text = "As anêmonas marinhas arrastam seus tentáculos venenosos em uma dança lenta e hipnótica. Moluscos se agarram perto, vivendo em silenciosa harmonia com elas. Predadores espreitam na escuridão do abismo, aguardando o momento certo. Este lugar é perigoso e belo, sombrio e deslumbrante — um mundo em si, uma miniatura do oceano."
  },
  AvgDialog_128698_Content_4 = {
    Text = "O leme é algo que controla a direção, assim como um volante. Você sabe o que é um volante?"
  },
  AvgDialog_128698_Content_40 = {Text = "Náutilo?"},
  AvgDialog_128698_Content_41 = {
    Text = "Isto, bonito, para você."
  },
  AvgDialog_128698_Content_42 = {
    Text = "Mosk, em algum momento, tirou uma pérola que emitia um brilho suave e, com uma expressão muito, muito séria, a colocou na palma da mão de Nautila."
  },
  AvgDialog_128698_Content_43 = {
    Text = "Mosk, aqui, gosto. Mosk, tesouro, gosto. Nautila, amigo, para você."
  },
  AvgDialog_128698_Content_44 = {
    Text = "(Eu pedi tantas vezes e você nunca me deu, grandalhão, malvado!)"
  },
  AvgDialog_128698_Content_45 = {
    Text = "Embora você estivesse murmurando isso em seu coração, ao pensar nas deliciosas trutas assadas e frutos do mar que comeu durante esse tempo, você generosamente empurrou as pérolas para a mão de Nautila junto com Mosk."
  },
  AvgDialog_128698_Content_46 = {
    Text = "Oh — obrigada! Bem, então eu também tenho um presente para Mosk."
  },
  AvgDialog_128698_Content_47 = {Text = "Casa Li?"},
  AvgDialog_128698_Content_48 = {
    Text = "Nautila desamarra a pequena pulseira de seu pulso — aquela que ela sempre usa, decorada com um pequeno pingente de nautilus."
  },
  AvgDialog_128698_Content_49 = {
    Text = "Algo que um amigo dá a outro amigo se chama \"presente\". A pérola é seu presente para mim. E isto... isto é meu presente para você."
  },
  AvgDialog_128698_Content_5 = {Text = "Hum?"},
  AvgDialog_128698_Content_50 = {
    Text = "Minha mãe me deu um colar e uma pulseira, e eu combinei com ela que me tornaria um grande aventureiro."
  },
  AvgDialog_128698_Content_51 = {
    Text = "Mosk, eu logo vou consertar o barco. Vamos partir juntas e encontrar seus pais."
  },
  AvgDialog_128698_Content_52 = {
    Text = "E depois disso... você estaria disposta a usar esta pulseira, trazer a Pequena bola de carvão junto, e vir em uma aventura comigo?"
  },
  AvgDialog_128698_Content_53 = {Text = "..."},
  AvgDialog_128698_Content_54 = {
    Text = "Nautila, Mosk, Pequena bola de carvão, Aventura!"
  },
  AvgDialog_128698_Content_55 = {Text = "Ahuh!"},
  AvgDialog_128698_Content_56 = {
    Text = "Depois de um breve silêncio que parecia uma ilusão, Mosk levantou seu sorriso brilhante como sempre e, abraçando você, soltou um grito de alegria."
  },
  AvgDialog_128698_Content_57 = {
    Text = "Pip! (Aventura!)"
  },
  AvgDialog_128698_Content_58 = {
    Text = "O que você pode perceber? Você é apenas uma lontra marinha. Mesmo que seu olfato aguçado tenha detectado algo, seu cérebro pequeno não permite que você compreenda. E assim você deixa passar, mergulhando de cabeça na atmosfera alegre."
  },
  AvgDialog_128698_Content_59 = {
    Text = "Ótimo, pequena bola de carvão, eu também preparei um presente para você!"
  },
  AvgDialog_128698_Content_6 = {
    Text = "O volante é o que controla a direção de todos os grandes veículos; para onde o volante aponta, o navio e o carro irão."
  },
  AvgDialog_128698_Content_60 = {Text = "..."},
  AvgDialog_128698_Content_61 = {Text = "!"},
  AvgDialog_128698_Content_62 = {
    Text = "O porão outrora em ruínas agora se transformou completamente; entre duas camas idênticas, simples, mas limpas e robustas, há uma caixa de madeira cheia de colchões macios."
  },
  AvgDialog_128698_Content_63 = {
    Text = "Hehe, agora todos têm uma cama."
  },
  AvgDialog_128698_Content_64 = {
    Text = "Assim que Nautila terminou de falar, você caiu todo no seu perfeito ninho — ela até deixou um espaço especial para suas preciosas conchinhas!"
  },
  AvgDialog_128698_Content_65 = {
    Text = "A sopa de frutos do mar do jantar ainda está morna em seu estômago, e com a respiração tranquila das meninas, você rapidamente adormeceu."
  },
  AvgDialog_128698_Content_66 = {
    Text = "Mas quando a verdadeira noite chega, aquela sensação sinistra se espalha como a névoa noturna pegajosa sobre o mar."
  },
  AvgDialog_128698_Content_67 = {
    Text = "<Shake:Mosk, @3...>"
  },
  AvgDialog_128698_Content_68 = {
    Text = "<Shake:Devolver a mim, obedeça-me, @4...@4!>"
  },
  AvgDialog_128698_Content_69 = {
    Text = "Na escuridão, o mar se torna repleto de horror e mistério. A luz do sol não toca mais a superfície, e nas profundezas do abismo, algo se agita com um murmúrio profundo e gutural."
  },
  AvgDialog_128698_Content_7 = {
    Text = "Oh — entendi! O volante! Que legal!"
  },
  AvgDialog_128698_Content_70 = {
    Text = "Você flutua em um vazio sem fim e frio, lutando desesperadamente para se aproximar da figura à distância que está chorando em voz baixa."
  },
  AvgDialog_128698_Content_71 = {
    Text = "Ah——(grande——)"
  },
  AvgDialog_128698_Content_72 = {
    Text = "Ah!(Grandão!)"
  },
  AvgDialog_128698_Content_73 = {
    Text = "Você acorda abruptamente, sem os suaves suspiros das meninas adormecidas, tudo está em silêncio. Você sai do seu ninho e segue o aroma de Mosk até o convés."
  },
  AvgDialog_128698_Content_74 = {
    Text = "Ela está olhando para o vórtice à distância."
  },
  AvgDialog_128698_Content_75 = {
    Text = "(Outro sonho, desde que aquelas pessoas humanas desagradáveis morreram, quantas vezes já foi desde que nos estabelecemos aqui?)"
  },
  AvgDialog_128698_Content_76 = {
    Text = "Chamar, Mosk, lá."
  },
  AvgDialog_128698_Content_77 = {
    Text = "Assustador... não..."
  },
  AvgDialog_128698_Content_78 = {
    Text = "Ei, Pequena bola de carvão, Mosk, o que vocês estão fazendo aí fora?"
  },
  AvgDialog_128698_Content_79 = {
    Text = "A voz de Náutilo interrompeu o sussurro do sonho de Mosk, e no instante seguinte, Náutilo empolgadamente empurrou um conjunto de chapa de ferro para mostrar a vocês."
  },
  AvgDialog_128698_Content_8 = {Text = "..."},
  AvgDialog_128698_Content_80 = {
    Text = "Mosk, você não disse antes que mergulhar em lugares muito profundos pode ser desconfortável, mas que ainda assim tem muita vontade de ver?"
  },
  AvgDialog_128698_Content_81 = {
    Text = "Eu consertei o traje de mergulho que encontrei no navio. Com isso, você poderá mergulhar por mais tempo, e não se sentirá mais desconfortável."
  },
  AvgDialog_128698_Content_82 = {
    Text = "Pena que preciso consertar o navio antes da próxima tempestade chegar. Depois da tempestade, vou fazer um conjunto para mim também."
  },
  AvgDialog_128698_Content_83 = {
    Text = "Um dia, vamos poder explorar o mar juntas!"
  },
  AvgDialog_128698_Content_84 = {
    Text = "Mosk raramente ficou em silêncio, e depois de um momento, ela acenou com a cabeça com força, te abraçou e deu um grande abraço em Nautila."
  },
  AvgDialog_128698_Content_85 = {Text = "escapar."},
  AvgDialog_128698_Content_86 = {
    Text = "Mosk, Nautila, Pequena bola de carvão, escapar! Juntos!"
  },
  AvgDialog_128698_Content_9 = {
    Text = "Os dados dos instrumentos mostram que temos no máximo uma semana até que uma tempestade chegue—uma que durará pelo menos meio mês. Este navio já está em mau estado... Nem sei se vai aguentar depois da tempestade."
  },
  AvgDialog_128699_Content_1 = {
    Text = "Plic, ploc."
  },
  AvgDialog_128699_Content_10 = {
    Text = "Mosk, ouça-me, fui eu quem sugeriu zarpar, e também fui eu quem não previu o tempo, então é minha obrigação resgatar você e a Pequena bola de carvão."
  },
  AvgDialog_128699_Content_11 = {
    Text = "Vou tirar o traje de mergulho para você agora. O navio ainda pode se mover, vou fazer o possível para controlá-lo e navegar até a borda do vórtice, então você..."
  },
  AvgDialog_128699_Content_12 = {Text = "Você..."},
  AvgDialog_128699_Content_13 = {
    Text = "Nautila ficou paralisada no mesmo lugar, ela viu a menina ingênua, alegre e despreocupada que antes raramente mostrava uma expressão de preocupação complexa."
  },
  AvgDialog_128699_Content_14 = {
    Text = "Nautila, desculpe."
  },
  AvgDialog_128699_Content_15 = {
    Text = "Mosk estendeu a mão. Embora não entendesse como o dispositivo funcionava, movida por um instinto bestial, ela forçosamente terminou de vestir o traje de mergulho em Nautila."
  },
  AvgDialog_128699_Content_16 = {
    Text = "Mosk, perigo, pressentimento."
  },
  AvgDialog_128699_Content_17 = {
    Text = "Mas, esperar, não vai acontecer."
  },
  AvgDialog_128699_Content_18 = {
    Text = "A água da chuva entra pelo buraco no telhado, batendo nas duas pessoas."
  },
  AvgDialog_128699_Content_19 = {
    Text = "O silêncio se espalhou pela casa, e no final, foi Mosk quem quebrou esse peso."
  },
  AvgDialog_128699_Content_2 = {
    Text = "<Shake:Crujido—Guinch guinch—>"
  },
  AvgDialog_128699_Content_20 = {
    Text = "Mosk, venha aqui, sonhe."
  },
  AvgDialog_128699_Content_21 = {
    Text = "Mosk sonhou com... algo chamado Mosk..."
  },
  AvgDialog_128699_Content_22 = {
    Text = "Mas, não quero ir. Frio, ninguém por perto, solidão..."
  },
  AvgDialog_128699_Content_23 = {
    Text = "Nautila de repente percebeu por que a chuva torrencial caiu mais cedo, por que o tornado apareceu sem aviso. Ela começou a tremer descontroladamente."
  },
  AvgDialog_128699_Content_24 = {
    Text = "Aquela coisa... bem ali..."
  },
  AvgDialog_128699_Content_25 = {
    Text = "Seguindo o dedo de Mosk, Nautila sentiu uma onda de medo que se espalhava em seu subconsciente."
  },
  AvgDialog_128699_Content_26 = {
    Text = "O medo que vem do fundo do vórtice de Merscus, transcendendo as coisas mortais."
  },
  AvgDialog_128699_Content_27 = {Text = "..."},
  AvgDialog_128699_Content_28 = {
    Text = "Não, não, não—eu sei o que você vai fazer, de jeito nenhum!"
  },
  AvgDialog_128699_Content_29 = {
    Text = "Acredite em mim, deve haver outra maneira!"
  },
  AvgDialog_128699_Content_3 = {
    Text = "A fúria da correnteza é como um par de mãos gigantes, torcendo o navio como se fosse uma toalha."
  },
  AvgDialog_128699_Content_30 = {
    Text = "Nautila pressionou ansiosamente Mosk, embora, considerando sua força, Mosk pudesse se libertar da restrição a qualquer momento, a menina bestial não o fez."
  },
  AvgDialog_128699_Content_31 = {
    Text = "Ela apenas te levantou e esfregou-se carinhosamente."
  },
  AvgDialog_128699_Content_32 = {
    Text = "Amigo, forte, mas, não. Apenas, Mosk, pode."
  },
  AvgDialog_128699_Content_33 = {
    Text = "Apenas, Mosk, pode."
  },
  AvgDialog_128699_Content_34 = {
    Text = "……Por quê, por que isso está acontecendo."
  },
  AvgDialog_128699_Content_35 = {
    Text = "Amigo, não chore, ria, Mosk, gosto!"
  },
  AvgDialog_128699_Content_36 = {
    Text = "Ah, desculpe, vi que vocês pareciam comer peixe cru, então preparei um pouco... Embora não haja temperos, quer Experimentar?"
  },
  AvgDialog_128699_Content_37 = {Text = "Awo!!"},
  AvgDialog_128699_Content_38 = {Text = "Awo!!"},
  AvgDialog_128699_Content_39 = {Text = "Delicioso"},
  AvgDialog_128699_Content_4 = {
    Text = "O casco emitia um som de torção insuportável, e Mosk quase gritava no meio da tempestade, enquanto lutava para enfiar o Nautila em um traje de mergulho, segurando você, que estava prestes a ser jogado para longe."
  },
  AvgDialog_128699_Content_40 = {
    Text = "Aventura, estou ansioso!"
  },
  AvgDialog_128699_Content_41 = {
    Text = "Mosk, vou consertar o navio em breve e levar você para longe daqui para encontrar sua mamãe e papai."
  },
  AvgDialog_128699_Content_42 = {
    Text = "Depois disso, você gostaria de levar esta pulseira, pegar o Coalsie e ir em uma aventura comigo?"
  },
  AvgDialog_128699_Content_43 = {
    Text = "Nautila, Mosk, Pequena bola de carvão, Aventura!"
  },
  AvgDialog_128699_Content_44 = {
    Text = "Amigo, gosto!"
  },
  AvgDialog_128699_Content_45 = {
    Text = "Amigo, deu-me Mosk, muito e muito!"
  },
  AvgDialog_128699_Content_46 = {
    Text = "Então, agora, Mosk vai dar muitos, muitos para os amigos!"
  },
  AvgDialog_128699_Content_47 = {
    Text = "Ela parece ter se construído como uma parede na tempestade, segurando você e Nautila firmemente no meio, então, respirou fundo, abriu a boca e mostrou o sorriso tranquilizador característico de Mosk."
  },
  AvgDialog_128699_Content_48 = {
    Text = "Mosk, com certeza, voltará!"
  },
  AvgDialog_128699_Content_49 = {
    Text = "…certo, eu confio em Mosk, quando você voltar, estarei pronto com o melhor navio do mundo, e levarei você e a Pequena bola de carvão para uma aventura incrível."
  },
  AvgDialog_128699_Content_5 = {
    Text = "Perigo! Agarre!"
  },
  AvgDialog_128699_Content_50 = {
    Text = "Nautila enxugou as lágrimas, forçou um pouco de ânimo e exibiu um sorriso um tanto feio."
  },
  AvgDialog_128699_Content_51 = {
    Text = "Vendo que Nautila finalmente a soltou, Mosk silenciosamente, bem silenciosamente, pega sua pata na dela e encosta o rosto nas suas almofadinhas."
  },
  AvgDialog_128699_Content_52 = {
    Text = "Não, tenha medo."
  },
  AvgDialog_128699_Content_53 = {
    Text = "Ah... Ah! (Você vai me deixar para trás...)"
  },
  AvgDialog_128699_Content_54 = {
    Text = "Ah!! Ah—(Você vai me deixar!!)"
  },
  AvgDialog_128699_Content_55 = {
    Text = "Você é colocado nos braços do Nautila ao som de um uivo agudo, e no momento seguinte, quando o Mosk se inclina novamente, você se vira sem hesitar e corre na direção do vórtice."
  },
  AvgDialog_128699_Content_56 = {Text = "...Plop."},
  AvgDialog_128699_Content_57 = {
    Text = "Como um peixe entrou no seu mar."
  },
  AvgDialog_128699_Content_58 = {Text = "Mosk!!"},
  AvgDialog_128699_Content_59 = {
    Text = "A tempestade cobriu todos os gritos, uma onda enorme subiu ao convés e os arrastou para o mar."
  },
  AvgDialog_128699_Content_6 = {Text = "Boom—"},
  AvgDialog_128699_Content_60 = {
    Text = "Sob as águas negras e azuis do mar, inúmeras linhas de lodo negro se abrem para Mosk, suas mãos se transformam em um enorme vórtice, com uma expressão serena e tranquila, nos profundos e calmos olhos, parece o centro do vórtice."
  },
  AvgDialog_128699_Content_61 = {
    Text = "Mosk, redemoinho. Mosk, leme."
  },
  AvgDialog_128699_Content_62 = {
    Text = "Pequena bola de carvão, Nautila, aqui, sempre."
  },
  AvgDialog_128699_Content_63 = {
    Text = "Mosk finalmente não consegue se conter e desata a chorar, pressionando a mão contra o próprio peito."
  },
  AvgDialog_128699_Content_64 = {
    Text = "Então ela ergue a mão. Um vórtice carregando força destrutiva, porém anormalmente gentil, empurra vocês dois para longe, muito longe do redemoinho."
  },
  AvgDialog_128699_Content_65 = {
    Text = "Um fio, e outro fio, o muco grudou no corpo de Mosk, rapidamente cobrindo todo o seu corpo."
  },
  AvgDialog_128699_Content_66 = {
    Text = "O vórtice começou a se fechar em torno do centro, envolvendo seu desejo realizado, a menina foi enrolada e puxada por inúmeras algas negras, gradualmente afundando no fundo sombrio do mar."
  },
  AvgDialog_128699_Content_67 = {Text = "..."},
  AvgDialog_128699_Content_68 = {
    Text = "Tudo se acalmou, o céu azul claro, e sobre a superfície tranquila do mar, os barcos flutuam silenciosamente."
  },
  AvgDialog_128699_Content_69 = {
    Text = "Huh, onde estou? Por que estou na água? Ufa, que abafado!"
  },
  AvgDialog_128699_Content_7 = {
    Text = "A tremulação violenta lançou Nautila para fora, fazendo-a colidir com o barril de madeira que rolava no chão."
  },
  AvgDialog_128699_Content_70 = {
    Text = "Você olhou estranhamente para a pessoa humana vestida de maneira esquisita, flutuando na água."
  },
  AvgDialog_128699_Content_71 = {
    Text = "(O que eu estou fazendo aqui, quem é aquele cara?)"
  },
  AvgDialog_128699_Content_72 = {Text = "Pat pat."},
  AvgDialog_128699_Content_73 = {Text = "Pat pat."},
  AvgDialog_128699_Content_74 = {
    Text = "(Ah, é mesmo, eu sou uma lontra marinha! E lontras marinhas procuram conchas. Conchas, conchas, conchas!)"
  },
  AvgDialog_128699_Content_75 = {
    Text = "Você mergulha alegremente na água morna, indo na direção oposta daquela pessoa que nada com dificuldade em direção ao barco."
  },
  AvgDialog_128699_Content_76 = {
    Text = "Você não percebeu que se misturou às lágrimas no mar."
  },
  AvgDialog_128699_Content_8 = {Text = "Ugh..."},
  AvgDialog_128699_Content_9 = {
    Text = "Nautila, suportando a dor, levantou-se cambaleando e correu em direção a Mosk."
  },
  AvgDialog_128700_Content_1 = {
    Text = "Glug... Glug..."
  },
  AvgDialog_128700_Content_10 = {
    Text = "Você é uma lontra de um ano e meio, procurando comida com seu grande amigo favorito."
  },
  AvgDialog_128700_Content_100 = {
    Text = "A saliva se secreta descontroladamente, e sob a tentação da comida pronta, você e Mosk quase ao mesmo tempo se lançam, mordendo o peixe assado."
  },
  AvgDialog_128700_Content_101 = {
    Text = "Delicioso — !"
  },
  AvgDialog_128700_Content_102 = {
    Text = "Ei, ah... Nautila, a mão?"
  },
  AvgDialog_128700_Content_103 = {
    Text = "Foi apenas uma luxação, eu já coloquei de volta sozinho. Para um aventureiro, não é nada demais, obrigado pelo remédio!"
  },
  AvgDialog_128700_Content_104 = {
    Text = "<Small:(Embora seja amargo e forte, o efeito é realmente bom.)>"
  },
  AvgDialog_128700_Content_105 = {
    Text = "Yahuu! Feliz, abrace..."
  },
  AvgDialog_128700_Content_106 = {
    Text = "Ei ei, Mosk, cuidado."
  },
  AvgDialog_128700_Content_107 = {
    Text = "Ei? Ei! Não se preocupe, Mosk, da próxima vez, eu vou gritar de dor para te avisar."
  },
  AvgDialog_128700_Content_108 = {Text = "Piu!"},
  AvgDialog_128700_Content_11 = {
    Text = "(O que temos aqui? Algas, ervas marinhas, pedrinhas...)"
  },
  AvgDialog_128700_Content_12 = {
    Text = "(E Pedra, tia de Pedra, avô de Pedra...?)"
  },
  AvgDialog_128700_Content_13 = {
    Text = "(PEDRA! Diga para toda a sua família parar de ficar nadando por aqui!!)"
  },
  AvgDialog_128700_Content_14 = {
    Text = "<Shake:ROAARRR—>"
  },
  AvgDialog_128700_Content_15 = {Text = "(Ai...)"},
  AvgDialog_128700_Content_16 = {
    Text = "O mar se agita formando um enorme redemoinho. Uma figura familiar vem disparada em sua direção, carregando algo grande nas costas!"
  },
  AvgDialog_128700_Content_17 = {
    Text = "Pequena bola de carvão! Carne! Mosk, peguei!"
  },
  AvgDialog_128700_Content_18 = {
    Text = "Feliz! Voltar para casa! Juntos!"
  },
  AvgDialog_128700_Content_19 = {
    Text = "Antes que você pudesse protestar, a garota te puxou para suas costas também e disparou em direção à superfície como um peixe."
  },
  AvgDialog_128700_Content_2 = {
    Text = "<Shake:Glu glu... Grrr...>"
  },
  AvgDialog_128700_Content_20 = {Text = "..."},
  AvgDialog_128700_Content_21 = {
    Text = "BOOM——! Um relâmpago corta o céu, o trovão ecoa, e as nuvens de chuva inchadas finalmente se rompem, despejando sua água no mar."
  },
  AvgDialog_128700_Content_22 = {
    Text = "Você e Mosk se refugiam na cabine segura, se encarando."
  },
  AvgDialog_128700_Content_23 = {
    Text = "Ah? Ah, ah! (Isto é carne? Grande, isso é igual a você!)"
  },
  AvgDialog_128700_Content_24 = {
    Text = "Igual a mim?"
  },
  AvgDialog_128700_Content_25 = {
    Text = "Mosk inclinou a cabeça, mostrando sua expressão de confusão característica, e então abaixou a cabeça seriamente para olhar a \"carne\" que ela havia colocado no chão."
  },
  AvgDialog_128700_Content_26 = {
    Text = "Pff—Urgh."
  },
  AvgDialog_128700_Content_27 = {
    Text = "O que aconteceu agora há pouco? Minha cabeça parece estar sempre na água. Onde estou? Eu morri?"
  },
  AvgDialog_128700_Content_28 = {
    Text = "Um estranho tossiu algumas vezes e cuspiu um grande bocado de água salgada."
  },
  AvgDialog_128700_Content_29 = {
    Text = "Amigo? Amigo!! Igual a Mosk!"
  },
  AvgDialog_128700_Content_3 = {
    Text = "<Shake:Glug glug glug—>"
  },
  AvgDialog_128700_Content_30 = {Text = "Eh... Hã?"},
  AvgDialog_128700_Content_31 = {
    Text = "<LightGray:É de alguma tribo indígena nas proximidades? Estranho... E onde exatamente é este lugar?>"
  },
  AvgDialog_128700_Content_32 = {
    Text = "Você percebe que ela está cautelosa, mas não hostil. Silenciosamente, você se aproxima para observar melhor esse recém-chegado."
  },
  AvgDialog_128700_Content_33 = {
    Text = "Parece ser a cabine de um navio. Desgastada, mas estruturalmente intacta na maior parte..."
  },
  AvgDialog_128700_Content_34 = {
    Text = "Espera—esses são rebites da Corporação Northdrey?! Medidores de nível de água, válvulas deslizantes anulares—"
  },
  AvgDialog_128700_Content_35 = {
    Text = "Vejamos, nesse caso..."
  },
  AvgDialog_128700_Content_36 = {
    Text = "O estranho vasculha animadamente a cabine abarrotada. Enquanto isso, Mosk fica por perto, piscando com curiosidade alegre."
  },
  AvgDialog_128700_Content_37 = {
    Text = "Brilhante, bonito. Mosk, trazer. Amigo, gostou?"
  },
  AvgDialog_128700_Content_38 = {
    Text = "Mosk, com essas peças, eu consigo fazer este navio voltar a funcionar. Você pode me dar?"
  },
  AvgDialog_128700_Content_39 = {
    Text = "Quando chegarmos a Aglo, eu prometo que vou te trazer ainda mais coisas brilhantes, ainda mais bonitas."
  },
  AvgDialog_128700_Content_4 = {
    Text = "Você flutua de costas na água morna do mar, esticando confortavelmente seus curtos membros e fazendo uma volta perfeita."
  },
  AvgDialog_128700_Content_40 = {
    Text = "SQUIII—!! (Não pode! Minha linda bolinha ainda está aí dentro!!)"
  },
  AvgDialog_128700_Content_41 = {
    Text = "Você grita irritado, querendo recuperar sua bolinha, mas sua atenção é imediatamente atraída por Mosk."
  },
  AvgDialog_128700_Content_42 = {
    Text = "Shh. Mosk, dar. Conchas."
  },
  AvgDialog_128700_Content_43 = {
    Text = "Mosk te passou secretamente duas conchas que você já estava de olho, e empurrou as peças em direção ao estranho, indicando que ele poderia entregá-las a ela."
  },
  AvgDialog_128700_Content_44 = {
    Text = "Amigo, gosto, Mosk dá!"
  },
  AvgDialog_128700_Content_45 = {
    Text = "Você não sabe como essas coisas podem deixar estranhos tão animados, enquanto enfiam o pequeno nariz feliz naqueles dois belos conchas que antes Moska não queria que você tocasse."
  },
  AvgDialog_128700_Content_46 = {
    Text = "Isso é ótimo! Obrigado... meu amigo."
  },
  AvgDialog_128700_Content_47 = {
    Text = "Aquecida pela bondade aberta e sincera de Mosk, a estranha finalmente relaxa um pouco e sorri para vocês dois."
  },
  AvgDialog_128700_Content_48 = {
    Text = "Aliás, meu nome é Nautila."
  },
  AvgDialog_128700_Content_49 = {
    Text = "Eba!! Nautila, Mosk, amigos, feliz!"
  },
  AvgDialog_128700_Content_5 = {
    Text = "(Espera, membros curtos?)"
  },
  AvgDialog_128700_Content_50 = {
    Text = "Mosk exclama e abre os braços, pronta para dar à nova amiga um enorme abraço de urso."
  },
  AvgDialog_128700_Content_51 = {
    Text = "Ah! (Que droga... o grandão...)"
  },
  AvgDialog_128700_Content_52 = {
    Text = "Amigo, abraço!"
  },
  AvgDialog_128700_Content_53 = {
    Text = "Espera, Mosk... Hum! Dói!"
  },
  AvgDialog_128700_Content_54 = {
    Text = "Os vórtices no ar se juntaram de repente, e no repentino aumento da pressão do vento, ouviu-se um som nítido de clang."
  },
  AvgDialog_128700_Content_55 = {Text = "Ai!!"},
  AvgDialog_128700_Content_56 = {
    Text = "Mosk imediatamente despertou, soltando rapidamente Nautila, mas Nautila já estava com o rosto distorcido de dor, com o braço claramente torcido em um ângulo não natural."
  },
  AvgDialog_128700_Content_57 = {
    Text = "Desculpe, desculpe... eu..."
  },
  AvgDialog_128700_Content_58 = {
    Text = "Vendo Mosk paralisada de pânico, você morde a barra da calça dela e a puxa em direção a algo."
  },
  AvgDialog_128700_Content_59 = {
    Text = "Ah, ah! (<Big: aqui!>)"
  },
  AvgDialog_128700_Content_6 = {
    Text = "<Shake:Ploc ploc.>"
  },
  AvgDialog_128700_Content_60 = {
    Text = "Ah, isso! Nautila — beba!"
  },
  AvgDialog_128700_Content_61 = {
    Text = "Não me toque!"
  },
  AvgDialog_128700_Content_62 = {
    Text = "Náutilo afastou inconscientemente a mão de Mosk, inclinando todo o corpo para trás."
  },
  AvgDialog_128700_Content_63 = {
    Text = "[@Tônico Composto]"
  },
  AvgDialog_128700_Content_64 = {
    Text = "Glub, glub — a garrafa de remédio cai no chão e rola até parar aos pés de Mosk."
  },
  AvgDialog_128700_Content_65 = {
    Text = "A garota que antes estava cheia de si percebeu rapidamente o medo do outro e, lentamente, deixou a mão cair."
  },
  AvgDialog_128700_Content_66 = {Text = "..."},
  AvgDialog_128700_Content_67 = {
    Text = "Desculpe, mas... há algum outro lugar no navio? Talvez eu precise descansar um pouco sozinho."
  },
  AvgDialog_128700_Content_68 = {
    Text = "Mosk ficou em silêncio por um momento, puxou o cobertor mais macio e grande do barco e estendeu-o no chão à distância."
  },
  AvgDialog_128700_Content_69 = {
    Text = "Mosk, imprudente, Força Bruta, ferir."
  },
  AvgDialog_128700_Content_7 = {Text = "Pat pat～"},
  AvgDialog_128700_Content_70 = {
    Text = "Mosk, ruim, desculpe. Lar, aquecido, Nautila."
  },
  AvgDialog_128700_Content_71 = {
    Text = "O corpo de repente ficou suspenso, Mosk, como se estivesse oferecendo um tesouro, cuidadosamente e um pouco timidamente, te entregou a Nautila."
  },
  AvgDialog_128700_Content_72 = {
    Text = "Fora, Mosk. Pequena bola de carvão, quente, Náutilo, aqui."
  },
  AvgDialog_128700_Content_73 = {
    Text = "Ela levantou o queixo, apontou para fora e depois para o cobertor, teimosamente parada entre Nautila e a porta."
  },
  AvgDialog_128700_Content_74 = {
    Text = "...Tudo bem, obrigado."
  },
  AvgDialog_128700_Content_75 = {
    Text = "Ah, ah? (Ei, ei, grandalhão?)"
  },
  AvgDialog_128700_Content_76 = {Text = "..."},
  AvgDialog_128700_Content_77 = {
    Text = "A chuva não para a noite toda. À meia-noite, Nautila caminha até a entrada da cabine e olha para a menina adormecida no convés."
  },
  AvgDialog_128700_Content_78 = {
    Text = "Encolhida num canto do barco, ela se protege do vento e da chuva."
  },
  AvgDialog_128700_Content_79 = {
    Text = "...Dormindo tão profundamente num lugar assim. Você realmente parece um bichinho..."
  },
  AvgDialog_128700_Content_8 = {
    Text = "(Ah, certo! Sou uma lontra marinha!)"
  },
  AvgDialog_128700_Content_80 = {
    Text = "Desculpe, não deveria ser tão agressivo com você, Mosk."
  },
  AvgDialog_128700_Content_81 = {
    Text = "Mosk está coberta com um cobertor extra. Ela estala os lábios enquanto dorme e mergulha em um sono ainda mais profundo e doce."
  },
  AvgDialog_128700_Content_82 = {Text = "Piu!"},
  AvgDialog_128700_Content_83 = {
    Text = "Na manhã seguinte, após a chuva, era o momento perfeito para pescar. \n Você orgulhosamente mordeu o maior peixe do dia e o lançou para Mosk, mas..."
  },
  AvgDialog_128700_Content_84 = {Text = "Pah!"},
  AvgDialog_128700_Content_85 = {Text = "..."},
  AvgDialog_128700_Content_86 = {
    Text = "Mosk recebeu o peixe diretamente no rosto, uma fissura apareceu na sua expressão de apatia que durava desde a manhã. Ela olhou para você, os cantos da boca se curvando para baixo, e então, lágrimas grandes começaram a cair."
  },
  AvgDialog_128700_Content_87 = {
    Text = "Ugh... ahhh..."
  },
  AvgDialog_128700_Content_88 = {
    Text = "Em seguida, ela ignorou tudo e enterrou completamente o rosto em seu estômago, começando a chorar desesperadamente."
  },
  AvgDialog_128700_Content_89 = {Text = "Mosk, mal!"},
  AvgDialog_128700_Content_9 = {
    Text = "Sua cabecinha, que é tão pequena, se lembrou alegremente da situação atual."
  },
  AvgDialog_128700_Content_90 = {
    Text = "Eek!! Squeak! SQUEAK!! (Grandalhona!! SEU RANHO!! Cuidado com o seu ranho!!)"
  },
  AvgDialog_128700_Content_91 = {
    Text = "<Italic:Sniff>— falar, igual, amiga, nunca...buaaa buaaa..."
  },
  AvgDialog_128700_Content_92 = {
    Text = "Mosk chorava descontroladamente, você se esforçou para tentar libertar sua barriga debaixo do rosto dela, mas no final só conseguiu suspirar, permitindo que ela espalhasse aquele muco."
  },
  AvgDialog_128700_Content_93 = {
    Text = "(Queria dizer que finalmente encontrei um amigo que fala como eu, mas acabei estragando tudo, não é? Mas será que o grandão pode ser considerado alguém que fala?)"
  },
  AvgDialog_128700_Content_94 = {
    Text = "(Ei, espere, que cheiro bom!)"
  },
  AvgDialog_128700_Content_95 = {Text = "..."},
  AvgDialog_128700_Content_96 = {
    Text = "Dentro da câmara, Nautila atravessou algumas peixes do mar com um fio de ferro fino, as chamas já haviam torrado a superfície dos peixes, e a gordura pingava no chão, emitindo um aroma exótico capaz de despertar os instintos animais."
  },
  AvgDialog_128700_Content_97 = {
    Text = "Ah, desculpe, vi que vocês pareciam comer peixe cru, então preparei um pouco... Embora não haja temperos, quer Experimentar?"
  },
  AvgDialog_128700_Content_98 = {Text = "Awo!!"},
  AvgDialog_128700_Content_99 = {Text = "Awo!!"},
  AvgDialog_130451_Content_1 = {
    Text = "A noite está escura, você acabou de terminar uma missão externa, e o Corpo Desperto que executou a tarefa com você — o pequeno cavaleiro de outro mundo, Juraquebrado·Ogier, segue quietamente atrás de você."
  },
  AvgDialog_130451_Content_10 = {
    Text = "Espere, por favor não se aproxime!"
  },
  AvgDialog_130451_Content_11 = {
    Text = "Antes que as palavras terminassem, sua visão de repente ficou completamente negra."
  },
  AvgDialog_130451_Content_12 = {
    Text = "As entidades invisíveis que sempre coexistiram com Juraquebrado·Ogier de repente o cercaram, grudando em seus membros, cobrindo seus olhos, enrolando-se firmemente ao seu redor, fazendo você sentir um frio."
  },
  AvgDialog_130451_Content_13 = {Text = "Ogier!"},
  AvgDialog_130451_Content_14 = {
    Text = "Você grita, mas aquela lama se enrola ainda mais apertado, como se tivesse pressa em aprisioná-lo completamente. Você estende a mão para arrancá-la com força, mas ela volta a envolvê-lo teimosamente como trepadeiras."
  },
  AvgDialog_130451_Content_15 = {Text = "Ugh..."},
  AvgDialog_130451_Content_16 = {
    Text = "A voz vaga e fraca do jovem chega em fragmentos, claramente contendo algo com grande esforço."
  },
  AvgDialog_130451_Content_17 = {
    Text = "Ogier? Você consegue me ouvir?"
  },
  AvgDialog_130451_Content_18 = {
    Text = "A força que o envolve treme levemente, depois se aperta novamente, como se estivesse sendo puxada entre duas vontades."
  },
  AvgDialog_130451_Content_19 = {
    Text = "Por causa da minha incompetência, você acabou se machucando mesmo assim. Se eu pudesse encontrar uma forma melhor de protegê-lo…"
  },
  AvgDialog_130451_Content_2 = {
    Text = "Esta missão não teve grande dificuldade. Como Guardião do segredo experiente, você e Juraquebrado·Ogier eliminaram todos os inimigos com facilidade. Porém, por um momento de descuido seu, ainda assim ficou uma pequena cicatriz no pulso."
  },
  AvgDialog_130451_Content_20 = {
    Text = "Você só consegue ouvir algumas palavras confusas, como um murmúrio para si mesmo."
  },
  AvgDialog_130451_Content_21 = {
    Text = "Embora essa lama o envolva com força, não lhe causa nenhuma dor ou sufocamento. Você de repente percebe que provavelmente não é uma intenção de machucá-lo — parece mais querer escondê-lo em um lugar absolutamente seguro, onde nada possa se aproximar."
  },
  AvgDialog_130451_Content_22 = {
    Text = "Não tem problema, estou bem, você não precisa ter medo."
  },
  AvgDialog_130451_Content_23 = {
    Text = "Suas palavras parecem ter surtido efeito. Desta vez, a força daquela lama finalmente foi se afrouxando aos poucos. Você aproveita a oportunidade para arrancá-la."
  },
  AvgDialog_130451_Content_24 = {
    Text = "Você vê Negação do Juramento·Ogier com a cabeça baixa e abatida, o cenho levemente franzido, ainda com um olhar perdido nos olhos, como uma estátua de penitente carregando um peso imenso de culpa."
  },
  AvgDialog_130451_Content_25 = {
    Text = "Você está bem?"
  },
  AvgDialog_130451_Content_26 = {
    Text = "Cheguei a usar um poder tão descontrolado contra você…"
  },
  AvgDialog_130451_Content_27 = {
    Text = "Não, preciso me… recuperar a consciência."
  },
  AvgDialog_130451_Content_28 = {
    Text = "Ele fechou os olhos e murmurou, transformando o pequeno aglomerado de lama negra que girava em sua mão na forma de uma adaga. A luz da lua caía sobre a lâmina fria e brilhante, e ela apontava para o seu próprio outro braço."
  },
  AvgDialog_130451_Content_29 = {
    Text = "No entanto, aquele objeto afiado não chegou a cair. Você avançou a tempo e deteve seu movimento. Só então percebeu, com um atraso, que as forças invisíveis que antes o envolviam com tanta força haviam recuado completamente."
  },
  AvgDialog_130451_Content_3 = {
    Text = "Ao redor está tudo silencioso. Você está um pouco atordoado pelo cansaço, quando de repente se assusta com um som vindo de trás."
  },
  AvgDialog_130451_Content_30 = {
    Text = "Meu senhor...?"
  },
  AvgDialog_130451_Content_31 = {
    Text = "Você se agachou levemente e o abraçou com suavidade, dando tapinhas reconfortantes em suas costas."
  },
  AvgDialog_130451_Content_32 = {
    Text = "Ele não se esquivou como de costume, ficando parado no lugar, mantendo a postura de quem estava sendo abraçado."
  },
  AvgDialog_130451_Content_33 = {
    Text = "Não tenha tanta pressa, relaxe. Veja, Ele foi suprimido com sucesso por você. Mas afinal, o que aconteceu?"
  },
  AvgDialog_130451_Content_34 = {
    Text = "Desculpe, meu senhor. Não sei por quê, mas hoje a presença que habita em mim estava estranhamente agitada, e meus pensamentos ficaram muito confusos."
  },
  AvgDialog_130451_Content_35 = {
    Text = "Mesmo com você ao meu lado, Ele não recuou como de costume — pelo contrário, ficou ainda mais ativo… Por isso queria usar a dor para me acalmar."
  },
  AvgDialog_130451_Content_36 = {
    Text = "Você abraça Ogier e consegue sentir a temperatura anormal em seu corpo, chegando mentalmente a uma conclusão. Não esperava que a influência do Rio Sagrado interferisse diretamente na outra força que habita Ogier."
  },
  AvgDialog_130451_Content_37 = {
    Text = "Isso não é culpa sua, mas sim a influência de… alguma outra coisa."
  },
  AvgDialog_130451_Content_38 = {
    Text = "Além disso, embora essa lama negra tenha me prendido por um momento, não me feriu em nada… Deve ser porque você estava controlando Ele, certo? Muito impressionante."
  },
  AvgDialog_130451_Content_39 = {
    Text = "Após um breve silêncio, você finalmente ouve a voz abafada do jovem."
  },
  AvgDialog_130451_Content_4 = {
    Text = "……Chega! Como eu poderia fazer isso ao meu senhor——"
  },
  AvgDialog_130451_Content_40 = {
    Text = "…Obrigado, por me consolar mais uma vez."
  },
  AvgDialog_130451_Content_41 = {
    Text = "Já está ficando tarde. Por favor, permita-me primeiro cuidar dos seus ferimentos e depois acompanhá-lo de volta ao quarto."
  },
  AvgDialog_130451_Content_5 = {
    Text = "Você sabe que, há muito tempo, Juraquebrado·Ogier tem lutado contra a entidade invisível que habita nele, mas a reação dele hoje parece exagerada de forma estranha."
  },
  AvgDialog_130451_Content_6 = {
    Text = "Então, você se vira e caminha em direção a ele."
  },
  AvgDialog_130451_Content_7 = {
    Text = "Ogier? Você está bem? Ela está tentando te controlar de novo?"
  },
  AvgDialog_130451_Content_8 = {Text = "!"},
  AvgDialog_130451_Content_9 = {
    Text = "Juraquebrado·Ogier ergue bruscamente a cabeça, que estava fixamente olhando para a ponta dos próprios sapatos, e recua um passo, tremendo."
  },
  AvgDialog_130453_Content_1 = {
    Text = "Dadas as habilidades especiais de Saya, todos têm estado apreensivos sobre como ela pode reagir à influência do Rio Sagrado."
  },
  AvgDialog_130453_Content_10 = {
    Text = "Tudo o que eu passei me faz quem eu sou, mas ainda há tanto que eu tenho a aprender."
  },
  AvgDialog_130453_Content_11 = {
    Text = "\"O instinto é a reprodução\", é isso. Ah... entendo agora..."
  },
  AvgDialog_130453_Content_12 = {
    Text = "Enquanto fala, ela te passa uma almofada."
  },
  AvgDialog_130453_Content_13 = {
    Text = "Você solta um longo suspiro de alívio, recostando-se assim como ela."
  },
  AvgDialog_130453_Content_14 = {
    Text = "Entendo... então depois de tudo o que você passou, a razão vence o instinto..."
  },
  AvgDialog_130453_Content_15 = {
    Text = "<Small: Mesmo depois de se tornar um Corpo Desperto, Saya continua sendo verdadeiramente única...>"
  },
  AvgDialog_130453_Content_16 = {
    Text = "Saya—se não for incômodo demais, posso usar sua casa como um refúgio seguro?!"
  },
  AvgDialog_130453_Content_17 = {
    Text = "Seus olhos se enchem de lágrimas de puro alívio enquanto você faz seu pedido desesperado."
  },
  AvgDialog_130453_Content_18 = {
    Text = "Neste momento, o que mais importa é que o pobre Guardião de Misaq finalmente tem um refúgio seguro e confiável."
  },
  AvgDialog_130453_Content_19 = {
    Text = "Hã? Embora não entenda muito bem..."
  },
  AvgDialog_130453_Content_2 = {
    Text = "No entanto, para a surpresa de todos, ela simplesmente fica parada junto à janela em silêncio. Sua pele pálida é quase translúcida, como se estivesse selada em outro mundo."
  },
  AvgDialog_130453_Content_20 = {
    Text = "Saya franzeu o cenho com ar de dificuldade proposital, e só voltou a sorrir depois de ver a expressão de decepção no seu rosto."
  },
  AvgDialog_130453_Content_21 = {
    Text = "Saya franze as sobrancelhas numa demonstração brincalhona de hesitação, sorrindo apenas depois de ver a expressão de decepção no seu rosto."
  },
  AvgDialog_130453_Content_22 = {
    Text = "Claro que pode. Mas... %player%, em troca, você poderia me dizer:"
  },
  AvgDialog_130453_Content_23 = {
    Text = "Quem é a pessoa com quem você mais se importa?"
  },
  AvgDialog_130453_Content_24 = {
    Text = "Como dois amigos próximos que compartilham tudo, vocês caem numa conversa confortável e descontraída."
  },
  AvgDialog_130453_Content_25 = {
    Text = "Uma silhueta surge em sua consciência, você relaxa e fecha os olhos, oferecendo igualmente uma Bênção pelo futuro de Saya — que esta existência possa atravessar o vasto fluxo do tempo."
  },
  AvgDialog_130453_Content_26 = {
    Text = "Uma certa figura surge na sua mente. Você fecha os olhos, relaxado, oferecendo uma bênção silenciosa para o futuro de Saya—contanto que esses sentimentos não acabem realmente com o mundo. Mas quem sabe?"
  },
  AvgDialog_130453_Content_27 = {
    Text = "O poder do Rio Sagrado flui entre vocês como uma maré suave, silenciosa e sem pressa."
  },
  AvgDialog_130453_Content_3 = {
    Text = "Olá, Guardião."
  },
  AvgDialog_130453_Content_4 = {
    Text = "Saya... você está se sentindo bem? Há algo... estranho?"
  },
  AvgDialog_130453_Content_5 = {
    Text = "Como se percebesse sua preocupação, a garota gira levemente sobre os calcanhares—"
  },
  AvgDialog_130453_Content_6 = {
    Text = "sem febre, sem batimento cardíaco acelerado, sem euforia estranha. Nada estranho."
  },
  AvgDialog_130453_Content_7 = {
    Text = "Não se preocupe comigo. Parece que nada de especial aconteceu comigo."
  },
  AvgDialog_130453_Content_8 = {
    Text = "Então o instinto da espécie da Lady Thais é reprodução... mas isso poderia me afetar também?"
  },
  AvgDialog_130453_Content_9 = {
    Text = "Ela se senta mais perto de você, aconchegando-se em uma almofada macia e sorrindo como um pequeno animal inofensivo."
  },
  AvgDialog_130454_Content_1 = {
    Text = "No salão vazio, apenas os passos de você e Murphy ecoam."
  },
  AvgDialog_13049_Content_1 = {
    Text = "Ogier apertou sua arma com força, alerta para cada ruído ao seu redor. Em seus olhos, cada movimento poderia ser uma emboscada das tropas inimigas."
  },
  AvgDialog_13049_Content_10 = {
    Text = "O som da água? Provavelmente é o relógio d'água ali."
  },
  AvgDialog_13049_Content_11 = {
    Text = "Parece que vem de fora. Vou dar uma olhada!"
  },
  AvgDialog_13049_Content_12 = {
    Text = "Não se apresse! Vamos juntos!"
  },
  AvgDialog_13049_Content_13 = {
    Text = "Antes que alguém pudesse detê-lo, Ogier pegou sua arma e correu em direção ao portão do palácio."
  },
  AvgDialog_13049_Content_14 = {
    Text = "Isto é—?!"
  },
  AvgDialog_13049_Content_15 = {
    Text = "Inimigo ataca!"
  },
  AvgDialog_13049_Content_2 = {
    Text = "Você não consegue encontrar palavras para confortá-lo. As palavras do dossiê do Despertador brilham diante de você—"
  },
  AvgDialog_13049_Content_3 = {
    Text = "Declaração do Despertador: Ogier Danske, @2 Cavaleiro do Ducado\nCaiu na Noite de Defesa do Lar..."
  },
  AvgDialog_13049_Content_4 = {
    Text = "Senhor Camarlengo, por favor, evacue para os arredores por segurança. Podemos lidar com as coisas aqui..."
  },
  AvgDialog_13049_Content_5 = {
    Text = "Vocês dois, cavaleiros, nem conseguem diferenciar a acônito das orquídeas. E se vocês acidentalmente derem veneno à princesa?"
  },
  AvgDialog_13049_Content_6 = {
    Text = "Uma recusa direta aliviou a tensão. Ogier corou, o cavaleiro da guarda abafou uma risada, e até mesmo uma risadinha abafada veio de trás da porta."
  },
  AvgDialog_13049_Content_7 = {
    Text = "Você não pode sair — preso no mistério centrado em Ogier, sair precipitadamente pode trazer consequências desconhecidas."
  },
  AvgDialog_13049_Content_8 = {
    Text = "Tick-tock—"
  },
  AvgDialog_13049_Content_9 = {
    Text = "Você ouviu algum som?"
  },
  AvgDialog_13050_Content_1 = {
    Text = "Finalmente, a Batalha acabou. Você e Ogier permaneceram ao pé das escadas para limpar o salão do palácio, enquanto os cavaleiros guardas já tinham retornado à frente do quarto da princesa."
  },
  AvgDialog_13050_Content_10 = {
    Text = "Farfalhando..."
  },
  AvgDialog_13050_Content_11 = {
    Text = "No entanto... pode a praga se transformar em monstros que pessoas comuns não conseguem ver?"
  },
  AvgDialog_13050_Content_12 = {
    Text = "Isto é verdadeiramente absurdo. Mesmo que os poetas da corte cantassem sobre isso, poucos acreditariam."
  },
  AvgDialog_13050_Content_13 = {
    Text = "A princípio, meu pai e eu achamos que era uma maldição dos magos do país vizinho, mas... logo eles também relataram a praga se alastrando."
  },
  AvgDialog_13050_Content_14 = {
    Text = "Até eu... *tosse, tosse*..."
  },
  AvgDialog_13050_Content_15 = {
    Text = "Enquanto falava, uma tosse angustiante ecoou atrás da porta."
  },
  AvgDialog_13050_Content_16 = {
    Text = "Princesa, por favor, não fale por agora. Retorne para a cama primeiro."
  },
  AvgDialog_13050_Content_17 = {
    Text = "Farfalhando..."
  },
  AvgDialog_13050_Content_18 = {
    Text = "Atendente! Atendente, volte e ajude! A princesa—"
  },
  AvgDialog_13050_Content_19 = {Text = "Ugh!"},
  AvgDialog_13050_Content_2 = {
    Text = "É a nossa primeira vez lutando contra inimigos invisíveis. Quando tudo isso acabar, que tal encontrarmos um bardo para registrar nossa história e transformá-la em uma canção?"
  },
  AvgDialog_13050_Content_20 = {
    Text = "O som agudo dos ossos se quebrando ecoou enquanto algo rasgava violentamente o tecido muscular firmemente unido, fazendo um líquido vermelho brilhante espirrar."
  },
  AvgDialog_13050_Content_21 = {
    Text = "Q...o quê...?"
  },
  AvgDialog_13050_Content_22 = {
    Text = "Senhor Fernando!!!"
  },
  AvgDialog_13050_Content_23 = {
    Text = "O Cavaleiro Guardião tossiu, sangue misturado com pedaços de carne jorrando de sua garganta. Seus olhos se arregalaram em descrença, cheios de confusão e medo."
  },
  AvgDialog_13050_Content_3 = {
    Text = "Já decidi o nome: \"Olho de Dansk, Espada de Fernando\"!"
  },
  AvgDialog_13050_Content_4 = {
    Text = "Ogier, chamado pelo nome, olhou para o cavaleiro guarda. Suas mãos estavam cobertas com muito D-Slime. Ele hesitou, sem saber como limpá-las, sentindo-se extremamente envergonhado."
  },
  AvgDialog_13050_Content_5 = {
    Text = "Você vai escrever meu nome na canção também? O que Ogier fez para merecer isso"
  },
  AvgDialog_13050_Content_6 = {
    Text = "Heh heh... O camareiro e eu não podemos pelo menos ter nossos nomes nisso?"
  },
  AvgDialog_13050_Content_7 = {
    Text = "Claro! Absolutamente! Seu nome estará na primeira linha desta canção!"
  },
  AvgDialog_13050_Content_8 = {
    Text = "Farfalhando..."
  },
  AvgDialog_13050_Content_9 = {
    Text = "@1 Suíte da Princesa... O que você acha? Eu tenho talento para poesia?"
  },
  AvgDialog_13051_Content_1 = {
    Text = "O que... o que está acontecendo?"
  },
  AvgDialog_13051_Content_10 = {
    Text = "Sir Fernando... Lembro que ele era o filho único em sua família."
  },
  AvgDialog_13051_Content_11 = {
    Text = "Se eu tivesse sido mais vigilante..."
  },
  AvgDialog_13051_Content_12 = {
    Text = "Não se culpe pela morte dele. Aqueles monstros @1 são evasivos. Fizemos o nosso melhor."
  },
  AvgDialog_13051_Content_13 = {
    Text = "Ogier balançou a cabeça; seu pálido conforto claramente falhou em consolá-lo.\nJusto então, um leve toque veio de trás."
  },
  AvgDialog_13051_Content_14 = {
    Text = "Camerista, leve Ogier com você."
  },
  AvgDialog_13051_Content_15 = {Text = "Por que!"},
  AvgDialog_13051_Content_16 = {
    Text = "Você... você não precisa mais de mim? Eu sei que falhei em salvar Lord Fernando, mas..."
  },
  AvgDialog_13051_Content_17 = {
    Text = "A praga traz doenças, guerra e dor... Ficar aqui só faz de você a próxima refeição."
  },
  AvgDialog_13051_Content_18 = {
    Text = "A voz dela tremia, mas ela falou em um tom brincalhão. Confrontada com a iminente ameaça da morte, ela não mostrou nenhum traço de medo."
  },
  AvgDialog_13051_Content_19 = {
    Text = "Suponho que... Lorde Fernando não gostaria de se reencontrar com você tão cedo, gostaria?"
  },
  AvgDialog_13051_Content_2 = {
    Text = "Um som distante de passos veio de dentro, seguido pelo deslizamento do fecho da porta—"
  },
  AvgDialog_13051_Content_20 = {
    Text = "Mas... isso... é minha responsabilidade..."
  },
  AvgDialog_13051_Content_21 = {
    Text = "Agora... sou apenas eu... Eu levarei adiante a vontade do Senhor Fernando... Eu herdarei..."
  },
  AvgDialog_13051_Content_22 = {
    Text = "Um longo suspiro resignado veio de trás da porta. Depois de um tempo, a princesa falou com você."
  },
  AvgDialog_13051_Content_23 = {
    Text = "Steward, prometa-me... quando minha voz estiver completamente ausente, você deve levar Ogier embora, mesmo que tenha que nocauteá-lo, certo?"
  },
  AvgDialog_13051_Content_24 = {
    Text = "... Como você desejar."
  },
  AvgDialog_13051_Content_25 = {
    Text = "Ogier apertou sua arma com força, suas mãos ficando brancas de esforço. Sentia como se a lança em seus braços fosse sua família com um destino incerto, uma princesa moribunda, ou o Fernando que partiu para sempre."
  },
  AvgDialog_13051_Content_26 = {
    Text = "Ele fitou fixamente o portão do palácio, sua mente vagando longe. Nem mesmo o forte estrondo do portão sendo batido conseguiu trazê-lo de volta à realidade."
  },
  AvgDialog_13051_Content_27 = {
    Text = "Ogier? Ogier?"
  },
  AvgDialog_13051_Content_28 = {
    Text = "Alguém está vindo."
  },
  AvgDialog_13051_Content_29 = {
    Text = "Alguém... está vindo? Os cavaleiros retornaram!?"
  },
  AvgDialog_13051_Content_3 = {Text = "Não saia!"},
  AvgDialog_13051_Content_30 = {
    Text = "O portão foi aberto com força, mas a bandeira tremulando ao vento não tinha a cor que você esperava."
  },
  AvgDialog_13051_Content_4 = {
    Text = "Princesa... por favor, não saia..."
  },
  AvgDialog_13051_Content_5 = {
    Text = "Ogier se esforçou para empurrar o corpo do Cavaleiro Fernando para longe da porta, e então puxou a cortina para cobrir o sangue acumulado pela fresta."
  },
  AvgDialog_13051_Content_6 = {
    Text = "Os espinhos do mutante perfuraram a armadura do peito e a carne, deixando o peito em um bagunça ensanguentada, como se tivesse explodido. O Cavaleiro Fernando já havia morrido em agonia."
  },
  AvgDialog_13051_Content_7 = {
    Text = "... Tudo bem."
  },
  AvgDialog_13051_Content_8 = {
    Text = "Por favor, faça o seu melhor para dar a ele um enterro adequado."
  },
  AvgDialog_13051_Content_9 = {
    Text = "Você e Ogier trocam um olhar, silenciosamente enrolam o corpo do cavaleiro em um tapete e se sentam no chão em frente à porta do quarto. Dor e ansiedade preenchiam o ar."
  },
  AvgDialog_13052_Content_1 = {
    Text = "O que está acontecendo? Onde estão os inimigos?"
  },
  AvgDialog_13052_Content_10 = {
    Text = "Excelência, você consegue ver também?"
  },
  AvgDialog_13052_Content_11 = {
    Text = "Você lhe dá um olhar tranquilizador e continua negociando com o cavaleiro."
  },
  AvgDialog_13052_Content_12 = {
    Text = "Ogier nunca foi do tipo que age irracionalmente, e você sabe disso melhor do que ninguém por ter treinado com ele, não sabe?"
  },
  AvgDialog_13052_Content_13 = {
    Text = "Mesmo que você diga isso, eu realmente não fiz nada..."
  },
  AvgDialog_13052_Content_14 = {
    Text = "...Espere um momento, Lorde Fernando."
  },
  AvgDialog_13052_Content_15 = {
    Text = "Um batida veio da direção da porta do quarto, trazendo todos de volta à frente com uma fraca voz feminina."
  },
  AvgDialog_13052_Content_16 = {
    Text = "Eles estavam certos... Era o inimigo invisível que espalhou a praga."
  },
  AvgDialog_13052_Content_17 = {
    Text = "Desde que a princesa disse isso..."
  },
  AvgDialog_13052_Content_18 = {
    Text = "O Cavaleiro Guardião cerrou os dentes, levantou sua arma e ficou ao seu lado."
  },
  AvgDialog_13052_Content_19 = {
    Text = "Diga-me a localização do inimigo, e farei o meu melhor para ajudar na batalha!"
  },
  AvgDialog_13052_Content_2 = {
    Text = "O cavaleiro da guarda também correu escada abaixo para o seu lado, completamente perplexo."
  },
  AvgDialog_13052_Content_3 = {
    Text = "Agora não é hora para brincar. Mantenha-se atento."
  },
  AvgDialog_13052_Content_4 = {
    Text = "Não estou brincando! Você não consegue ver?!"
  },
  AvgDialog_13052_Content_5 = {
    Text = "Ogier se defende ansiosamente, mas o cavaleiro da guarda permanece cético."
  },
  AvgDialog_13052_Content_6 = {
    Text = "Não é culpa dele; afinal, os inimigos que você e Ogier derrotaram eram totalmente aberrações derivadas da Dissolução."
  },
  AvgDialog_13052_Content_7 = {
    Text = "Para observar visualmente o Fenômeno D é extremamente raro.\nOgier é um dos infelizes poucos que também são considerados sortudos."
  },
  AvgDialog_13052_Content_8 = {
    Text = "Por favor, confie em nós."
  },
  AvgDialog_13052_Content_9 = {
    Text = "Por favor, confie em nós e acredite na integridade de Ogier."
  },
  AvgDialog_13053_Content_1 = {
    Text = "Cortina final"
  },
  AvgDialog_13053_Content_10 = {Text = "..."},
  AvgDialog_13053_Content_11 = {
    Text = "Vamos fazer com que Ogier guarde o palácio conosco.\nEle é, afinal, um legítimo e grandioso Cavaleiro Guardião nomeado pelo duque, não é?"
  },
  AvgDialog_13053_Content_12 = {
    Text = "O Cavaleiro Guarda não conseguiu encontrar outra razão para recusar. Após acenar em concordância, vocês dois voltaram ao palácio"
  },
  AvgDialog_13053_Content_13 = {
    Text = "O palácio está vazio; até a criada barulhenta se foi.\nAlém de vocês três, apenas a princesa permanece."
  },
  AvgDialog_13053_Content_14 = {
    Text = "Você bateu na porta do quarto luxuoso, o som ecoando pelo corredor silencioso, de forma estranha abafada."
  },
  AvgDialog_13053_Content_15 = {
    Text = "Princesa? Você está bem?"
  },
  AvgDialog_13053_Content_16 = {
    Text = "Não houve resposta de dentro. Depois de esperar um momento, você bateu na porta novamente."
  },
  AvgDialog_13053_Content_17 = {
    Text = "Princesa, o cavaleiro da guarda, Ogier, e eu estamos todos aqui."
  },
  AvgDialog_13053_Content_18 = {
    Text = "Através da pesada porta de madeira veio o som de tecido farfalhando, enquanto alguém lutava para se sentar na cama."
  },
  AvgDialog_13053_Content_19 = {Text = "...Tolos."},
  AvgDialog_13053_Content_2 = {Text = "\"Sonho\""},
  AvgDialog_13053_Content_20 = {
    Text = "Você... pode ir e se juntar aos outros. Não precisa ficar com um cadáver."
  },
  AvgDialog_13053_Content_21 = {
    Text = "A respiração da garota é fraca, sua voz tão suave quanto a de um mosquito. Parece que simplesmente responder a você drenou toda a sua força."
  },
  AvgDialog_13053_Content_22 = {
    Text = "A praga se espalhou caoticamente no ducado, poupando ninguém, nem mesmo a nobreza. A princesa adoeceu antes que a guerra começasse, e até hoje, ela não tem forças para deixar sua cama."
  },
  AvgDialog_13053_Content_23 = {
    Text = "O médico real afirmou francamente que a princesa não pode mais suportar a pressão de ser movida do palácio. Mesmo choques leves poderiam custar sua vida."
  },
  AvgDialog_13053_Content_24 = {
    Text = "Princesa..."
  },
  AvgDialog_13053_Content_25 = {
    Text = "Não importa o que você diga, eu não vou embora. Por favor, permita-me proteger você...\nfazendo meu dever como cavaleiro."
  },
  AvgDialog_13053_Content_26 = {Text = "..."},
  AvgDialog_13053_Content_27 = {
    Text = "...Não chegue muito perto do meu quarto. A peste é irreversível, pelo menos... não se deixem infectar."
  },
  AvgDialog_13053_Content_28 = {
    Text = "Quando o relógio de água se esgota, venha falar comigo, ok?\nQuando eu não responder mais... você deve sair."
  },
  AvgDialog_13053_Content_3 = {
    Text = "Conspirações agitam-se nas sombras, acendendo o pavio colocado pela peste. A guerra irrompe da noite para o dia."
  },
  AvgDialog_13053_Content_4 = {
    Text = "A incurável <Yellow:praga> já se espalhou por todo o ducado, e os guardas da cidade, atormentados pela doença, não conseguem resistir ao avanço dos invasores."
  },
  AvgDialog_13053_Content_5 = {
    Text = "Até mesmo os cavaleiros reais foram além do fosso por ordem do Duque Grande, juntando-se à última linha de defesa da capital."
  },
  AvgDialog_13053_Content_6 = {
    Text = "Ogier, por que você ainda está aqui?"
  },
  AvgDialog_13053_Content_7 = {
    Text = "Eu... eu quero me juntar a você na missão de escolta."
  },
  AvgDialog_13053_Content_8 = {
    Text = "Você é muito jovem; a guerra... ainda não te envolve.\nVolte e encontre um lugar seguro com sua família."
  },
  AvgDialog_13053_Content_9 = {
    Text = "A casa de Ogier, Dansk Estate... Deve estar do lado de fora da linha de defesa, certo?"
  },
  AvgDialog_13054_Content_1 = {
    Text = "Sonho ou ideal"
  },
  AvgDialog_13054_Content_10 = {
    Text = "Atendente, você poderia ir em meu nome?"
  },
  AvgDialog_13054_Content_100 = {
    Text = "As coisas que discutimos... Você realmente não contará à princesa, irá?"
  },
  AvgDialog_13054_Content_101 = {
    Text = "O que? Eu não tenho nenhum crédito com você?"
  },
  AvgDialog_13054_Content_102 = {
    Text = "Como isso pode ser! Eu nunca...!"
  },
  AvgDialog_13054_Content_103 = {
    Text = "Tudo bem, vou usar o que aconteceu hoje para te ameaçar."
  },
  AvgDialog_13054_Content_104 = {Text = "Ameaça?"},
  AvgDialog_13054_Content_105 = {
    Text = "Você se ajoelha diante de Ogier, faz contato visual com o filhote ansioso e estende a mão para ele."
  },
  AvgDialog_13054_Content_106 = {
    Text = "A conversa de hoje permanecerá enterrada em nossos corações para sempre. Mas em troca de eu manter este segredo, você deve me prometer uma coisa."
  },
  AvgDialog_13054_Content_107 = {
    Text = "Nesta era, não há o costume de promessas de dedo mindinho, mas Ogier ainda puxou inocentemente seu dedo mindinho estendido."
  },
  AvgDialog_13054_Content_108 = {
    Text = "Enquanto estiver dentro da minha capacidade..."
  },
  AvgDialog_13054_Content_109 = {
    Text = "Muito bem, eu reservarei o direito de fazer um desejo. Um dia no futuro, posso vir reivindicá-lo. Não se esqueça, \"Cavaleiro.\""
  },
  AvgDialog_13054_Content_11 = {
    Text = "Se for o último, despertar o dono do sonho deve nos permitir escapar daqui, certo?"
  },
  AvgDialog_13054_Content_12 = {
    Text = "Ei! Senhor Atendente? Acorde!"
  },
  AvgDialog_13054_Content_13 = {
    Text = "Seus pensamentos vagueavam longe, seguindo as pistas. Assim que o plano \"Despertar o Mestre dos Sonhos\" começou a tomar forma, suas unhas cravaram-se com força em seu braço, e a dor o trouxe de volta à realidade."
  },
  AvgDialog_13054_Content_14 = {
    Text = "Chiado—Está doendo!"
  },
  AvgDialog_13054_Content_15 = {
    Text = "Então você pode sentir dor! Estamos te chamando há tempos e você não respondeu, como um cadáver. Está com algum problema nos ouvidos?"
  },
  AvgDialog_13054_Content_16 = {
    Text = "Você tem estado distraído ultimamente. Está muito cansado? Que tal tirar uma folga na propriedade da sua família? Já faz muito tempo desde sua última férias."
  },
  AvgDialog_13054_Content_17 = {
    Text = "Não—Sinto muito, eu só tenho algo na cabeça..."
  },
  AvgDialog_13054_Content_18 = {
    Text = "A chave para escapar do \"Sonho\" está com Ogier. Embora você esteja curioso sobre como é o mundo além do centro do sonho, este não é o momento para vagar muito longe."
  },
  AvgDialog_13054_Content_19 = {
    Text = "Algo em mente? O que é? É sobre alguém que você gosta e isso está te trazendo problemas?"
  },
  AvgDialog_13054_Content_2 = {
    Text = "\"Sonho\"\nPalácio da Princesa"
  },
  AvgDialog_13054_Content_20 = {
    Text = "Está preocupado que a outra pessoa não goste de você? Princesa, por que não faz uma pequena adivinhação para o nosso querido acompanhante? Ou melhor ainda, dê a {Male=him,Female=her} uma poção do amor—"
  },
  AvgDialog_13054_Content_21 = {
    Text = "Vamos, como você pode usar mágica e poções para manter um relacionamento?"
  },
  AvgDialog_13054_Content_22 = {
    Text = "A princesa sorriu e mudou suavemente o tópico trazido pela criada, acenando para você."
  },
  AvgDialog_13054_Content_23 = {
    Text = "Ogier está atualmente treinando com os cavaleiros. Por favor, verifique como ele está e certifique-se de que não se machuque."
  },
  AvgDialog_13054_Content_24 = {
    Text = "Como desejar!"
  },
  AvgDialog_13054_Content_25 = {
    Text = "Quando a princesa trouxe um travesseiro enquanto você estava sonolento, isso lhe deu uma razão legítima para se aproximar de Ogier."
  },
  AvgDialog_13054_Content_26 = {
    Text = "No entanto, se você realmente precisar de poções, ainda pode vir até mim por elas."
  },
  AvgDialog_13054_Content_27 = {
    Text = [[
"Sonho"
Campo de Treinamento dos Cavaleiros]]
  },
  AvgDialog_13054_Content_28 = {
    Text = "Guiado por outros servos, você abre caminho através do castelo e dos jardins labirínticos até os campos de treinamento."
  },
  AvgDialog_13054_Content_29 = {
    Text = "O som nítido das armas e os gritos contínuos dos outros mostram claramente que alguém está praticando sob o sol escaldante."
  },
  AvgDialog_13054_Content_3 = {
    Text = "Após uma terceira tentativa de acordar que resultou apenas em uma mudança inexplicável de cena, você finalmente aceitou que estava preso nas memórias de Ogier."
  },
  AvgDialog_13054_Content_30 = {
    Text = "—Mal sabia você que um dos parceiros de sparring era Ogier."
  },
  AvgDialog_13054_Content_32 = {Text = "Ngh...!"},
  AvgDialog_13054_Content_33 = {
    Text = "Diante de uma disparidade absoluta de poder, persistência e fé são fúteis. O cavaleiro adulto nem mesmo usou toda a sua força, e ainda assim a ressonância metálica já enfraqueceu a pega do Ogier."
  },
  AvgDialog_13054_Content_34 = {
    Text = "A lança foi derrubada, e o jovem, ensopado de suor, ajoelhou-se no chão áspero de cascalho, ofegando por ar."
  },
  AvgDialog_13054_Content_35 = {
    Text = "Garoto, volte por enquanto. Se você continuar praticando assim, acabará quebrando a mão."
  },
  AvgDialog_13054_Content_36 = {
    Text = "Isso mesmo, você ainda é muito jovem.\nVolte para treinar em alguns anos. Você nem consegue levantar uma arma agora."
  },
  AvgDialog_13054_Content_37 = {Text = "Não..."},
  AvgDialog_13054_Content_38 = {
    Text = "Ogier tremia, se abaixou para pegar a lança caída e, com grande esforço, ajustou sua postura, apontando a ponta da lança para o cavaleiro de treinamento."
  },
  AvgDialog_13054_Content_39 = {
    Text = "Posso... aguentar!"
  },
  AvgDialog_13054_Content_4 = {
    Text = "Você está em um canto do quarto da Princesa, fingindo ouvir e obedientemente desempenhando o papel de um atendente."
  },
  AvgDialog_13054_Content_40 = {
    Text = "Você, criança teimosa..."
  },
  AvgDialog_13054_Content_41 = {
    Text = "O rosto do garoto ficou vermelho de exaustão e privação de oxigênio. A pessoa que pretendia fazer Ogier desistir durante o treinamento finalmente falou, diante de tal força de vontade."
  },
  AvgDialog_13054_Content_42 = {
    Text = "Nada mal. Os forasteiros estão de olho em nosso ducado com avareza. Precisamos de mais jovens firmes como o Jovem Mestre Danske."
  },
  AvgDialog_13054_Content_43 = {
    Text = "Devo ficar sério?"
  },
  AvgDialog_13054_Content_44 = {
    Text = "Não seja tão imprudente! Se essa criança desmaiar durante o treinamento, como você explicará isso ao Grande Duque e à Princesa?"
  },
  AvgDialog_13054_Content_45 = {
    Text = "Iniciar com treinamento físico básico. Fique de olho nele e assegure-se de que ele não se machuque com as armas."
  },
  AvgDialog_13054_Content_46 = {
    Text = "As palavras do líder incenderam Ogier. Os olhos do jovem brilhavam instantaneamente, transbordando de empolgação."
  },
  AvgDialog_13054_Content_47 = {
    Text = "Você concordou em me deixar me juntar aos Cavaleiros?!"
  },
  AvgDialog_13054_Content_48 = {
    Text = "Mesmo sem a piada do Grão-Duque, com esse nível de força de vontade, você está qualificado para ser um aprendiz de cavaleiro."
  },
  AvgDialog_13054_Content_49 = {
    Text = "Vendo as abrasões e manchas de sangue do garoto, o capitão hesitou, sentindo-se um tanto relutante."
  },
  AvgDialog_13054_Content_5 = {
    Text = "Princesa, princesa! Eu ouvi que o jovem mestre de Dansk informou novamente aos cavaleiros. É o terceiro dia!"
  },
  AvgDialog_13054_Content_50 = {
    Text = "Vá embora por hoje. A partir de amanhã, eu lhe darei um plano de treino personalizado—E vocês! parem de assistir e façam duas rodadas extras de exercícios com peso!"
  },
  AvgDialog_13054_Content_51 = {
    Text = "Poupe-nos, Capitão—"
  },
  AvgDialog_13054_Content_52 = {
    Text = "Antes que o líder terminasse de falar, a rara atmosfera leve provocou pequenos atos de rebelião, com jovens cavaleiros liberando seu estresse dessa maneira."
  },
  AvgDialog_13054_Content_53 = {
    Text = "Três rodadas!"
  },
  AvgDialog_13054_Content_54 = {
    Text = "Em meio aos lamentos incessantes, Ogier finalmente relaxou e colapsou no chão com um baque."
  },
  AvgDialog_13054_Content_55 = {
    Text = "Ótimo... Finalmente..."
  },
  AvgDialog_13054_Content_56 = {
    Text = "Ogier, podemos conversar?"
  },
  AvgDialog_13054_Content_57 = {
    Text = "Você é... Senhor Camareiro! Ter você me ver em um estado tão embaraçoso, eu..."
  },
  AvgDialog_13054_Content_58 = {
    Text = "Ogier instantaneamente se endireitou, seu joelho raspado esfregando-se contra a areia, a dor torcendo sua expressão tensa."
  },
  AvgDialog_13054_Content_59 = {
    Text = "Você acenou para ele e tirou a poção de cura que a princesa havia colocado em seu bolso em algum momento."
  },
  AvgDialog_13054_Content_6 = {
    Text = "Ele realmente levou a sério as palavras de seu pai... Como pode alguém tão jovem suportar o treinamento dos Cavaleiros?"
  },
  AvgDialog_13054_Content_60 = {
    Text = "Huh... Não dói? Não é um remédio para cura?"
  },
  AvgDialog_13054_Content_61 = {
    Text = "Este é um remédio preparado pessoalmente pela princesa, provavelmente com um tratamento especial."
  },
  AvgDialog_13054_Content_62 = {
    Text = "\"A princesa que você serve é uma garota misteriosa. Ela raramente sai de seus aposentos, mas possui uma compreensão e talento únicos para a medicina. Na sua era, ela seria uma farmacêutica renomada.\""
  },
  AvgDialog_13054_Content_63 = {
    Text = "É uma pena que seus talentos tenham sido mal interpretados naquelas séculos perdidos. Você ouviu outros atendentes chamá-la secretamente de \"bruxa\" mais de uma vez."
  },
  AvgDialog_13054_Content_64 = {
    Text = "Póção da princesa?! É muito preciosa para ser usada em mim—Aí!"
  },
  AvgDialog_13054_Content_65 = {
    Text = "Não se mova, ou você desperdiçará a misericórdia da princesa.\nSente-se primeiro e deixe-me terminar de tratar o ferimento."
  },
  AvgDialog_13054_Content_66 = {
    Text = "Temendo desperdiçar medicina preciosa, Ogier finalmente se sentou quieto.\nOs outros cavaleiros gradualmente deixaram a área, aproveitando esta rara oportunidade."
  },
  AvgDialog_13054_Content_67 = {
    Text = "Ogier, você consegue sentir que está sonhando?"
  },
  AvgDialog_13054_Content_68 = {
    Text = "De fato, é como um sonho..."
  },
  AvgDialog_13054_Content_69 = {
    Text = "O jovem adaptou suas palavras à situação atual. Ele fechou os olhos e suspirou, sua voz preenchida de satisfação e saudade."
  },
  AvgDialog_13054_Content_7 = {
    Text = "Não... não, espere... talvez haja outra possibilidade."
  },
  AvgDialog_13054_Content_70 = {
    Text = "Invocado, escolhido e reconhecido pelos cavaleiros... Realmente parece um sonho."
  },
  AvgDialog_13054_Content_71 = {
    Text = "<LightGray:(Devo dizer a ele diretamente que isso é um sonho? Mas eu ainda não descobri a essência aqui. É uma memória ou um sonho...?)>"
  },
  AvgDialog_13054_Content_72 = {
    Text = "Sua hesitação chamou a atenção de Ogier. Ele de repente ficou um pouco inquieto, esfregando nervosamente a barra de suas roupas."
  },
  AvgDialog_13054_Content_73 = {
    Text = "Senhor Chamberlain, a... a princesa está insatisfeita comigo?"
  },
  AvgDialog_13054_Content_74 = {Text = "..."},
  AvgDialog_13054_Content_75 = {
    Text = "Ogier é o filho de um nobre que poderia ter vivido uma vida de luxo. Por que insistir em se tornar um cavaleiro?"
  },
  AvgDialog_13054_Content_76 = {
    Text = "Porque... porque..."
  },
  AvgDialog_13054_Content_77 = {
    Text = "A voz de Ogier ficou mais baixa e sua cabeça se inclinou ainda mais em constrangimento. A resposta à pergunta claramente o fez sentir vergonha demais para falar."
  },
  AvgDialog_13054_Content_78 = {
    Text = "Eu juro, nossa conversa permanecerá desconhecida para qualquer terceiro."
  },
  AvgDialog_13054_Content_79 = {
    Text = "Porque... meu pai também está doente, assim como a Tia Merlyn na cozinha e o Irmão Pedro, o jardineiro..."
  },
  AvgDialog_13054_Content_8 = {
    Text = "Com base na descrição da criada, Ogier está passando por treinamento com a ordem dos cavaleiros. Como Ogier não participou desta conversa, a hipótese sobre \"as memórias de Ogier\" não pode ser estabelecida."
  },
  AvgDialog_13054_Content_80 = {
    Text = "Há muitos, muitos outros que contraíram a mesma doença."
  },
  AvgDialog_13054_Content_81 = {
    Text = "Meu pai não pode mais deixar sua cama, e eu ainda não cresci... Como seu único filho, eu..."
  },
  AvgDialog_13054_Content_82 = {
    Text = "Se o Pai falecer, todos na mansão serão dispensados.\nTodos ainda estão doentes... sem lugar para ir."
  },
  AvgDialog_13054_Content_83 = {
    Text = "Eu devo... Eu devo assumir a responsabilidade por todos... Apenas me tornando um cavaleiro e ganhando a proteção do Duque..."
  },
  AvgDialog_13054_Content_84 = {
    Text = "Ao dizer isso, o rosto de Ogier ficou pálido. Ele olhou para você ansiosamente, como se temesse que você o acusasse de \"motivos impuros\" ou o punisse em nome da princesa."
  },
  AvgDialog_13054_Content_85 = {
    Text = "Inocência semelhante, vontade idêntica e firme.\nSem dúvida, ele é o Ogier que você conhece."
  },
  AvgDialog_13054_Content_86 = {
    Text = "Desculpe, Sua Excelência... Se, se você deseja que a princesa me substitua... Eu-Eu não tenho objeções..."
  },
  AvgDialog_13054_Content_87 = {
    Text = "Na noite em que você foi escolhido pelo Grande Duque, você jurou pela honra da sua família na frente de todos os convidados, não foi?"
  },
  AvgDialog_13054_Content_88 = {
    Text = "Jure cumprir seus deveres de cavaleiro com sua vida... Você foi sincero ao recitar o juramento junto com os outros?"
  },
  AvgDialog_13054_Content_89 = {
    Text = "<Big:Claro! Eu não estou brincando!>"
  },
  AvgDialog_13054_Content_9 = {
    Text = "Isto não é apenas uma \"memória\". Talvez você tenha entrado em um pedaço da verdadeira história, ou talvez seja um sonho completado pelo seu subconsciente?"
  },
  AvgDialog_13054_Content_90 = {
    Text = "\"Serei sempre leal, sempre dedicado\"... Meu pai esperaria o mesmo de mim."
  },
  AvgDialog_13054_Content_91 = {
    Text = "Tudo bem, não vou contar à princesa sobre isso.\nNão fique tão preocupado, você está prestes a chorar."
  },
  AvgDialog_13054_Content_92 = {
    Text = "Há... realmente?! Com licença!"
  },
  AvgDialog_13054_Content_93 = {
    Text = "Ugh... Ugh?! Meus olhos... eles doem..."
  },
  AvgDialog_13054_Content_94 = {
    Text = "Ogier esfregou os olhos de forma desajeitada, mas seu lenço já tinha ficado empoeirado durante o treino, aumentando sua vergonha."
  },
  AvgDialog_13054_Content_95 = {
    Text = "Não consigo acreditar que o Camareiro me viu em um estado tão embaraçoso..."
  },
  AvgDialog_13054_Content_96 = {
    Text = "Não é nada, já vi você em um estado pior.\nVamos voltar ao palácio e te deixar em forma. Você não pode voltar pra casa assim."
  },
  AvgDialog_13054_Content_97 = {Text = "..."},
  AvgDialog_13054_Content_98 = {
    Text = "Sua Excelência, posso pedir um favor a você?"
  },
  AvgDialog_13054_Content_99 = {
    Text = "Eu gostaria de ouvir mais detalhes."
  },
  AvgDialog_13055_Content_1 = {
    Text = "Fios do passado"
  },
  AvgDialog_13055_Content_10 = {Text = "Reconectar"},
  AvgDialog_13055_Content_11 = {
    Text = "Vendo Ogier se aproximar da perda de controle, você decide não esperar mais e agarra firmemente suas mãos, agora cobertas de lama negra."
  },
  AvgDialog_13055_Content_12 = {
    Text = "A Chave Prata pisca enquanto você guia suas tendrils mentais através da tempestade de Gnosis, por camadas de escuridão, e se reconecta com Ogier."
  },
  AvgDialog_13055_Content_13 = {
    Text = "Acompanhado por uma dor aguda como um choque elétrico, cenas piscaram diante de seus olhos e depois desapareceram instantaneamente."
  },
  AvgDialog_13055_Content_14 = {
    Text = "Os sinais de perda de controle recuaram como a maré, e o estado de Ogier se estabilizou. Seu rosto juvenil mostrava um indício de fadiga."
  },
  AvgDialog_13055_Content_15 = {
    Text = "Meu senhor, desta vez... quanto tempo eu durei?"
  },
  AvgDialog_13055_Content_16 = {
    Text = "O cronômetro completou apenas meia rotação; após desconectar o link, Ogier não conseguiu durar mais do que na sessão de treinamento anterior."
  },
  AvgDialog_13055_Content_17 = {
    Text = "Hmm... 30 segundos, mais 200 milissegundos."
  },
  AvgDialog_13055_Content_18 = {
    Text = "Como... como isso aconteceu...!"
  },
  AvgDialog_13055_Content_19 = {
    Text = "Seu tom estava inquieto, afinal, foi ideia dele propor o <Yellow:Treinamento de Quebra de Cadeia>."
  },
  AvgDialog_13055_Content_2 = {
    Text = "Campos de Treinamento da Universidade Mythag\nCrepúsculo"
  },
  AvgDialog_13055_Content_20 = {
    Text = "Ele continua assombrado pela anomalia no dia da cerimônia de entrega da chave, temendo que um dia possa perder o controle e virar sua lança contra você. Assim, ele busca aprimorar sua capacidade de permanecer racional sem um link"
  },
  AvgDialog_13055_Content_21 = {
    Text = "Meu senhor, vamos tentar novamente!"
  },
  AvgDialog_13055_Content_22 = {
    Text = "Estamos treinando há muito tempo. Treinar demais pode ser contraproducente."
  },
  AvgDialog_13055_Content_23 = {
    Text = "Os olhos de Ogier piscaram, mas eventualmente se apagaram, seu tom carregado de autocrítica."
  },
  AvgDialog_13055_Content_24 = {
    Text = "Foi minha negligência..."
  },
  AvgDialog_13055_Content_25 = {Text = "..."},
  AvgDialog_13055_Content_26 = {
    Text = "Vejo você amanhã após o almoço. Não tenho nenhuma tarefa de investigação também."
  },
  AvgDialog_13055_Content_27 = {
    Text = "Meu Senhor!"
  },
  AvgDialog_13055_Content_28 = {
    Text = "Sob o olhar ansioso do filhote, você arrastou seu corpo igualmente exausto de volta para o dormitório."
  },
  AvgDialog_13055_Content_29 = {
    Text = "Uma múmia simplesmente lavada repousa em uma cama macia, grata pela escolha de suprimentos de cama de Mythag, enquanto a consciência gradualmente se esvai..."
  },
  AvgDialog_13055_Content_3 = {
    Text = "A chave prateada brilha enquanto você controla o delicado fio prateado invisível em sua mente, retirando-o da luz brilhante."
  },
  AvgDialog_13055_Content_30 = {Text = "..."},
  AvgDialog_13055_Content_31 = {
    Text = "Melodias estranhas ecoam na escuridão, acompanhadas pelo tilintar de copos de prata. Uma atmosfera agitada, mas elegante preenche o Sonho."
  },
  AvgDialog_13055_Content_32 = {
    Text = "Tão barulhento... Quem está fazendo uma festa nos dormitórios no meio da noite...?"
  },
  AvgDialog_13055_Content_33 = {
    Text = "Você se virou e alcançou o cobertor que havia sido chutado para fora da cama."
  },
  AvgDialog_13055_Content_34 = {
    Text = "Uma mão se estendeu na Névoa, agarrando uma nuvem pesada de desconhecidos, sentindo-se tanto real quanto irreal."
  },
  AvgDialog_13055_Content_35 = {
    Text = "Oh, aí está você! Eu estava apenas procurando por você."
  },
  AvgDialog_13055_Content_36 = {
    Text = "Q...o quê...?"
  },
  AvgDialog_13055_Content_37 = {
    Text = "Minhas pernas estão fracas novamente. Você poderia ir até meu pai e trazer meu cavaleiro?"
  },
  AvgDialog_13055_Content_38 = {
    Text = "Cavaleiro...?"
  },
  AvgDialog_13055_Content_39 = {
    Text = "O que você está esperando? Você não ouviu o que a princesa disse?"
  },
  AvgDialog_13055_Content_4 = {Text = "Ngh...!"},
  AvgDialog_13055_Content_40 = {
    Text = "A mulher de repente bateu em seu ombro. A escuridão recuou, revelando um local desconhecido."
  },
  AvgDialog_13055_Content_41 = {
    Text = "Um grande salão, uma banda tocando suítes antigas à distância, sobremesas requintadas e tentadoras, e mulheres nobres todas olhando para você."
  },
  AvgDialog_13055_Content_42 = {
    Text = "E a garota relaxando no sofá macio, cercada por eles."
  },
  AvgDialog_13055_Content_43 = {
    Text = "Não importa, não sejam tão duros com {Male=him,Female=her}. Minha atendente esteve ocupada a noite toda sem descanso para apresentar um banquete perfeito para todos."
  },
  AvgDialog_13055_Content_44 = {
    Text = "A garota, frequentemente chamada de princesa por outros devido ao seu status nobre, gentilmente te ajudou a sair da situação."
  },
  AvgDialog_13055_Content_45 = {
    Text = "Você poderia trazer o \"cavaleiro\" que meu pai me designou para encontrar? Então você pode descansar pelo dia, certo?"
  },
  AvgDialog_13055_Content_46 = {
    Text = "Uma inundação de memórias fragmentadas invade sua mente. Elas são desconexas e incompletas, mas suficientes para você assumir o papel deste recipiente — o único acompanhante da princesa."
  },
  AvgDialog_13055_Content_47 = {
    Text = "...Obrigado pela sua bondade, Princesa."
  },
  AvgDialog_13055_Content_48 = {
    Text = "O instinto do seu corpo o levou a se curvar para ela. No meio de olhares invejosos ou desdenhosos, você fez seu caminho pelo grupo de nobres em direção ao salão lotado."
  },
  AvgDialog_13055_Content_49 = {
    Text = "Você olha para \"suas\" mãos. A pele é alguns tons mais escura do que você normalmente mantém escondida sob luvas, marcada com cicatrizes leves que indicam claramente uma vida longe do luxo."
  },
  AvgDialog_13055_Content_5 = {
    Text = "Não se esforce demais. Quando você não conseguir segurar, Link com a Poça Negra!"
  },
  AvgDialog_13055_Content_50 = {
    Text = "O vaso metálico ornamentado que passava confirmou ainda mais a ominosa suspeita—"
  },
  AvgDialog_13055_Content_51 = {
    Text = "O reflexo mostrado ali não é o seu rosto."
  },
  AvgDialog_13055_Content_52 = {
    Text = "Excelência! Você veio aqui em nome da Princesa?"
  },
  AvgDialog_13055_Content_53 = {
    Text = "A empregada que surgiu da multidão tinha olhos mais aguçados que os seus, reconhecendo o familiar \"você\" instantaneamente no meio da agitação."
  },
  AvgDialog_13055_Content_54 = {
    Text = "<Small:O Duque escolheu um cavaleiro tão jovem! Eles realmente vão permitir que uma criança tão jovem participe do treinamento de cavaleiros? Duvido que ele consiga levantar uma arma.>"
  },
  AvgDialog_13055_Content_55 = {
    Text = "<BigItalic: Com licença, por favor, dê passagem. Estamos aqui por ordem da Princesa @1 para solicitar uma audiência—>"
  },
  AvgDialog_13055_Content_56 = {
    Text = "<Small:Você não viu agora há pouco, mas quando o Duque o trouxe na frente de todos, seu rosto ficou vermelho de vergonha.>"
  },
  AvgDialog_13055_Content_57 = {
    Text = "<BigItalic:Desculpe, desculpe! O atendente da princesa chegou!!>"
  },
  AvgDialog_13055_Content_58 = {
    Text = "<Small:Quanto tempo levará para uma criança como esta se tornar um verdadeiro cavaleiro... O Duque deve estar brincando, certo?>"
  },
  AvgDialog_13055_Content_59 = {
    Text = "A empregada desfez habilidosamente a multidão com suas palavras, enquanto sussurrava observações brincalhonas para você, levando-o ao trono."
  },
  AvgDialog_13055_Content_6 = {
    Text = "Posso... ainda... aguentar..."
  },
  AvgDialog_13055_Content_60 = {
    Text = "Olá. Você é o mordomo?"
  },
  AvgDialog_13055_Content_61 = {
    Text = "Você é...!"
  },
  AvgDialog_13055_Content_62 = {
    Text = "Eu sou o filho mais velho da família Danske. Profundamente grato ao Grão-Duque por seu favor, estou extremamente honrado em servir como cavaleiro da Princesa @1."
  },
  AvgDialog_13055_Content_7 = {
    Text = "Ogier ajoelhou-se; sem o apoio do link, ele se sustentou com uma lança para evitar cair"
  },
  AvgDialog_13055_Content_8 = {Text = "Mestre..."},
  AvgDialog_13055_Content_9 = {
    Text = "Um líquido negro escorreu dos cantos de seus olhos, das bordas de seus lábios e de seus canais auditivos. Seus órgãos haviam sido esmagados por uma lodo negro amorfo, deixando claro o quão inimaginável era a dor que o menino estava suportando."
  },
  AvgDialog_13056_Content_1 = {
    Text = "Nova balada"
  },
  AvgDialog_13056_Content_10 = {
    Text = "Não chegue mais perto! Não terei misericórdia!"
  },
  AvgDialog_13056_Content_100 = {
    Text = "Vamos. É um dia de folga hoje, e o Mercado Leste estará agitado. Também podemos visitar o orfanato e checar as crianças..."
  },
  AvgDialog_13056_Content_101 = {
    Text = "Você murmura deliberadamente sua agenda e se afasta do campo de treinamento sem preocupação em seu coração."
  },
  AvgDialog_13056_Content_102 = {
    Text = "Mestre! Mestre! Por favor, me diga como você soube—"
  },
  AvgDialog_13056_Content_103 = {
    Text = "Porque, você sabe, ele seguirá."
  },
  AvgDialog_13056_Content_11 = {
    Text = "Ogier levantou sua lança e bloqueou as escadas."
  },
  AvgDialog_13056_Content_12 = {
    Text = "Este é o seu aviso final. Deixe o palácio agora!"
  },
  AvgDialog_13056_Content_13 = {
    Text = "Ei, você ouviu isso? O que ele disse? \"Por favor, nos peça para sair\"?"
  },
  AvgDialog_13056_Content_14 = {
    Text = "Hahahaha, isso é hilário! Não me surpreende que o ducado seja tão fraco—eles estão se comportando como cavaleiros com crianças."
  },
  AvgDialog_13056_Content_15 = {
    Text = "Mantenha o volume baixo, meus ouvidos estão doendo."
  },
  AvgDialog_13056_Content_16 = {
    Text = "O oficial ignorou o aviso de Ogier, caminhou até a porta do quarto e olhou para baixo em Ogier."
  },
  AvgDialog_13056_Content_17 = {Text = "Afaste-se."},
  AvgDialog_13056_Content_18 = {
    Text = "Ogier se esforçou para segurar a lança horizontalmente, tentando bloquear o avanço do oficial."
  },
  AvgDialog_13056_Content_19 = {
    Text = "Por favor, saia!"
  },
  AvgDialog_13056_Content_2 = {
    Text = "Botas, faíscando e cobertas de poeira, pisaram no tapete do palácio."
  },
  AvgDialog_13056_Content_20 = {
    Text = "Você sabia que a arma de um cavaleiro não combina com você?"
  },
  AvgDialog_13056_Content_22 = {
    Text = "A resistência é inútil diante de um poder esmagador.\nO oficial desviou facilmente a lança do Ogier e cravou uma adaga em seu peito."
  },
  AvgDialog_13056_Content_23 = {
    Text = "*Tosse—!*"
  },
  AvgDialog_13056_Content_24 = {
    Text = "Você vê isso? Esta é a habilidade que você deve aprender.\nDepois de tudo, com seu país destruído, você só merece ficar nos becos escuros, nunca vendo a luz do dia."
  },
  AvgDialog_13056_Content_25 = {
    Text = "Roubo, fome e ódio mútuo... este é o seu destino.\nA lança, que simboliza a honra cavaleiresca, não será naturalmente útil para você no futuro."
  },
  AvgDialog_13056_Content_26 = {
    Text = "O sangue subiu pela traqueia, causando uma dor rombante, como afogar-se em terra. Cada respiração sputava com o cheiro de sangue."
  },
  AvgDialog_13056_Content_27 = {
    Text = "Você quer saltar sobre a mesa baixa, empurrar o sargento escada abaixo, e proteger o Ogier ajoelhado perto da porta.\nMas seu corpo, de repente, treme, se rígido, e não obedece mais suas ordens."
  },
  AvgDialog_13056_Content_28 = {
    Text = "Não... *tosse*..."
  },
  AvgDialog_13056_Content_29 = {
    Text = "Eu me expressei mal; você não verá mais aquele futuro—você se tornará combustível para este palácio, assim como ele."
  },
  AvgDialog_13056_Content_3 = {
    Text = "Este é o seu tapete favorito em \"Recolha dos Sonhos.\" Você e a empregada barulhenta passaram uma tarde inteira escolhendo-o no armazém do Grande Duque e mais meio dia o estendendo."
  },
  AvgDialog_13056_Content_30 = {
    Text = "A bota armada pisoteou o corpo de Fernando, acompanhada pelo clangor do metal e o som agudo dos ossos quebrando."
  },
  AvgDialog_13056_Content_31 = {
    Text = "...Justo..."
  },
  AvgDialog_13056_Content_33 = {
    Text = "Cada músculo impelido pela adrenalina, ele de repente levanta sua lança e avança contra o inimigo!"
  },
  AvgDialog_13056_Content_34 = {
    Text = "<Big:Não toque nele!>"
  },
  AvgDialog_13056_Content_36 = {Text = "Hngh—!"},
  AvgDialog_13056_Content_37 = {
    Text = "A resistência foi inútil. Seu ataque não apenas falhou em abalar o oficial, mas também deixou suas costas expostas ao escoteiro."
  },
  AvgDialog_13056_Content_38 = {
    Text = "Esta criança é realmente teimosa. Se ele tivesse fugido no começo, não teríamos tido tempo para persegui-lo, certo?"
  },
  AvgDialog_13056_Content_39 = {
    Text = "Irmãozinho, você parece tão resoluto. Está protegendo algo?\nA princesa está atrás da porta?"
  },
  AvgDialog_13056_Content_4 = {
    Text = "A princesa raramente sai de seu quarto. Encostada na grade do corredor do segundo andar, ela observa todos vocês se ocupando no salão com um comportamento relaxado. Ogier, aqui para uma audiência, está tão nervoso que não sabe onde colocar os pés."
  },
  AvgDialog_13056_Content_40 = {
    Text = "Sangue jorrou das orelhas de Ogier. Ele não conseguiu ouvir cada palavra, mas ainda pegou a pronúncia mais crucial."
  },
  AvgDialog_13056_Content_41 = {
    Text = "Não... não vá..."
  },
  AvgDialog_13056_Content_42 = {
    Text = "A visão começa a esbranquiçar nas bordas, e alguma força está puxando a consciência para fora do corpo jovem."
  },
  AvgDialog_13056_Content_43 = {
    Text = "Ele rastejou para frente, sobre o cadáver de Fernando, passando pelas botas de oficiais e escuteiros, até que seus dedos finalmente tocaram a pesada porta de madeira."
  },
  AvgDialog_13056_Content_44 = {
    Text = "Quente ao toque, com um aroma lenhoso levemente picante, uma voz suave e carinhosa frequentemente vem de trás da porta.\nNeste momento, além do tique-taque do relógio de água, não há um único som vindo de trás da porta."
  },
  AvgDialog_13056_Content_45 = {
    Text = "Partir... deste lugar..."
  },
  AvgDialog_13056_Content_46 = {
    Text = "<Big: Ah——!>"
  },
  AvgDialog_13056_Content_47 = {
    Text = "Desta vez, foi sua lança longa que perfurou profundamente a carne."
  },
  AvgDialog_13056_Content_48 = {
    Text = "A arma que foi zombada por incontáveis pessoas, desprezada pelos inimigos, mas nunca abandonada por seu portador."
  },
  AvgDialog_13056_Content_49 = {
    Text = "A lança perfurou seu corpo, prendendo-o à porta, deixando-o incapaz de se mover."
  },
  AvgDialog_13056_Content_5 = {
    Text = "Não é um cavaleiro ducal... Rápido, esconda-se!"
  },
  AvgDialog_13056_Content_50 = {
    Text = "Ow—não seja tão cruel.\nE se a \"Princesa Bruxa\" nos amaldiçoar por atormentar seu cavaleiro assim?"
  },
  AvgDialog_13056_Content_51 = {
    Text = "Uma bruxa? Ridículo."
  },
  AvgDialog_13056_Content_52 = {
    Text = "<Small:@1Princesa... não...>"
  },
  AvgDialog_13056_Content_53 = {
    Text = "Ogier abriu a boca, o nome da princesa na ponta da língua, mas simplesmente não conseguiu pronunciá-lo."
  },
  AvgDialog_13056_Content_54 = {
    Text = "<Small:@1...>"
  },
  AvgDialog_13056_Content_55 = {
    Text = "Ele ouviu o som da água fluindo. O relógio d'água tinha sido virado? Isso significava que...@1 a princesa ainda estava viva?"
  },
  AvgDialog_13056_Content_56 = {
    Text = "<Small:Não... não... não... não entre...>"
  },
  AvgDialog_13056_Content_57 = {
    Text = "Basta... Ogier... Obrigado..."
  },
  AvgDialog_13056_Content_58 = {
    Text = "Obrigado... meu..."
  },
  AvgDialog_13056_Content_59 = {
    Text = "Rios negros primeiro se infiltraram sob a porta, misturando-se com o sangue de Ogier, como lágrimas derramadas por alguém."
  },
  AvgDialog_13056_Content_6 = {
    Text = "Espera! E você?!"
  },
  AvgDialog_13056_Content_60 = {
    Text = "Então, uma onda massiva, semelhante a uma inundação, irrompeu pelas fendas da porta, rugindo e subindo, engolfando instantaneamente o palácio."
  },
  AvgDialog_13056_Content_61 = {
    Text = "<Shake:Ugh—Ugh!>"
  },
  AvgDialog_13056_Content_62 = {
    Text = "A praga, invisível para as pessoas comuns, inundou os dois enquanto uma lama negra invadia seus sentidos e os afogava no ar."
  },
  AvgDialog_13056_Content_63 = {
    Text = "<Shake: Maldição, é uma maldição—>"
  },
  AvgDialog_13056_Content_65 = {
    Text = "Guardião? Acorde, Guardião? %player%?"
  },
  AvgDialog_13056_Content_66 = {Text = "Ogier!"},
  AvgDialog_13056_Content_67 = {
    Text = "Tendo um pesadelo? Olhe mais de perto. Quem sou eu?"
  },
  AvgDialog_13056_Content_68 = {
    Text = "...Boneca? O que você está fazendo no meu quarto?"
  },
  AvgDialog_13056_Content_69 = {
    Text = "Eu não me importo com o conteúdo do seu pesadelo, mas na noite passada suas ondas espirituais estavam ativas como se estivessem dançando."
  },
  AvgDialog_13056_Content_7 = {
    Text = "Ogier te empurrou com força, forçando-o a se esconder sob a mesa baixa.\nSua visão girou, e tudo que você pode ver é o luxuoso tapete persa se enrolando nas bordas devido às chamas."
  },
  AvgDialog_13056_Content_70 = {
    Text = "Os Despertadores ligados a você, incluindo eu, mais ou menos perceberam algo anormal."
  },
  AvgDialog_13056_Content_71 = {
    Text = "Na noite passada? ...Apenas uma noite se passou. Poderia realmente ter sido apenas um sonho?"
  },
  AvgDialog_13056_Content_72 = {
    Text = "Você descreve tudo no sonho absurdo para a Boneca.\nPrincesas, cavaleiros, pestes..."
  },
  AvgDialog_13056_Content_73 = {
    Text = "Entre os Investigadores ligados aos Despertadores, ocorrências de ressonância de memória e emoção são raras. Mas o que você descreveu... Nunca ouvi falar disso."
  },
  AvgDialog_13056_Content_74 = {
    Text = "Parece que essa \"entrada de sonho\" não causou mais efeitos em você. Eu continuarei a monitorar de perto sua onda mental."
  },
  AvgDialog_13056_Content_75 = {
    Text = "...Talvez, você queira conhecer Ogier agora?"
  },
  AvgDialog_13056_Content_76 = {
    Text = "A sensação de ser devorado pelo D-slime era muito real. A luz do sol da manhã aquecia os cobertores, mas o corpo se sentia como se tivesse caído em um abismo gelado."
  },
  AvgDialog_13056_Content_77 = {
    Text = "Ogier... Sim, eu organizei mais treinamento com ele hoje..."
  },
  AvgDialog_13056_Content_78 = {
    Text = "Campo de Treinamento da Universidade Mythag\nManhã"
  },
  AvgDialog_13056_Content_79 = {
    Text = "Uau—Não, não, não, eu vou morrer—"
  },
  AvgDialog_13056_Content_8 = {
    Text = "É apenas esta criança? Chegamos ao lugar certo?"
  },
  AvgDialog_13056_Content_80 = {
    Text = "Poupe-me, poupe esta pobre repórter, Senhor Ogier—"
  },
  AvgDialog_13056_Content_81 = {
    Text = "Senhorita Hannah, apenas aguente um pouco mais. Faltam apenas uma volta.\nVocê com certeza vai passar neste teste de aptidão física!"
  },
  AvgDialog_13056_Content_82 = {
    Text = "Boohoo... Tudo bem..."
  },
  AvgDialog_13056_Content_83 = {
    Text = "A corretora do campus, com sacos de areia amarrados às panturrilhas, estava chorando enquanto corria pelo campo de treinamento.\nOgier corria ao lado dela, incentivando-a e mantendo o ritmo sem esforço, sem suar."
  },
  AvgDialog_13056_Content_84 = {Text = "Ogier"},
  AvgDialog_13056_Content_85 = {Text = "Guardião!"},
  AvgDialog_13056_Content_86 = {
    Text = "Ele deu a supervisão das tarefas de Hannah a outros funcionários e correu em sua direção."
  },
  AvgDialog_13056_Content_87 = {
    Text = "Você não disse que nosso treinamento começa à tarde? Por que você está aqui tão cedo?"
  },
  AvgDialog_13056_Content_88 = {
    Text = "Ele e os outros alunos, os Despertadores, estiveram no campo de treinamento a manhã toda, mas não mostram sinais de fadiga, olhando para você com reverência e energia."
  },
  AvgDialog_13056_Content_89 = {Text = "Eu..."},
  AvgDialog_13056_Content_9 = {
    Text = "Isso mesmo, está claramente marcado no mapa estratégico - esta é a ala feminina."
  },
  AvgDialog_13056_Content_90 = {
    Text = "... Após o treinamento da Hannah, vamos explorar o centro da cidade de Londinium."
  },
  AvgDialog_13056_Content_91 = {Text = "Huh?"},
  AvgDialog_13056_Content_92 = {
    Text = "Ogier claramente não esperava que você sugerisse de repente fazer uma pausa, e você também não."
  },
  AvgDialog_13056_Content_93 = {
    Text = "Mestre, por favor, me permita recusar. A crise da Dissolução é iminente. Eu... ainda não estou pronto."
  },
  AvgDialog_13056_Content_94 = {
    Text = "Em vez de me entregar ao lazer, desejo me concentrar mais em refinar minhas habilidades marciais."
  },
  AvgDialog_13056_Content_95 = {
    Text = "Vamos por outro lado."
  },
  AvgDialog_13056_Content_96 = {
    Text = "Aquela tarde que passei com ele nos Cavaleiros de repente veio à minha mente. Memórias que você pensou que desaparecessem com o sonho ressurgiram."
  },
  AvgDialog_13056_Content_97 = {
    Text = "Agora é a hora de cumprir seu desejo, Sir Knight."
  },
  AvgDialog_13056_Content_98 = {Text = "!?"},
  AvgDialog_13056_Content_99 = {
    Text = "Como... Como você soube disso?!"
  },
  AvgDialog_130571_Content_1 = {
    Text = "Bang——————"
  },
  AvgDialog_130571_Content_10 = {
    Text = "Ah, ah... Pequena bola de carvão, desculpe... Mosk, imobilizou."
  },
  AvgDialog_130571_Content_11 = {
    Text = "Nada, mas Mosk, por que você entrou de repente?"
  },
  AvgDialog_130571_Content_12 = {
    Text = "Ah! Mosk, quente! Abraço a pequena bola de carvão, confortável!"
  },
  AvgDialog_130571_Content_13 = {
    Text = "Mosk, estranho, porque não está frio."
  },
  AvgDialog_130571_Content_14 = {
    Text = "Mas está tão quente, tão quente..."
  },
  AvgDialog_130571_Content_15 = {
    Text = "(Oh não, será a influência do Rio Sagrado?)"
  },
  AvgDialog_130571_Content_16 = {
    Text = "Mosk, não sei..."
  },
  AvgDialog_130571_Content_17 = {
    Text = "O olhar de Mosk se torna cada vez mais turvo, enquanto seus dedos delicados se deslizam entre as costuras da roupa, acariciando suavemente sua pele."
  },
  AvgDialog_130571_Content_18 = {
    Text = "Você está muito familiarizado com essa sensação, naquele sonho, a \"Pequena bola de carvão\" às vezes desfrutava desse serviço de acariciar o pelo nos braços de Mosk."
  },
  AvgDialog_130571_Content_19 = {
    Text = "Pequena bola de carvão, abraçando, calmo~"
  },
  AvgDialog_130571_Content_2 = {
    Text = "Pequena bola de carvão, abraço——"
  },
  AvgDialog_130571_Content_20 = {
    Text = "Pequena bola de carvão, cheiro, agradável~"
  },
  AvgDialog_130571_Content_21 = {
    Text = "Mosk cheira suavemente em você, e você não tem certeza se é o perfume que ficou em seu corpo ou se a sua singularidade é o que acalmou Mosk."
  },
  AvgDialog_130571_Content_22 = {
    Text = "Mas você entende que não pode deixar o Mosk continuar assim."
  },
  AvgDialog_130571_Content_23 = {
    Text = "O piso é áspero, sua cintura protesta, sentindo falta da cama macia."
  },
  AvgDialog_130571_Content_24 = {
    Text = "Então me abrace esta noite, vamos dormir juntos?"
  },
  AvgDialog_130571_Content_25 = {
    Text = "Sim! Pequena bola de carvão, gosto! Quero abraçar!"
  },
  AvgDialog_130571_Content_26 = {
    Text = "Abraçando a pequena bola de carvão, durma, durma~"
  },
  AvgDialog_130571_Content_27 = {
    Text = "Você se deitou suavemente com Mosk na cama macia, os dois se abraçando e se olhando nos olhos, como naquela época no barco."
  },
  AvgDialog_130571_Content_28 = {
    Text = "Mosk, não está quente~ Mosk, tão confortável~"
  },
  AvgDialog_130571_Content_29 = {
    Text = "Boa noite...zzz...Pequena bola de carvão...zzz"
  },
  AvgDialog_130571_Content_3 = {
    Text = "Mosk, Mosk?"
  },
  AvgDialog_130571_Content_4 = {
    Text = "Mosk de repente entrou animadamente no quarto, com as mãos envolvendo sua cintura, seus longos cabelos prateados esfregando-se incessantemente em seu peito."
  },
  AvgDialog_130571_Content_5 = {
    Text = "Você solta um suspiro silencioso de alívio. Parece que ela teve a prudência de retrair o 'objeto horrendo' em sua mão esquerda, poupando você do risco de uma mordida acidental."
  },
  AvgDialog_130571_Content_6 = {
    Text = "Pequena bola de carvão, confortável——"
  },
  AvgDialog_130571_Content_7 = {
    Text = "Mosk, espere, espere um momento, ah——"
  },
  AvgDialog_130571_Content_8 = {Text = "Tum."},
  AvgDialog_130571_Content_9 = {
    Text = "Infelizmente, como você pensou, Mosk não controlou bem sua força e vocês caíram juntos no chão."
  },
  AvgDialog_131200_Content_1 = {
    Text = "Grilhões Gentis"
  },
  AvgDialog_131200_Content_10 = {
    Text = "Arachne acariciava a metade restante da bochecha da menina. Quando ela gentilmente fechou os olhos da menina, a enorme coluna de luz atrás dela emitiu um fraco brilho."
  },
  AvgDialog_131200_Content_11 = {
    Text = "Arachne estendeu a mão. Um pouco das cinzas restantes do poste de luz flutuava ao redor de seus dedos finos como se fossem grãos de areia levados pelo vento, dançando e fluindo, antes de cair no chão."
  },
  AvgDialog_131200_Content_12 = {
    Text = "Os restos da Dimensão Cinzas... nossa percepção não está errada, aqui já foi o lugar onde Nefraea escondia as Cinzas, mas agora, as Cinzas foram levadas por ela."
  },
  AvgDialog_131200_Content_13 = {
    Text = "Levar as cinzas, matar o ícone secreto, o que Nefraea realmente quer fazer..."
  },
  AvgDialog_131200_Content_14 = {Text = "Sim?"},
  AvgDialog_131200_Content_15 = {
    Text = "Parece que algo a assustou, Arachne levantou a cabeça e olhou na direção da plataforma próxima através da vitral com o símbolo da lanterna."
  },
  AvgDialog_131200_Content_16 = {
    Text = "Arachne? O que aconteceu com você?"
  },
  AvgDialog_131200_Content_17 = {
    Text = "A respiração do corpo... não consigo mais percebê-la."
  },
  AvgDialog_131200_Content_18 = {
    Text = "Um som nauseante e úmido de dilaceração se ergue no ar. Enormes patas de aranha irrompem pelos corpos dos oficiais e dos transeuntes, espirrando sangue espesso com cheiro de ferro por todo você."
  },
  AvgDialog_131200_Content_19 = {
    Text = "Você está dizendo que saiu do teatro?"
  },
  AvgDialog_131200_Content_2 = {
    Text = "Dedos, panturrilha, globo ocular, costelas, crânio... O mestre cortou a boneca amada e a jogou na gosma e no sangue."
  },
  AvgDialog_131200_Content_20 = {
    Text = "Enquanto procuramos a \"oculta secreta\", meu corpo está limpando os servos do abismo ao longo dos fios da cidade. Após descobrir o paradeiro da \"memória\", ela foi à igreja para nos encontrar."
  },
  AvgDialog_131200_Content_21 = {
    Text = "A sua presença já estava muito próxima... mas agora, essa presença desapareceu."
  },
  AvgDialog_131200_Content_22 = {
    Text = "Será que... algo de ruim aconteceu com ela? Mas a \"memória\" acabou de morrer, como poderia..."
  },
  AvgDialog_131200_Content_23 = {
    Text = "O que realmente aconteceu, eu não sei. Mas antes de desaparecer, ela tocou a rede que me permitia comunicar. Além das ordens de retorno, a última mensagem que ela deixou foi uma palavra."
  },
  AvgDialog_131200_Content_24 = {Text = "\"Alegria\"."},
  AvgDialog_131200_Content_25 = {
    Text = "Alegria...?"
  },
  AvgDialog_131200_Content_26 = {
    Text = "Diante de você aparece o sorriso odioso de N."
  },
  AvgDialog_131200_Content_27 = {
    Text = "Não entendi... vocês têm as mesmas memórias, você deve saber o que ela quer expressar."
  },
  AvgDialog_131200_Content_28 = {
    Text = "Arachne balança a cabeça levemente."
  },
  AvgDialog_131200_Content_29 = {
    Text = "Seu Destino é uma borboleta que não ouso tocar; qualquer explicação causaria ondulações imensuráveis."
  },
  AvgDialog_131200_Content_3 = {
    Text = "\"Memórias\"..."
  },
  AvgDialog_131200_Content_30 = {
    Text = "Mas você deve saber que, em seu breve futuro, \"Alegria\" é uma chave que abrirá o segredo que você enfrenta."
  },
  AvgDialog_131200_Content_31 = {
    Text = "Meu... futuro? Quer dizer que agora você realmente consegue ver meu Fio do Destino?!"
  },
  AvgDialog_131200_Content_32 = {
    Text = "Você sustenta o olhar dela. Dentro daquele sorriso gentil, você vê a autoridade inegável do Destino."
  },
  AvgDialog_131200_Content_33 = {
    Text = "......Não importa o que aconteça, confie em mim e confie em si mesmo."
  },
  AvgDialog_131200_Content_34 = {
    Text = "Retorne ao Teatro do Destino. A chave e a fechadura aguardam você lá, %player%."
  },
  AvgDialog_131200_Content_35 = {Text = "Mas..."},
  AvgDialog_131200_Content_36 = {
    Text = "A voz tranquila de Arachne era como o calor suave do sol poente de outono. Sua forma se transformou em um punhado de teias de aranha, desaparecendo na luz silenciosa da igreja."
  },
  AvgDialog_131200_Content_37 = {
    Text = "Sob o brilho caleidoscópico dos vitrais, apenas brasas dimensionais flutuam sobre o sangue e os membros decepados."
  },
  AvgDialog_131200_Content_38 = {
    Text = "\"Alegria\"..."
  },
  AvgDialog_131200_Content_39 = {
    Text = "Você murmura aquela palavra enigmática, vira-se e vê aqueles restos do corpo chamados de \"memórias\"."
  },
  AvgDialog_131200_Content_4 = {
    Text = "Você pega gentilmente os fragmentos da menina, e o líquido pegajoso e o sangue nas extremidades dilaceradas encharcam suas roupas."
  },
  AvgDialog_131200_Content_40 = {
    Text = "Banhados em fluido turvo e luz sagrada, os fragmentos parecem se fundir com a própria catedral sagrada."
  },
  AvgDialog_131200_Content_41 = {Text = "..."},
  AvgDialog_131200_Content_42 = {
    Text = "O caminho coberto de teias de aranha treme levemente, iluminado pela luz fraca do palco. No momento em que você pisa na teia, todos os fantoches param a apresentação."
  },
  AvgDialog_131200_Content_43 = {
    Text = "Todos nas dimensões olham para você. Eles estão curiosos, empolgados, alegres e reverentes."
  },
  AvgDialog_131200_Content_44 = {
    Text = "Esta é uma recepção solene e tranquila. Incontáveis atores se tornaram espectadores, e o único espectador se tornou o protagonista."
  },
  AvgDialog_131200_Content_45 = {
    Text = "Talvez não seja uma boa ideia ouvir Arachne..."
  },
  AvgDialog_131200_Content_46 = {
    Text = "Você segura a chave de prata com firmeza, passando sozinho por esse silêncio lotado e estranho."
  },
  AvgDialog_131200_Content_47 = {
    Text = "O novo mestre do teatro está esperando por você, {Male=Mr.,Female=Miss} Guardião."
  },
  AvgDialog_131200_Content_48 = {
    Text = "As sombras se reúnem no palco alto. Quase como uma reação instintiva, você rapidamente se inclina para trás, erguendo a chave de prata à sua frente."
  },
  AvgDialog_131200_Content_49 = {
    Text = "Novo mestre?"
  },
  AvgDialog_131200_Content_5 = {
    Text = "Talvez... talvez ainda haja uma maneira de salvá-la... o poder do plásmido... a correção do destino..."
  },
  AvgDialog_131200_Content_50 = {
    Text = "Bem-vindo de volta ao teatro, {Male=Mr.,Female=Miss} Guardião."
  },
  AvgDialog_131200_Content_51 = {
    Text = "Arachne, você..."
  },
  AvgDialog_131200_Content_52 = {
    Text = "Desculpe, nossa nova história precisa da sua participação."
  },
  AvgDialog_131200_Content_53 = {
    Text = "A teia de aranha treme suavemente. O mestre do teatro se aproxima lentamente, sua voz ainda tão suave quanto o crepúsculo."
  },
  AvgDialog_131200_Content_54 = {
    Text = "No palco ao seu redor, os bonecos idênticos à servente da aranha fria se viraram e saltaram em uníssono em sua direção..."
  },
  AvgDialog_131200_Content_55 = {
    Text = "Um som nauseante e úmido de dilaceração se ergue no ar. Enormes patas de aranha irrompem pelos corpos dos oficiais e dos transeuntes, espirrando sangue espesso com cheiro de ferro por todo você."
  },
  AvgDialog_131200_Content_6 = {
    Text = "Nefraea destruiu seus fios... seu destino já acabou, Guardião {Male=senhor, Female=senhorita}."
  },
  AvgDialog_131200_Content_7 = {
    Text = "O som da roca ainda é calmo e distante."
  },
  AvgDialog_131200_Content_8 = {
    Text = "\"A memória\" também foi assassinada por ela, isso significa que..."
  },
  AvgDialog_131200_Content_9 = {
    Text = "Nefraea, já possui o poder de mudar o destino deste palco."
  },
  AvgDialog_131201_Content_1 = {
    Text = "Hã... Esses servidores de Nefraea são realmente difíceis de lidar..."
  },
  AvgDialog_131201_Content_10 = {
    Text = "Vinte dias depois, ele começará a estudar seriamente o que está registrado neste livro... A partir daquele momento, este palco se encontrará, como todos os outros palcos, inevitavelmente aguardando o destino da destruição."
  },
  AvgDialog_131201_Content_100 = {
    Text = "O príncipe herdeiro e a senhora estavam sentados no banco de trás da carruagem aberta, admirando esta antiga cidade. As pessoas corriam atrás da carruagem, correndo em direção ao destino que já estava destinado a elas."
  },
  AvgDialog_131201_Content_11 = {
    Text = "Memórias deste mundo — novas e estranhamente familiares — inundam sua mente. Você nunca viu um lugar tão vibrante e próspero."
  },
  AvgDialog_131201_Content_12 = {
    Text = "Você já passou por demais, dissolvendo aquela paisagem desolada, cobrindo facilmente este mundo próspero, preenchendo sua imaginação."
  },
  AvgDialog_131201_Content_13 = {
    Text = "Arachne estendeu a mão e acariciou suavemente a luz da manhã que caía na entrada da rua. Ela estava de luto por mais um mundo prestes a morrer."
  },
  AvgDialog_131201_Content_14 = {
    Text = "Um mundo que não foi notado pelos deuses... Eu nunca tive uma imaginação assim antes."
  },
  AvgDialog_131201_Content_15 = {
    Text = "Ainda temos a chance de mudar isso?"
  },
  AvgDialog_131201_Content_16 = {
    Text = "Este é exatamente o que viemos fazer."
  },
  AvgDialog_131201_Content_17 = {
    Text = "Diga-me, o que devo fazer?"
  },
  AvgDialog_131201_Content_18 = {
    Text = "Espere!......"
  },
  AvgDialog_131201_Content_19 = {
    Text = "Você os notou, {Male=Mr.,Female=Miss} Guardião."
  },
  AvgDialog_131201_Content_2 = {
    Text = "Você se apoia na parede úmida de um beco isolado, ofegante."
  },
  AvgDialog_131201_Content_20 = {
    Text = "Do lado de fora da viela, um grupo de pessoas com flutuações mentais claramente diferentes das normais está se aproximando de vocês."
  },
  AvgDialog_131201_Content_21 = {
    Text = "Atrás, acima, à frente... cada vez mais inimigos aparecem na sua percepção."
  },
  AvgDialog_131201_Content_22 = {
    Text = "Estamos cercados!..."
  },
  AvgDialog_131201_Content_23 = {
    Text = "Desde que cheguei ao palco, estive corrigindo o destino que foi alterado. No entanto, corrigir o destino de tantas pessoas não é uma tarefa fácil."
  },
  AvgDialog_131201_Content_24 = {
    Text = "Nefraea deixou essas pessoas para obstruir minha reparação do destino."
  },
  AvgDialog_131201_Content_25 = {
    Text = "Talvez ainda temos outra maneira..."
  },
  AvgDialog_131201_Content_26 = {
    Text = "Arachne, eu sou um dos executores do assassinato que o Comitê de Restauração Nacional está tramando aqui hoje."
  },
  AvgDialog_131201_Content_27 = {
    Text = "Este mundo será destruído por causa daquela pessoa, o príncipe herdeiro, que estuda o livro de feitiçaria. Se eu conseguir, talvez consiga impedir que isso aconteça"
  },
  AvgDialog_131201_Content_28 = {
    Text = "Isso não é o mais correto..."
  },
  AvgDialog_131201_Content_29 = {
    Text = "Ali! Prendam-nos"
  },
  AvgDialog_131201_Content_3 = {
    Text = "Você não viu Arachne correndo, ela está parada ao seu lado tranquilamente, como se estivesse destinado a estar neste momento nesta viela."
  },
  AvgDialog_131201_Content_30 = {
    Text = "Arachne toca as cordas da harpa, preparando o servidor mutante parado na entrada da rua, como uma estátua."
  },
  AvgDialog_131201_Content_31 = {
    Text = "Ao longe, ouve-se a sonata de trompete e saxofone, acompanhada pelo rugido dos carros, que se aproxima lentamente."
  },
  AvgDialog_131201_Content_32 = {
    Text = "O plano de assassinato foi descoberto, os outros não conseguem fazer isso... Aquela pessoa, o príncipe herdeiro, já está se aproximando, se não fizermos nada, será tarde demais"
  },
  AvgDialog_131201_Content_33 = {
    Text = "Arachne olhou para seus olhos ansiosos e, após hesitar por um momento, acenou com a cabeça suavemente."
  },
  AvgDialog_131201_Content_34 = {
    Text = "Já que o rumo do destino é assim... talvez, tentar fazer uma escolha por este mundo seja o que você deve realizar."
  },
  AvgDialog_131201_Content_35 = {
    Text = "Vá. Faça o que deve ser feito, {Male=Mr.,Female=Miss} Guardião. A verdade do Destino será revelada a você aqui."
  },
  AvgDialog_131201_Content_36 = {
    Text = "Você não teve tempo de pensar cuidadosamente nas palavras de Arachne, acenou com a cabeça e, com a ajuda de Arachne, saiu correndo da alley e se juntou à multidão agitada."
  },
  AvgDialog_131201_Content_37 = {
    Text = "Aquele é o Duque Flaviano? O herdeiro do império... Imagino quanto custa um carro daqueles."
  },
  AvgDialog_131201_Content_38 = {
    Text = "Bah! Filho bastardo de um ladrão! Cada centavo que ele gasta foi arrancado do nosso suor e sangue!"
  },
  AvgDialog_131201_Content_39 = {
    Text = "Se minhas pernas não estivessem mancas, eu certamente morreria no campo de batalha ao atacar esses bandidos"
  },
  AvgDialog_131201_Content_4 = {
    Text = "Depois de ter feito toda essa preparação... o que ela realmente quer fazer?"
  },
  AvgDialog_131201_Content_40 = {
    Text = "Shh! Aqui estão por toda parte os guardas do império, você não quer viver?"
  },
  AvgDialog_131201_Content_41 = {Text = "..."},
  AvgDialog_131201_Content_42 = {
    Text = "Quando você consegue atravessar a multidão e finalmente chega à calçada, aquele carro conversível novinho está passando lentamente diante de você."
  },
  AvgDialog_131201_Content_43 = {
    Text = "O príncipe herdeiro, um homem beirando os sessenta, está sentado no banco de trás com sua esposa. Eles acenam graciosamente para a multidão enquanto apontam a arquitetura histórica de Havatz."
  },
  AvgDialog_131201_Content_44 = {
    Text = "Mesmo com suas memórias turvas, você conhece muito bem o profundo sofrimento que esta casa real infligiu sobre a terra."
  },
  AvgDialog_131201_Content_45 = {
    Text = "Preocupado em causar um impacto negativo neste mundo, você parou a mão que se estendia involuntariamente em direção à chave de prata, tirou a pistola que deveria estar ali do seu bolso e se aproximou do veículo que passava lentamente."
  },
  AvgDialog_131201_Content_46 = {
    Text = "Ei! Aquele estudante! Você não pode se aproximar..."
  },
  AvgDialog_131201_Content_47 = {
    Text = "Desculpe, Alteza, já que estou no palco, devo cumprir o que este personagem precisa fazer"
  },
  AvgDialog_131201_Content_48 = {
    Text = "BANG! BANG BANG!"
  },
  AvgDialog_131201_Content_49 = {
    Text = "Nesta rua caótica, o orgulhoso herdeiro do império não tem a segurança rigorosa que você imaginava. Com seu treinamento rigoroso, você se aproxima facilmente do veículo e aperta o gatilho."
  },
  AvgDialog_131201_Content_5 = {
    Text = "Nefraea deixou um prólogo. Neste vasto Rede do destino deste mundo, ela poluiu um dos fios."
  },
  AvgDialog_131201_Content_50 = {
    Text = "Quando três balas perfuraram com precisão o peito do grão-duque, o mundo inteiro parou."
  },
  AvgDialog_131201_Content_51 = {
    Text = "O grande duque em dor, a princesa assombrada, os guardas correndo, todos pararam de forma ridícula, como uma pintura a óleo vívida."
  },
  AvgDialog_131201_Content_52 = {
    Text = "!!! Isso é..."
  },
  AvgDialog_131201_Content_53 = {
    Text = "Após uma breve pausa, as cores da pintura a óleo começaram a fluir e se entrelaçar, o espaço-tempo e a gravidade se juntaram a esta festa caótica, seu corpo sendo puxado, inúmeras imagens passando diante de seus olhos."
  },
  AvgDialog_131201_Content_54 = {
    Text = "Um funeral grandioso. A fúria de um rei. Guerra. Canhões. Morte. O soar das trombetas de guerra e os gritos dos civis. Abutres descendo sobre os campos carmesins de Verdun para se banquetear com quatrocentos mil restos mutilados."
  },
  AvgDialog_131201_Content_55 = {
    Text = "A queda do império, as terras divididas, o rei arruinado, o livro de feitiços reaberto..."
  },
  AvgDialog_131201_Content_56 = {
    Text = "Uma substância negra e pegajosa engole brevemente seu campo de visão. Aquele conto familiar se repete, uma escuridão total e dor corroendo cada uma de suas células..."
  },
  AvgDialog_131201_Content_57 = {
    Text = "Não se preocupe, {Male=Mr.,Female=Miss} Guardião. Você está seguro agora."
  },
  AvgDialog_131201_Content_58 = {
    Text = "Uma mão repousa em seu ombro. As cores caóticas e sangrantes e a escuridão sem fim desaparecem."
  },
  AvgDialog_131201_Content_59 = {
    Text = "Seus olhos se abrem de repente. O café está tão silencioso como sempre; a pistola Browning sumiu de sua mão, e a Sachertorte recém–servida está diante de você, exalando um aroma irresistível."
  },
  AvgDialog_131201_Content_6 = {
    Text = "Nesta linha temporal corrompida, o príncipe herdeiro do Império Feo descobriu um certo livro dois meses atrás."
  },
  AvgDialog_131201_Content_60 = {
    Text = "Arachne... o que... está acontecendo?! Nós..."
  },
  AvgDialog_131201_Content_61 = {
    Text = "Por favor, não entre em pânico, já voltamos ao momento em que entramos no café. A boa notícia é que recebemos uma xícara de café grátis."
  },
  AvgDialog_131201_Content_62 = {
    Text = "Arachne levantou a xícara de café e sorriu enquanto tomava um gole. O líquido marrom refletia o seu rosto surpreso."
  },
  AvgDialog_131201_Content_63 = {
    Text = "As linhas do destino não são coisas que você pode ver claramente. Os atores de fora do palco, que forçam a mudar o destino deste mundo, acabam perdidos na teia do destino."
  },
  AvgDialog_131201_Content_64 = {
    Text = "Passado e futuro, os incontáveis destinos deste palco entrelaçando–se diante de seus olhos... essa é a verdadeira face da Rede do destino."
  },
  AvgDialog_131201_Content_65 = {
    Text = "O destino do futuro... Você está dizendo que tudo o que aconteceu agora, é real? Aqueles conflitos, mortes... foram causados por mim?"
  },
  AvgDialog_131201_Content_66 = {
    Text = "O Destino permitiu que você testemunhasse. Após o assassinato do Duque, esse era de fato o caminho que o mundo deveria seguir. Mas fique tranquilo, {Male=Mr.,Female=Miss} Guardião. Eu já reteci o destino deste palco."
  },
  AvgDialog_131201_Content_67 = {
    Text = "Você olhou pela janela. Ainda era a multidão animada, mas os cidadãos e policiais afetados por Nefraea já haviam desaparecido."
  },
  AvgDialog_131201_Content_68 = {
    Text = "Se eu seguisse o que fiz antes... se você não tivesse consertado o destino..."
  },
  AvgDialog_131201_Content_69 = {
    Text = "Um mês depois, este mundo irá explodir em uma das maiores guerras da história devido à morte deste príncipe herdeiro. Oito impérios estarão envolvidos, e vinte milhões de pessoas morrerão nesta guerra."
  },
  AvgDialog_131201_Content_7 = {
    Text = "Um livro que registra feitiços misteriosos e que pode conectar deuses que não pertencem a esta dimensão."
  },
  AvgDialog_131201_Content_70 = {
    Text = "A terra sob nossos pés se tornará cinzas, e as pessoas ao nosso redor no café não conseguiram sobreviver àquela guerra."
  },
  AvgDialog_131201_Content_71 = {
    Text = "Arachne balança a xícara de café, olhando para o movimento incessante da rua do lado de fora. Ela fala calmamente, como se estivesse apresentando uma sobremesa nada especial."
  },
  AvgDialog_131201_Content_72 = {
    Text = "As vozes efervescentes nas ruas trazem a melodia da paz e prosperidade, entrando em seus ouvidos."
  },
  AvgDialog_131201_Content_73 = {
    Text = "E a corrosão? Por que, mesmo após ter matado o herdeiro, ainda assim trago a corrosão para este mundo..."
  },
  AvgDialog_131201_Content_74 = {
    Text = "Nesta grande guerra, este império foi derrotado. Aquele rei, que originalmente teve que aceitar a cruel sentença do destino. Mas agora, ele tem uma nova escolha."
  },
  AvgDialog_131201_Content_75 = {
    Text = "Magia que não pertence a este mundo, divindade que transcende todo poder. O que poderia ser mais atraente para um pai que perdeu seu filho, um monarca que perdeu seu reino?"
  },
  AvgDialog_131201_Content_76 = {
    Text = "As palavras suaves de Arachne fizeram você estremecer. O peso de dois bilhões de vidas pesa sobre você como se fosse substancial."
  },
  AvgDialog_131201_Content_77 = {
    Text = "<Shake:Nunca imaginei que assassinar um príncipe levaria a tudo isso... Pensei que estava ajudando...>"
  },
  AvgDialog_131201_Content_78 = {
    Text = "O destino fez você tomar esta escolha, para que você possa vê-lo claramente. Você não consegue ver os fios, mas agora entende como eles se entrelaçam de forma tão complexa."
  },
  AvgDialog_131201_Content_79 = {
    Text = "As linhas do destino tecem uma enorme rede, cada leve tremor de uma linha pode fazer a rede do destino desmoronar."
  },
  AvgDialog_131201_Content_8 = {
    Text = "Arachne levantou a cabeça e olhou para aqueles fios que você não pode ver."
  },
  AvgDialog_131201_Content_80 = {
    Text = "Este é o destino — um destino tão complexo."
  },
  AvgDialog_131201_Content_81 = {
    Text = "Você respirou fundo uma vez, acalmando o coração que batia forte devido ao medo."
  },
  AvgDialog_131201_Content_82 = {
    Text = "Ainda bem, ainda bem que você impediu essa guerra..."
  },
  AvgDialog_131201_Content_83 = {
    Text = "Eu não impedi a guerra, {Male=Mr.,Female=Miss} Guardião."
  },
  AvgDialog_131201_Content_84 = {
    Text = "Arachne balançou a cabeça levemente."
  },
  AvgDialog_131201_Content_85 = {
    Text = "Na nova destino, o rei do império verá uma pequena parte dos milagres apresentados no livro de feitiçaria. Aquela força se tornará o apoio para ele iniciar a guerra."
  },
  AvgDialog_131201_Content_86 = {
    Text = "O rei e seus aliados desencadearam uma guerra em maior escala, e outros impérios de continentes diferentes também foram envolvidos nesse conflito."
  },
  AvgDialog_131201_Content_87 = {
    Text = "Os mortos nesta guerra são quatro vezes o número original."
  },
  AvgDialog_131201_Content_88 = {
    Text = "Ela continua sua narração calma, soando como uma mãe contando uma história de ninar para uma criança que não consegue dormir."
  },
  AvgDialog_131201_Content_89 = {
    Text = "<Shake:Isso... por que isso?>"
  },
  AvgDialog_131201_Content_9 = {
    Text = "Este palco nunca teve conexão com os deuses, por muito tempo, poderia ter sido poupado de cair no destino da dissolução."
  },
  AvgDialog_131201_Content_90 = {
    Text = "Você já viu a complexidade da teia do destino. Tentar evitar à força algumas coisas que estão destinadas a acontecer resultará em uma catástrofe ainda mais grave."
  },
  AvgDialog_131201_Content_91 = {
    Text = "O rei ainda é derrotado; o conhecimento limitado naquele livro não oferece ao império nenhuma salvação duradoura."
  },
  AvgDialog_131201_Content_92 = {
    Text = "Após este segundo fracasso, a feitiçaria será descartada como uma farsa. Nenhum governante neste palco jamais recorrerá a ela novamente."
  },
  AvgDialog_131201_Content_93 = {
    Text = "Seu olhar se voltou para outras coisas. Eles acreditavam na ciência, pesquisando armas que podiam devorar planetas, desfrutando de uma paz passageira sob a ameaça dessas armas que criaram, e então foram destruídos por elas."
  },
  AvgDialog_131201_Content_94 = {
    Text = "Este palco ainda está destinado a desaparecer em algum apocalipse futuro — esse é seu destino inescapável. Mas por um tempo, eles desfrutarão de um período de prosperidade tão belo quanto uma obra de arte."
  },
  AvgDialog_131201_Content_95 = {
    Text = "O Olhar de Toguwaibo será mantido à distância, pelo menos por um tempo."
  },
  AvgDialog_131201_Content_96 = {
    Text = "A colher de Arachne gira lentamente na xícara, aquele vórtice marrom escuro é idêntico ao que você vê na Rede do destino."
  },
  AvgDialog_131201_Content_97 = {
    Text = "Ela abaixou a cabeça. A luz do sol do lado de fora caía sobre ela, como um véu de tristeza."
  },
  AvgDialog_131201_Content_98 = {
    Text = "Lutar, tecer, remendar... e nada realmente muda. Isso é o Destino, {Male=Mr.,Female=Miss} Guardião."
  },
  AvgDialog_131201_Content_99 = {
    Text = "A música do trompete e do saxofone chegou à janela, levando consigo os aplausos e os xingamentos da multidão que gradualmente se afastavam."
  },
  AvgDialog_131202_Content_1 = {Text = "Estalo—"},
  AvgDialog_131202_Content_10 = {Text = "Crente?..."},
  AvgDialog_131202_Content_11 = {
    Text = "A túnica roxa... eu nunca... nunca vi..."
  },
  AvgDialog_131202_Content_12 = {
    Text = "Eles... levaram as \"Memórias\" ao altar... <Shake:Tosse, tosse...>"
  },
  AvgDialog_131202_Content_13 = {
    Text = "Rua São Basílio... uma igreja que pertence a eles..."
  },
  AvgDialog_131202_Content_14 = {
    Text = "Os ossos e a carne e sangue tremem, lutam, espremendo a última força vital deste corpo dilapidado."
  },
  AvgDialog_131202_Content_15 = {
    Text = "Ele sabia que a senhorita Arachne não conseguia ver os fios daquelas pessoas. Ele sabia que isso era algo que ele precisava fazer."
  },
  AvgDialog_131202_Content_16 = {
    Text = "Senhorita... os vilões nas sombras... estão nos caçando... ela manipulou nosso destino..."
  },
  AvgDialog_131202_Content_17 = {
    Text = "Eles levaram meu sangue... Naquela igreja, ela realizará aquele ritual de terror..."
  },
  AvgDialog_131202_Content_18 = {
    Text = "Vingador do destino, banhe-se em nosso Sangue... o deus maligno das sombras está prestes a chegar, e todo o destino mergulhará em... completo... <Shake:Tosse, tosse, tosse...><Big:Caos absoluto...!>"
  },
  AvgDialog_131202_Content_19 = {
    Text = "A pupila do velho dilatou-se repentinamente, seu corpo tremia de frio e medo, como se visse um inferno mais aterrador do que seu pesadelo mais profundo."
  },
  AvgDialog_131202_Content_2 = {
    Text = "As aranhas se dispersaram, e a última sombra caiu na luz prateada, o mestre da tempestade já havia desaparecido. Você e Arachne chegaram diante da figura caída no centro do quarto."
  },
  AvgDialog_131202_Content_20 = {
    Text = "Ele segurou firmemente a manga de Arachne, olhando para ela com um olhar quase suplicante."
  },
  AvgDialog_131202_Content_21 = {
    Text = "Senhorita... eu ainda estou acostumado a chamá-la de senhorita... Você demorou muito para aprender a falar, deixando o senhor e a senhora muito preocupados..."
  },
  AvgDialog_131202_Content_22 = {
    Text = "Você se despede de mim, todos estão felizes por finalmente poder falar, mas eu sei, apenas eu sei... aquela frase é o veredicto do destino que não pode ser desafiado..."
  },
  AvgDialog_131202_Content_23 = {
    Text = "Eu voltei para casa, esperando pela chegada da morte. Não consigo parar de chorar, não por mim, mas por você, senhorita Arachne..."
  },
  AvgDialog_131202_Content_24 = {
    Text = "Eu sei que o que você vai carregar é uma maldição extremamente pesada..."
  },
  AvgDialog_131202_Content_25 = {
    Text = "Lágrimas escorrem pela face marcada das rugas do velho. Ele agarra a mão de Arachne tremulamente. Através da luz turva das lágrimas, ele vê a jovem Arachne parada à sua frente."
  },
  AvgDialog_131202_Content_26 = {
    Text = "Aquela cara jovem nunca chorou em voz alta, ela sempre olhava curiosamente para o céu vazio, sorrindo para aqueles destinos que não podiam ver."
  },
  AvgDialog_131202_Content_27 = {
    Text = "Senhorita Arachne, por favor, cuide bem dela, cuide bem das \"Memórias\"... por favor, cuide bem de si mesma..."
  },
  AvgDialog_131202_Content_28 = {
    Text = "Não se perca... na... rede..."
  },
  AvgDialog_131202_Content_29 = {
    Text = "A voz da \"Bondade\" quase se tornou inaudível até o final. Quando seu sopro parou, Arachne gentilmente fechou seus olhos."
  },
  AvgDialog_131202_Content_3 = {
    Text = "É você..."
  },
  AvgDialog_131202_Content_30 = {
    Text = "\"Descanse agora, Senhor Lawrence...\""
  },
  AvgDialog_131202_Content_31 = {
    Text = "Os lábios do velho Edgar se curvaram levemente. Nos últimos momentos de sua vida, ele ouviu novamente a primeira frase que Arachne disse nesta vida."
  },
  AvgDialog_131202_Content_32 = {
    Text = "Ele não pede nada."
  },
  AvgDialog_131202_Content_33 = {
    Text = "Você usou as memórias do seu próprio mordomo para criar este ícone secreto... ele não é como os outros bonecos que você fez. Por quê?"
  },
  AvgDialog_131202_Content_34 = {
    Text = "Talvez seja para lembrar, ou talvez... seja para consolar a si mesmo."
  },
  AvgDialog_131202_Content_35 = {Text = "Conforto?"},
  AvgDialog_131202_Content_36 = {
    Text = "Confortando-me, eles sempre estiveram ao meu lado, nunca se afastaram..."
  },
  AvgDialog_131202_Content_37 = {
    Text = "Arachne colocou calmamente o corpo deteriorado do velho, sem dar mais explicações, e você não fez mais perguntas. Você sabia que a resposta estava esperando por você não muito longe."
  },
  AvgDialog_131202_Content_38 = {
    Text = "Nesta Rede do destino, a força de Nefraea está relacionada a eles. A morte deles tornará a ligação de Nefraea com a rede ainda mais estreita."
  },
  AvgDialog_131202_Content_39 = {
    Text = "Devemos detê-la antes que ela ganhe o poder de rasgar a teia. Isso é tudo que importa agora, {Male=Mr.,Female=Miss} Guardião."
  },
  AvgDialog_131202_Content_4 = {
    Text = "<Shake:Senhorita Arachne... Estrangeiro... cof cof...>"
  },
  AvgDialog_131202_Content_40 = {
    Text = "As mãos de Arachne acariciam o topo da cabeça do velho, tocando aquele fio que quase já não é visível. Do outro lado distante desta cidade, o fio do destino emite um eco fraco."
  },
  AvgDialog_131202_Content_41 = {
    Text = "O destino respondeu a você?"
  },
  AvgDialog_131202_Content_42 = {
    Text = "Arachne acenou com a cabeça. Antes de se levantar, ela deu uma última olhada no rosto sorridente do velho."
  },
  AvgDialog_131202_Content_43 = {
    Text = "\"As memórias\" ainda estão vivas. Aqueles convidados do Abismo estão esperando pela nossa chegada."
  },
  AvgDialog_131202_Content_5 = {
    Text = "Diante de você, o corpo é metade carne e sangue corroído por mordidas e metade osso branco tingido de vermelho."
  },
  AvgDialog_131202_Content_6 = {
    Text = "O velho tossiu violentamente, forçando algumas gotas de sangue ainda não seco a sair. Um fio invisível estava nas mãos de Arachne, como uma vela na tempestade, instável."
  },
  AvgDialog_131202_Content_7 = {
    Text = "Hemostasia... Precisamos de algo para estancar o sangue..."
  },
  AvgDialog_131202_Content_8 = {
    Text = "Já é tarde demais... Senhorita Arachne... Vá salvá-la... Vá salvar \"Memórias\"..."
  },
  AvgDialog_131202_Content_9 = {
    Text = "Aqueles crentes... levaram-na embora..."
  },
  AvgDialog_131203_Content_1 = {
    Text = "Arachne! O que você está fazendo?! Isso é o que você chama de... confiança?"
  },
  AvgDialog_131203_Content_10 = {
    Text = "Performance. Engano. Zombaria."
  },
  AvgDialog_131203_Content_11 = {
    Text = "\"Êxtase\", este é o seu destino. Suba ao palco, {Male=Mr.,Female=Miss} Guardião. \nNeste palco, você concluirá sua própria história."
  },
  AvgDialog_131203_Content_12 = {
    Text = "Neste palco, você terá seus desejos realizados."
  },
  AvgDialog_131203_Content_2 = {
    Text = "William, o companheiro mais velho... E-Ele ainda está se recuperando dos ferimentos!..."
  },
  AvgDialog_131203_Content_3 = {
    Text = "Não se preocupe, {Male=Mr.,Female=Miss} Guardião. Ele não tem nada a ver com este fio do Destino. Eu o teleportei para um lugar seguro."
  },
  AvgDialog_131203_Content_4 = {
    Text = "Este é um destino do qual nenhum de nós pode escapar, {Male=Mr.,Female=Miss} Guardião."
  },
  AvgDialog_131203_Content_5 = {
    Text = "Nunca te contei mentiras. Vou te levar ao palco que é seu, e você realizará a sua grandiosa apresentação neste palco."
  },
  AvgDialog_131203_Content_6 = {
    Text = "Arachne caminha lentamente em sua direção. Você olha para os olhos dela, que são como névoa, tentando ler as informações que ela não consegue transmitir diretamente a você."
  },
  AvgDialog_131203_Content_7 = {
    Text = "(pertencente a mim... apresentação...)"
  },
  AvgDialog_131203_Content_8 = {
    Text = "Uma luz espiritual passou pela sua mente, como uma estrela cadente que desaparece rapidamente, sumindo entre os fragmentos caóticos da consciência."
  },
  AvgDialog_131203_Content_9 = {
    Text = "As Serventes da Aranha Fria se dispersaram ao redor, não avançaram mais. Arachne levantou suavemente a mão e tocou as cordas vazias do instrumento."
  },
  AvgDialog_131204_Content_1 = {
    Text = "A luz prateada cortou as teias como uma lâmina afiada. Aproveitando essa brecha, você rapidamente atravessou a linha de defesa das serventes e chegou diante de Arachne."
  },
  AvgDialog_131204_Content_10 = {
    Text = "Ela se virou. Os fios se moveram suavemente, e um impulso repentino surgiu do fundo do seu coração, levando você a se levantar."
  },
  AvgDialog_131204_Content_11 = {
    Text = "Você tem certeza de que é totalmente autônomo, você é o perfeito representante do livre-arbítrio. Você segue os passos de Arachne inteiramente por sua própria vontade, caminhando com o mesmo ritmo e frequência que ela, em direção ao fim do Caminho da teia."
  },
  AvgDialog_131204_Content_12 = {Text = "..."},
  AvgDialog_131204_Content_13 = {
    Text = "Oh, bem-vindo! {Male=Mr.,Female=Miss} %player%, meu estimado convidado! Seus passos nunca soaram tão musicais."
  },
  AvgDialog_131204_Content_14 = {
    Text = "O novo proprietário do teatro faz sua entrada, e o tom exagerado de Nefraea ressoa no palco escuro."
  },
  AvgDialog_131204_Content_15 = {
    Text = "Não é agradável, é? Ter seu destino manipulado? Não importa, {Male=Mr.,Female=Miss} Guardião. Esta história está quase no fim."
  },
  AvgDialog_131204_Content_16 = {
    Text = "Nefraea, o que você realmente quer fazer?..."
  },
  AvgDialog_131204_Content_17 = {
    Text = "Suspense, isso mesmo, é exatamente a razão que leva o público a vir a este teatro! Mas não se apresse, querido."
  },
  AvgDialog_131204_Content_18 = {
    Text = "Senhoras e senhores! Preparem seus aplausos... Hmm, onde está meu fantoche... Ah, encontrei"
  },
  AvgDialog_131204_Content_19 = {
    Text = "Que tipo de apresentação imaginativa os grandes vingadores do destino, que caçaram os três segredos, desejam oferecer neste palco?"
  },
  AvgDialog_131204_Content_2 = {Text = "Entendi!"},
  AvgDialog_131204_Content_20 = {
    Text = "Agora, testemunhem o <Big:<Red:Clímax do Segundo Ato!>>"
  },
  AvgDialog_131204_Content_21 = {
    Text = "Eu o nomeei de \"novo nascido\" —"
  },
  AvgDialog_131204_Content_22 = {Text = "Estalo—"},
  AvgDialog_131204_Content_23 = {
    Text = "Um feixe de luz brilhante se concentra no palco, quebrando a breve tranquilidade e escuridão do teatro. Um boneco segurando uma roca sobe ao palco."
  },
  AvgDialog_131204_Content_24 = {
    Text = "Nefraea, a deusa da morte do Abismo, a vingadora do destino...<Shake:Eu já me submeti ao seu grande poder!>"
  },
  AvgDialog_131204_Content_25 = {
    Text = "Isso é romantismo, que torna as pessoas tolas. Isso é bondade, que torna as pessoas frágeis. Isso é memória... entre todas as qualidades belas, a memória é a fonte de todo o sofrimento."
  },
  AvgDialog_131204_Content_26 = {
    Text = "Eu não consigo suportá-los... Eu os ofereço a você, grande Nefraea."
  },
  AvgDialog_131204_Content_27 = {
    Text = "É verdade, irmã? Minha boa irmã..."
  },
  AvgDialog_131204_Content_28 = {
    Text = "Está tudo bem, neste mundo, sou a pessoa que mais te entende. Não precisa mais sofrer, deixe toda essa dor comigo."
  },
  AvgDialog_131204_Content_29 = {
    Text = "Veja, a lanterna do abismo já está acesa, sua luz nos guiará de volta para casa——"
  },
  AvgDialog_131204_Content_3 = {Text = "Ding—"},
  AvgDialog_131204_Content_30 = {
    Text = "Que luz quente... Mas, onde está o caminho de volta para casa?"
  },
  AvgDialog_131204_Content_31 = {
    Text = "Você ainda não entende? Minha boa irmã."
  },
  AvgDialog_131204_Content_32 = {
    Text = "Esta roca é o corpo do Apóstolo. Estas luzes são o olhar do Apóstolo — Ele está nos observando"
  },
  AvgDialog_131204_Content_33 = {
    Text = "\"Nefraea\" levantou-se empolgadamente, abrindo os braços."
  },
  AvgDialog_131204_Content_34 = {
    Text = "Apenas é necessário reunir os poderes das três essências, e o apóstolo sem nome despertará aqui"
  },
  AvgDialog_131204_Content_35 = {
    Text = "Ele abrirá para nós o caminho para a suprema Divindade... quando chegar esse momento, <Big:todo sofrimento perecerá, todo esforço em vão chegará ao Fim!>"
  },
  AvgDialog_131204_Content_36 = {
    Text = "\"Nefraea\" puxou repentinamente a máscara de madeira, revelando o rosto vibrante de Nefraea."
  },
  AvgDialog_131204_Content_37 = {
    Text = "Um palco de madeira, bonecos de madeira, o único corpo vivo está no centro do palco, com os braços abertos, desfrutando do olhar daquela única espectadora na plateia."
  },
  AvgDialog_131204_Content_38 = {
    Text = "O portal divino está prestes a se abrir, sua missão está prestes a ser cumprida, você entende, irmã mais velha?"
  },
  AvgDialog_131204_Content_39 = {
    Text = "Você não precisa mais tecer sua rede sem fim, você não precisa mais se descartar"
  },
  AvgDialog_131204_Content_4 = {
    Text = "A mão delicada se estende para o alto, movendo-se suavemente. As cordas do violão tremem levemente, e uma onda elegante se espalha pelo ar."
  },
  AvgDialog_131204_Content_40 = {
    Text = "Reabra-me as portas, tudo bem, Arachne? ... Deixe-me voltar a fazer parte de você..."
  },
  AvgDialog_131204_Content_41 = {
    Text = "As lágrimas arruinaram a maquiagem, deixando marcas negras como a corrosão em seu rosto. Risadas e choros insanos se entrelaçam como uma grande rede, envolvendo esta pessoa, o único ser vivo no palco."
  },
  AvgDialog_131204_Content_42 = {
    Text = "Nefraea agachou-se e levantou a face lisa e sem traços de Arachne. As lágrimas escorriam pelo rosto triste, caindo sobre a máscara sorridente do boneco."
  },
  AvgDialog_131204_Content_43 = {
    Text = "Ela observava atentamente Arachne abaixo do palco, com os lábios trêmulos levemente encostados na orelha do boneco. Sua voz era tão suave, como se estivesse falando apenas para si mesma."
  },
  AvgDialog_131204_Content_44 = {
    Text = "Não me deixe mais para trás... tudo bem?"
  },
  AvgDialog_131204_Content_5 = {
    Text = "As ondas passam pelo brilho prateado, o brilho prateado se dissipa, e a chave de prata, carregando um poderoso poder espiritual, desaparece sem deixar vestígios. As ondas passam pelo corpo, seu corpo se transforma em ossos secos, e o sangue se torna lama. Você se despedaça e, em seguida, se recupera como antes."
  },
  AvgDialog_131204_Content_6 = {
    Text = "Toda força se desfez em nada, todos os pensamentos se dissiparam em cinzas. Onde as ondas chegam, milhares de mundos se transformam em fios nas mãos dela. Incluindo você, você mesmo."
  },
  AvgDialog_131204_Content_7 = {
    Text = "Ela é a dona do teatro.\nEla é o próprio destino."
  },
  AvgDialog_131204_Content_8 = {
    Text = "Arachne, você... você pode controlar meu destino?!..."
  },
  AvgDialog_131204_Content_9 = {
    Text = "O sorriso de Arachne é como um lago tranquilo, você não consegue ver a aparência do lago, na superfície deste lago, você só pode ver seu próprio reflexo."
  },
  AvgDialog_131205_Content_1 = {Text = "Tiro"},
  AvgDialog_131205_Content_10 = {
    Text = "Você não precisa entregar nenhum dever de casa."
  },
  AvgDialog_131205_Content_11 = {
    Text = "Professor Arachne, o que você... quer dizer?"
  },
  AvgDialog_131205_Content_12 = {
    Text = "Ainda se lembra de quem você é e de onde veio?"
  },
  AvgDialog_131205_Content_13 = {
    Text = "Eu? Eu, claro, sou..."
  },
  AvgDialog_131205_Content_14 = {
    Text = "%player%. Um nativo de Havatz dos pés à cabeça. Estudante do primeiro ano na Academia de Artes Dramáticas. Seus pais são funcionários públicos comuns que lhe adoram. Você teve dois romances respeitáveis. Apaixonado, embora não excepcionalmente talentoso, com uma fraqueza por Sachertorte e wraps de carne grelhada."
  },
  AvgDialog_131205_Content_15 = {
    Text = "As memórias antes nítidas de repente se tornam turvas, outra memória salta abruptamente da sua mente. Misaq, Corpo Desperto, Dissolução, Toguwaibo..."
  },
  AvgDialog_131205_Content_16 = {
    Text = "Você arregala os olhos de repente, olhando para aquela mulher do outro lado que está saboreando café."
  },
  AvgDialog_131205_Content_17 = {
    Text = "Não... não é isso... Eu sou o Guardião do Segredo de Misaq... O que está acontecendo?"
  },
  AvgDialog_131205_Content_18 = {
    Text = "Eu me lembrei... nós estávamos no seu teatro, subimos em um palco e então... então..."
  },
  AvgDialog_131205_Content_19 = {
    Text = "Então você pediu chá da tarde ao garçom. Como uma pessoa local, seu gosto é bastante bom."
  },
  AvgDialog_131205_Content_2 = {Text = "Ding——"},
  AvgDialog_131205_Content_20 = {
    Text = "Arachne tomou um gole do líquido marrom na xícara de café e acenou com a cabeça em elogio."
  },
  AvgDialog_131205_Content_21 = {
    Text = "Senhores, os itens de vocês estão todos prontos."
  },
  AvgDialog_131205_Content_22 = {
    Text = "A bandeja nas mãos do garçom exala um aroma intoxicante, enquanto ele se inclina para servir, ele se aproxima discretamente do seu ouvido."
  },
  AvgDialog_131205_Content_23 = {
    Text = "O plano de assassinato vazou. O Duque provavelmente mudará sua rota. O contato irá notificá–lo assim que houver novidades. Prepare–se, %player%."
  },
  AvgDialog_131205_Content_24 = {
    Text = "Uma nova pistola Browning foi colocada discretamente em sua mão. Ao levantar a cabeça novamente, o rosto do garçom recuperou um sorriso amigável, e após fazer uma reverência, ele voltou para a cozinha com a bandeja."
  },
  AvgDialog_131205_Content_25 = {
    Text = "Memórias excessivas se acumulam em sua mente, e você esfrega a testa inchada com um pouco de dor."
  },
  AvgDialog_131205_Content_26 = {
    Text = "Duas memórias diferentes existem em um único cérebro, e para quem experimenta isso pela primeira vez, essa sensação realmente não é muito agradável."
  },
  AvgDialog_131205_Content_27 = {
    Text = "Ainda bem, comparado a enfrentar Toguwaibo, esse nível de dor de cabeça é como uma massagem."
  },
  AvgDialog_131205_Content_28 = {
    Text = "Minha memória diz que estou seguindo as ordens da Mão de Ferro. Em duas horas, devo usar esta arma para assassinar o herdeiro visitante do trono do Império Feo..."
  },
  AvgDialog_131205_Content_29 = {
    Text = "Você acaricia as texturas daquela pistola, organizando na sua mente as memórias que pertencem a este mundo."
  },
  AvgDialog_131205_Content_3 = {
    Text = "As rodas passaram sobre o caminho de pedras irregulares, os sinos raivosos gritaram em direção à enorme multidão do desfile, levantando uma nuvem de poeira e xingamentos."
  },
  AvgDialog_131205_Content_30 = {
    Text = "Antes que você pudesse continuar a perguntar, uma luz forte iluminou o café. Botas militares colidiram com o piso de cimento, chegando à frente do bar."
  },
  AvgDialog_131205_Content_31 = {
    Text = "Olá, senhores policiais, posso perguntar..."
  },
  AvgDialog_131205_Content_32 = {
    Text = "Antes que ele pudesse terminar a frase, um policial se aproximou rapidamente, prendeu suas mãos atrás das costas e pressionou sua cabeça contra o balcão."
  },
  AvgDialog_131205_Content_33 = {
    Text = "Em seus olhos apavorados, uma arma foi apontada para sua testa."
  },
  AvgDialog_131205_Content_34 = {
    Text = "Membro da Assembleia de Restauração, Bosante. Você tem dez segundos para me dizer onde está seu parceiro."
  },
  AvgDialog_131205_Content_35 = {
    Text = "O garçom arqueja em busca de ar, tremendo. Em seu desespero, seus olhos se voltam para o canto da sala."
  },
  AvgDialog_131205_Content_36 = {
    Text = "Mas a mesa que você acabou de ocupar está vazia. Apenas meia xícara de café permanece, seu vapor subindo preguiçosamente no ar."
  },
  AvgDialog_131205_Content_37 = {Text = "..."},
  AvgDialog_131205_Content_38 = {
    Text = "Aqui deve estar seguro por enquanto."
  },
  AvgDialog_131205_Content_39 = {
    Text = "Vocês saem pela porta dos fundos do café, como duas gotas d'água insignificantes, se juntando à multidão barulhenta."
  },
  AvgDialog_131205_Content_4 = {
    Text = "Você acenou com a mão, afastando a poeira que entrava pelas cortinas do café."
  },
  AvgDialog_131205_Content_40 = {
    Text = "Agora, essa situação... o que exatamente são essas memórias diferentes?"
  },
  AvgDialog_131205_Content_41 = {
    Text = "Suba ao palco do teatro do destino e torne-se um personagem nele. Cada personagem possui sua própria vida."
  },
  AvgDialog_131205_Content_42 = {
    Text = "Este mundo está situado em uma dimensão distante, que você nunca ouviu falar e nunca explorou. Mas, como um personagem que cresceu neste mundo, você o conhece como a palma da sua mão."
  },
  AvgDialog_131205_Content_43 = {
    Text = "Bem–vindo a um dos meus palcos, {Male=Mr.,Female=Miss} Guardião."
  },
  AvgDialog_131205_Content_44 = {
    Text = "Você quer dizer que... você consegue conectar outros mundos através do palco?"
  },
  AvgDialog_131205_Content_45 = {
    Text = "Arachne entendeu o significado em seu olhar ardente. Ela levantou a xícara de café que havia levado da loja, cheirando-a atentamente, e balançou a cabeça levemente."
  },
  AvgDialog_131205_Content_46 = {
    Text = "Fugindo com café e bolo, essa coisa estranha não chamou sua atenção nem um pouco. Aconteceu de forma tão harmoniosa com Arachne, como se fosse parte de seu destino."
  },
  AvgDialog_131205_Content_47 = {
    Text = "Lady Daffodil explicou a você os princípios da viagem dimensional. As barreiras entre mundos são incrivelmente sólidas. Cada travessia exige um preço terrível; não é algo que se faça levianamente."
  },
  AvgDialog_131205_Content_48 = {
    Text = "Mas agora não estamos aqui já...?"
  },
  AvgDialog_131205_Content_49 = {
    Text = "O Teatro do destino pode brevemente conectar os destinos de diferentes mundos."
  },
  AvgDialog_131205_Content_5 = {
    Text = "Uma porção de shawarma, uma Sachertorte e duas xícaras de café Havatz. Obrigado."
  },
  AvgDialog_131205_Content_50 = {
    Text = "Atualmente, somos apenas dois personagens perdidos em um mar de pessoas — projeções fugazes que desaparecerão num piscar de olhos."
  },
  AvgDialog_131205_Content_51 = {
    Text = "Projeção... Mesmo que seja uma projeção, você não pode me ajudar a voltar dessa forma..."
  },
  AvgDialog_131205_Content_52 = {
    Text = "Sinto muito, %player%. O portão que você fechou bloqueou o Olhar de Toguwaibo, mas também rompeu os Fios do destino."
  },
  AvgDialog_131205_Content_53 = {
    Text = "Se tentarmos exercer influência lá, enfrentaremos uma catástrofe que não podemos suportar."
  },
  AvgDialog_131205_Content_54 = {
    Text = "Ela olhou para a expressão de desânimo em seu rosto, sorrindo enquanto lhe entregava o bolo do prato."
  },
  AvgDialog_131205_Content_55 = {
    Text = "Fique tranquilo, %player%. Assim que lidarmos com minha irmã, a passagem de volta para Cardas se abrirá novamente."
  },
  AvgDialog_131205_Content_56 = {
    Text = "O destino não desaponta cada espera, e nós também não podemos desapontar cada presente do destino. Prove."
  },
  AvgDialog_131205_Content_57 = {
    Text = "Você respira fundo, pega o bolo e dá uma leve mordida. O sabor doce e aromático faz você quase esquecer o desconforto causado pela colisão de duas memórias diferentes."
  },
  AvgDialog_131205_Content_58 = {
    Text = "Hmm... Dizem que o Duque Flaviano nunca perde a chance de provar o bolo típico local sempre que visita. Para um príncipe herdeiro, ele certamente tem bom gosto."
  },
  AvgDialog_131205_Content_59 = {
    Text = "Então, o que Nefraea influenciou neste mundo? Como devemos corrigir isso..."
  },
  AvgDialog_131205_Content_6 = {
    Text = "Você entregou o menu feito de pergaminho ao garçom, olhando para a rua familiar do lado de fora com desânimo."
  },
  AvgDialog_131205_Content_60 = {
    Text = "Enquanto você falava, Arachne parecia ser atraída por algo, levantando a cabeça para olhar aquelas linhas no céu que você não conseguia ver claramente."
  },
  AvgDialog_131205_Content_61 = {
    Text = "Ela sorriu, bebeu o último gole de café na xícara, entregou algumas moedas e a xícara restante a um garçom que passava, apressando-se de volta ao café, e lhe agradeceu em voz baixa."
  },
  AvgDialog_131205_Content_62 = {
    Text = "Ela nos encontrou. Na hora certa. Cuidado, %player%."
  },
  AvgDialog_131205_Content_63 = {Text = "Bang—"},
  AvgDialog_131205_Content_64 = {
    Text = "Você se inclina instintivamente, e uma bala passa quase raspando o topo da sua cabeça."
  },
  AvgDialog_131205_Content_65 = {Text = "Bem ali"},
  AvgDialog_131205_Content_66 = {
    Text = "É um assassino do Comitê de Restauração Nacional! Prendam-nos"
  },
  AvgDialog_131205_Content_67 = {
    Text = "Liderados por alguns cidadãos que gritam, um enxame de oficiais abre caminho pela multidão para cercá–lo."
  },
  AvgDialog_131205_Content_68 = {
    Text = "Conforme se aproximam, seus corpos começam a se deformar — patas quitinosas e escuras de aranha irrompem de seus torsos, e garras afiadas como navalhas atacam."
  },
  AvgDialog_131205_Content_7 = {
    Text = "Essa rua realmente deveria ser ampliada, quando eu era criança, era assim, além de estar cada vez mais deteriorada, não mudou nada ao longo dos anos."
  },
  AvgDialog_131205_Content_8 = {
    Text = "As autoridades são inúteis para construir qualquer coisa. A única coisa em que são boas é vender as terras de Havatz e servir bolo para a família real."
  },
  AvgDialog_131205_Content_9 = {
    Text = "Refugiados, protestando, insistindo em visitar o duque neste momento... Professor Arachne, posso entregar meu trabalho de pesquisa sobre folclore um pouco mais tarde? As atividades do Comitê de Restauração Nacional têm consumido muita da minha energia recentemente."
  },
  AvgDialog_131206_Content_10 = {
    Text = "Crujido—crujido—os Fios do destino convergem em suas mãos."
  },
  AvgDialog_131206_Content_11 = {
    Text = "As marionetes marcham em fila, adentrando a Grande Teia."
  },
  AvgDialog_131206_Content_12 = {
    Text = "Elas dançam. Elas cantam. Crujido—crujido—"
  },
  AvgDialog_131206_Content_13 = {
    Text = "Morrem junto com a Grande Teia, em silêncio e sem deixar rastro."
  },
  AvgDialog_131206_Content_14 = {
    Text = "Eles morreram silenciosamente junto com a grande rede."
  },
  AvgDialog_131206_Content_15 = {Text = "..."},
  AvgDialog_131206_Content_16 = {
    Text = "A passagem de volta para Cardas foi fechada bem a tempo. {Male=mister,Female=miss} chegou à cidade."
  },
  AvgDialog_131206_Content_17 = {
    Text = "Muito bem. Gostou da nova peça?"
  },
  AvgDialog_131206_Content_18 = {
    Text = "Hmm... talvez seja um pouco complicada demais?"
  },
  AvgDialog_131206_Content_19 = {
    Text = "Histórias simples são mais fáceis de conduzir, sim—mas para certas pessoas, uma história simples não é capaz de conter seu Destino."
  },
  AvgDialog_131206_Content_2 = {
    Text = "A trombeta Dispara um floreio. O guerreiro de capa escura entra."
  },
  AvgDialog_131206_Content_20 = {
    Text = "Emoções intensas, reviravoltas dramáticas, um enredo comovente, um final trágico..."
  },
  AvgDialog_131206_Content_21 = {
    Text = "Esse é o destino que pertence a um \"Herói.\""
  },
  AvgDialog_131206_Content_22 = {
    Text = "Vá em frente; é a sua vez no palco."
  },
  AvgDialog_131206_Content_23 = {
    Text = "A donzela se prostra. No instante em que sua testa toca o chão, seu corpo se estilhaça—carne e pele se dissolvendo em aranhas violeta-pálidas que se espalham por cada canto da sala e desaparecem."
  },
  AvgDialog_131206_Content_24 = {
    Text = "A jovem se prostrou em reverência. No instante em que sua testa tocou o chão, seu corpo se fragmentou em Fissão, e toda a Carne e sangue se transformaram em aranhas lilás que desapareceram pelos cantos do quarto."
  },
  AvgDialog_131206_Content_25 = {Text = "..."},
  AvgDialog_131206_Content_26 = {
    Text = "<Shake:Tosse... tosse, tosse...>"
  },
  AvgDialog_131206_Content_27 = {
    Text = "O que foi aquilo..."
  },
  AvgDialog_131206_Content_28 = {
    Text = "Ah! O portal para Cardas!!"
  },
  AvgDialog_131206_Content_29 = {
    Text = "Você recobra a consciência num estalo, erguendo o olhar para o céu."
  },
  AvgDialog_131206_Content_3 = {
    Text = "Ah, Cardas, a terra natal dos meus sonhos! Enfim, posso retornar!"
  },
  AvgDialog_131206_Content_30 = {
    Text = "O céu está límpido, de um azul brilhante. A luz do sol banha você. Nenhum vestígio do sol negro ou da passagem dimensional permanece."
  },
  AvgDialog_131206_Content_31 = {
    Text = "E-essa pessoa é tão estranha... {Male=he,Female=she} acabou de cair do céu?"
  },
  AvgDialog_131206_Content_32 = {
    Text = "Bem, pelo que eu sei, há uma empresa de tecnologia por perto testando aeronaves. {Male=he,Female=she} provavelmente é um dos pilotos de teste deles."
  },
  AvgDialog_131206_Content_33 = {
    Text = "Bem, pelo que sei, há uma empresa de tecnologia nas redondezas testando aeronaves, {Male=他,Female=她} deve ser um Tester de aeronaves."
  },
  AvgDialog_131206_Content_34 = {Text = "Pessoas."},
  AvgDialog_131206_Content_35 = {
    Text = "Uma multidão densa preenche a sua visão, os seus olhos ainda a arder por causa da luz."
  },
  AvgDialog_131206_Content_36 = {
    Text = "Uma cidade tão movimentada como Londinium traz-lhe de volta memórias distantes de Cardas."
  },
  AvgDialog_131206_Content_37 = {
    Text = "Ruas movimentadas, multidões reunidas, lojas repletas de cor por todo o lado..."
  },
  AvgDialog_131206_Content_38 = {
    Text = "O mundo desta dimensão viu a sua população diminuir drasticamente devido à Dissolução. Nunca testemunhou uma cena tão viva, nem mesmo em Necrópole."
  },
  AvgDialog_131206_Content_39 = {
    Text = "Com licença... onde estou?"
  },
  AvgDialog_131206_Content_4 = {
    Text = "Meus mentores, meus companheiros, meu amigo mais querido, meu... tudo."
  },
  AvgDialog_131206_Content_40 = {
    Text = "Ha, que estranho! Alguém que nunca ouviu falar de Londinium? Esta é a maior cidade do mundo!"
  },
  AvgDialog_131206_Content_41 = {
    Text = "Ha, estranho, como pode haver alguém que nunca ouviu falar do nome de Londinium? Esta é a cidade mais grandiosa do mundo"
  },
  AvgDialog_131206_Content_42 = {
    Text = "<Shake:!!!>"
  },
  AvgDialog_131206_Content_43 = {
    Text = "Tem a certeza de que ouviu aquelas palavras."
  },
  AvgDialog_131206_Content_44 = {
    Text = "A sua mente enevoada clareia num instante. Levanta-se de um salto e observa tudo à sua volta."
  },
  AvgDialog_131206_Content_45 = {
    Text = "Interseção Brick. As letras desgastadas na placa da interseção são exatamente como se lembra."
  },
  AvgDialog_131206_Content_46 = {
    Text = "Livraria de livros antigos do Tempo Dobrada. Sempre que fugia da escola, a sua coisa favorita era esconder-se aqui e perder-se em romances policiais."
  },
  AvgDialog_131206_Content_47 = {
    Text = "Mercearia do Mercado Fragrante... onde o Professor Dexter sempre lhe pedia para trazer uma garrafa de gin. O pequeno truque do N."
  },
  AvgDialog_131206_Content_48 = {
    Text = "Estufa do Orvalho da Manhã. No aniversário do seu primeiro ano como Guardião, Ramona tinha planeado encomendar-lhe aqui o ramo mais vibrante de toda Londinium..."
  },
  AvgDialog_131206_Content_49 = {
    Text = "Casa das Flores de Orvalho. Na celebração do seu primeiro aniversário como Guardião do Segredo, Ramona pretendia encomendar aqui um buquê das flores mais vibrantes de Londinium para você..."
  },
  AvgDialog_131206_Content_5 = {
    Text = "Assim que eu atravessar este portal sombrio, me reunirei com eles mais uma vez!"
  },
  AvgDialog_131206_Content_50 = {Text = "..."},
  AvgDialog_131206_Content_51 = {
    Text = "Com licença... com licença, o que aconteceu a Misaq?!"
  },
  AvgDialog_131206_Content_52 = {
    Text = "Misaq? Nunca ouvimos falar de tal lugar, {Male=sir,Female=miss}."
  },
  AvgDialog_131206_Content_53 = {
    Text = "E a Dissolução? Com que gravidade atingiu este lugar?!"
  },
  AvgDialog_131206_Content_54 = {
    Text = "Disso... o quê? Esta cidade nunca sofreu nada do género."
  },
  AvgDialog_131206_Content_55 = {
    Text = "Jovem {Male=sir,Female=lady}, acho que está apenas cansado e um pouco confuso... Sente-se naquele banco e coma alguma coisa. Por acaso tenho um pouco comigo."
  },
  AvgDialog_131206_Content_56 = {
    Text = "O ancião estende o pão e a água que acabou de comprar na mercearia."
  },
  AvgDialog_131206_Content_57 = {
    Text = "Ah, muito obrigado... Mas não tenho fome agora, eu só... tenho algumas coisas que não consigo compreender..."
  },
  AvgDialog_131206_Content_58 = {
    Text = "Isto não pode estar certo... Nenhum Misaq, nenhuma Fusão..."
  },
  AvgDialog_131206_Content_59 = {
    Text = "<Small:Isso é impossível... sem Misaq, e sem Dissolução...>"
  },
  AvgDialog_131206_Content_6 = {
    Text = "Então por que esta porta, tão perto ao alcance, está trancada? Por que este céu cruel me abandonou?"
  },
  AvgDialog_131206_Content_60 = {
    Text = "Não é bonito dizer isso. {Male=he,Female=she} pode estar passando por algo difícil. Tenha bons modos com visitantes que vieram de longe."
  },
  AvgDialog_131206_Content_61 = {
    Text = "Uma mão toca gentilmente no seu ombro. Você se vira e encontra um rosto desconhecido."
  },
  AvgDialog_131206_Content_62 = {
    Text = "Somos patrulheiros da área, sob a jurisdição da Reunião de revisão do Acordo de Misdia. Aqui está minha identificação."
  },
  AvgDialog_131206_Content_63 = {
    Text = "Bom dia. Um cidadão gentil nos informou que um viajante se perdeu em nossa bela cidade."
  },
  AvgDialog_131206_Content_64 = {
    Text = "Há algo em que possamos ajudá-lo, {Male=sir,Female=miss}?"
  },
  AvgDialog_131206_Content_65 = {
    Text = "Você para um breve momento para pensar. Até entender o que está acontecendo, é melhor chamar o mínimo de atenção possível."
  },
  AvgDialog_131206_Content_66 = {
    Text = "Você tira um breve momento para pensar. Até entender o que está acontecendo, é melhor chamar o mínimo de atenção possível."
  },
  AvgDialog_131206_Content_67 = {
    Text = "Obrigado a vocês dois. Temos coisas a resolver, então vamos indo..."
  },
  AvgDialog_131206_Content_68 = {
    Text = "Entendo. Nesse caso, se não se importar — gostaria de tomar só mais um pouco do seu tempo. Há algumas coisas que gostaria de perguntar."
  },
  AvgDialog_131206_Content_69 = {
    Text = "O oficial se aproxima de você com um sorriso, tirando a poeira do seu ombro"
  },
  AvgDialog_131206_Content_7 = {
    Text = "Minha querida Chave de prata... ilumine meu caminho... conceda-me ao menos um fragmento de resposta..."
  },
  AvgDialog_131206_Content_70 = {
    Text = "Guardião — é assim que devo chamá-lo, não é?"
  },
  AvgDialog_131206_Content_71 = {
    Text = "<Red:Guardião>, devo chamá-lo assim, certo?"
  },
  AvgDialog_131206_Content_72 = {
    Text = "Gostaria de perguntar... você ficou satisfeito com esta cerimônia de boas-vindas em sua homenagem?"
  },
  AvgDialog_131206_Content_73 = {
    Text = "Um som nauseante e úmido de dilaceração se ergue no ar. Enormes patas de aranha irrompem pelos corpos dos oficiais e dos transeuntes, espirrando sangue espesso com cheiro de ferro por todo você."
  },
  AvgDialog_131206_Content_74 = {
    Text = "Um som nauseante de rasgo úmido ecoa no ar. Patas massivas de aranha irrompem pelos corpos dos oficiais e transeuntes, espirrando sangue espesso com cheiro de ferro sobre você."
  },
  AvgDialog_131206_Content_75 = {
    Text = "Nosso ilustre convidado chegou ao teatro. Levem {Male=him,Female=her} ao {Male=his,Female=her} assento, meus filhos."
  },
  AvgDialog_131206_Content_76 = {
    Text = "Sim, minha senhora."
  },
  AvgDialog_131206_Content_77 = {Text = "Cuidado!!"},
  AvgDialog_131206_Content_78 = {Text = "Cuidado!!"},
  AvgDialog_131206_Content_8 = {
    Text = "As luzes mudam. A Cantora de Prata sobe ao palco."
  },
  AvgDialog_131206_Content_9 = {
    Text = "Crujido—crujido—a Deusa do Destino gira Sua roda de fiar."
  },
  AvgDialog_131207_Content_1 = {
    Text = "Reflexo Divino"
  },
  AvgDialog_131207_Content_10 = {
    Text = "Você ainda tem a chance de parar, Nefraea."
  },
  AvgDialog_131207_Content_11 = {
    Text = "Desaparecer completamente, e então?"
  },
  AvgDialog_131207_Content_12 = {
    Text = "Nefraea sorriu de forma leviana e virou-se para aqueles Servidores de devoção."
  },
  AvgDialog_131207_Content_13 = {
    Text = "Diga-me, crianças, vocês estão com medo?"
  },
  AvgDialog_131207_Content_14 = {
    Text = "A resposta de Arachne foi uma risada desesperada."
  },
  AvgDialog_131207_Content_15 = {
    Text = "Hahahaha! Nós somos aqueles abandonados pelo destino, nenhuma catástrofe nos fará temer... Por favor, traga-nos a libertação, meu mestre."
  },
  AvgDialog_131207_Content_16 = {
    Text = "Bom garoto."
  },
  AvgDialog_131207_Content_17 = {
    Text = "Nefraea favoreiramente deu um tapinha na cabeça do Servidor."
  },
  AvgDialog_131207_Content_18 = {
    Text = "Você está enganada, minha boa irmã. O destino já nos condenou à pena de morte e ao encarceramento eterno. Um grupo de almas abandonadas não pedirá mais a misericórdia do destino."
  },
  AvgDialog_131207_Content_19 = {
    Text = "Nós estamos nos vingando do destino."
  },
  AvgDialog_131207_Content_2 = {
    Text = "Em um grande palco que você nunca viu, a roda de fuso negra de Nefraea ergue-se solitariamente no centro do palco. No meio do imenso anel, uma luz azulada que parece nunca se apagar ilumina o rosto alegre de Nefraea."
  },
  AvgDialog_131207_Content_20 = {
    Text = "Não sei se foi por acaso ou de propósito, mas uma das linhas do destino que Nefraea manipulava se quebrou silenciosamente."
  },
  AvgDialog_131207_Content_21 = {
    Text = "No momento em que a linha se rompe, um palco não muito distante de vocês explode em fragmentos, se aniquilando no infinito espaço dimensional do teatro."
  },
  AvgDialog_131207_Content_22 = {
    Text = "Ai, desculpe, desculpe, acidentalmente estraguei seu fio..."
  },
  AvgDialog_131207_Content_23 = {
    Text = "Vá em frente, boa irmã. Embora haja muitos palcos no teatro, se você quebrar mais, você também vai ficar triste, não é?"
  },
  AvgDialog_131207_Content_24 = {
    Text = "O suspiro de Arachne é quase inaudível. Quando ela abre os olhos novamente, ela levanta a ponta dos dedos e toca levemente o seu topo da cabeça."
  },
  AvgDialog_131207_Content_25 = {
    Text = "Arachne! Não faça isso... Com certeza podemos encontrar outra maneira..."
  },
  AvgDialog_131207_Content_26 = {
    Text = "Suba ao palco. Ofereça a Ordem de peso dos plásmidos ao Apóstolo... Este é o seu destino inescapável, {Male=Mr.,Female=Miss} Guardião."
  },
  AvgDialog_131207_Content_27 = {
    Text = "A voz irresistível de Arachne ecoa em seu mundo espiritual. Quando você levanta os pés para subir ao palco, três forças há muito esquecidas começam a agitar-se dentro de você."
  },
  AvgDialog_131207_Content_28 = {
    Text = "Eles se entrelaçam e colidem dentro de você, lutando contra as palavras proféticas de Arachne."
  },
  AvgDialog_131207_Content_29 = {
    Text = "Ai, não é à toa que são os três plásmidos... Com tão pouco poder, em dimensões tão distantes, ainda conseguem afetar o anfitrião."
  },
  AvgDialog_131207_Content_3 = {
    Text = "Olhe, {Male=Mr.,Female=Miss} Guardião, que luzes lindas..."
  },
  AvgDialog_131207_Content_30 = {
    Text = "Faça-os se comportarem, {Male=Mr.,Female=Miss} Guardião."
  },
  AvgDialog_131207_Content_4 = {
    Text = "Esta luz é um presente do destino, que nos guiará para o Éden, um lugar sem dor..."
  },
  AvgDialog_131207_Content_5 = {
    Text = "Nefraea estendeu a mão, acariciando as marcas deixadas pela luz no espaço dimensional. A sombra dos dedos lentamente se fechou, se contorcendo no rosto de Arachne."
  },
  AvgDialog_131207_Content_6 = {
    Text = "Venha, irmã, nosso protagonista deve entrar em cena."
  },
  AvgDialog_131207_Content_7 = {
    Text = "......destino não é algo que pode ser brincado ou manipulado, Nefraea."
  },
  AvgDialog_131207_Content_8 = {
    Text = "Cada destino já está selado. Se você despertar aquela divindade e deixar tudo acabar... alterar o Destino à força trará uma catástrofe além da sua imaginação."
  },
  AvgDialog_131207_Content_9 = {
    Text = "Seja o que você despreza ou o que você preza, tudo desaparecerá no apocalipse."
  },
  AvgDialog_131208_Content_1 = {Text = "Julgamento"},
  AvgDialog_131208_Content_10 = {
    Text = "A menina respirou fundo e sorriu satisfeita."
  },
  AvgDialog_131208_Content_11 = {
    Text = "As íris já começaram a florescer... mais uma primavera realmente chegou."
  },
  AvgDialog_131208_Content_12 = {
    Text = "Ei, Xiaofu, eu já te perguntei qual é a sua estação favorita?"
  },
  AvgDialog_131208_Content_13 = {
    Text = "... eu não tenho nenhuma estação favorita, mestre."
  },
  AvgDialog_131208_Content_14 = {Text = "Chato."},
  AvgDialog_131208_Content_15 = {
    Text = "Arachne revirou os olhos, estendeu a mão que não tinha fio de tecelagem e apanhou a luz do sol que entrava pela janela."
  },
  AvgDialog_131208_Content_16 = {
    Text = "Eu amo todas as estações, especialmente a primavera. Faz tanto tempo que saímos de casa... devíamos encontrar tempo para fazer uma trilha?"
  },
  AvgDialog_131208_Content_17 = {
    Text = "Ao lado da mansão onde nasci, há um jardim muito bem cuidado que vocês certamente vão gostar."
  },
  AvgDialog_131208_Content_18 = {
    Text = "Você já esperou três dias... É hora de tomar uma decisão, meu senhor."
  },
  AvgDialog_131208_Content_19 = {
    Text = "A servente cumpre seu dever, palavras frias como uma chuva gelada. Apagam a primavera radiante nos olhos de Arachne."
  },
  AvgDialog_131208_Content_2 = {
    Text = "Crujido—crujido—os Fios do destino convergem em suas mãos."
  },
  AvgDialog_131208_Content_20 = {
    Text = "Guinch, guinch..."
  },
  AvgDialog_131208_Content_21 = {
    Text = "Depois de uma pausa, a roca começou a girar novamente. Sua frequência é suave, clara e imutável desde a antiguidade."
  },
  AvgDialog_131208_Content_22 = {
    Text = "O reino em que estamos acaba de terminar um século de guerra. As pessoas reconstruíram suas cidades sobre as ruínas, aguardando que lhes venha um longo período de paz."
  },
  AvgDialog_131208_Content_23 = {
    Text = "Olha, ali......"
  },
  AvgDialog_131208_Content_24 = {
    Text = "Seguindo o olhar de Arachne, a servente olhou para uma enorme pintura pendurada no salão. Ela nunca conseguiu entender aquela pintura."
  },
  AvgDialog_131208_Content_25 = {
    Text = "Entre todas as grandes obras do Sr. Zoss, esta pintura é a que menos atenção recebe, mas é a minha favorita."
  },
  AvgDialog_131208_Content_26 = {
    Text = "Estes cervos, pintados em ocre e formas geométricas... mesmo como símbolos abstratos, pulsam com vida."
  },
  AvgDialog_131208_Content_27 = {
    Text = "Toda vez que a vejo, lembro-me da minha peça favorita..."
  },
  AvgDialog_131208_Content_28 = {
    Text = "A fenda já existe há três dias, Senhor. O destino desta dimensão já foi afetado pelo olhar daquela divindade."
  },
  AvgDialog_131208_Content_29 = {
    Text = "Se continuar assim, o lugar que Seu olhar vai destruir será muito mais do que aqui."
  },
  AvgDialog_131208_Content_3 = {
    Text = "As marionetes marcham em fila, adentrando a Grande Teia."
  },
  AvgDialog_131208_Content_30 = {
    Text = "Guinch, guinch."
  },
  AvgDialog_131208_Content_31 = {
    Text = "A menina fechou os olhos, desfrutando o toque do sol. O quarto quente caiu em silêncio, apenas a roca continuava a girar com a frequência ancestral."
  },
  AvgDialog_131208_Content_32 = {
    Text = "Você ainda se lembra de quantos destinos de mundos já tecemos?"
  },
  AvgDialog_131208_Content_33 = {
    Text = "Um total de vinte e sete, mestre."
  },
  AvgDialog_131208_Content_34 = {
    Text = "Depois que meu pai me deu esta roda de fiar, eu segui suas linhas e me aproximei da porta da verdade. Por trás da porta, vi o destino que este mundo está prestes a enfrentar..."
  },
  AvgDialog_131208_Content_35 = {
    Text = "Eu sei o que está me esperando à frente. Eu sei que tipo de escolha eu devo fazer... mas eu não consigo."
  },
  AvgDialog_131208_Content_36 = {
    Text = "Parentes. Amigos. Memórias. Dezessete mil anos de história grandiosa. Tecnologia e arte como estrelas brilhantes..."
  },
  AvgDialog_131208_Content_37 = {
    Text = "Depois de ver aquela resposta, comecei a tecer o destino deste mundo... Sempre pensei que, dado que o destino me concedeu essa habilidade, eu poderia fazer algo por este mundo."
  },
  AvgDialog_131208_Content_38 = {
    Text = "Este é meu lar. Minha criança. <Shake:Eu... Eu não consigo>, Xiaofu..."
  },
  AvgDialog_131208_Content_39 = {Text = "Mestre..."},
  AvgDialog_131208_Content_4 = {
    Text = "Elas dançam. Elas cantam. Crujido—crujido—"
  },
  AvgDialog_131208_Content_40 = {
    Text = "A servente se agachou e enxugou as lágrimas da senhora. Sob o sol da primavera, sua voz era clara e firme."
  },
  AvgDialog_131208_Content_41 = {
    Text = "Você previu este dia, então você me fez sua servente."
  },
  AvgDialog_131208_Content_42 = {
    Text = "Todo o significado da minha vida é, neste momento, dizer-lhe o que deve fazer..."
  },
  AvgDialog_131208_Content_43 = {
    Text = "Você é o mestre do destino, o guardião dessas muitas dimensões. Este é um caminho cruel, mas você já fez sua escolha."
  },
  AvgDialog_131208_Content_44 = {
    Text = "As Três Deusas do Destino, responsáveis por tecer, medir... e cortar."
  },
  AvgDialog_131208_Content_45 = {
    Text = "A partir do momento em que você faz sua escolha, essas se tornam as responsabilidades que você está destinado a cumprir."
  },
  AvgDialog_131208_Content_46 = {
    Text = "Arachne levantou a cabeça, e em seus olhos turvos, a fenda que os mortais não podiam ver brilhava no horizonte. Ela sempre esteve lá, ao lado daquela luz quente do sol da primavera, como um sorriso cruel."
  },
  AvgDialog_131208_Content_47 = {
    Text = "A fenda sussurrou para Arachne, contando-lhe sobre aqueles futuros gelados. Ela já havia aceitado essa maldição há muito tempo, e quando a chegada do futuro ocorreu, seu corpo ainda tremia de medo."
  },
  AvgDialog_131208_Content_48 = {
    Text = "Arachne sentou-se novamente diante do tear. Após o medo e o desespero, seu rosto apresentava um rubor não saudável."
  },
  AvgDialog_131208_Content_49 = {
    Text = "Ela acaricia os fios densos e emaranhados como se acariciasse o rosto de uma criança."
  },
  AvgDialog_131208_Content_5 = {
    Text = "Morrem junto com a Grande Teia, em silêncio e sem deixar rastro."
  },
  AvgDialog_131208_Content_50 = {
    Text = "No ano 804, antes mesmo de eu conseguir falar, nosso mordomo tocou uma peça ao piano."
  },
  AvgDialog_131208_Content_51 = {
    Text = "<Italic:\"Funeral do Rio Loás\"> de Elysion. A música era como uma fonte fluindo diante de um templo. Vi até os deuses pararem para ouvir..."
  },
  AvgDialog_131208_Content_52 = {
    Text = "Um fio foi cortado silenciosamente. Ele flutua tranquilamente no ar, balançando silenciosamente nas réplicas do destino."
  },
  AvgDialog_131208_Content_53 = {
    Text = "A música no salão se apagou, apenas o fonógrafo continua a girar. As ranhuras do disco foram preenchidas, e o nome da canção, escrito em letras cursivas bonitas, foi borrado."
  },
  AvgDialog_131208_Content_54 = {
    Text = "Elysion encontrou outro destino. Neste mundo solitário, sua vida grandiosa nunca existiu."
  },
  AvgDialog_131208_Content_55 = {
    Text = "Cassandra, a igreja que ela projetou é mais digna de admiração do que as divindades que nela habitam..."
  },
  AvgDialog_131208_Content_56 = {
    Text = "Mais um fio se rompe. A duzentos quilômetros de distância, a magnífica catedral se despedaça e desmorona, os olhos piedosos da estátua se quebram, tornando-se indistinguíveis da poeira."
  },
  AvgDialog_131208_Content_57 = {
    Text = "As fábulas de Monlin, a ópera de Aldo, as pinturas de Malmo, a poesia de Rovel..."
  },
  AvgDialog_131208_Content_58 = {
    Text = "Os livros se transformam em pedaços de papel, as esculturas em fragmentos, e as pinturas em cores desordenadas."
  },
  AvgDialog_131208_Content_59 = {
    Text = "Ela é uma repórter renomada. Ela é a executora. Ela recita o nome de cada grande artista deste mundo, cortando o fio que lhes pertence."
  },
  AvgDialog_131208_Content_6 = {
    Text = "A luz do sol ilumina seus rostos, que alegria —"
  },
  AvgDialog_131208_Content_60 = {
    Text = "Vilderburgo, uma grandiosa cidade pertencente aos heróis. Ela passou por cento e cinco batalhas, foi destruída e reconstruída trinta e sete vezes, e vinte e um grandes senhores aqui realizaram feitos, sucumbindo em batalha."
  },
  AvgDialog_131208_Content_61 = {
    Text = "Os nobres cantam aqui, os pobres gritam aqui, os poetas deixaram belos versos para isso, as canções à beira do rio Nerl e o som dos canhões ecoam acima dele. Sua história heroica termina hoje."
  },
  AvgDialog_131208_Content_62 = {
    Text = "Um grupo de fios cortados flutua desordenadamente, como uma dança frenética. A duzentos e trinta quilômetros de distância, a grandiosa cidade desmoronou com estrondo."
  },
  AvgDialog_131208_Content_63 = {
    Text = "Uma civilização antiga que sobreviveu por dezessete mil anos, resistindo com dificuldade a desastres naturais e calamidades humanas, sem nunca cair..."
  },
  AvgDialog_131208_Content_64 = {
    Text = "Fraqueza, tremendo. Arachne levantou a mão com todas as suas forças, segurando as vastas linhas de seda à sua frente."
  },
  AvgDialog_131208_Content_65 = {
    Text = "O fio se rompeu. A enorme e antiga nação, que carregava a civilização humana e nunca havia se extinguido, desapareceu assim na história da humanidade, como uma fumaça azul."
  },
  AvgDialog_131208_Content_66 = {Text = "..."},
  AvgDialog_131208_Content_67 = {
    Text = "Homem. Arte. Cidade. Nação. Civilização."
  },
  AvgDialog_131208_Content_68 = {
    Text = "Tudo está desmoronando, tudo está desaparecendo."
  },
  AvgDialog_131208_Content_69 = {
    Text = "<Shake:Está vendo, Xiaofu?> Minha primeira criança está morta... Eu a matei com minhas próprias mãos."
  },
  AvgDialog_131208_Content_7 = {
    Text = "Guinch, guinch."
  },
  AvgDialog_131208_Content_70 = {
    Text = "As lágrimas caem tranquilamente. Arachne sorri fracamente, olhando para fora da janela. No meio das ruínas do mundo, apenas aquela mansão instável do lado de fora ainda permanece de pé."
  },
  AvgDialog_131208_Content_71 = {
    Text = "Eu costumava pensar que, ao tecer o destino, se eu pudesse sempre olhar para o lugar onde eu costumava viver, isso me faria sentir menos sozinho neste Caminho."
  },
  AvgDialog_131208_Content_72 = {
    Text = "É realmente infantil... Para um carrasco sem escolha, preparei pessoalmente a punição mais cruel para mim mesmo."
  },
  AvgDialog_131208_Content_73 = {
    Text = "Ela estendeu a mão, puxando aquele fio nebuloso em sua cabeça, que ela também não conseguia ver claramente, conectando uma parte dele à última linha de fio deste mundo."
  },
  AvgDialog_131208_Content_74 = {
    Text = "Senhor, o que é isso...?"
  },
  AvgDialog_131208_Content_75 = {
    Text = "O romantismo traz lentidão, a bondade traz fragilidade, as memórias trazem dor..."
  },
  AvgDialog_131208_Content_76 = {
    Text = "Eu pensei bem, Xiao Fu. Eu sou o executor amaldiçoado, aquelas coisas belas não deveriam existir em mim."
  },
  AvgDialog_131208_Content_77 = {
    Text = "Você vai... extinguir uma parte de si mesma? Mas essas são as partes que você mais preza — como pode..."
  },
  AvgDialog_131208_Content_78 = {
    Text = "Quando eu era muito, muito pequeno, eu tive o meu primeiro sonho."
  },
  AvgDialog_131208_Content_79 = {
    Text = "Arachne estendeu a mão e agarrou aquele raio de sol que iluminava as intermináveis ruínas."
  },
  AvgDialog_131208_Content_8 = {
    Text = "A antiga roda de fiar emite um acompanhamento suave, enquanto a menina senta-se à frente da roca, cantando uma canção de melodia simples."
  },
  AvgDialog_131208_Content_80 = {
    Text = "No sonho, estou caminhando sobre a superfície de um lago. Ao meu redor, há ruínas e ossos sem fim, enquanto abaixo da superfície do lago, o reflexo da minha infância caminha em um belo reino."
  },
  AvgDialog_131208_Content_81 = {
    Text = "Sem morte, sem sofrimento, sem esquecimento. A suave luz do sol brilha eternamente lá, a multidão canta ao seu lado, sem parar..."
  },
  AvgDialog_131208_Content_82 = {
    Text = "Não consigo ver para onde meu fio leva, mas acho que agora vejo claramente o destino que aquele sonho pressagiava."
  },
  AvgDialog_131208_Content_83 = {
    Text = "Ela se esforçou para mover os cantos da boca, talvez para sua servente, ou talvez para alguma outra coisa."
  },
  AvgDialog_131208_Content_84 = {
    Text = "A mãe disse que, ao inverter o nome Arachne, se lê Nefraea. Na lenda deste mundo, é o nome da deusa da primavera."
  },
  AvgDialog_131208_Content_85 = {
    Text = "Eu gosto de todas as estações, especialmente da primavera. A primavera é muito menor do que o destino, muito, muito menor. Mas o destino sempre leva à morte, enquanto a primavera, a primavera só traz novo nascido..."
  },
  AvgDialog_131208_Content_86 = {
    Text = "Ela olha pela janela. Dos lados da moldura da janela, o destino e a primavera se encaram pela última vez."
  },
  AvgDialog_131208_Content_87 = {
    Text = "Deixe-me, meu reflexo, minha querida irmã. Junto com todas as nossas qualidades maravilhosas e todas as nossas boas memórias."
  },
  AvgDialog_131208_Content_88 = {
    Text = "Destino... Eu ofereço uma parte de mim como sacrifício total a você. Eu trilharei este caminho árduo no lugar dela."
  },
  AvgDialog_131208_Content_89 = {
    Text = "Arachne acariciava suavemente os fios entrelaçados. Os fios tremiam levemente, como se estivessem lutando e chorando."
  },
  AvgDialog_131208_Content_9 = {
    Text = "Um raio de sol atravessa a janela, iluminando uma placa gravada com \"Moira\" ao lado da roda."
  },
  AvgDialog_131208_Content_90 = {
    Text = "As lágrimas dela atravessaram o fio, pingando na placa de \"Moirai\"."
  },
  AvgDialog_131208_Content_91 = {
    Text = "Você está livre, \"Arachne\"."
  },
  AvgDialog_131208_Content_92 = {Text = "Chiado."},
  AvgDialog_131208_Content_93 = {
    Text = "O fio se rompe. Sob o calor suave do sol da primavera, a roda de fiar emitiu seu último suspiro."
  },
  AvgDialog_131209_Content_1 = {Text = "Reencontro"},
  AvgDialog_131209_Content_10 = {
    Text = "Se eu escolher ser uma atriz de ópera, a fila para comprar ingressos no teatro certamente se estenderá por mais de três quarteirões."
  },
  AvgDialog_131209_Content_11 = {
    Text = "Infelizmente, os fantoches de Londinium não tiveram a oportunidade de ver a minha magnífica apresentação. Olhando assim, você é realmente sortudo, meu querido."
  },
  AvgDialog_131209_Content_12 = {
    Text = "Nefraea acariciou suavemente o rosto da menina, como uma mãe que ama carinhosamente sua filha."
  },
  AvgDialog_131209_Content_13 = {
    Text = "No centro do salão da igreja, pregos atravessavam o peito, os ombros, as tíbias e as palmas da menina, perfurando cada parte de seu corpo que favorecia a suspensão e a percepção da dor, pregando-a firmemente em um enorme suporte de lâmpada em forma de roda."
  },
  AvgDialog_131209_Content_14 = {
    Text = "Nefraea levou as mãos ensanguentadas até a ponta do nariz, fechando os olhos em um êxtase obcecado."
  },
  AvgDialog_131209_Content_15 = {
    Text = "Ah... o sabor da vida, quão vibrante."
  },
  AvgDialog_131209_Content_16 = {
    Text = "Nestes anos, eu tentei muitas vezes, mordendo os corpos das crianças, mordendo meu próprio corpo, mas não consegui sentir nem um pouco do sabor da vida."
  },
  AvgDialog_131209_Content_17 = {
    Text = "O destino correto. Uma vida ardente. Que inveja... Mas você sabe? Você deveria, assim como nós, ter sido jogado na pilha de lixo do destino."
  },
  AvgDialog_131209_Content_18 = {
    Text = "Você não precisa comer, nunca fala. Além das memórias guardadas por ela, você não tem nada, não sabe de nada."
  },
  AvgDialog_131209_Content_19 = {
    Text = "O destino já te abandonou, pobrezinha. Você é apenas uma boneca para ela se confortar, uma guardiã das memórias dela, vagando solitariamente neste palco hipócrita..."
  },
  AvgDialog_131209_Content_2 = {
    Text = "<Shake:La...♪ La la...♪>"
  },
  AvgDialog_131209_Content_20 = {
    Text = "Ela olhou para a menina que quase não respirava, a voz sussurrante tremia de tristeza, e os dedos frios arrumavam suavemente os cabelos desordenados na têmpora da menina."
  },
  AvgDialog_131209_Content_21 = {
    Text = "Agora, sua cruel mãe destino está chegando... Não importa o que aconteça, enfrente tudo da forma mais bela possível, entendeu, querido?"
  },
  AvgDialog_131209_Content_22 = {Text = "..."},
  AvgDialog_131209_Content_23 = {
    Text = "Depois que seus olhos se adaptaram à luz sombria da igreja, o que mais chama sua atenção é um conjunto de enormes murais."
  },
  AvgDialog_131209_Content_24 = {
    Text = "Tinta viscosa é espalhada nas paredes de dezenas de metros de altura, estendendo-se sem fim na escuridão indetectável. Imponente, sagrada, suja, como uma estátua de um salvador erguida em um esgoto."
  },
  AvgDialog_131209_Content_25 = {
    Text = "A anfitriã compreensiva limpou o espaço para os visitantes, e na igreja vazia só ecoavam os passos e a respiração. Você se aproximou do grande mural e levantou a cabeça para olhar."
  },
  AvgDialog_131209_Content_26 = {
    Text = "Uma mulher está sentada diante da roda de fiar, cortando o fio de seda com uma tesoura... Este mural é uma pintura sua?"
  },
  AvgDialog_131209_Content_27 = {
    Text = "Parece realmente assim... Acho que isso é o que minha irmã queria nos contar."
  },
  AvgDialog_131209_Content_28 = {
    Text = "Arachne não estava apressada para encontrar o local das \"Memórias\". Ela seguiu seus passos, observando com interesse essas pinturas murais."
  },
  AvgDialog_131209_Content_29 = {
    Text = "Uma silhueta idêntica deixou a mulher sentada e caiu na escuridão do buraco..."
  },
  AvgDialog_131209_Content_3 = {
    Text = "Crujido—crujido—os Fios do destino convergem em suas mãos."
  },
  AvgDialog_131209_Content_30 = {
    Text = "Na caverna escura, uma mulher e outras criaturas da noite executam uma dança estranha. Ela segura... uma roda de fiar?"
  },
  AvgDialog_131209_Content_31 = {
    Text = "O centro brilha como uma Lanterna, iluminando as sombras."
  },
  AvgDialog_131209_Content_32 = {
    Text = "Uma mulher com uma lanterna em forma de roda de fuso chegou à cidade... Um grupo de pessoas vestidas com robes sagrados se ajoelhou diante da mulher e da lanterna. O que estava gravado em suas roupas... era o símbolo da lanterna?"
  },
  AvgDialog_131209_Content_33 = {
    Text = "Ele tem algumas diferenças sutis em relação ao símbolo da lanterna que você viu antes, com um círculo semelhante a uma roda de fiação ao redor do triângulo invertido maligno."
  },
  AvgDialog_131209_Content_34 = {
    Text = "Mas você entendeu cada elemento daquele símbolo. Você sabe claramente que é o símbolo da Igreja da Lanterna, que é o nascimento da Igreja da Lanterna."
  },
  AvgDialog_131209_Content_35 = {
    Text = "Última pintura..."
  },
  AvgDialog_131209_Content_36 = {
    Text = "A última pintura mural está de pé no final do corredor, como uma porta que separa o destino. A tinta suja ondula na pintura mural, refletindo as sombras turvas dentro da igreja."
  },
  AvgDialog_131209_Content_37 = {
    Text = "Uma mulher segura uma Lanterna, ajoelhada diante de uma figura borrada. Atrás deles se ergue algo enorme..."
  },
  AvgDialog_131209_Content_38 = {Text = "Ugh..."},
  AvgDialog_131209_Content_39 = {
    Text = "Quando você reconhece aquele enorme globo ocular que ainda não se abriu, uma onda familiar de dor aguda atinge você, levantando ondas turbulentas em seu espaço mental."
  },
  AvgDialog_131209_Content_4 = {
    Text = "As marionetes marcham em fila, adentrando a Grande Teia."
  },
  AvgDialog_131209_Content_40 = {
    Text = "Você rapidamente desvia o olhar e respira fundo para conter a onda crescente de náusea."
  },
  AvgDialog_131209_Content_41 = {
    Text = "<Shake:Huff... huff...> Os Portadores de Luz... Toguwaibo..."
  },
  AvgDialog_131209_Content_42 = {
    Text = "Neste dimensão, Nefraea na verdade... é a criadora da Igreja da Lanterna"
  },
  AvgDialog_131209_Content_43 = {
    Text = "Entendo... agora eu entendi!"
  },
  AvgDialog_131209_Content_44 = {
    Text = "Você viu a verdade, {Male=Mr.,Female=Miss} Guardião. Quando a Divindade Suprema se aproximava de seu despertar, minha irmã abandonada escapou do Abismo."
  },
  AvgDialog_131209_Content_45 = {
    Text = "Ela interferiu na minha visão, escondendo essa seita sob meu palco."
  },
  AvgDialog_131209_Content_46 = {
    Text = "Aquela pessoa que ela reverencia é o apóstolo que conecta este dimensão àquela divindade suprema."
  },
  AvgDialog_131209_Content_47 = {
    Text = "Você olha novamente para a sombra difusa que se conecta a Toguwaibo na muralha."
  },
  AvgDialog_131209_Content_48 = {
    Text = "Eu entendi... Nefraea quer fazer, é confiar na força daquela pessoa Apóstolo para restabelecer a conexão com Toguwaibo!..."
  },
  AvgDialog_131209_Content_49 = {
    Text = "Mas se é assim, por que ela quer caçar aqueles segredos...?"
  },
  AvgDialog_131209_Content_5 = {
    Text = "Elas dançam. Elas cantam. Crujido—crujido—"
  },
  AvgDialog_131209_Content_50 = {Text = "Dong—"},
  AvgDialog_131209_Content_51 = {
    Text = "Um som turvo de sino ecoou da torre da igreja, como um decreto sujo."
  },
  AvgDialog_131209_Content_52 = {
    Text = "A enorme catedral estrondosamente retumba. Durante a longa vibração, as paredes de pedra adornadas com murais sujos se elevam lentamente."
  },
  AvgDialog_131209_Content_53 = {Text = "Isso é!"},
  AvgDialog_131209_Content_54 = {
    Text = "Arachne... senhora..."
  },
  AvgDialog_131209_Content_55 = {
    Text = "Ai... nossas pequenas \"memórias\", a voz é tão fraca que dá pena."
  },
  AvgDialog_131209_Content_56 = {
    Text = "Nefraea! Liberar ela"
  },
  AvgDialog_131209_Content_57 = {
    Text = "O corpo da menina pendia na magnífica estrutura do fuso, sangue carmesim escorria lentamente sobre o mármore branco."
  },
  AvgDialog_131209_Content_58 = {
    Text = "A luz brilhante iluminava atrás da menina, delineando uma silhueta sagrada para o corpo ensanguentado."
  },
  AvgDialog_131209_Content_59 = {
    Text = "Nefraea, não faça mais essas lutas inúteis. Liberar ela."
  },
  AvgDialog_131209_Content_6 = {
    Text = "Morrem junto com a Grande Teia, em silêncio e sem deixar rastro."
  },
  AvgDialog_131209_Content_60 = {
    Text = "Oh? Nossa deusa do destino, agora começa a se preocupar com suas \"memórias\"?"
  },
  AvgDialog_131209_Content_61 = {
    Text = "Você nunca se importou com eles, você os abandonou, Arachne."
  },
  AvgDialog_131209_Content_62 = {
    Text = "Nefraea, eu sei que você quer invocar apóstolos, para despertar Toguwaibo novamente... Se houver algo, podemos discutir mais, não há necessidade de matá-los..."
  },
  AvgDialog_131209_Content_63 = {
    Text = "A forma como você ganha tempo é adorávelmente infantil, %player%."
  },
  AvgDialog_131209_Content_64 = {
    Text = "Você não entende nada. Eu nunca os matei. Eu apenas os estou levando de volta para casa."
  },
  AvgDialog_131209_Content_65 = {
    Text = "Vocês vieram aqui apenas para testemunhar o final completo deles."
  },
  AvgDialog_131209_Content_66 = {
    Text = "Ato II, Cena III. Eu o nomeei de \"Celebração\"."
  },
  AvgDialog_131209_Content_67 = {
    Text = "Nefraea olhou para você com desprezo. Suas unhas deslizaram suavemente pelo rosto das \"Memórias\", deixando uma fina marca de Sangue."
  },
  AvgDialog_131209_Content_68 = {
    Text = "Ela se inclinou, olhando com carinho para o rosto da menina que tremia de fraqueza e medo."
  },
  AvgDialog_131209_Content_69 = {
    Text = "Bom garoto, não tenha medo. Em breve, estaremos em casa."
  },
  AvgDialog_131209_Content_7 = {
    Text = "Eles morreram silenciosamente junto com a grande rede."
  },
  AvgDialog_131209_Content_70 = {
    Text = "Adeus às suas lembranças indesejáveis, querida irmã——"
  },
  AvgDialog_131209_Content_71 = {
    Text = "Espera aí... Nefraea!"
  },
  AvgDialog_131209_Content_72 = {Text = "Estalo—"},
  AvgDialog_131209_Content_73 = {
    Text = "Ao som nítido dos estalos de Nefraea, o corpo da menina explodiu como fogos de artifício vermelhos."
  },
  AvgDialog_131209_Content_74 = {
    Text = "A luz da lanterna ilumina as manchas de sangue, projetando uma flor carmesim em seus rostos."
  },
  AvgDialog_131209_Content_75 = {
    Text = "As gotículas de sangue salpicam no ar, param e depois voltam, subindo gananciosamente pelo corpo de Nefraea, tingindo cada centímetro do corpo de Nefraea de vermelho."
  },
  AvgDialog_131209_Content_76 = {
    Text = "As gotas de sangue continuavam a descer, descendo, infiltrando-se em suas roupas e pele, penetrando em cada veia dela, pulsando em seu corpo esguio."
  },
  AvgDialog_131209_Content_77 = {
    Text = "A língua lambendo o sangue ao redor dos lábios, Nefraea admirava alegremente as unhas tingidas de vermelho, como uma anfitriã elegantemente vestida, pronta para receber um reencontro festivo."
  },
  AvgDialog_131209_Content_78 = {
    Text = "Bem-vindo de volta, querido."
  },
  AvgDialog_131209_Content_79 = {Text = "Pare!"},
  AvgDialog_131209_Content_8 = {
    Text = "A canção ecoa na ampla igreja. Nefraea abre os braços, apreciando seu resquício sonoro."
  },
  AvgDialog_131209_Content_80 = {
    Text = "A luz prateada brilha em suas mãos, e você corre em direção a Nefraea."
  },
  AvgDialog_131209_Content_81 = {
    Text = "Sob a luz sagrada e sangrenta, inúmeras sombras se estendem nas paredes sujas, bloqueando seu caminho..."
  },
  AvgDialog_131209_Content_9 = {
    Text = "Como foi meu canto?"
  },
  AvgDialog_131210_Content_1 = {
    Text = "Não esperava te ver assim tão desajeitado na nossa próxima reunião."
  },
  AvgDialog_131210_Content_2 = {Text = "Thais..."},
  AvgDialog_131210_Content_3 = {
    Text = "Tawil está certo. Está tudo bem, Guardião."
  },
  AvgDialog_131210_Content_4 = {
    Text = "Você disse que me levaria para testemunhar outro final. Eu acredito em você, desde o começo até o fim."
  },
  AvgDialog_131210_Content_5 = {
    Text = "Não importa se você parar aqui ou se passar por mim, estarei sempre ao seu lado."
  },
  AvgDialog_131211_Content_1 = {Text = "Crisálida"},
  AvgDialog_131211_Content_10 = {
    Text = "Essa experiência, eu não quero passar por isso de novo..."
  },
  AvgDialog_131211_Content_11 = {
    Text = "Não tens a certeza se realmente queres dizer isso. Cerras o punho, reajustando-te ao corpo que acabaste de partilhar com \"N\"."
  },
  AvgDialog_131211_Content_12 = {
    Text = "A visão começa a ficar clara, você esfrega a cabeça que dói intensamente e caminha em direção àquela figura magra ajoelhada na borda do palco."
  },
  AvgDialog_131211_Content_13 = {
    Text = "Nefraea, seu plano já está......"
  },
  AvgDialog_131211_Content_14 = {Text = "Cuidado."},
  AvgDialog_131211_Content_16 = {
    Text = "Parece que fios estão puxando suavemente, fazendo seus passos hesitarem um pouco. Uma garra negra afiada quase toca seus olhos, passando perigosamente perto do seu rosto."
  },
  AvgDialog_131211_Content_17 = {
    Text = "Oito enormes membros venenosos rasgaram a roupa em sua coluna, balançando, distorcendo e lutando no ar. Nefraea parecia não se importar com nada disso."
  },
  AvgDialog_131211_Content_18 = {
    Text = "Os fragmentos do canal dimensional flutuavam ao seu redor como fogos de artifício caindo. Suas lágrimas caíam, molhando o fuso opaco em suas mãos que havia perdido a luz."
  },
  AvgDialog_131211_Content_19 = {
    Text = "O corredor da dimensão desapareceu, você não terá mais uma chance."
  },
  AvgDialog_131211_Content_2 = {
    Text = "......Guardião......"
  },
  AvgDialog_131211_Content_20 = {
    Text = "O destino caminha na sua trajetória adequada, Nefraea. Aceite isso."
  },
  AvgDialog_131211_Content_21 = {
    Text = "Oportunidade?... Hehehe..."
  },
  AvgDialog_131211_Content_22 = {
    Text = "A silhueta magra treme com as risadas, desenhando no ar uma trajetória angustiante com aqueles membros envenenados."
  },
  AvgDialog_131211_Content_23 = {
    Text = "Eu nunca tive uma oportunidade, nem precisei de uma."
  },
  AvgDialog_131211_Content_24 = {
    Text = "Liberdade, infância, família, amor, eu mesmo... O destino levou tudo de nós, eu nunca, nunca serei como você, um prisioneiro dele."
  },
  AvgDialog_131211_Content_25 = {
    Text = "Nefraea levantou-se lentamente, colocando seu corpo naquela roda de fiar escura e quebrada."
  },
  AvgDialog_131211_Content_26 = {
    Text = "Olhe bem, Arachne! As coisas que você deseja imensamente, mas não tem coragem de fazer, eu farei por você"
  },
  AvgDialog_131211_Content_27 = {
    Text = "Quase ao som do grito de raiva, o corpo de Nefraea parecia ser perfurado instantaneamente por inúmeras espinhos. Sangue fluía de seu corpo, conectado àquela roda de fiar quebrada, como uma rede ensanguentada."
  },
  AvgDialog_131211_Content_28 = {
    Text = "<Shake:@2—!>"
  },
  AvgDialog_131211_Content_29 = {
    Text = "Um grito agudo de alta frequência, insuportável para os humanos, emanou da cabeça de Nefraea. Seu corpo tremia de dor intensa, e as veias de cor púrpura escura se destacavam claramente em sua pele."
  },
  AvgDialog_131211_Content_3 = {
    Text = "{Male=Mr.,Female=Miss} Guardião."
  },
  AvgDialog_131211_Content_30 = {
    Text = "Os fragmentos do canal dimensional parecem ter sido atraídos por algo, parando de flutuar e lentamente se reunindo na rede tecida de sangue. A roda de fiar opaca reacende um brilho sanguinolento."
  },
  AvgDialog_131211_Content_31 = {
    Text = "Heh... Hahaha! <Big:<Shake:Se não existem deuses, eu tornar-me-ei um!>>"
  },
  AvgDialog_131211_Content_32 = {
    Text = "A minha história... o meu palco... nunca terão fim! Trarei libertação a esta teia que nunca deveria ter existido... <Big:<Shake:<Red:libertação!!!>>>"
  },
  AvgDialog_131211_Content_33 = {
    Text = "Sob os gritos de dor de Nefraea, todo o Teatro do Destino começou a tremer violentamente. Os fantoches no palco se inverteram e colidiram, as linhas que conectavam os fantoches se entrelaçaram em desordem..."
  },
  AvgDialog_131211_Content_34 = {
    Text = "Arachne olhava para a silhueta não muito distante, corroída pela força e loucura dos fragmentos dimensionais. Ondas de tristeza surgiram em seus olhos profundos, como no dia em que ela se despediu de si mesma pela primeira vez."
  },
  AvgDialog_131211_Content_35 = {
    Text = "Eu tentei libertá-lo desta maldição... Infelizmente, eu estava errado, Nefraea."
  },
  AvgDialog_131211_Content_36 = {
    Text = "Maldição, não há como escapar, gaiola, nunca conseguiremos escapar..."
  },
  AvgDialog_131211_Content_37 = {
    Text = "Aqueles fragmentos... aquela roda de fiar..."
  },
  AvgDialog_131211_Content_38 = {
    Text = "Nefraea está absorvendo a força residual na passagem dimensional! Ela... ela quer se tornar um pavio!!"
  },
  AvgDialog_131211_Content_39 = {
    Text = "Um leve suspiro ecoa claramente neste teatro instável."
  },
  AvgDialog_131211_Content_4 = {
    Text = "<Shake:Ugh... cof, cof...>"
  },
  AvgDialog_131211_Content_40 = {
    Text = "Aguenta-te firme, {Male=Mr.,Female=Miss} Guardião."
  },
  AvgDialog_131211_Content_41 = {Text = "O que..."},
  AvgDialog_131211_Content_42 = {
    Text = "<Shake:Boom—>"
  },
  AvgDialog_131211_Content_43 = {
    Text = "Antes que a voz se apagasse, todo o teatro se rasgou violentamente. Nefraea rasgava furiosamente os fios do destino, e nas fendas aterrorizantes, os edifícios da cidade se entrelaçavam com os fragmentos coloridos da dimensão."
  },
  AvgDialog_131211_Content_44 = {
    Text = "O palco principal do teatro se despedaçou em vários pedaços, fragmentos do passado, futuro e presente se entrelaçam caoticamente no palco quebrado, formando uma cena que você não consegue entender."
  },
  AvgDialog_131211_Content_45 = {
    Text = "Arachne... sua teia..."
  },
  AvgDialog_131211_Content_46 = {
    Text = "Arachne segurava a roca que girava rapidamente, enquanto as vastas cinzas da dimensão jorravam de seu corpo, seguindo os fios na roca, preenchendo os buracos quebrados na rede do destino, mantendo precariamente o palco longe da ruína do destino."
  },
  AvgDialog_131211_Content_47 = {
    Text = "Sob a puxada dos fios, você se levanta com dificuldade."
  },
  AvgDialog_131211_Content_48 = {
    Text = "Absorva a força que Ele dispersou, mudando a direção de toda a Rede do destino... você não é um fragmento Dele, não pode suportar tal pressão. Você não precisa perecer tão dolorosamente, Nefraea."
  },
  AvgDialog_131211_Content_49 = {
    Text = "Dor? Não, eu estou muito feliz, irmã! Nos inúmeros anos no abismo, eu sonhei com este dia a cada momento."
  },
  AvgDialog_131211_Content_5 = {
    Text = "O que aconteceu..."
  },
  AvgDialog_131211_Content_50 = {
    Text = "Foi essa ilusão que me fez aguentar até hoje..."
  },
  AvgDialog_131211_Content_51 = {
    Text = "O riso de loucura de Nefraea ecoa no espaço quebrado do teatro. Ela levanta a cabeça, absorvendo avidamente a luz sombria que emana dos fragmentos."
  },
  AvgDialog_131211_Content_52 = {
    Text = "O deus adormecido, o apóstolo cuja destino foi roubado... hehe... não faz mal, nada disso pode me impedir. Já que o deus não pode trazer bênçãos, então eu trarei em seu lugar!"
  },
  AvgDialog_131211_Content_53 = {
    Text = "Vingadores do Destino, subam ao palco! <Red:Este ato pertence-vos!>"
  },
  AvgDialog_131211_Content_54 = {
    Text = "Nefraea levantou a mão de repente. Uma infinidade de líquido negro pegajoso jorrou do corpo de Nefraea, construindo uma teia negra no vazio deste teatro."
  },
  AvgDialog_131211_Content_55 = {
    Text = "Incontáveis rancores, outrora descartados pelo Destino, ganham forma física. Rastejam ao longo da teia massiva numa maré avassaladora, avançando na tua direção."
  },
  AvgDialog_131211_Content_56 = {
    Text = "Arachne, em nossos corpos...!"
  },
  AvgDialog_131211_Content_57 = {
    Text = "Você de repente percebe que um fio preto que você consegue ver aparece vagamente do corpo de Arachne."
  },
  AvgDialog_131211_Content_58 = {
    Text = "Você levanta a cabeça e vê um fio preto nebuloso se estendendo de seu corpo, de cada palco, de cada corpo de boneco, conectando-se ao fuso nas mãos de Nefraea."
  },
  AvgDialog_131211_Content_59 = {
    Text = "Salve, Arachne! Bênção a você, a deusa do destino"
  },
  AvgDialog_131211_Content_6 = {
    Text = "Uma forte tontura e espasmos no estômago são os restos deixados pela alegria, você reprime a náusea e se levanta lentamente."
  },
  AvgDialog_131211_Content_60 = {
    Text = "Venham, desenrolem suas lâminas, soldados! Lute por nosso destino"
  },
  AvgDialog_131211_Content_61 = {
    Text = "Senhorita Arachne, aceite seu destino... não resista mais em vão..."
  },
  AvgDialog_131211_Content_62 = {
    Text = "Não se preocupe, querido. Sua libertação está chegando, em breve, em breve..."
  },
  AvgDialog_131211_Content_63 = {
    Text = "A roda obscura de Nefraea gira loucamente, enquanto os fantoches no palco se transformam em sombras no abismo, pisando na nova teia negra sob a puxada dos fios."
  },
  AvgDialog_131211_Content_64 = {
    Text = "Arachne fechou lentamente os olhos, a mão que segurava o fio tremia levemente de dor."
  },
  AvgDialog_131211_Content_65 = {
    Text = "Nefraea, elas não podem te ajudar a se tornar o deus que pode destruir todo destino... O que você faz, só fará com que elas enfrentem uma dor de extinção novamente."
  },
  AvgDialog_131211_Content_66 = {
    Text = "E qual é a diferença? Vingança, além da vingança, não queremos mais nada! Certo, filhos do destino?"
  },
  AvgDialog_131211_Content_67 = {
    Text = "<Shake:Heh... hahaha!>"
  },
  AvgDialog_131211_Content_68 = {
    Text = "Risos agudos, grandiosos e angustiantes ecoam da interminável teia negra, como um coro de dor."
  },
  AvgDialog_131211_Content_69 = {
    Text = "Aqueles destinos abandonados riem loucamente e choram, bloqueando o caminho de Nefraea."
  },
  AvgDialog_131211_Content_7 = {
    Text = "A consciência do Apóstolo deixou aquele fuso, perdendo a conexão com a divindade, e agora está quase totalmente destruída. O poder do plásmido também retornou à calma."
  },
  AvgDialog_131211_Content_70 = {
    Text = "Agora, a Porta do Abismo está completamente aberta. Venha, Arachne, veja esses destinos que você criou com suas próprias mãos, veja suas amadas crianças"
  },
  AvgDialog_131211_Content_71 = {
    Text = "Veja a dor deles, o desespero deles... Olhe para eles e, mais uma vez, mate-os"
  },
  AvgDialog_131211_Content_72 = {
    Text = "Observe o destino de tudo girar em minhas mãos, destrua!... Olhe para mim, torne-se a divindade que traz o fim"
  },
  AvgDialog_131211_Content_73 = {
    Text = "Os fragmentos da Dimensão, carregando o poder dos deuses e a vontade do Frenesi, foram cravados um a um no corpo de Nefraea, enquanto o Sangue fluía incessantemente para o fuso de Nefraea."
  },
  AvgDialog_131211_Content_74 = {
    Text = "O rosto dela contorce-se em agonia, mas a sua risada só se torna mais frenética."
  },
  AvgDialog_131211_Content_75 = {
    Text = "Ela olhava para o palco quebrado com expectativa, como uma dramaturga esperando a estreia de sua obra."
  },
  AvgDialog_131211_Content_76 = {
    Text = "Aquele abismo do destino já chegou a este palco... Nefraea está sacrificando a si mesma."
  },
  AvgDialog_131211_Content_77 = {
    Text = "Ela quer transformar tudo aqui, incluindo nós, em seus fantoches. Ela deseja se tornar aquela pessoa divina. Ela... quer se tornar o destino em si."
  },
  AvgDialog_131211_Content_78 = {
    Text = "O tom calmo de Arachne parecia pertencer a uma Uma que nunca entrou na peça. As Cinzas das dimensões que foram recuperadas pairavam em seus dedos como areia fina, sem fim."
  },
  AvgDialog_131211_Content_79 = {
    Text = "A roda de fiar dela girava com dificuldade, lutando para manter os destinos que estavam sendo destruídos por Nefraea, impedindo que aqueles fios negros se unissem nas mãos de Nefraea."
  },
  AvgDialog_131211_Content_8 = {
    Text = "Você realizou uma apresentação brilhante."
  },
  AvgDialog_131211_Content_80 = {
    Text = "As cinzas da dimensão já foram recuperadas, hoje não preciso mais ter receios."
  },
  AvgDialog_131211_Content_81 = {
    Text = "Por favor, ajude-me, chegue perto dela. A roda de fiar de Nefraea vai parar de girar, este destino errado, eu irei corrigir junto com você."
  },
  AvgDialog_131211_Content_82 = {
    Text = "Por favor, ajude-me... a trazer alívio para esses destinos abandonados."
  },
  AvgDialog_131211_Content_9 = {
    Text = "Ufa... não posso acreditar que aquelas palavras saíram da minha boca."
  },
  AvgDialog_131212_Content_1 = {
    Text = [[
Neste momento
do outro lado da cidade]]
  },
  AvgDialog_131212_Content_10 = {
    Text = "O número seis foi escolhido pelo duque na estábulo da mansão para enviar ao hipódromo, desta vez o número seis certamente ganhará, confie em mim, apostar no número seis não tem erro"
  },
  AvgDialog_131212_Content_11 = {
    Text = "O barulho de conversas no metrô se transforma em um riacho pulsante, Arachne observa silenciosamente as luzes que se aproximam e se afastam do lado de fora da janela, sorrindo enquanto ouve seus fantoches falarem sobre apresentações, corridas de cavalos e casamentos."
  },
  AvgDialog_131212_Content_12 = {
    Text = "Ela balança suavemente a roca que tem nas mãos. Entre milhões de fios complexos, ela desfruta deste momento de tranquilidade."
  },
  AvgDialog_131212_Content_13 = {
    Text = "Mestre, estamos quase chegando ao nosso destino. A carruagem de transferência já está pronta, e nossas irmãs estão lá esperando por você."
  },
  AvgDialog_131212_Content_14 = {
    Text = "Bom garoto."
  },
  AvgDialog_131212_Content_15 = {
    Text = "Ela olhou ao redor dos fantoches que ainda se apresentavam com um certo pesar, como um espectador relutante em deixar seu assento."
  },
  AvgDialog_131212_Content_16 = {
    Text = "Você ainda se lembra de quanto tempo não saímos do teatro?"
  },
  AvgDialog_131212_Content_17 = {
    Text = "Desde o dia em que me tornei a Aranha Fria, estive ao seu lado, nunca me afastei. Até agora... cinquenta anos? Ou sessenta anos? Também não me lembro muito bem."
  },
  AvgDialog_131212_Content_18 = {
    Text = "No entanto, já faz um tempo que saí do teatro."
  },
  AvgDialog_131212_Content_19 = {
    Text = "Isso é graças a Nefraea. Se não fosse pela chegada dela, eu não teria a oportunidade de ficar tanto tempo do lado de fora do teatro."
  },
  AvgDialog_131212_Content_2 = {
    Text = "Senhor, por favor, apresente seu bilhete."
  },
  AvgDialog_131212_Content_20 = {
    Text = "Em coordenação com as ações do Guardião do Segredo, já caçamos centenas de Servidores que vieram do Abismo nos últimos dias. Depois de salvar \"Memórias\", devemos voltar ao teatro."
  },
  AvgDialog_131212_Content_21 = {
    Text = "Se houver uma próxima oportunidade de sair, não sei quando será..."
  },
  AvgDialog_131212_Content_22 = {
    Text = "Parece sentir os pensamentos de Arachne, as luzes do metrô se apagaram. Ela olha para fora da janela escura, buscando nas memórias de inúmeras civilizações que se sucederam, aquelas memórias comuns sobre si mesma."
  },
  AvgDialog_131212_Content_23 = {
    Text = "O ponteiro do relógio girou por dois segundos. O dono da cidade percebeu que as conversas suaves no metrô pareciam desaparecer no momento em que o vagão entrou na escuridão."
  },
  AvgDialog_131212_Content_24 = {
    Text = "Senhor, parece que aqui está um pouco..."
  },
  AvgDialog_131212_Content_25 = {Text = "Karab—"},
  AvgDialog_131212_Content_26 = {
    Text = "O sangue frio da servente jorrou sobre o rosto sereno de Arachne, exalando um perfume semelhante ao íris."
  },
  AvgDialog_131212_Content_27 = {
    Text = "As luzes do lado de fora acenderam. Arachne viu o corpo da servente cortado, a lâmina afiada que atravessou seu corpo vindo em sua direção, e, atrás da lâmina, aqueles fantoches que se lançavam sobre ela como um bando de feras."
  },
  AvgDialog_131212_Content_28 = {Text = "..."},
  AvgDialog_131212_Content_29 = {
    Text = "O sistema de freios emitiu um som de atrito cansado, e a brisa gerada levantou os cabelos de outra servente."
  },
  AvgDialog_131212_Content_3 = {
    Text = "Já não foi verificado quando entramos na estação? O dinheiro dos contribuintes está sendo desperdiçado assim..."
  },
  AvgDialog_131212_Content_30 = {
    Text = "Ah! Chegamos"
  },
  AvgDialog_131212_Content_31 = {
    Text = "A porta do carro se abriu, mas a multidão barulhenta não apareceu. Apenas o sangue com um forte cheiro ferroso escorria entre as fendas de cada porta, como uma sinfonia silenciosa."
  },
  AvgDialog_131212_Content_32 = {
    Text = "Pisar neste rio de sangue que acompanha a música, Arachne saiu lentamente do compartimento. Suas roupas estavam imaculadas, sua roca ainda girava, sem parar."
  },
  AvgDialog_131212_Content_33 = {
    Text = "Aquilo é..."
  },
  AvgDialog_131212_Content_34 = {
    Text = "Um espetáculo interativo e emocionante. Como espectadores e atores, a experiência é, de fato, muito mais emocionante do que a dos autores da peça."
  },
  AvgDialog_131212_Content_35 = {
    Text = "Ela olha para a criada diante de si, sua expressão indecifrável."
  },
  AvgDialog_131212_Content_36 = {
    Text = "Minha servente está ao meu lado há muitos anos, eu não costumo tocar nas linhas do destino delas."
  },
  AvgDialog_131212_Content_37 = {
    Text = "Neste teatro monótono, elas são uma das poucas vidas vivas."
  },
  AvgDialog_131212_Content_38 = {
    Text = "Você matou minhas duas serventes hoje. A destruição do destino terá um preço, Nefraea."
  },
  AvgDialog_131212_Content_39 = {
    Text = "hehehehe...<Shake:ha ha ha ha!>Quão nobre, Arachne."
  },
  AvgDialog_131212_Content_4 = {
    Text = "Ei, Charlie, onde está o meu broche?"
  },
  AvgDialog_131212_Content_40 = {
    Text = "Como manteiga caindo em uma panela de estanho fervente, o corpo da servente começou a derreter. Sob a fervente e suja substância pegajosa de cor negra, aquele rosto idêntico ao de Arachne ria de alegria."
  },
  AvgDialog_131212_Content_41 = {
    Text = "\"Veja, eu sou o manipulador do destino, o executor diligente! Escolherei os destinos corretos e enviarei todos os erros para o abismo do nada...\""
  },
  AvgDialog_131212_Content_42 = {
    Text = "Você é meu ídolo, minha fé, querida irmã. Eu só estou apenas desempenhando o seu papel."
  },
  AvgDialog_131212_Content_43 = {
    Text = "E aí, estou me saindo bem como aprendiz?"
  },
  AvgDialog_131212_Content_44 = {
    Text = "Arachne observa silenciosamente aqueles olhos que a fitam. Eles são ardentes, brilhantes, cheios de expectativa, como se fossem apenas de uma menina que espera o elogio da irmã."
  },
  AvgDialog_131212_Content_45 = {
    Text = "Plataforma, escada, colunas, túnel... enquanto ela falava, inúmeras sombras surgiram em cada lugar que ela podia imaginar."
  },
  AvgDialog_131212_Content_46 = {
    Text = "A respiração turva das sombras está firmemente conectada, reunida nas mãos de Nefraea, como uma enorme rede que se aperta em direção a Arachne."
  },
  AvgDialog_131212_Content_47 = {
    Text = "Os cantos da boca de Arachne se levantaram suavemente."
  },
  AvgDialog_131212_Content_48 = {
    Text = "Eu nunca pensei que alguém tentaria me prender com uma rede."
  },
  AvgDialog_131212_Content_49 = {
    Text = "Você já viu um bicho-da-seda, irmã mais velha? É um inseto que vem do distante Oriente, que passa os dias sem fazer nada, apenas comendo incessantemente e tecendo fios... e então, ah, espera que os casulos feitos de fios o aprisionem."
  },
  AvgDialog_131212_Content_5 = {
    Text = "Quando você saiu, não deixou suas roupas aqui?"
  },
  AvgDialog_131212_Content_50 = {
    Text = "Quase todos os seus servidores já desapareceram em cada canto desta cidade, neste trem. Elas estiveram ao seu lado, passando longos anos no vazio."
  },
  AvgDialog_131212_Content_51 = {
    Text = "Você trouxe a elas um destino que não deveria ter acontecido. O destino é inescapável, Nefraea."
  },
  AvgDialog_131212_Content_52 = {
    Text = "Você quer dizer que o destino delas deve ser permanecer naquele abismo escuro, afundando em um tempo sem fim... certo, nobre controlador do destino?"
  },
  AvgDialog_131212_Content_53 = {
    Text = "Nefraea riu e balançou a cabeça."
  },
  AvgDialog_131212_Content_54 = {
    Text = "Eu as amo mais do que você imagina, irmã. Mas elas me disseram que, se a morte pudesse poupá-las do destino de serem aprisionadas novamente, elas a receberiam sem hesitar..."
  },
  AvgDialog_131212_Content_55 = {
    Text = "Depois do massacre no metrô, quantas cinzas restam para você corrigir seu destino?"
  },
  AvgDialog_131212_Content_56 = {
    Text = "Nefraea exibiu orgulhosamente a roda de fiar preta que segurava na mão. Incontáveis fios se estendiam do palco da cidade, conectando-se àquela roda de fiar parada."
  },
  AvgDialog_131212_Content_57 = {
    Text = "As linhas do destino desta cidade estão em minhas mãos. Não tenho a capacidade de controlá-las, muitas coisas interessantes não posso fazer, que pena..."
  },
  AvgDialog_131212_Content_58 = {
    Text = "Mas, felizmente, consertá-los requer muitas cinzas, enquanto a poluição não é necessária."
  },
  AvgDialog_131212_Content_59 = {
    Text = "Basta eu soltar assim levemente... seu teatro, seu palco, se tornará o berçário mais perfeito do caos, assim como... assim como aquele lugar onde passei incontáveis anos."
  },
  AvgDialog_131212_Content_6 = {
    Text = "Meu Deus... Eu preparei a festa de hoje por um mês inteiro! Se não fosse por este broche, esse vestido não seria diferente de um pano para cobrir um caixão..."
  },
  AvgDialog_131212_Content_60 = {
    Text = "E você só pode observar tudo isso acontecer. Nada pode ser mudado, nada pode ser resistido..."
  },
  AvgDialog_131212_Content_61 = {
    Text = "Nefraea chegou diante de Arachne e acariciou cuidadosamente seu rosto, onde as emoções eram difíceis de discernir."
  },
  AvgDialog_131212_Content_62 = {
    Text = "O que devo fazer, minha irmã... deve me obedecer ou deve se juntar a mim para apreciar como este mundo se transforma em um inferno?"
  },
  AvgDialog_131212_Content_63 = {
    Text = "Você é um destino incompleto, poluindo o destino de toda a cidade, você não possui tal..."
  },
  AvgDialog_131212_Content_64 = {
    Text = "Um som de um fio se rompendo ecoou ao lado da orelha de Arachne. Ela levantou a cabeça e, ao olhar para Nefraea, trouxe consigo uma ponta de tristeza pertencente ao público."
  },
  AvgDialog_131212_Content_65 = {
    Text = "... você também matou as \"memórias\"."
  },
  AvgDialog_131212_Content_66 = {
    Text = "É aceitação. Romance, bondade, memórias... Eu apenas fui recolhendo um a um, essas coisas que você descartou, trazendo-as de volta para suas casas."
  },
  AvgDialog_131212_Content_67 = {
    Text = "Nefraea se levantou e girou alegremente."
  },
  AvgDialog_131212_Content_68 = {
    Text = "Um eu completo, um vingador completo... Gosta, irmã mais velha?"
  },
  AvgDialog_131212_Content_69 = {
    Text = "Você já pode obter o caos que deseja... Então, o que está esperando?"
  },
  AvgDialog_131212_Content_7 = {
    Text = "A dança do grupo do Cisne é realmente encantadora, mas se houver um conflito de horários, certamente escolheria \"Jardim de Esmeralda\"."
  },
  AvgDialog_131212_Content_70 = {
    Text = "Ah, não, não, não, boa irmã, ainda estou muito longe do que eu quero."
  },
  AvgDialog_131212_Content_71 = {
    Text = "Eu cuidarei bem da sua roca. As cinzas da dimensão que você deseja nunca acabarão, e nenhum dos palcos que você ama será destruído por mim."
  },
  AvgDialog_131212_Content_72 = {
    Text = "E o que eu quero que você faça é apenas me ajudar com um pequeno, muito pequeno favor."
  },
  AvgDialog_131212_Content_73 = {
    Text = "Nefraea aproximou-se de Arachne, acariciando a roca que girava incessantemente em suas mãos, sua respiração acelerando devido à imaginação empolgante."
  },
  AvgDialog_131212_Content_74 = {
    Text = "Controle o Guardião do Segredo por mim, minha boa irmã, só o Guardião pode trazer aquilo que realmente desejo."
  },
  AvgDialog_131212_Content_75 = {
    Text = "Você sabe bem que %player% é um fragmento do Ser Supremo. Não podemos comandar o Destino de {Male=his,Female=her}..."
  },
  AvgDialog_131212_Content_76 = {
    Text = "Uma luz verde-escura emana da roca negra nas mãos de Nefraea. Sob a luz, um fio oculto e turvo aparece no campo de visão de Arachne."
  },
  AvgDialog_131212_Content_77 = {
    Text = "Isto é... <Shake:o Fio do Destino do Guardião?!>"
  },
  AvgDialog_131212_Content_78 = {
    Text = "<Shake:Heh...> <Big:<Shake:HAHAHAHA!>> É a primeira vez que ouço sua voz tremer. E então, irmã? Não é eletrizante?!"
  },
  AvgDialog_131212_Content_79 = {
    Text = "No abismo, o apóstolo que se manifestou na vontade daquela divindade foi acolhido nesta roda de fiar, tornando-se seu pavio... Foi ele quem iluminou o abismo, trazendo-nos a única luz."
  },
  AvgDialog_131212_Content_8 = {
    Text = "Uma narrativa multifacetada e multitemporal, que técnica tão maravilhosa e complexa. A ascensão e queda dos jardins reais não pode ser comparada a esses clichês..."
  },
  AvgDialog_131212_Content_80 = {
    Text = "Com nosso poder e a orientação do Apóstolo, <Big:até o Destino de um fragmento divino repousa em NOSSAS mãos!>"
  },
  AvgDialog_131212_Content_81 = {
    Text = "Este não é o caminho correto do destino, Nefraea... ninguém pode desafiar o destino."
  },
  AvgDialog_131212_Content_82 = {
    Text = "Em breve, irmã. Basta tocar no poder dos três plásmidos, o Apóstolo poderá renascer! Ele reabrirá o caminho de ligação com a divindade, e levará a voz dos crentes ao eterno templo"
  },
  AvgDialog_131212_Content_83 = {
    Text = "A Divindade Suprema despertará... e você nunca mais terá que podar outro destino agonizante ou tecer uma teia fadada a se despedaçar."
  },
  AvgDialog_131212_Content_84 = {
    Text = "Nefraea respirou fundo, uma lágrima caiu de seu rosto empolgado."
  },
  AvgDialog_131212_Content_85 = {
    Text = "A voz dela tremia por causa do maravilhoso sonho que estava por vir. Aqueles olhos cheios de lágrimas olhavam profundamente para o rosto sereno de Arachne."
  },
  AvgDialog_131212_Content_86 = {
    Text = "Não faça mais essas resistências dolorosas, irmã."
  },
  AvgDialog_131212_Content_87 = {
    Text = "Venha, venha até mim, vamos juntos receber o Seu Despertar e trazer a todos os palcos o desfecho que merecem!..."
  },
  AvgDialog_131212_Content_9 = {
    Text = "Ha, se você comprar o número oito, vai se dar mal! Deixa eu te contar em segredo, tenho notícias internas, hoje alguém vai colocar veneno na ração do número oito."
  },
  AvgDialog_131213_Content_1 = {
    Text = "Comédia improvisada"
  },
  AvgDialog_131213_Content_10 = {
    Text = "Agora, você recebe um novo crente —"
  },
  AvgDialog_131213_Content_100 = {
    Text = "Estou a usar a Ordem de peso de \"N\"... <color=#98918C>Estou a ocupar metade da consciência de %player%</color>... mas um nome é a coisa menos importante agora."
  },
  AvgDialog_131213_Content_101 = {
    Text = "O importante é que a colaboração seja agradável, Arachne."
  },
  AvgDialog_131213_Content_102 = {
    Text = "<Shake:Vocês... todos vocês... sabiam desde o início...>"
  },
  AvgDialog_131213_Content_103 = {
    Text = "O olhar fraco de Nefraea se moveu do rosto de Arachne para o seu. Você saboreia, com ganância, a infinita amargura e dor daquele olhar. Ah, que fragrância tão intoxicante..."
  },
  AvgDialog_131213_Content_104 = {
    Text = "Dê uma boa olhada, querida Nefraea, o travesso que escapou do lugar do Nada."
  },
  AvgDialog_131213_Content_105 = {
    Text = "Seu jogo me traz grande prazer. Um fragmento da consciência remanescente de Toguwaibo, um pedaço caído de Toguwaibo, somente seu encontro pode liberar completamente a autoridade do plásmido, me dando a oportunidade de experimentar essa alegria nunca antes sentida..."
  },
  AvgDialog_131213_Content_106 = {
    Text = "Se eu pudesse, eu adoraria continuar jogando assim, essa diversão poderia durar uma semana inteira para mim..."
  },
  AvgDialog_131213_Content_107 = {
    Text = "A garganta treme. Você suspira com grande arrependimento."
  },
  AvgDialog_131213_Content_108 = {
    Text = "Infelizmente, se aquela pessoa divina acordar novamente, este grandioso Paraíso estará prestes a me deixar."
  },
  AvgDialog_131213_Content_109 = {
    Text = "Então, infelizmente... o clímax tem de acabar. Olha para cima, querida. Aconteça o que acontecer, podemos pelo menos concordar numa coisa sobre esta história do Destino..."
  },
  AvgDialog_131213_Content_11 = {
    Text = "Os fios do destino puxam seu corpo. Com os dedos entrelaçados, você junta as mãos no peito e se ajoelha lentamente diante da roca à sua frente."
  },
  AvgDialog_131213_Content_110 = {
    Text = "Você se inclina, segurando o queixo elegante de Nefraea, e se aproxima do ouvido dela."
  },
  AvgDialog_131213_Content_111 = {
    Text = "A destruição é a cena mais bela deste universo, não é, querido?"
  },
  AvgDialog_131213_Content_112 = {
    Text = "Um estalo nítido, repleto de alegria e arrependimento infinitos, ressoou diante dos olhos de Nefraea."
  },
  AvgDialog_131213_Content_113 = {Text = "Boom—"},
  AvgDialog_131213_Content_114 = {
    Text = "No tremor da dimensão, o canal conectado aos deuses sacudiu abruptamente. Incontáveis fissuras se espalham pela superfície ilusória do canal..."
  },
  AvgDialog_131213_Content_115 = {
    Text = "<Big:<Shake:NÃÃÃOOO!!—>>"
  },
  AvgDialog_131213_Content_116 = {
    Text = "Nefraea gritou enquanto corria em direção ao corredor, e quando suas mãos estavam a poucos centímetros do corredor, ele se despedaçou e desabou."
  },
  AvgDialog_131213_Content_117 = {
    Text = "Incontáveis fragmentos ilusórios flutuam diante de Nefraea, como um caleidoscópio quebrado, aqueles baratos pedaços de papel colorido se espalham pelo ar, passando pelo rosto de Nefraea."
  },
  AvgDialog_131213_Content_118 = {
    Text = "Você tirou o chapéu de palha que não existia, girou duas vezes no ar e fez uma reverência para as costas confusas de Nefraea."
  },
  AvgDialog_131213_Content_119 = {
    Text = "Destino, que palco tão interessante... O terceiro ato da história chega ao fim. Seus aplausos e gritos de alegria me fazem sentir imensamente feliz."
  },
  AvgDialog_131213_Content_12 = {
    Text = "Eu... o apóstolo que anseia... sou... o seu mais fiel seguidor e do Deus Supremo."
  },
  AvgDialog_131213_Content_120 = {
    Text = "Aprecie o espetáculo, querida Nefraea."
  },
  AvgDialog_131213_Content_121 = {
    Text = "No grito dilacerante de Nefraea, a consciência do Apóstolo se fragmentou com a ruptura do portal. Você caiu diretamente no palco com o último sorriso de alegria."
  },
  AvgDialog_131213_Content_13 = {
    Text = "Sua traqueia e seus membros têm seu próprio destino. Eles não pertencem mais a você, e você não deve mais tentar controlá-los em vão."
  },
  AvgDialog_131213_Content_14 = {
    Text = "Não controle. Não entenda. Aproveite-os. O caminho da alegria está neles..."
  },
  AvgDialog_131213_Content_15 = {
    Text = "Olhe, irmã! Que ator excepcional você treinou!"
  },
  AvgDialog_131213_Content_16 = {
    Text = "Arachne estava sentada na plateia, com a roca girando naquela frequência eterna em suas mãos. Ela olhava silenciosamente as sombras escuras da lanterna no palco, como se fosse apenas uma espectadora que cumpria as regras."
  },
  AvgDialog_131213_Content_17 = {
    Text = "Ó meu querido Apóstolo... nossos Crença trouxeram a você a Oferta que mais deseja."
  },
  AvgDialog_131213_Content_18 = {
    Text = "O fuso escuro irrompe em uma explosão repentina, espalhando uma luz turva e viscosa por todos os cantos do palco."
  },
  AvgDialog_131213_Content_19 = {Text = "Hum—!!"},
  AvgDialog_131213_Content_2 = {
    Text = "Toque, toque, toque."
  },
  AvgDialog_131213_Content_20 = {
    Text = "Pain atinge sem aviso. Não atinge sua carne ou órgãos, mas irrompe dos recessos mais profundos do seu Espaço mental — do próprio assento da sua alma."
  },
  AvgDialog_131213_Content_21 = {
    Text = "Uma grande besta se manifesta dentro de você. Ela se debate e ruge, sua forma massiva se expandindo rapidamente em seu interior."
  },
  AvgDialog_131213_Content_22 = {
    Text = "A besta preenche todo o seu corpo, esmagando cada órgão. Ela se expande ainda mais, furiosa para romper sua pele. A pressão intensa e avassaladora quase faz você perder a consciência..."
  },
  AvgDialog_131213_Content_23 = {
    Text = "Hah... <Big:<Shake:AAAARGH!!—>>"
  },
  AvgDialog_131213_Content_24 = {
    Text = "Em seu grito angustiante, três respirações tênues emergem daquele corpo atormentado, flutuando em direção à roca que emite uma luz sombria."
  },
  AvgDialog_131213_Content_25 = {
    Text = "A Ordem de peso converge na luz como combustível puro despejado no fogo. Chamas turvas irrompem, ardendo ferozmente dentro do anel do fuso. A radiância da Lanterna se eleva, iluminando toda a dimensão."
  },
  AvgDialog_131213_Content_26 = {
    Text = "<Shake:Hah... Hah...>"
  },
  AvgDialog_131213_Content_27 = {
    Text = "Ai, que pena, nosso fiel pequeno crente..."
  },
  AvgDialog_131213_Content_28 = {
    Text = "Nefraea chegou ao seu lado, acariciando seu rosto molhado de suor com um olhar cheio de preocupação."
  },
  AvgDialog_131213_Content_29 = {
    Text = "Está tudo bem, {Male=Mr.,Female=Miss} Guardião. Está vendo? Nosso Apóstolo já revelou Sua forma..."
  },
  AvgDialog_131213_Content_3 = {
    Text = "As linhas do destino puxam suavemente, as solas dos sapatos da marionete colidem com o palco, produzindo um som nítido."
  },
  AvgDialog_131213_Content_30 = {
    Text = "Você levantou a cabeça com dor. A luz da roca começa a se reunir, e uma forma ilusória em constante mudança aparece sobre a luz."
  },
  AvgDialog_131213_Content_31 = {
    Text = "Eles não têm rosto nem forma. São o arauto fiel do Divino, fitando o vazio em direção ao Deus adormecido."
  },
  AvgDialog_131213_Content_32 = {
    Text = "Seu olhar é um convite. Sob aquele olhar fixo e inabalável, uma escadaria conectando ao local de repouso do Deus lentamente toma forma..."
  },
  AvgDialog_131213_Content_33 = {
    Text = "<Shake:Funcionou... funcionou!> A passagem para o Plano Superior está se abrindo... O Deus está prestes a despertar..."
  },
  AvgDialog_131213_Content_34 = {
    Text = "Irmã, você viu? Sua rede está quase pronta..."
  },
  AvgDialog_131213_Content_35 = {
    Text = "Nefraea olhou alegremente para o corredor que se tornava cada vez mais claro, com um sorriso e lágrimas aparecendo ao mesmo tempo em seu rosto."
  },
  AvgDialog_131213_Content_36 = {Text = "@2...@3..."},
  AvgDialog_131213_Content_37 = {
    Text = "O teatro começou a tremer violentamente. O palco desmorona, a dimensão treme. Todo o destino está com medo e se submete a esta grande chegada."
  },
  AvgDialog_131213_Content_38 = {
    Text = "A Ordem de peso dentro de você diminuiu até quase nada. O poder do plásmido foi absorvido pelo corpo do Apóstolo. Seu brilho é feroz demais para se contemplar; Sua existência é absolutamente inegável."
  },
  AvgDialog_131213_Content_39 = {
    Text = "Sob o olhar sereno de Arachne, em meio ao tremor de todos os destinos, Ele está prestes a chegar a este palco final —"
  },
  AvgDialog_131213_Content_4 = {
    Text = "Ah, queridos espectadores, o momento tão aguardado está chegando! Vamos aplaudir e dar as boas-vindas ao nosso protagonista, que fará sua brilhante entrada! Oh"
  },
  AvgDialog_131213_Content_40 = {
    Text = "Em...@2 nome...@3 crente..."
  },
  AvgDialog_131213_Content_41 = {
    Text = "Fale, Apóstolo... o que você quer me dizer? É o seu desejo? Ou as palavras daquela pessoa divina?"
  },
  AvgDialog_131213_Content_42 = {
    Text = "Que ordens Ele tem para transmitir a este mundo? Deseja que esses palcos se quebrem? Ou deseja que essas marionetes se unam para receber Sua chegada?"
  },
  AvgDialog_131213_Content_43 = {
    Text = "Diga-me, meu querido Apóstolo! Que besta perigosa e adorável você é, sabendo apenas arrancar e destruir... diga-me o que deseja..."
  },
  AvgDialog_131213_Content_44 = {
    Text = "Recitar@2... Meu nome... Despertar@2...@3 Primordial..."
  },
  AvgDialog_131213_Content_45 = {
    Text = "Ah, teu nome, isso mesmo... Eu vou recitar teu nome! Eu trarei tudo o que você deseja devorar até sua boca. Eu vou abrir essa prisão para você..."
  },
  AvgDialog_131213_Content_46 = {
    Text = "Meu nome...@2..."
  },
  AvgDialog_131213_Content_47 = {
    Text = "A voz do Apóstolo era turva e indistinta, Nefraea caminhou em direção àquela coluna de luz cada vez mais brilhante, sem sequer olhar para você, que tremia de dor."
  },
  AvgDialog_131213_Content_48 = {
    Text = "Fervor a preenche de admiração e riso enquanto ela se aproxima da grande figura. Sua respiração falha de pura exaltação."
  },
  AvgDialog_131213_Content_49 = {
    Text = "Ela acaricia aquela luz verde-escura, tocando essa magnífica besta que vai devorar tudo. Ela se tornará a primeira refeição da besta, sem hesitar, doce como mel."
  },
  AvgDialog_131213_Content_5 = {
    Text = "Nefraea levantou a mão, como uma teia de aranha de fogos de artifício que se espalha e cai. Você está no centro do palco, a luz fraca iluminando seu rosto."
  },
  AvgDialog_131213_Content_50 = {
    Text = "É agora, apóstolo... Diga-me, diga ao mundo, qual é o seu nome"
  },
  AvgDialog_131213_Content_51 = {
    Text = "Meu nome...@2..."
  },
  AvgDialog_131213_Content_52 = {
    Text = "O meu nome é... <Red:%player%>..."
  },
  AvgDialog_131213_Content_53 = {
    Text = "O meu nome é... <Yellow:%player%>!"
  },
  AvgDialog_131213_Content_54 = {
    Text = "Um som nauseante e úmido de dilaceração se ergue no ar. Enormes patas de aranha irrompem pelos corpos dos oficiais e dos transeuntes, espirrando sangue espesso com cheiro de ferro por todo você."
  },
  AvgDialog_131213_Content_55 = {
    Text = "O tempo para neste momento. As linhas do destino derretem e desmoronam nos olhos de Nefraea, o destino desmoronando como um vórtice turbulento em um vasto oceano, a envolvendo e devorando."
  },
  AvgDialog_131213_Content_56 = {
    Text = "<Shake:O que é... o que está a acontecer?!!>"
  },
  AvgDialog_131213_Content_57 = {
    Text = "O vórtice se acalma, o vasto oceano se recolhe, as gotas de água se reúnem novamente em fios, e a rede que elas elaboram já é de uma forma que Nefraea nunca poderia ter previsto."
  },
  AvgDialog_131213_Content_58 = {
    Text = "Não entendeu, Nefraea? Adore humildemente o seu Apóstolo. O Apóstolo que você pediu já está diante de você."
  },
  AvgDialog_131213_Content_59 = {
    Text = "Você está em frente a Nefraea, olhando para o corredor que conecta ao templo Toguwaibo, observando aquela figura suprema, e sorri."
  },
  AvgDialog_131213_Content_6 = {
    Text = "Venha, {Male=Mr.,Female=Miss} Guardião. Nosso ato final começa..."
  },
  AvgDialog_131213_Content_60 = {
    Text = "O poder dos três plásmidos flui livremente dentro de você, mas não mais causa dor. A luz da roda, com a suprema vontade dentro dela, flui para o seu corpo como um vasto oceano, fundindo-se com o poder dos três plásmidos."
  },
  AvgDialog_131213_Content_61 = {
    Text = "Você sente que a figura daquela pessoa está se sobrepondo ao seu corpo. Você se sente imenso. Você se sente ilimitado. Você se sente livre. Você sente... uma alegria suprema."
  },
  AvgDialog_131213_Content_62 = {
    Text = "Você... roubou o destino do Apóstolo?!"
  },
  AvgDialog_131213_Content_63 = {
    Text = "Hehehehe... hahahaha! O terceiro ato da história, Chegada? ... Ha, hahaha. O terceiro ato, isso mesmo. Mas esta não é a sua história, querida Nefraea."
  },
  AvgDialog_131213_Content_64 = {
    Text = "Sou eu quem escreve este ato. E dou-lhe o nome de... <Big:<color=#98918C>Êxtase</color>>!"
  },
  AvgDialog_131213_Content_65 = {
    Text = "<Shake:Vocês... todos vocês...>"
  },
  AvgDialog_131213_Content_66 = {
    Text = "Não, isso não é possível... Eu consigo ver seu destino... isso não é possível..."
  },
  AvgDialog_131213_Content_67 = {
    Text = "<color=#EE4D0C><Italic:\"Oh, meu caro Duque, por que essa cara tão comprida? Deixe o seu bobo da corte restaurar esse sorriso precioso!\"></color>"
  },
  AvgDialog_131213_Content_68 = {
    Text = "<color=#BF0909><Italic:\"Olhe para isto—o destino cruel, a maldição perversa... que espetáculo ridículo! Que mentira doce e deliciosa!\"></color>"
  },
  AvgDialog_131213_Content_69 = {
    Text = "<color=#FC1818><Italic:\"É assim que a história termina para o vilão... a única recompensa para a malícia é o Êxtase!\"></color>"
  },
  AvgDialog_131213_Content_7 = {
    Text = "Esta cena, eu a nomeio como — \"Chegada\""
  },
  AvgDialog_131213_Content_70 = {
    Text = "Aplausos estrondosos irrompem dos assentos vazios. Luzes brilhantes inundam o palco em ruínas. Tu és o eixo do mundo, o mestre da Singularidade. \nAbres os braços. Declaras que o Destino se curvará perante ti. Declaras esta atuação uma obra-prima."
  },
  AvgDialog_131213_Content_71 = {
    Text = "Engano. Manipulação. Puro deleite... <Shake:Hehe... <Big:HAHAHAHA!>> Que espetáculo delicioso, pequena aranha."
  },
  AvgDialog_131213_Content_72 = {
    Text = "<Shake:Tu... é impossível que tenhas o poder de alterar o Destino...>"
  },
  AvgDialog_131213_Content_73 = {
    Text = "Aww... Não, não, não. Esse esforço é para pessoas como tu. Um devoto do Êxtase nunca se rebaixaria a tal trabalho."
  },
  AvgDialog_131213_Content_74 = {
    Text = "<Shake:Eu vi o fim... Devias ter entregue a tua Ordem de peso! <Big:Devias ter assistido à abertura da passagem e morrido neste palco! PORQUÊ?!>>"
  },
  AvgDialog_131213_Content_75 = {
    Text = "Aquele que controla o destino sabe tudo, exceto sobre aqueles que buscam alegria. Porque, porque os que buscam alegria não têm destino, querido..."
  },
  AvgDialog_131213_Content_76 = {
    Text = "Você se inclina e admira os olhos tremulantes de Nefraea. A dor e o desespero que brilham neles nutrem cada centímetro do seu corpo."
  },
  AvgDialog_131213_Content_77 = {
    Text = "Toda a nossa vida é uma busca por alegria. Sem alegria, não temos nada... Aqueles que buscam alegria não têm destino."
  },
  AvgDialog_131213_Content_78 = {
    Text = "O que vês é um truque de salão. Uma pequena piada pregada ao meu eu do passado e ao Destino pelo novo eu, aquele abençoado com a vontade e o poder de um Deus."
  },
  AvgDialog_131213_Content_79 = {
    Text = "Para quê controlar o Destino quando podes fazer dele um tolo? Não é verdade, Executor do Destino?"
  },
  AvgDialog_131213_Content_8 = {
    Text = "Chegada. Atrás do palco, uma cortina de teias de aranha, parecendo uma substância viscosa, forma essa palavra enorme e aterrorizante. Nefraea respira fundo e abre os braços."
  },
  AvgDialog_131213_Content_80 = {
    Text = "Tentas manter um tom sério, mas não consegues reprimir a tua risada maníaca."
  },
  AvgDialog_131213_Content_81 = {
    Text = "Serás o Guardião? Serás \"N\"? Não sabes, e não te importas. A essência do Êxtase inunda a vontade do Apóstolo, preenchendo cada célula do teu corpo."
  },
  AvgDialog_131213_Content_82 = {
    Text = "Queres uivar de riso. Queres celebrar. Queres submeter este manipulador falhado à mais terna e devastadora humilhação."
  },
  AvgDialog_131213_Content_83 = {
    Text = "Você encontrou a chave que abre a fechadura. Você se virou e fez uma elegante reverência para aquela pessoa que planejou tudo."
  },
  AvgDialog_131213_Content_84 = {
    Text = "Arachne, o grande dramaturgo! Desde o primeiro momento em que cheguei a este mundo, começou a tecer este palco para mim"
  },
  AvgDialog_131213_Content_85 = {
    Text = "Leve-me a ver como o destino opera, deixe-me apreciar o charme da zombaria, conte-me o segredo da \"alegria\"..."
  },
  AvgDialog_131213_Content_86 = {
    Text = "Agora, a \"Alegria\" já está desbloqueada. E então, esta pessoa, você está satisfeito?"
  },
  AvgDialog_131213_Content_87 = {
    Text = "Sou apenas o construtor do palco, a escrita da história é decidida por você mesmo."
  },
  AvgDialog_131213_Content_88 = {
    Text = "Você sorriu para ela. Você é o apóstolo da divindade. Você é o escravo da alegria. Você é o único mestre indiscutível deste mundo. Você levanta a mão, como um maestro, e toca suavemente."
  },
  AvgDialog_131213_Content_89 = {
    Text = "Como recompensa... agora, vista sua fantasia, Arachne. Esta apresentação, em breve será a sua vez de atuar"
  },
  AvgDialog_131213_Content_9 = {
    Text = "Apóstolo do Deus Supremo, mensageiro da loucura do Caos. Sua luz ilumina a prisão eterna, eu ouvi sua chamada da voz do Caos."
  },
  AvgDialog_131213_Content_90 = {
    Text = "Dedilhas os Fios outrora invisíveis como se movesses blocos num berçário."
  },
  AvgDialog_131213_Content_91 = {
    Text = "À medida que a teia se remodela, as Dimensão Cinzas roubadas voam de volta para ela."
  },
  AvgDialog_131213_Content_92 = {
    Text = "Areia fina de cor roxa escura e infinita flui ao redor de Arachne, girando em torno dela. Em sua criação, aquelas que nunca foram roubadas pelas Dimensão Cinzas."
  },
  AvgDialog_131213_Content_93 = {
    Text = "<color=#8C7E96>No passado, no futuro, elas pertencem para sempre a Arachne.</color>"
  },
  AvgDialog_131213_Content_94 = {
    Text = "Arachne sorri e acena para você, escondendo aquelas cinzas em seu corpo. Sua roca nunca para. Seu sorriso nunca muda."
  },
  AvgDialog_131213_Content_95 = {
    Text = "Você balança a cabeça no palco e solta um suspiro exagerado."
  },
  AvgDialog_131213_Content_96 = {
    Text = "Morto, sem paixão... Você poderia ser uma pessoa tão interessante, Arachne."
  },
  AvgDialog_131213_Content_97 = {
    Text = "Você, assim como Tawil, é um voyeur do destino e também um servo do destino. A felicidade que sinto agora, vocês nunca poderão experimentar."
  },
  AvgDialog_131213_Content_98 = {
    Text = "Olhe para essa sua cara sem vida, Arachne. Sinto muito por vocês."
  },
  AvgDialog_131213_Content_99 = {
    Text = "Todos fazem a sua escolha, %player%... ou devo chamar-te Apóstolo? Ou talvez... \"N\"?"
  },
  AvgDialog_131214_Content_1 = {
    Text = "<Shake:AAAAARGH!!>"
  },
  AvgDialog_131214_Content_10 = {
    Text = "Porque... nossa vingança ainda não acabou, nunca acabará..."
  },
  AvgDialog_131214_Content_11 = {
    Text = "Você recuou um passo instintivamente. Mas não havia nenhuma onda de perigo vindo de Nefraea."
  },
  AvgDialog_131214_Content_12 = {
    Text = "Ela apenas balançou as patas, puxando para baixo o véu que cobria seu lado, revelando a cena por trás do pano."
  },
  AvgDialog_131214_Content_13 = {
    Text = "Isso é...!"
  },
  AvgDialog_131214_Content_14 = {
    Text = "Os fios carmesins conectam vários palcos dentro do teatro, conectam esta magnífica cidade onde se encontra o teatro, conectam inúmeras marionetes na cidade, fundindo-se no corpo dilacerado de Nefraea."
  },
  AvgDialog_131214_Content_15 = {
    Text = "Você... não prendeu o fio na roca?!"
  },
  AvgDialog_131214_Content_16 = {
    Text = "Ela já viu o final. Ela viu seu fracasso. Enquanto ainda tinha força, ela atou esses destinos a si mesma, como..."
  },
  AvgDialog_131214_Content_17 = {
    Text = "Assim como quando você me matou pela primeira vez."
  },
  AvgDialog_131214_Content_18 = {
    Text = "Nefraea sorriu, enquanto levantava uma linha muito oculta à sua frente."
  },
  AvgDialog_131214_Content_19 = {
    Text = "Aquela linha carmesim se estendia de sua nuca, passando por uma longa e cuidadosa jornada, ocultamente se reunindo ao corpo de Arachne."
  },
  AvgDialog_131214_Content_2 = {Text = "Boom—"},
  AvgDialog_131214_Content_20 = {
    Text = "Há muito tempo não estamos tão próximos, irmã. Foi só agora que encontrei a oportunidade de te devolver este fio de seda."
  },
  AvgDialog_131214_Content_21 = {
    Text = "\"Ainda\"...?"
  },
  AvgDialog_131214_Content_22 = {
    Text = "Esse fio... é aquele que cortei na primeira vez que destruí minha criação."
  },
  AvgDialog_131214_Content_23 = {
    Text = "Seu romance, sua bondade, suas memórias... tudo em mim já foi devolvido a você."
  },
  AvgDialog_131214_Content_24 = {
    Text = "Você completou, Arachne."
  },
  AvgDialog_131214_Content_25 = {
    Text = "Os lábios de Nefraea se curvaram, como uma criança escondida atrás de uma cortina, observando os adultos sendo enganados por suas travessuras."
  },
  AvgDialog_131214_Content_26 = {
    Text = "Nos momentos em que você possui poder... é isso que você quer fazer?"
  },
  AvgDialog_131214_Content_27 = {
    Text = "Como está? Uma ideia brilhante, não é"
  },
  AvgDialog_131214_Content_28 = {
    Text = "Venha, me mate! Destrua completamente aqueles destinos que você já abandonou! Destrua esta cidade onde você reside, destrua este teatro que você ama, destrua cada uma das pessoas aqui"
  },
  AvgDialog_131214_Content_29 = {
    Text = "Venha, Arachne! Traga todas as suas fraquezas, <Shake:mate tudo o que você ama, mais uma vez!!!>"
  },
  AvgDialog_131214_Content_3 = {
    Text = "Gritos de dor e o som de colapsos ecoaram pelo teatro em ruínas. O fio carmesim se rompeu aos poucos, e a roda de fiar que acompanhou Nefraea durante toda sua vida caiu diante dela."
  },
  AvgDialog_131214_Content_30 = {
    Text = "O grito excitado e as risadas de Nefraea ecoam no teatro em ruínas."
  },
  AvgDialog_131214_Content_31 = {
    Text = "O corpo de Arachne parecia ter se tornado mais pesado do que nunca. Ela lentamente girou a cabeça, olhando tudo que estava conectado a Nefraea."
  },
  AvgDialog_131214_Content_32 = {
    Text = "Através da fenda do teatro, ela viu carros e multidões lotando esta cidade próspera. Aqueles rostos familiares com nomes familiares estavam espalhados em cada canto que ela conhecia bem."
  },
  AvgDialog_131214_Content_33 = {
    Text = "Ela viu o palco que você havia pisado junto com ela. A guerra brutal havia terminado, e aquele mundo estava prestes a receber seus duzentos anos de longa e gloriosa paz."
  },
  AvgDialog_131214_Content_34 = {
    Text = "Naquela gosma negra, ela viu o rosto da mãe. Ela estava sentada com o pai sob o bétula branca no pátio, acenando para si mesma."
  },
  AvgDialog_131214_Content_35 = {
    Text = "O Senhor Lawrence está ao lado deles, polindo os talheres feitos especialmente para ela."
  },
  AvgDialog_131214_Content_36 = {
    Text = "Você chama isso de vingança, porque nunca viu claramente o destino, nem a mim, Nefraea."
  },
  AvgDialog_131214_Content_37 = {
    Text = "Uma linha coberta de muco conecta Arachne ao palco quebrado sob os pés de Nefraea. Arrastando seu corpo pesado, Arachne pisa na frágil linha."
  },
  AvgDialog_131214_Content_38 = {
    Text = "O fio treme como se pudesse se romper e lançar o Prisioneiro do Destino no abismo."
  },
  AvgDialog_131214_Content_39 = {
    Text = "Arachne olhou calmamente para os olhos surpresos de Nefraea. Seus passos nunca pararam por um momento."
  },
  AvgDialog_131214_Content_4 = {
    Text = "Ela segurou a roca como um bebê que caiu na água. Em suas mãos, a roca sombria desmoronou irresistivelmente, transformando-se em cinzas de dimensão, fundindo-se na areia movediça ao lado de Arachne."
  },
  AvgDialog_131214_Content_40 = {
    Text = "O momento destinado está chegando..."
  },
  AvgDialog_131214_Content_41 = {
    Text = "Arachne levantou a roca em sua mão sobre a teia. Você pode ver claramente o mundo inteiro parar por um instante, todo o universo conectado a este teatro, aguardando seu decreto."
  },
  AvgDialog_131214_Content_42 = {
    Text = "Eu, em nome do destino, declaro aqui—"
  },
  AvgDialog_131214_Content_43 = {
    Text = "Todos os destinos errôneos serão enterrados na poeira do tempo. O destino do mundo retornará ao seu curso pretendido."
  },
  AvgDialog_131214_Content_44 = {
    Text = "O destino errado termina aqui. Os abandonados encontrarão descanso..."
  },
  AvgDialog_131214_Content_45 = {
    Text = "A roca se inclina, milhares de fios tremem em resposta."
  },
  AvgDialog_131214_Content_46 = {
    Text = "O fio se rompe. Aguardando o palco da paz, desmoronando e desaparecendo."
  },
  AvgDialog_131214_Content_47 = {
    Text = "O fio se rompe. Nas fendas do teatro, não se vê mais o traço da cidade."
  },
  AvgDialog_131214_Content_48 = {
    Text = "O fio se rompe, se rompe, se rompe..."
  },
  AvgDialog_131214_Content_49 = {
    Text = "Você tem dificuldade em ver os fios do destino, mas pode ouvir claramente o choro do destino."
  },
  AvgDialog_131214_Content_5 = {
    Text = "Nefraea ficou olhando fixamente para essa esperança que passava, e de repente começou a rir."
  },
  AvgDialog_131214_Content_50 = {
    Text = "Incontáveis vidas passadas e presentes de pessoas, inumeráveis alegrias e tristezas se quebram, se desintegram, se reconstroem, se aniquilam ao seu redor..."
  },
  AvgDialog_131214_Content_51 = {Text = "...luz?"},
  AvgDialog_131214_Content_52 = {
    Text = "As luzes do palco, que vieram de algum lugar desconhecido, acendem-se. A luz penetra o teatro em ruínas, e aqueles abandonados que se escondem nas sombras desaparecem no momento em que a luz cai, como se nunca tivessem aparecido."
  },
  AvgDialog_131214_Content_53 = {
    Text = "Arachne, irmã, você..."
  },
  AvgDialog_131214_Content_54 = {
    Text = "Arachne trouxe a roca giratória, pisando naquela frágil linha de seda, e chegou à sua frente. Nefraea olhou para ela, como se olhasse para o destino irreversível em si."
  },
  AvgDialog_131214_Content_55 = {
    Text = "Chegue perto de mim, Nefraea."
  },
  AvgDialog_131214_Content_56 = {
    Text = "Arachne segurou a mão de Nefraea e a colocou em sua bochecha."
  },
  AvgDialog_131214_Content_57 = {
    Text = "No momento em que tocou Arachne, uma porta oculta se abriu para Nefraea. Nefraea atravessou as camadas de gaiolas, finalmente chegando diante de Arachne pela primeira vez."
  },
  AvgDialog_131214_Content_58 = {
    Text = "Naquela jaula, ela viu três rostos familiares."
  },
  AvgDialog_131214_Content_59 = {
    Text = "Arachne!!!você......"
  },
  AvgDialog_131214_Content_6 = {
    Text = "O riso dela aumentava, quase sem forças para se erguer. Sangue escorria de seu corpo tremulo, tingindo os fragmentos escuros da roca."
  },
  AvgDialog_131214_Content_60 = {
    Text = "<Shake:\"Romântico\", Bondade, Homenagem... eles... eles...>"
  },
  AvgDialog_131214_Content_61 = {
    Text = "Nunca consegui abandoná-los completamente. Nunca consegui realmente abandonar você."
  },
  AvgDialog_131214_Content_62 = {
    Text = "Mas você disse que não consegue suportar isso..."
  },
  AvgDialog_131214_Content_63 = {
    Text = "Tolo, Frágil, destruindo dolorosamente tudo o que valorizo... você não pode se vingar de mim assim, Nefraea."
  },
  AvgDialog_131214_Content_64 = {
    Text = "Porque esta é a punição que o destino já havia determinado para mim."
  },
  AvgDialog_131214_Content_65 = {
    Text = "Arachne sorriu para ela calmamente. Seu fuso girava, eternamente."
  },
  AvgDialog_131214_Content_66 = {
    Text = "Acabou, Nefraea."
  },
  AvgDialog_131214_Content_67 = {
    Text = "Uma corda de violão vibra suavemente. Nefraea ouviu o canto de uma garça branca, como quando era muito, muito pequena, no dia em que seu pai lhe trouxe aquele fuso chamado Moira."
  },
  AvgDialog_131214_Content_68 = {
    Text = "Este é o quarto que pertence a ela, a bétula do lado de fora é sua amiga fiel, uma prisioneira solitária imutável desde os tempos imemoriais."
  },
  AvgDialog_131214_Content_69 = {
    Text = "Eles estão presos pelo destino, dependendo um do outro aqui."
  },
  AvgDialog_131214_Content_7 = {
    Text = "O desfecho, o desfecho realmente não pode ser mudado... Isso é o destino..."
  },
  AvgDialog_131214_Content_70 = {
    Text = "Creak—Yaa—"
  },
  AvgDialog_131214_Content_71 = {
    Text = "A porta de madeira simples foi empurrada, Arachne se aproximou dela, inclinou-se e acariciou suavemente seu rosto."
  },
  AvgDialog_131214_Content_72 = {
    Text = "Irmã... eu perdi... nós perdemos..."
  },
  AvgDialog_131214_Content_73 = {
    Text = "Nunca tivemos o direito de ganhar."
  },
  AvgDialog_131214_Content_74 = {
    Text = "Você se lembra do desejo que fizemos no dia em que recebemos a roda de fiar?"
  },
  AvgDialog_131214_Content_75 = {
    Text = "\"Não desperdiçarei os dons do Destino... Trarei um belo destino a este mundo...\""
  },
  AvgDialog_131214_Content_76 = {
    Text = "Que desejo tão infantil, Arachne... Naquela época, não entendíamos o que isso significava."
  },
  AvgDialog_131214_Content_77 = {
    Text = "Arachne estendeu a mão levemente tremulante, acariciando o rosto distante de si mesma."
  },
  AvgDialog_131214_Content_78 = {
    Text = "Destino... quem realmente pode ver claramente."
  },
  AvgDialog_131214_Content_79 = {
    Text = "Mas mesmo que eu possa prever, minha escolha ainda não mudará."
  },
  AvgDialog_131214_Content_8 = {
    Text = "Esta vitória trágica, você já a viu, não é, Arachne?"
  },
  AvgDialog_131214_Content_80 = {
    Text = "<Shake:Por que, Arachne?> Você pode ir embora, você pode desistir, você pode..."
  },
  AvgDialog_131214_Content_81 = {
    Text = "Depois de deixar o abismo, você poderia ter a liberdade eterna. Você sabe que acabará falhando, mas ainda assim vem tentar trazer libertação para mim e para aqueles que seguem seu destino."
  },
  AvgDialog_131214_Content_82 = {
    Text = "Cada manipulador do destino se tornará um prisioneiro do destino, você e eu somos assim. Não é verdade, Nefraea?"
  },
  AvgDialog_131214_Content_83 = {
    Text = "Nefraea ficou em silêncio, olhando tristemente para o bétula do lado de fora da janela. Ela observou a árvore brotar, germinar, crescer e murchar."
  },
  AvgDialog_131214_Content_84 = {
    Text = "Ela suspirou suavemente, levantou a cabeça e acariciou as lágrimas que caíam lentamente do rosto de Arachne. Ela sorriu para ela."
  },
  AvgDialog_131214_Content_85 = {
    Text = "É tão bom ver você novamente... irmã."
  },
  AvgDialog_131214_Content_86 = {
    Text = "Uma lágrima leve caiu, pingando naquele rosto idêntico ao de Arachne."
  },
  AvgDialog_131214_Content_87 = {
    Text = "Desculpe-me pelo meu egoísmo..."
  },
  AvgDialog_131214_Content_88 = {
    Text = "Você... está livre, <Red:\"Arachne\">."
  },
  AvgDialog_131214_Content_89 = {Text = "Chiado."},
  AvgDialog_131214_Content_9 = {
    Text = "Recentemente, você também espiou tudo isso por um breve momento. Uma vez que já sabe qual é o desfecho, por que ainda se apegar a isso?"
  },
  AvgDialog_131214_Content_90 = {
    Text = "Quando o último fio se rompe, uma estrondosa salva de palmas irrompe."
  },
  AvgDialog_131214_Content_91 = {
    Text = "O palco, que sempre esteve vazio, agora está lotado. Os destinos abandonados e os fantoches que morreram em suas mãos estão abarrotando cada uma das cadeiras de veludo rasgadas."
  },
  AvgDialog_131214_Content_92 = {
    Text = "Os atores tomam seus lugares entre a plateia, assistindo ao desfecho se desenrolar neste palco destroçado em silêncio."
  },
  AvgDialog_131214_Content_93 = {
    Text = "Eles estão impassíveis, sem um som. \n Eles aplaudem entusiasticamente. Os aplausos são estrondosos e duradouros."
  },
  AvgDialog_131215_Content_1 = {Text = "Personagem"},
  AvgDialog_131215_Content_10 = {
    Text = "Eu não entendia antes por que Arachne queria excluir sua irmã da Rede do destino, e por que você queria obter poder de aqueles três ícones secretos."
  },
  AvgDialog_131215_Content_100 = {Text = "..."},
  AvgDialog_131215_Content_101 = {
    Text = "A deusa do destino, resiliente e fútil... quão desesperador, quão bela é essa cena..."
  },
  AvgDialog_131215_Content_102 = {
    Text = "Vocês dizem que ela faz isso por quê?"
  },
  AvgDialog_131215_Content_103 = {
    Text = "Nefraea olhava para aquele palco simples com atenção, sua voz tão baixa que parecia um sussurro."
  },
  AvgDialog_131215_Content_104 = {
    Text = "Isto é apenas um sonho, a deusa do destino... você poderia escolher o destino mais alegre para todos, você pode corrigir suas fantasias irreais e satisfazer tudo o que deseja."
  },
  AvgDialog_131215_Content_105 = {
    Text = "Mas você nunca pensou em fazer isso... Ao criar a perfeição, você também cria o sofrimento. Você traz o sofrimento a este mundo repetidamente."
  },
  AvgDialog_131215_Content_106 = {
    Text = "Você se esforçou ao máximo para tecer a grande rede do destino, mas a cena dentro daquela porta, o desfecho predestinado, nós dois já havíamos visto."
  },
  AvgDialog_131215_Content_107 = {
    Text = "No momento em que a rede do destino é tecida, é a hora em que aquela pessoa suprema desperta completamente..."
  },
  AvgDialog_131215_Content_108 = {Text = "O que...?!"},
  AvgDialog_131215_Content_109 = {
    Text = "Você olha para Arachne, esperando receber uma resposta negativa de seu rosto."
  },
  AvgDialog_131215_Content_11 = {
    Text = "Pelo menos, eu tenho que agradecer por você ter esclarecido minhas dúvidas."
  },
  AvgDialog_131215_Content_110 = {
    Text = "Você encontra apenas sua calma habitual e eterna. No palco do Destino, a serenidade é uma máscara que ela não consegue remover."
  },
  AvgDialog_131215_Content_111 = {
    Text = "Irmã, você não pode parar de tecer, pois não suporta ver o universo mergulhar no caos. Mas no dia em que sua teia estiver concluída, será você mesma quem enterrará tudo o que ama com suas próprias mãos."
  },
  AvgDialog_131215_Content_112 = {
    Text = "Que ironia, Arachne. Por quê? Por que não deixar este universo saudar o fim destinado com prazer?"
  },
  AvgDialog_131215_Content_113 = {
    Text = "Tudo que é destino tem um determinante. Tudo que é destino tem uma variável. Esses dois provérbios conflitantes são a essência do destino."
  },
  AvgDialog_131215_Content_114 = {
    Text = "Arachne olhou nos olhos de Nefraea e respondeu a essa pergunta que ela havia respondido a si mesma inúmeras vezes."
  },
  AvgDialog_131215_Content_115 = {
    Text = "Nefraea, na dimensão sem fim, ainda há inúmeras pessoas lutando por aquela variável."
  },
  AvgDialog_131215_Content_116 = {
    Text = "Manter o funcionamento do palco, esperar a aparição das variáveis... Esses são os grilhões que o destino me impôs. Essa é a responsabilidade da qual não posso escapar."
  },
  AvgDialog_131215_Content_117 = {
    Text = "Deveres, perigos... você fala de tudo isso grandioso, mas nunca fala de si mesma, Arachne, minha pobre irmã. Mas não se preocupe, seu doloroso dever está prestes a acabar."
  },
  AvgDialog_131215_Content_118 = {
    Text = "Nefraea acariciou o rosto de Arachne com ternura, mostrando-lhe um doce sorriso."
  },
  AvgDialog_131215_Content_119 = {
    Text = "No abismo, imaginei inúmeras vezes a cena do nosso reencontro, pensando em que tipo de presente poderia corresponder a essa nossa reunião."
  },
  AvgDialog_131215_Content_12 = {
    Text = "Por que não me contaram sobre essas coisas antes?"
  },
  AvgDialog_131215_Content_120 = {
    Text = "Pensei por muito, muito tempo. Eu pensei, querida irmã! Este é o melhor presente que posso te dar——"
  },
  AvgDialog_131215_Content_121 = {
    Text = "Eu lhe concedo... <Red:Exorcismo.>"
  },
  AvgDialog_131215_Content_122 = {
    Text = "Na suave fala de Nefraea, a substância pegajosa negra se reúne entre as fendas da Dimensão. No final da teia, um grandioso palco aparece diante de vocês."
  },
  AvgDialog_131215_Content_13 = {
    Text = "Você olha para a Arachne ao seu lado, que guia seus passos."
  },
  AvgDialog_131215_Content_14 = {
    Text = "Uma pedra que não provoca nenhuma ondulação no lago do destino, além de destruir a tranquilidade do lago, é de nenhuma utilidade."
  },
  AvgDialog_131215_Content_15 = {
    Text = "Ela e eu nos tornamos duas pessoas distintas há muito tempo, {Male=Mr.,Female=Miss} Guardião."
  },
  AvgDialog_131215_Content_16 = {
    Text = "Você previu este dia?"
  },
  AvgDialog_131215_Content_17 = {
    Text = "Nenhum prisioneiro vê seu próprio destino até que o julgamento seja proferido."
  },
  AvgDialog_131215_Content_18 = {
    Text = "Se você souber que aqueles destinos abandonados não desaparecerão, mas serão exilados para o eterno abismo... você ainda faria essas coisas, Arachne?"
  },
  AvgDialog_131215_Content_19 = {Text = "..."},
  AvgDialog_131215_Content_2 = {Text = "Lalalala"},
  AvgDialog_131215_Content_20 = {
    Text = "Silêncio. O silêncio é a catástrofe duradoura do autor da peça. O silêncio é a defesa impotente do prisioneiro. Em um silêncio de pena capital, ressoa a risada insana de Nefraea."
  },
  AvgDialog_131215_Content_21 = {
    Text = "Ah, você com certeza vai conseguir, irmã. O destino é sua doutrina, todas, todas as condições não podem mudar sua única resposta."
  },
  AvgDialog_131215_Content_22 = {
    Text = "A deusa do destino, quão pequena, quão frágil, quão cruel..."
  },
  AvgDialog_131215_Content_23 = {
    Text = "Mas não importa. Não importa o que você faça, durante todo esse tempo eu sempre estive pensando em você, minha boa irmã."
  },
  AvgDialog_131215_Content_24 = {
    Text = "Romance, bondade, memórias. Uma mistura maravilhosa de ingredientes, fermentando, transforma o sorriso de Nefraea em um doce veneno."
  },
  AvgDialog_131215_Content_25 = {
    Text = "Na sua sorriso radiante, a luz ao lado da estrada de teia de aranha ilumina o palco."
  },
  AvgDialog_131215_Content_26 = {
    Text = "Irmã, {Male=Mr.,Female=Miss} Guardião... estas novas peças são um presente meu, o novo mestre do teatro."
  },
  AvgDialog_131215_Content_27 = {
    Text = "Antes da grandiosa terceira ato, aprecie bem essa maravilhosa abertura... Lembre-se das regras de etiqueta do Teatro do Destino, não fale, ok"
  },
  AvgDialog_131215_Content_28 = {
    Text = "Nefraea abriu os braços como um Anunciador. O palco, vasto como as estrelas, acende-se um a um à medida que vocês passam lentamente."
  },
  AvgDialog_131215_Content_29 = {Text = "..."},
  AvgDialog_131215_Content_3 = {
    Text = "Elas dançam. Elas cantam. Guinch guinch~"
  },
  AvgDialog_131215_Content_30 = {
    Text = "Querida Deusa do Destino, os corpos das três consortes secretas já estão preparados para você."
  },
  AvgDialog_131215_Content_31 = {
    Text = "Que bonecos tão refinados... Aquilo que foi perdido, irá se reproduzir neles..."
  },
  AvgDialog_131215_Content_32 = {
    Text = "\"Arachne\" saiu do tear e foi até a frente da marionete."
  },
  AvgDialog_131215_Content_33 = {
    Text = "A primeira, eu te dou como \"romântico\"."
  },
  AvgDialog_131215_Content_34 = {
    Text = "Você é o capítulo mais apaixonado da sinfonia, uma coleção de emoções, os frutos das flores da primavera."
  },
  AvgDialog_131215_Content_35 = {
    Text = "Você irá ao paraíso da meia-noite, trazendo para esta cidade vinhos, encontros e impulsos que nunca se apagam."
  },
  AvgDialog_131215_Content_36 = {
    Text = "Obrigado, grande deusa do destino Arachne. De acordo com sua vontade, o vinho e o mel fluirão entre meus lábios."
  },
  AvgDialog_131215_Content_37 = {
    Text = "A bela mulher cumprimentou \"Arachne\"."
  },
  AvgDialog_131215_Content_38 = {
    Text = "A segunda, eu te concedo como \"bondade\"."
  },
  AvgDialog_131215_Content_39 = {
    Text = "Você é o velho que me acompanhou durante a infância. Você é a pena branca deixada por um anjo, é a luz do sol mais sagrada."
  },
  AvgDialog_131215_Content_4 = {
    Text = "Histórias antigas e passos alegres tremulam juntos na teia de aranha. Nefraea caminha alegremente para frente, com as mãos nas costas."
  },
  AvgDialog_131215_Content_40 = {
    Text = "Você virá para as ruas da cidade e aquecerá tudo o que vê com sua bondade."
  },
  AvgDialog_131215_Content_41 = {
    Text = "Obrigado! Grande deusa do destino Arachne. Minha vida foi dada por você, e não sei como retribuir."
  },
  AvgDialog_131215_Content_42 = {
    Text = "Eu não tenho nada, exceto o amor por tudo neste mundo. Vou proteger o que deve ser protegido e ajudar o que deve ser ajudado."
  },
  AvgDialog_131215_Content_43 = {
    Text = "Tudo o que sou está aberto aos sofredores."
  },
  AvgDialog_131215_Content_44 = {
    Text = "O velho bondoso se curvou profundamente para \"Arachne\"."
  },
  AvgDialog_131215_Content_45 = {
    Text = "E você, o terceiro... eu te concedo o título de \"memória\"."
  },
  AvgDialog_131215_Content_46 = {
    Text = "\"Arachne\" chegou diante do ícone secreto pequeno, agachou-se e olhou para os olhos que não existiam."
  },
  AvgDialog_131215_Content_47 = {
    Text = "Você é um órfão do destino, enterrado nas folhas secas da neve profunda."
  },
  AvgDialog_131215_Content_48 = {
    Text = "Você marcha solitária e penosa, sem conseguir falar, desconhecida por todos."
  },
  AvgDialog_131215_Content_49 = {
    Text = "Em sua longa e tranquila vida, você será o único guardião dessas memórias."
  },
  AvgDialog_131215_Content_5 = {
    Text = "Você segue inabalavelmente atrás de Arachne, caminhando ao longo da teia em direção ao fim."
  },
  AvgDialog_131215_Content_50 = {
    Text = "A menina silenciosa levantou a cabeça e acariciou o rosto de \"Arachne\"."
  },
  AvgDialog_131215_Content_51 = {
    Text = "\"Arachne\" se levantou e olhou suavemente para seus ícones secretos."
  },
  AvgDialog_131215_Content_52 = {
    Text = "Vão, meus filhos. Diante do tear do destino, eu os observarei para sempre."
  },
  AvgDialog_131215_Content_53 = {
    Text = "Aqueles que foram abandonados pela eternidade, florescerão um a um em seu destino."
  },
  AvgDialog_131215_Content_54 = {Text = "..."},
  AvgDialog_131215_Content_55 = {
    Text = "O palco escurece. À medida que vocês caminham, as luzes do próximo palco acendem."
  },
  AvgDialog_131215_Content_56 = {
    Text = "A luz do sol não existe aqui. Vento, flores, nuvens... Depois de três longos séculos, o calendário também não existe mais..."
  },
  AvgDialog_131215_Content_57 = {
    Text = "Mestre, um novo abandonado chegou."
  },
  AvgDialog_131215_Content_58 = {
    Text = "O oboé toca um floreio. Os esfarrapados Abandonados aparecem."
  },
  AvgDialog_131215_Content_59 = {
    Text = "\"Nefraea\" levantou-se e foi para o centro do palco."
  },
  AvgDialog_131215_Content_6 = {
    Text = "E então, {Male=Mr.,Female=Miss} Guardião? A apresentação foi espetacular? Especialmente com aquela espiada nos bastidores?"
  },
  AvgDialog_131215_Content_60 = {
    Text = "Diga-me, crianças pobres... quem são vocês e de onde vêm?"
  },
  AvgDialog_131215_Content_61 = {
    Text = "Deusa do destino, por favor, perdoe minha falta de respeito... mas a raiva me obriga a perguntar a você."
  },
  AvgDialog_131215_Content_62 = {
    Text = "Enfrentei perigos, deixando uma grande canção com minha coragem e vida, que deveria, junto à minha terra natal, alcançar o fim do universo."
  },
  AvgDialog_131215_Content_63 = {
    Text = "Por quê, grande deusa... por que nos expulsou para estas terras selvagens? <Shake:Por que transformou aquelas melodias imortais em pó!>"
  },
  AvgDialog_131215_Content_64 = {
    Text = "Meus soldados acabaram de passar por um longo inverno. Repelimos os invasores bárbaros e defendemos nossa civilização e história."
  },
  AvgDialog_131215_Content_65 = {
    Text = "Nos momentos mais brutais, os soldados feridos oferecem voluntariamente sua carne e sangue para alimentar seus companheiros de batalha... Que vitória tão dolorosa, minha deusa."
  },
  AvgDialog_131215_Content_66 = {
    Text = "Quando os inimigos recuam, lágrimas de alegria enchem os olhos de todos. No banquete de celebração, vou encher cada taça de vinho forte para os soldados."
  },
  AvgDialog_131215_Content_67 = {
    Text = "Mas nesse momento, antes mesmo de brindarmos, nosso lar se tornou uma ruína, e nossos entes queridos se desintegraram em poeira..."
  },
  AvgDialog_131215_Content_68 = {
    Text = "<Shake:Amada Deusa, não nos concederia sequer um único momento de alegria?>"
  },
  AvgDialog_131215_Content_69 = {Text = "..."},
  AvgDialog_131215_Content_7 = {
    Text = "Nefraea já se desvinculou daquele estado de loucura no palco, ela se virou e olhou para você com grande expectativa."
  },
  AvgDialog_131215_Content_70 = {
    Text = "\"Nefraea\" ouvia os bonecos como se estivessem contando uma história sem fim, e duas linhas de lágrimas caíram em seu rosto sem feições."
  },
  AvgDialog_131215_Content_71 = {
    Text = "Eu ouvi vocês, eu vi vocês..."
  },
  AvgDialog_131215_Content_72 = {
    Text = "A grande civilização desapareceu de suas mãos; as magníficas obras de arte se tornaram pó. As pessoas amadas esquecem tudo uma da outra, enfrentando a dolorosa extinção com temor..."
  },
  AvgDialog_131215_Content_73 = {
    Text = "Apenas um destino correto será deixado, enquanto todos os erros que ocorreram naquele momento se precipitam para este abismo sem fim e selvagem. Tão longo como o tempo parado, histórias assim se desenrolam todos os dias."
  },
  AvgDialog_131215_Content_74 = {
    Text = "Por quanto tempo você quer que eu veja e ouça, minha querida irmã..."
  },
  AvgDialog_131215_Content_75 = {
    Text = "\"Nefraea\" virou-se para o público e respirou fundo."
  },
  AvgDialog_131215_Content_76 = {
    Text = "Não se preocupe, meus bons filhos... O sofrimento de vocês foi criado por mim, e será encerrado por mim."
  },
  AvgDialog_131215_Content_77 = {
    Text = "Por favor, descansem aqui por um tempo. Um dia, eu os levarei para fora daqui, farei com que vocês recuperem o destino que lhes pertence..."
  },
  AvgDialog_131215_Content_78 = {
    Text = "Em nome da vingadora do destino, Nefraea, eu vos prometo..."
  },
  AvgDialog_131215_Content_79 = {Text = "..."},
  AvgDialog_131215_Content_8 = {
    Text = "Ela balançou a cabeça desapontada ao ver seu rosto silencioso."
  },
  AvgDialog_131215_Content_80 = {
    Text = "Lalalala... lalala..."
  },
  AvgDialog_131215_Content_81 = {
    Text = "O palco se afastava gradualmente, e antes que as luzes se apagassem, você viu os braços abertos da boneca e a marca de lágrima negra em seu rosto."
  },
  AvgDialog_131215_Content_82 = {
    Text = "Vocês não conversaram, apenas Nefraea cantava suavemente a melodia no palco. Sua canção soava rápida e clara, esta história que foi apresentada inúmeras vezes não lhe gerou mais nenhuma emoção excessiva."
  },
  AvgDialog_131215_Content_83 = {
    Text = "Ai! Meu palco favorito está chegando! Mais rápido, irmã"
  },
  AvgDialog_131215_Content_84 = {
    Text = "A voz de Nefraea se empolgou. Ela puxou a mão de Arachne e correu alegremente em direção ao palco à frente."
  },
  AvgDialog_131215_Content_85 = {Text = "..."},
  AvgDialog_131215_Content_86 = {
    Text = "As luzes se acendem. Não há música, nem diálogo — apenas uma marionete solitária diante de uma roda de fiar em um palco vazio."
  },
  AvgDialog_131215_Content_87 = {
    Text = "Crujido, crujido. A roda gira, como se o dia em que ela parará jamais fosse chegar."
  },
  AvgDialog_131215_Content_88 = {
    Text = "... Elas dançam. Elas cantam. Guinch——guinch——"
  },
  AvgDialog_131215_Content_89 = {
    Text = "A luz do sol ilumina seus rostos, que alegria —"
  },
  AvgDialog_131215_Content_9 = {
    Text = "Nenhum aplauso, nem lágrimas. O silêncio é uma humilhação... Eu pensei que, depois de ensaiar tanto no abismo, essa apresentação já estivesse perfeita, que pena, que pena."
  },
  AvgDialog_131215_Content_90 = {
    Text = "A canção saiu suavemente do rosto sem traços de \"Arachne\", enquanto ela girava o fuso de forma tranquila, sem pressa e sem lentidão."
  },
  AvgDialog_131215_Content_91 = {
    Text = "É um ritmo assombroso — basta um olhar para saber que, uma vez iniciado, jamais mudará até o fim de todas as coisas."
  },
  AvgDialog_131215_Content_92 = {
    Text = "A deusa do destino está prestes a tecer sua rede."
  },
  AvgDialog_131215_Content_93 = {
    Text = "A teia do destino completa, cuida de todas as pessoas... Elas dançam, elas cantam..."
  },
  AvgDialog_131215_Content_94 = {
    Text = "Uma enorme rede foi tecida pelo tear, cobrindo todo o palco. O excesso da rede do destino se estende para fora do palco."
  },
  AvgDialog_131215_Content_95 = {
    Text = "Toda vez que a teia se aproxima da conclusão, suas bordas mais externas começam a se desfazer."
  },
  AvgDialog_131215_Content_96 = {
    Text = "Gosma negra, pó negro, que acaba desaparecendo. É uma cena que você conhece muito bem."
  },
  AvgDialog_131215_Content_97 = {
    Text = "Celebre, meu filho, meu povo... a deusa do destino está prestes a tecer sua rede..."
  },
  AvgDialog_131215_Content_98 = {
    Text = "A marionete observa as redes que são constantemente tecidas e desaparecem."
  },
  AvgDialog_131215_Content_99 = {
    Text = "Sua voz não tremia, seus movimentos não hesitavam. Ela ainda cantava suavemente uma canção, a roca em suas mãos girava, sem parar."
  },
  AvgDialog_131216_Content_1 = {
    Text = "Festa de Máscaras"
  },
  AvgDialog_131216_Content_10 = {
    Text = "Um padrão duplo bastante descarado, Veterano."
  },
  AvgDialog_131216_Content_11 = {
    Text = "Ahem... Fazer julgamentos que se alinhem com o caráter de cada pessoa é uma habilidade básica para um Investigador..."
  },
  AvgDialog_131216_Content_12 = {
    Text = "William, o companheiro mais velho finge não perceber a sua provocação e começa a procurar seriamente um alvo digno de abordagem."
  },
  AvgDialog_131216_Content_13 = {
    Text = "Perdi tudo naquela batalha. O meu título, a minha família, a minha perna esquerda... a minha vida."
  },
  AvgDialog_131216_Content_14 = {
    Text = "Vinte anos. Vinte anos inteiros. Tem sido uma tortura lenta, meu amigo. O Destino achou por bem deixar-me viver, condenando-me a passar os meus dias restantes a expiar os meus erros."
  },
  AvgDialog_131216_Content_15 = {
    Text = "Destruí a minha própria linhagem com as minhas próprias mãos, mas que importa agora? Diga-me, há algo nesta vida mais importante do que um copo?"
  },
  AvgDialog_131216_Content_16 = {Text = "..."},
  AvgDialog_131216_Content_17 = {
    Text = "Oh, querido, lembra-se do cocktail que o barman preparou para nós da última vez que estivemos aqui?"
  },
  AvgDialog_131216_Content_18 = {
    Text = "Aposto que não encontrará uma bebida melhor em toda Londinium. Era tão preciso, tão elegante—parecia menos uma receita e mais uma profecia!"
  },
  AvgDialog_131216_Content_19 = {
    Text = "Estava a pensar como seria maravilhoso se pudéssemos convidar aquele barman para a nossa festa no próximo mês."
  },
  AvgDialog_131216_Content_2 = {
    Text = "\"90 minutos após a meia-noite, uma máscara de 15 polegadas, 10 galões de sonho, 2 onças de destilado—a única fórmula para a felicidade.\""
  },
  AvgDialog_131216_Content_20 = {Text = "..."},
  AvgDialog_131216_Content_21 = {Text = "Estalo—"},
  AvgDialog_131216_Content_22 = {
    Text = "Um estalo seco de dedos ecoa como um fogos de artifício ao lado do seu ouvido. Você se vira e encontra um rosto brilhando com um sorriso radiante."
  },
  AvgDialog_131216_Content_23 = {
    Text = "Desculpe interromper, estimado convidado. Com tantos tópicos interessantes, que tal acompanhar com uma bebida divertida?"
  },
  AvgDialog_131216_Content_24 = {
    Text = "Dê uma olhada na carta de bebidas, William, o companheiro mais velho."
  },
  AvgDialog_131216_Content_25 = {
    Text = "William entendeu seu olhar. Duas pessoas vestindo uniformes desconhecidos apareceram neste lugar, sem tocar em uma gota de álcool do começo ao fim, é realmente difícil não chamar a atenção das pessoas."
  },
  AvgDialog_131216_Content_26 = {
    Text = "Vendo o olhar dele à procura do cardápio de bebidas, o barman sorriu e balançou a cabeça."
  },
  AvgDialog_131216_Content_27 = {
    Text = "Carta de vinhos? Ah, entediante, chato, clichê."
  },
  AvgDialog_131216_Content_28 = {
    Text = "Uma taverna romântica não deveria ter coisas tão entediantes."
  },
  AvgDialog_131216_Content_29 = {
    Text = "Sem cardápio de bebidas? Então como vamos fazer o pedido?"
  },
  AvgDialog_131216_Content_3 = {
    Text = "Tenho o slogan da Máscara da Meia-Noite memorizado há anos. Quando estava em Cardas, era o lugar que eu mais queria visitar."
  },
  AvgDialog_131216_Content_30 = {
    Text = "Cada assento da máscara da meia-noite pertence a um convidado no teatro. Vocês estão aqui para assistir, se apresentar, saborear..."
  },
  AvgDialog_131216_Content_31 = {
    Text = "Em inúmeras histórias, eu escolherei cuidadosamente a parte que mais se adapta a você."
  },
  AvgDialog_131216_Content_32 = {
    Text = "Por favor, sentem-se, senhores. O leitor da história já está pronto."
  },
  AvgDialog_131216_Content_33 = {
    Text = "Você trocou um olhar com William e hesitante, sentou-se perto do bar."
  },
  AvgDialog_131216_Content_34 = {
    Text = "Primeiro, você, este cavalheiro de cabelos loiros e expressão severa."
  },
  AvgDialog_131216_Content_35 = {
    Text = "O bartender se aproximou de vocês. Diante dos olhos que observavam atentamente, William tossiu levemente e desviou o olhar, sentindo-se um pouco desconfortável."
  },
  AvgDialog_131216_Content_36 = {
    Text = "Ah... O treinamento rigoroso dia após dia trouxe conquistas tão extraordinárias. Persistência, calma, resiliência, coragem, sabedoria... Uma lenda viva cercada de flores e glória."
  },
  AvgDialog_131216_Content_37 = {
    Text = "E, no entanto, por trás dos elogios e da auréola há... arrependimento. Um arrependimento mais profundo e mais agonizante do que a névoa que sufoca esta cidade."
  },
  AvgDialog_131216_Content_38 = {
    Text = "Quantas lágrimas não vistas nas profundezas da noite. Aqueles juramentos ditos a si mesmo."
  },
  AvgDialog_131216_Content_39 = {
    Text = "Aquela luz que iluminou você no corredor escuro se apagou na escuridão infinita, levando seu mundo junto, quebrando-se, quebrando-se..."
  },
  AvgDialog_131216_Content_4 = {
    Text = "Não acha que as regras da Misaq são um pouco rígidas demais às vezes?"
  },
  AvgDialog_131216_Content_40 = {
    Text = "Você pensa consigo: <Italic:Se ao menos eu tivesse me esforçado mais. Se ao menos eu fosse mais forte... talvez pudesse ter tecido um destino diferente para meu querido amigo.>"
  },
  AvgDialog_131216_Content_41 = {
    Text = "A expressão de William, o companheiro mais velho permanece uma máscara de indiferença, mas você nota as veias saltando na mão que agora aperta o copo com força."
  },
  AvgDialog_131216_Content_42 = {
    Text = "Eu ouvi o som de um mundo se quebrando. O menino pequeno suportava a dor, recolhendo os pedaços um por um, juntando-os..."
  },
  AvgDialog_131216_Content_43 = {
    Text = "Nesta longa e cruel montagem, o menino finalmente se tornou um homem."
  },
  AvgDialog_131216_Content_44 = {
    Text = "O barman, com uma voz suave e prolongada, começou a preparar drinks enquanto retirava algumas garrafas de formas variadas de uma prateleira de bebidas que parecia não ter fim."
  },
  AvgDialog_131216_Content_45 = {
    Text = "Em breve, o líquido dourado claro em um copo clássico foi empurrado para frente de William."
  },
  AvgDialog_131216_Content_46 = {
    Text = "2 onças de whiskey, 1 onça de vinho branco, e aquela base dolorosa e resistente — 2 gotas de amargo."
  },
  AvgDialog_131216_Content_47 = {
    Text = "<Yellow:\"Guia\">. Espero que possa conduzir aqueles que o veneram juntos, encontrando o caminho certo — assim como aquele que você venera, um dia o conduziu."
  },
  AvgDialog_131216_Content_48 = {
    Text = "William, o companheiro mais velho aceita a bebida dourada, girando-a lentamente enquanto estuda a bartender com um olhar penetrante."
  },
  AvgDialog_131216_Content_49 = {
    Text = "Como você soube disso que acabei de dizer...?"
  },
  AvgDialog_131216_Content_5 = {
    Text = "Eu propus proibir os estudantes da Misaq de entrar em tais estabelecimentos sem autorização precisamente para evitar que certos Guardiões do segredo—do tipo negligente—gastassem os fundos de missão sob o pretexto de conduzir investigações."
  },
  AvgDialog_131216_Content_50 = {
    Text = "Um bom barman deve saber ouvir a voz do cliente. Este é o segredo do barman, querido hóspede."
  },
  AvgDialog_131216_Content_51 = {
    Text = "A bartender desvia do olhar de William, o companheiro mais velho com a graça de uma corça. Ela pressiona um dedo nos lábios num gesto de silêncio e então aponta diretamente para você."
  },
  AvgDialog_131216_Content_52 = {
    Text = "Chegou a sua vez, este convidado..."
  },
  AvgDialog_131216_Content_53 = {
    Text = "Tenho um pressentimento de que esta pode ser a coisa mais perigosa que já tentei na minha vida — mas tudo bem, eu amo aventuras."
  },
  AvgDialog_131216_Content_54 = {
    Text = "Ela se inclina para perto, fitando intensamente seus olhos. Você quase consegue ouvir o ritmo suave de sua respiração."
  },
  AvgDialog_131216_Content_55 = {
    Text = "Hmm... O que eu estou olhando é um visitante de longe, ou talvez... uma divindade que caiu no mundo mortal e enfrentou inúmeras dificuldades?"
  },
  AvgDialog_131216_Content_56 = {Text = "?!!"},
  AvgDialog_131216_Content_57 = {
    Text = "Você se levanta instintivamente e dá dois passos para trás."
  },
  AvgDialog_131216_Content_58 = {
    Text = "Isso não pode ser algo que um simples barman saberia... Quem é você?"
  },
  AvgDialog_131216_Content_59 = {
    Text = "Fique tranquilo, estimado convidado. Neste bar, não sou eu quem tem intenções maliciosas."
  },
  AvgDialog_131216_Content_6 = {
    Text = "Este Guardião em particular, afinal, acumulou um belo histórico durante o seu tempo como estudante."
  },
  AvgDialog_131216_Content_60 = {
    Text = "Talvez você já tenha notado que alguns de seus \"velhos amigos\" chegaram atrás de você."
  },
  AvgDialog_131216_Content_61 = {
    Text = "%player%, cuidado atrás de você."
  },
  AvgDialog_131216_Content_62 = {
    Text = "Senti isso..."
  },
  AvgDialog_131216_Content_63 = {
    Text = "Alertado pelo aviso, você percebe mais de uma dúzia de ondulações psíquicas afiadas se aproximando rapidamente de todas as direções."
  },
  AvgDialog_131216_Content_64 = {
    Text = "William, o companheiro mais velho se move para cobrir suas costas em perfeita sincronia. Você segura sua Chave de prata com firmeza, os olhos fixos no enigmático barman."
  },
  AvgDialog_131216_Content_65 = {
    Text = "A bartender coloca seu copo e move as garrafas para um canto seguro onde não serão quebradas no confronto."
  },
  AvgDialog_131216_Content_66 = {
    Text = "Calma aí, %player%. Eles estão rastreando vocês há algum tempo. Aqui, pelo menos, posso oferecer algum tipo de ajuda."
  },
  AvgDialog_131216_Content_67 = {
    Text = "Você? Eles? ..."
  },
  AvgDialog_131216_Content_68 = {
    Text = "Heh... Encontrei vocês."
  },
  AvgDialog_131216_Content_69 = {
    Text = "Este lugar imundo não é adequado para uma longa estadia, meus pequenos visitantes de terras distantes."
  },
  AvgDialog_131216_Content_7 = {
    Text = "Oh, mas parece-me recordar ter lido no ficheiro do Veterano Fengor que o seu maior passatempo era passar pela Máscara da Meia-Noite para beber um copo depois do trabalho..."
  },
  AvgDialog_131216_Content_70 = {
    Text = "Cuidado! Eles estão vindo!"
  },
  AvgDialog_131216_Content_8 = {
    Text = "...E claro, um descanso ocasional não é inteiramente desprovido de mérito."
  },
  AvgDialog_131216_Content_9 = {
    Text = "Além disso, a lista de membros da Máscara da Meia-Noite inclui a elite de toda Londinium. É o local ideal para recolher informações."
  },
  AvgDialog_131217_Content_1 = {
    Text = "O poder dos três plásmidos se acalmou dentro de você, mas você ainda não abriu os olhos."
  },
  AvgDialog_131217_Content_10 = {
    Text = "O espírito dos contratos, princípios comerciais... um acordo requer uma moeda de troca. Você sabe como isso funciona, não sabe?"
  },
  AvgDialog_131217_Content_11 = {
    Text = "\"N\" balança a cabeça, lutando para conter o riso."
  },
  AvgDialog_131217_Content_12 = {
    Text = "A boa notícia é que você sempre tem a moeda de troca perfeita."
  },
  AvgDialog_131217_Content_13 = {
    Text = "Um guardião valente prestes a abandonar a fé em {Male=his,Female=her}, afogando-se na teia do Destino — enganando, trapaceando, completamente sem princípios... que cena cativante!"
  },
  AvgDialog_131217_Content_14 = {
    Text = "Eu não perderia o melhor lugar da plateia por nada neste mundo."
  },
  AvgDialog_131217_Content_15 = {
    Text = "Quando eu disse..."
  },
  AvgDialog_131217_Content_16 = {
    Text = "O Folião não tem paciência para suas perguntas. Ele avalia a dívida que você terá no futuro e balança o dedo com um sorriso."
  },
  AvgDialog_131217_Content_17 = {
    Text = "Não é bem uma dica, mas sim uma pequena e sincera sugestão."
  },
  AvgDialog_131217_Content_18 = {
    Text = "Por que resistir a Nefraea? Por que não obedecê-la, Guardião {Male=senhor, Female=senhorita}?"
  },
  AvgDialog_131217_Content_19 = {
    Text = "\"N\" sorri e se inclina em sua direção, tão benevolente quanto um advogado visitando um cliente na prisão."
  },
  AvgDialog_131217_Content_2 = {
    Text = "Sua consciência mergulha, mergulha no vasto mar espiritual, até aquela escuridão infinita, até o abismo que pertence a você e que você não pode ver claramente."
  },
  AvgDialog_131217_Content_20 = {
    Text = "Você... o que disse? Não, eu nunca poderia..."
  },
  AvgDialog_131217_Content_21 = {
    Text = "Ah, isso mesmo, nunca desistir, nunca abrir mão, nunca reconhecer as ações de Nefraea... um heroísmo antigo e clássico."
  },
  AvgDialog_131217_Content_22 = {
    Text = "Leve-nos a Nefraea, invoque aquele seu querido primo, de volta ao palácio que pertence a você... Além disso, o que mais você pode fazer agora, %player%?"
  },
  AvgDialog_131217_Content_23 = {
    Text = "Vou te ensinar um segredo: já que não é possível escapar dessa rede, por que não abrir os braços e acolher a chegada dessa rede?"
  },
  AvgDialog_131217_Content_24 = {
    Text = "Pare de sonhar, \"N\". Eu jamais poderia..."
  },
  AvgDialog_131217_Content_25 = {
    Text = "Shh. Não se limite tão facilmente, querida."
  },
  AvgDialog_131217_Content_26 = {
    Text = "Não se esqueça, Arachne ligou seu destino à grande teia. Você já é um deles."
  },
  AvgDialog_131217_Content_27 = {
    Text = "Aquela pessoa, a deusa do destino, lhe deu uma chave chamada Alegria. Mas você já pensou, para onde essa porta realmente se dirige e aonde leva?"
  },
  AvgDialog_131217_Content_28 = {
    Text = "Para onde a Porta aponta... para onde ela leva...?"
  },
  AvgDialog_131217_Content_29 = {
    Text = "Eu pensei que Arachne era uma senhora trabalhadora, bondosa e sem nada de especial, cuja única habilidade era tecer teias e sorrir. Mas ela é muito mais interessante do que eu imaginava, muito mais interessante."
  },
  AvgDialog_131217_Content_3 = {
    Text = "Você se esforça para abrir a boca inexistente, gritando com raiva e em silêncio neste abismo."
  },
  AvgDialog_131217_Content_30 = {
    Text = "Ela teceu uma enorme rede para este palco, e desde o momento em que você chegou a este mundo, essa rede começou a se estender para você."
  },
  AvgDialog_131217_Content_31 = {
    Text = "Ter uma habilidade tão excelente, mas se ocupando de coisas tão estúpidas como manter o mundo funcionando... Que pena, realmente é uma pena."
  },
  AvgDialog_131217_Content_32 = {
    Text = "Suba ao palco do teatro do destino e torne-se um personagem nele. Cada personagem possui sua própria vida."
  },
  AvgDialog_131217_Content_33 = {
    Text = "O destino fez você tomar esta escolha, para que você possa vê-lo claramente. Você não consegue ver os fios, mas agora entende como eles se entrelaçam de forma tão complexa."
  },
  AvgDialog_131217_Content_34 = {
    Text = "As linhas do destino tecem uma enorme rede, cada leve tremor de uma linha pode fazer a rede do destino desmoronar."
  },
  AvgDialog_131217_Content_35 = {
    Text = "Este é o Destino, {Male=Mr.,Female=Miss} Guardião."
  },
  AvgDialog_131217_Content_36 = {
    Text = "Performance, zombaria, prazer... dentro de você, há esse poder. O palco do destino não oferece oportunidades para todos. Quando você precisar subir ao palco, essas forças o ajudarão."
  },
  AvgDialog_131217_Content_37 = {
    Text = "Você não pode se esconder dos papéis que foi destinado a desempenhar. Pense, depois atue, {Male=Mr.,Female=Miss} Guardião."
  },
  AvgDialog_131217_Content_38 = {Text = "\"Alegria\"."},
  AvgDialog_131217_Content_39 = {
    Text = "No seu breve futuro, \"Alegria\" é uma chave que irá desvendar o segredo que você enfrenta."
  },
  AvgDialog_131217_Content_4 = {Text = "\"N\"!"},
  AvgDialog_131217_Content_40 = {
    Text = "......Não importa o que aconteça, confie em mim e confie em si mesmo."
  },
  AvgDialog_131217_Content_41 = {
    Text = "Retorne ao Teatro do Destino. A chave e a fechadura aguardam você lá, %player%."
  },
  AvgDialog_131217_Content_42 = {
    Text = "As palavras de Arachne percorrem e se entrelaçam em sua mente como fios. Finalmente, elas se juntam em uma enorme e densa teia."
  },
  AvgDialog_131217_Content_43 = {
    Text = "Você finalmente entende que, desde o primeiro encontro, Arachne tem conversado com você através do tempo."
  },
  AvgDialog_131217_Content_44 = {
    Text = "Você olhou admirado para a rede precisa, como se algo muito importante estivesse gradualmente tomando forma em sua mente."
  },
  AvgDialog_131217_Content_45 = {
    Text = "Atuação, zombaria, agradar..."
  },
  AvgDialog_131217_Content_46 = {
    Text = "Ah, isso mesmo. Nunca tente entender. Apenas aproveite, esse é o único segredo da alegria."
  },
  AvgDialog_131217_Content_47 = {
    Text = "A tristeza e a alegria, o bem e o mal, todas as emoções e moralidades não existem mais. Além do prazer, não há nada."
  },
  AvgDialog_131217_Content_48 = {
    Text = "Agora, diga-me... você entende \"Alegria\", Guardião do Segredo?"
  },
  AvgDialog_131217_Content_49 = {
    Text = "O sorriso carmesim de \"N\" desvanece da sua mente. Você vê um espelho, e refletido nele está seu próprio rosto sorridente."
  },
  AvgDialog_131217_Content_5 = {
    Text = "Shh... Sua voz está muito alta, Guardião do Segredo."
  },
  AvgDialog_131217_Content_50 = {
    Text = "Alegria?...Alegria..."
  },
  AvgDialog_131217_Content_51 = {
    Text = "Hehehe... Hahaha. Isso mesmo, alegria, meu amigo"
  },
  AvgDialog_131217_Content_52 = {
    Text = "O vocabulário mais maravilhoso deste mundo, todo o significado da existência deste sonho..."
  },
  AvgDialog_131217_Content_53 = {
    Text = "Como se vislumbrasse a cena prestes a se desenrolar, o corpo inteiro de N treme de deleite. Ele pressiona um dedo envolto em névoa escura contra a própria testa."
  },
  AvgDialog_131217_Content_54 = {
    Text = "Você está quase lá. Apenas um passo, o último passo... Pense bem e então entre naquela teia, Guardião do Segredo."
  },
  AvgDialog_131217_Content_55 = {
    Text = "O caminho da alegria está nele."
  },
  AvgDialog_131217_Content_6 = {
    Text = "O fantasma de \"N\" permanece. Ele aparece no seu espaço mental com facilidade, parecendo o mestre indiscutível do domínio."
  },
  AvgDialog_131217_Content_7 = {
    Text = "Arachne disse que \"Alegria\" deve se referir a você"
  },
  AvgDialog_131217_Content_8 = {
    Text = "\"N\", me dê uma dica..."
  },
  AvgDialog_131217_Content_9 = {
    Text = "Dica? Hahahaha... O que eu fiz para você me humilhar assim?"
  },
  AvgDialog_131218_Content_10 = {
    Text = "Você... Todos vocês... o que está acontecendo?"
  },
  AvgDialog_131218_Content_11 = {
    Text = "O bêbado, a jovem senhora, o cavalheiro nobre, o brutamontes, o garçom cansado, a bela bartender..."
  },
  AvgDialog_131218_Content_12 = {
    Text = "Todos os rostos no bar — jovens, velhos, bonitos ou comuns — se viram para você em uníssono, suas expressões tão idênticas quanto cópias carbono."
  },
  AvgDialog_131218_Content_13 = {
    Text = "Eles não são indivíduos. São mais como..."
  },
  AvgDialog_131218_Content_14 = {
    Text = "Aqueles que pareciam tão cheios de vida há poucos instantes agora se erguem diante de você como manequins de madeira sem vida."
  },
  AvgDialog_131218_Content_15 = {
    Text = "...Mais como marionetes, presas em uma teia."
  },
  AvgDialog_131218_Content_16 = {
    Text = "Já ouvi falar da sua percepção aguçada, Sr. William."
  },
  AvgDialog_131218_Content_17 = {
    Text = "O que você vê diante de si são meros adereços em um palco — reflexos em um espelho."
  },
  AvgDialog_131218_Content_18 = {
    Text = "Por favor, me desculpe. Ainda não posso deixar minha teia. Preciso usar esses recipientes para falar com você."
  },
  AvgDialog_131218_Content_19 = {
    Text = "Bem-vindos ao meu palco, Sr. William, o companheiro mais velho... e você, {Male=Mr.,Female=Miss} Guardião."
  },
  AvgDialog_131218_Content_2 = {
    Text = "Acabou... mas o que diabos eram aquelas coisas?"
  },
  AvgDialog_131218_Content_20 = {
    Text = "Cada um das palavras é proferida com uma precisão perturbadora; vinte vozes distintas se entrelaçam em um único e frio fio de voz."
  },
  AvgDialog_131218_Content_21 = {
    Text = "Todos na sala se curvam em perfeita sincronia. O ângulo de suas colunas e a posição de suas mãos são espelhados com uma exatidão antinatural."
  },
  AvgDialog_131218_Content_22 = {
    Text = "Seu... palco? Quem é você?"
  },
  AvgDialog_131218_Content_23 = {
    Text = "É o mestre daqui e também um prisioneiro."
  },
  AvgDialog_131218_Content_24 = {
    Text = "Eu imagino que você deve ter muitas dúvidas."
  },
  AvgDialog_131218_Content_25 = {
    Text = "Aqui não é seguro, as pessoas deles logo estarão nos seguindo. Minha servente virá recebê-los, não se preocupem quando a virem."
  },
  AvgDialog_131218_Content_26 = {
    Text = "Depois de nos encontrarmos, eu responderei a todas as suas dúvidas uma a uma."
  },
  AvgDialog_131218_Content_27 = {
    Text = "No momento em que essas palavras saem de seus lábios, a consciência da multidão parece se esvair em um instante."
  },
  AvgDialog_131218_Content_28 = {
    Text = "O copo de cristal de um cavalheiro congela em seus lábios; o leque aberto de uma dama se imobiliza logo abaixo de seu queixo; a bartender permanece em pose, copo erguido no ar."
  },
  AvgDialog_131218_Content_29 = {
    Text = "Como se seus fios tivessem sido cortados de uma só vez, todos mantêm sua pose final — figuras de cera congeladas no lugar."
  },
  AvgDialog_131218_Content_3 = {
    Text = "Cuidado com as costas!!"
  },
  AvgDialog_131218_Content_30 = {
    Text = "Você respira lentamente e olha ao redor com inquietação para o mar de \"marionetes\", cada uma congelada com aquele mesmo sorriso imutável."
  },
  AvgDialog_131218_Content_31 = {
    Text = "Embora eles realmente me ajudaram antes, eu simplesmente não consigo acreditar completamente..."
  },
  AvgDialog_131218_Content_32 = {
    Text = "William, o companheiro mais velho, a coisa que queremos saber, esta pessoa \"mestre\" talvez seja o melhor respondedor."
  },
  AvgDialog_131218_Content_33 = {
    Text = "Mesmo que haja perigo, eu acho que preciso ir, apenas..."
  },
  AvgDialog_131218_Content_34 = {
    Text = "Eu entendo."
  },
  AvgDialog_131218_Content_35 = {
    Text = "Vendo seu olhar, William acenou com a cabeça em compreensão."
  },
  AvgDialog_131218_Content_36 = {
    Text = "Vou investigar os movimentos dessas sombras do lado de fora, elas estão te procurando, minha presença externa será mais segura do que a sua."
  },
  AvgDialog_131218_Content_37 = {
    Text = "Esta pessoa \"mestre\" tem origem desconhecida, se encontrar perigo..."
  },
  AvgDialog_131218_Content_38 = {
    Text = "William tocou levemente o emblema da escola em seu peito. Neste mundo, vocês são as únicas pessoas que podem se contatar através do emblema da escola um do outro."
  },
  AvgDialog_131218_Content_39 = {
    Text = "Entendi... você também, William, o companheiro mais velho."
  },
  AvgDialog_131218_Content_4 = {
    Text = "Um pico de pura adrenalina faz você despertar. Você gira e encontra uma lâmina de sombra solidificada pairando a poucos centímetros da sua garganta."
  },
  AvgDialog_131218_Content_40 = {
    Text = "\"Mestre\" entende sua cautela. Senhor William, este palco agora tem muitos perigos, por favor, tome cuidado. Dentro de nossas capacidades, forneceremos a ajuda necessária."
  },
  AvgDialog_131218_Content_41 = {
    Text = "Aranhas violeta pálidas convergem de todos os cantos do bar, e uma criada com traços aracnídeos aparece silenciosamente atrás de todos vocês. Após fazer uma reverência educada, ela caminha em direção à porta."
  },
  AvgDialog_131218_Content_42 = {
    Text = "{Male=Mr.,Female=Miss} Guardião, por favor, siga-me. A Dama está esperando por você."
  },
  AvgDialog_131218_Content_5 = {Text = "Sssss—"},
  AvgDialog_131218_Content_6 = {
    Text = "Você lentamente abaixa o braço que protegia seu rosto. A sombra foi cortada por alguém atrás de você; icor negro espirra pelo ar, respingando em suas roupas."
  },
  AvgDialog_131218_Content_7 = {
    Text = "Desculpe pelo susto."
  },
  AvgDialog_131218_Content_8 = {
    Text = "Eles estão caçando vocês. Dentro destas paredes, posso ao menos dar uma mão."
  },
  AvgDialog_131218_Content_9 = {
    Text = "Perdoe-me por ter tomado a liberdade de guiá-los até aqui sem o seu consentimento."
  },
  AvgDialog_131219_Content_1 = {
    Text = "Isso... acabou?"
  },
  AvgDialog_131219_Content_2 = {
    Text = "Tenha cuidado, Guardião... o fuso que desfaz o destino já começou a girar atrás dela..."
  },
  AvgDialog_131219_Content_3 = {
    Text = "Heh... hahahaha...!"
  },
  AvgDialog_131220_Content_1 = {
    Text = "Cisne a Voar"
  },
  AvgDialog_131220_Content_10 = {
    Text = "Você se lembra daquela grande porta enferrujada, que emitia um som abafado a cada movimento, como a respiração carinhosa do avô."
  },
  AvgDialog_131220_Content_11 = {
    Text = "A Universidade Miskatonic..."
  },
  AvgDialog_131220_Content_12 = {
    Text = "Neste ambiente familiar, você acaricia aquele nome completamente diferente na placa da praça."
  },
  AvgDialog_131220_Content_13 = {
    Text = "Cada ator tem seu palco favorito. Mesmo uma escola replicada a partir da memória é insubstituível para você."
  },
  AvgDialog_131220_Content_14 = {
    Text = "Por que criar um lugar exatamente igual a Missaga..."
  },
  AvgDialog_131220_Content_15 = {
    Text = "Eu não o criei, apenas ele deveria existir aqui. Assim como esta cidade e este mundo, eles são todos parte da teia do destino."
  },
  AvgDialog_131220_Content_16 = {
    Text = "Não olhe tão adiante, %player%. Se você está em um palco, há uma razão para estar aqui."
  },
  AvgDialog_131220_Content_17 = {
    Text = "Falando nisso, depois de tanto tempo convivendo com a Liz, eu nunca a vi se apresentar oficialmente ao vivo..."
  },
  AvgDialog_131220_Content_18 = {
    Text = "Você olha em volta da praça familiar, com as mãos deslizando suavemente sobre a grama abaixo de você."
  },
  AvgDialog_131220_Content_19 = {
    Text = "Os momentos mais maravilhosos da vida são aqueles em que você não percebe que está sorrindo."
  },
  AvgDialog_131220_Content_2 = {
    Text = "É realmente raro, o preço dos ingressos para esta companhia de dança no teatro, o mais barato ainda custa dois meses do meu salário."
  },
  AvgDialog_131220_Content_20 = {
    Text = "Ah... desculpe..."
  },
  AvgDialog_131220_Content_21 = {
    Text = "Lembrou-se das coisas sobre Missaga?"
  },
  AvgDialog_131220_Content_22 = {
    Text = "Nesta praça, realizamos muitas apresentações dentro do campus. Naquela época, assim como agora, os estudantes de Misaq lotavam a praça."
  },
  AvgDialog_131220_Content_23 = {
    Text = "Há muitos Despertados que têm uma profunda habilidade artística. Muitas pessoas não estavam muito dispostas a se apresentar em tais ocasiões no começo, e eu e os professores da academia pensamos em várias maneiras..."
  },
  AvgDialog_131220_Content_24 = {
    Text = "Depois, muitas pessoas também começaram a querer se apresentar para os companheiros aqui."
  },
  AvgDialog_131220_Content_25 = {
    Text = "A dança da Liz, a canção da Tinct, a sinfonia de Hameln, a poesia da Horla, a escultura da Sanga..."
  },
  AvgDialog_131220_Content_26 = {
    Text = "Não sei se a vida em Misaq voltou ao que era antes depois que eu fui embora..."
  },
  AvgDialog_131220_Content_27 = {
    Text = "A cortina se mexeu! A cortina se mexeu! A Srta. Liz está prestes a entrar!"
  },
  AvgDialog_131220_Content_28 = {
    Text = "Você balança a cabeça, afastando as emoções melancólicas da sua mente."
  },
  AvgDialog_131220_Content_29 = {
    Text = "De qualquer forma, é uma sorte poder ver a dança da Liz novamente neste mundo distante."
  },
  AvgDialog_131220_Content_3 = {
    Text = "Ouvi dizer que é uma apresentação beneficente patrocinada pela Senhora Sorel em seu nome pessoal! Seria maravilhoso se cada um dos senhores e senhoras desta cidade tivesse um coração tão bondoso"
  },
  AvgDialog_131220_Content_30 = {
    Text = "Depois que essa questão estiver completamente resolvida, se eu tiver tempo, gostaria de conversar com eles."
  },
  AvgDialog_131220_Content_31 = {
    Text = "Senhoras e senhores... Bem-vindos ao nosso espetáculo"
  },
  AvgDialog_131220_Content_32 = {
    Text = "O grupo de dança do cisne, que nome tão sagrado e inatingível! Este cisne branco, o mais elegante de Londinium, hoje, pousará pela primeira vez diante do público de Londinium"
  },
  AvgDialog_131220_Content_33 = {
    Text = "Agradecemos a todos pela espera. Nossos atores estão prontos. Um espetáculo incrível está prestes a ser apresentado a todos vocês"
  },
  AvgDialog_131220_Content_34 = {
    Text = "Com o estalar nítido dos dedos do anunciante, todas as luzes ao redor se apagaram, e alguns holofotes se concentraram no centro da tela."
  },
  AvgDialog_131220_Content_35 = {
    Text = "Em seguida, por favor, aprecie a dança trazida pela senhorita Liz, o cisne — voando!"
  },
  AvgDialog_131220_Content_36 = {
    Text = "No meio dos aplausos e gritos calorosos da multidão, a cortina se abre lentamente —"
  },
  AvgDialog_131220_Content_37 = {
    Text = "<Big:<Red:!!!!>>"
  },
  AvgDialog_131220_Content_38 = {
    Text = "Você já viu a Liz muitas vezes."
  },
  AvgDialog_131220_Content_39 = {
    Text = "No palco da sala de cerimônias de Misaq, ela gira apenas para você."
  },
  AvgDialog_131220_Content_4 = {
    Text = "Embora não entenda, essa oportunidade não pode ser perdida."
  },
  AvgDialog_131220_Content_40 = {
    Text = "Sob o céu estrelado de Londinium, ela se pôs na ponta dos pés para tocar a luz cintilante que dançava no céu noturno."
  },
  AvgDialog_131220_Content_41 = {
    Text = "Na brisa da Charing Cross, a saia dela se ergueu alto, como chamas ferventes."
  },
  AvgDialog_131220_Content_42 = {
    Text = "E hoje, no palco distante de uma terra estranha, ela aparece diante de você com uma postura que você nunca viu antes."
  },
  AvgDialog_131220_Content_43 = {
    Text = "A estrela principal do Corpo de Baile do Cisne, o fogo de artifício mais brilhante de toda a cidade. Espinhos negros perfuraram sua garganta, seus braços, seu peito e abdômen, seus pés nas pontas, perfurando o corpo que comandava a Dança."
  },
  AvgDialog_131220_Content_44 = {
    Text = "Sangue jorrava, desenhando um par de asas carmesim na parede atrás dela, deixando algumas marcas ferozes em seu rosto sereno e sorridente."
  },
  AvgDialog_131220_Content_45 = {
    Text = "A multidão estava silenciosa e tranquila, o vento soprava através da ampla praça, e a saia preto e verde dançava no ar, como uma chama eterna queimando."
  },
  AvgDialog_131220_Content_46 = {
    Text = "—— Neste momento, você entende completamente que, se a morte é inevitável, então esta é a forma de morte que Liz mais deseja."
  },
  AvgDialog_131220_Content_47 = {
    Text = "Ela completou uma apresentação de despedida com seu sangue e vida. Sua dança se congelou no mais belo salto, como um cisne negro voando."
  },
  AvgDialog_131220_Content_48 = {
    Text = "A dança da senhorita Liz é tão elegante, tão bela"
  },
  AvgDialog_131220_Content_49 = {
    Text = "Apreciem em silêncio, meus queridos amigos espectadores! Ver esta cena com seus próprios olhos é uma honra única em suas vidas."
  },
  AvgDialog_131220_Content_5 = {
    Text = "Trinta anos... Já se passaram trinta anos desde que consegui voltar ao teatro para ver uma apresentação..."
  },
  AvgDialog_131220_Content_50 = {
    Text = "Você vê o rosto do Anunciador que foi rasgado ao meio. O semblante do homem de meia idade, sem vida, derrete como uma substância viscosa, revelando os olhos de Nefraea, preenchidos com empolgação."
  },
  AvgDialog_131220_Content_51 = {
    Text = "No caos de gritos e fugas da multidão, o riso agudo dela perfura seu tímpano como uma agulha envenenada."
  },
  AvgDialog_131220_Content_52 = {
    Text = "<Big:Liz!!>"
  },
  AvgDialog_131220_Content_53 = {
    Text = "Você se abre caminho pela multidão assustada e corre até a frente do palco."
  },
  AvgDialog_131220_Content_54 = {
    Text = "Ah, esta pessoa inteligente, como você soube que esta apresentação de dança tem um segundo ato?"
  },
  AvgDialog_131220_Content_55 = {
    Text = "Ao redor do palco, alguns espectadores que não conseguiram escapar se aproximam rapidamente de você. Seus corpos se estouram enquanto correm, liberando aqueles servidores negros de aranhas que não param de atacar."
  },
  AvgDialog_131220_Content_56 = {
    Text = "No palco à sua frente, o corpo de Liz se afastou dos espinhos. Uma obra de arte feita por hereges, carregando um vazio cruel e sangue vibrante."
  },
  AvgDialog_131220_Content_57 = {
    Text = "Pegadas ensanguentadas se estendem do centro do palco. Liz caminha em sua direção, o rosto pintado em uma máscara macabra e deslumbrante de sangue que tira seu fôlego."
  },
  AvgDialog_131220_Content_58 = {
    Text = "Ela levantou a cabeça e olhou para você. Seus olhos vazios e ensanguentados fazem você lembrar de todas as obras de arte que merecem ser transmitidas ao mundo."
  },
  AvgDialog_131220_Content_59 = {
    Text = "Agora, hora de dançar com sua velha amiga... {Male=Mr.,Female=Miss} Guardião!"
  },
  AvgDialog_131220_Content_6 = {
    Text = "O balé, a dança mais pura do mundo, só é compreendida por aqueles que realmente a dançaram, entendendo quão bela é aquela cruel elegância"
  },
  AvgDialog_131220_Content_7 = {
    Text = "Nunca imaginei que pudesse ver a apresentação da Srta. Liz ao vivo..."
  },
  AvgDialog_131220_Content_8 = {
    Text = "Os sons ambientais que deveriam ser barulhentos se misturam em um ruído branco distante em seus ouvidos."
  },
  AvgDialog_131220_Content_9 = {
    Text = "Você se lembra deste gramado, daquele lago. Você se lembra dos prédios escolares altos e baixos, se lembra daquela escultura com olhar firme voltado para o horizonte."
  },
  AvgDialog_131221_Content_1 = {Text = "Ato Dois"},
  AvgDialog_131221_Content_10 = {
    Text = "Sou prisioneiro do destino, isso é apenas um dever que eu tenho que cumprir."
  },
  AvgDialog_131221_Content_11 = {
    Text = "Uma pessoa capaz de manipular o destino de inúmeros mundos talvez se chamasse juiz do destino ou carcereiro, não?"
  },
  AvgDialog_131221_Content_12 = {
    Text = "Na prisão do destino, não há diferença entre o carcereiro e o prisioneiro."
  },
  AvgDialog_131221_Content_13 = {
    Text = "Sr. William, você está se acostumando com esta jornada?"
  },
  AvgDialog_131221_Content_14 = {
    Text = "Graças à sua servente, se fosse apenas eu, para me livrar daqueles servidores nas sombras, provavelmente teria que pagar um preço ainda maior."
  },
  AvgDialog_131221_Content_15 = {
    Text = "Nefraea... você já encontrou outra pessoa dela?"
  },
  AvgDialog_131221_Content_16 = {
    Text = "William assentiu seriamente."
  },
  AvgDialog_131221_Content_17 = {
    Text = "Quando nos separamos, encontrei alguns transeuntes que pareciam... estranhos. Segui–os por um tempo e captei fragmentos de sua conversa."
  },
  AvgDialog_131221_Content_18 = {
    Text = "Elas estão procurando algo chamado \"ícone secreto\"."
  },
  AvgDialog_131221_Content_19 = {
    Text = "Eu quero... o que vocês estavam falando sobre a poluição do destino do palco, talvez seja apenas um meio preliminar."
  },
  AvgDialog_131221_Content_2 = {
    Text = "Que espetáculo..."
  },
  AvgDialog_131221_Content_20 = {
    Text = "Aqueles \"segredos\" são o verdadeiro objetivo delas."
  },
  AvgDialog_131221_Content_21 = {
    Text = "Minha irmã escondeu seus próprios Fios do destino junto com os de seus escudeiros; não consigo percebê–los facilmente. Esta é uma informação vital, Sr. William, o companheiro mais velho."
  },
  AvgDialog_131221_Content_22 = {
    Text = "Na próxima ação, eu estarei com vocês..."
  },
  AvgDialog_131221_Content_23 = {Text = "Não!"},
  AvgDialog_131221_Content_24 = {
    Text = "Não, você deve ficar! Nos separarmos antes foi uma necessidade, mas não vou arriscar uma repetição do que aconteceu em Lemvahi."
  },
  AvgDialog_131221_Content_25 = {
    Text = "O Guardião está certo. Minha criada tratará as toxinas em seu organismo. Até que esteja totalmente recuperado, por favor permaneça no teatro para descansar."
  },
  AvgDialog_131221_Content_26 = {
    Text = "Em breve, chegaremos ao dia em que você precisará ajudar."
  },
  AvgDialog_131221_Content_27 = {
    Text = "As palavras de Arachne eram como um veredicto suave, penetrando facilmente o corpo e a alma, pousando suavemente no destino de William."
  },
  AvgDialog_131221_Content_28 = {
    Text = "William olhou para o sangue que escorria de seu abdômen e deu um leve aceno com a cabeça."
  },
  AvgDialog_131221_Content_29 = {
    Text = "Se eu fosse agora, seria apenas um fardo. Fique tranquila, vou garantir que estarei pronto quando esse dia chegar."
  },
  AvgDialog_131221_Content_3 = {
    Text = "<Shake:Cof cof...>"
  },
  AvgDialog_131221_Content_30 = {
    Text = "Arachne sorriu e estendeu a mão. Uma, duas... inúmeras aranhas saíram de suas mangas, descendo pelas teias até o chão."
  },
  AvgDialog_131221_Content_31 = {
    Text = "As aranhas caem como chuva, convergindo e se aglomerando. A massa de aracnídeos se sobrepõe em uma silhueta humana enquanto cor e luz se agarram à forma mutável."
  },
  AvgDialog_131221_Content_32 = {
    Text = "Em breve, uma nova Arachne idêntica estará diante de você."
  },
  AvgDialog_131221_Content_33 = {
    Text = "Siga–me, {Male=Mr.,Female=Miss} Guardião. Acredito que chegou a hora de um encontro cara a cara com minha irmã."
  },
  AvgDialog_131221_Content_34 = {Text = "..."},
  AvgDialog_131221_Content_35 = {
    Text = "Nesta cidade há muitas lojas que eu adoro, mas assim como você, este também é um dos meus lugares favoritos."
  },
  AvgDialog_131221_Content_36 = {
    Text = "Na Taverna Máscara da Meia-Noite, você está sentado na mesma posição da última vez que veio, franzindo a testa enquanto observa Arachne que está olhando ao redor."
  },
  AvgDialog_131221_Content_37 = {
    Text = "Então, o que você é agora... um fantoche? Uma parte de você? Uma máquina misteriosa feita de um monte de aranhas que te ajuda a escapar?"
  },
  AvgDialog_131221_Content_38 = {
    Text = "Essencialmente, eu aqui e eu no teatro somos destinos com duas experiências diferentes no mesmo momento."
  },
  AvgDialog_131221_Content_39 = {
    Text = "A maior parte da minha força precisa ficar no teatro, continuando a tecer a grande teia do destino. Além disso, não temos nenhuma diferença. Não é necessário arruinar o clima deste momento por causa de dúvidas, Guardião."
  },
  AvgDialog_131221_Content_4 = {
    Text = "O som puxou a ferida, William cobriu o abdômen envolto em ataduras, não conseguindo conter a tosse."
  },
  AvgDialog_131221_Content_40 = {
    Text = "Arachne sorri calmamente, enquanto os cubos de gelo tilintam suavemente no copo de bebida balançando."
  },
  AvgDialog_131221_Content_41 = {
    Text = "Você sabia que este bar realiza uma festa à fantasia todo mês, e cada cliente que entra deve usar a máscara mais divertida que tiver."
  },
  AvgDialog_131221_Content_42 = {
    Text = "A socialização da alta sociedade muitas vezes torna este lugar entediante, mas apenas naquele dia, aqui se tornará o lugar mais digno de se visitar nesta cidade."
  },
  AvgDialog_131221_Content_43 = {
    Text = "Talvez na próxima festa à fantasia, eu também deva liberar tudo e realmente sentir uma vez."
  },
  AvgDialog_131221_Content_44 = {
    Text = "Eu pensei que alguém capaz de ver o desenvolvimento do destino não teria mais interesse em nada no futuro."
  },
  AvgDialog_131221_Content_45 = {
    Text = "Isso é verdade, %player%. No entanto, descobri uma maneira de afastar o tédio há muito tempo."
  },
  AvgDialog_131221_Content_46 = {
    Text = "Às vezes, eu venho do fundo do palco para a frente, adentrando o palco que criei, me tornando um dos personagens dele."
  },
  AvgDialog_131221_Content_47 = {
    Text = "Bloquear a própria visão do destino, colocar-se completamente no palco, para perceber detalhadamente o fluxo do tempo, a mudança do destino..."
  },
  AvgDialog_131221_Content_48 = {
    Text = "Esta é uma pausa rara. Oportunidades como essa não são muitas, e a cada vez, eu a considero um festival precioso."
  },
  AvgDialog_131221_Content_49 = {
    Text = "Arachne falava enquanto observava com interesse os hóspedes luxuosos e os gentis garçons, a luz ambígua da taberna fluía nos olhos de Arachne."
  },
  AvgDialog_131221_Content_5 = {
    Text = "Senhor William?! Você se machucou"
  },
  AvgDialog_131221_Content_50 = {
    Text = "Mesmo assim... não estamos aqui para procurar aquelas \"reliquias secretas\"? Por que viemos aqui?"
  },
  AvgDialog_131221_Content_51 = {
    Text = "Uma delas está aqui. Você em breve... ah não, você já a conheceu."
  },
  AvgDialog_131221_Content_52 = {
    Text = "Olá, queridos clientes."
  },
  AvgDialog_131221_Content_53 = {
    Text = "O som do mel marinando. Dedos talhados em porcelana. No pescoço exposto, o perfume radiante de jasmim e flor de acácia. E aqueles olhos que brilham como luzes de néon, capazes de ver através de tudo."
  },
  AvgDialog_131221_Content_54 = {
    Text = "Ah, eu me lembro de você, o elegante %player%."
  },
  AvgDialog_131221_Content_55 = {
    Text = "Criaturas nas sombras, uma luz prateada ofuscante... Que história de heróis tão incrível"
  },
  AvgDialog_131221_Content_56 = {
    Text = "Para ser sincero, durante o tempo em que você esteve ausente, o Bar Máscara da Meia-Noite ganhou bastante dinheiro com a sua história. Devemos lhe pagar direitos autorais — pelo menos, deixe-nos lhe oferecer uma bebida."
  },
  AvgDialog_131221_Content_57 = {
    Text = "Ah, é você... Eu não vou beber por enquanto, poderia trazer uma bebida para o meu amigo aqui primeiro?"
  },
  AvgDialog_131221_Content_58 = {
    Text = "Já pensei no nome, será Autoencenação."
  },
  AvgDialog_131221_Content_59 = {
    Text = "Nome bom. Quanto a se combina com você, meu amigo, eu ainda preciso observar mais de perto..."
  },
  AvgDialog_131221_Content_6 = {
    Text = "Sob a condução de Arachne, você atravessa a parede discreta ao lado do café Havatz."
  },
  AvgDialog_131221_Content_60 = {
    Text = "Este ícone secreto chamado \"romântico\" chegou ao bar e olhou seriamente nos olhos de Arachne."
  },
  AvgDialog_131221_Content_61 = {
    Text = "O criador discreto está imerso no palco que criou. Arachne sorri e troca olhares com ela."
  },
  AvgDialog_131221_Content_62 = {
    Text = "Ah, que profundidade de olhos, senhorita."
  },
  AvgDialog_131221_Content_63 = {
    Text = "Um oceano tão profundo e tão vasto, seu fundo invisível esconde segredos que ninguém conhece."
  },
  AvgDialog_131221_Content_64 = {
    Text = "Aquelas ondas turbulentas foram todas acolhidas por este oceano; não importa quão grande seja a agitação, ele continua a manter a calma eterna."
  },
  AvgDialog_131221_Content_65 = {
    Text = "O tempo passa, o mar de estrelas flui. Montanhas se transformam em campos, oceanos se tornam pradarias..."
  },
  AvgDialog_131221_Content_66 = {
    Text = "Mas, sob essa mudança, o que este oceano abandonou..."
  },
  AvgDialog_131221_Content_67 = {
    Text = "O barman sentou-se de frente para Arachne e levantou seu queixo. As unhas longas repousavam naturalmente na artéria carótida de Arachne."
  },
  AvgDialog_131221_Content_68 = {Text = "Isto é"},
  AvgDialog_131221_Content_69 = {
    Text = "O deus do destino, a grandiosa Arachne. A forma como você manipula o destino é tão elegante. Eu realmente invejo, invejo aqueles que você escolheu, que você deixou para trás."
  },
  AvgDialog_131221_Content_7 = {
    Text = "Quando você voltou ao palco do teatro, a primeira coisa que viu foi William, sentado sozinho na plateia."
  },
  AvgDialog_131221_Content_70 = {
    Text = "Infelizmente... nós nascemos apenas para ser a parte abandonada."
  },
  AvgDialog_131221_Content_71 = {
    Text = "...Parece que não vou conseguir provar aquela bebida hoje, afinal."
  },
  AvgDialog_131221_Content_72 = {
    Text = "Arachne não tentou se libertar daquela mão perigosa. Ela suspirou suavemente, como se estivesse suspirando por aquelas memórias distantes, e também como se estivesse suspirando por aquele coquetel que não podia beber."
  },
  AvgDialog_131221_Content_73 = {
    Text = "Você pode poluir os fios do destino desses ícones secretos, me impedindo de ver claramente, mas isso não tem sentido. Você não tem o poder de controlar o destino, Nefraea."
  },
  AvgDialog_131221_Content_74 = {
    Text = "Como uma boneca feita de creme negro derretido, a pele da bartender se desprende de seu corpo em uma poça lamacenta."
  },
  AvgDialog_131221_Content_75 = {
    Text = "Debaixo daquela lama, um rosto familiar apareceu diante de você."
  },
  AvgDialog_131221_Content_76 = {Text = "É você?"},
  AvgDialog_131221_Content_77 = {
    Text = "Minha boa irmã. As cinzas daquelas dimensões já são escassas para você."
  },
  AvgDialog_131221_Content_78 = {
    Text = "Eu gostaria de conversar com você mais uma vez, mas agora, vamos deixar meus pequenos aranhas te receberem bem."
  },
  AvgDialog_131221_Content_79 = {
    Text = "Cuidado atrás de você"
  },
  AvgDialog_131221_Content_8 = {
    Text = "Pequeno ferimento."
  },
  AvgDialog_131221_Content_9 = {
    Text = "O destino que aconteceu neste palco, eu vi tudo. Eu acho que alguém deve agradecer pelo seu esforço, senhora Arachne."
  },
  AvgDialog_131222_Content_1 = {
    Text = "Convite da Mansão"
  },
  AvgDialog_131222_Content_10 = {
    Text = "Convite? Nesta minha vida, nunca apresentei um convite."
  },
  AvgDialog_131222_Content_100 = {
    Text = "Sorel estreitou levemente os olhos, e uma rara chama de raiva acendeu-se em seus elegantes olhos."
  },
  AvgDialog_131222_Content_101 = {
    Text = "Eu não sei o que você fez com Karen, mas isso não importa. De qualquer forma, o preço que você pagará já está determinado."
  },
  AvgDialog_131222_Content_102 = {
    Text = "Ah, uma reunião de negócios fracassada... Lamento, Senhora Sorel. Parece que só o seu corpo poderá me contar."
  },
  AvgDialog_131222_Content_103 = {
    Text = "Sorel franziu a testa, percebendo a poderosa onda de força mental do outro. A sombra negra se aproximou rapidamente, bloqueando cada uma de suas rotas de fuga."
  },
  AvgDialog_131222_Content_105 = {
    Text = "Quando a lâmina afiada na sombra de repente cravou-se em Sorel, uma intensa luz prateada saltou para dentro da casa como uma estrela cadente."
  },
  AvgDialog_131222_Content_106 = {
    Text = "Sorel, recuar"
  },
  AvgDialog_131222_Content_11 = {Text = "Afaste-se."},
  AvgDialog_131222_Content_12 = {
    Text = "Desculpe, senhor. Para participar do banquete de hoje, é necessário ter um convite."
  },
  AvgDialog_131222_Content_13 = {
    Text = "Cara sem visão, você sabe quem eu sou?"
  },
  AvgDialog_131222_Content_14 = {
    Text = "Isso não é minha responsabilidade, senhor."
  },
  AvgDialog_131222_Content_15 = {
    Text = "Pelo seu sotaque, você é uma pessoa local, então acho que você deve conseguir entender o que eu digo."
  },
  AvgDialog_131222_Content_16 = {
    Text = "Você!! Certo, certo, eu farei você e o proprietário desta mansão pagarem o preço"
  },
  AvgDialog_131222_Content_17 = {
    Text = "Arachne olhou para a figura furiosa do nobre e balançou a cabeça."
  },
  AvgDialog_131222_Content_18 = {
    Text = "Parece que entrar nesta mansão não é tão fácil quanto parece."
  },
  AvgDialog_131222_Content_19 = {
    Text = "Se conseguir encontrar aquela servente que vende água de banho, talvez consiga comprar dois convites..."
  },
  AvgDialog_131222_Content_2 = {
    Text = "Mansão do Duque de Cadlin, o local social mais renomado de Londinium."
  },
  AvgDialog_131222_Content_20 = {
    Text = "Sais de banho raros provenientes da Ilha Sira, lavanda, cítricos, cravo, e pétalas de rosa trazidas do sul de Constantan..."
  },
  AvgDialog_131222_Content_21 = {
    Text = "A água do banho é mais preciosa e mais rara do que o convite."
  },
  AvgDialog_131222_Content_22 = {Text = "¿¿¿???"},
  AvgDialog_131222_Content_23 = {
    Text = "Eu pretendia apenas falar comigo mesmo... Como você sabe até mesmo o que aconteceu no meu sonho?"
  },
  AvgDialog_131222_Content_24 = {
    Text = "Embora não consiga ver seu destino, eu sempre estou observando o destino das pessoas ao seu redor."
  },
  AvgDialog_131222_Content_25 = {
    Text = "Já que o destino dessas pessoas pode ser controlado por você, mesmo que seja complicado fazer alterações, conseguir dois convites deve ser uma trivialidade, certo?"
  },
  AvgDialog_131222_Content_26 = {
    Text = "A reação em cadeia causada pela modificação do destino, você já testemunhou. O destino não é um brinquedo que eu possa manipular à vontade, mas uma casa de vidro que eu preciso cuidar com cuidado."
  },
  AvgDialog_131222_Content_27 = {
    Text = "Eu preciso fazer cada escolha com cautela, gastando muita energia e cinzas da dimensão. Toda imprudência e erro resultarão em colapso e destruição."
  },
  AvgDialog_131222_Content_28 = {
    Text = "Além do mais... Como eu disse antes, muitas vezes, ser um espectador é muito mais interessante do que ser um dramaturgo."
  },
  AvgDialog_131222_Content_29 = {
    Text = "Estou ansioso pela sua performance, %player%."
  },
  AvgDialog_131222_Content_3 = {
    Text = "Na primeira metade da vida do duque, o primeiro-ministro e os altos funcionários do gabinete escreviam em mesas de chá no prado as cartas que decidiriam o destino do império."
  },
  AvgDialog_131222_Content_30 = {
    Text = "Mas eu não sei nada sobre aqui..."
  },
  AvgDialog_131222_Content_31 = {
    Text = "Performance, zombaria, prazer... dentro de você, há esse poder. O palco do destino não oferece oportunidades para todos. Quando você precisar subir ao palco, essas forças o ajudarão."
  },
  AvgDialog_131222_Content_32 = {
    Text = "Você não pode se esconder dos papéis que foi destinado a desempenhar. Pense, depois atue, {Male=Mr.,Female=Miss} Guardião."
  },
  AvgDialog_131222_Content_33 = {
    Text = "Um sorriso cortês de Arachne esconde uma seriedade que não é difícil de perceber. Ela parece estar lhe contando algo, e aquele olhar parece ter atravessado você, dialogando com um futuro distante."
  },
  AvgDialog_131222_Content_34 = {
    Text = "Essa é uma ordem que o destino não pode recusar. Você baixa a cabeça, refletindo sobre as palavras de Arachne."
  },
  AvgDialog_131222_Content_35 = {
    Text = "Atuar, zombar, agradar... você está falando do poder de N?"
  },
  AvgDialog_131222_Content_36 = {
    Text = "Mas, após a batalha decisiva contra Toguwaibo, eu perdi a conexão com o poder dos três plásmidos..."
  },
  AvgDialog_131222_Content_37 = {
    Text = "O poder deles ainda está adormecido, mas a autoridade não é apenas força."
  },
  AvgDialog_131222_Content_38 = {
    Text = "Poder, não é apenas força..."
  },
  AvgDialog_131222_Content_39 = {
    Text = "Enquanto você tenta pensar nesta frase, uma luz espiritual brilha em seu mundo espiritual."
  },
  AvgDialog_131222_Content_4 = {
    Text = "A segunda metade da vida do duque, a figura encurvada que foi observada pela propriedade vendida enquanto ele se dirigia para o local da execução."
  },
  AvgDialog_131222_Content_40 = {
    Text = "Você pega duas folhas de bordo caídas do chão e toca suas texturas como se fossem cartas."
  },
  AvgDialog_131222_Content_41 = {
    Text = "Lembro que você disse antes que todas as pessoas deste mundo têm um Núcleo de prata dentro de si. Isso significa que o Mundo espiritual de todos pode ser influenciado pela Chave de prata... certo?"
  },
  AvgDialog_131222_Content_42 = {
    Text = "Arachne sorri para você, ao seu lado, caminhando em direção ao portão da mansão."
  },
  AvgDialog_131222_Content_43 = {
    Text = "Olá, por favor, apresente..."
  },
  AvgDialog_131222_Content_44 = {
    Text = "Que belo mansão. É uma grande honra receber o convite da Senhora Sorel."
  },
  AvgDialog_131222_Content_45 = {
    Text = "Ao entregar duas folhas de bordo ao guarda, a sua chave de prata brilhou com uma luz fraca em seu peito. Você capturou facilmente o ponto de luz do guarda."
  },
  AvgDialog_131222_Content_46 = {
    Text = "Ao mesmo tempo, outro ponto de luz brilha em seu mundo espiritual. No ponto de interseção do link entre os dois pontos de luz, o fantasma de Clementine balança o pêndulo que tem na mão."
  },
  AvgDialog_131222_Content_47 = {
    Text = "Heui... Conde Heui..."
  },
  AvgDialog_131222_Content_48 = {
    Text = "Ah, Conde Huey, Condessa, bem-vindos à propriedade Cadlin."
  },
  AvgDialog_131222_Content_49 = {
    Text = "Sob o olhar respeitoso do guarda, vocês pisaram na estrada de seixos bem cuidada da mansão."
  },
  AvgDialog_131222_Content_5 = {
    Text = "Após um breve silêncio, esta mansão foi novamente preenchida com convidados valiosos, e seu novo proprietário anunciou seu retorno com uma série de salões."
  },
  AvgDialog_131222_Content_50 = {
    Text = "Como se sente, {Male=Mr.,Female=Miss} Guardião?"
  },
  AvgDialog_131222_Content_51 = {
    Text = "Embora ainda não compreenda o significado do poder que você mencionou, de fato senti algo diferente agora há pouco..."
  },
  AvgDialog_131222_Content_52 = {
    Text = "A sensação que surge após a zombaria nunca havia aparecido em mim... como se... fosse uma emoção que não pertence a mim..."
  },
  AvgDialog_131222_Content_53 = {
    Text = "Você levantou a mão, duas lindas folhas de bordo deixaram suas pontas dos dedos, girando alegremente no vento."
  },
  AvgDialog_131222_Content_54 = {
    Text = "Enquanto você entra na mansão com um sorriso adequado para Arachne, você tem certeza de que ouviu uma risada de prazer vindo de dentro do seu corpo."
  },
  AvgDialog_131222_Content_55 = {Text = "..."},
  AvgDialog_131222_Content_56 = {
    Text = "É verdadeiramente notável ver alguém alcançar tanto em tão pouca idade."
  },
  AvgDialog_131222_Content_57 = {
    Text = "Após o término das negociações comerciais, as relações entre o mundo dos negócios e o político nesta cidade passarão por uma revolução sem precedentes. Esta é uma oportunidade rara..."
  },
  AvgDialog_131222_Content_58 = {
    Text = "Foi difícil para o editor conseguir o convite, desta vez precisamos filmar algumas cenas incríveis. Mais tarde, você leve o equipamento e nos siga, vamos tentar avançar um pouco e nos aproximar..."
  },
  AvgDialog_131222_Content_59 = {
    Text = "Saiu! Saiu!"
  },
  AvgDialog_131222_Content_6 = {
    Text = "Olá, este é o meu convite."
  },
  AvgDialog_131222_Content_60 = {
    Text = "Com o grito do jovem, todos correram em direção à grande porta que se abriu."
  },
  AvgDialog_131222_Content_61 = {
    Text = "A longa saia vermelha é como uma rosa ardente, fazendo com que toda a decoração e a multidão no quarto pareçam apagadas."
  },
  AvgDialog_131222_Content_62 = {
    Text = "Sorel exibe um sorriso impecável e ensaiado, acenando para os convidados com uma elegância natural."
  },
  AvgDialog_131222_Content_63 = {
    Text = "Então, ela é a atual proprietária da mansão..."
  },
  AvgDialog_131222_Content_64 = {
    Text = "Senhoras e senhores, bem-vindos. No salão de hoje, vários dos distritos comerciais da nossa cidade encontrarão seus novos mestres."
  },
  AvgDialog_131222_Content_65 = {
    Text = "E, claro, nossos nobres amigos receberão os benefícios que tão justamente merecem."
  },
  AvgDialog_131222_Content_66 = {
    Text = "Confio que esta será uma noite das mais esplêndidas e encantadoras."
  },
  AvgDialog_131222_Content_67 = {
    Text = "O chef da mansão preparou sobremesas e champanhe de primeira linha para todos, por favor, descansem um pouco. Em breve, nosso jantar começará oficialmente."
  },
  AvgDialog_131222_Content_68 = {
    Text = "O olhar de Sorel sorriu ao percorrer toda a sala, e ela se virou para subir as escadas."
  },
  AvgDialog_131222_Content_69 = {
    Text = "S... Sorel!... Karen"
  },
  AvgDialog_131222_Content_7 = {
    Text = "...Ah, bem-vindo, Sr. Fugen. O mestre está esperando por você lá dentro, entre, por favor."
  },
  AvgDialog_131222_Content_70 = {
    Text = "Seu grito se perde entre as discussões e gritos da multidão."
  },
  AvgDialog_131222_Content_71 = {
    Text = "Senhora Sorel! Senhora Sorel! Como a senhora planejou a divisão da área comercial? Isso vai tocar em..."
  },
  AvgDialog_131222_Content_72 = {
    Text = "Shh, senhor repórter. Eu acabei de voltar de fora, onde resolvi algumas coisas, e depois que eu me trocar, responderei todas as perguntas que você quiser saber."
  },
  AvgDialog_131222_Content_73 = {
    Text = "Sorel acenou para os repórteres e entrou na área dos quartos do andar superior da mansão."
  },
  AvgDialog_131222_Content_74 = {
    Text = "Parece que teremos que perguntar a ela depois que ela sair."
  },
  AvgDialog_131222_Content_75 = {
    Text = "Você notou a servente ao lado de Sorel?"
  },
  AvgDialog_131222_Content_76 = {
    Text = "Karen? Claro, ela também não deve ter ouvido... Espera, você quer dizer que..."
  },
  AvgDialog_131222_Content_77 = {
    Text = "Você se lembra da aura de Karen. Essa aura é completamente diferente da que você conhece, mesmo estando em dimensões diferentes, elas não poderiam pertencer à mesma pessoa."
  },
  AvgDialog_131222_Content_78 = {
    Text = "Eu senti na ela uma trajetória de destino que não pertence a este palco... O destino dela foi poluído."
  },
  AvgDialog_131222_Content_79 = {
    Text = "Senhora Sorel está em perigo"
  },
  AvgDialog_131222_Content_8 = {
    Text = "Hum, até um mercador tão cheio de cheiro de cobre como Fugen pode entrar na mansão do velho duque. A elegância de Londinium já desapareceu completamente..."
  },
  AvgDialog_131222_Content_80 = {
    Text = "Você empurra com força a multidão e encontra uma escada oculta na parte de trás do prédio."
  },
  AvgDialog_131222_Content_81 = {
    Text = "Minhas desculpas, {Male=sir,Female=lady}, mas esta é a residência particular da Senhora Sorel. Nenhuma pessoa não autorizada—"
  },
  AvgDialog_131222_Content_82 = {
    Text = "A Senhora Sorel me convidou para vir discutir assuntos importantes com ela."
  },
  AvgDialog_131222_Content_83 = {
    Text = "Você tirou um guardanapo que havia arrancado casualmente. Um brilho prateado apareceu, e uma carteira de policial do Comitê de Revisão foi colocada diante do Guarda."
  },
  AvgDialog_131222_Content_84 = {
    Text = "Desculpe, não reconheci você... A Senhora Sorel está em cima, posso lhe..."
  },
  AvgDialog_131222_Content_85 = {
    Text = "Missão confidencial, não deixe os outros saberem o que estou fazendo."
  },
  AvgDialog_131222_Content_86 = {
    Text = "Sem esperar que o policial falasse, você correu rapidamente escada acima."
  },
  AvgDialog_131222_Content_87 = {Text = "..."},
  AvgDialog_131222_Content_88 = {
    Text = "Suas roupas estão prontas, Senhora Sorel"
  },
  AvgDialog_131222_Content_89 = {
    Text = "Londinium é uma selva original, os políticos e mercadores são as hienas desta cidade..."
  },
  AvgDialog_131222_Content_9 = {
    Text = "Olá, por favor, apresente o convite."
  },
  AvgDialog_131222_Content_90 = {
    Text = "Sorel pega o traje que Karen preparou. A luz do sol filtra-se pela gaze vermelha, projetando uma vívida sombra carmesim pelo luxuoso quarto."
  },
  AvgDialog_131222_Content_91 = {
    Text = "As hienas também têm seu lado adorável. Um pedaço de carne podre é suficiente para atraí-las. Ganância, afiada, cruel, ingênua. Não há armas mais eficazes do que elas."
  },
  AvgDialog_131222_Content_92 = {
    Text = "Eles já perderam a paciência lá fora. Você apareceu tarde demais hoje, e este vestido caro foi manchado."
  },
  AvgDialog_131222_Content_93 = {
    Text = "A senhora deveria ter voltado mais cedo."
  },
  AvgDialog_131222_Content_94 = {
    Text = "O movimento de Sorel parou por um momento. Ela lentamente soltou a saia vermelha de sangue e olhou para o rosto tranquilo de Karen."
  },
  AvgDialog_131222_Content_95 = {
    Text = "Deve haver alguém que te ensinou como um servo deve falar com o mestre. O que aconteceu com você hoje?"
  },
  AvgDialog_131222_Content_96 = {
    Text = "Senhora Sorel, a senhora está com manchas do Distrito Leste. Estou curioso, para onde a senhora enviou aquela pessoa bondosa?"
  },
  AvgDialog_131222_Content_97 = {
    Text = "A sala iluminada escureceu por um instante. Várias aranhas negras se transformaram em formas humanas a partir das sombras, cercando Sorel no meio."
  },
  AvgDialog_131222_Content_98 = {
    Text = "Você tem uma empregada muito leal, Senhora Sorel. Embora ela esteja entusiasmada em roubar e vender seus bens, sua lealdade à sua segurança é inquestionável."
  },
  AvgDialog_131222_Content_99 = {
    Text = "Mesmo agora, a vontade dela luta ferozmente contra mim. Uma pena, na verdade—nenhum mortal pode resistir ao poder do Destino."
  },
  AvgDialog_131223_Content_1 = {
    Text = "Destino. Destino selvagem, vazio, lastimável. Os Destinos abandonados não sabem de onde vieram, nem para onde vão."
  },
  AvgDialog_131223_Content_10 = {
    Text = "A voz de Nefraea tornou-se subitamente aguda. Uma luz sombria acendeu-se, e fios carmesins a prenderam firmemente, enquanto as chamas remanescentes da lanterna queimavam seu corpo."
  },
  AvgDialog_131223_Content_11 = {
    Text = "As enormes pinças se movem no ar, com grandes olhos compostos que escorrem muco negro, olhando para vocês com um sorriso. Fios carmesins se enrolam em seu corpo, flutuando no vórtice do destino."
  },
  AvgDialog_131223_Content_12 = {
    Text = "Ao seu lado, aquele fuso quebrado que reunia fios girava lenta e implacavelmente, estrangulando todos os palcos, estrangulando a própria Nefraea."
  },
  AvgDialog_131223_Content_13 = {Text = "Hmm—"},
  AvgDialog_131223_Content_14 = {
    Text = "Você segura a cabeça com dor. Sob o giro da roda de fiar, seu mundo espiritual começa a agitar-se. Você respira fundo, tentando acalmar aquela dor intensa."
  },
  AvgDialog_131223_Content_15 = {
    Text = "Ao lado de Nefraea, os fragmentos da Passagem dimensional já são poucos. As linhas em vocês, aqueles padrões semelhantes a fantoches, tornam-se cada vez mais claros."
  },
  AvgDialog_131223_Content_16 = {
    Text = "A força do canal dimensional... Ela quase completou a absorção"
  },
  AvgDialog_131223_Content_17 = {
    Text = "Cinzas de cor lilás saem incessantemente do corpo de Arachne, como mariposas que se lançam contra a Rede do destino, que está quase totalmente destruída."
  },
  AvgDialog_131223_Content_18 = {
    Text = "As mãos trêmulas de Arachne giravam a roca com uma frequência imutável. Sua voz ainda era tão calma quanto quando você a viu pela primeira vez."
  },
  AvgDialog_131223_Content_19 = {
    Text = "Você já viu. Este é o ponto de interseção do destino, Nefraea."
  },
  AvgDialog_131223_Content_2 = {
    Text = "São atraídos por fios de seda, avançando na tua direção, apenas para se dissolverem em poças de lodo negro sob a tua radiância prateada."
  },
  AvgDialog_131223_Content_20 = {
    Text = "Todos os erros acabarão aqui."
  },
  AvgDialog_131223_Content_21 = {
    Text = "Que declaração confiante, senhora prisioneira. Então me mostre com o que você pretende impedir os deuses, impedir o próprio destino..."
  },
  AvgDialog_131223_Content_22 = {
    Text = "O sorriso louco floresce no rosto de Nefraea. Os fios que a restringem a levantam, e no palco quebrado, ela é a única luz."
  },
  AvgDialog_131223_Content_23 = {
    Text = "\"Vinde, fiéis rastejantes do mundo! Curvai as vossas cabeças e prostrai-vos diante de mim!\""
  },
  AvgDialog_131223_Content_24 = {
    Text = "\"A Exaltada desceu do trono celestial! O Fim Inescapável revela-se aqui e agora!\""
  },
  AvgDialog_131223_Content_25 = {
    Text = "\"Esse falso destino—vamos celebrar juntos a sua destruição!\""
  },
  AvgDialog_131223_Content_3 = {
    Text = "Gosma selvagem, nada, triste, como o próprio destino deles."
  },
  AvgDialog_131223_Content_4 = {
    Text = "Nefraea não se importou com tudo isso, a cena à sua frente se desenrolou por inúmeros anos, e ela já estava acostumada a isso."
  },
  AvgDialog_131223_Content_5 = {
    Text = "Eu vi claramente. As imagens que você viu, tudo o que você viu, eu finalmente vi claramente..."
  },
  AvgDialog_131223_Content_6 = {
    Text = "A dor trazida pelos fragmentos já estava dormente. Ela sorriu enquanto olhava para os buracos caóticos no teatro."
  },
  AvgDialog_131223_Content_7 = {
    Text = "Um sorriso orgulhoso, compassivo e indiferente, por um momento, você quase não conseguia distinguir ela de Arachne."
  },
  AvgDialog_131223_Content_8 = {
    Text = "Apenas aqueles que estão na prisão podem realmente abrir a cela. O caos e a destruição que você vê não são o destino real, Nefraea..."
  },
  AvgDialog_131223_Content_9 = {
    Text = "Hehehehe! ... Durante todos esses anos, você tem se enganado assim, Arachne?"
  },
  AvgDialog_131224_Content_1 = {
    Text = "Espectador, ator, autor"
  },
  AvgDialog_131224_Content_10 = {
    Text = "Isso é...!"
  },
  AvgDialog_131224_Content_100 = {
    Text = "Vão, meus filhos. Encontrem %player%."
  },
  AvgDialog_131224_Content_101 = {
    Text = "Tomem o poder de {Male=his,Female=her}, cortem cada fio do Destino e rasguem a Grande Rede em pedaços! Que toda alma que se colocar em nosso caminho pereça nela!"
  },
  AvgDialog_131224_Content_102 = {
    Text = "Nós usaremos o sangue deste fragmento para que o grande Primordial desperte novamente."
  },
  AvgDialog_131224_Content_103 = {
    Text = "Quando você vir sua preciosa Rede do destino despedaçada e reduzida a um lodaçal imundo, você afundará no vazio infinito assim como nós?"
  },
  AvgDialog_131224_Content_104 = {
    Text = "Deusa do destino, minha boa irmã, querida <Red:Arachne>?"
  },
  AvgDialog_131224_Content_105 = {
    Text = "A fronteira entre o palco e a plateia parece desaparecer; o próprio espaço perde todo significado."
  },
  AvgDialog_131224_Content_106 = {
    Text = "No meio de risadas sombrias, a marionete parecia estar de pé diante de vocês, olhando fixamente nos olhos de Arachne."
  },
  AvgDialog_131224_Content_107 = {
    Text = "A luz se dissipa, o telão cai. O fantoche e seu riso desaparecem, e no vazio do teatro, resta apenas o som do fuso girando suavemente."
  },
  AvgDialog_131224_Content_108 = {
    Text = "Desculpe, eu não entendi completamente... o destino abandonado, o que significa?"
  },
  AvgDialog_131224_Content_109 = {
    Text = "Como você pode ver, o destino é um emaranhado de fios caóticos, se ninguém o tecer, este universo cairá em um caos sem fim. Eu acho que essa é uma visão que todos nós não queremos ver."
  },
  AvgDialog_131224_Content_11 = {
    Text = "No momento em que você entrou pela porta, a porta atrás de você desapareceu."
  },
  AvgDialog_131224_Content_110 = {Text = "Claro..."},
  AvgDialog_131224_Content_111 = {
    Text = "Tecer fios em uma rede do destino, manter o funcionamento normal deste universo é minha eterna responsabilidade."
  },
  AvgDialog_131224_Content_112 = {
    Text = "A cada momento, o Destino guarda infinitas possibilidades. A cada momento, sou forçada a fazer uma escolha."
  },
  AvgDialog_131224_Content_113 = {
    Text = "Os destinos corretos são tecidos na Grande Rede; os errados são descartados. É assim que a rede funciona. É inevitável."
  },
  AvgDialog_131224_Content_114 = {
    Text = "Minha irmã, que também é uma parte de mim que foi abandonada por aqueles destinos errados."
  },
  AvgDialog_131224_Content_115 = {
    Text = "Arachne sorri, em seu relato sereno, você não percebe nenhum sinal de emoção."
  },
  AvgDialog_131224_Content_116 = {
    Text = "Aqueles destinos abandonados... serão enviados para o \"Abismo\"?"
  },
  AvgDialog_131224_Content_117 = {
    Text = "O sonho daquela divindade suprema constituiu este universo, aquele lugar chamado \"Abismo\" é o subconsciente da divindade, o local de reunião de tudo o que não aconteceu, de todos os destinos inexistentes."
  },
  AvgDialog_131224_Content_118 = {
    Text = "Elas deveriam ter desaparecido completamente naquele lugar vazio, mas sob a liderança da minha irmã, elas conseguiram sobreviver de alguma forma."
  },
  AvgDialog_131224_Content_119 = {
    Text = "Arachne olhou para aquele enorme pano, olhando para trás do pano, aquele fantoche que representava Nefraea."
  },
  AvgDialog_131224_Content_12 = {
    Text = "Dentro da loja estreita que você imaginava, há um vasto e infinito espaço de dimensão."
  },
  AvgDialog_131224_Content_120 = {
    Text = "Ela não tem o poder de controlar o destino, mas, assim como eu, consegue ver os fios do destino, bloqueá-los, poluí-los, destruir a trajetória que teci para eles, levando-os à morte..."
  },
  AvgDialog_131224_Content_121 = {
    Text = "Então ela quer me encontrar, usar minha força para despertar Toguwaibo novamente?"
  },
  AvgDialog_131224_Content_122 = {
    Text = "Não sei os planos específicos dela, mas parece que é assim. De qualquer forma, ela é um erro que eu preciso resolver."
  },
  AvgDialog_131224_Content_123 = {
    Text = "Ela fechou os canais entre as dimensões, também por causa disso, não é?"
  },
  AvgDialog_131224_Content_124 = {
    Text = "O túnel dimensional está fechado por mim. Ela tem esperado, esperando por este momento de ir a Cardas com você."
  },
  AvgDialog_131224_Content_125 = {
    Text = "Cardas é uma dimensão na qual meu poder nunca penetrou, e é também o lugar mais próximo da conexão com aquela pessoa suprema."
  },
  AvgDialog_131224_Content_126 = {
    Text = "Se você a levar de volta com você, o destino da catástrofe será irreversível."
  },
  AvgDialog_131224_Content_127 = {
    Text = "Perdoe-me por tomar tais liberdades, {Male=Mr.,Female=Miss} Guardião."
  },
  AvgDialog_131224_Content_128 = {
    Text = "Eu entendo, Arachne. Se o que você diz é verdade, então não é a visão que eu quero ver."
  },
  AvgDialog_131224_Content_129 = {
    Text = "Então, se eu quero voltar para Cardas, preciso primeiro lidar com ela..."
  },
  AvgDialog_131224_Content_13 = {
    Text = "Incontáveis palcos flutuam como estrelas nessa escuridão vasta, marionetes em cada um recitando suas falas."
  },
  AvgDialog_131224_Content_130 = {
    Text = "Senhor, houve uma anomalia no palco da área GI-9849. Esta é a terceira ocorrência de hoje."
  },
  AvgDialog_131224_Content_131 = {
    Text = "Depois de roubar os materiais do Tecelão do Destino, ela sempre se diverte em destruir o destino."
  },
  AvgDialog_131224_Content_132 = {
    Text = "Minhas desculpas, %player%, mas preciso cuidar dessas perturbações. Por favor, venha comigo. Há assuntos vitais que preciso que você veja."
  },
  AvgDialog_131224_Content_133 = {
    Text = "Arachne sorriu e balançou a cabeça. Ela fez um gesto de convite para você, levantando-se com a roca."
  },
  AvgDialog_131224_Content_134 = {Text = "..."},
  AvgDialog_131224_Content_135 = {
    Text = "Isso... é o palco destruído?..."
  },
  AvgDialog_131224_Content_136 = {
    Text = "Seguindo o caminho feito de teias de aranha, vocês chegam a um palco desgastado. Dentro de um simples café no palco, algumas pessoas que parecem estudantes estão conversando baixinho."
  },
  AvgDialog_131224_Content_137 = {
    Text = "Neste período, ela tem enviado seus servos para destruir o destino destes mundos. Minhas serventes estão por toda parte à procura delas, e suas batalhas fizeram com que muitas crianças boas perdessem a vida."
  },
  AvgDialog_131224_Content_138 = {
    Text = "O destino de todos os mundos está conectado em uma única rede gigante, cada colapso de um mundo rasgará toda a rede do destino, mergulhando tudo em um caos completo e fatal."
  },
  AvgDialog_131224_Content_139 = {
    Text = "Nefraea roubou os materiais do Tecelão do Destino, eu não consigo usar facilmente minha própria força. Guardião {Male=senhor, Female=senhorita}, eu penso que talvez você possa me ajudar a reparar o destino deste mundo?"
  },
  AvgDialog_131224_Content_14 = {
    Text = "As palavras chegam até você de longe, como o murmúrio de incontáveis devotos em oração."
  },
  AvgDialog_131224_Content_140 = {
    Text = "Se o que você disse é verdade, ela também é um problema que eu preciso resolver."
  },
  AvgDialog_131224_Content_141 = {
    Text = "Arachne acenou para você com um pedido de desculpas. Ela levantou a mão e gentilmente moveu os fios ocultos no ar vazio."
  },
  AvgDialog_131224_Content_142 = {Text = "Dong—"},
  AvgDialog_131224_Content_143 = {
    Text = "Após o som nítido dos instrumentos, a voz melodiosa do apresentador ecoa, como um fluxo eterno que se junta a um poço profundo sem fim."
  },
  AvgDialog_131224_Content_144 = {
    Text = "O trompete toca florido. Estudantes jovens e acadêmicos, acima——"
  },
  AvgDialog_131224_Content_145 = {
    Text = "Arachne fez um gesto de convite."
  },
  AvgDialog_131224_Content_146 = {
    Text = "É hora da nossa entrada, %player%."
  },
  AvgDialog_131224_Content_147 = {
    Text = "Você acena com a cabeça. Em meio à suave voz de apresentação, duas marionetes sobem ao palco que lhes pertence."
  },
  AvgDialog_131224_Content_15 = {
    Text = "Fios de aranha se estendem do bonequeiro e do palco, juntando-se ao caminho tecido de fios de aranha sob seus pés, convergindo para o palco no centro deste espaço."
  },
  AvgDialog_131224_Content_16 = {
    Text = "Você se virou, e a criada ao seu lado já estava caminhando para frente."
  },
  AvgDialog_131224_Content_17 = {
    Text = "Realmente é um ritual de boas-vindas estranho..."
  },
  AvgDialog_131224_Content_18 = {
    Text = "Você hesitou e caminhou em direção ao palco central ao longo do caminho emaranhado. À medida que passava pelos palcos flutuantes, fragmentos de conversas flutuaram até seus ouvidos."
  },
  AvgDialog_131224_Content_19 = {
    Text = "Esta pessoa, eu vi confusão em seus olhos."
  },
  AvgDialog_131224_Content_2 = {
    Text = "E uma pergunta..."
  },
  AvgDialog_131224_Content_20 = {
    Text = "Você não se assustou com o acidente que aconteceu na loja, né?"
  },
  AvgDialog_131224_Content_21 = {
    Text = "A estrutura à base de gim, com o sabor da flor de hibisco, deve ser perfeita para o seu estado de espírito atual."
  },
  AvgDialog_131224_Content_22 = {Text = "..."},
  AvgDialog_131224_Content_23 = {
    Text = "Ah! Uma criança de rua, tão pequena, tão pobre."
  },
  AvgDialog_131224_Content_24 = {
    Text = "Com essas roupas finas, como você vai passar por este inverno?"
  },
  AvgDialog_131224_Content_25 = {
    Text = "Venha comigo. Deixe-me encontrar um lugar para você se abrigar da tempestade..."
  },
  AvgDialog_131224_Content_26 = {Text = "..."},
  AvgDialog_131224_Content_27 = {
    Text = "Essas... são as pessoas que encontrei há pouco?"
  },
  AvgDialog_131224_Content_28 = {
    Text = "Como eles apareceram nesses palcos..."
  },
  AvgDialog_131224_Content_29 = {
    Text = "Policiais em patrulha, funcionários lendo jornais, motoristas apreciando a paisagem da rua, amantes comprando flores, nobres conversando..."
  },
  AvgDialog_131224_Content_3 = {
    Text = "Essa já é a sua vigésima terceira pergunta, %player%."
  },
  AvgDialog_131224_Content_30 = {
    Text = "Aqueles que você conheceu e os que não conheceu, encenam suas próprias histórias neste número infinito de palcos. Em seus próprios palcos, eles são os protagonistas de suas próprias histórias."
  },
  AvgDialog_131224_Content_31 = {
    Text = "Ave, %player%! Bendito seja, infante de Akutê!"
  },
  AvgDialog_131224_Content_32 = {
    Text = "Ave, %player%! Bendito seja, Guardião de Misaq!"
  },
  AvgDialog_131224_Content_33 = {
    Text = "Ave, %player%! Bendito seja, deus da destruição!"
  },
  AvgDialog_131224_Content_34 = {
    Text = "Depois que vocês se aproximaram do palco central, três fantoches de formas diferentes subiram ao palco e se curvaram na sua direção."
  },
  AvgDialog_131224_Content_35 = {
    Text = "A Senhora está esperando por você lá dentro. Por favor, entre—{Male=Mr.,Female=Miss} Guardião."
  },
  AvgDialog_131224_Content_36 = {
    Text = "Quando a porta da caixa se abriu, parecia que a imagem e o som de todo o teatro foram pausados por um instante."
  },
  AvgDialog_131224_Content_37 = {
    Text = "Você atravessa a porta e levanta a cortina——"
  },
  AvgDialog_131224_Content_38 = {
    Text = "Eles aparecem nesses palcos porque o nome deste teatro é destino."
  },
  AvgDialog_131224_Content_39 = {
    Text = "Uma voz fria e serena chega até você antes de qualquer cor."
  },
  AvgDialog_131224_Content_4 = {
    Text = "Em comparação com os enigmas deste lugar, minhas perguntas ainda são insuficientes."
  },
  AvgDialog_131224_Content_40 = {
    Text = "Em um camarote que parece não ter paredes, os fios que conectam cada palco e cada marionete convergem para um fuso que brilha suavemente. Uma mulher está sentada no ponto onde todos os fios se encontram, girando-o com uma mão delicada."
  },
  AvgDialog_131224_Content_41 = {
    Text = "Você vê cada detalhe dela com perfeita clareza. Mas a cada piscar de olhos, toda impressão desaparece de sua mente, sem deixar nada para trás."
  },
  AvgDialog_131224_Content_42 = {
    Text = "A imagem dela se recusa a permanecer. Quando ela vira a cabeça para olhar para você, seu coração—tenso de vigilância todo esse tempo—dispara em uma batida violenta."
  },
  AvgDialog_131224_Content_43 = {
    Text = "É você?!!"
  },
  AvgDialog_131224_Content_44 = {
    Text = "No Navio Paradis... e aqueles ataques...!"
  },
  AvgDialog_131224_Content_45 = {
    Text = "No momento em que você se prepara para injetar sua energia mental na chave de prata, a dona do teatro estende a mão e faz um movimento no ar. Seu gesto é suave e elegante, como se estivesse acariciando uma corda."
  },
  AvgDialog_131224_Content_46 = {
    Text = "Um som nauseante e úmido de dilaceração se ergue no ar. Enormes patas de aranha irrompem pelos corpos dos oficiais e dos transeuntes, espirrando sangue espesso com cheiro de ferro por todo você."
  },
  AvgDialog_131224_Content_47 = {
    Text = "O poder espiritual chegou à ponta dos seus dedos, mas ao mesmo tempo recuou como um fluxo contido por uma represa. Quando você levantou a mão no ar, percebeu de repente que, não se sabe desde quando, suas mãos estavam vazias."
  },
  AvgDialog_131224_Content_48 = {
    Text = "Chave de prata... a Chave de Prata sempre esteve na minha mão... por que..."
  },
  AvgDialog_131224_Content_49 = {
    Text = "A senhora oferece um leve sorriso e faz um pequeno aceno para sua criada."
  },
  AvgDialog_131224_Content_5 = {
    Text = "Não sou o respondedor que você está procurando. A pessoa que pode responder suas perguntas está aqui esperando por você."
  },
  AvgDialog_131224_Content_50 = {
    Text = "Sob seu olhar atônito, a criada se aproxima e respeitosamente coloca a Chave de prata de volta em sua mão."
  },
  AvgDialog_131224_Content_51 = {
    Text = "Impossível... Ela nunca poderia ter roubado a Chave de Prata!..."
  },
  AvgDialog_131224_Content_52 = {
    Text = "Antes de entrar no teatro, você segurou aquela chave com firmeza, mantendo uma conexão espiritual constante."
  },
  AvgDialog_131224_Content_53 = {
    Text = "Seu treinamento em Misaq lhe concedeu um nível de vigilância tão alto que ninguém jamais poderia esperar arrancá-la de suas mãos."
  },
  AvgDialog_131224_Content_54 = {
    Text = "Por quê..."
  },
  AvgDialog_131224_Content_55 = {
    Text = "Ninguém pode deixá-lo, mas o destino pode."
  },
  AvgDialog_131224_Content_56 = {
    Text = "Perdoe-me, %player%. Eu entendo sua ansiedade e respeito seu poder."
  },
  AvgDialog_131224_Content_57 = {
    Text = "Para evitar qualquer dano acidental ao meu teatro, não tive escolha senão alterar brevemente o destino da chave em sua mão. Espero que possa relevar essa liberdade."
  },
  AvgDialog_131224_Content_58 = {
    Text = "Ela acena com a mão, e um feixe de luz atravessa o espaço entre vocês. Olhando de perto, você vê um fio tênue, quase imperceptível, estendendo-se da Chave de prata, seguindo até a roda de fiar ao lado dela."
  },
  AvgDialog_131224_Content_59 = {
    Text = "Esses fios são...?"
  },
  AvgDialog_131224_Content_6 = {
    Text = "Vocês pararam em frente a uma porta de teatro que só tem a largura de uma pessoa. Sem placa, nem clientes, parecia uma teia de aranha insignificante entre as lojas luxuosas de Londinium."
  },
  AvgDialog_131224_Content_60 = {
    Text = "Existem muitas explicações sobre fios, algumas delas são excessivamente complexas para o momento atual. Você pode entendê-los simplesmente como... destino."
  },
  AvgDialog_131224_Content_61 = {
    Text = "A roda de fiar gira suavemente por conta própria. Ela se levanta e oferece um gracioso aceno de saudação."
  },
  AvgDialog_131224_Content_62 = {
    Text = "Arachne, a mestra do Teatro do Destino. É uma honra conhecê-lo, Guardião."
  },
  AvgDialog_131224_Content_63 = {
    Text = "Não se preocupe, você está seguro aqui."
  },
  AvgDialog_131224_Content_64 = {
    Text = "De fato, se você quer me matar, eu provavelmente não tive nenhuma chance de sobreviver agora há pouco."
  },
  AvgDialog_131224_Content_65 = {
    Text = "À medida que Arachne puxava os fios, a luz proveniente das rodas de fiar na cabine se apagava. Você olhava com uma expressão complexa para a chave de prata devolvida pela servente, franzindo a testa enquanto a encarava."
  },
  AvgDialog_131224_Content_66 = {
    Text = "No Navio Paradis, você me ajudou. Mas desde que cheguei a esta cidade, você me atacou duas vezes."
  },
  AvgDialog_131224_Content_67 = {
    Text = "Eu entendo sua cautela. Mas, por favor, acredite quando digo que nunca levantei um dedo para lhe fazer mal."
  },
  AvgDialog_131224_Content_68 = {
    Text = "Bloqueou meu link com Cardas, me atacou várias vezes... Você está dizendo que não foi você quem fez essas coisas?"
  },
  AvgDialog_131224_Content_69 = {
    Text = "Aquela pessoa que te incomodou, embora tenha o mesmo rosto que eu, não sou eu."
  },
  AvgDialog_131224_Content_7 = {
    Text = "A servente abriu a porta suavemente, sua figura se escondeu na escuridão dentro da porta. Uma luz desconhecida na escuridão piscava levemente, como um convite oculto."
  },
  AvgDialog_131224_Content_70 = {
    Text = "Quanto à sua conexão com Cardas... isso é uma armadilha perigosa, %player%."
  },
  AvgDialog_131224_Content_71 = {Text = "Armadilha?"},
  AvgDialog_131224_Content_72 = {
    Text = "Uma criança nascida de minha própria existência lhe causou sofrimento desnecessário, e por isso, sinto muito de verdade. Essa situação começou comigo, e estou fazendo tudo ao meu alcance para corrigir o erro."
  },
  AvgDialog_131224_Content_73 = {
    Text = "Eu não entendi..."
  },
  AvgDialog_131224_Content_74 = {
    Text = "Esta é uma história um pouco longa, relacionada ao destino. Histórias sempre são mais fáceis de entender do que simples declarações."
  },
  AvgDialog_131224_Content_75 = {
    Text = "Por favor, sente-se, {Male=Mr.,Female=Miss} Guardião. Este novo ato da nossa peça começou há pouco tempo."
  },
  AvgDialog_131224_Content_76 = {
    Text = "Arachne acena levemente. As cortinas se abrem, e um palco vazio flutuante aparece diante de você."
  },
  AvgDialog_131224_Content_77 = {
    Text = "Parece haver um espelho sutil no palco, refletindo suas figuras."
  },
  AvgDialog_131224_Content_78 = {
    Text = "As trombetas soam uma fanfarra. Entra: O Destino abandonado."
  },
  AvgDialog_131224_Content_79 = {
    Text = "Em breve, sua figura desapareceu no espelho, e a forma de Arachne se transformou em uma marionete."
  },
  AvgDialog_131224_Content_8 = {
    Text = "Você hesitou um pouco e entrou pela porta."
  },
  AvgDialog_131224_Content_80 = {
    Text = "A marionete permanece sentada, mas sua compostura gentil evaporou."
  },
  AvgDialog_131224_Content_81 = {
    Text = "Ela gira um cálice cheio de um vinho vermelho-sangue como se estivesse entronizada em um assento de carnificina. Seus olhos, inocentes e ao mesmo tempo absolutamente impiedosos, percorrem a plateia."
  },
  AvgDialog_131224_Content_82 = {
    Text = "Atrás da marionete, quatro pares de membros aracnídeos afiados como navalhas balançam preguiçosamente, as pontas roçando as bochechas dos atendentes próximos."
  },
  AvgDialog_131224_Content_83 = {
    Text = "Ah, o ar da liberdade..."
  },
  AvgDialog_131224_Content_84 = {
    Text = "Há quantos anos estamos presos naquele abismo, meu querido servidor?"
  },
  AvgDialog_131224_Content_85 = {
    Text = "Não sei, meu mestre."
  },
  AvgDialog_131224_Content_86 = {
    Text = "Nome, tempo, emoções... Eu esqueci de tudo... Eu só me lembro de você, meu mestre, respeitável Nefraea."
  },
  AvgDialog_131224_Content_87 = {
    Text = "Apenas me lembro de que você me disse que nos levaria para longe daqui, que nos levaria a brandir a lâmina afiada da vingança contra o destino."
  },
  AvgDialog_131224_Content_88 = {
    Text = "Eu me lembro, criança. Eu fiz a vocês noventa mil promessas, agora, deixe-me contar a vocês a noventa mil e uma."
  },
  AvgDialog_131224_Content_89 = {
    Text = "A cada momento, só pode existir um tipo de destino. O Executor desse destino cortará inúmeros destinos errados, deixando apenas o único destino correto."
  },
  AvgDialog_131224_Content_9 = {Text = "..."},
  AvgDialog_131224_Content_90 = {
    Text = "Nós somos o destino abandonado. Hehehehe... meu querido Servidor, você é um erro, assim como eu."
  },
  AvgDialog_131224_Content_91 = {
    Text = "Na consciência subconsciente deste universo, neste abismo de nada que não existe, somos exilados e aprisionados. Vagamos aqui, esquecidos, para toda a eternidade. Nossa pena é mais longa do que o próprio tempo..."
  },
  AvgDialog_131224_Content_92 = {
    Text = "A mulher chamada Nefraea levantou-se da cadeira, inclinou-se e sorriu ao fazer contato visual com Arachne na plateia."
  },
  AvgDialog_131224_Content_93 = {
    Text = "Mas por que, deusa do destino? Por que somos nós que devemos ser eliminados?"
  },
  AvgDialog_131224_Content_94 = {
    Text = "O supremo e único deus de inúmeros universos finalmente despertou por um instante. Ele caiu novamente em sono, mas a prisão de sua consciência, aquele abismo eterno, finalmente se abriu para nós."
  },
  AvgDialog_131224_Content_95 = {
    Text = "Eu já havia esquecido e desaparecido. Mas por que, por que exatamente eu tenho que lembrar de toda essa dor?"
  },
  AvgDialog_131224_Content_96 = {
    Text = "Nefraea bebeu o líquido do copo e soltou um suspiro de satisfação. O suco vermelho escarlate escorreu pelos lábios pálidos dela, pingando na roda de fiar opaca que ela segurava."
  },
  AvgDialog_131224_Content_97 = {
    Text = "Talvez, este seja o arranjo do destino... um destino que você também não pode controlar."
  },
  AvgDialog_131224_Content_98 = {
    Text = "O deus primordial adormece novamente, mas Seus fragmentos chegaram ao nosso lar."
  },
  AvgDialog_131224_Content_99 = {
    Text = "Eu não tenho a habilidade de controlar o destino como você. Eu sou apenas o corrigidor do destino, o executor vindo do Nada. Os pecados no rio do destino serão punidos por mim em nome do Primordial."
  },
  AvgDialog_131225_Content_1 = {
    Text = "Sombra do passado"
  },
  AvgDialog_131225_Content_10 = {
    Text = "Diferente do que você imaginou com base na experiência, o interior desta villa parece excepcionalmente apertado, e Nefraea parece determinada a escrever de maneira desordenada em seu roteiro."
  },
  AvgDialog_131225_Content_11 = {
    Text = "Estantes e prateleiras intermináveis permanecem silenciosos e apertados, com frascos de vários tamanhos preenchendo cada espaço disponível."
  },
  AvgDialog_131225_Content_12 = {
    Text = "Espelhos prateados, ovos de aranha, sapatos de dança de insetos estranhos... uma variedade de objetos imersos em um líquido desconhecido, como bocas que gritam em silêncio."
  },
  AvgDialog_131225_Content_13 = {
    Text = "Você se aproxima dos diversos frascos e murmura as palavras nos rótulos."
  },
  AvgDialog_131225_Content_14 = {
    Text = "Aos dois anos, disse sua primeira frase na vida. Não chamou seus familiares, mas se despediu do velho mordomo que cuidou de sua família por gerações."
  },
  AvgDialog_131225_Content_15 = {
    Text = "Naquela noite, o velho mordomo faleceu de um ataque cardíaco. Chorando com os pertences do mordomo, do lado de fora da porta do mordomo..."
  },
  AvgDialog_131225_Content_16 = {
    Text = "Era um broche de família antigo."
  },
  AvgDialog_131225_Content_17 = {
    Text = "Cinco anos, sob os gritos constrangedores dos convidados do jantar, dançando timidamente a valsa como a mãe..."
  },
  AvgDialog_131225_Content_18 = {
    Text = "Era um par de sapatos de dança vermelhos vibrantes."
  },
  AvgDialog_131225_Content_19 = {
    Text = "Aos sete anos, recebi um presente de aniversário do meu pai, uma roda de fiar chamada \"Moira\"."
  },
  AvgDialog_131225_Content_2 = {
    Text = "Brick Lane, você se lembra da cena da investigação nesta área de Londinium."
  },
  AvgDialog_131225_Content_20 = {
    Text = "Na linha da roca, vejo a projeção do destino..."
  },
  AvgDialog_131225_Content_21 = {
    Text = "Era um punhado de fios de fiar quebrados."
  },
  AvgDialog_131225_Content_22 = {
    Text = "Primeira vez que vou ao teatro com meus pais... Primeira vez que conheço um amigo próximo... Primeira vez que enterro meu cachorro..."
  },
  AvgDialog_131225_Content_23 = {
    Text = "As etiquetas dos frascos aparecem uma a uma diante dos seus olhos. Sempre que você as toca, uma memória vaga surge em sua mente. Você se vira e olha para Arachne, confuso."
  },
  AvgDialog_131225_Content_24 = {
    Text = "Esses... são suas memórias?"
  },
  AvgDialog_131225_Content_25 = {
    Text = "É uma memória minha. Há muito tempo, elas pertenciam àquela pessoa chamada \"Memória\"."
  },
  AvgDialog_131225_Content_26 = {
    Text = "Estas são memórias preciosas... Por que colocá-las em um objeto secreto?"
  },
  AvgDialog_131225_Content_27 = {
    Text = "Na vida de cada pessoa, é necessário fazer algumas escolhas. Cada escolha tem um preço."
  },
  AvgDialog_131225_Content_28 = {
    Text = "Para alcançar o fim do caminho, é preciso sempre deixar algo para trás. Acho que você entende isso melhor do que ninguém, {Male=Mr.,Female=Miss} Guardião."
  },
  AvgDialog_131225_Content_29 = {
    Text = "Arachne não respondeu diretamente à sua pergunta, ela olhou para aqueles armários, passando levemente a mão sobre os frascos cheios de líquido."
  },
  AvgDialog_131225_Content_3 = {
    Text = "Sujo, caótico, o ar cheio de fumaça de carvão e o cheiro de esgoto, esses cheiros acompanharam Mason e Jenkin durante todos os momentos de suas vidas."
  },
  AvgDialog_131225_Content_30 = {
    Text = "Os movimentos dela são leves e lentos, como os de um velho em seus últimos dias, acariciando aqueles brinquedos preciosos da infância."
  },
  AvgDialog_131225_Content_31 = {
    Text = "Retire essas memórias do ícone secreto e manifeste-as nesta forma. Esta é a paisagem que você preparou para mim, Nefraea."
  },
  AvgDialog_131225_Content_32 = {
    Text = "O que você quer me dizer, eu entendi..."
  },
  AvgDialog_131225_Content_33 = {
    Text = "<Big:<Shake:AAAHHHH!—>>"
  },
  AvgDialog_131225_Content_34 = {
    Text = "Um grito agudo ecoa no quarto, os potes cheios de memórias tremem suavemente, como um grupo de espectadores que riem em silêncio."
  },
  AvgDialog_131225_Content_35 = {
    Text = "!!No quarto atrás do corredor"
  },
  AvgDialog_131225_Content_36 = {Text = "Bang—"},
  AvgDialog_131225_Content_37 = {
    Text = "Você corre rapidamente pelo corredor e arromba a porta..."
  },
  AvgDialog_131225_Content_38 = {
    Text = "Você está no meio de uma tempestade."
  },
  AvgDialog_131225_Content_39 = {
    Text = "Sem trovões, sem vento e sem chuva. Apenas uma infinidade de aranhas caindo do teto vazio como uma tempestade."
  },
  AvgDialog_131225_Content_4 = {
    Text = "E neste momento, uma mansão dourada e brilhante apareceu abruptamente entre duas casas de lata, como uma caixa de joias colocada em um monte de lixo."
  },
  AvgDialog_131225_Content_40 = {
    Text = "Artrópodes negros e viscosos se reúnem em uma maré avassaladora, devorando todos os objetos e toda a luz dentro da casa."
  },
  AvgDialog_131225_Content_41 = {
    Text = "No centro da tempestade escura e violenta, aquelas aranhas que subiam e roíam freneticamente se reuniram em uma forma humana que era apenas reconhecível. Onde a maré de aranhas ainda não havia coberto, apareceu o rosto de um velho pálido que você já havia visto."
  },
  AvgDialog_131225_Content_42 = {
    Text = "Arachne... senhorita..."
  },
  AvgDialog_131225_Content_43 = {
    Text = "Rápido... fuja!..."
  },
  AvgDialog_131225_Content_44 = {
    Text = "Shh... Não há falas suas aqui, \"bondoso\" senhor."
  },
  AvgDialog_131225_Content_45 = {
    Text = "A Vingança do Destino, Ato II, Cena II. Eu o nomeei de \"Chuva Torrencial\"."
  },
  AvgDialog_131225_Content_46 = {
    Text = "Aproveitem bem este maravilhoso banho de chuva, queridos espectadores."
  },
  AvgDialog_131225_Content_47 = {
    Text = "Água acumulada levanta ondas, as aranhas negras ouvem a ordem suprema e se espalham por todos os cantos do quarto."
  },
  AvgDialog_131225_Content_48 = {
    Text = "Na admiração de Nefraea, os guardas e servidores feitos de aranhas, junto com as criaturas repugnantes, vêm em sua direção —"
  },
  AvgDialog_131225_Content_5 = {
    Text = "Os vagabundos e os trabalhadores cansados passaram diante desta caixa magnífica, sem que ninguém lançasse um olhar a mais, como se ela existisse aqui desde o momento em que nasceram."
  },
  AvgDialog_131225_Content_6 = {
    Text = "A cidade até mesmo teve seu destino afetado... A força de Nefraea realmente está aumentando."
  },
  AvgDialog_131225_Content_7 = {
    Text = "Você se aproxima cautelosamente, prestes a bater na porta, mas assim que sua mão toca a porta, ela se abre silenciosamente."
  },
  AvgDialog_131225_Content_8 = {
    Text = "Parece que nosso atencioso mestre deixou a porta aberta para nós."
  },
  AvgDialog_131225_Content_9 = {
    Text = "Aquilo é..."
  },
  AvgDialog_131226_Content_1 = {
    Text = "E-eles estão mortos!!"
  },
  AvgDialog_131226_Content_10 = {
    Text = "Eu vi tudo. Tu não passaste por aquele portal, %player%. Este não é o lugar onde precisamos de estar."
  },
  AvgDialog_131226_Content_11 = {
    Text = "Tudo parece estranho... a Fusão, os Misaq, as Catástrofes — eles não sabem nada sobre nada disto."
  },
  AvgDialog_131226_Content_12 = {
    Text = "Mas esta cidade é exatamente como eu me lembro. Exatamente como era antes do Toguwaibo. Talvez devêssemos voltar à escola e dar uma vista de olhos. Podemos encontrar alguma coisa..."
  },
  AvgDialog_131226_Content_13 = {
    Text = "Acabei de vir de lá. Não há Misaq aqui, %player%."
  },
  AvgDialog_131226_Content_14 = {
    Text = "Sem Misaq...?"
  },
  AvgDialog_131226_Content_15 = {
    Text = "O mapa-mundo na loja era diferente de tudo o que já vi. E todos os calendários que encontrei — são diferentes. Não é o calendário Aluvião que usamos."
  },
  AvgDialog_131226_Content_16 = {
    Text = "O mais estranho é... esta cidade não tem fim."
  },
  AvgDialog_131226_Content_17 = {
    Text = "Não... tem fim?"
  },
  AvgDialog_131226_Content_18 = {
    Text = "Indo para norte a partir de onde o Misaq deveria estar, deveríamos ultrapassar os limites de Londinium."
  },
  AvgDialog_131226_Content_19 = {
    Text = "Fui atacado por aquelas aranhas pelo caminho. Para lhes escapar, mantive-me naquela estrada. Mas no final... encontrei-me de volta perto de onde vocês estavam. O extremo sul de Londinium."
  },
  AvgDialog_131226_Content_2 = {
    Text = "A multidão grita e se dispersa. Antes mesmo de você perceber, William está ao seu lado, aquele cabelo dourado inconfundível como sempre."
  },
  AvgDialog_131226_Content_20 = {
    Text = "Isto não é Londinium. Isto não é Cardas."
  },
  AvgDialog_131226_Content_21 = {
    Text = "Então a minha memória estava certa... o portal realmente fechou-se antes de eu conseguir entrar..."
  },
  AvgDialog_131226_Content_22 = {
    Text = "Olhas para cima, para as vistas familiares além da passagem, e suspiras, enquanto uma sensação de vazio se instala."
  },
  AvgDialog_131226_Content_23 = {
    Text = "Um lugar idêntico a Londinium, uma cidade sem fim, aranhas negras a aparecer do nada... e a \"Dama\" a quem obedecem..."
  },
  AvgDialog_131226_Content_24 = {
    Text = "É cedo demais para ter certeza, mas não acredito que o fecho do portal e a nossa chegada aqui sejam uma coincidência. Alguém engendrou tudo isto deliberadamente — quem quer que comande aquelas aranhas."
  },
  AvgDialog_131226_Content_25 = {
    Text = "Ainda não entendemos nada. Precisamos reunir informações primeiro..."
  },
  AvgDialog_131226_Content_26 = {
    Text = "Vocês dois..."
  },
  AvgDialog_131226_Content_27 = {Text = "Quem?!"},
  AvgDialog_131226_Content_28 = {
    Text = "Uma radiância prateada irrompe na palma mecânica de William, como uma lâmina pronta para ser desembainhada a qualquer momento."
  },
  AvgDialog_131226_Content_29 = {
    Text = "Naquele brilho prateado e perigoso, você distingue o ancião que há pouco tentara lhe oferecer comida."
  },
  AvgDialog_131226_Content_3 = {
    Text = "William, o companheiro mais velho... quando você... o que está acontecendo?"
  },
  AvgDialog_131226_Content_30 = {
    Text = "Sou... sou apenas eu..."
  },
  AvgDialog_131226_Content_31 = {
    Text = "Isto... isto pertence a você?"
  },
  AvgDialog_131226_Content_32 = {
    Text = "O velho abre a mão. O distintivo escolar da Misaq — seu comunicador — repousa silenciosamente em sua palma áspera."
  },
  AvgDialog_131226_Content_33 = {
    Text = "Ah! Deve ter caído durante a luta..."
  },
  AvgDialog_131226_Content_34 = {
    Text = "Isso significa muito para mim... muito obrigado!"
  },
  AvgDialog_131226_Content_35 = {
    Text = "Sob o olhar atento de William, você pega o distintivo de volta e o guarda com cuidado."
  },
  AvgDialog_131226_Content_36 = {
    Text = "Senhor... o senhor não ficou assustado com o que acabou de acontecer?"
  },
  AvgDialog_131226_Content_37 = {
    Text = "Assustado... claro que fiquei. Vivi aqui a vida inteira. Nunca vi nada parecido..."
  },
  AvgDialog_131226_Content_38 = {
    Text = "Mas aquilo parecia importante para você, e vocês acabaram de chegar — se perdesse, não teria a menor ideia de onde começar a procurar. Então trouxe para cá."
  },
  AvgDialog_131226_Content_39 = {
    Text = "Que gentileza sua... obrigado."
  },
  AvgDialog_131226_Content_4 = {
    Text = "Este não é o lugar. Mexam-se!"
  },
  AvgDialog_131226_Content_40 = {
    Text = "Acabamos de chegar e há muita coisa que não sabemos. Seria possível lhe fazer algumas perguntas?"
  },
  AvgDialog_131226_Content_41 = {
    Text = "Não me importo de passar mais um tempinho com vocês dois, mas receio que sei muito pouco sobre o que procuram."
  },
  AvgDialog_131226_Content_42 = {
    Text = "Um lugar com mais gente talvez seja mais útil para vocês, eu acho."
  },
  AvgDialog_131226_Content_43 = {
    Text = "Bem, devolvi o que precisava ser devolvido. Vou indo."
  },
  AvgDialog_131226_Content_44 = {
    Text = "O velho dispensa suas cortesias de despedida com um aceno enquanto sai do beco."
  },
  AvgDialog_131226_Content_45 = {
    Text = "Ele não parece ter más intenções. E tem razão — precisamos encontrar um lugar onde as informações circulem mais livremente, e rápido."
  },
  AvgDialog_131226_Content_46 = {
    Text = "Conheço o lugar perfeito!"
  },
  AvgDialog_131226_Content_47 = {
    Text = "Se esta cidade realmente espelha Londinium, então aquele lugar deve ser exatamente o que precisamos."
  },
  AvgDialog_131226_Content_48 = {
    Text = "Ao sair, uma aranha violeta pálida espreita no limite da sua visão, rastejando ao longo do seu fio e deslizando para uma fenda na parede, desaparecendo sem deixar rastro."
  },
  AvgDialog_131226_Content_5 = {
    Text = "William agarra-te e segue na direção oposta à da multidão."
  },
  AvgDialog_131226_Content_6 = {Text = "..."},
  AvgDialog_131226_Content_7 = {
    Text = "Não deveria haver ninguém por aqui."
  },
  AvgDialog_131226_Content_8 = {
    Text = "O que é que está a acontecer? Porque é que Londinium ficou assim..."
  },
  AvgDialog_131226_Content_9 = {
    Text = "Aquelas aranhas que nos atacaram, e aquela pessoa... será que ela está ligada à mulher que encontrámos no Navio Paradis?"
  },
  AvgDialog_131227_Content_1 = {
    Text = "Tawil! Eu..."
  },
  AvgDialog_131227_Content_2 = {
    Text = "Eu entendo, Guardião."
  },
  AvgDialog_131227_Content_3 = {
    Text = "Seu destino foi modificado. Você não pode parar, nem deve parar."
  },
  AvgDialog_131227_Content_4 = {
    Text = "Arachne não consegue pronunciar o destino do futuro... por favor, diga-me o que devo fazer..."
  },
  AvgDialog_131227_Content_5 = {
    Text = "Não posso te dizer o que há atrás da porta. Em relação a isso, há pessoas mais adequadas para te ajudar do que eu."
  },
  AvgDialog_131227_Content_6 = {
    Text = "Siga em frente, Guardião. Seu destino precisa ser esclarecido por você mesmo."
  },
  AvgDialog_131228_Content_1 = {
    Text = "Hum... heróis e palhaços, fantoches do destino... um bom espetáculo."
  },
  AvgDialog_131228_Content_2 = {
    Text = "Arachne me disse que a chave para abrir o cadeado é \"Alegria\"... Este é o seu domínio, N."
  },
  AvgDialog_131228_Content_3 = {
    Text = "Shh! Não fique tão apressado. Destruir um grande espetáculo é o pecado mais imperdoável deste universo."
  },
  AvgDialog_131228_Content_4 = {
    Text = "Vamos lá, Guardião do Segredo. Faz tanto tempo que não nos vemos, deixe-me ver se você tem novas percepções sobre a Alegria?"
  },
  AvgDialog_131229_Content_10 = {
    Text = "Responda-me... Liz!..."
  },
  AvgDialog_131229_Content_11 = {
    Text = "O fio do destino dela já se rompeu... A vida dela chegou ao fim."
  },
  AvgDialog_131229_Content_12 = {
    Text = "<Shake:Não... não podemos deixar Nefraea ter sucesso assim>! Ela deve pagar pelo seu comportamento imprudente"
  },
  AvgDialog_131229_Content_13 = {
    Text = "O preço a ser pago, o destino já preparou para ela. As pistas não vão parar aqui."
  },
  AvgDialog_131229_Content_14 = {
    Text = "Mas você acabou de dizer que Liz agora já..."
  },
  AvgDialog_131229_Content_15 = {
    Text = "A morte é apenas uma parte do Destino. Este é o meu palco, {Male=Mr.,Female=Miss} Guardião. Todos os destinos são fios em minhas mãos, e somente eu teço seu curso."
  },
  AvgDialog_131229_Content_16 = {
    Text = "Um som nauseante e úmido de dilaceração se ergue no ar. Enormes patas de aranha irrompem pelos corpos dos oficiais e dos transeuntes, espirrando sangue espesso com cheiro de ferro por todo você."
  },
  AvgDialog_131229_Content_17 = {
    Text = "<Shake:Espere, você quer dizer...>"
  },
  AvgDialog_131229_Content_18 = {
    Text = "O rosto de Arachne não expressava tristeza nem alegria. Ela se aproximou do Anunciador que havia sido brevemente parasitado por Nefraea. A luz suave do crepúsculo contornava seu contorno difuso e estável, como o próprio destino."
  },
  AvgDialog_131229_Content_19 = {
    Text = "Hehe... hahahahaha... Arachne, você ainda é tão, tão arrogante! Hahahaha..."
  },
  AvgDialog_131229_Content_2 = {
    Text = "Os inimigos ao redor caíram, mas seu ataque ainda não parou."
  },
  AvgDialog_131229_Content_20 = {
    Text = "Nefraea parece ter visto algo extremamente divertido, rindo a ponto de rolar no chão."
  },
  AvgDialog_131229_Content_21 = {
    Text = "Poluição do destino de Liz, levando-a a um desfecho mortal... Tudo o que você fez, a teia do destino irá lembrar."
  },
  AvgDialog_131229_Content_22 = {
    Text = "O destino errado será corrigido. À frente do seu destino, há um preço esperando por você."
  },
  AvgDialog_131229_Content_23 = {
    Text = "Arachne estendeu a mão e gentilmente tocou o topo da cabeça do cadáver. A roca em sua mão girava suavemente, e tudo ao seu redor parecia estar se distorcendo e se reorganizando nesse giro..."
  },
  AvgDialog_131229_Content_24 = {
    Text = "As linhas do destino, ouça o chamado da rede. Ao longo daquele único caminho, suba novamente ao palco..."
  },
  AvgDialog_131229_Content_25 = {
    Text = "O corpo dela... desapareceu?"
  },
  AvgDialog_131229_Content_26 = {
    Text = "Com o movimento dos dedos de Arachne, o corpo de Liz acima do palco parecia estar passando por uma queima silenciosa, se transformando em cinzas e se dissipando no ar."
  },
  AvgDialog_131229_Content_27 = {
    Text = "Sob aquelas cinzas caídas, um novo corpo se apresenta diante de você."
  },
  AvgDialog_131229_Content_28 = {
    Text = "É... aquele apresentador?"
  },
  AvgDialog_131229_Content_29 = {
    Text = "Espinhos perfuraram o corpo do anunciante, suspendendo-a acima do palco, todos os movimentos e amplitudes eram exatamente iguais aos de Liz."
  },
  AvgDialog_131229_Content_3 = {
    Text = "Você gritou, pisoteando o rosto sorridente do apresentador até esmagá-lo no palco de madeira."
  },
  AvgDialog_131229_Content_30 = {
    Text = "O anunciador deixou para trás um sorriso sinistro, e não houve mais som."
  },
  AvgDialog_131229_Content_31 = {
    Text = "Arachne, você..."
  },
  AvgDialog_131229_Content_32 = {
    Text = "Desculpe, cheguei tarde, eu acabei de... ah"
  },
  AvgDialog_131229_Content_33 = {
    Text = "A figura familiar levantou a cortina e subiu ao palco. Seu olhar passou por vocês e parou no cadáver pendurado no ar."
  },
  AvgDialog_131229_Content_34 = {
    Text = "Os movimentos dela... são realmente lindos..."
  },
  AvgDialog_131229_Content_35 = {
    Text = "Liz parecia ter esquecido os corpos espalhados pelo chão e o público em pé. Ela foi até o centro do palco, passando a mão acima da parte das pernas do cadáver pendurado, como se estivesse contemplando aquela elegante curva."
  },
  AvgDialog_131229_Content_36 = {
    Text = "Arachne, você... trocou o destino do Anunciador e da Liz ?"
  },
  AvgDialog_131229_Content_37 = {
    Text = "Mas você disse que esse tipo de consumo é difícil de suportar..."
  },
  AvgDialog_131229_Content_38 = {
    Text = "O consumo não está relacionado à escolha. No meu destino, este é também o preço que devo pagar."
  },
  AvgDialog_131229_Content_39 = {
    Text = "Vá, %player%. Não deixe a Senhorita Liz esperando."
  },
  AvgDialog_131229_Content_4 = {
    Text = "Sim... é assim... raiva, desabafo! Que expressão espetacular..."
  },
  AvgDialog_131229_Content_40 = {
    Text = "Olhos etéreos e respiração. A saia que flutua ao vento, com uma sutil chama verde. Cada tremor das pontas dos dedos é como uma dança cuidadosamente coreografada."
  },
  AvgDialog_131229_Content_41 = {
    Text = "A figura ensanguentada que correu em sua direção há poucos instantes se sobrepõe à mulher diante de você agora. Liz está ali, vívida e viva—a intrincada retecedura do destino não deixou nenhuma marca sobre ela."
  },
  AvgDialog_131229_Content_42 = {
    Text = "Depois de um tempo, Liz voltou a si, afastando-se da apreciação do corpo, e virou-se para olhar você que estava ao seu lado."
  },
  AvgDialog_131229_Content_43 = {
    Text = "Hoje eu dormi em casa até a tarde e perdi a apresentação. Isso nunca tinha acontecido antes..."
  },
  AvgDialog_131229_Content_44 = {
    Text = "Parece que perdi algumas coisas muito importantes?"
  },
  AvgDialog_131229_Content_45 = {
    Text = "Os olhos de Liz varreram os cadáveres e manchas de sangue no chão que ela havia ignorado."
  },
  AvgDialog_131229_Content_46 = {
    Text = "Não, você não perdeu nada, Liz."
  },
  AvgDialog_131229_Content_47 = {
    Text = "Você... está bem? Seu corpo está com algum desconforto?"
  },
  AvgDialog_131229_Content_48 = {
    Text = "Eu me sinto bem. Mas me diga, {Male=sir,Female=miss}, nós já nos conhecemos? Você me parece estranhamente familiar..."
  },
  AvgDialog_131229_Content_49 = {
    Text = "Talvez seja porque, como seu seguidor, eu assisti a muitas das suas apresentações."
  },
  AvgDialog_131229_Content_5 = {
    Text = "Aquele rosto como lama sorriu, e uma voz fraca saiu de sua traqueia quebrada."
  },
  AvgDialog_131229_Content_50 = {
    Text = "Você sorri para ela. Este palco tem suas próprias histórias, e você não pretende contar a ela aquelas coisas antigas."
  },
  AvgDialog_131229_Content_51 = {
    Text = "Viemos por \"bondade\"."
  },
  AvgDialog_131229_Content_52 = {
    Text = "A amiga da Senhora Sorel finalmente chegou, eu estava preocupado em ir ao espetáculo e desapontar aquela \"boa\" pessoa... Por favor, sigam-me, minha residência fica não muito longe da companhia de dança."
  },
  AvgDialog_131229_Content_53 = {
    Text = "Liz lança um olhar demorado ao cadáver na parede antes de guiá-lo para trás da cortina."
  },
  AvgDialog_131229_Content_54 = {Text = "..."},
  AvgDialog_131229_Content_55 = {
    Text = "Então... o meu cadáver deveria estar pendurado no palco..."
  },
  AvgDialog_131229_Content_56 = {
    Text = "Não há tempo para lamentar os parceiros de dança que se foram, e também esqueceu de agradecer àqueles que o fizeram renascer."
  },
  AvgDialog_131229_Content_57 = {
    Text = "Na sua narrativa, os olhos de Liz piscam como chamas dançantes. Ela estende a mão, adotando a mesma postura que o corpo."
  },
  AvgDialog_131229_Content_58 = {
    Text = "Aquela imagem, é bonita?"
  },
  AvgDialog_131229_Content_59 = {
    Text = "A beleza suprema do mundo se revela em dois momentos: um é o nascimento, o outro é a morte. É uma imagem incomparável, senhorita Liz."
  },
  AvgDialog_131229_Content_6 = {
    Text = "Nefraea não está aqui, isso é apenas uma ilusão que ela deixou. Não se deixe enganar pela raiva, Guardião {Male=senhor, Female=senhorita}."
  },
  AvgDialog_131229_Content_60 = {
    Text = "Obrigado, senhora Arachne. Você é a tecelã do destino, então eu imagino que você deve estar frequentemente cercada por essas belezas. Isso é realmente... invejável."
  },
  AvgDialog_131229_Content_61 = {
    Text = "Muitos tesouros se tornarão uma punição."
  },
  AvgDialog_131229_Content_62 = {
    Text = "Se esta é a sua punição, qual é a recompensa que você deseja?"
  },
  AvgDialog_131229_Content_63 = {
    Text = "Liz não percebeu a breve pausa de Arachne e abriu a porta do quarto nos fundos do pátio."
  },
  AvgDialog_131229_Content_64 = {
    Text = "Aqui está a residência temporária do senhor \"Bondade\". Senhor \"Bondade\", seu amigo veio buscá-lo."
  },
  AvgDialog_131229_Content_65 = {
    Text = "\"Senhor Bondoso\"?"
  },
  AvgDialog_131229_Content_66 = {
    Text = "Um quarto simples, sem nenhum móvel que não pertença a aqui, sem nenhuma pessoa que não pertença a aqui."
  },
  AvgDialog_131229_Content_67 = {
    Text = "No interior da casa vazia, um simples bilhete está deitado silenciosamente na estante."
  },
  AvgDialog_131229_Content_68 = {
    Text = "\"Desculpe pela saída repentina. Senhora Sorel está preocupada com a sua segurança, por isso fez novos arranjos. Eu irei me esconder na villa das memórias.\""
  },
  AvgDialog_131229_Content_69 = {
    Text = "\"Sou imensamente grato pelo seu cuidado. Eu vou retribuir essa gentileza com seriedade.\""
  },
  AvgDialog_131229_Content_7 = {
    Text = "<Shake:Hu... Hu...>"
  },
  AvgDialog_131229_Content_70 = {
    Text = "Se a Sra. Sorel mudar de planos, certamente nos avisará..."
  },
  AvgDialog_131229_Content_71 = {
    Text = "Você olha para os olhos sem ondulação de Arachne. Naquele sorriso tranquilo que parece nunca desaparecer, você vê uma sombra que passa rapidamente."
  },
  AvgDialog_131229_Content_72 = {
    Text = "\"Memória\" é uma vagabunda. Ela não tem casa."
  },
  AvgDialog_131229_Content_73 = {
    Text = "O que?!... Isso..."
  },
  AvgDialog_131229_Content_74 = {
    Text = "\"As memórias\" do destino, provavelmente já foram alteradas por Nefraea. Os dois agora estão em perigo."
  },
  AvgDialog_131229_Content_75 = {
    Text = "Desculpe, eu não esperava..."
  },
  AvgDialog_131229_Content_76 = {
    Text = "Não é sua responsabilidade, senhorita Liz."
  },
  AvgDialog_131229_Content_77 = {
    Text = "Nefraea, já que pode alterar o seu destino, encontrar as pessoas ao seu redor também não é uma tarefa difícil. Essas são questões que precisamos resolver."
  },
  AvgDialog_131229_Content_78 = {
    Text = "As marcas em cima ainda não secaram completamente, o momento em que Nefraea agir não está longe, talvez ainda tenhamos tempo se formos rápidos..."
  },
  AvgDialog_131229_Content_79 = {
    Text = "Liz, algumas palavras, desta vez é tarde demais para dizer..."
  },
  AvgDialog_131229_Content_8 = {
    Text = "Quando aquele rosto sorridente já não pode mais ser reconhecido, você finalmente parou."
  },
  AvgDialog_131229_Content_80 = {
    Text = "Haverá outras oportunidades, {Male=Mr.,Female=Miss} Guardião. Espero que minha próxima dança o emocione tanto quanto esta."
  },
  AvgDialog_131229_Content_81 = {
    Text = "Depois de se despedir de vocês com um sorriso simples, Liz não se importa mais com as suas histórias complicadas."
  },
  AvgDialog_131229_Content_82 = {
    Text = "Ela levantou o braço, fazendo o mesmo arco que o cadáver, tentando restaurar a dança que sempre estava presente em sua mente."
  },
  AvgDialog_131229_Content_83 = {
    Text = "A brisa suave move a saia dela, como um cisne voando."
  },
  AvgDialog_131229_Content_9 = {
    Text = "O corpo de Liz, controlado, perdeu toda a vitalidade. Você coloca delicadamente seu corpo ensanguentado no chão e abre o canal espiritual conectado a ela."
  },
  AvgDialog_131230_Content_1 = {Text = "Fim"},
  AvgDialog_131230_Content_10 = {
    Text = "Já que você recriou esta cidade... eu pensei que você traria as coisas que já haviam desaparecido para cá."
  },
  AvgDialog_131230_Content_11 = {
    Text = "... você sente falta deles, não é?"
  },
  AvgDialog_131230_Content_12 = {
    Text = "Prefiro ver o palco se apresentando por si mesmo do que uma xícara de café."
  },
  AvgDialog_131230_Content_13 = {
    Text = "Recriei este lugar com minhas memórias, mas ainda assim não posso mudar o fato de que é um palco completamente novo."
  },
  AvgDialog_131230_Content_14 = {
    Text = "O novo café aqui também tem seu sabor único, não é?"
  },
  AvgDialog_131230_Content_15 = {
    Text = "Arachne sorriu, dando um leve gole naquele líquido amargo."
  },
  AvgDialog_131230_Content_16 = {
    Text = "Nefraea... o que aconteceu no final?"
  },
  AvgDialog_131230_Content_17 = {
    Text = "Seus fios do destino foram entrelaçados novamente. Isso significa... que vocês são mais uma vez a mesma pessoa?"
  },
  AvgDialog_131230_Content_18 = {
    Text = "Aquelas coisas que pertenciam a Nefraea, suas qualidades, sua natureza original, retornaram ao meu destino. Ou melhor, como você sabe — elas nunca partiram."
  },
  AvgDialog_131230_Content_19 = {
    Text = "Mas a Rede do destino é a única. Aquela pessoa que você conhece, Nefraea, aquela vingadora que afundou no Abismo e foi abandonada pelo destino, não tem fio que lhe pertença nesta rede."
  },
  AvgDialog_131230_Content_2 = {
    Text = [[
<Italic:Lascia ch'io pianga / Deixa-me chorar
mia cruda sorte, / meu cruel destino,>]]
  },
  AvgDialog_131230_Content_20 = {
    Text = "Ela... desvaneceu, {Male=Mr.,Female=Miss} Guardião."
  },
  AvgDialog_131230_Content_21 = {
    Text = "A roda de fiar gira suavemente, sem parar. Arachne fecha os olhos, levanta a cabeça delicadamente e cheira o leve perfume das flores no vento."
  },
  AvgDialog_131230_Content_22 = {
    Text = "O destino abandonado, enfrentando apenas o cárcere eterno e a completa extinção. É realmente uma coisa cruel..."
  },
  AvgDialog_131230_Content_23 = {
    Text = "A cada momento, o Destino exige uma decisão. Os caminhos certos permanecem, enquanto os errados são descartados. Até encontrarmos o Caminho Verdadeiro, isso é tão inevitável quanto o colapso do próprio universo."
  },
  AvgDialog_131230_Content_24 = {
    Text = "Até encontrarmos o Caminho Verdadeiro, isso é tão inevitável quanto o colapso do próprio universo."
  },
  AvgDialog_131230_Content_25 = {
    Text = "Diga-me, {Male=Mr.,Female=Miss} Guardião, se você tivesse o poder de controlar o Destino, deixaria que ele mergulhasse no caos? Ou faria a escolha pelos outros, mesmo que isso significasse carregar o nome de assassino?"
  },
  AvgDialog_131230_Content_26 = {
    Text = "Isso...eu..."
  },
  AvgDialog_131230_Content_27 = {
    Text = "Isso é meramente um debate para seu entretenimento, não uma pergunta que você precisa responder. Você já carrega peso demais; não precisa carregar este também."
  },
  AvgDialog_131230_Content_28 = {
    Text = "Arachne sorriu e balançou a cabeça."
  },
  AvgDialog_131230_Content_29 = {
    Text = "A decisão é uma forma de poder, mas muitos escolhem abrir mão dela mesmo quando está ao seu alcance."
  },
  AvgDialog_131230_Content_3 = {
    Text = "<Italic:E che sospiri la libertà! / e suspirar pela liberdade!>"
  },
  AvgDialog_131230_Content_30 = {
    Text = "Escolher é arcar com as consequências, e isso não é tarefa fácil, {Male=Mr.,Female=Miss} Guardião."
  },
  AvgDialog_131230_Content_31 = {
    Text = "Sou o manipulador do destino, todas as consequências do destino serão suportadas por mim."
  },
  AvgDialog_131230_Content_32 = {
    Text = "Esta é a palavra que Ele me deu quando bati pela primeira vez na porta de Chokmah-Da'at. A isso, eu aceito com alegria."
  },
  AvgDialog_131230_Content_33 = {
    Text = "Então você... embora não possa ver seu destino, tudo isso que está acontecendo agora... você na verdade já sabe."
  },
  AvgDialog_131230_Content_34 = {
    Text = "O sol quente brilha sobre esta rua, mas ao olhar para o rosto tranquilo de Arachne e imaginar as coisas que essa pessoa enfrenta todos os dias, até você não consegue evitar um arrepio."
  },
  AvgDialog_131230_Content_35 = {
    Text = "O romantismo traz lentidão, a bondade traz fragilidade, as memórias trazem dor..."
  },
  AvgDialog_131230_Content_36 = {
    Text = "Mesmo tendo se preparado para isso há muito tempo, você nunca verdadeiramente os deixou ir. Por quê?"
  },
  AvgDialog_131230_Content_37 = {
    Text = "Para você, desistir deles deve te fazer sentir um pouco mais leve."
  },
  AvgDialog_131230_Content_38 = {
    Text = "Você já esteve na prisão? Os prisioneiros que foram mantidos atrás das grades por tantos anos sempre levam consigo algumas coisas que valorizam."
  },
  AvgDialog_131230_Content_39 = {
    Text = "Uma medalha conquistada numa luta, um relógio de herança, uma foto de família..."
  },
  AvgDialog_131230_Content_4 = {
    Text = "Uma canção suave ecoa pelas ruas, flutuando com o vento ameno. Os pedestres na estrada param ou caminham ao som dessa melodia, desfrutando de sua tranquila vida na luz da primavera."
  },
  AvgDialog_131230_Content_40 = {
    Text = "Para os prisioneiros, esses desejos que os fazem sofrer são a motivação que os mantém vivos."
  },
  AvgDialog_131230_Content_41 = {
    Text = "Eles preservam essas coisas mais preciosas com cuidado, até o momento próximo da morte, entregando uma a uma aquelas coisas sem valor."
  },
  AvgDialog_131230_Content_42 = {
    Text = "...Na gaiola do Destino, não temos mais nada, {Male=Mr.,Female=Miss} Guardião."
  },
  AvgDialog_131230_Content_43 = {
    Text = [[
<Italic:Il duolo infranga / Que a dor despedace
queste ritorte / estas correntes>]]
  },
  AvgDialog_131230_Content_44 = {
    Text = "<Italic:de miei martiri / dos meus tormentos\nsol per pietà. / somente por piedade>"
  },
  AvgDialog_131230_Content_45 = {
    Text = "O cantor de ópera à beira da estrada canta para o rio do destino que flui pela cidade. A Arachne sorve café, ouvindo atentamente. Desde o início até o fim, o ângulo do seu sorriso nunca mudou."
  },
  AvgDialog_131230_Content_46 = {
    Text = "Sabe, {Male=Mr.,Female=Miss} Guardião, eu frequentemente sonho com a mesma cena repetidas vezes."
  },
  AvgDialog_131230_Content_47 = {
    Text = "Era um belo teatro, apenas eu e Nefraea. Foi nesta linda canção que me despedi dela."
  },
  AvgDialog_131230_Content_48 = {
    Text = "Veja, mesmo que não possamos ver nosso destino, seu julgamento está em toda parte."
  },
  AvgDialog_131230_Content_49 = {
    Text = "<Italic:E che sospiri la libertà! / E suspirar pela liberdade!\nE che sospiri la libertà! / E suspirar pela liberdade!>"
  },
  AvgDialog_131230_Content_5 = {
    Text = "Você pegou o café e tomou um grande gole."
  },
  AvgDialog_131230_Content_50 = {
    Text = "A voz do cantor de ópera nunca para, o fio da roca gira eternamente. Arachne deixou de lado a taça que segurava e, junto com o público que parou, aplaudiu sinceramente em silêncio."
  },
  AvgDialog_131230_Content_51 = {
    Text = "De qualquer forma, uma apresentação terminou, e este palco terá sua breve pausa. Nós, os atores, também estamos prestes a ir para o próximo palco."
  },
  AvgDialog_131230_Content_52 = {
    Text = "A influência de Nefraea já desapareceu, agora deve ser possível reabrir o portal conectado a Cardas?"
  },
  AvgDialog_131230_Content_53 = {
    Text = "O portal que conecta Cardas está no destino deste mundo. Você também já tentou atravessar dimensões."
  },
  AvgDialog_131230_Content_54 = {
    Text = "Você já conhece o perigo que está contido nele."
  },
  AvgDialog_131230_Content_55 = {
    Text = "De fato... não quero mais enfrentar aqueles olhares de Toguwaibo..."
  },
  AvgDialog_131230_Content_56 = {
    Text = "Arachne, você pode controlar o destino deste mundo, talvez você tenha uma maneira de me ajudar?"
  },
  AvgDialog_131230_Content_57 = {
    Text = "Estou muito feliz em servir, mas neste mundo, apenas esta cidade é o meu palco. O mestre do destino deste mundo não sou eu."
  },
  AvgDialog_131230_Content_58 = {
    Text = "Surpreendentemente!..."
  },
  AvgDialog_131230_Content_59 = {
    Text = "O Mestre deste mundo possui habilidades além até do meu alcance. Este mundo existe unicamente porque Ele assim o quis."
  },
  AvgDialog_131230_Content_6 = {
    Text = "Nem de longe se compara ao café bósnio."
  },
  AvgDialog_131230_Content_60 = {
    Text = "A menos que a passagem seja deliberadamente aberta, este lugar permanece oculto até mesmo do olhar do Primordial... É precisamente por isso que escolhi habitar aqui."
  },
  AvgDialog_131230_Content_61 = {
    Text = "Será que... ao abrir o portal, vai haver perigo aqui?"
  },
  AvgDialog_131230_Content_62 = {
    Text = "Como eu disse, o destino tem sua própria trajetória. Estar aqui é apenas esperar lentamente pela morte. Ajudar você a retornar a Cardas também é o desejo do mestre deste mundo."
  },
  AvgDialog_131230_Content_63 = {
    Text = "Pela luz que nos aguarda ao final do caminho do destino, este é um perigo que estamos mais do que dispostos a enfrentar."
  },
  AvgDialog_131230_Content_64 = {
    Text = "Entendi... tudo bem."
  },
  AvgDialog_131230_Content_65 = {
    Text = "Onde posso encontrá-Lo?"
  },
  AvgDialog_131230_Content_66 = {
    Text = "As linhas do destino d'Ele são vastas como o mar de estrelas, e tão efêmeras quanto a poeira. Apenas com a captura do destino, não consigo apontar diretamente a posição d'Ele para você."
  },
  AvgDialog_131230_Content_67 = {
    Text = "Mas talvez, isso possa te ajudar."
  },
  AvgDialog_131230_Content_68 = {
    Text = "Arachne lhe entrega uma página do folheto. Você franze a testa, olhando aquelas belas letras cursivas cheias de religiosidade."
  },
  AvgDialog_131230_Content_69 = {
    Text = "Anúncio de recrutamento:"
  },
  AvgDialog_131230_Content_7 = {
    Text = "Na última vez que fui ao palco para degustar, também achei o sabor bastante bom. Infelizmente, neste palco, a família que inventou aquele café já havia desaparecido há muito tempo."
  },
  AvgDialog_131230_Content_70 = {
    Text = "O Grande Senhor, o Eleito de Deus, o Executor do Deus Supremo, o herdeiro legítimo da grandiosa seita, o libertador dos sofrimentos e o Amigo próximo do Rei Divino já chegou ao Continente do Norte. A seita está se desenvolvendo rapidamente, os fiéis podem apressar-se para encontrá-Lo aqui."
  },
  AvgDialog_131230_Content_71 = {
    Text = "Os doze primeiros fiéis a chegar serão canonizados como santos, seguindo eternamente ao lado da fada, sob a proteção divina para sempre..."
  },
  AvgDialog_131230_Content_72 = {
    Text = "Isso... o que é isso?"
  },
  AvgDialog_131230_Content_73 = {
    Text = "Como você pode ver, é um folheto cuidadosamente criado."
  },
  AvgDialog_131230_Content_74 = {
    Text = "Como pode ser tão estranho o que está acima... Arachne, você consegue ver o destino, tem certeza de que isso não é uma armadilha?"
  },
  AvgDialog_131230_Content_75 = {
    Text = "Na sua linha de seda, eu vi a sua silhueta. Tenho certeza de que é o destino que você irá encontrar."
  },
  AvgDialog_131230_Content_76 = {
    Text = "É ajuda ou é perigo, eu não sei. Mas eu sei que, entre você e aquela pessoa que é o mestre do mundo, essa é a única conexão."
  },
  AvgDialog_131230_Content_77 = {
    Text = "A mão de Arachne se estendeu sobre o ridículo folheto, pegando algo invisível a você e colocando em sua palma."
  },
  AvgDialog_131230_Content_78 = {
    Text = "E isto é...?"
  },
  AvgDialog_131230_Content_79 = {
    Text = "Logo, um tênue fio de linha reluz com um brilho fraco em sua mão."
  },
  AvgDialog_131230_Content_8 = {
    Text = "Você olha ao redor desta cidade. A interseção Brick, a livraria de livros antigos, a mercearia do mercado aromático..."
  },
  AvgDialog_131230_Content_80 = {
    Text = "Este é o catalisador que o vincula àquele destino. Ele o guiará até onde você deve estar."
  },
  AvgDialog_131230_Content_81 = {
    Text = "Entendo. Assim que William, o companheiro mais velho, se recuperar, nós..."
  },
  AvgDialog_131230_Content_82 = {
    Text = "No breve vislumbre que tive dos seus fios, vi uma história interessante."
  },
  AvgDialog_131230_Content_83 = {
    Text = "Não pude ver o seu final, e por isso me alegro. Significa que ainda tenho a honra de ser espectadora do seu destino."
  },
  AvgDialog_131230_Content_84 = {
    Text = "Acredito que nenhuma história merece ficar sem ser ouvida... Então, por favor, não há necessidade de pressa. Vamos ouvir esta ópera até o seu fim, {Male=Mr.,Female=Miss} Guardião."
  },
  AvgDialog_131230_Content_85 = {
    Text = "A voz do cantor de ópera atravessou novamente as ruas. Arachne fechou os olhos, enquanto o sol caía sobre seu rosto sereno, suave como aquelas primaveras que ela já havia perdido."
  },
  AvgDialog_131230_Content_86 = {
    Text = "O fuso gira. A canção nunca para. Pessoas passam, e incontáveis fios que não se conseguem ver reúnem-se e tecem-se ao redor dela."
  },
  AvgDialog_131230_Content_87 = {
    Text = "Você olha para o rosto sorridente de Arachne. Você vê que não há nada ao seu redor."
  },
  AvgDialog_131230_Content_9 = {
    Text = "Tudo parece não ter mudado, até mesmo aquelas manchas de ferrugem desgastadas na placa da loja são idênticas às suas memórias."
  },
  AvgDialog_131231_Content_1 = {
    Text = "Ufa... Ainda bem que cheguei a tempo..."
  },
  AvgDialog_131231_Content_10 = {
    Text = "Sorel semicerrou os olhos enquanto observava Arachne. Ela descobriu que sua habilidade de reconhecer pessoas, da qual se orgulhava, havia falhado completamente. Ela não conseguia ver o passado da pessoa à sua frente, nem adivinhar seus desejos."
  },
  AvgDialog_131231_Content_11 = {
    Text = "Ela rapidamente esqueceu todos os detalhes daquele rosto no momento em que piscou. O canto da boca de Sorel se curvou de maneira divertida."
  },
  AvgDialog_131231_Content_12 = {
    Text = "Dois convidados fascinantes. Este salão certamente será inesquecível para mim. Por favor, sentem-se."
  },
  AvgDialog_131231_Content_13 = {
    Text = "Sorel virou-se e sentou-se no sofá, acenando para vocês com a mão."
  },
  AvgDialog_131231_Content_14 = {
    Text = "Tive várias interações com a \"bondade\", ele veio até mim em busca do meu abrigo."
  },
  AvgDialog_131231_Content_15 = {
    Text = "Vocês me salvaram. Eu não consigo ver vocês, mas posso perceber que não têm más intenções."
  },
  AvgDialog_131231_Content_16 = {
    Text = "Isso mesmo, Senhora Sorel. Viemos salvá-lo."
  },
  AvgDialog_131231_Content_17 = {
    Text = "Ele não está nesta mansão."
  },
  AvgDialog_131231_Content_18 = {
    Text = "Mas você disse agora há pouco..."
  },
  AvgDialog_131231_Content_19 = {
    Text = "Como você pode ver, minha mansão também não é segura."
  },
  AvgDialog_131231_Content_2 = {
    Text = "Após confirmar o estado de Karen, você se levanta e limpa o suor frio da testa."
  },
  AvgDialog_131231_Content_20 = {
    Text = "Sorel levantou o braço, olhando para os corpos desordenados no quarto magnífico e arrumado como se estivesse exibindo uma preciosa coleção."
  },
  AvgDialog_131231_Content_21 = {
    Text = "Aquele é um senhor de bom coração, mas não tolo. Eu posso ver que ele está em uma situação muito crítica."
  },
  AvgDialog_131231_Content_22 = {
    Text = "A amizade que tenho com ele é conhecida por muitos. Escondê-lo na mansão não é uma decisão sábia."
  },
  AvgDialog_131231_Content_23 = {
    Text = "Onde ele está agora?"
  },
  AvgDialog_131231_Content_24 = {
    Text = "Sorel se levanta e caminha até uma pintura a óleo. Você a segue, observando a imagem."
  },
  AvgDialog_131231_Content_25 = {
    Text = "Isso é...!"
  },
  AvgDialog_131231_Content_26 = {
    Text = "Anos atrás, eu fui ao Teatro de Londinium assistir a uma apresentação do Corpo de Baile do Cisne. Era para ser um simples compromisso, mas fiquei profundamente impressionado com a sua dança."
  },
  AvgDialog_131231_Content_27 = {
    Text = "Nestes anos, eu ocasionalmente visitei os bastidores quando fui convidado para apresentações da companhia de dança. Não temos uma amizade real, e é por isso que a companhia de dança em que ela está é o lugar mais adequado para acomodar aquela pessoa \"bondosa\"."
  },
  AvgDialog_131231_Content_28 = {
    Text = "Na pintura, Liz está vestida com trajes etéreos de dança, saltando alto no ar como um cisne em pleno voo."
  },
  AvgDialog_131231_Content_29 = {
    Text = "Liz... onde está sua companhia de dança agora?"
  },
  AvgDialog_131231_Content_3 = {
    Text = "Karen deve estar bem, ela foi afetada um pouco, com um tempo de descanso deve melhorar."
  },
  AvgDialog_131231_Content_30 = {
    Text = "Seguindo os Fios do destino que se tornavam cada vez mais claros, Arachne olhou para fora da janela, para o lugar conectado aos fios, escondido pela densa floresta."
  },
  AvgDialog_131231_Content_31 = {
    Text = "Em um lugar que você conhece muito bem."
  },
  AvgDialog_131231_Content_4 = {
    Text = "Consigo me lembrar claramente de cada rosto que já vi, mas a sensação que você me dá é estranha. Não posso ter certeza se já te vi... Isso nunca aconteceu comigo."
  },
  AvgDialog_131231_Content_5 = {
    Text = "Sorel pegou a garrafa de vinho que não havia sido derrubada na mesa de chá e serviu no copo, atravessando a sala cheia de corpos em fusão, e estendeu o copo em sua direção."
  },
  AvgDialog_131231_Content_6 = {
    Text = "Um Porto envelhecido por quarenta anos, minha coleção particular, os hienas lá embaixo não têm o direito de degustá-lo. Não importa quem vocês são ou por que estão aqui, eu acho que este vinho deve pertencer a vocês."
  },
  AvgDialog_131231_Content_7 = {
    Text = "Viemos por \"bondade\", Senhora Sorel."
  },
  AvgDialog_131231_Content_8 = {
    Text = "Arachne pegou o copo e acenou com um sorriso para Sorel."
  },
  AvgDialog_131231_Content_9 = {
    Text = "Quando não falava, ela era como uma teia de aranha na luz da manhã, não chamando a atenção. Depois que abriu a boca, todas as cores na sala pareciam se concentrar nela."
  },
  AvgDialog_131232_Content_1 = {
    Text = "Que batalha incrível, irmã."
  },
  AvgDialog_131232_Content_10 = {
    Text = "Você e seu servidor são pessoas que perderam o destino, não consigo capturar os fios do seu destino. Mas sua habilidade vem de mim, eu não consigo ver meu próprio destino, e você também não."
  },
  AvgDialog_131232_Content_11 = {
    Text = "Você e eu... esta é uma luta inútil destinada ao impasse. Não deveria ter acontecido."
  },
  AvgDialog_131232_Content_12 = {
    Text = "Claro, claro. Para você, essas coisas que já foram abandonadas por nós deveriam perecer no cemitério do destino, serem decompostas, desaparecerem, se extinguindo aqui, até a eternidade, eternamente."
  },
  AvgDialog_131232_Content_13 = {
    Text = "É uma pena, você não consegue ver Ele... mesmo que você tenha um poder imenso, como pode se comparar àquela pessoa suprema?"
  },
  AvgDialog_131232_Content_14 = {
    Text = "Você sabe. Você sabe que tudo isso é em vão. Mas você não pode parar de tecer a teia..."
  },
  AvgDialog_131232_Content_15 = {
    Text = "Uma vez que você já viu, não pode suportar aquelas linhas embaralhadas. Uma vez que você possui essa capacidade, não pode ficar de braços cruzados enquanto aqueles mundos caem em um caos interminável."
  },
  AvgDialog_131232_Content_16 = {
    Text = "Você lhes traz uma falsa tranquilidade, e também os leva por um caminho que inevitavelmente levará à destruição."
  },
  AvgDialog_131232_Content_17 = {
    Text = "Que pessoa triste, Arachne."
  },
  AvgDialog_131232_Content_18 = {
    Text = "Este é o nosso destino, Nefraea."
  },
  AvgDialog_131232_Content_19 = {
    Text = "Ah...parece que estou um pouco cansado. Debater com um tolo é a coisa mais entediante do mundo."
  },
  AvgDialog_131232_Content_2 = {
    Text = "O bar movimentado se silencia, os corpos caídos se transformam em um líquido negro e pó, dissipando-se sob a luz suave."
  },
  AvgDialog_131232_Content_20 = {
    Text = "Bem-vindo ao segundo ato desta história. Este é o seu palco, mas a partir de agora, esta história será escrita por mim."
  },
  AvgDialog_131232_Content_21 = {
    Text = "A pequena seção de abertura é a mais importante, certo? Que nome deveríamos dar... Ah, que tal \"Reencontro\""
  },
  AvgDialog_131232_Content_22 = {
    Text = "Nefraea estava bastante satisfeita com seu nome, mergulhou suas patas no vinho envelhecido do copo e o levou à boca, soltando um suspiro de prazer."
  },
  AvgDialog_131232_Content_23 = {
    Text = "Para este dia, eu já me preparei por muito, muito tempo. Vou aproveitar muito essa história com você, querida irmã."
  },
  AvgDialog_131232_Content_24 = {
    Text = "Não haverá mais oportunidades para vocês questionarem. As garras afiadas de Nefraea passaram suavemente pela borda da bochecha de Arachne e, em seguida, caíram no chão junto com seu corpo."
  },
  AvgDialog_131232_Content_25 = {Text = "Espere...!"},
  AvgDialog_131232_Content_26 = {
    Text = "Ela não está aqui, {Male=Mr.,Female=Miss} Guardião."
  },
  AvgDialog_131232_Content_27 = {
    Text = "Um som de efervescência surgiu, e o líquido negro escorreu novamente do rosto do cadáver."
  },
  AvgDialog_131232_Content_28 = {
    Text = "\"Romântico\" aqueles olhos encantadores ainda mantinham o arco do sorriso, a aranha negra rastejava descontroladamente em seu corpo, aparecendo e desaparecendo nas órbitas brilhantes. Aquele lábio elegante não emitiu mais nenhum som."
  },
  AvgDialog_131232_Content_29 = {
    Text = "Aquilo é..."
  },
  AvgDialog_131232_Content_3 = {
    Text = "Nefraea e Arachne ainda estavam sentadas uma em frente à outra, ela derramou um copo de vinho e empurrou para Arachne."
  },
  AvgDialog_131232_Content_30 = {
    Text = "Ela matou essa marionete secreta, deixando uma marca sobre ela, poluindo seu destino, fazendo com que ela existisse brevemente em seu corpo."
  },
  AvgDialog_131232_Content_31 = {
    Text = "Arachne aproximou-se do ícone secreto, estendeu a mão para o topo da cabeça do \"romântico\" e olhou para o fio que quase havia desaparecido."
  },
  AvgDialog_131232_Content_32 = {
    Text = "...Você viu algo?"
  },
  AvgDialog_131232_Content_33 = {
    Text = "Os outros bonecos secretos também foram contaminados, não consigo perceber a existência deles na teia do destino... mas o destino \"romântico\" está ligado a eles."
  },
  AvgDialog_131232_Content_34 = {
    Text = "Ela me contou sobre o paradeiro da \"bondade\"."
  },
  AvgDialog_131232_Content_35 = {
    Text = "Arachne Liberar destino fio, para \"romântico\" organizar aquela bela franja."
  },
  AvgDialog_131232_Content_36 = {
    Text = "A habilidade de Nefraea vem de mim, o destino que ela contaminou, eu não consigo ver, muitas habilidades também são limitadas por isso."
  },
  AvgDialog_131232_Content_37 = {
    Text = "Você é um fragmento do Divino—alguém cujo destino é invisível para nós. É por isso que preciso da sua ajuda, {Male=Mr.,Female=Miss} Guardião."
  },
  AvgDialog_131232_Content_38 = {
    Text = "Fique tranquilo, mesmo que seja apenas para retornar a Cardas, eu preciso resolver isso com ela."
  },
  AvgDialog_131232_Content_39 = {
    Text = "Ela busca esses segredos, para quê?"
  },
  AvgDialog_131232_Content_4 = {
    Text = "Embora a senhorita \"Romântica\" já não esteja mais aqui, o vinho aqui não deve ser desperdiçado."
  },
  AvgDialog_131232_Content_40 = {
    Text = "Esses segredos se tornarão a fonte do poder dela."
  },
  AvgDialog_131232_Content_41 = {
    Text = "Então precisamos nos apressar... encontrar aqueles ícones secretos e aquelas cinzas dimensionais que podem te ajudar a tecer o destino..."
  },
  AvgDialog_131232_Content_42 = {
    Text = "Onde está aquele boneco chamado \"Bondade\" agora?"
  },
  AvgDialog_131232_Content_43 = {
    Text = "\"Romântico\" conseguiu avisá-lo do perigo antes de cair. Ele está escondido agora, abrigado por um velho amigo seu."
  },
  AvgDialog_131232_Content_44 = {
    Text = "Velho amigo?..."
  },
  AvgDialog_131232_Content_45 = {
    Text = "Siga-me, {Male=Mr.,Female=Miss} Guardião. O grande salão da Senhora Sorel está prestes a começar."
  },
  AvgDialog_131232_Content_5 = {
    Text = "Quer tentar? Em comparação com aquele segredo encenado, eu sou a pessoa que realmente te entende."
  },
  AvgDialog_131232_Content_6 = {
    Text = "Arachne não hesitou, ela sorriu e levantou o copo, dando um leve gole."
  },
  AvgDialog_131232_Content_7 = {
    Text = "Você não é adequado para esta profissão, Nefraea. Além do amargo e do azedo, não há mais nenhum outro sabor."
  },
  AvgDialog_131232_Content_8 = {
    Text = "Eu o chamo de \"Destino.\" Gostou do sabor?"
  },
  AvgDialog_131232_Content_9 = {
    Text = "Arachne não deu atenção ao olhar expectante de Nefraea. Ela bebeu lentamente o vinho na taça e a colocou suavemente sobre a mesa."
  },
  AvgDialog_132684_Content_1 = {
    Text = "<Small:<LightGray:zip...? (hum...?)>>"
  },
  AvgDialog_132684_Content_10 = {
    Text = "Exatamente, e considerando que Misaq tem a tradição de brincar com as pessoas para comunicar sentimentos, a escola não punirá essa \"brincadeira\" que não é excessiva."
  },
  AvgDialog_132684_Content_11 = {
    Text = "Piu! Piu, Piu——!<Small:<LightGray:(Professor Doll, você está apertando minha mão e meu rosto, certo? Você está esfregando meu rosto, não é?)>>"
  },
  AvgDialog_132684_Content_12 = {
    Text = "Embora o tom continue frio como sempre, até mesmo com um leve toque de amargura, você tem certeza de que os cantos da boca de Doll se elevaram pelo menos 2 milímetros."
  },
  AvgDialog_132684_Content_13 = {
    Text = "Desculpe, Guardião. O tradutor de Núcleo de prata parece ter apresentado um problema, mas não se preocupe, o reagente reverso poderá ser sintetizado amanhã de manhã."
  },
  AvgDialog_132684_Content_14 = {
    Text = "Você olha para a Doll com uma expressão de choque; mesmo que sua mente seja apenas a de uma lontra, consegue perceber que o reagente atrás dela está claramente em estado concluído."
  },
  AvgDialog_132684_Content_15 = {
    Text = "Professor, procurar Mosk?"
  },
  AvgDialog_132684_Content_16 = {
    Text = "!!!Pequena bola de carvão—"
  },
  AvgDialog_132684_Content_17 = {
    Text = "Piu——<Small:<LightGray:(chefe——)>>"
  },
  AvgDialog_132684_Content_18 = {
    Text = "Dado que temos pessoas com vasta experiência em relação a esse grupo, eu acho que passar um dia com elas deve ajudar nosso Guardião a lembrar-se."
  },
  AvgDialog_132684_Content_19 = {
    Text = "Mosk, cuide da tarefa de %player% que foi passada para você."
  },
  AvgDialog_132684_Content_2 = {Text = "*salto"},
  AvgDialog_132684_Content_20 = {
    Text = "*Viva! Pequena bola de carvão, vamos brincar juntos"
  },
  AvgDialog_132684_Content_21 = {
    Text = "Piu!<Small:<LightGray:(Vamos brincar juntos!)>>"
  },
  AvgDialog_132684_Content_22 = {
    Text = "Puf—<Small:<LightGray:(não, Ramona, me salve—)>>"
  },
  AvgDialog_132684_Content_23 = {Text = "Tossir."},
  AvgDialog_132684_Content_24 = {
    Text = "Parceiro, hoje não há nada de importante, não se preocupe."
  },
  AvgDialog_132684_Content_25 = {
    Text = "Eu também vou reservar tempo hoje para garantir a sua segurança."
  },
  AvgDialog_132684_Content_26 = {
    Text = "Embora as palavras digam isso, é evidente que ela também foi completamente controlada pela sua habilidade incrível com as mãos, assim como a Mosk."
  },
  AvgDialog_132684_Content_27 = {
    Text = "Piu, piu piu piu...<Small:<LightGray:(há alguém que possa ajudar, William, o companheiro mais velho...)>>"
  },
  AvgDialog_132684_Content_28 = {
    Text = "A propósito, William saiu para uma missão hoje e voltará muito tarde."
  },
  AvgDialog_132684_Content_29 = {
    Text = "*beber chá <Small:<LightGray:(Ufa, uma oportunidade rara, meu estudante mais preocupado e mais importante, vamos deixar tudo de lado e relaxar por um dia.)>>"
  },
  AvgDialog_132684_Content_3 = {
    Text = "*esfregar o rosto"
  },
  AvgDialog_132684_Content_30 = {
    Text = "Neste momento, um certo companheiro mais velho à distância."
  },
  AvgDialog_132684_Content_31 = {Text = "Atchim"},
  AvgDialog_132684_Content_32 = {
    Text = "Estranho, tenho uma sensação estranha e não muito boa."
  },
  AvgDialog_132684_Content_33 = {
    Text = "Hoje é melhor voltar para a escola mais cedo."
  },
  AvgDialog_132684_Content_34 = {
    Text = "O Misaq do Dia da Mentira também é muito pacífico."
  },
  AvgDialog_132684_Content_35 = {
    Text = "É algo a se alegrar, é algo a se alegrar."
  },
  AvgDialog_132684_Content_4 = {Text = "¿¿¿!!!"},
  AvgDialog_132684_Content_5 = {
    Text = "Piu! Piu! Piu! Piu! Piu! Yiyiyiyi!!!<Small:<LightGray:(Eu me transformei em uma lontra! Ramona, salve-me!)>>"
  },
  AvgDialog_132684_Content_6 = {Text = "..."},
  AvgDialog_132684_Content_7 = {
    Text = "Boas notícias, o efeito deste spray não é irreversível e a preparação do reagente reverso é muito simples, claramente a outra parte não tem má intenção."
  },
  AvgDialog_132684_Content_8 = {
    Text = "Melhores notícias, você ousou usar o presente daquele pequeno mentiroso sem pensar, trocar temporariamente por um cérebro de lontra pode realmente ajudar você a se esclarecer."
  },
  AvgDialog_132684_Content_9 = {
    Text = "Então, essa conversão temporária não causará dano algum ao Guardião?"
  },
  AvgDialog_13733_Content_1 = {
    Text = "Rito Vermelho"
  },
  AvgDialog_13733_Content_10 = {
    Text = "Heh, você nunca pode contar com a percepção dos Lemwahsianos. Mantenha os olhos bem abertos e observe..."
  },
  AvgDialog_13733_Content_11 = {
    Text = "Prin sacou uma faca ritual de sua manga e, sem hesitar, cortou o próprio pulso."
  },
  AvgDialog_13733_Content_12 = {
    Text = "Sangue Carmesim gotejou, gota a gota, sobre o círculo ritual traçado em enxofre, e assim, um Milagre ocorreu—"
  },
  AvgDialog_13733_Content_13 = {
    Text = "Como se uma gota de água convergisse para um deserto árido, o círculo ritual, tendo Absorvido o Sangue fresco, emitiu rapidamente anel após anel de luz carmesim escura."
  },
  AvgDialog_13733_Content_14 = {
    Text = "Eram como chamas sob um céu enegrecido, lambendo avidamente a areia amarela varrida pelo vento, Como se tentassem devorar a Terra inteira em suas fauces."
  },
  AvgDialog_13733_Content_15 = {
    Text = "Está vendo? Este é o verdadeiro momento da magia! Hahahaha!"
  },
  AvgDialog_13733_Content_16 = {
    Text = "Hahaha... <Big:GAAAH!!!>"
  },
  AvgDialog_13733_Content_17 = {
    Text = "Prin desabou de joelhos com um baque, suas mãos involuntariamente agarrando a própria garganta."
  },
  AvgDialog_13733_Content_18 = {
    Text = "As correntes que o conectam a Uvhash se tensionam rapidamente, unindo sua carne e suas almas com força."
  },
  AvgDialog_13733_Content_19 = {
    Text = "Ngh... O quê...?"
  },
  AvgDialog_13733_Content_2 = {
    Text = [[
Limite do Deserto Kuxi
Local do Ritual]]
  },
  AvgDialog_13733_Content_20 = {
    Text = "Uvhash não conseguia mais manter sua postura despreocupada."
  },
  AvgDialog_13733_Content_21 = {
    Text = "Foi arremessado por uma Força invisível, encarando um tanto atordoado o círculo ritual diante dele que estava à beira de perder o controle."
  },
  AvgDialog_13733_Content_22 = {Text = "Ugh..."},
  AvgDialog_13733_Content_23 = {
    Text = "<Big:AAAAAGH!>"
  },
  AvgDialog_13733_Content_24 = {
    Text = "Prin jazia esparramado no chão, encarando ferozmente a forma debatendo-se de Uvhash, e soltou uma risada sinistra."
  },
  AvgDialog_13733_Content_25 = {
    Text = "Dói... Bom, deveria doer..."
  },
  AvgDialog_13733_Content_26 = {
    Text = "Agora, nossas consciências estão firmemente ligadas..."
  },
  AvgDialog_13733_Content_27 = {
    Text = "Você viu como os cães Lemwash massacram meus parentes e profanam minha esposa... você sentiu isso..."
  },
  AvgDialog_13733_Content_28 = {
    Text = "<Big:Responda-me, sua criatura estúpida não melhor que @1!>"
  },
  AvgDialog_13733_Content_29 = {Text = "Heh heh..."},
  AvgDialog_13733_Content_3 = {
    Text = "Bom, primeiro espalhe uma camada de enxofre, depois o pó de carvão..."
  },
  AvgDialog_13733_Content_30 = {
    Text = "Não comemore cedo demais... velho tolo."
  },
  AvgDialog_13733_Content_31 = {
    Text = "Quando eu me libertar destes Grilhões, você será o primeiro que eu despedaçarei— Mmph!!"
  },
  AvgDialog_13733_Content_32 = {
    Text = "Que infelicidade. Receio que não terá o seu desejo realizado desta vez..."
  },
  AvgDialog_13733_Content_33 = {
    Text = "Prin arfou por ar, suas mãos trêmulas agarrando a corrente invisível, e então deu um puxão violento—"
  },
  AvgDialog_13733_Content_34 = {
    Text = "A corrente outrora inquebrável se despedaçou assim, sem mais."
  },
  AvgDialog_13733_Content_35 = {
    Text = "Heh heh@3AHHH@1AHHH!!"
  },
  AvgDialog_13733_Content_36 = {
    Text = "Prin solta um grito agonizante enquanto a carne de seu rosto apodrece e se desprende como casca de árvore, revelando a carne viva por baixo."
  },
  AvgDialog_13733_Content_37 = {
    Text = "O círculo mágico abre suas fauces sombrias e escancaradas, devorando sua carne aos poucos até que o feiticeiro seja reduzido a um esqueleto oco."
  },
  AvgDialog_13733_Content_38 = {
    Text = "Sacrifiquei minha carne, minha alma e tudo mais... e você?"
  },
  AvgDialog_13733_Content_39 = {
    Text = "Você nunca alcançará a verdadeira liberdade até ter matado 10.000 cães Lermvahi!"
  },
  AvgDialog_13733_Content_4 = {
    Text = "Não, isso não está certo. Deixe-me verificar o que o livro diz..."
  },
  AvgDialog_13733_Content_40 = {
    Text = "Uvhash lentamente se pôs de pé."
  },
  AvgDialog_13733_Content_41 = {
    Text = "Seu rosto havia sido carbonizado em Cinzas enegrecidas por chamas invisíveis, desmoronando a cada rajada de vento."
  },
  AvgDialog_13733_Content_42 = {Text = "Heh..."},
  AvgDialog_13733_Content_43 = {
    Text = "\"Verdadeira liberdade\"...? Que diabos é isso?"
  },
  AvgDialog_13733_Content_44 = {
    Text = "O guerreiro carbonizado ergueu-se imponente em meio à luz flamejante do fogo. Seus olhos eram de um vermelho carmesim, Apenas um Abalar rouco escapando de sua garganta."
  },
  AvgDialog_13733_Content_45 = {
    Text = "Apenas sempre houve uma coisa com a qual eu, Uvhash, verdadeiramente me importo—"
  },
  AvgDialog_13733_Content_46 = {
    Text = "Ele avançou a uma velocidade cegante, derrubando o mago no chão."
  },
  AvgDialog_13733_Content_47 = {
    Text = "Então ele mostrou suas presas afiadas e mordeu selvagemente o pescoço do mago."
  },
  AvgDialog_13733_Content_48 = {
    Text = "<Red:E isso é Sangue!!>"
  },
  AvgDialog_13733_Content_49 = {Text = "Sr. Prin!"},
  AvgDialog_13733_Content_5 = {
    Text = "A menos de cinquenta metros do campo de batalha, Prin estava trabalhando sem parar."
  },
  AvgDialog_13733_Content_50 = {
    Text = "<Shake:Esta vida... é sua... Vingue@2Ajude-me...>"
  },
  AvgDialog_13733_Content_51 = {
    Text = "Ajudá-lo? Velho, você deve estar confuso..."
  },
  AvgDialog_13733_Content_52 = {
    Text = "Uma presa não tem o direito de me fazer exigências, Uvhash."
  },
  AvgDialog_13733_Content_53 = {
    Text = "A razão pela qual tenho obedientemente te ouvido é porque posso esmagar esse teu brinquedinho de corrente quando eu quiser—não por causa daquele contrato de merda que assinamos."
  },
  AvgDialog_13733_Content_54 = {
    Text = "Tempo de jogo acabou. Agora, quero que abra bem os olhos e observe com atenção—"
  },
  AvgDialog_13733_Content_55 = {
    Text = "Enquanto eu massacro seus inimigos, seus conterrâneos e todo ser vivo à vista..."
  },
  AvgDialog_13733_Content_56 = {
    Text = "<Change>Demônio... seu demônio..."
  },
  AvgDialog_13733_Content_57 = {
    Text = "O Sangue de Prin fluiu livremente pelo círculo ritual, fazendo até aquelas luzes carmesim parecerem incomparavelmente pálidas."
  },
  AvgDialog_13733_Content_58 = {
    Text = "Ele sacrificou sua própria vida em troca da liberdade de Uvhash."
  },
  AvgDialog_13733_Content_59 = {
    Text = "Hehe... Ahhh@4..."
  },
  AvgDialog_13733_Content_6 = {
    Text = "Uvhash, a pedido de Prin, sentou-se ereto no centro de um círculo de Ritual desenhado com pó de enxofre."
  },
  AvgDialog_13733_Content_60 = {
    Text = "Uvhash ergueu lentamente a cabeça. Sangue ainda persistia nos cantos de sua boca, ainda não lambido, e seus olhos há muito haviam sido consumidos pela escuridão."
  },
  AvgDialog_13733_Content_61 = {
    Text = "Ele havia se tornado uma verdadeira Besta. Ou talvez, essa sempre tenha sido sua verdadeira face."
  },
  AvgDialog_13733_Content_62 = {
    Text = "<Red:Voltou, tudo voltou...>"
  },
  AvgDialog_13733_Content_7 = {
    Text = "Huff... huff..."
  },
  AvgDialog_13733_Content_8 = {
    Text = "Impressionante, conseguir dormir numa situação como esta..."
  },
  AvgDialog_13733_Content_9 = {
    Text = "Ainda há uma questão técnica que gostaria de perguntar, Sr. Prin.\nO pó que você espalhou não vai simplesmente ser levado pelo vento?"
  },
  AvgDialog_13734_Content_1 = {
    Text = "Huff... Finalmente alcancei vocês.\nEstou avisando, Uvhash, você deveria saber as consequências de me deixar para trás, certo?"
  },
  AvgDialog_13734_Content_10 = {
    Text = "Você finalmente havia chegado ao destino desta jornada. Prin espremeu algumas risadas estranhas de sua garganta, as chamas da vingança fazendo todo o seu corpo tremer."
  },
  AvgDialog_13734_Content_11 = {
    Text = "<Shake:Vamos, Uvhash...>"
  },
  AvgDialog_13734_Content_12 = {
    Text = "<Red:Vamos matar até nos saciarmos.>"
  },
  AvgDialog_13734_Content_2 = {Text = "Shh!!"},
  AvgDialog_13734_Content_3 = {
    Text = "Uvhash se agachou no topo de uma duna alta, soltando um silvo impaciente pelas narinas, como uma Besta focada na caça sendo incomodada por uma Invasão."
  },
  AvgDialog_13734_Content_4 = {
    Text = "Seus lábios estavam ligeiramente entreabertos, suas narinas tremendo levemente, e o brilho vermelho-sangue em seus olhos estava mais intenso do que nunca."
  },
  AvgDialog_13734_Content_5 = {
    Text = "<RedShake:Encontrei, encontrei...>"
  },
  AvgDialog_13734_Content_6 = {
    Text = "Você seguiu o olhar dele para baixo—"
  },
  AvgDialog_13734_Content_7 = {
    Text = "Incontáveis pequenos pontos negros estavam espalhados pelas dunas ondulantes, como formigas rastejando sobre uma mesa de areia."
  },
  AvgDialog_13734_Content_8 = {
    Text = "O choque de lâminas, gritos rugindo e o troar de cascos subiam e desciam em ondas, enquanto uma grandiosa tapeçaria de guerra se desenrolava lentamente diante dos seus olhos."
  },
  AvgDialog_13734_Content_9 = {
    Text = "Lemwashianos, Leonianos... Bom, muito bom."
  },
  AvgDialog_13735_Content_1 = {
    Text = "Expedição Solar"
  },
  AvgDialog_13735_Content_10 = {
    Text = "Ele ainda estava preso por correntes invisíveis, forçado a sentar-se de pernas cruzadas no chão numa postura desconfortável, a sua forma quase fundindo-se numa só com a escuridão."
  },
  AvgDialog_13735_Content_11 = {
    Text = "...Não esperava que ainda estivesse acordado."
  },
  AvgDialog_13735_Content_12 = {
    Text = "Um <Yellow:Golem> não precisa de sono."
  },
  AvgDialog_13735_Content_13 = {Text = "Golem...?"},
  AvgDialog_13735_Content_14 = {
    Text = "Heh heh... Pare de fingir."
  },
  AvgDialog_13735_Content_15 = {
    Text = "Você pode ver as correntes em mim, então certamente deve saber o que é um Golem."
  },
  AvgDialog_13735_Content_16 = {
    Text = "Você não esperava que aquele olhar aparentemente casual daquela vez tivesse sido notado por ele.\nEle realmente tem os instintos de uma Besta."
  },
  AvgDialog_13735_Content_17 = {
    Text = "Meu professor uma vez me disse..."
  },
  AvgDialog_13735_Content_18 = {
    Text = "Durante a era da Roma antiga, um alquimista louco criou o primeiro Golem ao custo de uma grande quantidade de humanidade."
  },
  AvgDialog_13735_Content_19 = {
    Text = "É também a existência mais próxima de um Corpo Desperto encontrada em textos antigos."
  },
  AvgDialog_13735_Content_2 = {
    Text = "Norte do Deserto de Kushi, Noite"
  },
  AvgDialog_13735_Content_20 = {
    Text = "Aquele Golem— era você, não era?"
  },
  AvgDialog_13735_Content_21 = {
    Text = "Isso mesmo... Era eu. Me tornei o cão de estimação de <Blue:Calígula> e matei muitas pessoas por ele."
  },
  AvgDialog_13735_Content_22 = {
    Text = "Depois, eles não precisavam mais de mim, então me trancaram no subsolo em completa escuridão, até que aquele me Liberou."
  },
  AvgDialog_13735_Content_23 = {
    Text = "Enquanto Uvhash falava, seu olhar passou por Prin, que ainda dormia profundamente na tenda."
  },
  AvgDialog_13735_Content_24 = {
    Text = "—A condição?"
  },
  AvgDialog_13735_Content_25 = {
    Text = "A condição é servi-lo como um cão e matar muitos Lemvashi no campo de batalha."
  },
  AvgDialog_13735_Content_26 = {
    Text = "Depois nos separamos, cada um vivendo sua própria vida."
  },
  AvgDialog_13735_Content_27 = {
    Text = "Uvhash se espreguiçou confortavelmente, esticando as pernas enquanto se recostava na duna de areia."
  },
  AvgDialog_13735_Content_28 = {
    Text = "Correntes desse calibre não podem te conter. Por que não simplesmente matar o feiticeiro e ir embora?"
  },
  AvgDialog_13735_Content_29 = {
    Text = "Porque ele disse que haveria muitas pessoas no campo de batalha."
  },
  AvgDialog_13735_Content_3 = {
    Text = "Zzz... Zzz... Wheeze..."
  },
  AvgDialog_13735_Content_30 = {
    Text = "<Red:Onde há muitas pessoas, haverá muito Sangue.>"
  },
  AvgDialog_13735_Content_31 = {
    Text = "<RedShake:Você deveria saber, já faz quase mil anos desde a última vez que provei aquele Sangue...>"
  },
  AvgDialog_13735_Content_32 = {Text = "..."},
  AvgDialog_13735_Content_33 = {
    Text = "Aquele sujeito não parece ser do tipo que cumpre promessas. E se ele estiver mentindo para você?"
  },
  AvgDialog_13735_Content_34 = {
    Text = "Então eu o mato. Simples, não é?"
  },
  AvgDialog_13735_Content_35 = {Text = "..."},
  AvgDialog_13735_Content_36 = {
    Text = "Você tem que admitir, as palavras dele fazem muito sentido."
  },
  AvgDialog_13735_Content_37 = {
    Text = "O vento da noite sopra suavemente enquanto as dunas ondulantes se estendem infinitamente diante de você. Sob o céu sem limites, apenas duas pequenas figuras permanecem."
  },
  AvgDialog_13735_Content_38 = {
    Text = "Você ergue a cabeça, Olhar para cima para o céu estrelado."
  },
  AvgDialog_13735_Content_39 = {
    Text = "Para passar esta longa noite, você decide trocar alguns pensamentos e experiências com Este Golem diante de você."
  },
  AvgDialog_13735_Content_4 = {
    Text = "Roncos trovejantes preenchem a noite silenciosa. Parece que o pequeno incidente durante o dia não afetou em nada o sono profundo de Prin."
  },
  AvgDialog_13735_Content_40 = {
    Text = "Ficar trancado no subsolo deve ter sido horrível.\nAssim que cumprir o acordo, você vai recuperar sua liberdade. Como se sente agora?"
  },
  AvgDialog_13735_Content_41 = {
    Text = "E você?\nVocê também não é escravo há muito tempo. Vagando pelo deserto dia após dia, sobrevivendo a duras penas — como se sente?"
  },
  AvgDialog_13735_Content_42 = {Text = "..."},
  AvgDialog_13735_Content_43 = {
    Text = "Não muito bem, sinceramente. Neste lugar esquecido por Deus, você nem consegue ver o sol..."
  },
  AvgDialog_13735_Content_44 = {
    Text = "Você é cego? Não consegue ver aquele sol enorme no deserto?"
  },
  AvgDialog_13735_Content_45 = {
    Text = "Você não entende. Estou falando do tipo de sol que é gentil, brilhante e aconchegante quando brilha sobre você... Isso você não encontra no deserto."
  },
  AvgDialog_13735_Content_46 = {
    Text = "Você solta um bocejo enquanto a Sonolência gradualmente se aproxima.\nCom a guarda um pouco baixa, a conversa se torna muito mais descontraída."
  },
  AvgDialog_13735_Content_47 = {
    Text = "Para sua surpresa, Uvhash acaba sendo um ouvinte razoável."
  },
  AvgDialog_13735_Content_48 = {
    Text = "Você pode não acreditar, mas eu na verdade tenho uma missão própria..."
  },
  AvgDialog_13735_Content_49 = {
    Text = "Assim que eu terminar tudo o que precisa ser feito, com certeza vou encontrar um lugar para me deitar e tomar sol, e comer muitos e muitos bolinhos..."
  },
  AvgDialog_13735_Content_5 = {
    Text = "Incapaz de aguentar mais, você finalmente abre a aba da tenda e sai para fora."
  },
  AvgDialog_13735_Content_50 = {
    Text = "...Dificuldade de entender."
  },
  AvgDialog_13735_Content_51 = {
    Text = "Golems nascem da escuridão, temendo inerentemente a luz do sol. Quase mil anos de aprisionamento Apenas aprofundaram sua aversão a ela."
  },
  AvgDialog_13735_Content_52 = {
    Text = "Eu realmente sinto pena de você. Tomar sol é a coisa mais maravilhosa do mundo..."
  },
  AvgDialog_13735_Content_53 = {
    Text = "Infelizmente para mim, até um desejo simples assim é difícil de realizar..."
  },
  AvgDialog_13735_Content_54 = {
    Text = "O vento aumentou.\nA areia fina à deriva teceu camada após camada de véus dourado-pálidos, flutuando suavemente sob o céu noturno repleto de Estrelas."
  },
  AvgDialog_13735_Content_55 = {
    Text = "Ouvindo o som claro do vento ao longe, você finalmente adormeceu no Sonho."
  },
  AvgDialog_13735_Content_56 = {Text = "..."},
  AvgDialog_13735_Content_57 = {
    Text = "Deserto de Kushi do Norte, Dia"
  },
  AvgDialog_13735_Content_58 = {
    Text = "Que diabos?! Você não jurou de pés juntos que não haveria nenhuma tempestade de areia nos próximos dias?!"
  },
  AvgDialog_13735_Content_59 = {
    Text = "Prin arregalou os olhos, apontando para a areia furiosa que avançava do horizonte."
  },
  AvgDialog_13735_Content_6 = {
    Text = "Que lindo..."
  },
  AvgDialog_13735_Content_60 = {
    Text = "Agora me diz, <Big:o que@1é AQUILO?>"
  },
  AvgDialog_13735_Content_61 = {Text = "Uh"},
  AvgDialog_13735_Content_62 = {
    Text = "Antes de você entrar no Sonhar, o dono original havia de fato feito algumas promessas insinceras para tirar dinheiro dessa galinha dos ovos de ouro."
  },
  AvgDialog_13735_Content_63 = {
    Text = "Agora não é hora de discutir. A tempestade de areia está vindo — corra!"
  },
  AvgDialog_13735_Content_64 = {
    Text = "Com isso, você disparou a toda velocidade, deixando Prin para trás."
  },
  AvgDialog_13735_Content_65 = {
    Text = "<Big:Ei... Volta aqui!>"
  },
  AvgDialog_13735_Content_66 = {
    Text = "Tempestade de areia? O que é isso? A paisagem me parece bem bonita."
  },
  AvgDialog_13735_Content_67 = {
    Text = "Uvhash correu sem esforço ao seu lado enquanto olhava para trás, com os olhos fixos na distância sem piscar."
  },
  AvgDialog_13735_Content_68 = {
    Text = "Você nunca viu uma tempestade de areia?"
  },
  AvgDialog_13735_Content_69 = {
    Text = "Uvhash deu de ombros."
  },
  AvgDialog_13735_Content_7 = {
    Text = "Boa noite, Sr. Guia."
  },
  AvgDialog_13735_Content_70 = {
    Text = "Meu raio de atividade no passado era limitado à cidade de Roma. Há coisas demais que eu nunca vi."
  },
  AvgDialog_13735_Content_71 = {
    Text = "<Shake:Ugh... Blurgh...>"
  },
  AvgDialog_13735_Content_72 = {
    Text = "Puxada pelas correntes, Prin, que havia ficado muito para trás, foi arrancada do chão e saiu voando."
  },
  AvgDialog_13735_Content_73 = {
    Text = "<Shake:D-Devagar... Estou morrendo aqui...>"
  },
  AvgDialog_13735_Content_74 = {
    Text = "Tch. quase esqueci, ainda tem aquele velho."
  },
  AvgDialog_13735_Content_75 = {
    Text = "Uvhash se virou e ergueu sem esforço o corpo baixo e atarracado da maga."
  },
  AvgDialog_13735_Content_76 = {
    Text = "O-O que você está fazendo?"
  },
  AvgDialog_13735_Content_77 = {
    Text = "Nada de mais, só te ajudar a correr um pouco mais rápido."
  },
  AvgDialog_13735_Content_78 = {
    Text = "Com isso, Uvhash casualmente enfiou o mago debaixo do braço, deu um passo à frente com um pé e empurrou o chão com a ponta do pé de trás, enrolando o corpo inteiro como uma mola."
  },
  AvgDialog_13735_Content_79 = {
    Text = "Ei... estou te avisando, agora não é hora de brincadeira—<Big:AAARGH!!!>"
  },
  AvgDialog_13735_Content_8 = {Text = "!!"},
  AvgDialog_13735_Content_80 = {
    Text = "Uvhash impulsionou-se com força e disparou para a frente como uma flecha lançada de um arco."
  },
  AvgDialog_13735_Content_81 = {
    Text = "Eu— você... seu fedorento@1, me ponha no chão!"
  },
  AvgDialog_13735_Content_82 = {
    Text = "Uvhash explodiu numa gargalhada estrondosa.\nO riso voou no vento, entrelaçando-se com grãos dourados de areia e poeira, correndo alegremente em direção à distância."
  },
  AvgDialog_13735_Content_83 = {
    Text = "Nem pensar— ainda preciso te manter vivo para me ajudar a recuperar minha liberdade!"
  },
  AvgDialog_13735_Content_9 = {
    Text = "Uvhash apareceu do canto sem aviso, sorrindo para você."
  },
  AvgDialog_13736_Content_1 = {
    Text = "O Guia, o Feiticeiro e o escravo"
  },
  AvgDialog_13736_Content_10 = {
    Text = "Amareladas, Seco, com linhas ásperas e Desinibido nas palmas — estas são as mãos de um guerreiro."
  },
  AvgDialog_13736_Content_100 = {
    Text = "Desculpe, não tenho nada a dizer a você."
  },
  AvgDialog_13736_Content_101 = {
    Text = "Mercenários são um bando de escória sem fé. Quanto a escravos, eles não poderiam sequer compreender o que dignidade e honra significam."
  },
  AvgDialog_13736_Content_102 = {
    Text = "Você e aquele sujeito — não há diferença real entre vocês dois."
  },
  AvgDialog_13736_Content_103 = {
    Text = "Mas já passei há muito da idade de agir por impulso."
  },
  AvgDialog_13736_Content_104 = {
    Text = "Primeiro, não consigo vencê-lo numa luta.\nSegundo, você ainda me é útil."
  },
  AvgDialog_13736_Content_105 = {
    Text = "Não me importa de onde veio. Agora, neste preciso momento, continue a guiar o caminho, meu caro Guia."
  },
  AvgDialog_13736_Content_11 = {
    Text = "<Gray:Jamila · @1, 32 anos, ex-mercenária Mameluca, agora guia no deserto...>"
  },
  AvgDialog_13736_Content_12 = {
    Text = "Você processa silenciosamente sua nova Identidade."
  },
  AvgDialog_13736_Content_13 = {
    Text = "Parece que entraste no Sonhar mais uma vez."
  },
  AvgDialog_13736_Content_14 = {
    Text = "Ei, o que estás a resmungar? Se estás acordado, levanta-te de uma vez. O meu <Blue:escravo> e eu temos assuntos urgentes a tratar."
  },
  AvgDialog_13736_Content_15 = {
    Text = "O homem baixo e atarracado, com trajes peculiares, é o teu cliente para este trabalho — <Blue:Ludwig · Prin>."
  },
  AvgDialog_13736_Content_16 = {
    Text = "Falou com impaciência, apontando descuidadamente o chicote para trás."
  },
  AvgDialog_13736_Content_17 = {Text = "Hss..."},
  AvgDialog_13736_Content_18 = {
    Text = "Uvhash—?!"
  },
  AvgDialog_13736_Content_19 = {
    Text = "Apenas então reparas no homem escondido atrás da duna de areia."
  },
  AvgDialog_13736_Content_2 = {
    Text = "@2, o Papa perdeu o poder e o Poder Real surgiu.\nA cidade sagrada de Acre tornou-se uma terra ferozmente disputada.\n\nTemendo as forças Mamelucas lideradas por Baibars,\no Príncipe convocou todos os povos a marcharem para o leste e reconquistarem a cidade sagrada de Acre."
  },
  AvgDialog_13736_Content_20 = {
    Text = "Mantém uma postura agachada, os braços longos pousados casualmente no chão, como uma Besta pronta a atacar."
  },
  AvgDialog_13736_Content_21 = {
    Text = "Ao ver a tua expressão chocada, abre um sorriso, revelando uma fileira de presas brancas e reluzentes."
  },
  AvgDialog_13736_Content_22 = {
    Text = "O quê, conheces-me?"
  },
  AvgDialog_13736_Content_24 = {
    Text = "Antes que pudesses responder, o longo chicote do feiticeiro açoitou Uvhash com força."
  },
  AvgDialog_13736_Content_25 = {
    Text = "Este aqui, amigo, aconselho-te a não falares com ele."
  },
  AvgDialog_13736_Content_26 = {
    Text = "Pode ter os mesmos olhos e nariz que nós, mas continua a ser uma Besta incivilizada, ou melhor..."
  },
  AvgDialog_13736_Content_28 = {
    Text = "Mais um estalo do chicote açoitou Uvhash com força."
  },
  AvgDialog_13736_Content_29 = {
    Text = "Ele é um <Red:demon>."
  },
  AvgDialog_13736_Content_3 = {
    Text = "E assim, a grande <Yellow:Cruzada> mais uma vez começou seu Prólogo..."
  },
  AvgDialog_13736_Content_30 = {
    Text = "Apesar de ser atingido chicotada após chicotada, Uvhash nem sequer pestanejou."
  },
  AvgDialog_13736_Content_31 = {
    Text = "Limpou o Sangue que escorria da têmpora, levou a palma ao nariz e cheirou, e depois começou calmamente a lamber o Sangue das pontas dos dedos."
  },
  AvgDialog_13736_Content_32 = {
    Text = "Viste aquilo? Até o cão que guarda a minha Porta tem mais humanidade do que ele! Mais baixo que uma Besta, hahahaha!"
  },
  AvgDialog_13736_Content_33 = {
    Text = "Ei... velho, as tuas chicotadas estão muito mais fracas hoje.\nO que se passa, já nem consegues segurar o chicote firme?"
  },
  AvgDialog_13736_Content_34 = {Text = "Hmph..."},
  AvgDialog_13736_Content_35 = {
    Text = "A razão pela qual bestas são bestas é porque nunca conseguem controlar suas bocas nem reconhecer seu lugar."
  },
  AvgDialog_13736_Content_36 = {
    Text = "Não importa, eu vou <BigItalic:te ensinar direitinho>—"
  },
  AvgDialog_13736_Content_37 = {
    Text = "Prin ficou tão furioso que seus bigodes se eriçaram, e então, como uma bola lançada, disparou rapidamente em direção a Uvhash."
  },
  AvgDialog_13736_Content_38 = {Text = "Espere."},
  AvgDialog_13736_Content_39 = {
    Text = "Você agarrou Prin pelo pulso e o puxou de volta."
  },
  AvgDialog_13736_Content_4 = {Text = "..."},
  AvgDialog_13736_Content_40 = {
    Text = "Me dê o chicote."
  },
  AvgDialog_13736_Content_41 = {
    Text = "Me solte! Deixe-me dar uma lição naquela besta..."
  },
  AvgDialog_13736_Content_42 = {
    Text = "Sr. Jamila, eu sou seu empregador agora. Não preciso explicar o que é um empregador, preciso?"
  },
  AvgDialog_13736_Content_43 = {
    Text = "Desculpe, mas eu sou o guia desta viagem.\nJá que sou o guia, vocês seguem minha liderança."
  },
  AvgDialog_13736_Content_44 = {
    Text = "Caso contrário, vou embora agora mesmo, e vocês encontrem o caminho até o <Blue:campo de batalha> sozinhos."
  },
  AvgDialog_13736_Content_45 = {
    Text = "<Shake:Ei, ei...! Vamos conversar, vamos conversar...>"
  },
  AvgDialog_13736_Content_46 = {
    Text = "Mais uma coisa."
  },
  AvgDialog_13736_Content_47 = {
    Text = "Você franze a testa e olha para Uvhash."
  },
  AvgDialog_13736_Content_48 = {
    Text = "Embora seus caminhos raramente se cruzassem no campus, você ouviu uma coisa ou outra sobre suas diversas façanhas."
  },
  AvgDialog_13736_Content_49 = {
    Text = "Ele definitivamente não é do tipo que se deixa controlar por outros."
  },
  AvgDialog_13736_Content_5 = {
    Text = "Você abre os olhos de um longo e profundo sono. Até onde a vista alcança, não há nada além de um vasto e ilimitado deserto."
  },
  AvgDialog_13736_Content_50 = {
    Text = "O que você fez com ele? Como ele poderia obedecer a você tão voluntariamente?"
  },
  AvgDialog_13736_Content_51 = {
    Text = "O quê, está questionando minhas habilidades como <Blue:Feiticeiro-Chefe do Levante>?"
  },
  AvgDialog_13736_Content_52 = {
    Text = "Esta é uma arte rara e perdida do nosso ofício, e também minha privacidade como empregador. Eu pediria ao guia que não metesse o nariz onde não é chamado..."
  },
  AvgDialog_13736_Content_53 = {
    Text = "Não vai falar, é?\nEntão vou arrancar isso de você na marra."
  },
  AvgDialog_13736_Content_54 = {
    Text = "Ei, espere... <Big:Ai!>"
  },
  AvgDialog_13736_Content_56 = {
    Text = "<Shake:Hss, isso dói... V-Você não é um guia comum!>"
  },
  AvgDialog_13736_Content_57 = {
    Text = "Fale, você é um espião enviado por <Blue:Remvashi> para me interceptar?"
  },
  AvgDialog_13736_Content_58 = {
    Text = "Você não respondeu às Dúvidas de Prin, porque toda a sua atenção já havia sido atraída para outra coisa—"
  },
  AvgDialog_13736_Content_59 = {
    Text = "Uma corrente fina cintilava fracamente à luz do sol, emanando um brilho incomum."
  },
  AvgDialog_13736_Content_6 = {
    Text = "Acordou? Ora, essa é boa. Nem demos dois passos e nosso guia desmaiou de insolação. Que tipo de absurdo é esse?"
  },
  AvgDialog_13736_Content_60 = {
    Text = "Ela se estendia do pulso de Prin até onde terminava no pescoço de Uvhash."
  },
  AvgDialog_13736_Content_61 = {
    Text = "<Gray:Essa técnica parece tão familiar... Sinto que alguém mencionou isso antes...>"
  },
  AvgDialog_13736_Content_62 = {
    Text = "Se não se comportam, basta colocar uma coleira. Simples assim."
  },
  AvgDialog_13736_Content_63 = {
    Text = "Isso é ilegal em Londinium, Senhorita Agrippa. Receio que precisaremos instruí-la sobre alguns conhecimentos jurídicos básicos..."
  },
  AvgDialog_13736_Content_64 = {
    Text = "Hehe, eu não sou idiota."
  },
  AvgDialog_13736_Content_65 = {
    Text = "Você sabe sobre @1?"
  },
  AvgDialog_13736_Content_66 = {
    Text = "É uma arte secreta ancestral que permite ao conjurador controlar outros com uma corrente invisível..."
  },
  AvgDialog_13736_Content_67 = {
    Text = "Quanto ao preço..."
  },
  AvgDialog_13736_Content_68 = {
    Text = "Qual era o preço mesmo? Droga, não consigo lembrar..."
  },
  AvgDialog_13736_Content_69 = {
    Text = "Você estava perdido em suas memórias quando alguém arrancou a máscara do seu rosto de repente."
  },
  AvgDialog_13736_Content_7 = {
    Text = "Ainda bem que eu Apenas venho a este lugar maldito uma vez na vida, @1!"
  },
  AvgDialog_13736_Content_70 = {
    Text = "Três rios curvos... Você é um <Blue:mercenário escravo de Mamluk>?!"
  },
  AvgDialog_13736_Content_71 = {
    Text = "No momento em que Prin terminou de falar, Uvhash, que parecia completamente desinteressado, de repente se virou para olhar para você."
  },
  AvgDialog_13736_Content_72 = {
    Text = "Interessante..."
  },
  AvgDialog_13736_Content_73 = {
    Text = "Não, espere— O povo de Mamluk deveria estar no campo de batalha agora..."
  },
  AvgDialog_13736_Content_74 = {
    Text = "Entendo. Você é um desertor."
  },
  AvgDialog_13736_Content_75 = {
    Text = "Você instintivamente tocou o próprio rosto."
  },
  AvgDialog_13736_Content_76 = {
    Text = "<Gray:Então tenho tatuagens no rosto...>"
  },
  AvgDialog_13736_Content_77 = {
    Text = "Claro, eu sou um desertor. Minha cidade natal é <Blue:Lemwashi>, mas não quero voltar..."
  },
  AvgDialog_13736_Content_78 = {
    Text = "Desertores também precisam comer, então agora ganho a vida como guia.\nNão se preocupe— minha maior virtude é ser meticuloso com meu trabalho."
  },
  AvgDialog_13736_Content_79 = {
    Text = "Garanto que posso levá-lo ao campo de batalha—"
  },
  AvgDialog_13736_Content_8 = {
    Text = "Guia? Onde... é aqui..."
  },
  AvgDialog_13736_Content_80 = {Text = "Pfft."},
  AvgDialog_13736_Content_81 = {
    Text = "Tendo visto o bastante da farsa diante dele, Uvhash se espreguiçou preguiçosamente e caminhou até você."
  },
  AvgDialog_13736_Content_82 = {
    Text = "Ele passou o braço pelo seu ombro, depois gentilmente virou seu queixo até que seu olhar estivesse direcionado ao mago silencioso diante de você."
  },
  AvgDialog_13736_Content_83 = {
    Text = "Já que somos todos escravos, ou pelo menos já fomos— aqui vai uma dica—"
  },
  AvgDialog_13736_Content_84 = {
    Text = "Se eu fosse você, calaria a boca agora mesmo.\nSabe que tipo de pessoa aquele ali mais odeia?"
  },
  AvgDialog_13736_Content_85 = {
    Text = "...Receber lição sobre vigiar minhas palavras logo desse cara— que sensação peculiar."
  },
  AvgDialog_13736_Content_86 = {Text = "...Diga."},
  AvgDialog_13736_Content_87 = {
    Text = "Terceiro— mercenários Mamulu."
  },
  AvgDialog_13736_Content_88 = {
    Text = [[
Segundo, os Lemwashianos.
Quanto ao primeiro...]]
  },
  AvgDialog_13736_Content_89 = {
    Text = "Uma dor aguda atravessa seu ombro — Uvhash dá um tapa forte nas suas costas enquanto ri escandalosamente."
  },
  AvgDialog_13736_Content_9 = {
    Text = "O sol escaldante assa você até sua cabeça girar. Você olha para as próprias mãos."
  },
  AvgDialog_13736_Content_90 = {
    Text = "<Big:Claro, são os mercenários Mamulu de Lemwash!>"
  },
  AvgDialog_13736_Content_91 = {
    Text = "<Gray:...Ótimo. Ninguém mais poderia estar rindo disso.>"
  },
  AvgDialog_13736_Content_92 = {
    Text = "<Gray:Esse cara realmente tem um talento de primeira para ofender as pessoas.>"
  },
  AvgDialog_13736_Content_93 = {Text = "Heh..."},
  AvgDialog_13736_Content_94 = {
    Text = "Naquela época, os mercenários Mamulu massacraram dezenas de milhares do meu povo. Minha esposa, meus camaradas, meu mentor... todos pereceram aqui."
  },
  AvgDialog_13736_Content_95 = {
    Text = "Bem, minha história trágica acabou. Podem voltar a rir agora."
  },
  AvgDialog_13736_Content_96 = {
    Text = "Peço desculpa, Sr. Prin. Permita-me explicar — embora eu tenha um... bem, passado menos que honroso."
  },
  AvgDialog_13736_Content_97 = {
    Text = "Mas isso tudo ficou no passado. Não tem nada a ver com quem eu sou agora."
  },
  AvgDialog_13736_Content_98 = {
    Text = "Prin acena a mão desdenhosamente na sua direção."
  },
  AvgDialog_13736_Content_99 = {
    Text = "O seu rosto redondo, tostado sob o sol escaldante, parece uma maçã demasiado madura — infelizmente, esta maçã não está muito contente agora."
  },
  AvgDialog_13737_Content_1 = {
    Text = "O Adeus Trágico"
  },
  AvgDialog_13737_Content_10 = {
    Text = "<RedShake:Correr...>"
  },
  AvgDialog_13737_Content_11 = {
    Text = "Uvhash esmagou sem esforço o crânio daquele que bloqueava seu Caminho, e então caminhou lentamente em direção a outro soldado."
  },
  AvgDialog_13737_Content_12 = {
    Text = "<RedShake:Sangue... Preciso de mais Sangue...>"
  },
  AvgDialog_13737_Content_13 = {
    Text = "Ele lentamente levantou a mão."
  },
  AvgDialog_13737_Content_15 = {Text = "..."},
  AvgDialog_13737_Content_16 = {
    Text = "É você..."
  },
  AvgDialog_13737_Content_17 = {
    Text = "É, sou eu."
  },
  AvgDialog_13737_Content_18 = {
    Text = "Você se coloca entre os dois, virando-se para olhar os Soldados atrás de você que caíram de joelhos de medo."
  },
  AvgDialog_13737_Content_19 = {
    Text = "Vão. Correr o mais longe que puderem."
  },
  AvgDialog_13737_Content_2 = {
    Text = "Borda do Deserto de Kusi, Campo de Batalha"
  },
  AvgDialog_13737_Content_20 = {
    Text = "<Big:Saiam daqui!!>"
  },
  AvgDialog_13737_Content_21 = {
    Text = "<Shake:T-tá... Já estou indo...>"
  },
  AvgDialog_13737_Content_22 = {
    Text = "Os Soldados saíram rastejando de quatro."
  },
  AvgDialog_13737_Content_23 = {
    Text = "Por que se coloca no meu Caminho? Eu estava apenas começando a saborear a alegria do Sangue e da batalha..."
  },
  AvgDialog_13737_Content_24 = {
    Text = "Você só quer uma luta, certo? Eu Disparar com você."
  },
  AvgDialog_13737_Content_25 = {
    Text = "Você? Hahahaha, o que você é—"
  },
  AvgDialog_13737_Content_27 = {
    Text = "Você pressiona sua lâmina curva contra a garganta de Uvhash, fitando calmamente seus olhos que há muito perderam o foco."
  },
  AvgDialog_13737_Content_28 = {
    Text = "Como saberia sem tentar?"
  },
  AvgDialog_13737_Content_3 = {
    Text = "Ei, você ouviu? Mais um enlouqueceu, matando todos à vista."
  },
  AvgDialog_13737_Content_4 = {
    Text = "Eles dizem que ele não é nem Leoriano nem Lemwashiano... ninguém sabe de onde ele veio."
  },
  AvgDialog_13737_Content_5 = {
    Text = "De qualquer forma, vamos sair daqui—"
  },
  AvgDialog_13737_Content_6 = {Text = "..."},
  AvgDialog_13737_Content_7 = {
    Text = "<Shake:Q-quando você apareceu...>"
  },
  AvgDialog_13737_Content_8 = {
    Text = "Ahhh! Acelere—"
  },
  AvgDialog_13737_Content_9 = {Text = "—!!"},
  AvgDialog_13738_Content_1 = {
    Text = "Bom, a tempestade de areia foi para o outro lado. Agora nós..."
  },
  AvgDialog_13738_Content_10 = {Text = "..."},
  AvgDialog_13738_Content_11 = {
    Text = "Você quer ir ao campo de batalha, não quer? Então naturalmente deve avançar na <Red:direção do Sangue>."
  },
  AvgDialog_13738_Content_12 = {
    Text = "A direção do Sangue...?"
  },
  AvgDialog_13738_Content_13 = {
    Text = "Você apontou para a figura de Uvhash se afastando enquanto ele caminhava a passos largos."
  },
  AvgDialog_13738_Content_14 = {
    Text = "A direção dele."
  },
  AvgDialog_13738_Content_2 = {Text = "BLEGH—!!"},
  AvgDialog_13738_Content_3 = {
    Text = "Prin apoiou-se contra um tronco de árvore seco, curvando-se enquanto começava a vomitar violentamente."
  },
  AvgDialog_13738_Content_4 = {
    Text = "Eu juro, uma vez que este acordo esteja concluído. Eu juro..."
  },
  AvgDialog_13738_Content_5 = {
    Text = "Desta vez, a fraca maldição do mago não recebeu resposta alguma."
  },
  AvgDialog_13738_Content_6 = {
    Text = "Tendo descoberto algo, as pupilas de Uvhash contraíram-se subitamente de forma quase imperceptível por um instante."
  },
  AvgDialog_13738_Content_7 = {
    Text = "<Red:...Sangue.>"
  },
  AvgDialog_13738_Content_8 = {
    Text = "Com isso, ele partiu sem olhar para trás."
  },
  AvgDialog_13738_Content_9 = {
    Text = "Espere...! Sem minha permissão, você não pode ir a lugar nenhum!"
  },
  AvgDialog_13739_Content_1 = {
    Text = "Abutres gritam sob o crepúsculo vermelho-sangue. O campo de batalha há muito foi abandonado."
  },
  AvgDialog_13739_Content_10 = {
    Text = "Durante a luta, você percebe claramente que o Estado de Uvhash está se deteriorando a uma velocidade alarmante."
  },
  AvgDialog_13739_Content_11 = {
    Text = "Seja ou não um efeito colateral do contrato, ele agora está no seu limite."
  },
  AvgDialog_13739_Content_12 = {
    Text = "Uma batalha só é divertida quando os oponentes estão em pé de igualdade. Por isso, não me importo de ficar um pouco mais fraco."
  },
  AvgDialog_13739_Content_13 = {
    Text = "Nunca me importei com o que os humanos pensam, assim como os humanos nunca se importam com formigas."
  },
  AvgDialog_13739_Content_14 = {
    Text = "Mas você é diferente. Há uma Força poderosa dentro de você, e você sabe como exercer o Contrataque."
  },
  AvgDialog_13739_Content_15 = {
    Text = "Continue assim, guerreira. Esses seus desejos entediantes — o sol, pequenos bolinhos, e coisas do tipo — talvez eles realmente possam se tornar realidade."
  },
  AvgDialog_13739_Content_16 = {
    Text = "<Gray:Foi Apenas algo que eu disse sem pensar, e mesmo assim ele ainda se lembrou...>"
  },
  AvgDialog_13739_Content_17 = {
    Text = "Vamos... para o lugar de que você falou, onde o sol brilha."
  },
  AvgDialog_13739_Content_18 = {Text = "?!"},
  AvgDialog_13739_Content_19 = {
    Text = "E quanto a você?"
  },
  AvgDialog_13739_Content_2 = {
    Text = "Você e Uvhash estão a menos de dez metros de distância, encarando-se em silêncio."
  },
  AvgDialog_13739_Content_20 = {
    Text = "Eu...? O velho tinha um último truque na manga. Não vou viver muito mais. Heh heh..."
  },
  AvgDialog_13739_Content_21 = {
    Text = "O velho e eu, ambos temos que morrer... esse é o verdadeiro preço de quebrar o pacto."
  },
  AvgDialog_13739_Content_22 = {
    Text = "Ele caminhou em sua direção com passos pesados, lentamente encurtando a distância."
  },
  AvgDialog_13739_Content_23 = {
    Text = "Então ele mordeu o próprio pulso com os dentes."
  },
  AvgDialog_13739_Content_24 = {
    Text = "Sangue Carmesim e pungente jorrou em torrentes, pingando no topo da sua cabeça, nas suas pálpebras, e então escorrendo pela ponte do seu nariz até seus lábios ressequidos."
  },
  AvgDialog_13739_Content_25 = {
    Text = "Este Sangue... considere-o meu Presente de despedida."
  },
  AvgDialog_13739_Content_26 = {
    Text = "Abutres circulavam acima de sua cabeça, claramente tendo escolhido sua presa moribunda."
  },
  AvgDialog_13739_Content_27 = {
    Text = "Nasci de inúmeras carnes e vaguei por este mundo por quase mil anos..."
  },
  AvgDialog_13739_Content_28 = {
    Text = "Ainda há folhas de Ouro Dançando pelo céu durante procissões triunfais, e palácios de Ouro a Queimar ferozmente em chamas."
  },
  AvgDialog_13739_Content_29 = {
    Text = "Já saboreei o mais requintado Sangue, e vivenciei as mais brutais batalhas."
  },
  AvgDialog_13739_Content_3 = {
    Text = "Ei... há quanto tempo estamos lutando?"
  },
  AvgDialog_13739_Content_30 = {
    Text = "Eu massacrei humanos, e também fui acorrentado e explorado por humanos, e no final, sem surpresa, encontrei a minha morte pelas mãos de humanos."
  },
  AvgDialog_13739_Content_31 = {
    Text = "Agora, é hora de eu partir..."
  },
  AvgDialog_13739_Content_32 = {
    Text = "Ele olhou para ti lá de cima, os olhos desprovidos de qualquer emoção."
  },
  AvgDialog_13739_Content_33 = {
    Text = "Sangue Pegajoso pingava da ponta do teu nariz até ao chão, gota a gota."
  },
  AvgDialog_13739_Content_34 = {
    Text = "Eras como um iniciado batismal desorientado, completamente perdido e desamparado perante tudo o que se desenrolava diante dos teus olhos."
  },
  AvgDialog_13739_Content_35 = {
    Text = "Devolvo toda a minha carne a você e a este mundo."
  },
  AvgDialog_13739_Content_36 = {
    Text = "Eles pertencem ao céu, à Terra... a ti, mas não a mim."
  },
  AvgDialog_13739_Content_37 = {
    Text = "Agora podes desaparecer... desaparecer e não olhes para trás."
  },
  AvgDialog_13739_Content_38 = {
    Text = "A tua visão é finalmente engolida pela vasta névoa de Sangue.\nFechas os olhos, sentindo onda após onda de tontura, Como se a Terra estivesse a afundar-se sem fim."
  },
  AvgDialog_13739_Content_39 = {
    Text = "Mal consegues lembrar-te do que aconteceu Depois."
  },
  AvgDialog_13739_Content_4 = {Text = "..."},
  AvgDialog_13739_Content_40 = {
    Text = "Talvez já tivesses partido, ou talvez tenhas morrido ao lado dele neste deserto."
  },
  AvgDialog_13739_Content_41 = {
    Text = "Nada disso importa. Porque vais lembrar-te para sempre daquele momento antes da morte dele."
  },
  AvgDialog_13739_Content_42 = {
    Text = "Naquele momento, um bando de Abutres negros passou a voar, bloqueando o brilho atrás dele."
  },
  AvgDialog_13739_Content_43 = {
    Text = "A luz continuava a desvanecer-se, as sombras rastejavam de todos os lados, e ele ajoelhou-se ali naquelas sombras, a olhar para ti."
  },
  AvgDialog_13739_Content_44 = {
    Text = "Ele disse—"
  },
  AvgDialog_13739_Content_45 = {
    Text = "Desaparece."
  },
  AvgDialog_13739_Content_46 = {
    Text = "Vai encontrar aquele lugar esquecido por Deus onde o sol brilha."
  },
  AvgDialog_13739_Content_5 = {
    Text = "Quem sabe... uma hora, um dia?"
  },
  AvgDialog_13739_Content_6 = {Text = "..."},
  AvgDialog_13739_Content_7 = {
    Text = "Mil anos... faz quase mil anos desde que desfrutei de uma batalha tão eletrizante."
  },
  AvgDialog_13739_Content_8 = {
    Text = "Você é um guerreiro nato."
  },
  AvgDialog_13739_Content_9 = {
    Text = "Que surpresa. Quando foi que aprendeu a bajular como um humano?"
  },
  AvgDialog_138765_Content_1 = {
    Text = "As brasas da dimensão estão em movimento. A roda do destino, Moirai, já gira aqui."
  },
  AvgDialog_138765_Content_2 = {
    Text = "Arrisque tudo, Guardião dos Segredos{Male=先生,Female=小姐}. Eu o auxiliarei a corrigir o destino equivocado e a destruir os casulos que não deveriam existir."
  },
  AvgDialog_138765_Content_3 = {
    Text = "O curso do destino jamais foi tecido por outros."
  },
  AvgDialog_138766_Content_1 = {
    Text = "Isso... acabou?"
  },
  AvgDialog_138766_Content_2 = {
    Text = "Cuidado, Guardião... o fuso que desfaz o destino já começou a girar atrás dela..."
  },
  AvgDialog_138766_Content_3 = {
    Text = "Heh... hahahaha...!"
  },
  AvgDialog_138766_Content_4 = {
    Text = "\"Olhem, fiéis cegos do Destino! O sino que sempre foi destinado a tocar por vocês finalmente soou!\""
  },
  AvgDialog_138766_Content_5 = {
    Text = "\"Eu sou o fim— eu sou o Destino— eu sou @4!\""
  },
  AvgDialog_138766_Content_6 = {
    Text = "\"Agora, eu lhes concedo o fim derradeiro. Eu lhes concedo a libertação que tão desesperadamente ansiaram!!\""
  },
  AvgDialog_13946_Content_1 = {
    Text = "Mar sem apoio"
  },
  AvgDialog_13946_Content_10 = {
    Text = "Eles mandaram você me \"escoltar\" para encontrar a bruxa?\nQue piada. As intenções deles não poderiam ser mais óbvias..."
  },
  AvgDialog_13946_Content_11 = {
    Text = "Goliath solta um gemido de dor. Sob ele, uma poça de Sangue vermelho-escuro se espalha lentamente, escorrendo até seus pés."
  },
  AvgDialog_13946_Content_12 = {
    Text = "<Red:Eles querem que nós dois morramos aqui neste mar.>"
  },
  AvgDialog_13946_Content_13 = {
    Text = "Meu senhor, você está gravemente ferido! O que aconteceu..."
  },
  AvgDialog_13946_Content_14 = {
    Text = "Memórias caóticas inundam sua mente."
  },
  AvgDialog_13946_Content_15 = {
    Text = "Na última batalha decisiva, o líder Goliath subestimou seu inimigo e perdeu para uma tribo rival."
  },
  AvgDialog_13946_Content_16 = {
    Text = "Os Filisteus não aceitariam a derrota. O gravemente ferido Goliath foi banido, acompanhado apenas por um pequeno barco desgastado, e você—"
  },
  AvgDialog_13946_Content_17 = {
    Text = "O mais fraco dos Filisteus, que poderia até perder uma luta para uma criança de dez anos."
  },
  AvgDialog_13946_Content_18 = {
    Text = "Lembro que o Líder <Blue:Com Glen> disse uma vez que há uma bruxa misteriosa nas águas próximas. Ela usa um tipo de lama negra..."
  },
  AvgDialog_13946_Content_19 = {
    Text = "Apenas a derramarmos sobre a ferida, seus ferimentos certamente vão sarar!"
  },
  AvgDialog_13946_Content_2 = {
    Text = "Suspire pela Apostola do Mar.\nSuspire pela nossa luz, nossa esperança.\n\nPelo Destino de ser Exilada ao oceano, nós gememos, nós lamentamos, nós choramos até não restarem mais lágrimas."
  },
  AvgDialog_13946_Content_20 = {
    Text = "Você instintivamente soltou a lenda da bruxa, apenas para perceber algo estranho nisso um momento depois."
  },
  AvgDialog_13946_Content_21 = {
    Text = "<Gray:Espera, será que aquela lama é Lama Corrosiva...>"
  },
  AvgDialog_13946_Content_22 = {
    Text = "Líder, Com Glen?"
  },
  AvgDialog_13946_Content_23 = {
    Text = "Um sorriso lentamente se espalhou pelo rosto frio de Goliath."
  },
  AvgDialog_13946_Content_24 = {
    Text = "Então ele já se tornou seu novo Líder. Que eficiência. Como esperado do meu querido povo da tribo."
  },
  AvgDialog_13946_Content_25 = {Text = "Splash!!"},
  AvgDialog_13946_Content_26 = {
    Text = "O pequeno barco apodrecido finalmente não suportou o Impacto das ondas e se abriu com um grande buraco, a água do mar entrando sem parar."
  },
  AvgDialog_13946_Content_27 = {
    Text = "Tsc, como eu esperava."
  },
  AvgDialog_13946_Content_28 = {
    Text = "Isso é ruim, vamos nos afogar! Precisamos encontrar algo para tapar o buraco, rápido..."
  },
  AvgDialog_13946_Content_29 = {Text = "...Oh."},
  AvgDialog_13946_Content_3 = {
    Text = "Oh, por favor, vele pelos aflitos!\nLance seu olhar misericordioso sobre nós e conceda-nos a fonte negra de Vida."
  },
  AvgDialog_13946_Content_30 = {
    Text = "Goliath se encostou no convés com pouco interesse, deixando o Sangue sob ele tingir de vermelho a água do mar que inundava."
  },
  AvgDialog_13946_Content_31 = {
    Text = "Liberar. Mesmo que consertemos o barco, eles têm dez mil maneiras de garantir que eu morra nestas águas."
  },
  AvgDialog_13946_Content_32 = {
    Text = "Meu conselho é parar de se preocupar comigo. Saia do barco e nade de volta por conta própria."
  },
  AvgDialog_13946_Content_33 = {
    Text = "Diga a eles que você já me matou. Se tiver sorte, talvez consiga manter sua vida."
  },
  AvgDialog_13946_Content_34 = {
    Text = "E quanto a você...?"
  },
  AvgDialog_13946_Content_35 = {Text = "Eu?"},
  AvgDialog_13946_Content_36 = {
    Text = "Goliath admirou tranquilamente a paisagem no mar, então virou a cabeça em sua direção com um leve sorriso."
  },
  AvgDialog_13946_Content_37 = {
    Text = "Sentado aqui apreciando a vista do oceano, e esperando a morte chegar enquanto isso."
  },
  AvgDialog_13946_Content_38 = {Text = "...?"},
  AvgDialog_13946_Content_39 = {
    Text = "<Gray:Tão pessimista. Este é mesmo o Goliath que eu conheço?>"
  },
  AvgDialog_13946_Content_4 = {
    Text = "<Red:Mercy, mercy, mercy...>"
  },
  AvgDialog_13946_Content_40 = {
    Text = "Ah, é verdade, há outra coisa sobre a qual eu deveria te avisar."
  },
  AvgDialog_13946_Content_41 = {
    Text = "Tem um buraco atrás do seu traseiro. Pela minha Experiência, este barco está prestes a se partir ao meio a qualquer momento. Você não tem muito tempo para pensar."
  },
  AvgDialog_13946_Content_42 = {Text = "Splash!!"},
  AvgDialog_13946_Content_43 = {
    Text = "Como se para provar que as palavras de Goliath eram verdade, uma onda massiva atingiu o barco, e a embarcação de madeira instantaneamente se partiu em duas."
  },
  AvgDialog_13946_Content_44 = {
    Text = "<Shake:Aaaaah—!!>"
  },
  AvgDialog_13946_Content_45 = {
    Text = "Água salgada do mar não parava de inundar seus pulmões. Você abriu a boca, apenas para convidar mais água do mar a te Devorar por completo."
  },
  AvgDialog_13946_Content_46 = {
    Text = "Seu corpo continuava afundando, respirar se tornava cada vez mais Dificuldade..."
  },
  AvgDialog_13946_Content_47 = {
    Text = "Enquanto sua consciência se turvava, você pareceu ouvir um suspiro desamparado."
  },
  AvgDialog_13946_Content_48 = {
    Text = "Antes que pudesse reagir, uma força poderosa agarrou seu Cabelo e te ergueu do mar sem esforço."
  },
  AvgDialog_13946_Content_49 = {
    Text = "*Cof cof*... Urgh!"
  },
  AvgDialog_13946_Content_5 = {Text = "..."},
  AvgDialog_13946_Content_50 = {
    Text = "Segure-se firme. Esta é a única tábua de salvação que nos resta."
  },
  AvgDialog_13946_Content_51 = {
    Text = "Você olhou ao redor, apenas para Descobrir que você e Goliath estavam ambos espremidos numa prancha de madeira Instável, prestes a se desfazer."
  },
  AvgDialog_13946_Content_52 = {
    Text = "Que diabos... Os Filisteus são supostamente mestres do mar, navegando os quatro oceanos. Como é que você nem sabe nadar?"
  },
  AvgDialog_13946_Content_53 = {
    Text = "Você é mesmo um Filisteu?"
  },
  AvgDialog_13946_Content_54 = {
    Text = "<SmallShake:Minhas desculpas. Este meu corpo foi acometido por Doença desde a infância...>"
  },
  AvgDialog_13946_Content_55 = {
    Text = "Obrigado, meu senhor. Se não fosse por você, eu teria morrido aqui..."
  },
  AvgDialog_13946_Content_56 = {
    Text = "...Parece que você não foi enviado por eles para me matar."
  },
  AvgDialog_13946_Content_57 = {
    Text = "O instinto de sobrevivência que você acabou de demonstrar foi intenso. Não parecia ser uma encenação."
  },
  AvgDialog_13946_Content_58 = {
    Text = "Goliath afastou o Cabelo molhado grudado em sua testa e contemplou o mar envolto em névoa diante dele."
  },
  AvgDialog_13946_Content_59 = {
    Text = "Quando caímos no mar, você se agarrou a mim como um caranguejo enorme, se recusando a me soltar nem por um segundo. Por quê?"
  },
  AvgDialog_13946_Content_6 = {Text = "Despertar?"},
  AvgDialog_13946_Content_60 = {
    Text = "Hã? Para sobreviver, é claro..."
  },
  AvgDialog_13946_Content_61 = {
    Text = "Para sobreviver... Mas você é inútil mesmo estando vivo. Você nem sabe nadar."
  },
  AvgDialog_13946_Content_62 = {
    Text = "Para que exatamente você está vivendo?"
  },
  AvgDialog_13946_Content_63 = {
    Text = "A voz de Goliath foi ficando cada vez mais fraca, como se estivesse perguntando a você, mas também a si mesmo."
  },
  AvgDialog_13946_Content_64 = {
    Text = "Exilado por seus semelhantes, carregando um Ferimento grave — o Caminho à sua frente era como o mar envolto em névoa diante dele, com Apenas uma incerteza interminável restando."
  },
  AvgDialog_13946_Content_65 = {Text = "..."},
  AvgDialog_13946_Content_66 = {
    Text = "Meu senhor, você vivia dizendo que esperaria pela morte, mas quando as ondas realmente nos atingiram, você não apenas encontrou esta tábua e subiu nela, como também me salvou."
  },
  AvgDialog_13946_Content_67 = {
    Text = "...Isso foi porque você ficou se agarrando a mim e não me soltava."
  },
  AvgDialog_13946_Content_68 = {
    Text = "Nada disso importa. O que importa é que por sua causa, meu senhor, nós dois estamos vivos agora."
  },
  AvgDialog_13946_Content_69 = {
    Text = "Por que você acha que é assim?"
  },
  AvgDialog_13946_Content_7 = {
    Text = "O mar agita ondas escaldadas pela luz do sol, e o vento marítimo levemente salgado carrega um fedor forte e salgado até suas narinas."
  },
  AvgDialog_13946_Content_70 = {
    Text = "Goliath balançou a cabeça."
  },
  AvgDialog_13946_Content_71 = {
    Text = "Sinceramente, eu também não sei. Mas Ainda há uma coisa que passei a entender..."
  },
  AvgDialog_13946_Content_72 = {
    Text = "Goliath abaixou a cabeça e olhou para você pensativamente."
  },
  AvgDialog_13946_Content_73 = {
    Text = "Agora eu entendo como alguém tão inútil quanto você conseguiu sobreviver por tanto tempo."
  },
  AvgDialog_13946_Content_8 = {
    Text = "<Gray:Isso é... Sonhar?>"
  },
  AvgDialog_13946_Content_9 = {
    Text = "Como esperado do mais notório fracote doentio do clã — uma única onda grande é suficiente para te deixar inconsciente por meio dia."
  },
  AvgDialog_13947_Content_1 = {
    Text = "Crônica dos Gigantes"
  },
  AvgDialog_13947_Content_10 = {
    Text = "Apenas tolos confiam suas vidas a outros."
  },
  AvgDialog_13947_Content_11 = {
    Text = "<Gray:A bruxa...>"
  },
  AvgDialog_13947_Content_12 = {
    Text = "De acordo com o arquivo do Despertador de Golias, essa chamada \"bruxa\" é indubitavelmente Miryam."
  },
  AvgDialog_13947_Content_13 = {
    Text = "Embora o Desenvolvimento subsequente tenha sido menos que ideal, Miryam de fato salvou a vida de Goliath."
  },
  AvgDialog_13947_Content_14 = {
    Text = "Meu senhor, você sofreu um Ferimento grave. Parece não haver outra opção agora. Por que não encontramos a bruxa juntos—"
  },
  AvgDialog_13947_Content_15 = {Text = "BANG!!"},
  AvgDialog_13947_Content_16 = {
    Text = "Com uma força tremenda, sua garganta Frágil foi agarrada em um aperto de ferro. Seus pés deixaram o chão enquanto você era erguido diante dos olhos do gigante."
  },
  AvgDialog_13947_Content_17 = {
    Text = "Apenas vou dizer isso uma vez: não me olhe com esses olhos, e não fale comigo nesse tom."
  },
  AvgDialog_13947_Content_18 = {
    Text = "O que eu, Goliath, menos preciso é de piedade dos fracos."
  },
  AvgDialog_13947_Content_19 = {
    Text = "O tom de Goliath era neutro, sua expressão inalterada, Como se ele estivesse Apenas conversando sobre o clima com você."
  },
  AvgDialog_13947_Content_2 = {
    Text = "A luz do sol abrasa a superfície do mar, como se quisesse consumir toda a vida no calor interminável."
  },
  AvgDialog_13947_Content_20 = {
    Text = "Mas você estava tão perto—perto o suficiente para ver claramente a vermelhidão ao redor de seus olhos, nascida da dor e da obstinação."
  },
  AvgDialog_13947_Content_21 = {
    Text = "Naquele momento, ele parecia despido de toda a glória de um soberano dos mares, reduzido a um peixe à deriva perdido no oceano sem fim, Apenas como você."
  },
  AvgDialog_13947_Content_22 = {
    Text = "Minhas desculpas... ugh, meu senhor..."
  },
  AvgDialog_13947_Content_23 = {
    Text = "<Shake:Wooo——>"
  },
  AvgDialog_13947_Content_24 = {
    Text = "O som grave de uma corneta veio à deriva da distância."
  },
  AvgDialog_13947_Content_25 = {
    Text = "A pressão em seu pescoço subitamente aliviou. Goliath soltou o aperto e olhou na direção da corneta."
  },
  AvgDialog_13947_Content_26 = {
    Text = "<Gray:Cof cof... Hah, salvo...>"
  },
  AvgDialog_13947_Content_27 = {
    Text = "Que interessante... Preocupados que eu não esteja morrendo rápido o bastante, então vieram em bando para me dar adeus?"
  },
  AvgDialog_13947_Content_28 = {
    Text = "Em pouco tempo, uma frota massiva havia cercado vocês, prendendo-os em seu centro. A tábua à deriva se tornou a única Ilha isolada nestas águas."
  },
  AvgDialog_13947_Content_29 = {
    Text = "Você já está Enredado em um cerco."
  },
  AvgDialog_13947_Content_3 = {
    Text = "A tábua à qual você e Goliath se agarravam havia se tornado a única Ilha isolada no mar. Erguendo o olhar para o sol ardente sobre suas cabeças, você sentiu onda após onda de tontura mais uma vez."
  },
  AvgDialog_13947_Content_30 = {
    Text = "Permitam-me apresentar grandiosamente — o mais valente Líder de toda a história Filisteia! O poderoso gigante que possui uma Vontade Imortal e Inabalável! O herói tribal cuja fama abala os quatro mares, cujo Desprezo total não conhece limites —"
  },
  AvgDialog_13947_Content_31 = {
    Text = "<BigShake:O grande Senhor Goliath!>"
  },
  AvgDialog_13947_Content_32 = {
    Text = "A luz do sol refletida no mar era intensa demais. Você Apenas conseguiu vislumbrar uma silhueta escura de pé na proa, olhando para você do alto."
  },
  AvgDialog_13947_Content_33 = {
    Text = "Nossos irmãos mais novos talvez não saibam, mas Este grande senhor sofreu um Ferimento grave em um duelo e quase foi capturado, levando toda a nossa tribo a uma crise sem precedentes!"
  },
  AvgDialog_13947_Content_34 = {
    Text = "A aniquilação iminente Devorou a maioria do nosso povo! Elogio a você! Meu mais amado Senhor Goliath!"
  },
  AvgDialog_13947_Content_35 = {
    Text = "Heh heh... Como eu ousaria tomar todo o crédito por tamanha conquista, Com Glen?"
  },
  AvgDialog_13947_Content_36 = {
    Text = "Quem foi que se escondeu atrás de mim e não ousou enviar tropas? E quem foi o primeiro a largar a arma e chorar e gritar enquanto corria para casa?"
  },
  AvgDialog_13947_Content_37 = {Text = "Você...!"},
  AvgDialog_13947_Content_38 = {
    Text = "O rosto de Com Glen ficou vermelho como um tomate, seus olhos turvos tremendo sem parar, até que finalmente seu olhar se fixou em você."
  },
  AvgDialog_13947_Content_39 = {
    Text = "Oh, mesmo tendo o Líder perdido quase todo o seu povo, ele ainda tem um... seguidor muito adorável."
  },
  AvgDialog_13947_Content_4 = {
    Text = "<Shake:Desculpe, não estou me sentindo bem... Deixe-me dormir um pouco...>"
  },
  AvgDialog_13947_Content_40 = {
    Text = "A desgraça dos Filisteus — um inútil que não aguenta sequer um soco da própria tribo, mas quer segui-lo e se tornar um guerreiro..."
  },
  AvgDialog_13947_Content_41 = {
    Text = "Hahahaha...!!"
  },
  AvgDialog_13947_Content_42 = {
    Text = "Goliath ergueu a cabeça e olhou para você com surpresa em meio às gargalhadas estrondosas da multidão."
  },
  AvgDialog_13947_Content_43 = {
    Text = "Pirralho, você veio me seguir por vontade própria?"
  },
  AvgDialog_13947_Content_44 = {
    Text = "<Gray:Uh... pelo que consigo lembrar, parece que sim...>"
  },
  AvgDialog_13947_Content_45 = {
    Text = "Que comovente, não é? Eu Apenas mencionei casualmente uma coisa ou duas sobre a bruxa, e esse pequeno tolo levou a sério, vindo ansiosamente atrás para segui-lo..."
  },
  AvgDialog_13947_Content_46 = {
    Text = "Não consegui impedir o garoto de jeito nenhum, haha —"
  },
  AvgDialog_13947_Content_47 = {Text = "Splash!!"},
  AvgDialog_13947_Content_48 = {
    Text = "As risadas cessaram abruptamente. Um vento feroz e implacável Sibilou, e uma perna decepada rolou instantaneamente e parou diante dos olhos de Todos."
  },
  AvgDialog_13947_Content_49 = {
    Text = "AHHH... Minha perna, MINHA PERNA!!"
  },
  AvgDialog_13947_Content_5 = {
    Text = "Uma túnica fedendo a suor e Sangue foi jogada sobre sua cabeça, e o fedor fez você se levantar imediatamente."
  },
  AvgDialog_13947_Content_50 = {
    Text = "O antigo senhor dos mares erguia-se diante Com Glen como uma montanha, todo o seu ser emanando uma aura que incutia terror no coração."
  },
  AvgDialog_13947_Content_51 = {
    Text = "Desde há pouco, uma mosca tem estado a zumbir à volta do meu ouvido sem parar..."
  },
  AvgDialog_13947_Content_52 = {
    Text = "Goliath limpou calmamente as manchas de Sangue da sua lâmina, depois ergueu a cabeça e lançou a Com Glen um sorriso frio."
  },
  AvgDialog_13947_Content_53 = {
    Text = "Com Glen, eu por acaso te fiz alguma maldita pergunta agora?"
  },
  AvgDialog_13947_Content_6 = {
    Text = "*Cof cof*... Urgh!"
  },
  AvgDialog_13947_Content_7 = {
    Text = "Você está com insolação. Cubra sua cabeça com isso para bloquear o sol. Não tire."
  },
  AvgDialog_13947_Content_8 = {
    Text = "Como esperado das roupas usadas pelo meu senhor, verdadeiramente revigorante...\nEntão, para onde devemos ir agora? Encontrar a bruxa?"
  },
  AvgDialog_13947_Content_9 = {
    Text = "Que bruxa que nada? Não me diga que você realmente acreditou naquelas baboseiras."
  },
  AvgDialog_13948_Content_1 = {
    Text = "Melodia Dourada"
  },
  AvgDialog_13948_Content_10 = {
    Text = "A calma pálida do mar se despedaçou quando serpentes marinhas negro-púrpura irromperam subitamente, enrolando-se firmemente ao redor de Todos em um aperto apertado."
  },
  AvgDialog_13948_Content_11 = {
    Text = "Ugh... AAAAAHH!!"
  },
  AvgDialog_13948_Content_12 = {
    Text = "Com um som fraco e sinistro, os corpos das serpentes se transformaram em Lâminas afiadas negras como azeviche que perfuraram suas vítimas de lado a lado."
  },
  AvgDialog_13948_Content_13 = {
    Text = "<Big:Saiam daqui>... Hã?"
  },
  AvgDialog_13948_Content_15 = {
    Text = "Uma sensação suave e gélida veio de onde a serpente negra estava Enrolada ao redor do seu pescoço, e a ferida começou a cicatrizar gradualmente."
  },
  AvgDialog_13948_Content_16 = {
    Text = "Minhas feridas... todas cicatrizaram?"
  },
  AvgDialog_13948_Content_17 = {
    Text = "As serpentes negras deixaram você sem hesitar, e então se enrolaram firmemente Com Glen a uma velocidade cegante."
  },
  AvgDialog_13948_Content_18 = {
    Text = "Correr, a bruxa está vin... do..."
  },
  AvgDialog_13948_Content_19 = {
    Text = "Serpentes negras como breu rastejaram para fora dos olhos e da boca Com Glen. Ele desabou sem forças antes mesmo de conseguir pronunciar uma única frase completa."
  },
  AvgDialog_13948_Content_2 = {
    Text = "Suspire pela Apostola do Mar.\nSuspire pela nossa luz, nossa esperança.\n\nPelo Destino de ser Exilada ao oceano, nós gememos, nós lamentamos, nós choramos até não restarem mais lágrimas."
  },
  AvgDialog_13948_Content_20 = {
    Text = "Momentos depois, incontáveis cadáveres mutilados flutuaram até a superfície do mar."
  },
  AvgDialog_13948_Content_21 = {
    Text = "Foi um massacre silencioso."
  },
  AvgDialog_13948_Content_22 = {
    Text = "<Gray:Acabou, assim, sem mais? Impressionante—como esperado de Miryam.>"
  },
  AvgDialog_13948_Content_23 = {
    Text = "Você nos ajudou... Quem é você?"
  },
  AvgDialog_13948_Content_24 = {
    Text = "A mulher usando um véu negro nada disse. Ela permaneceu elegantemente na proa de seu navio, com Apenas um véu de névoa espessa entre vocês."
  },
  AvgDialog_13948_Content_25 = {
    Text = "Ela parecia tão perto, mas a mundos de distância."
  },
  AvgDialog_13948_Content_26 = {
    Text = "A mulher fitou o atônito Goliath, um leve sorriso curvando o canto de seus lábios. Ela estendeu a mão, apontando para a distância—um convite silencioso."
  },
  AvgDialog_13948_Content_27 = {
    Text = "Então ela virou seu navio e se afastou tranquilamente."
  },
  AvgDialog_13948_Content_28 = {
    Text = "Espere, não vá... <Big:Não vá!>"
  },
  AvgDialog_13948_Content_29 = {
    Text = "A névoa se dissipou, e um feixe de luz atravessou as nuvens. As ondas cintilavam com um tom dourado."
  },
  AvgDialog_13948_Content_3 = {
    Text = "O Campo de visão escureceu de repente enquanto a luz solar ofuscante gradualmente se desvanecia, e uma névoa Pegajosa envolveu todo o mar."
  },
  AvgDialog_13948_Content_30 = {
    Text = "Você piscou, e o horizonte já estava vazio."
  },
  AvgDialog_13948_Content_31 = {
    Text = "O vento e as ondas gradualmente se acalmaram. Você e Goliath se agarraram à única tábua intacta, ofegando por ar."
  },
  AvgDialog_13948_Content_32 = {
    Text = "O outrora azul mar há muito estava tingido de vermelho com Sangue. Vocês flutuavam sobre ele como lentilhas-d'água sem raízes."
  },
  AvgDialog_13948_Content_33 = {
    Text = "Então ainda não conseguimos um navio... Agora eu nem sei como vamos voltar para casa."
  },
  AvgDialog_13948_Content_34 = {
    Text = "Nós não vamos voltar para casa."
  },
  AvgDialog_13948_Content_35 = {
    Text = "Goliath apoiou uma perna e ficou olhando distraidamente na direção em que Miryam havia partido."
  },
  AvgDialog_13948_Content_36 = {
    Text = "Eu já me decidi. Vou encontrar aquela bruxa. Você vem comigo?"
  },
  AvgDialog_13948_Content_37 = {
    Text = "Ahem, \"Apenas um tolo confiaria sua vida a outra pessoa.\""
  },
  AvgDialog_13948_Content_38 = {
    Text = "Você deliberadamente abaixou a voz, imitando o tom anterior de Goliath enquanto repetia as próprias palavras dele de volta para ele."
  },
  AvgDialog_13948_Content_39 = {
    Text = "Hmph, isso é porque a Aposta não era alta o suficiente. Aquele tipo de Força que pode esmagar tudo em um instante — eu nunca vi nada parecido."
  },
  AvgDialog_13948_Content_4 = {
    Text = "Oh, por favor, protejam os aflitos.\nLancem sobre nós o vosso olhar misericordioso..."
  },
  AvgDialog_13948_Content_40 = {
    Text = "Além disso, Ela acabou de nos ajudar, e até me fez um convite..."
  },
  AvgDialog_13948_Content_41 = {
    Text = "Mas e se... for uma armadilha?"
  },
  AvgDialog_13948_Content_42 = {
    Text = "Uma armadilha..."
  },
  AvgDialog_13948_Content_43 = {
    Text = "Você ainda se lembra da pergunta que me fez antes?"
  },
  AvgDialog_13948_Content_44 = {
    Text = "...O que importa é que, graças a você, meu senhor, nós dois ainda estamos vivos."
  },
  AvgDialog_13948_Content_45 = {
    Text = "Por que você acha que é assim?"
  },
  AvgDialog_13948_Content_46 = {
    Text = "Agora eu sei a resposta."
  },
  AvgDialog_13948_Content_47 = {
    Text = "Qual é a resposta?"
  },
  AvgDialog_13948_Content_48 = {
    Text = "Um bando de petréis subitamente voou junto. Suas Asas brancas batendo eram como nuvens planando, espalhando-se livremente no vento do mar."
  },
  AvgDialog_13948_Content_49 = {
    Text = "Goliath não se perturbou com o bando de pássaros. Ele olhou fixamente para frente, seus olhos parpadeando com a luz da Empolgação."
  },
  AvgDialog_13948_Content_5 = {
    Text = "Uma canção antiga, carregada de Deceit, flutuava pelo ar. A silhueta da mulher na proa aparecia e desaparecia, como um espectro vagando pela névoa."
  },
  AvgDialog_13948_Content_50 = {
    Text = "Porque eu sou Golias."
  },
  AvgDialog_13948_Content_51 = {
    Text = "O Líder de reinado mais longo da história Filisteia, o poderoso gigante de Vontade Imortal e Inabalável, o herói tribal cujo nome inspira reverência pelos quatro mares — o Gigante Goliath."
  },
  AvgDialog_13948_Content_52 = {
    Text = "Mesmo com Apenas um Seguidor restante, Apenas haja uma última chance, eu posso me erguer novamente."
  },
  AvgDialog_13948_Content_53 = {
    Text = "Aquela bruxa é minha última chance. Apenas Ela pode me conceder Força absoluta."
  },
  AvgDialog_13948_Content_54 = {
    Text = "Mesmo que seja uma armadilha, eu vou."
  },
  AvgDialog_13948_Content_55 = {
    Text = "Então por que você me salvou? Um \"desperdício\" como eu provavelmente não pode te ajudar em nada..."
  },
  AvgDialog_13948_Content_56 = {
    Text = "Você enfatizou deliberadamente uma certa palavra, fazendo Goliath cair numa gargalhada sincera."
  },
  AvgDialog_13948_Content_57 = {
    Text = "A luz do sol rompeu as nuvens, lançando um manto de luz dourada. Fios de cabelo em Desordem Dançavam suavemente sob o céu azul."
  },
  AvgDialog_13948_Content_58 = {
    Text = "Não há como um comandante sem tropas realizar qualquer coisa neste mundo."
  },
  AvgDialog_13948_Content_59 = {
    Text = "Pequenino, você não é um desperdício.\nVocê é o Único Seguidor da Gigante Goliath, e ninguém jamais poderá substituí-lo."
  },
  AvgDialog_13948_Content_6 = {
    Text = "Hã? Alguém está cantando?"
  },
  AvgDialog_13948_Content_60 = {
    Text = "Quando eu alcançar minhas grandes ambições, no mínimo vou fazer de você um chefe tribal!"
  },
  AvgDialog_13948_Content_61 = {
    Text = "...Isso não será necessário."
  },
  AvgDialog_13948_Content_62 = {
    Text = "O céu havia escurecido antes que alguém percebesse. O brilho vespertino ao entardecer fluía pelo horizonte como rios Dourados e brilhantes."
  },
  AvgDialog_13948_Content_63 = {
    Text = "Ei, sabe de uma coisa? A razão pela qual heróis conseguem se tornar heróis é porque eles têm pessoas como nós para fazê-los parecer incríveis."
  },
  AvgDialog_13948_Content_64 = {
    Text = "<Small:Então eu também sou bem importante, entende...>"
  },
  AvgDialog_13948_Content_65 = {
    Text = "<Small:Mm...>"
  },
  AvgDialog_13948_Content_66 = {
    Text = "Palavras fragmentadas se espalharam como sementes de dente-de-leão sopradas pela brisa do mar, levadas para algum lugar muito, muito distante."
  },
  AvgDialog_13948_Content_67 = {
    Text = "Você e Goliath sentaram nas finas tábuas de madeira, e de longe, pareciam pequenas folhas à deriva num mar dourado."
  },
  AvgDialog_13948_Content_68 = {
    Text = "Ninguém sabia para onde vocês acabariam navegando."
  },
  AvgDialog_13948_Content_7 = {
    Text = "<Shake:A bruxa— é aquela bruxa!!>"
  },
  AvgDialog_13948_Content_8 = {
    Text = "Como pode ser... Será que aquela lenda é realmente verdade..."
  },
  AvgDialog_13948_Content_9 = {
    Text = [[
<Red:Piedade.
         Piedade.
                  Piedade...>]]
  },
  AvgDialog_139656_Content_1 = {Text = "Adeus"},
  AvgDialog_139656_Content_10 = {
    Text = "Como estou agora...? Hmm. Provavelmente é melhor que não veja."
  },
  AvgDialog_139656_Content_11 = {
    Text = "Depois da conexão de agora... muitas coisas mudaram."
  },
  AvgDialog_139656_Content_12 = {
    Text = "Sobre isso... eu tive um sonho."
  },
  AvgDialog_139656_Content_13 = {
    Text = "No sonho, Ramona tinha se tornado..."
  },
  AvgDialog_139656_Content_14 = {
    Text = "Não importa quantas vezes você tenha repassado isso na mente, a imagem ainda resiste a palavras. Seu corpo recua antes que seus pensamentos consigam acompanhar."
  },
  AvgDialog_139656_Content_15 = {
    Text = "Eu sei. Você ficou apavorado(a). Repugnado(a)."
  },
  AvgDialog_139656_Content_16 = {
    Text = "O Domínio faz parte da minha Paisagem Mental—então eu pude sentir."
  },
  AvgDialog_139656_Content_17 = {
    Text = "Sinto muito de verdade, pelo que fiz você passar."
  },
  AvgDialog_139656_Content_18 = {
    Text = "Não—não era isso que eu queria dizer."
  },
  AvgDialog_139656_Content_19 = {
    Text = "Quero dizer... naquela hora, eu não sabia se aquela coisa envolta em carne era realmente ela."
  },
  AvgDialog_139656_Content_2 = {
    Text = "O mundo voltou ao \"normal\". Normal pelos padrões do seu mundo."
  },
  AvgDialog_139656_Content_20 = {
    Text = "Mas agora eu sei. Aquela era a Ramona que eu conheço. Então, não tenho mais medo."
  },
  AvgDialog_139656_Content_21 = {
    Text = "As palavras lhe dão firmeza. Sua voz gradualmente se torna mais segura."
  },
  AvgDialog_139656_Content_22 = {
    Text = "A aparência não importa. O que importa é apenas a conexão entre mim e meus Corpos Despertos—aquelas que passam pelos Núcleos de Prata."
  },
  AvgDialog_139656_Content_23 = {
    Text = "Já vi coisas demais para ser abalado(a) apenas por aparências."
  },
  AvgDialog_139656_Content_24 = {
    Text = "Já vi um coração de ouro puro nascer do mais repugnante lodaçal do mundo;"
  },
  AvgDialog_139656_Content_25 = {
    Text = "Já vi o amor—verdadeiro, terno amor—criar raízes no mais febril desejo de procriação. Então—"
  },
  AvgDialog_139656_Content_26 = {
    Text = "Tudo cai em silêncio."
  },
  AvgDialog_139656_Content_27 = {
    Text = "Após uma longa pausa, um sorriso se propaga pelo outro lado da conexão—calmo e sereno."
  },
  AvgDialog_139656_Content_28 = {
    Text = "...Estou tão feliz por ter te conhecido."
  },
  AvgDialog_139656_Content_29 = {
    Text = "…E então, no Domínio abalado, você caiu novamente naquele Sonho."
  },
  AvgDialog_139656_Content_3 = {
    Text = "Areia amarela sufocada em lodo de dissolução se estende em uma vastidão interminável e uivante."
  },
  AvgDialog_139656_Content_30 = {
    Text = "Bem｢-vi｢ndo a｢o ｢Uni｢ver｢si｢da｢de Mi｢sa｢ge, %player%."
  },
  AvgDialog_139656_Content_31 = {
    Text = "O som viscoso e gutural rasteja para fora de uma massa de carne putrefata e contorcida."
  },
  AvgDialog_139656_Content_32 = {
    Text = "Em um mundo coberto de sangue e lodo, Ramona—encharcada de fluido—estende a mão. Seus dedos mal roçam seu mindinho."
  },
  AvgDialog_139656_Content_33 = {
    Text = "Eu nunca vou esquecer este momento."
  },
  AvgDialog_139656_Content_34 = {
    Text = "Você sussurra suavemente em seu coração."
  },
  AvgDialog_139656_Content_35 = {
    Text = "Que｢ a ｢cha｢ve ｢de ｢pra｢ta ｢gui｢e ｢o ｢ca｢mi｢nho."
  },
  AvgDialog_139656_Content_36 = {
    Text = "Em meio à carne e à desolação, você segura firmemente a mão de Ramona, encarando diretamente seus olhos vazios e sua forma manchada de sangue."
  },
  AvgDialog_139656_Content_37 = {
    Text = "Que a Chave de Prata nos guie"
  },
  AvgDialog_139656_Content_38 = {
    Text = "A radiância da Chave de prata se difunde por todo o mundo."
  },
  AvgDialog_139656_Content_39 = {
    Text = "Uma figura de branco puro surge em sua mente. É Saya, sorrindo."
  },
  AvgDialog_139656_Content_4 = {
    Text = "Apenas a pequena cabana na floresta está encharcada na cor crua e carnosa de entranhas. E através do vínculo, você sente Saya lá dentro. Você sabe que o fim dela está a meros batimentos de distância."
  },
  AvgDialog_139656_Content_40 = {
    Text = "Algo como belas asas tremula ao vento."
  },
  AvgDialog_139656_Content_41 = {
    Text = "Dentes-de-leão alçam voo, espalhando-se pelo céu azul."
  },
  AvgDialog_139656_Content_42 = {
    Text = "No momento em que cada semente se desprende do caule, o mundo nebuloso e onírico recua para a realidade."
  },
  AvgDialog_139656_Content_43 = {
    Text = "Você desperta do sonho, e todas as coisas revelam suas verdadeiras formas."
  },
  AvgDialog_139656_Content_44 = {
    Text = "Obrigado..."
  },
  AvgDialog_139656_Content_45 = {
    Text = "Você parece ouvir um sussurro de despedida ao seu ouvido. Será uma ilusão?"
  },
  AvgDialog_139656_Content_46 = {
    Text = "Em algum momento, um Núcleo de prata aparece em sua palma."
  },
  AvgDialog_139656_Content_47 = {
    Text = "É o mesmo núcleo que Tinct uma vez encontrou, aquele imbuído de um anseio eterno."
  },
  AvgDialog_139656_Content_48 = {
    Text = "Quando chegar o momento, você poderá usá-lo—para despertar o \"amor\" eterno dela."
  },
  AvgDialog_139656_Content_49 = {
    Text = "—O amor de Saya... o Corpo Desperto."
  },
  AvgDialog_139656_Content_5 = {
    Text = "Acredito que nossas almas estão conectadas agora. E com isso... a barreira desaparecerá completamente."
  },
  AvgDialog_139656_Content_50 = {Text = "Fim."},
  AvgDialog_139656_Content_6 = {
    Text = "Poder me sentir assim em meus momentos finais... Estou satisfeita. ...Obrigada."
  },
  AvgDialog_139656_Content_7 = {
    Text = "Agora—deixe este lugar. Caminhe pela areia. Na borda desse mar de dunas, você se reunirá com o seu passado."
  },
  AvgDialog_139656_Content_8 = {
    Text = "Está tudo bem. Mesmo quando eu partir deste mundo, a nossa consciência permanecerá conectada através dos Núcleos de Prata."
  },
  AvgDialog_139656_Content_9 = {
    Text = "Antes do fim—você me deixaria ver a sua verdadeira forma?"
  },
  AvgDialog_139657_Content_1 = {
    Text = "\"Propósito\""
  },
  AvgDialog_139657_Content_10 = {
    Text = "Algo está a chegar. Consigo senti-lo nos limites..."
  },
  AvgDialog_139657_Content_11 = {
    Text = "Saya franze o sobrolho, o rosto tenso e pálido."
  },
  AvgDialog_139657_Content_12 = {
    Text = "Arrancas a carne do pulso dela e ajuda-la a levantar-se."
  },
  AvgDialog_139657_Content_13 = {
    Text = "Quero ver o campo de dentes-de-leão. Caminhas comigo um pouco?"
  },
  AvgDialog_139657_Content_14 = {
    Text = "Devias estar a descansar..."
  },
  AvgDialog_139657_Content_15 = {
    Text = "Está tudo bem. A sério..."
  },
  AvgDialog_139657_Content_16 = {
    Text = "Saya empurra suavemente a porta da cabana. O mundo lá fora inunda a tua visão."
  },
  AvgDialog_139657_Content_17 = {
    Text = "A cor do campo mudou."
  },
  AvgDialog_139657_Content_18 = {
    Text = "O verde exuberante de ontem está agora revestido por uma sombra profunda de vermelho-negro. As escassas folhas não conseguem resistir, deformadas e consumidas pela decomposição."
  },
  AvgDialog_139657_Content_19 = {
    Text = "É <Red:Dissolução>...!"
  },
  AvgDialog_139657_Content_2 = {
    Text = "Sonhos grotescos vêm até ti como uma maré."
  },
  AvgDialog_139657_Content_20 = {
    Text = "Pareces... triste?"
  },
  AvgDialog_139657_Content_21 = {
    Text = "Ontem isto era um belo campo de dentes-de-leão."
  },
  AvgDialog_139657_Content_22 = {
    Text = "Hoje a Dissolução encontrou-o, engoliu-o por inteiro. Em poucos dias, terá desaparecido por completo."
  },
  AvgDialog_139657_Content_23 = {
    Text = "E com tempo suficiente, até a memória dele se desvanecerá—até da tua."
  },
  AvgDialog_139657_Content_24 = {
    Text = "Isso não te entristece?"
  },
  AvgDialog_139657_Content_25 = {
    Text = "Hmm, é assim que te sentes...?"
  },
  AvgDialog_139657_Content_26 = {
    Text = "Tu vês as coisas de forma diferente?"
  },
  AvgDialog_139657_Content_27 = {
    Text = "Mm. Há sempre tantas coisas diferentes neste mundo..."
  },
  AvgDialog_139657_Content_28 = {
    Text = "E os mais fortes tomam e saqueiam dos mais fracos."
  },
  AvgDialog_139657_Content_29 = {
    Text = "É assim que funciona, não é?"
  },
  AvgDialog_139657_Content_3 = {
    Text = "A figura de Ramona cintila, aparecendo e desaparecendo—a voz dela desfeita pelas costuras, rouca como ar forçado através de um fole partido."
  },
  AvgDialog_139657_Content_30 = {
    Text = "Não. É exatamente por isso que o Misaq existe."
  },
  AvgDialog_139657_Content_31 = {
    Text = "Nós nos colocamos entre a Dissolução e tudo o que ela engoliria—vidas e memórias que podem não ser poderosas, mas ainda carregam sua própria luz."
  },
  AvgDialog_139657_Content_32 = {
    Text = "E isso inclui você, Saya."
  },
  AvgDialog_139657_Content_33 = {
    Text = "...É mesmo."
  },
  AvgDialog_139657_Content_34 = {
    Text = "Ela murmura para si mesma."
  },
  AvgDialog_139657_Content_35 = {
    Text = "Nesse caso... talvez você tenha razão..."
  },
  AvgDialog_139657_Content_36 = {
    Text = "Você caminha pela paisagem repetitiva pelo que parece ser uma eternidade, até que um vislumbre de algo diferente finalmente quebra a monotonia."
  },
  AvgDialog_139657_Content_37 = {
    Text = "Outro canteiro de dentes-de-leão...?"
  },
  AvgDialog_139657_Content_38 = {
    Text = "Saya está com a cabeça baixa, respirando suavemente. Você não consegue ver o rosto dela."
  },
  AvgDialog_139657_Content_39 = {
    Text = "Esta é... a cabana de onde partimos. Olhe ali."
  },
  AvgDialog_139657_Content_4 = {
    Text = "Acordas sobressaltado."
  },
  AvgDialog_139657_Content_40 = {
    Text = "Você aponta para o canto do cômodo—o pedaço de carne que você arrancou do pulso de Saya e jogou de lado esta manhã."
  },
  AvgDialog_139657_Content_41 = {
    Text = "...Estivemos andando em círculos."
  },
  AvgDialog_139657_Content_42 = {
    Text = "Não há nada neste Domínio além de desolação."
  },
  AvgDialog_139657_Content_43 = {
    Text = "Até que é bom. Podemos... descansar um pouco."
  },
  AvgDialog_139657_Content_44 = {
    Text = "Ela sorri como se não fosse nada. Mas sua voz se desfaz nas bordas, tremendo levemente, de um jeito que ela não consegue conter."
  },
  AvgDialog_139657_Content_45 = {
    Text = "Saya, seu corpo..."
  },
  AvgDialog_139657_Content_46 = {
    Text = "Estou só um pouco cansada..."
  },
  AvgDialog_139657_Content_47 = {
    Text = "Bem diante dos seus olhos, os joelhos dela cedem—ela desaba no chão, como se tudo que a sustentava simplesmente tivesse falhado."
  },
  AvgDialog_139657_Content_48 = {Text = "Saya!"},
  AvgDialog_139657_Content_49 = {
    Text = "No meio da noite, Saya arde em febre. Seguindo as instruções dela, você acende uma fogueira com materiais que não saberia nomear nem se tentasse."
  },
  AvgDialog_139657_Content_5 = {
    Text = "*Tosse, tosse...*"
  },
  AvgDialog_139657_Content_50 = {
    Text = "Se eu soubesse que você estava tão doente, jamais teria deixado você caminhar o dia inteiro..."
  },
  AvgDialog_139657_Content_51 = {
    Text = "Está tudo bem. Não acho que estou doente por causa da caminhada.\nEnfim—podemos conversar um pouco?"
  },
  AvgDialog_139657_Content_52 = {
    Text = "Claro. Sobre o que você gostaria de conversar?"
  },
  AvgDialog_139657_Content_53 = {
    Text = "Hoje de manhã, você disse que você e Misaq querem lutar contra a Dissolução. Para proteger outras pessoas. Para me proteger."
  },
  AvgDialog_139657_Content_54 = {
    Text = "Você realmente quis dizer aquilo?"
  },
  AvgDialog_139657_Content_55 = {
    Text = "Cada palavra. Jurei isso no dia em que me foi concedida a Chave de prata."
  },
  AvgDialog_139657_Content_56 = {
    Text = "Sua voz sai mais firme do que você esperava. No instante em que as palavras deixam seus lábios, a cerimônia ressurge em sua mente—"
  },
  AvgDialog_139657_Content_57 = {
    Text = "O peso frio da Chave de prata se acomoda em sua palma. Os olhares solenes da multidão. A determinação ardente em seu coração quando você fechou os dedos ao redor dela."
  },
  AvgDialog_139657_Content_58 = {
    Text = "Saya fica em silêncio por um momento. A luz da fogueira dourava a pequena curva de sua silhueta com um brilho quente e âmbar."
  },
  AvgDialog_139657_Content_59 = {
    Text = "Então—se um dia você perder seu poder como Guardião... se você se tornar uma pessoa comum,"
  },
  AvgDialog_139657_Content_6 = {
    Text = "Saya está encostada à porta da cabine, tossindo suavemente."
  },
  AvgDialog_139657_Content_60 = {
    Text = "e não pudesse mais carregar o dever contra a Dissolução... o que você faria?"
  },
  AvgDialog_139657_Content_61 = {
    Text = "Bem, eu já pensei sobre isso."
  },
  AvgDialog_139657_Content_62 = {
    Text = "Você se reclina, apoiando as mãos na grama atrás de você, erguendo o rosto em direção às estrelas."
  },
  AvgDialog_139657_Content_63 = {
    Text = "Eu passaria o resto da minha vida com as pessoas que amo. Em paz. De forma comum."
  },
  AvgDialog_139657_Content_64 = {
    Text = "Quando estivermos velhos e grisalhos, cansados demais para correr, sentaríamos ao redor da lareira recontando as mesmas peripécias bobas da juventude até que todos as soubessem de cor."
  },
  AvgDialog_139657_Content_65 = {
    Text = "Ramona ainda estaria corrigindo cada nome que Lorde Dexter pronunciava errado. William teria aquele mesmo olhar perfeitamente composto no rosto, segurando um livro como se estivesse lendo enquanto suas orelhas ficavam atentas..."
  },
  AvgDialog_139657_Content_66 = {
    Text = "A Professora Czort ainda estaria agarrada à sua vodca, arrastando todo mundo para cantar no momento em que entrasse no ritmo."
  },
  AvgDialog_139657_Content_67 = {
    Text = "Você vira a cabeça. Saya está observando você em silêncio. A luz do fogo cintila em seus olhos como pequenas estrelas capturadas."
  },
  AvgDialog_139657_Content_68 = {
    Text = "Isso parece maravilhoso."
  },
  AvgDialog_139657_Content_69 = {Text = "Mas..."},
  AvgDialog_139657_Content_7 = {
    Text = "Saya! A tua mão!"
  },
  AvgDialog_139657_Content_70 = {
    Text = "A voz dela falha. Ela desvia o olhar, seus olhos se turvando, fixos no vazio de um canto escuro."
  },
  AvgDialog_139657_Content_71 = {
    Text = "Se você fosse separado deles—se não houvesse mais ninguém ao seu lado—o que você faria então?"
  },
  AvgDialog_139657_Content_72 = {
    Text = "Eles partiram? Ou nunca existiram para começo de conversa?"
  },
  AvgDialog_139657_Content_73 = {
    Text = "Se... você ainda tivesse as memórias. De tê-los encontrado, do tempo passado juntos..."
  },
  AvgDialog_139657_Content_74 = {
    Text = "Mas tempo demais se passou. As memórias estão em pedaços. E você nem sabe se são reais..."
  },
  AvgDialog_139657_Content_75 = {
    Text = "Enquanto eu ainda puder me lembrar, irei procurá-los."
  },
  AvgDialog_139657_Content_76 = {
    Text = "Onde quer que estejam. Custe o que custar."
  },
  AvgDialog_139657_Content_77 = {
    Text = "Não há sequer um lampejo de hesitação no seu olhar."
  },
  AvgDialog_139657_Content_78 = {
    Text = "Se... quer dizer, se você não conseguir encontrá-los?"
  },
  AvgDialog_139657_Content_79 = {
    Text = "Eu continuaria procurando da mesma forma—por cada estrada, sobre cada montanha, através de cada mar..."
  },
  AvgDialog_139657_Content_8 = {
    Text = "Carne entrelaçada com lodo negro infiltrou-se pelas frestas da porta e enrolou-se à volta do seu pulso."
  },
  AvgDialog_139657_Content_80 = {
    Text = "Até que a própria busca me conduzisse até o último dos meus dias."
  },
  AvgDialog_139657_Content_81 = {
    Text = "E quando esse último momento chegasse, quando meus olhos finalmente se fechassem, creio que me sentiria completo."
  },
  AvgDialog_139657_Content_82 = {
    Text = "Pois teria vivido com memórias que valiam a pena guardar, e um destino que eu estava fadado a alcançar, não importasse o custo."
  },
  AvgDialog_139657_Content_83 = {
    Text = "A própria busca é o significado."
  },
  AvgDialog_139657_Content_84 = {
    Text = "O silêncio cai enquanto suas palavras se assentam. Resta apenas o suave farfalhar dos dentes-de-leão na brisa."
  },
  AvgDialog_139657_Content_85 = {Text = "...Saya?"},
  AvgDialog_139657_Content_86 = {
    Text = "Saya fechou os olhos. Seu rosto está pálido, quase translúcido. Seu coração se aperta."
  },
  AvgDialog_139657_Content_87 = {Text = "Saya..."},
  AvgDialog_139657_Content_88 = {
    Text = "Você se inclina—e percebe que a respiração dela é lenta e uniforme, o peito subindo e descendo num ritmo quase imperceptível, como a mais ínfima ondulação num lago sereno."
  },
  AvgDialog_139657_Content_89 = {
    Text = "Hmm, você só está dormindo..."
  },
  AvgDialog_139657_Content_9 = {
    Text = "Mudanças como estas... não são o que me preocupa."
  },
  AvgDialog_139657_Content_90 = {
    Text = "Eu estou... um pouco cansado também..."
  },
  AvgDialog_139657_Content_91 = {
    Text = "O alívio chega de uma vez só, e com ele, a exaustão do dia e o desgaste visual da paisagem infernal finalmente vencem você."
  },
  AvgDialog_139657_Content_92 = {
    Text = "Antes que o fim chegue, esta noite também escapa silenciosamente por entre seus dedos."
  },
  AvgDialog_139658_Content_1 = {
    Text = "Depois da Chuva"
  },
  AvgDialog_139658_Content_10 = {
    Text = "Que bom... sentir o sol."
  },
  AvgDialog_139658_Content_11 = {
    Text = "Ela sorri, estendendo a mão na direção onde a luz cai, como uma planta se inclinando para a luz do sol."
  },
  AvgDialog_139658_Content_12 = {
    Text = "Você me ajuda a ir lá fora?"
  },
  AvgDialog_139658_Content_13 = {
    Text = "Você a guia para sentar-se encostada na parede da cabana. Mesmo esse curto trajeto a deixa com a respiração rasa e ofegante."
  },
  AvgDialog_139658_Content_14 = {
    Text = "Saya, seu corpo..."
  },
  AvgDialog_139658_Content_15 = {
    Text = "Não se preocupe com isso. Acho que meu tempo está quase no fim."
  },
  AvgDialog_139658_Content_16 = {
    Text = "Você também consegue sentir, não é? A barreira que bloqueia nosso vínculo... está desmoronando."
  },
  AvgDialog_139658_Content_17 = {
    Text = "Não vai demorar muito até que colapse por completo.\nQuando isso acontecer... devemos conseguir estabelecer a ligação de que você falou."
  },
  AvgDialog_139658_Content_18 = {Text = "Mas..."},
  AvgDialog_139658_Content_19 = {
    Text = "Uma vez que a ligação se forme, Saya pode desaparecer. Aquela barreira é o último escudo dela—e só está ficando mais fina porque suas forças estão se esgotando."
  },
  AvgDialog_139658_Content_2 = {
    Text = "Quando você acorda, a luz mudou."
  },
  AvgDialog_139658_Content_20 = {
    Text = "Por favor, não se contenha. Ter você aqui comigo, poder conversar assim... estou verdadeiramente feliz."
  },
  AvgDialog_139658_Content_21 = {
    Text = "Ela semicerra os olhos contra a luz, oferecendo um sorriso genuíno, porém frágil. Você mal consegue se forçar a olhar, mas se obriga a gravar cada detalhe na memória."
  },
  AvgDialog_139658_Content_22 = {
    Text = "Vou ficar com você. Até o fim."
  },
  AvgDialog_139658_Content_23 = {
    Text = "Vamos, não fique com essa cara pesada. Vamos continuar de onde paramos ontem."
  },
  AvgDialog_139658_Content_24 = {
    Text = "Você disse que mesmo sem seu poder, mesmo sem ninguém ao seu lado, continuaria em frente."
  },
  AvgDialog_139658_Content_25 = {
    Text = "Quero saber por quê."
  },
  AvgDialog_139658_Content_26 = {
    Text = "Por quê? A luz do sol após a chuva é forte o bastante para fazer seus olhos arderem com lágrimas contidas."
  },
  AvgDialog_139658_Content_27 = {
    Text = "Você inspira lenta e firmemente."
  },
  AvgDialog_139658_Content_28 = {
    Text = "Porque eu amo Ramona. Amo todos na Universidade de Misag.\nE sei—com certeza—que eles também me amam."
  },
  AvgDialog_139658_Content_29 = {
    Text = "Mas vocês estão tão distantes. Não podem se tocar. Não podem confirmar o que o outro sente."
  },
  AvgDialog_139658_Content_3 = {
    Text = "O ar úmido carrega um aroma puro, lavado. O que atravessa as frestas da porta já não é o vento, mas um feixe silencioso de luz."
  },
  AvgDialog_139658_Content_30 = {
    Text = "E num mundo com algo como a Dissolução—como você pode ter certeza de que as pessoas de quem sente falta já não se esqueceram de você?"
  },
  AvgDialog_139658_Content_31 = {
    Text = "A voz dela é suave, quase como um sonho murmurado à beira do sono."
  },
  AvgDialog_139658_Content_32 = {
    Text = "A Dissolução pode apagar a presença—mas os Núcleos de Prata unem Ramona e eu através do mar do subconsciente."
  },
  AvgDialog_139658_Content_33 = {
    Text = "Você olha para a distância. O horizonte após a chuva é incrivelmente nítido. O vento abre uma brecha entre as nuvens, e um pilar de luz dourada se derrama, atingindo a crista distante."
  },
  AvgDialog_139658_Content_34 = {
    Text = "Consigo sentir a presença dela. Mesmo agora, mesmo espalhados por mundos diferentes—isso não mudou."
  },
  AvgDialog_139658_Content_35 = {
    Text = "Além disso..."
  },
  AvgDialog_139658_Content_36 = {Text = "Sim?"},
  AvgDialog_139658_Content_37 = {
    Text = "Ela inclina levemente a cabeça."
  },
  AvgDialog_139658_Content_38 = {
    Text = "Amantes verdadeiros não precisam estar lado a lado para sentir seu vínculo... ou para confirmar seu amor."
  },
  AvgDialog_139658_Content_39 = {
    Text = "Não importa quantas vezes o mundo acabe e recomece, eu sempre encontrarei Ramona. E ela fará a mesma escolha."
  },
  AvgDialog_139658_Content_4 = {
    Text = "...Está tão silencioso lá fora."
  },
  AvgDialog_139658_Content_40 = {
    Text = "Eu simplesmente sei. Os pensamentos e sentimentos que compartilhamos no mar da consciência... jamais serão rompidos."
  },
  AvgDialog_139658_Content_41 = {
    Text = "Saya permanece em silêncio por um longo tempo. O vento lavado pela chuva atravessa a cabine, roçando sua bochecha exangue."
  },
  AvgDialog_139658_Content_42 = {
    Text = "Então ela sorri."
  },
  AvgDialog_139658_Content_43 = {
    Text = "Uma confiança tão feroz, tão inabalável... Um amor tão grandioso..."
  },
  AvgDialog_139658_Content_44 = {
    Text = "Quando ela pronuncia a palavra — amor — não há inveja em sua voz. Nem tristeza. Nem vestígio de anseio."
  },
  AvgDialog_139658_Content_45 = {
    Text = "Apenas uma ternura profunda."
  },
  AvgDialog_139658_Content_46 = {
    Text = "Como uma viajante que caminhou sozinha por uma longa noite de inverno e finalmente vislumbra a primeira luz da aurora na borda distante do horizonte — talvez nunca a alcance. Mas apenas saber que a luz existe já é o bastante."
  },
  AvgDialog_139658_Content_47 = {
    Text = "Saya sorri, perdida em um transe."
  },
  AvgDialog_139658_Content_48 = {
    Text = "Então ela estende a mão em sua direção."
  },
  AvgDialog_139658_Content_49 = {
    Text = "...Segure minha mão."
  },
  AvgDialog_139658_Content_5 = {
    Text = "A chuva... parou?"
  },
  AvgDialog_139658_Content_50 = {
    Text = "Sua mão é pálida, delgada e treme levemente. Ela não pode vê–lo, mas sua mão se estende infalivelmente em sua direção—"
  },
  AvgDialog_139658_Content_51 = {
    Text = "como se guiada por algo mais antigo que a visão, mais profundo que a linguagem."
  },
  AvgDialog_139658_Content_52 = {
    Text = "Você estende a mão e segura a dela."
  },
  AvgDialog_139658_Content_53 = {
    Text = "E no instante em que suas palmas se encontram—"
  },
  AvgDialog_139658_Content_54 = {
    Text = "Uma dor aguda explode atrás dos seus olhos."
  },
  AvgDialog_139658_Content_55 = {
    Text = "Algo muito mais intenso do que isso — abrasador, incandescente — se crava como um raio através do seu crânio, atingindo diretamente o núcleo mais profundo da sua mente."
  },
  AvgDialog_139658_Content_56 = {
    Text = "Sua visão oscila violentamente."
  },
  AvgDialog_139658_Content_57 = {
    Text = "Você vê dentes–de–leão úmidos reluzindo à luz do sol. O perfil pálido e tranquilo de Saya. O sorriso curvando seus lábios rachados—"
  },
  AvgDialog_139658_Content_58 = {
    Text = "E então tudo se rompe em um universo de carne. O céu se torna vermelho–sangue. A terra se torna vermelho–sangue. Até mesmo a Saya bem diante de você—"
  },
  AvgDialog_139658_Content_59 = {Text = "Não—"},
  AvgDialog_139658_Content_6 = {
    Text = "Saya olha na direção da janela, o olhar turvo e desfocado."
  },
  AvgDialog_139658_Content_60 = {
    Text = "Dois mundos piscam, sobrepõem-se e fundem-se diante dos seus olhos. Dois rios que nunca deveriam ter-se encontrado colidem violentamente numa junção impossível."
  },
  AvgDialog_139658_Content_61 = {
    Text = "A ligação entre você e Saya está completa."
  },
  AvgDialog_139658_Content_7 = {
    Text = "A luz do sol cai em seus olhos como uma pedra cai em água parada—e não levanta ondulação alguma."
  },
  AvgDialog_139658_Content_8 = {Text = "Parou."},
  AvgDialog_139658_Content_9 = {
    Text = "As palavras saem ásperas."
  },
  AvgDialog_139659_Content_1 = {Text = "\"Amor\""},
  AvgDialog_139659_Content_10 = {
    Text = "Saya está no campo de dentes–de–leão, banhada pela luz da manhã."
  },
  AvgDialog_139659_Content_11 = {
    Text = "A chuva soltou incontáveis sementes de seus caules. Elas caíram sobre a terra negro–carmesim — e algumas, de forma impossível, já começaram a brotar."
  },
  AvgDialog_139659_Content_12 = {
    Text = "Nascidas em uma noite, crescidas em uma noite..."
  },
  AvgDialog_139659_Content_13 = {
    Text = "Pela sua expressão... algo lhe veio à mente?"
  },
  AvgDialog_139659_Content_14 = {
    Text = "Sim. Uma vez vi uma cena parecida nos desertos de Aran."
  },
  AvgDialog_139659_Content_15 = {
    Text = "A terra de lá é abençoada pela Árvore Mãe. Os descendentes de sua linhagem criam raízes onde quer que caiam, crescendo com o vento."
  },
  AvgDialog_139659_Content_16 = {
    Text = "Isso parece bonito, não é?"
  },
  AvgDialog_139659_Content_17 = {
    Text = "...Mas pelo jeito que você disse, não parece achar isso."
  },
  AvgDialog_139659_Content_18 = {
    Text = "Não me cabe julgar. Sou uma pessoa de fora nessa história."
  },
  AvgDialog_139659_Content_19 = {
    Text = "É só que... acho que para a maioria das pessoas, cada fase da vida importa."
  },
  AvgDialog_139659_Content_2 = {
    Text = "Você e Saya se encolhem cada um em seu canto da cabana. A noite passa em silêncio."
  },
  AvgDialog_139659_Content_20 = {
    Text = "Nefru-Re, por exemplo. Ele nunca teve uma infância de verdade. Nunca soube o que era ser cuidado por um pai ou uma mãe. Ele foi lançado na guerra contra a Parede de tempestade antes que qualquer coisa disso pudesse acontecer..."
  },
  AvgDialog_139659_Content_21 = {
    Text = "Saya assente, sem ter muita certeza de que compreende."
  },
  AvgDialog_139659_Content_22 = {
    Text = "Então, para os humanos, a duração de uma vida também importa?"
  },
  AvgDialog_139659_Content_23 = {
    Text = "Mais do que isso. Cada experiência, cada pessoa que você encontra — todas se tornam parte das memórias que você carrega consigo."
  },
  AvgDialog_139659_Content_24 = {
    Text = "Essas memórias, acumuladas ao longo do tempo, são o que fazem de uma pessoa quem ela é."
  },
  AvgDialog_139659_Content_25 = {
    Text = "Pode-se até dizer que os humanos são recipientes de memória.\nMesmo depois que o corpo se vai, a memória continua — passada adiante, até que a última pessoa que a guarda esqueça."
  },
  AvgDialog_139659_Content_26 = {
    Text = "Entendo... Acho que compreendo."
  },
  AvgDialog_139659_Content_27 = {
    Text = "Então — se eu morrer um dia, a memória de hoje, de estar aqui assim com você, vai se tornar parte de quem você é?"
  },
  AvgDialog_139659_Content_28 = {Text = "Sim."},
  AvgDialog_139659_Content_29 = {
    Text = "À sombra do sorriso frágil de Saya, você assente com firmeza."
  },
  AvgDialog_139659_Content_3 = {
    Text = "Em algum momento, a exaustão arrasta você para um sono profundo."
  },
  AvgDialog_139659_Content_30 = {
    Text = "O dia passa entre exploração e caminhadas ao longo da fronteira."
  },
  AvgDialog_139659_Content_31 = {
    Text = "Além do campo de dentes-de-leão, a mesma paisagem desolada se repete em todas as direções. A terra está soterrada sob carne, irreconhecível sob camadas de vermelho e preto."
  },
  AvgDialog_139659_Content_32 = {
    Text = "Um mal-estar se instala no seu peito, infiltrando-se nos seus pensamentos. Você o reprime à força."
  },
  AvgDialog_139659_Content_33 = {
    Text = "(Se não há nada aqui fora, então o núcleo deste Domínio só pode estar...)"
  },
  AvgDialog_139659_Content_34 = {
    Text = "A noite cai novamente."
  },
  AvgDialog_139659_Content_35 = {
    Text = "Descanse um pouco. Estou me sentindo um pouco cansada."
  },
  AvgDialog_139659_Content_36 = {
    Text = "Ótimo. Gostaria de dormir cedo — quanto mais longe pudermos explorar amanhã, melhor."
  },
  AvgDialog_139659_Content_37 = {
    Text = "Com isso, vocês dois adormecem."
  },
  AvgDialog_139659_Content_38 = {Text = "..."},
  AvgDialog_139659_Content_39 = {
    Text = "Algo te acorda. Um som—ou um calor. Um calor que se infiltra sob a pele—como se estivesses de volta no deserto."
  },
  AvgDialog_139659_Content_4 = {
    Text = "(Tão frio... Espero que amanhã eu possa dormir numa cama de verdade...)"
  },
  AvgDialog_139659_Content_40 = {Text = "?!!"},
  AvgDialog_139659_Content_41 = {
    Text = "A tua cabeça está a andar à roda. Não consegues distinguir se é a cena sinistra à tua frente, ou a névoa que paira no ar."
  },
  AvgDialog_139659_Content_42 = {
    Text = "Ou a influência do Rio Sagrado."
  },
  AvgDialog_139659_Content_43 = {
    Text = "Que pena. Não era eu quem você estava ansioso para ver?"
  },
  AvgDialog_139659_Content_44 = {
    Text = "Rainha de Aran—Táias levantou a cortina e entrou. Ela se aproximou sem hesitação, o fino véu grudando em seu antebraço, emitindo um convite direto."
  },
  AvgDialog_139659_Content_45 = {
    Text = "Venha, aceite a linhagem de Arlan e torne-se um de nós."
  },
  AvgDialog_139659_Content_46 = {
    Text = "Aproxime-se, abrace-me... Dê-me seu sangue, sua essência..."
  },
  AvgDialog_139659_Content_47 = {
    Text = "As chamas piscam em suas fervorosas pupilas, suas bochechas rubras revelando um desejo mórbido."
  },
  AvgDialog_139659_Content_48 = {
    Text = "Apenas uma gota é suficiente. Assim que nossa carne óssea se fundir, Ele nos concederá o futuro que desejamos..."
  },
  AvgDialog_139659_Content_49 = {
    Text = "Vamos... gerar descendentes para a tribo, compartilhando por toda a eternidade..."
  },
  AvgDialog_139659_Content_5 = {
    Text = "Algo se deposita sobre você na escuridão."
  },
  AvgDialog_139659_Content_50 = {
    Text = "Arrancas a tua razão de algum lugar profundo, lutando contra a atração das palavras dela. O sino que te despertou pela primeira vez como Guardião permanece em silêncio."
  },
  AvgDialog_139659_Content_51 = {
    Text = "E então—uma voz diferente irrompe."
  },
  AvgDialog_139659_Content_52 = {
    Text = "Porquê? Porque é que continuas a recusar?"
  },
  AvgDialog_139659_Content_53 = {
    Text = "Ela apareceu de um canto da tenda sem fazer qualquer som."
  },
  AvgDialog_139659_Content_54 = {
    Text = "A voz dela é diferente do habitual. Algo mais pesado persiste sob as suas palavras, algo que não consegues nomear."
  },
  AvgDialog_139659_Content_55 = {
    Text = "Reprodução... Acho que é uma coisa boa. O propósito de todos os seres vivos..."
  },
  AvgDialog_139659_Content_56 = {
    Text = "Mas porque é que não aceitas?"
  },
  AvgDialog_139659_Content_57 = {
    Text = "Porquê? Porque é que continuas a recusar?"
  },
  AvgDialog_139659_Content_58 = {
    Text = "Porque isto não tem nada a ver com amor. Isto é apenas tentação."
  },
  AvgDialog_139659_Content_59 = {
    Text = "Tentação não é amor. Dever não é amor. Desejo não é amor."
  },
  AvgDialog_139659_Content_6 = {Text = "...Hmm?"},
  AvgDialog_139659_Content_60 = {
    Text = "Amor é —"
  },
  AvgDialog_139659_Content_61 = {
    Text = "Amor é —"
  },
  AvgDialog_139659_Content_62 = {
    Text = "O mundo apaga-se."
  },
  AvgDialog_139659_Content_63 = {
    Text = "Tudo mergulha numa escuridão longa e sem luz."
  },
  AvgDialog_139659_Content_7 = {
    Text = "Um cobertor fino foi colocado sobre você."
  },
  AvgDialog_139659_Content_8 = {
    Text = "O céu clareou."
  },
  AvgDialog_139659_Content_9 = {
    Text = "Hora de sair."
  },
  AvgDialog_139660_Content_1 = {
    Text = "\"Memórias\""
  },
  AvgDialog_139660_Content_10 = {
    Text = "E você está certa, não sou exatamente comum. Sou um investigador da Universidade de Misag."
  },
  AvgDialog_139660_Content_11 = {
    Text = "Há um olhar confuso no rosto de Saya—claramente esses termos não significam nada para ela."
  },
  AvgDialog_139660_Content_12 = {
    Text = "É uma longa história. Agora, tenho algo mais urgente para resolver."
  },
  AvgDialog_139660_Content_13 = {
    Text = "Minha parceira, Ramona. Eu vi algo consumi-la. Ela se tornou—"
  },
  AvgDialog_139660_Content_14 = {
    Text = "Você não termina. Não consegue."
  },
  AvgDialog_139660_Content_15 = {
    Text = "Palavras são apenas símbolos vazios. Não conseguem carregar o que você sentiu naquele momento—o medo que rastejou desde a base da sua espinha."
  },
  AvgDialog_139660_Content_16 = {
    Text = "O medo de perder Ramona para sempre."
  },
  AvgDialog_139660_Content_17 = {
    Text = "Ela é insubstituível para mim."
  },
  AvgDialog_139660_Content_18 = {
    Text = "O olhar de Saya fica desfocado por um momento."
  },
  AvgDialog_139660_Content_19 = {
    Text = "Insubstituível... Entendo."
  },
  AvgDialog_139660_Content_2 = {
    Text = "Antes de conseguir organizar qualquer uma das suas perguntas, ela fala primeiro."
  },
  AvgDialog_139660_Content_20 = {
    Text = "Acho que eu também tive... alguém assim."
  },
  AvgDialog_139660_Content_21 = {
    Text = "Ela olha para baixo, com a testa franzida, murmurando para si mesma."
  },
  AvgDialog_139660_Content_22 = {
    Text = "Havia alguém. Uma pessoa muito importante. Eu devia lembrar o rosto dele... Eu preciso lembrar. Mas quando tento imaginá-lo agora, tudo o que consigo ver é—"
  },
  AvgDialog_139660_Content_23 = {
    Text = "—apenas um contorno. Como olhar através de um vidro fosco. Eu sei que ele estava lá. Eu sei que ele era importante. Mas todos os detalhes foram... apagados."
  },
  AvgDialog_139660_Content_24 = {
    Text = "Não é só ele. Todo o resto é igual. Eu sei que há algo que preciso fazer—algo importante."
  },
  AvgDialog_139660_Content_25 = {
    Text = "Mas as memórias continuam lutando entre si. Uma diz que ele era gentil; a seguinte diz que fiquei em algum lugar muito escuro por muito tempo. Uma diz que eu estava esperando alguém vir me buscar; outra diz que eu tinha que fazer algo... que assustaria as pessoas."
  },
  AvgDialog_139660_Content_26 = {
    Text = "Cada fragmento parece real. Mas eles simplesmente não se encaixam."
  },
  AvgDialog_139660_Content_27 = {
    Text = "Cada pedaço parece real. Mas simplesmente não se encaixam."
  },
  AvgDialog_139660_Content_28 = {
    Text = "Você já viu essa condição antes."
  },
  AvgDialog_139660_Content_29 = {
    Text = "Não sei quais partes realmente aconteceram. Não sei quais memórias são realmente minhas..."
  },
  AvgDialog_139660_Content_3 = {
    Text = "Eu sou... hmm, pode me chamar de Saya.\nVocê sabe onde estamos?"
  },
  AvgDialog_139660_Content_30 = {
    Text = "Eu não sei quais partes realmente aconteceram. Eu não sei quais memórias são realmente minhas..."
  },
  AvgDialog_139660_Content_31 = {
    Text = "Os dedos de Saya se curvam para dentro, como se tentassem agarrar algo que já não existe."
  },
  AvgDialog_139660_Content_32 = {
    Text = "Enquanto ela vacila, o mundo ao seu redor começa a mudar."
  },
  AvgDialog_139660_Content_33 = {Text = "Cuidado!"},
  AvgDialog_139660_Content_34 = {
    Text = "Você olha para a borda do campo de dentes-de-leão. A membrana de carne, encharcada de lodo negro, está avançando para dentro centímetro a centímetro. O limite parece menos definido do que antes."
  },
  AvgDialog_139660_Content_4 = {
    Text = "Por que estou num lugar como este...\nHmm—há tanta coisa que não consigo lembrar."
  },
  AvgDialog_139660_Content_5 = {
    Text = "...Você não é uma pessoa comum, é?\nVocê tem algum tipo de habilidade especial...?"
  },
  AvgDialog_139660_Content_6 = {
    Text = "Você não responde de imediato. A menina chamada Saya solta sua mão, dá meio passo para trás, seus olhos se estreitando enquanto te avalia."
  },
  AvgDialog_139660_Content_7 = {
    Text = "Você me viu e não sentiu nada? Por que veio aqui?"
  },
  AvgDialog_139660_Content_8 = {
    Text = "Espere, uma pergunta de cada vez."
  },
  AvgDialog_139660_Content_9 = {
    Text = "Pelo que posso perceber, isto é muito provavelmente um Domínio."
  },
  AvgDialog_139661_Content_1 = {
    Text = "Paisagem Mental"
  },
  AvgDialog_139661_Content_10 = {
    Text = "Uma bela garota e um jovem rapaz."
  },
  AvgDialog_139661_Content_11 = {
    Text = "De mãos dadas, caminham juntos através da vastidão uivante."
  },
  AvgDialog_139661_Content_12 = {Text = "..."},
  AvgDialog_139661_Content_13 = {
    Text = "Ela ri, abrindo os braços para abraçar o vento."
  },
  AvgDialog_139661_Content_14 = {
    Text = "O jovem ao seu lado se inclina, ouvindo atentamente cada adorável palavra dela."
  },
  AvgDialog_139661_Content_15 = {
    Text = "O céu está limpo, mas tingido de uma melancolia silenciosa."
  },
  AvgDialog_139661_Content_16 = {
    Text = "Mas na silhueta que compartilham, você vislumbra uma alegria quieta e espontânea."
  },
  AvgDialog_139661_Content_17 = {
    Text = "Mesmo que não houvesse mais ninguém por perto, mesmo que não recebessem compreensão ou bênçãos de ninguém, o amor deles ainda assim —"
  },
  AvgDialog_139661_Content_18 = {
    Text = "Então o sonho se interrompe. A tempestade de areia varre tudo."
  },
  AvgDialog_139661_Content_19 = {
    Text = "O mundo mergulha num negro absoluto."
  },
  AvgDialog_139661_Content_2 = {
    Text = "O mundo é feito de areia."
  },
  AvgDialog_139661_Content_20 = {
    Text = "— Era uma vez uma cantora, seguindo seu caminho entre as estrelas."
  },
  AvgDialog_139661_Content_21 = {
    Text = "Em um universo árido e desolado, ela encontrou um Núcleo de prata jazendo na poeira."
  },
  AvgDialog_139661_Content_22 = {
    Text = "No momento em que ela o tocou, \"Eu\" despertei."
  },
  AvgDialog_139661_Content_23 = {
    Text = "\"Eu\" havia perdido toda a memória. Mas \"Eu\" sabia de uma coisa: eu precisava encontrar aquela \"pessoa insubstituível.\""
  },
  AvgDialog_139661_Content_24 = {
    Text = "\"Eu\" perguntei à cantora se podíamos viajar juntas, mas o pedido foi recusado."
  },
  AvgDialog_139661_Content_25 = {
    Text = "Eu vou encontrar aquela que significa o mundo para mim—minha irmã."
  },
  AvgDialog_139661_Content_26 = {
    Text = "Foi isso que ela disse."
  },
  AvgDialog_139661_Content_27 = {
    Text = "Espero que você também encontre o seu amor, Saya. Desejo-lhe de verdade um final feliz."
  },
  AvgDialog_139661_Content_28 = {
    Text = "Com essas palavras, a cantora partiu."
  },
  AvgDialog_139661_Content_29 = {
    Text = "E assim, deixada sem meu passado e agora sem a cantora,"
  },
  AvgDialog_139661_Content_3 = {
    Text = "Em meio aos ventos que varreram este deserto por eras, você permanece à deriva, contemplando tudo ao redor."
  },
  AvgDialog_139661_Content_30 = {
    Text = "Carreguei a bênção dela comigo enquanto caminhava sozinha por este mundo."
  },
  AvgDialog_139661_Content_31 = {
    Text = "Para encontrar aquela que um dia foi insubstituível... para reunir o que eu havia perdido..."
  },
  AvgDialog_139661_Content_32 = {
    Text = "Continuei seguindo em frente, acreditando que o que eu buscava estava esperando logo adiante."
  },
  AvgDialog_139661_Content_33 = {
    Text = "Até que, finalmente... eu encontrei você."
  },
  AvgDialog_139661_Content_4 = {
    Text = "Este lugar..."
  },
  AvgDialog_139661_Content_5 = {
    Text = "Nenhuma lama de Dissolução. Nenhuma massa visceral espalhada."
  },
  AvgDialog_139661_Content_6 = {
    Text = "A paisagem aqui é solitária, pura e bela."
  },
  AvgDialog_139661_Content_7 = {
    Text = "Esta é a minha Paisagem Mental."
  },
  AvgDialog_139661_Content_8 = {
    Text = "Um fragmento da minha existência — algo insubstituível, algo que jamais deveria ser esquecido..."
  },
  AvgDialog_139661_Content_9 = {
    Text = "A areia se move e ondula, e no canto distante do deserto, duas figuras emergem."
  },
  AvgDialog_139662_Content_10 = {
    Text = "Eu serei seu assistente, acompanhando-o até o final deste caminho... <Yellow:Que a Chave Prata ilumine seu caminho.>"
  },
  AvgDialog_139662_Content_11 = {
    Text = "Você está bem, %player%? Está um pouco pálido(a). Devemos passar pela enfermaria?"
  },
  AvgDialog_139662_Content_12 = {Text = "Ramona..."},
  AvgDialog_139662_Content_13 = {
    Text = "O nome fica preso na sua garganta. Você não consegue pronunciar o nome dela—o nome que conhece tão bem."
  },
  AvgDialog_139662_Content_14 = {
    Text = "<Shake:<Red:Ug ｦ,ﾋ保5険ｸk起Q见...ﾃ还爨是ｨ和A我ﾑ鑷链9ｴ接吧ﾅ.>>"
  },
  AvgDialog_139662_Content_16 = {
    Text = "<Red:Não, não, não, não. Nada está certo. Nada.>"
  },
  AvgDialog_139662_Content_17 = {
    Text = "<Shake:<Red:ﾒ从ｩﾇ龥年ｯ前7開ﾘ始L,ﾝ我就Q在ｱ齉其月ﾏ待r今ｮ天了麤.>>"
  },
  AvgDialog_139662_Content_18 = {
    Text = "<Shake:Não, aquilo não era Ramona. Ramona não seria uma massa de carne horrenda e Distorcida, não emitiria aquele gemido nauseante, não teria Lama Corrosiva negra brotando por todo o corpo...>"
  },
  AvgDialog_139662_Content_19 = {
    Text = "<Red:Não me fitaria fixamente com aqueles Olhos negros e vazios —>"
  },
  AvgDialog_139662_Content_2 = {
    Text = "Blo0ﾝdiｲwoRｮ"
  },
  AvgDialog_139662_Content_20 = {Text = "Não—!"},
  AvgDialog_139662_Content_21 = {
    Text = "Aquilo foi... um sonho?"
  },
  AvgDialog_139662_Content_22 = {
    Text = "Você acorda sobressaltado, encharcado em suor frio."
  },
  AvgDialog_139662_Content_23 = {
    Text = "Que sonho estranho. Mesmo acordado, ainda persiste na minha visão."
  },
  AvgDialog_139662_Content_24 = {
    Text = "O que você está vendo... é..."
  },
  AvgDialog_139662_Content_25 = {Text = "É..."},
  AvgDialog_139662_Content_26 = {
    Text = "<Shake:<Red:Massa de carne, grandes pedaços de carne empilhados e sobrepostos.>>"
  },
  AvgDialog_139662_Content_27 = {
    Text = "Entranhas Carmesim e contorcidas revestindo as paredes, estrangulando os pilares, rastejando pelas janelas.\nE entre as fendas da carne—"
  },
  AvgDialog_139662_Content_28 = {
    Text = "Líquido negro está escorrendo."
  },
  AvgDialog_139662_Content_29 = {
    Text = "Dissolução."
  },
  AvgDialog_139662_Content_3 = {
    Text = "Pain. Pain abrasadora. Um carmesim escuro inunda suas retinas."
  },
  AvgDialog_139662_Content_30 = {
    Text = "Você já viu Dissolução antes. Vezes demais. Mas nunca assim—duas enfermidades distintas dilacerando um único corpo ao mesmo tempo."
  },
  AvgDialog_139662_Content_31 = {Text = "Ramona..."},
  AvgDialog_139662_Content_32 = {
    Text = "A cena volta a piscar. Órbitas oculares negras e vazias. Um contorno Distorcido e inchado. Os dedos dela em sua palma se transformam em <Shake:excrescências de carne irregulares> —"
  },
  AvgDialog_139662_Content_33 = {
    Text = "Não—pare. Pare de pensar—"
  },
  AvgDialog_139662_Content_34 = {
    Text = "Ela ainda está lá fora—ela tem que estar em algum lugar—"
  },
  AvgDialog_139662_Content_35 = {
    Text = "Um leve tremor percorre a sua mente. Quase imperceptível."
  },
  AvgDialog_139662_Content_36 = {
    Text = "Instintivamente, você busca a origem—não é Ramona. Você reconheceria Ramona de olhos fechados; as ondas espirituais dela são calmas e suaves, como a superfície de um lago sereno."
  },
  AvgDialog_139662_Content_37 = {
    Text = "Vá para leste..."
  },
  AvgDialog_139662_Content_38 = {Text = "Quem?"},
  AvgDialog_139662_Content_39 = {
    Text = "Sem resposta."
  },
  AvgDialog_139662_Content_4 = {
    Text = "Minha cabeça..."
  },
  AvgDialog_139662_Content_40 = {
    Text = "Sem outras pistas, você se move em direção ao som."
  },
  AvgDialog_139662_Content_41 = {
    Text = "Você atravessa um rio que fede a ferrugem e podridão. Você pisa sobre uma terra membranosa infestada de tendões vermelho-escuros."
  },
  AvgDialog_139662_Content_42 = {
    Text = "Sua respiração se torna difícil; seus nervos pulsam sob a invasão daquelas cores eldritch."
  },
  AvgDialog_139662_Content_43 = {
    Text = "Alguém... qualquer um... me tirem deste sonho..."
  },
  AvgDialog_139662_Content_44 = {
    Text = "Tem que ser um sonho. A sensação é real demais—mas você precisa acreditar nisso. Precisa."
  },
  AvgDialog_139662_Content_45 = {
    Text = "Algo macio e branco pousa na ponta do seu nariz."
  },
  AvgDialog_139662_Content_46 = {
    Text = "Um dente-de-leão...?"
  },
  AvgDialog_139662_Content_47 = {
    Text = "Você pisa sobre uma fronteira. Uma visível—uma linha nítida e inconfundível dividindo dois mundos."
  },
  AvgDialog_139662_Content_48 = {
    Text = "Além dela: carne nauseante e lodo negro em ebulição."
  },
  AvgDialog_139662_Content_49 = {
    Text = "Dentro dele: um pequeno campo de dentes-de-leão. No centro, uma pequena cabana de madeira."
  },
  AvgDialog_139662_Content_5 = {
    Text = "Luz fraca e tremeluzente, um zumbido ecoando em seus tímpanos. Este mundo não é confiável. Tudo à vista não passa de ilusão."
  },
  AvgDialog_139662_Content_50 = {
    Text = "Algo se move no canteiro de dentes-de-leão."
  },
  AvgDialog_139662_Content_51 = {
    Text = "Você segue o movimento. Um tufo branco é afastado, revelando um canto de tecido pálido."
  },
  AvgDialog_139662_Content_52 = {
    Text = "Então ela se levanta."
  },
  AvgDialog_139662_Content_53 = {
    Text = "Uma garota, frágil e etérea como um dente-de-leão."
  },
  AvgDialog_139662_Content_54 = {
    Text = "Ela inclina a cabeça, observando sua expressão."
  },
  AvgDialog_139662_Content_55 = {
    Text = "Você não tem medo de mim?"
  },
  AvgDialog_139662_Content_56 = {
    Text = "É quase irônico. Depois de tudo por que você passou, ela é o único ser humano normal que você viu. A única existência que não é assustadora."
  },
  AvgDialog_139662_Content_57 = {
    Text = "Então... gostaria de apertar minha mão?"
  },
  AvgDialog_139662_Content_58 = {
    Text = "Hã? Por quê?"
  },
  AvgDialog_139662_Content_59 = {
    Text = "Hmm... só sinto que deveria."
  },
  AvgDialog_139662_Content_6 = {
    Text = "Acorde. Acorde agora..."
  },
  AvgDialog_139662_Content_60 = {
    Text = "Quanto ao motivo... não consigo me lembrar direito."
  },
  AvgDialog_139662_Content_61 = {
    Text = "Além disso..."
  },
  AvgDialog_139662_Content_62 = {
    Text = "A garota inclina a cabeça, um sorriso travesso adornando seus lábios."
  },
  AvgDialog_139662_Content_63 = {
    Text = "Você quer me tocar também, não quer?"
  },
  AvgDialog_139662_Content_64 = {
    Text = "Você quer. Claro que quer."
  },
  AvgDialog_139662_Content_65 = {
    Text = "Depois de tudo—a escuridão, o fedor, o repulsivo assalto sensorial—como você poderia não querer tocar a primeira pessoa viva que encontrou?"
  },
  AvgDialog_139662_Content_66 = {
    Text = "Você estende a mão, tocando seus dedos delicados e macios."
  },
  AvgDialog_139662_Content_67 = {
    Text = "Que sensação estranha..."
  },
  AvgDialog_139662_Content_68 = {
    Text = "Sim. Você também sente. Junto com o calor humano, há uma sensação tênue, como uma fraca corrente elétrica conectando vocês."
  },
  AvgDialog_139662_Content_69 = {
    Text = "É a ressonância dos Núcleos de Prata."
  },
  AvgDialog_139662_Content_7 = {
    Text = "Bem-vindo à Universidade Mythag, %player%."
  },
  AvgDialog_139662_Content_8 = {
    Text = "Ou melhor... bem-vindo, você oficialmente entrou no lado oculto do mundo."
  },
  AvgDialog_139662_Content_9 = {
    Text = "(Eu... voltei?)"
  },
  AvgDialog_139663_Content_1 = {
    Text = "Aquelas coisas são..."
  },
  AvgDialog_139663_Content_10 = {
    Text = "Se ela for comum... provavelmente não conseguirá falar comigo."
  },
  AvgDialog_139663_Content_11 = {
    Text = "Como você é um Corpo Desperto, talvez eu consiga estabelecer uma conexão com você. Através da ressonância onírica, você poderia ver como Ramona é."
  },
  AvgDialog_139663_Content_12 = {
    Text = "Talvez ela possa ser a pista para desvendar suas memórias."
  },
  AvgDialog_139663_Content_13 = {
    Text = "Você pega a mão de Saya novamente. Você se concentra internamente, traçando a forma de Ramona em sua mente—sua voz, seu rosto—esperando que a tênue conexão entre vocês possa transmiti-la."
  },
  AvgDialog_139663_Content_14 = {
    Text = "<Italic:Estalo>. A conexão se rompe."
  },
  AvgDialog_139663_Content_15 = {
    Text = "Parece que alguma parede sem forma está bloqueando nossa conexão..."
  },
  AvgDialog_139663_Content_16 = {
    Text = "Parece que alguma parede sem forma está bloqueando nossa ligação..."
  },
  AvgDialog_139663_Content_17 = {
    Text = "Talvez esteja relacionado ao que preciso fazer. Tenho a sensação... de que é algo proibido. Algo que não posso contar a todos."
  },
  AvgDialog_139663_Content_18 = {
    Text = "Parece que uma tempestade está vindo. Vamos descansar lá dentro por um tempo."
  },
  AvgDialog_139663_Content_19 = {
    Text = "Pelas frestas das tábuas de madeira, uma gosma negra ocasionalmente flutua para cima, desafiando a gravidade."
  },
  AvgDialog_139663_Content_2 = {
    Text = "Eu também não sei. Mas tenho a sensação de que... a resposta está em algum lugar nas minhas memórias."
  },
  AvgDialog_139663_Content_20 = {
    Text = "Saya se encolhe em um canto, a metade inferior do rosto escondida contra os braços. Ela pergunta baixinho—"
  },
  AvgDialog_139663_Content_21 = {
    Text = "Isso é o que você chamou de \"Dissolução,\" não é?"
  },
  AvgDialog_139663_Content_22 = {
    Text = "Você acena com a cabeça."
  },
  AvgDialog_139663_Content_23 = {
    Text = "Foi isso que levou minhas memórias?"
  },
  AvgDialog_139663_Content_24 = {
    Text = "Sim. E não apenas você, inúmeras pessoas perderam memórias importantes por causa da Dissolução."
  },
  AvgDialog_139663_Content_25 = {
    Text = "Algumas esqueceram os rostos de seus entes queridos. Passaram anos procurando—e às vezes, nessa busca, acabaram machucando justamente aqueles de quem sentem falta."
  },
  AvgDialog_139663_Content_26 = {
    Text = "Algumas esqueceram as cidades onde nasceram. Vagaram sozinhas pelo oceano, perseguindo um passado ao qual nunca podem retornar."
  },
  AvgDialog_139663_Content_27 = {
    Text = "...Perder memórias preciosas deve ser muito doloroso."
  },
  AvgDialog_139663_Content_28 = {
    Text = "Saya olha para a chuva caindo em linhas finas e constantes—como se a água pudesse lavar a imundície negra."
  },
  AvgDialog_139663_Content_29 = {
    Text = "Eu me pergunto... quais são as coisas importantes escondidas nas minhas memórias?"
  },
  AvgDialog_139663_Content_3 = {
    Text = "Vou encontrar um jeito de tirar você deste Domínio. Vamos recuperar suas memórias."
  },
  AvgDialog_139663_Content_30 = {
    Text = "Fico me perguntando... quais são as coisas importantes escondidas nas minhas memórias?"
  },
  AvgDialog_139663_Content_31 = {
    Text = "Você permanece em silêncio."
  },
  AvgDialog_139663_Content_32 = {
    Text = "Lá fora, a chuva continua caindo, constante e suave."
  },
  AvgDialog_139663_Content_4 = {Text = "Mas..."},
  AvgDialog_139663_Content_5 = {
    Text = "Você quer encontrar a Ramona primeiro, certo?"
  },
  AvgDialog_139663_Content_6 = {
    Text = "Para ser honesta... acho que me lembro de ter encontrado alguém uma vez, e depois..."
  },
  AvgDialog_139663_Content_7 = {
    Text = "Para ser honesta... acho que me lembro de ter encontrado alguém uma vez, e então..."
  },
  AvgDialog_139663_Content_8 = {
    Text = "Enfim. Essa Ramona—ela é... diferente, do jeito que você é?"
  },
  AvgDialog_139663_Content_9 = {
    Text = "Se ela for uma pessoa comum... provavelmente não vai conseguir falar comigo."
  },
  AvgDialog_141373_Content_1 = {
    Text = "Esta não é a sua primeira vez em Ebwynnos, mas nunca, em nenhuma outra ocasião, essas criaturas sem rosto estiveram tão agitadas como hoje."
  },
  AvgDialog_141373_Content_10 = {
    Text = "Espere, Você é... por que estaria aqui?"
  },
  AvgDialog_141373_Content_11 = {
    Text = "Um ruído branco e agudo engoliu a consciência, e uma maré antiga e invisível forçou você a erguer a cabeça pesadamente, olhando para a única coisa que conseguia reconhecer."
  },
  AvgDialog_141373_Content_12 = {
    Text = "Exatamente, nada disso importa — quem você é, o que quer fazer, O Motivo pelo qual veio até aqui."
  },
  AvgDialog_141373_Content_13 = {
    Text = "A voz grave afasta o som das ondas, e o mais velho estreita o cerco da Caça de cima para baixo."
  },
  AvgDialog_141373_Content_14 = {
    Text = "Você está seguro, bem-vindo de volta."
  },
  AvgDialog_141373_Content_15 = {
    Text = "Oh... é verdade, Ebwynnos, voltei para Ebwynnos."
  },
  AvgDialog_141373_Content_16 = {
    Text = "Você murmura repetindo as palavras, sem perceber que os cantos da boca se erguem, e tudo que vem a seguir parece completamente natural."
  },
  AvgDialog_141373_Content_17 = {
    Text = "Tudo bem, admito que isso é um pouco irregular, mas não se preocupe, vou te levar de volta a Misaq."
  },
  AvgDialog_141373_Content_18 = {
    Text = "O abismo já te envolve por completo, e sua Frágil inteligência, sacudida repetidas vezes, é totalmente incapaz de compreender tudo o que o outro está dizendo."
  },
  AvgDialog_141373_Content_19 = {Text = "O que?"},
  AvgDialog_141373_Content_2 = {
    Text = "Ei, Ei! Parem, eu não sou um inimi..."
  },
  AvgDialog_141373_Content_20 = {
    Text = "Uma risada rouca e breve."
  },
  AvgDialog_141373_Content_21 = {
    Text = "Apenas não agora."
  },
  AvgDialog_141373_Content_22 = {
    Text = "Úmido, Caos, aperto — eles te preenchem por completo, e então, em ondas contínuas, te deixam Enredado; você perde todo o controle."
  },
  AvgDialog_141373_Content_23 = {
    Text = "Nos seus ouvidos restam Apenas sussurros misturados a ofegos."
  },
  AvgDialog_141373_Content_24 = {
    Text = "Agora, você pertence a este lugar, pertence a mim, pertence a Ebwynnos."
  },
  AvgDialog_141373_Content_25 = {
    Text = "Você não entende nada, Apenas continua a se render às antigas águas do mar em meio à alegria."
  },
  AvgDialog_141373_Content_26 = {
    Text = "Ele não dá nenhum sinal de querer parar."
  },
  AvgDialog_141373_Content_3 = {
    Text = "*Som de apito de caça"
  },
  AvgDialog_141373_Content_4 = {
    Text = "O Ataque cessou, porém, a escuridão envolveu você de repente. Quase num instante, o silêncio estagnado lançou você em alguma corrente indescritível."
  },
  AvgDialog_141373_Content_5 = {Text = "Sim?"},
  AvgDialog_141373_Content_6 = {Text = "Ah..."},
  AvgDialog_141373_Content_7 = {
    Text = "Como Se quisesse confirmar algo, ignorando o arrepio que explodiu em você pelo estresse repentino, o senhor destas terras percorreu com gestos incontestáveis sua sobrancelha, o canto dos olhos, até o lado do pescoço."
  },
  AvgDialog_141373_Content_8 = {
    Text = "Visitar Ebwynnos neste momento não é uma boa ideia, %player%."
  },
  AvgDialog_141373_Content_9 = {
    Text = "<Small:Eu Apenas...>"
  },
  AvgDialog_142850_Content_1 = {
    Text = "Primeira Seção"
  },
  AvgDialog_142850_Content_10 = {
    Text = "Varo... Você, Você desista! Somos muitos, é impossível que Você saia vivo desta floresta!"
  },
  AvgDialog_142850_Content_100 = {
    Text = "Era uma velocidade e uma Força que ele não tinha como resistir. Varo ergueu os olhos confusos, olhando para Lotan sem compreender."
  },
  AvgDialog_142850_Content_101 = {
    Text = "Você... prometeu..."
  },
  AvgDialog_142850_Content_102 = {
    Text = "Eu prometi deixar você entrar na minha equipe. Mas não disse que você sairia vivo."
  },
  AvgDialog_142850_Content_103 = {
    Text = "A Fraqueza não é sua culpa. Mas seu coração não é puro, guerreiro."
  },
  AvgDialog_142850_Content_104 = {
    Text = "Lotan pega os dois Sigilos de Osso da mão de Varro e empurra seu cadáver — rosto ainda congelado em confusão — sobre a pilha de doze cavaleiros mortos, como se fosse lixo descartado."
  },
  AvgDialog_142850_Content_105 = {
    Text = "Ela olha em direção ao matagal, erguendo sua espada grande, pronta para cortar o Sigilo extra..."
  },
  AvgDialog_142850_Content_106 = {
    Text = "Espere!! —"
  },
  AvgDialog_142850_Content_107 = {
    Text = "A lâmina de Lotan para no ar. Com fria indiferença, ela observa você rastejar para fora dos arbustos."
  },
  AvgDialog_142850_Content_108 = {
    Text = "Não tenho interesse em oponentes muito fracos."
  },
  AvgDialog_142850_Content_109 = {
    Text = "Pequeno Escudeiro dos Cavaleiros, se eu fosse você, fugiria antes que ela mudasse de ideia, o mais rápido possível."
  },
  AvgDialog_142850_Content_11 = {
    Text = "Entregue seu Selo Ósseo, garantimos, garantimos que Você poderá sair em segurança!"
  },
  AvgDialog_142850_Content_110 = {
    Text = "O Senhor Elian ordenou que os Cavaleiros trouxessem a Coroa de volta para ele. Se... se ele descobrir que fugi, toda a minha família morrerá..."
  },
  AvgDialog_142850_Content_111 = {
    Text = "Você reuniu toda a sua coragem e deu um passo em direção a Lotan."
  },
  AvgDialog_142850_Content_112 = {
    Text = "A senhora ainda tem uma marca óssea... Por favor, deixe-me ir também ao Coliseu da Baleia Celeste, pode ser? Só preciso chegar lá e minha missão estará cumprida... A senhora é tão forte, não serei nenhuma ameaça para a senhora..."
  },
  AvgDialog_142850_Content_113 = {Text = "Você?"},
  AvgDialog_142850_Content_114 = {
    Text = "Lotan arqueou uma sobrancelha e olhou para você com Provocação."
  },
  AvgDialog_142850_Content_115 = {
    Text = "Sua Força é ainda menor do que a daqueles inúteis mortos por Varo. No primeiro segundo em que entrar naquele Coliseu, você morrerá como um inseto."
  },
  AvgDialog_142850_Content_116 = {
    Text = "Vá embora agora e ainda terá uma chance de sobreviver."
  },
  AvgDialog_142850_Content_117 = {
    Text = "Você olhou para os cadáveres espalhados pelo chão, olhou para a figura diante de você que lhe causava medo nas profundezas do coração, e engoliu em seco com dificuldade."
  },
  AvgDialog_142850_Content_118 = {
    Text = "Você sabe que a vitória nunca foi sua para conquistar. Todo instinto grita para fugir desse monstro, para correr o mais longe possível."
  },
  AvgDialog_142850_Content_119 = {
    Text = "Você quer esquecer sua mãe que foi sacrificada viva ao Cetus Astral. Você quer esquecer seus irmãos que foram confinados como gado nos estábulos. Você simplesmente quer sobreviver."
  },
  AvgDialog_142850_Content_12 = {
    Text = "Ele tem razão, Varo! Mesmo que Você seja o mercenário mais poderoso dos seis reinos, cercado pelos nossos treze homens, não terá nenhuma vantagem."
  },
  AvgDialog_142850_Content_120 = {
    Text = "Mas não havia como, você não conseguia esquecer. Assim como participar dessa disputa fadada ao fracasso, você nunca teve o direito de escolha."
  },
  AvgDialog_142850_Content_121 = {
    Text = "Sou o guia do grupo e conheço o Caminho até o Coliseu. Fui Escudeiro por muitos e muitos anos, sei como servir a um guerreiro! Sou muito útil, o senhor vai precisar de mim..."
  },
  AvgDialog_142850_Content_122 = {
    Text = "Você respira fundo, pega o Sigilo e usa um pano para limpar a sujeira da armadura de Lotan, assim como fazia pelos cavaleiros."
  },
  AvgDialog_142850_Content_123 = {
    Text = "Por favor, venha por aqui, Este... Este... Hã?"
  },
  AvgDialog_142850_Content_124 = {
    Text = "Você se curva diante dela, e a respiração calma dela te oprime a ponto de não ousares erguer a cabeça, podendo apenas fixar o olhar no chão sob seus pés. Você sente que O Olhar dela, afiado como uma Lâmina afiada, pousou sobre você por alguns segundos."
  },
  AvgDialog_142850_Content_125 = {
    Text = "Se encontrar perigo, não espere que eu vá te ajudar."
  },
  AvgDialog_142850_Content_126 = {
    Text = "Sem sufixo. Pode me chamar de Lotan."
  },
  AvgDialog_142850_Content_127 = {
    Text = "Lotan guardou a grande espada e caminhou na direção que você apontou."
  },
  AvgDialog_142850_Content_128 = {
    Text = "O Sangue havia penetrado completamente no solo. Nas profundezas do céu vermelho-escuro, uma sombra enorme e de movimento lento aparecia e desaparecia."
  },
  AvgDialog_142850_Content_129 = {
    Text = "Você deu um arrepio e correu para alcançar os passos de Lotan."
  },
  AvgDialog_142850_Content_13 = {
    Text = "Podemos cooperar, não é?"
  },
  AvgDialog_142850_Content_130 = {
    Text = "É... Senhora Lotan!"
  },
  AvgDialog_142850_Content_14 = {Text = "Cooperar?"},
  AvgDialog_142850_Content_15 = {
    Text = "A Baleia Celestial escolherá apenas uma pessoa para se tornar seu Executor, e isso não é algo que uma pessoa sozinha pode alcançar!"
  },
  AvgDialog_142850_Content_16 = {
    Text = "Basta largar o Selo Ósseo, garantimos que Você sairá daqui em segurança e obterá tudo o que puder obter..."
  },
  AvgDialog_142850_Content_17 = {Text = "É assim?"},
  AvgDialog_142850_Content_18 = {
    Text = "Eu sei, Varo, Você sobreviveu às feras da ilha deserta, matou diante do espelho a pessoa que mais amava — talvez seus pais, seu filho, ou outra coisa qualquer."
  },
  AvgDialog_142850_Content_19 = {
    Text = "Você viveu meio mês nesta floresta primitiva. Com certeza não quer voltar assim..."
  },
  AvgDialog_142850_Content_2 = {
    Text = "As folhas caíam dos galhos, cortando o céu vermelho escuro, caindo na poça de sangue no chão, provocando uma leve ondulação."
  },
  AvgDialog_142850_Content_20 = {
    Text = "Mas pense bem, pense no que Espera por Você lá na frente!"
  },
  AvgDialog_142850_Content_21 = {
    Text = "Você terá que romper nosso cerco, esquivar-se dos perigos ao longo do Caminho, encontrar o Coliseu da Baleia Celestial e lá travar um Duelo Mortal com as pessoas mais perigosas do mundo."
  },
  AvgDialog_142850_Content_22 = {
    Text = "Mesmo que esse Selo Ósseo possa levá-lo ao Coliseu, Você tem certeza de que será a última pessoa a sobreviver?"
  },
  AvgDialog_142850_Content_23 = {
    Text = "Desde Que Você desista, quando o Senhor Elian ascender ao poder, Você se tornará um dos fundadores do reino... Pense bem, Varo!"
  },
  AvgDialog_142850_Content_24 = {
    Text = "Sua proposta é tentadora. Mas que pena, Apenas os inúteis precisam se agrupar para se aquecer. Você simplesmente não entende o que é ser forte."
  },
  AvgDialog_142850_Content_25 = {
    Text = "Chega de conversa, venham todos de uma vez, escória dos Cavaleiros."
  },
  AvgDialog_142850_Content_26 = {Text = "Você..."},
  AvgDialog_142850_Content_27 = {
    Text = "Varo! Você pagará pelo seu desrespeito!"
  },
  AvgDialog_142850_Content_28 = {
    Text = "Cavaleiros! Carreguem!!!"
  },
  AvgDialog_142850_Content_29 = {
    Text = "Bando de lixo..."
  },
  AvgDialog_142850_Content_3 = {
    Text = "A antiga floresta estava impregnada de um cheiro adocicado de sangue que não se dissipava; os corpos que nutriam a terra com seu sangue jaziam sobre o musgo carmesim, olhos arregalados em inconformidade, há muito sem qualquer sinal de vida."
  },
  AvgDialog_142850_Content_30 = {
    Text = "Uma torrente de armaduras avançou como ondas do mar em direção à figura solitária no centro. A carga de mais de dez homens esmagou musgo e ossos secos, fazendo a Terra tremer sob seus pés."
  },
  AvgDialog_142850_Content_31 = {
    Text = "O estrondo violento do metal colidindo explodiu pela floresta densa, assustando um bando escuro de pássaros que voou para longe como fragmentos negros arrancados das copas das árvores."
  },
  AvgDialog_142850_Content_32 = {
    Text = "Os galhos e folhas do esconderijo tremeram. Você se encolheu atrás dos arbustos, segurando a respiração enquanto observava aquele massacre pelas frestas entre as trepadeiras."
  },
  AvgDialog_142850_Content_33 = {Text = "..."},
  AvgDialog_142850_Content_34 = {
    Text = "A cimitarra despedaçou espadas, perfurou a Carne e sangue Frágil sob as armaduras, e decepou membros e cabeças pelas frestas entre as placas. Cada golpe era preciso, brutal, sem nenhum movimento desnecessário."
  },
  AvgDialog_142850_Content_35 = {
    Text = "Força, velocidade, habilidade... Diante deste guerreiro, a ordem de Cavaleiros Elite caía um a um como cordeiros prontos para o abate."
  },
  AvgDialog_142850_Content_36 = {Text = "..."},
  AvgDialog_142850_Content_37 = {
    Text = "Essa... essa pessoa..."
  },
  AvgDialog_142850_Content_38 = {
    Text = "A carga e os gritos de batalha logo se silenciaram. Varo arrancou um pano limpo do corpo de um Cavaleiro morto e limpou o Sangue da cimitarra."
  },
  AvgDialog_142850_Content_39 = {
    Text = "Ele examinou a lâmina imaculada e assentiu com satisfação. Em seguida, revirou o cadáver do Cavaleiro líder e encontrou o selo de osso que dava acesso ao Coliseu."
  },
  AvgDialog_142850_Content_4 = {
    Text = "Ufa... calma... ninguém deve ter me descoberto..."
  },
  AvgDialog_142850_Content_40 = {
    Text = "Um, dois, três... onze, doze."
  },
  AvgDialog_142850_Content_41 = {
    Text = "Doze, doze..."
  },
  AvgDialog_142850_Content_42 = {
    Text = "Ele olhou ao redor, mas não encontrou o décimo terceiro cadáver."
  },
  AvgDialog_142850_Content_43 = {
    Text = "Não! Ele me descobriu... Preciso aproveitar e..."
  },
  AvgDialog_142850_Content_44 = {Text = "*Snap*—"},
  AvgDialog_142850_Content_45 = {
    Text = "Um tronco seco apareceu no pior momento possível no Caminho de sua retirada. Varo virou-se bruscamente, olhando na direção dos arbustos onde Você se escondia."
  },
  AvgDialog_142850_Content_46 = {
    Text = "Um som nauseante e úmido de dilaceração se ergue no ar. Enormes patas de aranha irrompem pelos corpos dos oficiais e dos transeuntes, espirrando sangue espesso com cheiro de ferro por todo você."
  },
  AvgDialog_142850_Content_47 = {
    Text = "Eu estava me perguntando por que parecia que faltava um para abater. Então havia alguém escondido aqui."
  },
  AvgDialog_142850_Content_48 = {
    Text = "Saia daí, amigo. Vou fazer isso ser rápido para Você."
  },
  AvgDialog_142850_Content_49 = {
    Text = "Varo admirava o reflexo de seu próprio rosto na cimitarra enquanto caminhava em direção a Você sem pressa."
  },
  AvgDialog_142850_Content_5 = {
    Text = "Um Sonho intenso. Você se esconde entre os arbustos, acalmando sua respiração ofegante, espiando pelo meio das folhagens."
  },
  AvgDialog_142850_Content_50 = {
    Text = "Você olhou ao redor, buscando ansiosamente uma rota de fuga adequada."
  },
  AvgDialog_142850_Content_51 = {
    Text = "Impossível... a floresta é densa por todos os lados... com este corpo de criança, jamais conseguirei fugir dele..."
  },
  AvgDialog_142850_Content_52 = {
    Text = "O que fazer..."
  },
  AvgDialog_142850_Content_53 = {
    Text = "Você fechou os olhos, esforçando-se para suprimir o medo que borbulhava em seu coração, a mente completamente em branco..."
  },
  AvgDialog_142850_Content_54 = {
    Text = "<Red:Fru. Fru. Fru.>"
  },
  AvgDialog_142850_Content_55 = {Text = "Sim?"},
  AvgDialog_142850_Content_56 = {
    Text = "Passos pisando folhas caídas e líquens, vindo de outra direção."
  },
  AvgDialog_142850_Content_57 = {
    Text = "Eram calmos, estáveis, como um passeio tranquilo à tarde."
  },
  AvgDialog_142850_Content_58 = {
    Text = "Um ajudante da Ordem dos Cavaleiros... não escolher escapar é muito corajoso, e também muito estúpido."
  },
  AvgDialog_142850_Content_59 = {
    Text = "Quando os passos pararam, o som do vento e o canto dos pássaros desapareceram por completo, e até o Sangue que escorria dos cadáveres atrás de Você pareceu cessar, toda a floresta mergulhando em um silêncio mortal e sinistro."
  },
  AvgDialog_142850_Content_6 = {
    Text = "Uma cimitarra foi arrancada do peito dele de forma limpa e precisa, emitindo um som de atrito que fazia ranger os dentes. O guerreiro sacudiu a poeira que havia se impregnado em sua armadura e ergueu o olhar para os Arredores."
  },
  AvgDialog_142850_Content_60 = {
    Text = "Uma mulher entra em cena. Uma armadura leve preta ornamental cobre seu corpo, e em suas mãos ela segura com desenvoltura duas espadas grandes e robustas, totalmente desproporcionais à sua compleição."
  },
  AvgDialog_142850_Content_61 = {
    Text = "Os Olhos dela varreram os cadáveres espalhados pelo chão, O Olhar passando rapidamente pelas feridas deles."
  },
  AvgDialog_142850_Content_62 = {
    Text = "Cada um morreu com menos de cinco golpes, todos direcionados às junções da armadura, com ângulo e força precisos... essas pessoas, foram Você quem matou?"
  },
  AvgDialog_142850_Content_63 = {
    Text = "Hehehe... isso mesmo. Pena que ainda não me diverti o suficiente, e eles já caíram."
  },
  AvgDialog_142850_Content_64 = {
    Text = "Doze pessoas, e Você não se feriu. Nada mal."
  },
  AvgDialog_142850_Content_65 = {
    Text = "A mulher de armadura negra assentiu com satisfação, seus passos firmes continuando a se aproximar dele."
  },
  AvgDialog_142850_Content_66 = {
    Text = "Varo ficou Esperando. Ele buscou medo nos Olhos daquela mulher, mas o que viu foi apenas uma calma irritante."
  },
  AvgDialog_142850_Content_67 = {
    Text = "Não importa quem Você seja, posso lhe dar três minutos para escapar. Depois de três minutos, se conseguirá sobreviver ou não depende de..."
  },
  AvgDialog_142850_Content_68 = {
    Text = "Estou dizendo, Você é surdo? Não consegue ouvir o que estou falando?"
  },
  AvgDialog_142850_Content_69 = {
    Text = "A mulher de armadura negra não respondeu, seus passos ainda tão tranquilos quanto os de quem passeava. A raiva acendeu instantaneamente em Varo; sua mão fechou-se sobre o cabo da faca, sacando aquela cimitarra afiada."
  },
  AvgDialog_142850_Content_7 = {
    Text = "O próximo, de quem é a vez?"
  },
  AvgDialog_142850_Content_70 = {
    Text = "Ia poupar sua vida, mas já que Você quer tanto morrer, então não vou ser tão gen..."
  },
  AvgDialog_142850_Content_71 = {Text = "Clang—"},
  AvgDialog_142850_Content_72 = {
    Text = "O som de colisão metálica mais cristalino que Varo já ouvira em toda a sua vida ecoou brevemente junto ao seu ouvido e desapareceu."
  },
  AvgDialog_142850_Content_73 = {
    Text = "A mulher que deveria estar à sua frente apareceu, sem que se soubesse quando, atrás dele. Uma das espadas colossais era segurada por Ela com uma só mão, a lâmina repousando casualmente contra o lado do pescoço dele."
  },
  AvgDialog_142850_Content_74 = {
    Text = "Varo baixou a cabeça. A cimitarra forjada pelos ferreiros mais habilidosos de seis nações, que havia ceifado inúmeros inimigos, estava suspensa a alguns centímetros fora da bainha, cortada rente à base."
  },
  AvgDialog_142850_Content_75 = {
    Text = "A magnífica lâmina da qual ele tanto se orgulhava girou no ar e cravou-se invertida na terra encharcada de sangue, como uma lápide fria."
  },
  AvgDialog_142850_Content_76 = {
    Text = "Isso... você..."
  },
  AvgDialog_142850_Content_77 = {
    Text = "Alguém capaz de dizimar uma ordem inteira de Cavaleiros... pensei que ao menos conseguiria despertar algum interesse em mim."
  },
  AvgDialog_142850_Content_78 = {
    Text = "A mulher de armadura negra falou com uma decepção que não fazia questão alguma de esconder."
  },
  AvgDialog_142850_Content_79 = {
    Text = "Selo ósseo, você tem?"
  },
  AvgDialog_142850_Content_8 = {
    Text = "Ele lambeu o Sangue da cimitarra, olhou ao redor para as dezenas de pessoas que o cercavam e perguntou com curiosidade."
  },
  AvgDialog_142850_Content_80 = {
    Text = "<Shake:Tenho! Tenho, tenho, tenho!>"
  },
  AvgDialog_142850_Content_81 = {
    Text = "Varo havia visto muita gente e muitas situações; ele sabia o que fazer em cada momento. Suas pernas fraquejaram e ele caiu de joelhos diante dela."
  },
  AvgDialog_142850_Content_82 = {
    Text = "Milady, milady, por favor me ouça... a Baleia do Céu Estrelado escolhe apenas uma pessoa para ser seu Executor, e isso é algo que ninguém consegue fazer sozinho!"
  },
  AvgDialog_142850_Content_83 = {
    Text = "A Coroa! Aquela Coroa com que todos sonham... Você também a quer, não é?!"
  },
  AvgDialog_142850_Content_84 = {
    Text = "Com uma Força tão poderosa como a sua, se formarmos uma equipe juntos, certamente alcançaremos a vitória final!"
  },
  AvgDialog_142850_Content_85 = {
    Text = "Serei seu servo mais leal, dedicado a você para sempre, e a ajudarei a obter a Força da Baleia do Céu Estrelado!..."
  },
  AvgDialog_142850_Content_86 = {
    Text = "Milady... por favor, considere..."
  },
  AvgDialog_142850_Content_87 = {
    Text = "Uma boa proposta. Aceito."
  },
  AvgDialog_142850_Content_88 = {
    Text = "Você... você..."
  },
  AvgDialog_142850_Content_89 = {
    Text = "Varo já havia preparado um longo discurso, mas descobriu que não precisaria de nada disso."
  },
  AvgDialog_142850_Content_9 = {
    Text = "Quando ele ergueu a cimitarra, Todos recuaram um passo ao mesmo tempo."
  },
  AvgDialog_142850_Content_90 = {
    Text = "Pode ficar tranquilo. Nunca volto atrás na minha palavra."
  },
  AvgDialog_142850_Content_91 = {
    Text = "<Shake:Que, que ótimo!>"
  },
  AvgDialog_142850_Content_92 = {
    Text = "Como um homem arrancado da beira do abismo, Varro vasculha seus pertences às cegas, finalmente apresentando os Sigilos de Osso a Lotan com mãos trêmulas e em concha."
  },
  AvgDialog_142850_Content_93 = {
    Text = "Aqui! É este!"
  },
  AvgDialog_142850_Content_94 = {
    Text = "Aqueles cavaleiros confiscaram dois Sigilos. Com estes, podemos entrar na arena juntos!"
  },
  AvgDialog_142850_Content_95 = {
    Text = "Quando chegar a hora, ninguém será capaz de nos vencer..."
  },
  AvgDialog_142850_Content_96 = {Text = "Swish—"},
  AvgDialog_142850_Content_97 = {Text = "ARGH!!"},
  AvgDialog_142850_Content_98 = {
    Text = "O fio da espada gigante cortou a armadura com facilidade, abrindo uma enorme ferida que quase atravessou o corpo de Varo da cintura direita até o ombro esquerdo."
  },
  AvgDialog_142850_Content_99 = {
    Text = "Sangue quente jorrou sobre os arbustos à sua frente, condensando-se em gotas vermelho-escuras sobre as folhas."
  },
  AvgDialog_142851_Content_1 = {
    Text = "A quarta seção"
  },
  AvgDialog_142851_Content_10 = {
    Text = "No centro das colunas partidas, uma fissura que levava a outro espaço Rasgou a realidade, como uma pupila vertical se abrindo lentamente."
  },
  AvgDialog_142851_Content_100 = {
    Text = "As paredes de carne sob os pés sofreram um violento espasmo, e um forte cheiro de ferrugem invadiu as narinas. O próprio espaço estava tomado pela Empolgação."
  },
  AvgDialog_142851_Content_101 = {
    Text = "Bem... Muito bem!"
  },
  AvgDialog_142851_Content_102 = {
    Text = "Doze mil anos, Lotan... Eu Esperei neste vazio, Esperando por alguém que me fizesse sentir que a existência não é uma tortura."
  },
  AvgDialog_142851_Content_103 = {
    Text = "Reis, santos, guerreiros, criaturas das trevas... vieram até mim carregando seus desejos que julgavam grandiosos, ajoelharam-se e imploraram."
  },
  AvgDialog_142851_Content_104 = {
    Text = "Então, foram sendo corroídos aos poucos pela Força que lhes concedi, tornando-se mais um rosto flutuando no abismo."
  },
  AvgDialog_142851_Content_105 = {
    Text = "Pensei que fosse esse o único conteúdo da eternidade."
  },
  AvgDialog_142851_Content_106 = {
    Text = "Até Você estar aqui, olhando para mim com esses Olhos que nada anseiam, dizendo-me que vai... hehehe... que vai me matar?!!"
  },
  AvgDialog_142851_Content_107 = {
    Text = "Um vermelho escuro, puro, denso e pesado jorrou da fissura do coração, engolindo todas as veias de luz e os rostos no abismo."
  },
  AvgDialog_142851_Content_108 = {
    Text = "Naquela escuridão vermelha e podre, o contorno do enorme corpo da Baleia Celestial surgiu no horizonte."
  },
  AvgDialog_142851_Content_109 = {
    Text = "Um corpo maior do que este mundo dobrou a própria forma do vazio, o plano sob seus pés começou a curvar como papel, e a escuridão ao longe começou a colapsar para dentro."
  },
  AvgDialog_142851_Content_11 = {
    Text = "Então não é preciso matar o oponente para que a Porta se abra... Você teve sorte."
  },
  AvgDialog_142851_Content_110 = {
    Text = "Este planeta cresceu sobre seu corpo, e os humanos dos seis reinos existem por causa dela. Ela é a divindade que Devora a Força dos planetas, a senhora incontestável deste planeta. Ela é o próprio espaço."
  },
  AvgDialog_142851_Content_111 = {
    Text = "O Fantasma desapareceu por completo, e Leviatã abriu subitamente seus magníficos olhos."
  },
  AvgDialog_142851_Content_112 = {
    Text = "Uma Força capaz de destruir os céus e a terra jorrou do corpo da Baleia Celestial. Todo o espaço dimensional começou a colapsar, e uma Força invisível lançou Você para longe, fazendo-o cair pesadamente na borda do plano."
  },
  AvgDialog_142851_Content_113 = {
    Text = "Seus dedos se agarraram à fissura, lutando desesperadamente para não escorregar para o abismo."
  },
  AvgDialog_142851_Content_114 = {
    Text = "Você me deixa muito, muito feliz, Lotan!"
  },
  AvgDialog_142851_Content_115 = {
    Text = "Depois de sua morte, farei com que todos os servos deste mundo esculpam para você a mais magnífica das estátuas!"
  },
  AvgDialog_142851_Content_116 = {
    Text = "No centro daquela escuridão que tudo engolia, diante daquela presença colossal e indescritível, Lotan empunhou a grande espada com ambas as mãos e caminhou em direção àqueles olhos imensos e aterrorizantes."
  },
  AvgDialog_142851_Content_117 = {
    Text = "Seus passos ficaram cada vez mais rápidos, cada vez mais rápidos, até que, por fim, se transformaram numa tempestade imparável. Em O Semblante dela, havia um sorriso de Fervor que Você jamais havia visto."
  },
  AvgDialog_142851_Content_118 = {
    Text = "Venha! Leviatã!!!"
  },
  AvgDialog_142851_Content_119 = {
    Text = "Um rugido glorioso como a maré do mar ecoou, despedaçando os últimos resquícios de sua consciência. As mãos que seguravam a pedra já não tinham mais Força, e naquele vento uivante, Você retornou ao Coliseu através da fissura."
  },
  AvgDialog_142851_Content_12 = {
    Text = "Lotan desviou O Olhar, ela nunca teve qualquer interesse em você. Aquela figura esbelta empunhou a espada enorme e caminhou em direção à fissura."
  },
  AvgDialog_142851_Content_120 = {
    Text = "Nos últimos lampejos de sua visão, Você viu Lotan empunhando aquelas duas grandes espadas, saltando em direção à divindade mais magnífica do que as próprias estrelas."
  },
  AvgDialog_142851_Content_121 = {
    Text = "A tempestade se despedaça.\nA tempestade jamais olha para trás."
  },
  AvgDialog_142851_Content_13 = {
    Text = "Somente quando a silhueta dela desapareceu completamente na fissura você finalmente se sentou, respirando fundo com dificuldade."
  },
  AvgDialog_142851_Content_14 = {
    Text = "Ufa... Que susto..."
  },
  AvgDialog_142851_Content_15 = {
    Text = "Aquele lugar... é a morada da Baleia Celestial..."
  },
  AvgDialog_142851_Content_16 = {
    Text = "Você queria fugir dali, mas uma atração irresistível emanava da fissura, como um fio invisível preso aos seus ossos, puxando-o suave e continuamente."
  },
  AvgDialog_142851_Content_17 = {
    Text = "Seus pés se moveram involuntariamente em direção à fissura. A fissura tremia levemente, como um olho gentil que o observava."
  },
  AvgDialog_142851_Content_18 = {
    Text = "Apenas um olhar, apenas um. Ver como é o grande senhor que Devora as estrelas... Você se aproximou furtivamente da fissura e foi seguindo para dentro..."
  },
  AvgDialog_142851_Content_19 = {Text = "..."},
  AvgDialog_142851_Content_2 = {
    Text = "Lo, Lotan, minha senhora! ......"
  },
  AvgDialog_142851_Content_20 = {
    Text = "Nenhuma luz, nenhum som, sequer os batimentos do seu próprio coração podiam ser ouvidos. Você não tinha certeza se ainda possuía um corpo, ou se já havia se tornado algum fragmento de consciência flutuando no Nada."
  },
  AvgDialog_142851_Content_21 = {
    Text = "O tato retornou ao seu corpo, e sob seus pés você sentiu um movimento suave, morno e rítmico. Ele se contraía levemente sob suas solas, como uma língua enorme te lambendo."
  },
  AvgDialog_142851_Content_22 = {
    Text = "O que é isso?! ......"
  },
  AvgDialog_142851_Content_23 = {
    Text = "Estrelas sombrias circulavam pelo céu estrelado, e uma pulsação que mudava constantemente de cor iluminava o espaço onde você se encontrava."
  },
  AvgDialog_142851_Content_24 = {
    Text = "Massas de Carne e sangue se estendiam interminavelmente sob seus pés, ondulando como uma língua gigante ou um estômago."
  },
  AvgDialog_142851_Content_25 = {
    Text = "Você respirou fundo e encarou aquela pulsação distante, parpadeante como um globo ocular. Em apenas um segundo, uma tontura intensa o invadiu, e um fluxo morno de Banquete de Sangue jorrou de suas narinas. Você desviou O Olhar rapidamente."
  },
  AvgDialog_142851_Content_26 = {
    Text = "Nos últimos lampejos da sua visão, você vê aquela massa pulsante e mutável se solidificar, e um Fantasma do Nada surge diante de Lotan. Quando Ele abre a boca, um vasto canto de baleia ecoa por todo o espaço."
  },
  AvgDialog_142851_Content_27 = {
    Text = "Bem-vindo, quatro milésimo desafiante a se apresentar diante de mim! Bem-vindo à minha morada."
  },
  AvgDialog_142851_Content_28 = {
    Text = "Era você, afinal."
  },
  AvgDialog_142851_Content_29 = {
    Text = "Uma disputa tão magnífica — que graça haveria em não presenciá-la pessoalmente."
  },
  AvgDialog_142851_Content_3 = {
    Text = "Eu... Eu não... Nunca pensei em disputar a Coroa com a senhora..."
  },
  AvgDialog_142851_Content_30 = {
    Text = "Assisti a cada uma das suas batalhas, criança que empunha a grande espada."
  },
  AvgDialog_142851_Content_31 = {
    Text = "Gracchus, as Irmãs Vaughan, Sanchi, Elian, Alish... Nessa grande arena, você derrotou todos os seres mais poderosos deste planeta."
  },
  AvgDialog_142851_Content_32 = {
    Text = "Sua espada não tem movimentos desnecessários. Sua alma não carrega fardos supérfluos. Sua vitória é mais do que merecida, Lotan."
  },
  AvgDialog_142851_Content_33 = {
    Text = "O Fantasma acenou com a cabeça em sinal de satisfação."
  },
  AvgDialog_142851_Content_34 = {
    Text = "Os seres que chegam até aqui têm apenas três razões: conhecimento, poder, Vida."
  },
  AvgDialog_142851_Content_35 = {
    Text = "O rei ganancioso deseja um trono imortal, a Mãe desesperada quer a ressurreição de seu filho morto, o feiticeiro louco quer ser um Voyeur do conhecimento proibido... o que desejam é muito, muito."
  },
  AvgDialog_142851_Content_36 = {
    Text = "E assim, causam Dano, matam, Sacrificam tudo. Ajoelham-se diante de mim e me suplicam com palavras que ouço há milhares e milhares de anos."
  },
  AvgDialog_142851_Content_37 = {
    Text = "Mas tudo valeu a pena... no fim, cada um obteve aquilo que tanto buscava."
  },
  AvgDialog_142851_Content_38 = {
    Text = "Então, bravo guerreiro... o que é que você deseja?"
  },
  AvgDialog_142851_Content_39 = {Text = "Força."},
  AvgDialog_142851_Content_4 = {
    Text = "Eu... Eu apenas..."
  },
  AvgDialog_142851_Content_40 = {
    Text = "A Força é Apenas uma ferramenta, um degrau — e acima desse degrau, há algo que Espera por você."
  },
  AvgDialog_142851_Content_41 = {
    Text = "Diga-me, o que é que você realmente deseja?"
  },
  AvgDialog_142851_Content_42 = {
    Text = "Já disse... o que desejo é Apenas Força. Uma Força cada vez maior, sem fim jamais."
  },
  AvgDialog_142851_Content_43 = {
    Text = "Qualquer coisa além da Força não me interessa."
  },
  AvgDialog_142851_Content_44 = {
    Text = "A Baleia Celestial observou Lotan com curiosidade, e uma gargalhada estrondosa ecoou por todo o espaço."
  },
  AvgDialog_142851_Content_45 = {Text = "Hehehe..."},
  AvgDialog_142851_Content_46 = {
    Text = "Essas palavras, já as ouvi muitas vezes. Cada pessoa que as disse acabou se Perdendo nos desejos que a Força traz consigo."
  },
  AvgDialog_142851_Content_47 = {
    Text = "Eles obtiveram minha Força, mas não conseguiram suportar seu peso. Ela crescia na medula óssea, Devorando as almas, e o anseio por matar e conquistar foi engolindo suas consciências uma a uma..."
  },
  AvgDialog_142851_Content_48 = {
    Text = "Histórias como essa, já assisti quatro mil vezes, e nunca me canso."
  },
  AvgDialog_142851_Content_49 = {
    Text = "Com o som de um canto de baleia, um enorme coração de baleia apareceu naquele espaço. Uma coluna de Sangue fluiu do coração, confluindo diante de Lotan em runas densamente agrupadas."
  },
  AvgDialog_142851_Content_5 = {
    Text = "Você já havia esquecido da ferida no ombro, sem coragem para encarar diretamente aqueles olhos serenos."
  },
  AvgDialog_142851_Content_50 = {
    Text = "Elas se organizavam em uma figura impossível de compreender, e sempre que Lotan tentava ver sua forma completa, ela se transformava em algo completamente diferente."
  },
  AvgDialog_142851_Content_51 = {
    Text = "Apenas com um olhar de relance, você sente um fluxo de Sangue ardente correr pelo seu corpo, causando Impacto em cada um dos seus órgãos, impelindo-o a pegar a espada e cravar no coração da pessoa à sua frente... Você rapidamente desvia os olhos."
  },
  AvgDialog_142851_Content_52 = {
    Text = "Assine. E você receberá o que tanto ansiou — minha força."
  },
  AvgDialog_142851_Content_53 = {
    Text = "Qual é o preço?"
  },
  AvgDialog_142851_Content_54 = {
    Text = "Não há preço, apenas uma promessa."
  },
  AvgDialog_142851_Content_55 = {
    Text = "Minha Força será compartilhada com você, meu destino estará ligado ao seu. A partir do momento em que O Testamento for assinado, você será o controlador deste planeta, o executor da minha vontade."
  },
  AvgDialog_142851_Content_56 = {
    Text = "Você terá tudo dos seis reinos, até — até que, três anos depois, uma nova disputa Comece e um novo rei nasça."
  },
  AvgDialog_142851_Content_57 = {
    Text = "Você me acompanhará, observando essas almas interessantes, observando a si mesmo, caminhando passo a passo em direção ao abismo. Assim como os reis que vieram antes de você."
  },
  AvgDialog_142851_Content_58 = {
    Text = "Mas eu sei que, mesmo conhecendo as consequências, você não irá resistir."
  },
  AvgDialog_142851_Content_59 = {
    Text = "Você está pensando que é diferente dos quatro mil desafiantes anteriores. Que possui uma vontade capaz de Superar tudo, que jamais cairá no abismo da Força e do desejo..."
  },
  AvgDialog_142851_Content_6 = {
    Text = "Lotan não disse nada, apenas empunhou a lâmina e caminhou em sua direção, sem pressa. Sua testa estava firmemente pressionada contra o chão, seu corpo tremendo diante daquela figura que se aproximava."
  },
  AvgDialog_142851_Content_60 = {
    Text = "Como assino este Testamento?"
  },
  AvgDialog_142851_Content_61 = {
    Text = "O sorriso da Baleia Celestial carregava um cansaço ancestral. Ela já havia visto a mesma história vezes demais. Desta vez, não havia nada de diferente."
  },
  AvgDialog_142851_Content_62 = {
    Text = "...Ganância. Determinação. Você não se preocupa com etiqueta, mas ao menos possui qualidades que me agradam."
  },
  AvgDialog_142851_Content_63 = {
    Text = "Estenda sua mão e coloque-a sobre O Testamento."
  },
  AvgDialog_142851_Content_64 = {
    Text = "Sem hesitar, Lotan estendeu a mão e a pressionou sobre aquela figura formada por Sangue."
  },
  AvgDialog_142851_Content_65 = {
    Text = "Caracteres líquidos e vivos rastejaram para fora do poço de Sangue. Eles escalaram e penetraram pelo braço de Lotan, infiltrando-se sob sua pele."
  },
  AvgDialog_142851_Content_66 = {
    Text = "Nos lugares por onde aqueles caracteres passavam, a Carne e sangue de Lotan rapidamente apodreceu e sofreu Fissão, restando apenas ossos brancos e alvos e Sangue carmesim."
  },
  AvgDialog_142851_Content_67 = {
    Text = "O corpo de Lotan tremia de dor, mas ela não emitiu nenhum som do começo ao fim. Ela abriu bem os olhos, já meio despedaçados, testemunhando tudo aquilo com atenção."
  },
  AvgDialog_142851_Content_68 = {
    Text = "Os caracteres se espalharam pela rede de vasos sanguíneos em direção ao coração, chegando finalmente aos seus olhos. Em um instante, as pupilas de Lotan se transformaram no mesmo vórtice da Baleia Celestial."
  },
  AvgDialog_142851_Content_69 = {
    Text = "Então, o vórtice desapareceu, e a cor das pupilas da Baleia Celestial ficou para sempre em seus olhos, enquanto uma armadura de ossos brancos cobria seu novo corpo nascido."
  },
  AvgDialog_142851_Content_7 = {
    Text = "Um desafiante escolheu a submissão, um desafiante escolheu a fuga, quinze desafiantes escolheram a morte... Parece que nosso último vencedor já foi decidido."
  },
  AvgDialog_142851_Content_70 = {
    Text = "Todo o vazio emitiu uma Resonância grave e profunda, e os rostos suspensos no abismo — os que morreram no Coliseu — abriram a boca ao mesmo tempo, soltando um lamento silencioso."
  },
  AvgDialog_142851_Content_71 = {
    Text = "Eles saudavam seu Novo Rei."
  },
  AvgDialog_142851_Content_72 = {
    Text = "Isso... é a Força da Baleia Celestial..."
  },
  AvgDialog_142851_Content_73 = {
    Text = "Lotan cerrou o punho, sentindo a Força do antigo deus que fluía impetuosamente dentro de si, sentindo seu Elo com este mundo."
  },
  AvgDialog_142851_Content_74 = {
    Text = "Os mundos Devorados pela Baleia Celestial pulsavam em sua percepção, e todas as Vidas criadas e escravizadas pela Baleia Celestial eram como pequenas chamas de vela — bastava um único pensamento para apagá-las todas."
  },
  AvgDialog_142851_Content_75 = {
    Text = "Aquele lago de Sangue se uniu em uma coroa Carmesim, que brilhava resplandecente diante dela."
  },
  AvgDialog_142851_Content_76 = {
    Text = "O Testamento está selado. Nossos destinos se fundiram em um só, irreversivelmente. Por quantos eons eu existí, tanto peso você herdará."
  },
  AvgDialog_142851_Content_77 = {
    Text = "Aproveite bem, Lotan. Já vi muitas almas semelhantes a você. Puras, ardentes, imbatíveis."
  },
  AvgDialog_142851_Content_78 = {
    Text = "Estarei aguardando... aguardando o dia em que você cair no abismo. Eu mergulharei em um novo longo sono... Agora, você pode ir fazer tudo o que deseja."
  },
  AvgDialog_142851_Content_79 = {
    Text = "O Fantasma da Baleia Celestial deixou um Adeus entediante e reabriu a fenda."
  },
  AvgDialog_142851_Content_8 = {
    Text = "A voz veio de todos os lados, carregando um prazer perturbador. Inúmeros Fantasmas nas arquibancadas se levantaram ao mesmo tempo, rostos em constante transformação exibindo sorrisos idênticos."
  },
  AvgDialog_142851_Content_80 = {
    Text = "Você terminou de falar?"
  },
  AvgDialog_142851_Content_81 = {
    Text = "A morada da Baleia Celestial mergulhou em um breve silêncio. Ela não recebeu a recitação e a submissão que esperava — o que encontrou foi um par de olhos de guerreira, ardendo com um desejo incontrolável de batalha."
  },
  AvgDialog_142851_Content_82 = {
    Text = "Então agora... é a sua vez de agir."
  },
  AvgDialog_142851_Content_83 = {
    Text = "Você jamais imaginou que veria confusão nos olhos de Um deus."
  },
  AvgDialog_142851_Content_84 = {
    Text = "Você... o que disse?"
  },
  AvgDialog_142851_Content_85 = {
    Text = "Você disse que eu posso fazer tudo o que quero... Há Apenas uma coisa que quero fazer. Matar você, ou ser morta por você."
  },
  AvgDialog_142851_Content_86 = {
    Text = "Meu hábito é deixar o oponente agir primeiro. Portanto, é a sua vez de agir, Leviatã."
  },
  AvgDialog_142851_Content_87 = {
    Text = "Você acabou de assinar O Testamento..."
  },
  AvgDialog_142851_Content_88 = {
    Text = "Eu prometi que me tornaria o Guardião deste planeta, o executor da sua vontade."
  },
  AvgDialog_142851_Content_89 = {
    Text = "Você é o senhor escravo deste planeta. Combatê-lo em nome deles também é cumprir meu dever."
  },
  AvgDialog_142851_Content_9 = {
    Text = "Um som abafado ecoou. As colunas de pedra do Coliseu desmoronaram atrás de você, fragmentos voando em direção ao céu, desaparecendo nas profundezas daquele céu vermelho-escuro como um pântano."
  },
  AvgDialog_142851_Content_90 = {
    Text = "Você é o devorador de estrelas, sinônimo de massacre e guerra. Lutar é a sua vontade."
  },
  AvgDialog_142851_Content_91 = {
    Text = "Uma piada muito boa, Lotan. Vá embora agora e ainda poderá ter tudo o que Todos desejam possuir. Fique aqui e não obterá nada."
  },
  AvgDialog_142851_Content_92 = {
    Text = "Já disse o que tinha a dizer com clareza."
  },
  AvgDialog_142851_Content_93 = {
    Text = "O Testamento uniu o seu destino ao meu. A minha morte é a sua morte."
  },
  AvgDialog_142851_Content_94 = {
    Text = "Não me importo."
  },
  AvgDialog_142851_Content_95 = {
    Text = "Sua Força não chega nem à metade da minha. Você acabou de obtê-la, não compreende de forma alguma a Força que pretende dominar... Você simplesmente não tem capacidade de me desafiar, Lotan."
  },
  AvgDialog_142851_Content_96 = {
    Text = "Quero tentar."
  },
  AvgDialog_142851_Content_97 = {
    Text = "Hehehe... Hahahaha!!!"
  },
  AvgDialog_142851_Content_98 = {
    Text = "A Baleia Celestial gargalhou. Ela não ria com tanto prazer há mais de dez mil anos."
  },
  AvgDialog_142851_Content_99 = {
    Text = "A gargalhada emergiu das profundezas do vazio, fazendo vibrar cada veia de luz, cada escama, cada rosto flutuando no abismo."
  },
  AvgDialog_142852_Content_1 = {
    Text = "A terceira secção"
  },
  AvgDialog_142852_Content_10 = {
    Text = "Você se virou e viu exatamente duas sombras avançando rapidamente em sua direção —"
  },
  AvgDialog_142852_Content_100 = {
    Text = "Alish olhou, atônito, para a jovem mulher diante dele. Um brilho vermelho-sangue sombrio iluminava sua silhueta. No último momento de sua vida, ele viu a própria essência de sua fé."
  },
  AvgDialog_142852_Content_101 = {
    Text = "Hah... Hahahaha! Que satisfação!"
  },
  AvgDialog_142852_Content_102 = {
    Text = "Imaginei minha própria morte muitas vezes... nenhuma delas me satisfez tanto quanto o que aconteceu hoje."
  },
  AvgDialog_142852_Content_103 = {
    Text = "Obrigado, senhora Lotan."
  },
  AvgDialog_142852_Content_104 = {
    Text = "O general Alish abriu os braços, banhando-se na luz do sol cor de Sangue."
  },
  AvgDialog_142852_Content_106 = {
    Text = "Um golpe de lâmina limpo e preciso relampejou, e a cabeça do velho Alish rolou ao lado do cavalo de guerra morto e das bandeiras partidas."
  },
  AvgDialog_142852_Content_107 = {
    Text = "Na cabeça marcada pelas vicissitudes da vida, havia um sorriso de satisfação. Quanto ao seu fim, o velho Alish nada mais desejava."
  },
  AvgDialog_142852_Content_108 = {
    Text = "Fechando os olhos dele, Lotan se virou e viu o nobre vestido com as roupas de primeiro-ministro, e a criança sob sua faca trêmula."
  },
  AvgDialog_142852_Content_109 = {
    Text = "Lo... Lorde Lotan..."
  },
  AvgDialog_142852_Content_11 = {
    Text = "Um som nauseante e úmido de dilaceração se ergue no ar. Enormes patas de aranha irrompem pelos corpos dos oficiais e dos transeuntes, espirrando sangue espesso com cheiro de ferro por todo você."
  },
  AvgDialog_142852_Content_110 = {
    Text = "Vira? Vira!"
  },
  AvgDialog_142852_Content_111 = {
    Text = "Seguindo a voz de Elian, Lotan virou a cabeça e olhou para a figura oculta na escuridão atrás dela."
  },
  AvgDialog_142852_Content_112 = {
    Text = "Após uma breve luta de alguns segundos, o envenenador da mansão do primeiro-ministro recolheu sua mão trêmula e correu para fora do Coliseu. Diante da morte, a maioria das pessoas sabe o que escolher."
  },
  AvgDialog_142852_Content_113 = {
    Text = "Parece que seu controle sobre as pessoas ao seu redor é bastante limitado."
  },
  AvgDialog_142852_Content_114 = {
    Text = "Senhora Lotan, somos aliados! Lembra?"
  },
  AvgDialog_142852_Content_115 = {
    Text = "Deixe-me viver, deixe-me ir até a Baleia Celestial... Eu lhe darei tudo o que quiser!"
  },
  AvgDialog_142852_Content_116 = {
    Text = "E essa criança... você não quer que {Male=him,Female=her} morra, quer? Eu consigo perceber... Você esteve protegendo {Male=him,Female=her} durante essa luta brutal..."
  },
  AvgDialog_142852_Content_117 = {
    Text = "Os passos da morte continuavam se aproximando de Elian. Sua voz começou a tremer."
  },
  AvgDialog_142852_Content_118 = {
    Text = "Ah!!!——"
  },
  AvgDialog_142852_Content_119 = {
    Text = "O afiado punhal mergulha fundo em seu ombro. Seu grito agonizante ecoa pela arena."
  },
  AvgDialog_142852_Content_12 = {Text = "..."},
  AvgDialog_142852_Content_120 = {
    Text = "Lotan! Se você se aproximar, essa pessoa morrerá por sua causa!"
  },
  AvgDialog_142852_Content_121 = {
    Text = "Você nunca mata inocentes... Você nunca deseja que inocentes morram por sua causa! Isso mesmo, isso mesmo!! Eu não me enganei a seu respeito!!"
  },
  AvgDialog_142852_Content_122 = {
    Text = "O punhal se retorce dentro de você, acompanhado pelos seus gritos incessantes."
  },
  AvgDialog_142852_Content_123 = {
    Text = "Lotan permanece calma, como se não pudesse ouvir nada, carregando sua grande espada enquanto caminha em direção a Elian, com passos tão estáveis quanto um passeio vespertino."
  },
  AvgDialog_142852_Content_124 = {
    Text = "Eu admiro pessoas puras. Intenção de matar pura, Força pura, glória pura, sabedoria e astúcia puras."
  },
  AvgDialog_142852_Content_125 = {
    Text = "Mas você, Elian..."
  },
  AvgDialog_142852_Content_126 = {
    Text = "Lotan balançou a cabeça com desdém."
  },
  AvgDialog_142852_Content_127 = {
    Text = "Você nem sequer descobriu o que me importa."
  },
  AvgDialog_142852_Content_128 = {
    Text = "Você não é nada."
  },
  AvgDialog_142852_Content_13 = {
    Text = "Duas rajadas de vento passaram por você, e um líquido morno espirrou sobre seu corpo."
  },
  AvgDialog_142852_Content_130 = {
    Text = "Uma lâmina limpa e precisa passou num relance. Este político que atravessou seis nações, com olhos surpresos e sem Força, encontrou seu fim."
  },
  AvgDialog_142852_Content_131 = {
    Text = "No Coliseu inteiro restavam apenas dois seres ainda capazes de respirar. A grande espada nas mãos de Lotan estava ensopada de Sangue, e aquele Olhar sem qualquer calor se voltou para você."
  },
  AvgDialog_142852_Content_14 = {
    Text = "Sem sentir dor, e a morte ainda não havia Chegado. Você afastou as mãos que cobriam seus Olhos e viu duas cabeças recém-decepadas, com seus olhos ressentidos fixos em você."
  },
  AvgDialog_142852_Content_15 = {Text = "ARGH!!"},
  AvgDialog_142852_Content_16 = {
    Text = "Você recuou rapidamente dois passos, quase tropeçando na metade do cadáver de Graco."
  },
  AvgDialog_142852_Content_17 = {
    Text = "Ha, as irmãs Vaughn, duas caçadoras de recompensas tão famosas. Os reis dos seis reinos tentaram de inúmeras maneiras recrutá-las, sem jamais conseguir."
  },
  AvgDialog_142852_Content_18 = {
    Text = "Agora, elas encontraram a única caçada em que falharam."
  },
  AvgDialog_142852_Content_19 = {
    Text = "Em meio aos gritos ensurdecedores do Público de Fantasmas, Elian cruzou satisfeito sobre os cadáveres."
  },
  AvgDialog_142852_Content_2 = {
    Text = "As altas paredes circulares de pedra do Coliseu se erguiam imponentes, e as arquibancadas estavam lotadas de Fantasmas atentos."
  },
  AvgDialog_142852_Content_20 = {
    Text = "A ordem foi diferente do que eu esperava, mas não importa. Nossos inimigos já são pouquíssimos. Agora, acho que Você precisa de descanso..."
  },
  AvgDialog_142852_Content_21 = {
    Text = "Um estrondo de cascos de cavalo acompanhado de um vento uivante interrompeu as palavras de Elian, surgindo de repente atrás de Elian e de Você."
  },
  AvgDialog_142852_Content_22 = {
    Text = "Antes que Você pudesse reagir, Lotan te ergueu e jogou para o lado."
  },
  AvgDialog_142852_Content_23 = {
    Text = "<RedBigShake:Morra —!>"
  },
  AvgDialog_142852_Content_24 = {
    Text = "O relincho estridente do cavalo de guerra ecoou pelo Coliseu. Em meio à poeira, Um general vestindo uma armadura antiga deteve o corcel em disparada e cravou os Espinhos do estandarte que segurava no peito de Um Cavaleiro que não conseguiu se esquivar a tempo."
  },
  AvgDialog_142852_Content_25 = {
    Text = "A poeira que se dispersava lentamente delineava uma silhueta não muito imponente. Ele puxou suavemente as rédeas, virando o cavalo de guerra, e seus olhos, acostumados a montanhas de cadáveres e mares de Sangue, olharam para vocês com calma."
  },
  AvgDialog_142852_Content_26 = {
    Text = "Você acidentalmente cruzou o olhar com aqueles Olhos. Uma poderosa sensação de opressão fez suas pernas fraquejarem, Quase sem conseguir se manter de pé."
  },
  AvgDialog_142852_Content_27 = {
    Text = "A poeira se dissipou. Você viu aquela armadura antiga da lenda, marcada por setenta rachaduras, e aquele cavalo de guerra encouraçado que havia pisado as terras de seis nações, soprando vapor com arrogância."
  },
  AvgDialog_142852_Content_28 = {
    Text = "Quatro cabeças pingando Sangue pendiam ao lado do cavalo de guerra — um hábito que o velho cultivara desde pequeno."
  },
  AvgDialog_142852_Content_29 = {
    Text = "General Alish."
  },
  AvgDialog_142852_Content_3 = {
    Text = "Nas profundezas do céu vermelho-escuro, semelhante a um pântano, uma sombra enorme como a de uma baleia nadava lentamente."
  },
  AvgDialog_142852_Content_30 = {
    Text = "Você notou que o tom de Lotan mudou visivelmente pela primeira vez. Sua voz estava rouca e cheia de Empolgação, como um leão que farejou a presa."
  },
  AvgDialog_142852_Content_31 = {
    Text = "Diga-me, como se chama meu oponente."
  },
  AvgDialog_142852_Content_32 = {
    Text = "Você pode me chamar de Lotan."
  },
  AvgDialog_142852_Content_33 = {
    Text = "Lotan... A maioria das pessoas neste mundo que valem a pena enfrentar, eu já ouvi falar, mas não me recordo desse nome."
  },
  AvgDialog_142852_Content_34 = {
    Text = "Talvez seja porque a maioria das pessoas que ouviram esse nome já esteja morta. Isso não importa. Daqui a cinco minutos, você vai se lembrar do meu nome."
  },
  AvgDialog_142852_Content_35 = {
    Text = "Ha... Este mundo frequentemente apresenta mudanças às quais tenho dificuldade de me Adaptar. Talvez os jovens de hoje tenham algo que me faça hesitar."
  },
  AvgDialog_142852_Content_36 = {
    Text = "Já se passou meia hora desde o início da corrida de eliminação. Ter sobrevivido até agora significa que você possui uma habilidade à altura de sua arrogância."
  },
  AvgDialog_142852_Content_37 = {
    Text = "O senhor está enganado, General Alish. Não somos seus inimigos."
  },
  AvgDialog_142852_Content_38 = {
    Text = "Saia do caminho, Elian."
  },
  AvgDialog_142852_Content_39 = {
    Text = "(em voz baixa) Senhora Lotan, por favor, não se esqueça do plano que traçamos anteriormente. Agora devemos primeiro eliminar os outros inimigos. Alish está velho e debilitado; quando ele estiver sem forças..."
  },
  AvgDialog_142852_Content_4 = {
    Text = "Ele sempre gostou tanto de assistir ao espetáculo?"
  },
  AvgDialog_142852_Content_40 = {
    Text = "Eu disse, saia do caminho."
  },
  AvgDialog_142852_Content_41 = {
    Text = "Elian já havia visto muitas pessoas perigosas. A voz de Lotan não era nada intensa comparada a elas, mas aquelas palavras frias fizeram Elian sentir um medo mais intenso do que jamais havia sentido."
  },
  AvgDialog_142852_Content_42 = {
    Text = "Ele não pensou por muito tempo e, com O Semblante impassível, abriu o Caminho."
  },
  AvgDialog_142852_Content_43 = {
    Text = "Não restam muitas pessoas neste Coliseu. Há Apenas um oponente digno do meu desafio."
  },
  AvgDialog_142852_Content_44 = {
    Text = "Lotan colocou a mão no cabo da espada gigante e caminhou em direção a Alish."
  },
  AvgDialog_142852_Content_45 = {
    Text = "As Aparições nas arquibancadas ficam completamente em silêncio, seus rostos sem feições se voltando em perfeita sincronia para acompanhar os passos de Lotan."
  },
  AvgDialog_142852_Content_46 = {
    Text = "O zumbido de baixa frequência no ar tornou-se ainda mais nítido, como uma expectativa antiga e cheia de Ganância."
  },
  AvgDialog_142852_Content_47 = {
    Text = "Eu vi você lutar, jovem. Em setenta anos de batalhas, jamais encontrei um oponente tão forte quanto você."
  },
  AvgDialog_142852_Content_48 = {
    Text = "Neste Coliseu habitam os inimigos mais poderosos do mundo, e todos querem atacar primeiro — mas você não. Você sempre espera seu oponente desembainhar a espada primeiro..."
  },
  AvgDialog_142852_Content_49 = {
    Text = "Pode me dizer por quê?"
  },
  AvgDialog_142852_Content_5 = {
    Text = "Lotan balançou a cabeça e arrancou a espada gigante do cadáver aos seus pés."
  },
  AvgDialog_142852_Content_50 = {
    Text = "Porque... um inimigo que desembainhou a espada fica um pouco mais forte."
  },
  AvgDialog_142852_Content_51 = {
    Text = "Um pouco... mais forte?"
  },
  AvgDialog_142852_Content_52 = {
    Text = "Apenas me interesso por algo mais forte. Erga seu estandarte de guerra, Alish."
  },
  AvgDialog_142852_Content_53 = {
    Text = "As palavras de Lotan não carregavam qualquer provocação. Ela pôs a mão sobre a grande espada, os Olhos fixos naquele general já envelhecido, seus passos solenes como os de um peregrino."
  },
  AvgDialog_142852_Content_54 = {
    Text = "Heh... Hahahaha!"
  },
  AvgDialog_142852_Content_55 = {
    Text = "O velho general ergueu a cabeça e gargalhou. Seu cavalo de guerra permanecia imóvel, homem e animal sozinhos no centro do Coliseu, enquanto a bandeira vermelha de Sangue voava Bagunçada ao vento."
  },
  AvgDialog_142852_Content_56 = {
    Text = "Muito parecido. Realmente muito parecido... Se fôssemos um pouco mais jovens, talvez pudéssemos ver outro nós mesmos neste mundo."
  },
  AvgDialog_142852_Content_57 = {
    Text = "De qualquer forma... espero que nenhum de nós decepcione o outro!"
  },
  AvgDialog_142852_Content_58 = {
    Text = "A voz de Alish de repente se eleva, suas pernas habilmente guiando sua montaria. O corcel que o carregou por inúmeras campanhas avança disparado, seu relincho penetrante ecoando pela vasta arena —"
  },
  AvgDialog_142852_Content_59 = {
    Text = "A bandeira voou, como um relâmpago vermelho rasgando a poeira no centro do Coliseu, avançando em disparada em direção a Lotan."
  },
  AvgDialog_142852_Content_6 = {
    Text = "Os ossos perfurados rangeram contra a lâmina com um som que fazia doer os dentes, o corpo robusto foi rasgado ao meio, e aqueles olhos ressentidos rolaram junto com a metade do corpo para dentro de uma sarjeta cheia de Sangue."
  },
  AvgDialog_142852_Content_60 = {
    Text = "Você vê os cantos da boca de Lotan se curvarem, sem conseguir conter um sorriso. É a primeira vez que você vê Lotan sorrir."
  },
  AvgDialog_142852_Content_61 = {
    Text = "Ela desembainhou a grande espada e avançou de frente contra aquele relâmpago vermelho —"
  },
  AvgDialog_142852_Content_62 = {Text = "..."},
  AvgDialog_142852_Content_63 = {Text = "BOOM!! —"},
  AvgDialog_142852_Content_64 = {
    Text = "A grande espada branca colidiu com o estandarte vermelho, e um som agudo e estridente fez vibrar os tímpanos de todos."
  },
  AvgDialog_142852_Content_65 = {
    Text = "Os cascos de ferro do cavalo levantaram nuvens de poeira, e as silhuetas de Lotan e Alish se cruzaram no campo de batalha sombrio."
  },
  AvgDialog_142852_Content_66 = {
    Text = "A cada colisão, a sombra da enorme baleia no céu estremecia violentamente, Como Se estivesse saboreando uma rara Iguaria Macabra."
  },
  AvgDialog_142852_Content_67 = {Text = "..."},
  AvgDialog_142852_Content_68 = {
    Text = "General Alish... Senhora Lotan..."
  },
  AvgDialog_142852_Content_69 = {
    Text = "Que batalha surpreendente..."
  },
  AvgDialog_142852_Content_7 = {
    Text = "Ele disse há pouco... como era mesmo o nome dele?"
  },
  AvgDialog_142852_Content_70 = {
    Text = "Você se esforça para capturar as silhuetas dos dois com seus Olhos, mas isso torna muito difícil distingui-los."
  },
  AvgDialog_142852_Content_71 = {
    Text = "Vira, aja agora."
  },
  AvgDialog_142852_Content_72 = {
    Text = "Sim, Senhor Elian."
  },
  AvgDialog_142852_Content_73 = {
    Text = "Um som nauseante e úmido de dilaceração se ergue no ar. Enormes patas de aranha irrompem pelos corpos dos oficiais e dos transeuntes, espirrando sangue espesso com cheiro de ferro por todo você."
  },
  AvgDialog_142852_Content_74 = {
    Text = "Aquele é... o feiticeiro envenenador da mansão do Primeiro-Ministro?! Senhora Lotan! Cuidado..."
  },
  AvgDialog_142852_Content_75 = {
    Text = "Você não terminou de falar, quando uma sensação gelada tocou sua pele."
  },
  AvgDialog_142852_Content_76 = {
    Text = "Shh... passarinho. Você sempre foi fiel a mim. Agora, vai me trair por alguém que nem conhece?"
  },
  AvgDialog_142852_Content_77 = {
    Text = "Eu... mas..."
  },
  AvgDialog_142852_Content_78 = {
    Text = "Eu disse que, quando eu obtiver a Coroa da Baleia Celeste e me tornar o Rei Supremo dos Seis Reinos, sua família e você receberão as recompensas que merecem."
  },
  AvgDialog_142852_Content_79 = {
    Text = "Mas agora, cale a boca para mim."
  },
  AvgDialog_142852_Content_8 = {
    Text = "Graco... o Gladiador mais famoso de todo o norte, que jamais sofreu uma derrota nos Coliseus dos seis reinos..."
  },
  AvgDialog_142852_Content_80 = {
    Text = "A garganta se move. Apenas quem foi escravo sabe o quão poderosa é a tentação nessas palavras de Elian."
  },
  AvgDialog_142852_Content_81 = {
    Text = "Você observa o envenenador se esconder, deslizando para dentro da poeira redemoinhante. Você não diz mais nada."
  },
  AvgDialog_142852_Content_82 = {Text = "Sim?"},
  AvgDialog_142852_Content_83 = {
    Text = "O general, que galopava a toda velocidade, avistou uma figura se dissolvendo na fumaça e franzou o cenho. Isso fez sua reação atrasar um instante."
  },
  AvgDialog_142852_Content_84 = {
    Text = "Quando aquela espada enorme e feroz veio novamente em sua direção, ele Apenas conseguiu erguer o estandarte militar para bloqueá-la."
  },
  AvgDialog_142852_Content_85 = {Text = "..."},
  AvgDialog_142852_Content_86 = {
    Text = "Um impacto de Força colossal fez o cavalo de guerra tropeçar e cair violentamente ao chão. O estandarte vermelho se partiu em dois pedaços, e uma enorme espada repousou sobre seu pescoço."
  },
  AvgDialog_142852_Content_87 = {
    Text = "Seus movimentos ficaram lentos, Alish."
  },
  AvgDialog_142852_Content_88 = {
    Text = "... Seu aliado te traiu."
  },
  AvgDialog_142852_Content_89 = {
    Text = "Isso importa?"
  },
  AvgDialog_142852_Content_9 = {
    Text = "Você já viu muitos mortos, mas a cena diante de seus olhos ainda fez seu estômago revirar."
  },
  AvgDialog_142852_Content_90 = {
    Text = "O que você disse...?"
  },
  AvgDialog_142852_Content_91 = {
    Text = "Lotan soltou um suave suspiro, repleto de lamento."
  },
  AvgDialog_142852_Content_92 = {
    Text = "Você está muito perto, Alish, mas ainda não é suficiente. Além da Força e do combate, você ainda tem outros anseios — honra."
  },
  AvgDialog_142852_Content_93 = {
    Text = "Você se importa demais com essas coisas tolas. Você ainda não é puro o suficiente."
  },
  AvgDialog_142852_Content_94 = {
    Text = "Lotan abriu os olhos, balançou a cabeça, completamente indiferente à sombra que se escondia atrás dela."
  },
  AvgDialog_142852_Content_95 = {
    Text = "Você acredita que, com a ajuda de Elian, vocês juntos me enfrentando, a vitória seria desonrosa."
  },
  AvgDialog_142852_Content_96 = {
    Text = "Não deveria ser assim? Duas pessoas de habilidades e pensamentos semelhantes, um duelo justo..."
  },
  AvgDialog_142852_Content_97 = {
    Text = "Veja quantas palavras você usou. Honra, justiça, dignidade... são todas correntes que os fracos forjam para si mesmos."
  },
  AvgDialog_142852_Content_98 = {
    Text = "O guerreiro nasce apenas para combater. O combate... é apenas combate. Não tem relação com mais nada."
  },
  AvgDialog_142852_Content_99 = {
    Text = "A sombra no céu pousou, emitindo um rugido satisfeito."
  },
  AvgDialog_142853_Content_1 = {
    Text = "A segunda secção"
  },
  AvgDialog_142853_Content_10 = {
    Text = "Eu disse... Senhor Lotan... o senhor não poderia andar um pouco mais devagar..."
  },
  AvgDialog_142853_Content_100 = {
    Text = "Senhora Lotan... não acredite no que ele diz! Ele é um mentiroso... Estando ao lado dele, vi inúmeros crimes que cometeu..."
  },
  AvgDialog_142853_Content_101 = {
    Text = "Tenho certeza de que a senhora não cooperaria com alguém como ele..."
  },
  AvgDialog_142853_Content_102 = {
    Text = "Você acenou repetidamente para Lotan. Queria alertá-la sobre o quão astuto Elian era."
  },
  AvgDialog_142853_Content_103 = {
    Text = "De escravo a Mercador, de Mercador a nobre, de nobre a primeiro-ministro, Elian percorreu um Caminho árduo deixando inúmeras pegadas, cada uma delas repleta de mentiras e Sangue."
  },
  AvgDialog_142853_Content_104 = {
    Text = "Mas Lotan não olhou para Você. Ela virou a cabeça e contemplou o céu vermelho-escuro. A enorme sombra em forma de baleia ainda se movia lentamente, seu contorno coberto de espinhos aparecendo e desaparecendo."
  },
  AvgDialog_142853_Content_105 = {Text = "Afaste-se."},
  AvgDialog_142853_Content_106 = {
    Text = "Você se afastou mecanicamente. Lotan passou ao seu lado, abaixou a cabeça e olhou fixamente para o primeiro-ministro à sua frente. A luz vermelho-escura delineou atrás dela uma silhueta afiada."
  },
  AvgDialog_142853_Content_107 = {
    Text = "Você é muito mais interessante do que sua Ordem de Cavaleiros, Elian. Não me importo com que tipo de pessoa você é, nem me preocupo com quando irá me trair. Você pode me ser útil, e isso é suficiente."
  },
  AvgDialog_142853_Content_108 = {
    Text = "Aceito seu pedido. Não interfira em meus combates — essa é minha única exigência."
  },
  AvgDialog_142853_Content_109 = {
    Text = "Senhora Lotan... a senhora..."
  },
  AvgDialog_142853_Content_11 = {
    Text = "Durante todo o Caminho, o senhor mal falou, só se preocupou em matar e caminhar, sem descansar..."
  },
  AvgDialog_142853_Content_110 = {
    Text = "A sede de poder que permeia o ar lava sobre você como uma maré. Um sorriso amargo se insinua em seu rosto. Todos aqui são iguais — você não deveria ter esperado algo diferente."
  },
  AvgDialog_142853_Content_111 = {
    Text = "Elian abriu um sorriso; em sua expressão não havia nem um traço de alegria além do esperado, Como Se aquela fosse uma negociação cuja vitória já estava garantida."
  },
  AvgDialog_142853_Content_112 = {
    Text = "Ele se virou e caminhou em direção às arquibancadas à beira do Coliseu."
  },
  AvgDialog_142853_Content_113 = {
    Text = "As informações de Todos, as equipes que formarão, o momento em que se romperão, e a ordem de desafios que mais lhe trará prazer — já pensei em tudo isso por você."
  },
  AvgDialog_142853_Content_114 = {
    Text = "Desfrute desta batalha, Senhora Lotan."
  },
  AvgDialog_142853_Content_12 = {
    Text = "Você prefere calar a boca sozinho, ou quer que eu enfie minha espada nela?"
  },
  AvgDialog_142853_Content_13 = {Text = "..."},
  AvgDialog_142853_Content_14 = {
    Text = "Você cobre a boca com força. O Olhar de Lotan não se detém sobre Você. Ela observa os Arredores, passando a mão sobre um fragmento de coluna de pedra quebrada."
  },
  AvgDialog_142853_Content_15 = {
    Text = "A superfície cortada da coluna estava coberta de veios negros, semelhantes a vasos sanguíneos, como se o tecido de algum ser vivo estivesse crescendo ali."
  },
  AvgDialog_142853_Content_16 = {
    Text = "Aquilo é..."
  },
  AvgDialog_142853_Content_17 = {
    Text = "Você encosta o ouvido na coluna de pedra e ouve vagamente um ritmo extremamente grave, como se alguma criatura enorme respirasse lentamente nas profundezas da pedra."
  },
  AvgDialog_142853_Content_18 = {
    Text = "Uma náusea inexplicável e um impulso de matar invadem seu corpo, e Você recua rapidamente."
  },
  AvgDialog_142853_Content_19 = {
    Text = "Esta coisa... está viva?!"
  },
  AvgDialog_142853_Content_2 = {
    Text = "É este o Caminho que você trouxe?"
  },
  AvgDialog_142853_Content_20 = {
    Text = "Segundo a lenda, a Baleia Celestial criou este mundo com Seu corpo, e os povos dos seis reinos existem sobre Sua forma."
  },
  AvgDialog_142853_Content_21 = {
    Text = "Parece que já estamos muito perto dela."
  },
  AvgDialog_142853_Content_22 = {
    Text = "Lotan se dirige a uma mesa de pedra no centro da praça. Aquela mesa feita de lápis-lazúli, com seu acabamento refinado e material precioso, destoa completamente daquele lugar desolado."
  },
  AvgDialog_142853_Content_23 = {
    Text = "A superfície da mesa estava coberta por uma camada de escamas finas e úmidas, que se abriam e fechavam lentamente sob a fraca luz, no mesmo ritmo da respiração que Você acabara de ouvir."
  },
  AvgDialog_142853_Content_24 = {
    Text = "Lotan coloca os dois Sigilos de Osso sobre ela. No instante em que as escamas tocam os Sigilos, elas se contraem como inúmeros dedos agarrando uma presa e devoram os dois Sigilos por inteiro."
  },
  AvgDialog_142853_Content_25 = {
    Text = "Nossos selos ósseos!!!"
  },
  AvgDialog_142853_Content_26 = {
    Text = "Ah! Dois novos desafiantes!"
  },
  AvgDialog_142853_Content_27 = {
    Text = "Enquanto Você avança em direção à mesa de pedra, um contorno em forma humana emerge lentamente do centro da mesa."
  },
  AvgDialog_142853_Content_28 = {
    Text = "Seu rosto muda incessantemente — ora é um rei, ora um Cavaleiro, ora algo que Você não consegue identificar."
  },
  AvgDialog_142853_Content_29 = {
    Text = "Sua voz parece vir de baixo de um mar de Sangue, e cada sílaba carrega uma estranha Ressonância."
  },
  AvgDialog_142853_Content_3 = {
    Text = "Estamos procurando o Coliseu, não ruínas. Este lugar parece estar abandonado há muitos anos."
  },
  AvgDialog_142853_Content_30 = {
    Text = "Sou o Fantasma da Baleia Celestial, Seu servo mais fiel, e também o administrador e o Público deste Coliseu."
  },
  AvgDialog_142853_Content_31 = {
    Text = "Vocês passaram por inúmeros perigos e finalmente chegaram até aqui pela própria Força e sabedoria. Vocês são o orgulho dos seis reinos, os mais poderosos e resilientes..."
  },
  AvgDialog_142853_Content_32 = {
    Text = "Pode poupar as palavras desnecessárias."
  },
  AvgDialog_142853_Content_33 = {
    Text = "......Você é bastante rude, desafiante. Felizmente, a Baleia Celestial jamais se importa com essas coisas."
  },
  AvgDialog_142853_Content_34 = {
    Text = "O que Ela se importa é com apenas uma coisa: Força. Força pura, sem a menor impureza."
  },
  AvgDialog_142853_Content_35 = {
    Text = "Bem-vindo, bem-vindo ao Coliseu da Baleia Celestial, bem-vindo ao palco da Força pura——"
  },
  AvgDialog_142853_Content_36 = {
    Text = "O Fantasma ergueu os dois braços, e um som de baixa frequência, vasto como o canto de uma baleia, emanou de seu interior, atravessando seus ossos e Ressonando dentro de sua cavidade craniana."
  },
  AvgDialog_142853_Content_37 = {
    Text = "!!! Isso é..."
  },
  AvgDialog_142853_Content_38 = {
    Text = "A canção se propaga para fora. Por onde passa, o céu é tingido de um vermelho sombrio. As ruínas em colapso, unidas por algum limo não identificável, se fundem em uma grande e antiga arena."
  },
  AvgDialog_142853_Content_39 = {
    Text = "As enormes esculturas de divindades ao redor exibiam gestos diferentes, observando com olhos de compaixão ou raiva as criaturas insignificantes como formigas a seus pés."
  },
  AvgDialog_142853_Content_4 = {
    Text = "Eu me lembro muito bem do mapa, deveria ser este lugar sem dúvida... Mas por que está diferente do que estava registrado?"
  },
  AvgDialog_142853_Content_40 = {
    Text = "Uma dúzia de desafiantes está espalhada pela plataforma, avaliando você."
  },
  AvgDialog_142853_Content_41 = {
    Text = "Um, dois, três... quinze, dezesseis."
  },
  AvgDialog_142853_Content_42 = {
    Text = "Há vinte Sigilos de Osso no total — mais duas pessoas deveriam estar chegando..."
  },
  AvgDialog_142853_Content_43 = {
    Text = "Não há mais, desafiantes. Esses dois Sigilos já foram destruídos na rodada anterior."
  },
  AvgDialog_142853_Content_44 = {
    Text = "Parabéns. Por ser o último a chegar, você conquista a honra de ter a atenção total de todos —"
  },
  AvgDialog_142853_Content_45 = {
    Text = "Entre as risadas leves do Fantasma, dezesseis olhares mal-intencionados se voltaram para vocês."
  },
  AvgDialog_142853_Content_46 = {
    Text = "Aquela pessoa parece tão familiar... Acho que já a vi em algum cartaz de promoção de uma arena de gladiadores?"
  },
  AvgDialog_142853_Content_47 = {
    Text = "Aquela roupa... parece pertencer à organização de assassinos chamada Dedo Mínimo! Não esperava encontrar alguém deles aqui..."
  },
  AvgDialog_142853_Content_48 = {
    Text = "Você sabe bastante."
  },
  AvgDialog_142853_Content_49 = {
    Text = "Não posso falar nas reuniões da Ordem dos Cavaleiros, mas já assisti a muitas como ouvinte. O Senhor Elian nos contou muitas coisas..."
  },
  AvgDialog_142853_Content_5 = {
    Text = "Você olha para os muros em ruínas ao redor, erodidos por anos de vento, e coça a cabeça."
  },
  AvgDialog_142853_Content_50 = {
    Text = "Ah! Olhe ali!! Aquela pessoa com uma armadura antiga!"
  },
  AvgDialog_142853_Content_51 = {
    Text = "É o general mais valente dos Seis Reinos! Ele já matou sozinho o rei de um país inimigo no campo de batalha, e cresci ouvindo suas histórias!"
  },
  AvgDialog_142853_Content_52 = {
    Text = "Um lendário vivo! Não esperava... não esperava encontrá-lo aqui!"
  },
  AvgDialog_142853_Content_53 = {
    Text = "Lotan ignorou seus gritos de empolgação incontrolável. Ela passou os olhos pelos participantes e se apoiou em uma coluna de pedra, fechando os olhos."
  },
  AvgDialog_142853_Content_54 = {
    Text = "Antes de a Ordem dos Cavaleiros participar desta disputa, eu e a senhora fizemos uma aposta sobre quem seria a pessoa a entrar no palácio da Baleia Celestial."
  },
  AvgDialog_142853_Content_55 = {
    Text = "Você se saiu muito bem, pardal. Depois que este jogo entediante terminar, a senhora vai me dever uma boa quantia."
  },
  AvgDialog_142853_Content_56 = {
    Text = "Um som nauseante e úmido de dilaceração se ergue no ar. Enormes patas de aranha irrompem pelos corpos dos oficiais e dos transeuntes, espirrando sangue espesso com cheiro de ferro por todo você."
  },
  AvgDialog_142853_Content_57 = {
    Text = "E... Senhor Elian..."
  },
  AvgDialog_142853_Content_58 = {
    Text = "Voz suave, passos firmes, um manto largo feito de tecido precioso, o aroma de seu perfume de zimbro... Mesmo reduzido a cinzas, você seria capaz de reconhecê-lo."
  },
  AvgDialog_142853_Content_59 = {
    Text = "O senhor... como o senhor mesmo veio... quero dizer..."
  },
  AvgDialog_142853_Content_6 = {
    Text = "O rei escreveu em seu diário que as paredes aqui eram feitas de Ouro, que mensageiros divinos de seis asas sobrevoavam o céu daqui, que mel e vinho corriam pelos rios daqui..."
  },
  AvgDialog_142853_Content_60 = {
    Text = "O senhor pediu à Ordem dos Cavaleiros que conquistasse a Coroa em seu nome, eu pensei..."
  },
  AvgDialog_142853_Content_61 = {
    Text = "Você achou que eu depositaria toda a minha esperança em uma Ordem dos Cavaleiros que não consegue nem vencer mercenários? Eu já lhe ensinei, pardal: nunca coloque todos os ovos na mesma cesta."
  },
  AvgDialog_142853_Content_62 = {
    Text = "Por favor, tenha um pouco de fé no bondoso Elian. A grande Baleia Celestial sempre concede sua Benção aos bons."
  },
  AvgDialog_142853_Content_63 = {
    Text = "O nobre sorriu com elegância. O Olhar dele nunca se afastou de Lotan."
  },
  AvgDialog_142853_Content_64 = {
    Text = "Esta é... sua amiga?"
  },
  AvgDialog_142853_Content_65 = {
    Text = "Bem, talvez não exatamente..."
  },
  AvgDialog_142853_Content_66 = {
    Text = "Lotan. Uma guerreira."
  },
  AvgDialog_142853_Content_67 = {
    Text = "É um prazer conhecê-la, senhora Lotan. Espero que meus servos não tenham lhe causado problemas."
  },
  AvgDialog_142853_Content_68 = {Text = "Chanceler?"},
  AvgDialog_142853_Content_69 = {
    Text = "O Olhar de Lotan percorreu os ornamentos de suas vestes e da espada presa à cintura. Mesmo para quem não se importava com a política dos Seis Reinos, a Marca do Chanceler ainda era bastante fácil de identificar."
  },
  AvgDialog_142853_Content_7 = {
    Text = "O que aconteceu com esta praça que parece uma ruína agora... Também não há ninguém verificando os selos de osso."
  },
  AvgDialog_142853_Content_70 = {
    Text = "Não passa de um título honorário, cuja única utilidade é poupar o tempo das apresentações."
  },
  AvgDialog_142853_Content_71 = {
    Text = "Elian sorriu e se sentou na coluna de pedra diante de Lotan."
  },
  AvgDialog_142853_Content_72 = {
    Text = "Você trouxe meu servo até aqui, mas minha Ordem dos Cavaleiros desapareceu. Creio que já entendi mais ou menos o que aconteceu no Caminho."
  },
  AvgDialog_142853_Content_73 = {
    Text = "Sua Ordem dos Cavaleiros morreu de forma bastante banal. Doze pessoas, sem sequer tocar na armadura de um guerreiro de baixo nível."
  },
  AvgDialog_142853_Content_74 = {
    Text = "E você, facilmente se tornou o vencedor daquela batalha."
  },
  AvgDialog_142853_Content_75 = {
    Text = "Você parece não ter o menor interesse na morte deles."
  },
  AvgDialog_142853_Content_76 = {
    Text = "Ah, não, não, não, a senhora me mal interpretou, Senhora Lotan..."
  },
  AvgDialog_142853_Content_77 = {
    Text = "Elian deu uma gargalhada e balançou a cabeça."
  },
  AvgDialog_142853_Content_78 = {
    Text = "Meus Cavaleiros são boas crianças, leais, dedicados... mas este é o Coliseu da Baleia Celestial. Os fracos encontraram o fim que lhes cabia, e isso não me preocupa."
  },
  AvgDialog_142853_Content_79 = {
    Text = "O que me preocupa é você, Senhora Lotan. Uma guerreira poderosa, que ama espadas, matança e Sangue, disposta a oferecer tudo pela Coroa forjada em Sangue..."
  },
  AvgDialog_142853_Content_8 = {
    Text = "Ei! Espere por mim..."
  },
  AvgDialog_142853_Content_80 = {
    Text = "O ritmo de fala de Elian foi acelerando cada vez mais. O ar impregnado de matança e sede de poder o envolvia, fazendo seu coração endurecido pelos anos pulsar de forma incontrolável."
  },
  AvgDialog_142853_Content_81 = {
    Text = "Parecendo perceber sua própria falta de compostura, ele respirou fundo e recuou meio passo."
  },
  AvgDialog_142853_Content_82 = {
    Text = "Acho que podemos cooperar."
  },
  AvgDialog_142853_Content_83 = {
    Text = "Você acha que sou uma pessoa que gosta de cooperar?"
  },
  AvgDialog_142853_Content_84 = {
    Text = "Os fracos sempre têm o hábito de se agrupar, você certamente não é assim. Mas, todo mundo tem necessidade de cooperação em algum momento, e você não é exceção."
  },
  AvgDialog_142853_Content_85 = {
    Text = "Lotan ainda não havia respondido quando inúmeros Fantasmas idênticos apareceram nos assentos do Coliseu, lotando as densas arquibancadas do Público, e uma voz semelhante ao canto de uma baleia ecoou novamente por todo o vasto Coliseu."
  },
  AvgDialog_142853_Content_86 = {
    Text = "Muito bem, desafiantes, já não conseguimos mais esperar. A prova final está prestes a começar neste glorioso Coliseu!"
  },
  AvgDialog_142853_Content_87 = {
    Text = "Quando o último vencedor surgir, uma Porta para o palácio da Baleia Celestial será aberta para ele!"
  },
  AvgDialog_142853_Content_88 = {
    Text = "Além dessa Porta, há glória infinita, riqueza, poder — tudo!"
  },
  AvgDialog_142853_Content_89 = {
    Text = "Escolher o vencedor... quais são as regras?"
  },
  AvgDialog_142853_Content_9 = {
    Text = "Enquanto você murmurava sozinho diante do antigo pedestal de pedra, Lotan caminhou em direção ao centro da enorme praça."
  },
  AvgDialog_142853_Content_90 = {
    Text = "Regras? Hehehe... Hahahaha! Regras?!..."
  },
  AvgDialog_142853_Content_91 = {
    Text = "As gargalhadas exageradas dos Fantasmas fizeram doer os tímpanos de Todos dentro do Coliseu. Entre as risadas de Loucura, eles pararam de falar e olharam com expectativa para o centro do vasto Coliseu."
  },
  AvgDialog_142853_Content_92 = {
    Text = "Mas... ele ainda não disse quais são as regras..."
  },
  AvgDialog_142853_Content_93 = {
    Text = "Ele já disse. \"O último vencedor\", Apenas Um. Essa é a única regra, passarinho."
  },
  AvgDialog_142853_Content_94 = {
    Text = "Matar, desafiar, aliar-se, trair... Dezoito participantes, apenas um de pé pode passar por aquela Porta."
  },
  AvgDialog_142853_Content_95 = {
    Text = "O sorriso familiar voltou ao rosto de Elian."
  },
  AvgDialog_142853_Content_96 = {
    Text = "O que Você enfrentará será o grupo de pessoas mais poderosas deste mundo."
  },
  AvgDialog_142853_Content_97 = {
    Text = "Por favor, não me entenda mal, não tenho nenhuma Dúvida sobre sua Força, Senhora Lotan."
  },
  AvgDialog_142853_Content_98 = {
    Text = "Mas imagino que Você também não gostaria de ter seu prazer perturbado por pessoas tediosas enquanto desfruta daquelas mortes deliciosas, não é?"
  },
  AvgDialog_142853_Content_99 = {
    Text = "Lotan ergueu a cabeça com seriedade pela primeira vez. Ela viu um rosto com um sorriso gentil, e sobre ele, aqueles Olhos que pareciam capazes de enxergar tudo."
  },
  AvgDialog_142854_Content_1 = {
    Text = "A quinta secção"
  },
  AvgDialog_142854_Content_10 = {
    Text = "Lo... Lord Lotan?"
  },
  AvgDialog_142854_Content_11 = {
    Text = "Você não consegue reconhecer se a pessoa coberta de Sangue à sua frente é Lotan ou não."
  },
  AvgDialog_142854_Content_12 = {
    Text = "Sangue sujo e corrompido cobre seu corpo inteiro, sem que se saiba se vem dela mesma ou de outra coisa."
  },
  AvgDialog_142854_Content_13 = {
    Text = "Sob aquele Sangue sujo e a armadura despedaçada, metade de seu corpo não passa de ossos brancos e nus."
  },
  AvgDialog_142854_Content_14 = {
    Text = "A guerreira com apenas metade do corpo emerge da fissura impregnada de cheiro de Sangue. Seus passos são lentos e exaustos, a enorme espada partida arrastando pelo chão, traçando um sulco raso na poça de Sangue."
  },
  AvgDialog_142854_Content_15 = {
    Text = "Em sua outra mão, a Coroa formada por Banquete de Sangue goteja Sangue sujo."
  },
  AvgDialog_142854_Content_16 = {
    Text = "Seus Olhos brilham como nunca antes."
  },
  AvgDialog_142854_Content_17 = {
    Text = "Lo... Lord Lotan... a Baleia dos Céus Estrelados... Ela..."
  },
  AvgDialog_142854_Content_18 = {
    Text = "Ela perdeu."
  },
  AvgDialog_142854_Content_19 = {
    Text = "A voz de Lotan não treme nem um pouco, Como Se estivesse apenas relatando algo que inevitavelmente aconteceria."
  },
  AvgDialog_142854_Content_2 = {
    Text = "Cof... Cof, cof..."
  },
  AvgDialog_142854_Content_20 = {
    Text = "Você assinou O Testamento com Ela... Se Ela sofresse Dano, Você também..."
  },
  AvgDialog_142854_Content_21 = {
    Text = "Você não precisa continuar perguntando. Os ferimentos no corpo de Lotan já dizem tudo."
  },
  AvgDialog_142854_Content_22 = {
    Text = "Senhora Lotan, você derrotou todos os desafiantes... até mesmo o Cetus Astral!"
  },
  AvgDialog_142854_Content_23 = {
    Text = "Agora, Você é o rei incontestável deste planeta... Agora é o momento mais glorioso de sua vida! Agora..."
  },
  AvgDialog_142854_Content_24 = {
    Text = "Agora é também o momento em que ela está mais Frágil."
  },
  AvgDialog_142854_Content_25 = {
    Text = "O cheiro de Sangue que emana da fissura envolve Você, e o Sussurro semelhante ao canto de uma baleia fica cada vez mais claro em seus ouvidos."
  },
  AvgDialog_142854_Content_26 = {
    Text = "Veja, a Coroa formada por Banquete de Sangue..."
  },
  AvgDialog_142854_Content_27 = {
    Text = "Os tronos dos seis reinos, a submissão de milhões de pessoas, riqueza e glória inesgotáveis... aquela Coroa pode dar tudo ao seu portador."
  },
  AvgDialog_142854_Content_28 = {
    Text = "Cada pessoa no Coliseu a deseja. Aqueles Cavaleiros que te Repreendiam todos os dias, Graco, as irmãs Vorn, o General Alish, o todo-poderoso Senhor Elian..."
  },
  AvgDialog_142854_Content_29 = {
    Text = "E Você também, pequeno pardal. Você também a deseja..."
  },
  AvgDialog_142854_Content_3 = {
    Text = "Aquilo é..."
  },
  AvgDialog_142854_Content_30 = {
    Text = "Você olha para a Coroa Carmesim nas mãos de Lotan. A cada gota de Banquete de Sangue que cai, o Sussurro da Baleia do Céu Estrelado torna-se mais nítido."
  },
  AvgDialog_142854_Content_31 = {
    Text = "Você nunca mais será uma escrava, pequeno pardal."
  },
  AvgDialog_142854_Content_32 = {
    Text = "Você construirá um grande mausoléu para sua mãe. Você tirará seus irmãos dos estábulos para viver com você em um esplêndido palácio."
  },
  AvgDialog_142854_Content_33 = {
    Text = "Aqueles que um dia os humilharam se ajoelharão diante de Você e beijarão o dorso dos seus pés."
  },
  AvgDialog_142854_Content_34 = {
    Text = "Poder. Poder supremo."
  },
  AvgDialog_142854_Content_35 = {
    Text = "Os nomes que fluem nas lendas morreram por isso... e agora, está diante dos seus Olhos, ao alcance das mãos."
  },
  AvgDialog_142854_Content_36 = {
    Text = "Vá, pequeno pardal. Em toda a sua vida, esta é sua única chance!"
  },
  AvgDialog_142854_Content_37 = {
    Text = "O sussurro transformou-se em estrondo, e um impulso intenso Surge em sua mente. Sua garganta ressecada se contrai, e sua mão trêmula ergue o punhal cravejado de joias deixado por Elian. Na lâmina do punhal, ainda há rastros do seu próprio Sangue."
  },
  AvgDialog_142854_Content_38 = {
    Text = "Você já chegou até aqui, por que não pode dar mais um passo? Aquilo é seu... a Coroa sempre foi sua..."
  },
  AvgDialog_142854_Content_39 = {
    Text = "Você já chegou até aqui, por que não pode dar mais um passo? Aquilo é seu... a Coroa sempre foi sua..."
  },
  AvgDialog_142854_Content_4 = {
    Text = "Você se levantou da poeira que cobria o chão, sacudiu os grãos de areia do corpo e levou alguns segundos para lembrar onde estava agora."
  },
  AvgDialog_142854_Content_40 = {
    Text = "<Red:Mate Ela?... Mate Ela... Mate Ela... Mate Ela!!!>"
  },
  AvgDialog_142854_Content_41 = {
    Text = "Três passos. Apenas três passos separam Você da glória suprema..."
  },
  AvgDialog_142854_Content_42 = {
    Text = "No momento em que Você reúne coragem para dar o primeiro passo, Lotan vira a cabeça. Aqueles Olhos cansados olham para Você com calma."
  },
  AvgDialog_142854_Content_43 = {
    Text = "No momento em que Você reúne coragem para dar o primeiro passo, Lotan vira a cabeça. Aqueles Olhos cansados olham para Você com calma."
  },
  AvgDialog_142854_Content_44 = {
    Text = "No instante em que é alcançado por O Olhar, todos os sussurros que o sustentavam desaparecem ao mesmo tempo, e seu Sangue fervente esfria de repente."
  },
  AvgDialog_142854_Content_45 = {
    Text = "Eu... Eu..."
  },
  AvgDialog_142854_Content_46 = {
    Text = "Nos Olhos de Lotan não há nenhum vestígio de intenção de matar. Ao contemplar aqueles Olhos, Você de repente compreende que, se não fosse para encontrar a Baleia do Céu Estrelado, ninguém aqui mereceria que Ela levantasse um dedo."
  },
  AvgDialog_142854_Content_47 = {
    Text = "Nos Olhos de Lotan não há nenhum vestígio de intenção de matar. Ao contemplar aqueles Olhos, Você de repente compreende que, se não fosse para encontrar a Baleia do Céu Estrelado, ninguém aqui mereceria que Ela levantasse um dedo."
  },
  AvgDialog_142854_Content_48 = {
    Text = "Era O Olhar de alguém que observa formigas disputando um pedaço de açúcar. Nada além disso, nenhuma emoção a mais."
  },
  AvgDialog_142854_Content_49 = {
    Text = "A história das formigas nunca muda. Ela ergue aquela mão já reduzida a ossos brancos e coloca casualmente o que segura sobre sua cabeça."
  },
  AvgDialog_142854_Content_5 = {
    Text = "As paredes de pedra do Coliseu se despedaçaram como papel, enormes blocos de pedra caíram das arquibancadas, e os últimos vestígios dos espectros do Público já haviam desaparecido."
  },
  AvgDialog_142854_Content_50 = {
    Text = "!!! Isso é..."
  },
  AvgDialog_142854_Content_51 = {
    Text = "Gotas de Sangue morno e sujo escorrem do topo da sua cabeça. Você estende a mão e, sobre sua própria cabeça, toca a Coroa fria e viscosa formada pela Confluência de Sangue."
  },
  AvgDialog_142854_Content_52 = {
    Text = "Inúmeros heróis mataram por isso, inúmeras humanidades caíram por isso. O poder e a riqueza de seis nações, a nobreza e a glória supremas, agora repousam levemente sobre sua cabeça."
  },
  AvgDialog_142854_Content_53 = {
    Text = "O vencedor final jogou-a para Você descuidadamente, como quem enfia um pedaço de açúcar na boca Gananciosa de uma criança — agora, Você possui tudo."
  },
  AvgDialog_142854_Content_54 = {
    Text = "Senhor Lotan... Você... Você..."
  },
  AvgDialog_142854_Content_55 = {
    Text = "Faça-me um favor."
  },
  AvgDialog_142854_Content_56 = {
    Text = "Vou procurar um novo oponente. Antes disso, preciso de um novo par de espadas."
  },
  AvgDialog_142854_Content_57 = {
    Text = "Lotan olhou para o par de espadas gigantes que a acompanharam por tantos anos e recolheu seus corpos destruídos para as bainhas."
  },
  AvgDialog_142854_Content_58 = {
    Text = "Ela se virou, arrastando seu corpo destruído, caminhando para frente de forma cansada e lenta, em direção a um destino que Você jamais poderia compreender."
  },
  AvgDialog_142854_Content_59 = {
    Text = "Na fissura atrás de Você, as runas antigas se apagaram uma a uma, e a divindade em processo de colapso e corrupção revelou um sorriso de satisfação que Você nunca havia visto antes."
  },
  AvgDialog_142854_Content_6 = {
    Text = "Você estava deitado no chão coberto de pedras quebradas, com um zumbido incessante nos ouvidos. A Fissura Dimensional pairava no centro do Coliseu, suas bordas se contraindo violentamente, como uma ferida horrenda."
  },
  AvgDialog_142854_Content_60 = {
    Text = "Em meu lugar... Registre o nome dela."
  },
  AvgDialog_142854_Content_61 = {
    Text = "Você ajoelhou-se na poça de Sangue, contemplando aquela silhueta que se afastava cada vez mais, incapaz de se levantar por um longo tempo."
  },
  AvgDialog_142854_Content_62 = {
    Text = "A Coroa sobre sua cabeça é pesada, muito pesada. O peso de doze milênios de desejo te faz cair de joelhos na poça de sangue. Você observa a figura dela se afastar, incapaz de se levantar por um longo, longo tempo."
  },
  AvgDialog_142854_Content_63 = {
    Text = "A Coroa sobre a cabeça era leve, muito leve, tão leve que parecia nunca ter existido."
  },
  AvgDialog_142854_Content_7 = {
    Text = "Um lamento grave e prolongado ecoou da ferida, atravessando seu crânio até as profundezas de sua mente, pesado como o suspiro de um planeta."
  },
  AvgDialog_142854_Content_8 = {
    Text = "Aquele som... é a Baleia Celestial?!"
  },
  AvgDialog_142854_Content_9 = {
    Text = "Um forte e nauseante cheiro de Sangue emanava da fissura. Enquanto Você se preparava para se aproximar lentamente dela, um pé composto apenas de ossos brancos saiu da fissura."
  },
  AvgDialog_142888_Content_1 = {
    Text = "Uma Mentira"
  },
  AvgDialog_142888_Content_10 = {
    Text = "Você não tem como responder, sua memória agora está tão embaralhada quanto um cão de pelo longo que rolou três vezes na lama."
  },
  AvgDialog_142888_Content_100 = {
    Text = "Inundando o peito, inundando os ouvidos, inundando..."
  },
  AvgDialog_142888_Content_101 = {
    Text = "Meu Senhor!"
  },
  AvgDialog_142888_Content_102 = {
    Text = "Você de repente volta à realidade. Ao longe, Ogier, Lotan e Ramona caminham em sua direção, tendo terminado o treinamento. As marionetes divididas de Doll estão analisando os dados do treinamento."
  },
  AvgDialog_142888_Content_103 = {
    Text = "A pessoa ao seu lado soltou um suspiro de profundo pesar."
  },
  AvgDialog_142888_Content_104 = {
    Text = "Não se preocupe, sempre manterei essa escolha aberta para você."
  },
  AvgDialog_142888_Content_105 = {
    Text = "Ninguém permanece ao seu lado. O horizonte onde o sol poente está prestes a se pôr refrata um brilho perolado suave e levemente psicodélico."
  },
  AvgDialog_142888_Content_106 = {Text = "Ah..."},
  AvgDialog_142888_Content_107 = {
    Text = "Você ainda tem muito a dizer. Sobre aquela catástrofe sem qualquer alvo específico, provocada apenas pela vontade travessa de N de seduzir os fiéis."
  },
  AvgDialog_142888_Content_108 = {
    Text = "Sobre o papel do Santuário da Lanterna em alimentar as chamas, sobre os vários atos insanos de retaliação de Pontos ao longo do século seguinte ou mais."
  },
  AvgDialog_142888_Content_109 = {
    Text = "Sobre... se houve um instante em que ele também vacilou diante de outra possibilidade, deixando que os anos marcassem seu corpo."
  },
  AvgDialog_142888_Content_11 = {
    Text = "Leisha, que também estava quase sem forças devido à batalha anterior, fez um esforço para se levantar e se colocou entre você e Pontos."
  },
  AvgDialog_142888_Content_110 = {
    Text = "Sobre Jago e Leisha — se ainda estão festejando em Ebwynnos agora."
  },
  AvgDialog_142888_Content_111 = {
    Text = "...No fim, você só quer rezar para que ele não cause nenhuma confusão com o Professor Dexter na escola."
  },
  AvgDialog_142888_Content_112 = {
    Text = "Você balança a cabeça e caminha em direção aos seus amigos sem hesitar."
  },
  AvgDialog_142888_Content_12 = {
    Text = "Pontos, acabou."
  },
  AvgDialog_142888_Content_13 = {
    Text = "Os que ainda estão vivos, se ficarem em Ebwynnos, terão de pagar o preço de esquecer as memórias de fora de Ebwynnos."
  },
  AvgDialog_142888_Content_14 = {
    Text = "E alguém como eu, que já morreu e foi refeito como um pesadelo, terá todas as memórias lentamente corroídas no final."
  },
  AvgDialog_142888_Content_15 = {
    Text = "Jago já fez a sua escolha, e eu também fiz a minha...\nVamos embora."
  },
  AvgDialog_142888_Content_16 = {
    Text = "Os lábios de Pontos se fecharam numa linha indiferente, com a mandíbula contraída."
  },
  AvgDialog_142888_Content_17 = {
    Text = "Você ainda deve se lembrar de que você existe dependendo de Ebwynnos. Se sair de Ebwynnos, você morrerá."
  },
  AvgDialog_142888_Content_18 = {
    Text = "Sim, mas as memórias do meu passado também voltarão. Morrerei como um ser humano — é o único caminho."
  },
  AvgDialog_142888_Content_19 = {
    Text = "Eu já... não consigo lembrar como você e Jago eram quando crianças. Pelo menos, antes que eu esqueça vocês dois por completo."
  },
  AvgDialog_142888_Content_2 = {
    Text = "A Intimidação sufocante recua como uma maré, seu cérebro é tomado por uma dor lancinante e sua visão pisca em branco repetidamente."
  },
  AvgDialog_142888_Content_20 = {
    Text = "Pontos ficou imóvel no lugar. Pela primeira vez, você viu uma expressão de tamanha tristeza aparecer em seu rosto."
  },
  AvgDialog_142888_Content_21 = {
    Text = "...Quem me dera poder dizer que aquela força ainda me controlava."
  },
  AvgDialog_142888_Content_22 = {
    Text = "Ele fechou os olhos, como se quisesse se esquivar das coisas que não queria encarar. Por fim, esboçou um sorriso autodepreciativo e abatido."
  },
  AvgDialog_142888_Content_23 = {
    Text = "Assim eu poderia ir contra a vontade de vocês com toda a razão do mundo e agir com maldade contra vocês."
  },
  AvgDialog_142888_Content_24 = {Text = "..."},
  AvgDialog_142888_Content_25 = {
    Text = "Pontos cede em silêncio. A carruagem que outrora o levou à vingança contra seus inimigos agora leva Leisha em seu caminho também."
  },
  AvgDialog_142888_Content_26 = {
    Text = "Enquanto a carruagem de luz perolada indescritível desliza para o céu além de Ebwynnos, um ar de alívio toma conta do rosto de Leisha. Ela se vira para encarar vocês dois..."
  },
  AvgDialog_142888_Content_27 = {
    Text = "E então desapareceu completamente na brisa noturna do mar."
  },
  AvgDialog_142888_Content_28 = {
    Text = "Nenhum de vocês abriu a boca, apenas contemplaram aquele Nada por um longo tempo, até que Pontos quebrou o silêncio."
  },
  AvgDialog_142888_Content_29 = {
    Text = "Como é a vida que você levou depois de partir de Ebwynnos, a vida de \"Tu\"?"
  },
  AvgDialog_142888_Content_3 = {
    Text = "Ah, que dor!"
  },
  AvgDialog_142888_Content_30 = {
    Text = "Você não esperava que sua primeira frase fosse essa. Ficou parado por um momento antes de começar a organizar aquelas memórias confusas."
  },
  AvgDialog_142888_Content_31 = {
    Text = "Algo parece ter dado errado com este Domínio. Nem as memórias de Jago nem as suas estão completamente intactas."
  },
  AvgDialog_142888_Content_32 = {
    Text = "...Não consigo lembrar com clareza. Minha mente agora guarda tanto memórias de ser Jago quanto memórias de ser outra pessoa, em um lugar distante. Todas as memórias estão misturadas."
  },
  AvgDialog_142888_Content_33 = {
    Text = "Instintivamente, você enfiou a mão no bolso para acariciar o gafanhoto de palha."
  },
  AvgDialog_142888_Content_34 = {
    Text = "Mas mesmo assim — simples, comum, agitada, as mesmas rotinas dia após dia — foi uma vida feliz."
  },
  AvgDialog_142888_Content_35 = {
    Text = "Feliz o suficiente para me fazer quem eu sou. Feliz o suficiente para que, não importa o que aconteça, eu queira voltar."
  },
  AvgDialog_142888_Content_36 = {
    Text = "Ele olha nos seus olhos, quieto e imóvel. Quase parece com a forma... com a forma como Leisha costumava olhar para você."
  },
  AvgDialog_142888_Content_37 = {
    Text = "<Red:Ele não está apenas olhando para Jago.>"
  },
  AvgDialog_142888_Content_38 = {
    Text = "Vocês estão enganados, Jago... <Red:%player%>."
  },
  AvgDialog_142888_Content_39 = {
    Text = "!!!¿¿¿???"
  },
  AvgDialog_142888_Content_4 = {
    Text = "Pontos está parado sozinho no lugar, e você não consegue distinguir sua expressão."
  },
  AvgDialog_142888_Content_40 = {Text = "O que?!"},
  AvgDialog_142888_Content_41 = {
    Text = "Um calafrio percorre você. Como ele pode saber <Red:\"seu\"> nome? Isto não é apenas um Domínio?"
  },
  AvgDialog_142888_Content_42 = {
    Text = "Ele volta àquela compostura fria e aristocrática, como se nada jamais tivesse escapado de suas mãos, e lhe dá um sorriso tranquilo."
  },
  AvgDialog_142888_Content_43 = {
    Text = "Eu sei que <Red:\"Tu\"> sempre estiveste aqui, eu sei que <Red:\"Tu\"> és \"ele\", desde que <Red:\"Tu\"> eras criança, eu já sabia que <Red:\"Tu\"> eras diferente dos outros."
  },
  AvgDialog_142888_Content_44 = {
    Text = "O ruído abafado, pertencente ao mar, voltou a inundar seus ouvidos."
  },
  AvgDialog_142888_Content_45 = {
    Text = "Vocês ainda são muito pequenos, muito ingênuos, enganando-se ao pensar que aquela mediocridade se chama felicidade."
  },
  AvgDialog_142888_Content_46 = {
    Text = "Desta vez, não cometerei o <Red:erro> de deixar a escolha nas suas mãos novamente."
  },
  AvgDialog_142888_Content_47 = {
    Text = "Você estava errado. Ele nunca cedeu. Ele não vai, e nunca ia, soltar. Ele apenas colocou uma isca brilhante."
  },
  AvgDialog_142888_Content_48 = {
    Text = "Há muito ele havia descoberto a outra parte de \"você\". \nEle ia encontrar \"você\". Ele não permitiria mais surpresas."
  },
  AvgDialog_142888_Content_49 = {
    Text = "Fácil demais. Aquela batalha, aquela vitória. \nFora uma armadilha para atrair <Italic:você> para fora."
  },
  AvgDialog_142888_Content_5 = {
    Text = "Mas, evidentemente, algo já havia partido dele."
  },
  AvgDialog_142888_Content_50 = {
    Text = "Independentemente do preço a pagar, independentemente de a qual existência devo jurar lealdade..."
  },
  AvgDialog_142888_Content_51 = {
    Text = "Farei com que a festa de Ebwynnos dure para sempre."
  },
  AvgDialog_142888_Content_52 = {
    Text = "Ninguém sabia por que ele, de repente, permitiu que o envelhecimento tomasse conta de si."
  },
  AvgDialog_142888_Content_53 = {
    Text = "Todo Ebwynnos treme com ele. Os médiuns ao seu redor e a água do mar que jorra de seu peito se fundem, indistinguíveis uns dos outros."
  },
  AvgDialog_142888_Content_54 = {
    Text = "Talvez sejam amigos, talvez inimigos. Incontáveis braços negros emergem de seu peito, arranhando sua pele, acariciando-a."
  },
  AvgDialog_142888_Content_55 = {
    Text = "Como se tentassem fugir. Como se ansiassem por estar com ele para sempre."
  },
  AvgDialog_142888_Content_56 = {
    Text = "Estou num caminho sem volta. E nem preciso de um."
  },
  AvgDialog_142888_Content_57 = {
    Text = "Os anos que você jamais viveu não significam nada. Aqui em Ebwynnos, eles são dóceis. Controláveis. Não podem te machucar."
  },
  AvgDialog_142888_Content_58 = {
    Text = "É uma pena de verdade. Ainda não posso te manter aqui. Nosso tempo acabou, <Red:%player%>."
  },
  AvgDialog_142888_Content_59 = {
    Text = "Um som nauseante e úmido de dilaceração se ergue no ar. Enormes patas de aranha irrompem pelos corpos dos oficiais e dos transeuntes, espirrando sangue espesso com cheiro de ferro por todo você."
  },
  AvgDialog_142888_Content_6 = {
    Text = "Dê-me um motivo."
  },
  AvgDialog_142888_Content_60 = {
    Text = "Uma leveza te pega de surpresa, arrancando você para cima e para fora do espaço rasgado. Thrall-Gaunts que encobrem o céu abrem suas asas membranosas e avançam em sua direção num impulso suave."
  },
  AvgDialog_142888_Content_61 = {
    Text = "Não se preocupe. Nos veremos novamente em breve."
  },
  AvgDialog_142888_Content_62 = {
    Text = "Ebwynnos e eu esperaremos pelo seu retorno. Para sempre."
  },
  AvgDialog_142888_Content_63 = {
    Text = "As marcas do tempo percorreram o corpo de Pontos como erosão."
  },
  AvgDialog_142888_Content_64 = {
    Text = "Gargalhando, ele ergue seu cálice em tua direção em Ebwynnos, que rapidamente se afasta de ti."
  },
  AvgDialog_142888_Content_65 = {
    Text = "No último vislumbre antes que a escuridão o engula, você vê duas figuras paradas ao seu lado."
  },
  AvgDialog_142888_Content_66 = {
    Text = "Ele não deixou ninguém ir. Guardou a todos — até o último."
  },
  AvgDialog_142888_Content_67 = {
    Text = "<Red:É Leisha, e Jago quando era jovem.>"
  },
  AvgDialog_142888_Content_68 = {Text = "..."},
  AvgDialog_142888_Content_69 = {
    Text = "Ei?! E depois, e depois? Guardião, ele deixou você cair à morte?!"
  },
  AvgDialog_142888_Content_7 = {
    Text = "Sua voz está rouca, mas seu corpo ainda está tenso, como algum animal encurralado sem saída."
  },
  AvgDialog_142888_Content_70 = {
    Text = "O tio Pontos foi tão cruel! Ele não pode fazer isso com você!!"
  },
  AvgDialog_142888_Content_71 = {
    Text = "É, como você pode ser tão malvado, Pontos!"
  },
  AvgDialog_142888_Content_72 = {
    Text = "Estavas animadamente sussurrando para Aurita sobre as experiências no Sonho, quando viraste a cabeça..."
  },
  AvgDialog_142888_Content_73 = {
    Text = "E te assustaste com alguém igualmente entusiasmado, de mãos nos bolsos, encostado à Porta, sem que soubesses há quanto tempo estava a ouvir."
  },
  AvgDialog_142888_Content_74 = {
    Text = "Depois disso, o pequeno Jago saiu em segurança. Ele abriu os olhos e acordou do sonho."
  },
  AvgDialog_142888_Content_75 = {
    Text = "Ele se viu deitado em sua própria cama em casa, com as pessoas que amava reunidas ao seu redor."
  },
  AvgDialog_142888_Content_76 = {
    Text = "O outro personagem principal da história se apoia na parede do quarto de Aurita e, em voz baixa e pausada, fornece o final."
  },
  AvgDialog_142888_Content_77 = {
    Text = "Ele relembrou todas as memórias de sua vida, fechou os olhos em paz e foi para um lugar de felicidade."
  },
  AvgDialog_142888_Content_78 = {
    Text = "Aurita emitiu um pequeno e satisfeito suspiro pelo nariz, adormecendo aos poucos num estado de sonolência, tal como a Vera que guardavas na memória."
  },
  AvgDialog_142888_Content_79 = {
    Text = "Pontos inclina a cabeça em direção à porta e faz um gesto de convite."
  },
  AvgDialog_142888_Content_8 = {
    Text = "Por que, por que até você precisa partir, por que prefere se lançar à morte em vez de —"
  },
  AvgDialog_142888_Content_80 = {
    Text = "Imagino que você gostaria de ter uma conversa comigo?"
  },
  AvgDialog_142888_Content_81 = {Text = "..."},
  AvgDialog_142888_Content_82 = {
    Text = "Reunidos após uma longa separação — que frase adorável."
  },
  AvgDialog_142888_Content_83 = {
    Text = "Você não contou a Aurita como realmente terminou. Você mentiu, não foi?"
  },
  AvgDialog_142888_Content_84 = {
    Text = "Você nunca deixou Leisha ir. E a única que conseguiu sair de Ebwynnos fui eu, não Jago."
  },
  AvgDialog_142888_Content_85 = {
    Text = "Interrompido tão abruptamente, Pontos não demonstra nenhum aborrecimento. Ele sorri e arqueia uma sobrancelha."
  },
  AvgDialog_142888_Content_86 = {
    Text = "Claro, evidentemente. Há histórias que não são adequadas para contar às crianças, não é verdade?"
  },
  AvgDialog_142888_Content_87 = {
    Text = "Então imagino que essa... <Italic:aparência> que você usa agora... é só para mostrar a todos que envelhecer — a única coisa que você perdeu — não significa nada para você."
  },
  AvgDialog_142888_Content_88 = {
    Text = "Para mostrar que você tem tudo sob controle, hein? O tempo. O envelhecimento. Até a vida das outras pessoas..."
  },
  AvgDialog_142888_Content_89 = {
    Text = "A hostilidade em suas palavras está ficando óbvia demais para passar despercebida. Pontos não responde diretamente; ele apenas lhe dá um sorriso que te irrita imensamente."
  },
  AvgDialog_142888_Content_9 = {
    Text = "E não \"Eu\"."
  },
  AvgDialog_142888_Content_90 = {
    Text = "Quem sabe? Talvez eu simplesmente quisesse tentar algo novo."
  },
  AvgDialog_142888_Content_91 = {
    Text = "De qualquer forma, fico feliz que você tenha lembrado. Desde a primeira vez que vim ao Misaq, estive aguardando este dia."
  },
  AvgDialog_142888_Content_92 = {
    Text = "Ebwynnos ainda está esperando por você, %player%."
  },
  AvgDialog_142888_Content_93 = {
    Text = "...Se precisar de um lembrete, Misaq possui um sistema de segurança completo."
  },
  AvgDialog_142888_Content_94 = {
    Text = "Não precisa ficar tão tenso."
  },
  AvgDialog_142888_Content_95 = {
    Text = "Por falar nisso, estou bastante curioso. Meu pequeno Um do Misaq, você não é mais Jago. Você tem uma resposta para mim agora?"
  },
  AvgDialog_142888_Content_96 = {
    Text = "Pontos inclina levemente a cabeça, e você olha para seus olhos azul-profundo."
  },
  AvgDialog_142888_Content_97 = {
    Text = "Se eu te desse mais uma chance de escolher, você escolheria a vida eterna com juventude perpétua, ou as memórias criadas ao longo de uma vida inteira?"
  },
  AvgDialog_142888_Content_98 = {
    Text = "O som do mar, o bater de asas."
  },
  AvgDialog_142888_Content_99 = {
    Text = "O ruído branco familiar e distante volta a permear lentamente o corpo."
  },
  AvgDialog_142889_Content_1 = {
    Text = "A Melhor Coisa do Mundo"
  },
  AvgDialog_142889_Content_10 = {
    Text = "Quando crescer, você vai entender. Sempre nos reencontraremos. Quando estivermos separados, vou sentir sua falta o tempo todo."
  },
  AvgDialog_142889_Content_100 = {
    Text = "Ele suspira. Com um sorriso perfeitamente natural, termina o resto da frase junto com outra voz."
  },
  AvgDialog_142889_Content_101 = {
    Text = "Do que você está falando? Aqui é Ebwynnos. Não há envelhecimento aqui. Vamos festejar para sempre, eternamente jovens."
  },
  AvgDialog_142889_Content_102 = {
    Text = "<Italic:Alguém> sai de trás de Orney. Ele fala baixo e rouco, como o mais magnânimo e digno dos anciãos."
  },
  AvgDialog_142889_Content_103 = {
    Text = "Aquela não é a voz de Pontos."
  },
  AvgDialog_142889_Content_104 = {
    Text = "Ele é tão antigo que varre toda a familiaridade de outrora, restando apenas o <Red:mais profundo> do oceano, onde a Resonância das águas lava sua consciência mais uma vez."
  },
  AvgDialog_142889_Content_105 = {
    Text = "Sim, sim, aqui é Ebwynnos. Eu voltei para Ebwynnos."
  },
  AvgDialog_142889_Content_106 = {
    Text = "<Shake:<Red:Vamos festejar para sempre.>>"
  },
  AvgDialog_142889_Content_107 = {
    Text = "<Red:Seremos jovens para sempre.>"
  },
  AvgDialog_142889_Content_108 = {
    Text = "Você está tão feliz, tão despreocupado. Você está em Ebwynnos."
  },
  AvgDialog_142889_Content_109 = {
    Text = "Além disso, todos os pensamentos sem importância se dissiparam."
  },
  AvgDialog_142889_Content_11 = {
    Text = "<Red:Clap——>"
  },
  AvgDialog_142889_Content_110 = {
    Text = "Porém, por algum motivo, você não deixou ninguém ver aquele gafanhoto cujo nome você esqueceu."
  },
  AvgDialog_142889_Content_12 = {
    Text = "No exato momento em que a bússola deixou suas mãos, uma série de sons suaves e densos veio de fora da janela."
  },
  AvgDialog_142889_Content_13 = {
    Text = "Em seguida, uma risada suave."
  },
  AvgDialog_142889_Content_14 = {
    Text = "Deixa-me ver quem é este pequeno rapaz bonito—"
  },
  AvgDialog_142889_Content_15 = {
    Text = "Com uma força invisível e imensa, a janela escancarou-se. Na escuridão profunda e cacofónica, a lua prateada cintilava por entre as frestas."
  },
  AvgDialog_142889_Content_16 = {
    Text = "Olá, Jago."
  },
  AvgDialog_142889_Content_17 = {
    Text = "Tantas... tantas asas, Avô!!"
  },
  AvgDialog_142889_Content_18 = {
    Text = "Incontáveis asas negras e membranosas, enormes, obscurecendo o céu, avançaram na tua direção. As tuas pupilas tremiam enquanto fitavas o centro escuro, incapaz de te mover."
  },
  AvgDialog_142889_Content_19 = {
    Text = "<Red:Tio Pontos...>"
  },
  AvgDialog_142889_Content_2 = {
    Text = "A memória termina. Você fica em silêncio por um longo tempo."
  },
  AvgDialog_142889_Content_20 = {
    Text = "Squelch... glub glub... <LightGray:*som úmido de compressão>"
  },
  AvgDialog_142889_Content_21 = {
    Text = "A pequena mão de Vera agarrou-se firmemente a você, deixando no final apenas uma marca profunda de arranhão.\nEnvolver, sufocar, engolir."
  },
  AvgDialog_142889_Content_22 = {
    Text = "Sereno. Calmo. Familiar. Prazeroso..."
  },
  AvgDialog_142889_Content_23 = {
    Text = "Ondas de ruído branco engolfaram os seus ouvidos."
  },
  AvgDialog_142889_Content_24 = {
    Text = "<Red:Queda.>"
  },
  AvgDialog_142889_Content_25 = {Text = "..."},
  AvgDialog_142889_Content_26 = {
    Text = "Jago, acorda. Para de dormir."
  },
  AvgDialog_142889_Content_27 = {
    Text = "A festividade de hoje está prestes a começar. Todos estão esperando por você."
  },
  AvgDialog_142889_Content_28 = {
    Text = "Um ruído branco perfurante envia uma dor aguda pelos seus tímpanos, e você instintivamente pula da cama."
  },
  AvgDialog_142889_Content_29 = {
    Text = "Eu disse que ele ia acordar logo. Meu Jago é um rapazinho notável."
  },
  AvgDialog_142889_Content_3 = {
    Text = "Chame isso de egoísmo de um velho, você pensa — porque talvez você seja a última pessoa que se lembra deles, e não quer que sejam esquecidos."
  },
  AvgDialog_142889_Content_30 = {
    Text = "Pontos sorri e cutuca Leisha com o cotovelo. Orney, Tio White e muitos rostos familiares estão todos aglomerados ao redor da sua cama."
  },
  AvgDialog_142889_Content_31 = {
    Text = "Sua consciência parece submersa em águas profundas. Você tem a sensação incômoda de que esqueceu algo, e a agilidade do seu corpo lhe parece sutilmente errada."
  },
  AvgDialog_142889_Content_32 = {
    Text = "Tio Pontos, mãe? O que aconteceu? Por que todos estão aqui?"
  },
  AvgDialog_142889_Content_33 = {
    Text = "Oh, você fez uma longa viagem, pequeno. Levei muito, muito tempo para te encontrar."
  },
  AvgDialog_142889_Content_34 = {
    Text = "Agora, eu te trouxe de volta para casa."
  },
  AvgDialog_142889_Content_35 = {
    Text = "O sol poente atravessa as nuvens, talhando o mar em ondulações cintilantes como ouro espalhado refletido no vidro da janela. Você está de volta à estalagem à beira-mar onde cresceu."
  },
  AvgDialog_142889_Content_36 = {
    Text = "Ah, certo. Este lugar é... @4"
  },
  AvgDialog_142889_Content_37 = {Text = "??!!!"},
  AvgDialog_142889_Content_38 = {
    Text = "ABYSSABYSSABYSSABYSSABYSSABYSSABYSSABYSS\nA@1YS@1@2Y@2@1B@1SSSS@2YA@4@2Y@1\n@1B@1S@2Y@2@2y@1sa@1y@2@4@2Y@1\na@1y@2A@4ss@2ysssssAb@3abyss@2@3\n厄@2@3波@1@3厄@2yssSS@2YA@4\n@1B@1S@2Y@2@2y@1sa@1y@2@4@2Y@1\nA@1YS@1@2Y@2@1B@1SSSS@2YA@4@2Y@1\n@1@2@3扬@1@3斯@2y!!ab@2YA@4\nABYssABySSabySSAByssabYSSa@2SAByssabyssABYSS@2\nABYSSABYSSABYSS@4@3SSABYSS@2@3\n@3@2@4@3@1@3@3!!!!!!!\na@1y@2A@4ss@2ysssssAb@3abyss@2@3\n@3@4YssAby!!!!!!!ABYSSABYSSABy@1\nA@1YS@1@2Y@2@1B@1SSSS@2YA@4@2Y@1@1\n@1B@1S@2Y@2@2y@1sa@1y@2@4<Red:!!!!!!>"
  },
  AvgDialog_142889_Content_39 = {
    Text = "Uma dor latejante, uma pressão empurrando — o nome da cidade fica preso na ponta da sua língua."
  },
  AvgDialog_142889_Content_4 = {
    Text = "Você olha ternamente para Vera. Sua família, atenciosa, deixou os dois a sós para que você não se canse."
  },
  AvgDialog_142889_Content_40 = {
    Text = "Um estrondo estridente como ferro raspando vidro ecoa de dentro do seu crânio até a garganta, transformando seu cérebro em uma pasta espessa e viscosa."
  },
  AvgDialog_142889_Content_41 = {
    Text = "Até que aquela palma quente e áspera envolve a nuca da sua cabeça, e como sempre, ele ri e pressiona a testa à sua."
  },
  AvgDialog_142889_Content_42 = {
    Text = "Ei, volte para mim. O que foi?"
  },
  AvgDialog_142889_Content_43 = {
    Text = "Você abre a boca lentamente, procurando a sua voz."
  },
  AvgDialog_142889_Content_44 = {
    Text = "Pontos observa-o atentamente, e você não entende — o jeito que ele olha para você, é o jeito que alguém olha para algo que pensou ter perdido para sempre."
  },
  AvgDialog_142889_Content_45 = {
    Text = "Como olhar para a coisa mais preciosa do mundo."
  },
  AvgDialog_142889_Content_46 = {
    Text = "Bem-vindo de volta a Ebwynnos, Jago."
  },
  AvgDialog_142889_Content_47 = {
    Text = "A consciência inunda de volta. Você olha para todas as coisas familiares ao seu redor, a luz do sol assando as tábuas do chão até que elas suam grãos de sal..."
  },
  AvgDialog_142889_Content_48 = {
    Text = "Uma estranha e serena felicidade afoga qualquer outro pensamento. Um sorriso emerge lentamente no seu rosto."
  },
  AvgDialog_142889_Content_49 = {
    Text = "Agora me lembro. Ebwynnos. Aqui é Ebwynnos — o lugar onde eu cresci..."
  },
  AvgDialog_142889_Content_5 = {
    Text = "Nunca mais vi a Mãe nem o Tio Pontos. Se não fosse esta bússola, provavelmente pensaria que tudo não passou de uma alucinação causada pela explosão."
  },
  AvgDialog_142889_Content_50 = {
    Text = "Isso mesmo. Há quanto tempo!"
  },
  AvgDialog_142889_Content_51 = {
    Text = "Você finalmente voltou para casa, Jago."
  },
  AvgDialog_142889_Content_52 = {Text = "..."},
  AvgDialog_142889_Content_53 = {
    Text = "Os teus pensamentos parecem ter sido embebidos num xarope chamado felicidade. Todos à tua volta parecem tão jovens como quando se separaram..."
  },
  AvgDialog_142889_Content_54 = {
    Text = "Oh... separaram."
  },
  AvgDialog_142889_Content_55 = {
    Text = "Quando foi que deixaste Ebwynnos, e como é que voltaste? Parece que ainda há pouco estavas deitado noutra cama. Tens uma neta, chamada..."
  },
  AvgDialog_142889_Content_56 = {
    Text = "Em que estás a pensar, miúdo?"
  },
  AvgDialog_142889_Content_57 = {
    Text = "Pontos encostou–se à janela, o sol poente já a afundar–se no mar, os seus últimos raios de luz escondidos atrás dele."
  },
  AvgDialog_142889_Content_58 = {
    Text = "Tio Pontos, sinto que me esqueci de algo muito importante. O que era..."
  },
  AvgDialog_142889_Content_59 = {
    Text = "Hahaha, se por enquanto não consegue lembrar, é porque não é tão importante assim. Não se apresse, em Ebwynnos, temos todo o tempo do mundo."
  },
  AvgDialog_142889_Content_6 = {
    Text = "Então, Vera, é por isso que o vovô queria te contar esta história."
  },
  AvgDialog_142889_Content_60 = {
    Text = "Vamos! Você ainda é jovem, tem muitos bons momentos pela frente — é claro que devem ser usados para festejar."
  },
  AvgDialog_142889_Content_61 = {
    Text = "Passou o braço pelos teus ombros e caminhou em direção ao salão recém–decorado no andar de baixo, onde a multidão em festa vos arrastou juntos para a pista de dança."
  },
  AvgDialog_142889_Content_62 = {
    Text = "Apenas agora você percebe que a estalagem se tornou um salão de esplendor deslumbrante."
  },
  AvgDialog_142889_Content_63 = {
    Text = "Rostos familiares riem pela pista de dança, erguendo as suas taças e acenando para você, taças de madeira e vidro se chocando num clamor disperso."
  },
  AvgDialog_142889_Content_64 = {
    Text = "Ainda sou jovem, ainda sou... jovem?"
  },
  AvgDialog_142889_Content_65 = {
    Text = "Uma forte tontura volta a lavar sobre você. Aquela estranha felicidade aperta-o com força, sem soltar."
  },
  AvgDialog_142889_Content_66 = {
    Text = "Você ergue o braço e vê duas mãos jovens e fortes;"
  },
  AvgDialog_142889_Content_67 = {
    Text = "você olha para o espelho, e o rosto de um jovem usa o mesmo riso que todos os outros."
  },
  AvgDialog_142889_Content_68 = {
    Text = "Amigos, ergamos os nossos copos—a Ebwynnos!"
  },
  AvgDialog_142889_Content_69 = {
    Text = "Antes que você possa se recompor, Pontos passa pelo seu ombro e ergue a sua taça para a multidão."
  },
  AvgDialog_142889_Content_7 = {
    Text = "Talvez eles ainda estejam voando em algum lugar no céu noturno. E se um dia eu partir, talvez eles tenham vindo me levar para casa."
  },
  AvgDialog_142889_Content_70 = {
    Text = "A Ebwynnos!"
  },
  AvgDialog_142889_Content_71 = {
    Text = "Em meio a uma alegria vasta e desorientante, você ergue a taça junto com todos, e a onda de vozes te arrasta para o centro da multidão."
  },
  AvgDialog_142889_Content_72 = {
    Text = "Você festeja, dança, bebe sem moderação."
  },
  AvgDialog_142889_Content_73 = {
    Text = "Os feixes de luz da grande casa atravessam a névoa que sobe do mar, cintilando a noite toda."
  },
  AvgDialog_142889_Content_74 = {
    Text = "Só quando uma ténue luz pálida surgiu no horizonte e as pessoas tombaram umas sobre as outras a dormir é que tu, ligeiramente embriagado, cantarolaste uma canção e te recostaste nas almofadas forradas a veludo."
  },
  AvgDialog_142889_Content_75 = {Text = "..."},
  AvgDialog_142889_Content_76 = {
    Text = "Você está quase a adormecer quando de repente vê o rosto de Leisha num canto do salão. Você corre até ela."
  },
  AvgDialog_142889_Content_77 = {
    Text = "Mamãe! Espere por mim, para onde você foi? Não te vi a noite toda."
  },
  AvgDialog_142889_Content_78 = {
    Text = "Um pânico inexplicável aperta o seu coração, e você não consegue evitar murmurar para si mesmo."
  },
  AvgDialog_142889_Content_79 = {
    Text = "Que estranho—não estive apenas fora numa viagem? Porque é que parece que não nos vemos há tanto tempo?"
  },
  AvgDialog_142889_Content_8 = {
    Text = "Mas... não quero ficar separada do Vovô. Pode me levar com você?"
  },
  AvgDialog_142889_Content_80 = {
    Text = "Os seus passos pararam abruptamente — por causa da expressão de total desamparo e tristeza no rosto de Leisha."
  },
  AvgDialog_142889_Content_81 = {
    Text = "Ele encontrou você. Meu pobre Jago, você nunca deveria ter vindo aqui."
  },
  AvgDialog_142889_Content_82 = {
    Text = "Pense, rápido — enquanto ainda não esqueceu. Lembre–se de que tipo de vida você viveu."
  },
  AvgDialog_142889_Content_83 = {
    Text = "As lágrimas da mãe caíram sobre sua mão, tão frias que você recuou instintivamente. O ar gélido enviou calafrios percorrendo todo o seu corpo em um instante."
  },
  AvgDialog_142889_Content_84 = {
    Text = "Olhe para as pessoas ao seu redor. Olhe para mim. Olhe para o que deveríamos ser."
  },
  AvgDialog_142889_Content_85 = {
    Text = "Coloque a mão no bolso, Jago."
  },
  AvgDialog_142889_Content_86 = {
    Text = "Tosco, grosseiro, um pouco áspero ao toque — ali havia um <Red:gafanhoto>."
  },
  AvgDialog_142889_Content_87 = {
    Text = "Um gafanhoto feito por <Red:Vera>, chamado <Red:Vera>."
  },
  AvgDialog_142889_Content_88 = {
    Text = "<Shake:<Red:Vera>... não, eu já... faz muito tempo...>"
  },
  AvgDialog_142889_Content_89 = {
    Text = "<Shake:Estou morrendo, estou deitado na cama, tive amigos, tive o amor da minha vida, tive filhos, eu era...>"
  },
  AvgDialog_142889_Content_9 = {
    Text = "Você não consegue conter o riso e tira do bolso aquela bússola que nunca deixou seu lado por décadas, colocando-a na palma da mão de Vera."
  },
  AvgDialog_142889_Content_90 = {
    Text = "Tudo ao seu redor gira em desordem caótica, dois fluxos de pensamento completamente diferentes entrelaçados."
  },
  AvgDialog_142889_Content_91 = {
    Text = "Você agarra a cabeça, curvando-se de dor, ofegante."
  },
  AvgDialog_142889_Content_92 = {
    Text = "Meu Deus, Jago, o que há com você? Você está com uma aparência terrível!"
  },
  AvgDialog_142889_Content_93 = {
    Text = "Orney se lança sobre você do nada, e o zumbido nos seus ouvidos desaparece de uma vez."
  },
  AvgDialog_142889_Content_94 = {
    Text = "Você olha para cima, e Leisha já foi embora."
  },
  AvgDialog_142889_Content_95 = {
    Text = "Orney, Orney, não, não, eu me lembro agora!"
  },
  AvgDialog_142889_Content_96 = {
    Text = "Crescemos juntos, não foi? Estive na sua formatura, no seu casamento. Você não deveria ser tão jovem! Temos a mesma idade, ambos envelhecemos..."
  },
  AvgDialog_142889_Content_97 = {
    Text = "Orney olha para você com uma expressão que você não reconhece de forma alguma, e fica olhando por um longo, longo tempo, até você quase querer fugir."
  },
  AvgDialog_142889_Content_98 = {Text = "Então..."},
  AvgDialog_142889_Content_99 = {
    Text = "Ah, Jago..."
  },
  AvgDialog_142890_Content_1 = {Text = "Ela e Ele"},
  AvgDialog_142890_Content_10 = {
    Text = "Obrigada pelo presente, tio Pontos, mas..."
  },
  AvgDialog_142890_Content_11 = {
    Text = "Deve ter sido uma Vida muito longa e preciosa — por isso, estou disposta a abrir mão da juventude e da Vida eternas."
  },
  AvgDialog_142890_Content_12 = {
    Text = "As pessoas param de falar. Em uníssono, todos se viram para olhar para ti."
  },
  AvgDialog_142890_Content_13 = {
    Text = "Seus tímpanos latejam de dor como se fossem rasgar, e o som do mar pulsando ressoa dentro do seu crânio."
  },
  AvgDialog_142890_Content_14 = {
    Text = "Atravessando as águas abafadas do mar, você ouve um suspiro."
  },
  AvgDialog_142890_Content_15 = {
    Text = "<Red:De novo assim.>"
  },
  AvgDialog_142890_Content_16 = {
    Text = "<Shake:<Red:Chiii... um, glu-glu, gu...>>"
  },
  AvgDialog_142890_Content_17 = {
    Text = "As quatro paredes tremem, tudo goteja em muco úmido e viscoso."
  },
  AvgDialog_142890_Content_18 = {
    Text = "Mesmo que eu tenha te separado disso, a velhice ainda te faz dizer essas <Red:tolices fracas>, assim como Leisha."
  },
  AvgDialog_142890_Content_19 = {
    Text = "Você subitamente percebe que ele <Red:não é mais> Pontos."
  },
  AvgDialog_142890_Content_2 = {
    Text = "Olhando para aquela mão familiar e calorosa, Você finalmente — recuou um passo."
  },
  AvgDialog_142890_Content_20 = {
    Text = "Um medo profundo e gélido, antigo a ponto de ter sido esquecido, vasto, majestoso e difícil de encarar, faz você ficar paralisado, soltando um <Red:grito> silencioso."
  },
  AvgDialog_142890_Content_21 = {
    Text = "ABYSSABYSSABYSSABYSSABYSSABYSSABYSSABYSS\nA@1YS@1@2Y@2@1B@1SSSS@2YA@4@2Y@1\n@1B@1S@2Y@2@2y@1sa@1y@2@4@2Y@1\na@1y@2A@4ss@2ysssssAb@3abyss@2@3\n厄@2@3波@1@3厄@2yssSS@2YA@4\n@1B@1S@2Y@2@2y@1sa@1y@2@4@2Y@1\nA@1YS@1@2Y@2@1B@1SSSS@2YA@4@2Y@1\n@1@2@3扬@1@3斯@2y!!ab@2YA@4\nABYssABySSabySSAByssabYSSa@2SAByssabyssABYSS@2\nABYSSABYSSABYSS@4@3SSABYSS@2@3\n@3@2@4@3@1@3@3!!!!!!!\na@1y@2A@4ss@2ysssssAb@3abyss@2@3\n@3@4YssAby!!!!!!!ABYSSABYSSABy@1\nA@1YS@1@2Y@2@1B@1SSSS@2YA@4@2Y@1@1\n@1B@1S@2Y@2@2y@1sa@1y@2@4<Red:!!!!!!>"
  },
  AvgDialog_142890_Content_22 = {
    Text = "Lembraste-te — aquele som de quando chegaste a Ebwynnos, quando partiste de Ebwynnos, quando regressaste a Ebwynnos."
  },
  AvgDialog_142890_Content_23 = {
    Text = "Pele, costelas, descascando para fora, desdobrando-se, e depois..."
  },
  AvgDialog_142890_Content_24 = {
    Text = "Vazio absoluto, inúmeras mãos, vazio absoluto, vazio absoluto, vazio absoluto, vazio absoluto, vazio absoluto, @2y@2, @4@4@2@4\n@3@2@4@3@1@3@3!!!!!!"
  },
  AvgDialog_142890_Content_25 = {
    Text = "Fique aqui, fique em Ebwynnos."
  },
  AvgDialog_142890_Content_26 = {
    Text = "<Change>Obedeça ao abismo, lance-se no abismo."
  },
  AvgDialog_142890_Content_27 = {Text = "Lua."},
  AvgDialog_142890_Content_28 = {
    Text = "A lua radiante e pura, pendurada ao longe no céu distante."
  },
  AvgDialog_142890_Content_29 = {
    Text = "Suas costelas sua pele seus braços seu peito seu abraço\nseu abraço seu abraço seu abraço seu abraço seu abraço\nseu abraço seu abraço seu abraço seu abraço seu abraço\nEb@3@4wyn@3@2nos\nEbwy@4@3@2n@4@3@2nos\nseu abraço suas costelas sua pele seus braços seu peito\npara sempre para sempre para sempre para sempre para sempre para sempre para\npara para sempre para sempre para sempre para sempre para sempre para sempre para sempre <Red:Ebwynnos>"
  },
  AvgDialog_142890_Content_3 = {
    Text = "...Há sim."
  },
  AvgDialog_142890_Content_30 = {
    Text = "<Red:Ebwynnos que veio ao seu abraço.>"
  },
  AvgDialog_142890_Content_31 = {
    Text = "Camadas e camadas de asas, envolvendo um abraço denso e sólido, irresistível, que tudo engole."
  },
  AvgDialog_142890_Content_32 = {
    Text = "Você é empurrado, você é envolvido, você é acolhido, você está caindo em uma quietude infinita."
  },
  AvgDialog_142890_Content_33 = {Text = "Pare!"},
  AvgDialog_142890_Content_34 = {
    Text = "Uma silhueta forçou caminho pela multidão fria e inconsciente, irrompendo em direção ao vórtice de <Red:\"Pontos\">."
  },
  AvgDialog_142890_Content_35 = {
    Text = "Sem causar qualquer dano, mas o choque extremamente evidente fez a pupila de <Red:\"Pontos\"> tremer, fixando o olhar no rosto dela."
  },
  AvgDialog_142890_Content_36 = {
    Text = "Eu sempre pensei... que havia apenas reconstruído uma Casca vazia."
  },
  AvgDialog_142890_Content_37 = {
    Text = "Assim como as coisas que Jago esqueceu, mas que ainda o influenciam, uma parte de mim também ainda existe."
  },
  AvgDialog_142890_Content_38 = {
    Text = "Deixe-o ir, Pontos, ele não pertence a este lugar."
  },
  AvgDialog_142890_Content_39 = {
    Text = "Oh, Leisha."
  },
  AvgDialog_142890_Content_4 = {Text = "O que?"},
  AvgDialog_142890_Content_40 = {
    Text = "Eu o amo, assim como você o ama."
  },
  AvgDialog_142890_Content_41 = {
    Text = "Orney, White."
  },
  AvgDialog_142890_Content_42 = {
    Text = "Todos os habitantes de Ebwynnos."
  },
  AvgDialog_142890_Content_43 = {
    Text = "Eles se aproximam de você em silêncio, junto com o pesadelo, como uma muralha opressora que avança."
  },
  AvgDialog_142890_Content_44 = {
    Text = "Não, não não não! Não!!"
  },
  AvgDialog_142890_Content_45 = {
    Text = "Leisha olha para você, olha para Jago, e também olha para... você."
  },
  AvgDialog_142890_Content_46 = {
    Text = "Eu sei por que você os quer tanto. Lá não está apenas Jago, há mais de uma alma."
  },
  AvgDialog_142890_Content_47 = {
    Text = "Ah... eles vão esquecer tudo, eles ficarão aqui."
  },
  AvgDialog_142890_Content_48 = {
    Text = "Leisha está presa mais uma vez. Ela torce seu corpo com toda a sua força e olha para você—não para o seu rosto, mas através dele, como se tentasse enxergar a parte mais profunda de sua alma."
  },
  AvgDialog_142890_Content_49 = {
    Text = "Por favor. Quem quer que você seja — eu sei que você está aí dentro. Leve Jago de volta. \nLeve-o de volta à vida que vocês deveriam viver!"
  },
  AvgDialog_142890_Content_5 = {
    Text = "Ele parece não ter entendido sua pergunta e franze levemente as sobrancelhas com incredulidade."
  },
  AvgDialog_142890_Content_50 = {
    Text = "Densas membranas negras se abrem, tudo isso é tão silencioso, tão... irresistível, você quase se dirige em direção a Eles."
  },
  AvgDialog_142890_Content_51 = {
    Text = "Então, você ouviu... a voz de <Red:\"Tu\">."
  },
  AvgDialog_142890_Content_52 = {
    Text = "Acho que <Red:\"Eu\"> já fiz minha escolha."
  },
  AvgDialog_142890_Content_53 = {
    Text = "Das profundezas da consciência, um espírito luta para emergir."
  },
  AvgDialog_142890_Content_54 = {
    Text = "Tendo sobrevivido à grande explosão de Akutê, \"Tu\", como <Red:\"Guardião de Misaq\">, assumiste o controle deste corpo."
  },
  AvgDialog_142890_Content_55 = {
    Text = "Uma radiância prateada cintilou na tua palma."
  },
  AvgDialog_142890_Content_56 = {
    Text = "As memórias dispersas de Jago são reunidas, peça por peça."
  },
  AvgDialog_142890_Content_57 = {
    Text = "Sabe, tio Pontos... a primeira coisa que acabei de lembrar foi algo tão pequeno. Algo que não deveria ter importado nada."
  },
  AvgDialog_142890_Content_58 = {Text = "..."},
  AvgDialog_142890_Content_59 = {
    Text = "\"Pontos\" não fala. Ele te observa em silêncio."
  },
  AvgDialog_142890_Content_6 = {
    Text = "Elas têm significado, essas memórias."
  },
  AvgDialog_142890_Content_60 = {
    Text = "Quando \"Eu\" completei dezoito anos, Orney e eu nos esgueiramos a bordo do vapor mais próximo e imploramos aos marinheiros para nos deixarem trabalhar no convés inferior em troca da passagem. Um cruzeiro gratuito, simples assim."
  },
  AvgDialog_142890_Content_61 = {
    Text = "Na manhã seguinte, vimos o nascer do sol mais lindo que qualquer um de nós já havia visto. Orney disse que desejava que o sol nunca se pusesse. Mas eu não."
  },
  AvgDialog_142890_Content_62 = {
    Text = "Porque o sol se põe. Porque todo dia termina. É isso que faz as coisas que vivemos terem significado."
  },
  AvgDialog_142890_Content_63 = {
    Text = "Chega dessa tolice. Em Ebwynnos, posso fazer o sol nascer e se pôr ao seu bel-prazer, se é isso que você deseja."
  },
  AvgDialog_142890_Content_64 = {
    Text = "Ele fecha os olhos, exausto, sua paciência finalmente esgotada. Você balança a cabeça com firmeza."
  },
  AvgDialog_142890_Content_65 = {
    Text = "O que importa é o tempo que vivemos. Não um sol que fica suspenso para sempre."
  },
  AvgDialog_142890_Content_66 = {
    Text = "Desculpa, Pontos."
  },
  AvgDialog_142890_Content_67 = {
    Text = "Ele ergue a mão. A parede de Gaunts se fecha sobre você."
  },
  AvgDialog_142890_Content_68 = {
    Text = "Ide, servos."
  },
  AvgDialog_142890_Content_7 = {
    Text = "Não para os outros, mas para mim mesmo."
  },
  AvgDialog_142890_Content_8 = {
    Text = "Quero saber que tipo de vida vivi — depois de perder as memórias, por que qualquer alegria me faz sentir que perdi algo."
  },
  AvgDialog_142890_Content_9 = {
    Text = "O espinho do gafanhoto pica levemente a ponta do seu dedo, e você estranhamente se lembra da silhueta daquela criança que chorava à beira da cama."
  },
  AvgDialog_142891_Content_1 = {
    Text = "Segredo de Família"
  },
  AvgDialog_142891_Content_10 = {
    Text = "Ele se chama — hm, ele se chama Vera, porque Vera foi o nome que o vovô escolheu, é o melhor nome."
  },
  AvgDialog_142891_Content_100 = {
    Text = "A ira d'Ele os consumirá, apenas a Alegria pode... @1!"
  },
  AvgDialog_142891_Content_101 = {Text = "Pfft."},
  AvgDialog_142891_Content_102 = {
    Text = "Sangue jorrou, e você ficou olhando, atônito, para Leisha e alguns dos frequentadores habituais da estalagem lutando montados nas mesmas criaturas que vocês haviam cavalgado."
  },
  AvgDialog_142891_Content_103 = {
    Text = "Por que diabos essas coisas malditas vieram parar aqui...\nBem, este deve ser o último."
  },
  AvgDialog_142891_Content_104 = {
    Text = "Espero que estejam apenas de passagem..."
  },
  AvgDialog_142891_Content_105 = {
    Text = "Leisha e seus companheiros foram embora. Você e Pontos ficaram nas sombras. Você teria desabado no chão se ele não estivesse segurando seus ombros."
  },
  AvgDialog_142891_Content_106 = {
    Text = "Você se agarrou à barra das roupas dele. Sua voz era calma e suave, como se ele estivesse se esforçando ao máximo para não te assustar ainda mais."
  },
  AvgDialog_142891_Content_107 = {
    Text = "Jago, é exatamente como o que você viu... essas criaturas que nos trouxeram aqui agora, elas se chamam Gaunts. Nós as fazemos lutar por nós."
  },
  AvgDialog_142891_Content_108 = {
    Text = "Ele fez uma pausa, com a mão apoiada no flanco do Gaunt, estalando os nós dos dedos, como se hesitasse sobre como explicar."
  },
  AvgDialog_142891_Content_109 = {
    Text = "Bem, somos os heróis de uma história de aventura — do tipo que domam dragões, só que nós domamos esses Gaunts."
  },
  AvgDialog_142891_Content_11 = {
    Text = "Vera... O avô precisa de descanso, venha para o papai."
  },
  AvgDialog_142891_Content_110 = {
    Text = "O-o quê... Do que você está falando, Tio Pontos?! Nossa família só administra uma estalagem..."
  },
  AvgDialog_142891_Content_111 = {
    Text = "Depois... depois do acidente, não sobrou muita gente. Leisha fez muito por todos, e as pessoas dependiam dela."
  },
  AvgDialog_142891_Content_112 = {
    Text = "Mas ela não queria que nós, especialmente você, tivéssemos qualquer envolvimento com tudo isso. Essa vida tranquila e anônima é exatamente a que ela queria para nós."
  },
  AvgDialog_142891_Content_113 = {
    Text = "Mas ainda há tantas coisas ruins e horríveis por aí neste mundo, assim como as que você viu hoje. Eu não entendo..."
  },
  AvgDialog_142891_Content_114 = {
    Text = "Um lampejo de frustração cruzou o rosto de Pontos — algo raro para ele — e ele jogou os cabelos dourados soltos da testa para trás."
  },
  AvgDialog_142891_Content_115 = {
    Text = "Ultimamente, os Gaunts me encontraram. E posso sentir algo muito mais poderoso por trás deles. Ele me escolheu, Ele está me chamando."
  },
  AvgDialog_142891_Content_116 = {
    Text = "Eu poderia fazer muito mais. Mas Leisha acha que enquanto nos escondermos bem, tudo ficará bem."
  },
  AvgDialog_142891_Content_117 = {
    Text = "O peso de tudo aquilo te deixou piscando sem entender. Pela primeira vez, você conhecia cada palavra e ainda assim não conseguia fazer sentido de nenhuma delas juntas."
  },
  AvgDialog_142891_Content_118 = {
    Text = "Pontos pareceu se dar conta, voltou ao momento presente e lhe deu um sorriso."
  },
  AvgDialog_142891_Content_119 = {
    Text = "Desculpe, Jago. Joguei muita coisa em cima de você de uma vez?"
  },
  AvgDialog_142891_Content_12 = {
    Text = "Seu filho está um pouco preocupado com sua saúde e quer afastar a neta; ela faz beicinho, quase prestes a chorar."
  },
  AvgDialog_142891_Content_120 = {
    Text = "Vamos voltar antes que Leisha descubra que saímos às escondidas. Temos todo o tempo do mundo para conversar sobre isso."
  },
  AvgDialog_142891_Content_121 = {
    Text = "Ao longe, Leisha pareceu olhar na sua direção. O Tio Pontos fez o gesto de <Italic:silêncio> para você novamente."
  },
  AvgDialog_142891_Content_122 = {Text = "..."},
  AvgDialog_142891_Content_123 = {
    Text = "A janela abriu e fechou novamente, sem fazer nenhum som."
  },
  AvgDialog_142891_Content_124 = {
    Text = "Como se o vento tivesse simplesmente aberto a janela. Lá fora, as ondas quebravam e recuavam. Ouviste o som de Leisha a subir as escadas."
  },
  AvgDialog_142891_Content_125 = {
    Text = "Vocês enterraram os rostos nos travesseiros com a respiração calma, fingindo que aquela ainda era uma noite comum."
  },
  AvgDialog_142891_Content_13 = {
    Text = "Você sorriu e tossiu algumas vezes, esforçando-se para erguer esses ossos Frágeis, apoiando-se na cabeceira da cama."
  },
  AvgDialog_142891_Content_14 = {
    Text = "Vera, não chore. O luar lá fora está tão bonito, apague um pouco a luz."
  },
  AvgDialog_142891_Content_15 = {
    Text = "O vovô ainda tem tempo para te contar mais uma história, deixe-me pensar..."
  },
  AvgDialog_142891_Content_16 = {
    Text = "Seu olhar pousa na bússola de latão que nunca saiu do seu lado. Intocada pelos anos, ela exibe uma suave borda prateada ao luar."
  },
  AvgDialog_142891_Content_17 = {
    Text = "Você passa o polegar lentamente sobre sua superfície, cheio de saudade, e sua voz fica rouca enquanto mergulha nas memórias."
  },
  AvgDialog_142891_Content_18 = {
    Text = "Foi... há mais de sessenta anos, quando eu ainda era criança."
  },
  AvgDialog_142891_Content_19 = {
    Text = "Leisha, o navio está prestes a zarpar. Ele ainda não voltou?"
  },
  AvgDialog_142891_Content_2 = {Text = "Lua."},
  AvgDialog_142891_Content_20 = {
    Text = "Parece que realmente não podemos despedir-nos pessoalmente. Por favor, ao menos aceita este broche..."
  },
  AvgDialog_142891_Content_21 = {
    Text = "O apito do porto soou. Os donos das bugigangas deixadas para trás abandonaram uma pilha tilintante de joias pessoais, com os rostos cheios de pesar enquanto regressavam ao navio."
  },
  AvgDialog_142891_Content_22 = {
    Text = "Meu Deus, pelo amor de @3, meu bem, quando é que seu tio vai aprender a não ter tantos \"amigos\"?"
  },
  AvgDialog_142891_Content_23 = {
    Text = "A tua mãe Leisha olhou para ti com uma expressão entre o divertido e o desamparado, suspirou e enfiou as joias na pequena caixa que seria devolvida ao capitão para entrega na próxima vez que o navio atracasse."
  },
  AvgDialog_142891_Content_24 = {
    Text = "A tua família geria uma pequena estalagem perfeitamente comum numa cidade costeira. Apenas uma coisa era ligeiramente especial..."
  },
  AvgDialog_142891_Content_25 = {
    Text = "Deixa-me ver quem é este pequeno rapaz bonito—"
  },
  AvgDialog_142891_Content_26 = {
    Text = "A Porta se abriu novamente com o vento salgado, e \"aquela coisa especial\" gargalhou enquanto te agarrava pela cintura e te girava no ar."
  },
  AvgDialog_142891_Content_27 = {
    Text = "Pontos! Quantas vezes já te disse, vais arrancar-lhe os braços!"
  },
  AvgDialog_142891_Content_28 = {
    Text = "Tio Pontos!"
  },
  AvgDialog_142891_Content_29 = {
    Text = "Ei, pequeno Jago, olha o que te trouxe!"
  },
  AvgDialog_142891_Content_3 = {
    Text = "A lua cheia mais brilhante que você já viu está suspensa no céu. Seus membros estão Enfraquecer e sem força, e seus pensamentos estão um pouco lentos."
  },
  AvgDialog_142891_Content_30 = {
    Text = "Ele estalou os dedos, abriu a mão no ar, e uma pesada bússola revestida de cobre caiu na tua palma."
  },
  AvgDialog_142891_Content_31 = {
    Text = "É melhor que isso tenha vindo por meios honestos. Esta casa não comporta mais \"lembranças de amor\" e \"corações partidos\"."
  },
  AvgDialog_142891_Content_32 = {
    Text = "Leisha jogou de volta para ele a caixinha de joias com um sorriso irônico e inclinou o queixo em direção à janela, de onde o navio que carregava a outra metade daqueles \"corações partidos\" acabara de partir do porto."
  },
  AvgDialog_142891_Content_33 = {
    Text = "Ah, vamos lá... você me conhece. Nunca fui bom em dizer não."
  },
  AvgDialog_142891_Content_34 = {
    Text = "Sorrindo, Pontos inclinou a cabeça e esquivou-se de um tapa forte de Leisha, depois te colocou no chão."
  },
  AvgDialog_142891_Content_35 = {
    Text = "A propósito, fiz alguns novos amigos. Precisamos conversar, Leisha."
  },
  AvgDialog_142891_Content_36 = {
    Text = "Sobre as coisas que você não quer falar."
  },
  AvgDialog_142891_Content_37 = {
    Text = "Ocupado demais estudando seu novo tesouro, você não percebeu a expressão sombria no rosto de Leisha. Pontos despenteou seu cabelo."
  },
  AvgDialog_142891_Content_38 = {
    Text = "Sua mãe e eu temos algumas coisas para conversar. Se meu jovem favorito topar subir para brincar lá em cima por um tempo, eu lhe contarei histórias maravilhosas das minhas viagens. Temos um acordo?"
  },
  AvgDialog_142891_Content_39 = {
    Text = "Ele estendeu a mão, e por causa da bússola você a aceitou — é o \"Aperto de Mão do Acordo\" que pertencia apenas aos dois."
  },
  AvgDialog_142891_Content_4 = {
    Text = "Ao levantar a mão, as rugas que representam a velhice já se espalharam por toda a sua pele."
  },
  AvgDialog_142891_Content_40 = {Text = "..."},
  AvgDialog_142891_Content_41 = {
    Text = "Deitado no chão do quarto de cima, você tirou um mapa e começou, em profunda concentração, a usar a bússola para encontrar os rumos daquelas histórias de navegação."
  },
  AvgDialog_142891_Content_42 = {
    Text = "No entanto, esta casa era demasiado velha, e o oceano e o vento desgastavam-na constantemente. Algumas palavras dispersas ainda subiam pelas frestas do soalho."
  },
  AvgDialog_142891_Content_43 = {
    Text = "...já... dizer... não podes simplesmente... esconder não é solução."
  },
  AvgDialog_142891_Content_44 = {
    Text = "...Aqueles <Italic:seres>... eu posso... Meu talento..."
  },
  AvgDialog_142891_Content_45 = {
    Text = "O tom do tio Pontos tornava-se cada vez mais urgente. Mesmo quando estavas prestes a encostar o ouvido mais perto por curiosidade—"
  },
  AvgDialog_142891_Content_46 = {
    Text = "CRASH! THUD!"
  },
  AvgDialog_142891_Content_47 = {
    Text = "A Porta foi aberta com um estrondo, Pontos foi arrastado pelo colarinho e jogado para dentro, enquanto Leisha franziu o rosto com uma expressão que significava \"não há negociação\"."
  },
  AvgDialog_142891_Content_48 = {
    Text = "Eu não concordo, Pontos. Meu único desejo é que todos vocês fiquem seguros e vivos... Fique longe desses seus novos amigos."
  },
  AvgDialog_142891_Content_49 = {
    Text = "Se as coisas realmente saírem do controle, eu levo todos vocês embora daqui."
  },
  AvgDialog_142891_Content_5 = {
    Text = "Ah, então já cheguei a essa idade... Talvez esta seja a última noite."
  },
  AvgDialog_142891_Content_50 = {
    Text = "Ei, Leisha, eu não sou mais criança! Não podemos simplesmente continuar fugindo para sempre."
  },
  AvgDialog_142891_Content_51 = {
    Text = "Aprenda a me ajudar a cuidar dos negócios primeiro. Pare de ficar vagando por aí o dia todo antes de falar sobre isso."
  },
  AvgDialog_142891_Content_52 = {
    Text = "Você raramente ouvira Leisha falar com tanta rispidez. Ela respirou fundo e forçou um sorriso tenso para você."
  },
  AvgDialog_142891_Content_53 = {
    Text = "Jago, faça um favor à mamãe. Cuide do seu tio, pelo menos esta noite não deixe ele sair por aí vagando."
  },
  AvgDialog_142891_Content_54 = {
    Text = "Ela deixou essas palavras para trás e desceu às pressas para os livros de contas que pareciam nunca ter fim, como se ansiosa para encerrar a conversa o mais rápido possível."
  },
  AvgDialog_142891_Content_55 = {
    Text = "Pontos ergueu uma sobrancelha e deu de ombros para você."
  },
  AvgDialog_142891_Content_56 = {
    Text = "Bem então, Jago, parece que podemos adiantar um pouquinho a hora das histórias."
  },
  AvgDialog_142891_Content_57 = {Text = "..."},
  AvgDialog_142891_Content_58 = {
    Text = "Talvez aqueles contos que despencavam das cabines dos navios junto com a carga fossem emocionantes e fantásticos demais. Mesmo à meia-noite, você não dormia profundamente."
  },
  AvgDialog_142891_Content_59 = {
    Text = "O luar do lado de fora da janela lançava um brilho prateado sobre suas pálpebras. Algo o bloqueou."
  },
  AvgDialog_142891_Content_6 = {
    Text = "As memórias gradualmente retornam, mas estranhamente, não há medo da morte em seu coração. Em vez disso, você sorri com uma profunda paz interior."
  },
  AvgDialog_142891_Content_60 = {
    Text = "Um clique — o trinco da janela. Você abriu os olhos. A janela já estava escancarada."
  },
  AvgDialog_142891_Content_61 = {Text = "!"},
  AvgDialog_142891_Content_62 = {
    Text = "Tio Pontos, você não pode sair pela janela! A mamãe vai ficar brava!"
  },
  AvgDialog_142891_Content_63 = {
    Text = "Mais da metade de Pontos já havia ultrapassado o parapeito da janela, e Você, sem pensar, correu para abraçá-lo, esquecendo até de considerar por que ele parecia estar... suspenso no ar."
  },
  AvgDialog_142891_Content_64 = {
    Text = "Espere, cuidado!"
  },
  AvgDialog_142891_Content_65 = {
    Text = "A sensação de imponderabilidade chegou, e então—"
  },
  AvgDialog_142891_Content_66 = {Text = "VUUSH!"},
  AvgDialog_142891_Content_67 = {Text = "Rasga—!"},
  AvgDialog_142891_Content_69 = {
    Text = "...! ...!!!!"
  },
  AvgDialog_142891_Content_7 = {
    Text = "Seus entes queridos estão reunidos ao seu redor, e a menor das netas, Vera, ainda não entende nada, apenas se apoia carinhosamente ao lado de sua mão."
  },
  AvgDialog_142891_Content_70 = {
    Text = "Você foi puxado para cima pelo tecido na sua cintura, a estranha sensação de pelos macios roçando seu rosto."
  },
  AvgDialog_142891_Content_71 = {
    Text = "Quando você abriu os olhos, um calafrio de horror percorreu sua espinha."
  },
  AvgDialog_142891_Content_72 = {Text = "Pon—"},
  AvgDialog_142891_Content_73 = {
    Text = "A cauda de uma criatura sem feições e indescritível estava enganada atrás das suas costas, sua ponta rastejando coberta de espinhos horrendos."
  },
  AvgDialog_142891_Content_74 = {
    Text = "Você não teve tempo de perceber que aquela coisa aterrorizante claramente acabara de te salvar — incontrolavelmente, um grito sufocado forçou caminho pela sua garganta."
  },
  AvgDialog_142891_Content_75 = {Text = "Shh!"},
  AvgDialog_142891_Content_76 = {
    Text = "Pontos, deitado sobre aquela criatura sem rosto, puxou Você para cima, tapando firmemente sua boca; a criatura abriu suas enormes asas de morcego e deslizou silenciosamente para dentro da noite."
  },
  AvgDialog_142891_Content_77 = {
    Text = "Não tenha medo. Eles não vão te machucar."
  },
  AvgDialog_142891_Content_78 = {
    Text = "Não há tempo, Jago. Fique quieto—eu explico tudo depois."
  },
  AvgDialog_142891_Content_79 = {
    Text = "Pontos envolveu um braço em volta dos seus ombros para te acalmar, colocando você entre ele e a criatura, seu corpo abaixado, seus olhos fixos nos recifes rochosos em um canto remoto do porto."
  },
  AvgDialog_142891_Content_8 = {
    Text = "Vovô, quando você vai brincar comigo de novo? Olha, já aprendi o que você me ensinou da última vez."
  },
  AvgDialog_142891_Content_80 = {
    Text = "Antes que você pudesse perguntar qualquer coisa, um som sinistro emergiu rastejando do mar, como vermes."
  },
  AvgDialog_142891_Content_81 = {
    Text = "<Shake:<Red:Farfalhar, farfalhar...>>"
  },
  AvgDialog_142891_Content_82 = {
    Text = "<Shake:<Red:Plaft, plaft... Splat—>>"
  },
  AvgDialog_142891_Content_83 = {
    Text = "!... Urgh..."
  },
  AvgDialog_142891_Content_84 = {
    Text = "Primeiro vieram pés com garras cobertos de escamas, depois braços—ou talvez membros macios e retorcidos de artrópodes—corpos incrustados de cracas e uma gosma blasfemamente abominável..."
  },
  AvgDialog_142891_Content_85 = {
    Text = "Você só conhecia o mar como uma fonte inesgotável de alimento. Jamais imaginou que ele também pudesse abrigar tais abominações. Seus olhos saltados e horrendos estavam cheios de malícia enquanto encaravam os edifícios da cidade."
  },
  AvgDialog_142891_Content_86 = {
    Text = "<Change>@4 Tipu... Por onde passar..."
  },
  AvgDialog_142891_Content_87 = {
    Text = "<Change>...Deve passar por aqui... Alimentar a Dissolução, entregar-se à Dissolução! Carne, carne!!"
  },
  AvgDialog_142891_Content_88 = {
    Text = "<Small:<Shake:Tio, mons, há um monstro!!>>"
  },
  AvgDialog_142891_Content_89 = {
    Text = "No segundo seguinte, a criatura alada sem rosto sob você mergulhou para baixo. Pontos abriu seus dedos ossudos, e uma luz obscura avançou em direção aos dois monstros miseráveis."
  },
  AvgDialog_142891_Content_9 = {
    Text = "Ela segura um gafanhoto torto e o coloca sobre o cobertor."
  },
  AvgDialog_142891_Content_90 = {Text = "Ngh, mmph!"},
  AvgDialog_142891_Content_91 = {
    Text = "Eles desabaram sem vida no chão, como duas estátuas de pedra decepadas."
  },
  AvgDialog_142891_Content_92 = {
    Text = "Tap— um toque suave."
  },
  AvgDialog_142891_Content_93 = {
    Text = "Então as duas metades do corpo se lançaram ao chão, transformando-se em pó cinzento levado pelo vento do mar."
  },
  AvgDialog_142891_Content_94 = {
    Text = "Ufa, eu sabia que sempre haveria um ou dois que escapariam, Leisha e os outros ainda são descuidados demais."
  },
  AvgDialog_142891_Content_95 = {
    Text = "<Shake:Mamãe e os outros? Tio Pontos, o que está acontecendo afinal?!>"
  },
  AvgDialog_142891_Content_96 = {
    Text = "O medo quase fez suas pernas cederem, e você quase escorregou das costas lisas da criatura."
  },
  AvgDialog_142891_Content_97 = {
    Text = "Aguente mais um pouco. Preciso ter certeza de que estão bem primeiro."
  },
  AvgDialog_142891_Content_98 = {
    Text = "Pontos deu um tapinha no seu ombro e guiou a criatura para carregá-los dois em direção à costa no outro lado da cidade."
  },
  AvgDialog_142891_Content_99 = {Text = "..."},
  AvgDialog_142892_Content_1 = {
    Text = "Quando Você Foi Embora"
  },
  AvgDialog_142892_Content_10 = {
    Text = "Areia amarela."
  },
  AvgDialog_142892_Content_11 = {
    Text = "Campos de Neve."
  },
  AvgDialog_142892_Content_12 = {Text = "Vazio."},
  AvgDialog_142892_Content_13 = {
    Text = "E então de volta à noite."
  },
  AvgDialog_142892_Content_14 = {
    Text = "Esta não é uma jornada ou trajetória que humanos possam compreender. Tempo e espaço perderam todo o significado. Você simplesmente continua atravessando, patrulhando. Você experiencia tudo, e então é destruído por tudo."
  },
  AvgDialog_142892_Content_15 = {
    Text = "Já que ousaram se intrometer, bani-los do mundo mortal! Façam-nos nos temer! Façam-nos lembrar do meu nome!"
  },
  AvgDialog_142892_Content_16 = {
    Text = "Pontos gasta o poder que tomou com abandono imprudente, e os seres que o conquistaram agora despedaçam seus inimigos também."
  },
  AvgDialog_142892_Content_17 = {
    Text = "Incontáveis monstros retorcidos e repugnantes são caçados pelos Thrall-Gaunts e pelos Gauntwards."
  },
  AvgDialog_142892_Content_18 = {
    Text = "São atravessados, tornados parte da festividade, arrancando assobios e risos de celebração sem fim."
  },
  AvgDialog_142892_Content_19 = {
    Text = "Não, não, de novo não, nãonãonãonãonão!!!!!!"
  },
  AvgDialog_142892_Content_2 = {
    Text = "A estranha sensação de pelo liso, o espinho afiado na sua cauda, enormes asas membranosas cortando silenciosamente o céu noturno."
  },
  AvgDialog_142892_Content_20 = {
    Text = "Você viu com seus próprios olhos o feixe que Pontos desferiu reduzir o fanático a pó, mas imediatamente depois, o corpo Dele se remontou mais uma vez, um uivo de medo irrompendo de Sua boca."
  },
  AvgDialog_142892_Content_21 = {
    Text = "Este era o mais devoto de todos os cultistas. E agora já suportou morte e remontagem em agonia, mais vezes do que alguém poderia contar."
  },
  AvgDialog_142892_Content_22 = {
    Text = "Tio Pontos, essa... <Italic:coisa>... está voltando à vida?"
  },
  AvgDialog_142892_Content_23 = {
    Text = "Não. Está simplesmente morrendo e voltando, repetidamente, para saborear o sofrimento que lhe foi prometido."
  },
  AvgDialog_142892_Content_24 = {
    Text = "Às vezes eu os deixo morrer, desde que renunciem à adoração daqueles deuses imundos e blasfemos."
  },
  AvgDialog_142892_Content_25 = {
    Text = "Mas se a fé deles for profunda demais, então nem mesmo a morte pode livrá-los do sofrimento."
  },
  AvgDialog_142892_Content_26 = {
    Text = "Falando tão casualmente como se fosse um assunto trivial, Pontos ergueu a palma. Uma força invisível abriu os braços do fanático, curvou seu tronco para frente e o forçou a se ajoelhar prostrado diante de Pontos."
  },
  AvgDialog_142892_Content_27 = {
    Text = "Agora, diga-me mais uma vez — você ainda adora seu deus imundo?"
  },
  AvgDialog_142892_Content_28 = {
    Text = "<LightGray:*soluço> Não... não, por favor, por favor, deixe-me morrer, Desde Que o senhor me deixe morrer!"
  },
  AvgDialog_142892_Content_29 = {
    Text = "<Shake:Hahaha, hahahahahaha, não há salvador, simplesmente não há salvador, apenas AB@2S, apenas @2@3!!>"
  },
  AvgDialog_142892_Content_3 = {
    Text = "Pontos leva você junto na caçada que precede a festividade noturna de Ebwynnos."
  },
  AvgDialog_142892_Content_30 = {
    Text = "Muito bem, presa. Erga a cabeça. Exponha sua garganta."
  },
  AvgDialog_142892_Content_31 = {
    Text = "O fanático, com a mente em crash, emitiu soluços distorcidos e gargalhadas loucas, avançando de joelhos, erguendo o pescoço em uma postura estranha."
  },
  AvgDialog_142892_Content_32 = {
    Text = "Eu concederei a morte a você."
  },
  AvgDialog_142892_Content_33 = {
    Text = "A luz derreteu através de Sua garganta como uma faca quente na manteiga. Seu corpo subitamente desmoronou em cinzas e pó, varrido pelo vento para o oceano."
  },
  AvgDialog_142892_Content_34 = {
    Text = "Desta vez, o cultista miserável não volta."
  },
  AvgDialog_142892_Content_35 = {
    Text = "Para onde vão os outros? Os monstros que são capturados?"
  },
  AvgDialog_142892_Content_36 = {
    Text = "Eles também estão em Ebwynnos."
  },
  AvgDialog_142892_Content_37 = {
    Text = "Um Ebwynnos igualmente eterno, só que sem a alegria."
  },
  AvgDialog_142892_Content_38 = {
    Text = "Lá, nada existe. Até mesmo a dor seria considerada uma misericórdia."
  },
  AvgDialog_142892_Content_39 = {
    Text = "Você entende pela metade. A luz da lua brilha. Os Gaunts guardam você enquanto esta estranha jornada se aproxima do fim."
  },
  AvgDialog_142892_Content_4 = {
    Text = "Por incontáveis meios além da compreensão, o povo de Ebwynnos caça sua \"presa\" por incontáveis dimensões."
  },
  AvgDialog_142892_Content_40 = {
    Text = "Feche os olhos, Jago."
  },
  AvgDialog_142892_Content_41 = {
    Text = "Uma escuridão úmida, familiar e íntima abraçou você, engoliu você por inteiro."
  },
  AvgDialog_142892_Content_42 = {
    Text = "Você retornou à Casa Alta. Pontos desceu da carruagem, revelando o prelúdio de mais uma festividade."
  },
  AvgDialog_142892_Content_43 = {
    Text = "Esta criança parece ter se afeiçoado bastante a você."
  },
  AvgDialog_142892_Content_44 = {
    Text = "Perto do parapeito da janela junto ao terraço, Pontos se afastou da animada multidão e estendeu a mão em direção ao Pesadelo que circulava do lado de fora da janela."
  },
  AvgDialog_142892_Content_45 = {
    Text = "Não consigo me lembrar de muitas coisas claramente por algum motivo, mas... Tio Pontos, você não é mais humano, e este não é mais o mundo como eu o conheço, é?"
  },
  AvgDialog_142892_Content_46 = {
    Text = "Eu já estou morto?"
  },
  AvgDialog_142892_Content_47 = {
    Text = "Aparentemente não esperando que você perguntasse tão diretamente, Pontos ergueu as sobrancelhas surpreso, e então—riu."
  },
  AvgDialog_142892_Content_48 = {
    Text = "Meu querido pequeno amigo, claro que não."
  },
  AvgDialog_142892_Content_49 = {
    Text = "Fique em Ebwynnos, e você viverá a vida grandiosa e extraordinária que ansiava quando lia livros de histórias na infância. Você nunca mais será desgastado."
  },
  AvgDialog_142892_Content_5 = {
    Text = "Aquele brilho sinistro ainda pulsa de dentro das janelas da casa."
  },
  AvgDialog_142892_Content_50 = {
    Text = "Nós partiremos em aventuras, escaparemos do mundo mundano. Aqueles inimigos que trouxeram turbulência e desastre às nossas vidas serão finalmente derrotados até que nunca mais ousem mostrar suas caras."
  },
  AvgDialog_142892_Content_51 = {
    Text = "Você respirou fundo. Sentiu aquele gafanhoto de novo—tosco, áspero, levemente espinhoso."
  },
  AvgDialog_142892_Content_52 = {
    Text = "Sim, tudo isso parece maravilhoso."
  },
  AvgDialog_142892_Content_53 = {
    Text = "Mas que preço devo pagar, Tio Pontos?"
  },
  AvgDialog_142892_Content_54 = {
    Text = "Sua sobrancelha franziu com uma lentidão excruciante, carregando um tipo de arrogância altiva desconhecida para você."
  },
  AvgDialog_142892_Content_55 = {
    Text = "O preço é Apenas... algo que não tem importância alguma, algo que Você não precisa e não vai lembrar. <Red:Dê-o a mim>, Jago."
  },
  AvgDialog_142892_Content_56 = {
    Text = "No momento em que ele terminou de falar, a cauda farpada do pesadelo desceu de fora da janela em direção ao seu bolso."
  },
  AvgDialog_142892_Content_57 = {
    Text = "Em direção ao gafanhoto torto que você estava escondendo."
  },
  AvgDialog_142892_Content_58 = {Text = "Não!"},
  AvgDialog_142892_Content_59 = {
    Text = "Você instintivamente tropeçou para trás, mas o movimento pareceu irritar Pontos, e ele agarrou seu braço."
  },
  AvgDialog_142892_Content_6 = {
    Text = "Gaunt após Gaunt circula no ar, até que Pontos — de pé ao seu lado em uma carruagem que irradia um indescritível brilho perolado — solta um grito retumbante."
  },
  AvgDialog_142892_Content_60 = {
    Text = "Você simplesmente não entende, criança. Sabe quanto esforço gastei para encontrar você..."
  },
  AvgDialog_142892_Content_61 = {
    Text = "Coo–coo, coo–coo..."
  },
  AvgDialog_142892_Content_62 = {
    Text = "Você congelou no lugar. Não eram apenas os dedos de Pontos pressionando contra sua pele—um medo sem nome fez você olhar para cima, e as pupilas azul–profundo de Pontos pesaram sobre você."
  },
  AvgDialog_142892_Content_63 = {
    Text = "Já que quer ver, então olhe bem—exatamente de que tipo de coisa eu resgatei você."
  },
  AvgDialog_142892_Content_64 = {
    Text = "Você foi <Red:engolido> novamente."
  },
  AvgDialog_142892_Content_65 = {Text = "..."},
  AvgDialog_142892_Content_66 = {
    Text = "Ei, ei, velho amigo, ouviu o que eu disse? Você viajou de novo! Cuidado!"
  },
  AvgDialog_142892_Content_67 = {
    Text = "Splash! Água lamacenta atingiu seu rosto, e você voltou à realidade, olhando atordoado para a pessoa ao seu lado. Envelhecido, curvado e tagarelando sem parar—mas você o reconheceu. Era inconfundivelmente um Orney idoso."
  },
  AvgDialog_142892_Content_68 = {
    Text = "Esses malditos Marinheiros, completamente fora de controle! Se quer saber, todas aquelas viagens deixaram seus corações selvagens. Não conseguem manter a cabeça em nada prático!"
  },
  AvgDialog_142892_Content_69 = {
    Text = "Orney? ...Do que você está falando? Você sempre sonhou em ser marinheiro quando éramos crianças, em ver todos os continentes!"
  },
  AvgDialog_142892_Content_7 = {
    Text = "Capturem-nos, garantam que nunca mais possam partir, façam-nos sofrer aqui por toda a eternidade!"
  },
  AvgDialog_142892_Content_70 = {
    Text = "Eu realmente disse algo assim? Não seja ridículo. Na nossa idade, você deveria saber que estabilidade é o melhor."
  },
  AvgDialog_142892_Content_71 = {
    Text = "Você esqueceu, velho amigo, desde o segundo ano da faculdade não discutimos mais isso. Conversamos sobre as notícias do jornal, uma pilha interminável de relatórios malditos, aposentadoria, o jantar em família a cada duas semanas."
  },
  AvgDialog_142892_Content_72 = {
    Text = "Ele deu um tapinha no seu ombro e, trêmulo, pegou dois sacos de papel no guichê da farmácia."
  },
  AvgDialog_142892_Content_73 = {
    Text = "Você não é igual a mim? Depois de se formar e voltar pra cá, ainda bem, a gente nem se dá mais ao trabalho de fazer uma viagem longa."
  },
  AvgDialog_142892_Content_74 = {
    Text = "Esta maldita artrite. Graças a Deus — além de você e desses analgésicos, não há mais nada que me obrigue a sair de casa."
  },
  AvgDialog_142892_Content_75 = {
    Text = "Solidão, ha! Quando éramos jovens, achávamos que era tão real quanto o Pé Grande."
  },
  AvgDialog_142892_Content_76 = {
    Text = "Orney continuava tagarelando sobre alguma coisa. Você ficou encarando os lábios dele abrindo e fechando, e uma onda repentina de tontura te arrancou da rotina mundana."
  },
  AvgDialog_142892_Content_77 = {Text = "..."},
  AvgDialog_142892_Content_78 = {
    Text = "Você viu no que aqueles dias mundanos transformaram o Orney? Vá dar outra olhada—naquilo que você trocou."
  },
  AvgDialog_142892_Content_79 = {
    Text = "Você se vê, deitado na cama, murcho e consumido."
  },
  AvgDialog_142892_Content_8 = {Text = "Nuvens."},
  AvgDialog_142892_Content_80 = {
    Text = "Claro, eles vão ficar tristes no começo, derramar algumas lágrimas por você."
  },
  AvgDialog_142892_Content_81 = {
    Text = "Você vê um casal e a filhinha deles saindo para passear, consolando um ao outro."
  },
  AvgDialog_142892_Content_82 = {
    Text = "Mas em uma semana, ou até em alguns dias, eles vão superar isso."
  },
  AvgDialog_142892_Content_83 = {
    Text = "Jantares, caminhadas, a universidade, quem sabe? As crianças podem aguentar um pouco mais. Não muito, claro."
  },
  AvgDialog_142892_Content_84 = {
    Text = "No fim, nada restará. Ninguém vai se lembrar de você."
  },
  AvgDialog_142892_Content_85 = {
    Text = "Inverno, primavera, outro inverno. Você observa a poeira pousar lentamente pela casa."
  },
  AvgDialog_142892_Content_86 = {
    Text = "Você entende agora, Jago? Eu simplesmente trouxe as partes interessantes de todos vocês... as partes vibrantes... para Ebwynnos."
  },
  AvgDialog_142892_Content_87 = {
    Text = "Sua casca de corpo está prestes a morrer. Com ou sem você, todos que você já conheceu continuarão vivendo suas próprias vidas, vidas que não têm nada a ver com você."
  },
  AvgDialog_142892_Content_88 = {
    Text = "A voz de Pontos ecoa nos seus ouvidos, e no segundo seguinte, você reaparece no grande salão da Casa Alta de Ebwynnos."
  },
  AvgDialog_142892_Content_89 = {
    Text = "Agora, Jago, pense nisso—pense com cuidado. Abandone aquela casca, descarte essas memórias sem sentido e fique conosco."
  },
  AvgDialog_142892_Content_9 = {
    Text = "Terra aniquilada."
  },
  AvgDialog_142892_Content_90 = {
    Text = "Orney, Tio White e todos no salão de dança lotado de Ebwynnos parecem de repente prestar atenção."
  },
  AvgDialog_142892_Content_91 = {
    Text = "Ei, por que vocês dois estão com essa cara? Acabamos de conquistar mais uma grande vitória!"
  },
  AvgDialog_142892_Content_92 = {
    Text = "Vamos, Jago, beba bem conosco. Não há nada com que se preocupar em Ebwynnos!"
  },
  AvgDialog_142892_Content_93 = {
    Text = "Eles riem de bom grado, reunindo você em meio a eles."
  },
  AvgDialog_142892_Content_94 = {
    Text = "As pessoas agora estão passando seus espólios adiante. As marés estão zumbindo em seus ouvidos novamente."
  },
  AvgDialog_142892_Content_95 = {
    Text = "Pontos estende a mão, esperando que você a tome."
  },
  AvgDialog_142892_Content_96 = {
    Text = "Assim como aquele \"aperto de mão de acordo\" que vocês dois combinaram quando crianças."
  },
  AvgDialog_142893_Content_1 = {Text = "O Motivo"},
  AvgDialog_142893_Content_10 = {
    Text = "<Red:Não deveria ser assim.>"
  },
  AvgDialog_142893_Content_11 = {
    Text = "Devias ter sido tu a descobrir acidentalmente a tua linhagem, a Mãe a ser convencida pelo Tio Pontos a guiar-te, e juntos embarcariam numa jornada, vivendo todo o tipo de coisas emocionantes, empolgantes e maravilhosas."
  },
  AvgDialog_142893_Content_12 = {
    Text = "<Shake:E então você se tornará um grande <Red:herói>, é assim que está escrito nos romances de aventura.>"
  },
  AvgDialog_142893_Content_13 = {
    Text = "Jago! Anime-se, está tudo bem, sua mãe é a mais forte dos Gauntwards que já vi, tudo vai se resolver!"
  },
  AvgDialog_142893_Content_14 = {
    Text = "Eu... Tio Pontos, Mãe..."
  },
  AvgDialog_142893_Content_15 = {
    Text = "A outrora pacífica cidade estava completamente engolida pelas chamas."
  },
  AvgDialog_142893_Content_16 = {
    Text = "Apenas um dia havia passado, e fanáticos surgiram de repente, em massa, inundando tudo que seus olhos podiam alcançar."
  },
  AvgDialog_142893_Content_17 = {
    Text = "Entre eles havia tanto humanos quanto monstros por completo, e os ataques indiscriminados faziam a cidade inteira Queimar em chamas."
  },
  AvgDialog_142893_Content_18 = {
    Text = "Sangue com um sabor salgado e metálico salpicou-te o rosto e o corpo. Pontos canalizava desesperadamente o apito de caça na sua mão, abrindo um caminho à força bruta ao lado do seu Pesadelo."
  },
  AvgDialog_142893_Content_19 = {
    Text = "Pontos, pega no Jago e foge!"
  },
  AvgDialog_142893_Content_2 = {
    Text = "Naquela noite, esgotado de tanto susto e tanto pensar, você logo adormeceu."
  },
  AvgDialog_142893_Content_20 = {
    Text = "Leisha, que estava com os outros Gauntwards se esforçando ao máximo para conter a maré de monstros, ao ver que você estava bem, seus Olhos se iluminaram, e ela gritou com toda a força para Pontos."
  },
  AvgDialog_142893_Content_21 = {Text = "Screeee!"},
  AvgDialog_142893_Content_22 = {
    Text = "Outra cabeça semelhante a uma anémona-do-mar foi dilacerada pelas garras afiadas do Pesadelo. Leisha lançou casualmente um raio da mesma luz branca críptica que Pontos, impedindo-o de avançar na direção dela."
  },
  AvgDialog_142893_Content_23 = {
    Text = "Não podemos vencer esta, mas ainda podemos ganhar-vos algum tempo. Foge, o mais longe que conseguires!"
  },
  AvgDialog_142893_Content_24 = {
    Text = "Que brincadeira é essa, você já resolveu situações com muito mais inimigos do que isso com facilidade, não vai acontecer nada! E além disso, você sabe, sempre temos um jeito."
  },
  AvgDialog_142893_Content_25 = {
    Text = "Você não sabia o que o Tio Pontos queria dizer com \"uma saída\". Você apenas viu seu olhar pousar naquele apito de caça, o mesmo que ele não havia largado desde o dia em que voltou."
  },
  AvgDialog_142893_Content_26 = {
    Text = "Não, <Red:jamais.>"
  },
  AvgDialog_142893_Content_27 = {
    Text = "<Shake:Eu sei o que você está pensando. <Red:Meu irmão jamais ficará preso para sempre naquele lugar maldito!>   >"
  },
  AvgDialog_142893_Content_28 = {
    Text = "Abracem o Festim@1, alimentem a Erosão!"
  },
  AvgDialog_142893_Content_29 = {Text = "Leisha!!!"},
  AvgDialog_142893_Content_3 = {
    Text = "Tanto você quanto Pontos pensaram que teriam muitas outras oportunidades de conversar sobre isso."
  },
  AvgDialog_142893_Content_30 = {
    Text = "Em meio ao som furioso de escamas se rompendo, um fanático com metade do corpo já rasgado tinha seus globos oculares Carmesim completamente saltados, grunhindo em Fúria enquanto se lançava sobre Leisha."
  },
  AvgDialog_142893_Content_31 = {
    Text = "...O som de ranger de dentes de pele e músculo sendo despedaçados."
  },
  AvgDialog_142893_Content_32 = {
    Text = "O som de dois corpos se chocando contra a estrada de paralelepípedos."
  },
  AvgDialog_142893_Content_33 = {
    Text = "O som de entranhas se derramando."
  },
  AvgDialog_142893_Content_34 = {
    Text = "Então, o mundo silenciou num instante. Você não conseguia ouvir nada, ver nada."
  },
  AvgDialog_142893_Content_35 = {
    Text = "Sangue, céu noturno, lua."
  },
  AvgDialog_142893_Content_36 = {
    Text = "Uma lua cor de sangue, pendurada distante no céu longínquo."
  },
  AvgDialog_142893_Content_37 = {
    Text = "Ah... ahhh."
  },
  AvgDialog_142893_Content_38 = {
    Text = "AAAAAAAAHHHHH!!!!!"
  },
  AvgDialog_142893_Content_39 = {
    Text = "Após um breve gemido sem fôlego espremido das profundezas de sua garganta, Pontos soltou algo que você nunca havia ouvido em toda a sua vida."
  },
  AvgDialog_142893_Content_4 = {
    Text = "<Red:Mas não tiveram.>"
  },
  AvgDialog_142893_Content_40 = {
    Text = "Um lamento completamente desumano."
  },
  AvgDialog_142893_Content_41 = {
    Text = "Ir— Irmã... Leisha, LEISHA!!!"
  },
  AvgDialog_142893_Content_42 = {
    Text = "Um zumbido agudo atravessou seu cérebro, e uma onda avassaladora de perplexidade se abateu sobre você como um maremoto. Não, não, não, não, não não não não não não..."
  },
  AvgDialog_142893_Content_43 = {
    Text = "Ninguém sobreviveu. Os Gaunt-guardiões, que durante o dia não pareciam mais do que vizinhos amigáveis, caíam um após o outro. Os moradores comuns gritavam no mar de fogo e na maré de monstros."
  },
  AvgDialog_142893_Content_44 = {
    Text = "Mas você não conseguia mais ouvir nada disso. Seu corpo havia te traído completamente, e uivava junto com eles, um grito cru e lancinante."
  },
  AvgDialog_142893_Content_45 = {
    Text = "<Change>Sacrifício! Sacrificai-os todos ao <Red:Êxtase>!"
  },
  AvgDialog_142893_Content_46 = {
    Text = "Os outros cultistas te localizaram sem a menor dificuldade, e bem quando aquelas garras escamosas, pingando de limo blasfemo, se estenderam em sua direção..."
  },
  AvgDialog_142893_Content_47 = {
    Text = "Pontos soprou o apito de caça."
  },
  AvgDialog_142893_Content_48 = {
    Text = "Você jamais havia ouvido um som tão estridente e tão antigo. Um poder irracional atravessou diretamente seus tímpanos e martelou cada último fragmento de sanidade em sua mente."
  },
  AvgDialog_142893_Content_49 = {
    Text = "Uma pressão incomparável e vasta desabou sobre a terra!"
  },
  AvgDialog_142893_Content_5 = {Text = "Hisss—!"},
  AvgDialog_142893_Content_50 = {
    Text = "Uma força invisível e enorme pressionou Pontos contra o chão, mas ele não parecia sentir nada, os olhos escancarados ao ponto de rasgar enquanto recitava uma oração incompreensível."
  },
  AvgDialog_142893_Content_51 = {
    Text = "Ó @2, @4,@3 Senhor do Abismo, eu te invoco em nome de @3..."
  },
  AvgDialog_142893_Content_52 = {
    Text = "Incontáveis presenças semelhantes a braços negros se estenderam pelas fissuras mais profundas do que o oceano mais antigo, alcançando a única <Red:presa> que desejavam."
  },
  AvgDialog_142893_Content_53 = {
    Text = "<Shake:Alcançando o <Red:mestre >escolhido por Eles.>"
  },
  AvgDialog_142893_Content_54 = {
    Text = "<Change>Tome minha carne, tome minha alma, tome tudo!"
  },
  AvgDialog_142893_Content_55 = {
    Text = "Naquele rosto que sempre ostentava um sorriso despreocupado, surgiu agora uma expressão de determinação trágica e abandono temerário."
  },
  AvgDialog_142893_Content_56 = {
    Text = "Enquanto algo muito maior e mais torrencial se fundia nele, asas que obscureciam o céu se ergueram, formando camada após camada de barreiras negras como breu."
  },
  AvgDialog_142893_Content_57 = {
    Text = "<Change>Responda à oração do seu Executor — reduza-os todos a pó!!"
  },
  AvgDialog_142893_Content_58 = {
    Text = "A essa altura, ninguém conseguia distinguir aquele som profundo e insondável da voz que um dia havia sido a de Pontos."
  },
  AvgDialog_142893_Content_59 = {
    Text = "Tornaram-se um, indistinguíveis, como Eles desejavam."
  },
  AvgDialog_142893_Content_6 = {
    Text = "<Shake:<Red:Não é assim, a história de aventura do herói não deveria ser assim.>>"
  },
  AvgDialog_142893_Content_60 = {
    Text = "Enquanto o apito estridente ecoava ao longo da costa, cada um dos cultistas desmoronou em cinzas brancas."
  },
  AvgDialog_142893_Content_61 = {Text = "..."},
  AvgDialog_142893_Content_62 = {
    Text = "Ahhh! ...O que aconteceu depois? Tio Pontos, e a mãe do vovô... eles..."
  },
  AvgDialog_142893_Content_63 = {
    Text = "Vera havia prendido a respiração durante todo o tempo, e finalmente não conseguiu se conter e exclamou, os olhos quase transbordando de lágrimas."
  },
  AvgDialog_142893_Content_64 = {
    Text = "O que aconteceu depois disso, por mais que eu tente, simplesmente não consigo lembrar. Tudo o que recordo é..."
  },
  AvgDialog_142893_Content_65 = {Text = "..."},
  AvgDialog_142893_Content_66 = {
    Text = "*Soluço*... Jago... Jago! Graças a Deus, você finalmente acordou."
  },
  AvgDialog_142893_Content_67 = {
    Text = "Papai, tia Leisa, todos, nossa cidade, tudo... Buaaaaaaa!!"
  },
  AvgDialog_142893_Content_68 = {
    Text = "Através do relato entre soluços de Orney, sua amiga de infância, você soube que a cidade inteira havia sido obliterada em uma explosão massiva."
  },
  AvgDialog_142893_Content_69 = {
    Text = "Apenas um punhado de pessoas sobreviveu nos escombros e foi acolhido por parentes ou amigos em cidades vizinhas. Você esteve inconsciente por quatro dias inteiros."
  },
  AvgDialog_142893_Content_7 = {
    Text = "Jago, fecha os olhos e segue-me!"
  },
  AvgDialog_142893_Content_70 = {
    Text = "Não, não foi uma explosão. Eu me lembro claramente... Argh! Minha cabeça dói tanto."
  },
  AvgDialog_142893_Content_71 = {
    Text = "O ruído branco penetrante em sua mente fez você voltar a adormecer. Quando acordou novamente, encontrou-se embalado de forma nebulosa nos braços de alguém."
  },
  AvgDialog_142893_Content_72 = {
    Text = "Mãe... Mãe?!"
  },
  AvgDialog_142893_Content_73 = {
    Text = "Não se mexa muito. Seus ferimentos ainda não cicatrizaram."
  },
  AvgDialog_142893_Content_74 = {
    Text = "Você viu com seus próprios olhos que Leisha—cujo ventre havia sido rasgado pelos fanáticos—estava sentada ao lado da cama completamente ilesa. A alegria avassaladora fez seus olhos se arregalarem enquanto lágrimas escorriam pelo seu rosto."
  },
  AvgDialog_142893_Content_75 = {
    Text = "Mãe! Foi tudo um sonho? Eu sabia que você estava bem, você ainda está viva."
  },
  AvgDialog_142893_Content_76 = {
    Text = "Shh, me escute, Jago. A mamãe precisa te deixar e ir para um lugar muito distante."
  },
  AvgDialog_142893_Content_77 = {
    Text = "A família de Orney vai cuidar bem de você. Amanhã de manhã eles encontrarão dinheiro suficiente na mesa. Você precisa viver bem."
  },
  AvgDialog_142893_Content_78 = {
    Text = "Espere, me deixar? Mãe, por quê? E o tio Pontos? Onde ele está?"
  },
  AvgDialog_142893_Content_79 = {
    Text = "Leisha de repente ficou em silêncio. Após um momento, ela apertou sua mão com força, pressionou a bússola de cobre que você havia deixado cair de volta em sua palma, e se inclinou para beijar sua testa."
  },
  AvgDialog_142893_Content_8 = {
    Text = "Roar! Roar!"
  },
  AvgDialog_142893_Content_80 = {
    Text = "Jago, guarda isto. Jura-me que vais viver em segurança, nalgum lugar."
  },
  AvgDialog_142893_Content_81 = {
    Text = "Querias desesperadamente abanar a cabeça, mas Leisha não te deu oportunidade."
  },
  AvgDialog_142893_Content_82 = {
    Text = "Lembra-te, nunca venhas à minha procura nem à do teu tio. Nunca."
  },
  AvgDialog_142893_Content_83 = {Text = "Mãe!..."},
  AvgDialog_142893_Content_84 = {
    Text = "Você se levantou de um salto."
  },
  AvgDialog_142893_Content_85 = {
    Text = "Uma brisa suave agitou as folhas. A noite havia caído sem que você percebesse."
  },
  AvgDialog_142893_Content_86 = {
    Text = "Foi um sonho? Sua mãe Leisha não estava em lugar algum. Orney, cochilando à sua cabeceira vigiando você, pareceu sobressaltado."
  },
  AvgDialog_142893_Content_87 = {
    Text = "Jago?! O que se passa?"
  },
  AvgDialog_142893_Content_88 = {
    Text = "Ficaste a olhar fixamente pela janela, com o olhar vazio. A lua ainda pairava distante no céu."
  },
  AvgDialog_142893_Content_89 = {
    Text = "Para além disso, não havia nada."
  },
  AvgDialog_142893_Content_9 = {
    Text = "Pontos te segura com força e corre para o interior, longe da costa, seu corpo servindo de escudo. Você olha aterrorizado para as chamas por toda parte e as pessoas se debatendo no caos."
  },
  AvgDialog_145231_Content_1 = {Text = "Bang—"},
  AvgDialog_145231_Content_10 = {
    Text = "Hoje, não consegui me concentrar na minha lâmina nem no meu inimigo."
  },
  AvgDialog_145231_Content_11 = {
    Text = "Algo mais ficava me distraindo."
  },
  AvgDialog_145231_Content_12 = {
    Text = "Algo mais? Como o quê?"
  },
  AvgDialog_145231_Content_13 = {Text = "Você."},
  AvgDialog_145231_Content_14 = {
    Text = "¿¿¿??? Você quer dizer..."
  },
  AvgDialog_145231_Content_15 = {
    Text = "Sim. Aquela louca da Thais, e seu rio louco."
  },
  AvgDialog_145231_Content_16 = {
    Text = "Não tem problema perder uma luta de vez em quando. Apenas descanse aqui por ora, vou buscar um remédio para você..."
  },
  AvgDialog_145231_Content_17 = {Text = "..."},
  AvgDialog_145231_Content_18 = {
    Text = "Você tenta escapar do quarto, mas Lotan não te dá essa chance."
  },
  AvgDialog_145231_Content_19 = {
    Text = "Dois estalos secos ressoam perto dos seus ouvidos. As lâminas de osso de Lotan perfuram a cama, seus cabos de osso prendendo suas mãos no colchão. Você não consegue se mover."
  },
  AvgDialog_145231_Content_2 = {
    Text = "A porta se abre com estrondo, como um tambor de guerra. Cheirando a sangue, alguém entra em disparada e cai na sua cama, ofegante."
  },
  AvgDialog_145231_Content_20 = {
    Text = "Não vim aqui para me curar. Vim para resolver um problema. E você... é o problema."
  },
  AvgDialog_145231_Content_21 = {
    Text = "Ei! Lotan... o que... o que você está fazendo..."
  },
  AvgDialog_145231_Content_22 = {
    Text = "Odeio não conseguir me concentrar na luta. Isso me irrita."
  },
  AvgDialog_145231_Content_23 = {
    Text = "E-Eu tenho uma ideia! Você poderia ir procurar Thais... mmph..."
  },
  AvgDialog_145231_Content_24 = {
    Text = "Uma mão manchada de sangue aperta sua mandíbula, abafando sua voz em gemidos incoerentes."
  },
  AvgDialog_145231_Content_25 = {
    Text = "Minha mente nunca guardou nada além de batalha. Mas ter uma exceção... não é tão ruim."
  },
  AvgDialog_145231_Content_26 = {
    Text = "Gosto de me concentrar em uma coisa de cada vez. Seja uma luta... ou outra coisa."
  },
  AvgDialog_145231_Content_27 = {
    Text = "Lotan olha para você de cima, como se estivesse imobilizando uma rival que lhe traz o prazer supremo, o espírito combativo em seus olhos se transformando em fome nua e crua."
  },
  AvgDialog_145231_Content_28 = {
    Text = "Derramei todo esse sangue por sua causa. Você vai ter que pagar por isso, não vai?"
  },
  AvgDialog_145231_Content_29 = {
    Text = "As garras de ferro de suas manoplas deslizam pela sua mandíbula, passando pelo seu pescoço, seu peito e sua cintura... Você se debate freneticamente, soltando ruídos sem sentido, mas as lâminas o prendem com firmeza, imóveis como pedra."
  },
  AvgDialog_145231_Content_3 = {
    Text = "Ah! Quem—"
  },
  AvgDialog_145231_Content_30 = {
    Text = "Lotan se inclina, admirando seu rosto corado de vermelho pela luta."
  },
  AvgDialog_145231_Content_31 = {
    Text = "Ela sorri, deixando seu sangue pingar dos lábios no seu rosto."
  },
  AvgDialog_145231_Content_32 = {
    Text = "Se debata à vontade. Vamos ver se você consegue se libertar... meu \"oponente\"."
  },
  AvgDialog_145231_Content_4 = {
    Text = "...Lotan? Você está ferida?!"
  },
  AvgDialog_145231_Content_5 = {
    Text = "Você a encara incrédulo, contemplando seu estado lamentável."
  },
  AvgDialog_145231_Content_6 = {
    Text = "Apenas arranhões. Nada sério."
  },
  AvgDialog_145231_Content_7 = {
    Text = "O que aconteceu... Quem poderia ter te machucado assim?"
  },
  AvgDialog_145231_Content_8 = {
    Text = "Um Verme do Mar Astral. Deveria ter sido fácil de matar. Mas hoje..."
  },
  AvgDialog_145231_Content_9 = {
    Text = "Ela franze o cenho, com irritação faiscando em seus olhos."
  },
  AvgDialog_14530_Content_10 = {
    Text = "Os lábios se separaram, um leve gosto salgado se espalhou.\nIsto não é chuva."
  },
  AvgDialog_14530_Content_11 = {
    Text = "<Gray:...Lágrimas?>"
  },
  AvgDialog_14530_Content_12 = {
    Text = "Como se tivesse sido lavado pela chuva, a vista gradualmente se torna mais clara."
  },
  AvgDialog_14530_Content_14 = {
    Text = "Ra... Mona..."
  },
  AvgDialog_14530_Content_15 = {
    Text = "Seu telefonema termina de repente."
  },
  AvgDialog_14530_Content_16 = {
    Text = "Estresse avassalador vem de todas as direções, e marés negras te engolfam."
  },
  AvgDialog_14530_Content_17 = {Text = "..."},
  AvgDialog_14530_Content_18 = {
    Text = "O relógio faz tique-taque, e o som do canto dos pássaros filtra pela janela entreaberta."
  },
  AvgDialog_14530_Content_19 = {
    Text = "A sufocação persistente faz com que você instinctivamente bata no peito. Sentando-se lentamente, leva um tempo até que você realmente se sinta acordado."
  },
  AvgDialog_14530_Content_2 = {
    Text = "Lágrimas da Chuva"
  },
  AvgDialog_14530_Content_20 = {
    Text = "<Gray:Eu tive tantos sonhos estranhos, mas esta é a primeira vez que sonho com minha própria morte.>"
  },
  AvgDialog_14530_Content_21 = {
    Text = "Sente-se estranho."
  },
  AvgDialog_14530_Content_22 = {
    Text = "Bastante interessante."
  },
  AvgDialog_14530_Content_23 = {
    Text = "Ring Ring—"
  },
  AvgDialog_14530_Content_24 = {
    Text = "Você desliga o despertador, se levanta e se espreguiça."
  },
  AvgDialog_14530_Content_25 = {
    Text = "Tudo bem, tanto faz. Lembro que preciso ir hoje—"
  },
  AvgDialog_14530_Content_26 = {
    Text = "Treinamento especial amanhã às 8 da manhã na Sala de Despertar. Não se atrase"
  },
  AvgDialog_14530_Content_27 = {
    Text = "Sala de Despertar? É para treinamento relacionado ao despertar?"
  },
  AvgDialog_14530_Content_28 = {
    Text = "Testando a estabilidade do <Yellow:Domínio Artificial>."
  },
  AvgDialog_14530_Content_29 = {
    Text = "O que é isso?"
  },
  AvgDialog_14530_Content_3 = {Text = "Caindo."},
  AvgDialog_14530_Content_30 = {
    Text = "Um pequeno projeto em que tenho trabalhado, mais como um hobby—usando a amplificação do dispositivo de Despertar para aumentar a consciência e o espírito durante o sono"
  },
  AvgDialog_14530_Content_31 = {
    Text = "Em teoria, um espírito suficientemente grande pode formar um domínio, e um domínio estabilizado pode existir independentemente tanto da dimensão da realidade quanto da dimensão espiritual."
  },
  AvgDialog_14530_Content_32 = {
    Text = "Este reino é bastante semelhante ao <Yellow:Domínio>, então eu o chamo de Domínio Artificial."
  },
  AvgDialog_14530_Content_33 = {
    Text = "Ao contrário dos domínios que ocorrem naturalmente e que invadem a realidade a partir da dimensão espiritual, os domínios artificiais são não agressivos, mais estáveis e controláveis, e podem <Yellow:recriar um momento de um tempo que não existe no presente>."
  },
  AvgDialog_14530_Content_34 = {
    Text = "\"O presente não existe\"—Você está dizendo que pode mostrar as memórias de alguém?"
  },
  AvgDialog_14530_Content_35 = {
    Text = "Pode <Yellow:apresentar uma memória com base na compreensão do Mestre Espírito>, e também permite que outros entrem nesta memória."
  },
  AvgDialog_14530_Content_36 = {
    Text = "Como entrar no Domínio...?"
  },
  AvgDialog_14530_Content_37 = {
    Text = "Nada mal. Sim, depois que um Domínio artificial se forma, outros indivíduos podem entrar fisicamente nele e interagir com a consciência da entidade espiritual—o proprietário do Domínio."
  },
  AvgDialog_14530_Content_38 = {
    Text = "Neste momento, se o espírito reconhece o visitante e qual atitude ele mantém... Ha, só de pensar nisso é interessante."
  },
  AvgDialog_14530_Content_39 = {
    Text = "Se o Domínio Artificial funcionar, será a melhor maneira para Investigadores, Guardiães e seus respectivos Despertadores construírem relações e aprofundarem a compreensão."
  },
  AvgDialog_14530_Content_4 = {
    Text = "Você está caindo."
  },
  AvgDialog_14530_Content_40 = {
    Text = "Pensando nos olhos ansiosos da Boneca, você sentiu um frio percorrer sua nuca."
  },
  AvgDialog_14530_Content_41 = {
    Text = "Eles chamam isso de treinamento especial, mas somos apenas cobaias...\nEspero que nada dê errado hoje."
  },
  AvgDialog_14530_Content_42 = {
    Text = "Você reúne seu espírito e empurra a porta no túnel subterrâneo."
  },
  AvgDialog_14530_Content_43 = {
    Text = "Antes que você possa reagir, uma luz ofuscante o engole por completo."
  },
  AvgDialog_14530_Content_5 = {
    Text = "A sensação de queda puxa você, lentamente desenhando sua consciência para fora do sonho negro como tinta."
  },
  AvgDialog_14530_Content_6 = {
    Text = "Uma luz borrada aparece diante dos seus olhos. Depois de um breve momento de confusão, você percebe que parece ter aberto os olhos."
  },
  AvgDialog_14530_Content_7 = {
    Text = "<Gray:Como... não consigo ver claramente...>"
  },
  AvgDialog_14530_Content_8 = {
    Text = "Uma gota, duas gotas... Um líquido fresco cai na sua testa, escorrendo pela sua bochecha."
  },
  AvgDialog_14530_Content_9 = {Text = "Chuva...?"},
  AvgDialog_145510_Content_10 = {
    Text = "Aos pés das montanhas nevadas, um mercado caótico brotou do solo congelado. Barracas de madeira, tendas e bancas improvisadas de couro de iaque espremem-se densamente nos dois lados de uma trilha lamacenta."
  },
  AvgDialog_145510_Content_11 = {
    Text = "O Continente do Norte Final é frio demais, estou com um pouco de saudade do chá quente da Senhora Sylvia..."
  },
  AvgDialog_145510_Content_12 = {
    Text = "Embora seja cedo demais para dizer isso, quando voltarmos para Misaq, vou pedir à Senhora Sylvia que forneça chá quente para você em um Ciclo de 24 horas."
  },
  AvgDialog_145510_Content_13 = {
    Text = "Por ora, vamos nos concentrar na missão em mãos."
  },
  AvgDialog_145510_Content_14 = {
    Text = "Você tira o folheto promocional amassado entre a bagagem e o gira sob o sol para comparar."
  },
  AvgDialog_145510_Content_15 = {
    Text = "A junção das montanhas parte da borda do folheto e se encaixa perfeitamente com o contorno das montanhas sob o céu sombrio."
  },
  AvgDialog_145510_Content_16 = {
    Text = "É aqui mesmo, Apenas não sei como encontrar aquele misterioso líder cujos títulos se empilham mais alto que o próprio Everest..."
  },
  AvgDialog_145510_Content_17 = {
    Text = "<Shake:Atenção, pessoal!>"
  },
  AvgDialog_145510_Content_18 = {
    Text = "Seguindo a direção da voz, uma garota de branco estava sozinha diante de uma tenda no alto de uma pequena colina, olhando para a multidão esparsa lá embaixo."
  },
  AvgDialog_145510_Content_19 = {
    Text = "Eu sou a Executor do deus supremo, a grande Fada do culto Caraboo, encarnação da deusa das montanhas nevadas Umapati que desceu ao mundo dos homens."
  },
  AvgDialog_145510_Content_2 = {
    Text = "Os Presos pela Neve"
  },
  AvgDialog_145510_Content_20 = {
    Text = "(Como é que está um pouco diferente do que está escrito no folheto...)"
  },
  AvgDialog_145510_Content_21 = {
    Text = "Ei, se você é a deusa das montanhas nevadas, então mostre um feitiço para todo mundo!"
  },
  AvgDialog_145510_Content_22 = {
    Text = "A Provocação do homem arrancou algumas risadas dispersas."
  },
  AvgDialog_145510_Content_23 = {
    Text = "Não, eu ainda não consigo fazer isso agora."
  },
  AvgDialog_145510_Content_24 = {
    Text = "A garota tirou casualmente uma maçã vermelha e brilhante do bolso, dando uma mordida."
  },
  AvgDialog_145510_Content_25 = {
    Text = "Porque perdi sete artefatos mágicos, sete tesouros que amo profundamente."
  },
  AvgDialog_145510_Content_26 = {
    Text = "São eles a Maçã Dourada de Éris, o Espelho de Yata, a Pena de Ma'at, a Chave de Salomão, o Olho de Balor..."
  },
  AvgDialog_145510_Content_27 = {
    Text = "Esses artefatos mágicos seus vêm de civilizações bem variadas e diversas!"
  },
  AvgDialog_145510_Content_28 = {
    Text = "Mais uma gargalhada geral, mas a garota não se importou nem um pouco."
  },
  AvgDialog_145510_Content_29 = {
    Text = "E também o Fio de Moira, e a Coroa de Ariadne."
  },
  AvgDialog_145510_Content_3 = {
    Text = [[
A maior mentira deste mundo,
sai da boca de quem jamais mente.]]
  },
  AvgDialog_145510_Content_30 = {
    Text = "O Fio de Moira… o tear das Três Parcas…"
  },
  AvgDialog_145510_Content_31 = {
    Text = "Será que isso é o que Arachne chamou de \"o destino que devemos receber\"?"
  },
  AvgDialog_145510_Content_32 = {
    Text = "Você retira do compartimento secreto do bolso aquele pequeno rolo de fio, e o brilhante Fio faísca entre seus dedos com cores fluidas quase impossíveis de captar a olho nu."
  },
  AvgDialog_145510_Content_33 = {
    Text = "Espere um pouco mais, aja com cautela."
  },
  AvgDialog_145510_Content_34 = {
    Text = "Embora o destino nos tenha guiado até aqui, ainda não nos revelou o papel que o dono do manual desempenha nessa história."
  },
  AvgDialog_145510_Content_35 = {
    Text = "*Tosse, tosse!*"
  },
  AvgDialog_145510_Content_36 = {
    Text = "Se entenderam tudo, deixem aqui as suas ofertas de Manutenção!"
  },
  AvgDialog_145510_Content_37 = {
    Text = "Nem mais nem menos, Desde Que cinquenta Cupons de ouro rosa! Assim a deusa da montanha nevada Umapati poderá sentir a sua sinceridade!"
  },
  AvgDialog_145510_Content_38 = {
    Text = "Como deusa da montanha nevada, após reunir os sete grandes artefatos e renascer sob a lua nova, certamente retribuirei suas preces mil e cem vezes!"
  },
  AvgDialog_145510_Content_39 = {
    Text = "Depois de tanto papo confuso, afinal veio pedir doações!"
  },
  AvgDialog_145510_Content_4 = {
    Text = "-Altitude 4000 m-"
  },
  AvgDialog_145510_Content_40 = {
    Text = "Desde que a deusa da montanha nevada se manifestou, os grupos que vieram escalar a montanha foram aos milhares, e nenhum deles veio de mãos vazias."
  },
  AvgDialog_145510_Content_41 = {
    Text = "Um sujeito como você, que só pensa em ganhar sem trabalhar, é melhor sumir logo e aprender a realizar seus desejos com as próprias mãos laboriosas!"
  },
  AvgDialog_145510_Content_42 = {
    Text = "Os curiosos se dispersaram em debandada."
  },
  AvgDialog_145510_Content_43 = {
    Text = "Você aproveitou a oportunidade para ir contra a multidão e se aproximar da jovem abatida, perguntando-lhe algo."
  },
  AvgDialog_145510_Content_44 = {
    Text = "Com licença… Gostaria de perguntar, foi você quem enviou este folheto?"
  },
  AvgDialog_145510_Content_45 = {
    Text = "Você tira aquele folheto extravagante e bate com o dedo nas palavras \"Grande Líder, Eleito da Divindade, Amigo próximo do Rei dos Deuses\"."
  },
  AvgDialog_145510_Content_46 = {
    Text = "Os olhos da jovem acenderam-se instantaneamente."
  },
  AvgDialog_145510_Content_47 = {
    Text = "<Shake:Ohhh! Você realmente pegou meu folheto de recrutamento!>"
  },
  AvgDialog_145510_Content_48 = {
    Text = "Então, onde estão seus doze apóstolos e os demais fiéis?"
  },
  AvgDialog_145510_Content_49 = {
    Text = "Essa história é longa de contar. Minha grandiosa seita foi traída por vilões, e entre os doze apóstolos havia um que nutria intenções malignas, almejando monopolizar a glória suprema."
  },
  AvgDialog_145510_Content_5 = {Text = "Chegamos"},
  AvgDialog_145510_Content_50 = {
    Text = "Os demais fiéis foram manipulados e divididos até se despedaçarem. Restei apenas eu, a Líder, sozinha, embarcando numa longa e árdua jornada para reviver a seita."
  },
  AvgDialog_145510_Content_51 = {
    Text = "Desde Que cada um patrocine agora mil Cupons de ouro rosa, poderá ascender ao topo dos novos Doze Apóstolos, tornando-se meu discípulo número um…"
  },
  AvgDialog_145510_Content_52 = {
    Text = "Mas há pouco, quando você estava se apresentando na rua, disse que era a deusa da montanha de Neve, Umapati."
  },
  AvgDialog_145510_Content_53 = {
    Text = "Isso se chama: quando se está fora de casa, a Identidade é a que você mesmo se dá, não é?"
  },
  AvgDialog_145510_Content_54 = {
    Text = "Tsc, fui Descoberta."
  },
  AvgDialog_145510_Content_55 = {
    Text = "A jovem deu um salto e, em dois ou três movimentos, desapareceu atrás de uma tenda."
  },
  AvgDialog_145510_Content_56 = {
    Text = "Você estava prestes a correr atrás da jovem quando, de repente, alguém deu um tapinha nas suas costas."
  },
  AvgDialog_145510_Content_57 = {
    Text = "Caros visitantes, vieram para escalar a montanha?"
  },
  AvgDialog_145510_Content_58 = {Text = "Hã, nós?"},
  AvgDialog_145510_Content_59 = {
    Text = "Sim! Só de olhar, dá para ver que vocês dois têm uma presença especial. Não são pessoas locais, são?"
  },
  AvgDialog_145510_Content_6 = {
    Text = "Este é o último posto de abastecimento no caminho para o Monte Everest."
  },
  AvgDialog_145510_Content_60 = {
    Text = "Ultimamente, quem vem até esta terra desolada não está atrás da deusa no topo da montanha, que dizem realizar todos os desejos?"
  },
  AvgDialog_145510_Content_61 = {
    Text = "Vocês dois não trouxeram muitos equipamentos, parece que pretendem aproveitar os suprimentos de outros. Que coincidência, não é?"
  },
  AvgDialog_145510_Content_62 = {
    Text = "<Yellow:Meu nome é Naraka. Sou um guia Sherpa local.>"
  },
  AvgDialog_145510_Content_63 = {
    Text = "A expedição em que estamos é patrocinada pela Fundação Green, os suprimentos já estão preparados, só falta o \"predestinado\" para juntar-se a nós no cume."
  },
  AvgDialog_145510_Content_64 = {
    Text = "Uma pessoa predestinada?"
  },
  AvgDialog_145510_Content_65 = {
    Text = "Sim, vivo aos pés desta montanha nevada há muitos anos. Quem tem capacidade de chegar ao topo—"
  },
  AvgDialog_145510_Content_66 = {
    Text = "Ele apontou para os próprios olhos."
  },
  AvgDialog_145510_Content_67 = {
    Text = "Estes olhos conseguem perceber isso de imediato."
  },
  AvgDialog_145510_Content_68 = {
    Text = "Oh? Por que não nos conta?"
  },
  AvgDialog_145510_Content_69 = {
    Text = "Primeiro, claro, a idade adequada, um corpo robusto e uma Força mental estável."
  },
  AvgDialog_145510_Content_7 = {
    Text = "Mais acima, os veículos já não conseguem passar."
  },
  AvgDialog_145510_Content_70 = {
    Text = "Além disso, mais importante ainda é a perseverança e determinação para chegar ao topo — a determinação de não dar o último suspiro Desde Que não tenha chegado ao cume."
  },
  AvgDialog_145510_Content_71 = {
    Text = "Dar o último suspiro no topo — parece que você não pretende nos deixar descer vivos, não é?"
  },
  AvgDialog_145510_Content_72 = {
    Text = "Ei, não pode dizer isso assim. Ao chegar ao topo e encontrar a Deusa da Montanha Nevada, qualquer desejo pode ser realizado. Nesse momento, uma coisa simples como descer a montanha, ainda precisaria se preocupar com isso?"
  },
  AvgDialog_145510_Content_73 = {
    Text = "Venham, me acompanhem até o acampamento de montanhismo para dar uma olhada. Garanto que ficarão satisfeitos."
  },
  AvgDialog_145510_Content_74 = {
    Text = "Você olha para William, pedindo silenciosamente sua opinião."
  },
  AvgDialog_145510_Content_75 = {
    Text = "Vamos. Aquela garota de antes, não sei para onde foi."
  },
  AvgDialog_145510_Content_76 = {
    Text = "Se realmente formos escalar a montanha, um guia local e suprimentos completos são indispensáveis."
  },
  AvgDialog_145510_Content_77 = {
    Text = "Vamos, dar uma olhada no acampamento."
  },
  AvgDialog_145510_Content_79 = {
    Text = "Que voz linda…"
  },
  AvgDialog_145510_Content_8 = {
    Text = "Você empurra a porta do carro, e o ar impregnado do aroma tostado do chá de manteiga, do cheiro forte dos animais e do frio rarefeito e cortante característico do planalto invade suas narinas sem pedir licença."
  },
  AvgDialog_145510_Content_80 = {
    Text = "Parece familiar."
  },
  AvgDialog_145510_Content_81 = {
    Text = "Como se despencasse de uma galáxia distante, ou como se emergisse suavemente das profundezas do Mar Profundo sem fim."
  },
  AvgDialog_145510_Content_83 = {
    Text = "O canto vinha da direção do acampamento, fio a fio, tornando-se gradualmente mais nítido, como névoa que se dissipa e revela o brilho puro da lua cheia."
  },
  AvgDialog_145510_Content_85 = {
    Text = "Em um espaço aberto ao lado do acampamento, uma jovem de semblante melancólico cantava em voz alta."
  },
  AvgDialog_145510_Content_86 = {
    Text = "Todos que passavam por ali instintivamente desaceleravam o passo e prendiam a respiração — com medo de perturbar aquela voz que fluía como luz de lua."
  },
  AvgDialog_145510_Content_88 = {
    Text = "Somente ao fim da canção Ela emergiu do mundo em que estava imersa, e então percebeu a presença de vocês."
  },
  AvgDialog_145510_Content_89 = {
    Text = "Há novos membros na equipe?"
  },
  AvgDialog_145510_Content_9 = {
    Text = "Um céu cinzento como chumbo pesa sobre o fim do mundo. Os picos nevados erguem-se como uma fileira de divindades silenciosas, imponentes na fronteira entre o crepúsculo e as nuvens."
  },
  AvgDialog_145511_Content_1 = {
    Text = "Algo não está certo."
  },
  AvgDialog_145511_Content_10 = {
    Text = "Não, não era apenas a capa — atrás dele, algo mais se ergueu."
  },
  AvgDialog_145511_Content_11 = {
    Text = "Era um par de asas."
  },
  AvgDialog_145511_Content_12 = {
    Text = "Um par de asas negras — um negro denso, profundo, que transmitia um presságio sombrio a todos que o contemplavam."
  },
  AvgDialog_145511_Content_13 = {
    Text = "<BigShake:Com este corpo imortal, resistirei a toda Catástrofe!>"
  },
  AvgDialog_145511_Content_14 = {
    Text = "Castor abriu as asas, e a neve acumulada explodiu atrás dele em um arco branco e brilhante, quase vertical."
  },
  AvgDialog_145511_Content_15 = {
    Text = "Ele se impulsiona pela encosta nevada, cobrindo uma distância que jamais conseguiria cruzar de outra forma—"
  },
  AvgDialog_145511_Content_16 = {
    Text = "E então se lançou entre o Wendigo e Evelyn."
  },
  AvgDialog_145511_Content_17 = {
    Text = "Suas asas se abrem amplamente, formando uma enorme barreira negra como breu atrás dele."
  },
  AvgDialog_145511_Content_18 = {
    Text = "A boca do Wendigo, prestes a se fechar, mordeu sua asa direita, arrancando um punhado de Penas pela raiz."
  },
  AvgDialog_145511_Content_19 = {
    Text = "<Shake:Ugh!!>"
  },
  AvgDialog_145511_Content_2 = {
    Text = "No canto do campo de visão, no canto da matilha, o Wendigo mais alto e mais magro não havia atacado desde o início da batalha."
  },
  AvgDialog_145511_Content_20 = {
    Text = "Castor solta um gemido abafado, mas não recua."
  },
  AvgDialog_145511_Content_21 = {
    Text = "Não desperdice a oportunidade que Castor criou — agora!"
  },
  AvgDialog_145511_Content_3 = {
    Text = "Ele esperava, observando o elo mais fraco da equipe de alpinismo."
  },
  AvgDialog_145511_Content_4 = {
    Text = "Ele contornou vocês três e se lançou ferozmente em direção a Evelyn."
  },
  AvgDialog_145511_Content_5 = {
    Text = "Evelyn——!"
  },
  AvgDialog_145511_Content_6 = {
    Text = "Caraboo estava longe demais; ao gritar, já sabia que não chegaria a tempo."
  },
  AvgDialog_145511_Content_7 = {
    Text = "— Mas alguém chegou a tempo."
  },
  AvgDialog_145511_Content_8 = {
    Text = "Castor correu velozmente e estendeu a mão para desatar as amarras da capa."
  },
  AvgDialog_145511_Content_9 = {
    Text = "A capa esvoaçou ao vento atrás dele——"
  },
  AvgDialog_145512_Content_1 = {
    Text = "Acabou, derrotado."
  },
  AvgDialog_145512_Content_10 = {
    Text = "Seu mestre disse algo assim: meu querido, você se esforçou tanto, isso é uma recompensa por tudo que você fez até agora."
  },
  AvgDialog_145512_Content_11 = {
    Text = "Que Apenas precisava escalar o pico nevado pessoalmente, afastar os oponentes e recuperar sua coroa?"
  },
  AvgDialog_145512_Content_12 = {
    Text = "Que pena! <BigShake:VOCÊ — FOI — EN — GA — NA — DO!!>"
  },
  AvgDialog_145512_Content_13 = {
    Text = "Uma peça no tabuleiro sempre será Apenas uma peça, e quando necessário, se tornará uma peça descartável."
  },
  AvgDialog_145512_Content_14 = {
    Text = "Quando o valor que você pode oferecer for completamente esgotado, quando você começar a se ressentir… chegará a hora de você entregar sua cabeça."
  },
  AvgDialog_145512_Content_15 = {
    Text = "Como uma das sete Ofertas no altar, você tem alguma última palavra a dizer?"
  },
  AvgDialog_145512_Content_16 = {
    Text = "Não devia… não devia confiar em ninguém…"
  },
  AvgDialog_145512_Content_17 = {
    Text = "Desde o início, confiar na graça daquela senhora… depois… ansiar pela vingança dos meus semelhantes…"
  },
  AvgDialog_145512_Content_18 = {
    Text = "E agora, ser movida pela promessa de alguém…"
  },
  AvgDialog_145512_Content_19 = {
    Text = "Tudo bem, tudo bem, o tempo que dei para você fazer seu discurso final foi apenas por cortesia, ninguém se importa de verdade com sua vida miserável e fracassada."
  },
  AvgDialog_145512_Content_2 = {
    Text = "Caraboo passa por cima de Helot ajoelhado no chão e delicadamente apanha o globo ocular do círculo mágico."
  },
  AvgDialog_145512_Content_20 = {
    Text = "O que você não consegue ganhar por conta própria, vá roubar, enganar ou tomar à força — de que adianta ficar esperando que os outros lhe deem de presente."
  },
  AvgDialog_145512_Content_21 = {
    Text = "Não há tempo suficiente agora, o restante da reflexão, deixe para continuar na próxima vida."
  },
  AvgDialog_145512_Content_22 = {
    Text = "Caraboo ergueu a mão e lançou levemente, e aquele globo ocular mergulhou no corpo de Helot."
  },
  AvgDialog_145512_Content_23 = {
    Text = "Em seguida, ecoou um som de rangidos e crepitações — o som da Ingestão."
  },
  AvgDialog_145512_Content_24 = {
    Text = "Come, come."
  },
  AvgDialog_145512_Content_25 = {
    Text = "O corpo de Helot rapidamente desmoronou, deixando para trás uma poça de Sangue."
  },
  AvgDialog_145512_Content_26 = {
    Text = "Exatamente, é assim que é — eles vão te devorar, até não restar nem os ossos…"
  },
  AvgDialog_145512_Content_27 = {
    Text = "Você vislumbrou, no O Semblante de Caraboo, uma espécie de prazer cruel."
  },
  AvgDialog_145512_Content_28 = {
    Text = "Veja, suas consequências miseráveis têm Fonte na sua estupidez, têm Fonte na sua credulidade diante de Uma Mentira."
  },
  AvgDialog_145512_Content_29 = {Text = "Caraboo…"},
  AvgDialog_145512_Content_3 = {
    Text = "Seu desejo também se tornará adubo para nutrir a montanha de Neve."
  },
  AvgDialog_145512_Content_30 = {
    Text = "Hm? O que está acontecendo?"
  },
  AvgDialog_145512_Content_31 = {
    Text = "Ela virou-se, contemplando a sua expressão."
  },
  AvgDialog_145512_Content_32 = {
    Text = "Ela exibiu seu jeito manhoso e dengoso de sempre, mas Você ainda conseguiu ler, no canto do Olho, um traço de arrogância que revelava seu ódio Oculto."
  },
  AvgDialog_145512_Content_33 = {
    Text = "Posso ver os seis artefatos sagrados?"
  },
  AvgDialog_145512_Content_34 = {Text = "Claro!"},
  AvgDialog_145512_Content_35 = {
    Text = "Caraboo deu um passo para o lado, cedendo a Você a posição de frente para o círculo mágico."
  },
  AvgDialog_145512_Content_36 = {
    Text = "O Fio de Moira — um presente de Arachne."
  },
  AvgDialog_145512_Content_37 = {
    Text = "O Espelho de Yata, encontrado à beira do lago de gelo onde Tinct vagava."
  },
  AvgDialog_145512_Content_38 = {
    Text = "A Pena de Ma'at, que caiu da Neve e do vento Depois que Castor partiu."
  },
  AvgDialog_145512_Content_39 = {
    Text = "O Olho de Balor, cristalizado na poça de Sangue de Helot."
  },
  AvgDialog_145512_Content_4 = {
    Text = "O globo ocular de repente se torna ameaçador, com a pupila vermelha se abrindo com um brilho de Sangue."
  },
  AvgDialog_145512_Content_40 = {
    Text = "a Maçã Dourada, Caraboo tirou de não se sabe qual trouxa."
  },
  AvgDialog_145512_Content_41 = {
    Text = "A Chave de Salomão é, na verdade, a Chave de Prata que você carrega consigo."
  },
  AvgDialog_145512_Content_42 = {
    Text = "E ainda, encontrada pela expedição anterior, a Coroa de Ariadne…"
  },
  AvgDialog_145512_Content_43 = {
    Text = "Você fica perplexo."
  },
  AvgDialog_145512_Content_44 = {
    Text = "Coroa de Ariadne… que Coroa de Ariadne é essa, isso não é a <Yellow:Coroa de Tulu>!"
  },
  AvgDialog_145512_Content_45 = {
    Text = "O que há de tão surpreendente? A Maçã Dourada também não é dourada, não é?"
  },
  AvgDialog_145512_Content_46 = {
    Text = "Mas, por que a Coroa de Tulu estaria aqui?"
  },
  AvgDialog_145512_Content_47 = {
    Text = "Porque é o artefato d'Ele, a oferenda d'Ele, o ingrediente favorito d'Ele."
  },
  AvgDialog_145512_Content_48 = {
    Text = "Com as últimas palavras de Caraboo, a Terra de repente Tremeu."
  },
  AvgDialog_145512_Content_49 = {
    Text = "O que aconteceu?"
  },
  AvgDialog_145512_Content_5 = {
    Text = "Não, como pode ser...!"
  },
  AvgDialog_145512_Content_50 = {
    Text = "Ele está rindo!"
  },
  AvgDialog_145512_Content_51 = {Text = "…Rindo?"},
  AvgDialog_145512_Content_52 = {
    Text = "O cume da montanha Tremeu repetidamente, Como Se uma jovem donzela, ao presenciar algo engraçado, gargalhasse até tremer de tanto rir."
  },
  AvgDialog_145512_Content_53 = {
    Text = "A Neve acumulada caiu sacudida."
  },
  AvgDialog_145512_Content_54 = {
    Text = "Aquele pico afiado não era uma montanha, mas sim uma enorme criatura vermiforme enroscada sobre o cume, semelhante a uma serpente colossal capaz de engolir os céus e devorar a Terra."
  },
  AvgDialog_145512_Content_55 = {
    Text = "Por causa da fraqueza humana de não conseguir encarar a realidade, eles escolheram acreditar em mentiras, confiando seus desejos a Divindades do Nada."
  },
  AvgDialog_145512_Content_56 = {
    Text = "Jamais pensaram — que as chamadas Divindades também mentem. Porque as Divindades também têm seus próprios desejos a realizar."
  },
  AvgDialog_145512_Content_57 = {
    Text = "O desejo das Divindades é — devorá-los."
  },
  AvgDialog_145512_Content_58 = {
    Text = "Coroa, Fio, Chave de Prata, fruto proibido, pena voadora, espelho luminoso, olho mágico. Os sete artefatos são as Ofertas que essas pessoas Gananciosas fizeram com suas Vidas."
  },
  AvgDialog_145512_Content_59 = {
    Text = "Tudo o que vocês são não passa de uma refeição farta para Ele."
  },
  AvgDialog_145512_Content_6 = {
    Text = "O Olho de Balor, o olho demoníaco do deus maligno. Capaz de destruir tudo o que observa, mas também é Sua única fraqueza."
  },
  AvgDialog_145512_Content_60 = {
    Text = "Agora, Ele obteve o que queria, é claro que Ele deveria estar sorrindo!"
  },
  AvgDialog_145512_Content_61 = {
    Text = "Chegamos até aqui, já é hora de nos dizer a verdade, não é?"
  },
  AvgDialog_145512_Content_62 = {
    Text = "Você não é de forma alguma como se apresentou, alguém que simplesmente se aproveitou desta viagem."
  },
  AvgDialog_145512_Content_63 = {
    Text = "Pelo contrário, toda a equipe de alpinismo chegou até aqui sob sua orientação."
  },
  AvgDialog_145512_Content_64 = {
    Text = "O encontro casual na caverna com Castor no início, a escolha de Tinct de ir contemplar o lago de gelo…"
  },
  AvgDialog_145512_Content_65 = {
    Text = "E também este Helot que nos seguiu o tempo todo — na verdade, você já havia previsto tudo."
  },
  AvgDialog_145512_Content_66 = {
    Text = "Quem você realmente é?"
  },
  AvgDialog_145512_Content_7 = {
    Text = "Seu mestre não lhe disse? Este globo ocular, Apenas embebido no seu Banquete de Sangue, merece ser chamado de \"Olho de Balor\"."
  },
  AvgDialog_145512_Content_8 = {
    Text = "Ele disse..."
  },
  AvgDialog_145512_Content_9 = {
    Text = "Shh, deixe-me adivinhar."
  },
  AvgDialog_145513_Content_1 = {
    Text = "Pacto dos Mentirosos"
  },
  AvgDialog_145513_Content_10 = {
    Text = "<Yellow:Foi você que queimou o meu pacote>? Vou arrancar essa máscara de pele humana sua —"
  },
  AvgDialog_145513_Content_11 = {
    Text = "Ela agarrou com força as bochechas de Naraka e puxou para os lados."
  },
  AvgDialog_145513_Content_12 = {
    Text = "<Shake:ESPERE!>"
  },
  AvgDialog_145513_Content_13 = {
    Text = "Rassssggg —"
  },
  AvgDialog_145513_Content_14 = {
    Text = "A casca conhecida como \"Naraka\" é rasgada ao meio, como uma boneca de borracha nas mãos de uma criança travessa."
  },
  AvgDialog_145513_Content_15 = {
    Text = "Borbulhando pela fenda, havia uma fumaça negra chamada \"Caos\"."
  },
  AvgDialog_145513_Content_16 = {
    Text = "A fumaça se agitou, se enrolou, se condensou, e então estendeu uma rosa com leveza e galhardia."
  },
  AvgDialog_145513_Content_17 = {
    Text = "Nos encontramos de novo, velho amigo."
  },
  AvgDialog_145513_Content_18 = {
    Text = "Antes de colocarmos o papo em dia, que tal um aquecimento para acalmar nossa pequena trapaceira furiosa?"
  },
  AvgDialog_145513_Content_2 = {
    Text = "No fim do Fio, a jovem emergiu das sombras."
  },
  AvgDialog_145513_Content_3 = {
    Text = "Ora, pequena trapaceira, acabou se envolvendo também?"
  },
  AvgDialog_145513_Content_4 = {
    Text = "As palavras de Naraka só aguçam o temperamento de uma garota que já estava de cabeça baixa em frustração."
  },
  AvgDialog_145513_Content_5 = {
    Text = "Você está bem à vontade."
  },
  AvgDialog_145513_Content_6 = {
    Text = "Caraboo ergueu a cabeça, seus olhos cheios de fúria fixos em Naraka."
  },
  AvgDialog_145513_Content_7 = {
    Text = "Pare de fingir. Um guia Sherpa engolido pelas entranhas da montanha ainda tem disposição para fazer piadas?"
  },
  AvgDialog_145513_Content_8 = {
    Text = "Desde o momento em que te vi pela primeira vez, eu soube — você também é um impostor."
  },
  AvgDialog_145513_Content_9 = {
    Text = "Caraboo se jogou sobre ela. Desta vez, não permitiu que Naraka escapasse."
  },
  AvgDialog_145514_Content_1 = {
    Text = "O último Wendigo se dissipou sob a sombra de Castor."
  },
  AvgDialog_145514_Content_10 = {
    Text = "Talvez os laços entre as pessoas Comecem justamente quando se revela um pequeno segredo, não é?"
  },
  AvgDialog_145514_Content_11 = {
    Text = "Sem que você percebesse quando, Caraboo se aproximou e disse com um sorriso, na sua frente, exatamente o que você estava pensando."
  },
  AvgDialog_145514_Content_12 = {
    Text = "Trocar segredos não é algo unilateral."
  },
  AvgDialog_145514_Content_13 = {
    Text = "Essa Tia Rosa que Você chamou tantas vezes — é alguém muito importante?"
  },
  AvgDialog_145514_Content_14 = {
    Text = "Claro que eu inventei. Você não acreditou de verdade, acreditou?"
  },
  AvgDialog_145514_Content_15 = {
    Text = "Hehe, enganar um tolo não tem graça, mas enganar Você não é nada fácil."
  },
  AvgDialog_145514_Content_16 = {
    Text = "Fazer o Wendigo acreditar que você foi enfeitiçado é muito mais difícil do que me enganar."
  },
  AvgDialog_145514_Content_17 = {
    Text = "Eles conseguem ouvir a voz do seu coração e depois a repetem através do vento."
  },
  AvgDialog_145514_Content_18 = {
    Text = "Mas quem poderia saber? Talvez a deusa da montanha nevada tenha histórias demais em seu coração, e cada uma pareça verdadeira?"
  },
  AvgDialog_145514_Content_19 = {
    Text = "Caraboo desviou do assunto com uma resposta espirituosa e leviana."
  },
  AvgDialog_145514_Content_2 = {
    Text = "Então o vento que roçava os ouvidos de repente ficou cristalino. O vento não carregava mais nenhum som."
  },
  AvgDialog_145514_Content_20 = {
    Text = "Já que Você não quer falar, nós certamente não vamos forçar."
  },
  AvgDialog_145514_Content_21 = {
    Text = "Mas a sinceridade é algo muito precioso — mesmo que Você seja um trapaceiro, é melhor não decepcionar as expectativas de todos."
  },
  AvgDialog_145514_Content_22 = {
    Text = "Este é meu conselho sincero, cabe a você decidir se vai ouvi-lo."
  },
  AvgDialog_145514_Content_23 = {
    Text = "William terminou de falar e foi para a frente do grupo."
  },
  AvgDialog_145514_Content_24 = {Text = "Hmph."},
  AvgDialog_145514_Content_25 = {
    Text = "Benfeitor, você não seria tão insensível quanto ele, seria?"
  },
  AvgDialog_145514_Content_26 = {
    Text = "Passei muito tempo trabalhando com William. Ele não é um homem que diz nada desnecessário."
  },
  AvgDialog_145514_Content_27 = {
    Text = "Na minha memória, cada conselho que ele deu foi eficaz."
  },
  AvgDialog_145514_Content_28 = {
    Text = "<Shake:Buááá, benfeitor, afinal você é tão cruel quanto ele...>"
  },
  AvgDialog_145514_Content_29 = {
    Text = "Caraboo fingiu estar triste e foi embora, enquanto você alcançou William, que estava conversando com Naraka."
  },
  AvgDialog_145514_Content_3 = {
    Text = "O silêncio significava segurança, mas essa segurança deixava um vazio melancólico."
  },
  AvgDialog_145514_Content_30 = {
    Text = "Ele sinalizou com os olhos para você se afastar alguns passos, até que as pessoas ao lado não pudessem ouvir os Sussurros de vocês."
  },
  AvgDialog_145514_Content_31 = {
    Text = "A batalha contra o Wendigo agora há pouco — você achou algo estranho?"
  },
  AvgDialog_145514_Content_32 = {Text = "Onde?"},
  AvgDialog_145514_Content_33 = {Text = "Naraka."},
  AvgDialog_145514_Content_34 = {
    Text = "Pense bem — desde quando aquelas vozes no vento começaram a soar, até o Wendigo aparecer, até o cerco de há pouco—"
  },
  AvgDialog_145514_Content_35 = {
    Text = "Naraka, houve algum momento, em que qualquer um dos Wendigos chegou perto de você?"
  },
  AvgDialog_145514_Content_36 = {
    Text = "Caraboo foi atacada por um Wendigo enquanto fingia ser a vítima, Evelyn foi derrubada pelo Wendigo mais alto, Castor teve uma Pena arrancada a dentadas…"
  },
  AvgDialog_145514_Content_37 = {
    Text = "Incluindo a vez anterior em que foi enfeitiçada pelo Wendigo, Naraka parece não ter sofrido nenhuma influência."
  },
  AvgDialog_145514_Content_38 = {
    Text = "Então você quer dizer..."
  },
  AvgDialog_145514_Content_39 = {
    Text = "Não estou insinuando nada."
  },
  AvgDialog_145514_Content_4 = {
    Text = "Evelyn olhou para as asas de Castor, mas sua expressão permaneceu tranquila, Como Se fosse completamente natural que toda pessoa no mundo escondesse um par de asas."
  },
  AvgDialog_145514_Content_40 = {
    Text = "Ainda faltam quatro ou cinco dias de subida, e não temos outro guia para substituir."
  },
  AvgDialog_145514_Content_41 = {
    Text = "Espero estar sendo excessivamente cauteloso, mas não podemos deixar de estar alertas."
  },
  AvgDialog_145514_Content_42 = {
    Text = "Neste Caminho, Nós já perdemos um Tinct. Não quero que, por descuido meu, mais alguém fique nesta montanha."
  },
  AvgDialog_145514_Content_43 = {
    Text = "O vento contornou a borda externa da crista rochosa."
  },
  AvgDialog_145514_Content_44 = {
    Text = "Contornou a silhueta agachada ao longe, quebrando o gelo."
  },
  AvgDialog_145514_Content_45 = {
    Text = "A ponta da picareta de Naraka batia nos fragmentos de gelo da sola do sapato, emitindo um som estável como um pêndulo, batida após batida."
  },
  AvgDialog_145514_Content_46 = {
    Text = "-Altitude 6.500 m-"
  },
  AvgDialog_145514_Content_5 = {
    Text = "Deixa eu fazer o curativo para você."
  },
  AvgDialog_145514_Content_6 = {
    Text = "Desculpe… ter escondido isso o tempo todo."
  },
  AvgDialog_145514_Content_7 = {
    Text = "Não tem problema. Todos nós viemos em busca de um Milagre extraordinário capaz de ressuscitar os mortos… Descobrir a existência de algo que quebra o senso comum num momento como esse é uma boa notícia."
  },
  AvgDialog_145514_Content_8 = {
    Text = "Além do mais, você não tira aquela capa nem para dormir — qualquer um saberia que você guarda um segredo."
  },
  AvgDialog_145514_Content_9 = {
    Text = "Apesar do tom de reclamação, você claramente percebe que, após essa batalha, todos Começaram a baixar a guarda e a se aproximar."
  },
  AvgDialog_145515_Content_1 = {
    Text = "Sete Fios do Destino"
  },
  AvgDialog_145515_Content_10 = {
    Text = "<Shake:Olhem ali — !>"
  },
  AvgDialog_145515_Content_11 = {
    Text = "Antes mesmo de terminar de falar, ela correu em direção à encosta suave do outro lado."
  },
  AvgDialog_145515_Content_12 = {
    Text = "Era um altar hexagonal."
  },
  AvgDialog_145515_Content_13 = {
    Text = "No centro do altar, já havia uma Coroa colocada."
  },
  AvgDialog_145515_Content_14 = {
    Text = "A mulher coberta de correntes contava os tesouros roubados. %player%A Chave de Prata e o Fio no bolso, o espelho, a Pluma Negra e a Maçã dourada no embrulho de Caraboo."
  },
  AvgDialog_145515_Content_15 = {
    Text = "O globo ocular de Balor?"
  },
  AvgDialog_145515_Content_16 = {
    Text = "Helot soltou uma risada desdenhosa e, em seguida, cravou suas unhas afiadas na bola de corrente ao seu lado."
  },
  AvgDialog_145515_Content_17 = {
    Text = "Com um som viscoso, a bola de corrente emitiu um barulho estranho e pegajoso."
  },
  AvgDialog_145515_Content_18 = {
    Text = "Ela mexeu, escavou… até retirar de lá um globo ocular ensanguentado."
  },
  AvgDialog_145515_Content_19 = {
    Text = "Tudo dado a você, seu guloso."
  },
  AvgDialog_145515_Content_2 = {
    Text = "–Altitude 8800 metros–"
  },
  AvgDialog_145515_Content_20 = {
    Text = "Ela colocou os seis tesouros em cada canto do altar."
  },
  AvgDialog_145515_Content_21 = {
    Text = "Agora, é hora de realizar meu desejo."
  },
  AvgDialog_145515_Content_22 = {
    Text = "Ela fechou os olhos e ficou em silêncio."
  },
  AvgDialog_145515_Content_23 = {
    Text = "Que Ela ressuscite… que eu possa matar meu inimigo com minhas próprias mãos e realizar minha vingança tão antiga."
  },
  AvgDialog_145515_Content_24 = {
    Text = "O vento cortante soprou pelos picos de Os Presos pela Neve. Seu pedido não recebeu nenhuma resposta."
  },
  AvgDialog_145515_Content_25 = {
    Text = "Por quê? Não entreguei as sete Manutenções a você?"
  },
  AvgDialog_145515_Content_26 = {
    Text = "A voz indignada de Helot ecoou em Reverberação entre os picos distantes, provocando uma série de pequenas avalanches."
  },
  AvgDialog_145515_Content_27 = {
    Text = "Porque uma das oferendas é falsa, ora?"
  },
  AvgDialog_145515_Content_28 = {Text = "Quem?!"},
  AvgDialog_145515_Content_29 = {
    Text = "Caraboo saltitou levemente para a frente, Como Se não ligasse nem um pouco para Helot."
  },
  AvgDialog_145515_Content_3 = {
    Text = "Este é um lugar onde os passos humanos jamais chegaram."
  },
  AvgDialog_145515_Content_30 = {
    Text = "Vocês só pensam nos próprios desejos, mas nunca refletem sobre o que a Divindade realmente quer como oferenda."
  },
  AvgDialog_145515_Content_31 = {
    Text = "a Maçã Dourada, a Maçã Dourada — você não acha que Desde Que seja uma Maçã dourada, já escolheu certo, né?"
  },
  AvgDialog_145515_Content_32 = {
    Text = "Ela pegou a Maçã Dourada do altar e deu uma mordida suave."
  },
  AvgDialog_145515_Content_33 = {
    Text = "Hmm, é você mesmo, como esperado."
  },
  AvgDialog_145515_Content_34 = {
    Text = "O papel dourado se desprendeu, revelando o verdadeiro conteúdo."
  },
  AvgDialog_145515_Content_35 = {
    Text = "Lanche, doce, tablete de cacau — pode chamar do que quiser, mas no fim das contas, é um chocolate comum dos mais comuns."
  },
  AvgDialog_145515_Content_36 = {
    Text = "<BigShake:Tcharam! A Bênção das fadas, o mais sublime dos sabores!>"
  },
  AvgDialog_145515_Content_37 = {
    Text = "Você... trapaceiro..."
  },
  AvgDialog_145515_Content_38 = {
    Text = "Um bandido não é muito melhor que um trapaceiro, não é?"
  },
  AvgDialog_145515_Content_39 = {
    Text = "Chega de conversa, entregue a verdadeira Maçã Dourada!"
  },
  AvgDialog_145515_Content_4 = {
    Text = "De pé no cume nevado, contemplando as montanhas brancas ao longe, o que reverbera no peito não é, surpreendentemente, a sensação de Conquistas por ter chegado ao topo."
  },
  AvgDialog_145515_Content_40 = {
    Text = "Para isso, você teria que perguntar se eles concordam."
  },
  AvgDialog_145515_Content_41 = {
    Text = "Caraboo se vira de lado, enquanto os membros da equipe de alpinismo ultrapassam o último penhasco."
  },
  AvgDialog_145515_Content_5 = {
    Text = "Mas sim o medo."
  },
  AvgDialog_145515_Content_6 = {
    Text = "O medo de estar longe do mundo dos homens, o medo de estar isolado de tudo que é familiar."
  },
  AvgDialog_145515_Content_7 = {
    Text = "Aqui não há picos mais altos ao longe, e tudo que aqueles que chegaram ao topo podem fazer é se ajoelhar diante do céu."
  },
  AvgDialog_145515_Content_8 = {
    Text = "Todos, chegamos ao topo."
  },
  AvgDialog_145515_Content_9 = {
    Text = "Entre os membros da expedição, havia Apenas uma pessoa que não foi minimamente abalada pela paisagem do cume."
  },
  AvgDialog_145516_Content_1 = {
    Text = "O Precursor"
  },
  AvgDialog_145516_Content_10 = {
    Text = "Então, ainda faltam a <Blue:Chave de Salomão> e o <Blue:Olho de Balor>."
  },
  AvgDialog_145516_Content_11 = {
    Text = "Caraboo dobra os dedos, murmurando para si mesma."
  },
  AvgDialog_145516_Content_12 = {
    Text = "Você acha que o Olho de Balor também vai cair do céu de repente, igual à Pena de Ma'at?"
  },
  AvgDialog_145516_Content_13 = {
    Text = "Essa piada não tem a menor graça."
  },
  AvgDialog_145516_Content_14 = {
    Text = "Você não sabe o que aconteceu com Castor, mas aquela pena negra como breu ainda carregava o rastro dele."
  },
  AvgDialog_145516_Content_15 = {
    Text = "Já está bem perto daqui."
  },
  AvgDialog_145516_Content_16 = {
    Text = "Antes de chegarmos ao cume, não podemos voltar atrás."
  },
  AvgDialog_145516_Content_17 = {
    Text = "William deu um tapinha no seu ombro. Evidentemente, ele sabia o que você estava pensando."
  },
  AvgDialog_145516_Content_18 = {
    Text = "Você sabia? Tenho uma sensação."
  },
  AvgDialog_145516_Content_19 = {
    Text = "Castor certamente encontrou algo que queria perseguir, e foi por isso que deixou o grupo."
  },
  AvgDialog_145516_Content_2 = {
    Text = "Este é o último ponto de descanso antes de chegar ao topo."
  },
  AvgDialog_145516_Content_20 = {
    Text = "E, se for ele, com certeza conseguirá realizar seu desejo."
  },
  AvgDialog_145516_Content_21 = {
    Text = "Evelyn deu uma leve tosse, como se quisesse dar mais Força às suas palavras, e acrescentou."
  },
  AvgDialog_145516_Content_22 = {
    Text = "Desde Que se viva tempo suficiente, é possível Espiar a tendência do destino alheio mesmo em convivências breves."
  },
  AvgDialog_145516_Content_23 = {
    Text = "Em Castor, o que você viu?"
  },
  AvgDialog_145516_Content_24 = {
    Text = "Simplicidade e resiliência."
  },
  AvgDialog_145516_Content_25 = {
    Text = "Até obter aquela única resposta, ele não vai parar.\nNão vai hesitar, nem vai desistir."
  },
  AvgDialog_145516_Content_26 = {
    Text = "E Você, Evelyn? Onde está Sua resposta?"
  },
  AvgDialog_145516_Content_27 = {
    Text = "Está lá na montanha."
  },
  AvgDialog_145516_Content_28 = {
    Text = "Que coincidência, seguimos o mesmo Caminho!"
  },
  AvgDialog_145516_Content_29 = {
    Text = "Caraboo tirou uma Maçã de não se sabe onde, jogou para o alto e a pegou."
  },
  AvgDialog_145516_Content_3 = {
    Text = "Olhando para as montanhas distantes, aos seus pés está a vasta neve e gelo, que se perde no horizonte longínquo entre as névoas do desfiladeiro."
  },
  AvgDialog_145516_Content_30 = {
    Text = "Se todos estiverem prontos, vamos Começar a última etapa."
  },
  AvgDialog_145516_Content_31 = {
    Text = "Não relaxem. Muitos imprevistos acontecem no último quilômetro."
  },
  AvgDialog_145516_Content_32 = {
    Text = "À sua frente ergue-se uma parede de gelo quase vertical."
  },
  AvgDialog_145516_Content_33 = {
    Text = "#N/ANaraka balança o machado de gelo, cravando a ponta diagonalmente na neve dura com um baque abafado, depois desloca seu peso para cima, com as pontas dianteiras pisando com precisão no pequeno buraco deixado pela ponta."
  },
  AvgDialog_145516_Content_34 = {
    Text = "Estranho, parece que alguém esteve aqui recentemente."
  },
  AvgDialog_145516_Content_35 = {
    Text = "Olhem, há alguns buracos aqui, parecem ter sido feitos por um picarete de gelo."
  },
  AvgDialog_145516_Content_36 = {
    Text = "Será que foram deixados pela expedição anterior?"
  },
  AvgDialog_145516_Content_37 = {
    Text = "Não parece. Já faz tempo demais, os rastros de então já teriam sido cobertos pelo gelo novamente."
  },
  AvgDialog_145516_Content_38 = {
    Text = "Deixa pra lá, não vou pensar demais nisso. Alguém já passou por aqui, o que é bom sinal — significa que este caminho é viável."
  },
  AvgDialog_145516_Content_39 = {
    Text = "Ele retirou um parafuso de gelo do arnês, girou-o e cravou na camada de gelo, produzindo um irritante rangido."
  },
  AvgDialog_145516_Content_4 = {
    Text = "A paisagem magnífica traz um certo alívio a vocês, que já estavam um pouco cansados."
  },
  AvgDialog_145516_Content_40 = {
    Text = "Até que o pino afundou até a base, Naraka pendurou um mosquetão de rosca nele, passou a corda principal por dentro e fechou a trava até o fim."
  },
  AvgDialog_145516_Content_41 = {
    Text = "Primeiro ponto de proteção."
  },
  AvgDialog_145516_Content_42 = {
    Text = "Todos, prendam os ascensores na corda principal. Usem as grampas das botas de montanhismo para se encaixar nos buracos que eu abri e avancem devagar."
  },
  AvgDialog_145516_Content_43 = {
    Text = "Você usou o picarete para encontrar um ponto de apoio sólido acima da cabeça, cravou a ponta com firmeza, depois levantou o pé direito e chutou com força a superfície de gelo, fazendo os dois dentes de aço mordirem o gelo."
  },
  AvgDialog_145516_Content_44 = {
    Text = "Transfira o peso para os pés, não se apoie na parede de gelo."
  },
  AvgDialog_145516_Content_45 = {
    Text = "Você respirou fundo o ar rarefeito que doía nos pulmões, afastou ligeiramente o corpo da parede de gelo e deixou as grampas suportarem o peso. O pé esquerdo acompanhou, mais um chute firme."
  },
  AvgDialog_145516_Content_46 = {
    Text = "O ascensor deslizava lentamente para cima junto com você, clicando a cada pequeno avanço."
  },
  AvgDialog_145516_Content_47 = {
    Text = "Na metade do percurso, você já estava encharcado de suor, e a concentração que antes era total começava a se dispersar sem que você conseguisse evitar."
  },
  AvgDialog_145516_Content_48 = {
    Text = "Mantenha o foco — este trecho não tolera nenhum imprevisto."
  },
  AvgDialog_145516_Content_49 = {
    Text = "Bem no momento em que suas palavras ecoaram, o imprevisto aconteceu."
  },
  AvgDialog_145516_Content_5 = {
    Text = "<Shake:Es... espera um momento.>"
  },
  AvgDialog_145516_Content_50 = {Text = "..."},
  AvgDialog_145516_Content_51 = {
    Text = "Um fio de luz vermelha relampejou na escuridão da noite, e a narina de William fremiu —"
  },
  AvgDialog_145516_Content_52 = {
    Text = "<BigShake:Abaixe-se —!>"
  },
  AvgDialog_145516_Content_53 = {
    Text = "Antes mesmo de terminar a frase, ele já havia se lançado sobre você com força, cobrindo seu corpo inteiro com o dele, e apenas a corda de segurança os sustentava, balançando contra a parede de gelo."
  },
  AvgDialog_145516_Content_54 = {
    Text = "Um fino fio de Sangue surgiu na bochecha dele."
  },
  AvgDialog_145516_Content_55 = {
    Text = "Hm, reflexos bem rápidos."
  },
  AvgDialog_145516_Content_56 = {
    Text = "Nas profundezas da escuridão, pesadas correntes arrastavam pelo chão, e o som do metal roçando no piso era abafado e prolongado."
  },
  AvgDialog_145516_Content_57 = {
    Text = "É você, hein — o sujeito que nos seguiu o caminho todo."
  },
  AvgDialog_145516_Content_58 = {
    Text = "Seguiu o caminho todo?"
  },
  AvgDialog_145516_Content_59 = {
    Text = "É verdade, quando encontramos Castor pela primeira vez, eu já avisei vocês que alguém estava nos seguindo."
  },
  AvgDialog_145516_Content_6 = {
    Text = "Evelyn respira ofegante. A baixa pressão da alta altitude claramente está causando um impacto severo em seu corpo."
  },
  AvgDialog_145516_Content_60 = {
    Text = "Só não sei quando ela passou à nossa frente."
  },
  AvgDialog_145516_Content_61 = {
    Text = "Não é à toa que essa presença me parecia estranhamente familiar."
  },
  AvgDialog_145516_Content_62 = {
    Text = "Eu me lembro do seu nome——"
  },
  AvgDialog_145516_Content_63 = {
    Text = "Que bom, assim dispensamos as apresentações."
  },
  AvgDialog_145516_Content_64 = {
    Text = "Na fronteira entre a luz e a sombra, uma silhueta emergiu lentamente."
  },
  AvgDialog_145516_Content_65 = {
    Text = "Seus dois pulsos estavam decepados, e atrás dela arrastavam-se duas pesadas bolas de corrente, sobre as quais um par de enormes olhos cor de Sangue fitava o mundo com ferocidade."
  },
  AvgDialog_145516_Content_66 = {
    Text = "……Helot: Catena."
  },
  AvgDialog_145516_Content_67 = {
    Text = "No mundo anterior, ela foi a última pessoa que vi."
  },
  AvgDialog_145516_Content_68 = {
    Text = "Em outras palavras — ela foi quem me matou."
  },
  AvgDialog_145516_Content_69 = {
    Text = "Naquela época, ela obedecia a Herbert, obedecia à Associação de Escultores."
  },
  AvgDialog_145516_Content_7 = {
    Text = "Atrás dela, a garota de estatura pequena caminha com passos surpreendentemente leves."
  },
  AvgDialog_145516_Content_70 = {
    Text = "E agora? <Yellow:Quem> te mandou vir?"
  },
  AvgDialog_145516_Content_71 = {
    Text = "Só um cão se preocupa com quem é seu dono."
  },
  AvgDialog_145516_Content_72 = {
    Text = "Só tenho uma coisa a fazer — enterrar vocês aqui para sempre."
  },
  AvgDialog_145516_Content_73 = {
    Text = "Inúmeras Pústulas emergem do chão, cercando vocês por todos os lados."
  },
  AvgDialog_145516_Content_8 = {
    Text = "Já temos o <Blue:Espelho de Yata> e a <Blue:Pena de Ma'at>. A <Blue:Coroa de Ariadne> deve estar no topo da montanha."
  },
  AvgDialog_145516_Content_9 = {
    Text = "Quanto ao <Blue:Fio de Moira>... Hehe, alguns de vocês não me contam, mas eu sei onde está. E consigo resolver a <Blue:Maçã Dourada>."
  },
  AvgDialog_145517_Content_1 = {
    Text = "Hoje as Aves Partem"
  },
  AvgDialog_145517_Content_10 = {
    Text = "Podem sair. Vocês já me seguiram o caminho todo, não é?"
  },
  AvgDialog_145517_Content_11 = {
    Text = "Já estou sozinho, e a distância agora não é suficiente para pedir socorro."
  },
  AvgDialog_145517_Content_12 = {
    Text = "<Shake:Vamos... nos... encarar...>"
  },
  AvgDialog_145517_Content_13 = {
    Text = "A pessoa que emergiu da floresta parecia ter saído de um sonho seu."
  },
  AvgDialog_145517_Content_14 = {
    Text = "<Shake:Não… você é…>"
  },
  AvgDialog_145517_Content_15 = {
    Text = "A figura ereta e nobre estava ainda mais magra do que quando se separaram."
  },
  AvgDialog_145517_Content_16 = {
    Text = "Meu nome é Pollux. Por ordem do Líder, vim para a Perseguição do fugitivo Castor."
  },
  AvgDialog_145517_Content_17 = {
    Text = "O conteúdo já não importava mais; a voz dele ressoava nos ouvidos de Castor como Murmúrios em Sonho."
  },
  AvgDialog_145517_Content_18 = {
    Text = "<SmallShake:Um Wendigo?>"
  },
  AvgDialog_145517_Content_19 = {
    Text = "Não, não era um Wendigo. Mesmo a mais bela das ilusões não conseguiria falsificar a textura real."
  },
  AvgDialog_145517_Content_2 = {
    Text = "O jovem corria velozmente pela Neve."
  },
  AvgDialog_145517_Content_20 = {
    Text = "Pecador… Castor… A luz sagrada iluminará seus pecados."
  },
  AvgDialog_145517_Content_21 = {
    Text = "Real, áspera, gelada, cruel, arrepiante."
  },
  AvgDialog_145517_Content_22 = {Text = "Pollux…"},
  AvgDialog_145517_Content_23 = {
    Text = "Aquela dor lancinante que subia ao coração."
  },
  AvgDialog_145517_Content_24 = {
    Text = "Por quanto tempo ainda poderia Esquivar? Por quanto tempo mais poderia Esquivar?"
  },
  AvgDialog_145517_Content_25 = {
    Text = "Castor pisou na Neve, avançando passo a passo em direção a Pollux."
  },
  AvgDialog_145517_Content_26 = {
    Text = "<Red:<Shake:Ajoelhe-se diante da Lanterna, e eu o absolverá de seus pecados, concedendo-lhe o renascimento em uma nova forma na terra santa sem pecado!>"
  },
  AvgDialog_145517_Content_27 = {
    Text = "Castor não obedeceu. Ele apenas continuou avançando em direção a Pollux."
  },
  AvgDialog_145517_Content_28 = {
    Text = "Mesmo que fosse um Wendigo, não importava. Ele apenas avançava."
  },
  AvgDialog_145517_Content_29 = {
    Text = "Pollux ergueu a faca. Uma faca familiar. Na última Perseguição, ela havia Penetrado o peito de Castor."
  },
  AvgDialog_145517_Content_3 = {
    Text = "Nada mais poderia detê-lo."
  },
  AvgDialog_145517_Content_30 = {
    Text = "<Big:Mais um passo, e a luz sagrada o abaterá!>"
  },
  AvgDialog_145517_Content_4 = {
    Text = "O Caminho de descida da montanha… era leve como voar com o vento."
  },
  AvgDialog_145517_Content_5 = {
    Text = "Um Caminho sem o peso de Uma Mentira fez sua alma também se elevar e flutuar."
  },
  AvgDialog_145517_Content_6 = {
    Text = "Desculpem, não deveria ter enganado vocês."
  },
  AvgDialog_145517_Content_7 = {
    Text = "Ainda bem que, agora, ainda há tempo para tudo."
  },
  AvgDialog_145517_Content_8 = {
    Text = "Cada vez que ele parava por um instante, sons semelhantes ao cair da Neve vinham da floresta atrás dele."
  },
  AvgDialog_145517_Content_9 = {
    Text = "Eram passos que cessavam abruptamente."
  },
  AvgDialog_145518_Content_1 = {
    Text = "A Lua Descongelada"
  },
  AvgDialog_145518_Content_10 = {
    Text = "Você aceita de bom grado."
  },
  AvgDialog_145518_Content_100 = {
    Text = "Ah, trapaceiros astutos, sempre aparecem com a imagem das vítimas mais inocentes…"
  },
  AvgDialog_145518_Content_101 = {
    Text = "Ela foi cantarolando uma melodia e voltou para a frente da fila."
  },
  AvgDialog_145518_Content_102 = {
    Text = "O que ela quis dizer com isso?"
  },
  AvgDialog_145518_Content_103 = {
    Text = "Eu também não entendi."
  },
  AvgDialog_145518_Content_104 = {
    Text = "Ei~, acompanhem, não fiquem para trás~"
  },
  AvgDialog_145518_Content_105 = {
    Text = "Os dois, sem entender nada, só puderam dar um passo à frente."
  },
  AvgDialog_145518_Content_106 = {
    Text = "-Altitude 6000m-"
  },
  AvgDialog_145518_Content_11 = {
    Text = "Eu sei que é difícil de acreditar, mas venho de uma estrela muito, muito distante. Derivei por tanto tempo que tudo que consigo lembrar é que em seus últimos dias, nós a chamávamos de <Blue:Estrela Abandonada.>"
  },
  AvgDialog_145518_Content_12 = {
    Text = "Passei por um tempo tão longo que não consigo nem contar, até chegar aqui."
  },
  AvgDialog_145518_Content_13 = {
    Text = "Eu acredito em você."
  },
  AvgDialog_145518_Content_14 = {
    Text = "O que quero dizer é… a Estrela Abandonada é distante demais, tão distante que até imaginá-la ou descrevê-la é muito difícil."
  },
  AvgDialog_145518_Content_15 = {
    Text = "Mas há pouco, nas águas do lago… acho que vi minha irmã, Faint."
  },
  AvgDialog_145518_Content_16 = {
    Text = "Tinct mordeu o lábio."
  },
  AvgDialog_145518_Content_17 = {
    Text = "Não, na verdade também não é bem isso… Apenas senti uma espécie de presságio, e a sombra no lago também vem da Estrela Abandonada…"
  },
  AvgDialog_145518_Content_18 = {
    Text = "Eu sei que é impossível, mas sinto que... <Shake:não foi uma alucinação...>"
  },
  AvgDialog_145518_Content_19 = {
    Text = "Você parece muito cansada."
  },
  AvgDialog_145518_Content_2 = {
    Text = "A neve e o vento cessaram em algum momento, e o que restou foi um silêncio tão vasto que fazia tremer. Acima, um azul profundo sem nenhuma nuvem, e até os picos nevados ao longe se revelavam em cada detalhe."
  },
  AvgDialog_145518_Content_20 = {
    Text = "Evelyn demonstrou uma expressão de preocupação."
  },
  AvgDialog_145518_Content_21 = {
    Text = "Se estiver se sentindo cansada, descanse quando precisar."
  },
  AvgDialog_145518_Content_22 = {
    Text = "Ainda não faz muito tempo que partimos, descer a montanha sozinha não seria perigoso."
  },
  AvgDialog_145518_Content_23 = {
    Text = "<Yellow:<Big:Não...! Não estou cansada! NÃO VOU EMBORA!>>"
  },
  AvgDialog_145518_Content_24 = {
    Text = "Para surpresa de todos, Tinct soltou um grito agitado."
  },
  AvgDialog_145518_Content_25 = {
    Text = "Ao perceber o olhar de todos voltado para ela, Tinct forçou a compostura, mas o peito ofegante ainda traía seus sentimentos reais."
  },
  AvgDialog_145518_Content_26 = {
    Text = "Desculpe… me perdi. Obrigada pela sua preocupação, <Yellow:não estou cansada.>"
  },
  AvgDialog_145518_Content_27 = {
    Text = "Mentir não tem graça nenhuma."
  },
  AvgDialog_145518_Content_28 = {
    Text = "Sou persistente. Não vou ficar para trás."
  },
  AvgDialog_145518_Content_29 = {
    Text = "Tinct cerrou os lábios novamente, lançou um olhar ao lago congelado e deu um passo para partir."
  },
  AvgDialog_145518_Content_3 = {
    Text = "Sob o céu completamente aberto, você caminha até a margem de um lago de gelo."
  },
  AvgDialog_145518_Content_30 = {
    Text = "Na superfície gelada do lago, apenas o reflexo desfocado dela se projetava."
  },
  AvgDialog_145518_Content_31 = {
    Text = "Vocês marcharam por meio dia, encontraram um terreno plano para montar acampamento, e Naraka instruiu todos os alpinistas a coletarem neve derretida para ferver água com os fogareiros de altitude."
  },
  AvgDialog_145518_Content_32 = {
    Text = "Quando vocês voltaram carregando a neve acumulada, descobriram uma densa fumaça saindo de perto do acampamento."
  },
  AvgDialog_145518_Content_33 = {
    Text = "Ei, a bagagem de quem está pegando fogo ali!"
  },
  AvgDialog_145518_Content_34 = {
    Text = "Hm...? Não!!!"
  },
  AvgDialog_145518_Content_35 = {
    Text = "As chamas lambiam a pequena bolsa de tecido que Caraboo sempre tratou como um tesouro."
  },
  AvgDialog_145518_Content_36 = {
    Text = "Espera, esse saco de moedas de ouro na sua bolsa?"
  },
  AvgDialog_145518_Content_37 = {
    Text = "Sob o calor das chamas, as moedas de ouro foram amolecendo e afundando."
  },
  AvgDialog_145518_Content_38 = {
    Text = "Não! Tudo bem! Eu consigo salvar!"
  },
  AvgDialog_145518_Content_39 = {
    Text = "Não, deixa eu ver!"
  },
  AvgDialog_145518_Content_4 = {
    Text = "Tinct ficou olhando fixamente para as águas do lago, perdida em pensamentos."
  },
  AvgDialog_145518_Content_40 = {
    Text = "Com o rasgar, todas as moedas de chocolate meio derretidas rolaram pelo chão."
  },
  AvgDialog_145518_Content_41 = {
    Text = "Uma delas rolou até os pés de William, que se abaixou para pegá-la."
  },
  AvgDialog_145518_Content_42 = {
    Text = "<Blue:Debauve & Gallais, chocolate Pistoles de Marie...>"
  },
  AvgDialog_145518_Content_43 = {
    Text = "Chocolate?!"
  },
  AvgDialog_145518_Content_44 = {
    Text = "<Shake:Ha, haha…> Isso… embora seja apenas chocolate, é muito caro!"
  },
  AvgDialog_145518_Content_45 = {
    Text = "Que absurdo, se não puder pagar a taxa do guia, saia da fila!"
  },
  AvgDialog_145518_Content_46 = {
    Text = "<Shake:Não, por favor, eu não conheço o Caminho sozinha…>"
  },
  AvgDialog_145518_Content_47 = {
    Text = "<Shake:Se você me expulsar do grupo, com certeza vou morrer na descida da montanha!>"
  },
  AvgDialog_145518_Content_48 = {
    Text = "Vai se danar, de que adianta ficar berrando aqui agora? Quem engana os outros tem que estar preparado para ser desmascarado!"
  },
  AvgDialog_145518_Content_49 = {
    Text = "Vendo que Naraka não cedia de jeito nenhum, Caraboo olhou ao redor e então, Como Se tivesse agarrado uma tábua de salvação, caiu de joelhos com um baque, abraçando firmemente suas coxas."
  },
  AvgDialog_145518_Content_5 = {
    Text = "Há algo no lago?"
  },
  AvgDialog_145518_Content_50 = {
    Text = "<Shake:Por favor, alma bondosa, Você não vai deixar uma menina descer a montanha sozinha e desamparada, vai?>"
  },
  AvgDialog_145518_Content_51 = {
    Text = "<Shake:Buááá, é sempre assim, eu sempre sou abandonada, não importa para onde eu vá, todo mundo me despreza por ser uma coitada sem nada…>"
  },
  AvgDialog_145518_Content_52 = {
    Text = "<Shake:Pessoa bondosa, alma caridosa, Você com certeza é diferente deles, Você vai me ajudar, não vai?>"
  },
  AvgDialog_145518_Content_53 = {
    Text = "Ela ergueu a cabeça, olhando para Você com os Olhos cheios de lágrimas."
  },
  AvgDialog_145518_Content_54 = {
    Text = "…Tudo bem. A taxa do guia dela, eu pago para Você depois que descermos."
  },
  AvgDialog_145518_Content_55 = {
    Text = "Incapaz de resistir ao ataque de Olhares dela, Você cedeu."
  },
  AvgDialog_145518_Content_56 = {
    Text = "<Big:Obrigada, muito obrigada, meu benfeitor!!> Você é o maior e mais magnífico salvador que Caraboo já conheceu!!"
  },
  AvgDialog_145518_Content_57 = {
    Text = "Caraboo imediatamente enxugou as lágrimas e saltou com um sorriso no rosto."
  },
  AvgDialog_145518_Content_58 = {
    Text = "Benfeitor, assim que eu recuperar meu poder como deusa da montanha, retribuirei sua bondade mil vezes!"
  },
  AvgDialog_145518_Content_59 = {
    Text = "Quando chegar a hora, pode esquecer trinta moedas de ouro — mesmo que fossem trezentas, ou três mil, eu conseguiria pagar!"
  },
  AvgDialog_145518_Content_6 = {
    Text = "Não, não, nada, não há nada…"
  },
  AvgDialog_145518_Content_60 = {
    Text = "Claro, claro."
  },
  AvgDialog_145518_Content_61 = {
    Text = "Você responde de forma evasiva."
  },
  AvgDialog_145518_Content_62 = {
    Text = "Afinal, todos ainda precisam escalar juntos. Desde Que esse assunto passe logo, está bom."
  },
  AvgDialog_145518_Content_63 = {
    Text = "A situação finalmente se acalmou, e todos voltaram a se ocupar ou a descansar."
  },
  AvgDialog_145518_Content_64 = {
    Text = "William te puxa de lado e sussurra algo para você."
  },
  AvgDialog_145518_Content_65 = {
    Text = "Está um pouco estranho. Eu me lembro que a mochila de Caraboo não estava naquela posição antes."
  },
  AvgDialog_145518_Content_66 = {
    Text = "<Red:Quem o colocou perto da fogueira?>"
  },
  AvgDialog_145518_Content_67 = {
    Text = "A água ferveu. Vamos todos tomar um pouco para aquecer o corpo."
  },
  AvgDialog_145518_Content_68 = {
    Text = "Tem sopa de alho?"
  },
  AvgDialog_145518_Content_69 = {
    Text = "Está me perguntando? Não tenho nada disso. Tome um pouco de água quente para se virar."
  },
  AvgDialog_145518_Content_7 = {
    Text = "Tinct voltou a si de repente, parecendo querer dizer algo, mas hesitando."
  },
  AvgDialog_145518_Content_70 = {
    Text = "Humph, não tem... Você, que se diz o melhor guia Sherpa, não é assim tão especial. E ainda cobra tão caro pela orientação."
  },
  AvgDialog_145518_Content_71 = {
    Text = "Vendo a tensão prestes a escalar novamente, Evelyn se apressou a intervir."
  },
  AvgDialog_145518_Content_72 = {
    Text = "Se quiser algo quente, tenho um pouco de chocolate quente aqui."
  },
  AvgDialog_145518_Content_73 = {
    Text = "E você, pequeno, as provisões que trouxe não são suficientes, não é? Percebi que você mal comeu."
  },
  AvgDialog_145518_Content_74 = {
    Text = "Eu? Não tem problema. Quando estamos em retiro espiritual, também comemos apenas uma refeição por dia."
  },
  AvgDialog_145518_Content_75 = {
    Text = "Mas ao escalar, não dá para não repor energia suficiente."
  },
  AvgDialog_145518_Content_76 = {
    Text = "Quando meu marido escalava, ele também gostava de carregar As Mochilas mais leves, assim como você."
  },
  AvgDialog_145518_Content_77 = {
    Text = "Desde que ficou preso em uma nevasca por vários dias, ele passou a escolher estratégias mais seguras."
  },
  AvgDialog_145518_Content_78 = {
    Text = "Seu marido... ele também é Alpinista?"
  },
  AvgDialog_145518_Content_79 = {
    Text = "Sim, ele é um Alpinista muito talentoso, que já tentou conquistar o Everest e o K2 antes."
  },
  AvgDialog_145518_Content_8 = {
    Text = "Depois de um momento, ela se virou para você e disse em voz baixa."
  },
  AvgDialog_145518_Content_80 = {
    Text = "E então, e agora?"
  },
  AvgDialog_145518_Content_81 = {Text = "E então?"},
  AvgDialog_145518_Content_82 = {
    Text = "Seu marido, ele parou de escalar montanhas?"
  },
  AvgDialog_145518_Content_83 = {
    Text = "<Shake:Hm? Por que você está me puxando?>"
  },
  AvgDialog_145518_Content_84 = {
    Text = "Todos olharam para o lado seguindo suas palavras. Caraboo tinha um sorriso no rosto, mas discretamente segurava a manga de Castor."
  },
  AvgDialog_145518_Content_85 = {
    Text = "Ao perceber que sua Ação havia sido descoberta, ela Recuperou a mão um tanto constrangida e murmurou baixinho."
  },
  AvgDialog_145518_Content_86 = {
    Text = "<Small:Idiota>."
  },
  AvgDialog_145518_Content_87 = {
    Text = "Não tem problema..."
  },
  AvgDialog_145518_Content_88 = {
    Text = "Meu marido... ele desapareceu durante a última tentativa de chegar ao cume do Everest. Ninguém sabe para onde ele foi. Nem o corpo foi encontrado."
  },
  AvgDialog_145518_Content_89 = {
    Text = "Antes, eu sempre o acompanhava, mas ficava esperando por volta do ponto C2."
  },
  AvgDialog_145518_Content_9 = {
    Text = "Desculpe, não sei por quê, mas tenho sempre uma sensação muito familiar com o senhor. Então… poderia me ouvir por um momento?"
  },
  AvgDialog_145518_Content_90 = {
    Text = "Agora que ele se foi, eu também quero ver a paisagem que ele via..."
  },
  AvgDialog_145518_Content_91 = {
    Text = "Evelyn contemplava a crista da montanha ao longe. A montanha de Neve eterna permanecia em silêncio, respondendo apenas com o Sibilo do vento."
  },
  AvgDialog_145518_Content_92 = {
    Text = "Desta vez, com certeza chegaremos ao cume."
  },
  AvgDialog_145518_Content_93 = {
    Text = "É nisso que acredito."
  },
  AvgDialog_145518_Content_94 = {
    Text = "Pouco depois da conversa, Caraboo voltou ao seu jeito descontraído, vagando de um lado para o outro com as mãos atrás das costas."
  },
  AvgDialog_145518_Content_95 = {
    Text = "Ela se aproximou de Castor de forma misteriosa."
  },
  AvgDialog_145518_Content_96 = {
    Text = "Ei, idiota, você não acha que alguém está nos seguindo?"
  },
  AvgDialog_145518_Content_97 = {
    Text = "Parece que não. Durante todo o Caminho, fiquei atento ao rastreamento da Igreja dos Portadores de Luz. Mas vocês são as primeiras pessoas que encontrei..."
  },
  AvgDialog_145518_Content_98 = {
    Text = "Eu também não senti nada."
  },
  AvgDialog_145518_Content_99 = {
    Text = "É? Então deve ser coisa da minha cabeça."
  },
  AvgDialog_145519_Content_1 = {Text = "..."},
  AvgDialog_145519_Content_10 = {
    Text = "O Espelho de Yata, junto com a Espada Kusanagi e o Colar de Jade Yasakani, são conhecidos na mitologia japonesa como os Três Tesouros Sagrados. Nas representações mais comuns, o Espelho de Yata é feito de metal, com ornamentos de estilo japonês esculpidos no verso."
  },
  AvgDialog_145519_Content_11 = {
    Text = "Mas olhe para este espelho…"
  },
  AvgDialog_145519_Content_12 = {
    Text = "A superfície do espelho é fina, plana e polida, de formato perfeitamente redondo, como a lua cheia suspensa no alto do céu."
  },
  AvgDialog_145519_Content_13 = {
    Text = "Sob a fria superfície de vidro, parece haver partículas de luz colorida circulando suavemente."
  },
  AvgDialog_145519_Content_14 = {
    Text = "De qualquer forma, vamos tirá-lo daqui primeiro para ver."
  },
  AvgDialog_145519_Content_15 = {
    Text = "Naraka ergueu um espigão de gelo e facilmente perfurou a camada de gelo, retirando o espelho."
  },
  AvgDialog_145519_Content_16 = {
    Text = "Caraboo avançou rapidamente, arrancou-o de uma vez e o guardou velozmente na mochila que carregava."
  },
  AvgDialog_145519_Content_17 = {
    Text = "<Shake:O que foi! O que estão olhando, não me olhem!>"
  },
  AvgDialog_145519_Content_18 = {
    Text = "Este é o tesouro da Deusa da Montanha Nevada, então claro que quem o encontrou deveria ficar com ele — e fui eu!"
  },
  AvgDialog_145519_Content_19 = {
    Text = "Ninguém tentou disputar a posse com Ela."
  },
  AvgDialog_145519_Content_2 = {
    Text = "Vocês vagam à beira do lago de gelo. A superfície do lago é Como um espelho, lisa e imaculada, com uma visão desobstruída ao redor — não há nenhum sinal de Tinct."
  },
  AvgDialog_145519_Content_20 = {
    Text = "Comparado a um espelho que parecia completamente comum, o desaparecimento de Tinct era claramente mais digno de atenção."
  },
  AvgDialog_145519_Content_21 = {
    Text = "Mas ninguém voltou a falar sobre o assunto. Apenas a sua sombra permanecia, inevitavelmente, pesando no coração de cada um."
  },
  AvgDialog_145519_Content_3 = {
    Text = "No som do vento que ecoa entre as montanhas nevadas, Como Se houvesse a mistura do canto de Tinct com soluços suaves — presentes e ausentes ao mesmo tempo, impossível distinguir se é o vento ou uma Ilusão."
  },
  AvgDialog_145519_Content_4 = {
    Text = "Tinct… será que não vai mais voltar?"
  },
  AvgDialog_145519_Content_5 = {
    Text = "Ninguém contestou."
  },
  AvgDialog_145519_Content_6 = {
    Text = "Estranho, isso estava aqui ontem?"
  },
  AvgDialog_145519_Content_7 = {
    Text = "Na superfície do lago gelado, encravado no gelo transparente e sólido, repousava silenciosamente um espelho perfeitamente redondo."
  },
  AvgDialog_145519_Content_8 = {
    Text = "<Shake:O Espelho de Yata! Este é o Espelho de Yata que deve ser oferecido à deusa da montanha!>"
  },
  AvgDialog_145519_Content_9 = {
    Text = "William, você parece querer dizer algo mas está se contendo."
  },
  AvgDialog_145520_Content_1 = {
    Text = "Sétimo Viajante"
  },
  AvgDialog_145520_Content_10 = {
    Text = "Nestes dias não há outras equipes de alpinismo, todos podem descansar aqui tranquilamente, ninguém virá incomodar—"
  },
  AvgDialog_145520_Content_100 = {
    Text = "Cuidado! Tem algo subindo!"
  },
  AvgDialog_145520_Content_11 = {
    Text = "Antes que Naraka terminasse de falar, um farfalhar súbito ecoou de um canto da caverna."
  },
  AvgDialog_145520_Content_12 = {
    Text = "…Hm, tem alguém?"
  },
  AvgDialog_145520_Content_13 = {
    Text = "A voz de William ecoou pela caverna sem obter resposta."
  },
  AvgDialog_145520_Content_14 = {
    Text = "Somos uma equipe de alpinismo, viemos aqui para nos abrigar do vento e da neve, não temos más intenções."
  },
  AvgDialog_145520_Content_15 = {
    Text = "Você emitia sinais amistosos, carregando a lanterna em direção às rochas."
  },
  AvgDialog_145520_Content_16 = {Text = "Cuidado!"},
  AvgDialog_145520_Content_17 = {
    Text = "A silhueta atrás das rochas se tensionou de repente. Sem esperar que alguém explicasse, um ataque feroz veio da escuridão."
  },
  AvgDialog_145520_Content_19 = {
    Text = "Talvez por estar em desvantagem numérica, o invasor lançou um Assalto e desapareceu nas sombras em um piscar de olhos. Mas você ainda reconheceu aquela silhueta no breve confronto."
  },
  AvgDialog_145520_Content_2 = {
    Text = "Depois de Naraka guiar vocês por um trecho, uma fenda negra se abriu entre os picos da montanha."
  },
  AvgDialog_145520_Content_20 = {
    Text = "<Shake:Castor?!>"
  },
  AvgDialog_145520_Content_21 = {
    Text = "Após um momento, uma capa negra emergiu das sombras, e por trás dela, metade de um rosto com expressão cautelosa se revelou."
  },
  AvgDialog_145520_Content_22 = {
    Text = "…Você me conhece?"
  },
  AvgDialog_145520_Content_23 = {
    Text = "Não, isso seria uma história muito longa de contar…"
  },
  AvgDialog_145520_Content_24 = {
    Text = "Então, por que você está aqui sozinho?"
  },
  AvgDialog_145520_Content_25 = {Text = "..."},
  AvgDialog_145520_Content_26 = {Text = "..."},
  AvgDialog_145520_Content_27 = {
    Text = "Bem, eu e meu irmão — Pollux combinamos de escapar da Igreja dos Portadores de Luz de maneiras diferentes, um após o outro. Mas esperei um mês no local combinado e ele nunca apareceu."
  },
  AvgDialog_145520_Content_28 = {
    Text = "Acho que minha fuga fez com que a Senhora Juliette reforçasse a vigilância. Desde então, tenho procurado uma maneira de resgatá-lo."
  },
  AvgDialog_145520_Content_29 = {
    Text = "<Yellow:Ainda bem que consegui me esconder com sucesso e escapar do rastreamento deles.>"
  },
  AvgDialog_145520_Content_3 = {
    Text = "Vamos entrar."
  },
  AvgDialog_145520_Content_30 = {
    Text = "Por fim, ouvi dizer que no topo da montanha nevada havia uma Divindade capaz de realizar qualquer desejo."
  },
  AvgDialog_145520_Content_31 = {
    Text = "Mas não posso me juntar a nenhuma expedição de alpinismo… Os espiões da Igreja estão por toda parte. Se eu aparecer com frequência, serei descoberto facilmente."
  },
  AvgDialog_145520_Content_32 = {Text = "Idiota."},
  AvgDialog_145520_Content_33 = {Text = "Ah… ?"},
  AvgDialog_145520_Content_34 = {
    Text = "Nunca vi ninguém tão estúpido quanto você."
  },
  AvgDialog_145520_Content_35 = {
    Text = "Mesmo que você escale a montanha sozinho, onde vai encontrar os sete artefatos sagrados?"
  },
  AvgDialog_145520_Content_36 = {Text = "..."},
  AvgDialog_145520_Content_37 = {
    Text = "Parece que eu não tinha pensado nisso…"
  },
  AvgDialog_145520_Content_38 = {
    Text = "Exatamente! Agora, você precisa da ajuda da Deusa da Neve."
  },
  AvgDialog_145520_Content_39 = {
    Text = "Venha! Desde que se junte a A Ordem Sagrada, garanto que, após chegarmos ao topo, ajudarei a resolver a sua separação do seu irmão!"
  },
  AvgDialog_145520_Content_4 = {
    Text = "Vocês se apoiaram mutuamente para descer pelas rochas irregulares, e você olhou para trás em direção à entrada da caverna."
  },
  AvgDialog_145520_Content_40 = {Text = "Sério?"},
  AvgDialog_145520_Content_41 = {
    Text = "Claro que é verdade! Não poderia ser mais verdade!"
  },
  AvgDialog_145520_Content_42 = {
    Text = "Mas para demonstrar sua sinceridade para com A Ordem Sagrada, todos os tesouros que você carrega devem ser entregues à fada para que ela os guarde por você."
  },
  AvgDialog_145520_Content_43 = {
    Text = "... Tudo bem."
  },
  AvgDialog_145520_Content_44 = {
    Text = "Castor hesitou por um bom tempo, gaguejando, e então tirou algumas moedas e um Livro de Histórias surrado e desgastado."
  },
  AvgDialog_145520_Content_45 = {
    Text = "É tudo o que tenho. Posso me juntar a vocês?"
  },
  AvgDialog_145520_Content_46 = {
    Text = "William deu um tapinha no seu braço."
  },
  AvgDialog_145520_Content_47 = {
    Text = "Já se divertiu o suficiente?"
  },
  AvgDialog_145520_Content_48 = {
    Text = "Hum, bem, Castor, seja bem-vindo à nossa equipe de expedição."
  },
  AvgDialog_145520_Content_49 = {
    Text = "Caraboo estava só brincando com você. Desde que traga seus próprios suprimentos, não precisa entregar nada além disso."
  },
  AvgDialog_145520_Content_5 = {
    Text = "A fissura era estreita e uniforme, como um olho semicerrado, bloqueando o vento e a neve do lado de fora."
  },
  AvgDialog_145520_Content_50 = {
    Text = "Humph, a deusa da montanha nevada também não se impressiona com essa miserável Manutenção sua, é melhor guardá-la para si mesmo."
  },
  AvgDialog_145520_Content_51 = {
    Text = "Castor alisou cuidadosamente as dobras do Livro de Histórias com todo o cuidado, e então o guardou com cautela no peito."
  },
  AvgDialog_145520_Content_52 = {
    Text = "Depois ele lançou um olhar para as moedas, com o olhar vagando entre vocês."
  },
  AvgDialog_145520_Content_53 = {
    Text = "Se ninguém as quer, então eu as aceito com prazer."
  },
  AvgDialog_145520_Content_54 = {
    Text = "Naraka fez um gesto com a mão e a pedra ficou instantaneamente vazia."
  },
  AvgDialog_145520_Content_55 = {
    Text = "A taxa de guia deste jovem senhor é bem mais barata do que a dos outros."
  },
  AvgDialog_145520_Content_56 = {
    Text = "Se não me engano, já pagamos a sua taxa de guia."
  },
  AvgDialog_145520_Content_57 = {
    Text = "Se for necessário pagar uma taxa adicional, eu pago por ele."
  },
  AvgDialog_145520_Content_58 = {
    Text = "Não precisa, somos completos estranhos, como posso me dar ao luxo de incomodá-la..."
  },
  AvgDialog_145520_Content_59 = {
    Text = "A mão estendida de Evelyn interrompeu as palavras de Castor, que hesitou por meio segundo e então apertou a mão dela em retorno."
  },
  AvgDialog_145520_Content_6 = {
    Text = "Aqui dentro… está tão quente…"
  },
  AvgDialog_145520_Content_60 = {
    Text = "Evelyn, me chamo Evelyn, sou arqueóloga."
  },
  AvgDialog_145520_Content_61 = {
    Text = "Agora não somos mais estranhos, certo?"
  },
  AvgDialog_145520_Content_62 = {Text = "..."},
  AvgDialog_145520_Content_63 = {
    Text = "A nevasca prende todos vocês na caverna estreita. Sem fogo ainda, a conversa é sua única defesa contra o frio."
  },
  AvgDialog_145520_Content_64 = {
    Text = "Você disse há pouco que está procurando seu irmão gêmeo, correto?"
  },
  AvgDialog_145520_Content_65 = {Text = "Bom."},
  AvgDialog_145520_Content_66 = {
    Text = "Castor assentiu com cautela."
  },
  AvgDialog_145520_Content_67 = {
    Text = "Que coincidência, eu também estou procurando minha irmã gêmea."
  },
  AvgDialog_145520_Content_68 = {
    Text = "Eu e Faint somos pessoas muito diferentes. Minha irmã mais velha, apesar de ter problemas de saúde, é na verdade uma pessoa corajosa e forte."
  },
  AvgDialog_145520_Content_69 = {
    Text = "Ao mencionar a irmã gêmea, Tinct, que costumava estar sempre perdida em devaneios, pareceu ganhar vida, exibindo um sorriso suave."
  },
  AvgDialog_145520_Content_7 = {
    Text = "Ufa, ufa, eu sou a deusa da montanha nevada, como é que eu não sabia que havia um lugar assim na montanha?"
  },
  AvgDialog_145520_Content_70 = {
    Text = "E Aquele Pollux? Que tipo de pessoa ele é?"
  },
  AvgDialog_145520_Content_71 = {
    Text = "<Shake:Pollux...>"
  },
  AvgDialog_145520_Content_72 = {
    Text = "Também é bem diferente de mim. Ele é inteligente, perspicaz, com grande capacidade de compreensão. Desde pequeno, o líder e os professores sempre o preferiram…"
  },
  AvgDialog_145520_Content_73 = {
    Text = "Não se preocupe. Você também tem suas qualidades. Por exemplo, você não disse agora mesmo que conseguiu escapar do rastreamento da Igreja? Isso também é muito impressionante."
  },
  AvgDialog_145520_Content_74 = {
    Text = "Castor corou levemente, deu uma leve tosse e desviou o assunto de volta para Tinct."
  },
  AvgDialog_145520_Content_75 = {
    Text = "Você e sua irmã, por que se separaram?"
  },
  AvgDialog_145520_Content_76 = {
    Text = "No momento da fuga, ela me deixou a última passagem do navio."
  },
  AvgDialog_145520_Content_77 = {
    Text = "Sua voz era suave, Como Se qualquer esforço pudesse dispersar aquela memória pelo vento e pela neve."
  },
  AvgDialog_145520_Content_78 = {
    Text = "Tomara que, no fim, possamos nos reencontrar com eles."
  },
  AvgDialog_145520_Content_79 = {
    Text = "Castor ficou em Silêncio por um momento, O Olhar passando por ela e pousando na tempestade branca que revolvia sem cessar do lado de fora da caverna."
  },
  AvgDialog_145520_Content_8 = {
    Text = "Claro, a taxa de guia dos Sherpa não é cobrada à toa."
  },
  AvgDialog_145520_Content_80 = {
    Text = "Entre as conversas, o tempo foi passando segundo a segundo."
  },
  AvgDialog_145520_Content_81 = {Text = "..."},
  AvgDialog_145520_Content_82 = {
    Text = "Na sétima hora, a tempestade atinge um pico quase malicioso."
  },
  AvgDialog_145520_Content_83 = {
    Text = "Parece que vamos passar a noite na caverna."
  },
  AvgDialog_145520_Content_84 = {
    Text = "Naraka removeu os restos já úmidos no espaço aberto no centro da caverna, tentando acender uma nova fogueira com galhos secos."
  },
  AvgDialog_145520_Content_85 = {
    Text = "Das Profundezas da caverna, na escuridão, vinha um som miúdo e fragmentado, como se algo estivesse arranhando a parede de pedra com as unhas."
  },
  AvgDialog_145520_Content_86 = {Text = "Tem ratos?"},
  AvgDialog_145520_Content_87 = {
    Text = "Nessa altitude não deveria haver ratos…"
  },
  AvgDialog_145520_Content_88 = {
    Text = "O som parou de repente. O silêncio dentro da caverna era perturbador."
  },
  AvgDialog_145520_Content_89 = {
    Text = "Daquela escuridão tão densa que não deixava passar nem um fio de luz, uma sensação de malícia veio como Vento no rosto."
  },
  AvgDialog_145520_Content_9 = {
    Text = "Os anciãos dizem que essa fissura apareceu de repente após uma avalanche."
  },
  AvgDialog_145520_Content_90 = {
    Text = "Naraka ergueu a tocha e iluminou as Profundezas da caverna seguindo o som. A luz avançou apenas alguns passos antes de ser engolida pela escuridão à frente."
  },
  AvgDialog_145520_Content_91 = {Text = "Não vá."},
  AvgDialog_145520_Content_92 = {
    Text = "Só vou dar uma olhada."
  },
  AvgDialog_145520_Content_93 = {
    Text = "Naraka se apoiou na parede de pedra e se inclinou com cuidado."
  },
  AvgDialog_145520_Content_94 = {
    Text = "A luz trêmula das chamas ultrapassou a borda rochosa aos seus pés, iluminando um poço de escuridão abaixo. A superfície da água era tão lisa que não havia uma única ondulação, quase Fusionar-se em um com as sombras ao redor."
  },
  AvgDialog_145520_Content_95 = {
    Text = "Abaixo tem água. <Shake:Parece muito fundo——>"
  },
  AvgDialog_145520_Content_96 = {
    Text = "Mal terminou de falar, aquela \"superfície d'água\" negra como breu afundou de repente."
  },
  AvgDialog_145520_Content_97 = {
    Text = "Naraka perdeu o equilíbrio, com meio pé já dentro da abertura que se expandia rapidamente."
  },
  AvgDialog_145520_Content_98 = {
    Text = "<Shake:Me segure——!>"
  },
  AvgDialog_145520_Content_99 = {
    Text = "Você o agarrou bruscamente pela gola e o puxou para trás."
  },
  AvgDialog_145521_Content_1 = {
    Text = "À Lareira, Após o Anoitecer"
  },
  AvgDialog_145521_Content_10 = {
    Text = "No canto havia algumas caixas de madeira mofadas, e na parede rochosa mais ao fundo, um pedaço de corrente de ferro quebrada estava pregado."
  },
  AvgDialog_145521_Content_100 = {
    Text = "Ele fechou os Olhos, sentindo os contornos que seus dedos percorriam."
  },
  AvgDialog_145521_Content_101 = {
    Text = "<Small:<Italic:...\"O vilão lançou um feitiço e transformou seu irmão mais novo em um corvo.\">>"
  },
  AvgDialog_145521_Content_102 = {
    Text = "<Small:<Italic:...\"Mas o irmão mais velho conhecia a cor de suas asas.\">>"
  },
  AvgDialog_145521_Content_103 = {
    Text = "A chama tremeluzeu uma vez e voltou a se apagar."
  },
  AvgDialog_145521_Content_104 = {
    Text = "Posso te trazer de volta?"
  },
  AvgDialog_145521_Content_105 = {
    Text = "Na próxima vez que nos encontrarmos, você ainda vai me reconhecer?"
  },
  AvgDialog_145521_Content_106 = {Text = "..."},
  AvgDialog_145521_Content_107 = {
    Text = "Muito tempo depois, ele fechou o livro, levantou-se e caminhou silenciosamente até a entrada da caverna, curvando-se para limpar as frestas de ventilação bloqueadas pela neve noturna."
  },
  AvgDialog_145521_Content_108 = {
    Text = "A neve escorregou entre seus dedos e caiu sobre o pequeno monte já acumulado, sem fazer nenhum som."
  },
  AvgDialog_145521_Content_109 = {
    Text = "O amanhecer ainda não havia chegado."
  },
  AvgDialog_145521_Content_11 = {
    Text = "Alguém morou aqui antes?"
  },
  AvgDialog_145521_Content_110 = {
    Text = "Você foi despertado pela fraca luz que entrava pela abertura da caverna."
  },
  AvgDialog_145521_Content_111 = {
    Text = "Castor já havia arrumado as mochilas e estava parado na entrada da caverna, esperando você acordar."
  },
  AvgDialog_145521_Content_112 = {
    Text = "Desculpe, estou prestes a partir."
  },
  AvgDialog_145521_Content_113 = {
    Text = "Meu desejo é diferente do de vocês."
  },
  AvgDialog_145521_Content_114 = {
    Text = "Quero encontrar meu irmão de volta, e posso fazer isso com minhas próprias mãos."
  },
  AvgDialog_145521_Content_115 = {
    Text = "Mas este caminho é muito perigoso, você sozinho——"
  },
  AvgDialog_145521_Content_116 = {
    Text = "…Há mais uma coisa sobre a qual eu estava hesitando se deveria contar a vocês. Mas agora é hora de ser honesto——"
  },
  AvgDialog_145521_Content_117 = {
    Text = "Castor respirou fundo, como se tivesse tomado uma grande decisão."
  },
  AvgDialog_145521_Content_118 = {
    Text = "Na primeira vez que nos encontramos, Tinct disse que, embora eu não fosse tão agradável quanto Pollux, eu tinha minhas próprias qualidades e conseguia escapar do rastreamento da Igreja dos Portadores da Luz sozinho."
  },
  AvgDialog_145521_Content_119 = {
    Text = "Mas isso era mentira. Era para enganar vocês."
  },
  AvgDialog_145521_Content_12 = {
    Text = "Era um ponto de abrigo de uma antiga equipe de alpinismo, abandonado há muitos anos. O local da fogueira fica ali, vou limpar."
  },
  AvgDialog_145521_Content_120 = {
    Text = "Sou muito mais fraco do que vocês sabem, e não consegui fazer isso."
  },
  AvgDialog_145521_Content_121 = {
    Text = "Os fiéis estão sempre colados nos meus calcanhares. Se eu continuar aqui, serei um fardo para todos vocês."
  },
  AvgDialog_145521_Content_122 = {
    Text = "Ele ergueu a cabeça e olhou para o interior da caverna, onde os outros ainda dormiam profundamente."
  },
  AvgDialog_145521_Content_123 = {
    Text = "O símbolo danificado na caverna — eu o reconheci, é o símbolo da Igreja dos Portadores da Luz."
  },
  AvgDialog_145521_Content_124 = {
    Text = "Este é o acampamento Temporário deles."
  },
  AvgDialog_145521_Content_125 = {
    Text = "Quanto mais alto, mais aberto fica. Cedo ou tarde eles vão me Descobrir. É melhor partir logo e me misturar à multidão — assim consigo escapar da Perseguição deles."
  },
  AvgDialog_145521_Content_126 = {
    Text = "Ele se virou e caminhou para dentro da Neve e do vento."
  },
  AvgDialog_145521_Content_127 = {
    Text = "Você ficou parado no mesmo lugar por um longo tempo, até que a silhueta dele desapareceu completamente."
  },
  AvgDialog_145521_Content_128 = {
    Text = "De trás vieram passos suaves."
  },
  AvgDialog_145521_Content_129 = {
    Text = "Caraboo havia acordado sem que ninguém percebesse, encostada na entrada da caverna, olhando na direção em que Castor havia partido."
  },
  AvgDialog_145521_Content_13 = {
    Text = "Ele caminhou com destreza em direção a uma plataforma de pedra enegrecida pela fumaça no centro da caverna, agachou-se e Começou a remover as Cinzas antigas."
  },
  AvgDialog_145521_Content_130 = {
    Text = "……Idiota."
  },
  AvgDialog_145521_Content_131 = {
    Text = "No tom de Ela, não havia os Espinhos de sempre."
  },
  AvgDialog_145521_Content_132 = {
    Text = "A equipe de alpinismo passou de cinco para quatro pessoas."
  },
  AvgDialog_145521_Content_14 = {
    Text = "O Olhar de Castor pousou brevemente sobre as gravuras na parede. Ele não disse nada, Apenas retirou O Olhar."
  },
  AvgDialog_145521_Content_15 = {
    Text = "Antes que houvesse tempo de perguntar, todos tiveram O Olhar atraído pelo Chamar de Caraboo."
  },
  AvgDialog_145521_Content_16 = {
    Text = "<Big:Uma caverna quentinha! Fogueira! Longo descanso!>"
  },
  AvgDialog_145521_Content_17 = {
    Text = "Caraboo estava com muita Empolgação."
  },
  AvgDialog_145521_Content_18 = {
    Text = "Embora todos estivessem se esforçando para manter o ânimo, Você conseguia perceber que todos estavam exaustos pela batalha contra o Wendigo."
  },
  AvgDialog_145521_Content_19 = {
    Text = "Uma caverna perfeita. Um descanso perfeito."
  },
  AvgDialog_145521_Content_2 = {
    Text = "A neve e o vento não cessavam. Vocês seguiram as fissuras do gelo em busca de abrigo, e finalmente encontraram uma caverna de neve protegida do vento sob uma parede rochosa."
  },
  AvgDialog_145521_Content_20 = {
    Text = "Independentemente dos perigos que espreitam à frente, nada pode impedi-los de desfrutar de um momento de tranquilidade agora."
  },
  AvgDialog_145521_Content_21 = {
    Text = "A fogueira foi acesa no lado interno da entrada da caverna, perto da abertura. A fumaça era carregada pelo vento oblíquo para fora da caverna."
  },
  AvgDialog_145521_Content_22 = {
    Text = "Evelyn tirou uma esteira impermeável da mochila, primeiro pressionou uma fina camada de Neve no chão, depois estendeu a esteira por cima."
  },
  AvgDialog_145521_Content_23 = {
    Text = "Todos tiraram seus casacos endurecidos pelo frio e se reuniram ao redor da fogueira, estendendo as mãos o mais perto possível das chamas."
  },
  AvgDialog_145521_Content_24 = {
    Text = "Seria ótimo se a montanha pudesse ser sempre tão quente assim."
  },
  AvgDialog_145521_Content_25 = {Text = "Pfft."},
  AvgDialog_145521_Content_26 = {
    Text = "O que você está rindo?"
  },
  AvgDialog_145521_Content_27 = {
    Text = "Estou rindo de você, seu tolo, por não saber medir suas palavras. E se a Deusa da Montanha Nevada considerar isso seu desejo real e decidir realizá-lo?"
  },
  AvgDialog_145521_Content_28 = {
    Text = "Também não seria ruim. Assim, todos os alpinistas estariam muito mais seguros."
  },
  AvgDialog_145521_Content_29 = {
    Text = "A luz da fogueira se refletia nos Olhos sérios de Castor."
  },
  AvgDialog_145521_Content_3 = {
    Text = "A entrada era estreita, mas o interior era surpreendentemente espaçoso."
  },
  AvgDialog_145521_Content_30 = {
    Text = "Deixa pra lá, não tem graça nenhuma brincar com você, seu tolo."
  },
  AvgDialog_145521_Content_31 = {
    Text = "Caraboo, você tem algum desejo?"
  },
  AvgDialog_145521_Content_32 = {
    Text = "Caraboo pareceu não esperar ser perguntada de repente, ficou por um momento surpresa e então seus Olhos se moveram de um lado para o outro."
  },
  AvgDialog_145521_Content_33 = {
    Text = "Eu sou a Deusa da Montanha Nevada, sou a responsável por realizar os desejos de vocês!"
  },
  AvgDialog_145521_Content_34 = {
    Text = "Se eu tivesse algum desejo, seria recuperar meu poder."
  },
  AvgDialog_145521_Content_35 = {
    Text = "Sim! Exatamente! Depois de recuperar meu poder, vou reorganizar A Ordem Sagrada! Farei todo o continente prestar Manutenção à Deusa da Montanha Nevada!"
  },
  AvgDialog_145521_Content_36 = {
    Text = "Evelyn solta uma risada suave. A luz da fogueira cintila em seus olhos escuros."
  },
  AvgDialog_145521_Content_37 = {
    Text = "E quanto aos outros?"
  },
  AvgDialog_145521_Content_38 = {
    Text = "Ela se virou para Você, mas seu olhar não carregava curiosidade, apenas a preocupação casual de uma Conversa cotidiana."
  },
  AvgDialog_145521_Content_39 = {
    Text = "Também estou curiosa! Que tipo de desejo devo conceder ao meu benfeitor?"
  },
  AvgDialog_145521_Content_4 = {
    Text = "Ninguém entre ainda."
  },
  AvgDialog_145521_Content_40 = {
    Text = "Alguém me indicou um Caminho de volta para Nosso Lar. Para voltar, preciso encontrar uma pessoa."
  },
  AvgDialog_145521_Content_41 = {
    Text = "Você também é tolo. Por que não faz um pedido para voltar logo?"
  },
  AvgDialog_145521_Content_42 = {
    Text = "Alguém já escreveu uma Profecia para mim."
  },
  AvgDialog_145521_Content_43 = {
    Text = "<Yellow:O destino é uma trama de elos interligados; aquele que tenta saltar qualquer nó para chegar ao fim certamente sofrerá a dor do fio rompido.>"
  },
  AvgDialog_145521_Content_44 = {
    Text = "Entendido. E este senhor William ao seu lado?"
  },
  AvgDialog_145521_Content_45 = {
    Text = "A história de William é um pouco complicada de contar."
  },
  AvgDialog_145521_Content_46 = {
    Text = "Pelo menos agora, para mim, a coisa mais importante é acompanhar %player% de volta a Misaq, de volta ao lado de Ramona."
  },
  AvgDialog_145521_Content_47 = {
    Text = "Você olha para William com espanto. Ele tem uma expressão tranquila, e você não consegue encontrar nenhum sinal de mentira em suas microexpressões."
  },
  AvgDialog_145521_Content_48 = {
    Text = "Não precisa me encarar assim."
  },
  AvgDialog_145521_Content_49 = {
    Text = "<Yellow:Minhas outras obrigações neste mundo chegaram a um fim temporário.>"
  },
  AvgDialog_145521_Content_5 = {
    Text = "Ele ergueu a picareta e foi batendo centímetro a centímetro ao longo do topo interno da entrada da caverna."
  },
  AvgDialog_145521_Content_50 = {
    Text = "Ao dizer isso, William deliberadamente levantou a mão para afastar os fios de cabelo que cobriam seus olhos, ocultando a maior parte de sua expressão."
  },
  AvgDialog_145521_Content_51 = {
    Text = "E você, tolo?"
  },
  AvgDialog_145521_Content_52 = {Text = "Eu?"},
  AvgDialog_145521_Content_53 = {
    Text = "Castor olhava fixamente para a fogueira."
  },
  AvgDialog_145521_Content_54 = {
    Text = "Eu quero que Pollux… volte."
  },
  AvgDialog_145521_Content_55 = {
    Text = "Caraboo ergueu os olhos em direção a Castor, e aquele traço habitual de irreverência em seu olhar desapareceu por um momento."
  },
  AvgDialog_145521_Content_56 = {
    Text = "Você acabou de dizer que quer que ele volte."
  },
  AvgDialog_145521_Content_57 = {
    Text = "Mas quando nos encontramos pela primeira vez, você disse que queria resgatá-lo."
  },
  AvgDialog_145521_Content_58 = {
    Text = "Há uma diferença sutil entre essas duas formas de dizer… mas não é impossível que sejam a mesma coisa."
  },
  AvgDialog_145521_Content_59 = {
    Text = "Castor, seu irmão, foi realmente aprisionado por aquele tal líder religioso?"
  },
  AvgDialog_145521_Content_6 = {
    Text = "Este bloco está Solto, evitem acampar diretamente abaixo dele."
  },
  AvgDialog_145521_Content_60 = {
    Text = "Um breve Silêncio. Caraboo pegou a Maçã e deu mais uma mordida, mudando de assunto como se nada tivesse acontecido."
  },
  AvgDialog_145521_Content_61 = {
    Text = "Na verdade, realizar um desejo é bem simples."
  },
  AvgDialog_145521_Content_62 = {
    Text = "Veja, entre os sete tesouros não há também uma pena? Talvez a pena que você carrega seja a <Yellow:Pena de Ma'at>."
  },
  AvgDialog_145521_Content_63 = {
    Text = "Ma'at, deusa da verdade, da ordem e da justiça, usa uma pena de avestruz na cabeça."
  },
  AvgDialog_145521_Content_64 = {
    Text = "No Julgamento dos mortos, Anúbis coloca o coração do Morto na balança junto com essa pena. Se o coração for mais pesado que a pena, ele é Devorado pelo monstro Ammit; se o coração for tão leve quanto a pena, o Morto pode entrar no Campo dos Juncos."
  },
  AvgDialog_145521_Content_65 = {
    Text = "A pena representa a \"inocência\" na mitologia egípcia."
  },
  AvgDialog_145521_Content_66 = {
    Text = "A Pena da Inocência… que ironia."
  },
  AvgDialog_145521_Content_67 = {
    Text = "Castor esboçou um sorriso levemente resignado."
  },
  AvgDialog_145521_Content_68 = {
    Text = "Essas Asas foram implantadas em mim e no meu irmão pela líder da Igreja dos Portadores da Luz, Juliette, para criar sua Divindade."
  },
  AvgDialog_145521_Content_69 = {
    Text = "Em sua narrativa, você ouviu uma voz. Uma voz de sofrimento incontrolável."
  },
  AvgDialog_145521_Content_7 = {
    Text = "Ele se curvou e caminhou para o interior mais profundo da caverna, agachou-se e ficou ouvindo rente ao chão por um momento, depois testou a umidade da superfície rochosa com o dorso da mão."
  },
  AvgDialog_145521_Content_70 = {
    Text = "Depois, ela arrancou as asas de Pollux. Agora, apenas eu ainda carrego essas Asas de Profanação."
  },
  AvgDialog_145521_Content_71 = {
    Text = "Castor acariciou suavemente as penas nas pontas das asas, e por um momento você teve a impressão de que estavam manchadas de Sangue."
  },
  AvgDialog_145521_Content_72 = {
    Text = "Portanto, falar em inocência… essas Asas talvez sejam a existência mais distante da inocência."
  },
  AvgDialog_145521_Content_73 = {
    Text = "O ar ficou em silêncio, com apenas o crepitar da fogueira Queimando."
  },
  AvgDialog_145521_Content_74 = {
    Text = "Naraka, e qual é o seu desejo?"
  },
  AvgDialog_145521_Content_75 = {
    Text = "William se virou de repente para Naraka, que estava aquecendo-se ao fogo ao lado e aparentemente não tinha intenção de participar da conversa."
  },
  AvgDialog_145521_Content_76 = {
    Text = "Eu Apenas sou um guia, não tenho intenção de fazer um desejo junto com vocês."
  },
  AvgDialog_145521_Content_77 = {
    Text = "Se for preciso falar em <Yellow:desejo de Naraka>, ele talvez queira que o nome dos guias Sherpa também seja registrado nos anais dos alpinistas."
  },
  AvgDialog_145521_Content_78 = {
    Text = "Mas realizar esse tipo de desejo por meio de um milagre seria sem graça demais, não é?"
  },
  AvgDialog_145521_Content_79 = {
    Text = "Criar mentiras através da Histórico compilando e falsificando livros é simples e fácil demais — tão fácil que perde o valor."
  },
  AvgDialog_145521_Content_8 = {
    Text = "Podem entrar, o Interior deve ser seguro."
  },
  AvgDialog_145521_Content_80 = {
    Text = "Chegar ao topo é algo que deve ser alcançado com os próprios pés."
  },
  AvgDialog_145521_Content_81 = {
    Text = "Com os próprios esforços…"
  },
  AvgDialog_145521_Content_82 = {
    Text = "Castor pareceu perceber algo."
  },
  AvgDialog_145521_Content_83 = {
    Text = "Ei — Você não parece o tipo de pessoa que faz esse tipo de declaração sensata."
  },
  AvgDialog_145521_Content_84 = {
    Text = "Caraboo tampou o nariz e fez vento com a mão, Como Se tivesse cheirado algo fedorento."
  },
  AvgDialog_145521_Content_85 = {
    Text = "Hora da sinceridade, para de fingir, vamos conversar de verdade?"
  },
  AvgDialog_145521_Content_86 = {
    Text = "Ela fitou os Olhos de Naraka com um sorriso malicioso, Naraka desviou O Olhar, e Ela se curvou, perseguindo seu olhar sem deixá-lo escapar."
  },
  AvgDialog_145521_Content_87 = {
    Text = "<Shake:Vamos lá, me mostre seu verdadeiro rosto!>"
  },
  AvgDialog_145521_Content_88 = {
    Text = "Caraboo se lançou para frente, tentando agarrar Naraka como uma águia capturando um pintinho, mas Naraka Apenas se desviou com um leve movimento de lado."
  },
  AvgDialog_145521_Content_89 = {
    Text = "Chega de bagunça, amanhã ainda temos Caminho a percorrer. Não quero que vocês não cheguem ao topo da montanha."
  },
  AvgDialog_145521_Content_9 = {
    Text = "Na parede rochosa havia vestígios de padrões desbotados, como o contorno de algum símbolo, com a tinta já tão descascada que era difícil de identificar."
  },
  AvgDialog_145521_Content_90 = {
    Text = "Caraboo errou o salto e aproveitou para sentar na Neve, sorrindo de orelha a orelha."
  },
  AvgDialog_145521_Content_91 = {
    Text = "Já que você também quer que a gente chegue ao topo, então estou tranquila."
  },
  AvgDialog_145521_Content_92 = {Text = "..."},
  AvgDialog_145521_Content_93 = {
    Text = "A fogueira queima até a madrugada, reduzida a brasas esparsas de luz vermelha."
  },
  AvgDialog_145521_Content_94 = {
    Text = [[
Naraka dividiu os turnos noturnos, duas horas para cada um.
Todos foram dormindo aos poucos. Do interior dos sacos de dormir vinham roncos suaves e abafados.]]
  },
  AvgDialog_145521_Content_95 = {
    Text = "Castor naturalmente assumiu o primeiro turno. Ele se apoiou na parede da caverna e, do fundo de As Mochilas, retirou um pequeno livro com as bordas desgastadas e embranquecidas."
  },
  AvgDialog_145521_Content_96 = {
    Text = "Era um Livro de Histórias."
  },
  AvgDialog_145521_Content_97 = {
    Text = "Seus dedos percorreram os dois nomes na página de rosto."
  },
  AvgDialog_145521_Content_98 = {
    Text = "A caligrafia caprichada de criança era a dele próprio; o outro nome estava rabiscado de forma torta com giz de cera vermelho, a cor desbotando gradualmente com o passar do tempo."
  },
  AvgDialog_145521_Content_99 = {Text = "Pollux…"},
  AvgDialog_145522_Content_1 = {
    Text = "Não Responda"
  },
  AvgDialog_145522_Content_10 = {
    Text = "Castor caminhava na retaguarda do grupo, mais silencioso do que de costume."
  },
  AvgDialog_145522_Content_11 = {
    Text = "Ei, distraído. Você está com frio?"
  },
  AvgDialog_145522_Content_12 = {Text = "Estou bem."},
  AvgDialog_145522_Content_13 = {
    Text = "Comigo também. Que estranho."
  },
  AvgDialog_145522_Content_14 = {
    Text = "Então, de quem seria essa respiração tão pesada e ofegante?"
  },
  AvgDialog_145522_Content_15 = {
    Text = "O grupo parou. Todos viraram a cabeça ao mesmo tempo. Atrás deles, havia apenas as pegadas que eles mesmos haviam deixado, umas mais fundas, outras mais rasas."
  },
  AvgDialog_145522_Content_16 = {
    Text = "Nas bordas das pegadas, a Neve estava limpa. Limpa como se algo tivesse a apagado suavemente."
  },
  AvgDialog_145522_Content_17 = {
    Text = "Silêncio. Apenas o vento. O vento soprava de muito longe, contornava o cume da montanha e se infiltrava pela gola de cada um."
  },
  AvgDialog_145522_Content_18 = {
    Text = "No vento havia um som Quase inaudível. Não era um canto. Era um Chamar."
  },
  AvgDialog_145522_Content_19 = {
    Text = "<Change>...Eve...lyn..."
  },
  AvgDialog_145522_Content_2 = {
    Text = "A nevasca diminuiu, mas o céu estava ainda mais sombrio do que quando a tempestade estava no auge."
  },
  AvgDialog_145522_Content_20 = {Text = "?!"},
  AvgDialog_145522_Content_21 = {
    Text = "Ela se virou bruscamente. O Campo de Neve estava vazio, não havia nada. Mas a voz voltou, desta vez mais próxima, carregando uma ternura quase cruel."
  },
  AvgDialog_145522_Content_22 = {
    Text = "<Change>...Evelyn... Estou com frio..."
  },
  AvgDialog_145522_Content_23 = {
    Text = "Aquilo é..."
  },
  AvgDialog_145522_Content_24 = {
    Text = "<Shake:Impossível…>"
  },
  AvgDialog_145522_Content_25 = {
    Text = "O Semblante dela perdeu instantaneamente toda a cor. Seus lábios estavam pálidos, sua voz tremia, como se o momento que Ela havia imaginado tantas vezes finalmente tivesse chegado."
  },
  AvgDialog_145522_Content_26 = {
    Text = "Vocês… vocês ouviram isso?!"
  },
  AvgDialog_145522_Content_27 = {Text = "É ele."},
  AvgDialog_145522_Content_28 = {
    Text = "<Shake:É a voz dele…>"
  },
  AvgDialog_145522_Content_29 = {
    Text = "Senhora Evelyn, independentemente de quem você esteja ouvindo, por favor não responda."
  },
  AvgDialog_145522_Content_3 = {
    Text = "Camadas de nuvens cinza-chumbo pairavam baixas sobre o cume da montanha, como um Sonho antigo e pesado que se recusava a dissipar."
  },
  AvgDialog_145522_Content_30 = {
    Text = "Vocês prendem a respiração. O vento do Campo de Neve passa pelos seus ouvidos, e então— \nVocês todos também ouviram."
  },
  AvgDialog_145522_Content_31 = {
    Text = "O vento se transformou em inúmeras vozes, inúmeros Chamares envolventes. Cada um soprava de uma direção que você já conheceu e já perdeu."
  },
  AvgDialog_145522_Content_32 = {
    Text = "Uma voz. Uma voz Chamando por você. Fria e cristalina."
  },
  AvgDialog_145522_Content_33 = {
    Text = "<Change>Estou esperando por você, parceira..."
  },
  AvgDialog_145522_Content_34 = {
    Text = "<Change>Não fique para trás. Chegaremos ao fim disso juntos."
  },
  AvgDialog_145522_Content_35 = {Text = "Ramona..."},
  AvgDialog_145522_Content_36 = {
    Text = "Você range os dentes, Contendo o desejo de seguir a voz."
  },
  AvgDialog_145522_Content_37 = {
    Text = "Seus pés parecem congelados na neve, sem obedecer aos seus comandos. Você consegue sentir uma força extremamente leve e suave, vinda da direção da voz, puxando lentamente, lentamente, seu centro de gravidade para frente."
  },
  AvgDialog_145522_Content_38 = {
    Text = "Era um Convite. Um Convite impossível de recusar."
  },
  AvgDialog_145522_Content_39 = {
    Text = "Desde Que você desse um passo à frente, poderia voltar a qualquer momento quente do passado—"
  },
  AvgDialog_145522_Content_4 = {
    Text = "Ninguém falava. Os cães-guia seguiam na frente, e até eles haviam suprimido os gemidos habituais que costumavam emitir."
  },
  AvgDialog_145522_Content_40 = {
    Text = "Guardião—"
  },
  AvgDialog_145522_Content_41 = {
    Text = "A voz de William chegou de muito longe. Só então você percebeu que, sem saber quando, já havia dado meio passo."
  },
  AvgDialog_145522_Content_42 = {
    Text = "Alguns cães-guia jazem mortos no chão ao seu lado, com as gargantas brutalmente dilaceradas, e sangue carmesim espalhado em manchas contrastantes e chocantes sobre a neve branca e imaculada."
  },
  AvgDialog_145522_Content_43 = {Text = "Afaste-se."},
  AvgDialog_145522_Content_44 = {
    Text = "Me dê sua mão."
  },
  AvgDialog_145522_Content_45 = {
    Text = "O rosto de William estava pálido como papel, e a mão com que segurava seu braço tremia involuntariamente."
  },
  AvgDialog_145522_Content_46 = {
    Text = "Você conseguia sentir que ele se esforçava para se Conter, para não ser seduzido por aquela voz."
  },
  AvgDialog_145522_Content_47 = {
    Text = "Aquela voz é falsa. Vocês precisam despertar."
  },
  AvgDialog_145522_Content_48 = {
    Text = "Ele disse em voz muito baixa, como se estivesse proclamando um Julgamento."
  },
  AvgDialog_145522_Content_49 = {
    Text = "<Shake:<Small:Uh... Tia Rosa...>>"
  },
  AvgDialog_145522_Content_5 = {
    Text = "Vá mais devagar, o terreno está irregular."
  },
  AvgDialog_145522_Content_50 = {
    Text = "Caraboo acordou como se saísse de um sonho, ainda murmurando algo."
  },
  AvgDialog_145522_Content_51 = {
    Text = "Mas nem todos conseguem acordar."
  },
  AvgDialog_145522_Content_52 = {
    Text = "Pollux...! Pollux...! Onde você está?!"
  },
  AvgDialog_145522_Content_53 = {
    Text = "<Shake:<Big:Pollux...!!!>>"
  },
  AvgDialog_145522_Content_54 = {
    Text = "<Italic:...Irmão, estou com frio...>"
  },
  AvgDialog_145522_Content_55 = {
    Text = "<Italic:Irmão, a cela é muito escura, estou com muito medo… por favor… me deixe sair… Sua Santidade, ela…>"
  },
  AvgDialog_145522_Content_56 = {
    Text = "<Shake:<Italic:...Irmão, por que você não vem me procurar...>>"
  },
  AvgDialog_145522_Content_57 = {
    Text = "Pollux!! Espere por mim, já vou até você—"
  },
  AvgDialog_145522_Content_58 = {
    Text = "<Shake:Ei, idiota, pare aí!>"
  },
  AvgDialog_145522_Content_59 = {
    Text = "Ignorando os chamados de vocês, Castor disparou para fora."
  },
  AvgDialog_145522_Content_6 = {
    Text = "Este trecho antes era uma encosta reta, agora surgiram ravinas transversais."
  },
  AvgDialog_145522_Content_60 = {
    Text = "<Shake:Segurem ele!>"
  },
  AvgDialog_145522_Content_61 = {
    Text = "Não deixem aquele idiota ser enganado!"
  },
  AvgDialog_145522_Content_7 = {
    Text = "São novas fissuras formadas após a última avalanche… não deveriam ser tão profundas."
  },
  AvgDialog_145522_Content_8 = {
    Text = "A forma da montanha está mudando."
  },
  AvgDialog_145522_Content_9 = {
    Text = "William não continuou. Seus olhos verde-azulados fitavam a distância, com as sobrancelhas levemente franzidas."
  },
  AvgDialog_145523_Content_1 = {
    Text = "O Cume Sem Desejos"
  },
  AvgDialog_145523_Content_10 = {
    Text = "William se agacha lentamente, as pontas dos dedos roçando as entalhes intrincados entre os pedestais, que você havia tomado por mera decoração."
  },
  AvgDialog_145523_Content_100 = {
    Text = "<Shake:Pare! Desligue isso! <Red:Vou apodrecer antes mesmo de o desejo ser concedido!>>"
  },
  AvgDialog_145523_Content_101 = {
    Text = "Isso nunca fez parte do nosso acordo."
  },
  AvgDialog_145523_Content_102 = {
    Text = "É, ele só prometeu iniciar o ritual por você. Nunca prometeu que você sobreviveria a ele."
  },
  AvgDialog_145523_Content_103 = {
    Text = "Entendo... Cada palavra que William disse era a mais pura verdade... mas costuradas juntas, formaram uma mentira perfeita."
  },
  AvgDialog_145523_Content_104 = {
    Text = "O sexto halo se ergue."
  },
  AvgDialog_145523_Content_105 = {
    Text = "A montanha inteira treme como algo agonizante. Incontáveis massas de carne pálida emergem sob as rochas que se partem e avançam em direção ao altar como uma onda."
  },
  AvgDialog_145523_Content_106 = {
    Text = "Não! Aqueles são meus! Minha Carne e sangue! Minha Força! Meus desejos!"
  },
  AvgDialog_145523_Content_107 = {
    Text = "Ou talvez nunca tenham sido seus para começo de conversa. Esse poder não pertence a você. São os desejos roubados dos inúmeros peregrinos que você atraiu e enterrou aqui."
  },
  AvgDialog_145523_Content_108 = {
    Text = "Esse poder pertence a todos que você enganou, devorou e descartou. Você não tem o direito de reivindicá-lo..."
  },
  AvgDialog_145523_Content_109 = {
    Text = "...E agora, eles simplesmente estão retornando ao lugar a que pertencem."
  },
  AvgDialog_145523_Content_11 = {
    Text = "Impossível... como isso poderia estar aqui... Essas marcas ao lado dos entalhes do altar... eu as reconheço."
  },
  AvgDialog_145523_Content_110 = {
    Text = "Tinct, Castor, Evelyn e Fengor, a quem você nunca chegou a conhecer pessoalmente..."
  },
  AvgDialog_145523_Content_111 = {
    Text = "Rosto após rosto, nome após nome emergem à superfície de sua mente, antes de afundar nas profundezas silenciosas da memória."
  },
  AvgDialog_145523_Content_112 = {
    Text = "<BigShake:Não ouse! NÃO OUSE!>"
  },
  AvgDialog_145523_Content_113 = {
    Text = "<Big:<Red:Vou destruir o altar primeiro, depois mastigar cada um de vocês em pedaços!>"
  },
  AvgDialog_145523_Content_114 = {
    Text = "William acena com a cabeça para você."
  },
  AvgDialog_145523_Content_115 = {
    Text = "Vamos cada um fazer a nossa parte. Eu manterei o ritual em andamento."
  },
  AvgDialog_145523_Content_116 = {
    Text = "Deixa comigo. Vou deter o verme!"
  },
  AvgDialog_145523_Content_12 = {
    Text = "Esta é a obra de Fengor."
  },
  AvgDialog_145523_Content_13 = {Text = "Fengor?"},
  AvgDialog_145523_Content_14 = {
    Text = "Você conhece esse nome. O parceiro de William, o Investigador que desapareceu de \"aquele mundo\" antes dele."
  },
  AvgDialog_145523_Content_15 = {
    Text = "Então é isso, a Chave de Salomão… o motivo pelo qual o verme não consegue iniciar o ritual… e o propósito de Fengor ao vir a este mundo…"
  },
  AvgDialog_145523_Content_16 = {
    Text = "Hahaha... Entendo! Entendo agora! Isso é hilário!"
  },
  AvgDialog_145523_Content_17 = {
    Text = "Então foi isso que aquela tecelã workaholic pretendia me mostrar. Ter te trazido até aqui valeu muito o meu tempo!"
  },
  AvgDialog_145523_Content_18 = {
    Text = "O que você quer dizer?"
  },
  AvgDialog_145523_Content_19 = {
    Text = "N simplesmente dá de ombros."
  },
  AvgDialog_145523_Content_2 = {
    Text = "Era um altar imenso, Como Se tivesse a mesma idade que toda a cordilheira."
  },
  AvgDialog_145523_Content_20 = {
    Text = "Ora, não sou seu tradutor. Veja este Sr. William aqui? Pergunte a ele. Você me deixou sair do seu ventre, mas será que pareço alguém que pretende retribuir o \"favor\"?"
  },
  AvgDialog_145523_Content_21 = {
    Text = "Eu faço a explicação."
  },
  AvgDialog_145523_Content_22 = {
    Text = "\"A Chave de Salomão\" na verdade não é uma chave, mas sim um grimório."
  },
  AvgDialog_145523_Content_23 = {
    Text = "E o conteúdo mais crucial registrado no grimório é o método de Invocação dos setenta e dois demônios de Salomão. Em outras palavras, é o método de conectar mundos."
  },
  AvgDialog_145523_Content_24 = {
    Text = "Ele ergueu a cabeça e olhou para o centro exato das sete bases — uma fechadura estreita, quase fundida com as sombras."
  },
  AvgDialog_145523_Content_25 = {
    Text = "Esses símbolos são um código secreto que apenas ele e eu conseguimos decifrar."
  },
  AvgDialog_145523_Content_26 = {
    Text = "William se ajoelha diante do círculo mágico, sua mão traçando cuidadosamente os entalhes no chão. Aos poucos, as palavras silenciosas começam a se encaixar em sua mente, formando uma voz familiar."
  },
  AvgDialog_145523_Content_27 = {
    Text = "É William? Eu sabia que você chegaria até aqui.\n\nO círculo mágico aqui contém três escritas antigas diferentes. Apostaria que, entre nosso grupo, apenas você, o aluno dedicado, conseguiria lê-las todas de uma vez.\nSão feitiços de invocação e selamento. Você deve entender o que isso significa."
  },
  AvgDialog_145523_Content_28 = {
    Text = "Ele controla a abertura e o fechamento de certa \"Porta.\""
  },
  AvgDialog_145523_Content_29 = {
    Text = "#N/AEm resumo, este círculo mágico usa a \"Coroa\" como meio, conectando-se à origem deste mundo. Portanto, apenas dentro deste mundo, ele pode de fato conceder qualquer desejo.\n\nCertamente você deve ter se perguntado por que foi lançado neste mundo desconhecido, não é?\n\nAgora, posso lhe dar a resposta.\n\nVocê é esse desejo... meu desejo."
  },
  AvgDialog_145523_Content_3 = {
    Text = "Degraus de pedra em forma circular subiam camada por camada, e no topo erguiam-se sete pedestais vazios dispostos em círculo. Entre um pedestal e outro, em sulcos antigos, havia uma luz dourado-escura há muito ressecada."
  },
  AvgDialog_145523_Content_30 = {
    Text = "Lamentavelmente, o poder que ofereci não foi suficiente. Só consegui abrir uma fresta para que seu Núcleo de prata pudesse passar.\n\nO destino que não pude alcançar... você deve alcançá-lo em meu lugar.\n\nAfinal, você é o lendário Investigador William, não é?"
  },
  AvgDialog_145523_Content_31 = {
    Text = "Espero que ainda tenha minha Chave de Prata.\n\nUse-a para ativar o círculo mágico, depois faça seu desejo, e Ele o guiará até a terra prometida.\n\nO caminho à frente — isso, deixo a seu cargo.\n\nAtenciosamente,\nFengor"
  },
  AvgDialog_145523_Content_32 = {
    Text = "Os dedos de William pararam."
  },
  AvgDialog_145523_Content_33 = {
    Text = "Ele não diz uma palavra. Você nunca viu essa expressão em seu rosto."
  },
  AvgDialog_145523_Content_34 = {Text = "%player%."},
  AvgDialog_145523_Content_35 = {
    Text = "Estou aqui."
  },
  AvgDialog_145523_Content_36 = {
    Text = "Você não me perguntou naquela época por que fui a primeira pessoa a despertar sob o Chamar de Wendigo?"
  },
  AvgDialog_145523_Content_37 = {
    Text = "Porque sou o único entre nós que já viu seus ossos em decomposição."
  },
  AvgDialog_145523_Content_38 = {
    Text = "Seu corpo estava completamente apodrecido, impossível de identificar. Mas reconheci a metade da Chave de prata que ele carregava."
  },
  AvgDialog_145523_Content_39 = {
    Text = "Número I-1021, um número pertencente a Fengor. Sempre que um número desaparece dos registros, sabemos que mais um predecessor foi esquecido pelo mundo."
  },
  AvgDialog_145523_Content_4 = {
    Text = "Este é o destino para onde o Verme da Montanha atraiu inúmeros alpinistas, usando os desejos como isca."
  },
  AvgDialog_145523_Content_40 = {
    Text = "Desde então, sempre carrego esta Chave de prata junto ao corpo."
  },
  AvgDialog_145523_Content_41 = {
    Text = "Ele fechou os olhos. Quando os abriu novamente, naqueles Olhos verde-jade, restava apenas algo sereno e inabalável."
  },
  AvgDialog_145523_Content_42 = {
    Text = "…Fengor, obrigado pela confiança que depositou em mim."
  },
  AvgDialog_145523_Content_43 = {
    Text = "Verme da Montanha, vou lhe dizer como ativar o ritual."
  },
  AvgDialog_145523_Content_44 = {
    Text = "Aqueles que oferecem seus desejos à montanha entregam suas próprias almas para alimentar o círculo mágico. Por meio deles, uma ponte é construída até a Origem do mundo."
  },
  AvgDialog_145523_Content_45 = {
    Text = "A Origem do mundo?"
  },
  AvgDialog_145523_Content_46 = {
    Text = "Se minha hipótese estiver correta, é o Sol Negro suspenso no céu."
  },
  AvgDialog_145523_Content_47 = {
    Text = "O Sol Negro existe de forma muito semelhante ao \"Black Pool\" de Misaq — abrangendo tudo, uma suspensão das ruínas de tudo que foi e que será, afogando-se em uma maré corrosiva."
  },
  AvgDialog_145523_Content_48 = {
    Text = "A escala do desejo concedido depende inteiramente de quanta dessa maré o desejante ousa extrair do Sol Negro."
  },
  AvgDialog_145523_Content_49 = {
    Text = "Garotinha, mantenha os olhos fixos nele. Certifique-se de que ele não está tecendo mentiras."
  },
  AvgDialog_145523_Content_5 = {
    Text = "Ninguém jamais saiu deste lugar com vida. Todos os alpinistas do passado... estão todos aqui. Sob nossos pés. Dentro do ventre da montanha."
  },
  AvgDialog_145523_Content_50 = {
    Text = "Relutantemente, Caraboo dá um passo à frente e olha fundo nos olhos de William."
  },
  AvgDialog_145523_Content_51 = {Text = "<Shake:!!>"},
  AvgDialog_145523_Content_52 = {
    Text = "William fecha os olhos e balança levemente a cabeça."
  },
  AvgDialog_145523_Content_53 = {
    Text = "Cada palavra que ele acabou de dizer é verdade."
  },
  AvgDialog_145523_Content_54 = {
    Text = "<Shake:Não minta para mim! Você hesitou agora mesmo, seu pequeno impostor!>"
  },
  AvgDialog_145523_Content_55 = {
    Text = "Estou mentindo? Você deveria saber melhor do que eu."
  },
  AvgDialog_145523_Content_56 = {
    Text = "O Verme solta uma gargalhada fria e zombeteira, fazendo uma cascata de neve despencar pelos penhascos."
  },
  AvgDialog_145523_Content_57 = {
    Text = "Hmph. O ritual é tudo que importa. Quando isso terminar, vou lidar com você pessoalmente, traidor."
  },
  AvgDialog_145523_Content_58 = {
    Text = "Diga-me então, Verme da Montanha — qual é a escala do desejo que você almeja?"
  },
  AvgDialog_145523_Content_59 = {
    Text = "Hehehe... você precisa mesmo perguntar? Quanto mais grandioso, melhor! Quero engolir o mundo inteiro em meu ventre — um banquete sem fim, inesgotável!"
  },
  AvgDialog_145523_Content_6 = {
    Text = "Chega de conversa. Me diga como esse círculo mágico funciona."
  },
  AvgDialog_145523_Content_60 = {
    Text = "Que criatura gananciosa e tola. Talvez devesse ter aprendido a beleza da moderação."
  },
  AvgDialog_145523_Content_61 = {
    Text = "Como um parasita do Caos como você poderia entender? Se eu tivesse seguido as regras, jamais teria alcançado tais alturas."
  },
  AvgDialog_145523_Content_62 = {
    Text = "E por \"alturas\", você quer dizer arrastar seu corpo inchado e contorcido pelo topo de um pico gelado?"
  },
  AvgDialog_145523_Content_63 = {
    Text = "Ugh... deixa pra lá. Ninguém nunca ouve meus excelentes conselhos de qualquer forma."
  },
  AvgDialog_145523_Content_64 = {Text = "Entendido."},
  AvgDialog_145523_Content_65 = {
    Text = "William assentiu com a cabeça."
  },
  AvgDialog_145523_Content_66 = {
    Text = "Para exigir um desejo de escala grandiosa, você deve entregar cada uma das oferendas."
  },
  AvgDialog_145523_Content_67 = {
    Text = "<BigShake:Pegue-os! Pegue todos eles! Eles existem exatamente para este momento!>"
  },
  AvgDialog_145523_Content_68 = {
    Text = "%player%, entregue-me as Ofertas."
  },
  AvgDialog_145523_Content_69 = {
    Text = "Você abre a maleta."
  },
  AvgDialog_145523_Content_7 = {
    Text = "A voz do Verme da Montanha ecoou de baixo dos pés. Desta vez, seu tom não continha apenas zombaria, mas também uma urgência reprimida por longos anos."
  },
  AvgDialog_145523_Content_70 = {
    Text = "a Maçã Dourada, o Espelho de Yata, a Pena de Ma'at, o Olho de Balor, o Fio das Moiras, a Coroa de Ariadne… e a própria Chave de Prata."
  },
  AvgDialog_145523_Content_71 = {
    Text = "Sete oferendas encontram seu lugar nos pedestais, e através dos sulcos antigos, uma luz dourada escura flui e pulsa novamente, conectando-se em um anel completo."
  },
  AvgDialog_145523_Content_72 = {
    Text = "<Shake:Haha... Finalmente... FINALMENTE!>"
  },
  AvgDialog_145523_Content_73 = {
    Text = "A Montanha terá Seu banquete. A Montanha gastará todo o Seu tesouro."
  },
  AvgDialog_145523_Content_74 = {
    Text = "A Montanha passou fome por isso por tanto, tanto tempo."
  },
  AvgDialog_145523_Content_75 = {
    Text = "William segurou aquela Chave única e a inseriu na fechadura."
  },
  AvgDialog_145523_Content_76 = {
    Text = "Em nome de Fengor —"
  },
  AvgDialog_145523_Content_77 = {
    Text = "<Red:Eu inicio este ritual.>"
  },
  AvgDialog_145523_Content_78 = {Text = "Clique."},
  AvgDialog_145523_Content_79 = {
    Text = "Com um som suave e agudo, todas as sete oferendas explodem em uma luz ofuscante."
  },
  AvgDialog_145523_Content_8 = {
    Text = "Todos os olhares se voltam para o altar, atraídos pela escrita misteriosa e densamente compactada que cobre sua superfície."
  },
  AvgDialog_145523_Content_80 = {
    Text = "O primeiro anel de luz se eleva acima do altar. Depois o segundo, e o terceiro. Os desejos adormecidos nos sete artefatos ressoam em harmonia, como sete rios correndo em direção a um único mar escuro."
  },
  AvgDialog_145523_Content_81 = {
    Text = "Se a Montanha tivesse mãos, arranharia o céu para agarrar aquele anel brilhante, ardendo de fome desesperada."
  },
  AvgDialog_145523_Content_82 = {
    Text = "<Shake:Este dia finalmente chegou!>"
  },
  AvgDialog_145523_Content_83 = {
    Text = "Arrancaria o anel dos céus e o pressionaria fundo contra Seu peito, enterrando-o em Sua carne inchada até que cada gota de seu poder fosse devorada."
  },
  AvgDialog_145523_Content_84 = {
    Text = "Você olha fixamente para o céu revolto. Quando o desejo da Montanha for concedido, o que será de suas vidas? Sua jornada simplesmente terminará neste deserto gelado?"
  },
  AvgDialog_145523_Content_85 = {
    Text = "Naquele instante, você vê o brilho do monóculo de William."
  },
  AvgDialog_145523_Content_86 = {
    Text = "Logo em seguida, o quarto anel de luz se acende."
  },
  AvgDialog_145523_Content_87 = {
    Text = "A rocha sólida sob seus pés range com um ronco baixo e pesado — um estremecimento que não pertence à pedra, mas à carne viva. Faint, clarões doentios de luz começam a sangrar pelas camadas de gelo que se partem abaixo."
  },
  AvgDialog_145523_Content_88 = {
    Text = "<Shake:...O que é isso?>"
  },
  AvgDialog_145523_Content_89 = {
    Text = "<Shake:Por que... minha força... está se esvaindo?>"
  },
  AvgDialog_145523_Content_9 = {
    Text = "Espere... esses padrões..."
  },
  AvgDialog_145523_Content_90 = {
    Text = "Este é o preço do ritual que você tanto desejava."
  },
  AvgDialog_145523_Content_91 = {
    Text = "Após pagar o preço, o que acontecerá com ele?"
  },
  AvgDialog_145523_Content_92 = {
    Text = "O ritual extrairá \"toda\" a Força da Oferta, então eu suponho que ela voltará ao que era antes de te encontrar, talvez ainda mais fraca."
  },
  AvgDialog_145523_Content_93 = {
    Text = "Então... fraco o suficiente para ser uma larva minúscula e miserável se contorcendo dentro de uma maçã podre? Uma que poderíamos esmagar com uma simples pitada?"
  },
  AvgDialog_145523_Content_94 = {
    Text = "<BigShake:Você me enganou! Seu miserável mentiroso!>"
  },
  AvgDialog_145523_Content_95 = {
    Text = "Eu prometi que iniciaria o ritual por completo, e você concordou em entregar <Italic:todas> as oferendas."
  },
  AvgDialog_145523_Content_96 = {
    Text = "Tudo o que você engoliu em seu ventre, toda a força vital desta montanha, será oferecido ao altar — sacrificado ao deus que esculpiu esta formação."
  },
  AvgDialog_145523_Content_97 = {
    Text = "O quinto halo se ergue."
  },
  AvgDialog_145523_Content_98 = {
    Text = "As pedras sob seus pés racham e se desprendem, revelando uma camada crua e pálida de carne convulsionando por baixo."
  },
  AvgDialog_145523_Content_99 = {
    Text = "Enormes camadas de neve desabam com um estrondo ensurdecedor, e o céu é engolido, pedaço por pedaço, por uma sombra inimaginável."
  },
  AvgDialog_145524_Content_1 = {
    Text = "Você… não se aproxime!"
  },
  AvgDialog_145524_Content_10 = {
    Text = "<Change>Ainda se lembra da sua missão?"
  },
  AvgDialog_145524_Content_11 = {
    Text = "<Small:Eliminar... o traidor... Eu preciso...>"
  },
  AvgDialog_145524_Content_12 = {
    Text = "O Caos nos olhos de Pollux foi gradualmente desaparecendo, substituído por um vazio, um vazio que só podia ser conduzido pela Voz na mente."
  },
  AvgDialog_145524_Content_13 = {
    Text = "Sim, é verdade, sou um traidor. Sou aquele que te traiu e fugiu."
  },
  AvgDialog_145524_Content_14 = {
    Text = "Mas agora, não vou mais partir."
  },
  AvgDialog_145524_Content_15 = {
    Text = "<Shake:Traidor, Castor...>"
  },
  AvgDialog_145524_Content_16 = {
    Text = "Ele estava perdido, queria resistir a algo, queria se agarrar a algo, mas a voz em sua mente lutava incessantemente."
  },
  AvgDialog_145524_Content_17 = {
    Text = "Pollux, você nos seguiu o tempo todo, então certamente também encontrou o Wendigo."
  },
  AvgDialog_145524_Content_18 = {
    Text = "Na Ilusão do Wendigo, o que você ouviu?"
  },
  AvgDialog_145524_Content_19 = {
    Text = "As pupilas de Pollux se dilataram instantaneamente, depois foram gradualmente se dispersando. Ele mergulhou em uma contemplação semelhante a Murmúrios em Sonho."
  },
  AvgDialog_145524_Content_2 = {
    Text = "Pollux arregalou os Olhos. Ele não entendia o que aquele fanático à sua frente estava pensando."
  },
  AvgDialog_145524_Content_20 = {
    Text = "Eu ouvi... alguém me Chamando..."
  },
  AvgDialog_145524_Content_21 = {
    Text = "Ele disse que poderíamos nos tornar cavaleiros extraordinários."
  },
  AvgDialog_145524_Content_22 = {
    Text = "Montávamos a cavalo, cruzávamos grandes montanhas, cruzávamos rios e mares, abatíamos dragões..."
  },
  AvgDialog_145524_Content_23 = {
    Text = "E então, então, no fim do sonho…"
  },
  AvgDialog_145524_Content_24 = {Text = "..."},
  AvgDialog_145524_Content_25 = {
    Text = "<BigShake:Não, não…!>"
  },
  AvgDialog_145524_Content_26 = {
    Text = "É muito doloroso, Juliette, <Shake:Salve-me, salve-me…>"
  },
  AvgDialog_145524_Content_27 = {
    Text = "<Shake:Eu sou… o nobre… o único… Filho Santo… Salve-me…<Small:Eu não consigo…>>"
  },
  AvgDialog_145524_Content_28 = {
    Text = "Não tem problema… Você não precisa se lembrar."
  },
  AvgDialog_145524_Content_29 = {
    Text = "O sofrimento insuportável, deixa que eu o carregue. Como quando éramos crianças."
  },
  AvgDialog_145524_Content_3 = {
    Text = "O rosto de Castor não demonstrava reverência pelos dogmas, nem medo diante da hostilidade."
  },
  AvgDialog_145524_Content_30 = {
    Text = "Afinal, eu sou o irmão mais velho."
  },
  AvgDialog_145524_Content_31 = {
    Text = "Castor abraçou Pollux, acalmando-o com uma voz suave como quem acalenta uma criança."
  },
  AvgDialog_145524_Content_32 = {
    Text = "A respiração de Pollux foi se acalmando, o rosto encostado no ombro de Castor, as pálpebras fechando-se aos poucos."
  },
  AvgDialog_145524_Content_33 = {
    Text = "<Shake:Castor…>"
  },
  AvgDialog_145524_Content_34 = {
    Text = "Sou eu, eu sou, Castor…"
  },
  AvgDialog_145524_Content_35 = {
    Text = "<Shake:Castor, Castor…>"
  },
  AvgDialog_145524_Content_36 = {
    Text = "<Shake:<Small:...Irmão?>>"
  },
  AvgDialog_145524_Content_37 = {
    Text = "As pupilas dispersas tornaram-se instantaneamente nítidas, a voz de Pollux era tão leve que quase se dispersava com o vento, mas ainda assim penetrou com precisão nos ouvidos de Castor."
  },
  AvgDialog_145524_Content_38 = {
    Text = "O Chamar que ele havia imaginado inúmeras vezes em sua mente finalmente ressoou novamente junto ao seu ouvido."
  },
  AvgDialog_145524_Content_39 = {Text = "Ah—"},
  AvgDialog_145524_Content_4 = {
    Text = "Ele apenas avançou, ultrapassando aquela lâmina, ultrapassando todos os obstáculos que deveriam existir, mas já não existiam."
  },
  AvgDialog_145524_Content_40 = {
    Text = "Ele queria chorar, queria gritar, queria rugir."
  },
  AvgDialog_145524_Content_41 = {
    Text = "Mesmo que ao seu redor houvesse apenas o vasto e infinito Campo de Neve, ele queria proclamar ao mundo inteiro, sem qualquer propósito, que seu irmão havia voltado."
  },
  AvgDialog_145524_Content_42 = {
    Text = "Mas ele não disse nada, como sempre, como quando Pollux o chamava de toco de madeira e Caraboo o chamava de idiota."
  },
  AvgDialog_145524_Content_43 = {
    Text = "<Shake:Pollux...>"
  },
  AvgDialog_145524_Content_44 = {
    Text = "— Naquele exato momento, no alto da montanha nevada — em algum lugar ainda mais alto, onde o topo não podia ser visto —"
  },
  AvgDialog_145524_Content_45 = {
    Text = "Um Olhar de Julgamento desceu sobre eles."
  },
  AvgDialog_145524_Content_46 = {
    Text = "<Change>Produto defeituoso."
  },
  AvgDialog_145524_Content_47 = {
    Text = "Castor agarrou o irmão com força—"
  },
  AvgDialog_145524_Content_48 = {
    Text = "Mas não adiantou. A luz brotou do peito de Pollux."
  },
  AvgDialog_145524_Content_49 = {
    Text = "A luz rasgou diretamente o peito dos dois, atravessou a capa surrada de Castor, atravessou as Asas que Castor estendera ao redor dos dois—"
  },
  AvgDialog_145524_Content_5 = {
    Text = "Ele abraçou Pollux com força contra seu peito."
  },
  AvgDialog_145524_Content_50 = {
    Text = "Como correntes de brancura pura, prendendo os dois firmemente, selando a promessa de que, a partir daquele momento, jamais haveria separação."
  },
  AvgDialog_145524_Content_51 = {
    Text = "Irmão… me perdoe…"
  },
  AvgDialog_145524_Content_52 = {
    Text = "Deixando essas últimas palavras, Pollux recostou-se no ombro de Castor e adormeceu profundamente."
  },
  AvgDialog_145524_Content_53 = {
    Text = "Assim… está bem… nunca mais nos separaremos…"
  },
  AvgDialog_145524_Content_54 = {
    Text = "Isso também é… um pequeno egoísmo meu…"
  },
  AvgDialog_145524_Content_55 = {
    Text = "Ele lançou um olhar para o alto da montanha, imaginando os companheiros da antiga expedição se ajudando mutuamente na escalada."
  },
  AvgDialog_145524_Content_56 = {
    Text = "Uma Mentira havia chegado ao fim, e essa jornada já não lhe pertencia."
  },
  AvgDialog_145524_Content_57 = {
    Text = "Trocando Uma Mentira por outra mentira…"
  },
  AvgDialog_145524_Content_58 = {
    Text = "Adeus… a todos… que a jornada de vocês… chegue à terra prometida…"
  },
  AvgDialog_145524_Content_59 = {
    Text = "Uma Pena negra desprendeu-se das Asas de Castor e foi arrastada pelo vento de Neve em direção ao alto."
  },
  AvgDialog_145524_Content_6 = {
    Text = "Assim como outrora no líquido amniótico."
  },
  AvgDialog_145524_Content_60 = {
    Text = "Que ela vá em nosso lugar até aquela terra pura e sem pecado que você desejou…"
  },
  AvgDialog_145524_Content_61 = {
    Text = "Uma fenda se abriu sob os pés dos dois, engolindo lentamente todo o peso nas neves do interior da montanha."
  },
  AvgDialog_145524_Content_62 = {
    Text = "Boa noite, Pollux."
  },
  AvgDialog_145524_Content_63 = {
    Text = "Vocês escalaram novos caminhos na montanha, reorganizando o pesado equipamento."
  },
  AvgDialog_145524_Content_64 = {
    Text = "Uma rajada de vento de Neve, Como Se dotada de vontade própria, redemoinhou pelo alto."
  },
  AvgDialog_145524_Content_65 = {
    Text = "Aquilo é..."
  },
  AvgDialog_145524_Content_66 = {
    Text = "Em meio ao vento de Neve, uma Pena de um negro absoluto desceu lentamente flutuando."
  },
  AvgDialog_145524_Content_67 = {
    Text = "Você levanta a mão, e ela pousa suavemente na sua palma."
  },
  AvgDialog_145524_Content_68 = {
    Text = "Como uma Bênção vindo de longe."
  },
  AvgDialog_145524_Content_69 = {
    Text = "Altitude -7000m-"
  },
  AvgDialog_145524_Content_7 = {
    Text = "Volte, Pollux. Como quando éramos crianças."
  },
  AvgDialog_145524_Content_8 = {
    Text = "A mente de Pollux estava repleta de confusão, repleta de incompreensão. Mas, por alguma razão, ele não conseguiu afastar aquele abraço caloroso."
  },
  AvgDialog_145524_Content_9 = {
    Text = "Uma repreensão severa ecoou subitamente junto ao seu ouvido."
  },
  AvgDialog_145525_Content_1 = {
    Text = "A caverna voltou a uma estranha calma, e todos, ainda sem se recuperar do susto, se entreolharam."
  },
  AvgDialog_145525_Content_10 = {
    Text = "Apenas há algo nesta montanha além da deusa, alguma presença que está tramando roubar os desejos de vocês."
  },
  AvgDialog_145525_Content_11 = {
    Text = "Pare de assustar a todos, Caraboo."
  },
  AvgDialog_145525_Content_12 = {
    Text = "Acreditem ou não, é com vocês. A deusa da montanha nevada consegue senti-la, está perto do nosso grupo, seguindo de perto..."
  },
  AvgDialog_145525_Content_13 = {
    Text = "Você não consegue discernir pelo tom de voz dela se estava apenas fingindo ou se realmente sentiu algo."
  },
  AvgDialog_145525_Content_14 = {
    Text = "A neve e o vento foram gradualmente cessando."
  },
  AvgDialog_145525_Content_15 = {
    Text = "Em meio a esse peso, vocês partem novamente."
  },
  AvgDialog_145525_Content_2 = {
    Text = "Estranho, já acompanhei equipes de alpinismo a esta altitude várias vezes, mas é a primeira vez que encontro algo assim..."
  },
  AvgDialog_145525_Content_3 = {
    Text = "Isso prova que os perigos desta montanha nevada não se limitam às temperaturas abaixo de trinta graus negativos e à falta de oxigênio nas grandes altitudes."
  },
  AvgDialog_145525_Content_4 = {
    Text = "Caraboo baixou a voz e foi descrevendo devagar, com um tom que gelava a espinha."
  },
  AvgDialog_145525_Content_5 = {
    Text = "A deusa da montanha nevada realmente existe."
  },
  AvgDialog_145525_Content_6 = {
    Text = "<Red:A deusa da montanha não lhe dá as boas-vindas. Ela não acolhe aqueles que carecem de devoção.>"
  },
  AvgDialog_145525_Content_7 = {
    Text = "O ar ficou tenso."
  },
  AvgDialog_145525_Content_8 = {
    Text = "Estava brincando com vocês! Não foram longe de acreditar de verdade!"
  },
  AvgDialog_145525_Content_9 = {
    Text = "Eu sou a deusa da montanha nevada mais bondosa que existe. Com minhas bênçãos, a montanha irá recebê-los e vocês chegarão ao cume."
  },
  AvgDialog_145526_Content_1 = {
    Text = "Dia da Partida do Ninho"
  },
  AvgDialog_145526_Content_10 = {
    Text = "Acabamos de resistir a um ataque, mas sua ofensiva não vai parar."
  },
  AvgDialog_145526_Content_11 = {
    Text = "Em um lugar perigoso como as montanhas, é inevitável que as pessoas demonstrem momentos de Frágil fraqueza…"
  },
  AvgDialog_145526_Content_12 = {
    Text = "Nesses momentos, é melhor enganar."
  },
  AvgDialog_145526_Content_13 = {
    Text = "Caraboo tirou uma Maçã de não se sabe onde, deu uma mordida com um estalo, com uma expressão de quem dizia \"essa frase não fui eu que disse\"."
  },
  AvgDialog_145526_Content_14 = {
    Text = "…Você não está errado em dizer isso."
  },
  AvgDialog_145526_Content_15 = {
    Text = "De qualquer forma, precisamos encontrá-lo e capturá-lo."
  },
  AvgDialog_145526_Content_16 = {
    Text = "Mas eles não deixam rastros ao caminhar sobre a Neve, como vamos…"
  },
  AvgDialog_145526_Content_17 = {
    Text = "Deixe comigo. Sou especialista em lidar com enganadores, não sou?"
  },
  AvgDialog_145526_Content_18 = {
    Text = "Veja, eles estão quase chegando."
  },
  AvgDialog_145526_Content_19 = {
    Text = "Caraboo aponta para o último cão-guia que você tem. Ele se agachou baixo, gemendo suavemente."
  },
  AvgDialog_145526_Content_2 = {Text = "Wendigo."},
  AvgDialog_145526_Content_20 = {
    Text = "Não se mexam, e não falem nada."
  },
  AvgDialog_145526_Content_21 = {
    Text = "Ela jogou para você a Maçã que havia mordido."
  },
  AvgDialog_145526_Content_22 = {
    Text = "Escondido no corte havia um pequeno bilhete: não importa o que eu diga a seguir, não acredite."
  },
  AvgDialog_145526_Content_23 = {
    Text = "Caraboo ficou quieta, fechou os olhos e os abriu novamente."
  },
  AvgDialog_145526_Content_24 = {
    Text = "Naquele instante, o olhar dela mudou. Distante, ansioso, nebuloso — sentimentos complexos transbordavam em seus pequenos olhos."
  },
  AvgDialog_145526_Content_25 = {
    Text = "<Shake:Tia Rosa, é você?>"
  },
  AvgDialog_145526_Content_26 = {
    Text = "<Shake:A senhora está fazendo torta de Maçã de novo? Eu sinto o cheiro.>"
  },
  AvgDialog_145526_Content_27 = {
    Text = "<Shake:Tia Rosa, nunca mais vou reclamar que a massa da torta de Maçã é grossa demais. Desde então, nunca mais comi uma torta de Maçã tão boa. Sinto falta daquele aroma tostado.>"
  },
  AvgDialog_145526_Content_28 = {
    Text = "<Shake:Tia Rosa. Vou até a senhora agora, me espere.>"
  },
  AvgDialog_145526_Content_29 = {
    Text = "Caraboo deu um passo à frente, cambaleando."
  },
  AvgDialog_145526_Content_3 = {
    Text = "William recitou palavra por palavra."
  },
  AvgDialog_145526_Content_30 = {
    Text = "Sobre a Neve, atrás de Caraboo, dois montes de neve com altura de um homem e meio surgiram abruptamente."
  },
  AvgDialog_145526_Content_31 = {
    Text = "Ele se lança em direção a Caraboo. No momento em que pula, ela se abaixa rapidamente."
  },
  AvgDialog_145526_Content_32 = {
    Text = "<Big:William, prepare-se!!>"
  },
  AvgDialog_145526_Content_4 = {
    Text = "<Italic:\"Seus pés são forjados em fogo — quando corre, a Neve Queima sob seus passos.\">"
  },
  AvgDialog_145526_Content_5 = {
    Text = "Consta no sétimo volume de \"Crônicas das Terras do Norte\": <Italic:Jamais responda àquele que Sussurra nas noites de inverno.>"
  },
  AvgDialog_145526_Content_6 = {
    Text = "<Italic:Responda uma vez, e ele Registrará seu nome; responda duas vezes, e ele reconhecerá sua sombra; responda pela terceira vez — e Você se tornará ele.>"
  },
  AvgDialog_145526_Content_7 = {
    Text = "Não podemos contorná-lo?"
  },
  AvgDialog_145526_Content_8 = {
    Text = "Não adianta. Desde Que o vento e a Neve se estendam, esse é o território onde o Wendigo vaga."
  },
  AvgDialog_145526_Content_9 = {
    Text = "Eles já foram humanos. Transformaram-se ao devorar seus semelhantes, e desde então seus lábios e dentes apodrecem, condenados à Fome eterna — nem devorar uma floresta inteira os saciaria."
  },
  AvgDialog_145527_Content_1 = {
    Text = "As Mochilas"
  },
  AvgDialog_145527_Content_10 = {Text = "Não."},
  AvgDialog_145527_Content_100 = {
    Text = "Ele aproximou seus próprios galhos do braseiro para acendê-los e então se juntou a vocês."
  },
  AvgDialog_145527_Content_101 = {
    Text = "As chamas se propagaram pelos galhos, e a luz Piscando iluminou um a um cada semblante erguido."
  },
  AvgDialog_145527_Content_102 = {
    Text = "No silêncio absoluto, Como Se fosse possível ouvir, vindo de não muito longe, o som grave de sutras sendo recitados, o tinido de sinos e o rufar de tambores."
  },
  AvgDialog_145527_Content_103 = {
    Text = "Gritem Lha Gyalo e então os lancem na fogueira."
  },
  AvgDialog_145527_Content_104 = {
    Text = "Uma voz rouca mas firme Reverberou no ar rarefeito, e os galhos nas mãos foram caindo um a um na fogueira ao som dos gritos."
  },
  AvgDialog_145527_Content_105 = {
    Text = "Agradecemos ao Deus da Montanha por tolerar nossa ousadia ao adentrar seu domínio sagrado."
  },
  AvgDialog_145527_Content_106 = {
    Text = "Galhos de pinheiro e cipreste crepitam no fogo, enviando fumaça cinza subindo em linha reta antes de ser despedaçada pelos ventos fortes."
  },
  AvgDialog_145527_Content_107 = {
    Text = "E você farejou no ar um presságio sombrio."
  },
  AvgDialog_145527_Content_108 = {Text = "..."},
  AvgDialog_145527_Content_109 = {
    Text = "Muito bem, já expliquei a todos os riscos desta escalada e os planos de emergência."
  },
  AvgDialog_145527_Content_11 = {
    Text = "Ei!!! Por quê!!!"
  },
  AvgDialog_145527_Content_110 = {
    Text = "Durante a última semana, todos já se adaptaram a se mover usando luvas, botas de montanha e óculos de neve, além de praticar e dominar o uso de cordas e grampos de neve."
  },
  AvgDialog_145527_Content_111 = {
    Text = "Com base no monitoramento rigoroso dos últimos dias, os próximos 5 a 7 dias representam a janela meteorológica mais favorável para a escalada — é um bom momento para partir."
  },
  AvgDialog_145527_Content_112 = {
    Text = "Por favor, verifiquem os mapas de rota, alimentos, combustível, cilindros de oxigênio, kits médicos e outros suprimentos que cada um está carregando."
  },
  AvgDialog_145527_Content_113 = {
    Text = "Reforço mais uma vez: durante a escalada, é obrigatório <Yellow:obedecer completamente às ordens do guia>, e, exceto pelos membros que se retirarem antecipadamente, os demais <Yellow:estão estritamente proibidos de agir fora do grupo>."
  },
  AvgDialog_145527_Content_114 = {
    Text = "Se estiverem prontos, vamos partir!"
  },
  AvgDialog_145527_Content_115 = {Text = "..."},
  AvgDialog_145527_Content_116 = {Text = "..."},
  AvgDialog_145527_Content_117 = {
    Text = "Vocês avançaram pela montanha por apenas meio dia quando o tempo claro subitamente se fechou em nuvens densas."
  },
  AvgDialog_145527_Content_118 = {
    Text = "O vento e a neve se intensificam abruptamente; até mesmo as cumeeiras das montanhas mal se distinguem, e os cães-guia choramingam, relutantes em continuar."
  },
  AvgDialog_145527_Content_119 = {
    Text = "Estranho, de acordo com nossos resultados de monitoramento, condições climáticas anormais não deveriam surgir tão rapidamente."
  },
  AvgDialog_145527_Content_12 = {
    Text = "Aqueles dois também não acabaram de entrar?"
  },
  AvgDialog_145527_Content_120 = {
    Text = "Já encontrou uma situação parecida antes?"
  },
  AvgDialog_145527_Content_121 = {
    Text = "Nunca. Mesmo quando o monitoramento apresenta desvios, eles geralmente ocorrem três dias após o resultado previsto."
  },
  AvgDialog_145527_Content_122 = {
    Text = "<Shake:Uma nevasca antinatural… parece… <Yellow:a montanha nos rejeitando>.>"
  },
  AvgDialog_145527_Content_123 = {
    Text = "Impossível! Como pode ser, se eu, a grande deusa da montanha, estou bem aqui?"
  },
  AvgDialog_145527_Content_124 = {
    Text = "Não precisa se preocupar demais; às vezes também encontramos tempestades de neve inesperadas ao descer."
  },
  AvgDialog_145527_Content_125 = {
    Text = "Há um abrigo de emergência por perto, onde há até alguns suprimentos extras. Vamos descansar um pouco, esperar a nevasca parar e depois nos reorganizamos para partir novamente."
  },
  AvgDialog_145527_Content_126 = {
    Text = "Então o que estamos esperando? Vamos logo!"
  },
  AvgDialog_145527_Content_13 = {
    Text = "Caraboo, com o rosto cheio de indignação, estendeu o dedo apontando para você e para William."
  },
  AvgDialog_145527_Content_14 = {
    Text = "É simples. Aqueles dois são adultos, capazes de cuidar de si mesmos."
  },
  AvgDialog_145527_Content_15 = {
    Text = "Alpinismo não é brincadeira de criança, menina."
  },
  AvgDialog_145527_Content_16 = {
    Text = "Aqui, você pode se declarar pai, mãe, deusa da Neve ou até a Vontade Suprema, tanto faz."
  },
  AvgDialog_145527_Content_17 = {
    Text = "Mas quando chegar a picos acima de cinco mil metros de altitude, todas as mentiras serão expostas pela neve, pelo vento e pelo mal de altitude."
  },
  AvgDialog_145527_Content_18 = {
    Text = "Mas eu tenho dinheiro, tenho <Italic:MUITO> dinheiro!"
  },
  AvgDialog_145527_Content_19 = {
    Text = "Você é uma criança, quanto pode ter——"
  },
  AvgDialog_145527_Content_2 = {
    Text = "Sob a orientação de Naraka, você e os membros da equipe de escalada se apresentam uns aos outros."
  },
  AvgDialog_145527_Content_20 = {Text = "<Big:!>"},
  AvgDialog_145527_Content_21 = {
    Text = "As palavras de Naraka foram interrompidas abruptamente."
  },
  AvgDialog_145527_Content_22 = {
    Text = "A garota tira uma pesada bolsa de tecido, pega um grande punhado de moedas de ouro e as deixa cair de volta na bolsa com um tinido em cascata. Ela fica com apenas uma, girando e fazendo-a dançar entre os dedos."
  },
  AvgDialog_145527_Content_23 = {
    Text = "Já disse que sou uma fada, como poderia me faltar algo tão insignificante quanto dinheiro, um mero Objeto externo!"
  },
  AvgDialog_145527_Content_24 = {
    Text = "<Small:Mas você não acabou de dizer que era uma deusa...?>"
  },
  AvgDialog_145527_Content_25 = {
    Text = "Tanto faz, quem se importa!"
  },
  AvgDialog_145527_Content_26 = {
    Text = "Caraboo jogou a moeda de ouro ao acaso, e Naraka se inclinou rapidamente para pegá-la, tropeçando e quase caindo na Neve."
  },
  AvgDialog_145527_Content_27 = {
    Text = "Ele segurou a moeda com as mãos e a mordeu, transbordando de alegria."
  },
  AvgDialog_145527_Content_28 = {
    Text = "<Shake:É de verdade...!>"
  },
  AvgDialog_145527_Content_29 = {
    Text = "Humph, as moedas de ouro de uma fada, como poderiam ser falsas?"
  },
  AvgDialog_145527_Content_3 = {
    Text = "Tinct, uma cantora misteriosa e distante, que afirma querer encontrar sua irmã."
  },
  AvgDialog_145527_Content_30 = {
    Text = "Enfim, posso me juntar à equipe de alpinismo agora, certo?"
  },
  AvgDialog_145527_Content_31 = {
    Text = "<Shake:<Small:De fato, deixar uma criança se juntar à equipe de alpinismo seria um pouco irresponsável quanto à sua segurança…>>"
  },
  AvgDialog_145527_Content_32 = {
    Text = "<BigShake:Hm?>"
  },
  AvgDialog_145527_Content_33 = {
    Text = "Mas, dito isso, nossa equipe de alpinismo tem vasta Experiência em escalada e suprimentos mais do que suficientes, proteger Você é <Big:mais do que suficiente>!"
  },
  AvgDialog_145527_Content_34 = {
    Text = "Mas deixa eu avisar logo: se Você decidir voltar no meio do caminho, deixaremos recursos suficientes para Você descer a montanha, mas a taxa de guia cobrada <Big:não será reembolsada>, tá bom."
  },
  AvgDialog_145527_Content_35 = {
    Text = "Sim, sim, uma fada vai se preocupar com esse dinheirinho?"
  },
  AvgDialog_145527_Content_36 = {
    Text = "<Shake:<Small:Que estranho, ela não estava mendigando com apresentações agora há pouco?>>"
  },
  AvgDialog_145527_Content_37 = {
    Text = "Não pense que não estou ouvindo!"
  },
  AvgDialog_145527_Content_38 = {
    Text = "Já disse, aquilo era Manutenção! O que a deusa recebe é a sinceridade de todos, entende?"
  },
  AvgDialog_145527_Content_39 = {
    Text = "<Shake:<Small:Quando não é necessário, a audição também é muito boa…>>"
  },
  AvgDialog_145527_Content_4 = {
    Text = "Evelyn, arqueóloga, que veio para realizar pesquisas científicas mesmo neste mundo pós-apocalíptico."
  },
  AvgDialog_145527_Content_40 = {
    Text = "<BigShake:ESSE EU TAMBÉM OUVI!>"
  },
  AvgDialog_145527_Content_41 = {
    Text = "Seu grupo faz um balanço dos suprimentos, e a conversa logo deriva para o ritual."
  },
  AvgDialog_145527_Content_42 = {
    Text = "Vocês realmente acreditam que no topo da montanha existe uma deusa capaz de realizar qualquer desejo?"
  },
  AvgDialog_145527_Content_43 = {
    Text = "William pergunta com ar de quem não tem interesse no assunto."
  },
  AvgDialog_145527_Content_44 = {
    Text = "Pelo menos as pessoas locais acreditam. Por causa da última expedição de alpinismo."
  },
  AvgDialog_145527_Content_45 = {
    Text = "A última expedição de alpinismo?"
  },
  AvgDialog_145527_Content_46 = {
    Text = "Sim. Desde que a notícia da Deusa da Montanha se espalhou, o Continente do Norte Final tornou-se uma terra inteiramente dominada pela busca de desejos, com toda uma sociedade construída em torno da escalada. Aquela equipe de escalada era a mais disciplinada e bem treinada de todas as que já tentaram; eles tinham as melhores chances de alcançar o cume."
  },
  AvgDialog_145527_Content_47 = {
    Text = "Sete deles partiram. Mas um a um, foram morrendo durante a escalada."
  },
  AvgDialog_145527_Content_48 = {
    Text = "Alguém saiu da tenda no meio da noite, descalço, e caminhou para dentro de uma tempestade de neve; alguém cortou sua própria corda de segurança e saltou de um penhasco de gelo;"
  },
  AvgDialog_145527_Content_49 = {
    Text = "E ainda houve alguém que desapareceu por vários dias, mas no final foi encontrado congelado à frente do grupo —"
  },
  AvgDialog_145527_Content_5 = {
    Text = "Enquanto vocês discutiam os planos para a Partida no dia seguinte, uma cabeça branca surgiu de repente na entrada do acampamento."
  },
  AvgDialog_145527_Content_50 = {
    Text = "Como se, mesmo depois de morto, ele continuasse escalando a montanha."
  },
  AvgDialog_145527_Content_51 = {
    Text = "Os movimentos de todos ao fazer o inventário dos suprimentos desaceleraram involuntariamente."
  },
  AvgDialog_145527_Content_52 = {
    Text = "No final, apenas uma pessoa voltou viva ao sopé da montanha."
  },
  AvgDialog_145527_Content_53 = {
    Text = "Porém, também não se pode dizer que ele realmente \"voltou vivo\"."
  },
  AvgDialog_145527_Content_54 = {
    Text = "O que você quer dizer?"
  },
  AvgDialog_145527_Content_55 = {
    Text = "Seus dez dedos estavam todos apodrecidos pelo frio, e seus ouvidos estavam entupidos de Neve misturada com Sangue. Não importava o que os outros perguntassem, ele apenas repetia as mesmas poucas frases."
  },
  AvgDialog_145527_Content_56 = {
    Text = "Naraka baixou a voz, imitando o tom de Murmúrios em Sonho do sobrevivente."
  },
  AvgDialog_145527_Content_57 = {
    Text = "<Shake:\"A lenda é verdadeira. O desejo no topo da montanha é verdadeiro.\">"
  },
  AvgDialog_145527_Content_58 = {
    Text = "<Shake:<Red:\"Tape os ouvidos, não ouça.\">>"
  },
  AvgDialog_145527_Content_59 = {
    Text = "<Shake:\"Quem ouvir o canto será seduzido, Devorado… e então subirá aos céus, transformando-se na <Red:lua>.\">"
  },
  AvgDialog_145527_Content_6 = {
    Text = "Ei~ Este é o grupo de alpinismo de Naraka?"
  },
  AvgDialog_145527_Content_60 = {
    Text = "E então, e agora?"
  },
  AvgDialog_145527_Content_61 = {
    Text = "Depois disso…"
  },
  AvgDialog_145527_Content_62 = {
    Text = "Naraka esboçou um sorriso estranho, entre irônico e divertido."
  },
  AvgDialog_145527_Content_63 = {
    Text = "Os moradores locais acreditavam que eles deviam ter profanado a deusa da montanha. Com medo de que esses forasteiros trouxessem a ira da deusa sobre suas aldeias…"
  },
  AvgDialog_145527_Content_64 = {
    Text = "Então, numa noite sem lua e com vento forte, o jogaram numa fenda de gelo sem fundo."
  },
  AvgDialog_145527_Content_65 = {
    Text = "E esse é o fim da história?"
  },
  AvgDialog_145527_Content_66 = {Text = "Não."},
  AvgDialog_145527_Content_67 = {
    Text = "Desde então, a cada lua cheia, quem passa por aquela fenda de gelo ainda ouve alguém cantando lá Abaixo."
  },
  AvgDialog_145527_Content_68 = {
    Text = "E assim todos souberam que ele dizia a verdade. Que havia algo na montanha."
  },
  AvgDialog_145527_Content_69 = {
    Text = "Naraka baixou a cabeça novamente e foi enrolando a corda em espiral dentro d'As Mochilas, Como Se o que havia dito fosse apenas um assunto antigo e sem importância."
  },
  AvgDialog_145527_Content_7 = {
    Text = "Está me procurando?"
  },
  AvgDialog_145527_Content_70 = {
    Text = "No breve silêncio, Apenas o vento varria a tenda, emitindo um gemido longo e indistinto."
  },
  AvgDialog_145527_Content_71 = {
    Text = "Também ouvi dizer que, durante a escalada, eles ouviram o canto das sereias."
  },
  AvgDialog_145527_Content_72 = {
    Text = "Você está falando bobagem de novo. As sereias são criaturas do mar, como poderiam aparecer numa montanha?"
  },
  AvgDialog_145527_Content_73 = {
    Text = "Caraboo franziu os lábios com descontentamento e soltou um leve resmungo."
  },
  AvgDialog_145527_Content_74 = {
    Text = "Se no mar há monstros que cantam, por que não poderia haver na montanha?"
  },
  AvgDialog_145527_Content_75 = {
    Text = "Acredite se quiser. Quando ouvir o canto, lembre-se de tampar os ouvidos."
  },
  AvgDialog_145527_Content_76 = {
    Text = "Quando Você ia perguntar mais, percebeu que Caraboo já havia se virado e entrado na cabana, sem intenção de continuar a discussão."
  },
  AvgDialog_145527_Content_77 = {Text = "..."},
  AvgDialog_145527_Content_78 = {
    Text = "Sete dias depois"
  },
  AvgDialog_145527_Content_79 = {
    Text = "O treino de hoje termina aqui. Amanhã é o dia oficial da escalada."
  },
  AvgDialog_145527_Content_8 = {
    Text = "Hehe, ouvi dizer que você é o melhor guia de montanhismo de todo o povo Sherpa!"
  },
  AvgDialog_145527_Content_80 = {
    Text = "Caraboo avançou de repente e barrou Naraka, que se preparava para partir."
  },
  AvgDialog_145527_Content_81 = {
    Text = "Não vai realizar <Yellow:o Ritual Lhasang>?"
  },
  AvgDialog_145527_Content_82 = {
    Text = "O Ritual Lhasang? O que é isso?"
  },
  AvgDialog_145527_Content_83 = {
    Text = "Antes de cada escalada, dez em cada dez Sherpas realizam esse ritual de Oração. Você não tem nenhum respeito pelas Divindades?"
  },
  AvgDialog_145527_Content_84 = {
    Text = "Naraka deu uma palmada na testa."
  },
  AvgDialog_145527_Content_85 = {
    Text = "<Yellow:Ah, com tantas coisas acontecendo, saiu da minha cabeça.>"
  },
  AvgDialog_145527_Content_86 = {
    Text = "Como você pode esquecer algo assim?"
  },
  AvgDialog_145527_Content_87 = {
    Text = "Não tem problema, amanhã cedo faço um simples e rápido."
  },
  AvgDialog_145527_Content_88 = {Text = "..."},
  AvgDialog_145527_Content_89 = {
    Text = "Você movimenta os ombros doloridos e abre a Porta do quarto; no corredor já flutua um tênue fio de fumaça."
  },
  AvgDialog_145527_Content_9 = {
    Text = "Pela Bênção da deusa da Neve, você pode me levar junto na escalada?"
  },
  AvgDialog_145527_Content_90 = {
    Text = "William está parado a alguns passos de distância diante de um espelho de bronze, alisando uma a uma as dobras da gola."
  },
  AvgDialog_145527_Content_91 = {
    Text = "Bom dia, Guardião."
  },
  AvgDialog_145527_Content_92 = {
    Text = "Você fareja o ar. O ar carrega o aroma de madeira queimando e ervas, com uma fragrância fresca e gelada sobreposta por baixo."
  },
  AvgDialog_145527_Content_93 = {
    Text = "Ao abrir o portão, o frio e o denso aroma de incenso invadem juntos."
  },
  AvgDialog_145527_Content_94 = {
    Text = "No espaço aberto do pátio, um pequeno braseiro de sang está aceso. Uma fumaça azul-esbranquiçada sobe entre galhos de pinheiro e cipreste e ervas aromáticas, subindo em linha reta em direção ao céu cinza-azulado."
  },
  AvgDialog_145527_Content_95 = {
    Text = "Os Sherpas consideram as montanhas como divindades, e no Monte Everest habita a própria deusa Mãe do Mundo."
  },
  AvgDialog_145527_Content_96 = {
    Text = "Antes da primeira escalada oficial, os Sherpas erguem altares, içam bandeiras de oração, recitam sutras e realizam o ritual de \"queima de sang\" ao lado do altar, deixando a fumaça levar as oferendas e as Orações até as divindades."
  },
  AvgDialog_145527_Content_97 = {
    Text = "O ritual de bênção é bastante elaborado; a cerimônia formal pode durar de três a quatro horas."
  },
  AvgDialog_145527_Content_98 = {
    Text = "Naraka retirou um feixe de galhos de pinheiro e cipreste de um saco de tecido e distribuiu um para cada pessoa."
  },
  AvgDialog_145527_Content_99 = {
    Text = "Ergam bem alto e aproximem."
  },
  AvgDialog_145528_Content_1 = {
    Text = "Você se lança sobre ele, abraçando firmemente a cintura de Castor por trás. Castor ainda se debate, suas cordas vocais Quase se Rasgando de tanto gritar no vento e na Neve."
  },
  AvgDialog_145528_Content_10 = {
    Text = "Evelyn se aproximou passo a passo. Ela se agachou, ficando cara a cara com o jovem que você e William seguravam na neve."
  },
  AvgDialog_145528_Content_11 = {
    Text = "Castor, ouça-me. Eu também já acreditei que o Wendigo era uma criatura que existia apenas nas lendas."
  },
  AvgDialog_145528_Content_12 = {
    Text = "Mas há pouco… ouvi."
  },
  AvgDialog_145528_Content_13 = {
    Text = "Ouvi… meu marido me chamando."
  },
  AvgDialog_145528_Content_14 = {
    Text = "Desde o dia em que ele desapareceu, ouço esse chamado todos os dias, mas nunca foi tão claro, tão real…"
  },
  AvgDialog_145528_Content_15 = {
    Text = "A voz de Evelyn fica levemente rouca por um momento."
  },
  AvgDialog_145528_Content_16 = {
    Text = "<Shake:Mas Castor… você sabe…>"
  },
  AvgDialog_145528_Content_17 = {
    Text = "Já se passaram mais de noventa dias desde que meu marido desapareceu na montanha nevada, há muito tempo além do prazo ideal de resgate."
  },
  AvgDialog_145528_Content_18 = {
    Text = "Na melhor das hipóteses, não faço mais do que encontrar seus ossos em algum caminho da montanha."
  },
  AvgDialog_145528_Content_19 = {
    Text = "Ele não estará vivo… aqui. Seu irmão, muito menos."
  },
  AvgDialog_145528_Content_2 = {
    Text = "Castor, não é ele."
  },
  AvgDialog_145528_Content_20 = {
    Text = "Precisamos continuar subindo, até chegar ao cume da montanha."
  },
  AvgDialog_145528_Content_21 = {
    Text = "Essa é a única chance que temos de ter um Reencontro com eles."
  },
  AvgDialog_145528_Content_22 = {
    Text = "Castor, acalmado pelas palavras de Evelyn, foi aos poucos se serenando."
  },
  AvgDialog_145528_Content_23 = {
    Text = "Você tem razão… não haveria uma cela de confinamento na montanha nevada… ele não estaria em um lugar assim."
  },
  AvgDialog_145528_Content_24 = {
    Text = "Vou persistir… até ter um Reencontro com ele."
  },
  AvgDialog_145528_Content_25 = {
    Text = "Atrás de vocês, alguém segurou um piolet e bateu duas vezes nas rochas com um som seco."
  },
  AvgDialog_145528_Content_26 = {
    Text = "Se todos já estiverem com as emoções estabilizadas, precisamos nos preparar para enfrentar a verdadeira ameaça."
  },
  AvgDialog_145528_Content_27 = {
    Text = "<Yellow:Wendigo>."
  },
  AvgDialog_145528_Content_3 = {
    Text = "<Shake:Como Você sabe que não é ele?! Você nem o conhece!>"
  },
  AvgDialog_145528_Content_4 = {
    Text = "Nenhum de vocês o conhece! Apenas eu o conheço, eu conheço a voz dele!! Fui eu quem o abandonou lá!"
  },
  AvgDialog_145528_Content_5 = {
    Text = "É a primeira vez que ele levanta a voz para William. Então ele se assusta com a própria voz."
  },
  AvgDialog_145528_Content_6 = {
    Text = "Castor, acalme-se, isso é um <Yellow:Wendigo>."
  },
  AvgDialog_145528_Content_7 = {
    Text = "O Wendigo, monstro das montanhas… escava a sombra mais profunda do seu coração…"
  },
  AvgDialog_145528_Content_8 = {
    Text = "Depois, ele toma emprestada a voz de quem você mais sente falta, seduzindo os Perdidos a cair em sua armadilha."
  },
  AvgDialog_145528_Content_9 = {
    Text = "<Shake:Não, com que certeza você diz——>"
  },
  AvgDialog_145529_Content_1 = {
    Text = "Outra Primavera"
  },
  AvgDialog_145529_Content_10 = {
    Text = "<Shake:Este lugar... onde estou?>"
  },
  AvgDialog_145529_Content_100 = {
    Text = "Uma vida tranquila, ou um ancião amoroso."
  },
  AvgDialog_145529_Content_101 = {
    Text = "Até mesmo aquele coelhinho."
  },
  AvgDialog_145529_Content_102 = {
    Text = "O coelho selvagem do campo virou-se, seus dois Olhos redondos e brilhantes encontrando os dela."
  },
  AvgDialog_145529_Content_103 = {
    Text = "Depois se virou, chutou a terra com as patas traseiras e se enfiou na toca de barro."
  },
  AvgDialog_145529_Content_11 = {
    Text = "Com base nas últimas palavras de Caraboo, nós estamos agora em Posição normal nas entranhas da montanha."
  },
  AvgDialog_145529_Content_12 = {
    Text = "A prioridade agora é encontrar um Caminho para Escapar."
  },
  AvgDialog_145529_Content_13 = {
    Text = "Eu também nunca estive neste lugar, então temo não poder servir de guia para vocês."
  },
  AvgDialog_145529_Content_14 = {
    Text = "Não se preocupe, já passamos por momentos muito mais difíceis do que este."
  },
  AvgDialog_145529_Content_15 = {
    Text = "%player%, o que é isso na sua mão?"
  },
  AvgDialog_145529_Content_16 = {
    Text = "Hm, isso é… o Fio de Arachne…"
  },
  AvgDialog_145529_Content_17 = {
    Text = "Sem saber quando, esse Fio se enrolou silenciosamente no seu mindinho."
  },
  AvgDialog_145529_Content_18 = {
    Text = "O Fio, que antes estava em Silêncio e era suave, agora brilhava e fluía com um lustre hipnótico, sua ponta se estendendo naturalmente para a escuridão ao longe."
  },
  AvgDialog_145529_Content_19 = {
    Text = "Seria isso uma orientação do destino? Siga-o e veja aonde leva."
  },
  AvgDialog_145529_Content_2 = {
    Text = "escuridão. escuridão sem fim."
  },
  AvgDialog_145529_Content_20 = {
    Text = "Caraboo seguiu o Fio, sem saber por quanto tempo avançou. Na ponta do Fio, surgiu um raio de luz."
  },
  AvgDialog_145529_Content_21 = {Text = "Luz…?"},
  AvgDialog_145529_Content_22 = {
    Text = "As luzes e sombras mudaram de repente."
  },
  AvgDialog_145529_Content_23 = {
    Text = "Aqui é...?"
  },
  AvgDialog_145529_Content_24 = {
    Text = "Ei, Caraboo, devagar!"
  },
  AvgDialog_145529_Content_25 = {
    Text = "Olha, Tia Rosa, tem um coelho ali!"
  },
  AvgDialog_145529_Content_26 = {
    Text = "Ah, ela correu para uma toca!"
  },
  AvgDialog_145529_Content_27 = {
    Text = "Ela esperou do dia até a noite, mas o coelho nunca apareceu."
  },
  AvgDialog_145529_Content_28 = {
    Text = "Tia Rosa, eu vi com meus próprios olhos! O coelho foi direto para este buraco!"
  },
  AvgDialog_145529_Content_29 = {
    Text = "Tia Rosa acariciou gentilmente o cabelo de Caraboo."
  },
  AvgDialog_145529_Content_3 = {
    Text = "Dói, dói, dói… Onde estou?"
  },
  AvgDialog_145529_Content_30 = {
    Text = "Criança tola, os coelhos não são animais tão simples assim."
  },
  AvgDialog_145529_Content_31 = {
    Text = "As tocas sob esses campos são como uma grande e emaranhada teia de túneis. Todos se conectam."
  },
  AvgDialog_145529_Content_32 = {
    Text = "Aquele coelhinho branco que você estava de olho já fugiu por alguma outra toca faz tempo."
  },
  AvgDialog_145529_Content_33 = {
    Text = "Então o que fazemos?"
  },
  AvgDialog_145529_Content_34 = {
    Text = "Nada, pequena Caraboo."
  },
  AvgDialog_145529_Content_35 = {
    Text = "Nós plantamos nos campos, Regamos, Esperamos que amadureçam, colhemos e desfrutamos dos frutos que a Divindade nos concede."
  },
  AvgDialog_145529_Content_36 = {
    Text = "Mas, e se eu quiser aquele coelho?"
  },
  AvgDialog_145529_Content_37 = {
    Text = "Querida pequena Caraboo, não devemos cobiçar aquele coelho. Se você quiser comer carne, podemos ir ao mercado e trocá-la por frutas e legumes."
  },
  AvgDialog_145529_Content_38 = {
    Text = "Mas, e se eu ainda quiser aquele coelho?"
  },
  AvgDialog_145529_Content_39 = {
    Text = "<Red:Por quê... Por que não posso ter aquele coelho?>"
  },
  AvgDialog_145529_Content_4 = {
    Text = "Sem precisar perguntar, ela já sabia. Estava nas entranhas do verme."
  },
  AvgDialog_145529_Content_40 = {Text = "..."},
  AvgDialog_145529_Content_41 = {Text = "..."},
  AvgDialog_145529_Content_42 = {
    Text = "Por que agora, estou vendo memórias da minha infância…?"
  },
  AvgDialog_145529_Content_43 = {
    Text = "Calma. Talvez seja porque andei na escuridão por tempo demais, estou tendo Ilusões."
  },
  AvgDialog_145529_Content_44 = {
    Text = "Isso não é uma Ilusão, sabia?"
  },
  AvgDialog_145529_Content_45 = {
    Text = "<Shake:Uaaah! Um fantasma!!>"
  },
  AvgDialog_145529_Content_46 = {
    Text = "Você ainda se lembra de um dos sete artefatos sagrados, o Fio do destino? O que você está vendo é a Trajetória do destino."
  },
  AvgDialog_145529_Content_47 = {
    Text = "A seguir, a Trajetória do destino revelará para você outra possibilidade, e também seu ponto de divergência."
  },
  AvgDialog_145529_Content_48 = {
    Text = "O que isso tem a ver com o fato de eu estar presa no estômago de um monstro agora?"
  },
  AvgDialog_145529_Content_49 = {
    Text = "Porque esse é o seu desejo. Os desejos são o rastilho, conduzindo cada pessoa ao seu fim predestinado."
  },
  AvgDialog_145529_Content_5 = {
    Text = "Que droga, atraiu alguém para dentro e acabou sendo devorada ela mesma."
  },
  AvgDialog_145529_Content_50 = {
    Text = "Chega de adivinhações! Você poderia usar um pouco desse fôlego para me dizer como sair daqui?! <BigShake:EI—>"
  },
  AvgDialog_145529_Content_51 = {
    Text = "A sombra desapareceu silenciosamente."
  },
  AvgDialog_145529_Content_52 = {
    Text = "Ora, que mesquinharia. Não tem jeito, de qualquer forma não há outro Caminho dentro da cavidade abdominal do verme, vou continuar em frente."
  },
  AvgDialog_145529_Content_53 = {Text = "..."},
  AvgDialog_145529_Content_54 = {Text = "..."},
  AvgDialog_145529_Content_55 = {
    Text = "Tia Rosa! Não se apresse, já vou ajudá-la!"
  },
  AvgDialog_145529_Content_56 = {
    Text = "Essa é… eu?"
  },
  AvgDialog_145529_Content_57 = {
    Text = "Boa menina, a titia Apenas veio ver como você está."
  },
  AvgDialog_145529_Content_58 = {
    Text = "Titia, a senhora tem dificuldade para andar, não precisa ficar vindo à plantação. Assim que eu terminar de colher essa manjericão, volto com a senhora para alimentar os coelhos."
  },
  AvgDialog_145529_Content_59 = {
    Text = "Você já viu? A Alface teve uma ninhada ontem à noite! Tantos coelhinhos, todos de cores diferentes!"
  },
  AvgDialog_145529_Content_6 = {
    Text = "Espera, o que é isso? Um Fio…?"
  },
  AvgDialog_145529_Content_60 = {
    Text = "Nossa Caraboo já cresceu e virou mocinha."
  },
  AvgDialog_145529_Content_61 = {
    Text = "Titia, o que a senhora está dizendo. Esse trabalho na roça, eu já conseguia fazer sozinha quando tinha treze anos."
  },
  AvgDialog_145529_Content_62 = {
    Text = "A decisão mais acertada que a titia tomou nessa vida foi trazer você dos seus pais para ficar comigo."
  },
  AvgDialog_145529_Content_63 = {
    Text = "Quando você me disse que seu pai bêbado havia te batido, fiquei hesitante a noite toda, e então, na madrugada, embarquei no primeiro trem disponível."
  },
  AvgDialog_145529_Content_64 = {
    Text = "Quase briguei com seu pai antes de conseguir te tirar de lá."
  },
  AvgDialog_145529_Content_65 = {
    Text = "Desde então, já se passaram quase dez anos, não é?"
  },
  AvgDialog_145529_Content_66 = {
    Text = "Agora, sem você, com estas pernas minhas, não sei como viveria sozinho—"
  },
  AvgDialog_145529_Content_67 = {
    Text = "Ah— Ah—"
  },
  AvgDialog_145529_Content_68 = {
    Text = "Isso é... aquela noite— aquela noite— uma outra possibilidade—"
  },
  AvgDialog_145529_Content_69 = {
    Text = "Aquela noite, a noite em que ela encontrou o \"Verme da Montanha\", a noite em que ela decidiu escapar do destino com suas próprias mãos."
  },
  AvgDialog_145529_Content_7 = {
    Text = "Um Fio cristalino e brilhante emergiu da escuridão distante, pairando diante de Caraboo."
  },
  AvgDialog_145529_Content_70 = {
    Text = "Pertencente ao mundo real, a noite que ela vivenciou."
  },
  AvgDialog_145529_Content_71 = {
    Text = "Ao som do crepitar das chamas da lareira, ela ficou parada diante do leito do pai embriagado, hesitando por um longo, longo tempo."
  },
  AvgDialog_145529_Content_72 = {
    Text = "Vá, faça o que você sempre quis fazer."
  },
  AvgDialog_145529_Content_73 = {
    Text = "Ela ergueu a faca—"
  },
  AvgDialog_145529_Content_74 = {
    Text = "Isso mesmo, exatamente assim."
  },
  AvgDialog_145529_Content_75 = {
    Text = "Mate-o, e todos poderão ser felizes."
  },
  AvgDialog_145529_Content_76 = {
    Text = "Então, lentamente, lentamente, abaixou-a."
  },
  AvgDialog_145529_Content_77 = {
    Text = "Desculpe, ainda não consigo fazer isso."
  },
  AvgDialog_145529_Content_78 = {
    Text = "Vá embora, desde que fuja bem longe daqui, não precisará mais suportar essa dor."
  },
  AvgDialog_145529_Content_79 = {
    Text = "Criaturinha inútil."
  },
  AvgDialog_145529_Content_8 = {
    Text = "Tanto faz, tanto faz, é melhor você não estar me enganando!"
  },
  AvgDialog_145529_Content_80 = {
    Text = "Tudo bem, o que me interessa em você é outra coisa."
  },
  AvgDialog_145529_Content_81 = {
    Text = "Vamos, com essa sua língua astuta, ainda conseguiremos o tesouro mais precioso."
  },
  AvgDialog_145529_Content_82 = {
    Text = "Na manhã seguinte, me escondi furtivamente na palha de uma carroça de bois e me infiltrei na cidade mais próxima."
  },
  AvgDialog_145529_Content_83 = {
    Text = "Depois, usando uma Identidade e documentos falsificados, embarquei no trem rumo ao Oriente."
  },
  AvgDialog_145529_Content_84 = {
    Text = "Desde então, tive muitas identidades: sobrinha do chefe de trem, amiga do Guarda, Fada do culto, deusa da montanha nevada..."
  },
  AvgDialog_145529_Content_85 = {
    Text = "Deixei todo o passado para trás, abandonado naquela noite de neve em que fugi."
  },
  AvgDialog_145529_Content_86 = {
    Text = "Depois, muito, muito tempo depois, foi por um conterrâneo encontrado por acaso no campo de batalha que soube—"
  },
  AvgDialog_145529_Content_87 = {
    Text = "O senhor Hans?"
  },
  AvgDialog_145529_Content_88 = {
    Text = "Num dia de grande nevada, ele bebeu até ficar completamente embriagado."
  },
  AvgDialog_145529_Content_89 = {
    Text = "O fogo da lareira foi apagado pela neve derretida que escorria pelo teto. Normalmente, era a filhinha dele quem ia acendê-lo novamente."
  },
  AvgDialog_145529_Content_9 = {
    Text = "Você acorda do torpor, e diante de seus olhos há um vazio suave, úmido e opressivo."
  },
  AvgDialog_145529_Content_90 = {
    Text = "Apenas naquele dia, a filhinha não estava em Nosso Lar, sem que se soubesse o porquê."
  },
  AvgDialog_145529_Content_91 = {
    Text = "Ele morreu de frio naquela noite de neve."
  },
  AvgDialog_145529_Content_92 = {
    Text = "Depois disso, também nunca mais vimos aquela menina."
  },
  AvgDialog_145529_Content_93 = {
    Text = "Ah, sim, grande Fada, por que a senhora pergunta isso de repente? Minha Bênção — pode me dar agora?"
  },
  AvgDialog_145529_Content_94 = {
    Text = "Caraboo pegou um punhado cheio de balas e entregou ao jovem à sua frente."
  },
  AvgDialog_145529_Content_95 = {
    Text = "Pela Fada nas alturas, uma por dia — quando terminar estas balas abençoadas, o ferimento na sua perna estará curado."
  },
  AvgDialog_145529_Content_96 = {
    Text = "Mesmo sabendo, no fundo do coração, que nenhuma bala poderia curar as pernas já amputadas do jovem."
  },
  AvgDialog_145529_Content_97 = {Text = "..."},
  AvgDialog_145529_Content_98 = {Text = "..."},
  AvgDialog_145529_Content_99 = {
    Text = "Que ridículo, que verdadeiramente ridículo. Afinal, naquela noite, Desde Que eu não fizesse nada, poderia ter obtido a felicidade que tanto ansiava."
  },
  AvgDialog_145530_Content_1 = {
    Text = "O Longo Sonho"
  },
  AvgDialog_145530_Content_10 = {
    Text = "Sendo assim, eu te apoio."
  },
  AvgDialog_145530_Content_11 = {
    Text = "Eu te apoio para recuperar o Você mesmo que foi descartado."
  },
  AvgDialog_145530_Content_12 = {
    Text = "Afinal, nós sempre fomos as pessoas mais egoístas."
  },
  AvgDialog_145530_Content_13 = {
    Text = "A montanha de Neve morreu."
  },
  AvgDialog_145530_Content_14 = {
    Text = "<Shake:Acabou…>"
  },
  AvgDialog_145530_Content_15 = {
    Text = "No centro da montanha de Neve, abriu-se uma ferida chocante, desde o topo da verme até a extremidade de sua cavidade abdominal."
  },
  AvgDialog_145530_Content_16 = {
    Text = "O corpo da verme, ao longo daquela ferida, lenta, lentamente desabou para os dois lados."
  },
  AvgDialog_145530_Content_17 = {
    Text = "Vocês também, junto com o colapso do cume, caíram em queda livre."
  },
  AvgDialog_145530_Content_18 = {
    Text = "<Shake:Cuidado, está desabando!>"
  },
  AvgDialog_145530_Content_19 = {
    Text = "No som do vento durante a queda, Você, de surpresa, ouviu um Sussurro."
  },
  AvgDialog_145530_Content_2 = {
    Text = "Você já decidiu?"
  },
  AvgDialog_145530_Content_20 = {
    Text = "Ainda não acabou."
  },
  AvgDialog_145530_Content_21 = {
    Text = "Caraboo estendeu a mão."
  },
  AvgDialog_145530_Content_22 = {
    Text = "Em O Semblante dela coberto de lágrimas, surgiu um sorriso despreocupado."
  },
  AvgDialog_145530_Content_23 = {
    Text = "Então, na gravidade que vocês não podiam controlar, os sete halos de luz se acenderam."
  },
  AvgDialog_145530_Content_24 = {
    Text = "O que morreu… foi apenas a montanha nevada… o ritual… ainda está em funcionamento!"
  },
  AvgDialog_145530_Content_25 = {
    Text = "Naquele instante, o céu e a terra pareciam ter perdido todo o som."
  },
  AvgDialog_145530_Content_26 = {
    Text = "Você apenas viu seus lábios se moverem levemente, pronunciando palavras que só começariam a reverberar pelo mundo muitos segundos depois."
  },
  AvgDialog_145530_Content_27 = {
    Text = "Meu desejo é que não haja mais nenhuma mentira neste mundo."
  },
  AvgDialog_145530_Content_28 = {
    Text = "No instante em que suas palavras saíram, o mundo diante de seus olhos se desfez."
  },
  AvgDialog_145530_Content_29 = {
    Text = "Cinzas prateadas e abundantes caíam do alto distante, de forma extremamente leve e lenta."
  },
  AvgDialog_145530_Content_3 = {
    Text = "Sim, já tomei minha decisão."
  },
  AvgDialog_145530_Content_30 = {
    Text = "Foi um colapso silencioso, uma queda lenta, o Fim de um Sonho eterno e ancestral."
  },
  AvgDialog_145530_Content_31 = {Text = "Os picos."},
  AvgDialog_145530_Content_32 = {
    Text = "A Neve acumulada."
  },
  AvgDialog_145530_Content_33 = {Text = "O céu."},
  AvgDialog_145530_Content_34 = {Text = "A Terra."},
  AvgDialog_145530_Content_35 = {
    Text = "Tudo o que existia, como Uma Mentira desmascarada, se transformou em Nada."
  },
  AvgDialog_145530_Content_36 = {
    Text = "......Por quê?"
  },
  AvgDialog_145530_Content_37 = {
    Text = "Um conhecimento que Você não deveria possuir, junto com memórias distantes, cravou-se em sua mente como Espinhos."
  },
  AvgDialog_145530_Content_38 = {
    Text = "Este navio é um sonho, mas quando o véu da mentira se levanta..."
  },
  AvgDialog_145530_Content_39 = {
    Text = "O mundo inteiro também é o sonho de alguém, apenas este sonho é maior, mais ilusório e mais distante..."
  },
  AvgDialog_145530_Content_4 = {
    Text = "Isso é Uma Mentira, é traição."
  },
  AvgDialog_145530_Content_40 = {
    Text = "Até o sol, a lua e as estrelas são fruto de Sua imaginação, apenas os seres que se entrelaçam com Seu espírito podem..."
  },
  AvgDialog_145530_Content_41 = {
    Text = "<Italic:O mundo inteiro é uma enorme mentira.>"
  },
  AvgDialog_145530_Content_42 = {
    Text = "Acompanhado por essa percepção, o colapso se acelerou. Do céu começou a cair uma chuva densa e prateada."
  },
  AvgDialog_145530_Content_43 = {
    Text = "A chuva cai sobre as águas. Os fragmentos que outrora foram o \"mundo\" se transformaram em gotas prateadas, afundando lentamente em direção ao Mar Profundo sem fim."
  },
  AvgDialog_145530_Content_44 = {
    Text = "E Você estava dentro daquelas águas."
  },
  AvgDialog_145530_Content_45 = {
    Text = "Afundando, afundando."
  },
  AvgDialog_145530_Content_46 = {
    Text = "Até que o longo Sonho ilusório chegasse ao fim, e Você abrisse os olhos novamente."
  },
  AvgDialog_145530_Content_47 = {
    Text = "Encarando a realidade real deste mundo."
  },
  AvgDialog_145530_Content_48 = {
    Text = "No fundo mais profundo e mais sombrio do Mar Profundo."
  },
  AvgDialog_145530_Content_49 = {
    Text = "O grandioso Reino Divino, já extinto, finalmente revelou sua verdadeira forma."
  },
  AvgDialog_145530_Content_5 = {
    Text = "Todos cuidaram de Você com carinho, e eles também têm desejos que querem realizar."
  },
  AvgDialog_145530_Content_6 = {
    Text = "Mas a chance de fazer um desejo, é Apenas uma."
  },
  AvgDialog_145530_Content_7 = {
    Text = "Mesmo assim, Você ainda quer fazer <Yellow:\"aquele\"> desejo?"
  },
  AvgDialog_145530_Content_8 = {
    Text = "Não há desejo mais importante do que este."
  },
  AvgDialog_145530_Content_9 = {
    Text = "A sombra sorriu."
  },
  AvgDialog_145531_Content_1 = {Text = "Boa Noite"},
  AvgDialog_145531_Content_10 = {
    Text = "Atrás dela, alguém abriu silenciosamente um Olho, espiando a silhueta dela se afastar."
  },
  AvgDialog_145531_Content_11 = {
    Text = "Tinct seguiu lentamente o caminho de onde vinha a canção, enquanto fragmentos de gelo e solo congelado emitiam sons suaves sob seus sapatos de sola fina."
  },
  AvgDialog_145531_Content_12 = {
    Text = "(Este lugar é… o lago de gelo de durante o dia…)"
  },
  AvgDialog_145531_Content_13 = {
    Text = "(Mas há algo um pouco diferente…)"
  },
  AvgDialog_145531_Content_14 = {
    Text = "As águas do lago, congeladas durante o dia, Despertaram por alguma razão desconhecida."
  },
  AvgDialog_145531_Content_15 = {
    Text = "A superfície da água, serena e sem ondas, Abriu os olhos para o céu como um espelho cristalino, refletindo silenciosamente a lua eterna."
  },
  AvgDialog_145531_Content_16 = {
    Text = "Faint, é você?"
  },
  AvgDialog_145531_Content_17 = {
    Text = "(A água do lago... estranhamente cristalina...)"
  },
  AvgDialog_145531_Content_18 = {
    Text = "Ela olhou para o fundo do lago."
  },
  AvgDialog_145531_Content_19 = {
    Text = "A água do lago era tão profunda que não se via o fundo, Como Se atravessasse a Terra, levando a algum lugar ainda mais distante do que as Estrelas."
  },
  AvgDialog_145531_Content_2 = {
    Text = "À meia-noite, Tinct é acordada por um som distante e fraco."
  },
  AvgDialog_145531_Content_20 = {
    Text = "Uma canção flutua no vento. Rouca, antiga, como se tivesse atravessado uma passagem de tempo inimaginavelmente longa e ainda não tivesse cessado."
  },
  AvgDialog_145531_Content_21 = {
    Text = "<Italic:Lá—lá lá~ lá~ ♪>"
  },
  AvgDialog_145531_Content_22 = {
    Text = "Tinct fechou os olhos e respirou fundo."
  },
  AvgDialog_145531_Content_23 = {
    Text = "(Uma melodia familiar... uma essência... saudosa...)"
  },
  AvgDialog_145531_Content_24 = {
    Text = "A textura da voz fazia pensar em leitos de rios secos, em camadas de arenito erodidas por cem mil anos de vento, nos gritos das florestas ancestrais comprimidas em carvão pelo peso das eras geológicas."
  },
  AvgDialog_145531_Content_25 = {
    Text = "(Isso parece ser... uma melodia... da Estrela Abandonada...)"
  },
  AvgDialog_145531_Content_26 = {
    Text = "As memórias de mil anos atrás foram gradualmente Revivendo, e Ela começou a tentar cantarolar, tentando acompanhar aquele canto errante e inconstante."
  },
  AvgDialog_145531_Content_27 = {
    Text = "<Shake:Lá lá~ lá lá lá~♪>"
  },
  AvgDialog_145531_Content_28 = {
    Text = "Ela sentiu, Ela capturou."
  },
  AvgDialog_145531_Content_29 = {
    Text = "Um júbilo sincero aflorou em O Semblante dela."
  },
  AvgDialog_145531_Content_3 = {
    Text = "(Lá fora... isso é... uma canção?)"
  },
  AvgDialog_145531_Content_30 = {
    Text = "Sua extensão vocal se expandiu, para cima. Uma voz cristalina como a de um rouxinol, Enrolando-se de forma melodiosa e leve sobre aquela melodia de base rouca."
  },
  AvgDialog_145531_Content_31 = {
    Text = "As duas vozes começaram a se puxar, a se entrelaçar, a se aproximar."
  },
  AvgDialog_145531_Content_32 = {
    Text = "<Change>Lá lá lá lá lá lá~♪"
  },
  AvgDialog_145531_Content_33 = {
    Text = "A camada de gelo foi se fechando pouco a pouco, e nas profundezas do lago, inúmeros rostos pálidos ergueram a cabeça seguindo o canto."
  },
  AvgDialog_145531_Content_34 = {
    Text = "Mas Tinct não percebia nada disso."
  },
  AvgDialog_145531_Content_35 = {
    Text = "Apenas o canto. O canto atravessou Os Presos pela Neve e as terras congeladas, atravessou o universo estrelado, atravessou as eras eternas, transformando-se em algo que cada pessoa deveria considerar uma existência eterna."
  },
  AvgDialog_145531_Content_36 = {
    Text = "É verdade, não devo mais me enganar…"
  },
  AvgDialog_145531_Content_37 = {
    Text = "Eu já… não quero mais procurar… A esperança não existe em lugar nenhum… Ela está na minha memória, e apenas na minha memória…"
  },
  AvgDialog_145531_Content_38 = {
    Text = "O Amigo antigo nas águas estendeu a mão para ela."
  },
  AvgDialog_145531_Content_39 = {
    Text = "Uma voz envelhecida e gentil a chamava, chamando pelo seu nome de mil anos atrás."
  },
  AvgDialog_145531_Content_4 = {
    Text = "O som é extremamente suave, emergindo de alguma profundeza insondável através de incontáveis camadas de gelo, neve e rocha."
  },
  AvgDialog_145531_Content_41 = {
    Text = "Devo desistir…"
  },
  AvgDialog_145531_Content_42 = {
    Text = "Esta jornada é longa demais, longa demais. Já faz muito tempo que estou… extremamente exausta…"
  },
  AvgDialog_145531_Content_43 = {
    Text = "O chamado vibrava contra seus ossos, presenteando-a com o consolo que tanto ansiava. Sua angústia sem destino, sua tristeza sem para onde ir, finalmente foram completamente compreendidas e acolhidas por uma presença."
  },
  AvgDialog_145531_Content_44 = {
    Text = "<Shake:Abraça-me, Faint… ó sombra da minha memória… Abraça-me, como antes…>"
  },
  AvgDialog_145531_Content_45 = {
    Text = "<Shake:Concede-me a Ning que tanto anseio…>"
  },
  AvgDialog_145531_Content_46 = {
    Text = "Ela, suavemente, suavemente, adentrou as águas tranquilas do lago."
  },
  AvgDialog_145531_Content_47 = {
    Text = "O lago não agita uma única ondulação. Como uma língua fria, lambe ternamente sua cintura, seus ombros, sua garganta."
  },
  AvgDialog_145531_Content_48 = {
    Text = "<Change>Lá lá…"
  },
  AvgDialog_145531_Content_49 = {
    Text = "Ela ainda cantava."
  },
  AvgDialog_145531_Content_5 = {
    Text = "É rouca e lenta, cada sílaba soa como areia varrida pelo vento rolando pela terra. Teimosa e incessante, segue como um rio subterrâneo que flui para sempre."
  },
  AvgDialog_145531_Content_50 = {
    Text = "Sua silhueta, seu corpo, sua existência foram se dissipando junto com o canto, derretendo e se espalhando na luz da lua."
  },
  AvgDialog_145531_Content_51 = {
    Text = "Um pensamento, um pensamento tão tênue que Quase era impossível de capturar, naquele instante, subiu misteriosamente à consciência de Tinct."
  },
  AvgDialog_145531_Content_52 = {
    Text = "(Estranho… hoje… deveria ser lua nova…)"
  },
  AvgDialog_145531_Content_53 = {
    Text = "E então — a superfície do lago subitamente colapsou para dentro."
  },
  AvgDialog_145531_Content_54 = {
    Text = "Nenhum respingo, nenhum grito. Apenas o canto ecoando e vagando."
  },
  AvgDialog_145531_Content_55 = {
    Text = "A lua no céu havia desaparecido, sem que se soubesse quando."
  },
  AvgDialog_145531_Content_56 = {
    Text = "Restava apenas o lago ondulante com a lua, refletindo com nitidez a sombra de Tinct."
  },
  AvgDialog_145531_Content_57 = {Text = "..."},
  AvgDialog_145531_Content_58 = {
    Text = "Na manhã seguinte."
  },
  AvgDialog_145531_Content_59 = {
    Text = "Alguém viu Tinct?"
  },
  AvgDialog_145531_Content_6 = {
    Text = "(Tão distante, e ao mesmo tempo tão familiar…)"
  },
  AvgDialog_145531_Content_60 = {
    Text = "Todos balançaram a cabeça."
  },
  AvgDialog_145531_Content_61 = {
    Text = "Hmm… ontem à noite ouvi um barulho perto de mim, mas logo adormeci."
  },
  AvgDialog_145531_Content_62 = {
    Text = "Procurei em todas as tendas, ela não está em nenhuma."
  },
  AvgDialog_145531_Content_63 = {
    Text = "Talvez tenha desistido no meio do caminho?"
  },
  AvgDialog_145531_Content_64 = {
    Text = "Ontem, quando ela estava à beira do lago de gelo, seu Estado já parecia muito estranho…"
  },
  AvgDialog_145531_Content_65 = {
    Text = "Evelyn murmurou Impaciente."
  },
  AvgDialog_145531_Content_66 = {
    Text = "Ela saiu sem sequer levar um cilindro de oxigênio."
  },
  AvgDialog_145531_Content_67 = {
    Text = "Este é um pico a seis mil metros de altitude — cada pessoa deve, e só pode, ser responsável pela própria Vida."
  },
  AvgDialog_145531_Content_68 = {
    Text = "Pelo menos… pelo menos vamos dar uma olhada à beira do lago de gelo."
  },
  AvgDialog_145531_Content_69 = {Text = "Vamos ir?"},
  AvgDialog_145531_Content_7 = {
    Text = "Os companheiros de equipe nas tendas ao redor haviam mergulhado num sono profundo, exaustos pela escalada do dia. Até os cães-guia roncavam."
  },
  AvgDialog_145531_Content_70 = {
    Text = "Você deseja ir em busca de Tinct, sem querer abandonar nenhuma possibilidade. Mas Você também sabe que cada escolha que faz carrega a vida de toda a equipe."
  },
  AvgDialog_145531_Content_71 = {
    Text = "Vamos, a altitude daqui e do lago de gelo é Quase a mesma, e o tempo de ida e volta está dentro de um intervalo controlável."
  },
  AvgDialog_145531_Content_72 = {
    Text = "A única coisa a observar são as feras selvagens ao longo do caminho."
  },
  AvgDialog_145531_Content_8 = {
    Text = "Hora de sair."
  },
  AvgDialog_145531_Content_9 = {
    Text = "Ela abriu o saco de dormir, levantou a lona da tenda e saiu lentamente."
  },
  AvgDialog_145532_Content_1 = {
    Text = "Ele Olhou para Trás"
  },
  AvgDialog_145532_Content_10 = {
    Text = "Depois, foi a vez de Evelyn. William ficou na retaguarda, com O Olhar sereno e concentrado guardando a todos."
  },
  AvgDialog_145532_Content_11 = {Text = "Espere…"},
  AvgDialog_145532_Content_12 = {
    Text = "O Olhar de Evelyn se fixou em um pedaço de corda na parede rochosa partida."
  },
  AvgDialog_145532_Content_13 = {
    Text = "Isso é… o mosquetão deles! Eu reconheço essa marca!"
  },
  AvgDialog_145532_Content_14 = {
    Text = "O ângulo formado pela cornija de Neve! O ângulo formado pela cornija de Neve cria uma zona segura, impedindo que a Neve a cubra!"
  },
  AvgDialog_145532_Content_15 = {
    Text = "Você olha para baixo na direção de Evelyn. Apenas um Olhar, e a Ilusão de queda já faz sua cabeça girar."
  },
  AvgDialog_145532_Content_16 = {
    Text = "Preciso ir encontrá-lo!"
  },
  AvgDialog_145532_Content_17 = {
    Text = "Evelyn soltou o mosquetão e começou a descer lentamente."
  },
  AvgDialog_145532_Content_18 = {
    Text = "É muito perigoso, Evelyn!"
  },
  AvgDialog_145532_Content_19 = {
    Text = "Não tem problema, foi para isso que vim! Se falarmos em perigo, a escalada em si já é perigosa o suficiente!"
  },
  AvgDialog_145532_Content_2 = {
    Text = "Quatro pessoas, como quatro dados, suspensas no tabuleiro chamado penhasco de gelo."
  },
  AvgDialog_145532_Content_20 = {
    Text = "Não se preocupem comigo! Eu alcanço vocês em breve!"
  },
  AvgDialog_145532_Content_21 = {
    Text = "Nas profundezas da fenda de gelo, havia algo que a atraía, Como Se fosse uma tentação."
  },
  AvgDialog_145532_Content_22 = {
    Text = "Evelyn, Você não pode——!"
  },
  AvgDialog_145532_Content_23 = {
    Text = "Você estende a mão até o seu mosquetão, respira fundo e se prepara para a queda."
  },
  AvgDialog_145532_Content_24 = {
    Text = "%player%..."
  },
  AvgDialog_145532_Content_25 = {
    Text = "William segura sua mão e balança a cabeça levemente."
  },
  AvgDialog_145532_Content_26 = {
    Text = "Ninguém sabe se Helot vai voltar. Não podemos ficar todos suspensos no ar."
  },
  AvgDialog_145532_Content_27 = {
    Text = "Olhe para cima."
  },
  AvgDialog_145532_Content_28 = {
    Text = "Caraboo já havia escalado a última parede de gelo."
  },
  AvgDialog_145532_Content_29 = {
    Text = "Para cima está o fim desta jornada, a terra prometida onde todos os desejos se realizam."
  },
  AvgDialog_145532_Content_3 = {
    Text = "Cada um agarrava firmemente a corda de segurança em suas mãos, buscando desesperadamente o próximo ponto de apoio."
  },
  AvgDialog_145532_Content_30 = {
    Text = "Para baixo, está o abismo da escuridão sem fundo."
  },
  AvgDialog_145532_Content_31 = {
    Text = "Mas não podemos perder mais companheiros——!"
  },
  AvgDialog_145532_Content_32 = {Text = "Eu sei."},
  AvgDialog_145532_Content_33 = {
    Text = "Então, deixa comigo."
  },
  AvgDialog_145532_Content_34 = {
    Text = "Antes mesmo de as palavras fazerem sentido, William desafixa o arnês e mergulha direto no abismo."
  },
  AvgDialog_145532_Content_35 = {
    Text = "A parede de gelo vertical que exigiu cada grama de suas forças para escalar é vencida em questão de segundos na descida. Em um piscar de olhos, William e Evelyn se reduziram a dois pequenos pontos distantes, engolidos pelas estreitas mandíbulas da fenda."
  },
  AvgDialog_145532_Content_36 = {
    Text = "Você observa Evelyn e William descerem cada vez mais, em direção à fenda de gelo."
  },
  AvgDialog_145532_Content_37 = {
    Text = "Depois, Você ergue a cabeça e crava o próximo pino na rocha."
  },
  AvgDialog_145532_Content_38 = {Text = "..."},
  AvgDialog_145532_Content_39 = {Text = "..."},
  AvgDialog_145532_Content_4 = {
    Text = "Acima há uma rocha, precisamos escalá-la."
  },
  AvgDialog_145532_Content_40 = {
    Text = "A fenda de gelo não tinha fundo visível, e quando pisaram em terra firme novamente, era uma escuridão total, sem ver a própria mão."
  },
  AvgDialog_145532_Content_41 = {
    Text = "Espere, Evelyn…"
  },
  AvgDialog_145532_Content_42 = {
    Text = "A luz da lanterna da cabeça da Dança se projetava para a frente."
  },
  AvgDialog_145532_Content_43 = {
    Text = "Abaixo da fenda de gelo parecia haver uma caverna de estalactites, com um ar diferente dos outros lugares. Frio, úmido, e o vento carregava um estranho odor inexplicável."
  },
  AvgDialog_145532_Content_44 = {
    Text = "Cuidado com o chão, há uma depressão aqui…"
  },
  AvgDialog_145532_Content_45 = {
    Text = "As palavras ficaram presas em sua garganta, transformando-se em uma inalação brusca de ar frio."
  },
  AvgDialog_145532_Content_46 = {
    Text = "Onde a luz varria, havia dezenas de ossos já saponificados."
  },
  AvgDialog_145532_Content_47 = {
    Text = "Eles mantinham a postura em que haviam caído — alguns encolhidos, outros abraçados —, cobrindo o chão em silêncio, camada sobre camada."
  },
  AvgDialog_145532_Content_48 = {
    Text = "Esses são… os uniformes da expedição Green."
  },
  AvgDialog_145532_Content_49 = {
    Text = "Todos eles estão aqui."
  },
  AvgDialog_145532_Content_5 = {
    Text = "Vocês se movem com cautela ao redor da pedra enorme, verificando se o chão sob os pés é rocha sólida ou neve solta."
  },
  AvgDialog_145532_Content_50 = {
    Text = "Após um longo silêncio, Evelyn se virou e olhou fixamente nos olhos de William."
  },
  AvgDialog_145532_Content_51 = {
    Text = "Parece que aqui também não há muitas informações de que vocês precisam, certo?"
  },
  AvgDialog_145532_Content_52 = {
    Text = "Sendo assim, você pode me deixar ficar aqui sozinha por um momento? Quero procurar e ver se ele está aqui."
  },
  AvgDialog_145532_Content_53 = {
    Text = "Se possível, gostaria de conversar um pouco com ele."
  },
  AvgDialog_145532_Content_54 = {
    Text = "Esses corpos podem carregar bactérias perigosas…"
  },
  AvgDialog_145532_Content_55 = {
    Text = "Evelyn expressou sua determinação com o olhar."
  },
  AvgDialog_145532_Content_56 = {Text = "Entendido."},
  AvgDialog_145532_Content_57 = {
    Text = "Mas prometa-me que você vai sair daqui em segurança."
  },
  AvgDialog_145532_Content_58 = {
    Text = "Sim, está bem, eu prometo. Vou concluir a escalada até o topo."
  },
  AvgDialog_145532_Content_59 = {
    Text = "William assentiu com a cabeça."
  },
  AvgDialog_145532_Content_6 = {
    Text = "Depois de finalmente contorná-la, antes mesmo de recuperarem o fôlego, uma fissura sem fundo aparece sob os pés."
  },
  AvgDialog_145532_Content_60 = {
    Text = "Vou esperar por você na entrada da caverna."
  },
  AvgDialog_145532_Content_61 = {Text = "..."},
  AvgDialog_145532_Content_62 = {Text = "..."},
  AvgDialog_145532_Content_63 = {
    Text = "Passou muito, muito tempo — tanto que William Quase não conseguia conter o impulso de entrar para investigar — quando, finalmente, o som de roupas roçando ecoou de dentro da caverna."
  },
  AvgDialog_145532_Content_64 = {
    Text = "Então Evelyn apareceu."
  },
  AvgDialog_145532_Content_65 = {
    Text = "Você… o encontrou?"
  },
  AvgDialog_145532_Content_66 = {
    Text = "Sim, encontrei."
  },
  AvgDialog_145532_Content_67 = {
    Text = "Evelyn assentiu, com um tom de voz estável, sem qualquer variação perceptível."
  },
  AvgDialog_145532_Content_68 = {
    Text = "Meus pêsames."
  },
  AvgDialog_145532_Content_69 = {
    Text = "Não, obrigado."
  },
  AvgDialog_145532_Content_7 = {
    Text = "Cuidado, não olhe para baixo."
  },
  AvgDialog_145532_Content_70 = {
    Text = "Evelyn deu uma risada suave."
  },
  AvgDialog_145532_Content_71 = {
    Text = "Eu já sabia que seria assim."
  },
  AvgDialog_145532_Content_72 = {
    Text = "Você também, não é?"
  },
  AvgDialog_145532_Content_73 = {
    Text = "Você também está procurando por alguém que nunca vai voltar."
  },
  AvgDialog_145532_Content_74 = {
    Text = "É sempre assim."
  },
  AvgDialog_145532_Content_75 = {
    Text = "No começo, sempre há esperança, pensando que talvez ele volte amanhã."
  },
  AvgDialog_145532_Content_76 = {
    Text = "Então um amanhã…"
  },
  AvgDialog_145532_Content_77 = {
    Text = "…e mais um amanhã."
  },
  AvgDialog_145532_Content_78 = {
    Text = "A esperança vai se tornando cada vez mais tênue, e a pedra no fundo do coração vai pesando cada vez mais."
  },
  AvgDialog_145532_Content_79 = {
    Text = "Ela vai caindo, caindo, dia após dia."
  },
  AvgDialog_145532_Content_8 = {
    Text = "Você segue logo atrás de Naraka, segurando a corda com toda a força para cruzar a fissura."
  },
  AvgDialog_145532_Content_80 = {
    Text = "Até que um dia, você percebe que não pensa mais nisso."
  },
  AvgDialog_145532_Content_81 = {
    Text = "Você come, dorme, trabalha, viaja, conversa com as pessoas, ri como de costume…"
  },
  AvgDialog_145532_Content_82 = {
    Text = "E então, por muito, muito tempo, não menciona mais."
  },
  AvgDialog_145532_Content_83 = {
    Text = "A voz de Evelyn mudou levemente de tom."
  },
  AvgDialog_145532_Content_84 = {
    Text = "Mas você sabe que não esqueceu, nunca esqueceu."
  },
  AvgDialog_145532_Content_85 = {
    Text = "Você jamais vai esquecer."
  },
  AvgDialog_145532_Content_86 = {
    Text = "Basta uma lenda, uma faísca, e ela começa a Queimar…"
  },
  AvgDialog_145532_Content_87 = {
    Text = "Ela vai te engolir por inteiro..."
  },
  AvgDialog_145532_Content_88 = {
    Text = "...e te reduzir a cinzas."
  },
  AvgDialog_145532_Content_89 = {
    Text = "William ergueu a cabeça abruptamente, encarando O Olhar de Evelyn."
  },
  AvgDialog_145532_Content_9 = {
    Text = "Ao passar o olhar rapidamente, você avista apenas uma escuridão aterrorizante dentro da fissura, sem saber onde ela termina."
  },
  AvgDialog_145532_Content_90 = {
    Text = "A outra apenas o encarou de volta com suavidade; o que preenchia aqueles Olhos era chamas ou vazio, ele não conseguia distinguir através do reflexo dos óculos de proteção."
  },
  AvgDialog_145532_Content_91 = {
    Text = "Pare de ficar distraído, vamos. Eu prometi a você que subiria ao topo com vocês, não foi?"
  },
  AvgDialog_145532_Content_92 = {
    Text = "Por algum motivo, William sempre achou que, apesar de seus olhares se cruzarem, o alvo da conversa da outra pessoa parecia não ser ele."
  },
  AvgDialog_145532_Content_93 = {
    Text = "Evelyn não esperou mais por ele. Ela se virou e caminhou para fora da caverna, abaixando-se para verificar a corda de tração, com movimentos tão ágeis Como Se o Solilóquio de pouco antes jamais tivesse acontecido."
  },
  AvgDialog_145532_Content_94 = {
    Text = "William fica parado no lugar, as palavras que não conseguia dizer presas em sua garganta. Ele a observa sumir na distância, depois olha para a boca escura e aberta da caverna atrás dele."
  },
  AvgDialog_145532_Content_95 = {
    Text = "Ele não encontrou motivo para ficar mais um segundo. Ele recolheu O Olhar e, em Silêncio, seguiu os passos dela."
  },
  AvgDialog_145534_Content_1 = {
    Text = "A farsa acabou. Agora, a montanha de neve vai engolir vocês."
  },
  AvgDialog_145534_Content_10 = {
    Text = "O cume da montanha se Rasgou subitamente pelo centro, abrindo-se cada vez mais, transformando-se numa enorme garganta que cortava verticalmente os céus e a Terra; saliva escarlate escorria pelos dentes presas em camadas, despejando-se como chuva."
  },
  AvgDialog_145534_Content_11 = {
    Text = "A enorme garganta se fechou de repente—"
  },
  AvgDialog_145534_Content_12 = {
    Text = "Antes que a multidão pudesse soltar o primeiro grito, já havia sido engolida em seu ventre sem fundo."
  },
  AvgDialog_145534_Content_13 = {
    Text = "A Terra cessou seu Tremor; da Neve que caía suavemente, ergueu-se um pequeno chapéu pontudo."
  },
  AvgDialog_145534_Content_14 = {
    Text = "Caraboo sacudiu a Neve acumulada por todo o corpo e inspecionou satisfeita os frutos de sua batalha—"
  },
  AvgDialog_145534_Content_15 = {
    Text = "Por quê? Por que você ainda está aqui?"
  },
  AvgDialog_145534_Content_16 = {
    Text = "Uma silhueta solitária, que não deveria existir, de outra pessoa."
  },
  AvgDialog_145534_Content_17 = {
    Text = "Eu também gostaria de saber por que ainda estou aqui."
  },
  AvgDialog_145534_Content_18 = {
    Text = "Você disse agora mesmo que os visitantes oferecem seus desejos à montanha, e a montanha responde às preces de quem pede."
  },
  AvgDialog_145534_Content_19 = {
    Text = "Talvez seja porque, comparada a todos vocês, eu não tenha nenhum desejo. Sou comum demais, ordinária demais, não sou suficientemente saborosa, talvez?"
  },
  AvgDialog_145534_Content_2 = {
    Text = "Caraboo se virou, voltando-se para as montanhas contínuas, para o vento e a Neve abertos."
  },
  AvgDialog_145534_Content_20 = {
    Text = "Não, isso não é possível. Você não tem nenhum desejo que queira entregar à montanha?"
  },
  AvgDialog_145534_Content_21 = {
    Text = "Caraboo arregalou os olhos, e em sua indagação havia uma pitada de incredulidade e irritação."
  },
  AvgDialog_145534_Content_22 = {
    Text = "Não. O único desejo que eu tinha nesta jornada já foi realizado."
  },
  AvgDialog_145534_Content_23 = {
    Text = "Ao pé do último penhasco, encontrei seus restos mortais. Que sorte incrível — ele estava preso numa fenda na rocha, sem ter sido soterrado pela neve acumulada."
  },
  AvgDialog_145534_Content_24 = {
    Text = "A carne já entrou em Podridão, mas a Placa ainda estava lá. Ainda pude reconhecê-lo, ainda pude confirmar sua existência."
  },
  AvgDialog_145534_Content_25 = {
    Text = "Como é possível, como é possível ser satisfeita tão facilmente assim!"
  },
  AvgDialog_145534_Content_26 = {
    Text = "É simplesmente assim. Os desejos dos mortais não deveriam ser coisas que precisam do poder divino para se realizar."
  },
  AvgDialog_145534_Content_27 = {
    Text = "E há mais boas notícias. Pelo equipamento que carregava, pode-se deduzir que eles encontraram seu fim durante a descida."
  },
  AvgDialog_145534_Content_28 = {
    Text = "Portanto, em vida, ele já havia realizado o desejo de chegar ao cume mais alto."
  },
  AvgDialog_145534_Content_29 = {
    Text = "Embora separados por algum tempo, aqui neste lugar, ambos morreremos em plenitude."
  },
  AvgDialog_145534_Content_3 = {
    Text = "Ó verdadeira fada da montanha de Neve, ó grande deus dos vermes, trouxe a Manutenção que lhe é devida!"
  },
  AvgDialog_145534_Content_30 = {
    Text = "<Shake:Não, você está se enganando... isso não é verdade, você deve estar querendo mais...>"
  },
  AvgDialog_145534_Content_31 = {
    Text = "A voz de Caraboo ficou cada vez mais aguda, e lágrimas brotaram dos cantos dos seus Olhos."
  },
  AvgDialog_145534_Content_32 = {
    Text = "Evelyn apenas a observava com O Olhar de compaixão."
  },
  AvgDialog_145534_Content_33 = {
    Text = "A Neve continuava caindo."
  },
  AvgDialog_145534_Content_34 = {
    Text = "Depois de um longo silêncio, Evelyn se aproximou e sacudiu a neve que havia caído sobre os ombros de Caraboo."
  },
  AvgDialog_145534_Content_35 = {
    Text = "Pense bem nisso. Vou me juntar ao meu marido agora."
  },
  AvgDialog_145534_Content_36 = {
    Text = "Após dizer isso, ela cantarolou suavemente algo, caminhando passo a passo em direção ao fundo do penhasco."
  },
  AvgDialog_145534_Content_37 = {
    Text = "Sem corda de segurança fixada, ela não temia a queda. A fenda de gelo na base da rocha era seu destino."
  },
  AvgDialog_145534_Content_38 = {
    Text = "<Shake:Não vá, Evelyn, não vá—>"
  },
  AvgDialog_145534_Content_39 = {
    Text = "Quem a recusou não era Evelyn."
  },
  AvgDialog_145534_Content_4 = {
    Text = "Ela estava em êxtase, Ela ria freneticamente. Ela sentia prazer pelo sucesso de seu engano."
  },
  AvgDialog_145534_Content_40 = {
    Text = "Quem a reteve tampouco era alguém além de Evelyn."
  },
  AvgDialog_145534_Content_41 = {Text = "Por que"},
  AvgDialog_145534_Content_42 = {
    Text = "Por que… a montanha está em Tremor?…"
  },
  AvgDialog_145534_Content_43 = {Text = "..."},
  AvgDialog_145534_Content_44 = {
    Text = "Nas montanhas habita a criatura de maior terror."
  },
  AvgDialog_145534_Content_45 = {
    Text = "Ela se estende por mil milhas, enrolando-se sobre a terra que reivindica. Ela se farta dos corações dos homens e devora suas ilusões."
  },
  AvgDialog_145534_Content_46 = {
    Text = "Agora, Ela veio capturar sua presa."
  },
  AvgDialog_145534_Content_47 = {
    Text = "<Change>Desejo… desejo… um desejo ardente…"
  },
  AvgDialog_145534_Content_48 = {
    Text = "Não! Eu os enganei todos para você, você prometeu que não me comeria!"
  },
  AvgDialog_145534_Content_49 = {
    Text = "<Change>Quem seguiria… o acordo… de um mentiroso…"
  },
  AvgDialog_145534_Content_5 = {
    Text = "Ó pessoas gananciosas, ó pessoas tolas."
  },
  AvgDialog_145534_Content_50 = {
    Text = "O verme sobre a Maçã também ergueu a voz, rindo em gargalhadas agudas."
  },
  AvgDialog_145534_Content_51 = {
    Text = "Aliás, não foi desde o início que você sabia que uma das ofertas era \"a Maçã Dourada\"?"
  },
  AvgDialog_145534_Content_52 = {
    Text = "Não, eu sou a deusa da montanha nevada, a Maçã Dourada é meu artefato sagrado, eu não posso ser uma Oferta!"
  },
  AvgDialog_145534_Content_53 = {
    Text = "Você esqueceu quem é? Deixe-me lembrá-la, Caraboo, você não é ninguém."
  },
  AvgDialog_145534_Content_54 = {
    Text = "Você não é uma deusa, nem uma princesa, nem uma fada.\nVocê é apenas um destroço nascido no campo de batalha, uma refugiada que esqueceu até mesmo o rosto de seus pais."
  },
  AvgDialog_145534_Content_55 = {
    Text = "Você já deveria saber… as Identidades que fabricou para si mesma, as honrarias que obteve através do engano… um dia tudo isso voltaria para você de forma cruel e em dobro."
  },
  AvgDialog_145534_Content_56 = {
    Text = "Hoje, chegou a hora."
  },
  AvgDialog_145534_Content_57 = {
    Text = "A montanha abriu sua enorme boca de Sangue."
  },
  AvgDialog_145534_Content_58 = {
    Text = "<Change>Entre… em meu ventre… e torne-se… minha Força…"
  },
  AvgDialog_145534_Content_59 = {Text = "..."},
  AvgDialog_145534_Content_6 = {
    Text = "Entreguem seus desejos à montanha, entreguem seus anseios à montanha."
  },
  AvgDialog_145534_Content_60 = {
    Text = "A encosta suave tornou-se abruptamente íngreme, e Evelyn, a apenas algumas dezenas de metros da fenda no gelo, abandonou tudo que a atrasava."
  },
  AvgDialog_145534_Content_61 = {
    Text = "Ela arrancou os fechos do cilindro de oxigênio, tirou as pesadas botas com crampons e, sem hesitar, cortou a única corda principal que a prendia."
  },
  AvgDialog_145534_Content_62 = {
    Text = "Nada mais poderia detê-la."
  },
  AvgDialog_145534_Content_63 = {
    Text = "Ela simplesmente se lançou, levemente, quase com alegria, em direção ao amado que dormia na fenda do gelo."
  },
  AvgDialog_145534_Content_64 = {
    Text = "Meu amor, vim te buscar."
  },
  AvgDialog_145534_Content_65 = {
    Text = "Em meio a uma nova onda de tremores, Evelyn abraçou ternamente os ossos do ser amado."
  },
  AvgDialog_145534_Content_66 = {
    Text = "No campo de visão da queda, a montanha nevada abria sua enorme boca, engolindo aquela pequena silhueta que parecia um bolo de creme de cereja."
  },
  AvgDialog_145534_Content_67 = {
    Text = "Engolida de uma vez pelas entranhas das montanhas."
  },
  AvgDialog_145534_Content_7 = {
    Text = "<BigShake:A montanha vai ouvi-los e então \"responder\" a vocês!>"
  },
  AvgDialog_145534_Content_8 = {
    Text = "Num instante, o corpo da montanha Surgiu abruptamente desde sua base — a Neve branca e imaculada desmoronou aos pedaços, o corpo segmentado se revolvia e se entrelaçava, erguendo-se trecho a trecho como uma geleira em colapso."
  },
  AvgDialog_145534_Content_9 = {
    Text = "A \"montanha\" inteira se ergueu com estrondo, curvando-se sobre eles, cada centímetro de seu rastejo esmagando o Campo de Neve sob seus pés em pó."
  },
  AvgDialog_145535_Content_1 = {
    Text = "Convidados no Banquete"
  },
  AvgDialog_145535_Content_10 = {
    Text = "Enganar? E daí se enganei, quem não está enganando?"
  },
  AvgDialog_145535_Content_11 = {
    Text = "Você consegue perceber, não é, %player%? Eu sei que você consegue farejar mentiras como eu."
  },
  AvgDialog_145535_Content_12 = {
    Text = "<Yellow:Ainda bem que consegui me esconder com sucesso e escapar do rastreamento deles.>"
  },
  AvgDialog_145535_Content_13 = {
    Text = "<Yellow:<Big:Não...! Não estou cansada! NÃO VOU EMBORA!>>"
  },
  AvgDialog_145535_Content_14 = {
    Text = "<Yellow:Minhas outras obrigações neste mundo chegaram a um fim temporário.>"
  },
  AvgDialog_145535_Content_15 = {
    Text = "Tinct claramente não ia sobreviver àquela noite, mas ela escolheu esconder sua Doença — ela não é uma mentirosa?"
  },
  AvgDialog_145535_Content_16 = {
    Text = "Castor, desde o momento em que nos encontrou, escondeu o fato de carregar Asas — ele não é um mentiroso?"
  },
  AvgDialog_145535_Content_17 = {
    Text = "William claramente queria outra coisa. Algo pessoal. Mas não quis nos contar. Ele também é um mentiroso, não é?"
  },
  AvgDialog_145535_Content_18 = {
    Text = "Todo mundo está enganando, todo mundo é mentiroso, então por que a acusação recai só sobre mim?"
  },
  AvgDialog_145535_Content_19 = {
    Text = "Mas Tinct só queria continuar um pouco mais. Quanto às asas de Castor e ao desejo secreto de William... isso é privacidade deles."
  },
  AvgDialog_145535_Content_2 = {
    Text = "Quem você realmente é?"
  },
  AvgDialog_145535_Content_20 = {
    Text = "Eles não disseram a verdade, mas também não tinham intenção de causar Dano a ninguém."
  },
  AvgDialog_145535_Content_21 = {
    Text = "Como você ainda não entende — as pessoas, vivendo neste mundo, as coisas que anseiam, seja Força, seja um desejo, são como esta Maçã —"
  },
  AvgDialog_145535_Content_22 = {
    Text = "Todo mundo quer, todo mundo busca desesperadamente…"
  },
  AvgDialog_145535_Content_23 = {
    Text = "Caraboo jogou a Maçã longe casualmente, fingiu correr atrás dela, e então caiu dramaticamente de barriga na pilha de neve."
  },
  AvgDialog_145535_Content_24 = {Text = "Mas..."},
  AvgDialog_145535_Content_25 = {
    Text = "Para sempre, para sempre, apenas um número limitado de pessoas pode obtê-la."
  },
  AvgDialog_145535_Content_26 = {
    Text = "E eu, serei sua dona eterna e única."
  },
  AvgDialog_145535_Content_27 = {
    Text = "Mas o meio que você usou para alcançar esse objetivo foi Uma Mentira."
  },
  AvgDialog_145535_Content_28 = {
    Text = "É mesmo, Uma Mentira não é suficiente?"
  },
  AvgDialog_145535_Content_29 = {
    Text = "O que os atraiu até aqui não foi o destino, nem um deus rei, nem qualquer coisa grandiosa ou majestosa — apenas Uma Mentira, somente Uma Mentira!"
  },
  AvgDialog_145535_Content_3 = {
    Text = "Caraboo deu uma risada leve."
  },
  AvgDialog_145535_Content_30 = {
    Text = "Vocês oferecem Manutenção à montanha, e a montanha responde aos seus desejos conforme seu humor. Isso não é diferente das Divindades do mundo dos homens."
  },
  AvgDialog_145535_Content_31 = {
    Text = "Apenas que desta vez, o que a montanha exige de vocês é... <RedItalic:tudo.>"
  },
  AvgDialog_145535_Content_32 = {
    Text = "Não vou deixar você vencer...!"
  },
  AvgDialog_145535_Content_4 = {
    Text = "Quem eu realmente sou?"
  },
  AvgDialog_145535_Content_5 = {
    Text = "Não foi desde o início que eu lhes disse? Sou a deusa da montanha nevada, a fada madrinha, a encarnação da vontade da montanha de Neve."
  },
  AvgDialog_145535_Content_6 = {
    Text = "Sou eu, o Guia mais importante e mais adorável, Caraboo, que vai alimentar vocês a Ele agora."
  },
  AvgDialog_145535_Content_7 = {
    Text = "Caraboo… você nos enganou."
  },
  AvgDialog_145535_Content_8 = {
    Text = "Enganou Evelyn, que cuidou de você ao longo do Caminho, enganou %player%, que lutou por você para que ficasse durante a disputa."
  },
  AvgDialog_145535_Content_9 = {
    Text = "É isso que você buscava como resultado?"
  },
  AvgDialog_145862_Content_1 = {Text = "Caraboo…"},
  AvgDialog_145862_Content_2 = {
    Text = "O que você disse agora… é verdade?"
  },
  AvgDialog_145862_Content_3 = {
    Text = "O que você acha?"
  },
  AvgDialog_145862_Content_4 = {
    Text = "Não sei..."
  },
  AvgDialog_145862_Content_5 = {
    Text = "Então não pense nisso. Cuidado, há inimigos vindo por ali!"
  },
  AvgDialog_146405_Content_1 = {
    Text = "Saiam do caminho, deixem-me ir encontrá-lo!"
  },
  AvgDialog_146405_Content_2 = {
    Text = "Pollux está me chamando!"
  },
  AvgDialog_146516_Content_1 = {
    Text = "Maldição, essas Pústulas não podem ser congeladas?"
  },
  AvgDialog_146516_Content_10 = {
    Text = "Até então, ninguém havia dado atenção aos tesouros mencionados por Caraboo."
  },
  AvgDialog_146516_Content_11 = {
    Text = "Afinal, nenhuma lenda continha tal elemento."
  },
  AvgDialog_146516_Content_12 = {
    Text = "Diziam apenas que, ao chegar ao topo, seu desejo seria realizado."
  },
  AvgDialog_146516_Content_13 = {Text = "Feito."},
  AvgDialog_146516_Content_14 = {
    Text = "Portanto, quando a bola de corrente de Helot passou por todos vocês, enganchando os pacotes de cada um, ninguém havia previsto."
  },
  AvgDialog_146516_Content_15 = {
    Text = "Apenas inúmeros chocolates de moedas douradas voaram pelas frestas das bolsas, espalhando-se pela encosta rochosa."
  },
  AvgDialog_146516_Content_16 = {
    Text = "Como uma chuva dourada e radiante."
  },
  AvgDialog_146516_Content_17 = {
    Text = "<Shake:Tinct… Castor…>"
  },
  AvgDialog_146516_Content_18 = {
    Text = "Você não sabe o que perdeu.\nMas com certeza vocês perderam algo, algo muito importante."
  },
  AvgDialog_146516_Content_19 = {
    Text = "Não desistam! Ela ainda vai ao altar no topo da montanha!"
  },
  AvgDialog_146516_Content_2 = {
    Text = "Hmph, elas cresceram desde pequenas na Neve acumulada."
  },
  AvgDialog_146516_Content_20 = {
    Text = "Antes do ritual terminar, ainda há uma chance!"
  },
  AvgDialog_146516_Content_21 = {
    Text = "Caraboo foi a primeira a se reerguer e Começar a escalar, sem esquecer de abaixar a cabeça para Chamar vocês."
  },
  AvgDialog_146516_Content_22 = {
    Text = "Por alguma razão, você viu em seus olhos uma alegria de origem inexplicável."
  },
  AvgDialog_146516_Content_23 = {
    Text = "Ouça Caraboo."
  },
  AvgDialog_146516_Content_24 = {
    Text = "Com Helot: Catena… nos encontramos no topo."
  },
  AvgDialog_146516_Content_25 = {
    Text = "Ao longe, o contorno do topo da montanha nevada aparecia e desaparecia entre as nuvens."
  },
  AvgDialog_146516_Content_26 = {
    Text = "-Altitude 7950m-"
  },
  AvgDialog_146516_Content_3 = {
    Text = "As bolas de corrente voam pelo ar, e você e William protegem Evelyn e Naraka, mal conseguindo dar conta de tudo."
  },
  AvgDialog_146516_Content_4 = {
    Text = "Caraboo está escondida atrás de algum monte de neve, e a Neve branca pura oculta sua silhueta."
  },
  AvgDialog_146516_Content_5 = {
    Text = "Vocês não acham estranho? Ela está nos seguindo desde que começamos a subir a montanha."
  },
  AvgDialog_146516_Content_6 = {
    Text = "Por que lançar um ataque tão repentinamente agora?"
  },
  AvgDialog_146516_Content_7 = {
    Text = "<Shake:E se o objetivo dela não fosse nos matar, mas sim——>"
  },
  AvgDialog_146516_Content_8 = {
    Text = "Tarde demais. As correntes giratórias separaram a todos, fazendo com que vocês não tivessem tempo de cuidar das pesadas bagagens."
  },
  AvgDialog_146516_Content_9 = {
    Text = "<Big:——Os tesouros em nossas mãos!>"
  },
  AvgDialog_147080_Content_1 = {Text = "..."},
  AvgDialog_147080_Content_10 = {
    Text = "Tudo bem, tudo bem, eu sei. Mas não posso contar a vocês."
  },
  AvgDialog_147080_Content_100 = {
    Text = "Teseu usou o novelo de fio de Ariadne para sair do labirinto, mas o amor deles não foi abençoado pela deusa do destino…"
  },
  AvgDialog_147080_Content_101 = {
    Text = "Por fim, o deus do vinho Dionísio presenteou Ariadne com uma coroa esplêndida adornada com sete joias cristalinas."
  },
  AvgDialog_147080_Content_102 = {
    Text = "William lançou um olhar para Caraboo."
  },
  AvgDialog_147080_Content_103 = {
    Text = "Embora tenham percorrido o caminho juntos e superado dificuldades lado a lado, Teseu e Ariadne talvez estivessem destinados a não ser companheiros de jornada."
  },
  AvgDialog_147080_Content_104 = {
    Text = "Caraboo desviou o olhar de William."
  },
  AvgDialog_147080_Content_105 = {
    Text = "Uma Casca vazia que já cumpriu sua missão, em troca de um desejo capaz de reescrever o destino — você não acha que está saindo perdendo?"
  },
  AvgDialog_147080_Content_106 = {
    Text = "O propósito de subirmos a montanha era justamente encontrar o dono da Coroa por meio desta Coroa."
  },
  AvgDialog_147080_Content_107 = {
    Text = "Você pode ler diretamente a consciência de Caraboo, e Ela consegue observar se estamos dizendo Uma Mentira."
  },
  AvgDialog_147080_Content_108 = {
    Text = "Portanto, você pode ter certeza de que o que estou dizendo agora é a verdade, certo?"
  },
  AvgDialog_147080_Content_109 = {
    Text = "<Yellow:Minha carta na manga é justamente revelar minha carta na manga>."
  },
  AvgDialog_147080_Content_11 = {
    Text = "Você responde com um olhar furioso."
  },
  AvgDialog_147080_Content_110 = {Text = "..."},
  AvgDialog_147080_Content_111 = {
    Text = "<Shake:Ha, hahaha!> Exatamente, é até possível usar esse mecanismo de forma inversa. Fazer negócios com pessoas inteligentes é simples."
  },
  AvgDialog_147080_Content_112 = {
    Text = "<Big:Prepare-se para reconquistar sua liberdade!>"
  },
  AvgDialog_147080_Content_113 = {
    Text = "<Shake:Contagem regressiva, três, dois, um—>"
  },
  AvgDialog_147080_Content_114 = {Text = "—Zero."},
  AvgDialog_147080_Content_115 = {
    Text = "As paredes de carne dos quatro lados pressionam vocês ao mesmo tempo, e o líquido viscoso que escorre entre as dobras se transforma em inúmeros tentáculos finos e compridos, enrolando-se nos pulsos, tornozelos e cinturas."
  },
  AvgDialog_147080_Content_116 = {
    Text = "Espera, isso não é um pouco diferente da liberdade que foi prometida—"
  },
  AvgDialog_147080_Content_117 = {
    Text = "Eu só prometi tirá-los daqui. Nunca prometi que a jornada seria confortável."
  },
  AvgDialog_147080_Content_118 = {
    Text = "Uma força irresistível surge de baixo dos seus pés."
  },
  AvgDialog_147080_Content_119 = {
    Text = "Vocês são empurrados para fora como um corpo estranho sendo engolido ao contrário pelo esôfago, subindo rapidamente por um corredor de Carne estreito e escorregadio."
  },
  AvgDialog_147080_Content_12 = {
    Text = "Não fique com raiva, não fique com raiva, vou começar a explicar agora."
  },
  AvgDialog_147080_Content_120 = {
    Text = "O Campo de visão é engolido pela escuridão. Ao redor, resta apenas o som viscoso da Carne se esfregando, e o batimento cardíaco surdo e prolongado de toda a montanha."
  },
  AvgDialog_147080_Content_121 = {Text = "Tum."},
  AvgDialog_147080_Content_122 = {Text = "Tum."},
  AvgDialog_147080_Content_123 = {
    Text = "<Red:Pum—>"
  },
  AvgDialog_147080_Content_124 = {
    Text = "Quando o último batimento cardíaco ecoa, uma luz branca ofuscante rasga o espaço à frente."
  },
  AvgDialog_147080_Content_125 = {
    Text = "Vento furioso envolto em Neve e gelo vem de encontro ao rosto."
  },
  AvgDialog_147080_Content_126 = {
    Text = "Vocês são arremessados violentamente por aquela força e caem pesadamente na Neve acumulada até os joelhos."
  },
  AvgDialog_147080_Content_127 = {
    Text = "Tosse… essa criatura definitivamente está se vingando."
  },
  AvgDialog_147080_Content_128 = {
    Text = "Pelo menos não cobrou taxa de limpeza na saída. Pelos padrões de hospitalidade dEle, isso já pode ser considerado generoso."
  },
  AvgDialog_147080_Content_129 = {
    Text = "Você se apoia na Neve e se levanta. O cheiro de Sangue persistente em seus pulmões finalmente é dispersado pelo vento frio e cortante."
  },
  AvgDialog_147080_Content_13 = {
    Text = "Para discutir como sair daqui, primeiro precisamos saber onde estamos e por que estamos aqui."
  },
  AvgDialog_147080_Content_130 = {
    Text = "Este lugar já não é o cume da montanha por onde vieram."
  },
  AvgDialog_147080_Content_131 = {
    Text = "Ao olhar ao redor, todos os picos mais baixos estão submersos no mar de nuvens. O céu negro está tão próximo que parece ao alcance das mãos, e as Estrelas piscam intermitentemente atrás do véu de Neve levantado pelo vento furioso."
  },
  AvgDialog_147080_Content_132 = {
    Text = "Vocês estão no pico mais alto de toda a cordilheira."
  },
  AvgDialog_147080_Content_133 = {
    Text = "Este lugar..."
  },
  AvgDialog_147080_Content_134 = {
    Text = "O verdadeiro cume da montanha."
  },
  AvgDialog_147080_Content_135 = {
    Text = "Uma voz vinha de baixo da neve acumulada."
  },
  AvgDialog_147080_Content_136 = {
    Text = "A camada de gelo tremeu levemente, Como Se este pico nevado não fosse mais do que um fragmento de osso exposto de alguma criatura colossal."
  },
  AvgDialog_147080_Content_137 = {
    Text = "O local do ritual está logo à frente. Coloquem os sete artefatos de volta em seus devidos lugares, e a formação dirá naturalmente o que fazer a seguir."
  },
  AvgDialog_147080_Content_138 = {
    Text = "Você não vai conosco?"
  },
  AvgDialog_147080_Content_139 = {
    Text = "Estou em todo lugar."
  },
  AvgDialog_147080_Content_14 = {
    Text = "Estamos dentro do ventre do Verme da Montanha, e o motivo pelo qual o Verme da Montanha usou o ritual do desejo para atraí-los até aqui..."
  },
  AvgDialog_147080_Content_140 = {
    Text = "Uma risada grave e profunda ecoou sob os pés."
  },
  AvgDialog_147080_Content_141 = {
    Text = "A montanha inteira é minha carcaça. Cada passo que vocês dão, caminham sobre minha Carne e sangue."
  },
  AvgDialog_147080_Content_142 = {
    Text = "Portanto, não alimentem o delírio de tentar algum truque ridículo."
  },
  AvgDialog_147080_Content_143 = {
    Text = "Sigam em frente. Deixem-me ver que tipo de Porta vocês, carregando tantos desejos, acabarão abrindo para mim."
  },
  AvgDialog_147080_Content_144 = {
    Text = "A neve se abre lentamente diante de vocês."
  },
  AvgDialog_147080_Content_145 = {
    Text = "Uma antiga escadaria de pedra, soterrada pela neve por incontáveis anos, se revela, serpenteando até o cume."
  },
  AvgDialog_147080_Content_146 = {
    Text = "E ao fim da escadaria, sete raios de luz dourada e opaca se acendem um a um, como olhos que dormiam há mil anos, finalmente aguardando aqueles que vieram Desperta-los."
  },
  AvgDialog_147080_Content_147 = {
    Text = "William foi o primeiro a subir a escadaria."
  },
  AvgDialog_147080_Content_148 = {
    Text = "Sua mão permanecia pressionada contra o interior do casaco — Como Se acalmasse um desejo que já havia sido abandonado."
  },
  AvgDialog_147080_Content_149 = {
    Text = "Naquele momento, ninguém percebeu que a Chave, em Silêncio por tantos anos, emitia um Tremor extremamente sutil através do tecido da roupa."
  },
  AvgDialog_147080_Content_15 = {
    Text = "Foi para Devorar a Força de vocês."
  },
  AvgDialog_147080_Content_150 = {
    Text = "Como Se algo, no cume da montanha, a estivesse aguardando."
  },
  AvgDialog_147080_Content_16 = {
    Text = "Uma explicação clara e simples."
  },
  AvgDialog_147080_Content_17 = {
    Text = "Então, a Força dos outros alpinistas..."
  },
  AvgDialog_147080_Content_18 = {
    Text = "Está toda nestas Ofertas."
  },
  AvgDialog_147080_Content_19 = {
    Text = "O mecanismo de cooperação entre Caraboo e o Verme da Montanha era: ela selecionava Ofertas com desejos intensos e espiritualidade, atraindo-as para as montanhas."
  },
  AvgDialog_147080_Content_2 = {
    Text = "Então, meu caro senhor, que capricho levou Vossa Excelência a fazer cosplay de guia Sherpa de montanhismo? Não pode ser amor pelos esportes radicais humanos, pode?"
  },
  AvgDialog_147080_Content_20 = {
    Text = "A questão é: por que o Verme da Montanha rompeu ativamente essa cooperação?"
  },
  AvgDialog_147080_Content_21 = {
    Text = "Porque ele sabia que eu havia Abalado."
  },
  AvgDialog_147080_Content_22 = {
    Text = "Caraboo mencionou a última conversa no cume da montanha."
  },
  AvgDialog_147080_Content_23 = {
    Text = "Eu costumava acreditar que ninguém conseguia Conter a cobiça, que para realizar desejos só havia dependência de \"seres não humanos\". Mas ela me fez entender que aceitar a simplicidade também pode trazer felicidade."
  },
  AvgDialog_147080_Content_24 = {
    Text = "Naquele instante, surgiu em mim um \"desejo\" desnecessário."
  },
  AvgDialog_147080_Content_25 = {
    Text = "O \"desejo\" é a isca, é o gatilho."
  },
  AvgDialog_147080_Content_26 = {
    Text = "Desde o início, eu era a \"Maçã Dourada\" destinada a ser Devorada."
  },
  AvgDialog_147080_Content_27 = {
    Text = "Como podemos ter certeza de que você não está nos enganando novamente?"
  },
  AvgDialog_147080_Content_28 = {
    Text = "Acredite se quiser. Agora sou eu, entre todos vocês, quem mais odeia o Verme da Montanha."
  },
  AvgDialog_147080_Content_29 = {
    Text = "Se não fosse naquela noite de neve, quando o Verme da Montanha me seduziu e fechei O Testamento com ele... eu jamais teria trilhado o caminho que trilhei hoje."
  },
  AvgDialog_147080_Content_3 = {
    Text = "Se eu disser que é para dar voz ao povo Sherpa, você acreditaria?"
  },
  AvgDialog_147080_Content_30 = {
    Text = "<Small:Maldito trapaceiro>."
  },
  AvgDialog_147080_Content_31 = {
    Text = "No breve Silêncio, só se ouvia a respiração nauseante das paredes de Carne e sangue, subindo e descendo."
  },
  AvgDialog_147080_Content_32 = {
    Text = "Entendido. Desde Que você não faça nada fora dos limites, não vamos cobrar as questões do passado por enquanto."
  },
  AvgDialog_147080_Content_33 = {
    Text = "O que é mais urgente agora é encontrar uma maneira de sair do estômago desta Divindade… de preferência sem recorrer à Força do Sr. N."
  },
  AvgDialog_147080_Content_34 = {
    Text = "Ora, ora, vocês vão desperdiçar assim a boa vontade do bondoso e gentil Sr. N?"
  },
  AvgDialog_147080_Content_35 = {
    Text = "Ou vocês realmente acham que sair da barriga Dela é tão simples quanto deixar um quarto de hotel com o qual não estão satisfeitos?"
  },
  AvgDialog_147080_Content_36 = {
    Text = "Você disse que não podia nos contar."
  },
  AvgDialog_147080_Content_37 = {
    Text = "Acha que estou escondendo de vocês de propósito? Que injustiça para comigo."
  },
  AvgDialog_147080_Content_38 = {
    Text = "N brincava com a rosa que surgira do nada entre seus dedos, lançando O Olhar calmamente em direção a Caraboo."
  },
  AvgDialog_147080_Content_39 = {
    Text = "Qualquer método que eu tenha, não posso deixar que Você saiba. Certo, pequena mentirosa?"
  },
  AvgDialog_147080_Content_4 = {
    Text = "Acredito, não só nisso, como também que a Senhora Sorel defende o laissez-faire, que Ryker largou as Apostas de vez, que Erica é uma alma iluminada de palavras brilhantes..."
  },
  AvgDialog_147080_Content_40 = {
    Text = "Caraboo não rebateu. Ela Apenas mordia o lábio inferior com força, desviando o olhar de todos."
  },
  AvgDialog_147080_Content_41 = {Text = "Caraboo?"},
  AvgDialog_147080_Content_42 = {
    Text = "…Ele consegue me ouvir."
  },
  AvgDialog_147080_Content_43 = {
    Text = "Não é uma metáfora. Quando tinha seis anos, ao partir com ele naquela noite de Neve, empenhei minha própria alma a ele."
  },
  AvgDialog_147080_Content_44 = {
    Text = "Este é O Testamento entre mim e ele. Ele me emprestou a Força de \"Uma Mentira\", permitindo-me enganar todas as pessoas do mundo; e como preço —"
  },
  AvgDialog_147080_Content_45 = {
    Text = "Para ele, não consigo esconder nenhum pensamento meu."
  },
  AvgDialog_147080_Content_46 = {
    Text = "…Então, neste momento, cada palavra que dizemos —"
  },
  AvgDialog_147080_Content_47 = {
    Text = "Desde Que chegue aos meus ouvidos e entre na minha cabeça, ele saberá de tudo."
  },
  AvgDialog_147080_Content_48 = {
    Text = "A Carne e sangue ao redor se contraiu subitamente por um instante, depois relaxou Solto aos poucos. Como se alguma criatura enorme estivesse escondida atrás das cortinas, ouvindo tudo isso com grande interesse."
  },
  AvgDialog_147080_Content_49 = {
    Text = "Agora vocês entendem?"
  },
  AvgDialog_147080_Content_5 = {
    Text = "Agora não é hora de brigas."
  },
  AvgDialog_147080_Content_50 = {
    Text = "Sempre houve um jeito. Mas se isso chegar aos ouvidos desta jovem senhora, é como jogar Texas Hold'em com suas cartas-trunfo viradas para cima."
  },
  AvgDialog_147080_Content_51 = {
    Text = "Quando estivermos discutindo o plano, pedimos para Caraboo Esquivar por um momento?"
  },
  AvgDialog_147080_Content_52 = {
    Text = "Mesmo que eu não ouça o plano de vocês, posso perceber algo estranho durante a execução."
  },
  AvgDialog_147080_Content_53 = {
    Text = "Não posso ver suas microexpressões, seus pequenos gestos. Caso contrário, saberei qual frase é Uma Mentira."
  },
  AvgDialog_147080_Content_54 = {
    Text = "Talvez Você possa não olhar?"
  },
  AvgDialog_147080_Content_55 = {
    Text = "Não, Uma Mentira é uma atmosfera fluida… e eu já estou imersa nela há tempo demais."
  },
  AvgDialog_147080_Content_56 = {
    Text = "Às vezes, mesmo que ninguém fale, consigo sentir a existência de Uma Mentira no ar congelado."
  },
  AvgDialog_147080_Content_57 = {
    Text = "Deixe-me tentar."
  },
  AvgDialog_147080_Content_58 = {
    Text = "Acompanhada de um estalo de dedos nítido, uma fumaça negra sobe sobre os olhos de Caraboo."
  },
  AvgDialog_147080_Content_59 = {
    Text = "Pronto, Abra os olhos."
  },
  AvgDialog_147080_Content_6 = {
    Text = "Arachne nos trouxe até aqui, certamente por alguma razão. E você deve ser um elo desse destino."
  },
  AvgDialog_147080_Content_60 = {
    Text = "Caraboo Abra os olhos. Tudo diante de seus Olhos estava envolto numa camada de fumaça de Distorção, e até os sons tornaram-se confusos e distantes."
  },
  AvgDialog_147080_Content_61 = {
    Text = "William, porém, de repente baixou os Olhos, com os nós dos dedos apoiados no queixo, como se estivesse fazendo a inferência de um jogo de xadrez que Apenas ele podia ver."
  },
  AvgDialog_147080_Content_62 = {Text = "Pare."},
  AvgDialog_147080_Content_63 = {Text = "Sim?"},
  AvgDialog_147080_Content_64 = {
    Text = "Não é preciso cobrir os Olhos dela."
  },
  AvgDialog_147080_Content_65 = {
    Text = "Pelo contrário, a partir de agora, espero que Caraboo fique com toda a atenção possível para discernir a veracidade de cada palavra que eu disser."
  },
  AvgDialog_147080_Content_66 = {
    Text = "Ouça bem, Caraboo — ou melhor, o Verme da Montanha por trás de Caraboo. Quero fazer uma negociação com Você."
  },
  AvgDialog_147080_Content_67 = {
    Text = "A parede de carne estremeceu como se estivesse rindo com escárnio."
  },
  AvgDialog_147080_Content_68 = {
    Text = "Que piada. Vocês estão dentro do meu ventre. O que você tem para me oferecer em troca?"
  },
  AvgDialog_147080_Content_69 = {Text = "Um desejo."},
  AvgDialog_147080_Content_7 = {
    Text = "Você sabe como sair daqui, não sabe, N?"
  },
  AvgDialog_147080_Content_70 = {
    Text = "De repente, tudo ao redor ficou em silêncio."
  },
  AvgDialog_147080_Content_71 = {
    Text = "O círculo de desejos no topo da montanha <Yellow:não foi criado por você>, mas por algo mais antigo do que você, não é?"
  },
  AvgDialog_147080_Content_72 = {Text = "..."},
  AvgDialog_147080_Content_73 = {
    Text = "O Verme da Montanha ficou em silêncio por um instante, depois soltou uma risada ambígua."
  },
  AvgDialog_147080_Content_74 = {
    Text = "Interessante. Continue."
  },
  AvgDialog_147080_Content_75 = {
    Text = "Antes desta escalada, a lenda que Caraboo contou tinha algumas diferenças em relação à que circula entre os montanheses. Em resumo, os montanheses só sabem que chegar ao topo realiza desejos, mas não sabem da existência dos sete artefatos."
  },
  AvgDialog_147080_Content_76 = {
    Text = "Isso faz sentido. Se o objetivo é apenas atrair humanos para escalar a montanha e depois Devorá-los, não há necessidade de criar a lenda dos sete artefatos."
  },
  AvgDialog_147080_Content_77 = {
    Text = "Basta dizer a todos que chegar ao topo realiza desejos."
  },
  AvgDialog_147080_Content_78 = {
    Text = "Quanto maior a dificuldade, menos desafiantes aparecem — esse princípio básico vocês não poderiam ignorar, a menos que—"
  },
  AvgDialog_147080_Content_79 = {
    Text = "A menos que—"
  },
  AvgDialog_147080_Content_8 = {
    Text = "Eu sei… ou será que não sei… Ah, que pergunta interessante."
  },
  AvgDialog_147080_Content_80 = {
    Text = "O Verme da Montanha arrastou o tom de forma sarcástica."
  },
  AvgDialog_147080_Content_81 = {
    Text = "A menos que os sete artefatos existam de verdade, e o ritual para realizar desejos também seja real."
  },
  AvgDialog_147080_Content_82 = {
    Text = "E você está instalado ao lado do círculo não apenas para Devorar os escaladores.\nVocê também está Esperando uma oportunidade para ativar o ritual."
  },
  AvgDialog_147080_Content_83 = {
    Text = "O mundo de Carne e sangue parou de respirar."
  },
  AvgDialog_147080_Content_84 = {
    Text = "Se você sempre guardou o ritual, por que não o ativa sozinho?"
  },
  AvgDialog_147080_Content_85 = {
    Text = "Humano, você tem perguntas demais."
  },
  AvgDialog_147080_Content_86 = {
    Text = "Parece que fiz a pergunta certa."
  },
  AvgDialog_147080_Content_87 = {
    Text = "Deixe-me adivinhar."
  },
  AvgDialog_147080_Content_88 = {
    Text = "Existe um núcleo no círculo mágico que você não consegue decifrar, certo? Por isso, ao longo de todos esses anos, você acumulou leva após leva de Ofertas, mas nunca conseguiu abrir aquela última Porta."
  },
  AvgDialog_147080_Content_89 = {
    Text = "As paredes de carne se contraíram subitamente, Quase esmagando todos."
  },
  AvgDialog_147080_Content_9 = {
    Text = "Sem rodeios, fale diretamente."
  },
  AvgDialog_147080_Content_90 = {
    Text = "Eu sei por que você não consegue decifrar. Acabei de dar uma olhada no círculo mágico de longe, e as runas gravadas nele contêm latim e outras escritas antigas."
  },
  AvgDialog_147080_Content_91 = {
    Text = "E esta sua… pequena Executor, calculando pelo tempo desde que Ela saiu de Nosso Lar, obviamente nunca recebeu uma boa educação acadêmica…"
  },
  AvgDialog_147080_Content_92 = {
    Text = "<Shake:É, desculpe por não saber ler! E daí?!>"
  },
  AvgDialog_147080_Content_93 = {
    Text = "O tempo era curto, e antes que eu pudesse ler com atenção, você me engoliu aqui. Mas imagino que o que está Acima Registrado seja, em sua maior parte, conhecimento relacionado à ativação do círculo mágico."
  },
  AvgDialog_147080_Content_94 = {
    Text = "A deusa do destino nos guiou até aqui, os sete grandes artefatos já estão reunidos. Você deve saber que esta é a vez em que você está mais perto de realizar seu desejo."
  },
  AvgDialog_147080_Content_95 = {
    Text = "E nós podemos <Yellow:abrir mão voluntariamente da chance de fazer um pedido à montanha>."
  },
  AvgDialog_147080_Content_96 = {
    Text = "O verme da montanha mergulhou em um longo Silêncio. Quando vocês já achavam que ele não responderia mais, ele emitiu um leve resmungo."
  },
  AvgDialog_147080_Content_97 = {
    Text = "Abrir mão de um desejo… que Sacrifício admirável. O que você quer não deve ser apenas que eu os deixe sair, certo?"
  },
  AvgDialog_147080_Content_98 = {
    Text = "Depois que o ritual terminar, todos os outros artefatos podem ficar com você, mas nós levaremos a <Blue:Coroa de Ariadne>."
  },
  AvgDialog_147080_Content_99 = {
    Text = "A Coroa de Ariadne…"
  },
  AvgDialog_147095_Content_1 = {
    Text = "No salão vazio, apenas os passos de você e Murphy ecoam."
  },
  AvgDialog_149752_Content_1 = {
    Text = "Covil do Dragão"
  },
  AvgDialog_149752_Content_10 = {
    Text = "Você já não tem nada, não pode suportar o esquecimento novamente."
  },
  AvgDialog_149752_Content_11 = {
    Text = "As chamas que ardiam intensamente foram apagadas pela chuva, você atravessa o portão sem guardas e avista a desolação por toda parte."
  },
  AvgDialog_149752_Content_12 = {
    Text = "O castelo ergue-se em silêncio — barris vazios, sacos rasgados, escudos despedaçados, lanças quebradas, flechas curvadas pelo vento como palha rasteira, o cheiro acre da lama úmida misturado ao persistente odor de queimado."
  },
  AvgDialog_149752_Content_13 = {
    Text = "Aqui houve um combate, e agora restam apenas sombras."
  },
  AvgDialog_149752_Content_14 = {
    Text = "As sombras se espalham livremente pela escuridão, escalam os altos muros, rastejam pelas ameias, engolfam os corpos espalhados pelo chão, emitindo sons úmidos e viscosos. Você tenta não pensar no que isso significa."
  },
  AvgDialog_149752_Content_15 = {
    Text = "Siga as sombras… basta seguir as sombras…"
  },
  AvgDialog_149752_Content_16 = {
    Text = "Ah… ah… so… socorro…"
  },
  AvgDialog_149752_Content_17 = {
    Text = "Gemidos de dor ecoam sob o elmo deformado, as sombras se aninham junto a ele como amantes íntimos, e você reúne coragem para se aproximar."
  },
  AvgDialog_149752_Content_18 = {
    Text = "Aquele que trouxe as sombras — para onde foi?"
  },
  AvgDialog_149752_Content_19 = {
    Text = "<Shake:Som… bra? Não, não, aquilo é um monstro! Sangue negro… vazio por dentro… cavaleiro da morte… é verdade, tudo é verdade!>"
  },
  AvgDialog_149752_Content_2 = {
    Text = "O que é uma promessa? Uma magia que só se torna real quando se acredita nela."
  },
  AvgDialog_149752_Content_20 = {
    Text = "<Shake:Fuja… ah… fuja logo! Um monstro imortal… vingança… destruição… glu… glu glu glu…>"
  },
  AvgDialog_149752_Content_21 = {
    Text = "Sons viscosos e espessos borbulham na garganta do monstro, ele se contorce como um peixe encalhado, mas lentamente ergue o braço em direção ao embrulho em seus braços, e uma lama mole e rastejante escorre pelas juntas da armadura."
  },
  AvgDialog_149752_Content_22 = {
    Text = "São as sombras. Elas querem o cálice sagrado."
  },
  AvgDialog_149752_Content_23 = {
    Text = "Não, impossível, isso é algo importante, não posso dar a você."
  },
  AvgDialog_149752_Content_24 = {
    Text = "A recusa não surte efeito — as sombras escorregam pelos muros e convergem rapidamente em sua direção, você aperta o embrulho nos braços em pânico e corre fundo adentro do castelo."
  },
  AvgDialog_149752_Content_25 = {
    Text = "A torre do portão, o salão, a capela — escadas de pedra em espiral que descem para as profundezas da terra; o castelo é um covil perigoso de dragão. O ar fica cada vez mais frio, sua respiração ofegante e seus passos são amplificados pelas paredes de pedra, soando como se fossem de outra pessoa."
  },
  AvgDialog_149752_Content_26 = {
    Text = "Uma chama se acende no fim da escada em espiral, e você avista uma silhueta familiar."
  },
  AvgDialog_149752_Content_27 = {Text = "O——"},
  AvgDialog_149752_Content_28 = {
    Text = "Você estava prestes a chamá-lo com alegria, quando de repente percebe que não são apenas vocês dois. O monstro tomou a palavra antes de você."
  },
  AvgDialog_149752_Content_29 = {
    Text = "<Shake:Tosse, tosse, tosse… Ogier…>"
  },
  AvgDialog_149752_Content_3 = {
    Text = "O que é a separação? O momento seguinte após a chegada."
  },
  AvgDialog_149752_Content_30 = {
    Text = "Como você chegou a esse estado?"
  },
  AvgDialog_149752_Content_31 = {
    Text = "Meu… estado?"
  },
  AvgDialog_149752_Content_32 = {
    Text = "Sobre a mesa estavam dispostos vinhos finos e iguarias, talheres de prata reluzindo à luz das velas. Se não fosse o frio cortante que se infiltrava pelas fendas das pedras, aquela decoração cuidadosa quase faria esquecer que estavam nas profundezas sombrias da terra."
  },
  AvgDialog_149752_Content_33 = {
    Text = "O senhor esquálido sentava-se sozinho atrás da mesa, olhos fundos, maçãs do rosto proeminentes, envolto em pesadas camadas de seda, como um dragão maligno entocado em meio a ouro e prata."
  },
  AvgDialog_149752_Content_34 = {
    Text = "Seu cavaleiro avançava passo a passo em direção a ele, arrastando uma longa sombra atrás de si. Talvez ele próprio fosse uma sombra. Suas vestes estavam em farrapos, seu rosto, horrendo, e seus passos, silenciosos."
  },
  AvgDialog_149752_Content_35 = {
    Text = "Sim, se não tivesse visto com meus próprios olhos, mal acreditaria… tosse, tosse… o mais jovem cavaleiro do ducado, reduzido a um monstro."
  },
  AvgDialog_149752_Content_36 = {
    Text = "O ducado… já foi destruído."
  },
  AvgDialog_149752_Content_37 = {
    Text = "Por sua causa."
  },
  AvgDialog_149752_Content_38 = {
    Text = "Pela guerra, pela peste, pela ganância dos países vizinhos, pela própria fraqueza. São muitas as razões que levam um ducado à ruína. Eu fui apenas, tosse tosse, a mais insignificante delas."
  },
  AvgDialog_149752_Content_39 = {
    Text = "<Shake:Você… traiu o ducado… conluio com o inimigo… vendeu… os súditos…>"
  },
  AvgDialog_149752_Content_4 = {
    Text = "O que é a morte? Um amanhã sem despedida."
  },
  AvgDialog_149752_Content_40 = {
    Text = "<Shake:Traidor… merece morrer.>"
  },
  AvgDialog_149752_Content_41 = {
    Text = "Sim, sim, como você pode ver, as consequências já recaíram sobre mim. Meu tempo é curto, tosse, tosse, tosse."
  },
  AvgDialog_149752_Content_42 = {
    Text = "A peste não me poupou, Ogier. A morte, ela não faz distinção, aguarda pacientemente na outra margem da ponte, e ninguém escapa… exceto você."
  },
  AvgDialog_149752_Content_43 = {
    Text = "Diga-me, que pacto você fez com o diabo?"
  },
  AvgDialog_149752_Content_44 = {Text = "..."},
  AvgDialog_149752_Content_45 = {
    Text = "O preço de fugir da morte só pode ser mais pesado do que a própria morte. Cavaleiro da Morte… tornar-se seu carrasco foi um desejo que você fez, ou uma punição que recebeu?"
  },
  AvgDialog_149752_Content_46 = {
    Text = "Ogier, o cavaleiro mais leal e mais devoto do ducado, hah, <Shake:tosse, tosse, tosse, tosse…>"
  },
  AvgDialog_149752_Content_47 = {
    Text = "Sou um maldito traidor, e você não é?"
  },
  AvgDialog_149752_Content_48 = {Text = "!!"},
  AvgDialog_149752_Content_49 = {
    Text = "Um raio invisível atingiu seu cavaleiro, pregando-o firmemente no lugar. As sombras nas trevas tremeram violentamente, de alegria ou de raiva — elas já não conseguiam mais esperar."
  },
  AvgDialog_149752_Content_5 = {
    Text = "O que é o esquecimento?"
  },
  AvgDialog_149752_Content_50 = {
    Text = "Eu traí o Grão-Duque, mas você, você e sua princesa, vocês traíram a Deus."
  },
  AvgDialog_149752_Content_51 = {
    Text = "Você ainda se lembra… você ainda tem a ousadia de mencionar…"
  },
  AvgDialog_149752_Content_52 = {
    Text = "<Red:Princesa Bruxa>, tss tss tss, que ironia — seus truques finalmente foram expostos, e nem mesmo seu nome é mais lembrado por alguém. Eu sempre disse: entregue-a, e o fogo da guerra se apagaria, o Principado não precisaria ter sido destruído."
  },
  AvgDialog_149752_Content_53 = {
    Text = "Você sabe o que ela trouxe, você sabe muito bem. A maldição… a guerra começou por causa dela, e por causa dela terminou. Graças a ela, o Principado de @3 tornou-se um lugar esquecido."
  },
  AvgDialog_149752_Content_54 = {
    Text = "Cale a boca! Você… não tem o direito… de falar dela!"
  },
  AvgDialog_149752_Content_55 = {
    Text = "A lança amorfa partiu a longa mesa ao meio, taças e pratos despencaram pelo chão, o banquete hipócrita se despedaçou, revelando sua verdadeira face de caos."
  },
  AvgDialog_149752_Content_56 = {
    Text = "As sombras estenderam pseudópodes viscosos, devorando avidamente tudo o que tocavam; o pântano brotou das trevas sem luz, e assim o mundo começou a afundar."
  },
  AvgDialog_149752_Content_57 = {
    Text = "Morte… e depois o esquecimento… como se nunca tivesse acontecido. Este é o destino de quem abandona a Deus."
  },
  AvgDialog_149752_Content_58 = {
    Text = "Foi ela quem te transformou nessa figura… arrastou o Principado inteiro para o vazio, e ainda deixou para trás um fantoche cheio de ódio, espalhando morte real pela terra. Cumprir uma missão como essa — você chama isso de lealdade?"
  },
  AvgDialog_149752_Content_59 = {
    Text = "Ogier… a quem você realmente serve?"
  },
  AvgDialog_149752_Content_6 = {Text = "..."},
  AvgDialog_149752_Content_60 = {
    Text = "<Shake:Não… não… a princesa não é… glu… glu glu…>"
  },
  AvgDialog_149752_Content_61 = {
    Text = "Seu cavaleiro apertou a cabeça com as mãos em agonia, sombras brotando do peito, das orelhas, dos cantos dos olhos. O tormento incessante do demônio dia e noite o havia enfraquecido; ele já não conseguia emitir som algum, como um boneco de barro se dissolvendo nas águas negras do rio."
  },
  AvgDialog_149752_Content_62 = {
    Text = "Quando nenhum de vocês estava prestando atenção, o senhor girou sua cadeira de rodas — na parede de pedra atrás dele havia uma seteira do tamanho de um punho. Uma sombra negra como uma serpente passou diante dos olhos, acompanhada de um baque surdo, e uma lança de ferro atravessou o peito do seu cavaleiro."
  },
  AvgDialog_149752_Content_63 = {
    Text = "<Big:Ogier!!!>"
  },
  AvgDialog_149752_Content_64 = {
    Text = "<Shake:Tss tss tss tss…> Um monstro que rastejou para fora de um túmulo é melhor que volte logo para o túmulo."
  },
  AvgDialog_149752_Content_65 = {
    Text = "Você e seu monstrozinho serão enterrados aqui juntos."
  },
  AvgDialog_149752_Content_66 = {
    Text = "Alguns guardas totalmente armados surgiram de uma passagem secreta, escudos e espadas reluzindo com um brilho sinistro — a armadilha final finalmente veio à tona."
  },
  AvgDialog_149752_Content_7 = {Text = "..."},
  AvgDialog_149752_Content_8 = {
    Text = "<Red:Uma maldição.>"
  },
  AvgDialog_149752_Content_9 = {
    Text = "Maldição. Praga. Punição. O vazio corroído pelos vermes. O leito do rio partido. Apodrecer no silêncio. Erosão. Afundamento. Um olhar esgotado. Desvanecer de história a sombra. A última morte."
  },
  AvgDialog_149753_Content_1 = {
    Text = "Cálice Sagrado"
  },
  AvgDialog_149753_Content_10 = {
    Text = "Nada do que faço é digno de um cavaleiro, você já viu isso."
  },
  AvgDialog_149753_Content_11 = {
    Text = "Por quê? Um cavaleiro deve lutar contra monstros, esse é o seu dever, e você o cumpre muito bem."
  },
  AvgDialog_149753_Content_12 = {
    Text = "E você está procurando algo, não é? Eu percebi. Você vai de lugar em lugar procurando, desde que entramos na cidade, já faz vários dias. Os monstros também roubaram algo seu?"
  },
  AvgDialog_149753_Content_13 = {Text = "..."},
  AvgDialog_149753_Content_14 = {
    Text = "\"Estamos aqui.\""
  },
  AvgDialog_149753_Content_15 = {
    Text = "A luz quente e sedutora das velas enchia as paredes, a porta de carvalho bloqueava o vento frio — para os errantes sem lar, o armazém do mosteiro aberto numa noite de chuva podia até salvar vidas."
  },
  AvgDialog_149753_Content_16 = {
    Text = "Mas você não se deixaria enganar pelas aparências, você se lembrava deles. Aqueles que circulavam de um lado para o outro com castiçais, mantos negros, pingentes de latão, os carrascos que se autodenominavam pastores — eram monstros entre os monstros."
  },
  AvgDialog_149753_Content_17 = {
    Text = "<Small:Por que viemos aqui… o que você procura está aqui?>"
  },
  AvgDialog_149753_Content_18 = {
    Text = "Fique aqui e me espere, não me siga."
  },
  AvgDialog_149753_Content_19 = {
    Text = "<Big:O quê?! Não! De jeito nenhum!>"
  },
  AvgDialog_149753_Content_2 = {
    Text = "<Shake:Eu não sabia, eu não sabia que era — não, não, não, por favor, por favor, tenha misericórdia —>"
  },
  AvgDialog_149753_Content_20 = {
    Text = "<Big:Eu não fico aqui, eu não fico aqui de forma alguma! Quero ir com você!>"
  },
  AvgDialog_149753_Content_21 = {
    Text = "O que aconteceu? Criança, você precisa de ajuda?"
  },
  AvgDialog_149753_Content_22 = {
    Text = "Sim, por favor cuide dela, não a deixe fugir."
  },
  AvgDialog_149753_Content_23 = {
    Text = "Oh… tão tarde, com essa chuva forte, onde você está com tanta pressa? Espere o sol nascer para ir, não deixe sua irmãzinha sozinha."
  },
  AvgDialog_149753_Content_24 = {
    Text = "Virei buscá-la ao amanhecer."
  },
  AvgDialog_149753_Content_25 = {
    Text = "Se você insiste, tudo bem, tudo bem. Pobrezinha, encharcada até os ossos, venha, venha até aqui, deixe-me enxugar seu rosto."
  },
  AvgDialog_149753_Content_26 = {
    Text = "Você está presa, incapaz de se mover, um linho seco roçando suas bochechas, sem saber quando ele irá cobrir sua boca e nariz."
  },
  AvgDialog_149753_Content_27 = {
    Text = "O medo esmagou seu peito, você não consegue respirar, só consegue gritar."
  },
  AvgDialog_149753_Content_28 = {
    Text = "<Shake:Volte! Você é meu cavaleiro, você deve me proteger, não pode me abandonar — você prometeu!>"
  },
  AvgDialog_149753_Content_29 = {
    Text = "<Shake:Por favor, não vou causar problemas, deixe-me ir com você!>!"
  },
  AvgDialog_149753_Content_3 = {Text = "Ah!!"},
  AvgDialog_149753_Content_30 = {
    Text = "Muitos olhos foram atraídos pelos seus gritos desesperados, alguns pareciam besouros, outros cabras, outros corujas."
  },
  AvgDialog_149753_Content_31 = {
    Text = "Eles te encaravam fixamente, como se você fosse a única sem olhos."
  },
  AvgDialog_149753_Content_32 = {
    Text = "<SmallShake:Não… não vá embora… você havia prometido…>"
  },
  AvgDialog_149753_Content_33 = {
    Text = "<SmallShake:Por favor, não me abandone…>"
  },
  AvgDialog_149753_Content_34 = {
    Text = "Mudei de ideia, deixe-a vir comigo."
  },
  AvgDialog_149753_Content_35 = {
    Text = "Você ergueu a cabeça de repente, seu cavaleiro havia retornado sem que você percebesse, bloqueando com as costas todos os olhares dos monstros."
  },
  AvgDialog_149753_Content_36 = {
    Text = "Mas para onde você pretende levá-la? Não há muitos lugares na cidade para se abrigar da chuva, e nenhum deles é adequado para uma criança."
  },
  AvgDialog_149753_Content_37 = {
    Text = "O lugar para onde vou não fica na cidade."
  },
  AvgDialog_149753_Content_38 = {
    Text = "Fora da cidade há ainda menos — ah! Será que você quer ir àquela mansão?"
  },
  AvgDialog_149753_Content_39 = {
    Text = "O que há de errado com aquela mansão?"
  },
  AvgDialog_149753_Content_4 = {
    Text = "Os gritos foram abafados pela chuva torrencial, misturando-se ao sangue que escorria para as valetas junto às paredes, apodrecendo com a lama, o esterco de cavalo e as folhas de legumes, até serem engolidos pelo beco escuro."
  },
  AvgDialog_149753_Content_40 = {
    Text = "Aquele lugar, aquele lugar… ai, vocês também vieram fugindo, não é? Criança, não se aproxime dali."
  },
  AvgDialog_149753_Content_41 = {
    Text = "Aquele senhor, ele já foi um homem bom, mas a guerra, a peste, as calamidades vieram e foram como marés, e as pessoas deixaram de ser pessoas. Todos dizem que ele enlouqueceu. A cidade foi esvaziando, e aqueles que foram pedir pão nunca mais voltaram."
  },
  AvgDialog_149753_Content_42 = {
    Text = "Que o Senhor perdoe… todos dizem que ele come pessoas às escondidas."
  },
  AvgDialog_149753_Content_43 = {
    Text = "Monstros comem pessoas, você já sabia disso, então não ficou nada surpresa, nem com medo… pelo menos não tanto. Você tinha seu cavaleiro."
  },
  AvgDialog_149753_Content_44 = {
    Text = "Fique perto de mim, algo aqui não está certo."
  },
  AvgDialog_149753_Content_45 = {
    Text = "Tudo bem, tudo bem."
  },
  AvgDialog_149753_Content_46 = {
    Text = "A vasta mansão estava completamente vazia, sem guardas nem serventes, como se houvesse sido abandonada há muito tempo, e nos corredores estreitos e compridos só se ouvia o som dos passos de vocês, deliberadamente abafados."
  },
  AvgDialog_149753_Content_47 = {
    Text = "Então… o que você está procurando afinal? É importante para você? Me diga como é, posso te ajudar a encontrar."
  },
  AvgDialog_149753_Content_48 = {
    Text = "Um cálice de ouro."
  },
  AvgDialog_149753_Content_49 = {
    Text = "Cálice de ouro? Quer dizer, feito de ouro? Uau, qual é o tamanho, a altura? Para que serve? Como é o ouro, será que brilha como a lua à noite?"
  },
  AvgDialog_149753_Content_5 = {
    Text = "O corpo caiu mole no chão, o brilho frio do metal relampejou e desapareceu, o assassino apertou a capa e saiu a passos rápidos, seus passos também se dissolvendo na chuva."
  },
  AvgDialog_149753_Content_50 = {
    Text = "...Eu não sei."
  },
  AvgDialog_149753_Content_51 = {
    Text = "Hein? Não é seu?"
  },
  AvgDialog_149753_Content_52 = {
    Text = "Não, mas é muito importante para mim."
  },
  AvgDialog_149753_Content_53 = {
    Text = "Oh! Já sei, é o Santo Graal, não é? Ouvi falar em histórias, um tesouro mágico que só um cavaleiro que superar as provações pode obter. Não é à toa que você procura há tanto tempo."
  },
  AvgDialog_149753_Content_54 = {
    Text = "Hum, sendo sua princesa, se você conseguir o Santo Graal, isso também me beneficia, então…"
  },
  AvgDialog_149753_Content_55 = {
    Text = "Ele parou subitamente, ergueu o dedo indicador e fez um gesto de silêncio em sua direção."
  },
  AvgDialog_149753_Content_56 = {
    Text = "Você imediatamente ficou imóvel, prendendo a respiração sem perceber. A Lanterna se apagou, e a escuridão avançou de todos os lados, envolvendo você de forma sufocante."
  },
  AvgDialog_149753_Content_57 = {
    Text = "Contando o décimo quarto batimento do coração, um baque surdo ecoou do fundo do corredor, acompanhado pelo estilhaçar de objetos caindo no chão, e alguns gritos descontrolados quebraram o silêncio."
  },
  AvgDialog_149753_Content_58 = {
    Text = "Uma luz surgiu, oscilando, como as silhuetas de muitas pessoas em luta intensa. Você correu em direção a ela, mas foi repelido por uma onda de calor. Era fogo — fogo azul."
  },
  AvgDialog_149753_Content_59 = {
    Text = "Sol— cof cof — solte-me! Eu estava quase conseguindo! Só faltava um pouco, só um pouquinho!"
  },
  AvgDialog_149753_Content_6 = {
    Text = "Você se apressou a colocar o capuz e correu sob a chuva para conseguir, com dificuldade, acompanhá-lo."
  },
  AvgDialog_149753_Content_60 = {
    Text = "Um cheiro acre pairava pelo quarto secreto, um líquido suspeito de tom vermelho-escuro escorria lentamente pelos tubos de vidro, as velas incendiaram o líquido derramado no chão, e chamas azul-escuras ardiam em silêncio — no fundo da mansão, havia um laboratório alquímico escondido."
  },
  AvgDialog_149753_Content_61 = {
    Text = "No centro de inúmeros recipientes de vidro, um cálice dourado de haste alta brilhava intensamente, mais luminoso que o Pavio — aquele devia ser o Santo Graal."
  },
  AvgDialog_149753_Content_62 = {
    Text = "O que você colocou lá dentro?"
  },
  AvgDialog_149753_Content_63 = {
    Text = "Solte-me! Você não entende! Já está quase chegando, ela está quase chegando… Rastejando pelas cortinas apodrecidas, espalhando-se pelo caminho do esquecimento. Vivos, mortos, ninguém escapa… ninguém escapa…"
  },
  AvgDialog_149753_Content_64 = {Text = "Ela?"},
  AvgDialog_149753_Content_65 = {
    Text = "Ela… a noite eterna sem fim, a extinção suprema… é uma maldição… <Shake:A maldição está chegando! A maldição que devora tudo, a maldição da <Red:princesa bruxa>!!>"
  },
  AvgDialog_149753_Content_66 = {
    Text = "O que você disse?!"
  },
  AvgDialog_149753_Content_67 = {
    Text = "A sombra atrás dele estremeceu violentamente, as chamas se refletiram nos olhos arregalados de terror — o que foi aceso? Medo, ou esperança?"
  },
  AvgDialog_149753_Content_68 = {
    Text = "Aquelas palavras certamente escondiam um poderoso feitiço, pois seu cavaleiro de repente se petrificou como uma estátua de pedra, e ao mesmo tempo pareceu ganhar vida pela primeira vez. Sua sombra tremia sem parar."
  },
  AvgDialog_149753_Content_69 = {
    Text = "Vo, você……você se lembra dela? O que mais você se lembra?"
  },
  AvgDialog_149753_Content_7 = {
    Text = "O que você está procurando?"
  },
  AvgDialog_149753_Content_70 = {
    Text = "<Shake:Vaidade, vaidade das vaidades, tudo é vaidade… Os homens se afanam como poeira sobre a pedra, sem passado, sem futuro…>"
  },
  AvgDialog_149753_Content_71 = {
    Text = "Não, o cálice dourado! O cálice dourado é a única salvação! Deixa-me beber a verdade, deixa-me — devo continuar!"
  },
  AvgDialog_149753_Content_72 = {
    Text = "<Big:Responda minha pergunta! @1@2Princesa, quanto você ainda se lembra sobre ela?!>"
  },
  AvgDialog_149753_Content_73 = {
    Text = "As sombras se contorciam, as sombras se agitavam, as sombras dançavam freneticamente, enrolando-se em círculos cada vez mais apertados ao redor do pescoço do monstro, cujos dois lábios se abriam e fechavam em vão."
  },
  AvgDialog_149753_Content_74 = {
    Text = "<Shake:Eu me lembro… da praga… da poção… da maldição… cra, cra… eu me lembro, eu me lembro de você…>"
  },
  AvgDialog_149753_Content_75 = {
    Text = "<Shake:<Red:Au……gil>… meu cavaleiro… você… fuja…>"
  },
  AvgDialog_149753_Content_76 = {Text = "\"Cra.\""},
  AvgDialog_149753_Content_77 = {
    Text = "As palavras ainda não tinham terminado, mas já não havia como continuar — as sombras quebraram seu pescoço. A cabeça inchada pendurou-se para o lado como um saco de estopa amarrado, sem forças, e pelos buracos rasgados espreitavam dois globos oculares enferrujados, ainda fixos no vazio."
  },
  AvgDialog_149753_Content_78 = {Text = "..."},
  AvgDialog_149753_Content_79 = {
    Text = "Au… gil? Será que esse é… o seu nome?"
  },
  AvgDialog_149753_Content_8 = {
    Text = "Eu não prometi que você poderia me seguir."
  },
  AvgDialog_149753_Content_80 = {
    Text = "Ele virou o rosto de repente, como um espectro com a verdadeira identidade revelada, com uma expressão entre o aturdimento e o ódio. As sombras na parede balançavam, dançando passos alegres, envolvendo vocês dois no centro."
  },
  AvgDialog_149753_Content_81 = {
    Text = "Não, está errado? Tudo bem… de qualquer forma, não importa como você se chame, você é meu cavaleiro."
  },
  AvgDialog_149753_Content_82 = {
    Text = "O cálice sagrado já foi encontrado. Para onde vamos agora?"
  },
  AvgDialog_149753_Content_83 = {
    Text = "Lembrado por você, ele virou lentamente a cabeça, olhando para o cálice dourado sobre a mesa, e então, com dificuldade, se desprendeu das sombras e ergueu o meio cálice restante de antídoto — ou veneno, você não sabia."
  },
  AvgDialog_149753_Content_84 = {
    Text = "Você apenas o viu inclinar a cabeça e beber."
  },
  AvgDialog_149753_Content_85 = {Text = "<Big:Ei!!>"},
  AvgDialog_149753_Content_9 = {
    Text = "Se eu não viesse, e se você traísse sua princesa? Você nem quis fazer um juramento."
  },
  AvgDialog_149754_Content_1 = {
    Text = "O estrondo era ensurdecedor, como se toda a torre principal estivesse tremendo; pedaços de tijolos e pedras estalavam ao cair, e os monstros restantes cercaram o senhor bem no centro, recuando em direção à passagem secreta."
  },
  AvgDialog_149754_Content_10 = {
    Text = "Não se sabia ao certo quanto haviam caminhado quando um vento soprou de frente. Salgado. Era o mar."
  },
  AvgDialog_149754_Content_11 = {
    Text = "Sa-saímos! Escapamos! Ogier, está me ouvindo? Estamos salvos!!"
  },
  AvgDialog_149754_Content_12 = {Text = "…Ogier?"},
  AvgDialog_149754_Content_13 = {
    Text = "Ele não emitiu nenhum som, e você mal conseguia sentir sua respiração. As ondas batiam nas rochas, e a água gelada do mar misturada com chuva açoitava seu rosto. Era como se você sentisse frio pela primeira vez — não conseguia parar de tremer."
  },
  AvgDialog_149754_Content_14 = {
    Text = "<SmallShake:…Tosse… tosse, tosse…>"
  },
  AvgDialog_149754_Content_15 = {
    Text = "Ogier! Que alívio — eu sabia que você não ia morrer!"
  },
  AvgDialog_149754_Content_16 = {
    Text = "<Shake:Eu… não… prometi… que viria.>"
  },
  AvgDialog_149754_Content_17 = {
    Text = "Já sei, quantas vezes ainda vai repetir isso. Uma princesa precisa da permissão do cavaleiro para ir aonde quiser?"
  },
  AvgDialog_149754_Content_18 = {Text = "..."},
  AvgDialog_149754_Content_19 = {
    Text = "<Shake:Eu… já tive… uma… princesa.>"
  },
  AvgDialog_149754_Content_2 = {
    Text = "Seu cavaleiro lutou com todas as forças, um grito rouco irrompendo do peito despedaçado, mas as sombras avançaram como uma maré. Mais do que aos inimigos, elas pareciam querer devorá-lo vivo."
  },
  AvgDialog_149754_Content_20 = {
    Text = "<Shake:Não consegui… protegê-la.>"
  },
  AvgDialog_149754_Content_21 = {
    Text = "Seu murmúrio fraco soava como palavras de sonho, facilmente dispersas pelo vento do mar. Você precisou prender a respiração para ouvir."
  },
  AvgDialog_149754_Content_22 = {
    Text = "Antes… da guerra… estourar… ela me ordenou… que partisse…"
  },
  AvgDialog_149754_Content_23 = {
    Text = "Eu… obedeci."
  },
  AvgDialog_149754_Content_24 = {
    Text = "Não imaginei… que o inimigo… fosse tão rápido… Não consegui chegar a tempo, tosse tosse, não consegui chegar a tempo…"
  },
  AvgDialog_149754_Content_25 = {
    Text = "Massacre… cadáveres… praga negra… <Shake:A princesa ela… ela mesma, tosse tosse tosse tosse!>"
  },
  AvgDialog_149754_Content_26 = {
    Text = "Sem saber que memórias dolorosas ele reviveu, você consegue sentir que ele se encolheu, como uma lesma coberta de sal."
  },
  AvgDialog_149754_Content_27 = {
    Text = "<Shake:Fui eu… não consegui proteger… tudo desapareceu… tudo vai desaparecer…>"
  },
  AvgDialog_149754_Content_28 = {
    Text = "<Shake:Eu já quis… me tornar um cavaleiro…>"
  },
  AvgDialog_149754_Content_29 = {
    Text = "<Shake:Mas… agora… eu sou… quem afinal…>"
  },
  AvgDialog_149754_Content_3 = {
    Text = "Parem! Os monstros são vocês! Não fujam!!"
  },
  AvgDialog_149754_Content_30 = {
    Text = "O passado é passado, o presente é presente, agora você também tem uma princesa, e ainda precisa me proteger."
  },
  AvgDialog_149754_Content_31 = {
    Text = "Ele ficou em silêncio por um longo tempo, mas se agitou levemente."
  },
  AvgDialog_149754_Content_32 = {
    Text = "<Shake:Me, tosse tosse tosse, me solte.>"
  },
  AvgDialog_149754_Content_33 = {
    Text = "Eu sou o mais fraco… o mais incapaz…"
  },
  AvgDialog_149754_Content_34 = {
    Text = "O que mais merece… ficar… permanecer… no passado… esquecido…"
  },
  AvgDialog_149754_Content_35 = {
    Text = "Impossível! Sua promessa ainda não foi cumprida, você quer voltar atrás?"
  },
  AvgDialog_149754_Content_36 = {
    Text = "A maré alta cobriu seus joelhos, você avança com dificuldade na escuridão, as pedras afiadas dos recifes cortaram suas panturrilhas, as feridas dormeceram encharcadas pela água do mar, você cerrou os dentes sem soltar um gemido de dor."
  },
  AvgDialog_149754_Content_37 = {
    Text = "As palavras foram rasgadas por respirações pesadas, você forçou as frases para fora da garganta, a cada frase concluída, dava um passo à frente, como se as usasse para se sustentar no caminho."
  },
  AvgDialog_149754_Content_38 = {
    Text = "Você é meu, escolhido, cavaleiro. Se você ficar, como a princesa vai, sozinha, vencer o monstro, completar a aventura?"
  },
  AvgDialog_149754_Content_39 = {
    Text = "… Isso é apenas uma história."
  },
  AvgDialog_149754_Content_4 = {
    Text = "Tomada de angústia e raiva, você arremessou com força o embrulho que carregava. Estava cheio até transbordar, e o nó frouxo se desfez no ar, espalhando os pertences de alguém por toda parte — velas, um pente, um boneco de pedra… e o cálice sagrado."
  },
  AvgDialog_149754_Content_40 = {
    Text = "Todas as coisas, são histórias."
  },
  AvgDialog_149754_Content_41 = {
    Text = "Ontem, é a história de hoje, hoje é, a história de amanhã. Algumas, desapareceram, outras, continuarão. Mas não pode, não haver histórias."
  },
  AvgDialog_149754_Content_42 = {
    Text = "Então, vá encontrar, a Ilha das Maçãs. Vá, ha, ha… vá completar, a nossa história."
  },
  AvgDialog_149754_Content_5 = {
    Text = "O brilho dourado rolou e voou alto sobre o pântano de sombras, bateu na parede de pedra, quicou duas vezes no chão e, por fim, foi parar exatamente aos pés do senhor."
  },
  AvgDialog_149754_Content_6 = {
    Text = "Você o viu erguer a mão para deter os guardas, curvar-se pessoalmente e recolher o pequeno cálice dourado, passando o polegar sobre os relevos da taça, como se estivesse lembrando de algo — e então virou o olhar para você, cheio de escárnio."
  },
  AvgDialog_149754_Content_7 = {
    Text = "Que rapidamente se transformou em terror."
  },
  AvgDialog_149754_Content_8 = {
    Text = "…Antes que o castelo desabasse por completo em ruínas, soterando sombras, dragão e relíquias, seu cavaleiro arrastou você para dentro de um corredor secreto."
  },
  AvgDialog_149754_Content_9 = {
    Text = "Ele estava completamente exausto, incapaz até de se manter de pé. Você o segurou firmemente pelo braço, arrastando os passos com dificuldade, como se carregasse um saco pesado de trigo."
  },
  AvgDialog_149755_Content_1 = {
    Text = "Ilha Maçã"
  },
  AvgDialog_149755_Content_10 = {
    Text = "A ferida na perna nunca havia cicatrizado, e com os dias consecutivos de chuva a dor só piorava, o joelho abaixo inchou como uma cenoura, impossível dar um único passo. Nos últimos dias, foi Ogier quem carregou você nas costas por montanhas e vales."
  },
  AvgDialog_149755_Content_100 = {
    Text = "Princesa, não precisa chorar por mim. Já há monstros demais neste mundo. A única coisa que posso fazer por você é proteger o paraíso que pertence aos humanos, que pertence a você. Este é meu dever, e também minha redenção."
  },
  AvgDialog_149755_Content_101 = {
    Text = "Não estou caminhando para o fim — vou atravessar o fim, pois já conquistei o amanhecer."
  },
  AvgDialog_149755_Content_102 = {
    Text = "Continuarei a velar por você no lugar onde o sol nasce."
  },
  AvgDialog_149755_Content_103 = {
    Text = "Sombras jorram no lugar do sangue. Quando alguém adentrou aquela correnteza rugindo, desapareceu em um piscar de olhos — mas as sombras ainda não se dissiparam."
  },
  AvgDialog_149755_Content_104 = {
    Text = "As sombras se contorcem, as sombras se agitam, as sombras se condensam em escudos, em muros, e por fim em uma enorme barragem. Você fita fixamente a escuridão mais profunda, até que o carro de boi dobra uma curva e você não consegue mais ver a superfície do rio."
  },
  AvgDialog_149755_Content_105 = {
    Text = "Seu cavaleiro desapareceu sem deixar rastros desde então. Ele cumpriu apenas metade de sua promessa, mas deixou um último adeus astucioso o suficiente para fazer com que você, mesmo adormecendo entre lágrimas, ainda anseie pelo amanhã."
  },
  AvgDialog_149755_Content_106 = {
    Text = "Pois naquele momento um novo sol nascerá, dia após dia, sem jamais mudar."
  },
  AvgDialog_149755_Content_11 = {
    Text = "Toma, acabei de colher."
  },
  AvgDialog_149755_Content_12 = {
    Text = "Como se fosse um consolo, ele enfiou uma fruta em sua mão, e você mordeu meio atordoado, só percebendo o que era quando uma acidez se espalhou pela raiz dos dentes."
  },
  AvgDialog_149755_Content_13 = {
    Text = "…Uma maçã?"
  },
  AvgDialog_149755_Content_14 = {
    Text = "Sim, passamos por um pomar de maçãs antes."
  },
  AvgDialog_149755_Content_15 = {
    Text = "Maçã… a Ilha das Maçãs, já chegamos?"
  },
  AvgDialog_149755_Content_16 = {
    Text = "Já falta pouco."
  },
  AvgDialog_149755_Content_17 = {
    Text = "Ele desfez as ataduras, aplicou as ervas sobre a ferida e voltou a enrolá-las camada por camada. Você observou sua expressão e sentiu que não era de expectativa."
  },
  AvgDialog_149755_Content_18 = {
    Text = "Você queria continuar questionando, mas foi interrompido por latidos que se aproximavam ao longe."
  },
  AvgDialog_149755_Content_19 = {
    Text = "Espera, não corra tão rápido! Para onde você vai? Aquele caminho não leva de volta à aldeia — ah!"
  },
  AvgDialog_149755_Content_2 = {
    Text = "……acor……"
  },
  AvgDialog_149755_Content_20 = {
    Text = "Um cão pastor furioso saltou dos arbustos, latindo alto para expulsar os intrusos, e a jovem que corria atrás dele, ao ver vocês, não conseguiu conter um grito de susto, e a cesta de vime que carregava caiu no chão."
  },
  AvgDialog_149755_Content_21 = {
    Text = "Era Ogier — cicatrizes negras e sujas cobriam seu rosto, como um boneco de pano rasgado e remendado às pressas, evocando muitas lendas aterrorizantes."
  },
  AvgDialog_149755_Content_22 = {
    Text = "Ele olhou para a jovem em silêncio, depois se levantou e colocou o capuz."
  },
  AvgDialog_149755_Content_23 = {
    Text = "Vamos embora agora."
  },
  AvgDialog_149755_Content_24 = {
    Text = "Não… não é isso, eu não estava — espere um momento!"
  },
  AvgDialog_149755_Content_25 = {
    Text = "Ogier mal havia dado alguns passos carregando você nas costas quando a jovem o seguiu apressadamente."
  },
  AvgDialog_149755_Content_26 = {
    Text = "Não vá! Não foi isso que quis dizer, ainda há muitas pessoas doentes na aldeia, eu os levo até elas!"
  },
  AvgDialog_149755_Content_27 = {Text = "Doentes?"},
  AvgDialog_149755_Content_28 = {
    Text = "Sim, todos são leprosos. No começo só havia leprosos, mas depois o exército chegou, destruiu inúmeras aldeias, mas nunca se aproximava das aldeias de leprosos, então algumas pessoas sem lar fugiram para cá, inclusive eu."
  },
  AvgDialog_149755_Content_29 = {
    Text = "Não se preocupe, todos já estão acostumados. Na verdade, além da aparência diferente, não somos muito diferentes, todos comemos, dormimos, trabalhamos da mesma forma… A lepra ainda não é tão assustadora quanto o exército, você se acostuma."
  },
  AvgDialog_149755_Content_3 = {
    Text = "……chuva……descanse……acorde……"
  },
  AvgDialog_149755_Content_30 = {
    Text = "Desculpe, não estava com medo de você, só nunca tinha visto… Desculpe! Esta cesta de maçãs azuis é para você, escolhi as melhores, garanto que são as maiores e mais doces!"
  },
  AvgDialog_149755_Content_31 = {
    Text = "Como deveria ser o paraíso?"
  },
  AvgDialog_149755_Content_32 = {
    Text = "Sem monstros, sem desespero, sem o pânico indescritível, sem olhos espreitando na escuridão, sem precisar temer não acordar antes de dormir, podendo tomar uma sopa quente todos os dias."
  },
  AvgDialog_149755_Content_33 = {
    Text = "Você não sabe de nenhum lugar mais parecido com o paraíso do que este."
  },
  AvgDialog_149755_Content_34 = {
    Text = "…Já está bom."
  },
  AvgDialog_149755_Content_35 = {
    Text = "Uma faca afiada corta o abscesso, removendo aos poucos a carne podre e deteriorada, o ferro em brasa é pressionado contra a ferida que não para de sangrar, a dor excruciante faz você gritar abafado, encharcado de suor."
  },
  AvgDialog_149755_Content_36 = {
    Text = "Acabou. O pano enfiado em sua boca é retirado, você respira com todas as suas forças, quase engolindo o ar até o estômago."
  },
  AvgDialog_149755_Content_37 = {
    Text = "Desta vez é diferente, você sabe. Eles estão aqui para salvá-lo, e seu cavaleiro também está ao seu lado."
  },
  AvgDialog_149755_Content_38 = {
    Text = "O remédio, leve de volta e ferva em água para beber. Uma vez ao amanhecer, uma vez ao anoitecer."
  },
  AvgDialog_149755_Content_39 = {
    Text = "Certo, obrigado."
  },
  AvgDialog_149755_Content_4 = {
    Text = "Você é gentilmente sacudido para acordar, e em meio à consciência turva, ouve o suave farfalhar da chuva."
  },
  AvgDialog_149755_Content_40 = {
    Text = "Ele tirou algumas moedas como pagamento, mas o barbeiro acenou com a mão recusando. Em um lugar isolado do mundo, os preços do exterior não tinham utilidade alguma, e as pessoas daqui não viviam por isso."
  },
  AvgDialog_149755_Content_41 = {
    Text = "<Small:O tempo abriu…>"
  },
  AvgDialog_149755_Content_42 = {
    Text = "<Small:Ogier, quero ir ao pomar de maçãs.>"
  },
  AvgDialog_149755_Content_43 = {
    Text = "Você precisa descansar."
  },
  AvgDialog_149755_Content_44 = {
    Text = "Me leve lá, tenho uma grande descoberta… para te contar."
  },
  AvgDialog_149755_Content_45 = {
    Text = "Chegamos. Que grande descoberta?"
  },
  AvgDialog_149755_Content_46 = {
    Text = "Ufa… Descobri que este lugar é a Ilha das Maçãs, já a encontramos."
  },
  AvgDialog_149755_Content_47 = {
    Text = "Seu cavaleiro te coloca sobre um tronco caído, dobra os joelhos e apoia cuidadosamente sua perna ferida. Seu olhar é concentrado e preocupado — claramente, a verdade que você acabou de perceber não o surpreendeu."
  },
  AvgDialog_149755_Content_48 = {
    Text = "Mas este lugar não é uma ilha."
  },
  AvgDialog_149755_Content_49 = {
    Text = "Ninguém disse que uma ilha precisa estar no mar, não é? Desde que não esteja ligada ao exterior, já é uma ilha."
  },
  AvgDialog_149755_Content_5 = {
    Text = "A chuva voltou a cair, ela nunca havia realmente parado."
  },
  AvgDialog_149755_Content_50 = {
    Text = "Além disso, aqui também há fadas."
  },
  AvgDialog_149755_Content_51 = {Text = "Fadas?"},
  AvgDialog_149755_Content_52 = {
    Text = "Sim, há muitas fadas na aldeia. Algumas têm rosto de leão, outras têm escamas de peixe, e há ainda as que trocam de pele como cobras — elas são as fadas que vivem em terras encantadas."
  },
  AvgDialog_149755_Content_53 = {
    Text = "São fadas… não são monstros?"
  },
  AvgDialog_149755_Content_54 = {
    Text = "Claro que não! Como fadas e monstros poderiam ser a mesma coisa?"
  },
  AvgDialog_149755_Content_55 = {
    Text = "Monstros devoram pessoas, fazem de tudo para devorá-las — às vezes matam diretamente com uma faca, outras vezes inventam mentiras, cercam as pessoas e cortam sua carne aos poucos para comer."
  },
  AvgDialog_149755_Content_56 = {
    Text = "Não apenas comem sozinhos — transformam em sopa, em carne salgada, em mingau, e dão para outros comerem. Carne humana está em todo lugar; quem não come morre de fome, mas quem já comeu carne humana se torna um monstro, e assim os monstros se multiplicam."
  },
  AvgDialog_149755_Content_57 = {
    Text = "Humanos não comem humanos, e fadas também não. Na Ilha das Maçãs, elas são puras."
  },
  AvgDialog_149755_Content_58 = {
    Text = "E eu? Não sou humano, nem sou uma fada. Minhas mãos estão manchadas de sangue, e um demônio habita meu corpo — você mesmo já viu sua forma."
  },
  AvgDialog_149755_Content_59 = {
    Text = "Por que não tem medo?"
  },
  AvgDialog_149755_Content_6 = {
    Text = "A floresta escondia os exilados em fuga, a notícia do massacre do castelo pelos monstros chegou aos ouvidos dos governantes, os cartazes de procurado foram espalhados por cada cidade, os cavaleiros da Igreja e os mercenários foram mobilizados, e vocês precisaram marchar dia e noite."
  },
  AvgDialog_149755_Content_60 = {
    Text = "Por que teria medo? Desde o primeiro momento em que o viu, você soube que ele era, sem dúvida, um cavaleiro. Através das sombras que o envolviam sem dissipar, você ainda conseguia enxergar sua essência de cavaleiro — tão clara, tão inegável, como se já o tivesse visto em algum lugar."
  },
  AvgDialog_149755_Content_61 = {
    Text = "O que é preciso para se tornar um verdadeiro cavaleiro? Lealdade, coragem, compaixão, sacrifício, e ainda…"
  },
  AvgDialog_149755_Content_62 = {
    Text = "A condecoração do senhor."
  },
  AvgDialog_149755_Content_63 = {
    Text = "Hum, hum… Então, eu declaro, em nome da princesa, que te armo cavaleiro."
  },
  AvgDialog_149755_Content_64 = {
    Text = "Você derrotou o monstro, obteve o cálice sagrado, resistiu ao demônio e me protegeu. Você cumpriu sua promessa, levando sua princesa à Ilha das Maçãs."
  },
  AvgDialog_149755_Content_65 = {
    Text = "Não importa quem você foi, em nossa história, você é um cavaleiro, e nenhuma princesa teme o seu próprio cavaleiro."
  },
  AvgDialog_149755_Content_66 = {
    Text = "Você será sempre o meu cavaleiro."
  },
  AvgDialog_149755_Content_67 = {
    Text = "Seu cavaleiro ficou estupefato, uma das mãos agarrando firmemente a capa, como se quisesse se esconder na sombra ampla que ela projetava. A capa ocultava os rastros da sombra, e só ele sabia quão miserável era o que se escondia sob aquele disfarce."
  },
  AvgDialog_149755_Content_68 = {
    Text = "Galhos finos ainda úmidos de orvalho pousaram levemente em seus ombros. Um anseio tão antigo que quase havia sido esquecido subitamente se tornava real, mas o que fazia sua alma tremer não era alegria."
  },
  AvgDialog_149755_Content_69 = {
    Text = "Mas sim o medo."
  },
  AvgDialog_149755_Content_7 = {
    Text = "Há uma aldeia à frente, vou trocar por comida e remédios, você descansa aqui, quando a chuva parar partimos."
  },
  AvgDialog_149755_Content_70 = {
    Text = "As chamas do medo ascendiam do abismo sem fundo, sob seus pés, sobre sua cabeça, nos olhos aterrorizados por trás das frestas. Escaldantes, mornas, jorradas de pescoços partidos, brotando de peitos abertos. As chamas eram tão retorcidas que as sombras também enlouqueciam. Fogo e sombra eram uma só coisa."
  },
  AvgDialog_149755_Content_71 = {
    Text = "Foi um massacre, sem honra alguma, sem justiça alguma, igual para todos. O desfecho ensanguentado rasgou o verniz das palavras sedutoras — a morte era apenas morte. Ele não se lembrava de como havia sobrevivido; talvez não tivesse sobrevivido."
  },
  AvgDialog_149755_Content_72 = {
    Text = "Monstro decaído, espectro da vingança — sua busca era como tentar apagar o fogo com lenha. A Alma Perdida deslizava irresistivelmente para o fim, sem nunca ter acreditado que poderia ser redimida."
  },
  AvgDialog_149755_Content_73 = {
    Text = "<Shake:Mas… mas…>"
  },
  AvgDialog_149755_Content_74 = {
    Text = "Ogier, Ogier? Ei, você está ouvindo? Eu terminei, é a sua vez."
  },
  AvgDialog_149755_Content_75 = {Text = "..."},
  AvgDialog_149755_Content_76 = {
    Text = "Sim, aceito."
  },
  AvgDialog_149755_Content_77 = {
    Text = "Em nome da minha terra natal perdida, eu, Ogier, filho da Família Danske, juro-lhe lealdade e respeito."
  },
  AvgDialog_149755_Content_78 = {
    Text = "Ofereço-lhe meu escudo e minha lança, junto com a fé que manchei, meu eterno temor e meu coração partido. Perdi meu nome na longa noite, e foi o seu chamado que iluminou o amanhecer."
  },
  AvgDialog_149755_Content_79 = {
    Text = "Quem quebrou seus juramentos não merece mais ser chamado de fiel, mas se o seu olhar ainda quiser pousar sobre mim, então serei seu, até o último suspiro de minha vida."
  },
  AvgDialog_149755_Content_8 = {
    Text = "<Small:Entendido… volte logo.>"
  },
  AvgDialog_149755_Content_80 = {
    Text = "As histórias nem sempre têm começos coloridos; podem também começar na outra margem do desespero."
  },
  AvgDialog_149755_Content_81 = {
    Text = "Mesmo que o fim permaneça erguido para sempre, lançando sua sombra pesada sobre todas as coisas, antes de chegar lá, vocês ainda têm a liberdade de escolher o que se tornará o destino."
  },
  AvgDialog_149755_Content_82 = {
    Text = "Brisa suave, luz do sol, o perfume de maçãs maduras, névoa erguendo-se da floresta como nuvens — o mundo era belo como uma pintura, e você sorria alegremente, como se um final perfeito tivesse chegado."
  },
  AvgDialog_149755_Content_83 = {
    Text = "Mas você sabe que a história continuará, ela sempre continua."
  },
  AvgDialog_149755_Content_84 = {
    Text = "<Big:Quantas pessoas ainda não acordaram? Vá chamá-las depressa, a enchente está chegando!>"
  },
  AvgDialog_149755_Content_85 = {
    Text = "A escuridão da noite amplificou a fúria da tempestade. As gotas de chuva caíam como pedras com estrondos secos, as águas turvas do rio rugiam transbordando pelas margens, e a lama já havia ultrapassado os joelhos."
  },
  AvgDialog_149755_Content_86 = {
    Text = "Silhuetas corriam de um lado para o outro, gritando em alto e bom som, batendo com força em cada porta e janela. Mas os elfos se moviam lentamente, e ao cair não conseguiam se levantar, incapazes de atravessar sozinhos os terrenos irregulares e alagados."
  },
  AvgDialog_149755_Content_87 = {
    Text = "\"BOOM!!\" Um estrondo ensurdecedor fez seu coração tremer. Sob o manto da noite, as pessoas olhavam em volta desorientadas, sem saber o que estava prestes a desabar."
  },
  AvgDialog_149755_Content_88 = {
    Text = "<Big:Não, é a barragem!!>"
  },
  AvgDialog_149755_Content_89 = {
    Text = "<Big:Fujam! Quem puder andar, fuja agora, não há mais tempo!>"
  },
  AvgDialog_149755_Content_9 = {
    Text = "Embora não quisesse ficar, seu corpo estava ardendo de febre, e você já não tinha forças para acompanhá-lo."
  },
  AvgDialog_149755_Content_90 = {
    Text = "Súplicas, gemidos, choros — o paraíso dos seus sonhos balançava à beira do colapso, prestes a ser destruído pela chuva interminável, deixando para trás apenas ruínas desoladas. E você sequer conseguia andar por conta própria, não podendo fazer nada além de assistir impotente."
  },
  AvgDialog_149755_Content_91 = {
    Text = "Seu cavaleiro ergueu você até a borda da carruagem, desatou sua capa e a enrolou firmemente ao seu redor."
  },
  AvgDialog_149755_Content_92 = {
    Text = "Princesa, peço humildemente sua permissão para partir e enfrentar a enchente devastadora."
  },
  AvgDialog_149755_Content_93 = {
    Text = "Você consegue conter as águas?"
  },
  AvgDialog_149755_Content_94 = {
    Text = "Farei o que estiver ao meu alcance."
  },
  AvgDialog_149755_Content_95 = {
    Text = "Você consegue voltar?"
  },
  AvgDialog_149755_Content_96 = {
    Text = "……Farei o que estiver ao meu alcance."
  },
  AvgDialog_149755_Content_97 = {
    Text = "<Big:Não, não! Eu não concordo! Eu não permito!>"
  },
  AvgDialog_149755_Content_98 = {
    Text = "Vamos embora, agora mesmo… haverá um próximo lugar, a Ilha das Maçãs, a Ilha das Abóboras, qualquer coisa, haverá sempre um próximo lugar!"
  },
  AvgDialog_149755_Content_99 = {
    Text = "Você agarrou a barra de sua roupa com todas as suas forças, mas sabia no fundo que era inútil — ele já havia feito sua escolha. Ele se curvou diante de você, como o herói mais gentil e o cavaleiro mais leal de todas as histórias."
  },
  AvgDialog_149756_Content_1 = {Text = "Princesa"},
  AvgDialog_149756_Content_10 = {
    Text = "Você quer gritar em protesto, quer rir, quer praguejar, quer berrar, mas um trapo encharcado de óleo veda sua boca. O objeto rançoso e gorduroso pressiona com força a raiz da sua língua, e além de engasgos secos, você não consegue emitir nenhum som."
  },
  AvgDialog_149756_Content_11 = {
    Text = "Vejam, ela está tremendo — o demônio dentro dela se debate, essa é a sua verdadeira face horrenda."
  },
  AvgDialog_149756_Content_12 = {
    Text = "Senhor misericordioso, imploro que desate sua boca, selada pelo diabo, e que ela confesse seus pecados com as próprias palavras, se ainda guardar em seu coração o anseio pela redenção."
  },
  AvgDialog_149756_Content_13 = {
    Text = "O pano que vedava sua boca foi arrancado com brutalidade, você tosse e engasga duas vezes, começa a respirar fundo com dificuldade, e a saliva escorre pelo canto dos lábios."
  },
  AvgDialog_149756_Content_14 = {
    Text = "Os monstros formam um círculo ao redor de você, empunhando machados e forcados, olhando para você com cautela. Mais ao longe, nos terraços dos campos, entre os galhos das árvores, pelas janelas entreabertas, espreitam ainda mais olhos."
  },
  AvgDialog_149756_Content_15 = {
    Text = "Fale, criança! Proclame ao Senhor o seu arrependimento — este é o seu último momento para escapar da condenação eterna!"
  },
  AvgDialog_149756_Content_16 = {
    Text = "<Small:…Monstros.>"
  },
  AvgDialog_149756_Content_17 = {
    Text = "O quê? O que ela disse?"
  },
  AvgDialog_149756_Content_18 = {
    Text = "<BigShake:Monstros! Monstros! Mons— cof cof cof!>"
  },
  AvgDialog_149756_Content_19 = {
    Text = "A farsa cuidadosamente arquitetada foi desmascarada por você, os monstros exibem expressões de pânico, e você sente uma cruel e amarga satisfação."
  },
  AvgDialog_149756_Content_2 = {
    Text = "Os monstros devoraram minha família, e agora planejam me devorar também."
  },
  AvgDialog_149756_Content_20 = {
    Text = "Uma maldição, é uma maldição! Maldita bruxa!"
  },
  AvgDialog_149756_Content_21 = {
    Text = "Tapem a boca dela logo!"
  },
  AvgDialog_149756_Content_22 = {
    Text = "Senhor… protegei-nos…"
  },
  AvgDialog_149756_Content_23 = {
    Text = "<Big:Queimem ela! Queimem ela!>"
  },
  AvgDialog_149756_Content_24 = {
    Text = "<Big:Duendes! Monstros do pântano! Ghoul! Monstros! Vocês todos são mons— uuuuu——!!>"
  },
  AvgDialog_149756_Content_25 = {
    Text = "O diabo já tomou sua alma. Para proteger nossa aldeia dos malefícios da feitiçaria, é preciso eliminar essa impureza."
  },
  AvgDialog_149756_Content_26 = {
    Text = "Que o fogo sagrado queime seus pecados, que o Senhor nos conceda paz."
  },
  AvgDialog_149756_Content_27 = {
    Text = "Feixe após feixe de lenha seca foi empilhado aos seus pés, os espinhos rasgaram sua pele exposta, você se debateu de dor, as correntes tilintando ruidosamente."
  },
  AvgDialog_149756_Content_28 = {
    Text = "Isso lhe rendeu ainda mais insultos, e uma corda de cânhamo amarrada ainda mais apertada."
  },
  AvgDialog_149756_Content_29 = {
    Text = "O fogo se acendeu."
  },
  AvgDialog_149756_Content_3 = {
    Text = "O crepúsculo é um presságio de algum despertar; o sol poente parece uma mancha vermelha doentia, e o céu incha com o roxo de um hematoma."
  },
  AvgDialog_149756_Content_30 = {
    Text = "Nós te exorcizamos… alma impura, herege apóstata… como fumaça dispersada pelo vento, como cera derretida pelo fogo…"
  },
  AvgDialog_149756_Content_31 = {
    Text = "Ser decaído, perseguidor, banido, em nome de Sua Majestade, eu te ordeno, treme, submete-te, foge—"
  },
  AvgDialog_149756_Content_32 = {
    Text = "Sua voz cessou abruptamente, como se tivesse sido cortada ao meio por uma tesoura."
  },
  AvgDialog_149756_Content_33 = {
    Text = "Você forçou seus olhos ardentes a se abrirem, e através da densa fumaça, viu uma silhueta desconhecida parada ao lado do sacerdote."
  },
  AvgDialog_149756_Content_34 = {
    Text = "Quando ele havia aparecido? Você não sabia. Você olhou para os monstros restantes — eles estavam imóveis, como um bando de sapos boquiabertos."
  },
  AvgDialog_149756_Content_35 = {
    Text = "O sacerdote convulsionou nervosamente, as duas mãos cobrindo o pescoço, o sangue escorrendo entre seus dedos, jorrando de sua boca, seu rosto da mesma cor que o céu. Ele caiu."
  },
  AvgDialog_149756_Content_36 = {
    Text = "<Big:Ah——!!>"
  },
  AvgDialog_149756_Content_37 = {
    Text = "Gritos, mais altos que um apito, e as línguas de fogo tremeram junto."
  },
  AvgDialog_149756_Content_38 = {
    Text = "Sangue… tanto sangue… assassinato! Socorro, o monstro matou alguém!"
  },
  AvgDialog_149756_Content_39 = {
    Text = "Não, não… um demônio, é um demônio! Aquela bruxa invocou algo do inferno! Senhor, tende piedade de nós…"
  },
  AvgDialog_149756_Content_4 = {
    Text = "O fogo ainda não foi aceso, mas as árvores secas já se contorceram, com aquela postura desesperada, como se até a luz do dia que retorna fosse uma queimadura insuportável."
  },
  AvgDialog_149756_Content_40 = {
    Text = "Seu coração batia freneticamente — você sabia quem ele era, sabia que sua vida não terminaria hoje, que era apenas um prelúdio, um interlúdio, para recebê-lo."
  },
  AvgDialog_149756_Content_41 = {
    Text = "Tomada por um ardor cheio de esperança, você se contorceu desesperadamente, gemendo chamados, ansiosa para que ele olhasse para você, quase esquecendo as correntes escaldantes."
  },
  AvgDialog_149756_Content_43 = {
    Text = "Uma mão enluvada puxou você para fora da fogueira, suas pernas cederam sem controle e você caiu no chão, tossindo e vomitando ao mesmo tempo, lágrimas e muco misturados."
  },
  AvgDialog_149756_Content_44 = {
    Text = "<Shake:Toss toss toss toss toss toss toss——!! Espe, toss toss toss toss, espere! Não vá embora!>"
  },
  AvgDialog_149756_Content_45 = {
    Text = "Antes que ele se virasse para partir, você agarrou apressadamente sua capa."
  },
  AvgDialog_149756_Content_46 = {
    Text = "Parecendo não ter previsto seu gesto, o capuz dele deslizou para um lado, revelando o rosto de um jovem."
  },
  AvgDialog_149756_Content_47 = {Text = "Solte."},
  AvgDialog_149756_Content_48 = {
    Text = "Você é esperto, sabe distinguir uma ameaça de um aviso. Ao se lembrar da morte do padre pouco antes, você se encolheu."
  },
  AvgDialog_149756_Content_49 = {
    Text = "Mas então você viu o rosto dele. Sem dúvida, o nobre cavaleiro das histórias deveria ser exatamente assim. Ele certamente veio por você, e você até achou aquele par de sobrancelhas e olhos estranhamente familiar."
  },
  AvgDialog_149756_Content_5 = {
    Text = "<BigShake:Não se deixe enganar pela sua aparência!> O rosto de criança é apenas um disfarce — dentro daquele corpo mora um demônio. Os seus pecados, o Senhor viu todos."
  },
  AvgDialog_149756_Content_50 = {
    Text = "Claro, você certamente o viu em algum lugar antes — em sonhos, em maldições, ou em profecias. Do contrário, como explicar a coragem que surgiu do nada?"
  },
  AvgDialog_149756_Content_51 = {
    Text = "<Shake:Não… cof cof cof, você não pode ir embora.>"
  },
  AvgDialog_149756_Content_52 = {Text = "Por que?"},
  AvgDialog_149756_Content_53 = {
    Text = "Porque, cof cof, porque você veio me salvar, como pode me deixar para trás?"
  },
  AvgDialog_149756_Content_54 = {
    Text = "Você já foi salva. Volte para a vida que lhe pertence."
  },
  AvgDialog_149756_Content_55 = {
    Text = "Não há vida alguma que me pertença aqui. Há monstros por toda parte, que só sabem capturar e devorar pessoas — você já viu isso."
  },
  AvgDialog_149756_Content_56 = {
    Text = "Não é problema meu."
  },
  AvgDialog_149756_Content_57 = {
    Text = "Como pode não ser problema seu? Eu estive esperando por você o tempo todo."
  },
  AvgDialog_149756_Content_58 = {
    Text = "Esperando por mim? Você… você me conhece?"
  },
  AvgDialog_149756_Content_59 = {
    Text = "Claro. Você é o meu cavaleiro."
  },
  AvgDialog_149756_Content_6 = {
    Text = "Ela é uma ladra, uma mentirosa, uma serva das trevas. A desgraça flui de sua boca, o veneno contaminou poços e rios, e assim o gado tombou nos currais e os piedosos adoeceram."
  },
  AvgDialog_149756_Content_60 = {
    Text = "Choque, confusão, agitação, angústia — inúmeras expressões invadiram o rosto dele ao mesmo tempo. Ele te jogou para longe de repente, como se estivesse se esquivando de uma cobra venenosa, e encostou a espada curta manchada de sangue no seu pescoço."
  },
  AvgDialog_149756_Content_61 = {
    Text = "Quem é você!"
  },
  AvgDialog_149756_Content_62 = {
    Text = "Eu, eu sou uma princesa! Isso mesmo, sou uma princesa, fui capturada por monstros e fiquei esperando você vir me salvar!"
  },
  AvgDialog_149756_Content_63 = {
    Text = "Não desacredite. Se eu não fosse uma princesa, por que os céus teriam enviado um cavaleiro para me salvar?"
  },
  AvgDialog_149756_Content_64 = {Text = "..."},
  AvgDialog_149756_Content_65 = {
    Text = "Ele embainhando a espada curta, levantou-se e caminhou para o interior da floresta densa, sem dizer mais uma palavra a você."
  },
  AvgDialog_149756_Content_66 = {
    Text = "Espere, para onde você vai? Eu, cof, eu vou com você."
  },
  AvgDialog_149756_Content_67 = {
    Text = "<Shake:Pare! Cof cof, em nome da princesa, eu ordeno que você pare!>"
  },
  AvgDialog_149756_Content_68 = {
    Text = "Embora ele fosse surpreendentemente ágil, você tinha a vantagem de conhecer aquela floresta como a palma da sua mão."
  },
  AvgDialog_149756_Content_69 = {
    Text = "Além disso, você não tem para onde ir, só pode seguir em frente, seguir em frente, mesmo que caia aqui na floresta e se torne alimento para as feras."
  },
  AvgDialog_149756_Content_7 = {
    Text = "Todos vocês são testemunhas — quantas vezes ela entrou na floresta, desapareceu, e voltou como se nada tivesse acontecido? Isso é prova de que pratica feitiçaria!"
  },
  AvgDialog_149756_Content_70 = {
    Text = "<Shake:Hah… hah… espere, eu… eu conheço as regras.>"
  },
  AvgDialog_149756_Content_71 = {
    Text = "Tenho um lugar para ir. Leve-me até lá e receberá honra e recompensa."
  },
  AvgDialog_149756_Content_72 = {
    Text = "Não preciso."
  },
  AvgDialog_149756_Content_73 = {
    Text = "Precisa, sim. Pelo menos agora, você precisa de alguém para guiá-lo para fora daqui, não é?"
  },
  AvgDialog_149756_Content_74 = {
    Text = "Ele não respondeu, mas aos poucos foi parando."
  },
  AvgDialog_149756_Content_75 = {
    Text = "Para onde você vai?"
  },
  AvgDialog_149756_Content_76 = {
    Text = "Hm… ah, a Ilha das Maçãs, já ouviu falar? Um paraíso onde não é preciso cultivar, onde não se adoece e não há inverno — é para lá que vou."
  },
  AvgDialog_149756_Content_77 = {
    Text = "Nunca ouvi falar. Onde fica?"
  },
  AvgDialog_149756_Content_78 = {
    Text = "A fada não me disse a direção, mas disse que eu a encontraria um dia, assim como ela. Podemos caminhar e procurar ao mesmo tempo. Afinal, as grandes aventuras são sempre repletas de desafios, não é?"
  },
  AvgDialog_149756_Content_79 = {
    Text = "A capa negra se fundiu com a escuridão da noite. Ele estava parado atrás de um arbusto desgrenhado, com o rosto indistinto."
  },
  AvgDialog_149756_Content_8 = {
    Text = "<SmallShake:A praga… a bruxa… é isso, foi por causa da bruxa… a maldição da bruxa…>"
  },
  AvgDialog_149756_Content_80 = {
    Text = "Você se aproximou dele muito devagar, com extremo cuidado, como se temesse assustar um lobo selvagem."
  },
  AvgDialog_149756_Content_81 = {
    Text = "Pare. Fique aí. Não dê mais um passo."
  },
  AvgDialog_149756_Content_82 = {
    Text = "Guie o caminho."
  },
  AvgDialog_149756_Content_83 = {
    Text = "Isso significa que você aceitou, valoroso cavaleiro?"
  },
  AvgDialog_149756_Content_84 = {Text = "..."},
  AvgDialog_149756_Content_85 = {
    Text = "Não sou cavaleiro."
  },
  AvgDialog_149756_Content_86 = {
    Text = "É sim. A partir de agora, você é meu leal cavaleiro."
  },
  AvgDialog_149756_Content_87 = {
    Text = "Cavaleiros cumprem suas promessas. Até chegarmos à Ilha das Maçãs, você deve me proteger. Deve caminhar à frente, limpar os espinhos e as trepadeiras para mim, e se algum monstro nos perseguir, você deve espantá-lo, e ainda…"
  },
  AvgDialog_149756_Content_88 = {
    Text = "Para onde você vai? Ainda não fez o juramento! Se ousar mentir e enganar sua princesa, será capturado e devorado por monstros. Jure primeiro."
  },
  AvgDialog_149756_Content_89 = {
    Text = "Ei! Não vá embora, espere por mim — eu conheço o caminho!"
  },
  AvgDialog_149756_Content_9 = {
    Text = "Uma bruxa com menos de dez anos? Nem um louco seria capaz de inventar uma mentira dessas."
  },
  AvgDialog_149757_Content_1 = {Text = "Túmulo"},
  AvgDialog_149757_Content_10 = {
    Text = "<Shake:Hah, hah… onde você está… meu cavaleiro…>"
  },
  AvgDialog_149757_Content_11 = {
    Text = "Você se lembrou do rumor e ficou ainda mais preocupada. Não podia deixar que seu único cavaleiro fosse derrotado pelo demônio. Você guardaria o nome dele na memória — e já havia guardado."
  },
  AvgDialog_149757_Content_12 = {
    Text = "Ogier… é isso, Ogier! Onde você está! <Big:O — gi — er —>"
  },
  AvgDialog_149757_Content_13 = {
    Text = "Um grito de dor atravessou a cortina de chuva, mais parecido com o urro de um animal ferido do que com uma voz humana. Você imediatamente correu em direção ao som."
  },
  AvgDialog_149757_Content_14 = {
    Text = "Pare de se esconder! Já estou te vendo!"
  },
  AvgDialog_149757_Content_15 = {
    Text = "Vá embora! Não, ha, não chegue perto!!"
  },
  AvgDialog_149757_Content_16 = {
    Text = "A chama da lanterna tremia, incapaz de dissipar a escuridão que se fechava por todos os lados. Seu cavaleiro estava encurralado, as costas tensas como um arco prestes a disparar."
  },
  AvgDialog_149757_Content_17 = {
    Text = "Cale a boca! Eu não esqueci! Isso não é — não, eu nunca — eu não vou esquecer!"
  },
  AvgDialog_149757_Content_18 = {
    Text = "<Shake:Vou me vingar por eles… preciso me vingar por eles… olho por olho, dente por dente…>"
  },
  AvgDialog_149757_Content_19 = {
    Text = "Não, não vai, você está mentindo! A princesa não diria isso, a princesa, a princesa ela —"
  },
  AvgDialog_149757_Content_2 = {
    Text = "Você já ouviu alguém dizer que o nome de cada pessoa é um feitiço."
  },
  AvgDialog_149757_Content_20 = {
    Text = "<Big:Aaah —!!>"
  },
  AvgDialog_149757_Content_21 = {
    Text = "As palavras confusas foram interrompidas por um grito de agonia, como se alguém o tivesse atravessado com uma lança no peito. Ele cambaleou e caiu de joelhos, mas a sombra atrás dele permanecia de pé, como uma armadura, como uma jaula."
  },
  AvgDialog_149757_Content_22 = {
    Text = "Você sentiu um pavor repentino. Sabia que, se não o impedisse agora, a sombra se tornaria o homem, e o homem se afundaria na sombra."
  },
  AvgDialog_149757_Content_23 = {
    Text = "Acorde! Pare de ouvir o que ela diz, sua princesa está aqui!!"
  },
  AvgDialog_149757_Content_24 = {
    Text = "<Shake:… @1@2Princesa… eu a desapontei?>"
  },
  AvgDialog_149757_Content_25 = {
    Text = "<Shake:Eu não fugi, foi a senhora quem me mandou —> Não, não era isso que eu quis dizer. Fui eu quem a decepcionei, não tenho o direito de implorar por perdão."
  },
  AvgDialog_149757_Content_26 = {
    Text = "<Shake:Vergonha… vergonha vergonha vergonha vergonha vergonha vergonha vergonha vergonha, a vergonha é a única coisa que possuo…>"
  },
  AvgDialog_149757_Content_27 = {
    Text = "<Shake:Não sou um cavaleiro, eu sou… eu sou…>"
  },
  AvgDialog_149757_Content_28 = {
    Text = "<Red:Quem?>"
  },
  AvgDialog_149757_Content_29 = {
    Text = "No momento de confusão, ele ergueu o rosto em sua direção — se é que aquilo ainda podia ser chamado de rosto."
  },
  AvgDialog_149757_Content_3 = {
    Text = "Se por descuido o nome se perde — seja por esquecimento próprio ou por ser esquecido pelos outros — é como uma ovelha que se separa do rebanho: perde a proteção e fica à mercê do diabo."
  },
  AvgDialog_149757_Content_30 = {
    Text = "As sombras corroeram sua carne, deixando rastros como trilhas de lesma, seu semblante estava manchado e em decomposição, e das feridas brotava um lodo negro e viscoso."
  },
  AvgDialog_149757_Content_31 = {
    Text = "De quem ele esperava uma resposta? A chuva fria congelou seus lábios e sua língua, você ficou parado, entorpecido na lama, enquanto um tremor tardio percorria seus membros."
  },
  AvgDialog_149757_Content_32 = {
    Text = "…E-espera, eu sei! Você é —"
  },
  AvgDialog_149757_Content_33 = {
    Text = "<BigShake:Não! Ogier!!>"
  },
  AvgDialog_149757_Content_34 = {
    Text = "O lodo negro jorrou de seu peito, seu cavaleiro esgotou suas forças no silêncio e desabou, como uma casca vazia abandonada, enquanto as sombras o cercavam, rindo e chorando ao mesmo tempo."
  },
  AvgDialog_149757_Content_35 = {
    Text = "Você testemunhou como uma pessoa se despedaça por completo."
  },
  AvgDialog_149757_Content_36 = {
    Text = "Ogier! Você é Ogier! Eu sei, eu me lembrei! O demônio não pode te machucar, eu já me lembrei!"
  },
  AvgDialog_149757_Content_37 = {
    Text = "Acorde! Está me ouvindo? Acorde logo, ainda não chegamos! Você vai ficar bem, a Ilha das Maçãs — o demônio não pode ir até lá, quando chegarmos à Ilha das Maçãs ficará tudo bem! Levante-se, levante-se logo!"
  },
  AvgDialog_149757_Content_38 = {
    Text = "A tempestade transformou a floresta em um pântano podre, você gritou com todas as suas forças, puxou, chorou, mas só conseguiu afundar ainda mais. Você não sabia para onde mais poderia fugir."
  },
  AvgDialog_149757_Content_39 = {
    Text = "Então era assim que o mundo morria… soterrado vivo pelo desespero."
  },
  AvgDialog_149757_Content_4 = {
    Text = "Talvez o seu cavaleiro, assim como você, tenha tido tudo roubado por monstros — ele até perdeu mais do que você, sem conseguir preservar sequer o próprio nome."
  },
  AvgDialog_149757_Content_40 = {
    Text = "<SmallShake:Tosse… tosse tosse…>"
  },
  AvgDialog_149757_Content_41 = {
    Text = "<SmallShake:Quando a chuva parar… ir ao cemitério…>"
  },
  AvgDialog_149757_Content_42 = {
    Text = "Ogier! Você ainda está vivo!"
  },
  AvgDialog_149757_Content_43 = {
    Text = "Espera, ir ao cemitério para quê? Você… você ainda está vivo ou não?"
  },
  AvgDialog_149757_Content_44 = {
    Text = "<Shake:Ir ao cemitério… enterrar… não há tempo… preciso ir enterrar…>"
  },
  AvgDialog_149757_Content_45 = {
    Text = "Quem? Você quer ir enterrar quem?"
  },
  AvgDialog_149757_Content_46 = {Text = "..."},
  AvgDialog_149757_Content_47 = {
    Text = "Ele parou de falar e olhou fixamente para cima, onde todos os pântanos terminam, onde todas as memórias e esquecimentos se dissolvem, onde a chuva cai e o ar fica cada vez mais rarefeito."
  },
  AvgDialog_149757_Content_48 = {
    Text = "Mas vocês jamais conseguirão alcançar o céu, então só lhes resta caminhar em direção ao cemitério. É o lugar mais próximo do fim."
  },
  AvgDialog_149757_Content_49 = {
    Text = "Tanto dinheiro por um simples pedaço de terra vazia…"
  },
  AvgDialog_149757_Content_5 = {
    Text = "E assim o <Red:demônio> à espreita mostrou suas garras."
  },
  AvgDialog_149757_Content_50 = {
    Text = "Se soubesses antes o quanto custa o lugar onde os monstros enterram os seus, certamente não terias vindo."
  },
  AvgDialog_149757_Content_51 = {
    Text = "A chuva caiu por três dias seguidos e só então deu uma breve trégua. Teu cavaleiro ficou gravemente ferido no confronto com o demônio e só pôde te enviar ao cemitério em seu lugar, para enterrar o embrulho que carregava consigo. Ele disse que eram os pertences de alguém."
  },
  AvgDialog_149757_Content_52 = {
    Text = "A lápide estava completamente em branco, sem nome algum. Não sabes para quem ela foi erguida."
  },
  AvgDialog_149757_Content_53 = {
    Text = "Uma vela, um pente, um boneco de pedra, um pergaminho…"
  },
  AvgDialog_149757_Content_54 = {
    Text = "O embrulho era leve, com poucas coisas dentro, mas todas bastante danificadas. Por mais que tentasses, não conseguiste encontrar uma resposta. Teu cavaleiro também era um mistério para ti — não sabes nada sobre ele."
  },
  AvgDialog_149757_Content_55 = {
    Text = "…Vais enterrar o cálice sagrado também?"
  },
  AvgDialog_149757_Content_56 = {
    Text = "Ei, pequena ali, de que família és? O que estás fazendo aqui a espreitar assim?"
  },
  AvgDialog_149757_Content_57 = {
    Text = "Monstros vestidos de armadura cruzavam o cemitério quando um deles parou de repente, e toda a fila parou junto. Estavam enfileirados com perfeita uniformidade, sem qualquer diferença entre si, como uma enorme centopeia de muitos segmentos."
  },
  AvgDialog_149757_Content_58 = {
    Text = "Ficaste surda? Perguntei de onde— ei, por que estás a correr? Peguem-na!"
  },
  AvgDialog_149757_Content_59 = {
    Text = "Soltem! Me soltem! Não fiz nada de errado, comprei este terreno!"
  },
  AvgDialog_149757_Content_6 = {
    Text = "Onde… onde… não é nessa direção?"
  },
  AvgDialog_149757_Content_60 = {
    Text = "Compraste? Ha, então explica: a lápide não tem nome nenhum. De quem é este túmulo?"
  },
  AvgDialog_149757_Content_61 = {
    Text = "Eu... eu..."
  },
  AvgDialog_149757_Content_62 = {
    Text = "Senhores, este é o cemitério da paróquia. A criança de facto comprou o terreno — está tudo registado no livro de registos."
  },
  AvgDialog_149757_Content_63 = {
    Text = "Quanto ao nome, a peste já chegou. Todos os dias há pessoas que desaparecem. Acaso faltam lápides sem nome?"
  },
  AvgDialog_149757_Content_64 = {
    Text = "A expressão dos monstros mudou. Trocaram alguns olhares e foram embora apressados, como se temessem ser contaminados por algo. Naqueles olhos, reconheceste um medo familiar."
  },
  AvgDialog_149757_Content_65 = {Text = "Praga?"},
  AvgDialog_149757_Content_66 = {
    Text = "Sim, a cruel peste, a terrível peste. Fazer o homem esquecer requer apenas um pouco de tempo; fazer a pedra esquecer, porém, requer transformá-la em areia."
  },
  AvgDialog_149757_Content_67 = {
    Text = "Há cada vez mais pedras que esquecem. Os velhos ficam tão vazios quanto crianças. Não temos mais histórias."
  },
  AvgDialog_149757_Content_68 = {
    Text = "Tu… não achas que isto é uma maldição? Por causa de alguma bruxa, ou de outra coisa qualquer."
  },
  AvgDialog_149757_Content_69 = {
    Text = "Maldição, praga, punição do Senhor, ou vingança do cavaleiro da morte, qual a diferença? Não podemos fazer nada, criança, só podemos olhar para o presente, o presente é tudo o que podemos ter, sempre foi."
  },
  AvgDialog_149757_Content_7 = {
    Text = "A noite sem lua era muito escura, e a floresta densa parecia não ter fim. Você carregava a Lanterna no colo, procurando por todos os lados os rastros da fuga desesperada."
  },
  AvgDialog_149757_Content_70 = {
    Text = "Vá para casa, está quase anoitecendo."
  },
  AvgDialog_149757_Content_71 = {
    Text = "Espere, cavaleiro da morte? O que é isso?"
  },
  AvgDialog_149757_Content_72 = {
    Text = "Uma lenda. Aquela guerra foi um erro, eles gritavam para erradicar a praga, mas só fizeram com que ela chegasse mais rápido, criaram um monstro."
  },
  AvgDialog_149757_Content_73 = {
    Text = "Ele se esconde nas sombras das árvores, dos barcos, das paredes de pedra e dos pássaros em voo, movendo-se de um lugar para outro, intocável pela luz do sol."
  },
  AvgDialog_149757_Content_74 = {
    Text = "Seu sangue é negro como breu, seu coração arde com um fogo sombrio, seus olhos brilham como luzes nas profundezas de um pântano, e por onde passa, deixa sombras que dividem o dia."
  },
  AvgDialog_149757_Content_75 = {
    Text = "Ele é a continuação daquela guerra, a soma do rancor dos mortos, aparece apenas à noite para eliminar seus inimigos. Ele nunca esquece, nunca descuida, e o motivo de sua vinda é óbvio — nosso senhor, o país que um dia lhe pertenceu."
  },
  AvgDialog_149757_Content_76 = {
    Text = "O quê? Você está dizendo que o senhor é seu inimigo, e ele veio até aqui… por vingança?"
  },
  AvgDialog_149757_Content_77 = {
    Text = "Claro, todos nós sabemos, e o senhor também sabe. Por que mais a cidade de repente teria tantos soldados patrulhando?"
  },
  AvgDialog_149757_Content_78 = {
    Text = "Todos estão esperando por ele."
  },
  AvgDialog_149757_Content_79 = {
    Text = "A chuva voltou a cair, e as ruas parecem um rio em movimento."
  },
  AvgDialog_149757_Content_8 = {
    Text = "Antes de ser engolido pela sombra, ele mandou você ir embora, mas como poderia uma princesa ficar sem seu cavaleiro? Você tentou resgatá-lo, mas ele se soltou da sua mão, atravessou a janela e saltou do sótão, desaparecendo na floresta selvagem além dos limites da mansão."
  },
  AvgDialog_149757_Content_80 = {
    Text = "Você carrega todos os pertences no colo, correndo freneticamente pelos becos estreitos, desviando por pouco de uma guarda após a outra, em direção ao galpão de palha onde vocês se escondem."
  },
  AvgDialog_149757_Content_81 = {
    Text = "<Shake:Mais rápido, mais rápido, volte e avise-o…>"
  },
  AvgDialog_149757_Content_82 = {
    Text = "O monstro na boca dos monstros, sem dúvida é o seu cavaleiro — seus assassinatos descarados finalmente chegaram aos ouvidos do senhor, e dizem que esta noite os guardas vasculharão cada canto da cidade."
  },
  AvgDialog_149757_Content_83 = {
    Text = "Ainda há tempo, os portões ainda não fecharam, basta ser um pouco mais rápido…"
  },
  AvgDialog_149757_Content_84 = {
    Text = "<Big:Ogier! Corra, eles estão vindo—>"
  },
  AvgDialog_149757_Content_85 = {
    Text = "O abrigo estreito estava erguido no fundo de um beco sem saída, cercado por pilhas de sacos de estopa que ainda assim não conseguiam conter a lama que escorria por todo lado. Você se lança em direção à figura deitada no canto mais fundo e arranca sua capa — mas só a capa."
  },
  AvgDialog_149757_Content_86 = {
    Text = "Dentro do abrigo não havia nada além de feno, seu cavaleiro havia desaparecido."
  },
  AvgDialog_149757_Content_9 = {
    Text = "A tempestade encobriu os galhos quebrados e as pegadas deixadas para trás. A paisagem ao redor era toda igual, seus passos foram ficando cada vez mais lentos, até que você parou, perdida."
  },
  AvgDialog_15363_Content_1 = {
    Text = "Morte da Sra. Coral"
  },
  AvgDialog_15363_Content_10 = {
    Text = "As pessoas aglomeravam-se tão densamente ao redor que nem uma gota de água passaria. Incontáveis flashes de câmaras dispararam em uníssono, e uma cacofonia de conversas subia e descia — até que um funcionário puxou a cobertura num único movimento rápido."
  },
  AvgDialog_15363_Content_11 = {
    Text = "Isto é... meu Deus."
  },
  AvgDialog_15363_Content_12 = {
    Text = "...Inacreditável."
  },
  AvgDialog_15363_Content_13 = {
    Text = "Como se um interruptor tivesse sido acionado, a multidão silenciou por conta própria. O salão outrora barulhento e animado de repente pareceu quase vazio."
  },
  AvgDialog_15363_Content_14 = {
    Text = "Você lutou para abrir caminho pela multidão, finalmente avistando a obra cercada no centro."
  },
  AvgDialog_15363_Content_15 = {Text = "..."},
  AvgDialog_15363_Content_16 = {
    Text = "Era Sanga. Ela havia perdido toda cor e emoção, transformada numa escultura de coral branco puro."
  },
  AvgDialog_15363_Content_17 = {
    Text = "A luz brilhante do dia refratava-se através da cúpula de vidro imaculado acima, envolvendo-a num véu suave de luz dourada pálida."
  },
  AvgDialog_15363_Content_18 = {
    Text = "Você olhou para a placa de latão no pedestal da escultura. Acima dela, em escrita elegante, estava gravado o nome da escultura: <Red:\"Filha do Coral Sem Nome\">."
  },
  AvgDialog_15363_Content_19 = {
    Text = "Coral Sem Nome..."
  },
  AvgDialog_15363_Content_2 = {
    Text = "Caro Monsieur Claudel:\n\nMuito aconteceu recentemente. Peço perdão pela demora na minha resposta.\n\nApós a partida da Menina Sanga, o Monsieur Agosto nunca mais conseguiu produzir obras notáveis.\nSob a pressão da opinião pública, anunciou a suspensão indefinida da sua carreira de escultor.\nRecebeu o castigo que merecia, mas não consigo alegrar-me — <Yellow:o paradeiro da Menina Sanga continua desconhecido.>"
  },
  AvgDialog_15363_Content_20 = {
    Text = "Você ficou olhando para a sequência de palavras em transe, sua consciência parecendo balançar e se contorcer junto com aquelas curvas elegantes das letras..."
  },
  AvgDialog_15363_Content_21 = {
    Text = "Você ergueu a mão para esfregar os olhos, apenas para descobrir que, em algum momento, camadas de branco áspero e opaco haviam começado a se espalhar pelos seus dedos."
  },
  AvgDialog_15363_Content_22 = {Text = "?!"},
  AvgDialog_15363_Content_23 = {
    Text = "A névoa de coral branco continuou a se propagar dos seus dedos, cobrindo todo o seu corpo pouco a pouco, inundando rapidamente todo o salão de exposições, e então—"
  },
  AvgDialog_15363_Content_24 = {Text = "—!!"},
  AvgDialog_15363_Content_25 = {
    Text = "Você e o salão de exposições se estilhaçaram simultaneamente em incontáveis fragmentos brancos, mergulhando nas profundezas ilimitadas do oceano."
  },
  AvgDialog_15363_Content_26 = {
    Text = "Em meio a incontáveis esculturas brancas e corais, sob a luz tranquila da manhã, as ruínas brancas de um palácio erguiam-se imponentes."
  },
  AvgDialog_15363_Content_27 = {
    Text = "Peixes de todas as cores passavam velozes pelos arcos inclinados e corredores das ruínas, aproveitando seus agradáveis momentos de lazer."
  },
  AvgDialog_15363_Content_28 = {
    Text = "As ruínas inteiras pareciam ter sido abandonadas nas sombras do tempo, longe da Corrosão do mundo mundano, evitando o tumulto da multidão."
  },
  AvgDialog_15363_Content_29 = {
    Text = "Quando você vir aqueles Milagres... vai me entender..."
  },
  AvgDialog_15363_Content_3 = {
    Text = "<Yellow:Amanhã irei à exposição do Salon da Cité para procurar as \"respostas\" de que a Menina Sanga falou.>\nDesejo-me sorte.\n\nCamille@1\nA.F.2@1, setembro"
  },
  AvgDialog_15363_Content_30 = {
    Text = "Este é... o Milagre que você viu, Senhorita Sanga?"
  },
  AvgDialog_15363_Content_31 = {
    Text = "Você flutuou pela água do mar morna, contemplando tudo diante de si com fascínio e perplexidade."
  },
  AvgDialog_15363_Content_32 = {
    Text = "Saiam da frente, me deixem passar!!"
  },
  AvgDialog_15363_Content_33 = {
    Text = "<Big:Deixe-me passar!!>"
  },
  AvgDialog_15363_Content_34 = {
    Text = "O clamor da comoção arrastou você de volta à realidade."
  },
  AvgDialog_15363_Content_35 = {
    Text = "Um velho esfarrapado rompeu as camadas de Grilhões de segurança e avançou em sua direção, agarrando sua mão com uma força mortal."
  },
  AvgDialog_15363_Content_36 = {
    Text = "Você também viu, não foi? O mar profundo, o palácio, todas aquelas ilusões caóticas..."
  },
  AvgDialog_15363_Content_37 = {Text = "?!"},
  AvgDialog_15363_Content_38 = {
    Text = "Essa mulher maligna, Ela é uma ladra..."
  },
  AvgDialog_15363_Content_39 = {
    Text = "O velho murmurava incessantemente. Você fitou o rosto oculto sob a aba larga de seu chapéu e a barba espessa, e de repente vislumbrou algo familiar."
  },
  AvgDialog_15363_Content_4 = {
    Text = "Exposição do Salon da Cité\nDia de Abertura"
  },
  AvgDialog_15363_Content_40 = {
    Text = "...Sr. Agosto?!"
  },
  AvgDialog_15363_Content_41 = {
    Text = "Chiado, é realmente ele... Meu Deus! O que aconteceu com ele?"
  },
  AvgDialog_15363_Content_42 = {
    Text = "Ele faliu há muito tempo, você não ouviu? Após o fiasco da \"Musa Trágica\", ele investiu pesadamente em vários projetos, mas nenhum deles vendeu"
  },
  AvgDialog_15363_Content_43 = {
    Text = "O governo desconfia da reputação dele agora e parou de lhe dar encomendas. Ele provavelmente enlouqueceu de tanto estresse..."
  },
  AvgDialog_15363_Content_44 = {
    Text = "A multidão observava Agosto a uma distância cautelosa, chocada e amedrontada."
  },
  AvgDialog_15363_Content_45 = {
    Text = "Agosto soltou sua mão. Ele mancou em direção à escultura, seus olhos transbordando de um ódio que não podia mais ser contido."
  },
  AvgDialog_15363_Content_46 = {
    Text = "Hah... Achou que morrer apagaria tudo o que você fez?"
  },
  AvgDialog_15363_Content_47 = {
    Text = "Você enganou Todos... Meu talento, meu Discernimento e minha reputação foram todos tomados por você."
  },
  AvgDialog_15363_Content_48 = {
    Text = "Estou arruinado, completamente arruinado. E você? Sentada aqui à vontade, banhando-se no Olhar para cima de todos, esperando que a consagrem como um clássico..."
  },
  AvgDialog_15363_Content_49 = {Text = "..."},
  AvgDialog_15363_Content_5 = {
    Text = "Ouviste? O Sr. Agosto veio expor as suas esculturas outra vez."
  },
  AvgDialog_15363_Content_50 = {
    Text = "Diante das maldições histéricas de seu antigo mestre, a escultura permaneceu em silêncio, sua expressão indiferente sem diminuir nem um pouco."
  },
  AvgDialog_15363_Content_51 = {
    Text = "Agosto não aguentava mais. Ele avançou ferozmente contra a escultura."
  },
  AvgDialog_15363_Content_52 = {
    Text = "Essa expressão de novo, essa zombaria de novo...\""
  },
  AvgDialog_15363_Content_53 = {
    Text = "Demônio... Demônio! <Big:Vou arrancar sua máscara!>"
  },
  AvgDialog_15363_Content_6 = {
    Text = "Agosto, aquele escultor? Ele não desapareceu depois de ser atingido por aquelas Dúvidas sobre plágio? Pensei que nunca mais mostraria a cara."
  },
  AvgDialog_15363_Content_7 = {
    Text = "Mas estou bastante curiosa. Sem aquela aprendiz dele, o que é que ele poderá ter criado agora..."
  },
  AvgDialog_15363_Content_8 = {
    Text = "A cerimónia de abertura da exposição do Salon estava repleta de visitantes."
  },
  AvgDialog_15363_Content_9 = {
    Text = "A obra de Agosto encontrava-se no centro do salão de exposições, coberta por camadas de tecido pesado, despertando a curiosidade de inúmeros espectadores."
  },
  AvgDialog_15364_Content_1 = {Text = "UUGHH!"},
  AvgDialog_15364_Content_10 = {
    Text = "Exposição do Salão Cité\nNoite de Abertura"
  },
  AvgDialog_15364_Content_11 = {
    Text = "Quando a última Trava pesada se encaixou, o salão de exposições mergulhou em um silêncio escuro como breu."
  },
  AvgDialog_15364_Content_12 = {
    Text = "Você saiu das sombras no canto e se colocou diante Dela mais uma vez."
  },
  AvgDialog_15364_Content_13 = {
    Text = "Livre do clamor diurno, este era o momento perfeito para conversar."
  },
  AvgDialog_15364_Content_14 = {
    Text = "Srta. Sanga, o Sr. Agosto foi levado hoje. Ele disse...\nVocê enganou Todos."
  },
  AvgDialog_15364_Content_15 = {
    Text = "\"Todos\" aqui me inclui?"
  },
  AvgDialog_15364_Content_16 = {Text = "..."},
  AvgDialog_15364_Content_17 = {
    Text = "Você uma vez prometeu que iria para casa comigo. Isso era verdade?"
  },
  AvgDialog_15364_Content_18 = {Text = "..."},
  AvgDialog_15364_Content_19 = {
    Text = "A escultura permaneceu silenciosa como sempre. Mesmo que as vidas de Todos tivessem sido desviadas por causa Dela, Ela nunca sequer baixou os olhos de seu olhar distante."
  },
  AvgDialog_15364_Content_2 = {
    Text = "Me soltem, quem vocês deveriam prender é Ela, é Ela—"
  },
  AvgDialog_15364_Content_20 = {
    Text = "O luar atravessava as janelas de vidro do salão de exposições, envolvendo-a em uma névoa de luz branca pálida."
  },
  AvgDialog_15364_Content_21 = {
    Text = "<Red:Sigam meu olhar...>"
  },
  AvgDialog_15364_Content_22 = {
    Text = "Siga o olhar... Pode ser?!"
  },
  AvgDialog_15364_Content_23 = {
    Text = "Você ficou na ponta dos pés, apenas para descobrir que, sob o luar, os olhos outrora distantes e desfocados da escultura há muito haviam mudado, cristalizando-se em algo concreto e intensamente emocional."
  },
  AvgDialog_15364_Content_24 = {
    Text = "O olhar Dela sempre esteve fixo na distância."
  },
  AvgDialog_15364_Content_25 = {
    Text = "Você se virou, seguindo a linha de visão Dela."
  },
  AvgDialog_15364_Content_26 = {
    Text = "No instante em que seus olhos vagaram, o salão de exposições sob seus pés desapareceu como por Milagre."
  },
  AvgDialog_15364_Content_27 = {
    Text = "Em seu lugar se estendia um mar sem fim e uma vasta extensão de areia branca."
  },
  AvgDialog_15364_Content_28 = {
    Text = "O estrondo de um trovão distante rolou em sua direção enquanto as marés Surgiam violentamente, avançando na sua direção."
  },
  AvgDialog_15364_Content_29 = {
    Text = "Este era o mar que você e Sanga haviam visitado juntas."
  },
  AvgDialog_15364_Content_3 = {
    Text = "Sr. Agosto, recebemos uma denúncia de que o seu comportamento causou sérias perturbações à ordem da exposição do salão. Por favor, venha conosco agora."
  },
  AvgDialog_15364_Content_4 = {
    Text = "Não, não..."
  },
  AvgDialog_15364_Content_5 = {
    Text = "A cena estava em completo Caos. A multidão vindo de todas as direções separou você completamente de Agosto. Você Apenas pôde observar enquanto ele era arrastado à força pela polícia."
  },
  AvgDialog_15364_Content_6 = {
    Text = "Não comemore cedo demais... Uma dia, você vai acabar igual a mim..."
  },
  AvgDialog_15364_Content_7 = {
    Text = "Heh... Heheheh..."
  },
  AvgDialog_15364_Content_8 = {
    Text = "A ordem foi finalmente restaurada no salão de exposições."
  },
  AvgDialog_15364_Content_9 = {
    Text = "A última risada trêmula e neurótica de Agosto persistiu como ondulações que se dissipavam, mal perceptíveis no vasto salão vazio."
  },
  AvgDialog_15365_Content_1 = {
    Text = "Meio do mar"
  },
  AvgDialog_15365_Content_10 = {
    Text = "Então é você.\nDesculpe, eu te acordei quando me levantei?"
  },
  AvgDialog_15365_Content_11 = {
    Text = "Em vez de se preocupar em me acordar, você deveria se preocupar mais em perturbar aqueles <Blue:velhos companheiros dormindo debaixo da terra>."
  },
  AvgDialog_15365_Content_12 = {
    Text = "Você ergueu o queixo para apontar para a sepultura diante dela, escavada quase trinta centímetros de profundidade."
  },
  AvgDialog_15365_Content_13 = {
    Text = "Parece que você está procurando algo. Precisa de ajuda?"
  },
  AvgDialog_15365_Content_14 = {
    Text = "Está tudo bem, eu já o encontrei."
  },
  AvgDialog_15365_Content_15 = {
    Text = "Sanga abriu a mão na sua direção com um sorriso radiante. Estava coberta por um líquido viscoso e negro como breu—"
  },
  AvgDialog_15365_Content_16 = {
    Text = "Lama Corrosiva. Você não poderia estar mais familiarizado com isso."
  },
  AvgDialog_15365_Content_17 = {
    Text = "Viu? Sob o luar, elas emitem um estranho tom azulado. Durante o dia, assumem uma aparência completamente diferente..."
  },
  AvgDialog_15365_Content_18 = {
    Text = "Este é o material de escultura mais perfeito que já vi."
  },
  AvgDialog_15365_Content_19 = {Text = "..."},
  AvgDialog_15365_Content_2 = {
    Text = "Caro Sr. Claud:\n\nA Srta. Sanga não recusou o pedido de voltar para casa, mas ela espera que eu possa lhe dar algum tempo.\nEla disse: <Yellow:Depois que a exposição do Salão terminar, poderei voltar para casa.>\n\nDito isso, o Estado da Srta. Sanga ultimamente tem sido preocupante.\nTodas as noites ela sai silenciosamente e não retorna até a Madrugada."
  },
  AvgDialog_15365_Content_20 = {
    Text = "Você tem saído escondida toda noite apenas para coletar Lama Corrosiva aqui?"
  },
  AvgDialog_15365_Content_21 = {
    Text = "Você sabe o nome delas? Está bastante familiarizado com elas."
  },
  AvgDialog_15365_Content_22 = {
    Text = "Não é... nada raro. Há bastante disso em Besançon."
  },
  AvgDialog_15365_Content_23 = {
    Text = "Entendo... Eu pensei que esta fosse uma Descoberta maravilhosa só minha."
  },
  AvgDialog_15365_Content_24 = {
    Text = "Fusão... Que nome adequado, de fato."
  },
  AvgDialog_15365_Content_25 = {
    Text = "Agora não é hora para gracejos, Sanga."
  },
  AvgDialog_15365_Content_26 = {
    Text = "Você vai morrer. Isso não é algo que pessoas comuns como nós deveriam tocar."
  },
  AvgDialog_15365_Content_27 = {
    Text = "Eu entendo, claro que entendo... A beleza inevitavelmente atrai o perigo."
  },
  AvgDialog_15365_Content_28 = {
    Text = "Mas, por outro lado, o perigo em si não é uma forma de beleza?\nPara mim, a morte não é algo a ser temido."
  },
  AvgDialog_15365_Content_29 = {
    Text = "O que é verdadeiramente aterrorizante é..."
  },
  AvgDialog_15365_Content_3 = {
    Text = "Estranhamente, esse padrão persistente de dormir de dia e sair à noite a encheu de vitalidade,\ne até mesmo o Sr. Agosto está bastante satisfeito com sua eficiência de trabalho recente.\n\n<Yellow:Ela se tornou tão irreconhecível.>\n\nEm várias noites, acordei de pesadelos e a encontrei ali, parada ao lado da minha cama...\nEla me encarava sem piscar, seus olhos cheios de coisas assustadoras que eu não conseguia compreender."
  },
  AvgDialog_15365_Content_30 = {
    Text = "Um vento suave soprou, engolindo as próximas palavras de Sanga. A lua havia emergido das camadas de nuvens escuras em algum momento, lançando seu luar frio sobre vocês dois."
  },
  AvgDialog_15365_Content_31 = {
    Text = "Então você viu as cicatrizes no pescoço de Sanga."
  },
  AvgDialog_15365_Content_32 = {
    Text = "Eram como tentáculos de coral, em Propagação sempre ascendente, cintilando com um Brilho de Mareel azul-acinzentado nos intervalos onde o luar se alternava."
  },
  AvgDialog_15365_Content_33 = {
    Text = "Senhorita Sanga, você já foi infectada...?!"
  },
  AvgDialog_15365_Content_34 = {
    Text = "Mesmo sabendo que isso era Apenas um Sonho, seu coração ainda foi atingido por uma breve pontada de dor."
  },
  AvgDialog_15365_Content_35 = {
    Text = "Afinal, você agora possuía todas as memórias e emoções da hospedeira original. Esta Donzela do interior de Besançon nutria um profundo afeto por Ela, sua senhora."
  },
  AvgDialog_15365_Content_36 = {
    Text = "É por causa do Sr. Agosto? As palavras dele colocaram pressão demais em você, então..."
  },
  AvgDialog_15365_Content_37 = {
    Text = "Sanga balançou a cabeça dela."
  },
  AvgDialog_15365_Content_38 = {
    Text = "Do início ao fim, esse assunto não tinha nada a ver com ele.\nVenha, deixe-me levar você a um lugar."
  },
  AvgDialog_15365_Content_39 = {
    Text = "Finalmente chegamos — minha base secreta."
  },
  AvgDialog_15365_Content_4 = {
    Text = "<Yellow:Decidi segui-la secretamente esta noite e ver o que ela realmente está fazendo.>\nDeseje-me sorte.\n\nCamille@1\nA.F.2@1 Setembro"
  },
  AvgDialog_15365_Content_40 = {
    Text = "Era um armazém abandonado à beira-mar. Dentro havia muitos Estudos de escultura bizarramente retorcidos em todo tipo de poses."
  },
  AvgDialog_15365_Content_41 = {
    Text = "Coral, conchas, tentáculos e edifícios e criaturas adornados com estranhas esculturas... Sua única semelhança é a sua estreita conexão com o oceano."
  },
  AvgDialog_15365_Content_42 = {
    Text = "A textura dessas esculturas..."
  },
  AvgDialog_15365_Content_43 = {
    Text = "Não é mármore nem granito. Onde você encontrou esse material?"
  },
  AvgDialog_15365_Content_44 = {
    Text = "Sanga lhe deu um parpadeio travesso."
  },
  AvgDialog_15365_Content_45 = {
    Text = "Isso é meu segredo. Você vai descobrir um dia."
  },
  AvgDialog_15365_Content_46 = {
    Text = "No centro da cabana de madeira havia uma escultura humanoide inacabada."
  },
  AvgDialog_15365_Content_47 = {
    Text = "Seu corpo estava envolto em tentáculos horrendos, retorcido em ângulos inimagináveis. As veias do pescoço estavam salientes, como uma serpente sinuosa."
  },
  AvgDialog_15365_Content_48 = {
    Text = "Bonito, não é?\nTodos me chamam de \"a Açougueira,\" porque sou sempre implacável com meus modelos."
  },
  AvgDialog_15365_Content_49 = {
    Text = "Mas é precisamente por isso que consigo capturar a essência — a agonia emaranhada que jaz sob a pele e a carne."
  },
  AvgDialog_15365_Content_5 = {
    Text = "Setembro na Cité já é amargamente frio.\nVocê caminha silenciosamente pela rua, tentando se ocultar nas sombras."
  },
  AvgDialog_15365_Content_50 = {
    Text = "Mas meu professor sempre tratou seus modelos com cuidado excessivo, e é por isso que ele só conseguiu ser um escultor de segunda categoria."
  },
  AvgDialog_15365_Content_51 = {
    Text = "Você contempla a escultura diante de si. É inegavelmente bela, mas também cruel."
  },
  AvgDialog_15365_Content_52 = {
    Text = "É essa a peça que você planeja levar à exposição?"
  },
  AvgDialog_15365_Content_53 = {
    Text = "Sanga balançou a cabeça dela."
  },
  AvgDialog_15365_Content_54 = {
    Text = "Apenas alguns rascunhos. Antes de encontrar aquelas... Lamas Corrosivas, minha compreensão de escultura ainda era bastante superficial."
  },
  AvgDialog_15365_Content_55 = {
    Text = "Agora sou como uma recém-nascida que acabou de abrir os olhos, forçada a redescobrir o mundo diante de mim..."
  },
  AvgDialog_15365_Content_56 = {
    Text = "<Yellow:E a redescobrir você.>"
  },
  AvgDialog_15365_Content_57 = {Text = "Eu...?"},
  AvgDialog_15365_Content_58 = {
    Text = "Sim, você. Nos seus olhos e na sua expressão, eu vejo novas possibilidades."
  },
  AvgDialog_15365_Content_59 = {
    Text = "Sanga traçou suavemente os contornos do seu rosto com os dedos."
  },
  AvgDialog_15365_Content_6 = {
    Text = "A silhueta esbelta de Sanga estava logo à frente.\nVocê manteve uma distância entre vocês — nem muito perto, nem muito longe — como se conectados por um fio invisível."
  },
  AvgDialog_15365_Content_60 = {
    Text = "Diferente de outras jovens damas mimadas, as pontas dos seus dedos tinham uma fina camada de calosidades, dando-lhes uma textura singularmente áspera."
  },
  AvgDialog_15365_Content_61 = {
    Text = "Você está com medo. Não se preocupe, não vou forçá-lo a fazer nada."
  },
  AvgDialog_15365_Content_62 = {
    Text = "Você ainda se lembra de quando éramos crianças?"
  },
  AvgDialog_15365_Content_63 = {
    Text = "Quando éramos crianças?"
  },
  AvgDialog_15365_Content_64 = {
    Text = "Seguindo as palavras dela, você mergulha cada vez mais fundo nas memórias emaranhadas do dono original, explorando..."
  },
  AvgDialog_15365_Content_65 = {
    Text = "Até que finalmente se detém naquele verão turvo e nebuloso."
  },
  AvgDialog_15365_Content_66 = {
    Text = "Claro que me lembro. Quando você tinha 5 anos, já conseguia esculpir um esqueleto humano com barro."
  },
  AvgDialog_15365_Content_67 = {
    Text = "Eu ia até o litoral procurar todo tipo de materiais para você, e o Senhorito Paul Claud ficava encarregado de jogar aqueles modelos na fornalha para queimá-los."
  },
  AvgDialog_15365_Content_68 = {
    Text = "Sim, era o nosso pequeno segredo — apenas nós três."
  },
  AvgDialog_15365_Content_69 = {
    Text = "Uma vez, quando o seu pai descobriu, você assumiu toda a culpa e ainda foi obrigado a ficar de pé como castigo a noite inteira."
  },
  AvgDialog_15365_Content_7 = {
    Text = "Esse fio guiou vocês dois por edifício após edifício, através da longa e sombria geada, até que finalmente chegaram ao destino em comum—"
  },
  AvgDialog_15365_Content_70 = {
    Text = "Uma fina névoa de tristeza brotou nos olhos cinzentos de Sanga."
  },
  AvgDialog_15365_Content_71 = {
    Text = "Ela te abraça gentilmente."
  },
  AvgDialog_15365_Content_72 = {
    Text = "Vocês são toda a minha família, para sempre. Foi o Paul que o enviou para me encontrar, não foi?"
  },
  AvgDialog_15365_Content_73 = {
    Text = "Sim. O senhorito... ele adoeceu e não pôde vir pessoalmente."
  },
  AvgDialog_15365_Content_74 = {
    Text = "Você respira suavemente contra a curva do pescoço de Sanga, o perfume dela preenchendo suas narinas.\nO sabor embriagante das ondas do mar."
  },
  AvgDialog_15365_Content_75 = {
    Text = "Não se preocupe. Já que prometi que voltaríamos para casa juntos, não vou voltar atrás na minha palavra."
  },
  AvgDialog_15365_Content_76 = {
    Text = "Mas antes disso, preciso deixá-lo."
  },
  AvgDialog_15365_Content_77 = {
    Text = "Deixar-me...? Para onde vais?"
  },
  AvgDialog_15365_Content_78 = {
    Text = "Sanga não diz mais nada, virando-se para contemplar o mar cinzento e nebuloso lá fora."
  },
  AvgDialog_15365_Content_79 = {
    Text = "É uma noite envolta em nevoeiro. As ondas suaves avançam num ritmo eterno e imutável, tal como o pulso sentido na lateral do pescoço de Sanga."
  },
  AvgDialog_15365_Content_8 = {
    Text = "Uma sepultura desolada."
  },
  AvgDialog_15365_Content_80 = {
    Text = "Não sei. Talvez as profundezas do oceano, ou talvez @1..."
  },
  AvgDialog_15365_Content_81 = {
    Text = "Depois daquele dia, a Menina Sanga desapareceu."
  },
  AvgDialog_15365_Content_82 = {
    Text = "Fui a todos os lugares aonde podia ir, perguntei a todas as pessoas que consegui encontrar, mas não descobri nada.\n\nEla deixou-nos como uma rajada de vento.\nAinda hoje, dou por mim a reviver aquela noite junto ao mar, vezes sem conta."
  },
  AvgDialog_15365_Content_83 = {
    Text = "Naquele momento, a Menina Sanga abraçou-me com força.\nTalvez me tenha dito algo mais depois, ou talvez não. Não sei.\n\nAs minhas memórias começaram a ficar turvas a partir daquele dia.\n\n<Red:Coral branco, conchas em espiral, um palácio misterioso sob o mar...>\nAinda hoje, essas imagens caóticas continuam a atormentar a minha mente na calada da noite."
  },
  AvgDialog_15365_Content_84 = {
    Text = "<Yellow:\"Vai à exposição do Salon e procura as respostas.\">\n\nFoi o que a Menina Sanga me disse. Ela também disse—"
  },
  AvgDialog_15365_Content_85 = {
    Text = "Quando tiveres testemunhado esses milagres, vais compreender-me."
  },
  AvgDialog_15365_Content_86 = {
    Text = "Apenas seguires o meu olhar..."
  },
  AvgDialog_15365_Content_87 = {
    Text = "Eu prometo a você."
  },
  AvgDialog_15365_Content_9 = {
    Text = "Senhorita Sanga."
  },
  AvgDialog_15367_Content_1 = {
    Text = "Vá embora, não me toque...!!"
  },
  AvgDialog_15367_Content_10 = {
    Text = "Sei que você tem mantido secretamente uma espécie de <Yellow:ateliê> por fora, mas acho que devo lembrá-la."
  },
  AvgDialog_15367_Content_11 = {
    Text = "Não espere que suas <Yellow:criações amadoras, profanas e abomináveis> conquistem o favor dos oficiais do governo."
  },
  AvgDialog_15367_Content_12 = {
    Text = "Admito que você é muito talentosa, e tem sido de grande ajuda para o ateliê. Mas para buscar a arte em um lugar como a Cité, é preciso muito mais do que talento."
  },
  AvgDialog_15367_Content_13 = {
    Text = "Se você me irritar..."
  },
  AvgDialog_15367_Content_14 = {
    Text = "Sr. August, por favor, preste atenção nas suas palavras."
  },
  AvgDialog_15367_Content_15 = {
    Text = "Está tudo bem, Camille."
  },
  AvgDialog_15367_Content_16 = {
    Text = "Sanga gentilmente puxou você para trás. Diante da repreensão de Agosto, sua expressão permaneceu calma."
  },
  AvgDialog_15367_Content_17 = {
    Text = "Ela se ajoelhou, recolheu os pedaços estilhaçados do rosto da escultura um por um e os jogou na pilha de lixo próxima."
  },
  AvgDialog_15367_Content_18 = {
    Text = "Se eu o irritar, minhas obras não poderão ser exibidas, não poderão ser vendidas, e como artista eu nunca verei a luz do dia. E no final..."
  },
  AvgDialog_15367_Content_19 = {
    Text = "Apenas morrerei congelada nas ruas, ou serei mandada para um asilo."
  },
  AvgDialog_15367_Content_2 = {
    Text = "Todos se apressaram para conter Este — o mestre escultor, agora fora de si de raiva."
  },
  AvgDialog_15367_Content_20 = {
    Text = "É claro que sei de tudo isso perfeitamente bem, Mestre."
  },
  AvgDialog_15367_Content_3 = {
    Text = "Não seja imprudente, meu querido professor."
  },
  AvgDialog_15367_Content_4 = {
    Text = "Uma obra tão medíocre arruinaria não apenas meu humor, mas também sua reputação."
  },
  AvgDialog_15367_Content_5 = {
    Text = "Heh... Não seja tão presunçosa. A exposição do Salão é em menos de meio ano. Consegue conjurar algo melhor do nada?"
  },
  AvgDialog_15367_Content_6 = {Text = "Um mês."},
  AvgDialog_15367_Content_7 = {Text = "...O que?"},
  AvgDialog_15367_Content_8 = {
    Text = "Me dê um mês, e eu entregarei uma absoluta <Yellow:surpresa>."
  },
  AvgDialog_15367_Content_9 = {Text = "...Hmph."},
  AvgDialog_15368_Content_1 = {
    Text = "Uma Carta Para Ti"
  },
  AvgDialog_15368_Content_10 = {
    Text = "Suas têmporas estão pulsando. Você tenta mover seu corpo, mas—"
  },
  AvgDialog_15368_Content_11 = {Text = "...!"},
  AvgDialog_15368_Content_12 = {
    Text = "<Shake:Minhas pernas... ficaram dormentes...>"
  },
  AvgDialog_15368_Content_13 = {
    Text = "Hã, é apenas minha imaginação? No momento em que você abriu os olhos agora, achei que vi um brilho que nunca tinha visto antes."
  },
  AvgDialog_15368_Content_14 = {
    Text = "Não, não é minha imaginação. Sua expressão também está diferente..."
  },
  AvgDialog_15368_Content_15 = {
    Text = "Os olhos da jovem aprendiz de escultora brilham com Empolgação enquanto ela de repente se inclina para perto de você."
  },
  AvgDialog_15368_Content_16 = {
    Text = "Quem é você?"
  },
  AvgDialog_15368_Content_17 = {Text = "Sua Dama"},
  AvgDialog_15368_Content_18 = {
    Text = "<Shake:E-Eu sou sua Servente, Camille@1! Não se lembra? Haha...>"
  },
  AvgDialog_15368_Content_19 = {
    Text = "Você mantém sua Identidade firmemente em mente."
  },
  AvgDialog_15368_Content_2 = {
    Text = "Caro Monsieur Claudel:\n\nCheguei à Cité.\nAo contrário da tranquilidade de Besançon, este lugar está sempre repleto de ruído clamoroso.\nBadaladas de sinos, o estalar das carruagens, e o barulho incessante da multidão...\nO pensamento de que a Menina Sanga tem vivido num ambiente assim enche-me de inquietação."
  },
  AvgDialog_15368_Content_20 = {
    Text = "Desta vez, você é a Donzela que cresceu com Sanga desde a infância, enviada pelo Senhorito Paul para trazer Sanga para casa."
  },
  AvgDialog_15368_Content_21 = {
    Text = "\"Você deve resgatar a alma dela das garras daquele demônio que Apenas explora e plagia os outros.\""
  },
  AvgDialog_15368_Content_23 = {
    Text = "<Gray:Não, isso não está certo...>"
  },
  AvgDialog_15368_Content_24 = {
    Text = "Você mantém sua Identidade firmemente em mente."
  },
  AvgDialog_15368_Content_25 = {
    Text = "Desta vez, você é uma criada que cresceu com Sanga e foi enviada pelo Mestre @1·Claudel para levar ela de volta para casa."
  },
  AvgDialog_15368_Content_26 = {
    Text = "\"Você deve resgatar a alma dela das garras daquele diabo que Apenas explora e plagia seus subordinados.\""
  },
  AvgDialog_15368_Content_27 = {
    Text = "E–eu sou sua Donzela, Camille@1! Não se lembra? Haha..."
  },
  AvgDialog_15368_Content_28 = {
    Text = "<Shake:Depois de tantos anos separadas, ambas mudamos um pouco, não é?>"
  },
  AvgDialog_15368_Content_29 = {Text = "..."},
  AvgDialog_15368_Content_3 = {
    Text = "Os rumores já se espalharam.\nAs pessoas dizem que a Menina Sanga passa os seus dias e noites com um homem mais de 20 anos mais velho, \"em nome da arte.\"\nIsto é completamente absurdo. Amanhã visitarei o ateliê para ver com os meus próprios olhos.\n\nDesta vez, cumprirei o seu pedido—\n<Yellow:Trazer a sua irmã, a nossa querida Menina Sanga, de volta a Besançon.>\n\nCamille@1\nA.F.2@1 Agosto"
  },
  AvgDialog_15368_Content_30 = {
    Text = "Você realmente está bem diferente. Está tão mais vívida agora do que antes.\nÉ como se... tivesse subitamente ganhado vida."
  },
  AvgDialog_15368_Content_31 = {
    Text = "<Gray:Então este é o Olfato de uma artista... Vou ter que ser mais cuidadosa de agora em diante.>"
  },
  AvgDialog_15368_Content_32 = {
    Text = "<Shake:Se não se importar, poderia me ajudar? Não consigo me levantar agora...>"
  },
  AvgDialog_15368_Content_33 = {
    Text = "Sanga gentilmente segura sua mão, um lampejo de preocupação passando por seus olhos calmos e serenos."
  },
  AvgDialog_15368_Content_34 = {
    Text = "Me desculpe, estava absorta demais no meu trabalho agora há pouco. Você deve estar muito desconfortável agora. Deixe–me dar uma olhada."
  },
  AvgDialog_15368_Content_35 = {
    Text = "Whoosh—!!"
  },
  AvgDialog_15368_Content_36 = {
    Text = "A porta do ateliê foi escancarada."
  },
  AvgDialog_15368_Content_37 = {
    Text = "Um homem alto e sombrio entrou, seguido por vários rostos desconhecidos."
  },
  AvgDialog_15368_Content_38 = {
    Text = "Sem precisar acessar nenhuma das memórias da hospedeira original, você o reconheceu por seu bigode característico—"
  },
  AvgDialog_15368_Content_39 = {
    Text = "O renomado escultor, <Blue:Agosto>."
  },
  AvgDialog_15368_Content_4 = {
    Text = "Menina Sanga, volte comigo. Não há sequer um lugar para se aquecer aqui—"
  },
  AvgDialog_15368_Content_40 = {
    Text = "Mesmo agora, suas esculturas ainda são aclamadas como obras–primas, altamente cobiçadas nos leilões de Londinium."
  },
  AvgDialog_15368_Content_41 = {
    Text = "Ao ver suas mãos e as de Sanga entrelaçadas, Agosto franziu a testa. Mas logo, sua atenção foi atraída pela escultura diante dele."
  },
  AvgDialog_15368_Content_42 = {
    Text = "Isto é... <Big:Uma obra–prima, uma obra–prima indiscutível!>"
  },
  AvgDialog_15368_Content_43 = {
    Text = "Os outros se reuniram ao redor também, contemplando curiosamente a escultura recém–concluída, soltando ondas de admiração."
  },
  AvgDialog_15368_Content_44 = {
    Text = "Bom, muito bom... Entrem em contato com o pessoal do Ministério da Cultura. Digam que temos uma exposição promissora para a exibição da Cité deste ano."
  },
  AvgDialog_15368_Content_45 = {
    Text = "Mal posso esperar para ver as caras daqueles críticos quando seus queixos caírem... Hahahaha!"
  },
  AvgDialog_15368_Content_46 = {
    Text = "A risada calorosa de Agosto ressoou pelo espaçoso ateliê. Ele empurrou você para o lado e segurou firmemente a mão de Sanga."
  },
  AvgDialog_15368_Content_47 = {
    Text = "Eu sabia que você não me decepcionaria, Sanga."
  },
  AvgDialog_15368_Content_48 = {
    Text = "Sanga retirou lentamente a mão e caminhou até a escultura."
  },
  AvgDialog_15368_Content_49 = {
    Text = "Uma indiscutível... obra-prima?"
  },
  AvgDialog_15368_Content_5 = {
    Text = "Não se mova, e não fale. Apenas fique assim.\nSim, assim mesmo..."
  },
  AvgDialog_15368_Content_50 = {
    Text = "O que você acha, Camille?"
  },
  AvgDialog_15368_Content_51 = {
    Text = "Hã, eu...?"
  },
  AvgDialog_15368_Content_52 = {
    Text = "Você contemplou a escultura que se parecia quase exatamente com \"você\" e mergulhou em profunda reflexão..."
  },
  AvgDialog_15368_Content_53 = {Text = "Medíocre"},
  AvgDialog_15368_Content_54 = {
    Text = "Hmm, a expressão é rígida, a estrutura é caótica e falta tensão..."
  },
  AvgDialog_15368_Content_55 = {
    Text = "Você comentou com um ar de autoridade. Na verdade, você sempre foi completamente alheio à arte. A única razão pela qual disse aquilo foi porque não suportava a atitude arrogante de Agosto."
  },
  AvgDialog_15368_Content_56 = {
    Text = "Você não gosta dele."
  },
  AvgDialog_15368_Content_57 = {
    Text = "Sanga observou você com um sorriso, como uma Mãe amorosa diante do balbucio sem sentido de uma criança."
  },
  AvgDialog_15368_Content_58 = {
    Text = "Hmm... Embora nossas razões sejam diferentes, chegamos à mesma conclusão."
  },
  AvgDialog_15368_Content_59 = {
    Text = "Uma obra-prima!"
  },
  AvgDialog_15368_Content_6 = {
    Text = "Seja uma boa modelo para mim, me deixe terminar esta peça... depois podemos discutir sobre voltar para casa."
  },
  AvgDialog_15368_Content_60 = {
    Text = "Verdadeiramente incomparável. Não consigo encontrar um único defeito nela."
  },
  AvgDialog_15368_Content_61 = {
    Text = "Como todos os outros, sua mente foi completamente cativada por esta escultura — aparentemente livre, mas meticulosamente precisa."
  },
  AvgDialog_15368_Content_62 = {
    Text = "É claro, isso também tinha a ver com a má Circulação Sanguínea causada por manter a mesma pose por tanto tempo."
  },
  AvgDialog_15368_Content_63 = {
    Text = "Um cérebro privado de oxigênio não consegue perceber as coisas com clareza, mas bajulação nunca é errado."
  },
  AvgDialog_15368_Content_64 = {
    Text = "Você tem razão. Não ter defeitos — esse é precisamente o seu maior problema."
  },
  AvgDialog_15368_Content_65 = {
    Text = "Agora... o que devo fazer com você?"
  },
  AvgDialog_15368_Content_66 = {
    Text = "Sanga apoiou o queixo na mão, contemplando a escultura diante de si. Então estendeu o dedo indicador e tocou casualmente a escultura entre as sobrancelhas—"
  },
  AvgDialog_15368_Content_67 = {Text = "CRASH—!!"},
  AvgDialog_15368_Content_68 = {
    Text = "A escultura traçou um arco elegante pelo ar e então se espatifou no chão."
  },
  AvgDialog_15368_Content_69 = {
    Text = "Camille — ou melhor, aquele rosto angustiado — se despedaçou em incontáveis fragmentos num instante."
  },
  AvgDialog_15368_Content_7 = {
    Text = "O que é isto...?"
  },
  AvgDialog_15368_Content_70 = {Text = "..."},
  AvgDialog_15368_Content_71 = {
    Text = "Senhorita Claudel, enlouqueceu?!"
  },
  AvgDialog_15368_Content_72 = {
    Text = "Agosto avançou em sua direção com raiva."
  },
  AvgDialog_15368_Content_73 = {
    Text = "<Big:Este era o mais puro mármore pentélico, extraído de Paros—>"
  },
  AvgDialog_15368_Content_8 = {
    Text = "Um quarto bagunçado."
  },
  AvgDialog_15368_Content_9 = {
    Text = "Esculturas de diversas argilas Pegajosas, mármore e granito estão colocadas de forma desordenada, transformando este espaço em um estúdio de escultura improvisado."
  },
  AvgDialog_15370_Content_1 = {
    Text = "Cabeça Dourada"
  },
  AvgDialog_15370_Content_10 = {
    Text = "A chuva ficava cada vez mais forte, sua garganta cada vez mais seca.\nEm uma tempestade como esta, você precisava gritar só para ouvir sua própria voz."
  },
  AvgDialog_15370_Content_11 = {
    Text = "Aqui... estou aqui..."
  },
  AvgDialog_15370_Content_12 = {
    Text = "A@1hi hi hi aqui aqui@2qui qui qui..."
  },
  AvgDialog_15370_Content_13 = {
    Text = "Inúmeras vozes a assaltaram de todas as direções. Incapaz de aguentar, você finalmente desabou na areia."
  },
  AvgDialog_15370_Content_14 = {
    Text = "Talvez tudo fosse apenas sua Ilusão... talvez a Sra. Sanga já tivesse partido para sempre."
  },
  AvgDialog_15370_Content_15 = {
    Text = "<Shake:Sra. Sanga, por favor, apareça... eu sei que você está aqui...>"
  },
  AvgDialog_15370_Content_16 = {
    Text = "Em algum momento, a consciência da Donzela havia gradualmente Devorado você. As esperanças e o sofrimento Dela tocaram profundamente seu coração."
  },
  AvgDialog_15370_Content_17 = {
    Text = "Você pressiona a testa contra a areia úmida, um gemido estranho escapando da sua garganta."
  },
  AvgDialog_15370_Content_18 = {
    Text = "<Shake:Senhorita Sanga...>"
  },
  AvgDialog_15370_Content_19 = {
    Text = "<Red:Aqui... Estou aqui...>"
  },
  AvgDialog_15370_Content_2 = {
    Text = "Caro Sr. Claud:\n\n\"Morte da Sra. Coral\" foi um tremendo sucesso em Cité. Todos estão falando sobre isso.\nOlhando para esta escultura, não consigo deixar de pensar em você.\n\nÉ feita de um material branco e opaco, muito parecido com a pedra que cobriu todo o seu corpo e o impediu de se mover.\nMas eles não me deixam tocar na escultura@1\nVou encontrar um jeito."
  },
  AvgDialog_15370_Content_20 = {
    Text = "...O que é isso?"
  },
  AvgDialog_15370_Content_21 = {
    Text = "Um frio gélido alcança as pontas dos seus dedos."
  },
  AvgDialog_15370_Content_22 = {
    Text = "A névoa branca se Propaga por entre seus dedos mais uma vez, como trepadeiras vivas..."
  },
  AvgDialog_15370_Content_23 = {
    Text = "Lentamente, metodicamente..."
  },
  AvgDialog_15370_Content_24 = {
    Text = "Enfim... este momento finalmente chegou."
  },
  AvgDialog_15370_Content_25 = {
    Text = "Um par de delicados sapatos femininos de couro param diante de você.\nSanga segura uma faca de entalhar, sua expressão tão indiferente como sempre."
  },
  AvgDialog_15370_Content_26 = {
    Text = "Senhorita Sanga... você realmente ainda está viva..."
  },
  AvgDialog_15370_Content_27 = {
    Text = "Isso depende de como você define \"viva\"."
  },
  AvgDialog_15370_Content_28 = {
    Text = "O brilho suave das luzes distantes envolve gentilmente o corpo de Sanga. Ela sorri quietamente para você."
  },
  AvgDialog_15370_Content_29 = {
    Text = "Voltei, Camille. Você deve ter esperado por mim por muito tempo, não é?"
  },
  AvgDialog_15370_Content_3 = {
    Text = "A Sra. Sanga finalmente realizou o desejo Dela. Ela trocou Sua própria Vida para alcançar a arte imortal.\nMas por causa disso, ela nos deixou para sempre.\nJá faz quase um mês desde a exposição, e ainda sinto muita falta Dela.\n\n<Yellow:Eu vou encontrá-La e trazê-La para casa.>\n\nCamille@1\nA.F.2@1 Agosto"
  },
  AvgDialog_15370_Content_30 = {
    Text = "Angústia, choque, êxtase..."
  },
  AvgDialog_15370_Content_31 = {
    Text = "Incontáveis emoções surgem dentro do seu peito. Você abre a boca, apenas para Descobrir que não consegue mais formar uma sílaba completa."
  },
  AvgDialog_15370_Content_32 = {
    Text = "Sanga@1... não@2..."
  },
  AvgDialog_15370_Content_33 = {Text = "Shh..."},
  AvgDialog_15370_Content_34 = {
    Text = "Você sabia? O corpo humano é como um mundo tremulante e pulsante."
  },
  AvgDialog_15370_Content_35 = {
    Text = "Quando a carne e a alma foram temperadas o suficiente, no auge da erupção emocional, passam por uma Metamorfose na escultura mais perfeita..."
  },
  AvgDialog_15370_Content_36 = {
    Text = "Dedos gélidos acariciam seu rosto gradualmente enrijecido."
  },
  AvgDialog_15370_Content_37 = {
    Text = "Sanga olhou para você com amor, seus olhos ardentes quase reduzindo você a cinzas."
  },
  AvgDialog_15370_Content_38 = {
    Text = "Apenas como você está agora..."
  },
  AvgDialog_15370_Content_39 = {
    Text = "Como eu estou agora...? Sra. Sanga, é a Lama Corrosiva..."
  },
  AvgDialog_15370_Content_4 = {
    Text = "Você cambaleou até a praia. Não havia ninguém aqui — apenas o Silêncio opaco do mar e o horizonte nebuloso para lhe fazer companhia."
  },
  AvgDialog_15370_Content_40 = {
    Text = "Shh... Silêncio."
  },
  AvgDialog_15370_Content_41 = {
    Text = "Para mim, a morte nunca foi algo assustador. O que é verdadeiramente assustador é..."
  },
  AvgDialog_15370_Content_42 = {
    Text = "<Yellow:Perder a beleza, ou fechar os olhos para isso.>"
  },
  AvgDialog_15370_Content_43 = {
    Text = "<Shake:Saia... daqui... Me deixe...>"
  },
  AvgDialog_15370_Content_44 = {
    Text = "Não seja tola, Camille."
  },
  AvgDialog_15370_Content_45 = {
    Text = "<Red:Você já está morta há muito tempo. Não se lembra?>"
  },
  AvgDialog_15370_Content_46 = {
    Text = "<Red:Morta...>"
  },
  AvgDialog_15370_Content_47 = {Text = "..."},
  AvgDialog_15370_Content_48 = {
    Text = "Você mergulhou mais uma vez nas profundezas do oceano sem fim."
  },
  AvgDialog_15370_Content_49 = {
    Text = "Fragmentos selados na memória emergiram como espuma branca flutuando ao redor, surgindo sem cessar, encontrando sem cessar a Destruição..."
  },
  AvgDialog_15370_Content_5 = {
    Text = "Vocês são todos minha família, para sempre."
  },
  AvgDialog_15370_Content_50 = {
    Text = "No momento final antes da morte, você não teve escolha senão encarar aquelas cruéis verdades reais—"
  },
  AvgDialog_15370_Content_51 = {
    Text = "A culpa é toda minha, Camille. A culpa é toda minha... Deixe–me abraçá–la, e a ferida não vai mais doer."
  },
  AvgDialog_15370_Content_52 = {
    Text = "Minha irmã é uma verdadeira gênia. Ela definitivamente se tornará uma grande artista imortalizada nos livros!"
  },
  AvgDialog_15370_Content_53 = {
    Text = "*cof cof*... Pare de se enganar, Camille..."
  },
  AvgDialog_15370_Content_54 = {
    Text = "Traga–a de volta para me ver@2Há algo que quero perguntar a ela pessoalmente..."
  },
  AvgDialog_15370_Content_55 = {
    Text = "Notícia urgente, notícia urgente!!"
  },
  AvgDialog_15370_Content_56 = {
    Text = "O chocante <Yellow:caso do assassinato da escultura> faz mais uma vítima!"
  },
  AvgDialog_15370_Content_57 = {
    Text = "Até o momento, os casos de <Yellow:Sintoma: Tontura e Sintoma: Histeria> causados pela visualização de \"Morte da Sra. Coral\" subiram para 54..."
  },
  AvgDialog_15370_Content_58 = {
    Text = "<Red:Destes, 23 já cometeram suicídio...>"
  },
  AvgDialog_15370_Content_59 = {Text = "..."},
  AvgDialog_15370_Content_6 = {
    Text = "Não se preocupe. Já que prometi que voltaríamos para casa juntos, não vou voltar atrás na minha palavra."
  },
  AvgDialog_15370_Content_60 = {
    Text = "Então eu... já sabia de tudo desde o início..."
  },
  AvgDialog_15370_Content_61 = {
    Text = "Você vê aquele palácio oceânico branco mais uma vez. Plânctons se aglomeram sobre o carbonato de cálcio branco, esticando preguiçosamente seus membros."
  },
  AvgDialog_15370_Content_62 = {
    Text = "Você também vê aquelas esculturas brancas vagando sem rumo pela água do mar."
  },
  AvgDialog_15370_Content_63 = {
    Text = "Entre elas há alguns rostos familiares — o Sr. Agosto, por exemplo, ainda congelado na raiva e desespero de quando avançou contra a escultura."
  },
  AvgDialog_15370_Content_64 = {
    Text = "O Senhor Paulo, por outro lado, suas órbitas Enredadas transbordando melancolia, como se há muito tivesse previsto seu próprio Destino."
  },
  AvgDialog_15370_Content_65 = {
    Text = "A água morna do mar envolve seu corpo, seu ritmo incessante como uma canção de ninar fluindo."
  },
  AvgDialog_15370_Content_66 = {
    Text = "Antes de Abrir os olhos o infante agita pequenas mãos\nSegurando figuras de argila sentindo uma alegria semelhante ao amor materno\nA arte de moldar e controlar desde então se Propaga entre os dedos\n\n<Red:Abra os olhos e tudo que se vê nasce da beleza beleza beleza beleza beleza beleza beleza...>"
  },
  AvgDialog_15370_Content_67 = {
    Text = "Mãos frias gentilmente abraçam você. Sanga enterra Sua bochecha macia contra seu ombro rígido."
  },
  AvgDialog_15370_Content_68 = {
    Text = "Você consegue ouvi-los? Aqueles cantos — eles ecoam sem fim na minha mente."
  },
  AvgDialog_15370_Content_69 = {
    Text = "São <Yellow:Eles> que Chamam, o Destino inescapável que me Invoca..."
  },
  AvgDialog_15370_Content_7 = {
    Text = "Ela não quebraria Sua promessa... não quebraria."
  },
  AvgDialog_15370_Content_70 = {
    Text = "Eu segui aqueles cantos e finalmente encontrei este lugar."
  },
  AvgDialog_15370_Content_71 = {
    Text = "O Milagre e a beleza das profundezas do oceano... Ainda há nada que eu possa oferecer a Eles além de você."
  },
  AvgDialog_15370_Content_72 = {Text = "Eu...?"},
  AvgDialog_15370_Content_73 = {
    Text = "Sim, Apenas você — %player%."
  },
  AvgDialog_15370_Content_74 = {
    Text = "Ela pronunciou seu nome original claramente, sem qualquer dúvida."
  },
  AvgDialog_15370_Content_75 = {
    Text = "Desde o exato momento em que você abriu seus Olhos, eu soube."
  },
  AvgDialog_15370_Content_76 = {
    Text = "<Yellow:Você é a verdadeira \"Morte da Sra. Coral\".>"
  },
  AvgDialog_15370_Content_77 = {
    Text = "A consciência se esvai. Coral branco há muito se Propagou por todo o seu corpo."
  },
  AvgDialog_15370_Content_78 = {
    Text = "Você sente seu Sangue e carne ficando pesados, mas estranhamente, seus corpos continuam subindo em meio à espuma e ao coral."
  },
  AvgDialog_15370_Content_79 = {
    Text = "<Shake:Não... casa... ir para casa...>"
  },
  AvgDialog_15370_Content_8 = {
    Text = "Você levantou a barra da saia e continuou Correndo ao longo da extensa costa."
  },
  AvgDialog_15370_Content_80 = {
    Text = "Esta é a sua casa, %player%."
  },
  AvgDialog_15370_Content_81 = {Text = "Não..."},
  AvgDialog_15370_Content_82 = {
    Text = "Você olha fixamente para o rosto de Sanga, com os olhos arregalados, até que suas pupilas também são cobertas pelo coral cinza-pálido."
  },
  AvgDialog_15370_Content_83 = {
    Text = "Você afunda em um vazio sem limites."
  },
  AvgDialog_15370_Content_84 = {
    Text = "Todo o oceano, o coral, as esculturas se afastam de você, mas a voz dela permanece."
  },
  AvgDialog_15370_Content_85 = {
    Text = "Gentil como sempre, aquela voz fria e distante."
  },
  AvgDialog_15370_Content_86 = {
    Text = "Eu prometi que levaria você para casa comigo..."
  },
  AvgDialog_15370_Content_87 = {
    Text = "Eu prometi a você."
  },
  AvgDialog_15370_Content_9 = {
    Text = "Sra. Sanga— Sra. Sanga—"
  },
  AvgDialog_15605_Content_1 = {
    Text = "Iniciar Teste"
  },
  AvgDialog_15605_Content_10 = {
    Text = "Será que você entrou no passado do Corpo Desperto novamente? Você se lembra de que estava lendo alguns documentos..."
  },
  AvgDialog_15605_Content_11 = {
    Text = "Por que não há nenhuma resposta? O módulo auditivo está com defeito?"
  },
  AvgDialog_15605_Content_12 = {
    Text = "Isso depende— você entrou escondida e mexeu nos módulos de novo depois que eu saí ontem?"
  },
  AvgDialog_15605_Content_13 = {
    Text = "Não não, dessa vez eu realmente não mexi, eu juro!\nDeixa eu tentar de novo— Pessoa Tick-Tock, você consegue me ouvir?"
  },
  AvgDialog_15605_Content_14 = {Text = "Sim."},
  AvgDialog_15605_Content_15 = {
    Text = "Olha, olha! A boca dele se mexeu! Eu disse que ia funcionar!"
  },
  AvgDialog_15605_Content_16 = {
    Text = "O primeiro fantoche mecânico totalmente automático do mundo que consegue seguir comandos de voz! O primeiro! Totalmente automático!\nQuerido Pai Deus, leva-me agora, não tenho mais arrependimentos na vida!"
  },
  AvgDialog_15605_Content_17 = {
    Text = "Ainda há muitos arrependimentos, no entanto—como não ter completado o teste de resposta a comandos, o teste de flexibilidade dos membros, o teste de duração de operação..."
  },
  AvgDialog_15605_Content_18 = {
    Text = "Me—i—tu não tens mesmo graça nenhuma."
  },
  AvgDialog_15605_Content_19 = {
    Text = "...teste de coordenação geral, teste de equilíbrio, teste de carga..."
  },
  AvgDialog_15605_Content_2 = {
    Text = "Engrenagem de transmissão, normal; sistema hidráulico, nenhum vazamento de pressão detectado; motor MF311000 operando normalmente, temperatura levemente elevada, mas dentro da faixa aceitável."
  },
  AvgDialog_15605_Content_20 = {
    Text = "Está bem, está bem, eu percebi! <Small:Tu és ainda mais mecânica do que a Pessoa Tick-Tock.>"
  },
  AvgDialog_15605_Content_21 = {
    Text = "O que você disse?"
  },
  AvgDialog_15605_Content_22 = {
    Text = "Ah—a iniciar agora o teste básico de receção e compreensão de comandos!\nPessoa Tick-Tock, pisca os olhos."
  },
  AvgDialog_15605_Content_23 = {Text = "Piscar"},
  AvgDialog_15605_Content_24 = {
    Text = "Segue o meu dedo, muito bem.\nAbre a boca? Muito bem, que boa criança."
  },
  AvgDialog_15605_Content_25 = {Text = "...Ugh."},
  AvgDialog_15605_Content_26 = {
    Text = "O quê! Eu construí-a peça por peça com as minhas próprias mãos—é perfeitamente razoável que me chame mamã."
  },
  AvgDialog_15605_Content_27 = {
    Text = "Sim, sim, Mamã Maníaca-das-Engrenagens. Traz o braço esquerdo do teu querido bebé de aço—está na hora de começar o teste dos membros."
  },
  AvgDialog_15605_Content_28 = {
    Text = "Um braço composto por engrenagens intrincadas e estruturas mecânicas que não conseguirias sequer compreender apareceu brevemente no teu Campo de visão, depois desapareceu para o teu lado esquerdo, seguido do direito."
  },
  AvgDialog_15605_Content_29 = {
    Text = "A instalação dos quatro membros correu sem problemas. Levantaste os braços e estendeste as pernas seguindo comandos, e o sorriso no rosto de Erica tornava-se cada vez mais radiante."
  },
  AvgDialog_15605_Content_3 = {
    Text = "Fonte de energia especial S, estado estável."
  },
  AvgDialog_15605_Content_30 = {
    Text = "Bem, a seguir—Ah!"
  },
  AvgDialog_15605_Content_31 = {
    Text = "Fumo negro e espesso subiu abaixo da tua linha de visão: algo estava a arder.\nOlhaste para baixo e viste faíscas elétricas e clarões de luz a piscar na tua cavidade abdominal."
  },
  AvgDialog_15605_Content_32 = {
    Text = "Extintor de incêndio, Mei, Mei!"
  },
  AvgDialog_15605_Content_33 = {
    Text = "Saia do caminho!"
  },
  AvgDialog_15605_Content_34 = {
    Text = [[
Espuma branca jorrou do extintor, e o cheiro de queimado dispersou-se pelo ar.
Erica correu para a frente e, sem se importar com o calor abrasador, desconectou o motor.]]
  },
  AvgDialog_15605_Content_35 = {Text = "Erica!"},
  AvgDialog_15605_Content_36 = {
    Text = "O motor enegrecido estava sobre a bancada de trabalho. Erica recuperou o fôlego e, só depois, soprou nas mãos cobertas de espuma branca."
  },
  AvgDialog_15605_Content_37 = {
    Text = "Ai ai ai, está queimando!"
  },
  AvgDialog_15605_Content_38 = {
    Text = "Fonte S, rápido, verifique a Fonte S!"
  },
  AvgDialog_15605_Content_39 = {
    Text = "Erica se inclinou perto do motor, seus dedos levemente avermelhados pelo calor passando suavemente pela carcaça de metal."
  },
  AvgDialog_15605_Content_4 = {
    Text = "Ufa— você está pronto?\nAutômato Pessoa Tick-Tock, 13º teste de ativação, Começar."
  },
  AvgDialog_15605_Content_40 = {
    Text = "Parece que a fiação externa entrou em curto-circuito e pegou fogo. A parte interna deve estar intacta."
  },
  AvgDialog_15605_Content_41 = {
    Text = "Não se preocupe, vou fazer uma verificação completa em um momento."
  },
  AvgDialog_15605_Content_42 = {
    Text = "...Você vai me expulsar de novo?"
  },
  AvgDialog_15605_Content_43 = {Text = "Mei..."},
  AvgDialog_15605_Content_44 = {
    Text = "Eu sei que foi errado da minha parte experimentar com a Fonte S sem permissão, mas você sabe a nossa situação de financiamento. Usar S como avanço poderia nos dar mais tempo e materiais."
  },
  AvgDialog_15605_Content_45 = {
    Text = "Apenas me deixe dar uma olhada, por favor. Apenas uma vez. Eu juro que não vou revelar nenhuma informação sobre isso a ninguém.\nPor favor."
  },
  AvgDialog_15605_Content_46 = {
    Text = "Eu já te disse, não há nada Dentro."
  },
  AvgDialog_15605_Content_47 = {
    Text = "...Você nem se dá mais ao trabalho de inventar uma desculpa. É realmente necessário ter toda essa cautela comigo?\nEu não estive sempre pensando no nosso futuro?"
  },
  AvgDialog_15605_Content_48 = {Text = "..."},
  AvgDialog_15605_Content_49 = {
    Text = "Esquece.\nVou ficar um pouco na Lanchonete do Joey. Faça o que quiser."
  },
  AvgDialog_15605_Content_5 = {
    Text = "Abra os olhos"
  },
  AvgDialog_15605_Content_50 = {
    Text = "A Porta se fechou, os passos se distanciaram, e Erica soltou um suspiro."
  },
  AvgDialog_15605_Content_51 = {
    Text = "Ela ainda... mas aquela pessoa me alertou sobre a Fonte S...\nNão posso deixar Mei compartilhar esse risco comigo."
  },
  AvgDialog_15605_Content_52 = {
    Text = "Ela se virou de volta para o motor, como se reunisse sua determinação."
  },
  AvgDialog_15605_Content_53 = {
    Text = "Vou descobrir isso. Espere por mim, Mei."
  },
  AvgDialog_15605_Content_54 = {
    Text = "Ela desparafusou a tampa e retirou um cilindro preto de Dentro."
  },
  AvgDialog_15605_Content_55 = {
    Text = "Naquele instante, seu mundo mergulhou na escuridão."
  },
  AvgDialog_15605_Content_6 = {
    Text = "Pessoa Tick-Tock, você consegue me ouvir?"
  },
  AvgDialog_15605_Content_7 = {Text = "...Erica?"},
  AvgDialog_15605_Content_8 = {
    Text = "Aquele rosto familiar exibe uma expressão natural completamente diferente daquela em sua memória. Em vez de um autômato, ela se parece mais com uma pessoa viva."
  },
  AvgDialog_15605_Content_9 = {
    Text = "...O que está acontecendo?"
  },
  AvgDialog_15606_Content_1 = {
    Text = "A voz disse assim"
  },
  AvgDialog_15606_Content_10 = {
    Text = "Ela murmurou enquanto saía, deixando você para trás com os motores e peças na bancada."
  },
  AvgDialog_15606_Content_11 = {
    Text = "Você olha para suas próprias mãos."
  },
  AvgDialog_15606_Content_12 = {
    Text = "Esbeltas, fortes, o delicado revestimento de porcelana cuidadosamente limpo e mantido. Embora frias ao toque, não pareciam diferentes das de uma pessoa viva sob a luz fraca."
  },
  AvgDialog_15606_Content_13 = {
    Text = "Estas são as mãos de Erica—as mãos do <Blue:autômato Erica> que você conheceu.\nVocê parece ter assumido o corpo Depois de Ela, tornando-se o autômato que Ela criou através de Criação."
  },
  AvgDialog_15606_Content_14 = {
    Text = "A Ela que você acabou de ver era claramente uma humana.\nQue tipo de Experiência poderia tê-la transformado no que Ela Depois se tornou?"
  },
  AvgDialog_15606_Content_15 = {Text = "Erica?"},
  AvgDialog_15606_Content_16 = {
    Text = "Você pisca, e Mei entrou no quarto em algum momento sem você perceber.\nO olhar dela percorre o quarto antes de finalmente se fixar no motor ao seu lado."
  },
  AvgDialog_15606_Content_17 = {Text = "..."},
  AvgDialog_15606_Content_18 = {
    Text = "Depois de examinar o quarto uma segunda vez, Ela fecha a Porta e caminha rapidamente em direção ao motor."
  },
  AvgDialog_15606_Content_19 = {
    Text = "Me desculpe, Erica."
  },
  AvgDialog_15606_Content_2 = {
    Text = "Pessoa Tick-Tock, querida, pode me ouvir?"
  },
  AvgDialog_15606_Content_20 = {
    Text = "A tampa gira e se abre, e Mei pinça o objeto Dentro. Desta vez você vê claramente—um cilindro de metal com não mais de 5 centímetros de diâmetro, com a letra \"S\" gravada em sua lateral."
  },
  AvgDialog_15606_Content_21 = {
    Text = "Quando Ela puxar completamente o cilindro para fora, você perderá a consciência novamente.\nEntão, antes que isso aconteça, você precisa—"
  },
  AvgDialog_15606_Content_22 = {
    Text = "Agarrar a mão dela"
  },
  AvgDialog_15606_Content_23 = {Text = "Ai!!"},
  AvgDialog_15606_Content_24 = {
    Text = "O que está acontecendo, o que está acontecendo—"
  },
  AvgDialog_15606_Content_25 = {
    Text = "Erica entra no quarto de repente, a preocupação em seu rosto congelando no instante em que ela vê o cilindro na mão de Mei."
  },
  AvgDialog_15606_Content_26 = {
    Text = "Mei, o que você está fazendo?"
  },
  AvgDialog_15606_Content_27 = {
    Text = "O que você está fazendo!"
  },
  AvgDialog_15606_Content_28 = {
    Text = "Eu só estava tentando... Essa fonte de energia... Ela realmente funciona..."
  },
  AvgDialog_15606_Content_29 = {
    Text = "Olhando fixamente para o pequeno cilindro que havia alimentado todo o motor e toda a maquinaria conectada, os olhos de Mei se arregalaram."
  },
  AvgDialog_15606_Content_3 = {
    Text = "Despertada da escuridão eterna, você Descobre que ainda está na oficina. O motor carbonizado permanece na bancada, conectado ao seu corpo por cabos de espessuras variadas."
  },
  AvgDialog_15606_Content_30 = {
    Text = "Você sabe o que isso significa, Erica?"
  },
  AvgDialog_15606_Content_31 = {
    Text = "Significa que é perigoso. Eu te disse, Mei, você não pode simplesmente ficar mexendo nisso—"
  },
  AvgDialog_15606_Content_32 = {
    Text = "Não, não, escuta, Erica— Essa coisa, essa coisinha minúscula, pode fornecer energia de longo prazo sem perda e sem emissão. Você não entende?"
  },
  AvgDialog_15606_Content_33 = {
    Text = "Carvão, petróleo— não são nada comparados a isso. Se conseguirmos produzir em massa, vamos reescrever toda a infraestrutura energética da humanidade. Vamos entrar para a história!"
  },
  AvgDialog_15606_Content_34 = {
    Text = "Você tem que me dizer como você fez isso. Tem que dizer!"
  },
  AvgDialog_15606_Content_35 = {
    Text = "Erica, aonde você vai? Como assim você não sabe como é feito? Erica!"
  },
  AvgDialog_15606_Content_36 = {
    Text = "O investidor disse que, assim que ele vir um protótipo, está disposto a nos fornecer um financiamento enorme, até mesmo uma oficina dedicada."
  },
  AvgDialog_15606_Content_37 = {
    Text = "Por que você não escuta— eu não sei como essa coisa é feita. Eu não consigo fazer!"
  },
  AvgDialog_15606_Content_38 = {
    Text = "Já passei da idade de acreditar em contos de fadas, Erica. Um <Blue:Vendedor Misterioso>? Se vai me enrolar, pelo menos invente uma desculpa melhor."
  },
  AvgDialog_15606_Content_39 = {
    Text = "Você claramente consegue fazer algo tão incrível. Por que não consegue enxergar o panorama geral?"
  },
  AvgDialog_15606_Content_4 = {
    Text = "Eu consigo te ouvir."
  },
  AvgDialog_15606_Content_40 = {
    Text = "Por que você insiste em se prender num lugar como este, mexendo com sucata?"
  },
  AvgDialog_15606_Content_41 = {
    Text = "As palavras de Mei atingiram Erica como um tapa no rosto. Ela encarou sua parceira, sua companheira, sem conseguir acreditar no que estava ouvindo."
  },
  AvgDialog_15606_Content_42 = {
    Text = "...Sucata. É isso que você realmente pensa?"
  },
  AvgDialog_15606_Content_43 = {
    Text = "Eu pensei que compartilhávamos o mesmo sonho."
  },
  AvgDialog_15606_Content_44 = {
    Text = "Mei cerrou os dentes e apertou o cilindro com mais força."
  },
  AvgDialog_15606_Content_45 = {
    Text = "Encare os fatos, Erica. Ninguém mais quer gastar dinheiro com autômatos. Nova energia— essa é a Saída para nós."
  },
  AvgDialog_15606_Content_46 = {
    Text = "...Largue a fonte de energia especial."
  },
  AvgDialog_15606_Content_47 = {
    Text = "Pense em tudo que poderíamos ter— mais financiamento, mais recursos.\nCom isso, você pode continuar seu sonho. Com isso, você pode—"
  },
  AvgDialog_15606_Content_48 = {
    Text = "Eu disse para largar!"
  },
  AvgDialog_15606_Content_49 = {
    Text = "Erica avançou para arrancá-lo. Mei não conseguiu desviar a tempo e colidiu com um armário próximo."
  },
  AvgDialog_15606_Content_5 = {
    Text = "Desculpa por isso. Prometo que vou focar no módulo de voz a seguir! Apenas aguente um pouco, tá?"
  },
  AvgDialog_15606_Content_50 = {Text = "!!"},
  AvgDialog_15606_Content_51 = {
    Text = "Garrafas e frascos cheios de diversos reagentes e combustíveis começaram a cair. Você se jogou para frente para proteger as duas, e no segundo seguinte—"
  },
  AvgDialog_15606_Content_6 = {Text = "Assentir."},
  AvgDialog_15606_Content_7 = {
    Text = "Pai Deus abençoe, que ótimo. Eu estava com muito medo de que algum fio tivesse queimado."
  },
  AvgDialog_15606_Content_8 = {
    Text = "Ela soltou um suspiro de alívio, depois deu um grande bocejo como se o cansaço tivesse finalmente a alcançado."
  },
  AvgDialog_15606_Content_9 = {
    Text = "Preciso ir pegar uma xícara de café, e jantar..."
  },
  AvgDialog_15607_Content_1 = {
    Text = "O canhão de plasma disparou contra a mão gigante. A Prata se soltou da palma sob o Impacto e caiu silenciosamente no chão."
  },
  AvgDialog_15607_Content_10 = {
    Text = "O que... eu... fiz..."
  },
  AvgDialog_15607_Content_11 = {
    Text = "Você ainda não entende. Mas não importa—você já acendeu esta revolução de vida e alma—esta <Red:\"Transcendência\">.\nMorra em paz. Eu garantirei que o mundo inteiro se lembre de sua contribuição."
  },
  AvgDialog_15607_Content_12 = {
    Text = "Erica fechou os olhos."
  },
  AvgDialog_15607_Content_13 = {
    Text = "Você está... certa, você sempre esteve..."
  },
  AvgDialog_15607_Content_14 = {
    Text = "Lágrimas negras escorreram dos cantos de seus olhos. Ela franziu o nariz, então de repente se virou para olhar para você."
  },
  AvgDialog_15607_Content_15 = {
    Text = "Eu deveria ter... ouvido... você... desde o início... Eu... não deveria ter pego essa coisa..."
  },
  AvgDialog_15607_Content_16 = {
    Text = "Minha sanidade... minha... ajude-me... desta uma última vez..."
  },
  AvgDialog_15607_Content_17 = {
    Text = "Existe realmente uma terceira consciência dentro deste corpo, ou você é meramente a manifestação da culpa dela sob a influência da Fusão? Você não tem como saber."
  },
  AvgDialog_15607_Content_18 = {
    Text = "Ela estende a mão em sua direção."
  },
  AvgDialog_15607_Content_19 = {
    Text = "Me ajude... salvar..."
  },
  AvgDialog_15607_Content_2 = {
    Text = "Após um momento de imobilidade, a mão gigante desmoronou e se desintegrou. Lodo negro despejou como uma chuva torrencial — passou através de você, mas manchou o fantasma de Erica de negro."
  },
  AvgDialog_15607_Content_20 = {
    Text = "Tudo o que você sabe é que vai ajudá-la, e testemunhar o fim dela como \"humana.\""
  },
  AvgDialog_15607_Content_21 = {
    Text = "Segurar a mão dela"
  },
  AvgDialog_15607_Content_22 = {
    Text = "Ela olha para você surpresa, como se nunca tivesse imaginado que poderia realmente tocar sua própria \"sanidade.\""
  },
  AvgDialog_15607_Content_23 = {Text = "Nódulo"},
  AvgDialog_15607_Content_24 = {
    Text = "Ela olha para você surpresa, como se nunca esperasse que sua própria \"consciência\" pudesse lhe dar uma resposta."
  },
  AvgDialog_15607_Content_25 = {
    Text = "Obrigado..."
  },
  AvgDialog_15607_Content_26 = {
    Text = "O fantasma se despedaça e se dissipa como uma bolha, deixando Apenas o orbe de luz Piscando, ainda emitindo seu brilho final."
  },
  AvgDialog_15607_Content_27 = {
    Text = "Você embala o agora diminuto orbe de luz em seus braços e olha em direção à Prata estilhaçada por perto."
  },
  AvgDialog_15607_Content_28 = {
    Text = "Você terá sucesso."
  },
  AvgDialog_15607_Content_3 = {
    Text = "Está... acabou..."
  },
  AvgDialog_15607_Content_4 = {
    Text = "Você realmente acha isso?"
  },
  AvgDialog_15607_Content_5 = {Text = "!?"},
  AvgDialog_15607_Content_6 = {
    Text = "Eu disse, Apenas eu entrar neste coração de Prata, a verdadeira imortalidade me aguarda."
  },
  AvgDialog_15607_Content_7 = {
    Text = "Lute o quanto quiser. A substância negra eventualmente vai apagá-la, e então eu poderei trazer a verdadeira <Red:\"Metamorfose\"> ao mundo — Todos agraciados com a imortalidade, Todos agraciados com a vida eterna."
  },
  AvgDialog_15607_Content_8 = {
    Text = "Isso é... morte... não..."
  },
  AvgDialog_15607_Content_9 = {
    Text = "Mais e mais escuridão consumia o corpo Dela. Erica se dobrou em agonia, Seu espírito à beira do colapso."
  },
  AvgDialog_15608_Content_1 = {
    Text = "Isso é... o Espaço mental?"
  },
  AvgDialog_15608_Content_2 = {
    Text = "Meu Deus, o que é isso, o que é isso..."
  },
  AvgDialog_15608_Content_3 = {
    Text = "Uma voz... Erica!"
  },
  AvgDialog_15609_Content_1 = {
    Text = "Não, Erica, não acredite nisso!"
  },
  AvgDialog_15609_Content_10 = {
    Text = "Um corpo de Carne e sangue não passa de Grilhões para a alma. Apenas libertando a alma ela poderá se juntar a nós.\nApenas um corpo e uma mente de metal podem nos conceder a eternidade."
  },
  AvgDialog_15609_Content_11 = {
    Text = "Os dedos se apertaram, e uma expressão de agonia apareceu no rosto de Mei."
  },
  AvgDialog_15609_Content_12 = {
    Text = "<Shake:Você... enlouqueceu...>"
  },
  AvgDialog_15609_Content_13 = {
    Text = "Outra mão trêmula apareceu no quadro. Erica agarrou o próprio pulso e girou, destacando a mão incontrolável e jogando-a de lado."
  },
  AvgDialog_15609_Content_14 = {
    Text = "A mão gigante hesitou por um momento, como se estivesse um pouco confusa."
  },
  AvgDialog_15609_Content_15 = {
    Text = "Por que resistir a mim? Estou dando a ela um novo nascido curado."
  },
  AvgDialog_15609_Content_16 = {
    Text = "Ilusão, é tudo, uma Ilusão."
  },
  AvgDialog_15609_Content_17 = {
    Text = "Erica segurou a inconsciente Mei e lentamente se pôs de pé."
  },
  AvgDialog_15609_Content_18 = {
    Text = "Preciso levá-la a um hospital. Preciso... mantê-la viva."
  },
  AvgDialog_15609_Content_19 = {
    Text = "Ela apoiou Mei sobre o ombro, atravessou o estúdio destruído pela explosão e seguiu em direção à Porta não muito distante."
  },
  AvgDialog_15609_Content_2 = {
    Text = "Erica, Erica!"
  },
  AvgDialog_15609_Content_3 = {
    Text = "Enquanto você lutava contra o inimigo à sua frente, um monstro feito de lodo circulou por trás de você e se lançou sobre o orbe de luz que representava o espírito de Erica."
  },
  AvgDialog_15609_Content_4 = {
    Text = "Como tinta derramada na água, a escuridão se espalhou Dentro do orbe de luz, cobrindo tudo.\nO orbe de luz começou a parpadejar."
  },
  AvgDialog_15609_Content_5 = {
    Text = "O que está acontecendo, minhas mãos... sozinhas..."
  },
  AvgDialog_15609_Content_6 = {
    Text = "Isso é obra sua? Pare, <Big:pare com isso!>"
  },
  AvgDialog_15609_Content_7 = {
    Text = "Por quê, você não quer mais salvar Ela?"
  },
  AvgDialog_15609_Content_8 = {
    Text = "Você está tentando estrangulá-la! Solte!"
  },
  AvgDialog_15609_Content_9 = {
    Text = "Entre flashes de escuridão e luz, você viu a mão mecânica se aproximar cada vez mais do pescoço de Mei."
  },
  AvgDialog_15610_Content_1 = {
    Text = "A linha de defesa de uma pessoa era praticamente Nenhuma. Não importava quantos Monstros você despedaçasse, seus corpos feitos de limo conseguiam se reagrupar rapidamente, passar por você e saltar direto no orbe de luz."
  },
  AvgDialog_15610_Content_10 = {
    Text = "Plasma dourado crepitou através da sombra, e a forma de Erica se tornou cada vez mais sólida."
  },
  AvgDialog_15610_Content_11 = {
    Text = "Ela ergueu a mão e dispersou os Monstros diante de você com plasma. A mão gigante se agitou levemente e soltou um suspiro."
  },
  AvgDialog_15610_Content_12 = {
    Text = "Eu Apenas queria retribuir por me trazer de volta e me dar um novo corpo. Por que você precisa me causar tanto Dano?"
  },
  AvgDialog_15610_Content_13 = {
    Text = "Trazida de volta? O que quer dizer com trazida de volta? Eu nunca..."
  },
  AvgDialog_15610_Content_14 = {
    Text = "Essa coisa pode alimentar minha marionete?"
  },
  AvgDialog_15610_Content_15 = {
    Text = "Erica segurou o tubo de metal negro com desconfiança, examinando-o de todos os ângulos."
  },
  AvgDialog_15610_Content_16 = {
    Text = "Se está preocupada que ele não consiga sustentar a operação prolongada da marionete, não há necessidade.\nAlgo assim é mais do que suficiente para alimentar algo muito mais complexo e massivo."
  },
  AvgDialog_15610_Content_17 = {
    Text = "Está dizendo que outra pessoa está usando esse tipo de fonte de energia?"
  },
  AvgDialog_15610_Content_18 = {
    Text = "Algo semelhante? Sim. Mas uma cópia exata? Absolutamente impossível."
  },
  AvgDialog_15610_Content_19 = {
    Text = "O que você queria era uma \"fonte de energia única,\" e a lojinha da Daffodil nunca decepciona seus clientes."
  },
  AvgDialog_15610_Content_2 = {
    Text = "Droga... de..."
  },
  AvgDialog_15610_Content_20 = {
    Text = "Ah, e um lembrete amigável — não fique curiosa sobre sua construção ou como funciona.\nUma vez que a caixa de Pandora é aberta, você terá que arcar com as consequências sozinha."
  },
  AvgDialog_15610_Content_21 = {
    Text = "Eu odiaria ver uma gênia como você morrer jovem. Além do projetor, tenho tantas outras ideias que quero dar vida."
  },
  AvgDialog_15610_Content_22 = {
    Text = "Ansioso pela sua próxima visita, Erica."
  },
  AvgDialog_15610_Content_23 = {
    Text = "Não, isso é impossível. Dentro da Fonte de Energia S, havia claramente apenas—"
  },
  AvgDialog_15610_Content_24 = {
    Text = "Um pequeno <Yellow:fragmento de Prata>, certo?\nUma coisinha maravilhosa — não só pode alimentar maquinário, como também pode preservar as almas de seres vivos."
  },
  AvgDialog_15610_Content_25 = {
    Text = "Seu espírito já se fundiu com este corpo com a ajuda da substância negra. Apenas você entrar no <Yellow:coração de Prata> antes de ser corroída por eles, você pode alcançar a verdadeira imortalidade. Você e eu.\n\nComo minha \"Mãe\" nesta vida, você tem o direito de compartilhá-lo comigo.\nUma pena que teve que ser tão teimosa."
  },
  AvgDialog_15610_Content_26 = {
    Text = "Não tenho escolha senão deixar a <Yellow:substância negra> Devorar você."
  },
  AvgDialog_15610_Content_27 = {
    Text = "A mão gigante subitamente entrou em movimento, abrindo seus cinco dedos para revelar a palma. A Prata em seu interior estava coberta de rachaduras, mas ainda brilhava intensamente."
  },
  AvgDialog_15610_Content_28 = {
    Text = "Adeus, minha breve criadora."
  },
  AvgDialog_15610_Content_3 = {
    Text = "O orbe de luz parpadeou novamente, e você viu as pernas de Erica tremendo incontrolavelmente."
  },
  AvgDialog_15610_Content_4 = {
    Text = "Engrenagens se entrelaçaram e se apertaram umas contra as outras, e arcos de eletricidade amarelo-brilhante faiscaram entre os canos e suportes."
  },
  AvgDialog_15610_Content_5 = {
    Text = "Pare de resistir. Entregue o controle do seu corpo a mim."
  },
  AvgDialog_15610_Content_6 = {
    Text = "Você não quer mais salvá-la? Não quer que ela obtenha a eternidade junto com você?"
  },
  AvgDialog_15610_Content_7 = {
    Text = "Mais arcos de eletricidade surgiram na cena."
  },
  AvgDialog_15610_Content_8 = {
    Text = "Partículas cintilantes se dissiparam do orbe de luz, reunindo-se para formar um fantasma humanoide."
  },
  AvgDialog_15610_Content_9 = {Text = "E-Erica?!"},
  AvgDialog_15611_Content_1 = {
    Text = "Por que salvá-la?\nEla trocou o seu Sonho pela própria carreira. Você realmente não sente nenhum Rancor?"
  },
  AvgDialog_15611_Content_10 = {
    Text = "Mas logo eu entendi: isto não é um desastre, não é uma Ilusão, mas uma oportunidade para a humanidade."
  },
  AvgDialog_15611_Content_11 = {
    Text = "Nenhuma dor ou morte nas máquinas; nas máquinas, podemos criar um verdadeiro Reino Divino, melhor do que o seu falso.\n\nPodemos transcender a vida de Caro."
  },
  AvgDialog_15611_Content_12 = {
    Text = "Limo negro escorreu da mão gigante mais uma vez. As gotas tremiam e se contorciam, rastejando para frente enquanto se fundiam umas às outras, vibrando de Empolgação diante da visão sinistra que a voz pintava."
  },
  AvgDialog_15611_Content_13 = {
    Text = "A voz atingiu um crescendo. A mão gigante balançou, arremessando mais limo, mais Monstros."
  },
  AvgDialog_15611_Content_14 = {
    Text = "Nós podemos nos tornar deuses nós mesmos."
  },
  AvgDialog_15611_Content_15 = {
    Text = "O limo acelerou subitamente, avançando mais uma vez em direção ao orbe de luz atrás de você."
  },
  AvgDialog_15611_Content_2 = {
    Text = "Ela Apenas... tomou uma decisão errada.\nQuando ela acordar, vamos conversar, e tudo pode ser resolvido."
  },
  AvgDialog_15611_Content_3 = {
    Text = "O telefone público mais próximo fica a um Quilômetro de distância. Ela não pode esperar."
  },
  AvgDialog_15611_Content_4 = {
    Text = "Desculpe, prefiro acreditar na vontade de sobreviver da humanidade do que nas suas bobagens sobre \"libertar almas\"."
  },
  AvgDialog_15611_Content_5 = {
    Text = "Se minhas palavras são falsas, como você explica seu Estado atual?\nSeu corpo de Carne e sangue se despedaçou, mas seu espírito persiste, e pode até controlar este corpo para continuar vivendo.\n\nIsso não é prova suficiente do que eu digo?"
  },
  AvgDialog_15611_Content_6 = {
    Text = "<Big:Você não pode ter certeza de que essa é a razão pela qual me tornei assim!>"
  },
  AvgDialog_15611_Content_7 = {
    Text = "Erica parou. Ela parecia querer respirar, mas já havia perdido os órgãos para fazê-lo."
  },
  AvgDialog_15611_Content_8 = {
    Text = "O que estou fazendo, discutindo com uma Ilusão... Não ouça, não pense, é uma Ilusão, uma Ilusão causada por fumaça tóxica—"
  },
  AvgDialog_15611_Content_9 = {
    Text = "Você está com medo, então tenta fugir.\nEu entendo. Quando eu tinha Apenas completado minha <Red:\"Metamorfose\">, eu estava cheia de medo assim como você."
  },
  AvgDialog_15612_Content_1 = {
    Text = "Um ritmo invisível envolve você, cerca você. Pontos de luz Faint cintilam ao longe, parecendo Frágeis e impossivelmente distantes."
  },
  AvgDialog_15612_Content_10 = {
    Text = "<Gray: Nem pensar... Poderia ser...>"
  },
  AvgDialog_15612_Content_11 = {
    Text = "Será que neste momento, você e a Erica estão compartilhando o mesmo corpo?\nSerá que essa é a razão pela qual ela se tornou um autômato mecânico?"
  },
  AvgDialog_15612_Content_12 = {
    Text = "<Gray:Mas como uma explosão comum poderia ter esse tipo de Efeito?>"
  },
  AvgDialog_15612_Content_13 = {
    Text = "Você quer salvá-la?"
  },
  AvgDialog_15612_Content_14 = {Text = "?!"},
  AvgDialog_15612_Content_15 = {
    Text = "Uma voz surge do nada—onipresente, porém irrastreável.\nVocê olha ao redor. Dentro do vasto e vazio Espaço mental, uma silhueta começa a emergir."
  },
  AvgDialog_15612_Content_16 = {
    Text = "Quem, quem está aí?"
  },
  AvgDialog_15612_Content_17 = {
    Text = "Eu sou a vontade que responde ao seu chamado, a vida à qual você deu um corpo completamente novo."
  },
  AvgDialog_15612_Content_18 = {
    Text = "Você pode me chamar de sua Criação, e você, é minha \"mãe\" nesta vida."
  },
  AvgDialog_15612_Content_19 = {
    Text = "Uma mão enorme se condensou atrás do orbe de luz que representava o espírito de Erica, suas pontas dos dedos se contorcendo e tremendo, gotejando gotas de lodo negro."
  },
  AvgDialog_15612_Content_2 = {
    Text = "Mei, Mei! Acorde, Mei!"
  },
  AvgDialog_15612_Content_20 = {
    Text = "...Pessoa Tick–Tock...?"
  },
  AvgDialog_15612_Content_21 = {
    Text = "Eu gosto desse nome. Sim, me chame de Pessoa Tick–Tock.\nComo retribuição por me conceder um novo nascido curado, eu posso ajudá–lo a salvar Ela.\nVocê Apenas precisa soltar."
  },
  AvgDialog_15612_Content_22 = {
    Text = "Solte, e então, deixe tudo comigo."
  },
  AvgDialog_15612_Content_23 = {
    Text = "O lodo acumulado no chão de repente se agitou. Eles se fundiram uns com os outros, coalescendo em formas individuais retorcidas, se contorcendo e rastejando em direção à luz."
  },
  AvgDialog_15612_Content_3 = {
    Text = "Você se apressa em direção à origem da voz."
  },
  AvgDialog_15612_Content_4 = {
    Text = "É uma esfera de luz suspensa no ar. Através dela, você vê um rosto coberto de Sangue e poeira—o rosto de Mei."
  },
  AvgDialog_15612_Content_5 = {
    Text = "Ela parece estar em Desmaio. Mesmo quando uma mão pálida a acaricia suavemente, não há resposta."
  },
  AvgDialog_15612_Content_6 = {
    Text = "<Gray:Aquela mão...>"
  },
  AvgDialog_15612_Content_7 = {
    Text = "Você olha para baixo e confirma a suspeita em sua mente: a mão mostrada na esfera de luz é idêntica à sua.\nÉ a mão de um autômato, agora se movendo de acordo com a vontade de outra pessoa."
  },
  AvgDialog_15612_Content_8 = {
    Text = "Droga, Mei! Precisamos sair daqui, Mei!"
  },
  AvgDialog_15612_Content_9 = {
    Text = "A mão mecânica se move para repousar no ombro de Mei. A cena dentro da esfera de luz muda, revelando a oficina ainda em chamas, como se alguém estivesse olhando ao redor freneticamente."
  },
  AvgDialog_15613_Content_1 = {
    Text = "Um Final Brilhante"
  },
  AvgDialog_15613_Content_10 = {
    Text = "Pé direito."
  },
  AvgDialog_15613_Content_11 = {
    Text = "Erica desaba para frente, caindo de joelhos. Os curtos-circuitos excessivamente frequentes roubaram a energia de sua perna esquerda, deixando-a mal conseguindo se apoiar com o braço direito, ao qual falta a mão."
  },
  AvgDialog_15613_Content_12 = {
    Text = "Ela cuidadosamente encosta Mei contra a cabine telefônica, depois rasteja para dentro de quatro.\nA corrente elétrica força a cabine a se ativar. Ela pressiona o botão de chamada de emergência e diz a localização da cabine telefônica."
  },
  AvgDialog_15613_Content_13 = {
    Text = "Dessa forma... ela... estará segura..."
  },
  AvgDialog_15613_Content_14 = {
    Text = "O que... vem... depois..."
  },
  AvgDialog_15613_Content_15 = {
    Text = "Você sabe o que é."
  },
  AvgDialog_15613_Content_16 = {
    Text = "Você se lembra agora—o conteúdo do arquivo que leu antes de entrar neste lugar."
  },
  AvgDialog_15613_Content_17 = {
    Text = "A.F. 297, @1/@1, 03:47. Uma explosão não identificada ocorreu a sudeste da cidade de @1@2@1, Província de @3, República de Agro. A onda de choque provocou um terremoto local de magnitude 3,8, com tremores perceptíveis alcançando vilarejos a 5 quilômetros da cidade de @1@2@1.\n\n...\n\nA.F. 297, @1/@1. 13 componentes foram recuperados da floresta a sudeste da cidade de @3@1@2@1, Província de @3, República de Agro, numerados de A101 a A114. Entre eles, os componentes A108, A109 e A113 estavam severamente danificados e foram entregues à Doll para reconstrução de projeto.\nA equipe de investigação recuperou uma série de plantas de projeto do Caminho @2 Nº @1. Os desenhos correspondem aos componentes remanescentes encontrados no local da explosão e suspeita-se que sejam plantas do dispositivo explosivo. Também foram entregues à Doll para análise."
  },
  AvgDialog_15613_Content_18 = {
    Text = "Você ouve o som do vento roçando as folhas."
  },
  AvgDialog_15613_Content_19 = {
    Text = "O orbe de luz ficou muito fraco, quase se fundindo com a escuridão ao redor."
  },
  AvgDialog_15613_Content_2 = {
    Text = "Pé esquerdo."
  },
  AvgDialog_15613_Content_20 = {
    Text = "Mesmo que você salve o corpo de carne e sangue dela, e daí?\nA morte virá eventualmente. Quando vier, ela vai te agradecer, ou te ressentir por roubar dela a chance de imortalidade?\n\nDesista, Erica. Deixe-me assumir este corpo.\nEu concederei a ela a <Red:\"Metamorfose\">, e lhe darei um futuro melhor."
  },
  AvgDialog_15613_Content_21 = {
    Text = "Eu... sempre pensei... que morreria numa explosão...\nDesculpe... por... arrastar você comigo..."
  },
  AvgDialog_15613_Content_22 = {
    Text = "...O que você está fazendo?"
  },
  AvgDialog_15613_Content_23 = {
    Text = "Cale a boca... demônio... Não estou... falando com você..."
  },
  AvgDialog_15613_Content_24 = {
    Text = "A imagem que aparece dentro do orbe de luz é uma mão mecânica, já coberta de marcas de queimadura, ainda vazando eletroplasma continuamente."
  },
  AvgDialog_15613_Content_25 = {
    Text = "Em algum momento, a mão havia agarrado vários fios, cobertos de lodo negro."
  },
  AvgDialog_15613_Content_26 = {
    Text = "Me desculpe, Pessoa Tick-Tock... No fim... Eu tenho que... destruir você com minhas próprias mãos..."
  },
  AvgDialog_15613_Content_27 = {
    Text = "O Silêncio desce entre vocês.\nVocê ainda não tem certeza da sua Identidade neste Sonho, e ela também não parece estar esperando uma resposta."
  },
  AvgDialog_15613_Content_28 = {
    Text = "*suspiro*..."
  },
  AvgDialog_15613_Content_29 = {
    Text = "Que... pena..."
  },
  AvgDialog_15613_Content_3 = {
    Text = "Pé direito."
  },
  AvgDialog_15613_Content_30 = {
    Text = "Ela puxa com toda a sua força."
  },
  AvgDialog_15613_Content_32 = {
    Text = "Você se levanta de um salto, encontrando-se de volta ao seu quarto familiar."
  },
  AvgDialog_15613_Content_33 = {
    Text = "Alguém está batendo na sua porta."
  },
  AvgDialog_15613_Content_34 = {Text = "Entre."},
  AvgDialog_15613_Content_35 = {
    Text = "Boa tarde, Guardião. Você tem uma mensagem da Boneca. Gostaria de recebê-la?"
  },
  AvgDialog_15613_Content_36 = {
    Text = "Que nova funcionalidade Doll preparou para você desta vez... Receber."
  },
  AvgDialog_15613_Content_37 = {
    Text = "Bip— Você se lembra que dia é hoje, %player%? Duas palavras para você: a prova."
  },
  AvgDialog_15613_Content_38 = {
    Text = "...Ah, não."
  },
  AvgDialog_15613_Content_39 = {
    Text = "Sugiro que apareça na sala de aula dentro de cinco minutos, ou não posso garantir como será sua vida de treinamento nos próximos 30 dias. Talvez o regime de treinamento físico seja dobrado?"
  },
  AvgDialog_15613_Content_4 = {
    Text = "A cada passo, faíscas voam. A cada passo, o som estridente de maquinário rangendo contra si mesmo pode ser ouvido."
  },
  AvgDialog_15613_Content_40 = {
    Text = "Bip— Fim da mensagem. Gostaria de responder?"
  },
  AvgDialog_15613_Content_41 = {
    Text = "Responder?! Não tem tempo para isso, tenho que correr!!"
  },
  AvgDialog_15613_Content_42 = {
    Text = "A figura do Guardião desapareceu no final do corredor. Erica se virou e olhou para os documentos espalhados pela mesa."
  },
  AvgDialog_15613_Content_43 = {
    Text = "Aluvião 298, @1/@2, Departamento de Despertar da Universidade de Misag, @3\nRestauração do torso do autômato E concluída com base na planta T-38, número de série EA301881.\nEsta é nossa 10ª tentativa de restauração. Devo admirar quem originalmente projetou e fez a Criação disto— o autômato é extraordinariamente intrincado e elegante. Centenas e milhares de engrenagens e rolamentos se interligam, juntos executando uma magnífica sinfonia de engenharia mecânica. Mesmo agora, enquanto permanece imóvel, consigo sentir uma vitalidade única dentro dele.\nInfelizmente, ainda não encontramos a chave para a planta do motor— um cilindro de 5 centímetros de diâmetro e 10 centímetros de comprimento. Deveria ser o núcleo de energia de todo o autômato, mas nunca vi algo desse tamanho capaz de alimentar um mecanismo tão complexo...\nEspero que a Professora Doll consiga pensar em algo. Mal posso esperar para vê-lo realmente ganhar vida."
  },
  AvgDialog_15613_Content_44 = {
    Text = "Aluvião 298, @1/@2, Departamento de Despertar da Universidade de Misag, @3\nRestauração do motor concluída, número de série MF311028.\nEmbora tenhamos encontrado bastantes contratempos ao longo do caminho (Pai Deus, fizemos 28 tentativas completas, 28!), a hipótese final da Professora Doll se provou correta— o núcleo de energia do motor é um Núcleo de prata.\nApós testar múltiplos Núcleos de prata, Apenas o Núcleo de prata E-1929 permitiu que o motor funcionasse corretamente. Não consigo deixar de imaginar que esta é alguma influência remanescente da vontade do projetista, embora ainda não saibamos o paradeiro dessa pessoa."
  },
  AvgDialog_15613_Content_45 = {
    Text = "Aluvião 300, @2/@1, Departamento de Despertar da Universidade de Misag, Doll\nO autômato Erica Despertou com sucesso.\nO Corpo Desperto exibe agressividade extrema e impulsos destrutivos. Mesmo com um Investigador mantendo Seu Estado mental, Ela ainda demonstra claras tendências de Ataque e Libera correntes elétricas incontrolavelmente, conduzindo ataques indiscriminados aos objetos ao redor.\nAlistair determinou que E–1929 contém dois espíritos— um avassaladoramente poderoso em sua Loucura, e outro que, embora fraco, possui maior racionalidade. Deve-se tentar Separar os dois, ou Inibir a Loucura a um nível controlável.\n...\nAluvião 300, @2/@2, Departamento de Despertar da Universidade de Misag, Doll\nImpossível Separar os espíritos. Considerando ativamente o segundo plano.\nUm dispositivo de Inibição de espírito é uma boa ideia.\n...\nAluvião 303, @1/@2, Departamento de Despertar da Universidade de Misag, Doll\nDispositivo de Inibição criado e instalado com sucesso.\nA Loucura do Corpo Desperto foi Inibida. Estado geral tendendo à estabilidade, embora breves falhas na Inibição ainda ocorram.\nA personalidade, interesses e outros traços do Corpo Desperto foram completamente perdidos. Seu comportamento se assemelha mais ao de uma boneca do que ao de uma pessoa.\nPelo menos Ela não está mais à beira de explodir a cada momento.\n..."
  },
  AvgDialog_15613_Content_46 = {
    Text = "Erica inclinou a cabeça, organizou os documentos e saiu do quarto."
  },
  AvgDialog_15613_Content_5 = {
    Text = "Sob um poste de luz não muito distante, uma cabine telefônica pública permanece em silêncio."
  },
  AvgDialog_15613_Content_6 = {
    Text = "Pé esquerdo."
  },
  AvgDialog_15613_Content_7 = {
    Text = "Pé direito."
  },
  AvgDialog_15613_Content_8 = {
    Text = "Como se percebesse sua determinação, a gosma espalhada no chão continua seu ataque à consciência de Erica, tingindo até você de negro absoluto."
  },
  AvgDialog_15613_Content_9 = {
    Text = "Pé esquerdo."
  },
  AvgDialog_18708_Content_1 = {
    Text = "Um som nauseante e úmido de dilaceração se ergue no ar. Enormes patas de aranha irrompem pelos corpos dos oficiais e dos transeuntes, espirrando sangue espesso com cheiro de ferro por todo você."
  },
  AvgDialog_18708_Content_10 = {
    Text = "Acompanhado por gemidos dolorosos, as feições do Caçador de Crânios se contorceram a um grau inacreditável, com cistos cheios de pus se retorcendo sob a pele, prontos para estourar."
  },
  AvgDialog_18708_Content_11 = {
    Text = "O que é isto...?"
  },
  AvgDialog_18708_Content_13 = {
    Text = "Sua cabeça é implacavelmente severa, lodo D preto jorrando do pescoço, quase respingando em seu rosto."
  },
  AvgDialog_18708_Content_14 = {
    Text = "Ser excessivamente curioso não é um bom hábito, Guardião."
  },
  AvgDialog_18708_Content_15 = {
    Text = "Seu crânio estava cheio de D-Slime acumulado. Eu sugiro que você mantenha sua distância."
  },
  AvgDialog_18708_Content_16 = {
    Text = "Lady Daffodil!"
  },
  AvgDialog_18708_Content_17 = {
    Text = "Boa noite, minha pequena rosa."
  },
  AvgDialog_18708_Content_18 = {
    Text = "Por que é você de novo...?"
  },
  AvgDialog_18708_Content_19 = {
    Text = "Eu segui a trilha do Caçador de Crânios aqui e recuperei minha flor."
  },
  AvgDialog_18708_Content_2 = {
    Text = "O Caçador de Crânios colapsa pesadamente no chão, emitindo um gemido suave."
  },
  AvgDialog_18708_Content_20 = {
    Text = "Daffodil caminhou sem esforço pelo chão manchado de sangue e D-Slime, pegou um narciso ao lado da cama e o cheirou levemente."
  },
  AvgDialog_18708_Content_21 = {
    Text = "Este é meu Narciso Marrom, que cultivei cuidadosamente por três anos. Ele tem um efeito calmante e reconfortante."
  },
  AvgDialog_18708_Content_22 = {
    Text = "Você gostaria de dar uma cheirada?"
  },
  AvgDialog_18708_Content_23 = {
    Text = "<LightGray:Não é de se admirar que eu tenha dormido tão profundamente agora...>"
  },
  AvgDialog_18708_Content_24 = {
    Text = "Você irritadamente afastou o narciso úmido e em flor em sua mão."
  },
  AvgDialog_18708_Content_25 = {
    Text = "Você parece saber muito sobre o Caçador de Crânios."
  },
  AvgDialog_18708_Content_26 = {
    Text = "Como você sabe que o cérebro dele ia gotejar Limo d?"
  },
  AvgDialog_18708_Content_27 = {
    Text = "Se você tivesse vivido tanto quanto eu e visto suficientes pacientes de Dissolução, você naturalmente entenderia mais."
  },
  AvgDialog_18708_Content_28 = {
    Text = "O Rastro do Caçador de Crânios?"
  },
  AvgDialog_18708_Content_29 = {
    Text = "\"Seguindo o Rastro do Caçador de Caveiras\"—Você consegue sentir sua localização?"
  },
  AvgDialog_18708_Content_3 = {
    Text = "Você ouve \"tum, tum, tum\" vindo das escadas. A porta de madeira atrás de você é repentinamente puxada para abrir."
  },
  AvgDialog_18708_Content_30 = {
    Text = "Eu tenho meus métodos. No entanto... para evitar assustar as crianças, é melhor não revelá-los."
  },
  AvgDialog_18708_Content_31 = {Text = "..."},
  AvgDialog_18708_Content_32 = {
    Text = "Por favor, saia por agora, Senhora Narciso. Não interfira na investigação do Guardião."
  },
  AvgDialog_18708_Content_33 = {
    Text = "Huh, você não está mais duvidando de mim?"
  },
  AvgDialog_18708_Content_34 = {
    Text = "Não consigo descartar completamente sua suspeita ainda. Mas minha intuição me diz..."
  },
  AvgDialog_18708_Content_35 = {
    Text = "Se você fosse o \"Caçador de Caveiras\", lidaria com isso de forma mais limpa e eficiente, não deixando vestígios tão óbvios para trás."
  },
  AvgDialog_18708_Content_36 = {
    Text = "Oh meu, isso é realmente um elogio para mim?\nPara ser preciso, é um fato, não apenas uma intuição."
  },
  AvgDialog_18708_Content_37 = {
    Text = "...Não mude de assunto."
  },
  AvgDialog_18708_Content_38 = {
    Text = "Desde que você chegou na cidade hoje, quem era aquela pessoa que eu vi na noite passada?"
  },
  AvgDialog_18708_Content_39 = {
    Text = "Você tem uma irmã gêmea?"
  },
  AvgDialog_18708_Content_4 = {
    Text = "{Male=Mr.,Female=Miss} %player%, acabei de ouvir um barulho, o que aconteceu?"
  },
  AvgDialog_18708_Content_40 = {Text = "..."},
  AvgDialog_18708_Content_41 = {
    Text = "Daffodil parecia preocupada em pensamento, então de repente estendeu a mão para você."
  },
  AvgDialog_18708_Content_42 = {
    Text = "Dedos suaves tocam seu rosto por um momento, depois deslizam para seu pescoço, parando para sentir o pulso dentro dos seus vasos sanguíneos."
  },
  AvgDialog_18708_Content_43 = {
    Text = "<Shake:...?>"
  },
  AvgDialog_18708_Content_44 = {
    Text = "Eu sempre pensei que os humanos eram criaturas habilidosas em disfarces."
  },
  AvgDialog_18708_Content_45 = {
    Text = "Vocês se envolvem em um Caro semelhante, falando palavras semelhantes, com pulsos e batimentos cardíacos semelhantes..."
  },
  AvgDialog_18708_Content_46 = {
    Text = "Por muito tempo, eu não consegui distinguir entre vocês, assim como vocês não conseguiram me distinguir."
  },
  AvgDialog_18708_Content_47 = {
    Text = "Então... você quer dizer que vocês não são gêmeos, mas compartilham algum tipo de relacionamento especial?"
  },
  AvgDialog_18708_Content_48 = {
    Text = "É possível. Quer fazer uma suposição? Você tem três chances."
  },
  AvgDialog_18708_Content_49 = {
    Text = "...Eu recuso."
  },
  AvgDialog_18708_Content_5 = {
    Text = "E-Isso é...?!"
  },
  AvgDialog_18708_Content_50 = {
    Text = "Mesmo que eu acerte, você ainda não me dirá a verdadeira resposta. Estou correto?"
  },
  AvgDialog_18708_Content_51 = {
    Text = "Daffodil traçou descuidadamente as veias no seu pescoço com as pontas dos dedos, seus olhos cheios de um sorriso ainda mais profundo."
  },
  AvgDialog_18708_Content_52 = {
    Text = "Você está realmente me conhecendo melhor, {Male=Mr.,Female=Miss} Guardião."
  },
  AvgDialog_18708_Content_53 = {
    Text = "Você dá meia passada para trás, saindo do alcance de Narciso, e lhe lança um olhar de advertência."
  },
  AvgDialog_18708_Content_54 = {
    Text = "Em seus olhos, será que a aparência exatamente igual os torna gêmeos?"
  },
  AvgDialog_18708_Content_55 = {
    Text = "De modo geral, esta é provavelmente a única possibilidade."
  },
  AvgDialog_18708_Content_56 = {
    Text = "Mas você e eu sabemos que o mundo em que vivemos é tudo, menos \"comum.\""
  },
  AvgDialog_18708_Content_57 = {
    Text = "Claro. O aspecto mais triste deste mundo é sua \"não-conformidade\""
  },
  AvgDialog_18708_Content_58 = {
    Text = "Ser um par de irmãs gêmeas despreocupadas também parece bom."
  },
  AvgDialog_18708_Content_6 = {
    Text = "Você avança e puxa o capuz preto do Caçador de Crânios, revelando o rosto por baixo"
  },
  AvgDialog_18708_Content_7 = {
    Text = "Maxilares altos, nariz aquilino e bochechas afundadas—um rosto completamente desconhecido."
  },
  AvgDialog_18708_Content_8 = {
    Text = "Você realmente sabe como escolher seus alvos, me seguindo até aqui. Quem exatamente é você?"
  },
  AvgDialog_18708_Content_9 = {
    Text = "Ugh... Ah..."
  },
  AvgDialog_18709_Content_1 = {
    Text = "Chuva amarga"
  },
  AvgDialog_18709_Content_10 = {
    Text = "Você se apoia contra a cabeceira da cama, lembranças de eventos recentes passando diante de seus olhos. Muitas questões ainda precisam ser resolvidas."
  },
  AvgDialog_18709_Content_11 = {
    Text = "Vamos perguntar à Srta. Horla o que ela sabe primeiro."
  },
  AvgDialog_18709_Content_12 = {
    Text = "Pergunte ao Velho Freeman"
  },
  AvgDialog_18709_Content_13 = {
    Text = "O Velho Freeman? Então ele ainda está vivo..."
  },
  AvgDialog_18709_Content_14 = {
    Text = "Ouvi os aldeões dizerem que ele era uma pessoa otimista e alegre quando jovem, e todos gostavam dele."
  },
  AvgDialog_18709_Content_15 = {
    Text = "Após a <Yellow:plague>, ele deixou a Cidade Reny e voltou como uma pessoa completamente diferente."
  },
  AvgDialog_18709_Content_16 = {Text = "Praga?"},
  AvgDialog_18709_Content_17 = {
    Text = "Três anos atrás, um desastre de Dissolução ocorreu ao norte da cidade de Ryker. Os locais referiam-se a isso como uma praga."
  },
  AvgDialog_18709_Content_18 = {
    Text = "Agora se transformou completamente em uma terra estéril."
  },
  AvgDialog_18709_Content_19 = {
    Text = "Pergunte a Daffodil"
  },
  AvgDialog_18709_Content_2 = {Text = "..."},
  AvgDialog_18709_Content_20 = {
    Text = "Senhorita Horla, o tom que você usou ao falar do Narciso agora pouco... vocês duas se conheciam antes?"
  },
  AvgDialog_18709_Content_21 = {
    Text = "A Dama Narciso..."
  },
  AvgDialog_18709_Content_22 = {
    Text = "Horla olhou para a página do livro em sua mão, um sorriso suave brincando em seu rosto."
  },
  AvgDialog_18709_Content_23 = {
    Text = "A Dama Narciso, ela... me ajudou."
  },
  AvgDialog_18709_Content_24 = {
    Text = "Ano 15@1, San Pedro"
  },
  AvgDialog_18709_Content_25 = {
    Text = "Esta coleção de poemas de Longsa é única. Certifique-se de valorizá-la."
  },
  AvgDialog_18709_Content_26 = {
    Text = "Muito obrigado, Senhora Narciso. Não posso acreditar que você realmente encontrou..."
  },
  AvgDialog_18709_Content_27 = {
    Text = "\"Que você retenha para sempre a radiante beleza de uma rosa.\""
  },
  AvgDialog_18709_Content_28 = {
    Text = "Poesia bonita. Você tem excelente gosto."
  },
  AvgDialog_18709_Content_29 = {
    Text = "Sim, mas eu prefiro \"Eu honro este momento com leite e flores...\""
  },
  AvgDialog_18709_Content_3 = {
    Text = "Finalmente acordaste, {Male=Mr.,Female=Miss} Guardião."
  },
  AvgDialog_18709_Content_30 = {
    Text = "Ah... Desculpe, eu me distraí de novo."
  },
  AvgDialog_18709_Content_31 = {
    Text = "Eu conheço as regras da \"Loja de Trocas\". Então, o que você quer de mim?"
  },
  AvgDialog_18709_Content_32 = {
    Text = "Hmm... Vou ter que observar você de perto, minha pequena rosa."
  },
  AvgDialog_18709_Content_33 = {
    Text = "O olhar percorreu todo o corpo de Horla sem emoção. A menina endireitou involuntariamente as costas."
  },
  AvgDialog_18709_Content_34 = {
    Text = "Você pode compartilhar uma memória comigo?  \nDorosa, triste... qualquer memória infeliz servirá."
  },
  AvgDialog_18709_Content_35 = {
    Text = "Memórias infelizes? E-Isso não é uma boa coisa. O que você planeja fazer com elas...?"
  },
  AvgDialog_18709_Content_36 = {
    Text = "Eu planejo usá-lo para um pequeno experimento. Você saberá então."
  },
  AvgDialog_18709_Content_37 = {
    Text = "Dias de exaustão constante erosionaram seus nervos; você adormece ao som das suaves palavras de Horla."
  },
  AvgDialog_18709_Content_38 = {Text = "..."},
  AvgDialog_18709_Content_39 = {
    Text = "Depois de um tempo desconhecido, uma leve garoa começou do lado de fora da janela."
  },
  AvgDialog_18709_Content_4 = {
    Text = "Eu lembro que parece que eu desmaiei, e então..."
  },
  AvgDialog_18709_Content_40 = {
    Text = "Alguém está caminhando lentamente e sem fim pela estrada lamacenta na chuva."
  },
  AvgDialog_18709_Content_41 = {
    Text = "Eles aparecem apenas em noites de chuva, seus passos escondidos pela chuva, se aproximando silenciosamente de você..."
  },
  AvgDialog_18709_Content_42 = {
    Text = "Os Caçadores de Caveira não são uma nem duas pessoas. Os Caçadores de Caveira são uma organização."
  },
  AvgDialog_18709_Content_43 = {
    Text = "Uma noite chuvosa, sozinho... <Red: Não é essa a sua situação atual?>"
  },
  AvgDialog_18709_Content_44 = {
    Text = "<Red:Zzz... Krr...>"
  },
  AvgDialog_18709_Content_45 = {
    Text = "<RedBig:Snap!>"
  },
  AvgDialog_18709_Content_46 = {Text = "?!"},
  AvgDialog_18709_Content_47 = {
    Text = "Um pálido relâmpago fere a quietude da noite. Você abre abruptamente os olhos na escuridão."
  },
  AvgDialog_18709_Content_48 = {
    Text = "Alguém está de pé ao lado da sua cama."
  },
  AvgDialog_18709_Content_49 = {
    Text = "O olhar pesado se sente como uma foice fria e úmida traçando seus membros, costas e..."
  },
  AvgDialog_18709_Content_5 = {
    Text = "Sim, foi a Senhora Narciso quem te trouxe de volta e me instruiu a cuidar bem de você."
  },
  AvgDialog_18709_Content_50 = {
    Text = "Um pescoço desprotegido."
  },
  AvgDialog_18709_Content_51 = {
    Text = "Cabeça@1 Crânio@4"
  },
  AvgDialog_18709_Content_54 = {Text = "Hmm...!!"},
  AvgDialog_18709_Content_55 = {
    Text = "Você de repente cai da cama e instintivamente cobre seu pescoço."
  },
  AvgDialog_18709_Content_56 = {
    Text = "Uma figura sombria segurando uma foice está ao lado da cama, quase se misturando com a noite escura atrás."
  },
  AvgDialog_18709_Content_57 = {
    Text = "O ar está cheio com o cheiro de chuva e ferrugem. Sangue vermelho escuro goteja da lâmina fria e branca, formando uma poça no chão."
  },
  AvgDialog_18709_Content_58 = {
    Text = "—É o Caçador de Crânios."
  },
  AvgDialog_18709_Content_6 = {
    Text = "Daffodil...?"
  },
  AvgDialog_18709_Content_7 = {
    Text = "Você captura um cheiro familiar."
  },
  AvgDialog_18709_Content_8 = {
    Text = "Um vaso de pescoço esguio apareceu na mesa de cabeceira, com flores de narciso brancas esticando suas pétalas em direção à luz do sol."
  },
  AvgDialog_18709_Content_9 = {
    Text = "É o cheiro dela..."
  },
  AvgDialog_18710_Content_1 = {
    Text = "Reino das bestas"
  },
  AvgDialog_18710_Content_10 = {
    Text = "Era uma noite clara de verão, e eu estava diligentemente carregando meus \"despojos\", como de costume."
  },
  AvgDialog_18710_Content_11 = {
    Text = "<Shake:Cabeças... mais cabeças...>"
  },
  AvgDialog_18710_Content_12 = {
    Text = "Tap. Tap. Tap."
  },
  AvgDialog_18710_Content_13 = {
    Text = "O som de passos leves se aproximou silenciosamente, e uma voz suave veio de cima."
  },
  AvgDialog_18710_Content_14 = {
    Text = "Heh... Olhe o que encontrei? Uma pequena besta perdida."
  },
  AvgDialog_18710_Content_15 = {
    Text = "Naquela noite, uma mulher veio até mim."
  },
  AvgDialog_18710_Content_16 = {
    Text = "Quando ela se aproximou de mim, percebi uma fragrância agradável.\nEra o cheiro de flores e névoa."
  },
  AvgDialog_18710_Content_17 = {
    Text = "Este é o cheiro de outro mundo, tão diferente do meu reino quanto o dia é da noite, nunca destinado a se encontrar."
  },
  AvgDialog_18710_Content_18 = {
    Text = "Mas ela ainda marchou através do lodo fedido, atravessou as sombras da cidade e estendeu a mão para mim."
  },
  AvgDialog_18710_Content_19 = {
    Text = "Ela disse..."
  },
  AvgDialog_18710_Content_2 = {
    Text = "Eu sou uma besta... Eu sou um paciente.\n\nEu estou além da redenção."
  },
  AvgDialog_18710_Content_20 = {
    Text = "Você gostaria de vir comigo, pequeirinho?"
  },
  AvgDialog_18710_Content_21 = {
    Text = "5:00, ao norte da cidade de Reni"
  },
  AvgDialog_18710_Content_22 = {
    Text = "Este lugar é... verdadeiramente desolado."
  },
  AvgDialog_18710_Content_23 = {
    Text = "Três anos atrás, um <Yellow:S-Class D-Rift> apareceu aqui. Água, vegetação... todo o ecossistema sofreu danos severos."
  },
  AvgDialog_18710_Content_24 = {
    Text = "Felizmente, houve poucas baixas, e os residentes foram evacuados sob a organização do Comitê."
  },
  AvgDialog_18710_Content_25 = {
    Text = "Você observa as paredes desoladas e as árvores pálidas e murchas à sua frente."
  },
  AvgDialog_18710_Content_26 = {
    Text = "Se não fosse pela Dissolução, este seria um campo verde em plena floração com lilases. Quando o vento sopra, a grama se agita como ondas, parecendo um oceano verde."
  },
  AvgDialog_18710_Content_27 = {
    Text = "Você tem certeza de que o Caçador de Crânios está aqui, Senhora Narciso?"
  },
  AvgDialog_18710_Content_28 = {
    Text = "A única resposta é o grasnar rouco de corvos."
  },
  AvgDialog_18710_Content_29 = {
    Text = "Oh, a Dama dos narcisos está desaparecida?"
  },
  AvgDialog_18710_Content_3 = {
    Text = "Durante o dia, eu me escondo nas sombras da cidade, deitando de costas com a barriga para cima, dormindo tranquilamente."
  },
  AvgDialog_18710_Content_30 = {
    Text = "Bem, as consequências de confiar nos outros."
  },
  AvgDialog_18710_Content_31 = {
    Text = "Ahem. Ela é sempre tão imprevisível em seus movimentos; eu já me acostumei com isso há muito tempo."
  },
  AvgDialog_18710_Content_32 = {
    Text = "Não se preocupe, posso investigar sozinho. Definitivamente encontrarei algo aqui..."
  },
  AvgDialog_18710_Content_33 = {
    Text = "<Big:Boom—!!>"
  },
  AvgDialog_18710_Content_34 = {
    Text = "O trovão retumba nas nuvens baixas, e folhas secas farfalham no vento de outono."
  },
  AvgDialog_18710_Content_35 = {
    Text = "Este é um sinal de chuva."
  },
  AvgDialog_18710_Content_36 = {
    Text = "Por que só aparece em dias de chuva?"
  },
  AvgDialog_18710_Content_37 = {
    Text = "Porque quando chove, sangue e chuva se misturam e fluem para os esgotos."
  },
  AvgDialog_18710_Content_38 = {
    Text = "Sim, flui para os esgotos, caixões e os pequenos canais ao seu redor..."
  },
  AvgDialog_18710_Content_39 = {
    Text = "<Red:Zzz... Krr...>"
  },
  AvgDialog_18710_Content_4 = {
    Text = "À noite, eu vagueio pelas ruas como um fantasma, procurando por uma cabeça após a outra."
  },
  AvgDialog_18710_Content_40 = {
    Text = "Uma noite chuvosa e escura... Não, estou sonhando acordado novamente."
  },
  AvgDialog_18710_Content_41 = {
    Text = "Você sacudiu a cabeça vigorosamente, tentando limpar o caos da sua mente."
  },
  AvgDialog_18710_Content_42 = {
    Text = "O tempo está se esgotando. Você deve agir rapidamente."
  },
  AvgDialog_18710_Content_5 = {
    Text = "<Red:Caveira. Caveira. Caveira.>"
  },
  AvgDialog_18710_Content_6 = {
    Text = "<RedBig:Cabeças.\n        Cabeças.\n                Cabeças.\n                        Cabeças.\n                                Cabeças.\n                                        Cabeças...>"
  },
  AvgDialog_18710_Content_7 = {
    Text = "Minha mente não pode mais contemplar sobrevivência, amor e dignidade.\n\nEla já está cheia até a borda com essas fantasias insaciáveis."
  },
  AvgDialog_18710_Content_8 = {
    Text = "Estou além da redenção."
  },
  AvgDialog_18710_Content_9 = {
    Text = "Ano 15@1, Cidade de San Pedro"
  },
  AvgDialog_18711_Content_1 = {Text = "Ahhhh—!!"},
  AvgDialog_18711_Content_10 = {
    Text = "Ela ignorou a limo e o sangue imundos no chão, agachou-se e encarou a criatura que lutava à sua frente."
  },
  AvgDialog_18711_Content_11 = {
    Text = "Pare de procurar. Eles foram embora e nunca voltarão."
  },
  AvgDialog_18711_Content_12 = {
    Text = "O que você precisa não são essas coisas."
  },
  AvgDialog_18711_Content_13 = {
    Text = "Não precisa...? Não, Head@1, me dê isso."
  },
  AvgDialog_18711_Content_14 = {Text = "..."},
  AvgDialog_18711_Content_15 = {
    Text = "Você sabia? Na verdade... somos iguais.\nEu entendo sua dor."
  },
  AvgDialog_18711_Content_16 = {
    Text = "Ano 15@1, Cidade de San Pedro"
  },
  AvgDialog_18711_Content_17 = {
    Text = "Você vem comigo, pequena besta? Você precisa de ajuda."
  },
  AvgDialog_18711_Content_18 = {
    Text = "Ano 15@1 No verão do primeiro ano, uma mulher estendeu a mão para mim."
  },
  AvgDialog_18711_Content_19 = {
    Text = "Talvez seja seu cheiro agradável, ou talvez ela apenas pareça gentil."
  },
  AvgDialog_18711_Content_2 = {
    Text = "Uma massa de carne colapsa, despejando D-Slime e muco cinza, revelando o corpo frágil de Harriet."
  },
  AvgDialog_18711_Content_20 = {
    Text = "Em resumo, eu não a rejeitei."
  },
  AvgDialog_18711_Content_21 = {
    Text = "Eu ingenuamente segurei a mão dela, e com isso, meu destino futuro."
  },
  AvgDialog_18711_Content_22 = {
    Text = "Cof... Cof..."
  },
  AvgDialog_18711_Content_23 = {
    Text = "Você está morrendo, Narciso."
  },
  AvgDialog_18711_Content_24 = {
    Text = "Criança tola... Depois de todos esses anos, você ainda não aprendeu a falar corretamente."
  },
  AvgDialog_18711_Content_25 = {
    Text = "Não chore... *tosse*..."
  },
  AvgDialog_18711_Content_26 = {
    Text = "<Shake:Eu... eu não...>"
  },
  AvgDialog_18711_Content_27 = {
    Text = "Tome minha cabeça. Confio a você minha identidade, aparência e esta pequena loja."
  },
  AvgDialog_18711_Content_28 = {Text = "?!"},
  AvgDialog_18711_Content_29 = {
    Text = "Eu sei, cough cough... você sempre quis andar pelo mundo como um humano comum."
  },
  AvgDialog_18711_Content_3 = {
    Text = "Cránios cinza-claros surgiram, apenas para desaparecer num piscar de olhos."
  },
  AvgDialog_18711_Content_30 = {
    Text = "Você se esconde no canto, observando como eu falo e ando. Quando estou longe, você secretamente veste minhas roupas e até finge ser eu para fazer amigos..."
  },
  AvgDialog_18711_Content_31 = {
    Text = "Eu sempre soube."
  },
  AvgDialog_18711_Content_32 = {
    Text = "Desculpe, Narciso, eu não quis fazer isso..."
  },
  AvgDialog_18711_Content_33 = {
    Text = "Agora, eu vou realizar seu desejo, ahem... mas você deve me prometer..."
  },
  AvgDialog_18711_Content_34 = {
    Text = "No futuro, não corte casualmente as cabeças dos inocentes. Se encontrar alguém como você, deve ajudá-los."
  },
  AvgDialog_18711_Content_35 = {
    Text = "Apenas como eu estou te ajudando agora."
  },
  AvgDialog_18711_Content_36 = {
    Text = "<Shake:Socorra-me, socorra-me...>"
  },
  AvgDialog_18711_Content_37 = {
    Text = "Harriet solta um uivo animal e, tremendo, estende a mão para Lady Narciso."
  },
  AvgDialog_18711_Content_38 = {Text = "..."},
  AvgDialog_18711_Content_39 = {
    Text = "Naquela época... quando você viu seu marido no cemitério, deve ter se sentido completamente sem esperança, não é?"
  },
  AvgDialog_18711_Content_4 = {
    Text = "Cabeça@1 Não..."
  },
  AvgDialog_18711_Content_40 = {
    Text = "Freeman... Huh.@2..."
  },
  AvgDialog_18711_Content_41 = {
    Text = "Nós suportamos a mesma maldição, mas eu sou muito mais sortudo que você."
  },
  AvgDialog_18711_Content_42 = {
    Text = "Quando eu ainda não conhecia a diferença entre o bem e o mal, foi aquela senhora quem se estendeu para mim."
  },
  AvgDialog_18711_Content_43 = {
    Text = "Daffodil se ajoelhou diante da Sra. Harriet, segurando gentilmente sua mão marcada e coberta de D-Slime."
  },
  AvgDialog_18711_Content_44 = {
    Text = "Eu aprendi a falar e andar como ela, moldando-me à sua imagem."
  },
  AvgDialog_18711_Content_45 = {
    Text = "Cuidado, Senhora Narciso! As mãos da Harriet estão cobertas de Limo d—"
  },
  AvgDialog_18711_Content_46 = {
    Text = "Shh... Eu ainda tenho algo a dizer a ela."
  },
  AvgDialog_18711_Content_47 = {
    Text = "Daffodil continuou a olhar para Harriet. Uma conexão secreta fluía entre elas, isolando-as de todas as distrações."
  },
  AvgDialog_18711_Content_48 = {
    Text = "Agora posso finalmente me relacionar com os outros, assim como ela fez... Mas é tarde demais."
  },
  AvgDialog_18711_Content_49 = {
    Text = "Fumaça roxa pálida sobe lentamente, flutuando na sala sombria."
  },
  AvgDialog_18711_Content_5 = {
    Text = "Harriet, sem cabeça e inquieta, contorcia-se enquanto as veias em seu pescoço pulsavam rapidamente, emitindo um zumbido suave."
  },
  AvgDialog_18711_Content_50 = {
    Text = "Você captura novamente aquele cheiro floral familiar, misturado com a umidade da neblina da meia-noite, diluindo o pesado odor de sangue da sala."
  },
  AvgDialog_18711_Content_51 = {
    Text = "Daffodil colocou a mão ao lado da Sra. Harriet gentilmente."
  },
  AvgDialog_18711_Content_52 = {
    Text = "Fique tranquilo, Lady Harriet. Você não sentirá dor alguma."
  },
  AvgDialog_18711_Content_53 = {
    Text = "Uma fenda se rasga rapidamente da palma dela, engolfando lentamente Harriet..."
  },
  AvgDialog_18711_Content_54 = {
    Text = "<Shake:...>"
  },
  AvgDialog_18711_Content_55 = {
    Text = "Diga ao meu marido@2 para parar de beber."
  },
  AvgDialog_18711_Content_56 = {
    Text = "Há mais..."
  },
  AvgDialog_18711_Content_57 = {
    Text = "A garganta exposta de Harriet tremeu levemente, mas finalmente caiu em silêncio como uma folha murcha."
  },
  AvgDialog_18711_Content_58 = {
    Text = "Ela soltou a mão de Narciso e caiu silenciosamente em uma fenda dimensional insondável."
  },
  AvgDialog_18711_Content_59 = {
    Text = "<Change>Adeus, adeus..."
  },
  AvgDialog_18711_Content_6 = {
    Text = "Me dê@2 cabeças, me dê..."
  },
  AvgDialog_18711_Content_60 = {
    Text = "Finalmente... acabou? Para onde você a levou, Senhora Narciso?"
  },
  AvgDialog_18711_Content_61 = {
    Text = "O Oceano Primal. Ela terá muito tempo para lembrar... ou esquecer tudo o que aconteceu."
  },
  AvgDialog_18711_Content_62 = {
    Text = "A Dama Harriet..."
  },
  AvgDialog_18711_Content_63 = {
    Text = "Antes que você possa reunir seus pensamentos dispersos, passos suaves ecoam do lado de fora da casa."
  },
  AvgDialog_18711_Content_64 = {
    Text = "Quem está aí? Vamos seguir e dar uma olhada."
  },
  AvgDialog_18711_Content_65 = {
    Text = "Sim, sou eu... hic."
  },
  AvgDialog_18711_Content_66 = {
    Text = "Há quanto tempo, pequeno detetive! Você se lembra de mim, o coveiro Velho Freeman?"
  },
  AvgDialog_18711_Content_67 = {
    Text = "O Velho Freeman, segurando uma garrafa de conhaque, continuou arrotando com um sorriso constrangido no rosto."
  },
  AvgDialog_18711_Content_68 = {
    Text = "O Velho Freeman?! O que você está fazendo aqui... Você ouviu tudo?"
  },
  AvgDialog_18711_Content_69 = {Text = "Eu..."},
  AvgDialog_18711_Content_7 = {
    Text = "Ela se arrastava ansiosamente pelo chão, com seus braços ósseos se debatendo. Como uma besta encurralada, ela soltou gemidos desesperados da garganta."
  },
  AvgDialog_18711_Content_70 = {
    Text = "Eu também não sei o que aconteceu. Dormi profundamente depois de beber."
  },
  AvgDialog_18711_Content_71 = {
    Text = "Não consigo recordar o que aconteceu no meio, mas de alguma forma acabei aqui atordoado."
  },
  AvgDialog_18711_Content_72 = {
    Text = "Então eu ouvi alguns barulhos dentro... Não se preocupe, eu não olhei nem uma única vez!"
  },
  AvgDialog_18711_Content_73 = {
    Text = "O Velho Freeman de repente se inclina e lhe manda uma piscadela misteriosa.\nVocê não desviou a tempo e pegou um forte cheiro ardente de fumaça e álcool."
  },
  AvgDialog_18711_Content_74 = {
    Text = "Você matou aquele Caçador de Caveiras, certo?"
  },
  AvgDialog_18711_Content_75 = {
    Text = "Não é ótimo, mas está perto o suficiente. Ninguém vai perturbar seu sono a partir de agora."
  },
  AvgDialog_18711_Content_76 = {
    Text = "Você pinça seu nariz, dá três passos para trás e acena com a cabeça perfunctoriamente."
  },
  AvgDialog_18711_Content_77 = {Text = "Oh..."},
  AvgDialog_18711_Content_78 = {
    Text = "O Velho Freeman esfregou seu cabelo bagunçado, um traço de confusão piscando em seus olhos."
  },
  AvgDialog_18711_Content_79 = {
    Text = "Bem bom, bem bom..."
  },
  AvgDialog_18711_Content_8 = {Text = "..."},
  AvgDialog_18711_Content_80 = {
    Text = "Sr. Freeman. A partir de agora... sem mais bebidas."
  },
  AvgDialog_18711_Content_81 = {
    Text = "Parar de beber? Não, não, não... Eu prefiro morrer."
  },
  AvgDialog_18711_Content_82 = {
    Text = "Este é um pedido de um amigo. Ela foi para muito, muito longe... mas ainda se preocupa com você."
  },
  AvgDialog_18711_Content_83 = {
    Text = "Amigos? Heh, não se engane. O velho Freeman não tem amigos..."
  },
  AvgDialog_18711_Content_84 = {
    Text = "Ele te dispensou com desdém, murmurando enquanto cambaleava para longe."
  },
  AvgDialog_18711_Content_85 = {
    Text = "Ele parece tão abatido. Que pena...\nEle nunca saberá por que se sente assim."
  },
  AvgDialog_18711_Content_86 = {
    Text = "É como se ele não entendesse por que está aqui."
  },
  AvgDialog_18711_Content_87 = {
    Text = "Isso deve ser o que a Sra. Harriet esperava."
  },
  AvgDialog_18711_Content_88 = {
    Text = "Não lhe diga nada... Ele pode continuar bebendo, cantando e vagando pela vida assim."
  },
  AvgDialog_18711_Content_89 = {
    Text = "De certa forma, isso é também uma espécie de sorte. A vida de um humano é muito curta..."
  },
  AvgDialog_18711_Content_9 = {
    Text = "Daffodil soltou um suave suspiro, seus olhos brilhando com uma tristeza não expressa."
  },
  AvgDialog_18711_Content_90 = {
    Text = "Você assiste Old Freeman partir."
  },
  AvgDialog_18711_Content_91 = {
    Text = "Uma figura encurvada treme no vento sombrio, tornando-se cada vez menor, cada vez mais distante..."
  },
  AvgDialog_18711_Content_92 = {
    Text = "Até ser completamente engolido pelo horizonte distante."
  },
  AvgDialog_18711_Content_93 = {
    Text = "Então você vê um raio fraco de amanhecer penetrando pela névoa, iluminando gradualmente o céu."
  },
  AvgDialog_18711_Content_94 = {
    Text = "A chuva parou... Narciso."
  },
  AvgDialog_18712_Content_1 = {
    Text = "Hino das sombras"
  },
  AvgDialog_18712_Content_10 = {
    Text = "Dê para mim... <Big:Devolva-me>!"
  },
  AvgDialog_18712_Content_11 = {
    Text = "Fios negros se estendem continuamente de seu pescoço, absorvendo avidamente as cabeças caídas em seu corpo."
  },
  AvgDialog_18712_Content_12 = {
    Text = "A cada crânio que devora, seu tamanho aumenta ainda mais."
  },
  AvgDialog_18712_Content_13 = {
    Text = "A última coisa que está diante de você é uma enorme pilha de carne empilhada."
  },
  AvgDialog_18712_Content_14 = {
    Text = "<Bold:—!!!>"
  },
  AvgDialog_18712_Content_15 = {
    Text = "Essas cabeças... Já as vi antes."
  },
  AvgDialog_18712_Content_16 = {
    Text = "Você viu alguns deles nos arquivos que a polícia te deu, nessas frias fotos de vítimas alinhadas."
  },
  AvgDialog_18712_Content_17 = {
    Text = "Você as viu."
  },
  AvgDialog_18712_Content_18 = {
    Text = "Agora você entende, nunca houve organização dos Caçadores de Crânios."
  },
  AvgDialog_18712_Content_19 = {
    Text = "<Yellow:Do início ao fim, o Caçador de Crânios sempre esteve sozinho.>"
  },
  AvgDialog_18712_Content_2 = {
    Text = "Lady Daffodil...?!"
  },
  AvgDialog_18712_Content_20 = {
    Text = "<RedShake: Não é suficiente...>"
  },
  AvgDialog_18712_Content_21 = {
    Text = "<RedShake: Não é suficiente... não é suficiente...>"
  },
  AvgDialog_18712_Content_22 = {
    Text = "Um corpo inchado embutido com inúmeras cabeças expressando dor e lamentação, subindo e descendo com a gordura suave..."
  },
  AvgDialog_18712_Content_23 = {
    Text = "Tal ondas espirituais familiares... Poderia ser a Miragem Milenar?!"
  },
  AvgDialog_18712_Content_24 = {
    Text = "É um poder que se origina da mesma fonte que o Mil Miras, razão pela qual consigo sentir sua localização."
  },
  AvgDialog_18712_Content_25 = {
    Text = "Agora está completamente fora de controle e continua a crescer.\nDevemos agir rapidamente."
  },
  AvgDialog_18712_Content_26 = {Text = "Então..."},
  AvgDialog_18712_Content_27 = {
    Text = "Daffodil de repente se inclinou, segurando a Chave de Prata em seu peito."
  },
  AvgDialog_18712_Content_28 = {
    Text = "Você gostaria de formar uma equipe comigo, %player%?"
  },
  AvgDialog_18712_Content_29 = {
    Text = "Oh, você quer se Linkar comigo?"
  },
  AvgDialog_18712_Content_3 = {
    Text = "Desculpe... Eu deliberadamente te deixei aqui para atrair isso. Você deve estar me culpando em seu coração, certo?"
  },
  AvgDialog_18712_Content_30 = {
    Text = "Depois de todo esse tempo trabalhando juntos, pensei que teríamos alguma compreensão até agora"
  },
  AvgDialog_18712_Content_31 = {
    Text = "Ou... você não está confiante de que pode lidar comigo?"
  },
  AvgDialog_18712_Content_32 = {
    Text = "Heh... Vamos tentar?"
  },
  AvgDialog_18712_Content_33 = {
    Text = "Você fecha os olhos e se concentra, instigando a Chave de Prata em seu peito."
  },
  AvgDialog_18712_Content_34 = {
    Text = "Em breve, a chave prateada começou a emitir uma vibração contínua e fraca, e o brilho branco frio rapidamente engolfou toda a sala escura."
  },
  AvgDialog_18712_Content_35 = {
    Text = "Você sente como se estivesse em um imenso mar de tempo."
  },
  AvgDialog_18712_Content_36 = {
    Text = "Uma energia estranha surge em seu peito, uma torrente cruzando dimensões."
  },
  AvgDialog_18712_Content_37 = {
    Text = "Do outro lado do vasto mar do tempo, o Narciso observa você calmamente.\nNeste momento, uma expressão sutil e unfamiliar aparece em seu rosto."
  },
  AvgDialog_18712_Content_38 = {
    Text = "Isso é uma confiança absoluta e inquestionável, refinada ao longo de centenas de anos por meio de incontáveis confrontos e batalhas."
  },
  AvgDialog_18712_Content_39 = {
    Text = "Vamos partir, %player%. Estou completamente preparado."
  },
  AvgDialog_18712_Content_4 = {Text = "..."},
  AvgDialog_18712_Content_5 = {
    Text = "Nós resolveremos isso assim que sairmos."
  },
  AvgDialog_18712_Content_6 = {
    Text = "<Shake:Minha cabeça... Devolva-a...>"
  },
  AvgDialog_18712_Content_7 = {
    Text = "\"Hilota\" tropeçou para frente dois passos, alcançando inutilmente acima do pescoço."
  },
  AvgDialog_18712_Content_8 = {
    Text = "Uma batida, duas batidas..."
  },
  AvgDialog_18712_Content_9 = {
    Text = "Percebendo que sua cabeça já tinha ido, ela soltou uma série de gritos agudos."
  },
  AvgDialog_18713_Content_1 = {
    Text = "Está chovendo."
  },
  AvgDialog_18713_Content_10 = {
    Text = "Você limpa apressadamente a chuva do seu rosto e pisca, apenas para perceber que alguém está realmente falando com você."
  },
  AvgDialog_18713_Content_11 = {
    Text = "Eu pensei que ninguém morava mais aqui."
  },
  AvgDialog_18713_Content_12 = {
    Text = "A maior parte das pessoas se mudou."
  },
  AvgDialog_18713_Content_13 = {
    Text = "Aqueles que estavam doentes ou idosos escolheram ficar, enquanto alguns saíram e depois voltaram..."
  },
  AvgDialog_18713_Content_14 = {
    Text = "Nem todos conseguem se adaptar à vida fora."
  },
  AvgDialog_18713_Content_15 = {
    Text = "Eu entendi. Mas eu não vi ninguém agora há pouco."
  },
  AvgDialog_18713_Content_16 = {
    Text = "...Eles odeiam lidar com forasteiros."
  },
  AvgDialog_18713_Content_17 = {
    Text = "Você olha ao redor das casas escassas e em ruínas."
  },
  AvgDialog_18713_Content_18 = {
    Text = "Através das janelas negras como breu, olhares silenciosos podem ser vagamente vistos, transbordando cautela e hostilidade."
  },
  AvgDialog_18713_Content_19 = {
    Text = "Olá, senhora. Posso perguntar-lhe—"
  },
  AvgDialog_18713_Content_2 = {
    Text = "Você anda sozinho na chuva, o frio e a água molhando suas roupas e grudando na sua pele."
  },
  AvgDialog_18713_Content_20 = {
    Text = "Você já viu algo estranho?"
  },
  AvgDialog_18713_Content_21 = {
    Text = "Coisas estranhas...?"
  },
  AvgDialog_18713_Content_22 = {
    Text = "Uh... seja uma pessoa ou uma besta, ele se move extremamente rápido."
  },
  AvgDialog_18713_Content_23 = {
    Text = "A mulher balançou a cabeça."
  },
  AvgDialog_18713_Content_24 = {
    Text = "Faz muito tempo desde que alguém veio aqui; até mesmo os urubus se recusam a se aproximar."
  },
  AvgDialog_18713_Content_25 = {
    Text = "Você já viu o Narciso?"
  },
  AvgDialog_18713_Content_26 = {
    Text = "Você já viu uma bela dama em um vestido longo roxo?"
  },
  AvgDialog_18713_Content_27 = {
    Text = "A mulher balançou a cabeça."
  },
  AvgDialog_18713_Content_28 = {
    Text = "Faz muito tempo desde que alguém veio aqui; até mesmo os urubus se recusam a se aproximar."
  },
  AvgDialog_18713_Content_29 = {
    Text = "<Big:Boom—>"
  },
  AvgDialog_18713_Content_3 = {
    Text = "Você caminha por uma casa abandonada após outra, passando por um túmulo após outro."
  },
  AvgDialog_18713_Content_30 = {
    Text = "A chuva está caindo mais forte, transformando tudo em cinza."
  },
  AvgDialog_18713_Content_31 = {
    Text = "A figura da mulher começa a borrar e perder o foco, e até mesmo sua voz fica cada vez mais baixa..."
  },
  AvgDialog_18713_Content_32 = {
    Text = "Entre, {Male=sir,Female=miss}. Você vai pegar um resfriado nessa chuva forte..."
  },
  AvgDialog_18713_Content_33 = {Text = "..."},
  AvgDialog_18713_Content_34 = {
    Text = "Com prazer."
  },
  AvgDialog_18713_Content_4 = {
    Text = "Onde quer que vão, só há cicatrizes e desolação."
  },
  AvgDialog_18713_Content_5 = {
    Text = "Apenas chuva. Uma chuva interminável e fria te acompanha o tempo todo."
  },
  AvgDialog_18713_Content_6 = {
    Text = "{Male=Senhor,Female=Senhora}..."
  },
  AvgDialog_18713_Content_7 = {
    Text = "Uma mulher idosa está em frente à cabine, acenando para você."
  },
  AvgDialog_18713_Content_8 = {
    Text = "Ela vestia um vestido apagado, seu rosto oculto na chuva cinza, se misturando perfeitamente com a casa dilapidada atrás dela."
  },
  AvgDialog_18713_Content_9 = {
    Text = "{Male=Sir,Female=Miss}, você parece estar com muito frio... Gostaria de entrar e se sentar um pouco?"
  },
  AvgDialog_18714_Content_1 = {
    Text = "Ruptura de tempestade"
  },
  AvgDialog_18714_Content_10 = {
    Text = "Uma única pessoa?!"
  },
  AvgDialog_18714_Content_11 = {
    Text = "Oh querido, você parece péssimo. Precisa de ajuda?"
  },
  AvgDialog_18714_Content_12 = {
    Text = "Você dá um passo para trás. Eu tenho algo a te perguntar."
  },
  AvgDialog_18714_Content_13 = {
    Text = "Isso é realmente doloroso. O que, estou exalando algum tipo de cheiro desagradável?"
  },
  AvgDialog_18714_Content_14 = {
    Text = "Eu não sei... Talvez o cheiro dos mortos?"
  },
  AvgDialog_18714_Content_15 = {
    Text = "Beren Stock, Dwight Williams... Esses nomes lhe parecem familiares?"
  },
  AvgDialog_18714_Content_16 = {Text = "..."},
  AvgDialog_18714_Content_17 = {
    Text = "Eu vejo, você suspeita que eu sou o Caçador de Caveiras."
  },
  AvgDialog_18714_Content_18 = {
    Text = "E você sabe claramente os nomes das vítimas do Caçador de Crânios."
  },
  AvgDialog_18714_Content_19 = {Text = "..."},
  AvgDialog_18714_Content_2 = {
    Text = "Daffodil se aproximou de você com um ar de casual elegância, como se estivesse de férias."
  },
  AvgDialog_18714_Content_20 = {
    Text = "Eu pensei que passando tempo com a Lai, poderíamos construir um pouco de confiança."
  },
  AvgDialog_18714_Content_21 = {
    Text = "O Caçador de Caveira pegou um <Yellow:crânio precioso> de mim, então estou apenas realizando uma pequena investigação. É assim que funciona."
  },
  AvgDialog_18714_Content_22 = {
    Text = "De quem é essa cabeça preciosa... poderia ser?"
  },
  AvgDialog_18714_Content_23 = {Text = "..."},
  AvgDialog_18714_Content_24 = {
    Text = "Daffodil sorri para você. Ela sempre coloca esse sorriso quando não quer responder às perguntas dos outros."
  },
  AvgDialog_18714_Content_25 = {
    Text = "Se eu me lembro corretamente, você sempre teve o hábito de colecionar cabeças. Renny está a menos de 15 milhas de Rai em linha reta, tornando a viagem de ida e volta bastante conveniente."
  },
  AvgDialog_18714_Content_26 = {
    Text = "Desculpe, só coleciono cabeças, não as produzo."
  },
  AvgDialog_18714_Content_27 = {
    Text = "Há uma diferença sutil entre as duas coisas... Acredito que você consiga entender, nosso esperto Guardião?"
  },
  AvgDialog_18714_Content_28 = {
    Text = "Claro, eu entendo.\nEntão, onde você estava e o que estava fazendo às 8:15 da noite passada?"
  },
  AvgDialog_18714_Content_29 = {
    Text = "Deixe-me pensar... A loja recebeu um novo lote de sais de banho, então eu os experimentei na banheira."
  },
  AvgDialog_18714_Content_3 = {
    Text = "É você...?"
  },
  AvgDialog_18714_Content_30 = {
    Text = "Bem, quer ouvir os detalhes do meu julgamento?"
  },
  AvgDialog_18714_Content_31 = {
    Text = "É assim? Mas quando eu te vi ontem à noite, você estava parado sozinho sob o poste de luz, segurando uma cabeça humana."
  },
  AvgDialog_18714_Content_32 = {
    Text = "Não parece nada com sais de banho."
  },
  AvgDialog_18714_Content_33 = {Text = "..."},
  AvgDialog_18714_Content_34 = {
    Text = "Você está dizendo... que viu alguém que se parece exatamente comigo na noite passada?"
  },
  AvgDialog_18714_Content_35 = {
    Text = "Você se lembra de ter visto o Narciso na noite passada."
  },
  AvgDialog_18714_Content_36 = {
    Text = "Sem dúvida, suas aparências são quase idênticas, mas seu comportamento e aura são vastly diferentes."
  },
  AvgDialog_18714_Content_37 = {
    Text = "Ou melhor, eu vi <Yellow:you>, não alguém que se parece exatamente com você."
  },
  AvgDialog_18714_Content_38 = {
    Text = "Todas as evidências desfavoráveis agora apontam para você, e eu tenho todo o motivo para suspeitar de você."
  },
  AvgDialog_18714_Content_39 = {
    Text = "Hmm, sua suspeita é, de fato, bem fundamentada."
  },
  AvgDialog_18714_Content_4 = {
    Text = "Oh querido, alguém parece relutante em me ver?"
  },
  AvgDialog_18714_Content_40 = {Text = "..."},
  AvgDialog_18714_Content_41 = {
    Text = "Você não tem nada a explicar?"
  },
  AvgDialog_18714_Content_42 = {
    Text = "Daffodil olhou para você com surpresa, como se você tivesse feito uma pergunta ridícula."
  },
  AvgDialog_18714_Content_43 = {
    Text = "Explicar? Desculpe, não preciso explicar nada a ninguém."
  },
  AvgDialog_18714_Content_44 = {
    Text = "Ela caminha graciosamente em sua direção."
  },
  AvgDialog_18714_Content_45 = {
    Text = "A saia larga farfalha as folhas secas, enquanto fumaça roxa se enrola como tentáculos ao redor."
  },
  AvgDialog_18714_Content_46 = {
    Text = "No próximo segundo, ela desaparece no ar diante dos seus olhos."
  },
  AvgDialog_18714_Content_47 = {
    Text = "As nuvens baixas bloqueiam completamente a luz do sol, fazendo você sentir como se estivesse em um sonho cinza, com os sussurros de Narciso pairando em seus ouvidos—"
  },
  AvgDialog_18714_Content_48 = {
    Text = "Desde que você acha que eu sou o \"Caçador de Crânios\"... qual é o próximo passo? O que você planeja fazer comigo?"
  },
  AvgDialog_18714_Content_49 = {
    Text = "Ou melhor... o que você pode fazer comigo?"
  },
  AvgDialog_18714_Content_5 = {
    Text = "O vento outonal desolador sopra de suas costas. Você se vira, mas não há nada na sua frente; o Velho Freeman já desapareceu há muito tempo."
  },
  AvgDialog_18714_Content_6 = {
    Text = "Pensando em tudo que acabou de acontecer, foi como um pesadelo."
  },
  AvgDialog_18714_Content_7 = {
    Text = "Sr. Freeman...?"
  },
  AvgDialog_18714_Content_8 = {
    Text = "Hmm, você trouxe um companheiro? É aquela garota que sempre parece tão séria?"
  },
  AvgDialog_18714_Content_9 = {
    Text = "Apenas agora, você estava aqui parado sozinho, completamente imóvel, como se estivesse possuído."
  },
  AvgDialog_18715_Content_1 = {
    Text = "Eu me rendo, {Male=Mr.,Female=Miss} Guardiã do segredo."
  },
  AvgDialog_18715_Content_10 = {
    Text = "Você mergulha em um mar de essência primordial cinza."
  },
  AvgDialog_18715_Content_11 = {
    Text = "A luz do dia fere seus olhos, revelando uma vasta extensão de oceano cinza."
  },
  AvgDialog_18715_Content_12 = {
    Text = "As ondas cinzentas em movimento cintilam com uma luz brilhante, pontilhadas por incontáveis manchas negras."
  },
  AvgDialog_18715_Content_13 = {
    Text = "À medida que sua visão se ajusta gradualmente, você percebe que não é uma mancha negra, mas apenas um crânio."
  },
  AvgDialog_18715_Content_14 = {
    Text = "Incontáveis cabeças estão submersas no mar cinza, subindo e descendo com as ondas. Elas gritam e uivam, afogando-se em imensa tristeza e medo."
  },
  AvgDialog_18715_Content_15 = {
    Text = "<Change>Cristais, cristais..."
  },
  AvgDialog_18715_Content_16 = {
    Text = "<Shake:Não toque naquele livreto, não toque...>"
  },
  AvgDialog_18715_Content_17 = {
    Text = "<Shake:San Pedro, deixe-me voltar, deixe-me voltar...>"
  },
  AvgDialog_18715_Content_18 = {
    Text = "Incontáveis vozes gritam em seus ouvidos, forçando você a cobri-los, como se milhares de agulhas estivessem perfurando sua mente."
  },
  AvgDialog_18715_Content_19 = {
    Text = "Hmm... <Big:Aaah...!!>"
  },
  AvgDialog_18715_Content_2 = {
    Text = "Como não consigo suportar ver você se machucar, continuar essa luta seria apenas um desperdício de tempo para todos."
  },
  AvgDialog_18715_Content_20 = {
    Text = "Sangue quente flui de suas orelhas e narinas, criando ondas massivas no momento em que atinge a água."
  },
  AvgDialog_18715_Content_21 = {
    Text = "A maré se ergue com raiva e medo, carregando incontáveis cabeças flutuando em suas ondas, correndo em direção a você."
  },
  AvgDialog_18715_Content_22 = {
    Text = "<Change>Não, não..."
  },
  AvgDialog_18715_Content_23 = {
    Text = "<Shake:Invasores... Invasores!!>"
  },
  AvgDialog_18715_Content_24 = {
    Text = "Você não tem saída. Apenas feche os olhos."
  },
  AvgDialog_18715_Content_25 = {Text = "Ngh...!"},
  AvgDialog_18715_Content_26 = {
    Text = "Cof... Cof..."
  },
  AvgDialog_18715_Content_27 = {
    Text = "Daffodil segurou a testa e franziu a testa para você."
  },
  AvgDialog_18715_Content_28 = {
    Text = "Saiu tão cedo...? Eu pensei que poderia mantê-lo preso por pelo menos um dia inteiro."
  },
  AvgDialog_18715_Content_29 = {
    Text = "Parece que estamos destinados a estar ligados um ao outro, não estamos?"
  },
  AvgDialog_18715_Content_3 = {
    Text = "Dadas as diferenças irreconciliáveis entre nós, sugiro que você pare de me incomodar."
  },
  AvgDialog_18715_Content_30 = {
    Text = "Cabeça... dói..."
  },
  AvgDialog_18715_Content_31 = {
    Text = "O que foi aquilo agora...? Que tipo de coisa era aquilo...?"
  },
  AvgDialog_18715_Content_32 = {
    Text = "Este é meu espaço ultra-dimensional. Eu o nomeei <Yellow:Mil Ilusões>.\nO que você acha? Não é fascinante?"
  },
  AvgDialog_18715_Content_33 = {Text = "..."},
  AvgDialog_18715_Content_34 = {
    Text = "%player%, você está com hemorragia nasal. Espere, até suas orelhas estão sangrando..."
  },
  AvgDialog_18715_Content_35 = {
    Text = "<Shake:Estou bem... Fique longe...>"
  },
  AvgDialog_18715_Content_36 = {
    Text = "Não é sábio agir como se fosse forte agora; você mal consegue ficar de pé."
  },
  AvgDialog_18715_Content_37 = {
    Text = "*Tosse tosse*... não chegue mais perto..."
  },
  AvgDialog_18715_Content_38 = {
    Text = "Sua visão escurece, e você desaba pesadamente ao chão."
  },
  AvgDialog_18715_Content_39 = {
    Text = "Na escuridão, você parece ouvir uma voz familiar."
  },
  AvgDialog_18715_Content_4 = {
    Text = "Daffodil, com uma expressão fria, rapidamente desenhou uma série de runas roxas brilhantes no ar."
  },
  AvgDialog_18715_Content_40 = {
    Text = "Gentil, indiferente, envolto em um zumbido elétrico ligeiramente áspero, parecendo distante e vago."
  },
  AvgDialog_18715_Content_41 = {
    Text = "%player%, você pode me ouvir agora...<Red:Direção de investigação incorreta>..."
  },
  AvgDialog_18715_Content_42 = {
    Text = "O Caçador de Caveira ataca novamente...\nTrês vítimas, todas com suas cabeças retiradas..."
  },
  AvgDialog_18715_Content_43 = {
    Text = "Apenas um momento atrás..."
  },
  AvgDialog_18715_Content_5 = {
    Text = "<Change>Mil Mirage, ative."
  },
  AvgDialog_18715_Content_6 = {
    Text = "O mundo diante de seus olhos se transforma subitamente em reflexos fragmentados na água, piscando suavemente à sua frente."
  },
  AvgDialog_18715_Content_7 = {
    Text = "Você instinctivamente estende a mão, mas é puxado para um profundo vórtice no momento em que toca os Fragmentos de Sombra."
  },
  AvgDialog_18715_Content_8 = {Text = "Aaaah...!!"},
  AvgDialog_18715_Content_9 = {
    Text = "Aquilo é..."
  },
  AvgDialog_18716_Content_1 = {Text = "Aaahh—!!"},
  AvgDialog_18716_Content_10 = {
    Text = "Os fios de repente se contraíram, quebrando a porta do quarto enquanto incontáveis cabeças rolavam para fora."
  },
  AvgDialog_18716_Content_11 = {
    Text = "Quando você recuperou os sentidos, uma cabeça um tanto familiar já estava anexada ao pescoço vazio de Harriet."
  },
  AvgDialog_18716_Content_12 = {
    Text = "Esta cabeça... Este rosto..."
  },
  AvgDialog_18716_Content_13 = {
    Text = "Beren Stock, a vítima anterior... O que está acontecendo?!"
  },
  AvgDialog_18716_Content_14 = {
    Text = "O crânio pálido emite um som de rangido rígido e finalmente abre seus olhos desfocados."
  },
  AvgDialog_18716_Content_15 = {
    Text = "A \"Harriet\" renascida sorri e avança em sua direção com uma velocidade incrível."
  },
  AvgDialog_18716_Content_16 = {
    Text = "Aaaahhh—!!"
  },
  AvgDialog_18716_Content_18 = {
    Text = "A lâmina fria corta impiedosamente a escuridão."
  },
  AvgDialog_18716_Content_19 = {
    Text = "No próximo segundo, a cabeça de \"Harriet\" voou graciosamente e rolou ao lado de sua saia larga."
  },
  AvgDialog_18716_Content_2 = {
    Text = "Harriet colapsou no chão, emitindo um lamento penetrante de dentro de sua garganta."
  },
  AvgDialog_18716_Content_20 = {
    Text = "Ufa... Parece que não estou muito atrasado."
  },
  AvgDialog_18716_Content_21 = {
    Text = "Você está com um bom espírito, %player%."
  },
  AvgDialog_18716_Content_3 = {
    Text = "Você avança e a segura pela gola."
  },
  AvgDialog_18716_Content_4 = {
    Text = "Fale, quem são seus cúmplices e onde estão? O Velho Freeman é um deles?"
  },
  AvgDialog_18716_Content_5 = {
    Text = "Freeman...? Heh... Hehehe..."
  },
  AvgDialog_18716_Content_6 = {
    Text = "Seu rosto se contorceu violentamente, com inúmeras pústulas inchando sob sua pele fina, à beira de estourar."
  },
  AvgDialog_18716_Content_7 = {
    Text = "Zzzzap—!!"
  },
  AvgDialog_18716_Content_8 = {
    Text = "A cabeça de Harriet foi estourada em uma massa quente."
  },
  AvgDialog_18716_Content_9 = {
    Text = "O pescoço dela contorcia-se continuamente, com Limo d misturado com sangue formando fios finos que se estendiam até o teto, paredes e chão..."
  },
  AvgDialog_18717_Content_1 = {
    Text = "Muse felina"
  },
  AvgDialog_18717_Content_10 = {
    Text = "Aquilo foi uma experiência bastante interessante."
  },
  AvgDialog_18717_Content_11 = {
    Text = "As memórias originalmente tristes, reinterpretadas através de imagens, adquiriram inesperadamente um charme cômico."
  },
  AvgDialog_18717_Content_12 = {
    Text = "Ouvi que você mais tarde formou um clube de cinema chamado <Yellow:\"Sociedade da Poesia Philin\">?"
  },
  AvgDialog_18717_Content_13 = {
    Text = "Sim... Às vezes eu ajudo a escrever roteiros, embora sempre tenha sido um péssimo dramaturgo."
  },
  AvgDialog_18717_Content_14 = {
    Text = "Foi a Dama Narciso quem me ajudou a seguir em frente a partir do passado, independentemente de suas verdadeiras intenções."
  },
  AvgDialog_18717_Content_15 = {
    Text = "Eu sempre fui grato à Lady Narciso."
  },
  AvgDialog_18717_Content_16 = {
    Text = "Eu vejo, então foi isso que ela te disse."
  },
  AvgDialog_18717_Content_17 = {
    Text = "Sou também profundamente grato à Srta. Horla. Foi um encontro bonito."
  },
  AvgDialog_18717_Content_18 = {
    Text = "Então, pelo bem da Senhora Horla, vou confiar em você desta vez."
  },
  AvgDialog_18717_Content_19 = {
    Text = "<LightGray:Além disso, as pessoas enviadas pela escola já estão a caminho.>"
  },
  AvgDialog_18717_Content_2 = {
    Text = "2:15, Rua Kenting"
  },
  AvgDialog_18717_Content_20 = {
    Text = "<LightGray:Se eu demorar muito para voltar, eles não ficarão apenas parados...>"
  },
  AvgDialog_18717_Content_21 = {
    Text = "Então vamos partir, {Male=Mr.,Female=Miss} Guardião."
  },
  AvgDialog_18717_Content_22 = {
    Text = "Daffodil acenou com a cabeça feliz, estendendo a mão para você."
  },
  AvgDialog_18717_Content_23 = {Text = "..."},
  AvgDialog_18717_Content_24 = {
    Text = "Você segura suavemente a mão de Narciso. Ao contrário das expectativas, a mão dela é suave e quente."
  },
  AvgDialog_18717_Content_25 = {
    Text = "Aguarde firme, Guardião."
  },
  AvgDialog_18717_Content_26 = {
    Text = "Seu equilíbrio vacila, e você é puxado para uma dimensão profunda."
  },
  AvgDialog_18717_Content_27 = {
    Text = "Bem-vindo de volta ao meu \"Mil Miragens\""
  },
  AvgDialog_18717_Content_28 = {
    Text = "Aqui está aquele familiar Mar da Essência Primordial novamente, com cabeças ainda balançando junto com as ondas."
  },
  AvgDialog_18717_Content_29 = {
    Text = "Diferentemente da última vez, as cabeças parecem muito mais silenciosas agora. Suas órbitas oculares ocos se voltam todas para você, ainda assim continuam a sussurrar entre si."
  },
  AvgDialog_18717_Content_3 = {
    Text = "Eu não esperava que você concordasse em vir comigo tão prontamente. Você não está preocupada que eu possa te levar a algum lugar estranho?"
  },
  AvgDialog_18717_Content_30 = {
    Text = "Daffodil acenou com a mão levemente, e duas cabeças tremeram enquanto flutuavam até o nível dos seus olhos."
  },
  AvgDialog_18717_Content_31 = {
    Text = "<Change>Meu mestre..."
  },
  AvgDialog_18717_Content_32 = {
    Text = "<Change>Longo tempo sem ver..."
  },
  AvgDialog_18717_Content_33 = {
    Text = "<Change>Ajude-me a encontrar alguém..."
  },
  AvgDialog_18717_Content_34 = {
    Text = "Daffodil e o crânio estão sussurrando em uma língua que você não consegue entender. O que quer que tenham discutido, fez ela rir felizmente."
  },
  AvgDialog_18717_Content_35 = {
    Text = "Você nunca a viu sorrir assim; parece fora de lugar."
  },
  AvgDialog_18717_Content_36 = {
    Text = "Em vez disso, atravessou centenas de anos e pousou em um canto de uma história desconhecida para você."
  },
  AvgDialog_18717_Content_37 = {Text = "..."},
  AvgDialog_18717_Content_38 = {
    Text = "Qual é o problema? Tem algo no meu rosto?"
  },
  AvgDialog_18717_Content_39 = {
    Text = "Você olha com deleite."
  },
  AvgDialog_18717_Content_4 = {
    Text = "Então, você... me levará a lugares estranhos?"
  },
  AvgDialog_18717_Content_40 = {
    Text = "Estas são todas minhas coleções valiosas."
  },
  AvgDialog_18717_Content_41 = {
    Text = "Faz muito tempo desde que voltei. Sinto saudades deles."
  },
  AvgDialog_18717_Content_42 = {
    Text = "Sobre o que você está falando?"
  },
  AvgDialog_18717_Content_43 = {
    Text = "Passado, presente e futuro."
  },
  AvgDialog_18717_Content_44 = {
    Text = "Cada uma dessas cabeças é uma <Yellow:projeção da realidade>. Sua visão e memória transcendem as dimensões de tempo e espaço, ajudando-me a descobrir muitas coisas inesperadas."
  },
  AvgDialog_18717_Content_45 = {
    Text = "Então é por isso que sua loja tem tantos itens estranhos e incomuns...?"
  },
  AvgDialog_18717_Content_46 = {
    Text = "Daffodil piscou, concordando tacitamente com sua suposição."
  },
  AvgDialog_18717_Content_47 = {
    Text = "De onde vieram todas essas cabeças?"
  },
  AvgDialog_18717_Content_48 = {
    Text = "Negociação, presente e um pouco de sorte.\nClaro, eu também fiquei com parte disso."
  },
  AvgDialog_18717_Content_49 = {
    Text = "Dizem que você caçou até @1 cabeças — este é apenas o número registrado oficialmente."
  },
  AvgDialog_18717_Content_5 = {Text = "Claro."},
  AvgDialog_18717_Content_50 = {
    Text = "Daffodil tomou uma longa tragada de seu longo cachimbo, depois exalou uma nuvem de fumaça branca."
  },
  AvgDialog_18717_Content_51 = {
    Text = "Desculpe desapontá–lo, {Male=Mr.,Female=Miss} Guardião, mas repreensões morais não me afetam."
  },
  AvgDialog_18717_Content_52 = {
    Text = "As regras criadas pelos humanos não se aplicam a nós. O que você vê agora sou eu, com olhos e um nariz como os seus..."
  },
  AvgDialog_18717_Content_53 = {
    Text = "Daffodil pegou a Chave de Prata em seu peito, traçando levemente seus padrões intrincados."
  },
  AvgDialog_18717_Content_54 = {
    Text = "Zumbidos e vibrações caóticas preenchem seu peito, colidindo ferozmente como uma guerra silenciosa."
  },
  AvgDialog_18717_Content_55 = {
    Text = "Sente isso? Não somos humanos. Somos \"bestas\", ou como alguns nos chamariam..."
  },
  AvgDialog_18717_Content_56 = {
    Text = "Nós somos <Yellow:seres superiores>."
  },
  AvgDialog_18717_Content_57 = {
    Text = "Toleramos humanos ignorantes, seguimos regras em constante mudança, obedecemos a Links frágeis, tudo por medo..."
  },
  AvgDialog_18717_Content_58 = {
    Text = "Ela acaricia suavemente seu rosto."
  },
  AvgDialog_18717_Content_59 = {
    Text = "E uma promessa."
  },
  AvgDialog_18717_Content_6 = {Text = "..."},
  AvgDialog_18717_Content_60 = {Text = "..."},
  AvgDialog_18717_Content_61 = {
    Text = "Então você se tornou um dos poucos Despertadores registrados sem nenhum Link."
  },
  AvgDialog_18717_Content_62 = {
    Text = "Ninguém nasce para gostar de ser controlado; a maioria das criaturas anseia por liberdade de forma inerente."
  },
  AvgDialog_18717_Content_63 = {
    Text = "Pessoalmente, não desgosto do chamado \"Link\"... Enquanto for mutuamente benéfico, por que se preocupar com aparências?"
  },
  AvgDialog_18717_Content_64 = {
    Text = "O problema pode não estar comigo.\nNinguém se conecta comigo porque não são qualificados. Entendeu?"
  },
  AvgDialog_18717_Content_65 = {Text = "Hm..."},
  AvgDialog_18717_Content_66 = {
    Text = "E quanto a mim? Sou eu também um dos \"não qualificados\"...?"
  },
  AvgDialog_18717_Content_67 = {
    Text = "Daffodil estourou em risadas, mas engasgou com a fumaça e não pôde evitar tossir várias vezes."
  },
  AvgDialog_18717_Content_68 = {
    Text = "Não se preocupe, garoto... Você saberá a resposta em breve."
  },
  AvgDialog_18717_Content_69 = {
    Text = "<LightGray: Outra resposta ambígua...>"
  },
  AvgDialog_18717_Content_7 = {
    Text = "Na verdade... a Senhorita Horla me falou sobre seu primeiro encontro esta tarde. Ela disse—"
  },
  AvgDialog_18717_Content_70 = {
    Text = "Oops, talvez eu tenha falado demais."
  },
  AvgDialog_18717_Content_71 = {
    Text = "Daffodil levantou a mão e tocou cada testa, fazendo-os flutuar obedientemente."
  },
  AvgDialog_18717_Content_72 = {
    Text = "<Change>Obrigado a todos."
  },
  AvgDialog_18717_Content_73 = {
    Text = "Certo. Vamos, Guardião."
  },
  AvgDialog_18717_Content_74 = {
    Text = "Eu já sei a localização do Caçador de Crânios."
  },
  AvgDialog_18717_Content_8 = {
    Text = "Mais tarde descobri que ela transformou aquela memória em algo chamado \"filme.\""
  },
  AvgDialog_18717_Content_9 = {
    Text = "Eu sentei na plateia e assisti ao primeiro filme da minha vida."
  },
  AvgDialog_18718_Content_1 = {
    Text = "Uma Reunião Solitária"
  },
  AvgDialog_18718_Content_10 = {
    Text = "Esta é minha casa.\nNão tenho outro lugar para ir além daqui."
  },
  AvgDialog_18718_Content_11 = {
    Text = "Para pessoas como nós do campo, não importa onde vamos, é tudo a mesma coisa."
  },
  AvgDialog_18718_Content_12 = {
    Text = "A Dama Harriet..."
  },
  AvgDialog_18718_Content_13 = {
    Text = "A atmosfera dentro da casa ficou um pouco pesada."
  },
  AvgDialog_18718_Content_14 = {
    Text = "A chuva ainda cai suavemente enquanto você e ela olham para o interminável véu de chuva."
  },
  AvgDialog_18718_Content_15 = {
    Text = "O exterior está envolto em uma névoa cinza, com vapor d'água envolvendo você apertadamente, fazendo parecer que você é a única vida restante entre o céu e a terra."
  },
  AvgDialog_18718_Content_16 = {
    Text = "<LightGray:Onde está a Dama dos narcisos agora...>"
  },
  AvgDialog_18718_Content_17 = {
    Text = "Por favor, aguarde um momento, {Male=sir,Female=miss}. Vou preparar um chá quente na cozinha."
  },
  AvgDialog_18718_Content_18 = {
    Text = "Embora seja humilde aqui, ainda posso lhe oferecer uma xícara de chá."
  },
  AvgDialog_18718_Content_19 = {
    Text = "A Sra. Harriet arrastou seus passos lentos em direção à cozinha."
  },
  AvgDialog_18718_Content_2 = {
    Text = "Você segue a mulher para dentro da cabana de madeira.\nO interior é muito simples, e você sente um leve cheiro de madeira úmida."
  },
  AvgDialog_18718_Content_20 = {
    Text = "Até que sua silhueta fosse engolida pelas profundas sombras do corredor, você finalmente voltou a si."
  },
  AvgDialog_18718_Content_21 = {
    Text = "Parece que vai demorar um pouco até a chuva parar. Vamos dar uma olhada ao redor."
  },
  AvgDialog_18718_Content_3 = {
    Text = "A mulher lentamente se curvou, pegou alguns gravetos do canto e os jogou no pequeno fogão escuro."
  },
  AvgDialog_18718_Content_4 = {
    Text = "Coloque suas mãos aqui, aqueça-as um pouco mais, e você não sentirá frio."
  },
  AvgDialog_18718_Content_5 = {
    Text = "Muito obrigado..."
  },
  AvgDialog_18718_Content_6 = {
    Text = "Meu nome é Harriet: @1, {Male=sir,Female=miss}. Pode me chamar de Harriet."
  },
  AvgDialog_18718_Content_7 = {
    Text = "Claro, Sra. Harriet. Para ser honesto, estou curioso—por que você está ficando aqui?"
  },
  AvgDialog_18718_Content_8 = {
    Text = "Esta área não parece muito habitável."
  },
  AvgDialog_18718_Content_9 = {
    Text = "A Sra. Harriet se agachou, mexendo com a lenha. As chamas tremeluziantes dançavam em seu rosto magro e cansado."
  },
  AvgDialog_18719_Content_1 = {
    Text = "Coleta de caça aos crânios"
  },
  AvgDialog_18719_Content_10 = {
    Text = "Na noite passada, você não conseguiu alcançar Narciso e só pôde seguir o endereço fornecido por Ramona até a residência de Horla."
  },
  AvgDialog_18719_Content_11 = {
    Text = "B-Bom dia, Srta. Horla."
  },
  AvgDialog_18719_Content_12 = {
    Text = "Bom dia, {Male=Mr.,Female=Miss} %player%."
  },
  AvgDialog_18719_Content_13 = {Text = "..."},
  AvgDialog_18719_Content_14 = {Text = "..."},
  AvgDialog_18719_Content_15 = {
    Text = "Um silêncio constrangedor preenche o ar. Você percebe que este Despertador não parece muito bom em socializar."
  },
  AvgDialog_18719_Content_16 = {
    Text = "Senhorita Horla, estou aqui a respeito do evento Skull Hunter.\nComo você vive aqui há muito tempo, tem alguma pista ou informação?"
  },
  AvgDialog_18719_Content_17 = {
    Text = "\"Caçador de Caveiras\"... Por favor, aguarde um momento."
  },
  AvgDialog_18719_Content_18 = {
    Text = "Horla se virou e começou a vasculhar a estante alta."
  },
  AvgDialog_18719_Content_19 = {
    Text = "Encontrei! *Tosse, tosse...*"
  },
  AvgDialog_18719_Content_2 = {Text = "Daffodil!"},
  AvgDialog_18719_Content_20 = {
    Text = "Horla afastou a poeira que flutuava ao redor e colocou o caderno amarelado em sua mão."
  },
  AvgDialog_18719_Content_21 = {
    Text = "Há um mês, a Srta. Boneca pediu minha ajuda."
  },
  AvgDialog_18719_Content_22 = {
    Text = "Não tenho habilidades particulares, mas documentei todos os casos recentes. Espero que isso possa ajudar."
  },
  AvgDialog_18719_Content_23 = {
    Text = "Você abre o caderno e, em uma escrita elegante, registra a hora e o local de descoberta de cada caso, incluindo até esboços dos corpos e cenas do crime."
  },
  AvgDialog_18719_Content_24 = {
    Text = "<Shake:Peço desculpas, minhas habilidades de desenho são bem ruins. Você pode simplesmente ignorá-las...>"
  },
  AvgDialog_18719_Content_25 = {
    Text = "Não, é muito impressionante.\nObrigado, Senhorita Horla. Esta nota é crucial para nós."
  },
  AvgDialog_18719_Content_26 = {
    Text = "Não importa o que aconteça, fico feliz em ajudar. Aqueles pobres..."
  },
  AvgDialog_18719_Content_27 = {
    Text = "Horla soltou um suspiro suave e virou-se para olhar o céu sombrio do lado de fora."
  },
  AvgDialog_18719_Content_28 = {
    Text = "Cidade Chuvosa (Chuvosa) é um lugar onde chove o ano todo. No entanto, após a chuva, o que frequentemente enfrenta não é uma colheita abundante, mas inundações e pragas intermináveis."
  },
  AvgDialog_18719_Content_29 = {
    Text = "Jovens trabalham em grandes cidades como Londinium, deixando apenas os idosos e crianças para trás."
  },
  AvgDialog_18719_Content_3 = {
    Text = "Huh... Onde é este lugar?"
  },
  AvgDialog_18719_Content_30 = {
    Text = "Agora, até os anciãos estão começando a sair um por um..."
  },
  AvgDialog_18719_Content_31 = {
    Text = "Eu assisti a alguns funerais locais. Sempre que um ente querido falece, os Reenianos cantam uma canção antiga..."
  },
  AvgDialog_18719_Content_32 = {
    Text = "Horla começou a cantarolar suavemente, e a melodia melancólica logo se consolidou em palavras tão escuras quanto tinta."
  },
  AvgDialog_18719_Content_33 = {
    Text = "<RedItalic: Nós escrevemos com sangue como nossa caneta e lama como nosso papel.\n<RedItalic: Inscrevemos tristeza e medo com corpos encharcados pela chuva...>"
  },
  AvgDialog_18719_Content_34 = {
    Text = "Essas palavras fluiram lentamente ao redor do Horla, então formaram uma carta amarelada que a envolveu."
  },
  AvgDialog_18719_Content_35 = {
    Text = "Ela soltou um leve suspiro, lágrimas brilhando em seus olhos."
  },
  AvgDialog_18719_Content_36 = {
    Text = "Não é tudo isso a tristeza que os Renier escreveram com seus corpos encharcados de chuva"
  },
  AvgDialog_18719_Content_37 = {
    Text = "O ar está cheio de uma silenciosa e densa sensação de depressão, quase suffocando você."
  },
  AvgDialog_18719_Content_38 = {
    Text = "<Shake:Tosse, Senhorita Horla...>"
  },
  AvgDialog_18719_Content_39 = {Text = "..."},
  AvgDialog_18719_Content_4 = {
    Text = "O alegre canto dos pássaros o puxa de volta à realidade dos seus sonhos."
  },
  AvgDialog_18719_Content_40 = {
    Text = "Ah! Desculpe, fiz isso de novo..."
  },
  AvgDialog_18719_Content_41 = {
    Text = "Horla recuperou a consciência e respirou fundo duas vezes."
  },
  AvgDialog_18719_Content_42 = {
    Text = "As emoções opressivas finalmente dissiparam, e o peso pesado em seu peito diminuiu significativamente."
  },
  AvgDialog_18719_Content_43 = {Text = "..."},
  AvgDialog_18719_Content_44 = {Text = "..."},
  AvgDialog_18719_Content_45 = {
    Text = "Ah, certo, certo."
  },
  AvgDialog_18719_Content_46 = {
    Text = "Preparei um bule de chá de rosa usando pétalas recém-colhidas. Você gostaria de se juntar a mim para um gosto?"
  },
  AvgDialog_18719_Content_47 = {
    Text = "Em meia hora"
  },
  AvgDialog_18719_Content_48 = {
    Text = "Em uma mão, você segura uma xícara de porcelana fina cheia de chá de rosas, enquanto com a outra, folheia as anotações de Horla, buscando um possível avanço."
  },
  AvgDialog_18719_Content_49 = {
    Text = "Onde estão as pessoas da delegacia?"
  },
  AvgDialog_18719_Content_5 = {
    Text = "Você observa o quarto limpo e simples com confusão, então levanta o cobertor e faz uma sniff."
  },
  AvgDialog_18719_Content_50 = {
    Text = "Na Norwich Street, o lugar por onde você passou ontem à noite."
  },
  AvgDialog_18719_Content_51 = {Text = "..."},
  AvgDialog_18719_Content_52 = {
    Text = "Chuva. Sangue. Narciso.\nAo recordar o encontro da noite passada, você não consegue discernir se foi um sonho ou uma realidade."
  },
  AvgDialog_18719_Content_53 = {
    Text = "Você parece fraco... Você não descansou bem na noite passada?"
  },
  AvgDialog_18719_Content_54 = {
    Text = "Não, é apenas..."
  },
  AvgDialog_18719_Content_55 = {
    Text = "Você sacudiu a cabeça, tentando clarear os pensamentos confusos da sua mente."
  },
  AvgDialog_18719_Content_56 = {Text = "..."},
  AvgDialog_18719_Content_57 = {
    Text = "A investigação na Cidade Lai foi concluída há apenas dois dias, e suas feridas ainda não se curaram completamente."
  },
  AvgDialog_18719_Content_58 = {
    Text = "Sussurro, não dá para evitar que os outros Investigadores também estejam ocupados, dá?"
  },
  AvgDialog_18719_Content_59 = {
    Text = "Neste ponto, vamos encerrar este caso rapidamente. Eu quero tirar férias."
  },
  AvgDialog_18719_Content_6 = {
    Text = "Bom. Seco e macio, sem cheiro de chuva ou sangue."
  },
  AvgDialog_18719_Content_60 = {
    Text = "Huh, isso é..."
  },
  AvgDialog_18719_Content_61 = {
    Text = "O som do virar de páginas parou abruptamente."
  },
  AvgDialog_18719_Content_62 = {
    Text = "Você se concentra na página congelada, começando a formular seu próximo plano de investigação"
  },
  AvgDialog_18719_Content_63 = {
    Text = "Ramona... Antes de me encontrar com o detetive, quero ir a algum lugar primeiro."
  },
  AvgDialog_18719_Content_7 = {
    Text = "Bom dia, {Male=Mr.,Female=Miss} %player%. Bem-vindo à minha humilde morada..."
  },
  AvgDialog_18719_Content_8 = {
    Text = "Senhorita Horla?!"
  },
  AvgDialog_18719_Content_9 = {
    Text = "A Memória começa a se recuperar gradualmente."
  },
  AvgDialog_18720_Content_1 = {
    Text = "11:00, Cemitério Highgate"
  },
  AvgDialog_18720_Content_10 = {
    Text = "Não espere muito da expertise de detetives em áreas remotas."
  },
  AvgDialog_18720_Content_11 = {
    Text = "...Faz sentido."
  },
  AvgDialog_18720_Content_12 = {
    Text = "Você tira sua lupa e continua observando o esqueleto."
  },
  AvgDialog_18720_Content_13 = {
    Text = "Há um <Red:corte irregular> na vértebra do pescoço..."
  },
  AvgDialog_18720_Content_14 = {
    Text = "No entanto, está bastante bagunçado com numerosos cortes sobrepostos, completamente diferente do que vimos nas fotos anteriormente."
  },
  AvgDialog_18720_Content_15 = {
    Text = "Ainda bastante inexperiente, primeira vez cometendo um crime?"
  },
  AvgDialog_18720_Content_16 = {
    Text = "Começar a investigação centrada no Cemitério.\nNovatos inexperientes normalmente não se afastam muito de casa durante seu primeiro crime."
  },
  AvgDialog_18720_Content_17 = {
    Text = "Entendido. Estou confiante desta vez; o culpado será capturado em breve!"
  },
  AvgDialog_18720_Content_18 = {
    Text = "Assassino? Como você se atreve a supor, *hic*, que há apenas um assassino?"
  },
  AvgDialog_18720_Content_19 = {
    Text = "Das profundezas da floresta densa surgiu um velho, exalando álcool e com as bochechas ruborizadas."
  },
  AvgDialog_18720_Content_2 = {
    Text = "Você anda sozinho através dos montes funerários desolados."
  },
  AvgDialog_18720_Content_20 = {
    Text = "Desculpe, não quis ouvir sua monólogo."
  },
  AvgDialog_18720_Content_21 = {
    Text = "Eu sou o cuidador deste cemitério. Você pode me chamar de... eh, <Blue:Velho Freeman>."
  },
  AvgDialog_18720_Content_22 = {
    Text = "Boa tarde, Sr. Freeman.\nVocê acabou de insinuar que há mais de um assassino?"
  },
  AvgDialog_18720_Content_23 = {
    Text = "O Velho Freeman pegou a garrafa e encheu o bucho com a bebida, sua protuberante maçã-de-adão balançando para cima e para baixo."
  },
  AvgDialog_18720_Content_24 = {
    Text = "Argh! Esta floresta miserável nunca vê uma alma o dia todo. Já que você está aqui, deixe-me contar uma história..."
  },
  AvgDialog_18720_Content_25 = {
    Text = "Aquilo foi provavelmente no início deste ano...? Não consigo me lembrar bem."
  },
  AvgDialog_18720_Content_26 = {
    Text = "Como de costume, eu bebi e cochilei em um local sombreado."
  },
  AvgDialog_18720_Content_27 = {
    Text = "E então eu ouvi alguns ruídos estranhos, quase como..."
  },
  AvgDialog_18720_Content_28 = {
    Text = "<RedItalic:Zzz... Crack...>"
  },
  AvgDialog_18720_Content_29 = {
    Text = "Som estranho. O que vem a seguir?"
  },
  AvgDialog_18720_Content_3 = {
    Text = "Corvos planam pelo céu sombrio enquanto o desolador vento de outono uiva."
  },
  AvgDialog_18720_Content_30 = {
    Text = "Não se preocupe, pequeno detetive. \nEu abri meus olhos... hics, adivinha o que eu vi?"
  },
  AvgDialog_18720_Content_31 = {
    Text = "De jeito nenhum, é apenas o Caçador de Crânios, não é?"
  },
  AvgDialog_18720_Content_32 = {
    Text = "Claro, é um Caçador de Caveiras! Ou, você poderia dizer que é uma mulher..."
  },
  AvgDialog_18720_Content_33 = {
    Text = "Uma mulher está decapitando Pinóquio!"
  },
  AvgDialog_18720_Content_34 = {
    Text = "Então ela me viu—hic—como se tivesse visto um fantasma, e correu mais rápido do que qualquer outra pessoa!"
  },
  AvgDialog_18720_Content_35 = {
    Text = "Minha pobre Pinoko, seu pescoço está mal segurado por um fio!"
  },
  AvgDialog_18720_Content_36 = {
    Text = "Haha, <Big:Hahahaha...>"
  },
  AvgDialog_18720_Content_37 = {
    Text = "O Velho Freeman explodiu em uma série de risadas altas, até derramando lágrimas de alegria."
  },
  AvgDialog_18720_Content_38 = {
    Text = "<SmallShake:Paciência, paciência...>"
  },
  AvgDialog_18720_Content_39 = {
    Text = "Hic, hic! Já faz cerca de um mês, e eu ouvi aquela voz novamente..."
  },
  AvgDialog_18720_Content_4 = {Text = "Encontrei."},
  AvgDialog_18720_Content_40 = {
    Text = "<RedItalic:Zzz... Crack... Crack...>"
  },
  AvgDialog_18720_Content_41 = {
    Text = "Desta vez, não foi a mulher que voltou, mas um homem muito magro."
  },
  AvgDialog_18720_Content_42 = {
    Text = "Esse é um trabalhador habilidoso! Com um único golpe..."
  },
  AvgDialog_18720_Content_43 = {
    Text = "<RedBig:Whoosh!> A cabeça de Pinoko se foi!"
  },
  AvgDialog_18720_Content_44 = {
    Text = "Parece que havia dois Caçadores de Crânios. O que aconteceu a seguir?"
  },
  AvgDialog_18720_Content_45 = {
    Text = "Depois? Não há depois. Essa é toda a história do Velho Freeman e dos Headcrabs, hic."
  },
  AvgDialog_18720_Content_46 = {
    Text = "O Velho Freeman soltou um arroto satisfeito, semicerrando seus olhos amarelos turvos, e olhou você de cima a baixo."
  },
  AvgDialog_18720_Content_47 = {
    Text = "Você parece completamente perdido, pobre pequeno detetive. Você já ouviu falar de <Red:A Lenda do Caçador de Crânios>?"
  },
  AvgDialog_18720_Content_48 = {
    Text = "A Lenda do Caçador de Crânios? Conte-me."
  },
  AvgDialog_18720_Content_49 = {
    Text = "O Velho Freeman se reclinou preguiçosamente contra a lápide, tomou alguns goles para terminar a bebida restante na garrafa e a jogou casualmente no chão."
  },
  AvgDialog_18720_Content_5 = {
    Text = "Você para em frente a um túmulo solitário, a tampa do caixão podre já aberta embaixo."
  },
  AvgDialog_18720_Content_50 = {
    Text = "O líquido escorreu da garrafa quebrada, deixando um rastro sinuoso no chão. Como lágrimas, ou talvez sangue."
  },
  AvgDialog_18720_Content_51 = {
    Text = "Alguns dizem que o Caçador de Crânios é um monstro nascido da <Yellow:Epidemia>."
  },
  AvgDialog_18720_Content_52 = {
    Text = "Alguns dizem que o Caçador de Crânios não é uma pessoa nem duas."
  },
  AvgDialog_18720_Content_53 = {
    Text = "<Red:Os Caçadores de Caveiras são uma organização.>"
  },
  AvgDialog_18720_Content_54 = {
    Text = "Organização?"
  },
  AvgDialog_18720_Content_55 = {
    Text = "Sim, uma organização."
  },
  AvgDialog_18720_Content_56 = {
    Text = "Eles aparecem apenas em noites de chuva, seus passos ocultos pela chuva, se aproximando silenciosamente de você..."
  },
  AvgDialog_18720_Content_57 = {
    Text = "<RedBig:Snap!>"
  },
  AvgDialog_18720_Content_58 = {Text = "!!"},
  AvgDialog_18720_Content_59 = {
    Text = "Hahaha! O que é isso? Já com medo, meu pequeno detetive?"
  },
  AvgDialog_18720_Content_6 = {
    Text = "Um esqueleto sem cabeça repousa no caixão, agora um paraíso para musgos e insetos."
  },
  AvgDialog_18720_Content_60 = {
    Text = "Ele se inclina mais perto, seus olhos amarelos turvos revirando, quase queimando em você."
  },
  AvgDialog_18720_Content_61 = {
    Text = "Esta pessoa parece estranha. Deixe este lugar rapidamente."
  },
  AvgDialog_18720_Content_62 = {
    Text = "Desculpe, Senhor Freeman. Está ficando tarde. Acho que preciso ir embora..."
  },
  AvgDialog_18720_Content_63 = {
    Text = "Você respirou levemente e se afastou sem olhar para trás."
  },
  AvgDialog_18720_Content_64 = {
    Text = "Risos zombeteiros vêm de trás, mas você não pode se dar ao luxo de se preocupar com isso agora. Tudo o que você quer é sair."
  },
  AvgDialog_18720_Content_65 = {
    Text = "O céu escureceu gradualmente, com nuvens escuras pairando baixas bloqueando a pálida luz do sol. O vento agitou as folhas, fazendo-as ondular como ondas."
  },
  AvgDialog_18720_Content_66 = {
    Text = "No final do cemitério, você vê uma figura que é ao mesmo tempo familiar e estranha."
  },
  AvgDialog_18720_Content_67 = {
    Text = "É Narciso. A maior parte do seu rosto está escondida sob a aba do chapéu abaixado, com cabelos grisalhos que balançam suavemente ao vento."
  },
  AvgDialog_18720_Content_68 = {
    Text = "Vendo você em tal estado desgrenhado, Daffodil riu felizmente."
  },
  AvgDialog_18720_Content_69 = {
    Text = "Há quanto tempo, {Male=Mr.,Female=Miss} Guardião."
  },
  AvgDialog_18720_Content_7 = {
    Text = "A nota registra o tempo da descoberta como há seis meses; o momento da morte deve ter sido ainda mais cedo..."
  },
  AvgDialog_18720_Content_8 = {
    Text = "Em outras palavras, esta é provavelmente a vítima mais antiga conhecida do \"Caçador de Crânios\". No entanto, os registros da polícia nunca a mencionaram..."
  },
  AvgDialog_18720_Content_9 = {
    Text = "Não há hospital ou funerária adequada aqui, e ninguém presta muita atenção aos mortos."
  },
  AvgDialog_18721_Content_1 = {
    Text = "Talvez tentar usar a Rastrear Mente para encontrar o Caçador de Crânios?"
  },
  AvgDialog_18721_Content_2 = {
    Text = "Esse método tem pouco efeito em criaturas do Reino Ultra."
  },
  AvgDialog_18721_Content_3 = {
    Text = "A retrospecção espiritual também não é onipotente."
  },
  AvgDialog_18722_Content_1 = {
    Text = "Até nos encontrarmos novamente"
  },
  AvgDialog_18722_Content_10 = {
    Text = "<LightGray:Um crânio precioso? De quem poderia ser...>"
  },
  AvgDialog_18722_Content_11 = {Text = "..."},
  AvgDialog_18722_Content_12 = {
    Text = "Você parece preocupado, %player%. Parece que você realmente quer saber a resposta?"
  },
  AvgDialog_18722_Content_13 = {
    Text = "É apenas mediano."
  },
  AvgDialog_18722_Content_14 = {
    Text = "Ahem, não sou do tipo que se intromete casualmente na privacidade dos outros."
  },
  AvgDialog_18722_Content_15 = {
    Text = "É assim? Mas sua expressão já o traiu."
  },
  AvgDialog_18722_Content_16 = {
    Text = "Claro, eu quero saber."
  },
  AvgDialog_18722_Content_17 = {
    Text = "Eu só quero saber mais sobre você, Senhora Daffodil."
  },
  AvgDialog_18722_Content_18 = {
    Text = "Oh? Alguém parece estar se tornando mais ganancioso."
  },
  AvgDialog_18722_Content_19 = {
    Text = "Aqui está uma dica: <Yellow: É algo que você já viu antes.>"
  },
  AvgDialog_18722_Content_2 = {
    Text = "Tropas de apoio e o Comitê estão a caminho. Fique aqui e mantenha a área segura."
  },
  AvgDialog_18722_Content_20 = {
    Text = "Já viu isso antes...?"
  },
  AvgDialog_18722_Content_21 = {
    Text = "Você reflete profundamente, a história dos últimos dois dias e as pessoas que conheceu passam diante de seus olhos como uma lanterna giratória."
  },
  AvgDialog_18722_Content_22 = {Text = "..."},
  AvgDialog_18722_Content_23 = {Text = "!!"},
  AvgDialog_18722_Content_24 = {
    Text = "Poderia ser o de Norwich Street que parece exatamente com você...?"
  },
  AvgDialog_18722_Content_25 = {
    Text = "Muito inteligente."
  },
  AvgDialog_18722_Content_26 = {
    Text = "Mas por que... Eu não entendo."
  },
  AvgDialog_18722_Content_27 = {
    Text = "Daffodil olhou para o amanhecer nebuloso no horizonte distante, o vento frio levantando seu longo cabelo."
  },
  AvgDialog_18722_Content_28 = {
    Text = "Isso é um \"especime.\" Pertencia ao meu antigo mestre."
  },
  AvgDialog_18722_Content_29 = {
    Text = "Aqui está um segredo: Meu rosto atual é modelado a partir disso."
  },
  AvgDialog_18722_Content_3 = {
    Text = "Não se preocupe, desta vez vou me comportar e esperar aqui. Não vou correr para todo lado."
  },
  AvgDialog_18722_Content_30 = {Text = "?!"},
  AvgDialog_18722_Content_31 = {
    Text = "<LightGray:Então esta não é a verdadeira aparência da Dama dos narcisos...>"
  },
  AvgDialog_18722_Content_32 = {
    Text = "Você realmente me ajudou desta vez.\nAinda não consigo me perdoar por usar um Guardião tão inexperiente como isca."
  },
  AvgDialog_18722_Content_33 = {
    Text = "...Não importa. Desde que a investigação seja concluída, eu não me importo de ser usado uma vez."
  },
  AvgDialog_18722_Content_34 = {
    Text = "É assim? Mas eu realmente me sinto mal por isso. Então..."
  },
  AvgDialog_18722_Content_35 = {
    Text = "Como um pedido de desculpas, posso lhe conceder um pedido."
  },
  AvgDialog_18722_Content_36 = {
    Text = "É grátis~"
  },
  AvgDialog_18722_Content_37 = {Text = "!!"},
  AvgDialog_18722_Content_38 = {
    Text = "A pessoa à sua frente é um mercador astuto e implacável, possuindo inteligência, conhecimento tabu e colecionáveis preciosos que muitos almejam."
  },
  AvgDialog_18722_Content_39 = {
    Text = "E agora, ela pode te conceder um pedido sem custo."
  },
  AvgDialog_18722_Content_4 = {
    Text = "Nunca esperei que a investigação fosse concluída tão rapidamente.\nÓtimo trabalho, %player%."
  },
  AvgDialog_18722_Content_40 = {
    Text = "<LightGray:Não... A senhora Boneca ficaria chateada se descobrisse que eu estava fazendo negócios com outros fora.>"
  },
  AvgDialog_18722_Content_41 = {
    Text = "Uma enxurrada de possibilidades passa pela sua mente—Relíquias de Ouro perdidas, os bolos mais deliciosos, a enorme Presa de Leo..."
  },
  AvgDialog_18722_Content_42 = {
    Text = "Pensamentos conflitantes entrelaçam-se e colidem, mas eventualmente recuam como a maré — você decide seguir seus instintos."
  },
  AvgDialog_18722_Content_43 = {
    Text = "Você decidiu sobre seu pedido? Não seja muito ganancioso."
  },
  AvgDialog_18722_Content_44 = {
    Text = "Eu tomei uma decisão. Meus requisitos são simples."
  },
  AvgDialog_18722_Content_45 = {
    Text = "Deixa eu ver sua verdadeira forma."
  },
  AvgDialog_18722_Content_46 = {Text = "..."},
  AvgDialog_18722_Content_47 = {
    Text = "É realmente tão simples assim? Pense bem. Posso lhe dar muitas coisas, cada uma das quais vale mais do que isso."
  },
  AvgDialog_18722_Content_48 = {
    Text = "O valor é determinado pelo meu julgamento. Essa é a minha única exigência."
  },
  AvgDialog_18722_Content_49 = {
    Text = "Como esperado de um Guardião {Male=Mr.,Female=Miss}, você sempre me surpreende. Então..."
  },
  AvgDialog_18722_Content_5 = {
    Text = "Cof, graças à Dama dos Narcisos desta vez."
  },
  AvgDialog_18722_Content_50 = {
    Text = "Daffodil caminhou em sua direção. O vento levantou seu cabelo longo, fazendo-o flutuar como ondas cinzas."
  },
  AvgDialog_18722_Content_51 = {
    Text = "Você está tão perto que quase pode ver seu reflexo nos olhos dela."
  },
  AvgDialog_18722_Content_52 = {
    Text = "Lembre-se de manter em segredo, %player%."
  },
  AvgDialog_18722_Content_53 = {
    Text = "Mal ela falou e suas características começaram a borrifar e dissolver, como tintas a óleo na água..."
  },
  AvgDialog_18722_Content_54 = {
    Text = "Finalmente, você finalmente viu seu rosto claramente."
  },
  AvgDialog_18722_Content_55 = {
    Text = "Aquele era um rosto @2, lembrando-o de muitas coisas."
  },
  AvgDialog_18722_Content_56 = {
    Text = "Como a névoa úmida após a chuva, o narciso florescendo silenciosamente no canto ou o pequeno animal encolhido na escuridão..."
  },
  AvgDialog_18722_Content_57 = {
    Text = "Antes que você pudesse dar uma olhada mais de perto, o rosto desapareceu como uma gota de água se fundindo à água."
  },
  AvgDialog_18722_Content_58 = {
    Text = "Então... esta é a sua verdadeira forma."
  },
  AvgDialog_18722_Content_59 = {
    Text = "Como está? Está feio, certo?"
  },
  AvgDialog_18722_Content_6 = {
    Text = "É apenas um pequeno esforço, e eu também recuperei o que foi perdido."
  },
  AvgDialog_18722_Content_60 = {
    Text = "Você balança a cabeça."
  },
  AvgDialog_18722_Content_61 = {
    Text = "Inesperadamente... ainda assim tão típico de você."
  },
  AvgDialog_18722_Content_62 = {
    Text = "A luz da manhã varreu a umidade da chuva, envolvendo-a em um suave halo."
  },
  AvgDialog_18722_Content_63 = {
    Text = "Para ser honesto... Eu estava um pouco assustado agora há pouco, e depois fiquei surpreso com meu próprio medo."
  },
  AvgDialog_18722_Content_64 = {
    Text = "Dez anos, cinquenta anos? Eu não consigo nem lembrar a última vez que senti medo."
  },
  AvgDialog_18722_Content_65 = {
    Text = "Com medo...? Poderia ser que você esteja preocupado que eu possa achar você pouco atraente?"
  },
  AvgDialog_18722_Content_66 = {
    Text = "Daffodil não respondeu, apenas bagunçou suavemente seu cabelo."
  },
  AvgDialog_18722_Content_67 = {
    Text = "%player%, você agora é a única pessoa no mundo que viu \"eu\"."
  },
  AvgDialog_18722_Content_68 = {
    Text = "Heh, agora tenho uma pequena vantagem sobre você."
  },
  AvgDialog_18722_Content_69 = {
    Text = "Antes de eu perder minha memória, preciso desenhar rapidamente seu rosto no papel."
  },
  AvgDialog_18722_Content_7 = {
    Text = "Da perspectiva do comerciante, este foi um \"negócio\" perfeito"
  },
  AvgDialog_18722_Content_70 = {
    Text = "Daffodil sorriu, seus olhos formando um belo arco."
  },
  AvgDialog_18722_Content_71 = {
    Text = "Que criança tola."
  },
  AvgDialog_18722_Content_72 = {
    Text = "Bem, seu Comitê e amigos policiais devem estar a caminho agora, certo?"
  },
  AvgDialog_18722_Content_73 = {
    Text = "<Shake:Então você sabia o tempo todo...>"
  },
  AvgDialog_18722_Content_74 = {
    Text = "Eu não tenho paciência para essas interrogações tediosas.\nNa próxima vez, vamos encontrar um lugar tranquilo e tomar uma xícara de café."
  },
  AvgDialog_18722_Content_75 = {
    Text = "Adeus, meu {Male=Mr.,Female=Miss} Guardião."
  },
  AvgDialog_18722_Content_76 = {
    Text = "Huh? Oh... Adeus, Senhora Narciso."
  },
  AvgDialog_18722_Content_77 = {
    Text = "Daffodil acenou para você e se afastou."
  },
  AvgDialog_18722_Content_78 = {
    Text = "Olhando para sua figura relaxada à distância, você sente seu humor melhorar."
  },
  AvgDialog_18722_Content_79 = {
    Text = "A neblina remanescente se dissipou completamente, e o céu finalmente se clareou. A luz do sol filtra através das nuvens preguiçosas, aquecendo todo o seu corpo."
  },
  AvgDialog_18722_Content_8 = {
    Text = "Coisas perdidas..."
  },
  AvgDialog_18722_Content_80 = {
    Text = "Por alguma razão, você tem uma premonição—"
  },
  AvgDialog_18722_Content_81 = {
    Text = "Vocês continuarão se encontrando através de diferentes tempos e dimensões."
  },
  AvgDialog_18722_Content_9 = {
    Text = "O Caçador de Caveira pegou um <Yellow:crânio precioso> de mim, então estou aqui para fazer um pequeno investigação. É tão simples."
  },
  AvgDialog_18723_Content_1 = {
    Text = "Cof, cof, Despertadores do Reino Ultra são realmente difíceis de alcançar..."
  },
  AvgDialog_18723_Content_10 = {
    Text = "Responder...?"
  },
  AvgDialog_18723_Content_11 = {
    Text = "Ele saiu correndo enquanto você estava temporariamente ausente, e a Sra. Horla e eu estávamos conversando."
  },
  AvgDialog_18723_Content_12 = {
    Text = "Mas não há necessidade de se preocupar. Se você me seguir, verá isso em breve."
  },
  AvgDialog_18723_Content_13 = {
    Text = "Está no <Blue:Deserto ao norte da Cidade Reny>?"
  },
  AvgDialog_18723_Content_14 = {
    Text = "Oh? Parece que nossa pequena detetive é bastante perspicaz. Como você conseguiu descobrir?"
  },
  AvgDialog_18723_Content_15 = {
    Text = "Aquele cara exibe o Fenômeno D, que provavelmente está relacionado à praga que ocorreu no norte há três anos."
  },
  AvgDialog_18723_Content_16 = {
    Text = "Agora que está gravemente ferido e enfrentando ataques tanto nossos quanto da polícia, não há muitos lugares restantes para onde ir."
  },
  AvgDialog_18723_Content_17 = {
    Text = "Não importa se é se esconder na terra devastada, é um avanço que vale a pena investigar."
  },
  AvgDialog_18723_Content_18 = {
    Text = "Nada mal, bastante inteligente. Mas você sabe quão vasto é aquele desperdício?"
  },
  AvgDialog_18723_Content_19 = {
    Text = "Aproximadamente 50 milhas quadradas.\nVocê não gostaria de desperdiçar suas preciosas férias em exploração geológica e trabalho de censo populacional, gostaria?"
  },
  AvgDialog_18723_Content_2 = {
    Text = "Você cambaleia até uma encruzilhada."
  },
  AvgDialog_18723_Content_20 = {
    Text = "E eu sei o seu exato esconderijo.  \nVocê gostaria de vir junto?"
  },
  AvgDialog_18723_Content_21 = {
    Text = "Não concorde. Ela é extremamente perigosa; não se deixe enganar por ela."
  },
  AvgDialog_18723_Content_22 = {
    Text = "Vou contar até três. Três, dois..."
  },
  AvgDialog_18723_Content_23 = {Text = "..."},
  AvgDialog_18723_Content_24 = {
    Text = "Vou com você."
  },
  AvgDialog_18723_Content_25 = {Text = "..."},
  AvgDialog_18723_Content_26 = {
    Text = "Hmm, que criança obediente."
  },
  AvgDialog_18723_Content_27 = {
    Text = "Lady Daffodil, posso acompanhá-la?"
  },
  AvgDialog_18723_Content_28 = {
    Text = "Uma menina frágil sai das sombras das árvores atrás de você, seus olhos cheios de preocupação."
  },
  AvgDialog_18723_Content_29 = {
    Text = "Eu sei que você está preocupado com %player%."
  },
  AvgDialog_18723_Content_3 = {
    Text = "Não há mais caçadores aqui, apenas Narciso e sua sombra alongada."
  },
  AvgDialog_18723_Content_30 = {
    Text = "Mas eu sinto muito, minha pequena rosa. Desta vez, só posso levar uma pessoa."
  },
  AvgDialog_18723_Content_31 = {
    Text = "O vento frio uiva pelas ruas da noite. Horla se envolve firmemente na carta à prova de vento e aquecedora, seu rosto pálido levantado enquanto olha para Narciso com uma expressão séria."
  },
  AvgDialog_18723_Content_32 = {
    Text = "Por que? Posso não ser bom em lutar, mas uma mão extra sempre é útil, não é?"
  },
  AvgDialog_18723_Content_33 = {
    Text = "Eu só posso levar um. Desculpe, Pequena Rosa, tenho meus motivos."
  },
  AvgDialog_18723_Content_34 = {Text = "..."},
  AvgDialog_18723_Content_35 = {
    Text = "Lady Daffodil, você certamente vai escoltar {Male=Mr.,Female=Miss} %player% de volta em segurança, certo?"
  },
  AvgDialog_18723_Content_36 = {
    Text = "Daffodil observou as mariposas flutuando sob o poste de luz e soprou lentamente um anel de fumaça de sua boca."
  },
  AvgDialog_18723_Content_37 = {
    Text = "Claro, pode ficar tranquilo."
  },
  AvgDialog_18723_Content_4 = {
    Text = "Por algum motivo, você sente que ela está lá em pé há muito tempo."
  },
  AvgDialog_18723_Content_5 = {
    Text = "Parece que desde tempos antigos, ela está aqui sozinha, olhando silenciosamente para o horizonte sem pronunciar uma palavra."
  },
  AvgDialog_18723_Content_6 = {
    Text = "Você está aqui."
  },
  AvgDialog_18723_Content_7 = {
    Text = "Daffodil se virou, sua expressão ainda vaga."
  },
  AvgDialog_18723_Content_8 = {
    Text = "Onde está o Caçador de Crânios? Você perdeu o rastro?"
  },
  AvgDialog_18723_Content_9 = {
    Text = "Sim, perdemos o controle. Mas... acho que já sei a resposta."
  },
  AvgDialog_18724_Content_1 = {Text = "De longe"},
  AvgDialog_18724_Content_10 = {
    Text = "Com base na condição dos corpos e nas declarações das testemunhas, os dois morreram dentro de meia hora um do outro."
  },
  AvgDialog_18724_Content_11 = {
    Text = "O lugar da morte está por perto?"
  },
  AvgDialog_18724_Content_12 = {
    Text = "Ramona balançou a cabeça."
  },
  AvgDialog_18724_Content_13 = {
    Text = "Mesmo de carro, leva mais de uma hora, sem mencionar que muito poucas pessoas na cidade possuem carros."
  },
  AvgDialog_18724_Content_14 = {
    Text = "... Talvez o Velho Freeman estivesse certo."
  },
  AvgDialog_18724_Content_15 = {
    Text = "Os Caçadores de Crânios são uma organização. Mas qual é seu verdadeiro propósito?"
  },
  AvgDialog_18724_Content_16 = {
    Text = "Cabeças@2 Mais cabeças..."
  },
  AvgDialog_18724_Content_17 = {
    Text = "Um vento frio repentino soprava de trás."
  },
  AvgDialog_18724_Content_18 = {
    Text = "Você se vira, apenas para ver o corpo sem cabeça correndo em sua direção com uma velocidade incrível."
  },
  AvgDialog_18724_Content_19 = {Text = "?!"},
  AvgDialog_18724_Content_2 = {
    Text = "00:15, Cabana de Horla"
  },
  AvgDialog_18724_Content_20 = {
    Text = "Me dê cabeça@3 dê@1 cabeça@4"
  },
  AvgDialog_18724_Content_21 = {
    Text = "Você rapidamente desvia seu corpo. O corpo despedaça o vidro à frente, desaparecendo na vasta noite."
  },
  AvgDialog_18724_Content_22 = {
    Text = "Tal velocidade incrível... Poderia ser um Despertador do Reino Ultra?"
  },
  AvgDialog_18724_Content_23 = {
    Text = "Assim como você está confuso, um forte aroma de narcisos envolvendo você completamente."
  },
  AvgDialog_18724_Content_24 = {
    Text = "Uma saia roxa passa rapidamente por você, então desaparece diante de seus olhos."
  },
  AvgDialog_18724_Content_25 = {
    Text = "Lady Daffodil...?"
  },
  AvgDialog_18724_Content_26 = {
    Text = "Rápido, alcance! Não deixe a pista importante escapar."
  },
  AvgDialog_18724_Content_3 = {
    Text = "Você encontrou um canto tranquilo e explicou o que havia acabado de acontecer para Ramona."
  },
  AvgDialog_18724_Content_4 = {
    Text = "Claro, apenas pule a parte em que você quase teve a garganta cortada."
  },
  AvgDialog_18724_Content_5 = {Text = "..."},
  AvgDialog_18724_Content_6 = {
    Text = "Liguei para você <Red:35> vezes desde esta tarde, mas não houve resposta."
  },
  AvgDialog_18724_Content_7 = {
    Text = "Desculpe, aconteceu tão de repente..."
  },
  AvgDialog_18724_Content_8 = {
    Text = "...Isso não acontecerá novamente."
  },
  AvgDialog_18724_Content_9 = {
    Text = "As identidades das vítimas encontradas durante o dia foram confirmadas.\nCarpinteiro Damon Mendes, 35; Jovem desempregado Thomas Quillen, 23."
  },
  AvgDialog_18725_Content_1 = {
    Text = "Uma moldura de foto invertida chama a sua atenção."
  },
  AvgDialog_18725_Content_10 = {
    Text = "<RedItalic:Ele bebeu dez garrafas de álcool no domingo, perdeu seu emprego e perdeu sua esposa.>"
  },
  AvgDialog_18725_Content_11 = {
    Text = "Alguém está suavemente murmurando uma canção de ninar sem ritmo."
  },
  AvgDialog_18725_Content_12 = {
    Text = "A melodia seca parece uma mão invisível e úmida acariciando suavemente os pelos já eretos na nuca."
  },
  AvgDialog_18725_Content_13 = {
    Text = "<RedItalic: O velho Freeman gemia e bebia onze garrafas de licor novamente na segunda-feira...>"
  },
  AvgDialog_18725_Content_14 = {
    Text = "Acompanhado pelo rangido das tábuas de madeira, Harriet ficou em silêncio diante do corredor mal iluminado."
  },
  AvgDialog_18725_Content_15 = {
    Text = "Isso mesmo, o Velho Freeman é meu marido."
  },
  AvgDialog_18725_Content_16 = {Text = "O que?!"},
  AvgDialog_18725_Content_17 = {
    Text = "Naquela época, todos pensavam que eu estava morta, incluindo meu marido."
  },
  AvgDialog_18725_Content_18 = {
    Text = "Depois, após um tempo desconhecido, voltei à vida... mas algo em mim havia mudado."
  },
  AvgDialog_18725_Content_19 = {
    Text = "Você permanece em silêncio, já adivinhando o resto da história."
  },
  AvgDialog_18725_Content_2 = {
    Text = "Da cozinha vinha o som borbulhante da água fervendo; a Sra. Harriet ainda estava ocupada lá dentro."
  },
  AvgDialog_18725_Content_20 = {
    Text = "Os humanos infectados por Dissolução sofrem danos mentais irreversíveis, levando a várias complicações"
  },
  AvgDialog_18725_Content_21 = {
    Text = "Não é surpresa que Lady Harriet tenha terminado assim."
  },
  AvgDialog_18725_Content_22 = {
    Text = "Eu comecei a desejar cabeças, muitas cabeças... Então me esgueirei em um cemitério."
  },
  AvgDialog_18725_Content_23 = {
    Text = "Eu me inclinei sobre o corpo do velho Pinoco, usando uma foice enferrujada para tentar cortar sua cabeça.\nMas eu estava fraco naquela época e não conseguia nem segurar a foice firmemente..."
  },
  AvgDialog_18725_Content_24 = {
    Text = "E adivinha quem eu encontrei?"
  },
  AvgDialog_18725_Content_25 = {Text = "..."},
  AvgDialog_18725_Content_26 = {
    Text = "Eu encontrei meu marido."
  },
  AvgDialog_18725_Content_27 = {
    Text = "Ele ficou mais gordo, mais velho, e se tornou um bêbado."
  },
  AvgDialog_18725_Content_28 = {
    Text = "Heh... Este mundo sempre encontra novas maneiras de nos atormentar, pobres almas."
  },
  AvgDialog_18725_Content_29 = {
    Text = "Ele segurou sua bebida e me olhou como um cachorro de rua."
  },
  AvgDialog_18725_Content_3 = {
    Text = "Você gentilmente vira a moldura da foto."
  },
  AvgDialog_18725_Content_30 = {
    Text = "Ele riu o tempo todo. Sim, eu sei que eu devia ter parecido patético e ridículo naquela época."
  },
  AvgDialog_18725_Content_31 = {
    Text = "Mas ele... não me reconhece de jeito nenhum."
  },
  AvgDialog_18725_Content_32 = {
    Text = "...Então, você é o caçador de crânios que ele mencionou."
  },
  AvgDialog_18725_Content_33 = {
    Text = "Harriet inclinou mecanicamente a cabeça para a direita, produzindo um som \"estalado\" de seu pescoço."
  },
  AvgDialog_18725_Content_34 = {
    Text = "Sim. Mesmo sabendo que ele não se lembra de mim, eu ainda dou uma espiada nele."
  },
  AvgDialog_18725_Content_35 = {
    Text = "Então você ouviu nossa conversa, descobriu que eu estava conduzindo uma investigação sobre os assassinatos, e decidiu me seguir e emboscar?"
  },
  AvgDialog_18725_Content_36 = {Text = "..."},
  AvgDialog_18725_Content_37 = {
    Text = "Você é realmente diferente deles. Eu disse tantas coisas, mas você continua sereno."
  },
  AvgDialog_18725_Content_38 = {
    Text = "Você solta um suave suspiro, olhando para a porta trancada ao seu lado."
  },
  AvgDialog_18725_Content_39 = {
    Text = "Sangue vermelho escuro goteja como um xarope espesso da fenda da porta, lentamente rastejando em direção aos seus pés."
  },
  AvgDialog_18725_Content_4 = {
    Text = "Isso é uma velha foto de família. Os rostos da esposa e da criança há muito estão borrados, deixando apenas o marido de pé à extrema esquerda."
  },
  AvgDialog_18725_Content_40 = {
    Text = "Você sabia..."
  },
  AvgDialog_18725_Content_41 = {
    Text = "O chão, o teto, os armários... todos fedem a sangue e ao cheiro de morte."
  },
  AvgDialog_18725_Content_42 = {
    Text = "Desde o momento em que entrei, sabia de tudo."
  },
  AvgDialog_18725_Content_5 = {
    Text = "Ele está de pé, alto e relaxado, em frente à sua casa recém-construída, mostrando um sorriso radiante para a câmera."
  },
  AvgDialog_18725_Content_6 = {
    Text = "Você observa a testa e os olhos dele, um tanto familiares, e um pensamento ridículo passa de repente pela sua mente."
  },
  AvgDialog_18725_Content_7 = {
    Text = "Old Freeman...?!"
  },
  AvgDialog_18725_Content_8 = {
    Text = "Poderia ele ser o marido da Sra. Harriet?"
  },
  AvgDialog_18725_Content_9 = {
    Text = "<RedItalic: Velho Freeman, Velho Freeman, o pobre e louco bêbado Velho Freeman...>"
  },
  AvgDialog_18726_Content_1 = {
    Text = "Você caminha mais fundo na rua, seu casaco já encharcado pela chuva."
  },
  AvgDialog_18726_Content_10 = {
    Text = "Toque, toque, toque."
  },
  AvgDialog_18726_Content_11 = {
    Text = "O som de passos tranquilos ecoou da rua fora do beco, e uma figura embaçada apareceu sob o lampião da rua."
  },
  AvgDialog_18726_Content_12 = {
    Text = "É perigoso aqui, saia imediatamente—"
  },
  AvgDialog_18726_Content_13 = {
    Text = "Isso é uma mulher."
  },
  AvgDialog_18726_Content_14 = {
    Text = "Ela está sozinha sob o candeeiro, segurando uma cabeça gordinha que se encaixa perfeitamente com o pescoço do corpo sem cabeça atrás de você."
  },
  AvgDialog_18726_Content_15 = {
    Text = "O sangue goteja do pescoço, fluindo lentamente ao longo das fendas nos azulejos do chão."
  },
  AvgDialog_18726_Content_16 = {
    Text = "Fique bem aí.\nQuem é você?"
  },
  AvgDialog_18726_Content_17 = {
    Text = "As luzes de rua fracas piscam, emitindo um zumbido elétrico irritante."
  },
  AvgDialog_18726_Content_18 = {
    Text = "A mulher levanta a cabeça, e você finalmente consegue distinguir seus traços."
  },
  AvgDialog_18726_Content_19 = {Text = "..."},
  AvgDialog_18726_Content_2 = {
    Text = "Sangue vermelho escuro flui do <Sombra>, estendendo tentáculos ameaçadores, convidando-o silenciosamente."
  },
  AvgDialog_18726_Content_20 = {
    Text = "<Gray:Daphne... Lady Delf?>"
  },
  AvgDialog_18726_Content_3 = {
    Text = "Está quieto aqui; você só pode ouvir o som da chuva, passos e respiração."
  },
  AvgDialog_18726_Content_4 = {
    Text = "Eles soam como um batucar caótico, crescendo mais rápido e mais alto, até você alcançar o final do beco."
  },
  AvgDialog_18726_Content_5 = {
    Text = "O cadáver inchado jaz mole na pilha de lixo, descartado descuidadamente."
  },
  AvgDialog_18726_Content_6 = {
    Text = "A incisura no pescoço está borrada, com sangue vermelho escuro jorrando dos vasos."
  },
  AvgDialog_18726_Content_7 = {
    Text = "Você não precisa tocá-lo para saber que o sangue está quente."
  },
  AvgDialog_18726_Content_8 = {
    Text = "Cabeça faltando, feridas irregulares no pescoço..."
  },
  AvgDialog_18726_Content_9 = {
    Text = "É \"Caçador de Crânios.\""
  },
  AvgDialog_18727_Content_1 = {
    Text = "Serendipidade"
  },
  AvgDialog_18727_Content_10 = {
    Text = "Se ela não mentiu ou julgou mal, então sim."
  },
  AvgDialog_18727_Content_11 = {
    Text = "<Blue:Vanguarda> chegou à Cidade Rini há uma semana e detectou sinais de um Prata ativo no local da morte."
  },
  AvgDialog_18727_Content_12 = {
    Text = "Incluindo os últimos três, este é o oitavo <Blue:Evento Predador Cranial> na Cidade Rennie."
  },
  AvgDialog_18727_Content_13 = {
    Text = "Caçador de Crânios? É assim que as pessoas aqui chamam o assassino?"
  },
  AvgDialog_18727_Content_14 = {
    Text = "Muito vívido, não é? Graças a ele, ninguém se atreve a sair depois de escurecer aqui."
  },
  AvgDialog_18727_Content_15 = {
    Text = "Você observa a rua desolada à sua frente."
  },
  AvgDialog_18727_Content_16 = {
    Text = "Às 20h, todas as portas e janelas próximas estão firmemente trancadas. O medo se infiltra pelas janelas escuras como breu, envolvendo silenciosamente os arredores."
  },
  AvgDialog_18727_Content_17 = {
    Text = "Exceto por alguns latidos de cachorro prolongados, está estranhamente silencioso aqui."
  },
  AvgDialog_18727_Content_18 = {
    Text = "Pitter-patter..."
  },
  AvgDialog_18727_Content_19 = {
    Text = "Hmm, está chovendo?"
  },
  AvgDialog_18727_Content_2 = {
    Text = "Belen Stock, 46, morreu em casa na cozinha no dia 12 de setembro.\n<Red:Cabeça desaparecida>, corpo intacto exceto por um corte serrilhado no pescoço."
  },
  AvgDialog_18727_Content_20 = {
    Text = "Uma fina e fresca chuva pinga do céu noturno, lançando um véu branco diante de você."
  },
  AvgDialog_18727_Content_21 = {
    Text = "Eu ouço chuva do seu lado. Você tem um guarda-chuva?"
  },
  AvgDialog_18727_Content_22 = {
    Text = "<Shake:Oh não. Você sempre é quem traz um guarda-chuva, então...>"
  },
  AvgDialog_18727_Content_23 = {
    Text = "Parece que ainda preciso me acostumar a viver sem você."
  },
  AvgDialog_18727_Content_24 = {Text = "..."},
  AvgDialog_18727_Content_25 = {
    Text = "Desculpe, não pude ir com você desta vez."
  },
  AvgDialog_18727_Content_26 = {
    Text = "A Senhorita Boneca insiste que eu fique para conduzir algumas pesquisas de Dissolução supostamente \"importantes\" com ela..."
  },
  AvgDialog_18727_Content_27 = {
    Text = "<Small:Ramona, você poderia me passar a amostra de Prata na terceira prateleira da quinta fileira, código SI-3007...>"
  },
  AvgDialog_18727_Content_28 = {Text = "..."},
  AvgDialog_18727_Content_29 = {
    Text = "Cuide de você, %player%. Quanto à acomodação... <Blue:Senhorita Horla> irá organizar tudo."
  },
  AvgDialog_18727_Content_3 = {
    Text = "Dwight Williams, 56 anos, morreu na interseção da Deman Street em 13 de setembro.\n<Red:Cabeça Faltando>, corpo intacto com um corte irregular no pescoço."
  },
  AvgDialog_18727_Content_30 = {
    Text = "Senhorita Horla? Não é de se admirar que a raramente a vejamos na escola; ela vive do lado de fora?"
  },
  AvgDialog_18727_Content_31 = {
    Text = "Mythag não é um acampamento de um único sentido."
  },
  AvgDialog_18727_Content_32 = {
    Text = "Despertadores de baixo risco podem sair de férias, passar a noite fora ou visitar a família.\nA condição é simples: aplicar com antecedência e evitar causar problemas."
  },
  AvgDialog_18727_Content_33 = {
    Text = "Uh... Então a Srta. Horla também participará da investigação?"
  },
  AvgDialog_18727_Content_34 = {
    Text = "Nem todos os Despertadores estão interessados em missões de campo. Se você achar necessário, pergunte a opinião dela."
  },
  AvgDialog_18727_Content_35 = {
    Text = "A situação atual está estável e gerenciável, sem necessidade de—"
  },
  AvgDialog_18727_Content_36 = {Text = "Whoosh—"},
  AvgDialog_18727_Content_37 = {
    Text = "De repente, o som de Caro espirrando veio do beco à frente, seguido por passos caóticos, quebrando abruptamente o silêncio da noite."
  },
  AvgDialog_18727_Content_38 = {Text = "?!"},
  AvgDialog_18727_Content_39 = {
    Text = "Neste momento, este som... Poderia ser...?"
  },
  AvgDialog_18727_Content_4 = {
    Text = "Falecido nº 012, identidade e idade desconhecidas, morreu à beira do Lago Knerl no norte na manhã do dia 16 de setembro..."
  },
  AvgDialog_18727_Content_40 = {
    Text = "Vamos seguir e dar uma olhada. Lembre-se de manter contato."
  },
  AvgDialog_18727_Content_41 = {
    Text = "Que a Chave de prata ilumine o meu caminho."
  },
  AvgDialog_18727_Content_5 = {
    Text = [[
20:00, Rua Norwich
Cidade de Renny]]
  },
  AvgDialog_18727_Content_6 = {
    Text = "Cabeça ausente, cicatrizes serrilhadas..."
  },
  AvgDialog_18727_Content_7 = {
    Text = "E todos morreram ou ao sair sozinhos ou em casa."
  },
  AvgDialog_18727_Content_8 = {
    Text = "Além disso, uma semana após a morte de Dwight Williams, sua esposa afirmou vê-lo correndo apressadamente na selva."
  },
  AvgDialog_18727_Content_9 = {
    Text = "...Ressuscitado?"
  },
  AvgDialog_18764_Content_1 = {
    Text = "Não, por favor..."
  },
  AvgDialog_18764_Content_10 = {
    Text = "Cof cof cof... V–você, como pode trapacear assim!"
  },
  AvgDialog_18764_Content_11 = {
    Text = "<SmallShake:Era só um jogo de adivinhação, não precisa ficar tão exaltada...>"
  },
  AvgDialog_18764_Content_12 = {
    Text = "Onde fica a saída do labirinto?"
  },
  AvgDialog_18764_Content_13 = {
    Text = "Hehe, quer saber? Então ajoelhe-se, faça uma reverência digna a esta grande rainha, e depois..."
  },
  AvgDialog_18764_Content_14 = {
    Text = "Você lentamente levanta a mão."
  },
  AvgDialog_18764_Content_15 = {
    Text = "<Shake:E–espera! Eu falo...>"
  },
  AvgDialog_18764_Content_16 = {
    Text = "A menina abriu a boca, depois abaixou a cabeça em desânimo."
  },
  AvgDialog_18764_Content_17 = {
    Text = "Na verdade... eu também não sei. Estou trancada aqui há quase mil anos..."
  },
  AvgDialog_18764_Content_18 = {
    Text = "Tudo o que faço é dormir, ficar olhando pro nada e cuidar da minha prole. Estou enlouquecendo de tédio!"
  },
  AvgDialog_18764_Content_19 = {Text = "..."},
  AvgDialog_18764_Content_20 = {
    Text = "Você não é a mestra do labirinto? Como pode não saber onde fica a saída?"
  },
  AvgDialog_18764_Content_21 = {
    Text = "<SmallShake:Você teria que perguntar a quem me jogou aqui dentro. Como eu saberia o que Eles estavam pensando...>"
  },
  AvgDialog_18764_Content_22 = {
    Text = "Como isso é possível..."
  },
  AvgDialog_18764_Content_23 = {
    Text = "Então, e se, digo hipoteticamente—"
  },
  AvgDialog_18764_Content_24 = {
    Text = "E se a pessoa que entrou no labirinto não estiver fisicamente presente, mas existir em alguma forma de consciência."
  },
  AvgDialog_18764_Content_25 = {
    Text = "Seria possível para ela, hm, digamos... contornar as regras deste labirinto?"
  },
  AvgDialog_18764_Content_26 = {
    Text = "Agrippa lançou-lhe um olhar intrigado."
  },
  AvgDialog_18764_Content_27 = {
    Text = "Claro que não."
  },
  AvgDialog_18764_Content_28 = {
    Text = "Quer adivinhar por que tem visto tantas pessoas e lugares familiares no labirinto?"
  },
  AvgDialog_18764_Content_29 = {
    Text = "Ilusão? Não, memórias..."
  },
  AvgDialog_18764_Content_3 = {
    Text = "Você finalmente eliminou a última \"Charlotte.\""
  },
  AvgDialog_18764_Content_30 = {
    Text = "Agrippa balançou a cabeça."
  },
  AvgDialog_18764_Content_31 = {
    Text = "Nenhum dos dois. Para ser precisa, é <Yellow:consciência>."
  },
  AvgDialog_18764_Content_32 = {
    Text = "<Yellow:O que ficou preso no labirinto sempre foi apenas a sua consciência, afinal.>"
  },
  AvgDialog_18764_Content_4 = {
    Text = "A Keygrave gradualmente desvaneceu, e você retornou ao lugar onde tudo começou."
  },
  AvgDialog_18764_Content_5 = {
    Text = "Saia. Eu sei onde você está."
  },
  AvgDialog_18764_Content_6 = {
    Text = "Um zumbido semelhante a um Abalar surgiu das profundezas subterrâneas, e o chão lentamente se abriu em rachaduras."
  },
  AvgDialog_18764_Content_7 = {Text = "BOOM!!"},
  AvgDialog_18764_Content_8 = {
    Text = "Pfft... Ptui ptui ptui!!"
  },
  AvgDialog_18764_Content_9 = {
    Text = "Agrippa irrompeu do subsolo, coberta de poeira."
  },
  AvgDialog_18765_Content_1 = {
    Text = "Consciência coletiva"
  },
  AvgDialog_18765_Content_10 = {
    Text = "Você fez o dever de casa desta semana? A prova de \"Introdução à Dissolução\" está chegando. Como está a sua revisão?"
  },
  AvgDialog_18765_Content_11 = {
    Text = "Ramona?! Não, eu não... Espere, isso não é..."
  },
  AvgDialog_18765_Content_12 = {
    Text = "%player%, você chegou 5 minutos atrasado(a) na aula hoje. Seu atraso acumulado neste mês é de 30 minutos e 15 segundos."
  },
  AvgDialog_18765_Content_13 = {
    Text = "Venha ao meu escritório depois da aula."
  },
  AvgDialog_18765_Content_14 = {Text = "—!!"},
  AvgDialog_18765_Content_15 = {
    Text = "Pfft. <Big:Ahahahahahaha!>"
  },
  AvgDialog_18765_Content_16 = {
    Text = "Assustado, não é? Você realmente deveria se olhar no espelho e ver como está agora."
  },
  AvgDialog_18765_Content_17 = {Text = "..."},
  AvgDialog_18765_Content_18 = {
    Text = "Esses... truques de metamorfose, onde você aprendeu todos eles?"
  },
  AvgDialog_18765_Content_19 = {
    Text = "Você uma vez viu o arquivo de Agrippa nos arquivos do Corpo Desperto. Não havia registros relacionados a \"metamorfose\" Acima."
  },
  AvgDialog_18765_Content_20 = {
    Text = "Aprender? Eu sou o mestre deste labirinto. No meu domínio, eu faço o que... eu... quiser."
  },
  AvgDialog_18765_Content_21 = {
    Text = "Esqueça apenas uma... eu posso fazer um espetáculo com dez, cem delas."
  },
  AvgDialog_18765_Content_22 = {
    Text = "Após falar, Agrippa desapareceu mais uma vez."
  },
  AvgDialog_18765_Content_23 = {
    Text = "Em pouco tempo, uma, duas... ainda mais Charlottes apareceram diante de você."
  },
  AvgDialog_18765_Content_24 = {
    Text = "Adivinhe qual é o verdadeiro eu, hehe..."
  },
  AvgDialog_18765_Content_25 = {
    Text = "Buááá... Qual Charlotte é realmente Agrippa?"
  },
  AvgDialog_18765_Content_26 = {
    Text = "Uma chance, Apenas uma chance..."
  },
  AvgDialog_18765_Content_27 = {
    Text = "Incontáveis vozes estridentes se entrelaçaram em uma melodia caótica e dissonante, ecoando pela sua mente."
  },
  AvgDialog_18765_Content_28 = {
    Text = "Saiam... saiam daqui...!!"
  },
  AvgDialog_18765_Content_29 = {
    Text = "Você respirou fundo e finalmente acalmou seus nervos."
  },
  AvgDialog_18765_Content_3 = {
    Text = "Charlotte, como você acabou assim?"
  },
  AvgDialog_18765_Content_30 = {
    Text = "Desculpe. Vocês todas parecem iguais. Não consigo distinguir."
  },
  AvgDialog_18765_Content_31 = {
    Text = "Hã? Desistindo tão cedo? Que chato."
  },
  AvgDialog_18765_Content_33 = {
    Text = "No segundo seguinte, uma \"Charlotte\" foi derrubada no chão.\nVocê massageou as têmporas e disse calmamente—"
  },
  AvgDialog_18765_Content_34 = {
    Text = "Mas tudo bem."
  },
  AvgDialog_18765_Content_35 = {
    Text = "Eu posso derrubar cada uma de vocês, e depois perguntar uma por uma."
  },
  AvgDialog_18765_Content_4 = {
    Text = "\"Charlotte\" torceu a cabeça, e um zumbido arrepiante emanou das profundezas de sua garganta."
  },
  AvgDialog_18765_Content_5 = {
    Text = "<Shake:Hee hee, não esperava por essa, esperava? Aquela sua amiguinha já se tornou uma das minhas crias há muito tempo!>"
  },
  AvgDialog_18765_Content_6 = {
    Text = "Essa voz... É você, Agrippa?"
  },
  AvgDialog_18765_Content_7 = {
    Text = "Que comovente, você ainda se lembra da minha voz.\nEspere, deixe–me mostrar algo impressionante!"
  },
  AvgDialog_18765_Content_8 = {
    Text = "Um riso abafado veio da garganta de \"Charlotte\", então seu pescoço se torceu bruscamente e, em um instante, sua aparência mudou completamente."
  },
  AvgDialog_18765_Content_9 = {
    Text = "%player%, você está comendo escondido de novo!"
  },
  AvgDialog_18766_Content_1 = {Text = "Porta"},
  AvgDialog_18766_Content_10 = {
    Text = "Você está pronta, @1? Vamos empurrar juntas para abrir."
  },
  AvgDialog_18766_Content_11 = {Text = "Creak—"},
  AvgDialog_18766_Content_12 = {Text = "<Big:!!!>"},
  AvgDialog_18766_Content_13 = {
    Text = "Isso é... que tipo de lugar...?"
  },
  AvgDialog_18766_Content_14 = {
    Text = "É o lugar onde você vai ficar obedientemente pelo resto da sua vida."
  },
  AvgDialog_18766_Content_15 = {
    Text = "A menina estava sentada na plataforma oca com um sorriso travesso, o queixo apoiado em ambas as mãos, a perna direita cruzada balançando preguiçosamente."
  },
  AvgDialog_18766_Content_16 = {
    Text = "Bem-vinda ao meu labirinto."
  },
  AvgDialog_18766_Content_17 = {
    Text = "Você estava dormindo tão profundamente. Eu estava prestes a te dar uns insetos para te animar."
  },
  AvgDialog_18766_Content_18 = {
    Text = "<LightGray: Agrippa...?>"
  },
  AvgDialog_18766_Content_19 = {
    Text = "Você olha para as roupas desconhecidas que está vestindo e percebe que entrou em Sonhar mais uma vez."
  },
  AvgDialog_18766_Content_2 = {
    Text = "Dizem que no labirinto \"Dele\", não é apenas o senso de direção que se perde."
  },
  AvgDialog_18766_Content_20 = {
    Text = "O que há de diferente é que desta vez você quase perdeu todas as memórias da hospedeira original.\nQuem é Ela? De onde Ela veio?"
  },
  AvgDialog_18766_Content_21 = {
    Text = "Você não sabe nada."
  },
  AvgDialog_18766_Content_22 = {
    Text = "<Shake:O que está acontecendo... A hospedeira original, não, quem sou eu...>"
  },
  AvgDialog_18766_Content_23 = {
    Text = "Tudo bem, desista de pensar. Você não vai se lembrar de nada."
  },
  AvgDialog_18766_Content_24 = {
    Text = "Mesmo depois de 1 dia, 100 dias, 1000 dias, sua mente ainda estará tão limpa quanto a de um bebê recém-nascido."
  },
  AvgDialog_18766_Content_25 = {
    Text = "Agora vou te dar duas escolhas."
  },
  AvgDialog_18766_Content_26 = {
    Text = "<Red:Uma: Assine um contrato comigo e então se torne minha cria.>"
  },
  AvgDialog_18766_Content_27 = {
    Text = "<Red:Duas: Morra de fome no labirinto e então se torne minha cria.>"
  },
  AvgDialog_18766_Content_28 = {
    Text = "Agrippa habilmente expôs a situação e apresentou as escolhas para você, Como se essa rotina já tivesse sido repetida incontáveis vezes."
  },
  AvgDialog_18766_Content_29 = {
    Text = "Descendentes? O que é isso?"
  },
  AvgDialog_18766_Content_3 = {
    Text = "Seu nome, sua terra natal, seu amado... tudo que é importante e sem importância será deixado para trás."
  },
  AvgDialog_18766_Content_30 = {
    Text = "Liberar. Sem veneno, sem dor, sem dano. Quanto a efeitos colaterais? Você nem vai notar que existem."
  },
  AvgDialog_18766_Content_31 = {
    Text = "Então, comparado àqueles deuses malignos que constantemente exigem que você ofereça sua vida ou mate seus entes queridos, não diria que sou muito mais gentil?"
  },
  AvgDialog_18766_Content_32 = {Text = "..."},
  AvgDialog_18766_Content_33 = {
    Text = "Agora vou te dar três segundos para fazer sua escolha. Assinar o pacto, ou morrer de fome?"
  },
  AvgDialog_18766_Content_34 = {Text = "Três—"},
  AvgDialog_18766_Content_35 = {Text = "Dois—"},
  AvgDialog_18766_Content_36 = {
    Text = "Certo, eu me decidi."
  },
  AvgDialog_18766_Content_37 = {Text = "Uh...?"},
  AvgDialog_18766_Content_38 = {
    Text = "Decisivo. Você... não é nada mal. Então me diga sua escolha."
  },
  AvgDialog_18766_Content_39 = {
    Text = "Você acena com a cabeça, silenciosamente recuando o pé direito uma curta distância."
  },
  AvgDialog_18766_Content_4 = {
    Text = "A partir de então, você tem Apenas uma Identidade: <Red:Sua progênie>."
  },
  AvgDialog_18766_Content_40 = {
    Text = "Minha escolha é—"
  },
  AvgDialog_18766_Content_41 = {
    Text = "Você gira sem hesitar e dispara em velocidade máxima."
  },
  AvgDialog_18766_Content_42 = {
    Text = "<BigShake:Corra!!>"
  },
  AvgDialog_18766_Content_43 = {
    Text = "Muito, muito tempo Depois..."
  },
  AvgDialog_18766_Content_44 = {
    Text = "Huff... huff..."
  },
  AvgDialog_18766_Content_45 = {
    Text = "Você Corre pelo longo corredor, até que uma Porta bloqueia seu Caminho."
  },
  AvgDialog_18766_Content_46 = {
    Text = "O Museu de cera? De novo..."
  },
  AvgDialog_18766_Content_47 = {
    Text = "Se eu me lembro corretamente, esta é a 23ª vez que eu vi isso."
  },
  AvgDialog_18766_Content_48 = {
    Text = "Sim, há inúmeras Portas aqui, levando a inúmeros espaços."
  },
  AvgDialog_18766_Content_49 = {
    Text = "Elas aparecem diante de você repetidamente, com tal frequência que seria suficiente para enlouquecer até o Investigador mais sereno."
  },
  AvgDialog_18766_Content_5 = {
    Text = "<Shake:P–progênie?>"
  },
  AvgDialog_18766_Content_50 = {
    Text = "Você empurra a Porta e continua pelo corredor."
  },
  AvgDialog_18766_Content_51 = {
    Text = "Este corredor de novo... 15 vezes."
  },
  AvgDialog_18766_Content_52 = {
    Text = "Você instintivamente toca os Cufflinks de prata cravados na sua manga."
  },
  AvgDialog_18766_Content_53 = {
    Text = "Um antigo emblema escolar de Misaq... Então desta vez me tornei uma veterana do passado?"
  },
  AvgDialog_18766_Content_54 = {
    Text = "Mas como ela entrou no labirinto?"
  },
  AvgDialog_18766_Content_55 = {
    Text = "Enquanto você pondera, mais uma Porta bloqueia seu Caminho."
  },
  AvgDialog_18766_Content_56 = {
    Text = "Você está diante desta Porta agora, @1. Abra-a."
  },
  AvgDialog_18766_Content_57 = {
    Text = "Quem está falando?!"
  },
  AvgDialog_18766_Content_58 = {
    Text = "Cabeça... dói. Essas são as memórias do Senpai?"
  },
  AvgDialog_18766_Content_59 = {
    Text = "Respire fundo, %player%. Esvazie sua mente..."
  },
  AvgDialog_18766_Content_6 = {
    Text = "Sim. Incontáveis progênies, como uma maré pálida, avançam para o labirinto vindas de todas as direções."
  },
  AvgDialog_18766_Content_60 = {
    Text = "Você se força a se acalmar, gira a maçaneta de latão e puxa a Porta suavemente para abri-la."
  },
  AvgDialog_18766_Content_61 = {
    Text = "...Keygrave?"
  },
  AvgDialog_18766_Content_62 = {
    Text = "Através da névoa rodopiante, você nota uma figura ao mesmo tempo familiar e estranha."
  },
  AvgDialog_18766_Content_63 = {
    Text = "Charlotte... <Big:Charlotte!>"
  },
  AvgDialog_18766_Content_64 = {
    Text = "Você se lembra da menina chamada Charlotte. Ela era a amiga que trouxe \"você\" para o labirinto."
  },
  AvgDialog_18766_Content_65 = {
    Text = "<Big:Espere por mim, Charlotte!>"
  },
  AvgDialog_18766_Content_66 = {
    Text = "Você corre para frente e agarra Charlotte pelo pulso."
  },
  AvgDialog_18766_Content_67 = {
    Text = "No instante em que sua pele toca a dela, incontáveis fragmentos caóticos lampejam pela sua mente."
  },
  AvgDialog_18766_Content_68 = {
    Text = "Abra a Porta, @1."
  },
  AvgDialog_18766_Content_69 = {
    Text = "<Shake:Não, eu— Acabei de lembrar que não terminei meu dever de casa, eu quero—>"
  },
  AvgDialog_18766_Content_7 = {
    Text = "Passagens para o labirinto estão por toda parte. Nas paredes, nos esgotos, e onde estamos agora..."
  },
  AvgDialog_18766_Content_70 = {
    Text = "<Big:Aaaaah!!>"
  },
  AvgDialog_18766_Content_71 = {
    Text = "<Shake:Charlotte, seu rosto...>"
  },
  AvgDialog_18766_Content_72 = {
    Text = "Porta... Porta..."
  },
  AvgDialog_18766_Content_73 = {
    Text = "@1Porta@2abrir@4"
  },
  AvgDialog_18766_Content_74 = {
    Text = "<RedBig:Abrir a Porta...>"
  },
  AvgDialog_18766_Content_75 = {
    Text = "Então é assim. Foi você quem atraiu \"eu\" para o labirinto..."
  },
  AvgDialog_18766_Content_76 = {
    Text = "Instintivamente, você soltou o pulso de Charlotte e recuou alguns passos, tropeçando."
  },
  AvgDialog_18766_Content_77 = {
    Text = "A neblina se dissipou gradualmente. Charlotte se virou com algum esforço e olhou para você com tristeza."
  },
  AvgDialog_18766_Content_78 = {
    Text = "...@4Porta@4@1"
  },
  AvgDialog_18766_Content_79 = {
    Text = "—Com aquelas órbitas ocas e vazias."
  },
  AvgDialog_18766_Content_8 = {
    Text = "Em um portão oculto sob a <Blue:Biblioteca Municipal>."
  },
  AvgDialog_18766_Content_9 = {
    Text = "<Shake:Eu... Não consigo acreditar que um lugar assim realmente existe... Todas aquelas lendas eram verdade...>"
  },
  AvgDialog_18767_Content_1 = {
    Text = "O fim do labirinto"
  },
  AvgDialog_18767_Content_10 = {
    Text = "Shh... Fecha os olhos, limpa a mente, não penses em nada."
  },
  AvgDialog_18767_Content_11 = {
    Text = "Não faça nada..."
  },
  AvgDialog_18767_Content_12 = {Text = "UUGHH!"},
  AvgDialog_18767_Content_13 = {
    Text = "A minha cabeça está prestes a rachar... É melhor não usar este método com muita frequência..."
  },
  AvgDialog_18767_Content_14 = {
    Text = "<Shake:Saiam do caminho, saiam todos do meu caminho!>"
  },
  AvgDialog_18767_Content_15 = {
    Text = "Quem se atrever a tocar na minha família— mato este porco primeiro!!"
  },
  AvgDialog_18767_Content_16 = {
    Text = "Uma Lâmina afiada trémula pressiona contra a tua garganta."
  },
  AvgDialog_18767_Content_17 = {Text = "...?"},
  AvgDialog_18767_Content_18 = {
    Text = "Sonhar bem-sucedido— embora não fosse bem a entrada que tinhas imaginado."
  },
  AvgDialog_18767_Content_19 = {
    Text = "À frente ergue-se uma multidão de escravos de peito nu. Há muito desapareceu a sua habitual subserviência, os seus olhos brilhando de ódio."
  },
  AvgDialog_18767_Content_2 = {
    Text = "Queres dizer que podes mergulhar na minha consciência e mudar o passado?"
  },
  AvgDialog_18767_Content_20 = {
    Text = "Diante da ameaça de Agrippa, eles ficam em silêncio a princípio, depois caem numa explosão de gargalhadas."
  },
  AvgDialog_18767_Content_21 = {
    Text = "Pfft. Hahahahahaha!"
  },
  AvgDialog_18767_Content_22 = {
    Text = "Ora ora, nossa pequena Princesa tem coragem!"
  },
  AvgDialog_18767_Content_23 = {
    Text = "Heh. Vocês não acreditam em mim, não..."
  },
  AvgDialog_18767_Content_24 = {
    Text = "A Lâmina afiada corta rapidamente, e uma dor ardente atravessa seu pescoço."
  },
  AvgDialog_18767_Content_25 = {
    Text = "Ngh! Você está falando sério!!"
  },
  AvgDialog_18767_Content_26 = {
    Text = "<Big:Calem a boca!> Você e eles— estão todos juntos nisso! Foi você quem roubou a chave da minha família e os contratos de servidão!"
  },
  AvgDialog_18767_Content_27 = {Text = "...?"},
  AvgDialog_18767_Content_28 = {
    Text = "E vocês todos! Se alguém rir de novo, vou fazer outro corte no pescoço {Male=his,Female=her}!"
  },
  AvgDialog_18767_Content_29 = {
    Text = "Abaixe a faca, Agrippa... <Big:Correr!>"
  },
  AvgDialog_18767_Content_3 = {
    Text = "Se realmente tivesses esse tipo de poder, como é que eu te teria aprisionado?"
  },
  AvgDialog_18767_Content_31 = {
    Text = "O chicote golpeou violentamente a mulher. Antes que pudesse emitir um som, ela caiu inconsciente."
  },
  AvgDialog_18767_Content_32 = {
    Text = "<Big:Mãe!!>"
  },
  AvgDialog_18767_Content_33 = {
    Text = "Pare com esse seu ato ridículo. Não somos mais Os escravos."
  },
  AvgDialog_18767_Content_34 = {
    Text = "Quando você mandava em nós nos campos de treinamento, por que não pensou no dia de hoje?"
  },
  AvgDialog_18767_Content_35 = {
    Text = "Abra os olhos e observe bem, \"pequena Princesa.\" Veja como vamos humilhá-la..."
  },
  AvgDialog_18767_Content_36 = {
    Text = "<Shake:Covardes, todos vocês são covardes! Como ousam...>"
  },
  AvgDialog_18767_Content_37 = {
    Text = "<Shake:Quem maltratou vocês fui eu, não eles... Não, eu fui tola demais. Eu não deveria ter tratado vocês daquela forma...>"
  },
  AvgDialog_18767_Content_38 = {
    Text = "<Shake:Venham para cima de mim, façam o que quiserem! Apenas deixem minha mãe ir...>"
  },
  AvgDialog_18767_Content_39 = {
    Text = "A menina já estava em tal pânico que suas palavras saíam incoerentes. O punhal em sua mão tremia violentamente, quase caindo no chão."
  },
  AvgDialog_18767_Content_4 = {
    Text = "Ahem... Para ser preciso, é influência, não mudança."
  },
  AvgDialog_18767_Content_40 = {
    Text = "Você soltou um suspiro suave e gentilmente tirou o punhal da mão dela."
  },
  AvgDialog_18767_Content_41 = {
    Text = "Não tenha medo, Agrippa. Eu vou te ajudar."
  },
  AvgDialog_18767_Content_42 = {
    Text = "Ajude-me? Você não é..."
  },
  AvgDialog_18767_Content_43 = {
    Text = "Puseste-te à frente de Agrippa, olhando os escravos diretamente nos olhos."
  },
  AvgDialog_18767_Content_44 = {
    Text = "Muito bem, o Tempo de jogo acabou.\nJá conseguiram o que queriam. Agora podem ir embora."
  },
  AvgDialog_18767_Content_45 = {
    Text = "Oh, alguém agora quer bancar o chefe, a dar-nos lições e tudo."
  },
  AvgDialog_18767_Content_46 = {
    Text = "Cres, não devias estar do nosso lado?"
  },
  AvgDialog_18767_Content_47 = {
    Text = "Você balança a cabeça."
  },
  AvgDialog_18767_Content_48 = {
    Text = "Sempre respeitei a vossa causa de rebelião, mas ninguém tem o direito de massacrar inocentes."
  },
  AvgDialog_18767_Content_49 = {
    Text = "\"Inocente\"...?"
  },
  AvgDialog_18767_Content_5 = {
    Text = "Não te subestimes. O teu labirinto é muito mais complexo do que eu esperava..."
  },
  AvgDialog_18767_Content_50 = {
    Text = "Heh, este tipo traiu-nos completamente. Para quê desperdiçar mais palavras com ele."
  },
  AvgDialog_18767_Content_51 = {
    Text = "<Big:Mate-o!>"
  },
  AvgDialog_18767_Content_6 = {
    Text = "Agrippa olha para ti com desconfiança."
  },
  AvgDialog_18767_Content_7 = {
    Text = "Esquece, não é como se houvesse outra maneira.\nO que precisas que eu faça?"
  },
  AvgDialog_18767_Content_8 = {
    Text = "Tentas com esforço recordar o teu Estado de cada vez que entraste em Sonhar, e gentilmente pegas na mão de Agrippa."
  },
  AvgDialog_18767_Content_9 = {
    Text = "Ei, tu— não estás a tentar aproveitar-te de mim, pois não?"
  },
  AvgDialog_18768_Content_1 = {
    Text = "Cof... Cof..."
  },
  AvgDialog_18768_Content_10 = {
    Text = "O som grave das trompas ecoa ao longe—ainda não conseguiste escapar à Caçada do exército rebelde."
  },
  AvgDialog_18768_Content_11 = {
    Text = "Tu e Agrippa Correm de mãos dadas sob o céu escuro como breu."
  },
  AvgDialog_18768_Content_12 = {
    Text = "A família dela não está longe de você. Todos, movidos tanto pelo medo quanto pela esperança, correm em direção a um horizonte sem fim à vista."
  },
  AvgDialog_18768_Content_13 = {
    Text = "Quem é você? Por que você me salvou?"
  },
  AvgDialog_18768_Content_14 = {
    Text = "Hmm... para ser preciso, fiz isso para salvar a mim mesmo."
  },
  AvgDialog_18768_Content_15 = {
    Text = "Oh... independentemente do motivo, você é... uma boa pessoa."
  },
  AvgDialog_18768_Content_16 = {
    Text = "Quando formos resgatados, vou te dar todo o dinheiro e as joias que escondi secretamente ao longo dos anos."
  },
  AvgDialog_18768_Content_17 = {
    Text = "Você não consegue conter o riso."
  },
  AvgDialog_18768_Content_18 = {
    Text = "Não preciso do seu dinheiro. Mas... se quiser me retribuir, tenho um pedido."
  },
  AvgDialog_18768_Content_19 = {
    Text = "Diga—vou realizar, custe o que custar."
  },
  AvgDialog_18768_Content_2 = {
    Text = "Por respeito aos velhos tempos, os irmãos contiveram-se agora há pouco."
  },
  AvgDialog_18768_Content_20 = {
    Text = "Uma estrela cadente cruza o céu noturno—agora é o momento perfeito para fazer um pedido."
  },
  AvgDialog_18768_Content_21 = {
    Text = "Meu pedido é simples. Continue sorrindo e lembre-se de como você se sente agora."
  },
  AvgDialog_18768_Content_22 = {
    Text = "Como me sinto agora? Hmm... Feliz, aliviada, preocupada? Qual deles você quer dizer!"
  },
  AvgDialog_18768_Content_23 = {
    Text = "Siga seu coração. Estou curioso para saber a qual Agrippa eles vão me levar."
  },
  AvgDialog_18768_Content_24 = {Text = "?"},
  AvgDialog_18768_Content_25 = {
    Text = "<SmallShake:Esse cara pode ser uma boa pessoa, mas o jeito dele falar é muito estranho...>"
  },
  AvgDialog_18768_Content_26 = {
    Text = "O som da trombeta finalmente se dissipou, e a tranquilidade da noite retornou mais uma vez."
  },
  AvgDialog_18768_Content_27 = {
    Text = "Finalmente... acabou."
  },
  AvgDialog_18768_Content_28 = {
    Text = "A donzela correu até o topo da duna de areia em poucos passos rápidos, cerrou os punhos e gritou na direção onde a trombeta havia desaparecido."
  },
  AvgDialog_18768_Content_29 = {
    Text = "Aposto que não esperava por essa, seu @2, fui eu quem sobreviveu até o fim!"
  },
  AvgDialog_18768_Content_3 = {
    Text = "Já que insistes em ajudá-los, não nos culpes por não mostrarmos piedade—"
  },
  AvgDialog_18768_Content_30 = {
    Text = "Hahahahahaha, @2!"
  },
  AvgDialog_18768_Content_31 = {
    Text = "<Shake:Agrippa! Seja uma dama, uma dama...!>"
  },
  AvgDialog_18768_Content_32 = {
    Text = "Não consigo te ouvir!!!"
  },
  AvgDialog_18768_Content_33 = {
    Text = "Que se dane ser uma dama e toda essa etiqueta, finalmente estou livre!!"
  },
  AvgDialog_18768_Content_34 = {
    Text = "Com essa declaração retumbante, a donzela abriu os braços, como se embalasse o magnífico céu estrelado acima em suas mãos."
  },
  AvgDialog_18768_Content_35 = {
    Text = "<Big:Estou livre—!!>"
  },
  AvgDialog_18768_Content_36 = {Text = "CRASH—!!"},
  AvgDialog_18768_Content_37 = {Text = "...Hã?"},
  AvgDialog_18768_Content_38 = {
    Text = "O céu desapareceu, e o labirinto desapareceu com ele."
  },
  AvgDialog_18768_Content_39 = {
    Text = "O Vale Cámbrico invadiu diretamente seu campo de visão."
  },
  AvgDialog_18768_Content_4 = {Text = "CRASH!"},
  AvgDialog_18768_Content_40 = {
    Text = "A água profunda do lago, como um espelho, fluía em quieta serenidade, enquanto o vento partia a superfície, enviando anéis de ondulações luminosas."
  },
  AvgDialog_18768_Content_41 = {
    Text = "Agrippa estava sentada atordoada na grama, olhando fixamente para tudo diante dela."
  },
  AvgDialog_18768_Content_42 = {
    Text = "%player%, nós... saímos?"
  },
  AvgDialog_18768_Content_43 = {
    Text = "Bem-vindo de volta ao mundo real, Agrippa."
  },
  AvgDialog_18768_Content_44 = {Text = "...Oh."},
  AvgDialog_18768_Content_45 = {
    Text = "Então este é o vale do rio. É cem vezes mais bonito do que dizem— não, mil vezes mais bonito."
  },
  AvgDialog_18768_Content_46 = {
    Text = "A tênue luz da manhã atravessa a névoa e recai sobre você."
  },
  AvgDialog_18768_Content_47 = {
    Text = "Agrippa fecha os olhos, saboreando avidamente os aromas há muito perdidos."
  },
  AvgDialog_18768_Content_48 = {
    Text = "Consigo sentir tantos cheiros. Terra, grama, frésia e luz do sol..."
  },
  AvgDialog_18768_Content_49 = {
    Text = "Luz do sol também tem cheiro?"
  },
  AvgDialog_18768_Content_5 = {
    Text = "Aproveitando o caos, empurras o pilar que bloqueia o caminho à frente, e o edifício inteiro começa a ficar Instável, à beira do colapso."
  },
  AvgDialog_18768_Content_50 = {
    Text = "Mm-hm. O tipo de cheiro que dá sonolência."
  },
  AvgDialog_18768_Content_51 = {
    Text = "Obrigado, %player%."
  },
  AvgDialog_18768_Content_52 = {
    Text = "Ela se espreguiça preguiçosamente e começa a cantarolar suavemente uma antiga balada romana."
  },
  AvgDialog_18768_Content_53 = {
    Text = "A melodia leve espirala pelo ar, levando o bom humor de sua cantora a cada canto do vale do rio."
  },
  AvgDialog_18768_Content_54 = {
    Text = "Após mais de mil anos, ela finalmente viu a luz do sol mais uma vez."
  },
  AvgDialog_18768_Content_55 = {
    Text = "E finalmente viu o vale do rio pela primeiríssima vez."
  },
  AvgDialog_18768_Content_6 = {
    Text = "Agora é a nossa oportunidade—sigam-me, depressa!"
  },
  AvgDialog_18768_Content_7 = {
    Text = "Agarras a mão de Agrippa e foges apressadamente com Ela e a sua família."
  },
  AvgDialog_18768_Content_8 = {
    Text = "O outrora glorioso pátio desmorona como uma besta silenciosa a tombar no chão."
  },
  AvgDialog_18768_Content_9 = {
    Text = "16@1 anos antes do Aluvião, arredores de Cápua"
  },
  AvgDialog_18769_Content_1 = {
    Text = "Barreira de Memória"
  },
  AvgDialog_18769_Content_10 = {
    Text = "O que você@1 acabou de dizer—"
  },
  AvgDialog_18769_Content_11 = {
    Text = "Esquece, não se meta com esse cara. Ele é um lunático..."
  },
  AvgDialog_18769_Content_12 = {
    Text = "Os escravos empurraram-se uns aos outros ao sair, e a cela escura finalmente ficou em silêncio."
  },
  AvgDialog_18769_Content_13 = {
    Text = "A menina emergiu das sombras no canto da cela, com a cabeça baixa."
  },
  AvgDialog_18769_Content_14 = {
    Text = "Por que não foi com eles? Esta noite seria uma chance perfeita para recuperar sua liberdade."
  },
  AvgDialog_18769_Content_15 = {
    Text = "Eu gosto daqui. Por que eu iria embora?"
  },
  AvgDialog_18769_Content_16 = {
    Text = "Gosta...? Haha, que notável. Você gosta de ser xingada, ou gosta de ser açoitada pelo meu chicote?"
  },
  AvgDialog_18769_Content_17 = {
    Text = "O Gladiador bocejou e esticou os membros confortavelmente."
  },
  AvgDialog_18769_Content_18 = {
    Text = "Eu gosto de Sangue, e gosto ainda mais de matar. Para mim, matar é liberdade."
  },
  AvgDialog_18769_Content_19 = {
    Text = "Quanto ao título de escravo, não me importa quantos me derem. Por que eu iria embora?"
  },
  AvgDialog_18769_Content_2 = {
    Text = "16 anos antes do Aluvião@1, Cápua"
  },
  AvgDialog_18769_Content_20 = {Text = "..."},
  AvgDialog_18769_Content_21 = {
    Text = "Heh... Agora estou realmente começando a te ver com outros olhos. Você é uma lunática genuína."
  },
  AvgDialog_18769_Content_22 = {
    Text = "Agrippa olhou para cima, em direção à saída da masmorra, sua expressão perfeitamente calma."
  },
  AvgDialog_18769_Content_23 = {
    Text = "Ondas carmesins de fogo avançaram em direção ao céu. Risos, choros, gritos... todo tipo de som se reuniu, compondo uma sinfonia do inferno."
  },
  AvgDialog_18769_Content_24 = {
    Text = "Em breve, eles vão me encontrar,@1 me, e então cortar minha cabeça, assim como fizeram com meus pais."
  },
  AvgDialog_18769_Content_25 = {
    Text = "Não quero essas criaturas inferiores perto de mim. Mas você..."
  },
  AvgDialog_18769_Content_26 = {
    Text = "Você é diferente deles.\nSei que tivemos algumas \"desavenças\" entre nós, mas desta vez, você certamente não vai recusar meu pedido."
  },
  AvgDialog_18769_Content_27 = {Text = "Oh? Diga."},
  AvgDialog_18769_Content_28 = {Text = "..."},
  AvgDialog_18769_Content_29 = {Text = "Mate-me."},
  AvgDialog_18769_Content_3 = {
    Text = "Droga, aquela mulher fugiu."
  },
  AvgDialog_18769_Content_30 = {
    Text = "<RedBig:Me mate...>"
  },
  AvgDialog_18769_Content_31 = {
    Text = "Agrippa...?"
  },
  AvgDialog_18769_Content_32 = {
    Text = "<RedBig:Me mate me mate me mate me mate me mate me mate me mate me mate...>"
  },
  AvgDialog_18769_Content_33 = {Text = "Agrippa!"},
  AvgDialog_18769_Content_34 = {Text = "!!"},
  AvgDialog_18769_Content_35 = {
    Text = "<Shake:Ugh...>"
  },
  AvgDialog_18769_Content_36 = {
    Text = "Eu tive um Sonho muito, muito longo..."
  },
  AvgDialog_18769_Content_37 = {
    Text = "Ouça, parece que deixamos passar algumas perguntas antes."
  },
  AvgDialog_18769_Content_38 = {
    Text = "Absurdo! Eu sou o Senhor do Labirinto—tudo está sob meu controle—"
  },
  AvgDialog_18769_Content_39 = {
    Text = "Primeiro, por que suas crias podem entrar e sair livremente do labirinto, mas você e eu não podemos?"
  },
  AvgDialog_18769_Content_4 = {
    Text = "Heh heh. Então agora ela sabe se esconder? Quando a encontrarmos, vamos cortar as pernas dela primeiro..."
  },
  AvgDialog_18769_Content_40 = {
    Text = "Vocês não compartilham uma consciência coletiva?"
  },
  AvgDialog_18769_Content_41 = {
    Text = "O que você sabe? Como o Senhor do Labirinto, devo manter uma aura de mistério o tempo todo."
  },
  AvgDialog_18769_Content_42 = {
    Text = "Além disso, Apenas eu queira, todos têm de rastejar obedientemente de volta. Como é que isso é \"entrar e sair livremente\"?"
  },
  AvgDialog_18769_Content_43 = {
    Text = "Você assente e então puxa o caderno que tem na mão."
  },
  AvgDialog_18769_Content_44 = {
    Text = "Há mais uma pergunta."
  },
  AvgDialog_18769_Content_45 = {
    Text = "Eu fiz um Lembre-se de todos os lugares que encontrei no labirinto—a escola, o Museu de cera, as ruas de Londinium..."
  },
  AvgDialog_18769_Content_46 = {
    Text = "Mas nenhum dos lugares que você Experienciou estava lá. Nenhum sequer."
  },
  AvgDialog_18769_Content_47 = {
    Text = "Por quê? Você também não está presa aqui?"
  },
  AvgDialog_18769_Content_48 = {
    Text = "Tantas perguntas! Porque esta grande rainha não quer relembrar, por que se incomodar pensando em coisas desagradáveis."
  },
  AvgDialog_18769_Content_49 = {
    Text = "Sim, <Yellow:você não quer se lembrar>."
  },
  AvgDialog_18769_Content_5 = {
    Text = "Ei, Uvhash, você viu Agrippa?"
  },
  AvgDialog_18769_Content_50 = {
    Text = "Será possível que..."
  },
  AvgDialog_18769_Content_51 = {
    Text = "É precisamente porque você—o Senhor do Labirinto—rejeita o compartilhamento de consciência que este labirinto, formado a partir da consciência daqueles presos dentro dele, permanecerá para sempre incompleto."
  },
  AvgDialog_18769_Content_52 = {
    Text = "Então nunca conseguiremos encontrar a saída."
  },
  AvgDialog_18769_Content_53 = {Text = "..."},
  AvgDialog_18769_Content_54 = {
    Text = "As perguntas que você está fazendo—eu também pensei nelas, naquela época. Afinal, este é o meu labirinto."
  },
  AvgDialog_18769_Content_55 = {
    Text = "Mas no momento em que penso no passado, isso me deixa absolutamente louca..."
  },
  AvgDialog_18769_Content_56 = {
    Text = "Agrippa agarrou a cabeça, palavras jorrando rapidamente de seus lábios como murmúrios em um sonho."
  },
  AvgDialog_18769_Content_57 = {
    Text = "Aqueles vermes desprezíveis... como ousaram fazer aquilo comigo..."
  },
  AvgDialog_18769_Content_58 = {
    Text = "Nada além de escravos, mal podiam ser chamados de humanos. Mereciam ser pisoteados sob nossos pés por toda a eternidade."
  },
  AvgDialog_18769_Content_59 = {
    Text = "Rebelião? Que fantasia."
  },
  AvgDialog_18769_Content_6 = {
    Text = "O Gladiador nas sombras abriu lentamente os olhos."
  },
  AvgDialog_18769_Content_60 = {
    Text = "Mas eles não apenas fizeram isso—penduraram as cabeças dos meus pais nas muralhas da cidade, me agarraram pelos cabelos e me fizeram olhar de perto, com cuidado, sem poder perder um único detalhe."
  },
  AvgDialog_18769_Content_61 = {
    Text = "E depois minha irmãzinha, Julia. Quando a encontrei, seu corpo inteiro@3, e ela ainda era tão jovem..."
  },
  AvgDialog_18769_Content_62 = {
    Text = "Que ridículo... Você acha que eu chorei?"
  },
  AvgDialog_18769_Content_63 = {
    Text = "Não, nunca. Preferia morrer a derramar uma única lágrima na frente deles."
  },
  AvgDialog_18769_Content_64 = {
    Text = "Somos descendentes do Lobo Cinzento. Morremos com dignidade, como verdadeiros lobos. Aqueles vira-latas nunca vão entender isso em vida."
  },
  AvgDialog_18769_Content_65 = {
    Text = "Hahahaha..."
  },
  AvgDialog_18769_Content_66 = {
    Text = "Agrippa segurou a barriga, rindo tanto que lágrimas escorriam pelo seu rosto."
  },
  AvgDialog_18769_Content_67 = {
    Text = "Eles devem ter ficado tão desapontados quando viram meu cadáver... Hahaha..."
  },
  AvgDialog_18769_Content_68 = {
    Text = "Agrippa...? Agrippa!"
  },
  AvgDialog_18769_Content_69 = {
    Text = "Você segura firmemente os ombros de Agrippa, tentando trazê-la de volta do Pesadelo do passado."
  },
  AvgDialog_18769_Content_7 = {
    Text = "...Caiam fora."
  },
  AvgDialog_18769_Content_70 = {
    Text = "Pare. Tudo isso já ficou no passado."
  },
  AvgDialog_18769_Content_71 = {Text = "..."},
  AvgDialog_18769_Content_72 = {
    Text = "Me desculpe, Agrippa. Eu não sabia antes... Deixe essas coisas desagradáveis no passado."
  },
  AvgDialog_18769_Content_73 = {
    Text = "Você é a Senhor do Labirinto, afinal. Nada pode realmente te machucar."
  },
  AvgDialog_18769_Content_74 = {Text = "...Mm."},
  AvgDialog_18769_Content_75 = {
    Text = "Agrippa cai em um silêncio raro. Parece que ela ainda não emergiu das sombras do passado."
  },
  AvgDialog_18769_Content_76 = {
    Text = "<LightGray:Se ao menos eu pudesse realmente mudar o passado... Assim eu poderia ajudá-la e encontrar uma saída para essa situação.>"
  },
  AvgDialog_18769_Content_77 = {
    Text = "<LightGray:Não, não desista ainda. Pense em outro caminho...>"
  },
  AvgDialog_18769_Content_78 = {
    Text = "Você procura desesperadamente em suas memórias fragmentadas por qualquer informação que possa ser útil."
  },
  AvgDialog_18769_Content_79 = {
    Text = "Sonhar não pode mudar o passado, mas pode influenciar o futuro. É por isso que durante o Sonhar, o Guardião deve aprender a exercer o Contrataque."
  },
  AvgDialog_18769_Content_8 = {
    Text = "Heh heh, todos os irmãos estão lutando pela grande causa, e só você está disposto a ficar para trás e continuar sendo um cão."
  },
  AvgDialog_18769_Content_80 = {
    Text = "Influenciar o futuro?"
  },
  AvgDialog_18769_Content_81 = {
    Text = "Simplificando, a memória de uma pessoa é como um lago tranquilo."
  },
  AvgDialog_18769_Content_82 = {
    Text = "Sonhar é como jogar uma pedra Dentro dele—as ondulações que cria logo desaparecem."
  },
  AvgDialog_18769_Content_83 = {
    Text = "Mas a pedra permanece."
  },
  AvgDialog_18769_Content_84 = {
    Text = "Exatamente. Mesmo que a pessoa que foi submetida a Sonhar não se lembre de nada após acordar..."
  },
  AvgDialog_18769_Content_85 = {
    Text = "Essa pedra afundará para sempre no seu subconsciente, influenciando o seu presente."
  },
  AvgDialog_18769_Content_86 = {
    Text = "Um som nauseante e úmido de dilaceração se ergue no ar. Enormes patas de aranha irrompem pelos corpos dos oficiais e dos transeuntes, espirrando sangue espesso com cheiro de ferro por todo você."
  },
  AvgDialog_18769_Content_87 = {
    Text = "Agrippa, eu sei como sair."
  },
  AvgDialog_18769_Content_9 = {
    Text = "Eu disse, caiam fora. Não entenderam?"
  },
  AvgDialog_18770_Content_1 = {
    Text = "O Reino Dela"
  },
  AvgDialog_18770_Content_10 = {
    Text = "É inútil, completamente inútil! Quando ficaram presos no labirinto, havia pessoas brilhantes como matemáticos também, sabia!"
  },
  AvgDialog_18770_Content_11 = {
    Text = "Se nem eles conseguiram resolver este enigma, nem tente."
  },
  AvgDialog_18770_Content_12 = {
    Text = "Se quer saber, já que nenhum de nós consegue matar o outro, é melhor nos darmos bem."
  },
  AvgDialog_18770_Content_13 = {
    Text = "Vamos conversar! Ou jogar cartas. Quais jogos de cartas você conhece?"
  },
  AvgDialog_18770_Content_14 = {
    Text = "Não deixes que o facto de eu ter ficado presa no subsolo te engane — desenvolvi umas habilidades de cartas arrasadoras. Ninguém me consegue vencer!"
  },
  AvgDialog_18770_Content_15 = {
    Text = "Tinhas de admitir, as palavras dela foram de certa forma um golpear para ti."
  },
  AvgDialog_18770_Content_16 = {
    Text = "Se ninguém conseguiu decifrar este labirinto ao longo de todos estes anos, o que te faz pensar que tu consegues?"
  },
  AvgDialog_18770_Content_17 = {
    Text = "Tu certamente não tens uma mente tão afiada como a da Ramona."
  },
  AvgDialog_18770_Content_18 = {
    Text = "Com esse pensamento, deixas-te cair de cara na almofada macia."
  },
  AvgDialog_18770_Content_19 = {
    Text = "Não sou muito bom a cartas. Vamos só conversar.\nComo é que acabaste presa neste labirinto?"
  },
  AvgDialog_18770_Content_2 = {
    Text = "39, 40, 41..."
  },
  AvgDialog_18770_Content_20 = {Text = "Hm..."},
  AvgDialog_18770_Content_21 = {
    Text = "Como se não tivesse antecipado esta pergunta, os olhos compostos que giravam incessantemente dentro das órbitas da menina congelaram todos coletivamente por um instante."
  },
  AvgDialog_18770_Content_22 = {
    Text = "Foste tu que disseste que precisamos de nos dar bem. Pois bem, ser honesto um com o outro é o primeiro passo."
  },
  AvgDialog_18770_Content_23 = {
    Text = "Está bem, eu falo, eu falo...! É só uma história cliché, de qualquer forma."
  },
  AvgDialog_18770_Content_24 = {
    Text = "Antigamente, a minha família era a mais rica de Cápua. A fila de escravos que me seguia todos os dias estendia-se até onde a vista alcançava..."
  },
  AvgDialog_18770_Content_25 = {
    Text = "Depois aqueles tolos começaram mesmo uma revolução, a falar de \"libertação\" e \"liberdade\" — coisas que eu nunca entendi, de qualquer forma."
  },
  AvgDialog_18770_Content_26 = {
    Text = "Eu não queria morrer às mãos deles, então mandei um gladiador matar-me."
  },
  AvgDialog_18770_Content_27 = {
    Text = "Disse Agrippa, estendendo as mãos na tua direção."
  },
  AvgDialog_18770_Content_28 = {
    Text = "...Quando acordei, já estava aqui."
  },
  AvgDialog_18770_Content_29 = {
    Text = "Já ouvi falar desta revolução nas aulas de História. Supostamente—"
  },
  AvgDialog_18770_Content_3 = {
    Text = "Você anotou apressadamente o Lembre-se de <Blue:Dormitório de Estudantes: 41> no caderno que o seu companheiro mais velho carregava."
  },
  AvgDialog_18770_Content_30 = {
    Text = "Não quero ouvir. Este tema é tão aborrecido! Próximo tema, próximo tema."
  },
  AvgDialog_18770_Content_31 = {
    Text = "Uma hora depois..."
  },
  AvgDialog_18770_Content_32 = {
    Text = "A conversa insípida continuou, até que Agrippa finalmente redirecionou o tema de volta para si mesma."
  },
  AvgDialog_18770_Content_33 = {
    Text = "Sabias que, ainda há mil descendentes sob o meu comando agora..."
  },
  AvgDialog_18770_Content_34 = {
    Text = "Eles podem entrar e sair livremente pelo labirinto, recolhendo histórias do que acontece lá fora para mim, e até trazer de volta pobres almas adequadas para se tornarem novos descendentes."
  },
  AvgDialog_18770_Content_35 = {
    Text = "Se não fossem eles, eu já teria morrido de tédio há muito tempo."
  },
  AvgDialog_18770_Content_36 = {
    Text = "Enquanto escuta as queixas intermináveis dela, por alguma razão, uma imagem surge na sua mente—"
  },
  AvgDialog_18770_Content_37 = {
    Text = "Um rei idoso apoiado numa bengala, Enredado num trono pesado e em Podridão."
  },
  AvgDialog_18770_Content_38 = {
    Text = "O seu domínio estende-se sem fim, o seu poder inquestionável."
  },
  AvgDialog_18770_Content_39 = {
    Text = "Ele enviou muitos emissários, pedindo-lhes que trouxessem histórias vindas de longe: gemas verdes de olho de gato, elefantes perdidos e arco-íris após a chuva..."
  },
  AvgDialog_18770_Content_4 = {
    Text = "Pare de perder tempo com isso e venha Disparar um jogo comigo!"
  },
  AvgDialog_18770_Content_40 = {
    Text = "Quando os contos chegavam às partes mais emocionantes, os emissários agitavam os braços com entusiasmo. Mas o rei permanecia sempre em silêncio, como uma estátua coberta de musgo."
  },
  AvgDialog_18770_Content_41 = {
    Text = "Nada podia fazer, pois há muito que era incapaz de se afastar do seu trono sequer meio passo."
  },
  AvgDialog_18770_Content_42 = {
    Text = "Agrippa, já ouviste tantas histórias do mundo exterior... Há algum lugar aonde gostarias de ir?"
  },
  AvgDialog_18770_Content_43 = {
    Text = "Um lugar aonde gostaria de ir..."
  },
  AvgDialog_18770_Content_44 = {
    Text = "<Blue:Vale Cámbrico>, suponho."
  },
  AvgDialog_18770_Content_45 = {
    Text = "Agrippa respondeu quase sem hesitar."
  },
  AvgDialog_18770_Content_46 = {
    Text = "Os meus descendentes disseram-me que o centro deste labirinto parece estar Abaixo de um vale chamado Cámbrico."
  },
  AvgDialog_18770_Content_47 = {
    Text = "Ouvi dizer que é um lugar bonito, com lagos como um espelho."
  },
  AvgDialog_18770_Content_48 = {
    Text = "Todas as primaveras, flores chamadas Freesia florescem por todo o lado..."
  },
  AvgDialog_18770_Content_49 = {
    Text = "Agrippa apoiou o queixo na mão, olhando pensativamente para a distância."
  },
  AvgDialog_18770_Content_5 = {Text = "..."},
  AvgDialog_18770_Content_50 = {
    Text = "Há um lago bonito na minha terra natal também, mas nunca o vi."
  },
  AvgDialog_18770_Content_51 = {
    Text = "Porque não vais vê-lo?"
  },
  AvgDialog_18770_Content_52 = {
    Text = "Agrippa lançou-te um olhar altivo, erguendo o seu pequeno queixo pontiagudo."
  },
  AvgDialog_18770_Content_53 = {
    Text = "Eu sou uma dama romana de Porta nobre. Uma dama não pode simplesmente vaguear por aí como lhe apetece."
  },
  AvgDialog_18770_Content_54 = {
    Text = "Então podes comandar muitos escravos, mas tu própria não és inteiramente livre."
  },
  AvgDialog_18770_Content_55 = {
    Text = "A realidade dela exposta pela sua simples observação, o rosto da menina desmoronou instantaneamente, como uma berinjela queimada pela geada."
  },
  AvgDialog_18770_Content_56 = {
    Text = "Naquela época, eu estava ainda pior do que aqueles escravos. Quanto mais agora..."
  },
  AvgDialog_18770_Content_6 = {
    Text = "Desculpe, poderia colocar um rosto diferente antes de falar comigo?"
  },
  AvgDialog_18770_Content_7 = {
    Text = "Tsc, que mesquinharia!"
  },
  AvgDialog_18770_Content_8 = {
    Text = "\"William\" revirou os olhos e então desapareceu no ar com um \"puf\"."
  },
  AvgDialog_18770_Content_9 = {
    Text = "Você mergulhou a cabeça de volta nos Lembre-ses densamente compactados à sua frente, tentando encontrar uma maneira de decifrar o labirinto."
  },
  AvgDialog_18779_Content_1 = {
    Text = "Isso, isso é o embrião?"
  },
  AvgDialog_18779_Content_10 = {
    Text = "Ela está sugando energia de Miryam?!\nDeve vir mais uma vez?"
  },
  AvgDialog_18779_Content_11 = {
    Text = "Inútil. \nEstá protegido pela \"placenta\", e o poder fornecido por Miryam ainda pode reparar a placenta mais três vezes"
  },
  AvgDialog_18779_Content_12 = {
    Text = "Para destruí-lo completamente, deve atacar o núcleo verdadeiro"
  },
  AvgDialog_18779_Content_13 = {Text = "Núcleo?"},
  AvgDialog_18779_Content_14 = {
    Text = "O coração pálido está incrustado no casulo transparente, à luz da lua, a sombra de \"Ele\" é vagamente visível"
  },
  AvgDialog_18779_Content_15 = {
    Text = "É a própria \"falsificação\"?"
  },
  AvgDialog_18779_Content_16 = {Text = "Sim e não"},
  AvgDialog_18779_Content_17 = {
    Text = "É... Murphy?"
  },
  AvgDialog_18779_Content_18 = {
    Text = "Sim. Claro!"
  },
  AvgDialog_18779_Content_19 = {
    Text = "Miryam adiantou o ritual com força, mas \"Ele\" nasceu de mentiras e desejos; antes que as estrelas chegassem ao alinhamento, sua existência não seria reconhecida pela realidade"
  },
  AvgDialog_18779_Content_2 = {
    Text = "Parece ter parado"
  },
  AvgDialog_18779_Content_20 = {
    Text = "Antes do nascimento, o núcleo ainda era dela"
  },
  AvgDialog_18779_Content_3 = {
    Text = "Ainda não acabou."
  },
  AvgDialog_18779_Content_4 = {
    Text = "\"Coração\" parou de bater, mas o lamento baixo trazido pelo vento do mar é inegável"
  },
  AvgDialog_18779_Content_5 = {
    Text = "Vocês ouviram um choro?"
  },
  AvgDialog_18779_Content_6 = {
    Text = "As ondas do mar rugem, o grande casulo sobe abruptamente com o suporte de Miryam, erguendo-se acima da superfície do mar"
  },
  AvgDialog_18779_Content_7 = {
    Text = "Sim, assim mesmo"
  },
  AvgDialog_18779_Content_8 = {
    Text = "Tomar o que é seu direito, para seu nascimento, para punir os descrentes"
  },
  AvgDialog_18779_Content_9 = {
    Text = "A voz de Miryam se torna cada vez mais fraca, mas a presença dentro do casulo adormecido se torna mais concreta"
  },
  AvgDialog_18784_Content_10 = {
    Text = "Patético. Apenas perder um link de Prata te reduz a isso."
  },
  AvgDialog_18784_Content_11 = {
    Text = "O monstro do abscesso ignorou as provocações de lotan, apenas rugindo enquanto avançava em direção ao inimigo"
  },
  AvgDialog_18784_Content_12 = {
    Text = "<Change>Entregue-a... a... mim..."
  },
  AvgDialog_18784_Content_13 = {
    Text = "Basta pegar aquela garota... Basta se tornar a gêmea sagrada com ela"
  },
  AvgDialog_18784_Content_14 = {
    Text = "Ela não será abandonada, não precisará lamentar sua origem, nem se tornará uma peça manipulada"
  },
  AvgDialog_18784_Content_17 = {
    Text = "<Change>Entregue-a... para... mim!"
  },
  AvgDialog_18784_Content_18 = {
    Text = "Perdeu até a capacidade de falar?"
  },
  AvgDialog_18784_Content_19 = {
    Text = "Já que é assim, coloque suas palavras e sentimentos na espada.\nDeixe-me ouvir sua raiva!"
  },
  AvgDialog_18784_Content_2 = {
    Text = "<BigShake:Roar——>"
  },
  AvgDialog_18784_Content_3 = {
    Text = "Vocês avançaram na escuridão por um tempo, quando um monstruoso ser pegajoso emergiu debaixo da ponte, seu corpo massivo arrastava inúmeras bolas pegajosas e caiu abruptamente diante de vocês"
  },
  AvgDialog_18784_Content_4 = {
    Text = "O monstro levantou a parte superior do corpo, que mal era humano, olhando ao redor de vocês, os olhos parando em Lily, com uma expressão cada vez mais louca"
  },
  AvgDialog_18784_Content_6 = {
    Text = "Entregue ela... para mim!"
  },
  AvgDialog_18784_Content_7 = {
    Text = "Lotan se colocou na frente de vocês, encarando de forma orgulhosa os olhos da criatura"
  },
  AvgDialog_18784_Content_8 = {
    Text = "As algemas se despedaçam, o corpo incha e deforma, mas o rosto sujo sob o cabelo emaranhado ainda prova a identidade do dono do corpo"
  },
  AvgDialog_18784_Content_9 = {
    Text = "Você é... Hilota"
  },
  AvgDialog_18785_Content_1 = {
    Text = "Realidade distorcida"
  },
  AvgDialog_18785_Content_10 = {
    Text = "À luz, ela viu inúmeras feridas negras na pele lisa da \"mãe\""
  },
  AvgDialog_18785_Content_11 = {
    Text = "\"Sinto muito...\""
  },
  AvgDialog_18785_Content_12 = {
    Text = "O muco negro borbulhava, perturbando a calma do fundo"
  },
  AvgDialog_18785_Content_13 = {
    Text = "\"Mãe\" soltou um grito agudo, seus tentáculos se agitaram, inserindo algo no peito do filhote"
  },
  AvgDialog_18785_Content_14 = {
    Text = "Tentáculos frios e escorregadios se enrolam ao seu redor, a água escura não obstrui mais sua boca e nariz, mas, como o líquido amniótico, sustenta sua vida"
  },
  AvgDialog_18785_Content_15 = {
    Text = "<Change>\"Desculpe......\"\n\"Eu ainda...... não quero morrer......\""
  },
  AvgDialog_18785_Content_16 = {
    Text = "A superfície da água permaneceu calma por muito tempo, nem mesmo o vento polar conseguiu criar ondulações na água viscosa"
  },
  AvgDialog_18785_Content_17 = {
    Text = "Senhorita Miryam, a santa já...não"
  },
  AvgDialog_18785_Content_18 = {
    Text = "Ela nasceu no último momento de alinhamento do planeta, sendo uma criança \"visível\""
  },
  AvgDialog_18785_Content_19 = {
    Text = "Ninguém no mundo merece mais o reconhecimento do sangue divino do que ela"
  },
  AvgDialog_18785_Content_2 = {
    Text = "Um filhote com asas quebradas caiu em um lago negro"
  },
  AvgDialog_18785_Content_20 = {
    Text = "A mulher esquelética estava cercada, no ponto mais alto, olhando todos de cima.\nO véu obscurecia seu rosto, nem mesmo os servos próximos podiam ler seus pensamentos"
  },
  AvgDialog_18785_Content_21 = {Text = "Murphy..."},
  AvgDialog_18785_Content_3 = {
    Text = "As orações murmuradas do Grande Sacerdote eram etéreas e firmes, suas palavras fervorosas penetraram o líquido negro, transformando-se em lâminas que abriram o peito do pássaro"
  },
  AvgDialog_18785_Content_4 = {
    Text = "Líquido vermelho emerge do peito, florescendo de forma sinistra na superfície negra e calma da água—"
  },
  AvgDialog_18785_Content_5 = {
    Text = "Ela continuava a afundar, com raízes ensanguentadas, mergulhando no fundo, em um abraço suave e frio"
  },
  AvgDialog_18785_Content_6 = {Text = "..."},
  AvgDialog_18785_Content_7 = {Text = "..."},
  AvgDialog_18785_Content_8 = {
    Text = "Ela viu.\nEla olhou para cima, \"mãe\" abaixou três pares de olhos e a encarou"
  },
  AvgDialog_18785_Content_9 = {
    Text = "Era uma enorme criatura vermelha, com partes transparentes onde o sangue a manchava. \"Mãe\" emitia um fraco brilho, iluminando um pequeno espaço"
  },
  AvgDialog_18786_Content_1 = {
    Text = "Fade in de vídeo"
  },
  AvgDialog_18786_Content_2 = {
    Text = "Loop de vídeo 1"
  },
  AvgDialog_18786_Content_3 = {
    Text = "Loop de vídeo 2"
  },
  AvgDialog_18786_Content_4 = {
    Text = "Desvanecimento do Vídeo"
  },
  AvgDialog_18786_Content_5 = {Text = "Nada"},
  AvgDialog_18787_Content_1 = {
    Text = "Mas agora há coisas mais urgentes"
  },
  AvgDialog_18787_Content_10 = {
    Text = "Essa é a garota que Herbert está rastreando, ela pode ter pistas para sua investigação"
  },
  AvgDialog_18787_Content_11 = {
    Text = "Vamos, o que estão esperando? \nQuerem passar a noite ao ar livre com os lobos?"
  },
  AvgDialog_18787_Content_12 = {
    Text = "Quer enfrentar as intempéries? Estou pronto, mas duvido que essa garota frágil aguente"
  },
  AvgDialog_18787_Content_13 = {
    Text = "Lotan deu um tapinha no ombro de Ramona, que fez uma expressão como se tivesse comido uma mosca, mas não disse nada"
  },
  AvgDialog_18787_Content_14 = {
    Text = "Senhora Daphodala...... soa como uma pessoa rica e bondosa, certo?"
  },
  AvgDialog_18787_Content_2 = {Text = "?"},
  AvgDialog_18787_Content_3 = {
    Text = "Se você não planeja usar a neve como cobertor, deveria pensar onde vamos dormir à noite, Guardião"
  },
  AvgDialog_18787_Content_4 = {
    Text = "<Italic:Grande irmão, grande irmã, vocês vieram de muito longe?>"
  },
  AvgDialog_18787_Content_5 = {
    Text = "Uma voz jovem interrompeu sua conversa"
  },
  AvgDialog_18787_Content_6 = {
    Text = "Quem está aí?"
  },
  AvgDialog_18787_Content_7 = {
    Text = "A neve na parede reflete a luz da lua, e no centro está uma garota mais branca que a luz da lua"
  },
  AvgDialog_18787_Content_8 = {
    Text = "Se você não consegue encontrar um lugar para ficar, você pode temporariamente ficar no quarto da <Blue:Dama dos narcisos>.\nFica logo na esquina."
  },
  AvgDialog_18787_Content_9 = {
    Text = "Você fez um sinal para Ramona, que respondeu com um olhar afirmativo"
  },
  AvgDialog_18790_Content_1 = {
    Text = "Vocês romperam até a proa do navio, mas antes de olhar para o mar, um impacto de baixo para cima inclinou o navio ainda mais"
  },
  AvgDialog_18790_Content_2 = {
    Text = "O cargueiro sobe e desce com as ondas, algo emerge da água——"
  },
  AvgDialog_18790_Content_3 = {Text = "Murphy!"},
  AvgDialog_18790_Content_4 = {
    Text = "A cabeça da cobra estava firmemente segurando o corpo da jovem, Miryam só podia rezar com uma voz rouca e indistinta"
  },
  AvgDialog_18790_Content_5 = {
    Text = "Ph'nglui mglw'nafh @3..."
  },
  AvgDialog_18790_Content_6 = {
    Text = "Ela ergueu Murphy sob a luz da lua, e pequenas mãos negras saíram do peito da garota, se contorcendo e tecendo, envolvendo o corpo da garota em um grande casulo negro"
  },
  AvgDialog_18790_Content_7 = {
    Text = "Em um rosnado surdo, a mão e os fios negros consideram Miryam como suporte, envolvendo o casulo firmemente ao longo do corpo imenso da serpente"
  },
  AvgDialog_18790_Content_8 = {
    Text = "A casca do casulo ficou transparente devido à expansão, inúmeras mãos entrelaçadas formam um trono, erguendo um coração pálido"
  },
  AvgDialog_18790_Content_9 = {
    Text = "Ph'nglui mglw'nafh @1'@2 wgah'nagl fhtagn!"
  },
  AvgDialog_18792_Content_1 = {
    Text = "Ela é Apenas uma criança da favela, ela não sabe de nada. Ela não vai representar nenhuma ameaça para o senhor..."
  },
  AvgDialog_18792_Content_10 = {
    Text = "Que irritante, minha mão está cansada. Vai morrer aqui hoje, 24?"
  },
  AvgDialog_18792_Content_11 = {
    Text = "Perder um escravo obediente como você me faz chorar~"
  },
  AvgDialog_18792_Content_12 = {
    Text = "Desculpe... Não vou sair daqui"
  },
  AvgDialog_18792_Content_14 = {Text = "Pah—!"},
  AvgDialog_18792_Content_15 = {
    Text = "Em pouco tempo, o corpo inteiro de 24 está coberto de sangue. Ainda assim, ela não se move um centímetro, repetindo as mesmas palavras repetidamente."
  },
  AvgDialog_18792_Content_16 = {
    Text = "<Shake:D–Deixe ela ir... Por favor...>"
  },
  AvgDialog_18792_Content_17 = {
    Text = "<Shake:Deixe-a ir...>"
  },
  AvgDialog_18792_Content_18 = {
    Text = "Se tem coragem, venha para cima de mim, bando de inúteis! Não"
  },
  AvgDialog_18792_Content_19 = {
    Text = "<Bold:Não bata na minha irmã...>"
  },
  AvgDialog_18792_Content_2 = {Text = "Pah—!"},
  AvgDialog_18792_Content_20 = {
    Text = "Srta. 24! Pare... Ugh"
  },
  AvgDialog_18792_Content_21 = {
    Text = "<Small:Não consigo me mover. Preciso pegar a Chave de Prata...>"
  },
  AvgDialog_18792_Content_22 = {
    Text = "Tão desajeitado, tão desajeitado! Então não me culpe por ser cruel, ok~"
  },
  AvgDialog_18792_Content_23 = {
    Text = "Leigh, chegou a sua vez de brilhar"
  },
  AvgDialog_18792_Content_3 = {
    Text = "O chicote caiu impiedosamente, deixando uma marca vermelha no rosto de 24"
  },
  AvgDialog_18792_Content_4 = {Text = "Hngh—!"},
  AvgDialog_18792_Content_5 = {
    Text = "24 se colocou na frente de Jenkins, com as omoplatas tremendo como asas de borboleta"
  },
  AvgDialog_18792_Content_6 = {
    Text = "Ela forçou um sorriso, mas parecia pior do que chorar"
  },
  AvgDialog_18792_Content_7 = {
    Text = "Meu senhor, por favor, tenha misericórdia... Deixe-a ir, e eu farei qualquer coisa..."
  },
  AvgDialog_18792_Content_8 = {Text = "Pah—!"},
  AvgDialog_18792_Content_9 = {
    Text = "Incontáveis chicotadas caem como gotas de chuva."
  },
  AvgDialog_18795_Content_1 = {
    Text = "A ponta da espada perfura a energia em forma de escamas de cobra, atingindo o ponto vital da serpente"
  },
  AvgDialog_18795_Content_10 = {
    Text = "Rei... Meu Senhor... Murphy... Murphy..."
  },
  AvgDialog_18795_Content_12 = {
    Text = "Agora... ainda há uma chance.\nVolte para a Ordem, você ainda será a \"Mãe Divina\""
  },
  AvgDialog_18795_Content_13 = {
    Text = "Seu funeral será a cerimônia mais grandiosa na história do Reino de Deus, admirada por dezenas de milhares... Seu nome também será inscrito nos anais da história, passado de geração em geração."
  },
  AvgDialog_18795_Content_14 = {
    Text = "Volte para mim, vamos... executar este <Blue:herege> juntos"
  },
  AvgDialog_18795_Content_15 = {
    Text = "Execução... essa pessoa imunda disfarçada como nosso mestre!"
  },
  AvgDialog_18795_Content_16 = {
    Text = "A grande serpente se dissipa e se condensa, sob o impacto do poder de Miryam, o espaço se distorce e se transforma gradualmente"
  },
  AvgDialog_18795_Content_17 = {
    Text = "Miryam! Eu comando que você pare!"
  },
  AvgDialog_18795_Content_18 = {
    Text = "Falsos deuses, impostores, irreverentes... sem @1@2... proibido usar a aparência de @3@4!"
  },
  AvgDialog_18795_Content_19 = {
    Text = "Em um momento, a projeção que cobre a sala de energia se solidificou.\nUma estrutura distorcida e indescritível ergue-se do chão"
  },
  AvgDialog_18795_Content_2 = {
    Text = "Ei, ei! Alguém vai cair!"
  },
  AvgDialog_18795_Content_20 = {
    Text = "<Change>Pessoa desrespeitosa... pessoa desrespeitosa...... desrespeito desrespeito desrespeito▼▼▼▼▼▼▼▼!"
  },
  AvgDialog_18795_Content_21 = {
    Text = "Ela soltou ruídos estridentes incoerentes, enquanto Miryam segurava seu próprio pescoço com as duas mãos, e seu corpo começou a se deformar e esticar"
  },
  AvgDialog_18795_Content_22 = {
    Text = "Cuidado! Ela está perdendo o controle!"
  },
  AvgDialog_18795_Content_3 = {
    Text = "Você também estava caindo no rugido da grande serpente"
  },
  AvgDialog_18795_Content_4 = {
    Text = "——Então caiu em um abraço quente e trêmulo"
  },
  AvgDialog_18795_Content_5 = {
    Text = "......%player%."
  },
  AvgDialog_18795_Content_6 = {
    Text = "Estou no paraíso?"
  },
  AvgDialog_18795_Content_7 = {
    Text = "Desculpe, ainda estamos no Sonaniel. E a crise está próxima"
  },
  AvgDialog_18795_Content_8 = {
    Text = "<Small:Imperdoável...>"
  },
  AvgDialog_18795_Content_9 = {
    Text = "Cuidado! Miryam está agindo de forma estranha!"
  },
  AvgDialog_18796_Content_1 = {
    Text = "Cof, cof, olá a todos! Hoje vamos testar os efeitos de transição do Z1~"
  },
  AvgDialog_18796_Content_10 = {
    Text = "Adequado para mudar rapidamente para cenas mais sombrias."
  },
  AvgDialog_18796_Content_11 = {
    Text = "Ufa... Estou exausto, não preciso nem dizer, né? Depois do 4 vem o 5, claro!"
  },
  AvgDialog_18796_Content_12 = {
    Text = "Hum...em resumo, a transição número 5 é a mais usada, adequada para muitas situações"
  },
  AvgDialog_18796_Content_13 = {
    Text = "Certo, agora o último intervalo—Vamos lá, número 6!"
  },
  AvgDialog_18796_Content_14 = {
    Text = "Esta é a transição mais longa de todas~"
  },
  AvgDialog_18796_Content_15 = {
    Text = "Esses são todos os efeitos de transição. Todos entenderam?"
  },
  AvgDialog_18796_Content_16 = {
    Text = "Até a próxima vez♡"
  },
  AvgDialog_18796_Content_2 = {
    Text = "Agora, a transição número 1 - transição lateral~!!"
  },
  AvgDialog_18796_Content_3 = {
    Text = "Tcham tcham tcham! Que tal, não é esplêndido?"
  },
  AvgDialog_18796_Content_4 = {
    Text = "Essa transição é geralmente usada para alternar entre cenas no mesmo local"
  },
  AvgDialog_18796_Content_5 = {
    Text = "A seguir, transição número 2—"
  },
  AvgDialog_18796_Content_6 = {
    Text = "Essa transição é geralmente usada para mudar para uma cena mais clara"
  },
  AvgDialog_18796_Content_7 = {
    Text = "Então é... transição 3!"
  },
  AvgDialog_18796_Content_8 = {
    Text = "A 3ª transição também serve para mudar para cenas brilhantes, mas o ritmo é um pouco mais lento, hehe"
  },
  AvgDialog_18796_Content_9 = {
    Text = "O próximo a se aproximar é—Transição 4!"
  },
  AvgDialog_18797_Content_1 = {
    Text = "Mi...@1...uh"
  },
  AvgDialog_18797_Content_10 = {
    Text = "Você não é o \"Rei Deus\"!"
  },
  AvgDialog_18797_Content_11 = {
    Text = "Em suma, você, como o servo de miryam, o dito Deus ressuscitado, é o que traz a profecia, não é?"
  },
  AvgDialog_18797_Content_12 = {Text = "Você..."},
  AvgDialog_18797_Content_13 = {
    Text = "Eu acabei de ver... através da ligação, vi suas memórias"
  },
  AvgDialog_18797_Content_14 = {Text = "...Sim."},
  AvgDialog_18797_Content_15 = {
    Text = "Foi a profecia que eu desci, mas o chamado \"oráculo\" não existe"
  },
  AvgDialog_18797_Content_16 = {Text = "O que?"},
  AvgDialog_18797_Content_17 = {
    Text = "Muito antes da chegada daquela enchente, eu já havia perdido a capacidade de vislumbrar o futuro pelos sonhos de Deus.\nEu não sei onde Ele está, Ele pode ter despertado, ou talvez tenha partido"
  },
  AvgDialog_18797_Content_18 = {
    Text = "E sua profecia"
  },
  AvgDialog_18797_Content_19 = {
    Text = "Miryam é uma fiel devota, nascida para o Reino Divino e movida pela Minha vontade."
  },
  AvgDialog_18797_Content_2 = {
    Text = "Murphy gemeu de dor, murmurando palavras desconexas"
  },
  AvgDialog_18797_Content_20 = {
    Text = "Eu apenas esperei que minhas palavras a confortassem em seus momentos finais, nunca esperando que ela as tomasse como evangelho e buscasse reconstruir o Reino Divino."
  },
  AvgDialog_18797_Content_21 = {Text = "Tudo isso"},
  AvgDialog_18797_Content_22 = {
    Text = "Sim, tudo isso é minha culpa"
  },
  AvgDialog_18797_Content_23 = {
    Text = "Contagem regressiva 60 minutos"
  },
  AvgDialog_18797_Content_3 = {
    Text = "! O que é isso?!"
  },
  AvgDialog_18797_Content_4 = {
    Text = "Marcas horríveis de cor azul-preta aparecem no rosto de Murphy, como raízes de plantas profundamente enraizadas em sua pele"
  },
  AvgDialog_18797_Content_5 = {
    Text = "Ele começou a bloquear o fluxo sanguíneo do hospedeiro"
  },
  AvgDialog_18797_Content_6 = {
    Text = "Não disseram que ficar longe dos corpos celestes seria suficiente?"
  },
  AvgDialog_18797_Content_7 = {
    Text = "Quero dizer que ela talvez não se sinta tão mal"
  },
  AvgDialog_18797_Content_8 = {
    Text = "O corpo celeste entrou em órbita, sem volta"
  },
  AvgDialog_18797_Content_9 = {
    Text = "Não há mesmo solução?"
  },
  AvgDialog_18798_Content_1 = {
    Text = "Ufa... Ufa... Não vi nada em cima, nem embaixo"
  },
  AvgDialog_18798_Content_10 = {
    Text = "Murphy desabou instantaneamente, escorregando pela amurada até o convés, sem se importar com a postura"
  },
  AvgDialog_18798_Content_11 = {
    Text = "Ela procurou um apoio para não cair e, após tatear, encostou-se em seu ombro"
  },
  AvgDialog_18798_Content_12 = {
    Text = "Apenas um momento..."
  },
  AvgDialog_18798_Content_13 = {
    Text = "Após alguns segundos, uma respiração rápida e ritmada soou em seus ouvidos.\nMurphy perdeu a consciência novamente"
  },
  AvgDialog_18798_Content_14 = {
    Text = "Ela está ficando mais fraca..."
  },
  AvgDialog_18798_Content_15 = {
    Text = "O deus que conecto vem de entre as estrelas, mesmo uma imitação não pode ser resistida por humanos"
  },
  AvgDialog_18798_Content_16 = {
    Text = "Não há alívio?"
  },
  AvgDialog_18798_Content_17 = {
    Text = "......leve-a embora"
  },
  AvgDialog_18798_Content_18 = {
    Text = "Manter-se longe dos corpos celestes pode fazê-la se sentir melhor"
  },
  AvgDialog_18798_Content_2 = {
    Text = "Eles... onde estão?"
  },
  AvgDialog_18798_Content_3 = {
    Text = "<Small:Que chato... este navio é tão grande...>"
  },
  AvgDialog_18798_Content_4 = {
    Text = "Você está bem?"
  },
  AvgDialog_18798_Content_5 = {
    Text = "Estou perfeitamente bem! Tosse, tosse..."
  },
  AvgDialog_18798_Content_6 = {
    Text = "Murphy respondeu em voz alta, mas se engasgou e começou a tossir violentamente"
  },
  AvgDialog_18798_Content_7 = {
    Text = "Mas estou muito cansado, e minha cabeça dói um pouco"
  },
  AvgDialog_18798_Content_8 = {
    Text = "Enquanto falava, você já estava sentado"
  },
  AvgDialog_18798_Content_9 = {
    Text = "E... vamos descansar um pouco... só um pouco"
  },
  AvgDialog_18802_Content_1 = {
    Text = "Se eu fosse mais forte, se eu pudesse resistir a ele...\nMas não consigo, não consigo"
  },
  AvgDialog_18802_Content_10 = {
    Text = "Desculpa... desculpa... foi tudo minha culpa"
  },
  AvgDialog_18802_Content_11 = {
    Text = "Sou um monstro inútil, matei tantas pessoas e não consegui salvar a irmã de Jenkins"
  },
  AvgDialog_18802_Content_12 = {
    Text = [[
Ela foi levada, ela foi levada, mas eu nem sei para onde...
Eu nem sei quem nos controla]]
  },
  AvgDialog_18802_Content_13 = {
    Text = "Ramona ajoelhou-se diante de Aigis e abraçou a garota gentilmente"
  },
  AvgDialog_18802_Content_14 = {
    Text = "Você já se esforçou muito, Aigis. Não foi sua culpa"
  },
  AvgDialog_18802_Content_15 = {
    Text = "Isso é culpa do verdadeiro Estripador, aquele que controla vocês e comete esses crimes.\nNunca foi sua culpa"
  },
  AvgDialog_18802_Content_16 = {
    Text = "A menina se jogou nos braços de Ramona e começou a chorar alto, mas sua mão direita nunca deixou de cobrir os olhos"
  },
  AvgDialog_18802_Content_17 = {
    Text = "Nós vamos encontrar aquela pessoa."
  },
  AvgDialog_18802_Content_18 = {
    Text = "Vamos encontrá-lo e fazê-lo pagar.\nEu juro"
  },
  AvgDialog_18802_Content_19 = {
    Text = "Obrigado, obrigado a todos... Obrigado a todos"
  },
  AvgDialog_18802_Content_2 = {
    Text = "Da última vez que resisti a ele, eu... eu... não consegui, buááá"
  },
  AvgDialog_18802_Content_20 = {
    Text = "A luz dourada do pôr do sol atravessou o grande mostrador transparente do campanário, caindo sobre a menina"
  },
  AvgDialog_18802_Content_21 = {
    Text = "Aigis virou-se, colocou uma mão no vidro, e apertou os olhos para receber o calor do sol"
  },
  AvgDialog_18802_Content_22 = {
    Text = "Hoje, o sol está visível"
  },
  AvgDialog_18802_Content_24 = {
    Text = "Como animada pelo raro dia ensolarado, ela se levantou e cambaleou até um vidro mais limpo"
  },
  AvgDialog_18802_Content_25 = {
    Text = "A visão turva finalmente clareia. Ela observa as ruas, algumas familiares, outras estranhas, e ouve um sussurro"
  },
  AvgDialog_18802_Content_26 = {
    Text = "Veja, aquela voz disse que esta noite veremos um céu estrelado"
  },
  AvgDialog_18802_Content_28 = {
    Text = "Menina abaixa a cabeça, sorrindo nostalgicamente"
  },
  AvgDialog_18802_Content_29 = {
    Text = "Antigamente, nos dias em que podíamos ver o sol, Tiyug me levava à noite às escondidas"
  },
  AvgDialog_18802_Content_3 = {
    Text = "Chega, não me force a fazer isso de novo"
  },
  AvgDialog_18802_Content_30 = {
    Text = "A Srta. Sarah nunca nos deixou vir aqui, disse que é perigoso e podemos nos machucar. Mas Tiyug não se importa"
  },
  AvgDialog_18802_Content_31 = {
    Text = "Ele tem uma visão excelente, vê claramente no escuro"
  },
  AvgDialog_18802_Content_32 = {
    Text = "Ele é como Jenkin, esperto e corajoso, sempre conhece caminhos e mecanismos secretos"
  },
  AvgDialog_18802_Content_33 = {
    Text = "Basta ele estar conosco, a Srta. Sarah não nos descobrirá"
  },
  AvgDialog_18802_Content_34 = {
    Text = "Contanto que ele esteja conosco, esse lugar será sempre nossa base secreta"
  },
  AvgDialog_18802_Content_35 = {
    Text = "Ele me disse que eu preciso me conectar mais com as estrelas para fortalecer minha magia.\nEmbora não possamos ver nenhuma estrela aqui"
  },
  AvgDialog_18802_Content_36 = {
    Text = "Naquela época, ele era o único que acreditava em mim.\nAcreditava que eu podia ver aquelas coisas negras, dizendo que era um talento de bruxa"
  },
  AvgDialog_18802_Content_37 = {
    Text = "Depois, os médicos começaram a levar os pacientes para fora, não mais atendendo na casa de caridade. Eu não consegui coletar evidências, e não pude vingar Teiog"
  },
  AvgDialog_18802_Content_38 = {
    Text = "Se eu fosse tão inteligente quanto ele, tão corajoso quanto Jenkins, já teria descoberto a verdade"
  },
  AvgDialog_18802_Content_39 = {
    Text = "Mas eu não sou uma bruxa"
  },
  AvgDialog_18802_Content_4 = {
    Text = "Não quero machucar ninguém, não quero matar"
  },
  AvgDialog_18802_Content_40 = {
    Text = "Só sou um covarde"
  },
  AvgDialog_18802_Content_41 = {Text = "Um monstro"},
  AvgDialog_18802_Content_42 = {
    Text = "Um... assassino."
  },
  AvgDialog_18802_Content_43 = {
    Text = "Vocês sabem quantas vezes fui manipulado?\nVocês sabem quantas vezes minhas mãos se mancharam de sangue?"
  },
  AvgDialog_18802_Content_44 = {
    Text = "Estou apavorado, com medo do que estou me tornando"
  },
  AvgDialog_18802_Content_46 = {
    Text = "Meus olhos e corpo doíam antes, mas agora não sinto nada, como se eu também fosse feito de pedra"
  },
  AvgDialog_18802_Content_48 = {
    Text = "Maldito, onde todos foram"
  },
  AvgDialog_18802_Content_49 = {
    Text = "Aquilo é..."
  },
  AvgDialog_18802_Content_5 = {
    Text = "<Shake:<AvgNormalFont:Não! Não!\nNão deixe o Mike fazer isso, ele é tão pequeno, como ele pode...<Shake:Por favor...>>>"
  },
  AvgDialog_18802_Content_50 = {
    Text = "Aigis?! Aigis—!"
  },
  AvgDialog_18802_Content_51 = {
    Text = "De repente, a voz de Jenkins veio debaixo do campanário, ela apareceu no pátio sem que ninguém percebesse"
  },
  AvgDialog_18802_Content_52 = {
    Text = "Ela gritou ansiosamente o nome de Aigis, abrindo os braços para o céu"
  },
  AvgDialog_18802_Content_53 = {
    Text = "Corpo pequeno da menina desaparece na queda, para sempre da noite"
  },
  AvgDialog_18802_Content_54 = {
    Text = "Um pássaro voa pelo céu noturno, desaparecendo na névoa espessa sem deixar traços."
  },
  AvgDialog_18802_Content_55 = {
    Text = "Jenkins estendeu os braços, apenas para segurar confusamente a saia vazia de Aigis, e um a um, as folhas quadradas caíam como flocos de neve"
  },
  AvgDialog_18802_Content_56 = {
    Text = [[
Ai... Aigis...? 
Como... como pode]]
  },
  AvgDialog_18802_Content_57 = {
    Text = "Um desenho de borboleta dourada no papel, bordas alisadas com cuidado, caindo com cheiro doce"
  },
  AvgDialog_18802_Content_58 = {
    Text = "Ugh... Aigis"
  },
  AvgDialog_18802_Content_59 = {
    Text = "Uma fita ensanguentada cai junto com o papel de bala na mão da garota, acariciando seus dedos como um toque gentil"
  },
  AvgDialog_18802_Content_6 = {
    Text = "Não ouço, não ouço, não ouço ouço ouço—"
  },
  AvgDialog_18802_Content_60 = {
    Text = "A menina piscou, e as lágrimas que embaçavam sua visão caíram silenciosamente no vermelho brilhante"
  },
  AvgDialog_18802_Content_61 = {
    Text = "Esta cor e textura familiares... só falta uma fivela prateada para coincidir perfeitamente com a memória dela"
  },
  AvgDialog_18802_Content_62 = {
    Text = "...Irmã...?"
  },
  AvgDialog_18802_Content_7 = {
    Text = "Con-segui?\nCorra, rápido, mas por favor, não conte a ninguém"
  },
  AvgDialog_18802_Content_8 = {
    Text = "<Shake:<AvgNormalFont:Espere, não, o que é isso! Minha cabeça, minha cabeça...\nAh... Ahhh...!<Shake:Ah——!!>>>"
  },
  AvgDialog_18802_Content_9 = {
    Text = "Desculpa... desculpa"
  },
  AvgDialog_18804_Content_1 = {
    Text = "Um guardião digno, roubado por algumas crianças comuns. Um ano de treinamento desperdiçado. Até os calouros da escola pública são mais espertos que você"
  },
  AvgDialog_18804_Content_2 = {
    Text = "Ainda bem que o ladrão estava no local da missão, caso contrário, você estaria com azar. Não permitirei que você desperdice tempo de missão com assuntos pessoais"
  },
  AvgDialog_18804_Content_3 = {
    Text = "A situação não é tão ruim, Boneca, dê um pouco de confiança ao %player%"
  },
  AvgDialog_18804_Content_4 = {
    Text = "Por favor, não interfira na investigação do Guardião do Segredo"
  },
  AvgDialog_18805_Content_1 = {
    Text = "Um guardião digno, roubado por algumas crianças comuns. Um ano de treinamento desperdiçado. Até os calouros da escola pública são mais espertos que você"
  },
  AvgDialog_18805_Content_2 = {
    Text = "Ainda bem que o ladrão estava no local da missão, caso contrário, você estaria com azar. Não permitirei que você desperdice tempo de missão com assuntos pessoais"
  },
  AvgDialog_18805_Content_3 = {
    Text = "A situação não é tão ruim, Boneca, dê um pouco de confiança ao %player%"
  },
  AvgDialog_18805_Content_4 = {
    Text = "Por favor, não interfira na investigação do Guardião do Segredo"
  },
  AvgDialog_18808_Content_1 = {
    Text = "Este é o teste de diálogo sem contexto 1"
  },
  AvgDialog_18808_Content_2 = {
    Text = "Este é o teste de diálogo sem contexto 2"
  },
  AvgDialog_18809_Content_1 = {
    Text = "Murphy não hesitou, puxou Ramona para o lado e começou a tirar a roupa.\nCom o último botão desabotoado, Ramona viu o \"deus\" dentro da garota"
  },
  AvgDialog_18809_Content_2 = {
    Text = "Há uma pele transparente no peito, puxando a pele e os músculos ao redor, fazendo com que toda a cavidade torácica pareça cinza e decadente"
  },
  AvgDialog_18809_Content_3 = {
    Text = "Essa visão revela os órgãos no peito, Ramona vê um jovem coração vermelho e um \"ovo\" branco"
  },
  AvgDialog_18809_Content_4 = {
    Text = "Infinitos filamentos emergem do \"óvulo\", entrelaçando-se densamente com as veias de Murphy, dependendo mutuamente"
  },
  AvgDialog_18809_Content_5 = {
    Text = "Se não fosse por sua presença esmagadora no coração de Murphy, pareceria uma parte natural do tórax transparente, não um objeto estranho"
  },
  AvgDialog_18809_Content_6 = {
    Text = "Ele é caótico e silencioso, o triângulo invertido negro que o marca também está congelado, como uma estranha obra de arte"
  },
  AvgDialog_18809_Content_7 = {
    Text = "Corrosão de Fusão... Isso já foi corroído"
  },
  AvgDialog_18809_Content_8 = {
    Text = "Já viu o suficiente?"
  },
  AvgDialog_18809_Content_9 = {
    Text = "Desculpe, fui indelicado, vista-se rápido"
  },
  AvgDialog_18810_Content_1 = {
    Text = "Contagem regressiva 20 minutos"
  },
  AvgDialog_18810_Content_10 = {
    Text = "Cuidado! Não caia no mar!"
  },
  AvgDialog_18810_Content_11 = {
    Text = "Uma enorme serpente emergiu do mar, quase virando o navio.\nVárias cabeças de serpente se contorciam, lançando sombras horríveis no convés"
  },
  AvgDialog_18810_Content_12 = {
    Text = "Usurpador... Insolente... Tolo!"
  },
  AvgDialog_18810_Content_13 = {
    Text = "Mãe divina... Mãe divina...@3!"
  },
  AvgDialog_18810_Content_14 = {
    Text = "Oh não, é Miryam!"
  },
  AvgDialog_18810_Content_15 = {
    Text = "Leve Murphy para fora!"
  },
  AvgDialog_18810_Content_16 = {Text = "Ah!!"},
  AvgDialog_18810_Content_17 = {
    Text = "Você olha de volta para o convés; Murphy não está mais lá. A cabeça de uma cobra gigante agarrou a garota e a arrastou para Aequor."
  },
  AvgDialog_18810_Content_2 = {
    Text = "Link? É no sentido de fazê-la depender de você para viver no futuro?"
  },
  AvgDialog_18810_Content_3 = {
    Text = "Apenas uma medida temporária, não temos a intenção de levar a Senhorita Celeste de suas mãos"
  },
  AvgDialog_18810_Content_4 = {
    Text = "Isso não é algo que eu possa decidir"
  },
  AvgDialog_18810_Content_5 = {
    Text = "Celeste, você está disposta?"
  },
  AvgDialog_18810_Content_6 = {
    Text = "Como se um gatilho tivesse sido acionado, Celeste levantou a cabeça, mas olhou para o mar atrás dela, e a navegação parou"
  },
  AvgDialog_18810_Content_7 = {
    Text = "O navio não se move"
  },
  AvgDialog_18810_Content_8 = {
    Text = "Algo me pegou"
  },
  AvgDialog_18810_Content_9 = {
    Text = "Antes de terminar de falar, o chão começou a tremer violentamente, e o navio inclinou-se em um ângulo impossível"
  },
  AvgDialog_18812_Content_1 = {
    Text = "Até vocês são assim... um bando de adultos egoístas"
  },
  AvgDialog_18812_Content_10 = {
    Text = "A luz ofuscante fere seus olhos, causando lágrimas incontroláveis."
  },
  AvgDialog_18812_Content_11 = {Text = "Isso, é!?"},
  AvgDialog_18812_Content_12 = {
    Text = "Conforme o líquido turvo se esvai, seus olhos finalmente voltam a focar na garota."
  },
  AvgDialog_18812_Content_13 = {
    Text = "Com uma lâmina cravada fundo em seu peito, a garota banhada pelo luar abre os olhos."
  },
  AvgDialog_18812_Content_14 = {
    Text = "A lua cheia, símbolo da morte, paira próxima, mas nenhum traço de medo se mostra em seu rosto jovem."
  },
  AvgDialog_18812_Content_15 = {
    Text = "Eu... perfurei... Não nascerá..."
  },
  AvgDialog_18812_Content_16 = {
    Text = "Agora, eu posso..."
  },
  AvgDialog_18812_Content_17 = {
    Text = "A mão dela segurando a faca cai fracamente, enquanto um líquido espesso, viscoso e carmesim escuro escorre pela lâmina, pingando entre seus dedos até o mar."
  },
  AvgDialog_18812_Content_18 = {
    Text = "O sangue escorria rapidamente do corpo, deixando-o pálido, mas emanando uma estranha vitalidade"
  },
  AvgDialog_18812_Content_19 = {
    Text = "Não... não, não, não, ahhh—"
  },
  AvgDialog_18812_Content_2 = {
    Text = "Ninguém nunca pediu minha opinião... Hmph"
  },
  AvgDialog_18812_Content_20 = {
    Text = "Deus todo-poderoso, perdoe-me, perdoe esta criança, perdoe seus devotos"
  },
  AvgDialog_18812_Content_21 = {
    Text = "O momento do alinhamento está chegando, está chegando"
  },
  AvgDialog_18812_Content_22 = {
    Text = "\"Placenta\" se rompe, \"Coração\" colapsa - inúmeras mãos emergem, esmagando o tórax da garota"
  },
  AvgDialog_18812_Content_23 = {
    Text = "A mão deformada apertou os restos irreconhecíveis, sobrepondo, expandindo, sobrepondo, expandindo—"
  },
  AvgDialog_18812_Content_24 = {
    Text = "Ah... Você me ouviu... Você respondeu a mim..."
  },
  AvgDialog_18812_Content_25 = {
    Text = "Eles empurraram uma existência deformada para a luz da lua"
  },
  AvgDialog_18812_Content_26 = {
    Text = "Meu grande Deus...!"
  },
  AvgDialog_18812_Content_3 = {
    Text = "Uma vida comprada com sacrifício... quem quer isso?"
  },
  AvgDialog_18812_Content_4 = {
    Text = "Não, a placenta está muito turva.\nConsegue ver dentro com \"Rastreamento Mental\"?"
  },
  AvgDialog_18812_Content_5 = {
    Text = "Você aperta a chave de prata vibrante e mergulha novamente no espaço da consciência"
  },
  AvgDialog_18812_Content_6 = {
    Text = "No espaço coberto pela dissolução, aquele ponto que simboliza vida e inteligência se torna especialmente brilhante"
  },
  AvgDialog_18812_Content_7 = {
    Text = "——Era uma faca ritual refletindo a fria luz da lua"
  },
  AvgDialog_18812_Content_8 = {
    Text = "——Ugh!!"
  },
  AvgDialog_18812_Content_9 = {
    Text = "A luz explode de repente, expulsando você do mundo espiritual"
  },
  AvgDialog_18813_Content_1 = {
    Text = "A seguir, teste de efeito de transição Tempo Lento"
  },
  AvgDialog_18813_Content_10 = {
    Text = "Tempestade de areia 2"
  },
  AvgDialog_18813_Content_11 = {
    Text = "Fim do teste"
  },
  AvgDialog_18813_Content_12 = {
    Text = "A seguir, teste de efeito de tela Tremor Contínuo"
  },
  AvgDialog_18813_Content_13 = {
    Text = "Início do teste"
  },
  AvgDialog_18813_Content_16 = {
    Text = "Fim do teste"
  },
  AvgDialog_18813_Content_17 = {
    Text = "Agora vamos testar o vídeo de efeito de[tela] com a ativação da s-energia"
  },
  AvgDialog_18813_Content_18 = {
    Text = "Início do teste"
  },
  AvgDialog_18813_Content_19 = {
    Text = "Fim do teste, mas vou começar diretamente o efeito especial da Chave de Prata na tela Teste"
  },
  AvgDialog_18813_Content_2 = {
    Text = "Início do teste"
  },
  AvgDialog_18813_Content_20 = {
    Text = "Início do teste"
  },
  AvgDialog_18813_Content_21 = {
    Text = "Em andamento"
  },
  AvgDialog_18813_Content_22 = {
    Text = "Fim do teste"
  },
  AvgDialog_18813_Content_23 = {
    Text = "A seguir, teste de efeito FadeDarkRole"
  },
  AvgDialog_18813_Content_26 = {Text = "Fim"},
  AvgDialog_18813_Content_3 = {
    Text = "Fim do teste"
  },
  AvgDialog_18813_Content_4 = {
    Text = "A seguir, teste de transição de fundo Tempo Rápido"
  },
  AvgDialog_18813_Content_5 = {
    Text = "Início do teste"
  },
  AvgDialog_18813_Content_6 = {
    Text = "Fim do teste"
  },
  AvgDialog_18813_Content_7 = {
    Text = "A seguir, teste de efeito de tela Tempestade de Areia"
  },
  AvgDialog_18813_Content_8 = {
    Text = "Início do teste"
  },
  AvgDialog_18813_Content_9 = {
    Text = "Tempestade de areia 1"
  },
  AvgDialog_18814_Content_1 = {
    Text = "Ufa. Desculpe, não há tempo para você se adaptar a tudo isso adequadamente."
  },
  AvgDialog_18814_Content_10 = {
    Text = "Ramona parece aterrorizada; você nunca a viu tão perturbada."
  },
  AvgDialog_18814_Content_11 = {
    Text = "A garota, bombardeada com perguntas, fala com a voz trêmula, sua exaustão evidente."
  },
  AvgDialog_18814_Content_12 = {
    Text = "Obviamente. Achou que eu vim aqui para um passeio tranquilo?"
  },
  AvgDialog_18814_Content_13 = {
    Text = "Ela fecha os olhos, recompondo-se rapidamente."
  },
  AvgDialog_18814_Content_14 = {
    Text = "Deveria ter previsto, os atacantes conhecem bem Missaga, o Cofre não escapará.\nAqui é perto da porta dos fundos, saiam rápido"
  },
  AvgDialog_18814_Content_15 = {
    Text = "Podemos ir! %player% pode nos conectar todos e depois comandar—"
  },
  AvgDialog_18814_Content_16 = {
    Text = "Ramona.\nEsses são nossos deveres, %player% é apenas um novato que ainda não nasceu"
  },
  AvgDialog_18814_Content_17 = {
    Text = "Mas %player% pode, eu sei que {Male=ele,Female=ela} pode"
  },
  AvgDialog_18814_Content_18 = {
    Text = "Doll examina você atentamente, depois se vira para Ramona com uma expressão severa."
  },
  AvgDialog_18814_Content_19 = {
    Text = "Se não me falha a memória, a cerimônia de juramento foi interrompida. {Male=He,Female=She} ainda não recebeu a Chave de prata de {Male=his,Female=her}, correto?"
  },
  AvgDialog_18814_Content_2 = {
    Text = "Esses Mutantes chegaram à Keygrave antes do alarme soar. A <Blue:Barreira de Névoa> ao redor de Misaq deve ter caído."
  },
  AvgDialog_18814_Content_20 = {
    Text = "Invadir a zona proibida de Misaga sem autorização é um incidente de que nível, achei que você, crescendo aqui, soubesse"
  },
  AvgDialog_18814_Content_21 = {
    Text = "A situação é urgente, e %player% não é um calouro comum, {Male=ele,Female=ela} é nosso único Guardião do Segredo"
  },
  AvgDialog_18814_Content_22 = {
    Text = "Você deve se lembrar do <Yellow:grande explosão de Akut> um ano atrás. Se não fosse {Male=ele,Female=ela} ligando todos os despertadores com suas próprias forças, eu não estaria aqui discutindo com você"
  },
  AvgDialog_18814_Content_23 = {
    Text = "A garota de cabelo rosa não responde e, em vez disso, se vira para você."
  },
  AvgDialog_18814_Content_24 = {
    Text = "Eu sei que você vislumbrou o que existe além da <Yellow:Porta>; mas a realidade, seja a fundação de Misaq ou o destino do mundo, pode não ser como você idealiza."
  },
  AvgDialog_18814_Content_25 = {
    Text = "Estamos enfrentando um fenômeno que destrói a existência material, uma vez contaminado por <Yellow:corrosão>, tudo seu desaparecerá, até as memórias sobre você"
  },
  AvgDialog_18814_Content_26 = {
    Text = "O nome que você gravou na lápide durante a cerimônia de juramento se transformará em lama negra, esquecida por todos"
  },
  AvgDialog_18814_Content_27 = {
    Text = "Responda-me. Você está realmente pronta para isso?"
  },
  AvgDialog_18814_Content_28 = {
    Text = "O olhar gélido de Doll encontra o seu, sua voz inexpressiva."
  },
  AvgDialog_18814_Content_29 = {
    Text = "Seu rosto não revela nada, mas no fundo de suas pupilas gélidas, você vislumbra um fogo ardente."
  },
  AvgDialog_18814_Content_3 = {
    Text = "Informamos <Blue:William, o companheiro mais velho> sobre a cerimônia de hoje, mas nenhum reforço veio em nosso auxílio. O sino... devemos nos reagrupar e <Yellow:eliminar a fonte da anomalia>!"
  },
  AvgDialog_18814_Content_30 = {
    Text = "Sua resposta é—"
  },
  AvgDialog_18814_Content_31 = {
    Text = "Minha lápide agora faz parte da Keygrave."
  },
  AvgDialog_18814_Content_32 = {
    Text = "Você é membro da Misaq. Talvez já fosse desde Akutê."
  },
  AvgDialog_18814_Content_33 = {
    Text = "Há coisas que só eu posso realizar."
  },
  AvgDialog_18814_Content_34 = {
    Text = "A decisão pode ser precipitada, mas alguém pode realmente estar preparado para tudo na vida?"
  },
  AvgDialog_18814_Content_35 = {Text = "Bom."},
  AvgDialog_18814_Content_36 = {
    Text = "Pela autoridade do 6º Diretor da Misaq, <Blue:Oliver Elsie>, eu confiro a você a Chave de prata K-0617."
  },
  AvgDialog_18814_Content_38 = {
    Text = "Doll retira a Chave de prata de um estojo ornamentado, colocando-a sobre seu peito. Ela brilha suavemente, inundando você com uma vaga sensação de familiaridade."
  },
  AvgDialog_18814_Content_39 = {
    Text = "De agora em diante, você se ergue como Guardião entre a miríade de estudantes e acadêmicos da Misaq."
  },
  AvgDialog_18814_Content_4 = {Text = "?!"},
  AvgDialog_18814_Content_40 = {Text = "..."},
  AvgDialog_18814_Content_41 = {
    Text = "Agora, estabeleça um vínculo comigo."
  },
  AvgDialog_18814_Content_5 = {
    Text = "Na periferia da sua visão, um jovem loiro ergue um enorme escudo negro, mal conseguindo se defender do ataque de uma espadachim que empunha duas lâminas."
  },
  AvgDialog_18814_Content_6 = {
    Text = "Ele protege uma garota de cabelo rosa atrás de si, cada ataque deflectido o empurrando mais um passo para trás."
  },
  AvgDialog_18814_Content_7 = {
    Text = "Você reconhece a jovem de cabelo rosa; ela é a professora Doll, conhecida por sua dificuldade em se comunicar, pertencente ao <Blue: Instituto de Pesquisa da Ressonância>. Em outras palavras, ela não é uma combatente"
  },
  AvgDialog_18814_Content_8 = {
    Text = "Espere... quem está atacando... é um Despertado?"
  },
  AvgDialog_18814_Content_9 = {
    Text = "Doll? A <Blue:Torre do Relógio> foi comprometida?!"
  },
  AvgDialog_18815_Content_1 = {
    Text = "Contagem regressiva 80 minutos"
  },
  AvgDialog_18815_Content_10 = {
    Text = "Murphy deu dois passos à frente, de repente balançou o corpo e caiu suavemente ao longo do mastro"
  },
  AvgDialog_18815_Content_11 = {Text = "Murphy?!"},
  AvgDialog_18815_Content_12 = {
    Text = "Você levantou Murphy, que estava desmaiada no convés, com a testa molhada de suor frio e o cabelo grudado na testa"
  },
  AvgDialog_18815_Content_13 = {
    Text = "Dor... muita dor"
  },
  AvgDialog_18815_Content_14 = {
    Text = "Hum...@1...@1"
  },
  AvgDialog_18815_Content_15 = {
    Text = "Ela agarrou sua mão de apoio, a dor fez seus dedos se apertarem instintivamente, afundando na carne, mas você não se importou com a dor"
  },
  AvgDialog_18815_Content_16 = {
    Text = "Você ouviu o som crescente dos tambores——músculos não humanos batendo no peito da garota"
  },
  AvgDialog_18815_Content_17 = {
    Text = "O embrião... Está drenando sua força vital."
  },
  AvgDialog_18815_Content_18 = {Text = "Mi...@2"},
  AvgDialog_18815_Content_19 = {
    Text = "Além de gemer, Murphy só consegue balbuciar palavras sem sentido"
  },
  AvgDialog_18815_Content_2 = {
    Text = "A névoa densa repousa sobre o mar, o convés é iluminado pela luz da lua, onde as expressões de todos são extremamente claras"
  },
  AvgDialog_18815_Content_20 = {
    Text = "No caos, o inimigo emerge das sombras"
  },
  AvgDialog_18815_Content_3 = {Text = "A lua..."},
  AvgDialog_18815_Content_4 = {
    Text = "O que aconteceu com a lua?"
  },
  AvgDialog_18815_Content_5 = {
    Text = "Está ficando mais brilhante"
  },
  AvgDialog_18815_Content_6 = {
    Text = "Murphy engoliu a segunda metade da frase, mas você sabia o que ela queria dizer"
  },
  AvgDialog_18815_Content_7 = {
    Text = "O tempo dela também está se esgotando"
  },
  AvgDialog_18815_Content_8 = {
    Text = "......Aproveite o tempo para se reunir com os outros, o capitão pode ter uma maneira rápida de atracar"
  },
  AvgDialog_18815_Content_9 = {Text = "Hmm..."},
  AvgDialog_18818_Content_1 = {Text = "Entendi!"},
  AvgDialog_18818_Content_10 = {
    Text = "A besta de aparência estranha abaixa a cabeça obedientemente, como se esperasse o carinho da garota branca"
  },
  AvgDialog_18818_Content_11 = {
    Text = "A cabeça humana coroada que emerge do pescoço do corpo do cão gigante torna a cena extremamente bizarra"
  },
  AvgDialog_18818_Content_12 = {Text = "Lily..."},
  AvgDialog_18818_Content_13 = {
    Text = "A garota branca caminhou lentamente em direção à besta grotesca, estendendo seu braço fino para acariciar sua cabeça como se fosse um animal de estimação"
  },
  AvgDialog_18818_Content_14 = {
    Text = "A cabeça humana coroada que emerge do pescoço do corpo do cão gigante torna a cena extremamente bizarra"
  },
  AvgDialog_18818_Content_15 = {Text = "..."},
  AvgDialog_18818_Content_16 = {
    Text = "Você e Ramona se entreolharam, com muitas palavras não ditas"
  },
  AvgDialog_18818_Content_17 = {
    Text = "Ei, vocês não estão apenas assistindo, estão? O cão infernal está bem diante de vocês"
  },
  AvgDialog_18818_Content_18 = {
    Text = "O culpado que investigamos está perto, como dizem? \"Achado sem esforço\"?"
  },
  AvgDialog_18818_Content_19 = {
    Text = "Menina parece não ouvir, sussurra no ouvido de Kum, brisa noturna leva a voz suave"
  },
  AvgDialog_18818_Content_2 = {
    Text = "Ramona salta para frente, o monstro encurralado ruge ferozmente, tentando resistir até a morte"
  },
  AvgDialog_18818_Content_20 = {
    Text = "Kum, seja obediente e siga as ordens do mestre.\nQuem obedece é um bom menino"
  },
  AvgDialog_18818_Content_21 = {
    Text = "Assim que terminou de falar, Lily girou e veio em sua direção"
  },
  AvgDialog_18818_Content_22 = {
    Text = "A Dama dos narcisos disse que se Kumm for descoberto, Lily precisa voltar para a sua mãe"
  },
  AvgDialog_18818_Content_23 = {
    Text = "Agora, vamos voltar para a loja.\nA Senhora Narciso lhe contará tudo."
  },
  AvgDialog_18818_Content_3 = {
    Text = "<Italic:Não, não, Kum, volte!>"
  },
  AvgDialog_18818_Content_4 = {
    Text = "Essa voz... parece familiar?"
  },
  AvgDialog_18818_Content_5 = {
    Text = "Das sombras escuras, surgiu uma figura pequena e encolhida"
  },
  AvgDialog_18818_Content_6 = {
    Text = "Kum, não machuque o irmão mais velho ou a irmã mais velha"
  },
  AvgDialog_18818_Content_7 = {
