  AvgDialog_18823_Content_1 = {
    Text = "Ei, acorde!"
  },
  AvgDialog_18823_Content_10 = {
    Text = "Tempo de memórias acabou! Agora vem a parte principal—"
  },
  AvgDialog_18823_Content_11 = {
    Text = "Filtre o simulador de limos que imitam o fluxo de dissolução!"
  },
  AvgDialog_18823_Content_12 = {
    Text = "É um filtro mais longo, recomendo usar com várias falas"
  },
  AvgDialog_18823_Content_13 = {Text = "..."},
  AvgDialog_18823_Content_14 = {Text = "..."},
  AvgDialog_18823_Content_15 = {
    Text = "Certo, tempo esgotado! Agora vamos ao nosso módulo de clima—"
  },
  AvgDialog_18823_Content_16 = {
    Text = "Está nevando!"
  },
  AvgDialog_18823_Content_17 = {
    Text = "Achoo! Achoo! Eu não me vesti suficientemente quente hoje..."
  },
  AvgDialog_18823_Content_18 = {
