  AvgDialog_18824_Content_31 = {
    Text = "Você e Ramona entraram na floresta fora do portão da escola e viram Jenkins e um aluno uniformizado brigando no chão"
  },
  AvgDialog_18824_Content_32 = {Text = "..."},
  AvgDialog_18824_Content_33 = {Text = "..."},
  AvgDialog_18824_Content_34 = {
    Text = "Rato morde doninha"
  },
  AvgDialog_18824_Content_35 = {
    Text = "Maravilha do mundo, ratos atacam furões e os mordem!"
  },
  AvgDialog_18824_Content_36 = {
    Text = "Quem você está chamando de rato?!"
  },
  AvgDialog_18824_Content_37 = {
    Text = "Quem você está chamando de furão?!"
  },
  AvgDialog_18824_Content_38 = {
    Text = "Hannah? Jenkin? O que você está..."
  },
  AvgDialog_18824_Content_39 = {
    Text = "Não me culpe, foi ela quem chamou os guardas primeiro!"
  },
  AvgDialog_18824_Content_4 = {
    Text = "......Desbloqueie, agora, a senhorita Diana assumiu a liderança do ateliê, e o pequeno Mike também voltou"
  },
  AvgDialog_18824_Content_40 = {
    Text = "Ah, só fiz uma pequena brincadeira com ela.\nLevar a vida muito a sério é chato"
  },
  AvgDialog_18824_Content_41 = {
    Text = "Então a pessoa que ela veio procurar eram vocês? Onde vocês se conheceram, no ateliê de Lilyan? Desmembrador? Ah! Ela é aquele pequeno Jenkin, não é?"
  },
  AvgDialog_18824_Content_42 = {
    Text = "Não é à toa que você é a primeira doninha do Reino de Leo. Está coletando material para o jornal da escola?"
  },
  AvgDialog_18824_Content_43 = {
    Text = "É mais que isso. Ramona, você me conhece—informação é minha vida."
  },
  AvgDialog_18824_Content_44 = {
    Text = "Então, em plena luz do dia, uma pobre órfã se aventura na floresta, mas por quê? E as duas pessoas que ela procura, podem trazer alguma luz?"
  },
  AvgDialog_18824_Content_45 = {
    Text = "Hannah falou enquanto tirava um caderno de algum lugar, olhando para vocês com expectativa, pronta para anotar cada palavra"
  },
  AvgDialog_18824_Content_46 = {
    Text = "A repórter de linha de frente Hannah Peasley, prestes a fazer uma cobertura!"
  },
  AvgDialog_18824_Content_47 = {
    Text = "......Agora entendi, nesta universidade maluca, ninguém fala de forma compreensível"
  },
  AvgDialog_18824_Content_48 = {
    Text = "Sou inocente, de verdade"
  },
  AvgDialog_18824_Content_49 = {
    Text = "Desde que ela não esteja aqui.\nE você, Jenkins, aconteceu algo?"
  },
  AvgDialog_18824_Content_5 = {
    Text = "A Universidade de Mythag iniciou uma doação para a oficina, com bons resultados, e juntamente com o financiamento do Lorde Dexter, pode operar por um tempo"
  },
  AvgDialog_18824_Content_50 = {
    Text = "Jenkins tirou um maço de jornais amassados da bolsa e os entregou a você e Ramona"
  },
  AvgDialog_18824_Content_51 = {
    Text = "Tivemos um acordo: você prometeu me ajudar a encontrar minha irmã. Agora, é hora de você cumprir sua promessa."
  },
  AvgDialog_18824_Content_52 = {
    Text = "Ela abriu o jornal e apontou para uma curiosidade local intitulada \"Pintura Tridimensional\""
  },
  AvgDialog_18824_Content_53 = {
    Text = "O autor escreveu em estilo de narrativa documental que ele viu uma exibição surpreendente no museu de cera localizado na 44ª rua de Nanhua: a nova obra \"Primavera\" do artista de cera Rogers"
  },
  AvgDialog_18824_Content_54 = {
    Text = "Para aumentar a credibilidade, uma foto foi cuidadosamente anexada ao lado"
  },
  AvgDialog_18824_Content_55 = {
    Text = "É um grupo de estátuas de cera inspirado na famosa pintura \"Primavera\" de Botticelli, com uma figura feminina no centro, pintada de forma cômica e com expressão dolorosa"
  },
  AvgDialog_18824_Content_56 = {
    Text = "Quero proteger todos, proteger a Srta. Sarah, proteger o pequeno Mike, proteger Jenkins.\nNão quero que eles se tornem <Yellow:estátuas de cera>"
  },
  AvgDialog_18824_Content_57 = {
    Text = "Não sei o endereço, mas andei por muito tempo até chegar ao distrito oeste, onde havia uma casa com uma vitrine exibindo pessoas. Na placa estava escrito <Yellow:nº 44>"
  },
  AvgDialog_18824_Content_58 = {
    Text = "Rogers... uma estátua de cera? E na Rua Southwark, nº <Yellow:44>, isso não parece coincidência"
  },
  AvgDialog_18824_Content_59 = {
    Text = "O que é isso, vocês sabem de algo?"
  },
  AvgDialog_18824_Content_6 = {
    Text = "Então, pode ficar tranquilo"
  },
  AvgDialog_18824_Content_60 = {
    Text = "Aigis mencionou—"
  },
  AvgDialog_18824_Content_61 = {Text = "Cof cof!"},
  AvgDialog_18824_Content_62 = {
    Text = "Você piscou para Ramona, mas já era tarde demais.\nAo ouvir o nome de Aigis, Jenkins visivelmente se desanimou"
  },
  AvgDialog_18824_Content_63 = {
    Text = "......Não fique tão triste por causa de Aigis"
  },
  AvgDialog_18824_Content_64 = {
    Text = "Eu não estou triste. Eu só... \nPrometi a ela que seria minha irmã"
  },
  AvgDialog_18824_Content_65 = {
    Text = "Ela faltou ao compromisso, realmente sem integridade"
  },
  AvgDialog_18824_Content_66 = {
    Text = "Como está aquela mulher nojenta, ela já sabe? Sabe sobre Aigis"
  },
  AvgDialog_18824_Content_67 = {Text = "..."},
  AvgDialog_18824_Content_68 = {
    Text = "Deixa pra lá, é melhor ela não saber. Aigis não quer que ela fique triste"
  },
  AvgDialog_18824_Content_69 = {
    Text = "Então, o que vocês ouviram?\nNão fiquem enrolando, rápido! Vocês prometeram me ajudar a encontrar alguém!"
  },
  AvgDialog_18824_Content_7 = {
    Text = "A Miss Sarah."
  },
  AvgDialog_18824_Content_70 = {
    Text = "Aigis mencionou que, quando estava sob controle, foi a um lugar na área oeste com o número de porta <Yellow:44>, além de \"eles se tornaram esculturas de cera\"... será que os desaparecidos estão todos lá?"
  },
  AvgDialog_18824_Content_71 = {
    Text = "Desgraçado... Não importa quem seja, eu não vou perdoar!"
  },
  AvgDialog_18824_Content_72 = {
    Text = "Quando partimos?"
  },
  AvgDialog_18824_Content_73 = {
    Text = "Considerando que o outro lado pode ser perigoso, prefiro que você espere aqui por notícias. Mas — você deve ter outra ideia, certo?"
  },
  AvgDialog_18824_Content_74 = {
    Text = "Ela é minha irmã, eu não posso deixar de ir!\nAlém disso, vocês podem precisar de mim para passar pelos dutos de ventilação!"
  },
  AvgDialog_18824_Content_75 = {
    Text = "Essa ideia é muito específica"
  },
  AvgDialog_18824_Content_76 = {
    Text = "Parece que preciso submeter uma solicitação urgente de trabalho de campo."
  },
  AvgDialog_18824_Content_77 = {
    Text = "Estou indo falar com o professor Alistair, ele deve nos ajudar"
  },
  AvgDialog_18824_Content_78 = {
    Text = "Se você falar, não haverá problema. Mas—espero que William possa adiar o prazo de nosso relatório"
  },
  AvgDialog_18824_Content_79 = {
    Text = "Sobre isso, não precisam se preocupar"
  },
  AvgDialog_18824_Content_8 = {
    Text = "Ótimo, realmente... Ótimo.\nMuito obrigado, Ash—não, %player%, Srta. Ramona"
  },
  AvgDialog_18824_Content_80 = {Text = "?"},
  AvgDialog_18824_Content_81 = {
    Text = "Há uma hora, William saiu com a permissão de campo"
  },
  AvgDialog_18824_Content_82 = {
    Text = "Eu ia segui-lo para ver se conseguia alguma notícia, mas o perdi no caminho e voltei. Parecia que ele estava indo para o distrito oeste de Lentinion"
  },
  AvgDialog_18824_Content_83 = {
    Text = [[
A Rua Southwark fica no distrito oeste.
Desta vez, podemos testemunhar o famoso investigador William]]
  },
  AvgDialog_18824_Content_84 = {
    Text = "......Tenho a sensação de que ele vai me xingar muito"
  },
  AvgDialog_18824_Content_85 = {
    Text = [[
18:24, Distrito Oeste de Lentini
Rua Southwark]]
  },
  AvgDialog_18824_Content_86 = {
    Text = "Obrigado pela cooperação, eu cuido do resto sozinho"
  },
  AvgDialog_18824_Content_87 = {
    Text = "Isso não vai funcionar, senhor, as ordens são claras, devemos acompanhá-lo na investigação.\nAlém disso, Rogers também é nosso suspeito, não podemos deixá-lo trabalhar sozinho"
  },
  AvgDialog_18824_Content_88 = {
    Text = "E, com a gente aqui, sua identidade pode ser melhor escondida, não é?"
  },
  AvgDialog_18824_Content_89 = {Text = "..."},
  AvgDialog_18824_Content_9 = {
    Text = "Estamos apenas fazendo o nosso melhor"
  },
  AvgDialog_18824_Content_90 = {
    Text = "Relaxe, senhor. Temos armas e somos rápidos, não seremos um fardo"
  },
  AvgDialog_18824_Content_91 = {
    Text = "Certo, aumente a vigilância. Se necessário, priorize sua vida"
  },
  AvgDialog_18824_Content_92 = {
    Text = "Relatório. Chegamos ao local da missão, 44 South Harker St., Museu de Cera do Rogers. Alvo confirmado: Verifique a possível ligação entre o proprietário do museu de cera, Rogers, e os escultores"
  },
  AvgDialog_18824_Content_93 = {
    Text = "Chegada ao local da missão confirmada, objetivo de investigação confirmado.\nQue a Chave de Prata guie o caminho"
  },
  AvgDialog_18824_Content_94 = {
    Text = "Que a Chave de Prata nos guie"
  },
  AvgDialog_18825_Content_1 = {
    Text = "Ramona deu um passo em direção ao lugar onde viu a sombra"
  },
  AvgDialog_18825_Content_10 = {
    Text = "De repente, um deles agarra o pescoço do outro. Um grito curto explode como óleo quente na água, causando pânico ao redor"
  },
  AvgDialog_18825_Content_11 = {
    Text = "Espalhem-se!"
  },
  AvgDialog_18825_Content_2 = {
    Text = "Senhorita Mary, isso, isso aqui fora é o jardim, você já viu, vamos voltar ao percurso original da visita"
  },
  AvgDialog_18825_Content_3 = {
    Text = "Oh? Eu queria dar uma volta no jardim, pode entender, Srta. Sarah?"
  },
  AvgDialog_18825_Content_4 = {
    Text = "Claro, claro. Entendo perfeitamente. Mas, que tal uma xícara de chá primeiro? Srta. Mary—"
  },
  AvgDialog_18825_Content_5 = {
    Text = "Ignorando a objeção de Sarah, Ramona entrou no pátio, procurando com os olhos entre os trabalhadores ocupados"
  },
  AvgDialog_18825_Content_6 = {
    Text = "O ar está cheio de suor e um cheiro estranho, como carvão úmido queimando"
  },
  AvgDialog_18825_Content_7 = {
    Text = "Veja, Srta. Mary, eu disse que não havia nada para ver aqui. Vamos voltar"
  },
  AvgDialog_18825_Content_8 = {
    Text = [[
As Sarah spoke, several workers suddenly stopped their actions.
Their lips moved as if whispering something, swaying slightly]]
  },
  AvgDialog_18825_Content_9 = {
    Text = "No olho esquerdo sob a lente, Ramona vê suas costas se arqueando, um líquido negro escorrendo, como se tivesse vida, descendo pelos membros"
  },
  AvgDialog_18826_Content_1 = {
    Text = "No meio da multidão caótica, Ramona luta para defender os trabalhadores afetados, permitindo que os outros escapem em segurança"
  },
  AvgDialog_18826_Content_2 = {
    Text = "Cuidador! Chame o cuidador!"
  },
  AvgDialog_18826_Content_3 = {
    Text = "Passos apressados soam. Algumas pessoas em uniformes especiais vêm apressadas na contramão da multidão, segurando cordas com expressão séria"
  },
  AvgDialog_18826_Content_4 = {
    Text = "Atrás deles, uma figura vestida de branco"
  },
  AvgDialog_18826_Content_5 = {
    Text = "Senhorita Mary, cuidado!"
  },
  AvgDialog_18826_Content_6 = {
    Text = "Ramona desviou-se, aproveitando o ataque do trabalhador anômalo para avançar, pressionando a ponta da espada embainhada contra o esterno do oponente, forçando-o a recuar alguns passos"
  },
  AvgDialog_18826_Content_7 = {
    Text = "Atrás dela, os cuidadores pararam"
  },
  AvgDialog_18826_Content_8 = {
    Text = "Vou colaborar com vocês, estou pronto"
  },
  AvgDialog_18827_Content_1 = {
    Text = "Névoa Sangrenta"
  },
  AvgDialog_18827_Content_10 = {
    Text = "Olhando para o rosto confuso de Aigis, Jenkins suspirou profundamente, pegou a pesada chaleira da bandeja e a embrulhou em um pano"
  },
  AvgDialog_18827_Content_11 = {
    Text = "Jenkins, se brincar com isso, a Srta. Sarah vai ficar brava"
  },
  AvgDialog_18827_Content_12 = {
    Text = "Quem está brincando! Estou te ajudando!\nVamos, vamos, quanto mais cedo terminarmos, melhor!"
  },
  AvgDialog_18827_Content_13 = {Text = "Mm, mm!"},
  AvgDialog_18827_Content_14 = {
    Text = "20:27, Lilian na Oficina de Trabalho  \nPátio Frontal"
  },
  AvgDialog_18827_Content_15 = {
    Text = "......Vocês realmente acreditaram naquela garota e planejam esperar aqui por uma sombra negra?"
  },
  AvgDialog_18827_Content_16 = {
    Text = "Considerando as anomalias de marcas de dissolução que apareceram na oficina de trabalho, e o \"investigador\" desaparecido, ficar de olho realmente é uma boa ideia"
  },
  AvgDialog_18827_Content_17 = {
    Text = "...Certo, é seu próprio tempo que está desperdiçando.\nVoltando ao assunto, você não encontrou nenhum Clades na oficina?"
  },
  AvgDialog_18827_Content_18 = {
    Text = "A Chave Prata não mostra reação. Presumo que a forma de vida desconhecida não seja uma nova Clades, mas esteja mais ligada a D-Marks especiais e à \"Pesquisadora.\""
  },
  AvgDialog_18827_Content_19 = {
    Text = "Nunca vi uma marca de dissolução assim. Parece até uma tentativa de costura mal feita.\nE a droga que ele usou para subjugar a criatura mutante... Na verdade, eu duvido que eles consigam interferir na dissolução"
  },
  AvgDialog_18827_Content_2 = {
    Text = "20:27, oficina de trabalho Lilian\nrefeitório"
  },
  AvgDialog_18827_Content_20 = {
    Text = "Sem Clades, mas há Dissolução, D-Mark costurado... Poderia ser eles?"
  },
  AvgDialog_18827_Content_21 = {
    Text = "Leitura da palavra-chave bem-sucedida, \"D-Mark Costurado,\" com um total de 37 incidentes relacionados.\nPalavras-chave do Evento: <Blue:Atividade da Organização Maligna, Os Escultores>."
  },
  AvgDialog_18827_Content_22 = {
    Text = "Eles não foram eliminados na operação conjunta entre Mythi e <Blue:comitê> há 14 anos?"
  },
  AvgDialog_18827_Content_23 = {
    Text = "A operação falhou e os membros principais escaparam. A equipe de investigação não os encontrou por anos, e agora os encontramos aqui"
  },
  AvgDialog_18827_Content_24 = {
    Text = "A natureza da situação mudou, preparem-se para evacuar.\nLembrem-se de não agir precipitadamente, ou eu serei o primeiro a dar-lhes mais treinamento"
  },
  AvgDialog_18827_Content_25 = {
    Text = "Espere, Boneca—"
  },
  AvgDialog_18827_Content_26 = {
    Text = "O professor Dôl já foi embora, você precisa deixar uma mensagem?"
  },
  AvgDialog_18827_Content_27 = {
    Text = "Tão autoritário quanto no laboratório.\nNão precisa deixar recado, obrigado, Erica"
  },
  AvgDialog_18827_Content_28 = {
    Text = "O comunicador silenciou, você olhou para Ramona e viu a mesma emoção nos olhos dela"
  },
  AvgDialog_18827_Content_29 = {
    Text = "Isto é nossa missão."
  },
  AvgDialog_18827_Content_3 = {
    Text = "Eu não entendo, você ajuda na cozinha e leva comida para aquele Rogers.\nVocê gosta tanto de trabalhar? Nunca para"
  },
  AvgDialog_18827_Content_30 = {
    Text = "A investigação que começamos deve ser finalizada por nós."
  },
  AvgDialog_18827_Content_31 = {
    Text = "Não podemos sair."
  },
  AvgDialog_18827_Content_32 = {
    Text = "Você sabe que eu sempre apoio suas decisões, não importa quais sejam.\nEu confio em você, %player%"
  },
  AvgDialog_18827_Content_33 = {
    Text = "Se pudermos descobrir algo antes da evacuação, a boneca deve ser persuadida, não?"
  },
  AvgDialog_18827_Content_34 = {
    Text = "Deixe-a ver até onde podemos ir"
  },
  AvgDialog_18827_Content_35 = {
    Text = [[
20:35, oficina de trabalho Lilian
corredor]]
  },
  AvgDialog_18827_Content_36 = {
    Text = "Até onde você vai pelo pequeno Mike? Não dê seu jantar toda vez que ele estiver com fome!"
  },
  AvgDialog_18827_Content_37 = {
    Text = "Não me importo de comer menos, o pequeno Mike precisa comer mais para ser saudável e não adoecer"
  },
  AvgDialog_18827_Content_38 = {
    Text = "Você acha que é grande coisa? Se eu não tivesse roubado o dinheiro do %player% para comprar doces e pão para você, você não sabe quanto tempo ficaria com fome!"
  },
  AvgDialog_18827_Content_39 = {
    Text = "Mas ele é obediente, depois de comer, ele me chama de irmã com alegria, e ainda me deu um presente"
  },
  AvgDialog_18827_Content_4 = {
    Text = "Jenkins encostou-se na mesa de distribuição, observando Aigis e alguns cuidadores e cozinheiras ocupados"
  },
  AvgDialog_18827_Content_40 = {
    Text = "Bonito, não é? Um irmão mais velho que veio pedir direções deu isso a ele anteontem, todos ficaram com inveja.\nE, ah, o pequeno Mike disse—"
  },
  AvgDialog_18827_Content_41 = {
    Text = "Um para mim, um para você, seremos sempre os melhores amigos!"
  },
  AvgDialog_18827_Content_42 = {
    Text = "......tch, quem se importa. Quando encontrar minha irmã, vamos embora juntas, e você será minha irmã também, te dou duas irmãs!"
  },
  AvgDialog_18827_Content_43 = {Text = "...Aigis?"},
  AvgDialog_18827_Content_44 = {
    Text = "<Small:Névoa... como pode... hoje, de novo...>"
  },
  AvgDialog_18827_Content_45 = {
    Text = "Hmm? É verdade. Nunca houve tantos dias de neblina antes, o clima está estranho ultimamente"
  },
  AvgDialog_18827_Content_46 = {
    Text = "Ele me lembra da noite em que nos conhecemos pela primeira vez."
  },
  AvgDialog_18827_Content_47 = {
    Text = [[
20:35, oficina de trabalho Lilian
jardim da frente]]
  },
  AvgDialog_18827_Content_48 = {
    Text = "Este clima... O sobrevivente não disse que na noite do acidente também havia neblina repentina?"
  },
  AvgDialog_18827_Content_49 = {
    Text = "A fraca luz da lanterna não atravessa a névoa, tudo ao redor é indistinto, você mal consegue ver o portão de ferro próximo"
  },
  AvgDialog_18827_Content_5 = {
    Text = "Eu também gostaria de fazer outra coisa, mas... mas sou tão inútil, só sei fazer esses trabalhos pesados"
  },
  AvgDialog_18827_Content_50 = {
    Text = "Uma sombra passou rapidamente, despertando uma névoa adormecida"
  },
  AvgDialog_18827_Content_51 = {
    Text = "Isso é...!"
  },
  AvgDialog_18827_Content_52 = {
    Text = "O portão de ferro fechado fez um som estridente, você e Ramona correram, mas só viram o portão aberto e a rua coberta pela névoa noturna"
  },
  AvgDialog_18827_Content_53 = {Text = "Persiga!"},
  AvgDialog_18827_Content_6 = {
    Text = "De novo, quem disse que você é inútil?"
  },
  AvgDialog_18827_Content_7 = {
    Text = "Este garoto tem sido assim desde que chegou à oficina, não escuta o que se diz"
  },
  AvgDialog_18827_Content_8 = {
    Text = "Diana sorriu enquanto passava a bandeja com os utensílios de chá e petiscos para Aigis, e deu um tapinha na cabeça de Jenkin"
  },
  AvgDialog_18827_Content_9 = {
    Text = "Então, cabe a você fazer com que ela não se trate tão mal, pequeno Jenkins"
  },
  AvgDialog_18828_Content_1 = {
    Text = "Realmente não vamos pará-los? Se eles são de \"Os escultores\"..."
  },
  AvgDialog_18828_Content_2 = {
    Text = "Vamos ver a situação e agir conforme necessário. Se os alertarmos, será difícil pegá-los"
  },
  AvgDialog_18829_Content_1 = {
    Text = "Desça rápido!"
  },
  AvgDialog_18829_Content_10 = {
    Text = "Realmente pode? Isso é incrível!"
  },
  AvgDialog_18829_Content_11 = {
    Text = "Temos que tentar. Eu a suprimirei, siga meu comando"
  },
  AvgDialog_18829_Content_12 = {
    Text = "Preparar... vai!"
  },
  AvgDialog_18829_Content_3 = {
    Text = "A lâmina cortou o ar, movendo o fluxo de ar atrás de você. Ramona desviou e bloqueou um golpe com a espada, empurrando você em direção às escadas"
  },
  AvgDialog_18829_Content_5 = {
    Text = "Sarah, em sua loucura, entra no porão atrás de vocês, sua espada colidindo com o muco negro endurecido, fazendo um som metálico estridente"
  },
  AvgDialog_18829_Content_6 = {
    Text = "Você se vira e, junto com Ramona, recua defensivamente para o fundo da sala"
  },
  AvgDialog_18829_Content_7 = {
    Text = "Erica! Um mutante especial de Dissolução, mantendo uma forma humanoide exceto pela cabeça e possuindo inteligência. Suspeito de ser induzido por ondas de Espírito acionadas pela emoção. Solução?"
  },
  AvgDialog_18829_Content_8 = {
    Text = "Recuperando, por favor aguarde."
  },
  AvgDialog_18829_Content_9 = {
    Text = "Além de eliminar Metamorfos, a Chave de prata pode ser usada para influenciar a psique de Metamorfos e Metamorfos especiais."
  },
  AvgDialog_18830_Content_1 = {
    Text = "Srta. Sarah— Srta. Sarah, acorde, olhe para mim, Srta. Sarah—"
  },
  AvgDialog_18830_Content_2 = {
    Text = "Essa mutação deve ter sido desencadeada por emoções fortes e manteve alguma inteligência.\nNunca vi algo assim, é completamente diferente dos outros mutantes"
  },
  AvgDialog_18830_Content_3 = {
    Text = "Que Metamorfo, que coisa, que diabos!"
  },
  AvgDialog_18830_Content_4 = {
    Text = "Não deixe ela passar, seria ruim se encontrasse civis"
  },
  AvgDialog_18830_Content_5 = {
    Text = "Vá ao porão, veja se consegue acalmá-la"
  },
  AvgDialog_18830_Content_6 = {
    Text = "Senhorita Sarah! Por favor, não machuque a senhorita Sarah!"
  },
  AvgDialog_18830_Content_7 = {
    Text = "Jenkin, tire Aigis daqui!"
  },
  AvgDialog_18830_Content_8 = {
    Text = "Maldito, na hora crucial, sempre depende de mim, Aigis! Rápido!"
  },
  AvgDialog_18830_Content_9 = {
    Text = "Senhorita Sarah—!"
  },
  AvgDialog_18831_Content_1 = {
    Text = "Perigo Interno"
  },
  AvgDialog_18831_Content_10 = {
    Text = "Jenkins, não me assuste, estou com medo, volte, por favor? Ou posso ir com você? Jenkins——"
  },
  AvgDialog_18831_Content_11 = {
    Text = [[
A porta fechou-se silenciosamente, deixando a garota e o rato dentro.
Aigis sentou-se na cama, tremendo incontrolavelmente]]
  },
  AvgDialog_18831_Content_12 = {
    Text = "Por quê, já houve uma pessoa hoje, por que de novo, por quê...!"
  },
  AvgDialog_18831_Content_13 = {
    Text = "Lágrimas rolaram pelas bochechas, molhando os lençóis pela enésima vez naquela noite.\nLá fora, a névoa cobriu a lua cheia, tudo ficou escuro e indistinto"
  },
  AvgDialog_18831_Content_14 = {
    Text = "O que fazer... O que devo fazer, o que devo sacrificar... para"
  },
  AvgDialog_18831_Content_15 = {
    Text = "00:17，Lilian Atelier\nQuarto de hóspedes"
  },
  AvgDialog_18831_Content_16 = {Text = "..."},
  AvgDialog_18831_Content_17 = {
    Text = "......Que... som...?"
  },
  AvgDialog_18831_Content_18 = {
    Text = "Como eu adormeci?"
  },
  AvgDialog_18831_Content_19 = {
    Text = [[
Lembro que estava falando com Sarah, como adormeci... 
Ramona, Ramona?]]
  },
  AvgDialog_18831_Content_2 = {
    Text = "00:14，Lilian Atelier\nQuarto de Aigis"
  },
  AvgDialog_18831_Content_20 = {
    Text = "Você não ouviu resposta, apenas moveu lentamente seus membros pesados, tentando se concentrar e observar ao redor"
  },
  AvgDialog_18831_Content_21 = {
    Text = "A fechadura da porta estava solta, a porta entreaberta, e o vento frio da noite entrava pela fresta escura"
  },
  AvgDialog_18831_Content_22 = {
    Text = "Uma sombra rápida saltou de trás da mesa e cadeiras, atacando você em um instante"
  },
  AvgDialog_18831_Content_24 = {Text = "!"},
  AvgDialog_18831_Content_25 = {
    Text = "A lâmina afiada reflete um brilho frio, a lâmina curta reflete seu rosto.\nO reflexo condicionado pelo treinamento faz você desviar a tempo e ver a figura do atacante"
  },
  AvgDialog_18831_Content_26 = {Text = "Jenkin?!"},
  AvgDialog_18831_Content_27 = {
    Text = "Os olhos vazios da garota não possuíam cor; seu olhar era tão inexpressivo que quase parecia em transe, e ela não ouvia seu chamado, como se não pudesse discernir as coisas"
  },
  AvgDialog_18831_Content_28 = {
    Text = "Enquanto isso, seus movimentos eram incrivelmente ágeis. A lâmina cortou o ar em um arco gelado, sem dar-lhe tempo para pensar, a garota atacou novamente"
  },
  AvgDialog_18831_Content_29 = {
    Text = "Esquiva imediata"
  },
  AvgDialog_18831_Content_3 = {
    Text = "A luz da lua que inundava o quarto ficou turva, como se estivesse coberta por uma névoa.\nAlguém se sentou de repente na cama, perturbando a paz do quarto"
  },
  AvgDialog_18831_Content_30 = {
    Text = "Ramona, acorde!"
  },
  AvgDialog_18831_Content_31 = {
    Text = "Você recuou para o lado de Ramona e sacudiu seu ombro com força"
  },
  AvgDialog_18831_Content_32 = {
    Text = "O que...? O que aconteceu?"
  },
  AvgDialog_18831_Content_33 = {
    Text = "Sim, foi Jenkins, ela me atacou de repente!"
  },
  AvgDialog_18831_Content_34 = {
    Text = "Despertar Ramona"
  },
  AvgDialog_18831_Content_35 = {
    Text = "Maldito, desse jeito"
  },
  AvgDialog_18831_Content_36 = {
    Text = "Você fecha os olhos e se concentra, a chave de prata no seu peito brilha levemente"
  },
  AvgDialog_18831_Content_37 = {
    Text = "A relação sustentada pela ligação espiritual, mesmo a milhares de quilômetros de distância, ou entre o mundo desperto e as várias cidades dos sonhos, responderá ao convocador"
  },
  AvgDialog_18831_Content_38 = {Text = "Ramona!"},
  AvgDialog_18831_Content_4 = {
    Text = "......Jenkins?"
  },
  AvgDialog_18831_Content_40 = {
    Text = "As lâminas se chocam, Ramona bloqueia a faca. Ela vira a cabeça ligeiramente, confirmando sua segurança com o canto do olho"
  },
  AvgDialog_18831_Content_41 = {
    Text = "Você está bem?"
  },
  AvgDialog_18831_Content_42 = {
    Text = "Você acordou na hora certa"
  },
  AvgDialog_18831_Content_43 = {Text = "Jenkin?"},
  AvgDialog_18831_Content_44 = {
    Text = "Jenkins não respondeu, apenas levantou a adaga novamente"
  },
  AvgDialog_18831_Content_45 = {
    Text = "Parece que só podemos dominá-la e depois interrogá-la. Levem-na para fora!"
  },
  AvgDialog_18831_Content_5 = {
    Text = "O som de roupas sendo vestidas é a única resposta, Aigis esfrega os olhos inchados e vê Jenkins sair da cama e ir para a porta"
  },
  AvgDialog_18831_Content_6 = {
    Text = "Squeak? Squeak squeak!"
  },
  AvgDialog_18831_Content_7 = {
    Text = "Jenkins, você... vai ao banheiro?"
  },
  AvgDialog_18831_Content_8 = {
    Text = "Ignorando as perguntas dos companheiros e os guinchos nervosos dos ratos, Jenkins abriu a porta sem expressão"
  },
  AvgDialog_18831_Content_9 = {
    Text = "O rosto de Aigis ficou instantaneamente pálido"
  },
  AvgDialog_18832_Content_1 = {
    Text = "Na escuridão, uma pequena figura branca estava encolhida"
  },
  AvgDialog_18832_Content_10 = {
    Text = "Desista, feche os olhos, deixe tudo comigo. \nSarah, Mike... todos na sua oficina se tornarão beleza, se tornarão eternidade"
  },
  AvgDialog_18832_Content_100 = {
    Text = "A fita amarrada no pulso soltou-se e voou ao vento, enquanto o pequeno corpo da garota desaparecia para sempre no céu noturno"
  },
  AvgDialog_18832_Content_101 = {
    Text = "O vestido branco vazio, junto com os fragmentos de papel quadrado, deslizava suavemente nas mãos de Jenkin"
  },
  AvgDialog_18832_Content_102 = {
    Text = "Nem um resquício de calor foi deixado"
  },
  AvgDialog_18832_Content_103 = {
    Text = "Ai... Aigis...?"
  },
  AvgDialog_18832_Content_104 = {
    Text = "Uma borboleta dourada é desenhada no papel, com suas bordas franzidas cuidadosamente achatadas. Ela ainda carrega um leve toque de doçura de doce."
  },
  AvgDialog_18832_Content_105 = {
    Text = "Como... como isso pode ser..."
  },
  AvgDialog_18832_Content_106 = {
    Text = "A fita vermelha cai na mão da menina junto com o papel de bala, acariciando suavemente seus dedos, como um consolo gentil"
  },
  AvgDialog_18832_Content_107 = {
    Text = "A menina piscou, e as lágrimas que embaçavam sua visão caíram silenciosamente no vermelho brilhante"
  },
  AvgDialog_18832_Content_108 = {Text = "Aigis..."},
  AvgDialog_18832_Content_11 = {
    Text = "Não, não...! Por favor, não faça isso, não pode!"
  },
  AvgDialog_18832_Content_12 = {
    Text = "Aquele ratinho é seu amigo, não é? Em troca de você ter coletado tantos materiais para mim, posso priorizar transformá-la em eterna, livrando-a da dor"
  },
  AvgDialog_18832_Content_13 = {
    Text = "Não pode! Não os machuque! Por favor! Eu farei qualquer coisa, qualquer coisa!"
  },
  AvgDialog_18832_Content_14 = {
    Text = "Eu também implorei a ele assim, mas depois entendi seu ideal.\nVocê também vai entender o meu, afinal, o que mais você pode fazer?"
  },
  AvgDialog_18832_Content_15 = {Text = "Eu—"},
  AvgDialog_18832_Content_16 = {
    Text = "Resistir? Sua mente está quase no limite, se não fosse assim, eu não poderia influenciá-lo enquanto você está consciente"
  },
  AvgDialog_18832_Content_17 = {
    Text = "Que tal desistir? Então, você pode me ajudar a transformar todos aqui em materiais valiosos"
  },
  AvgDialog_18832_Content_18 = {
    Text = "Uma grande sombra está paralisada à distância, você rapidamente tira a chave de prata e, ignorando os avisos de Boneca e Ramona, a lança ao ar"
  },
  AvgDialog_18832_Content_19 = {
    Text = "A Chave de Prata flutuou no ar, emitindo uma luz suave. Você fechou os olhos e mergulhou na escuridão fria"
  },
  AvgDialog_18832_Content_2 = {
    Text = "O velho Charlie tinha um gato malhado que ele amava muito. Um dia, ela desapareceu, e ele a procurou por toda parte"
  },
  AvgDialog_18832_Content_20 = {
    Text = "As incontáveis luzes prateadas ao redor desaparecem, restando apenas um ponto de luz fraco flutuando à sua frente.\nVocê ouve atentamente, como se escutasse o sussurro de uma garota"
  },
  AvgDialog_18832_Content_21 = {
    Text = "Quero proteger todos, proteger a Srta. Sarah, proteger o pequeno Mike, proteger Jenkins.\nNão quero que eles se tornem estátuas de cera"
  },
  AvgDialog_18832_Content_22 = {
    Text = "Vou protegê-los, mesmo que isso me custe tudo—"
  },
  AvgDialog_18832_Content_23 = {
    Text = "Você tenta tocar o pequeno ponto, a chave de prata zumbindo como se respondesse"
  },
  AvgDialog_18832_Content_24 = {
    Text = "...O que é isso?"
  },
  AvgDialog_18832_Content_25 = {
    Text = "A menina levantou o rosto e viu uma pequena chave prateada à sua frente, girando lentamente e emitindo uma luz suave e brilhante como estrelas"
  },
  AvgDialog_18832_Content_26 = {
    Text = "Ela esforçou-se para mover o braço, apoiando-se.\nA escuridão a envolveu de todos os lados, pressionando-a, prendendo-a no lugar, incapaz de se mover"
  },
  AvgDialog_18832_Content_27 = {
    Text = "Um brinquedinho especial. Não se mexa, Aigis, ainda preciso de você. \nContinue assim e nunca verá seus amigos de novo. Está tudo bem com isso?"
  },
  AvgDialog_18832_Content_28 = {
    Text = "Eu não vou ouvir... Eu nunca mais vou ouvir."
  },
  AvgDialog_18832_Content_29 = {
    Text = [[
Mesmo que eu nunca mais possa comer doces, ver todos na oficina, ou ver o jenkin. 
Mesmo que eu morra]]
  },
  AvgDialog_18832_Content_3 = {
    Text = "A próxima frase eu sei! Ele revirou o guarda-roupa e olhou debaixo da cama"
  },
  AvgDialog_18832_Content_30 = {
    Text = "Eu definitivamente não deixarei você machucá-los novamente, de jeito nenhum"
  },
  AvgDialog_18832_Content_31 = {
    Text = "A Chave de Prata piscou intensamente, a garota se levantou de repente, ouvindo vagamente um som de algo se rasgando"
  },
  AvgDialog_18832_Content_32 = {
    Text = "A venda cai lentamente, cores ondulantes substituem a escuridão, e uma enorme íris pálida aparece abaixo dela, como se a observasse há muito tempo"
  },
  AvgDialog_18832_Content_33 = {
    Text = "Você é... um olho?"
  },
  AvgDialog_18832_Content_34 = {
    Text = "Realmente pode me emprestar sua força?\n... Não importa, mesmo que seja por um momento, eu... tenho algo a dizer a eles"
  },
  AvgDialog_18832_Content_35 = {
    Text = "Obrigado..."
  },
  AvgDialog_18832_Content_36 = {
    Text = "Aigis se mexeu, abrindo os olhos de verdade"
  },
  AvgDialog_18832_Content_37 = {
    Text = "Após um grito agudo, o corpo do monstro se dissolveu em lodo negro, desmoronando e subindo como poeira, tingindo as vigas de madeira"
  },
  AvgDialog_18832_Content_38 = {
    Text = "Você cai no chão, lutando contra a dor de cabeça e a náusea"
  },
  AvgDialog_18832_Content_39 = {Text = "%player%!"},
  AvgDialog_18832_Content_4 = {
    Text = "A pequena Aigis, veja o que fiz para você? Este tapa-olho é mais bonito que o anterior"
  },
  AvgDialog_18832_Content_40 = {
    Text = "Energia mental esgotada? Eu disse para não exagerar.\nTrabalho de campo não é como na escola, se algo acontecer, ninguém vai te ajudar"
  },
  AvgDialog_18832_Content_41 = {
    Text = "Não se preocupe comigo, vá ver a Aigis"
  },
  AvgDialog_18832_Content_42 = {
    Text = "O som de evaporação do líquido diminui até desaparecer.\nNo chão manchado de muco negro, a garota senta-se em silêncio"
  },
  AvgDialog_18832_Content_43 = {
    Text = "Senhorita Ramona... e... %player%.\nQue bom que vocês estão bem"
  },
  AvgDialog_18832_Content_44 = {
    Text = "Desculpa, de verdade. Se eu tivesse falado antes, admitido antes, talvez tudo já tivesse acabado"
  },
  AvgDialog_18832_Content_45 = {
    Text = "Eu não feri mais ninguém, certo? Eu... eu também posso ser considerada uma resistente, certo?"
  },
  AvgDialog_18832_Content_46 = {
    Text = "Sim, você é corajoso e incrível. Você protegeu todos na oficina"
  },
  AvgDialog_18832_Content_47 = {
    Text = "Então está bem... Resta apenas uma coisa.\nVou contar tudo o que sei"
  },
  AvgDialog_18832_Content_48 = {
    Text = "<Small:Preciso... aproveitar o tempo...>"
  },
  AvgDialog_18832_Content_49 = {
    Text = "Não sei desde quando, mas aquela voz misteriosa apareceu.\nEla sempre vem nas noites de nevoeiro, entra em nossas mentes e nos faz fazer coisas ruins"
  },
  AvgDialog_18832_Content_5 = {
    Text = "Aigis, Aigis! Hoje o sol está brilhando, você certamente poderá ver as estrelas!"
  },
  AvgDialog_18832_Content_50 = {
    Text = "Eu descobri pela primeira vez, uma noite, quando fui ao banheiro, a pequena Lucy estava com uma faca. Eu a vi esconder a faca no armário e depois voltar para a cama"
  },
  AvgDialog_18832_Content_51 = {
    Text = "Ela estava com medo de ser repreendida por sujar o pijama, então a ajudei a trocar de roupa e lençóis. Ela acordou e perguntou por que eu estava trocando, como se... não soubesse o que tinha feito"
  },
  AvgDialog_18832_Content_52 = {
    Text = "Estou apavorado, quero contar à Srta. Sarah, mas tenho medo de que ela puna Lucy, e mais medo ainda de que ela não acredite em mim"
  },
  AvgDialog_18832_Content_53 = {
    Text = "Então, no final, não disse nada"
  },
  AvgDialog_18832_Content_54 = {
    Text = "Depois do incidente com a pequena Lucy, nada aconteceu por várias noites. Achei que estava tudo bem, mas um dia acordei com uma faca na mão"
  },
  AvgDialog_18832_Content_55 = {
    Text = "Uma irmã caiu na minha frente. Ela chorava e implorava, eu queria parar, mas"
  },
  AvgDialog_18832_Content_56 = {
    Text = "Não consigo"
  },
  AvgDialog_18832_Content_57 = {
    Text = "Enquanto aquela voz estiver cantando, eu não posso fazer isso."
  },
  AvgDialog_18832_Content_58 = {
    Text = "A voz percebeu que eu ainda estava \"acordado\" e ficou muito feliz, disse que eu tinha talento e que deveria obedecer, senão transformaria todos em pedra, em seu \"material\""
  },
  AvgDialog_18832_Content_59 = {
    Text = "Eu disse que contaria à Srta. Sarah, mas ele riu e disse que eu poderia tentar, ver se alguém acreditaria"
  },
  AvgDialog_18832_Content_6 = {
    Text = "Aigis, às vezes é normal ser teimosa. Entendeu?"
  },
  AvgDialog_18832_Content_60 = {
    Text = "A voz está certa, em coisas ruins, ela parece sempre estar certa"
  },
  AvgDialog_18832_Content_61 = {
    Text = "Ninguém acredita em mim, ninguém se lembra do que aconteceu à noite. E toda vez que neblina aparece à noite, sempre que aquela canção ressoa em nossas cabeças, crianças são controladas pelo som e saem da oficina"
  },
  AvgDialog_18832_Content_62 = {
    Text = "Cada criança que volta está coberta de sangue, cada criança controlada é um \"desmembrador\".\nAlguns são mais jovens que eu, se realmente forem pegos pela polícia"
  },
  AvgDialog_18832_Content_63 = {
    Text = "Não posso deixar isso acontecer"
  },
  AvgDialog_18832_Content_64 = {
    Text = "Então, escondi todas as coisas ensanguentadas no quintal. Não posso resistir às vozes, mas pelo menos posso protegê-los da polícia"
  },
  AvgDialog_18832_Content_65 = {
    Text = "Por que a voz nos manda cortar os corpos dos outros, eu não sei, só sei que o que cortamos é enviado para uma casa com uma vitrine na Zona Oeste"
  },
  AvgDialog_18832_Content_66 = {
    Text = "A irmã de Jenkins... eu também a levei para lá, uma casa com a placa <Blue:44> na porta"
  },
  AvgDialog_18832_Content_67 = {
    Text = "Quando eu saí, ela ainda estava chorando. Quis confortá-la, mas só pude ser levado de volta à oficina.\nEmbora assim que eu tivesse a chance de me mover, eu saí para procurá-la, mas quando cheguei lá, ela já tinha desaparecido"
  },
  AvgDialog_18832_Content_68 = {
    Text = "Desapareceu com ela, também o irmão mais velho que eu transformei em pedra naquela noite"
  },
  AvgDialog_18832_Content_69 = {
    Text = "Não sei se eles ainda estão vivos. Se puderem encontrá-los, podem pedir desculpas por mim?"
  },
  AvgDialog_18832_Content_7 = {
    Text = "Aigis! Clang! Clang——pão! Eu sou incrível, não sou?"
  },
  AvgDialog_18832_Content_70 = {
    Text = "Se não fosse por mim, eles não teriam... e Jenkins não estaria tão triste.\nEu... realmente sinto muito por ela, por eles, por todos"
  },
  AvgDialog_18832_Content_71 = {Text = "Aigis..."},
  AvgDialog_18832_Content_73 = {
    Text = "Aigis observou a sombra projetada à sua frente, seus olhos brilhando com uma luz fraca"
  },
  AvgDialog_18832_Content_74 = {
    Text = "Queria tanto, tanto recomeçar... Se pudesse, eu certamente"
  },
  AvgDialog_18832_Content_76 = {
    Text = "A visão turva finalmente clareia. Ela observa as ruas, algumas familiares, outras estranhas, e ouve um sussurro"
  },
  AvgDialog_18832_Content_77 = {
    Text = "A menina piscou e sorriu nostalgicamente"
  },
  AvgDialog_18832_Content_78 = {
    Text = "Você sabe, antigamente, nos dias em que podíamos ver o sol, Tiyug me levava secretamente para cima à noite"
  },
  AvgDialog_18832_Content_79 = {
    Text = "A Srta. Sarah nunca nos deixou vir aqui, disse que é perigoso e podemos nos machucar"
  },
  AvgDialog_18832_Content_8 = {
    Text = "A menina se encolheu e apertou o ursinho em seus braços.\nO papel de bala dobrado dentro ainda exalava um doce aroma"
  },
  AvgDialog_18832_Content_80 = {
    Text = "Mas Tiyug não se importa. Toda noite, depois que a Srta. Sarah termina a ronda, ele me leva secretamente para cima no escuro"
  },
  AvgDialog_18832_Content_81 = {
    Text = "Ele é como Jenkin, esperto e corajoso, sempre conhece caminhos e mecanismos secretos"
  },
  AvgDialog_18832_Content_82 = {
    Text = "Basta ele estar conosco, a Srta. Sarah não nos descobrirá"
  },
  AvgDialog_18832_Content_83 = {
    Text = "Contanto que ele esteja conosco, esse lugar será sempre nossa base secreta"
  },
  AvgDialog_18832_Content_84 = {
    Text = "Ele é o único que acredita em mim. Acredita que eu posso ver aquelas coisas negras, e me disse que isso é um dom de bruxa"
  },
  AvgDialog_18832_Content_85 = {
    Text = "Ele disse que quanto mais contato com as estrelas, mais forte a magia, e que em dias ensolarados, as estrelas apareceriam à noite.\nMas olhar para as estrelas não adianta"
  },
  AvgDialog_18832_Content_86 = {
    Text = "Não sou uma bruxa"
  },
  AvgDialog_18832_Content_87 = {
    Text = "Só sou um covarde"
  },
  AvgDialog_18832_Content_88 = {Text = "Um inútil"},
  AvgDialog_18832_Content_89 = {
    Text = "Um... assassino."
  },
  AvgDialog_18832_Content_9 = {Text = "Jenkin..."},
  AvgDialog_18832_Content_90 = {
    Text = "Não consigo parar o doutor, nem a voz misteriosa. Sei que mais pessoas vão morrer, mas não posso fazer nada"
  },
  AvgDialog_18832_Content_91 = {
    Text = "Tenho medo de que todos se machuquem, de que sejam levados, mas o que mais temo... o que mais temo"
  },
  AvgDialog_18832_Content_93 = {
    Text = "O Dr. Clementine está certo, arriscar a vida certamente trará algo em troca.\nAntes eu tinha medo, agora—"
  },
  AvgDialog_18832_Content_95 = {
    Text = "Droga, eles deveriam ter esperado na sala, mas agora ninguém sabe para onde foram."
  },
  AvgDialog_18832_Content_96 = {
    Text = "Aquilo é..."
  },
  AvgDialog_18832_Content_97 = {
    Text = "Aigis?! Aigis—!"
  },
  AvgDialog_18832_Content_98 = {
    Text = "De repente, a voz de Jenkins veio debaixo do campanário, ela gritou ansiosamente o nome de Aigis, levantando os braços para o céu"
  },
  AvgDialog_18832_Content_99 = {
    Text = "Um pássaro voa pelo céu noturno, desaparecendo na névoa espessa sem deixar traços."
  },
  AvgDialog_18833_Content_1 = {
    Text = "Aigis balançou, mas não diminuiu a velocidade.\nEla segurou a cabeça e gritou de dor, correndo em frente sem olhar para trás"
  },
  AvgDialog_18833_Content_2 = {Text = "Aigis!"},
  AvgDialog_18833_Content_3 = {
    Text = "A menina atravessou rapidamente o corredor e subiu as escadas para o topo da torre, murmurando algo o tempo todo"
  },
  AvgDialog_18833_Content_4 = {
    Text = "Vocês a seguem subindo. A escada em espiral dá voltas e mais voltas, com o cheiro de madeira e poeira no ar"
  },
  AvgDialog_18833_Content_5 = {
    Text = "Eu não quero feri-los, por favor..."
  },
  AvgDialog_18833_Content_6 = {
    Text = "Não quero... Não queria fazer isso, pare de falar, pare de falar...!"
  },
  AvgDialog_18834_Content_1 = {
    Text = "Você e Ramona tentaram escapar, mas perderam o garoto de capuz. As crianças ainda bloqueavam seu caminho"
  },
  AvgDialog_18834_Content_2 = {
    Text = "Vocês... são... cúmplices!"
  },
  AvgDialog_18834_Content_3 = {Text = "E daí!"},
  AvgDialog_18834_Content_4 = {
    Text = "Se tem coragem, nos bata!"
  },
  AvgDialog_18834_Content_5 = {
    Text = "Não se pode ser tão violento com crianças. Mas—"
  },
  AvgDialog_18834_Content_6 = {
    Text = "Uma educação adequada é necessária, não acham?"
  },
  AvgDialog_18835_Content_1 = {
    Text = "Quando vocês se aproximaram da oficina, a rua de repente ficou em silêncio, apenas um vagabundo sentado sem ânimo à beira do caminho"
  },
  AvgDialog_18835_Content_2 = {
    Text = "Por que está tão quieto aqui? Algo está errado"
  },
  AvgDialog_18835_Content_3 = {
    Text = "Então vamos ser cautelosos, Corrosão—"
  },
  AvgDialog_18835_Content_4 = {
    Text = "Antes que ela terminasse de falar, o corpo do mendigo se deformou abruptamente, e o muco que jorrava de seu peito se transformou em um enorme monstro negro, rastejando em sua direção"
  },
  AvgDialog_18836_Content_1 = {
    Text = "O monstro negro se dispersa e rapidamente se reúne, levantando seu corpo e emitindo um som rouco e estridente"
  },
  AvgDialog_18836_Content_2 = {
    Text = "......Socorro...@4...Socorro"
  },
  AvgDialog_18836_Content_3 = {
    Text = "Está... está falando...?"
  },
  AvgDialog_18836_Content_4 = {
    Text = "Não faça um som!"
  },
  AvgDialog_18836_Content_5 = {
    Text = "Sha...@2...morte...morte...!"
  },
  AvgDialog_18836_Content_6 = {Text = "!"},
  AvgDialog_18837_Content_1 = {
    Text = "Vocês mal começaram a perseguir, e as crianças que estavam brincando rapidamente se reúnem na sua frente, bloqueando o caminho"
  },
  AvgDialog_18837_Content_2 = {
    Text = "Com licença, crianças, por favor"
  },
  AvgDialog_18837_Content_3 = {
    Text = "Blá blá blá—se você tem coragem, pule!"
  },
  AvgDialog_18837_Content_4 = {
    Text = "Você olha para Ramona em busca de ajuda."
  },
  AvgDialog_18837_Content_5 = {
    Text = "Certo, é melhor você acompanhar."
  },
  AvgDialog_18838_Content_1 = {
    Text = "Saia daqui, os pacientes estão loucos e atacando!"
  },
  AvgDialog_18838_Content_2 = {
    Text = "Eles não eram loucos antes - Meu Deus! Por que todos saíram?!"
  },
  AvgDialog_18838_Content_3 = {
    Text = "Você acha que estou mentindo? Corra logo!"
  },
  AvgDialog_18839_Content_1 = {
    Text = "Vendo que vocês não são fáceis de lidar, as crianças fugiram.\nVocê e Ramona pegaram uma delas"
  },
  AvgDialog_18839_Content_2 = {
    Text = "Ai, vou dizer, não posso dizer ainda! A pessoa que roubou suas coisas foi para a oficina de trabalho, vá lá e procure, vá lá e procure"
  },
  AvgDialog_18839_Content_3 = {
    Text = "... Como se sentisse um pouco exagerado. Vocês gostam de ficar perto da oficina?"
  },
  AvgDialog_18839_Content_4 = {
    Text = "Não ouso. Todos dizem que há demônios devoradores de homens lá, só um tolo iria brincar lá"
  },
  AvgDialog_18839_Content_5 = {
    Text = "Então, seu companheiro de capuz não foi para lá?"
  },
  AvgDialog_18839_Content_6 = {
    Text = "Eu, eu não menti para vocês! Eu—enfim, acreditem se quiserem!"
  },
  AvgDialog_18839_Content_7 = {
    Text = "Aquela criança saiu correndo depois de falar, você olhou para ele se afastando e suspirou"
  },
  AvgDialog_18839_Content_8 = {
    Text = "Deixa pra lá, a missão é mais importante. Vamos ao workshop de trabalho"
  },
  AvgDialog_18840_Content_1 = {
    Text = "O q...uê é isso!?"
  },
  AvgDialog_18840_Content_2 = {
    Text = "Crianças, venham rápido!"
  },
  AvgDialog_18840_Content_3 = {
    Text = "Sarah recuou apressada, segurando uma criança em cada mão. Tremendo de medo, ainda assim se colocou na frente das crianças e cobriu seus olhos"
  },
  AvgDialog_18840_Content_4 = {Text = "Afaste-se!"},
  AvgDialog_18840_Content_5 = {
    Text = "Cuidado, %player%!"
  },
  AvgDialog_18841_Content_1 = {
    Text = "Uma maçã por dia"
  },
  AvgDialog_18841_Content_10 = {
    Text = "08:16，Lilian Atelier\nRefeitório"
  },
  AvgDialog_18841_Content_11 = {
    Text = "Mas, eu não levantei à noite? Aigis, por que você continua me perguntando isso? Eu só dormi ontem à noite"
  },
  AvgDialog_18841_Content_12 = {Text = "Eu..."},
  AvgDialog_18841_Content_13 = {
    Text = "Sim. Por quê, Aigis?"
  },
  AvgDialog_18841_Content_14 = {
    Text = "Você, perguntando repetidamente, mesmo que digamos que não sabemos. Por quê?\nSabe o que fizemos ontem à noite?"
  },
  AvgDialog_18841_Content_15 = {
    Text = "Não sou, eu, como poderia—"
  },
  AvgDialog_18841_Content_16 = {
    Text = "Tu és meu amigo, Aigis. Não quero suspeitar de amigos. Me diga, o que você sabe?"
  },
  AvgDialog_18841_Content_17 = {
    Text = "......Jenkins, eu... não entendo"
  },
  AvgDialog_18841_Content_18 = {
    Text = "Queria te perguntar ontem, o que é isso?"
  },
  AvgDialog_18841_Content_19 = {Text = "!"},
  AvgDialog_18841_Content_2 = {
    Text = "Segundo dia"
  },
  AvgDialog_18841_Content_20 = {
    Text = "Eu estava pensando se você encontrou uma fita bonita em algum lugar e decidiu guardá-la"
  },
  AvgDialog_18841_Content_21 = {
    Text = "Mas, depois de ver a metade na mão de %player%, por que não disse nada?\nEsses dois claramente são da mesma coisa"
  },
  AvgDialog_18841_Content_22 = {
    Text = "As outras crianças na mesa não notaram a conversa delas, continuando a rir e brincar.\nAigis abaixou a cabeça, com os ombros tremendo levemente"
  },
  AvgDialog_18841_Content_23 = {
    Text = "Você pode me dizer onde encontrou isso? Onde está minha irmã?\nQualquer coisa menos isso—"
  },
  AvgDialog_18841_Content_24 = {
    Text = "Seja um dilema ou qualquer outra coisa, eu entendo. Mas você precisa falar, Aigis.\nOnde minha irmã desapareceu? Me diga, por favor?"
  },
  AvgDialog_18841_Content_25 = {
    Text = "Não posso... Desculpe... Não sei, realmente não sei...\nJenkins, Jenkins, eu daria tudo, por favor, não vá, não deixe de ser meu amigo"
  },
  AvgDialog_18841_Content_26 = {
    Text = "O que diabos você está falando?"
  },
  AvgDialog_18841_Content_27 = {
    Text = "Reunidos! Crianças, trabalhadores, venham para o pátio! Formem filas—"
  },
  AvgDialog_18841_Content_28 = {
    Text = "08:16，Lilian Atelier\nRefeitório"
  },
  AvgDialog_18841_Content_29 = {
    Text = "Desculpe, ontem eu queria esconder a existência dos pacientes, por isso falei que a Senhorita Mary estava errada.\n Afinal, não haveria um pesquisador assim em uma oficina normal"
  },
  AvgDialog_18841_Content_3 = {
    Text = "08:15，Lilian Atelier\nRefeitório"
  },
  AvgDialog_18841_Content_30 = {
    Text = "Falando nisso, onde está o pesquisador? Não o vi.\nEu e Ash {Male=senhor,Female=senhorita} queríamos perguntar sobre a terapia experimental"
  },
  AvgDialog_18841_Content_31 = {
    Text = "Provavelmente voltou ao laboratório, eles têm que relatar periodicamente.\nNão sei os detalhes"
  },
  AvgDialog_18841_Content_32 = {
    Text = "Então, pode me dar o endereço deles?"
  },
  AvgDialog_18841_Content_33 = {
    Text = "Hum...não sei o endereço exato. Mas hoje é o dia que o Dr. Miller vê os pacientes, talvez vocês possam perguntar diretamente a ele? Está quase na hora—ah, olhem, eles chegaram"
  },
  AvgDialog_18841_Content_34 = {
    Text = "Você olha na direção que Sarah acena: Rogers e alguns homens de terno com maletas médicas estão vindo, mas Clementine não está entre eles"
  },
  AvgDialog_18841_Content_35 = {
    Text = "Dr. Miller, e o Sr. Rogers! Eu e Ash{Male=senhor,Female=senhorita} estávamos falando de vocês"
  },
  AvgDialog_18841_Content_36 = {
    Text = "O nobre hóspede mencionou-me? Que honra.\nOlá, Ash{Male=senhor,Female=senhorita}, Srta. Mary. O Sr. Rogers estava falando sobre vocês"
  },
  AvgDialog_18841_Content_37 = {
    Text = "Prazer em conhecê-lo"
  },
  AvgDialog_18841_Content_38 = {
    Text = "Para ser sincero, tanto eu quanto {Male=senhor,Female=senhorita} estamos muito curiosos sobre a sua terapia experimental, será que poderemos observar seu tratamento mais tarde?"
  },
  AvgDialog_18841_Content_39 = {
    Text = "Isso é realmente infeliz. Recentemente, organizamos todos os tratamentos dentro do instituto, e temo que não será muito conveniente"
  },
  AvgDialog_18841_Content_4 = {
    Text = "Precisamos nos apressar, Deus sabe quando Boneca nos deixará evacuar"
  },
  AvgDialog_18841_Content_40 = {
    Text = "Talvez possamos visitar seu instituto? Se o efeito for como a Srta. Sarah e o Sr. Rogers disseram, gostaríamos de contribuir com fundos e esforços"
  },
  AvgDialog_18841_Content_41 = {
    Text = "Quanto mais aliados com interesses comuns, melhor. Mas estamos em uma fase crítica da pesquisa e não podemos receber visitantes. Vocês entendem, certo?"
  },
  AvgDialog_18841_Content_42 = {
    Text = "Ou, talvez você possa dar a eles seu cartão de visita, Dr. Miller?\nAssim fica mais fácil para vocês se comunicarem no futuro"
  },
  AvgDialog_18841_Content_43 = {
    Text = "O Sr. Rogers está certo.\nVamos marcar um horário e receber vocês bem"
  },
  AvgDialog_18841_Content_44 = {
    Text = "Dr. Miller entrega um cartão de visita a vocês, com \"Frederick Miller, Rua da Cruz 10\" impresso"
  },
  AvgDialog_18841_Content_45 = {
    Text = "Os números de rua e casa muito perfeitos fazem você duvidar se há alguma verdade neste cartão de visita"
  },
  AvgDialog_18841_Content_46 = {
    Text = "Miss Sarah, please gather everyone so we can identify who needs to be examined and treated"
  },
  AvgDialog_18841_Content_47 = {
    Text = "Sem problema.\nReúnam-se! Crianças, trabalhadores, venham para o pátio! Formem uma fila—"
  },
  AvgDialog_18841_Content_48 = {
    Text = "Você segue Sarah e o Dr. Miller até o pátio"
  },
  AvgDialog_18841_Content_5 = {
    Text = "Retirada? Que retirada?"
  },
  AvgDialog_18841_Content_6 = {
    Text = "Oh, não é nada. Bom dia, Senhorita Sarah."
  },
  AvgDialog_18841_Content_7 = {
    Text = [[
Bom dia, Ash {Male=senhor,Female=senhorita}, Srta. Mary.
Como passaram a noite?]]
  },
  AvgDialog_18841_Content_8 = {
    Text = "Graças a você, dormi muito bem.\nO chá da Srta. Sarah tem um efeito único"
  },
  AvgDialog_18841_Content_9 = {
    Text = "Sim, sim... Que bom"
  },
  AvgDialog_18842_Content_1 = {
    Text = "Você é o assassino, você me controlou, você... ugh... ah"
  },
  AvgDialog_18842_Content_2 = {
    Text = "Aigis, ouça-me. Temos uma maneira de te ajudar a escapar daquela pessoa que tenta te controlar, você não precisa ficar assim"
  },
  AvgDialog_18842_Content_3 = {
    Text = "Não se aproxime... não... ahhh...!"
  },
  AvgDialog_18843_Content_1 = {
    Text = "Atrás da Parede de Pedra"
  },
  AvgDialog_18843_Content_10 = {
    Text = "Não quero ir, não quero. Eu já fui da última vez, já fui, não quero ir de novo, não quero"
  },
  AvgDialog_18843_Content_11 = {
    Text = "Mas você não tem dito que vê coisas pretas recentemente? Perguntei ao Dr. Miller, ele disse que ver ilusões não é algo trivial, e hoje você precisa fazer novos exames"
  },
  AvgDialog_18843_Content_12 = {
    Text = "Srta. Sarah, por favor, não me mande.\nEu não vi nada, realmente não vi. Por favor"
  },
  AvgDialog_18843_Content_13 = {
    Text = "E se você ficar igual aos loucos depois? Não, tem que ir. Obedeça"
  },
  AvgDialog_18843_Content_14 = {
    Text = "Senhorita Sarah—"
  },
  AvgDialog_18843_Content_15 = {
    Text = "Esta é a criança."
  },
  AvgDialog_18843_Content_16 = {
    Text = "Não... eu não quero ir... já fui uma vez, não quero"
  },
  AvgDialog_18843_Content_17 = {
    Text = "Vou, senhor."
  },
  AvgDialog_18843_Content_18 = {Text = "!"},
  AvgDialog_18843_Content_19 = {
    Text = "... Você está se sentindo mal?"
  },
  AvgDialog_18843_Content_2 = {
    Text = "Eu realmente vi, de verdade! Aqueles pretos, triangulares. Todos que vão ao Dr. voltam com essas coisas, é assustador, muito assustador"
  },
  AvgDialog_18843_Content_20 = {
    Text = "Eu não me sinto mal; eu posso correr e pular, perfeitamente saudável!\nMas eu consigo ver coisas."
  },
  AvgDialog_18843_Content_21 = {
    Text = "Oh? O que você pode ver?"
  },
  AvgDialog_18843_Content_22 = {
    Text = "Eu e Aigis vemos as ilusões negras.\nVocê poderia me ajudar?"
  },
  AvgDialog_18843_Content_23 = {
    Text = "Interessante. Hoje é sua vez"
  },
  AvgDialog_18843_Content_24 = {Text = "Tiyog"},
  AvgDialog_18843_Content_25 = {
    Text = "Não tenha medo, Aigis."
  },
  AvgDialog_18843_Content_26 = {
    Text = "Voltarei em breve."
  },
  AvgDialog_18843_Content_27 = {
    Text = "09:00，Lilian Atelier\nQuarto de Aigis"
  },
  AvgDialog_18843_Content_28 = {
    Text = "Vocês estavam na sala de Aigis, ouvindo a garota contar sua história entrecortadamente"
  },
  AvgDialog_18843_Content_29 = {
    Text = "As pessoas que o doutor leva de volta têm buracos negros no corpo, cada vez mais.\nMas ninguém vê, todos dizem que sou mentiroso"
  },
  AvgDialog_18843_Content_3 = {
    Text = "Preto... você quer dizer que a roupa está suja? Talvez tenha esfregado em algo"
  },
  AvgDialog_18843_Content_30 = {
    Text = "Só Tiyog acredita em mim, só Tiyog. Mas ele morreu...\nEle morreu, foi minha culpa"
  },
  AvgDialog_18843_Content_31 = {
    Text = "Se eu não tivesse deixado ele fazer o exame por mim, se eu fosse mais forte, se eu pudesse fazer mais, ele não teria... não teria... Eu sou um inútil"
  },
  AvgDialog_18843_Content_32 = {
    Text = "Não fale assim de você, você não é!"
  },
  AvgDialog_18843_Content_33 = {
    Text = "Sou, sou! Não consegui salvá-lo, não consegui salvar ninguém, não consigo fazer nada!\nMamãe estava certa, sou um fardo, um lixo que ninguém quer, não consigo"
  },
  AvgDialog_18843_Content_34 = {Text = "Eu... nada"},
  AvgDialog_18843_Content_35 = {Text = "E daí!"},
  AvgDialog_18843_Content_36 = {
    Text = "A voz de Jenkins atravessou o quarto estreito, e Aigis olhou para ela, atônita"
  },
  AvgDialog_18843_Content_37 = {
    Text = "E daí se não puder salvar? E daí se for covarde? Quem disse que você tem que salvar alguém?\nIsso nunca foi sua responsabilidade!"
  },
  AvgDialog_18843_Content_38 = {
    Text = "Mas, isso é de todos"
  },
  AvgDialog_18843_Content_39 = {
    Text = "O que houve com todos, vocês realmente acham que uma criança deve salvar o mundo? Por quê?\nVocê já não fez o suficiente?"
  },
  AvgDialog_18843_Content_4 = {
    Text = "Não! Eles são escuros, úmidos, fazem suas mãos e pés desaparecerem!"
  },
  AvgDialog_18843_Content_40 = {
    Text = "Jenkins tirou uma fita amassada do bolso e a entregou a Aigis, com a mesma cor vibrante da que você tem"
  },
  AvgDialog_18843_Content_41 = {
    Text = "Você não é um mentiroso, nem um inútil, você é meu amigo.\nO que você não pode fazer sozinho, podemos fazer juntos"
  },
  AvgDialog_18843_Content_42 = {
    Text = "Eu acredito em você, você acredita em mim, certo?"
  },
  AvgDialog_18843_Content_43 = {
    Text = "Aigis ficou olhando para a fita em suas mãos, as lágrimas caindo uma a uma.\nEla balançou a cabeça com força, uma expressão de dor apareceu novamente em seu rosto"
  },
  AvgDialog_18843_Content_44 = {Text = "Aigis—"},
  AvgDialog_18843_Content_45 = {
    Text = "Jenkins, deixe pra lá, Aigis deve ter suas próprias preocupações"
  },
  AvgDialog_18843_Content_46 = {
    Text = "Agora, parece que a sala de tratamento é uma boa direção para investigar.\nAigis, pode ser forte e nos levar até lá?"
  },
  AvgDialog_18843_Content_47 = {
    Text = "Só até a porta, se você não se sentir bem, não precisa entrar"
  },
  AvgDialog_18843_Content_48 = {
    Text = "Entendi, eu... eu vou levar vocês"
  },
  AvgDialog_18843_Content_49 = {
    Text = "09:11，Lilian Atelier\nConsultório temporário"
  },
  AvgDialog_18843_Content_5 = {
    Text = "Irmã Diana, não vá, por favor, não vá para a inspeção. Irmã Diana, irmã Diana!"
  },
  AvgDialog_18843_Content_50 = {
    Text = "Aqui o espaço é pequeno, dá para ver o fim. Além de algumas mesas e cadeiras, não há quase nada, nem um arquivo"
  },
  AvgDialog_18843_Content_51 = {
    Text = "Depois que fomos trazidos, todos somos obrigados a tomar remédios e adormecemos"
  },
  AvgDialog_18843_Content_52 = {
    Text = "Depois de dormir, você sonha que está em um lugar escuro e frio, sem janelas, apenas uma grande luz brilhando no seu rosto, muito ofuscante"
  },
  AvgDialog_18843_Content_53 = {
    Text = "Quando acordar, verá... aquelas manchas pretas"
  },
  AvgDialog_18843_Content_54 = {
    Text = "Escuro e frio, sem janelas. Parece um porão"
  },
  AvgDialog_18843_Content_55 = {
    Text = "Mas, a entrada do porão da oficina não está aqui, e lá dentro está cheio de tralhas. Não é como nos sonhos"
  },
  AvgDialog_18843_Content_56 = {
    Text = "Será uma sala secreta?"
  },
  AvgDialog_18843_Content_57 = {
    Text = "Sala secreta, né? Isso eu entendo. Brown!"
  },
  AvgDialog_18843_Content_58 = {Text = "Chiado!"},
  AvgDialog_18843_Content_59 = {
    Text = "O rato correu e desapareceu na fenda da parede.\nLogo, você ouviu guinchos de rato do outro lado da parede"
  },
  AvgDialog_18843_Content_6 = {
    Text = "Mas não há nada escuro aqui, Aigis é uma grande mentirosa! Grande mentirosa, nariz longo!"
  },
  AvgDialog_18843_Content_60 = {
    Text = "Ali, ali tem um lugar vago!"
  },
  AvgDialog_18843_Content_61 = {
    Text = "Jenkins batia desordenadamente na parede. Percebendo o que ela fazia, você se juntou a ela, pressionando os tijolos com intenção"
  },
  AvgDialog_18843_Content_62 = {
    Text = "A parede afundou de repente na palma de Ramona, após um clique vindo de algum lugar, a parede se projetou um pouco e começou a abrir lentamente"
  },
  AvgDialog_18843_Content_63 = {
    Text = "Com o alargamento das fendas entre os tijolos, sangue e cheiro de podridão jorraram"
  },
  AvgDialog_18843_Content_64 = {
    Text = "Um túnel escuro e estreito aparece diante de vocês, descendo"
  },
  AvgDialog_18843_Content_7 = {
    Text = "Não estou mentindo, não estou. Eu realmente vi!"
  },
  AvgDialog_18843_Content_8 = {
    Text = "Eu realmente vi isso... Acredite em mim..."
  },
  AvgDialog_18843_Content_9 = {
    Text = "Aigis, venha. Vamos ao consultório"
  },
  AvgDialog_18844_Content_1 = {
    Text = "O que aconteceu com aquela criança?"
  },
  AvgDialog_18844_Content_2 = {
    Text = "Ela parece estar falando com alguém que não podemos ver"
  },
  AvgDialog_18844_Content_3 = {
    Text = "Ela também foi controlada como Jenkins? Como isso é possível?"
  },
  AvgDialog_18845_Content_1 = {
    Text = "Tente rastrear. Outros investigadores podem ter dificuldade em rastrear não-despertos"
  },
  AvgDialog_18845_Content_2 = {
    Text = "Mas se for você—com sua acuidade, você certamente pode"
  },
  AvgDialog_18846_Content_1 = {
    Text = "Você respirou fundo, fechou os olhos e sua visão mergulhou na escuridão.\nNo começo, não havia nada, apenas o som da sua respiração e de Ramona"
  },
  AvgDialog_18846_Content_2 = {
    Text = "Gradualmente, você pode ouvir as gotas de água na névoa colidindo, os monstros de lama se desintegrando atrás de vocês, e a poeira negra caindo suavemente"
  },
  AvgDialog_18846_Content_3 = {
    Text = "A Chave de Prata começou a zumbir, você escutou atentamente e conseguiu distinguir uma melodia oculta.\nO ritmo era alegre, como uma canção, chamando suavemente de algum lugar próximo"
  },
  AvgDialog_18846_Content_4 = {
    Text = "\"O velho Charlie tinha um gato malhado que ele amava...\""
  },
  AvgDialog_18846_Content_5 = {Text = "Aqui!"},
  AvgDialog_18847_Content_1 = {
    Text = "O monstro que vocês derrotaram desmoronou em uma poça de lama negra. Você olha ao redor, vendo apenas a névoa branca"
  },
  AvgDialog_18847_Content_2 = {
    Text = "Maldição, não consigo ver nada"
  },
  AvgDialog_18847_Content_3 = {
    Text = "Meus óculos não mostram muita coisa"
  },
  AvgDialog_18847_Content_4 = {Text = "E agora?"},
  AvgDialog_18847_Content_5 = {
    Text = "Se houver uma maneira de investigar sem usar a visão, seria ótimo"
  },
  AvgDialog_18847_Content_6 = {
    Text = "Palavra-chave lida com sucesso, \"método de rastreamento sem visão\", pesquisando...\nPesquisa concluída, Guardião pode considerar rastreamento mental"
  },
  AvgDialog_18847_Content_7 = {
    Text = "Não é isso que os Investigadores usam para rastrear Corpos Despertos perdidos? Funciona em Metamorfos também?"
  },
  AvgDialog_18847_Content_8 = {
    Text = "O princípio da retrospecção mental é localizar ondas mentais diferentes das pessoas comuns.\nNesse aspecto, os mutantes são iguais aos despertos"
  },
  AvgDialog_18847_Content_9 = {
    Text = "Mas—antes disso, vamos lidar com esse cara"
  },
  AvgDialog_18848_Content_1 = {
    Text = "Um Metamorfo após o outro se dissipou sob a lâmina de Ramona. A compleição de Aigis ficou cada vez mais pálida em meio à poeira negra que se espalhava."
  },
  AvgDialog_18848_Content_2 = {
    Text = "O que estão esperando? Me prendam logo.\nEu sou o assassino, me levem, e... tragam Lucy de volta"
  },
  AvgDialog_18848_Content_3 = {
    Text = "Se você quer que ela volte, prove sua inocência e conte-nos a verdade, em vez de agir assim. Isso não é um bom método"
  },
  AvgDialog_18848_Content_4 = {
    Text = "Você não entende, vocês... vocês não entendem... Só eu sou o verdadeiro desmembrador"
  },
  AvgDialog_18848_Content_5 = {
    Text = "Ela cambaleou e atacou vocês dois"
  },
  AvgDialog_18849_Content_1 = {
    Text = "15:01，Londinium Leste\nLilian Atelier"
  },
  AvgDialog_18849_Content_10 = {
    Text = "Jenkins agarrou a fita de uma vez.\nAigis também parecia tensa, contagiada pela emoção dela"
  },
  AvgDialog_18849_Content_11 = {
    Text = "Irmã, isso é... isso é da minha irmã! Eu mesmo fiz o fecho, não tem como errar"
  },
  AvgDialog_18849_Content_12 = {
    Text = "Seu rosto está cada vez mais pálido, segurando a fita como se pesasse toneladas. Seus dedos rígidos tentam segurá-la firmemente, mas sem querer danificá-la"
  },
  AvgDialog_18849_Content_13 = {
    Text = "Onde ela está, ela está bem? Ela está ferida? Será que... será que"
  },
  AvgDialog_18849_Content_14 = {
    Text = "Guinch guinch, guinch guinch guinch"
  },
  AvgDialog_18849_Content_15 = {
    Text = "Sim, sim. Ela deve ter desaparecido, certo? Vocês também não conseguiram encontrá-la, certo?"
  },
  AvgDialog_18849_Content_16 = {
    Text = "De fato, não encontramos nenhuma pista dela."
  },
  AvgDialog_18849_Content_17 = {
    Text = "Então ainda há esperança. A fita foi rompida, ela deve ter conseguido escapar, e então se escondeu na oficina, deve ser isso"
  },
  AvgDialog_18849_Content_18 = {
    Text = "Você consegue ver a tremor nos olhos dela. Mas às vezes, em vez da cruel realidade, uma crença falsa pode sustentar uma pessoa para avançar"
  },
  AvgDialog_18849_Content_19 = {
    Text = "Aigis tirou algumas balas bem embaladas de baixo do colchão e as ofereceu a Jenkin"
  },
  AvgDialog_18849_Content_2 = {
    Text = "Você disse <Blue:louco>, que tipo de louco?"
  },
  AvgDialog_18849_Content_20 = {
    Text = "Nós... encontraremos sua irmã. Com certeza"
  },
  AvgDialog_18849_Content_21 = {
    Text = "Menina murmura, voz de consolo diminuindo. Ela está pálida, parece em grande dor"
  },
  AvgDialog_18849_Content_22 = {
    Text = "%player%. Algo está acontecendo no pátio, venha rápido"
  },
  AvgDialog_18849_Content_23 = {
    Text = "Você chegou apressado e viu Ramona amarrando um homem com algumas pessoas vestidas de forma diferente dos outros trabalhadores"
  },
  AvgDialog_18849_Content_24 = {
    Text = "O corpo do homem estava coberto de cicatrizes estranhas, parecendo fissuras mal cicatrizadas, com uma substância negra grudando nas feridas"
  },
  AvgDialog_18849_Content_25 = {
    Text = "Aquilo é uma <Yellow:marca de corrosão>, parece estar na <Yellow:fase intermediária de corrosão>.\nVocê nunca viu algo assim"
  },
  AvgDialog_18849_Content_26 = {
    Text = "Veja, esses são os loucos que eu mencionei.\nEles ainda estão com suas roupas de trabalho, provavelmente acabaram de adoecer, assustador"
  },
  AvgDialog_18849_Content_27 = {
    Text = "Uma pessoa de branco tirou uma seringa de algum lugar.\nEle injetou no pescoço do homem, que se contorceu duas vezes e depois fechou os olhos, ficando imóvel"
  },
  AvgDialog_18849_Content_28 = {
    Text = "Você controlou sua expressão - medicamentos comuns não funcionariam em um corpo corroído, como ele conseguiu?"
  },
  AvgDialog_18849_Content_29 = {
    Text = [[
Vendo o homem desmaiar, eles o amarraram e o levaram rapidamente.
Ramona tentou segui-los, mas Sarah bloqueou seu caminho]]
  },
  AvgDialog_18849_Content_3 = {
    Text = "Hum, não sei dizer. Essas pessoas podem estar normais ontem e hoje estarem loucas.\nSeus olhos e narizes podem se fundir de repente, é assustador"
  },
  AvgDialog_18849_Content_30 = {
    Text = "Senhorita Mary, não vá, deixe que eles cuidem disso.\nSe você se machucar, como vou explicar para o {Male=senhor,Female=senhorita} Ash?"
  },
  AvgDialog_18849_Content_31 = {
    Text = "Não há necessidade de explicações."
  },
  AvgDialog_18849_Content_32 = {
    Text = "Ai, Ai Ash{Male=senhor,Female=senhorita}!"
  },
  AvgDialog_18849_Content_33 = {
    Text = "Embora o <Yellow:Comitê de Revisão> regule rigorosamente a pesquisa civil sobre Dissolução, sempre há um ou dois indivíduos com meios especiais. A pessoa de branco foi capaz de subjugar um Metamorfo em um instante — certamente não é uma pessoa comum."
  },
  AvgDialog_18849_Content_34 = {
    Text = "Será que ele sabe algo sobre esses eventos no Leste?\nSerá que ele está envolvido?"
  },
  AvgDialog_18849_Content_35 = {
    Text = "O que foi isso antes? Quem era aquele em roupas brancas, de que oficina ele vem?"
  },
  AvgDialog_18849_Content_36 = {
    Text = "E... é apenas um <Blue:pesquisador>—"
  },
  AvgDialog_18849_Content_37 = {
    Text = "Espero que seja honesta conosco, Srta. Sarah.\nNão quero ver as coisas saírem do controle"
  },
  AvgDialog_18849_Content_38 = {
    Text = "Você olha para Sarah, que evita seu olhar, com uma expressão séria.\nSarah morde o lábio, como se entendesse, e toma uma decisão"
  },
  AvgDialog_18849_Content_39 = {
    Text = "Certo. Já que você disse isso... Por favor, me siga"
  },
  AvgDialog_18849_Content_4 = {
    Text = "Deixe-me te contar, este lugar secreto tem muitas surpresas.\nAquela mulher fedida escondeu muitas coisas em seu escritório"
  },
  AvgDialog_18849_Content_40 = {
    Text = "15:01，Lilian Atelier\nÁrea de saúde temporária"
  },
  AvgDialog_18849_Content_41 = {
    Text = "Dezenas de camas apertadas no refeitório já estreito, todos os pacientes amarrados, presos às camas"
  },
  AvgDialog_18849_Content_42 = {
    Text = "Os enfermeiros circulam, alguns com faixas de tecido, prontos para reforçar as amarras dos pacientes"
  },
  AvgDialog_18849_Content_43 = {
    Text = "Na cama perto da janela, um velho magro olhava fixamente, com uma gota de líquido negro e viscoso escorrendo do canto do olho"
  },
  AvgDialog_18849_Content_5 = {Text = "Brown."},
  AvgDialog_18849_Content_6 = {
    Text = "Brown saiu da bolsa, segurando dois anéis brilhantes.\nPelo trabalho e material, não são inestimáveis, mas são caros"
  },
  AvgDialog_18849_Content_7 = {
    Text = "Você pensou na fita com fivela de prata"
  },
  AvgDialog_18849_Content_8 = {
    Text = "Então, você viu algo parecido com isso?"
  },
  AvgDialog_18849_Content_9 = {Text = "!"},
  AvgDialog_18850_Content_1 = {
    Text = "O monstro distorcido está à beira da morte, a lama negra se contorce com dificuldade, inúmeras faces surgem e desaparecem, emitindo sons horripilantes"
  },
  AvgDialog_18850_Content_10 = {
    Text = "Ele já está... quase sem forças, parece ter apenas um pouco de consciência.\nQuero falar com ele, ouvir o que ele tem a dizer, há alguma maneira?"
  },
  AvgDialog_18850_Content_100 = {
    Text = "Para ela, hoje deve ter sido muito difícil.\nPensando assim, você seguiu Ramona e Jenkin, e ouviu Aigis seguindo você"
  },
  AvgDialog_18850_Content_11 = {
    Text = "......Entre os investigadores comuns, não há precedentes.\nMas o Professor Alistair conseguiu se comunicar com a consciência residual dos Mutantes usando a Chave de Prata"
  },
  AvgDialog_18850_Content_12 = {
    Text = "Não precisa dizer mais nada, você pega a chave de prata e instintivamente fecha os olhos"
  },
  AvgDialog_18850_Content_13 = {
    Text = "O cheiro de carne podre, o ar frio do porão e a leve vibração da chave de prata desapareceram rapidamente.\nVocê está imerso na escuridão, ouvindo atentamente cada grito de dor"
  },
  AvgDialog_18850_Content_14 = {
    Text = "Irmã Sasa... me ajude"
  },
  AvgDialog_18850_Content_15 = {
    Text = "Não quero morrer, não quero morrer"
  },
  AvgDialog_18850_Content_16 = {
    Text = "Tudo é ela... é essa mulher... foi ela que me fez aceitar tratamento, foi ela"
  },
  AvgDialog_18850_Content_17 = {
    Text = "Perigo... deve esperar... Missaga"
  },
  AvgDialog_18850_Content_18 = {
    Text = "Você localizou a voz"
  },
  AvgDialog_18850_Content_19 = {
    Text = "Sou o novo guardião dos segredos, você é... o veterano que administra a academia?"
  },
  AvgDialog_18850_Content_2 = {
    Text = "Em meio às orações frenéticas de Sara, um rosto com olhos e dentes em excesso emergiu do Mutante. Ele abriu a boca e soltou um gemido rouco."
  },
  AvgDialog_18850_Content_20 = {
    Text = "Sou eu... cinco dias atrás... eu e Sean... investigando o Desmembrador... encontramos um monstro...\nSean... está seguro?"
  },
  AvgDialog_18850_Content_21 = {
    Text = "Ele estava recebendo tratamento na escola, a situação estava estável.\n Você pode me contar o que aconteceu?"
  },
  AvgDialog_18850_Content_22 = {
    Text = "O monstro me transformou... levou a senhora... depois... alguém... a pessoa com a marca da faca... me trouxe aqui... quebrou, cortou... e me colocou com os outros"
  },
  AvgDialog_18850_Content_23 = {
    Text = "Eles mencionaram um... plano... fora da oficina... e muitas outras coisas...\nEncontrá-los... guardiões... e então... interromper"
  },
  AvgDialog_18850_Content_24 = {
    Text = "A voz tênue desvanece gradualmente. Você abre os olhos. O rosto humano pálido no Mutante se dissolve lentamente no ar, deixando Apenas uma poça de resíduo negro como piche no chão."
  },
  AvgDialog_18850_Content_25 = {
    Text = "Você está bem?"
  },
  AvgDialog_18850_Content_26 = {
    Text = "Estou bem. Só que... aquele veterano me disse que foi transformado em estátua por uma entidade desconhecida, levado para experimentos e depois deixado aqui com os outros"
  },
  AvgDialog_18850_Content_27 = {
    Text = "A pessoa que o estudou tinha uma marca de bisturi"
  },
  AvgDialog_18850_Content_28 = {
    Text = "Com certeza é a associação dos escultores. Seu símbolo é uma faca de esculpir"
  },
  AvgDialog_18850_Content_29 = {
    Text = "Além disso, ele também disse que os escultores mencionaram um plano.\nUm plano que envolve fora da oficina"
  },
  AvgDialog_18850_Content_3 = {
    Text = "Sha... Sha... irmã"
  },
  AvgDialog_18850_Content_30 = {
    Text = "Ramona balançou a espada, guardou-a na bainha e olhou para Sarah, que estava sentada no chão"
  },
  AvgDialog_18850_Content_31 = {
    Text = "Fale. Qual o objetivo dos experimentos humanos e assassinatos?\nQual é o plano?"
  },
  AvgDialog_18850_Content_32 = {
    Text = "Experimentos humanos, escultor? Não entendo"
  },
  AvgDialog_18850_Content_33 = {
    Text = "Eu só quero que a oficina continue, para que todos possam crescer saudáveis"
  },
  AvgDialog_18850_Content_34 = {
    Text = "Saúde? Olhe para os pacientes, olhe para Aigis! Eles estragaram os olhos dela, você chama isso de saúde?"
  },
  AvgDialog_18850_Content_35 = {
    Text = "Não, impossível... Eu verifiquei o Doutor, tentei o tratamento, achei seguro, não é possível"
  },
  AvgDialog_18850_Content_36 = {
    Text = "Aigis, querida, diga-me, você está bem, certo?\nO doutor curou suas alucinações, não é verdade?"
  },
  AvgDialog_18850_Content_37 = {
    Text = "Aigis olhou para vocês, como se finalmente tivesse reunido coragem"
  },
  AvgDialog_18850_Content_38 = {
    Text = "Não, não faça experimentos com ele!"
  },
  AvgDialog_18850_Content_39 = {Text = "Aigis!"},
  AvgDialog_18850_Content_4 = {
    Text = "......Pequeno Willy...?\nSó o Pequeno Willy me chama assim, é você, Pequeno Willy?"
  },
  AvgDialog_18850_Content_40 = {
    Text = "É você, pequena Aigis.  \nVocê já pensou nisso, para colaborar conosco?"
  },
  AvgDialog_18850_Content_41 = {
    Text = "Eu, eu... eu não"
  },
  AvgDialog_18850_Content_42 = {
    Text = "Quando você está doente, é necessário examinar e medicar de acordo com o diagnóstico. Se vocês podem ver as coisas negras, todos deveriam receber tratamento para se recuperar o mais rápido possível, certo?"
  },
  AvgDialog_18850_Content_43 = {
    Text = "Não... Tiyog, Tiyog não pode ver...! Solte-o!\nSe continuarem assim, eu, eu, eu vou contar para a Srta. Sarah!"
  },
  AvgDialog_18850_Content_44 = {
    Text = "Não vê? Então é um mentiroso.\nSe ele não vê, então—"
  },
  AvgDialog_18850_Content_45 = {
    Text = "Aigis! Cuidado com as costas!"
  },
  AvgDialog_18850_Content_47 = {
    Text = "——Você faz isso"
  },
  AvgDialog_18850_Content_48 = {
    Text = "Hum...aqui é"
  },
  AvgDialog_18850_Content_49 = {
    Text = "A intensa luz fez as pessoas querendo fechar os olhos involuntariamente, enquanto Aigis tentava piscar, mas descobriu que não conseguia"
  },
  AvgDialog_18850_Content_5 = {
    Text = "Eu sou... Missaga"
  },
  AvgDialog_18850_Content_50 = {
    Text = "Algo prendeu seus olhos, você só pode ver o homem de branco com uma faca fina"
  },
  AvgDialog_18850_Content_51 = {
    Text = "<Big:Não, não, Srta. Sarah, Srta. Sarah!>"
  },
  AvgDialog_18850_Content_52 = {
    Text = "A lâmina prateada segue o movimento do pesquisador, traçando um longo rastro prateado"
  },
  AvgDialog_18850_Content_53 = {
    Text = "<Big:Senhorita Sarah! Tiyog! Socorro! Me ajudem! Me ajudem!>"
  },
  AvgDialog_18850_Content_54 = {
    Text = "A ponta da faca se aproxima, cada vez mais, até preencher toda a visão.\nEntão—"
  },
  AvgDialog_18850_Content_55 = {
    Text = "<Shake:Ah——!>"
  },
  AvgDialog_18850_Content_56 = {
    Text = "Na escuridão infinita, ela flutua sozinha, como se envolta por águas geladas.\nSeus membros estão dormentes, incapazes de se mover"
  },
  AvgDialog_18850_Content_57 = {
    Text = "Dói... meus olhos estão desconfortáveis"
  },
  AvgDialog_18850_Content_58 = {
    Text = "Cores brilhantes e ondulantes infiltraram-se. Essas cores eram um líquido viscoso, misturado com sangue e lágrimas, fluindo incessantemente"
  },
  AvgDialog_18850_Content_59 = {
    Text = "Errei, sou um inútil... não devia... não devia tentar fazer o impossível"
  },
  AvgDialog_18850_Content_6 = {Text = "!?"},
  AvgDialog_18850_Content_60 = {
    Text = "Substituiu a água do lago, o ar, os cheiros, sons e toques.\nTornou-se tudo para ela, dando-lhe um abraço doloroso"
  },
  AvgDialog_18850_Content_61 = {
    Text = "Srta. Sarah... Tiyug... me ajude... dói... estou sofrendo"
  },
  AvgDialog_18850_Content_62 = {
    Text = "As cores pulsantes subiram rapidamente, ela caiu em uma cortina de luz branca. Impulsos estranhos se transformaram em mil cores em seus olhos, ela tentou cobrir os olhos, mas não conseguiu se mover"
  },
  AvgDialog_18850_Content_63 = {
    Text = "Quem... é você...?"
  },
  AvgDialog_18850_Content_64 = {
    Text = "A dor excessiva finalmente se transformou em dormência. Não sei quanto tempo passou, mas ela finalmente captou um som no silêncio"
  },
  AvgDialog_18850_Content_65 = {
    Text = "Ver os olhos de @2 é o melhor material.\nSe não fosse por Sarah e esse garoto, já teria usado para experimentos"
  },
  AvgDialog_18850_Content_66 = {
    Text = "Agora não é tarde, doutor, finalmente conseguimos @4@2, isso merece uma celebração!"
  },
  AvgDialog_18850_Content_67 = {
    Text = "Ruídos indistintos ecoam nos ouvidos. De quem são essas vozes? O que estão dizendo? Com o fim do pesadelo, tudo se torna vago"
  },
  AvgDialog_18850_Content_68 = {
    Text = "Aigis percebeu que não sabia há quanto tempo estava sentada em uma cadeira, com pesquisadores vestindo roupas brancas ao seu redor, falando animadamente, mas ela não conseguia ouvir nada"
  },
  AvgDialog_18850_Content_69 = {
    Text = "Ti... Tiyog...?"
  },
  AvgDialog_18850_Content_7 = {
    Text = "Isso, é o desaparecido...!"
  },
  AvgDialog_18850_Content_70 = {
    Text = "Os rostos familiares à frente perdem a cor como se lavados, antes que a íris marrom fosse completamente substituída pela pedra branca, ele, ou ela, soltou o último suspiro"
  },
  AvgDialog_18850_Content_71 = {
    Text = "Ai... Ji Si"
  },
  AvgDialog_18850_Content_72 = {
    Text = "<Shake:Tiyog——!!>"
  },
  AvgDialog_18850_Content_73 = {
    Text = "Quando eu acordar, estarei no quarto, e Tiyug terá se transformado... em algo ruim"
  },
  AvgDialog_18850_Content_74 = {
    Text = "Se eu não tivesse entrado à toa, se eu soubesse que sou um inútil... não os teria irritado, e eles não teriam feito isso com Tiyug"
  },
  AvgDialog_18850_Content_75 = {
    Text = "Impossível, isso não é real, isso não é real...!"
  },
  AvgDialog_18850_Content_76 = {
    Text = "<Big:Para de fingir ignorância!>"
  },
  AvgDialog_18850_Content_77 = {
    Text = "Jenkins empurrou Sarah com força, quase derrubando-a. O rato em seu ombro compartilhava sua raiva, mostrando os dentes para Sarah"
  },
  AvgDialog_18850_Content_78 = {
    Text = "Fale, para onde aquele maldito doutor levou as pessoas? Onde está minha irmã? Fale!"
  },
  AvgDialog_18850_Content_79 = {
    Text = "Jenkins, não faça isso...! A Srta. Sarah não fez de propósito, ela não sabia"
  },
  AvgDialog_18850_Content_8 = {
    Text = "Encontraram a pessoa? Como ele está? Precisa de ajuda?"
  },
  AvgDialog_18850_Content_80 = {
    Text = "Pare de protegê-la! Você ficou assim, aqueles loucos ficaram assim, minha irmã desapareceu, tudo por causa dela! Ela deve pagar!"
  },
  AvgDialog_18850_Content_81 = {
    Text = "Desculpa, desculpa"
  },
  AvgDialog_18850_Content_82 = {
    Text = "......Erica, contate a equipe de investigação. Temos uma necessidade de transporte"
  },
  AvgDialog_18850_Content_83 = {
    Text = "Enviando solicitação de assistência na investigação.\nEnviado, confirmado, a equipe de investigação 3 chegará ao local em 3 horas"
  },
  AvgDialog_18850_Content_84 = {
    Text = "Por favor, Srta. Sarah.\nAté que o pessoal chegue, você terá que esperar no escritório"
  },
  AvgDialog_18850_Content_85 = {
    Text = "Desculpa... de verdade... desculpa"
  },
  AvgDialog_18850_Content_86 = {
    Text = "Você dá alguns passos e percebe que uma pequena figura branca está faltando"
  },
  AvgDialog_18850_Content_87 = {
    Text = "Ela pode precisar de um tempo sozinha"
  },
  AvgDialog_18850_Content_88 = {Text = "?"},
  AvgDialog_18850_Content_89 = {
    Text = "Não é nada. Vamos embora."
  },
  AvgDialog_18850_Content_9 = {
    Text = "O Mutante diante deles se contorcia em agonia. Seu rosto quase humano se esticou e distorceu, depois se aglomerou — de qualquer forma, estava claramente além de qualquer salvação."
  },
  AvgDialog_18850_Content_90 = {Text = "Aigis?"},
  AvgDialog_18850_Content_91 = {
    Text = "Você olhou para trás e viu a garota parada, imóvel"
  },
  AvgDialog_18850_Content_92 = {
    Text = "O que aconteceu, Aigis? Você quer que eu te leve de volta para descansar?"
  },
  AvgDialog_18850_Content_93 = {
    Text = "......A Srta. Sarah vai ficar bem?"
  },
  AvgDialog_18850_Content_94 = {
    Text = "Só queremos fazer algumas perguntas a ela, não se preocupe"
  },
  AvgDialog_18850_Content_95 = {
    Text = "Ela vai voltar?"
  },
  AvgDialog_18850_Content_96 = {
    Text = "Ela... ela pode voltar"
  },
  AvgDialog_18850_Content_97 = {Text = "..."},
  AvgDialog_18850_Content_98 = {Text = "Aigis?"},
  AvgDialog_18850_Content_99 = {
    Text = [[
Tudo bem... Vamos, %player%{Male=senhor,Female=senhora}.
Eu vou ficar bem]]
  },
  AvgDialog_18851_Content_1 = {
    Text = "13:37，Londinium Leste\nLilian Atelier"
  },
  AvgDialog_18851_Content_10 = {
    Text = "Ela tirou um pedaço de ferro e um prego fino do bolso e os inseriu na fechadura, enquanto o rato em seu ombro ficava em pé, olhando ao redor com cautela"
  },
  AvgDialog_18851_Content_11 = {
    Text = "A fechadura fez um clique, ela girou a maçaneta e empurrou a porta"
  },
  AvgDialog_18851_Content_12 = {
    Text = "Hehe, moleza!"
  },
  AvgDialog_18851_Content_13 = {
    Text = "13:37，Londinium Leste\nLilian Atelier"
  },
  AvgDialog_18851_Content_14 = {
    Text = "Srta. Sarah, por que não veste a pequena Aigis com algo bonito? Hoje temos convidados importantes"
  },
  AvgDialog_18851_Content_15 = {
    Text = "O que você sabe? Se nos vestirmos muito bem, parecerá que não precisamos de dinheiro. Se nos vestirmos mal, parecerá que somos um buraco sem fundo, assustando os patrocinadores"
  },
  AvgDialog_18851_Content_16 = {
    Text = "Ela puxou a saia de Aigis e, depois de umedecer um pouco na manga, limpou com força a bochecha de Aigis"
  },
  AvgDialog_18851_Content_17 = {
    Text = "Aigis, minha boa Aigis, o que você deve dizer quando encontrar o patrocinador, você ainda se lembra?"
  },
  AvgDialog_18851_Content_18 = {
    Text = "Lembro, Srta. Sarah. Eu obedeci, estava revisando antes de dormir ontem à noite"
  },
  AvgDialog_18851_Content_19 = {
    Text = "Sarah nodded in satisfaction, then glanced at the middle-aged man beside her with his hands in his pockets"
  },
  AvgDialog_18851_Content_2 = {
    Text = "Aigis o que você ainda está fazendo? O patrocinador está chegando!"
  },
  AvgDialog_18851_Content_20 = {
    Text = "Tome cuidado também, não diga nada desnecessário, entendeu?"
  },
  AvgDialog_18851_Content_21 = {
    Text = "Entendi, entendi!"
  },
  AvgDialog_18851_Content_22 = {
    Text = "Entendido, fiquem firmes, {Male=ele,Female=ela} estão vindo"
  },
  AvgDialog_18851_Content_23 = {
    Text = "Não encontramos a carteira e ainda encontramos uma mutação corrosiva. Isso é o que chamam de baixo risco"
  },
  AvgDialog_18851_Content_24 = {
    Text = "Você nem terminou de falar e uma voz familiar soa em sua mente"
  },
  AvgDialog_18851_Content_25 = {
    Text = "Os eventos não permanecerão sempre os mesmos, e as tarefas também não.\nOu você tem um problema com o julgamento de William?"
  },
  AvgDialog_18851_Content_26 = {
    Text = "Confio plenamente no julgamento do senhor Drapule, deve ter havido uma piora no fenômeno de dissolução!"
  },
  AvgDialog_18851_Content_27 = {
    Text = "Reação rápida.\nCerto, concentre-se. Se você encontrar um mutante, significa que não está longe do local alvo."
  },
  AvgDialog_18851_Content_28 = {
    Text = "De fato. Olhe."
  },
  AvgDialog_18851_Content_29 = {
    Text = "Você olha na direção que ela sinaliza. Não muito longe está uma porta de ferro com as palavras \"Oficina de Laboratório de Lilliane\" gravadas, diante dela standando três pessoas"
  },
  AvgDialog_18851_Content_3 = {
    Text = "Cheguei, desculpe Srta. Sarah, eu, eu não queria fazer você esperar"
  },
  AvgDialog_18851_Content_30 = {
    Text = "Relatório, cheguei ao local da missão"
  },
  AvgDialog_18851_Content_31 = {
    Text = "Confirmação de chegada ao local da missão. Verificação do objetivo da missão: infiltrar na oficina de trabalhos, recuperar o estudante desaparecido, confirmar a identidade do ser desconhecido e interromper suas ações"
  },
  AvgDialog_18851_Content_32 = {
    Text = "Verificação do objetivo da missão concluída. Estamos prestes a entrar na oficina, mantenha as comunicações claras"
  },
  AvgDialog_18851_Content_33 = {
    Text = "Ramona olha para você."
  },
  AvgDialog_18851_Content_34 = {
    Text = "Como está, pronto?"
  },
  AvgDialog_18851_Content_35 = {
    Text = "Posso lidar com isso, desde que as pessoas lá dentro não sejam como aquelas crianças"
  },
  AvgDialog_18851_Content_36 = {
    Text = "<Small: ... não como a boneca.>"
  },
  AvgDialog_18851_Content_37 = {
    Text = "Você sabe que o Comunicador de Prata é muito sensível, certo?"
  },
  AvgDialog_18851_Content_38 = {
    Text = "<Shake:Cof cof!>"
  },
  AvgDialog_18851_Content_39 = {
    Text = "Relaxe. Vou proteger seu broche e abotoaduras com minha vida, Ash{Male=senhor,Female=senhorita}"
  },
  AvgDialog_18851_Content_4 = {
    Text = "Certo, já são adultos e ainda tão imaturos. Vamos, vamos, se nos atrasarmos será ruim"
  },
  AvgDialog_18851_Content_40 = {
    Text = "Então vou contar com você, querida governanta Mary"
  },
  AvgDialog_18851_Content_41 = {
    Text = "Se você continuar brincando com identidades falsas, prepare-se para treinamento extra quando voltar."
  },
  AvgDialog_18851_Content_5 = {
    Text = "Menina segue obediente, olha para trás e acena para a planta no canto.\nPassos se afastam, menina com rato aparece entre as folhas"
  },
  AvgDialog_18851_Content_6 = {
    Text = "Finalmente! Aquela mulher irritante fica no escritório o dia todo, mas hoje finalmente tive minha chance!"
  },
  AvgDialog_18851_Content_7 = {
    Text = "Chirp! Chirp, chirp!"
  },
  AvgDialog_18851_Content_8 = {
    Text = "Fique tranquilo, Aigis disse que elas vão levar aquele tal de autoajuda para uma visita, não voltarão até o meio-dia. Preciso procurar bem, nenhum fio de cabelo deve escapar"
  },
  AvgDialog_18851_Content_9 = {
    Text = "Hora de trabalhar, os corredores da área residencial estão vazios. A garota chega a uma porta com a placa \"Escritório do Administrador\""
  },
  AvgDialog_18852_Content_1 = {
    Text = "Ash{Male=senhor,Female=senhorita}, Srta. Mary!"
  },
  AvgDialog_18852_Content_2 = {
    Text = "Estamos bem, leve todos para trás, nós cuidamos disso"
  },
  AvgDialog_18852_Content_3 = {
    Text = "Certo, certo. Meu Deus, isso é... crianças, venham para cá"
  },
  AvgDialog_18852_Content_4 = {
    Text = "Rápido, tem um problema vindo"
  },
  AvgDialog_18853_Content_1 = {
    Text = "A agitação terminou e as pessoas formaram fila novamente.\nAigis está de pé entre as crianças, pálida e ligeiramente tremendo"
  },
  AvgDialog_18853_Content_10 = {Text = "Droga—"},
  AvgDialog_18853_Content_11 = {
    Text = "O que você está fazendo? Pare!"
  },
  AvgDialog_18853_Content_2 = {
    Text = "Esses aqui, e então - vamos adicionar Aigis.\nEla é nossa criança favorita"
  },
  AvgDialog_18853_Content_3 = {
    Text = "Não, não, por favor... não quero ir, não quero me transformar"
  },
  AvgDialog_18853_Content_4 = {
    Text = "Obedeça, Aigis, venha aqui. Não desperdice o tempo dos adultos"
  },
  AvgDialog_18853_Content_5 = {
    Text = "Quando o pesquisador ia estender a mão, Jenkins pulou na frente de Aigis"
  },
  AvgDialog_18853_Content_6 = {
    Text = "Eu disse para não ir, você não ouviu?"
  },
  AvgDialog_18853_Content_7 = {
    Text = "Você é o novo garoto?"
  },
  AvgDialog_18853_Content_8 = {
    Text = "Não importa se sou novo ou antigo, se Aigis não quer ir, ninguém pode forçá-la! \nBrown, ajude!"
  },
  AvgDialog_18853_Content_9 = {Text = "Chiado!"},
  AvgDialog_18854_Content_1 = {
    Text = "Você e Ramona estavam discutindo em voz baixa quando de repente ouviram um tumulto atrás de vocês"
  },
  AvgDialog_18854_Content_2 = {
    Text = "Cuidado, pessoal lá fora! O paciente fugiu! Fugiu!"
  },
  AvgDialog_18854_Content_3 = {Text = "!"},
  AvgDialog_18855_Content_1 = {
    Text = "Uma canção inaudível guia você à frente, você atravessa a névoa, mas nunca vê o fim"
  },
  AvgDialog_18855_Content_10 = {
    Text = "Fique de olho nos arredores por mim."
  },
  AvgDialog_18855_Content_11 = {
    Text = "Você evita as manchas de sangue e se ajoelha para investigar.\nNão há sinais de petrificação, mas você vê pegadas de cores estranhas ao lado do corpo"
  },
  AvgDialog_18855_Content_12 = {
    Text = "Lodo de dissolução? Também está nos cadáveres... poderia ser do assassino?"
  },
  AvgDialog_18855_Content_13 = {
    Text = "Nesta área, além da oficina de trabalho, só aqui surgiram marcas de dissolução.\nNão acredito que seja uma coincidência"
  },
  AvgDialog_18855_Content_14 = {
    Text = "Isso quase prova que o agressor veio da oficina, a pergunta restante é: quem é ele, onde está escondido na oficina? É a forma de vida desconhecida que vocês estão procurando?"
  },
  AvgDialog_18855_Content_15 = {
    Text = "Espere, esse tamanho... são pegadas de criança?!"
  },
  AvgDialog_18855_Content_16 = {Text = "?!"},
  AvgDialog_18855_Content_17 = {
    Text = "......Realmente, parece que a direção está indo em direção ao ateliê"
  },
  AvgDialog_18855_Content_18 = {
    Text = "Rápido, encontre-o antes que se esconda"
  },
  AvgDialog_18855_Content_19 = {
    Text = [[
20:47, oficina de trabalho Lilian
corredor]]
  },
  AvgDialog_18855_Content_2 = {
    Text = "Os edifícios ao longo da rua te observam silenciosamente com suas janelas escuras, e o som dos seus passos ecoa na névoa, dando a impressão de que você está correndo sozinho por essa rua há muito tempo"
  },
  AvgDialog_18855_Content_20 = {
    Text = "Na neblina onipresente, a oficina se tornou mais sombria do que nunca.\nUm homem com um bastão preso à cintura patrulha o corredor sem ninguém e sem luz, segurando uma lanterna"
  },
  AvgDialog_18855_Content_21 = {
    Text = "Não acenda a luz, economize energia—**. Aquela Sarah é muito mão de vaca. E cheia de frescuras! Neste lugar caindo aos pedaços, qual ladrão se interessaria... hã?"
  },
  AvgDialog_18855_Content_22 = {
    Text = "Sob a luz amarelada, uma porta se abre silenciosamente"
  },
  AvgDialog_18855_Content_23 = {
    Text = "Quem, quem está aí?"
  },
  AvgDialog_18855_Content_24 = {
    Text = "Ele apertou o bastão de madeira, reunindo coragem para avançar"
  },
  AvgDialog_18855_Content_25 = {
    Text = "A velha lanterna apagou de repente"
  },
  AvgDialog_18855_Content_26 = {
    Text = "Um som nauseante e úmido de dilaceração se ergue no ar. Enormes patas de aranha irrompem pelos corpos dos oficiais e dos transeuntes, espirrando sangue espesso com cheiro de ferro por todo você."
  },
  AvgDialog_18855_Content_27 = {
    Text = "Uma força invisível o puxou para dentro. A porta de madeira se fechou com um estrondo, e o corredor voltou à paz e silêncio"
  },
  AvgDialog_18855_Content_28 = {
    Text = [[
20:43, oficina de trabalho Lilian
corredor]]
  },
  AvgDialog_18855_Content_29 = {
    Text = "Duas meninas se encolhem na fraca luz da lanterna, olhando ao redor constantemente"
  },
  AvgDialog_18855_Content_3 = {
    Text = "Nada tem começo ou fim. Você continuará avançando até que sua vida se esgote, até que o tempo—"
  },
  AvgDialog_18855_Content_30 = {
    Text = "Passos suaves se aproximam de longe, quase ensurdecedores no corredor silencioso"
  },
  AvgDialog_18855_Content_31 = {
    Text = "Quem, quem está aí?\nSaia! Eu, eu aviso, estou armada!"
  },
  AvgDialog_18855_Content_32 = {
    Text = "Não havia corrente de ar no corredor, mas a chama da lâmpada tremulava como se soprada pelo vento"
  },
  AvgDialog_18855_Content_33 = {
    Text = "A bandeja nas mãos de Aigis tremia, as xícaras e os pires brancos se batiam, emitindo um lamento como o choro de passarinhos recém-nascidos"
  },
  AvgDialog_18855_Content_34 = {
    Text = "Os passos se aproximam cada vez mais. As garras de Brown cravam-se profundamente no ombro de Jenkins, ele mostra os dentes, emitindo um chiado agudo característico dos roedores"
  },
  AvgDialog_18855_Content_35 = {
    Text = "Como se a voz de Brown a estimulasse, os passos aceleraram, vindo em direção aos dois"
  },
  AvgDialog_18855_Content_36 = {
    Text = "A sombra densa engoliu a fraca chama da vela, as meninas fecharam os olhos e sentiram apenas uma onda de vapor"
  },
  AvgDialog_18855_Content_37 = {
    Text = "Uma mão estendeu-se da escuridão, pousando precisamente na xícara de chá tremendo, silenciando-a"
  },
  AvgDialog_18855_Content_38 = {
    Text = "O que aconteceu com vocês? Estão tão pálidos"
  },
  AvgDialog_18855_Content_39 = {
    Text = "Sr. Rogers!\nEstá tão escuro aqui. Nós..."
  },
  AvgDialog_18855_Content_4 = {
    Text = "Cheiro de sangue"
  },
  AvgDialog_18855_Content_40 = {
    Text = "Noites enevoadas realmente assustam, não é?"
  },
  AvgDialog_18855_Content_41 = {
    Text = "Rogers abriu a porta, e a luz quente dissipou as sombras profundas do corredor"
  },
  AvgDialog_18855_Content_42 = {
    Text = "Obrigado por trazer comida para mim, Aigis, Jenkin"
  },
  AvgDialog_18855_Content_43 = {
    Text = "Coloque a bandeja na mesinha, Rogers pegou uma boneca bem feita da cama e sorriu para as duas meninas"
  },
  AvgDialog_18855_Content_44 = {
    Text = "Como recompensa, quer tocá-lo?\nGeorge ficará muito feliz"
  },
  AvgDialog_18855_Content_45 = {
    Text = "Os olhos inorgânicos da boneca refletem a luz amarela, como se silenciosamente implorassem à garota: toque-me, só uma vez"
  },
  AvgDialog_18855_Content_46 = {
    Text = "Acaricie-me, e então—"
  },
  AvgDialog_18855_Content_47 = {
    Text = "Seja meu amigo leal"
  },
  AvgDialog_18855_Content_5 = {
    Text = "Você acorda abruptamente, sentindo o cheiro metálico e doce.\nVocê diminui o passo e se aproxima da sombra caída à frente"
  },
  AvgDialog_18855_Content_6 = {
    Text = "São os restos despedaçados de uma mulher. Sua cavidade abdominal aberta ainda exala calor, seu rosto é uma massa confusa de carne, e ambos os braços estão ausentes — as secções transversais são limpas, como se alguém os tivesse cortado com precisão."
  },
  AvgDialog_18855_Content_7 = {
    Text = "Essa técnica é do Desmembrador"
  },
  AvgDialog_18855_Content_8 = {
    Text = "Evisceração, membros removidos como troféus, exatamente como os crimes do desmembrador no relatório da polícia.\nVocê não sabe o que é mais cruel: corrosão ou o assassino"
  },
  AvgDialog_18855_Content_9 = {
    Text = "Mas por que a canção da rastreabilidade mental o levaria a aqui? A capacidade do ser vivo desconhecido é claramente petrificação, ou será que existem mais de um indivíduo especial aqui?"
  },
  AvgDialog_18856_Content_1 = {
    Text = "Peso da consciência"
  },
  AvgDialog_18856_Content_10 = {
    Text = "Você seguiu atrás de Sarah até o grande portão de metal da oficina e viu alguns homens de uniforme segurando uma garotinha que chorava e se debatendo, indo para fora"
  },
  AvgDialog_18856_Content_11 = {
    Text = "É o Comitê de Censura"
  },
  AvgDialog_18856_Content_12 = {
    Text = "Isso não é o que a boneca disse sobre a retirada! Por que chegou tão rápido?"
  },
  AvgDialog_18856_Content_13 = {
    Text = "Solte! Para onde estão levando ela? Para onde estão levando Lucy?"
  },
  AvgDialog_18856_Content_14 = {Text = "Espera!"},
  AvgDialog_18856_Content_15 = {
    Text = "Você tira o colar escondido sob a roupa, e a chave de prata pendurada nele flutua na sua mão, emitindo uma luz suave"
  },
  AvgDialog_18856_Content_16 = {
    Text = "Guardião da Universidade de Mythag %player%, número da chave K-0617, solicitando conversar com o responsável pela operação"
  },
  AvgDialog_18856_Content_17 = {
    Text = "A pessoa à sua frente desvia o olhar da Chave de Prata e te saúda"
  },
  AvgDialog_18856_Content_18 = {
    Text = "<Blue:comitê do tratado de mystia> Chefe da terceira equipe de resposta, responsável pela transferência do inquérito sobre a organização especial S"
  },
  AvgDialog_18856_Content_19 = {
    Text = "Não esperava encontrar o novo Guardião do Segredo aqui, é uma honra, %player%{Male=senhor,Female=senhora}"
  },
  AvgDialog_18856_Content_2 = {
    Text = "10:20，Lilian Atelier\nEm frente ao escritório do administrador"
  },
  AvgDialog_18856_Content_20 = {
    Text = "O que aconteceu aqui? Por que vocês de repente prenderam membros da oficina?"
  },
  AvgDialog_18856_Content_21 = {
    Text = "Por favor, permita-me explicar"
  },
  AvgDialog_18856_Content_22 = {
    Text = "O capitão acenou e um agente ao lado entregou um saco de papel"
  },
  AvgDialog_18856_Content_23 = {
    Text = "Você abre a bolsa e encontra um pijama infantil velho. As bordas do pijama estão manchadas de manchas marrons escuras, endurecidas pelo líquido seco"
  },
  AvgDialog_18856_Content_24 = {
    Text = "Após receber a notificação de investigação conjunta da universidade de mythag, chegamos aqui às 10:23 e realizamos uma busca inicial na oficina, confirmando a situação da oficina"
  },
  AvgDialog_18856_Content_25 = {
    Text = "Durante a busca, encontramos vestígios de sangue no antigo quarto ao sudeste do primeiro andar da oficina, e na despensa sob a escada, encontramos este objeto, além de uma faca de cortar carne manchada de sangue"
  },
  AvgDialog_18856_Content_26 = {
    Text = "Após a identificação por membros da oficina, este pijama pertence à criança chamada Lucy. Com base nas manchas de sangue no antigo quarto e o testemunho de alguém gritando na noite passada, decidimos levá-la para investigação"
  },
  AvgDialog_18856_Content_27 = {
    Text = "Sou eu, fui eu que gritei! Fiquei assustado com a sombra ontem à noite, mas nada de ruim aconteceu! Este guardião também viu, nada aconteceu, certo?"
  },
  AvgDialog_18856_Content_28 = {
    Text = "Senhor, esta situação é complicada, suspeitamos de uma terceira parte envolvida. Esta criança pode estar sendo controlada. Poderia não levá-la?"
  },
  AvgDialog_18856_Content_29 = {
    Text = "Já sabemos dos eventos do grupo ilegal. Mas não importa se foi ordenado, o perpetrador sempre será um criminoso. Em termos de protocolo, não posso permitir que ela atue livremente"
  },
  AvgDialog_18856_Content_3 = {
    Text = "Antes de chegarem ao escritório, uma jovem mulher corre em sua direção"
  },
  AvgDialog_18856_Content_30 = {
    Text = "O Comitê de Censura seguirá as regras do Acordo durante a investigação, ela não sofrerá tratamento injusto. Posso garantir isso"
  },
  AvgDialog_18856_Content_31 = {
    Text = "Além disso, o carro para levá-los de volta à escola está pronto. A situação é especial, designarei dois agentes para acompanhá-los e garantir sua segurança. Por favor, sigam-me"
  },
  AvgDialog_18856_Content_32 = {Text = "Não."},
  AvgDialog_18856_Content_33 = {
    Text = "Os Escultores usam a chamada pesquisa como uma fachada, conduzindo secretamente experimentos humanos na oficina com o apoio do patrocinador Rogers, o que levou à ocorrência de dissolução anormal."
  },
  AvgDialog_18856_Content_34 = {
    Text = "Com base nas pistas atuais, além da \"loucura\" da oficina, o \"desmembrador\" que tem estado ativo na área leste é provavelmente uma das manifestações de dissolução anômala"
  },
  AvgDialog_18856_Content_35 = {
    Text = "Encontramos muitas coisas, faltando apenas a identidade do Desmembrador, para esclarecer completamente a verdade do evento e ainda arruinar os planos do escultor. Neste momento, não podemos sair"
  },
  AvgDialog_18856_Content_36 = {
    Text = "Entendo seu desejo de continuar a investigação, mas minhas ordens—"
  },
  AvgDialog_18856_Content_37 = {
    Text = "Ele de repente pressionou o brasão do comitê em seu braço, como se estivesse ouvindo algo.\nDeve ser o comunicador de prata fornecido pela universidade de Mythag ao comitê; há alguma nova ordem?"
  },
  AvgDialog_18856_Content_38 = {
    Text = "<Blue:Oficial Lydia>. Sim, os Guardiões do Segredo não querem desistir da investigação.\nTrês dias? Não, não estou questionando você... Sim, entendo. Confirmando recebimento da comunicação"
  },
  AvgDialog_18856_Content_39 = {
    Text = "Olá, é uma honra falar com você, <Blue:Primeiro Guardião do Segredo>"
  },
  AvgDialog_18856_Content_4 = {
    Text = "Srta. Sarah, algo terrível aconteceu! Estão levando Lucy!"
  },
  AvgDialog_18856_Content_40 = {
    Text = "Você só conhece uma pessoa que pode suportar esse título - seu mentor que vive no subsolo de Mythag há muitos anos. No último ano, você nunca o viu entrar em contato com você ou com a boneca, será que"
  },
  AvgDialog_18856_Content_41 = {
    Text = "Ok, entendi. Adeus, senhor"
  },
  AvgDialog_18856_Content_42 = {
    Text = "O capitão parou de conversar e se virou para você, enquanto a voz suave do professor ecoava em sua mente"
  },
  AvgDialog_18856_Content_43 = {
    Text = "Faça o que quiser, %player%, eu cuido do resto.\nConfio em você"
  },
  AvgDialog_18856_Content_44 = {
    Text = "Ele disse a mesma coisa antes de você partir.\nParece que você não precisa voltar por enquanto"
  },
  AvgDialog_18856_Content_45 = {
    Text = "Após a discussão com o primeiro guardião, o comitê decidiu permitir que o guardião continue a investigação do caso da oficina Lilian. Mas você só tem três dias. Após três dias, o caso será transferido para um investigador mais experiente"
  },
  AvgDialog_18856_Content_46 = {
    Text = "Ele se virou e começou a dar ordens aos agentes"
  },
  AvgDialog_18856_Content_47 = {
    Text = "Transferência suspensa, bloqueio de nível 5 em execução, suspeito detido até o fim da transferência para interrogatório"
  },
  AvgDialog_18856_Content_48 = {
    Text = "Não, não! Por favor, eu dou qualquer coisa, por favor, não a levem! Lucy, <Big:Lucy—>"
  },
  AvgDialog_18856_Content_49 = {
    Text = "Não foi ela, não foi ela! %player%! Por favor, ajude Lucy, ajude-a!"
  },
  AvgDialog_18856_Content_5 = {
    Text = "O q...uê?!"
  },
  AvgDialog_18856_Content_50 = {
    Text = "Desculpe, esta é uma ordem de morte, devo cumprir.\nEntão, me despeço"
  },
  AvgDialog_18856_Content_51 = {
    Text = "Juro perfurar a escuridão com minha lâmina"
  },
  AvgDialog_18856_Content_52 = {
    Text = "Ele mais uma vez fez uma saudação a você e, ignorando os gritos de Lucy e os apelos de Sarah e Aigis, fez com que seus subordinados levassem a garota e entrou no veículo que estava à espera"
  },
  AvgDialog_18856_Content_53 = {
    Text = "A porta do carro se fechou, bloqueando todas as vistas, os carros saíram um após o outro, e Sarah, sem forças, caiu de joelhos"
  },
  AvgDialog_18856_Content_54 = {
    Text = "<Small:Sou inútil, não sou um bom diretor, não consigo proteger todos, nem as crianças...>"
  },
  AvgDialog_18856_Content_55 = {
    Text = "A Miss Sarah, por favor... Todos nós entendemos. Você fez o seu melhor."
  },
  AvgDialog_18856_Content_56 = {
    Text = [[
<Small: desculpe, Mikey, desculpe, aigis, desculpe... jenkin...
desculpe, diana, henry, lucy...>]]
  },
  AvgDialog_18856_Content_57 = {
    Text = "Ela se encolheu, abraçando a cabeça, seus sussurros tristes tornando-se roucos e confusos, difíceis de entender"
  },
  AvgDialog_18856_Content_58 = {
    Text = "Senhorita Sarah...?"
  },
  AvgDialog_18856_Content_59 = {
    Text = "A oficina iluminada e barulhenta parecia ter mergulhado nas profundezas da água, caindo instantaneamente em um silêncio gélido e mortal.\nA pressão invisível veio de repente, você respirou fundo, percebendo que algo estava errado"
  },
  AvgDialog_18856_Content_6 = {
    Text = "Eles vestem uniformes desconhecidos, com cara de poucos amigos, e depois de uma olhada, disseram que Lucy é suspeita, não conseguimos impedir"
  },
  AvgDialog_18856_Content_60 = {
    Text = "Droga, Ramona, faça os outros saírem!"
  },
  AvgDialog_18856_Content_61 = {
    Text = "É tarde demais.\nA cabeça do jovem administrador se abriu como uma flor, e o líquido negro espirrou no chão"
  },
  AvgDialog_18856_Content_62 = {
    Text = "Srta. Sarah!!"
  },
  AvgDialog_18856_Content_63 = {
    Text = "Ela soltou um grito agudo, e ao longe, alguns gritos responderam.\nCorpos distorcidos e corrompidos saíram correndo do prédio"
  },
  AvgDialog_18856_Content_7 = {
    Text = "Como pode ser a Lucy?! Claramente"
  },
  AvgDialog_18856_Content_8 = {
    Text = "Henry e Manny estão segurando a porta, não sei quanto tempo vão aguentar, rápido!"
  },
  AvgDialog_18856_Content_9 = {
    Text = "Sarah immediately lifted her skirt and ran out"
  },
  AvgDialog_18857_Content_1 = {
    Text = "Noite sem Pássaros"
  },
  AvgDialog_18857_Content_10 = {
    Text = "Como se não a visse, a garota continuou andando, passo a passo"
  },
  AvgDialog_18857_Content_11 = {
    Text = "Quando ela passou, Aigis ouviu uma canção extremamente sutil"
  },
  AvgDialog_18857_Content_12 = {
    Text = "Velho Charlie tem um gato malhado que ele ama muito"
  },
  AvgDialog_18857_Content_13 = {
    Text = "Lucy, para onde você está indo? Me dê a faca, Lucy!"
  },
  AvgDialog_18857_Content_14 = {
    Text = "Está tão frio... Aqui é... lá fora? Como cheguei aqui?"
  },
  AvgDialog_18857_Content_15 = {
    Text = "Eu estava dormindo no quarto, mas o pequeno Mike continuava fazendo barulho... Meus olhos doem"
  },
  AvgDialog_18857_Content_16 = {
    Text = "Louco... Louco! Não se aproxime! Fique longe!"
  },
  AvgDialog_18857_Content_17 = {
    Text = "Senhora, precisa de ajuda? Não tenha medo, vou chamar alguém—"
  },
  AvgDialog_18857_Content_18 = {
    Text = "Socorro! Alguém! Me ajude!"
  },
  AvgDialog_18857_Content_19 = {
    Text = "Eu, não consigo me mexer?! Por que, por que meu corpo não se move?"
  },
  AvgDialog_18857_Content_2 = {
    Text = "O vapor se condensou em uma névoa densa, tornando o corredor estreito ainda mais sombrio, até ser completamente engolido pela escuridão"
  },
  AvgDialog_18857_Content_20 = {
    Text = "Recuperou a consciência, que criança especial"
  },
  AvgDialog_18857_Content_21 = {
    Text = "Quem é você? O que vai fazer com essa senhora?"
  },
  AvgDialog_18857_Content_22 = {
    Text = "Eu? Não, não, você está errado, não sou eu que vai fazer algo com ela"
  },
  AvgDialog_18857_Content_23 = {
    Text = "Eu, minha mão"
  },
  AvgDialog_18857_Content_24 = {
    Text = "Você vai fazer algo com ela"
  },
  AvgDialog_18857_Content_25 = {
    Text = "Não me mate, <Big:por favor, não me mate!>"
  },
  AvgDialog_18857_Content_26 = {
    Text = "Não fui eu, não fui eu! Largue a faca! Corra, corra!"
  },
  AvgDialog_18857_Content_27 = {
    Text = "<BigShake:AHHH—!>"
  },
  AvgDialog_18857_Content_28 = {
    Text = "Desculpa... desculpa"
  },
  AvgDialog_18857_Content_29 = {
    Text = "Corram, corram!"
  },
  AvgDialog_18857_Content_3 = {
    Text = "A vela luta para iluminar uma pequena área no ar úmido. No fim da luz, algo se aproxima na escuridão"
  },
  AvgDialog_18857_Content_30 = {
    Text = "Velho Charlie tem um gato malhado que ele ama muito"
  },
  AvgDialog_18857_Content_31 = {
    Text = "Minhas pernas, minhas pernas não se movem, me ajude! Me ajude!"
  },
  AvgDialog_18857_Content_32 = {Text = "Senhorita!"},
  AvgDialog_18857_Content_33 = {
    Text = "Senpai, não vá, senpai!"
  },
  AvgDialog_18857_Content_34 = {
    Text = "Por favor, misterioso senhor, não faça isso."
  },
  AvgDialog_18857_Content_35 = {
    Text = "Um dia ela desapareceu, e ele a procurou por toda parte"
  },
  AvgDialog_18857_Content_36 = {
    Text = "Contate a escola!"
  },
  AvgDialog_18857_Content_37 = {
    Text = "Eu não quero machucá-los, por favor, eu farei tudo o que pedir, só — não os machuquem"
  },
  AvgDialog_18857_Content_38 = {
    Text = "Ele revirou o armário. Ele conferiu debaixo da cama."
  },
  AvgDialog_18857_Content_39 = {
    Text = "<Shake:S-Senpai... p-por trás de você!>"
  },
  AvgDialog_18857_Content_4 = {
    Text = "Os sussurros se transformam em passos leves, uma sombra se aproxima lentamente da ilha solitária"
  },
  AvgDialog_18857_Content_40 = {
    Text = "Ele deu uma volta no porão onde a caldeira estava acesa"
  },
  AvgDialog_18857_Content_41 = {Text = "Ah... ah!!"},
  AvgDialog_18857_Content_42 = {
    Text = "Por favor! Senhor! Por favor, não! Não, não, não!"
  },
  AvgDialog_18857_Content_43 = {
    Text = "Velho Charlie não consegue encontrar seu gato malhado em lugar nenhum"
  },
  AvgDialog_18857_Content_44 = {
    Text = "<Shake:Não, não, não se aproxime... Não se aproxime... Por favor, por favor, me deixe...>"
  },
  AvgDialog_18857_Content_45 = {
    Text = "Então ele chorou e chorou—"
  },
  AvgDialog_18857_Content_46 = {
    Text = "<Shake:Eu tenho uma irmã... por favor... não me mate...>"
  },
  AvgDialog_18857_Content_47 = {
    Text = "——Até desaparecer também"
  },
  AvgDialog_18857_Content_48 = {
    Text = "<BigShake:Aaaah!>"
  },
  AvgDialog_18857_Content_49 = {Text = "Não..."},
  AvgDialog_18857_Content_5 = {
    Text = "Pequena Lucy, onde você foi? Você saiu à noite por tanto tempo que fiquei preocupado—"
  },
  AvgDialog_18857_Content_50 = {
    Text = "Por quê... o que fizemos de errado... por que temos que passar por isso"
  },
  AvgDialog_18857_Content_51 = {
    Text = "Xiao Mike estava com uma expressão séria, olhando para frente, segurando uma faca ensanguentada, com a roupa encharcada de sangue pingando líquido viscoso"
  },
  AvgDialog_18857_Content_52 = {
    Text = "Atrás dele havia uma porta aberta, e do lado de fora podia-se ver um corpo mutilado deitado no quarto"
  },
  AvgDialog_18857_Content_53 = {
    Text = "Todos ouviram aquela voz, mas ninguém se lembra. Se, se a voz for atrás de Jenkins"
  },
  AvgDialog_18857_Content_54 = {
    Text = "Pobre criança, você está tentando fazer algo fútil novamente?"
  },
  AvgDialog_18857_Content_55 = {
    Text = "...!\nÉ você...! Vilão! Não controle o Mike!"
  },
  AvgDialog_18857_Content_56 = {
    Text = "Não o controle mais! Ou, ou eu vou contar—contar"
  },
  AvgDialog_18857_Content_57 = {
    Text = "Dizer a quem, à sua querida senhorita Sarah?\nAigis, você esqueceu como ela reagiu na última vez que você falou com ela?"
  },
  AvgDialog_18857_Content_58 = {Text = "..."},
  AvgDialog_18857_Content_59 = {
    Text = "Ela acha que você está tendo um pesadelo ou vendo uma alucinação, pronta para mandá-lo para \"exame\".  \nAs provas que você apresentou foram tratadas como lixo deixado pelo doutor \"diagnosticando pacientes\""
  },
  AvgDialog_18857_Content_6 = {Text = "!!"},
  AvgDialog_18857_Content_60 = {
    Text = "Ver você tão triste me machuca, mas essa é a cruel realidade.\nSe seus olhos não fossem úteis, eu te libertaria e te transformaria em uma bela criação"
  },
  AvgDialog_18857_Content_61 = {
    Text = "Agora, continue fazendo o que estava fazendo: limpe as marcas, queime as provas.\nÉ só isso que você sabe fazer"
  },
  AvgDialog_18857_Content_62 = {
    Text = "O menino caminhou sem expressão para longe.\nAigis entrou na sala e se ajoelhou ao lado do corpo do segurança, que ainda tinha um pouco de calor"
  },
  AvgDialog_18857_Content_63 = {
    Text = "Ela removeu a venda, e as pontas dos dedos do homem endureceram e ficaram brancas, parecendo uma escultura de pedra. Um objeto metálico redondo rolou da mão endurecida, e Aigis estava prestes a pegá-lo quando ouviu um grito atrás de si"
  },
  AvgDialog_18857_Content_64 = {
    Text = "A, Aigis...?!"
  },
  AvgDialog_18857_Content_65 = {
    Text = "Eu matei aquela pessoa, e quando estava lidando com o corpo, a Srta. Sarah viu"
  },
  AvgDialog_18857_Content_66 = {
    Text = "Ela me puxou para fora, limpou o sangue das minhas mãos e disse que tudo ficaria bem, que eu deveria deixar com ela"
  },
  AvgDialog_18857_Content_67 = {
    Text = "Acabei de ver, o quarto está limpo, deve ter sido a Srta. Sarah que limpou.\nE além disso—"
  },
  AvgDialog_18857_Content_68 = {
    Text = "Ela tirou um botão brilhante do ursinho de pelúcia e mostrou para vocês.\nO estilo e o material eram idênticos aos que vocês encontraram ontem"
  },
  AvgDialog_18857_Content_69 = {
    Text = "Vocês encontraram, eu perdi meu botão de punho lá"
  },
  AvgDialog_18857_Content_7 = {
    Text = "A sombra foi gradualmente iluminada. Era uma criança, sem expressão, olhando para frente, segurando uma faca afiada com a ponta ainda pingando sangue"
  },
  AvgDialog_18857_Content_70 = {
    Text = "Eu não acredito. Independentemente de você ter ou não motivos, você não é assim, Aigis.\nVocê é uma boa criança, diga-nos a verdade, e encontraremos uma solução juntos, certo?"
  },
  AvgDialog_18857_Content_71 = {
    Text = "...\nEu não contei a vocês como Tiyug morreu"
  },
  AvgDialog_18857_Content_72 = {
    Text = "Aigis retirou a venda do seu olho direito, revelando um olho pálido como uma escultura"
  },
  AvgDialog_18857_Content_73 = {Text = "Sou eu."},
  AvgDialog_18857_Content_74 = {
    Text = "Transformei-o em pedra"
  },
  AvgDialog_18857_Content_75 = {
    Text = "Aigis, nós—"
  },
  AvgDialog_18857_Content_76 = {
    Text = "Pare de falar! Eu... sou o verdadeiro culpado."
  },
  AvgDialog_18857_Content_77 = {
    Text = "Ela deu um passo para trás enquanto um muco negro, que apareceu do nada, se movia ao seu redor"
  },
  AvgDialog_18857_Content_8 = {
    Text = "<Shake:Isso... isso... Lucy...? Você... matou...?>"
  },
  AvgDialog_18857_Content_9 = {
    Text = "Ela não conseguiu evitar e se virou, vomitando todo o jantar frugal no canto da parede"
  },
  AvgDialog_18858_Content_1 = {
    Text = "Aqueles são... os pacientes? As pessoas que Aigis disse ter coisas negras? É assim que eles ficam?"
  },
  AvgDialog_18858_Content_2 = {
    Text = "Essas são as pessoas... desaparecidas?"
  },
  AvgDialog_18859_Content_1 = {
    Text = "No espaço negro, pontos brilhantes de prata se conectam, flutuando como ondas"
  },
  AvgDialog_18859_Content_10 = {
    Text = "Os pontos de luz se afastam de repente, e o espaço negro se dissipa rapidamente"
  },
  AvgDialog_18859_Content_11 = {
    Text = "Você abre os olhos e encontra o olhar confuso de Jenkins"
  },
  AvgDialog_18859_Content_12 = {
    Text = "01:14，Lilian Atelier\nQuarto de hóspedes"
  },
  AvgDialog_18859_Content_13 = {
    Text = "%player%... o que aconteceu?"
  },
  AvgDialog_18859_Content_14 = {
    Text = "Jenkins esfregou os olhos e tentou se levantar, mas percebeu que suas mãos estavam amarradas atrás das costas"
  },
  AvgDialog_18859_Content_15 = {
    Text = "O que está acontecendo?! Quem fez isso, solte-me agora!"
  },
  AvgDialog_18859_Content_16 = {
    Text = "Você acena para Ramona, que saca a espada e corta a corda no pulso de Jenkins"
  },
  AvgDialog_18859_Content_17 = {
    Text = "Desculpe, a situação é urgente, tivemos que tomar algumas medidas de proteção.\nVocê... lembra o que fez agora há pouco?"
  },
  AvgDialog_18859_Content_18 = {
    Text = "Eu estava dormindo com Brown e Aigis, tive um sonho confuso... Espera, isso não é o quarto de Aigis, como cheguei aqui?"
  },
  AvgDialog_18859_Content_19 = {
    Text = "Vocês, me trouxeram aqui para quê? Vão me sequestrar e me matar?"
  },
  AvgDialog_18859_Content_2 = {
    Text = "Você está entre eles, mas também acima deles. Você é um deles, mas não se encaixa. \nVocê não sabe exatamente o que eles são, só sabe que está aqui para encontrar alguém"
  },
  AvgDialog_18859_Content_20 = {
    Text = "Isso não condiz com o estilo e as regras dos investigadores da Universidade de Mythag"
  },
  AvgDialog_18859_Content_22 = {
    Text = "A espada de Ramona saiu da bainha em um instante. A lâmina prateada estava no pescoço de Clementine, que não mostrou medo e afastou a espada com dois dedos"
  },
  AvgDialog_18859_Content_23 = {
    Text = "Você observa cautelosamente a mulher à sua frente—sem portas ou janelas abertas, ela apareceu do nada. Silenciosa como um fantasma"
  },
  AvgDialog_18859_Content_24 = {
    Text = "Quem é você? Como sabe nossa identidade?"
  },
  AvgDialog_18859_Content_25 = {
    Text = "Você é um membro dos escultores? E há pouco, na névoa, suas asas...\nVocê - é humana?"
  },
  AvgDialog_18859_Content_26 = {
    Text = "Sou apenas uma terceira parte útil, embora tenha algum interesse pessoal.\nVocê me intriga, Investigador especial."
  },
  AvgDialog_18859_Content_27 = {
    Text = "Ela sorriu para você, com um olhar que continha um fervor estranho"
  },
  AvgDialog_18859_Content_28 = {
    Text = "...Por que?"
  },
  AvgDialog_18859_Content_29 = {
    Text = "Isso não é algo que eu possa comentar.\nApenas a entidade suprema pode te dar a resposta que deseja"
  },
  AvgDialog_18859_Content_3 = {
    Text = "\"Irmã... irmã...\""
  },
  AvgDialog_18859_Content_30 = {
    Text = "Mas como compensação, não me importo de responder sua pergunta anterior.\nComo você pensou, o coração humano é feito de carne e sangue, mas eu, eu tenho um coração de prata"
  },
  AvgDialog_18859_Content_31 = {
    Text = "Já que é assim, não podemos deixá-lo ir"
  },
  AvgDialog_18859_Content_32 = {
    Text = "Se eu estivesse sozinho, claro que adoraria ir com vocês.\nMas tenho que pensar nos meus pacientes, eles não podem ficar sem mim agora"
  },
  AvgDialog_18859_Content_33 = {
    Text = "Clementine tirou um pingente estranho de algum lugar e o balançou levemente, e um cansaço esmagador caiu sobre você. Você se apoiou na mesa, mal conseguindo ficar de pé, sem conseguir dar um passo"
  },
  AvgDialog_18859_Content_34 = {
    Text = "A espada de Ramona caiu, sua cabeça balançava levemente, quase não conseguia manter os olhos abertos.\nJenkins estava deitado no chão, imóvel, aparentemente adormecido"
  },
  AvgDialog_18859_Content_35 = {
    Text = "O que... você fez..."
  },
  AvgDialog_18859_Content_36 = {
    Text = "Um pequeno truque que me permite sair daqui.  \nCom a sua capacidade, deve ser fácil para você acabar com isso, certo?"
  },
  AvgDialog_18859_Content_37 = {
    Text = "Adeus, <Blue:olho cego pálido>, nós aqui... ainda teremos um encontro"
  },
  AvgDialog_18859_Content_38 = {
    Text = "Ela fez uma reverência e saiu do quarto. Você não conseguiu mais se segurar e caiu na cadeira"
  },
  AvgDialog_18859_Content_39 = {
    Text = "Clementine fechou a porta, cantarolando uma música alegre, acenou para o corredor e foi embora"
  },
  AvgDialog_18859_Content_4 = {
    Text = "Você olha na direção do som; um ponto de luz extraordinariamente fraco brilha no mar de estrelas. Fios pretos com um brilho metálico estranho o envolvem, puxando-o e deixando-o incapaz de se mover"
  },
  AvgDialog_18859_Content_40 = {
    Text = "Na escuridão, uma garota de vestido estava quieta como uma estátua.\nEla abaixou a cabeça, segurando uma venda branca"
  },
  AvgDialog_18859_Content_5 = {
    Text = "Daquela linha preta vinha uma melodia alegre, como uma canção de ninar cantada por crianças.\nO velho Charlie tinha um gato malhado que ele amava muito"
  },
  AvgDialog_18859_Content_6 = {
    Text = "\"Irmã... não vá...\""
  },
  AvgDialog_18859_Content_7 = {
    Text = "A voz de Jenkins veio do globo de luz. Tentou se aproximar de você, mas foi puxada para trás por fios negros, como uma marionete controlada"
  },
  AvgDialog_18859_Content_8 = {
    Text = "Você entende imediatamente, alguém ou algo está controlando ela.\nVocê tenta libertá-la, mas os fios negros se afinam e desaparecem"
  },
  AvgDialog_18859_Content_9 = {
    Text = "\"Não... Aigis...?\""
  },
  AvgDialog_18860_Content_1 = {
    Text = "Vocês seguem Aigis até o topo da torre do relógio"
  },
  AvgDialog_18860_Content_2 = {
    Text = "Aigis parou no palco, virou-se, e as lágrimas tingidas de fluído de dissolução misturadas a sangue escorriam de seus olhos cobertos"
  },
  AvgDialog_18860_Content_3 = {
    Text = "Desculpa... eu... não consigo mais resistir"
  },
  AvgDialog_18860_Content_4 = {
    Text = "Seu corpo incha rapidamente, a pele borbulha com protuberâncias redondas, bloqueando a escada e alcançando o teto"
  },
  AvgDialog_18860_Content_5 = {
    Text = "No som horrível de membros se torcendo, a voz da garota mal se mantém"
  },
  AvgDialog_18860_Content_6 = {
    Text = "<Shake:Corra...>"
  },
  AvgDialog_18861_Content_1 = {
    Text = "Não julgue um livro pela capa"
  },
  AvgDialog_18861_Content_10 = {
    Text = "Um dia ela desapareceu, e ele a procurou por toda parte"
  },
  AvgDialog_18861_Content_11 = {
    Text = "Corra! Não se preocupe conosco! Vá contatar a escola!"
  },
  AvgDialog_18861_Content_12 = {
    Text = "Ele revirou o armário. Ele conferiu debaixo da cama."
  },
  AvgDialog_18861_Content_13 = {
    Text = "<Shake:S-Senpai... p-por trás de você!>"
  },
  AvgDialog_18861_Content_15 = {
    Text = "Garras negras rasgam a névoa, agarrando o cabelo da mulher"
  },
  AvgDialog_18861_Content_16 = {
    Text = "A fita vermelha cai lentamente, o contorno de um grande olho aparece na sombra"
  },
  AvgDialog_18861_Content_17 = {
    Text = "Ele deu uma volta no porão onde a caldeira estava acesa"
  },
  AvgDialog_18861_Content_18 = {
    Text = "Os olhos piscam ao ritmo da canção infantil, e o rosto do jovem endurece e descolore naquele instante.\nEle abre a boca, e seu grito se solidifica junto com seu corpo em uma estátua"
  },
  AvgDialog_18861_Content_19 = {Text = "Ah... ah!!"},
  AvgDialog_18861_Content_2 = {
    Text = "A névoa densa engoliu o bairro úmido e sombrio, a luz amarelada refletida nas poças parecia olhar para este mundo obscuro"
  },
  AvgDialog_18861_Content_20 = {
    Text = "Velho Charlie não consegue encontrar seu gato malhado em lugar nenhum"
  },
  AvgDialog_18861_Content_21 = {
    Text = "<Shake:Não, não, por favor... Por favor, me deixe...>"
  },
  AvgDialog_18861_Content_22 = {
    Text = "Então ele chorou e chorou—"
  },
  AvgDialog_18861_Content_23 = {
    Text = "<Shake:Eu tenho uma irmã... por favor... não me mate...>"
  },
  AvgDialog_18861_Content_24 = {
    Text = "——Até desaparecer também"
  },
  AvgDialog_18861_Content_25 = {
    Text = "<BigShake:Aaaah!>"
  },
  AvgDialog_18861_Content_26 = {
    Text = "08:00，Universidade de Mythag, Edifício de Despertar\nNo escritório de William de Lapoule"
  },
  AvgDialog_18861_Content_27 = {
    Text = "Você está sentado à mesa, sob o olhar de William, examinando os itens na bandeja à sua frente:\nUma mão esculpida em pedra, incrivelmente realista, e uma fita de cetim vermelha com um fecho de prata"
  },
  AvgDialog_18861_Content_28 = {Text = "Como está"},
  AvgDialog_18861_Content_29 = {
    Text = "Você está nervoso. William não é apenas seu veterano, mas também seu instrutor.\nMesmo sendo um guardião oficial, ainda sente que está sendo avaliado por ele"
  },
  AvgDialog_18861_Content_3 = {
    Text = "Um sapato esmagou o reflexo na água parada e saiu apressado"
  },
  AvgDialog_18861_Content_30 = {
    Text = "Isso deve ser parte da estátua. Mas uma estátua oca, é a primeira vez que vejo.\nE dentro... é sangue?"
  },
  AvgDialog_18861_Content_31 = {
    Text = "Isto está relacionado àqueles dois alunos que saíram correndo da escola, certo?"
  },
  AvgDialog_18861_Content_32 = {
    Text = "Exato. Há cinco dias, dois alunos saíram da escola sem permissão, indo para <Blue:Londinium Leste>, com a intenção de investigar <Red:\"caso de assassinato em série de desmembramento\">"
  },
  AvgDialog_18861_Content_33 = {
    Text = "Era noite, e os dois ouviram um grito de socorro na Bernard Road, perto de <Blue: Oficina de Lily>, foram verificar e descobriram que uma mulher estava sendo perseguida por <Yellow: um ser de vida desconhecida>"
  },
  AvgDialog_18861_Content_34 = {
    Text = "Dois alunos seguiram o lema da escola e tentaram resgatar, mas foram atacados. No final, um aluno do primeiro ano conseguiu escapar e voltou à escola há quatro dias, enquanto o aluno do segundo ano está desaparecido"
  },
  AvgDialog_18861_Content_35 = {
    Text = "Três dias atrás, um calouro despertou do desmaio e narrou os eventos.\nEle nos disse que a criatura parece ter a capacidade de petrificar, transformando as pernas das mulheres em pedra"
  },
  AvgDialog_18861_Content_36 = {
    Text = "Petrificação? Isso significa que esta estátua é... parte do estudante desaparecido?"
  },
  AvgDialog_18861_Content_37 = {
    Text = "Os sobreviventes são irreconhecíveis, mas é bem possível.\nQuanto a esta fita, provavelmente pertence à vítima feminina"
  },
  AvgDialog_18861_Content_38 = {
    Text = "Houve alguma descoberta do <Yellow:Fenômeno d> no local? Com uma habilidade tão única, suspeito que a forma de vida não identificada poderia ser uma nova <Yellow:Clades>."
  },
  AvgDialog_18861_Content_39 = {
    Text = "Essa é a parte estranha. Clades, como o núcleo de <Yellow:D-Rifts>, deveria <Yellow:Dissolver indiscriminadamente>. Nunca ouvi falar deles atacando proativamente."
  },
  AvgDialog_18861_Content_4 = {
    Text = "Rápido! Está quase nos alcançando!"
  },
  AvgDialog_18861_Content_40 = {
    Text = "Além disso, exceto por uma quantidade pequena de <Yellow: limo d>, não conseguimos encontrar marcas de dissolução visíveis no local, nem mesmo em toda a área leste, o que não está de acordo com as <Yellow: características de dissolução> da fenda d"
  },
  AvgDialog_18861_Content_41 = {
    Text = "Atualmente, podemos confirmar que: os casos de desaparecimento recentemente ocorridos na <Blue: oficina de trabalho de Lilian> e suas áreas circunvizinhas, inclusive o caso <Red: \"desmembrador\">, podem estar relacionados a aquela entidade"
  },
  AvgDialog_18861_Content_42 = {
    Text = "Após uma análise preliminar, concluímos que é altamente provável que a entidade de vida desconhecida esteja escondida na oficina de trabalho de Lilian"
  },
  AvgDialog_18861_Content_43 = {
    Text = "Parece que precisamos ir até lá"
  },
  AvgDialog_18861_Content_44 = {
    Text = "Exato. Confirmar o paradeiro dos alunos desaparecidos, esclarecer a verdade por trás do incidente, localizar e impedir o autor do evento, esse é seu objetivo nesta missão"
  },
  AvgDialog_18861_Content_45 = {
    Text = "Como está, %player%, consegue fazer isso?"
  },
  AvgDialog_18861_Content_46 = {Text = "Moleza"},
  AvgDialog_18861_Content_47 = {
    Text = "Farei o meu melhor."
  },
  AvgDialog_18861_Content_48 = {
    Text = "Muito bem. Considerando que o alvo pode ser inteligente, sugiro que peguem disfarces no departamento de logística antes de partir, para não alertar o inimigo"
  },
  AvgDialog_18861_Content_49 = {
    Text = "Leve esta fita de cetim, talvez possamos descobrir por que a entidade desconhecida atacou seu dono e, se possível, confirmar a identidade da vítima"
  },
  AvgDialog_18861_Content_5 = {
    Text = "Três pessoas correm na névoa, respirando pesadamente, como ratos perseguidos por um gato sob uma canção alegre"
  },
  AvgDialog_18861_Content_50 = {
    Text = "A periculosidade da missão não é alta, manteremos as comunicações abertas; <Blue:boneca> e <Blue:erica> estarão sempre prontos para oferecer orientação e ajuda a você"
  },
  AvgDialog_18861_Content_51 = {
    Text = "Você toca o emblema da escola no peito, onde está incrustado um <Blue:fragmento de núcleo de prata>, garantindo a comunicação à distância"
  },
  AvgDialog_18861_Content_52 = {
    Text = "Sem demora, partam imediatamente"
  },
  AvgDialog_18861_Content_53 = {
    Text = "Que a Chave de prata ilumine o meu caminho."
  },
  AvgDialog_18861_Content_54 = {
    Text = [[
