  AvgDialog_18861_Content_64 = {
    Text = [[
13:10, Distrito Leste de Lentini
Uma rua]]
  },
  AvgDialog_18861_Content_65 = {
    Text = "Assim que você desceu do carro, foi sufocado pela umidade pesada e pelo cheiro de podridão"
  },
  AvgDialog_18861_Content_66 = {
    Text = "Uma forte tontura e zumbido nos ouvidos te atingem de repente. Imagens borradas passam pela sua mente, como se você já tivesse visto isso antes"
  },
  AvgDialog_18861_Content_67 = {
    Text = "É uma ilusão ou é parte da memória que você perdeu?\nAntes que você possa se lembrar, uma criança brincalhona esbarra em você"
  },
  AvgDialog_18861_Content_68 = {Text = "!"},
  AvgDialog_18861_Content_69 = {
    Text = "Você segura o braço dolorido, notando que Ramona te observa com um sorriso enigmático"
  },
  AvgDialog_18861_Content_7 = {
    Text = "Minhas pernas, minhas pernas não se movem, me ajude! Me ajude!"
  },
  AvgDialog_18861_Content_70 = {
    Text = "Qual é o problema?"
  },
  AvgDialog_18861_Content_71 = {
    Text = "Ela apontou para o seu bolso. Você seguiu a direção do dedo dela e de repente lembrou de uma frase.\n\"O ritual de boas-vindas mais infame do Leste é fazer sua carteira desaparecer sem que você perceba.\""
  },
  AvgDialog_18861_Content_72 = {
    Text = "Não pode ser... Minha carteira!"
  },
  AvgDialog_18861_Content_73 = {
    Text = "Apresse-se, %player%, ou você não conseguirá comprar cupcakes este mês."
  },
  AvgDialog_18861_Content_8 = {Text = "Senhorita!"},
  AvgDialog_18861_Content_9 = {
    Text = "Senpai, não vá, senpai!"
  },
  AvgDialog_18862_Content_1 = {
    Text = "Ramona bloqueou o ataque de Aigis. Aigis cambaleou para trás, tremendo, com líquido negro escorrendo pelos dedos que cobriam os olhos"
  },
  AvgDialog_18862_Content_10 = {
    Text = "Não se aproxime... não se aproxime!"
  },
  AvgDialog_18862_Content_11 = {
    Text = "A menina virou-se e correu"
  },
  AvgDialog_18862_Content_12 = {Text = "Aigis!"},
  AvgDialog_18862_Content_13 = {
    Text = "Pare de gritar, corra!"
  },
  AvgDialog_18862_Content_2 = {
    Text = "Aigis, você está bem?"
  },
  AvgDialog_18862_Content_3 = {
    Text = "Ela levantou a cabeça de repente, com o olhar ora vago, ora claro"
  },
  AvgDialog_18862_Content_4 = {
    Text = "Co-como pode... Não, eu não estava dormindo, não"
  },
  AvgDialog_18862_Content_5 = {Text = "Aigis?"},
  AvgDialog_18862_Content_6 = {
    Text = "Não fale, não, não, ainda não escureceu, não há neblina, você não pode me controlar, não pode...!"
  },
  AvgDialog_18862_Content_7 = {
    Text = "Aigis cobriu a cabeça, seu pequeno corpo se inclinando para frente em uma dor inexplicável"
  },
  AvgDialog_18862_Content_8 = {
    Text = "Não... me transforme em estátua de cera... Eu não quero, eu não quero"
  },
  AvgDialog_18862_Content_9 = {
    Text = "Você ouviu algo? Aigis, Aigis?"
  },
  AvgDialog_18863_Content_1 = {
    Text = "***Ela parecia normal, como pode ter enlouquecido! Aigis, cuidado, afaste-se!"
  },
  AvgDialog_18863_Content_2 = {
    Text = "Ela disse que recebeu tratamento, provavelmente foi naquela época...\nDe qualquer forma, precisamos levá-la a um lugar mais isolado"
  },
  AvgDialog_18863_Content_3 = {
    Text = "Antes disso, vamos lidar com esses caras"
  },
  AvgDialog_18864_Content_1 = {
    Text = "Você e Ramona combatiam e recuavam, recuando para o pátio da oficina sem perturbar os outros"
  },
  AvgDialog_18864_Content_2 = {
    Text = "Está nevoeiro de novo!"
  },
  AvgDialog_18864_Content_3 = {
    Text = "Uma névoa densa de origem desconhecida cobriu tudo, trazendo gritos estranhos que se aproximam de onde a visão não alcança"
  },
  AvgDialog_18864_Content_4 = {
    Text = "Você e Ramona ficaram de costas um para o outro, observando as sombras distorcidas com cautela"
  },
  AvgDialog_18864_Content_5 = {
    Text = "Como pode haver Mutantes aqui? Os pacientes não estavam trancados?"
  },
  AvgDialog_18864_Content_6 = {
    Text = "Não importa de onde vieram, apenas derrote-os!"
  },
  AvgDialog_18864_Content_7 = {
    Text = "Ramona balançou a espada fina e partiu em direção aos monstros mais próximos a vocês"
  },
  AvgDialog_18865_Content_1 = {
    Text = "Os Mutantes caíram diante da lâmina de Ramona, rapidamente se desfazendo em fina poeira negra que se dissipou no ar."
  },
  AvgDialog_18865_Content_10 = {
    Text = "Você respirou fundo e se endireitou"
  },
  AvgDialog_18865_Content_11 = {
    Text = "Cuidado, Ramona."
  },
  AvgDialog_18865_Content_12 = {
    Text = "Não se preocupe, eu conheço meus limites."
  },
  AvgDialog_18865_Content_2 = {
    Text = "Você limpa o suor da testa, piscando com força enquanto respira pesadamente"
  },
  AvgDialog_18865_Content_3 = {
    Text = "Você está bem?"
  },
  AvgDialog_18865_Content_4 = {
    Text = "Tudo bem. Só estou com um pouco de dor de cabeça"
  },
  AvgDialog_18865_Content_5 = {
    Text = "Minha cabeça vai explodir pelos olhos"
  },
  AvgDialog_18865_Content_6 = {
    Text = "Ainda brincando, parece que não é nada sério"
  },
  AvgDialog_18865_Content_7 = {
    Text = "Precisa de um descanso?"
  },
  AvgDialog_18865_Content_8 = {
    Text = "Melhor encontrar Jenkins rápido, algo não está certo"
  },
  AvgDialog_18865_Content_9 = {
    Text = "Uma pequena figura emerge da névoa, joelhos dobrados, corpo tenso, pronta para atacar"
  },
  AvgDialog_18866_Content_1 = {
    Text = "E... não há ninguém lá, você deve estar vendo coisas"
  },
  AvgDialog_18866_Content_2 = {
    Text = "Senhorita Mary, para onde você está indo? Oh, Senhorita Mary!"
  },
  AvgDialog_18867_Content_1 = {Text = "%player%!"},
  AvgDialog_18867_Content_10 = {
    Text = "Srta. Sarah, estou com medo, por favor"
  },
  AvgDialog_18867_Content_11 = {
    Text = "Senhorita Sarah..."
  },
  AvgDialog_18867_Content_12 = {
    Text = "Qual é o problema, Aigis?"
  },
  AvgDialog_18867_Content_13 = {
    Text = "Srta. Sarah, você pode cantar aquela música de novo, só uma vez? Quero dizer, se não for incomodar"
  },
  AvgDialog_18867_Content_14 = {
    Text = "Querida pequena Aigis, ouça bem, você é a criança mais obediente e compreensiva de toda a oficina. É a mais querida de todos"
  },
  AvgDialog_18867_Content_15 = {
    Text = "Então, às vezes ser teimoso não é problema. Entendeu?"
  },
  AvgDialog_18867_Content_16 = {
    Text = "E... eu, eu quero ouvir a Srta. Sarah cantar a canção de ninar novamente"
  },
  AvgDialog_18867_Content_17 = {
    Text = [[
Sem problema.
O velho Charlie tem um gato malhado que ele ama muito]]
  },
  AvgDialog_18867_Content_18 = {
    Text = "Você abre os olhos abruptamente, caindo no mundo real cheio de cores"
  },
  AvgDialog_18867_Content_19 = {
    Text = "%player%, você está bem?"
  },
  AvgDialog_18867_Content_2 = {
    Text = "Enquanto Ramona mantém Sarah à distância, você se concentra e se afunda naquele espaço negro familiar"
  },
  AvgDialog_18867_Content_20 = {
    Text = "Você acenou com a cabeça, lutando contra a tontura.\nNesse momento, viu uma figura branca pelo canto do olho"
  },
  AvgDialog_18867_Content_21 = {
    Text = "Aigis? Isso é perigoso, volte e procure Jenkin"
  },
  AvgDialog_18867_Content_22 = {
    Text = "Srta. Sarah, está dormindo?"
  },
  AvgDialog_18867_Content_23 = {Text = "...?"},
  AvgDialog_18867_Content_24 = {
    Text = "Tudo bem, a Srta. Sarah não dorme bem há muito tempo"
  },
  AvgDialog_18867_Content_25 = {
    Text = "Para evitar a dissolução da oficina, ela sempre corre por aí, visitando aqueles senhores e senhoras ricas que moram no castelo, sem tempo para comer ou descansar"
  },
  AvgDialog_18867_Content_26 = {
    Text = "Ao voltar para a oficina à noite, ela acende uma vela no escritório, contando e contando, para ver se o dinheiro conseguido com o patrão é suficiente"
  },
  AvgDialog_18867_Content_27 = {
    Text = "Vamos ver quanto podemos conseguir com as joias que pegamos das damas"
  },
  AvgDialog_18867_Content_28 = {
    Text = "Eles riam dela e diziam coisas cruéis, mas a Srta. Sarah nunca se irritava. Ela ainda me consolava e cantava para nós"
  },
  AvgDialog_18867_Content_29 = {
    Text = "Ela nos trata bem, realmente. Ela também me trata muito bem."
  },
  AvgDialog_18867_Content_3 = {
    Text = "A Chave de Prata zumbiu intensamente, e a escuridão à sua frente mudou várias vezes, até que a luz começou a brilhar nas bordas da sua visão"
  },
  AvgDialog_18867_Content_30 = {
    Text = "Sou um fardo para minha mãe, fui abandonado por ela. O antigo administrador não quis me acolher, foi a senhorita Sarah que se ofereceu para fazer dois trabalhos e me trouxe para cá"
  },
  AvgDialog_18867_Content_31 = {
    Text = "Desde então, jurei que nunca seria um fardo para a Srta. Sarah, que seria uma criança útil"
  },
  AvgDialog_18867_Content_32 = {
    Text = "Desculpa, Srta. Sarah. Eu tentei muito, mas não consegui proteger o pequeno Mike, nem você. Desculpa"
  },
  AvgDialog_18867_Content_33 = {
    Text = "Aigis tocou levemente o rosto de Sarah e então se virou para vocês"
  },
  AvgDialog_18867_Content_34 = {
    Text = "Aigis, você..."
  },
  AvgDialog_18867_Content_35 = {
    Text = "Você quer saber o que aconteceu na noite passada?"
  },
  AvgDialog_18867_Content_36 = {
    Text = "A garota abriu a boca, revelando uma expressão que mal podia ser chamada de sorriso"
  },
  AvgDialog_18867_Content_37 = {
    Text = "Solte a pequena Lucy e a Srta. Sarah.\nEu sou o Jack, o Desmembrador, que vocês procuram"
  },
  AvgDialog_18867_Content_4 = {
    Text = "Irmã Sasa, estou com muita fome"
  },
  AvgDialog_18867_Content_5 = {
    Text = "Lamento, Srta. Sarah, não podemos mais financiar vocês"
  },
  AvgDialog_18867_Content_6 = {
    Text = "Srta. Sarah, por que minha mãe me abandonou?"
  },
  AvgDialog_18867_Content_7 = {
    Text = "Luzes preto e branco piscam, como vários filmes sendo projetados ao mesmo tempo, mas você não consegue ver claramente"
  },
  AvgDialog_18867_Content_8 = {
    Text = "Srta. Sarah, minha mãe disse que sou inútil... Posso realmente fazer essas coisas?"
  },
  AvgDialog_18867_Content_9 = {
    Text = "Srta. Sarah, minha mãe me abandonou, você... você também vai me abandonar?"
  },
  AvgDialog_18868_Content_1 = {
    Text = "Meu Deus... Isso"
  },
  AvgDialog_18868_Content_2 = {
    Text = "Relaxe, Srta. Sarah, o Dr. Miller vai ajudar os pacientes"
  },
  AvgDialog_18868_Content_3 = {
    Text = "Miss Sarah, please reorganize the team. The sooner we finish selecting, the quicker they can receive treatment"
  },
  AvgDialog_18869_Content_1 = {
    Text = "Todos, acalmem-se!"
  },
  AvgDialog_18869_Content_2 = {
    Text = "Estou muito calmo. Pergunte a ele o que fez com Aigis para deixá-la tão assustada!"
  },
  AvgDialog_18869_Content_3 = {
    Text = "O que você sabe! Estamos fazendo isso pelo bem da humanidade!"
  },
  AvgDialog_18870_Content_1 = {
    Text = "Nosso Segredo"
  },
  AvgDialog_18870_Content_10 = {
    Text = "A pesquisa foi realizada.\nDesculpe, não há registros relevantes. Recomendo enviar um pedido de investigação assistida"
  },
  AvgDialog_18870_Content_11 = {
    Text = "Investigadora Ramona, número do comunicador I-3017, oficialmente submeteu para Clementine Fairfex, suspeita de ser um despertador não <Blue:\"O Acordo\">, atualmente disfarçada como psicóloga de George Rogers"
  },
  AvgDialog_18870_Content_12 = {
    Text = "Solicitação de investigação de assistência recebida.\nAprovação concedida, transferida para <Blue:Departamento de Investigação de Miryam>"
  },
  AvgDialog_18870_Content_13 = {
    Text = "Pedido enviado. Deixe o resto com a equipe de investigação.\nAinda falta um tempo para o amanhecer. Quer descansar um pouco?"
  },
  AvgDialog_18870_Content_14 = {
    Text = "Não pode ser! Para convencer a boneca, devemos encontrar pistas revolucionárias rapidamente, ou um suspeito"
  },
  AvgDialog_18870_Content_15 = {
    Text = "Você está falando de Sarah"
  },
  AvgDialog_18870_Content_16 = {
    Text = "O que ela nos deu para beber com certeza não é tão simples quanto chá. Além disso, é difícil para mim acreditar que alguém que viveu tanto tempo na oficina tenha medo de sombras"
  },
  AvgDialog_18870_Content_17 = {
    Text = "Agora ela acha que estamos dormindo, deve baixar a guarda"
  },
  AvgDialog_18870_Content_18 = {
    Text = "Vá. Primeiro, verifique aquele corredor, depois vá ao escritório dela.\nEla será nossa brecha"
  },
  AvgDialog_18870_Content_19 = {
    Text = "01:15，Lilian Atelier\nQuarto de hóspedes"
  },
  AvgDialog_18870_Content_2 = {
    Text = "01:13，Lilian Atelier\nQuarto de hóspedes"
  },
  AvgDialog_18870_Content_20 = {
    Text = "Aigis abriu a porta suavemente e se aproximou de Jenkin, que estava adormecido.\nEla ficou parada por um momento e começou a chorar de forma contida"
  },
  AvgDialog_18870_Content_21 = {
    Text = "Você está bem, que bom...! Desculpe, desculpe, desculpe"
  },
  AvgDialog_18870_Content_22 = {
    Text = "Eu deveria ter vindo mais cedo, eu deveria ter tentado, mesmo sendo um inútil, mesmo que eu... \nA doutora Clementine está certa, mas"
  },
  AvgDialog_18870_Content_23 = {
    Text = "Vou descobrir, vou saber qual é o preço suficiente...\nEu vou conseguir"
  },
  AvgDialog_18870_Content_24 = {
    Text = "Ela saiu silenciosamente, e quando a porta se fechou, Jenkin abriu seus olhos em silêncio."
  },
  AvgDialog_18870_Content_25 = {
    Text = "01:37，Lilian Atelier\nCorredor"
  },
  AvgDialog_18870_Content_26 = {
    Text = "Vocês se aproximam silenciosamente do lugar onde encontraram Sarah e Aigis.\nÉ o fim do corredor, além das paredes e da janela para o pátio, há apenas uma porta digna de nota"
  },
  AvgDialog_18870_Content_27 = {
    Text = "Ramona abriu a porta, a luz da lanterna iluminando a cama e o armário, revelando a poeira flutuante no ar"
  },
  AvgDialog_18870_Content_28 = {
    Text = "Isso é... um quarto antigo?"
  },
  AvgDialog_18870_Content_29 = {
    Text = "Ramona se agachou, passou os dedos pelas fendas dos tijolos e cheirou levemente"
  },
  AvgDialog_18870_Content_3 = {
    Text = "Após um brilho ofuscante da Chave de Prata, você e Ramona se sentiram leves e correram para fora.\nNo corredor, além de vocês dois, não havia ninguém"
  },
  AvgDialog_18870_Content_30 = {
    Text = "Cheiro de sangue, bem fraco, provavelmente foi limpo.\nPela umidade, deve ter sido na última hora"
  },
  AvgDialog_18870_Content_31 = {
    Text = "Ela iluminou o chão ao redor com a lanterna, os restos de água entre os tijolos refletiam levemente, e você até viu um líquido negro sinistro em algumas fendas"
  },
  AvgDialog_18870_Content_32 = {
    Text = "O que aconteceu? Alguém se machucou ou morreu?\nFoi o Desmembrador? Ou uma entidade desconhecida?"
  },
  AvgDialog_18870_Content_33 = {
    Text = "Pela situação dos corpos que encontramos antes, o desmembrador estava apenas dez minutos à nossa frente. Mesmo com o tempo que levamos para examinar os corpos, não deveríamos estar muito atrás dele"
  },
  AvgDialog_18870_Content_34 = {
    Text = "E com base no tamanho das pegadas, o desmembrador pode ser... uma criança.\nMas, quando estávamos passeando pelo ateliê com Sarah, não vimos nenhuma criança ensanguentada"
  },
  AvgDialog_18870_Content_35 = {
    Text = "Em tão pouco tempo, matar, pegar o saque, fugir, matar novamente, esconder a identidade. Acho impossível para uma única pessoa"
  },
  AvgDialog_18870_Content_36 = {
    Text = "Você quer dizer que essa criança pode ter um cúmplice?"
  },
  AvgDialog_18870_Content_37 = {
    Text = "Pode até ser cúmplice, cometendo um segundo crime ao mesmo tempo ou quase ao mesmo tempo que o primeiro"
  },
  AvgDialog_18870_Content_38 = {
    Text = "Pode ser Sarah? Ela teve tempo suficiente e também apareceu aqui"
  },
  AvgDialog_18870_Content_39 = {
    Text = "Agora, não há pistas suficientes para julgar"
  },
  AvgDialog_18870_Content_4 = {
    Text = "Ela disse que tem um \"Coração de Prata\", provavelmente algo semelhante a um Despertado. Então"
  },
  AvgDialog_18870_Content_40 = {
    Text = "Ramona foi até o canto da parede, pegou um pequeno objeto metálico do escuro.\nEra um botão de punho ensanguentado"
  },
  AvgDialog_18870_Content_41 = {
    Text = "Observando o trabalho, isso deve ser um dos \"joias de ouro e prata\" que jenkin mencionou. \nVamos, vamos ao escritório, talvez possamos encontrar mais evidências"
  },
  AvgDialog_18870_Content_42 = {
    Text = "01:55，Lilian Atelier\nEscritório do diretor"
  },
  AvgDialog_18870_Content_43 = {
    Text = "Eu sabia, %player%, veja"
  },
  AvgDialog_18870_Content_44 = {
    Text = "Ramona tirou um pequeno frasco marrom da gaveta da mesa. Você pegou e olhou, havia um rótulo com o nome e os efeitos do medicamento"
  },
  AvgDialog_18870_Content_45 = {
    Text = "Mas ajuda os pacientes a relaxar e dormir - parece que é o que adicionamos ao nosso chá"
  },
  AvgDialog_18870_Content_46 = {
    Text = "Ainda bem que ela não domina a dosagem dos medicamentos, senão nosso destino seria diferente esta noite"
  },
  AvgDialog_18870_Content_47 = {
    Text = "Falando nisso, como é a história com Jenkin? Sarah também não parece ter a capacidade de controlar a mente dos outros... Hã? O que é isso"
  },
  AvgDialog_18870_Content_48 = {
    Text = "Você fala enquanto procura, tirando um caderno de capa preta do fundo da gaveta.\nVocê o coloca na mesa e abre, encontrando uma lista de nomes"
  },
  AvgDialog_18870_Content_49 = {
    Text = "John Douglas, Diana Wolf... lista da oficina? Também indica gênero, idade e situação familiar. Mas por trás disso"
  },
  AvgDialog_18870_Content_5 = {
    Text = "Você fecha os olhos e força-se a entrar novamente no mundo ilusório, mas tudo parece embaçado, como se coberto por um véu"
  },
  AvgDialog_18870_Content_50 = {
    Text = "Atrás de cada nome há um símbolo representa a moeda comum do reino de Leo, <Blue:loja de leo>, seguido por um número"
  },
  AvgDialog_18870_Content_51 = {
    Text = "Os números e as informações sobre pessoal dispostos de forma ordenada fazem você se sentir confuso, sem saber se está diante da lista de trabalhadores de uma oficina ou de um catálogo de produtos de alguma revista"
  },
  AvgDialog_18870_Content_52 = {
    Text = "Cada pessoa tem um preço diferente, homens, mulheres... crianças"
  },
  AvgDialog_18870_Content_53 = {
    Text = "É como tratar pessoas como mercadorias.\nQuem? Quem faria esse tipo de negócio com ela?"
  },
  AvgDialog_18870_Content_54 = {
    Text = "Lembra-se de quem estava ajudando os pacientes a serem curados, Sarah?"
  },
  AvgDialog_18870_Content_55 = {
    Text = "Laboratório do Dr. Miller. Será que esse laboratório é a disfarce da associação dos escultores?"
  },
  AvgDialog_18870_Content_56 = {
    Text = "É possível. Vamos levar as provas principais.\nAmanhã vamos tentar falar com Sarah e ver o que conseguimos descobrir"
  },
  AvgDialog_18870_Content_57 = {
    Text = "01:50，Lilian Atelier\nAlgum lugar no quintal"
  },
  AvgDialog_18870_Content_58 = {
    Text = "Sarah acendeu um fósforo e jogou na pilha de lenha à sua frente"
  },
  AvgDialog_18870_Content_59 = {
    Text = "Com a ajuda da gasolina, as chamas queimaram rapidamente, consumindo as roupas manchadas de sangue"
  },
  AvgDialog_18870_Content_6 = {
    Text = "A parte de trás da cabeça começou a doer, com um zumbido agudo nos ouvidos, você segurou a testa e teve que parar de tentar rastrear"
  },
  AvgDialog_18870_Content_60 = {
    Text = "Ela ficou em silêncio por um momento, certificou-se de que as chamas não se apagariam e se virou para sair"
  },
  AvgDialog_18870_Content_7 = {
    Text = "Você já gastou muita energia hoje, não se force"
  },
  AvgDialog_18870_Content_8 = {
    Text = "Mas Clementine... não podemos deixá-la assim"
  },
  AvgDialog_18870_Content_9 = {
    Text = [[
Podemos pedir ajuda ao suporte.
Erica, procure Clementine Fairfax]]
  },
  AvgDialog_18871_Content_1 = {
    Text = "Minha carteira, meu bolinho"
  },
  AvgDialog_18871_Content_2 = {
    Text = "Relaxe. Talvez essa missão bem-sucedida traga recompensas extras"
  },
  AvgDialog_18871_Content_3 = {
    Text = "Se não der certo, eu não me importo de compartilhar, viu"
  },
  AvgDialog_18872_Content_1 = {
    Text = "Pesadelo colorido"
  },
  AvgDialog_18872_Content_10 = {
    Text = "......ok, se Lorde{Male=senhor,Female=senhorita} Ash ordenar"
  },
  AvgDialog_18872_Content_11 = {
    Text = "09:23，Lilian Atelier\nCâmara subterrânea"
  },
  AvgDialog_18872_Content_12 = {
    Text = "Aqui é uma sala de experimentos e cirurgias. No centro há uma mesa de operações modificada, com manchas suspeitas"
  },
  AvgDialog_18872_Content_13 = {
    Text = "No canto profundo do porão, há uma pilha de roupas sujas irreconhecíveis, meia altura de uma pessoa, exalando um fedor constante"
  },
  AvgDialog_18872_Content_14 = {
    Text = "Isso, isso, onde estamos?!"
  },
  AvgDialog_18872_Content_15 = {
    Text = "Pare de fingir ignorância, sabemos de suas tramas malignas com aquele doutor de merda"
  },
  AvgDialog_18872_Content_16 = {
    Text = "Que maldade, você é barulhento desde que chegou, precisa de uma lição"
  },
  AvgDialog_18872_Content_17 = {
    Text = "Vimos seu caderno!"
  },
  AvgDialog_18872_Content_18 = {Text = "...?"},
  AvgDialog_18872_Content_19 = {
    Text = "Você pega o livro de contas ao lado e o abre, sinalizando para Sarah"
  },
  AvgDialog_18872_Content_2 = {
    Text = "09:15，Lilian Atelier\nEscritório do diretor"
  },
  AvgDialog_18872_Content_20 = {
    Text = [[
Mike, masculino, 5 anos, 10 leus; Diana, feminino, 23 anos, 5 leus...
Aigis, feminino, 8 anos, 40 leus]]
  },
  AvgDialog_18872_Content_21 = {
    Text = "Você termina de falar e pega a lista de pacientes que encontraram"
  },
  AvgDialog_18872_Content_22 = {
    Text = "Mike, masculino, 5 anos, 5 leus; Diana, feminino, 23 anos, 5 leus; Aigis, feminino, 8 anos, 5 leus"
  },
  AvgDialog_18872_Content_23 = {
    Text = "...Devo continuar?"
  },
  AvgDialog_18872_Content_24 = {
    Text = "Não, não é o que você pensa, eu—"
  },
  AvgDialog_18872_Content_25 = {
    Text = "Pare de mentir! Você está apenas fazendo com que as pessoas da oficina se tornem experimentos para aquele Dr. cão e depois trocando por dinheiro para suas joias!"
  },
  AvgDialog_18872_Content_26 = {
    Text = "Não, não é isso! A senhorita Sarah disse que isso é um subsídio nutricional para as pessoas que recebem tratamento no laboratório, 5 Léos por pessoa a cada vez, isso estava combinado"
  },
  AvgDialog_18872_Content_27 = {Text = "Aigis!"},
  AvgDialog_18872_Content_28 = {
    Text = "Sim. Quanto às joias que a criança mencionou, é pura bobagem. Por favor, acredite em mim, Ash {Male=senhor,Female=senhorita}!"
  },
  AvgDialog_18872_Content_29 = {
    Text = "Jenkins tirou dois anéis de prata do fundo da bolsa"
  },
  AvgDialog_18872_Content_3 = {
    Text = "Colar esmeralda, anel... Estranho, onde está meu livro de contas?"
  },
  AvgDialog_18872_Content_30 = {
    Text = "Você quer dizer que esses dois objetos na gaveta direita do escritório apareceram do nada?"
  },
  AvgDialog_18872_Content_31 = {
    Text = "Como isso está com você? Devolva, é um presente de outro patrocinador!"
  },
  AvgDialog_18872_Content_32 = {
    Text = "Aesh {Male=senhor,Female=senhorita} você acredita em mim, eu só as considerava como suprimentos de emergência para o ateliê, como poderia, como poderia ferir as crianças do ateliê por causa dessas coisas?"
  },
  AvgDialog_18872_Content_33 = {
    Text = "Então, e este?"
  },
  AvgDialog_18872_Content_34 = {Text = "...!!"},
  AvgDialog_18872_Content_35 = {
    Text = "Abotoaduras?"
  },
  AvgDialog_18872_Content_36 = {
    Text = "Entramos no quarto de ontem"
  },
  AvgDialog_18872_Content_37 = {
    Text = "Ali foi recentemente limpo, o chão ainda está molhado, e há vestígios de sangue entre os tijolos.\nIsso deve ter sido deixado por acidente, está no canto"
  },
  AvgDialog_18872_Content_38 = {
    Text = "Ela utiliza materiais requintados, e seu trabalho é considerado refinado.\nNo ateliê, além de você, diretora, quem mais teria tais enfeites?"
  },
  AvgDialog_18872_Content_39 = {
    Text = "Não, não é dela! Não é da Senhorita Sarah, é meu! Eu deixei lá!"
  },
  AvgDialog_18872_Content_4 = {
    Text = "? Quem é.\nEntre"
  },
  AvgDialog_18872_Content_40 = {
    Text = "É ela, é ela! Assassina, sequestradora!"
  },
  AvgDialog_18872_Content_41 = {
    Text = "Ignorando a resistência de Aigis, Jenkins avançou e agarrou a saia de Sarah"
  },
  AvgDialog_18872_Content_42 = {
    Text = "Desgraçado, diga-me onde está minha irmã! <Big: Onde vocês levaram minha irmã!>"
  },
  AvgDialog_18872_Content_43 = {
    Text = "Você ia intervir, mas sentiu um arrepio.\nAlgo estava atrás de você, observando com malícia"
  },
  AvgDialog_18872_Content_44 = {
    Text = "Você se vira e vê roupas sujas no canto se movendo"
  },
  AvgDialog_18872_Content_45 = {
    Text = "Líquido negro vaza pelas costuras do tecido, encharcando as roupas e formando mutantes gotejantes no chão"
  },
  AvgDialog_18872_Content_46 = {Text = "Ramona!"},
  AvgDialog_18872_Content_5 = {
    Text = "A Miss Sarah."
  },
  AvgDialog_18872_Content_6 = {
    Text = "Senhorita Mary! \nHá algo com que eu possa te ajudar?"
  },
  AvgDialog_18872_Content_7 = {
    Text = [[
Preciso que venha comigo.
Ash{Male=senhor,Female=senhorita} tem um problema, precisa da sua ajuda]]
  },
  AvgDialog_18872_Content_8 = {
    Text = "Ash{Male=senhor,Female=senhorita}? Não pode esperar um pouco? Estou um pouco ocupado"
  },
  AvgDialog_18872_Content_9 = {
    Text = "Estou com medo de que devo insistir."
  },
  AvgDialog_18873_Content_1 = {
    Text = "Pequena, estamos fazendo isso pelo bem de Aigis. A situação dela é especial, e se não for controlada, pode se tornar um problema"
  },
  AvgDialog_18873_Content_10 = {
    Text = [[
Jenkins, pare de lutar!
... Eu vou]]
  },
  AvgDialog_18873_Content_11 = {Text = "...Hã?!"},
  AvgDialog_18873_Content_12 = {
    Text = "Isso é o que devo fazer. Uma vez começado, uma vez que está no corpo... não vai"
  },
  AvgDialog_18873_Content_13 = {
    Text = "O que quer dizer \"dever\"? Por quê?!"
  },
  AvgDialog_18873_Content_14 = {
    Text = "O Dr. Miller tem razão, se eu tiver uma recaída, será um incômodo para todos.\nNão quero prejudicar você, eu... me deixe ir"
  },
  AvgDialog_18873_Content_15 = {
    Text = "Você, está louco?! O que está fazendo, falando sozinho, eu disse que não pode ir!"
  },
  AvgDialog_18873_Content_16 = {Text = "Jenkin—"},
  AvgDialog_18873_Content_17 = {
    Text = "Dr. Miller."
  },
  AvgDialog_18873_Content_18 = {
    Text = "Vamos parar por aqui hoje, podemos falar mais tarde"
  },
  AvgDialog_18873_Content_19 = {
    Text = "...Você tem certeza, Sr. Rogers?"
  },
  AvgDialog_18873_Content_2 = {
    Text = "Pode até machucar as pessoas ao redor"
  },
  AvgDialog_18873_Content_20 = {
    Text = "É o que eu acho"
  },
  AvgDialog_18873_Content_21 = {
    Text = "Certo, acho que uma semana sem checar não faz diferença.\nEntão, vou me despedir. Adeus, Srta. Sarah, Sr. Rogers, {Male=senhor,Female=senhorita} Ash"
  },
  AvgDialog_18873_Content_22 = {
    Text = "Dr. Miller faz uma reverência e sai com alguns pesquisadores"
  },
  AvgDialog_18873_Content_23 = {
    Text = "Intuitivamente, você sente que não deve deixá-los ir, mas—tudo é mera especulação no momento. Você não sabe se eles são realmente dos Escultores, nem quantos são, ou onde está a base deles."
  },
  AvgDialog_18873_Content_24 = {
    Text = "Você olha para Ramona, seu rosto sombrio, compartilhando suas preocupações:\nSe os detivermos agora, será que só alertaremos o inimigo?"
  },
  AvgDialog_18873_Content_25 = {
    Text = "Eu, eu também estou saindo, Srta. Sarah. Até o próximo mês"
  },
  AvgDialog_18873_Content_26 = {
    Text = "Então vou levar a Aigis e Jenkins para descansar.\nSenhorita Sarah, que tal nos encontrarmos no seu escritório depois?"
  },
  AvgDialog_18873_Content_27 = {
    Text = "Huh? Mas, Aigis, ela—"
  },
  AvgDialog_18873_Content_28 = {
    Text = "Ela parecia muito assustada, espero poder ficar com ela um tempo para acalmá-la"
  },
  AvgDialog_18873_Content_29 = {
    Text = "E... tudo bem. Desculpe incomodar, Ash{Male=senhor,Female=senhorita}"
  },
  AvgDialog_18873_Content_3 = {
    Text = "Olhe, Aigis, esta é a consequência de você não ouvir e não cooperar"
  },
  AvgDialog_18873_Content_4 = {
    Text = "Seus amigos, as pessoas ao seu redor... todos pagarão o preço por isso"
  },
  AvgDialog_18873_Content_5 = {
    Text = "Obedeça, seja submisso, não resista. Saiba que não há para onde fugir"
  },
  AvgDialog_18873_Content_6 = {
    Text = "Ao redor? Que besteira, fiquei com ela por tanto tempo e nada aconteceu"
  },
  AvgDialog_18873_Content_7 = {
    Text = "......Jenkins"
  },
  AvgDialog_18873_Content_8 = {
    Text = "Aigis não tenha medo, veja como eu cuido dele. Marrom, morda-o!"
  },
  AvgDialog_18873_Content_9 = {Text = "Chiado!"},
  AvgDialog_18874_Content_1 = {
    Text = "Aviso de pessoa desaparecida"
  },
  AvgDialog_18874_Content_10 = {
    Text = "Vamos, não sejam tão pessimistas; nós também esperamos que a oficina melhore cada vez mais —"
  },
  AvgDialog_18874_Content_11 = {Text = "Ugh!"},
  AvgDialog_18874_Content_12 = {
    Text = "Você foi empurrado de repente ao lado, e ao olhar para baixo, viu uma criança pequena caída no chão, tremendo incontrolavelmente"
  },
  AvgDialog_18874_Content_13 = {
    Text = "Tem, tem, tem um monstro!!"
  },
  AvgDialog_18874_Content_14 = {
    Text = "Alguns minutos atrás, na oficina de Lilian"
  },
  AvgDialog_18874_Content_15 = {
    Text = "No corredor silencioso, a porta com placa de metal abriu lentamente.\nUm rato saiu pela fresta, olhou ao redor e chiou para trás"
  },
  AvgDialog_18874_Content_16 = {
    Text = "Da última vez você disse que não havia ninguém! Se não fosse por Aigis, eu estaria em apuros"
  },
  AvgDialog_18874_Content_17 = {
    Text = "Chiado, chiado chiado!"
  },
  AvgDialog_18874_Content_18 = {
    Text = "Sim, sim, você está certo. Nosso Brown é o melhor!"
  },
  AvgDialog_18874_Content_19 = {
    Text = "Chirp, chirp."
  },
  AvgDialog_18874_Content_2 = {
    Text = "14:01，Lilian Atelier"
  },
  AvgDialog_18874_Content_20 = {
    Text = "Relaxe, aquela mulher tem tantas joias, só peguei dois anéis, ela não vai notar!"
  },
  AvgDialog_18874_Content_21 = {
    Text = "Mas... hehe, agora sei onde ela guarda as coisas boas. Quando encontrar minha irmã, vou roubar tudo daquela mulher!"
  },
  AvgDialog_18874_Content_22 = {Text = "Chiado!"},
  AvgDialog_18874_Content_23 = {
    Text = "Certo, pare de falar—hmm? \nO que é... esse som?"
  },
  AvgDialog_18874_Content_24 = {
    Text = "No final do corredor, algo piscou ao redor da esquina."
  },
  AvgDialog_18874_Content_25 = {Text = "Brown."},
  AvgDialog_18874_Content_26 = {
    Text = "O rato pulou da bolsa, movendo-se agilmente ao longo da parede até o canto para verificar"
  },
  AvgDialog_18874_Content_27 = {Text = "Chiado!"},
  AvgDialog_18874_Content_28 = {
    Text = "Ao ouvir o sinal de segurança do companheiro, a garota se agachou e seguiu.\nEla se encostou na parede e espiou, aliviada ao ver que não havia ninguém"
  },
  AvgDialog_18874_Content_29 = {
    Text = "Decidiu sair rapidamente, a garota recuou, mas viu uma sombra pálida de relance"
  },
  AvgDialog_18874_Content_3 = {
    Text = "Como você pode ver, apesar de tentarmos acomodar, as pessoas que precisam de ajuda são muitas demais, se continuar assim, esta oficina de trabalho não aguentará por muito mais tempo. Eu... ah!"
  },
  AvgDialog_18874_Content_30 = {Text = "?"},
  AvgDialog_18874_Content_31 = {
    Text = "Ela entrou no corredor e viu um objeto branco de forma irregular no chão de madeira suja, parecia algum tipo de pedra"
  },
  AvgDialog_18874_Content_32 = {
    Text = "Parece parte de uma máscara de pedra, muito detalhada, cada sobrancelha esculpida vividamente"
  },
  AvgDialog_18874_Content_33 = {
    Text = "O que é isso? Não vi máscaras ou estátuas de pedra sendo trabalhadas na oficina"
  },
  AvgDialog_18874_Content_34 = {
    Text = "Ela inclinou a cabeça, olhando curiosamente e cutucando com o dedo indicador"
  },
  AvgDialog_18874_Content_35 = {
    Text = "Por que ainda está quente"
  },
  AvgDialog_18874_Content_36 = {
    Text = "Ela estava prestes a pegar a máscara, quando os lábios de pedra se abriram de repente, soltando um gemido de dor que não deveria existir"
  },
  AvgDialog_18874_Content_37 = {Text = "!!"},
  AvgDialog_18874_Content_38 = {
    Text = "Ela recua dois passos em terror; em meio à sua respiração acelerada, sente o fedor de carne em decomposição."
  },
  AvgDialog_18874_Content_39 = {
    Text = "Monstro... Monstro... Monstro!"
  },
  AvgDialog_18874_Content_4 = {
    Text = "Miss Sarah, você trabalha tão duro todos os dias e até vendeu suas coisas favoritas para ajudar a oficina. Por favor, nos ajude"
  },
  AvgDialog_18874_Content_40 = {
    Text = "14:37，Lilian Atelier\nQuarto de Aigis"
  },
  AvgDialog_18874_Content_41 = {
    Text = "Então eu corri, bati em você. E vocês insistiram para eu \"descansar\", e aqui estou"
  },
  AvgDialog_18874_Content_42 = {
    Text = "Desta vez foi bem detalhado, não?"
  },
  AvgDialog_18874_Content_43 = {Text = "Hmm..."},
  AvgDialog_18874_Content_44 = {
    Text = "Duas crianças sentam-se lado a lado na cama, você olha para elas, especialmente para Jenkin, e finalmente faz a pergunta"
  },
  AvgDialog_18874_Content_45 = {
    Text = "Você... é menino ou menina?"
  },
  AvgDialog_18874_Content_46 = {
    Text = "Você tem problema de visão?! Eu sou mulher, mulher!"
  },
  AvgDialog_18874_Content_47 = {
    Text = "Confirmar, confirmar"
  },
  AvgDialog_18874_Content_48 = {
    Text = "Que pessoa estranha... está bem da cabeça?\nTerminou? Agora é minha vez"
  },
  AvgDialog_18874_Content_49 = {
    Text = "A mão de Jenkins se moveu rapidamente, tirando uma carteira de algum lugar.\nO contorno familiar e o emblema da Universidade de Missaga: sim, era sua carteira, mas"
  },
  AvgDialog_18874_Content_5 = {
    Text = "Não diga isso, minha adorável e lamentável Aigis. Se a oficina realmente não der conta, eu morreria de fome sozinha, mas definitivamente não deixarei você passar fome!"
  },
  AvgDialog_18874_Content_50 = {
    Text = "...Por que está vazio lá dentro? Onde está meu dinheiro!"
  },
  AvgDialog_18874_Content_51 = {
    Text = "Esse não é o ponto!"
  },
  AvgDialog_18874_Content_52 = {
    Text = "Cof cof, enfim, não se engane, eu ainda sei ler um pouco.\nIsso aqui não é um certificado de {Male=senhor,Female=senhorita}, %player%"
  },
  AvgDialog_18874_Content_53 = {
    Text = "E se eu contar quem vocês são para aquela mulher, acha que ela vai mandar os guardas expulsarem vocês?"
  },
  AvgDialog_18874_Content_54 = {
    Text = "Essa é uma criança da oficina?"
  },
  AvgDialog_18874_Content_55 = {
    Text = "Não... senão, hahaha, nossa oficina é muito rigorosa em segurança, não é permitido a entrada de pessoas que não conhecem os detalhes"
  },
  AvgDialog_18874_Content_56 = {
    Text = "Pelo jeito que Sarah reagiu, ela claramente não conhece Jenkins. Então—"
  },
  AvgDialog_18874_Content_57 = {
    Text = "Se eu for descoberto, não serei o único em apuros, certo? Afinal, você também não é da oficina"
  },
  AvgDialog_18874_Content_58 = {
    Text = "Tenho muitas maneiras de entrar. Mas você, sem o status de autossuficiente, será difícil entrar novamente"
  },
  AvgDialog_18874_Content_59 = {
    Text = "......É um patrocinador"
  },
  AvgDialog_18874_Content_6 = {
    Text = "Srta. Sarah...! Eu, eu vou obedecer, vou cuidar bem de você, não serei um fardo"
  },
  AvgDialog_18874_Content_60 = {
    Text = "Tanto faz! De qualquer forma, ou você me ajuda, ou ambos estamos ferrados!"
  },
  AvgDialog_18874_Content_61 = {
    Text = "Primeiro de tudo, não roubo"
  },
  AvgDialog_18874_Content_62 = {
    Text = "Roubar? Preciso de ajuda para encontrar alguém!"
  },
  AvgDialog_18874_Content_63 = {
    Text = "Diga-me suas exigências primeiro"
  },
  AvgDialog_18874_Content_64 = {
    Text = "Preciso que me ajude a encontrar alguém, alguém muito importante"
  },
  AvgDialog_18874_Content_65 = {Text = "Quem?"},
  AvgDialog_18874_Content_66 = {
    Text = "Minha irmã, Mason."
  },
  AvgDialog_18874_Content_7 = {Text = "..."},
  AvgDialog_18874_Content_8 = {
    Text = "Minha querida pequena Aigis—"
  },
  AvgDialog_18874_Content_9 = {
    Text = "Vendo a atuação dos dois—principalmente de Sarah—ficar cada vez mais exagerada, você se sente um pouco impotente.\nEmbora entenda, a ajuda que você pode oferecer não é financeira"
  },
  AvgDialog_18875_Content_1 = {
    Text = "Pequeno Detetive"
  },
  AvgDialog_18875_Content_10 = {
    Text = "Tsc, não importa, você quase me fez ser descoberto, é sua responsabilidade"
  },
  AvgDialog_18875_Content_11 = {
    Text = "Deixe-me ser honesto com você, não sou dessa oficina quebrada.\nMeu nome é Jenkins, este é Marrom"
  },
  AvgDialog_18875_Content_12 = {Text = "Chiado!"},
  AvgDialog_18875_Content_13 = {
    Text = "Entrei para procurar minha irmã. Ela se chama Mason, desapareceu aqui perto há duas semanas.\nAlguém chamado Mason apareceu por aqui recentemente?"
  },
  AvgDialog_18875_Content_14 = {
    Text = "Sinto muito, eu... não sei... Sinto muito..."
  },
  AvgDialog_18875_Content_15 = {
    Text = "Pense bem, ela é assim de alta, tem cabelos longos, amarrados com uma fita vermelha bonita"
  },
  AvgDialog_18875_Content_16 = {Text = "..."},
  AvgDialog_18875_Content_17 = {
    Text = "Você já viu isso? Fale algo. Ela está assediada por algum bandido da sua oficina, não está obrigando-a a ficar como uma escrava, está?"
  },
  AvgDialog_18875_Content_18 = {
    Text = "Tsk, não dá, vendo você assim não sabe de nada, preciso ficar, mesmo que seja apenas disfarçado para entrar na oficina—"
  },
  AvgDialog_18875_Content_19 = {
    Text = "Não pode! Se você entrar, terá que ser tratado, não pode!"
  },
  AvgDialog_18875_Content_2 = {
    Text = "3 dias atrás, distrito leste de Londinium\noficina de trabalho Lilian"
  },
  AvgDialog_18875_Content_20 = {
    Text = "Cale-se! Você não tem medo de ser descoberto, mas eu tenho!"
  },
  AvgDialog_18875_Content_21 = {
    Text = "Vou ajudar você a encontrar sua irmã. Posso ajudá-la a se esconder, e trazer comida. Não entre na oficina, ok?"
  },
  AvgDialog_18875_Content_22 = {
    Text = "Sério? Claro que sim! Eu juro que vou retribuir!"
  },
  AvgDialog_18875_Content_23 = {
    Text = "Aliás, qual é o seu nome?"
  },
  AvgDialog_18875_Content_24 = {
    Text = "Eu... meu nome é Aigis."
  },
  AvgDialog_18875_Content_25 = {
    Text = "Prazer em conhecê-la, Aigis. A partir de hoje, somos amigos!"
  },
  AvgDialog_18875_Content_26 = {
    Text = "15:00，Londinium Leste\nLilian Atelier"
  },
  AvgDialog_18875_Content_27 = {
    Text = "Mais tarde, Aigis me ajudou a me esconder no armário, enquanto eu procurava minha irmã na oficina quando os adultos não estavam prestando atenção"
  },
  AvgDialog_18875_Content_28 = {
    Text = "Achei que, com todos juntos no descanso, seria fácil achar.\nMas não vi ninguém ontem e anteontem, então só pude procurar durante o trabalho"
  },
  AvgDialog_18875_Content_29 = {
    Text = "Embora eu não tenha medo de ser expulso, também não quero problemas, você é diferente.\nCom sua posição, andar à vontade na oficina não vai causar comentários"
  },
  AvgDialog_18875_Content_3 = {
    Text = "À meia-noite, o distrito leste estava escuro. Nem as luzes da rua nem a lua podiam penetrar a névoa densa, deixando apenas sombras vagas flutuando no ar"
  },
  AvgDialog_18875_Content_30 = {
    Text = "Não peço muito, só quero que veja se minha irmã está entre os trabalhadores"
  },
  AvgDialog_18875_Content_31 = {
    Text = "Se você me ajudar, devolverei sua carteira e aquele documento, e guardarei seu segredo.\nSe não me ajudar... hum hum!"
  },
  AvgDialog_18875_Content_32 = {
    Text = "Faça o que quiser!"
  },
  AvgDialog_18875_Content_33 = {
    Text = "Por que você tem tanta certeza de que sua irmã está aqui?"
  },
  AvgDialog_18875_Content_34 = {
    Text = "Você pode não saber, mas este é o famoso \"Ateliê de Comedores\", muitas pessoas desapareceram nas proximidades, minha irmã também sumiu por aqui"
  },
  AvgDialog_18875_Content_35 = {
    Text = "Dias atrás, vi uma <Red:sombra escura> correndo pelo pátio à noite, deve haver algo estranho acontecendo"
  },
  AvgDialog_18875_Content_36 = {
    Text = "... Tudo bem, eu prometo ajudar você a encontrar sua irmã. Em troca, você também me ajudará a investigar a oficina, tudo bem?"
  },
  AvgDialog_18875_Content_37 = {Text = "Combinado!"},
  AvgDialog_18875_Content_38 = {
    Text = "Ela cuspiu na palma da mão e olhou para você com expectativa"
  },
  AvgDialog_18875_Content_39 = {Text = "..."},
  AvgDialog_18875_Content_4 = {
    Text = "No pátio da oficina de trabalho, duas pequenas silhuetas estão em um canto"
  },
  AvgDialog_18875_Content_40 = {
    Text = "O que está esperando? Aperte a mão. Está desrespeitando as regras da rua?"
  },
  AvgDialog_18875_Content_41 = {
    Text = "Aperte a mão dela"
  },
  AvgDialog_18875_Content_42 = {
    Text = "Você imitou o gesto dela, cuspiu na palma da mão e apertou a dela com força"
  },
  AvgDialog_18875_Content_43 = {
    Text = "Você é esperto, cara do Oeste. Subestimei você"
  },
  AvgDialog_18875_Content_44 = {
    Text = "Você imitou o gesto dela, cuspiu na palma da mão e apertou a dela com força"
  },
  AvgDialog_18875_Content_45 = {
    Text = "Prazer em trabalhar com você!"
  },
  AvgDialog_18875_Content_46 = {
    Text = "14:50，Londinium Leste\nLilian Atelier"
  },
  AvgDialog_18875_Content_47 = {
    Text = "Senhorita Mary, por favor, você deve, precisa, transmitir minhas mais sinceras desculpas ao {Male=senhor,Female=senhorita} Ash"
  },
  AvgDialog_18875_Content_48 = {
    Text = "As pessoas na oficina são todos pobres de bom caráter, aquele menino não é... eh, quero dizer, eu definitivamente vou ensinar uma lição a ela!"
  },
  AvgDialog_18875_Content_49 = {
    Text = "Ramona ia responder, mas viu uma figura estranha no fim do corredor"
  },
  AvgDialog_18875_Content_5 = {
    Text = "Você, você não é o pequeno Mike, nem a pequena Lucy! Quem é você...!"
  },
  AvgDialog_18875_Content_50 = {
    Text = "Senhorita Mary?"
  },
  AvgDialog_18875_Content_51 = {
    Text = "Aquilo é...?"
  },
  AvgDialog_18875_Content_6 = {
    Text = "Quem é você? Andando por aí no meio da noite, sem dormir, parece o desmembrador que está causando problemas"
  },
  AvgDialog_18875_Content_7 = {
    Text = "Não sou! Não fui eu!"
  },
  AvgDialog_18875_Content_8 = {
    Text = "Shh! Você tem ouvidos? Eu disse para falar baixo!"
  },
  AvgDialog_18875_Content_9 = {
    Text = "Eu... eu... sinto muito, eu só... eu não... eu..."
  },
  AvgDialog_18876_Content_1 = {
    Text = "Não fale o que não deve"
  },
  AvgDialog_18876_Content_10 = {
    Text = "Ele realmente era forte, até curou os olhos da Aigis, fazendo com que ela deixasse de ver fantasmas"
  },
  AvgDialog_18876_Content_100 = {
    Text = "Chirp, chirp."
  },
  AvgDialog_18876_Content_101 = {
    Text = "Mesmo que ela saiba onde está minha irmã, eu... não, acho que ela não é má.\nVamos embora, depois eu pergunto quando estivermos sozinhos"
  },
  AvgDialog_18876_Content_11 = {
    Text = "Certo, Aigis?"
  },
  AvgDialog_18876_Content_12 = {
    Text = "......Sim, Dr. Miller... muito impressionante"
  },
  AvgDialog_18876_Content_13 = {
    Text = "Não pode! Se você entrar, terá que ser tratado, não pode!"
  },
  AvgDialog_18876_Content_14 = {
    Text = "Vou ajudar você a encontrar sua irmã, farei isso, posso ajudá-la a se esconder, mas não entre na oficina, ok?"
  },
  AvgDialog_18876_Content_15 = {
    Text = "Com base na descrição de Jenkin e na reação atual, essa criança parece estar cheia de medo de Dr. Miller e do \"tratamento\""
  },
  AvgDialog_18876_Content_16 = {
    Text = "Se aquele pesquisador for um homem do Dr. Miller, então essa \"terapia experimental\" é muito provavelmente algo incomum, relacionado à dissolução e à marca d"
  },
  AvgDialog_18876_Content_17 = {
    Text = "Então, algumas cozinheiras empurrando um carrinho entraram, trazendo o aroma de mingau de aveia"
  },
  AvgDialog_18876_Content_18 = {
    Text = "Olhe para mim, perdi a noção do tempo, o {Male=senhor,Female=senhorita} Ash deve estar faminto"
  },
  AvgDialog_18876_Content_19 = {
    Text = "Aigis, boa criança, vá procurar a Diana e peça para ela trazer as refeições para os convidados.\nDepois você poderá entregar as refeições aos pacientes, tudo bem?"
  },
  AvgDialog_18876_Content_2 = {
    Text = "15:11，Londinium Leste\nLilian Atelier"
  },
  AvgDialog_18876_Content_20 = {
    Text = "Entendi, Srta. Sarah, vou agora"
  },
  AvgDialog_18876_Content_21 = {
    Text = "A menina carregava uma bandeja, caminhando lentamente entre as camas, cumprimentando pacientes lúcidos e insanos"
  },
  AvgDialog_18876_Content_22 = {
    Text = "Boa tarde, Sra. Thompson; boa tarde, Sr. Kelvin"
  },
  AvgDialog_18876_Content_23 = {
    Text = [[
Ela parou ao lado de uma cama perto da janela.
Na cama, um velho estava amarrado com tiras de pano, gemendo de dor]]
  },
  AvgDialog_18876_Content_24 = {
    Text = "Vovô Robert, deixei sua comida de lado, lembre-se de comer"
  },
  AvgDialog_18876_Content_25 = {
    Text = "Menina arruma o cobertor do idoso, sem notar o triângulo negro engolindo seu rosto"
  },
  AvgDialog_18876_Content_26 = {
    Text = "Comer bem para se recuperar rápido.\nEntão podemos ir ao parque Drell juntos e alimentar os pombos"
  },
  AvgDialog_18876_Content_27 = {
    Text = "O braço magro do Velho rasgou as faixas e levantou-se de repente—"
  },
  AvgDialog_18876_Content_28 = {
    Text = "Se tivéssemos mais fundos, talvez pudéssemos contratar profissionais para ajudar, e os pacientes poderiam se recuperar em um lugar melhor—"
  },
  AvgDialog_18876_Content_29 = {Text = "!"},
  AvgDialog_18876_Content_3 = {
    Text = "Vocês seguem Sarah até uma sala cheia de camas improvisadas.\nParece que era um refeitório, com uma mesa longa ainda no centro"
  },
  AvgDialog_18876_Content_30 = {
    Text = "Você olha rapidamente para a origem do som e vê um monstro com um buraco negro no rosto segurando Aigis"
  },
  AvgDialog_18876_Content_31 = {Text = "Aigis!"},
  AvgDialog_18876_Content_32 = {
    Text = "Ramona reagiu rapidamente. Ela passou pela multidão em pânico e bateu a bainha da espada no ombro do monstro"
  },
  AvgDialog_18876_Content_33 = {
    Text = "O monstro soltou a mão, e os atendentes rapidamente amarraram a criatura que ainda gritava de volta à cama"
  },
  AvgDialog_18876_Content_34 = {
    Text = "Vovô Robert, Vovô Robert—"
  },
  AvgDialog_18876_Content_35 = {
    Text = "No meio dos gritos da menina, você olhou para a \"pessoa\" lutando na cama e sentiu uma tristeza profunda.\n<Yellow:Estágio final de corrosão>, este velho só conseguirá manter a forma humana por mais alguns dias"
  },
  AvgDialog_18876_Content_36 = {
    Text = "Bandagem, encontrei a bandagem! Aigis, deixe-me ver seu ferimento!"
  },
  AvgDialog_18876_Content_37 = {
    Text = "Vovô Robert, vá ajudar o vovô Robert"
  },
  AvgDialog_18876_Content_38 = {
    Text = "Por que está pensando nos outros agora? Se não tratar a ferida logo, será um problema!"
  },
  AvgDialog_18876_Content_39 = {
    Text = "Jenkins segurou o braço de Aigis e puxou a manga, revelando uma ferida sangrando"
  },
  AvgDialog_18876_Content_4 = {
    Text = "Para cuidar deles, tivemos que alocar parte da força de trabalho, o que afetou a eficiência do trabalho e a receita da oficina, além de uma doença estranha"
  },
  AvgDialog_18876_Content_40 = {
    Text = "Esse maldito louco, arranhou muito forte!"
  },
  AvgDialog_18876_Content_41 = {
    Text = "Arranhões no braço da menina sangram, mas são insignificantes comparados à cicatriz preta no pulso"
  },
  AvgDialog_18876_Content_42 = {
    Text = "Costuras cruzadas puxam a pele para o centro, tentando \"fechar\" a abertura negra, mas parecendo mais uma boca faminta"
  },
  AvgDialog_18876_Content_43 = {
    Text = "Esta é a <Yellow:Marca de Corrosão>, igual àqueles pacientes, uma marca de corrosão distorcida"
  },
  AvgDialog_18876_Content_44 = {
    Text = "......Jenkins, traga um pouco de água"
  },
  AvgDialog_18876_Content_45 = {
    Text = "Jenkins assentiu vigorosamente e correu para longe"
  },
  AvgDialog_18876_Content_46 = {
    Text = "Ramona pegou um lenço e limpou suavemente o sangue de Aigis, evitando o pulso.\nAigis olhou para Ramona, depois para você, parecendo hesitante"
  },
  AvgDialog_18876_Content_47 = {
    Text = "Aigis, há algo que você quer dizer?"
  },
  AvgDialog_18876_Content_48 = {Text = "!"},
  AvgDialog_18876_Content_49 = {
    Text = "Não... não... Eu não"
  },
  AvgDialog_18876_Content_5 = {
    Text = "Não queria arriscar a confiança dos patrocinadores, então escondi tudo, apenas o principal patrocinador <Blue:Sr. Rogers> sabia"
  },
  AvgDialog_18876_Content_50 = {
    Text = "Não tenha medo, Aigis, seja o que for, vamos te ajudar"
  },
  AvgDialog_18876_Content_51 = {
    Text = "Não tenha medo, Aigis. Dr. Miller está aqui para te ajudar."
  },
  AvgDialog_18876_Content_52 = {
    Text = "Não tenha medo, Aigis. É só uma injeção. Não vai doer."
  },
  AvgDialog_18876_Content_53 = {
    Text = "Não tenha medo, Aigis. Vai acabar logo."
  },
  AvgDialog_18876_Content_54 = {
    Text = "Não tenha medo, Aigis..."
  },
  AvgDialog_18876_Content_55 = {
    Text = "Não tenha medo"
  },
  AvgDialog_18876_Content_56 = {Text = "Aigis?"},
  AvgDialog_18876_Content_57 = {
    Text = "A menina balançou a cabeça vigorosamente.\nNesse momento, Sarah, que havia acalmado os outros trabalhadores, chegou apressada até vocês"
  },
  AvgDialog_18876_Content_58 = {
    Text = "Aigis você—oh não, você está sangrando! Onde estão os curativos? Rápido, traga os curativos!"
  },
  AvgDialog_18876_Content_59 = {
    Text = [[
Estou bem, Srta. Sarah.
Desculpe, fui descuidado e te preocupei]]
  },
  AvgDialog_18876_Content_6 = {
    Text = "Você olhou ao redor, vendo que os pacientes tinham diferentes graus de corrosão, todos com formas distorcidas, semelhantes ao homem de antes"
  },
  AvgDialog_18876_Content_60 = {
    Text = "Você... ai. Quantas vezes eu disse que esses loucos são perigosos, mas você não ouve e insiste em levar comida. Por que é tão teimoso?"
  },
  AvgDialog_18876_Content_61 = {
    Text = "Desculpa... eu não queria"
  },
  AvgDialog_18876_Content_62 = {
    Text = "Eu sei que você quer ajudar, mas você também precisa olhar para suas capacidades. Não está tornando as coisas mais complicadas para todos?"
  },
  AvgDialog_18876_Content_63 = {
    Text = "Que preocupação. Com essa teimosia, quando vai crescer?"
  },
  AvgDialog_18876_Content_64 = {
    Text = "Já falou o suficiente!"
  },
  AvgDialog_18876_Content_65 = {
    Text = "Jenkins voltou sem que ninguém percebesse. Ela jogou o balde no chão e se colocou na frente de Aigis"
  },
  AvgDialog_18876_Content_66 = {
    Text = "Aigis trabalha tanto todos os dias, ajudando você com tantas coisas, o que mais você tem a reclamar?\nCrescendo, se crescer significa que você faz o que quer, então é melhor que eu nunca cresça nesta vida!"
  },
  AvgDialog_18876_Content_67 = {
    Text = "O que está acontecendo?"
  },
  AvgDialog_18876_Content_68 = {
    Text = "Você se virou ao ouvir o som e viu duas pessoas atrás de você.\nVocê reconheceu uma delas: ela te entregou um questionário psicológico na rua"
  },
  AvgDialog_18876_Content_69 = {
    Text = "Senhor Rogers, Dr. Fairfax!\nVocê não costuma chegar à noite? Se tivesse me avisado antes, eu poderia ir recebê-lo na porta"
  },
  AvgDialog_18876_Content_7 = {
    Text = "O estranho é que a pessoa de jaleco chamada de \"<Blue:Pesquisador>\" por Sarah não está aqui agora"
  },
  AvgDialog_18876_Content_70 = {
    Text = "Já conheço bem aqui, Srta. Sarah, não precisa se preocupar.\nMas por que a pequena Ai e Aigis estão chorando tanto? Alguém as machucou?"
  },
  AvgDialog_18876_Content_71 = {
    Text = "É só aquela maldita Sarah! Ela é simplesmente"
  },
  AvgDialog_18876_Content_72 = {
    Text = "Com os gritos de Jenkins, Clementine se abaixou e segurou a mão de Aigis com habilidade"
  },
  AvgDialog_18876_Content_73 = {
    Text = "Pequena Aigis está tendo novos problemas, será que deve conversar novamente com o doutor Clementine?"
  },
  AvgDialog_18876_Content_74 = {
    Text = "Espere, quem é você? Não puxe as pessoas"
  },
  AvgDialog_18876_Content_75 = {
    Text = "Eu conheço a pequena Aigis há muito tempo. O novo menino. Antes, sempre que Aigis estava triste, ela vinha conversar comigo"
  },
  AvgDialog_18876_Content_76 = {
    Text = "Afinal, desabafar é uma forma de terapia, e eu sou um ótimo ouvinte.\nQuer se juntar a nós? Parece que você também tem algo em mente"
  },
  AvgDialog_18876_Content_77 = {
    Text = "Não vou, essas coisas de terapia psicológica são estranhas"
  },
  AvgDialog_18876_Content_78 = {
    Text = "É uma pena. Se você mudar de ideia, pode vir se juntar a nós a qualquer momento.\nVamos, Aigis"
  },
  AvgDialog_18876_Content_79 = {
    Text = "Depois que os dois saem, você volta sua atenção para o presente"
  },
  AvgDialog_18876_Content_8 = {
    Text = "O Sr. Rogers foi um dos primeiros a descobrir a doença estranha e sempre acompanhou os pacientes. Ele nos apresentou ao <Blue:Dr. Miller>, especialista em doenças raras"
  },
  AvgDialog_18876_Content_80 = {
    Text = "George Rogers, prazer em conhecê-los"
  },
  AvgDialog_18876_Content_81 = {
    Text = "Ele estendeu a mão e apertou a sua. No toque, uma forte tontura o atingiu"
  },
  AvgDialog_18876_Content_82 = {
    Text = "Tudo ao redor derrete como cera, até a pessoa à sua frente se distorce.\nSob o rosto jovem, ossos pálidos se entrelaçam como vinhas"
  },
  AvgDialog_18876_Content_83 = {
    Text = "Uma ilusão estranha desapareceu após algumas piscadelas, apenas o zunido agudo ainda ecoava em seus ouvidos—é uma alucinação causada pelo cansaço, ou alguma premonição?"
  },
  AvgDialog_18876_Content_84 = {
    Text = "Você não sabe. Você só sabe que é parecido com o que aconteceu no cemitério alguns dias atrás"
  },
  AvgDialog_18876_Content_85 = {
    Text = "......Todo mês ele vem pessoalmente ver a situação dos pacientes. Graças a ele, conseguimos estabelecer essa área de cuidados médicos para tratar os doentes. Ele é um verdadeiro benfeitor do nosso ateliê"
  },
  AvgDialog_18876_Content_86 = {
    Text = "A Srta. Sarah me elogia demais, sou apenas uma pessoa comum querendo fazer algo pelo mundo"
  },
  AvgDialog_18876_Content_87 = {
    Text = "Prazer em conhecê-lo, Sr. Rogers. Meu nome é Ash, este é meu mordomo, Mary.\nEste é Jenkins... hein?"
  },
  AvgDialog_18876_Content_88 = {
    Text = "Onde foi parar agora?"
  },
  AvgDialog_18876_Content_89 = {
    Text = "Aigis segurou a mão de Clementine e caminhou com os passos dela pelo pátio"
  },
  AvgDialog_18876_Content_9 = {
    Text = "O Dr. Miller concordou em nos fornecer tratamento gratuito, desde que usemos sua \"<Blue:Terapia Experimental>\""
  },
  AvgDialog_18876_Content_90 = {
    Text = "Entendi, aquela <Red:\"voz\"> que sempre aparece na sua mente à noite te fez fazer coisas ruins de novo?"
  },
  AvgDialog_18876_Content_91 = {
    Text = "Tentei trancar a porta, tapar os ouvidos... Mas a \"voz\" sempre encontra uma maneira de me alcançar, e a todos"
  },
  AvgDialog_18876_Content_92 = {
    Text = "Eles não se lembram da \"voz\", só eu. Mesmo querendo esquecer, não consigo"
  },
  AvgDialog_18876_Content_93 = {
    Text = "Muitas pessoas morreram, incluindo a irmã de Jenkins... Eu não aguento mais, se continuar assim, todos serão descobertos e presos pela polícia!"
  },
  AvgDialog_18876_Content_94 = {
    Text = "Você acha que eles são inocentes?"
  },
  AvgDialog_18876_Content_95 = {
    Text = "Eu sei que eles são inocentes! Tudo por causa daquela \"voz\", ela fez todos mudarem, eu também"
  },
  AvgDialog_18876_Content_96 = {
    Text = "Você pode me ajudar, doutor Clementine? Meu aviso não é acreditado por ninguém, mas se for você, eles certamente ouvirão"
  },
  AvgDialog_18876_Content_97 = {
    Text = "Vozes que outros não ouvem não são provas, e é difícil reagir a avisos sem provas, mas——não desanime"
  },
  AvgDialog_18876_Content_98 = {
    Text = "Neste mundo, nada é impossível de conseguir se arriscando a vida"
  },
  AvgDialog_18876_Content_99 = {
    Text = "Aigis baixou a cabeça, pensativa.\n Atrás de algumas caixas de madeira empilhadas ao lado da parede do pátio, uma cabeça com capuz marrom apareceu"
  },
  AvgDialog_18877_Content_1 = {
    Text = "Quem Matou o Tordo"
  },
  AvgDialog_18877_Content_10 = {
    Text = "A oficina afunda na névoa, cercada pela obscuridade, mas isso parece não afetar a menina. \nEla corre com todas as suas forças, para frente"
  },
  AvgDialog_18877_Content_11 = {
    Text = "Rápido, tem que ser rápido, se alguém descobrir, se %player% descobrir...\nEles vão levar aquela pessoa, com certeza"
  },
  AvgDialog_18877_Content_12 = {
    Text = "Ela virou uma esquina e parou abruptamente"
  },
  AvgDialog_18877_Content_13 = {
    Text = "Não, meu Deus, não"
  },
  AvgDialog_18877_Content_14 = {
    Text = "Não seja você, Mike"
  },
  AvgDialog_18877_Content_15 = {
    Text = [[
20:50, oficina de trabalho Lilian
quarto da Aigis]]
  },
  AvgDialog_18877_Content_16 = {
    Text = "Jenkins deu uma volta na sala vazia, suspirando com as mãos na cintura"
  },
  AvgDialog_18877_Content_17 = {
    Text = "Não está no banheiro, nem na cozinha, nem no refeitório. Onde ela foi?"
  },
  AvgDialog_18877_Content_18 = {
    Text = "Ela se sentou no chão e começou a tatear embaixo do colchão"
  },
  AvgDialog_18877_Content_19 = {
    Text = "Deixa pra lá, não importa, ela vai voltar para dormir, vou esperar aqui comendo doces!"
  },
  AvgDialog_18877_Content_2 = {
    Text = "20:43, oficina de trabalho Lilian\nquarto de hóspedes"
  },
  AvgDialog_18877_Content_20 = {
    Text = "Chirp! Chirp! Chirp!"
  },
  AvgDialog_18877_Content_21 = {
    Text = "Não vá contar! Além disso, vou comprar mais para ela depois—"
  },
  AvgDialog_18877_Content_22 = {
    Text = [[
Ela parou de se mover e tirou algo de dentro.
Uma fita vermelha, um fivela prateada, uma extremidade parecia rasgada]]
  },
  AvgDialog_18877_Content_23 = {
    Text = "Isso é... da irmã...?"
  },
  AvgDialog_18877_Content_24 = {
    Text = [[
20:50, oficina de trabalho Lilian
jardim da frente]]
  },
  AvgDialog_18877_Content_25 = {
    Text = "A oficina sob a obtenção da noite adormece; você e Ramona apressam-se, uma sensação de pressentimento surge em seu coração — \n em breve, algo além de vocês quebrará a tranquilidade"
  },
  AvgDialog_18877_Content_26 = {Text = "%player%."},
  AvgDialog_18877_Content_27 = {
    Text = "Você fechou os olhos novamente. Um frio indescritível se espalhou da nuca para os membros, e a canção desconhecida foi se tornando indistinta, como se fosse desaparecer com o vento"
  },
  AvgDialog_18877_Content_28 = {
    Text = "Você abre os olhos e percebe que a névoa ao redor está se dissipando"
  },
  AvgDialog_18877_Content_29 = {
    Text = "Não sinto mais, é como se... como se o som tivesse enfraquecido"
  },
  AvgDialog_18877_Content_3 = {
    Text = "Rogers manipulou a mão de George, fazendo a estátua de cera cumprimentar Jenkins"
  },
  AvgDialog_18877_Content_30 = {
    Text = "As ondas mentais dos indivíduos especiais estão ligadas à névoa?"
  },
  AvgDialog_18877_Content_31 = {Text = "!"},
  AvgDialog_18877_Content_32 = {
    Text = "Vindo daquela direção!"
  },
  AvgDialog_18877_Content_33 = {
    Text = "Vocês imediatamente correram na direção do som, colidindo com Jenkins na entrada da oficina"
  },
  AvgDialog_18877_Content_34 = {Text = "Jenkin?"},
  AvgDialog_18877_Content_35 = {
    Text = "Aigis não está no quarto! Aquele que estava falando pode—ah, de qualquer forma, vamos rápido!"
  },
  AvgDialog_18877_Content_36 = {
    Text = "Ao recordar a cena horrível na rua, você apressou os passos para entrar na oficina.\nEm breve, uma luz suave surgiu à frente do corredor"
  },
  AvgDialog_18877_Content_37 = {
    Text = "Era uma lanterna antiga, iluminando os rostos da mulher e da criança"
  },
  AvgDialog_18877_Content_38 = {
    Text = "Aigis! Eu ouvi gritos, você está bem?"
  },
  AvgDialog_18877_Content_39 = {
    Text = "A garota tremia nos braços de Sarah, enterrando o rosto mais fundo no pescoço dela.\nJenkins ficou surpreso e se virou furioso para Sarah"
  },
  AvgDialog_18877_Content_4 = {
    Text = "Olá, parceiro. Você gosta do George?"
  },
  AvgDialog_18877_Content_40 = {
    Text = "Sua bruxa, o que você fez com ela? Solte-a, ouviu?"
  },
  AvgDialog_18877_Content_41 = {Text = "..."},
  AvgDialog_18877_Content_42 = {
    Text = [[
Sarah silently set the girl down.
Aigis lowered her head, but you could still see in the light that her face was covered in tears]]
  },
  AvgDialog_18877_Content_43 = {
    Text = "Você pode levá-la para descansar? Aigis se perdeu e tem medo do escuro, ela precisa descansar agora"
  },
  AvgDialog_18877_Content_44 = {
    Text = "Jenkins olhou desconfiada para Sarah enquanto segurava a mão de Aigis"
  },
  AvgDialog_18877_Content_45 = {
    Text = "Aigis segurou o vestido de Sarah e começou a chorar suavemente"
  },
  AvgDialog_18877_Content_46 = {
    Text = "Vá, pequena Aigis"
  },
  AvgDialog_18877_Content_47 = {
    Text = "Durma bem, amanhã o pesadelo acabará, ok?"
  },
  AvgDialog_18877_Content_48 = {
    Text = "Mas... Senhorita Sarah..."
  },
  AvgDialog_18877_Content_49 = {
    Text = "Vamos. Eu tenho uma lanterna, não tenha medo"
  },
  AvgDialog_18877_Content_5 = {
    Text = "Tão bonita, quem não gosta! Não é, Aigis?"
  },
  AvgDialog_18877_Content_50 = {
    Text = "Duas crianças de mãos dadas se afastam lentamente.\nSarah se vira para vocês, esboçando um sorriso rígido"
  },
  AvgDialog_18877_Content_51 = {
    Text = "Desculpe, meu grito assustou vocês?"
  },
  AvgDialog_18877_Content_52 = {
    Text = "Dias de nevoeiro sempre deixam as pessoas tensas, eu também me assustei com uma sombra. Por favor, aceitem minhas desculpas e deixem-me preparar um chá para vocês"
  },
  AvgDialog_18877_Content_53 = {
    Text = "Não precisa se incomodar, Srta. Sarah, eu e {Male=senhor,Female=senhorita} podemos voltar sozinhos"
  },
  AvgDialog_18877_Content_54 = {
    Text = "Como isso pode ser? Por favor, me prometa, Lorde{Male=senhor,Female=senhorita}, Senhorita Mary.\nCaso contrário, não conseguirei descansar!"
  },
  AvgDialog_18877_Content_55 = {
    Text = "Se a senhorita Sarah insistir nisso, então venha conosco dar uma voltinha na oficina.\nAssim, o chá ficará ainda mais saboroso, não acha?"
  },
  AvgDialog_18877_Content_56 = {
    Text = "......ok. Por aqui, por favor"
  },
  AvgDialog_18877_Content_57 = {
    Text = [[
21:03, oficina de trabalho Lilian
corredor para o quarto da Aigis]]
  },
  AvgDialog_18877_Content_58 = {
    Text = "Jenkins, você... vá para o meu quarto. Eu vou ao banheiro"
  },
  AvgDialog_18877_Content_59 = {
    Text = "Vai sair de novo? Não tem medo? Quer que eu vá com você?"
  },
  AvgDialog_18877_Content_6 = {
    Text = [[
...
Desculpe, Jenkins, eu... preciso sair um momento]]
  },
  AvgDialog_18877_Content_60 = {
    Text = "Tudo bem, eu volto logo"
  },
  AvgDialog_18877_Content_61 = {Text = "Em breve."},
  AvgDialog_18877_Content_62 = {
    Text = "22:00, oficina de trabalho Lilian\nquarto de hóspedes"
  },
  AvgDialog_18877_Content_63 = {
    Text = "O tempo está quase acabando, a consulta de hoje termina aqui"
  },
  AvgDialog_18877_Content_64 = {
    Text = "Obrigado, doutora Clementine.\nApós cada conversa com você, sinto que minha mente fica mais clara"
  },
  AvgDialog_18877_Content_65 = {
    Text = "Isso é o que devo fazer.\nMe diga, você sabe o que fazer a seguir?"
  },
  AvgDialog_18877_Content_66 = {
    Text = "Cla-claro. Eu continuarei"
  },
  AvgDialog_18877_Content_67 = {
    Text = "Como ele disse: a beleza substituirá todo o sofrimento"
  },
  AvgDialog_18877_Content_7 = {
    Text = "Aigis? Para onde você vai? Ei, Aigis!"
  },
  AvgDialog_18877_Content_8 = {
    Text = [[
20:44, oficina de trabalho Lilian
corredor]]
  },
  AvgDialog_18877_Content_9 = {
    Text = "Correndo.\nAigis está correndo"
  },
  AvgDialog_18878_Content_1 = {
    Text = "Ogier e Ramona detiveram o Jenkin resistente dos dois lados."
  },
  AvgDialog_18878_Content_10 = {
    Text = "Velho Charlie tem um gato malhado que ele ama muito"
  },
  AvgDialog_18878_Content_11 = {
    Text = "\"Irmã... não vá...\""
  },
  AvgDialog_18878_Content_12 = {
    Text = "A voz de Jenkin emerge da massa de luz. Tenta se aproximar de você, mas está firmemente amarrada por fios negros, recuando como uma marionete sob o controle de alguém."
  },
  AvgDialog_18878_Content_13 = {
    Text = "Você entende imediatamente, alguém ou algo está controlando ela.\nVocê tenta libertá-la, mas os fios negros se afinam e desaparecem"
  },
  AvgDialog_18878_Content_14 = {
    Text = "\"Não... Aigis...?\""
  },
  AvgDialog_18878_Content_15 = {
    Text = "Os pontos de luz se afastam de repente, e o espaço negro se dissipa rapidamente"
  },
  AvgDialog_18878_Content_16 = {
    Text = "Você abre os olhos e encontra o olhar confuso de Jenkins"
  },
  AvgDialog_18878_Content_17 = {
    Text = "%player%... o que aconteceu?"
  },
  AvgDialog_18878_Content_18 = {
    Text = "Chirp chirp chirp chirp!"
  },
  AvgDialog_18878_Content_19 = {
    Text = "Jenkin piscou seus olhos secos e tentou se sentar, apenas para descobrir que suas mãos estavam amarradas atrás das costas."
  },
  AvgDialog_18878_Content_2 = {
    Text = "Ela está... histérica...?"
  },
  AvgDialog_18878_Content_20 = {
    Text = "O que está acontecendo?! Quem fez isso, solte-me agora!"
  },
  AvgDialog_18878_Content_21 = {
    Text = "Você acena para Ramona. Ela avança e rapidamente corta a corda no pulso de Jenkin com sua espada."
  },
  AvgDialog_18878_Content_22 = {
    Text = "Desculpe, a situação é urgente, tivemos que tomar algumas medidas de proteção.\nVocê... lembra o que fez agora há pouco?"
  },
  AvgDialog_18878_Content_23 = {
    Text = "Agora mesmo? Não tínhamos concordado em invadir o porão daquela mulher? Para passar tempo, Brown e eu nos escondemos no quarto de Aigis, esperando ela voltar. Acidentalmente adormecemos e tivemos um sonho bizarro..."
  },
  AvgDialog_18878_Content_24 = {
    Text = "Espere, este não é o quarto da Aigis. Como eu acabei aqui? O que você está planejando? Você vai me sequestrar e me silenciar?"
  },
  AvgDialog_18878_Content_25 = {
    Text = "Você realmente veio como prometido, mas agora você estava em um estado terrível, como se..."
  },
  AvgDialog_18878_Content_26 = {
    Text = "Sente como se algo estivesse controlando você. Em outras palavras, você pode ter sido hipnotizado."
  },
  AvgDialog_18878_Content_27 = {
    Text = "Hipnose... Ah! Poderia ser o psicólogo que levou Aigis?"
  },
  AvgDialog_18878_Content_28 = {
    Text = "Isso é bastante rude. A psicoterapia é uma ciência, não algum superpoder para controlar mentes... Ah, a ciência, semelhante ao que os <Blue:Pygmalions> buscam."
  },
  AvgDialog_18878_Content_3 = {
    Text = "Não, %player%, o espírito dela está inquieto.\nO poder mental da Chave Prata pode ter um efeito calmante."
  },
  AvgDialog_18878_Content_30 = {
    Text = "A espada de Ramona saiu da bainha em um instante. A lâmina prateada estava no pescoço de Clementine, que não mostrou medo e afastou a espada com dois dedos"
  },
  AvgDialog_18878_Content_31 = {
    Text = "Você observa cautelosamente a mulher à sua frente—sem portas ou janelas abertas, ela apareceu do nada. Silenciosa como um fantasma"
  },
  AvgDialog_18878_Content_32 = {
    Text = "Você é da Associação dos Escultores?"
  },
  AvgDialog_18878_Content_33 = {
    Text = "Sou apenas uma terceira parte útil, embora tenha algum interesse pessoal.\nVocê me intriga, Investigador especial."
  },
  AvgDialog_18878_Content_34 = {
    Text = "Ela sorriu para você, com um olhar que continha um fervor estranho"
  },
  AvgDialog_18878_Content_35 = {
    Text = "...Por que?"
  },
  AvgDialog_18878_Content_36 = {
    Text = "Clementine, com um sorriso misterioso, dá dois passos para trás e se curva ligeiramente para você."
  },
  AvgDialog_18878_Content_37 = {
    Text = "Falei o suficiente esta noite, o suficiente para fazer meu <Yellow:coração prateado> tremer de excitação."
  },
  AvgDialog_18878_Content_38 = {
    Text = "<Yellow:Coração de Prata>... Você é um Despertador?!"
  },
  AvgDialog_18878_Content_39 = {
    Text = "Desde que é assim, não podemos deixar você sair tão facilmente, Clementine."
  },
  AvgDialog_18878_Content_4 = {
    Text = "Ativar Chave de Prata"
  },
  AvgDialog_18878_Content_40 = {
    Text = "Não seria chato se a história do nosso encontro terminasse hoje?"
  },
  AvgDialog_18878_Content_41 = {
    Text = "Clementine tirou um pingente estranho de algum lugar e o balançou levemente, e um cansaço esmagador caiu sobre você. Você se apoiou na mesa, mal conseguindo ficar de pé, sem conseguir dar um passo"
  },
  AvgDialog_18878_Content_42 = {
    Text = "A espada de Ramona caiu, sua cabeça balançava levemente, quase não conseguia manter os olhos abertos.\nJenkins estava deitado no chão, imóvel, aparentemente adormecido"
  },
  AvgDialog_18878_Content_43 = {
    Text = "O que... você fez..."
  },
  AvgDialog_18878_Content_44 = {
    Text = "Um pequeno truque para me deixar sair daqui.\nCom suas habilidades, você deve voltar a si rapidamente, certo?"
  },
  AvgDialog_18878_Content_45 = {
    Text = "Adeus, Olho Pálido Cego. Nos encontraremos novamente no futuro..."
  },
  AvgDialog_18878_Content_46 = {
    Text = "Ela se curva para você e sai da sala.\nVocê não consegue mais se segurar e desaba de volta na cadeira."
  },
  AvgDialog_18878_Content_47 = {
    Text = "Clementine fechou a porta, cantarolando uma música alegre, acenou para o corredor e foi embora"
  },
  AvgDialog_18878_Content_48 = {
    Text = "Na escuridão, uma garota de vestido estava quieta como uma estátua.\nEla abaixou a cabeça, segurando uma venda branca"
  },
  AvgDialog_18878_Content_5 = {
    Text = "Você se encontra em um espaço de pura escuridão, onde pontos prateados que brilham fracamente formam conexões e ondulam como ondas, movendo-se em um padrão inscrutável."
  },
  AvgDialog_18878_Content_6 = {
    Text = "Você está entre eles, mas também acima deles. Você é um deles, mas não se encaixa. \nVocê não sabe exatamente o que eles são, só sabe que está aqui para encontrar alguém"
  },
  AvgDialog_18878_Content_7 = {
    Text = "\"Irmã... irmã...\""
  },
  AvgDialog_18878_Content_8 = {
    Text = "Você olha para o som, uma luz particularmente fraca piscando no mar de estrelas.\nFios pretos com um brilho metálico sinistro se entrelaçam, puxando-a e tornando-a imóvel."
  },
  AvgDialog_18878_Content_9 = {
    Text = "Uma melodia alegre surge levemente da linha negra, como uma canção infantil cantada por crianças."
  },
  AvgDialog_18879_Content_1 = {
    Text = "Você sai do beco e chega ao portão de ferro do albergue."
  },
  AvgDialog_18879_Content_2 = {
    Text = "Um homem de meia-idade com o rosto oleoso senta-se no banco de madeira perto da porta, um bastão preto amarrado em sua cintura e um cachimbo escuro na boca."
  },
  AvgDialog_18879_Content_3 = {
    Text = "Você nota uma pequena marca preta no braço do homem. A ferida triangular se assemelha a um mini abismo, com um líquido viscoso lentamente oozando para fora."
  },
  AvgDialog_18879_Content_4 = {
    Text = "Ramona limpou suavemente a garganta e deu um passo à frente com o queixo erguido, como um orgulhoso mordomo nobre."
  },
  AvgDialog_18879_Content_5 = {
    Text = "Bom dia, senhor. Por favor, informe aqueles dentro que um convidado chegou."
  },
  AvgDialog_18879_Content_6 = {
    Text = "Antes que ela pudesse terminar de falar, o corpo do guarda de repente se deformou. Lodo negro jorrou de seu peito, formando um enorme monstro que se arrastou em sua direção."
  },
  AvgDialog_18880_Content_1 = {
    Text = "Irmã, o que são aquelas coisas? Irmã?"
  },
  AvgDialog_18880_Content_10 = {
    Text = "E você só pode assistir ela cair, cair, aterrissando no sujo chão do esgoto, a dura <Red:estátua> se espatifando em pedaços de vários tamanhos."
  },
  AvgDialog_18880_Content_11 = {
    Text = "...Estátua? Por que uma estátua?"
  },
  AvgDialog_18880_Content_12 = {
    Text = "Sem tempo para pensar, você olha para onde sua irmã caiu."
  },
  AvgDialog_18880_Content_13 = {
    Text = "Não... não pode ser..."
  },
  AvgDialog_18880_Content_14 = {
    Text = "A garotinha que você conhece está lá, sua venda branca caiu, os olhos vazios, segurando uma fita vermelha como sangue."
  },
  AvgDialog_18880_Content_2 = {
    Text = "Não pergunte, apenas corra, Jenkin."
  },
  AvgDialog_18880_Content_3 = {
    Text = "Os monstros estão se aproximando, forçando você gradualmente em direção ao Abismo."
  },
  AvgDialog_18880_Content_4 = {
    Text = "Ela é apenas uma criança dos bairros pobres, não sabe nada e nunca representará qualquer ameaça para você..."
  },
  AvgDialog_18880_Content_5 = {
    Text = "Seguindo as instruções de sua irmã, você desce pelo tubo de esgoto enquanto carrega Brown."
  },
  AvgDialog_18880_Content_6 = {
    Text = "<Shake:Por favor, eu te imploro...>"
  },
  AvgDialog_18880_Content_7 = {
    Text = "Aquilo foi a última meia frase que minha irmã disse."
  },
  AvgDialog_18880_Content_8 = {
    Text = "No instante em que a voz foi cortada, uma silhueta familiar despencou do céu, ainda segurando metade de uma fita vermelha."
  },
  AvgDialog_18880_Content_9 = {
    Text = "A fita foi feita sob medida para ela usando a mesada que você economizou durante o último ano.\nVocê nunca conheceu seus pais biológicos; ela é a pessoa mais próxima de você."
  },
  AvgDialog_18881_Content_1 = {
    Text = "De repente, uma sombra negra disparou do canto, passando por Aigis e colidindo com a parede à esquerda."
  },
  AvgDialog_18881_Content_10 = {
    Text = "Ele de repente se libertou da pessoa atrás dele e se lançou contra você."
  },
  AvgDialog_18881_Content_2 = {
    Text = "Você finalmente vê claramente: é um homem desgrenhado.\nEle está descalço, vestindo roupas de caridade, com marcas claras de ataduras em seus pulsos e tornozelos."
  },
  AvgDialog_18881_Content_3 = {
    Text = "Alguns atendentes pareciam estar correndo atrás dele, tentando afastá-lo.\nO homem permaneceu impassível. Ele se recostou e então bateu a cabeça na parede fria e dura."
  },
  AvgDialog_18881_Content_4 = {
    Text = "Atrás de você, Aigis ofegou."
  },
  AvgDialog_18881_Content_5 = {Text = "—!"},
  AvgDialog_18881_Content_6 = {
    Text = "O som pressado da carne batendo na parede de tijolos aumentou em frequência enquanto o homem continuava a colidir sem mostrar sinais de dor."
  },
  AvgDialog_18881_Content_7 = {
    Text = "O sangue respingou, deixando manchas escuras nas paredes e no chão.\nVocê avança para ajudar, mas o homem de repente para de se mover."
  },
  AvgDialog_18881_Content_8 = {
    Text = "Ele cheirou fundo, como um cachorro, e então lentamente e rigidamente se virou para você."
  },
  AvgDialog_18881_Content_9 = {
    Text = "O sangue escorre lentamente pela sua testa. A ferida, inchada do impacto, abriu a pele, revelando um vislumbre de osso branco."
  },
  AvgDialog_18882_Content_1 = {
    Text = "Vocês mal começaram a perseguir, e as crianças que estavam brincando rapidamente se reúnem na sua frente, bloqueando o caminho"
  },
  AvgDialog_18882_Content_2 = {
    Text = "Cavalheiro gentil, me dê alguns trocados. Se não for a Crina, o Pensh servirá..."
  },
  AvgDialog_18882_Content_3 = {
    Text = "Se você tirar a mão do bolso de %player%, talvez possamos considerar isso."
  },
  AvgDialog_18882_Content_4 = {Text = "Hmph!"},
  AvgDialog_18882_Content_5 = {
    Text = "A criança saiu correndo."
  },
  AvgDialog_18882_Content_6 = {
    Text = "É hora de dar uma pequena lição a essas crianças infelizes e não educadas, você não acha?"
  },
  AvgDialog_18882_Content_7 = {
    Text = "Experimente."
  },
  AvgDialog_18882_Content_8 = {
    Text = "Eles parecem estar em conluio com os de capuz marrom"
  },
  AvgDialog_18882_Content_9 = {
    Text = "Certo, vamos. Defender a justiça também é um dever cívico."
  },
  AvgDialog_18883_Content_1 = {
    Text = "Ogier corre ansiosamente por trás de um muro de tijolos vermelhos enegrecidos, manchado pelo ar de Londinium."
  },
  AvgDialog_18883_Content_10 = {
    Text = "Estou bem, e este jovem não quis fazer mal, certo?"
  },
  AvgDialog_18883_Content_11 = {
    Text = "Sinto muito. Não consegui perceber a situação ao meu redor a tempo."
  },
  AvgDialog_18883_Content_12 = {
    Text = "Clementine ofereceu um sorriso gentil, afastando poeira imaginária de suas roupas.\nEla acenou em cumprimento e partiu graciosamente."
  },
  AvgDialog_18883_Content_13 = {
    Text = "Ao olhar para cima, você viu \"Casa de Alívio Lily\" escrito em grandes letras enferrujadas em uma enorme placa de ferro.\nAbaixo, um guarda de segurança com aparência entediada estava sentado sem fazer nada."
  },
  AvgDialog_18883_Content_14 = {
    Text = [[
A esta altura, vamos entrar e dar uma olhada.
Lembram-se de suas identidades falsas, Ashe{Male=senhor,Female=senhorita}, Jovem Mestre Ashe?]]
  },
  AvgDialog_18883_Content_15 = {
    Text = "Não se preocupe, querida Mary, o mordomo."
  },
  AvgDialog_18883_Content_16 = {
    Text = "À sua disposição, Senhora Mary."
  },
  AvgDialog_18883_Content_17 = {
    Text = "...Não faz mal, contanto que a desvio não seja muito grande."
  },
  AvgDialog_18883_Content_2 = {
    Text = "Primeira vez trabalhando no campo com você, meu senhor. Não posso cometer erros..."
  },
  AvgDialog_18883_Content_3 = {Text = "Ugh!"},
  AvgDialog_18883_Content_4 = {
    Text = "Uma porta de ferro embutida na parede de tijolos se abre para dentro, e uma mulher vestida de branco aparece de repente, colidindo de frente com Ogier."
  },
  AvgDialog_18883_Content_5 = {
    Text = "<Small: Ah...>"
  },
  AvgDialog_18883_Content_6 = {
    Text = "Não, desculpe! Você está bem?"
  },
  AvgDialog_18883_Content_7 = {
    Text = "Você e Ramona finalmente alcançaram Ogier."
  },
  AvgDialog_18883_Content_8 = {
    Text = "Desculpe, nós... Hã, você é o psicólogo que estava distribuindo questionários mais cedo?"
  },
  AvgDialog_18883_Content_9 = {
    Text = "É uma grande honra para mim que você se lembre de mim após apenas um encontro."
  },
  AvgDialog_18884_Content_1 = {
    Text = "Tantos monstros estão escondidos neste espaço subterrâneo apertado..."
  },
  AvgDialog_18884_Content_2 = {
    Text = "Esta casa de assistência realmente não deve ser subestimada."
  },
  AvgDialog_18884_Content_3 = {
    Text = "Shh, por favor, mantenha a calma. Está quase acabando."
  },
  AvgDialog_18885_Content_1 = {
    Text = "O monstro negro soltou um rugido e colapsou em lodo, caindo no chão."
  },
  AvgDialog_18885_Content_10 = {
    Text = "Você encosta os restos do guarda na grade de ferro e então entra no Asilo de Lily."
  },
  AvgDialog_18885_Content_11 = {
    Text = "No final da esquina, uma figura branca passou rapidamente."
  },
  AvgDialog_18885_Content_12 = {
    Text = "Eles são... Precisamos voltar antes que encontrem a senhora Sarah. Vamos entrar pela janela da cozinha."
  },
  AvgDialog_18885_Content_13 = {
    Text = "Aquelas pessoas podem ser de ajuda; não resista à chegada delas."
  },
  AvgDialog_18885_Content_14 = {Text = "Não!"},
  AvgDialog_18885_Content_15 = {
    Text = "Eu juro, aquelas pessoas não ficarão assustadas com nada que aconteça aqui."
  },
  AvgDialog_18885_Content_16 = {
    Text = "Não... eu não posso envolver mais pessoas... É perigoso para qualquer um que se aproxime. Você sabe disso..."
  },
  AvgDialog_18885_Content_17 = {
    Text = "<Red: Sr. Anderson.>"
  },
  AvgDialog_18885_Content_2 = {
    Text = "Isto... como ele mudou de repente!"
  },
  AvgDialog_18885_Content_3 = {
    Text = "<Yellow:Erosão de Dissolução Precoce>.\nNão deveria acontecer tão cedo... não deveria acontecer de forma alguma."
  },
  AvgDialog_18885_Content_4 = {
    Text = "Duass vozes ecoam pelo broche, ressoando em suas mentes."
  },
  AvgDialog_18885_Content_5 = {
    Text = "Parece o resultado de uma catálise artificial."
  },
  AvgDialog_18885_Content_6 = {
    Text = "A Dissolução anormal... está provavelmente conectada à <Yellow:a disappearance of Investigator Sean Anderson>. \nÉ possível que alguém tenha colocado seus olhos no hospício... e até mesmo em você."
  },
  AvgDialog_18885_Content_7 = {
    Text = "Nós vamos ficar de olho nisso."
  },
  AvgDialog_18885_Content_8 = {
    Text = "Fique vigilante, Guardião."
  },
  AvgDialog_18885_Content_9 = {Text = "Eu irei."},
  AvgDialog_18886_Content_1 = {
    Text = "Parece que este recém-chegado é um pouco diferente."
  },
  AvgDialog_18886_Content_2 = {
    Text = "É hora de ficar sério."
  },
  AvgDialog_18887_Content_1 = {
    Text = "Enquanto isso—\nOgier observava a cena no pátio do asilo através da janela."
  },
  AvgDialog_18887_Content_10 = {
    Text = "Não, você não pode levá-la embora!"
  },
  AvgDialog_18887_Content_11 = {
    Text = "Pequeno, você entendeu algo errado?\nNós somos médicos contratados pela casa de pobres para levá-la para um check-up regular."
  },
  AvgDialog_18887_Content_12 = {
    Text = "O rosto de Ogier ficou vermelho quando ele teve uma inspiração repentina."
  },
  AvgDialog_18887_Content_13 = {
    Text = "De jeito nenhum! %player% disse que logo iremos perguntar à Aigis sobre a situação em nome do Nobre Ash. Você não pode levá-la agora."
  },
  AvgDialog_18887_Content_14 = {
    Text = "Para crianças desobedientes, pode ser necessário recorrer a alguns métodos de adultos."
  },
  AvgDialog_18887_Content_2 = {
    Text = "A porta de ferro rangeu ao abrir, e um grupo de figuras vestidas de branco entrou.\nAs crianças se alinharam na névoa cinza, permitindo que fossem selecionadas."
  },
  AvgDialog_18887_Content_3 = {
    Text = "Entre as crianças, Ogier reconheceu uma figura familiar:\na pequena garota branca que tinha recebido todos naquele dia."
  },
  AvgDialog_18887_Content_4 = {
    Text = "Ela encolheu os ombros e baixou a cabeça, torcendo firmemente a barra de suas roupas. Embora parecesse assustada, ainda assim deu um passo à frente para ficar diante das outras crianças."
  },
  AvgDialog_18887_Content_5 = {
    Text = "Ela tentou encolher-se, ainda mais, tentando desaparecer em seu próprio corpo. Uma sombra alta pairava sobre ela; ela tremeu e não ousou se mover."
  },
  AvgDialog_18887_Content_6 = {
    Text = "Conflito eclodiu.\nO estranho de traje branco agarrou o braço da menina, aparentemente forçando-a a obedecê-lo."
  },
  AvgDialog_18887_Content_7 = {Text = "—Pare!"},
  AvgDialog_18887_Content_8 = {
    Text = "Ogier não pôde mais se conter e avançou diretamente entre o estranho vestido de branco e a garota."
  },
  AvgDialog_18887_Content_9 = {
    Text = "Ai, Jovem Mestre Ashe?"
  },
  AvgDialog_18888_Content_1 = {
    Text = "Vovô Robert... como isso pôde acontecer..."
  },
  AvgDialog_18888_Content_2 = {
    Text = "Cuidado, ele parece ter perdido completamente a cabeça!"
  },
  AvgDialog_18889_Content_1 = {
    Text = "Por favor, não machuque a Senhorita Sarah. Eu lhe contarei tudo..."
  },
  AvgDialog_18889_Content_2 = {
    Text = "Ai... Ji Si"
  },
  AvgDialog_18889_Content_3 = {
    Text = "Ela ainda tem um brilho de consciência!"
  },
  AvgDialog_18889_Content_4 = {
    Text = "Elimine primeiro esses monstros, restrinja Sarah! Precisamos interrogá-la sobre o paradeiro de Sean!"
  },
  AvgDialog_18889_Content_5 = {Text = "Entendido!"},
  AvgDialog_18890_Content_1 = {
    Text = "Ramona se moveu rapidamente atrás do homem, segurando seu pulso com uma mão e pressionando seu ombro com a outra. Ela torceu seu braço para trás, restringindo firmemente seus movimentos."
  },
  AvgDialog_18890_Content_10 = {
    Text = "Já conheço bem aqui, Srta. Sarah, não precisa se preocupar.\nMas por que a pequena Ai e Aigis estão chorando tanto? Alguém as machucou?"
  },
  AvgDialog_18890_Content_11 = {
    Text = "<Small:Estou bem, Sr. Rogers.>"
  },
  AvgDialog_18890_Content_12 = {
    Text = "Sob o olhar ligeiramente urgente do reitor, Aigis engoliu abruptamente suas palavras.\nEla se curvou para todos, deu a você um último olhar e sua pequena figura desapareceu atrás da porta."
  },
  AvgDialog_18890_Content_13 = {
    Text = "Sinto muito por esconder a existência da enfermaria de você. Eu estava apenas preocupado que as condições dos pacientes pudessem se espalhar para você..."
  },
  AvgDialog_18890_Content_14 = {
    Text = "Sussurro, não vamos nos detiver sobre isso. Permita-me apresentar nosso patrono de longa data — o renomado escultor de cera, Sr. Rogers."
  },
  AvgDialog_18890_Content_15 = {
    Text = "Esta área médica e o tratamento dos pacientes foram todos possíveis graças a ele."
  },
  AvgDialog_18890_Content_16 = {
    Text = "George Rogers, prazer em conhecer todos vocês."
  },
  AvgDialog_18890_Content_17 = {
    Text = "Ele liberta uma das mãos para balançar suavemente a sua.\nNo instante em que suas palmas se tocam, uma onda intensa de tontura o invade."
  },
  AvgDialog_18890_Content_18 = {
    Text = "Tudo ao seu redor parece dissolver-se como cera derretida; até a pessoa à sua frente se torce e deforma. Debaixo do rosto, esqueletos pálidos se entrelaçam como vinhas."
  },
  AvgDialog_18890_Content_19 = {
    Text = "A estranha ilusão desaparece em alguns piscares, deixando apenas um zumbido agudo nos seus ouvidos—era uma ilusão nascida da fadiga? Você não sabe."
  },
  AvgDialog_18890_Content_2 = {
    Text = "Ogier rapidamente avançou e, com a assistência de Ramona, amarrou suas mãos e pés com tiras de pano. \nO homem continuou a lutar, expondo uma cicatriz peculiar através de seu colarinho aberto."
  },
  AvgDialog_18890_Content_20 = {
    Text = "Você só sabe que isso é muito semelhante ao que você experienciou no cemitério há alguns dias."
  },
  AvgDialog_18890_Content_21 = {
    Text = "...Todo mês, ele pessoalmente vem verificar os pacientes. Ele é verdadeiramente um grande benfeitor e um grande apoiador do nosso hospital de caridade."
  },
  AvgDialog_18890_Content_22 = {
    Text = "A Srta. Sarah me elogia demais, sou apenas uma pessoa comum querendo fazer algo pelo mundo"
  },
  AvgDialog_18890_Content_23 = {
    Text = "Falando nisso, você mencionou ontem que viria hoje com um <Yellow:amigo>..."
  },
  AvgDialog_18890_Content_24 = {
    Text = "A escultora, <Yellow:Sculptor>, encontrou inspiração e já retornou ao estúdio."
  },
  AvgDialog_18890_Content_25 = {
    Text = "Quem são esses jovens...?"
  },
  AvgDialog_18890_Content_26 = {
    Text = "...{Male=senhor,Female=senhora}? Ash {Male=senhor,Female=senhora}?"
  },
  AvgDialog_18890_Content_27 = {
    Text = "Oh, desculpe, posso estar um pouco distraído, pois não descansei bem na noite passada. Prazer em conhecê-lo, Sr. Rogers.\nMeu nome é Ash. Este é meu irmão mais novo Ogier e nossa governanta Mary. Este é Jenkins..."
  },
  AvgDialog_18890_Content_28 = {Text = "Ei?"},
  AvgDialog_18890_Content_29 = {
    Text = "Para onde aquele garoto Jenkin foi?"
  },
  AvgDialog_18890_Content_3 = {
    Text = "Uma cicatriz profunda atravessa o peito, mal mantida unida por pontos torcidos. Uma secreção negra ainda escorre lentamente das lacunas."
  },
  AvgDialog_18890_Content_4 = {
    Text = "Passos apressados soam do lado de fora da área médica. Sarah aparece, sem fôlego, segurando a moldura da porta."
  },
  AvgDialog_18890_Content_5 = {
    Text = "Vendo que tudo dentro havia sido resolvido, ela pareceu relaxar por um momento, então imediatamente franziu a testa e se virou para a garota encolhida no canto."
  },
  AvgDialog_18890_Content_6 = {
    Text = "Aigis! Eu não disse que os patrocinadores não são permitidos na área médica?\nSe algo acontecer a um patrocinador aqui, quem..."
  },
  AvgDialog_18890_Content_7 = {
    Text = "O que está acontecendo?"
  },
  AvgDialog_18890_Content_8 = {
    Text = "Você se vira seguindo o som e encontra duas pessoas paradas atrás de você.\nUma delas você reconhece: a mulher de branco com quem Ogier uma vez se encontrou."
  },
  AvgDialog_18890_Content_9 = {
    Text = "Sr. Rogers, Dr. Fairfax!\nSinto muito, por favor, aproveitem alguns petiscos na sala de espera enquanto aguardam. Eu irei cumprimentá-los assim que terminar aqui."
  },
  AvgDialog_18891_Content_1 = {
    Text = "Pequeno Detetive"
  },
  AvgDialog_18891_Content_10 = {
    Text = "Seguindo a localização indicada no pedaço de papel, você chega ao quintal. Antes de se aproximar, ouve uma voz infantil murmurando perto da base da parede."
  },
  AvgDialog_18891_Content_11 = {
    Text = "Lembre-se, se o patrocinador estiver contra nós, você vai e nos avisa.\nAquela mulher desagradável definitivamente enviará Aigis para o <Yellow:Madman>. Apenas traga-a."
  },
  AvgDialog_18891_Content_12 = {
    Text = "Que tipo de lunático?"
  },
  AvgDialog_18891_Content_13 = {
    Text = "Uau! Por que você apareceu de repente! E eu não te disse para vir sozinho!"
  },
  AvgDialog_18891_Content_14 = {
    Text = "O pequeno rato correu para o ombro da criança de capuz, tremendo nervosamente seus bigodes para você."
  },
  AvgDialog_18891_Content_15 = {
    Text = "Isso não é minha carteira. Eu não consigo tomar uma decisão."
  },
  AvgDialog_18891_Content_16 = {
    Text = "Pare de fingir. Nada escapa dos olhos do pequeno rato—A irmã de cabelo branco está disfarçada de mordomo, a de cabelo dourado está encarregada de pedir direções, e você é a única que não está fazendo nada com as mãos nos bolsos."
  },
  AvgDialog_18891_Content_17 = {
    Text = "Não pense que eu não vejo — você é quem está no comando. Afinal, isso não está cheio de certificados para jovens mestres."
  },
  AvgDialog_18891_Content_18 = {
    Text = "Jenkin estalou os dedos, puxando uma carteira do nada. Tinha uma textura e forma familiares, gravadas com o emblema da Universidade Mythag—era a carteira de Ogier."
  },
  AvgDialog_18891_Content_19 = {
    Text = "Não é verdade, Brown?"
  },
  AvgDialog_18891_Content_2 = {
    Text = "Como você pode ver, apesar de nossos melhores esforços para abrigar aqueles que precisam, simplesmente há pessoas demais! Nesse ritmo, a casa dos pobres não vai aguentar por muito mais tempo... Eu... suspiro!"
  },
  AvgDialog_18891_Content_20 = {
    Text = "Chiado, chiado!"
  },
  AvgDialog_18891_Content_21 = {
    Text = "Ah! Minha carteira!"
  },
  AvgDialog_18891_Content_22 = {
    Text = "Ogier rapidamente estendeu a mão para pegar a carteira, mas Jenkin desviou e a carteira desapareceu como mágica mais uma vez."
  },
  AvgDialog_18891_Content_23 = {
    Text = "Quão rude, cabelo dourado.\nÉ assim que todos da Universidade Mythag tratam garotas que estão nas ruas?"
  },
  AvgDialog_18891_Content_24 = {
    Text = "Você é... uma garota?"
  },
  AvgDialog_18891_Content_25 = {
    Text = "Você está cego!? Claro, sou uma mulher, uma mulher!"
  },
  AvgDialog_18891_Content_26 = {
    Text = "Tudo bem, não vamos falar sobre isso. Eu aconselho você a se comportar e apenas seguir meu —"
  },
  AvgDialog_18891_Content_27 = {
    Text = "Certo, concordamos. Em troca, você nos leva para ver aqueles <Yellow:malucos> que você mencionou."
  },
  AvgDialog_18891_Content_28 = {Text = "...Hã?"},
  AvgDialog_18891_Content_29 = {
    Text = "Você não está nos pedindo para encontrar alguém na casa de caridade para você? Diga-me, quem você está procurando?"
  },
  AvgDialog_18891_Content_3 = {
    Text = "A Miss Sha, a Miss Sarah trabalha tão duro todos os dias. Ela até vendeu suas coisas favoritas para apoiar o abrigo. Por favor, por favor, nos ajude..."
  },
  AvgDialog_18891_Content_30 = {
    Text = "Eu ainda não disse nada!"
  },
  AvgDialog_18891_Content_31 = {
    Text = "Você diria isso. Então eu sugiro que pulemos a sondagem desnecessária e sejamos honestos um com o outro."
  },
  AvgDialog_18891_Content_32 = {
    Text = "Você deve estar aqui para investigar o <Yellow:caso de pessoas desaparecidas> perto do orfanato, certo? \nEstamos aqui pela mesma razão. Ajudar não é nenhum problema."
  },
  AvgDialog_18891_Content_33 = {
    Text = "Como... como você soube?"
  },
  AvgDialog_18891_Content_34 = {
    Text = "É simples. Você tem mãos ágeis e um grupo de parceiros confiáveis, o que lhe permite ganhar uma renda estável, mas ilegal."
  },
  AvgDialog_18891_Content_35 = {
    Text = "Ramona falou enquanto caminhava habitualmente pelo pátio."
  },
  AvgDialog_18891_Content_36 = {
    Text = "Você tem um plano completo: você lida com a tarefa principal, eles fornecem cobertura para garantir sua fuga tranquila. Como pagamento, você lhes dará uma parte."
  },
  AvgDialog_18891_Content_37 = {
    Text = "Você pode viver uma vida mais confortável e livre nas ruas; não há necessidade de depender do pobre. Além disso, entrar no pobre sem permissão pode te meter em sérios problemas se você for pego."
  },
  AvgDialog_18891_Content_38 = {
    Text = "Por quê? O que te motiva a ficar na casa de trabalho, mesmo com o risco de multas ou prisão?"
  },
  AvgDialog_18891_Content_39 = {
    Text = "Isso, junto com a recente onda de desaparecimentos nas proximidades, leva a uma suspeita:\nSeu ente querido ou amigo desapareceu, e você suspeita que a casa de pobres esteja envolvida."
  },
  AvgDialog_18891_Content_4 = {
    Text = "Assistindo ao drama entre os dois—principalmente Sarah—tornando-se cada vez mais exagerado, você se sente bastante impotente."
  },
  AvgDialog_18891_Content_40 = {
    Text = "A garota ficou olhando em branco para Ramona por um bom tempo antes de reagir."
  },
  AvgDialog_18891_Content_41 = {
    Text = "Nós nem trocamos dez frases, mas você age como se estivesse me seguindo há dez dias..."
  },
  AvgDialog_18891_Content_42 = {
    Text = "Incluindo a vez em que você pegou emprestado a carteira de Ogier, você falou conosco dezesseis vezes.\nCombinado com observações do mundo real, isso é suficiente para analisar e deduzir sua história de vida."
  },
  AvgDialog_18891_Content_43 = {
    Text = "...Você é realmente impressionante. Nesse caso, Marrom."
  },
  AvgDialog_18891_Content_44 = {Text = "Chiado!"},
  AvgDialog_18891_Content_45 = {
    Text = "O pequeno rato chamado Brown chiou, saltando da árvore com uma carteira e jogando-a nos braços de Ogier."
  },
  AvgDialog_18891_Content_46 = {
    Text = "Vou te levar para ver os lunáticos e te contar tudo que sei. Em troca—"
  },
  AvgDialog_18891_Content_47 = {
    Text = "Você deve me ajudar a derrotar o fantasma da casa de pobres e a salvar minha irmã, <Blue:Mason>."
  },
  AvgDialog_18891_Content_48 = {
    Text = "Você segue Jenkin pelos corredores da casa de pobres."
  },
  AvgDialog_18891_Content_49 = {
    Text = "Minha irmã vai à casa de caridade toda quinta-feira para coletar roupas e levá-las para casa para lavar. Talvez essas roupas não estivessem limpas também, pois ela pegou a recente doença chamada \"<Yellow:Hysteria>.\""
  },
  AvgDialog_18891_Content_5 = {
    Text = "Naquele momento, uma pequena bola de papel atingiu sua cabeça."
  },
  AvgDialog_18891_Content_50 = {
    Text = "Um médico do hospital de caridade estava passando para uma consulta.\nAlgum tempo atrás, ela disse que viria para tratamento e nunca retornou para casa."
  },
  AvgDialog_18891_Content_51 = {
    Text = "Jenkin parece muito ansiosa."
  },
  AvgDialog_18891_Content_52 = {
    Text = "Eu não sei por quê, mas recentemente não consigo lembrar como minha irmã é."
  },
  AvgDialog_18891_Content_53 = {
    Text = "Às vezes, ver algo que minha irmã deixou para trás traz de volta memórias brevemente, mas elas rapidamente desvanecem."
  },
  AvgDialog_18891_Content_54 = {
    Text = "Ramona parou de repente e acenou para você com a cabeça."
  },
  AvgDialog_18891_Content_55 = {
    Text = "Por que você parou? Você não vai ver o médico louco?"
  },
  AvgDialog_18891_Content_56 = {
    Text = "A respeito da doença da sua irmã... podemos ter algumas pistas."
  },
  AvgDialog_18891_Content_57 = {Text = "..."},
  AvgDialog_18891_Content_58 = {
    Text = "Depois de enviar um pedido de divulgação de informações via comunicações, Ramona lentamente se virou para Jenkin e começou a explicar informações relacionadas à Dissolução."
  },
  AvgDialog_18891_Content_59 = {
    Text = "Jenkin, sua irmã está afetada por um fenômeno especial de Dissolução. Esse fenômeno faz com que as pessoas esqueçam gradualmente da existência dela."
  },
  AvgDialog_18891_Content_6 = {
    Text = "De onde você veio—"
  },
  AvgDialog_18891_Content_60 = {
    Text = "O corpo, identidade, passado e conexões sociais... desaparecerão completamente sem deixar vestígios."
  },
  AvgDialog_18891_Content_61 = {
    Text = "As condições daqueles lunáticos que você mencionou soam como <Yellow:sintomas iniciais de Dissolução>. Sua irmã já alcançou o ponto onde sua existência está começando a ser apagada; temo que ela..."
  },
  AvgDialog_18891_Content_62 = {
    Text = "Jenkin, há quanto tempo Mason... está desaparecida?"
  },
  AvgDialog_18891_Content_63 = {
    Text = "27 dias. Tenho contado cada dia desde então."
  },
  AvgDialog_18891_Content_64 = {
    Text = "Vendo a expressão preocupada de Ramona, Jenkins fungou."
  },
  AvgDialog_18891_Content_65 = {
    Text = "Eu sei, passou tanto tempo que você deve ter perdido a esperança.\nMas eu acredito que minha irmã ainda está viva... A intuição das crianças de rua é muito afiada."
  },
  AvgDialog_18891_Content_66 = {
    Text = "Então... eu devo me apressar para encontrar minha irmã. Caso contrário, posso esquecer completamente o seu rosto e não reconhecê-la mesmo que nos encontremos cara a cara."
  },
  AvgDialog_18891_Content_67 = {
    Text = "Não fique triste, nós vamos ajudar você a encontrar sua irmã. Quando você a ver, você não vai se lembrar?"
  },
  AvgDialog_18891_Content_68 = {
    Text = "Ramona permaneceu em silêncio.\nSob seu olhar um tanto melancólico, você recordou o conteúdo que a Boneca narrava na aula."
  },
  AvgDialog_18891_Content_69 = {
    Text = "<Yellow:\"A eliminação da existência é o sintoma final da Dissolução, e o processo é irreversível.\">"
  },
  AvgDialog_18891_Content_7 = {
    Text = "Você se estendeu para parar a raiva de Sarah, desenrolando o papel amassado. Nele há uma linha de escrita rabiscada."
  },
  AvgDialog_18891_Content_8 = {
    Text = "\"Se você quiser sua velha bolsa de volta, venha ao quintal você mesmo.\""
  },
  AvgDialog_18891_Content_9 = {Text = "..."},
  AvgDialog_18892_Content_1 = {
    Text = "Você é acordado abruptamente por um chiado agudo e urgente de camundongos. Ramona é a primeira a se levantar da cama e acende a luz do quarto."
  },
  AvgDialog_18892_Content_10 = {
    Text = "A lâmina afiada reflete uma luz fria, a faca curta revelando seu rosto."
  },
  AvgDialog_18892_Content_11 = {Text = "Quem!"},
  AvgDialog_18892_Content_12 = {
    Text = "Seus reflexos condicionados do treinamento permitem que você desvie a tempo, permitindo que você vislumbre a figura que se aproxima."
  },
  AvgDialog_18892_Content_13 = {Text = "Jenkin?!"},
  AvgDialog_18892_Content_14 = {
    Text = "Os olhos ocos da garota carecem de qualquer cor. Ela parece quase atordoada, completamente insensível aos seus chamados."
  },
  AvgDialog_18892_Content_15 = {
    Text = "Eu irei... vingar... minha irmã..."
  },
  AvgDialog_18892_Content_16 = {
    Text = "Os movimentos dela são extraordinariamente ágeis, sua lâmina cortando um arco frio através do ar.\nSem lhe dar mais tempo para pensar, a garota avança contra você novamente."
  },
  AvgDialog_18892_Content_17 = {
    Text = "Parece que só podemos dominá-la antes de interrogar.\nRamona, Ogier, atraia-a para uma área aberta!"
  },
  AvgDialog_18892_Content_18 = {Text = "Aqui!"},
  AvgDialog_18892_Content_19 = {
    Text = "À sua ordem!"
  },
  AvgDialog_18892_Content_2 = {
    Text = "Brown? Por que você está aqui sozinho?"
  },
  AvgDialog_18892_Content_3 = {
    Text = "Squeak—! Squeak squeak!"
  },
  AvgDialog_18892_Content_4 = {
    Text = "Nós não somos Jenkin. Nós não entendemos o que você quer dizer."
  },
  AvgDialog_18892_Content_5 = {
    Text = "É hora. Jenkin deve se juntar a nós em breve."
  },
  AvgDialog_18892_Content_6 = {
    Text = "Você olha pela janela; em meio à frauma neblina branca, as sombras dos edifícios se erguem como estátuas em um cemitério."
  },
  AvgDialog_18892_Content_7 = {
    Text = "A porta se abriu com um pequeno rangido, deixando entrar o vento frio da noite através da fenda escura."
  },
  AvgDialog_18892_Content_8 = {
    Text = "Uma sombra rápida saltou de trás da mesa e cadeiras, atacando você em um instante"
  },
  AvgDialog_18893_Content_1 = {
    Text = "Primavera de Botticelli"
  },
  AvgDialog_18893_Content_10 = {
    Text = "O rato ataca o furão."
  },
  AvgDialog_18893_Content_11 = {
    Text = "Quem você está chamando de rato?!"
  },
  AvgDialog_18893_Content_12 = {
    Text = "Quem você está chamando de furão?!"
  },
  AvgDialog_18893_Content_13 = {
    Text = "Hannah? Jenkin? O que você está..."
  },
  AvgDialog_18893_Content_14 = {
    Text = "Não me culpe, foi ela quem chamou os guardas primeiro!"
  },
  AvgDialog_18893_Content_15 = {
    Text = "Oh, vai, foi apenas uma piada. A vida não é divertida se você levar tão a sério."
  },
  AvgDialog_18893_Content_16 = {
    Text = "Então ela veio te procurar, certo? Onde vocês se conheceram, Lily do Asilo? Ah! Ela é a pequena Jenkin, não é?"
  },
  AvgDialog_18893_Content_17 = {
    Text = "Não é à toa que você é a primeira doninha do Reino de Leo. Está coletando material para o jornal da escola?"
  },
  AvgDialog_18893_Content_18 = {
    Text = "É mais que isso. Ramona, você me conhece—informação é minha vida."
  },
  AvgDialog_18893_Content_19 = {
    Text = "Então, à luz do dia, o que poderia levar uma pobre órfã a se aventurar sozinha na floresta profunda?"
  },
  AvgDialog_18893_Content_2 = {
    Text = [[
13:20, Londinium
Universidade Mythag]]
  },
  AvgDialog_18893_Content_20 = {
    Text = "A pessoa que ela busca pode trazer alguma luz para ela?\nHannah Peasley, repórter da linha de frente, está prestes a começar sua cobertura!"
  },
  AvgDialog_18893_Content_21 = {
    Text = "Hannah falou enquanto tirava um caderno de algum lugar, olhando para vocês com expectativa, pronta para anotar cada palavra"
  },
  AvgDialog_18893_Content_22 = {
    Text = "......Agora entendi, nesta universidade maluca, ninguém fala de forma compreensível"
  },
  AvgDialog_18893_Content_23 = {
    Text = "Sou inocente, de verdade"
  },
  AvgDialog_18893_Content_24 = {
    Text = "Desde que ela não esteja aqui.\nE você, Jenkins, aconteceu algo?"
  },
  AvgDialog_18893_Content_25 = {
    Text = "Jenkins tirou um maço de jornais amassados da bolsa e os entregou a você e Ramona"
  },
  AvgDialog_18893_Content_26 = {
    Text = "Tivemos um acordo: você prometeu me ajudar a encontrar minha irmã. Agora, é hora de você cumprir sua promessa."
  },
  AvgDialog_18893_Content_27 = {
    Text = "Ela abriu o jornal e apontou para uma curiosidade local intitulada \"Pintura Tridimensional\""
  },
  AvgDialog_18893_Content_28 = {
    Text = "O autor escreveu em estilo de narrativa documental que ele viu uma exibição surpreendente no museu de cera localizado na 44ª rua de Nanhua: a nova obra \"Primavera\" do artista de cera Rogers"
  },
  AvgDialog_18893_Content_29 = {
    Text = "Para aumentar a credibilidade, uma foto foi cuidadosamente anexada ao lado"
  },
  AvgDialog_18893_Content_3 = {
    Text = "Você e Ramona tinham acabado de voltar ao portão da escola quando viram Jenkin e um estudante de uniforme lutando no chão."
  },
  AvgDialog_18893_Content_30 = {
    Text = "É um grupo de estátuas de cera inspirado na famosa pintura \"Primavera\" de Botticelli, com uma figura feminina no centro, pintada de forma cômica e com expressão dolorosa"
  },
  AvgDialog_18893_Content_31 = {
    Text = "Esta pessoa... Não sei por quê, mas ela me lembra minha irmã mais velha."
  },
  AvgDialog_18893_Content_32 = {
    Text = "Rogers... Foi o Dr. Miller quem o apresentou a Sarah. Depois do incidente na casa de pobres, ele desapareceu misteriosamente."
  },
  AvgDialog_18893_Content_33 = {
    Text = "Então, esse cara é quem matou minha irmã... e... Aigis..."
  },
  AvgDialog_18893_Content_34 = {
    Text = "Não posso esperar mais. Quando vamos partir?"
  },
  AvgDialog_18893_Content_35 = {
    Text = "Considerando que o outro lado pode ser perigoso, prefiro que você espere aqui por notícias. Mas — você deve ter outra ideia, certo?"
  },
  AvgDialog_18893_Content_36 = {
    Text = "Ela é minha irmã, eu não posso deixar de ir!\nAlém disso, vocês podem precisar de mim para passar pelos dutos de ventilação!"
  },
  AvgDialog_18893_Content_37 = {
    Text = "Esta habilidade única é realmente bastante útil."
  },
  AvgDialog_18893_Content_38 = {
    Text = "Parece que preciso submeter uma solicitação urgente de trabalho de campo."
  },
  AvgDialog_18893_Content_39 = {
    Text = "Estou prestes a encontrar o Professor Alistair, esperando que ele esteja disposto a nos dar uma porta dos fundos."
  },
  AvgDialog_18893_Content_4 = {Text = "..."},
  AvgDialog_18893_Content_40 = {
    Text = "Enquanto você se manifestar, deve estar tudo bem. Mais importante — precisamos de William para adiar o prazo de submissão do nosso relatório."
  },
  AvgDialog_18893_Content_41 = {
    Text = "Sobre isso, não precisam se preocupar"
  },
  AvgDialog_18893_Content_42 = {Text = "?"},
  AvgDialog_18893_Content_43 = {
    Text = "Há uma hora, William saiu com a permissão de campo"
  },
  AvgDialog_18893_Content_44 = {
    Text = "Eu ia segui-lo para ver se conseguia alguma notícia, mas o perdi no caminho e voltei. Parecia que ele estava indo para o distrito oeste de Lentinion"
  },
  AvgDialog_18893_Content_45 = {
    Text = "Southwark Street fica na Zona Oeste. Parece que, desta vez, teremos a oportunidade de testemunhar o renomado Investigador William, o companheiro mais velho, em ação."
  },
  AvgDialog_18893_Content_46 = {
    Text = "Até o <Italic:William, o companheiro mais velho> tem de ir, hein..."
  },
  AvgDialog_18893_Content_47 = {
    Text = [[
18:24, Distrito Oeste de Lentini
Rua Southwark]]
  },
  AvgDialog_18893_Content_48 = {
    Text = "Obrigado pela cooperação, eu cuido do resto sozinho"
  },
  AvgDialog_18893_Content_49 = {
    Text = "Isso não vai funcionar, senhor, as ordens são claras, devemos acompanhá-lo na investigação.\nAlém disso, Rogers também é nosso suspeito, não podemos deixá-lo trabalhar sozinho"
  },
  AvgDialog_18893_Content_5 = {Text = "..."},
  AvgDialog_18893_Content_50 = {
    Text = "E conosco, sua identidade pode ser melhor escondida, certo?"
  },
  AvgDialog_18893_Content_51 = {Text = "..."},
  AvgDialog_18893_Content_52 = {
    Text = "Relaxe, senhor. Temos armas e somos rápidos, não seremos um fardo"
  },
  AvgDialog_18893_Content_53 = {
    Text = "Certo, aumente a vigilância. Se necessário, priorize sua vida"
  },
  AvgDialog_18893_Content_54 = {
    Text = "Relatório. Chegamos ao local da missão, 44 South Harker St., Museu de Cera do Rogers. Alvo confirmado: Verifique a possível ligação entre o proprietário do museu de cera, Rogers, e os escultores"
  },
  AvgDialog_18893_Content_55 = {
    Text = "Chegada ao local da missão confirmada, objetivo de investigação confirmado.\nQue a Chave de Prata guie o caminho"
  },
  AvgDialog_18893_Content_56 = {
    Text = "Que a Chave de Prata nos guie"
  },
  AvgDialog_18893_Content_6 = {
    Text = "Rato morde doninha"
  },
  AvgDialog_18893_Content_7 = {
    Text = "Eu acho que acabei de ver uma maravilha do mundo."
  },
  AvgDialog_18893_Content_8 = {Text = "Ha?"},
  AvgDialog_18893_Content_9 = {
    Text = "Que maravilha?"
  },
  AvgDialog_18894_Content_1 = {
    Text = "Noite sem Pássaros"
  },
  AvgDialog_18894_Content_10 = {
    Text = "Não posso ficar estagnado por mais tempo."
  },
  AvgDialog_18894_Content_11 = {
    Text = "Eu não quero ver a Senhorita Sarah, o Pequeno Mike, Jenkins, ou qualquer um de vocês...\nTodos que conheço estão se tornando pedras imóveis, assim como Tiyug."
  },
  AvgDialog_18894_Content_12 = {
    Text = "Contendo as lágrimas, Aigis virou-se e correu em direção à saída do porão."
  },
  AvgDialog_18894_Content_13 = {Text = "Pare ela!"},
  AvgDialog_18894_Content_2 = {
    Text = "Este é meu... pecado."
  },
  AvgDialog_18894_Content_3 = {
    Text = "Aigis parou por um momento e fechou os olhos."
  },
  AvgDialog_18894_Content_4 = {
    Text = "Eu sou aquele que matou Tiyoug, transformou o Pequeno Willy em um homem de doces, e eu sou o verdadeiro fantasma da casa de caridade."
  },
  AvgDialog_18894_Content_5 = {
    Text = "Desde então, algo tem tentado controlar meu corpo. No início, felizmente, havia <Yellow:Sr. Anderson> me ajudando. Ele estava sempre à vista, me ensinando como resistir à escuridão."
  },
  AvgDialog_18894_Content_6 = {
    Text = "Mas sua voz ficou cada vez mais fraca. No final, toda vez que era <Yellow:uma noite nebulosa>, eu perdia o controle... É tudo minha culpa, toda minha culpa."
  },
  AvgDialog_18894_Content_7 = {
    Text = "Eu tentei usar uma máscara nos olhos, tentei me amarrar à cama, mas nada funcionou. As tiras que não se moviam não importa o quanto eu tentasse durante o dia, eram facilmente rompidas por aquela força à noite."
  },
  AvgDialog_18894_Content_8 = {
    Text = "Aigis acariciou suavemente seu pulso, que estava ruborizado."
  },
  AvgDialog_18894_Content_9 = {
    Text = "A Senhorita Sarah deve ter notado algo, certo?\nÉ por isso que ela está tão desesperada, tão ansiosa para que o médico me cure."
  },
  AvgDialog_18895_Content_1 = {
    Text = "Quem Matou o Tordo"
  },
  AvgDialog_18895_Content_10 = {
    Text = "Você ouviu esta canção em um sonho."
  },
  AvgDialog_18895_Content_11 = {
    Text = "O corpo gradualmente se torna rígido, e os ossos estalam a cada tentativa de movimento. Cada movimento parece forçar engrenagens enferrujadas de uma marionete mecânica. Você pode sentir uma fina poeira caindo dentro de suas articulações."
  },
  AvgDialog_18895_Content_12 = {
    Text = "<Italic:Um dia, ela desapareceu, e ele a procurou em todos os lugares.>"
  },
  AvgDialog_18895_Content_13 = {
    Text = "Minhas pálpebras sentem-se tão pesadas quanto chumbo, forçando-se a fechar.\nNo mundo das trevas, apenas uma névoa densa gira ao redor."
  },
  AvgDialog_18895_Content_14 = {
    Text = "<Italic: O velho Charlie não conseguiu encontrar seu gato tigrado em lugar nenhum.>"
  },
  AvgDialog_18895_Content_15 = {
    Text = "No vazio escuro, você está sozinho.\nAcima dos céus infinitos, olhos da cor do mel derramam lágrimas densas, olhando para baixo em você."
  },
  AvgDialog_18895_Content_16 = {
    Text = "<Italic:Então ele chorou e chorou—>"
  },
  AvgDialog_18895_Content_17 = {
    Text = "Por algum motivo, você lembra da luta do velho moribundo e da grossa lágrima preta no canto de seu olho."
  },
  AvgDialog_18895_Content_18 = {
    Text = "<Italic:—até que ele também desapareça.>"
  },
  AvgDialog_18895_Content_19 = {
    Text = "Seguindo um instinto inexplicável, você olha para cima e pergunta suavemente aos olhos no céu, que parecem estar falando com você."
  },
  AvgDialog_18895_Content_2 = {
    Text = "De acordo com Jenkin, o <Yellow:Fantasma do Asilo> perambula pelo pátio em noites nebulosas, sequestrando vítimas. O Investigador Anderson pode ser uma delas."
  },
  AvgDialog_18895_Content_20 = {
    Text = "Isto não é o resultado que você esperava, é?"
  },
  AvgDialog_18895_Content_21 = {
    Text = "Olhos da cor do mel tremem e piscam.\nLágrimas caem, pousando na sua bochecha e emitindo um forte aroma doce."
  },
  AvgDialog_18895_Content_22 = {
    Text = "O canto chega a um abrupto término, a escuridão rapidamente se desvanece, e a sensação retorna a seus nervos.\nDurante o tempo em que você esteve perdido, a névoa densa parece ter diminuído um pouco."
  },
  AvgDialog_18895_Content_23 = {Text = "Uau!"},
  AvgDialog_18895_Content_24 = {
    Text = "A garota correu até você, reconheceu você de uma distância muito próxima e agarrou-se nervosamente ao seu ursinho de pelúcia."
  },
  AvgDialog_18895_Content_25 = {
    Text = "Sponsor, por que você está aqui?"
  },
  AvgDialog_18895_Content_26 = {
    Text = "Obrigado pela sua hospitalidade esta noite. Estamos apenas dando uma caminhada para digerir nossa comida. Algum problema?"
  },
  AvgDialog_18895_Content_27 = {
    Text = "Dias nublados são perigosos. Absolutamente não deve vagar do lado de fora, ou então..."
  },
  AvgDialog_18895_Content_28 = {
    Text = "Caso contrário... o que acontecerá?"
  },
  AvgDialog_18895_Content_29 = {
    Text = "Deixe-me adivinhar... eles desapareceram, certo?\nVocê sabe quem são as vítimas e para onde foram, não sabe?"
  },
  AvgDialog_18895_Content_3 = {
    Text = "Vamos não perder tempo; vamos para a câmara subterrânea que o Jenkin mencionou agora mesmo."
  },
  AvgDialog_18895_Content_30 = {
    Text = "Aigis ficou abalada, tremendo e balançando a cabeça, incapaz de falar."
  },
  AvgDialog_18895_Content_31 = {
    Text = "Aigis, você é uma boa criança. Boas crianças não devem contar mentiras."
  },
  AvgDialog_18895_Content_32 = {Text = "Eu..."},
  AvgDialog_18895_Content_33 = {
    Text = "Responda-me, Aigis! Você disse que não deveríamos vagar na névoa, então por que você está aqui?"
  },
  AvgDialog_18895_Content_34 = {
    Text = "As mãos da garota estavam firmemente entrelaçadas."
  },
  AvgDialog_18895_Content_35 = {
    Text = "Por favor... pare de perguntar..."
  },
  AvgDialog_18895_Content_36 = {
    Text = "Ramona, a névoa engrossou novamente."
  },
  AvgDialog_18895_Content_37 = {
    Text = "Na névoa, pares de olhos escarlates se acendem, encarando você sem saída."
  },
  AvgDialog_18895_Content_4 = {
    Text = "Não se preocupe, a entrada está perto da sala do diretor."
  },
  AvgDialog_18895_Content_5 = {
    Text = "Espere até a noite se aprofundar e Sarah adormecer, então começaremos nossa busca.\nAté lá, vamos descansar e recuperar nossas forças."
  },
  AvgDialog_18895_Content_6 = {
    Text = "Huh? Está ficando nebuloso?"
  },
  AvgDialog_18895_Content_7 = {
    Text = "Enquanto você fala, uma névoa incomumente densa se espalha ao redor da área.\nA névoa, que deveria ser leve e flutuante, gruda em você como um peso pesado e pegajoso."
  },
  AvgDialog_18895_Content_8 = {
    Text = "Na espessa névoa, você ouve canções."
  },
  AvgDialog_18895_Content_9 = {
    Text = "<Italic:Velho Charlie tem um gato tigrado que ele adora muito...>"
  },
  AvgDialog_18896_Content_1 = {
    Text = "Em um estado de atordoamento, uma voz misteriosa sussurrou no ouvido da garota."
  },
  AvgDialog_18896_Content_2 = {
    Text = "Desista, feche seus olhos e deixe tudo para mim.\nSarah, pequeno Mike... todos no orfanato se tornarão belos e eternos."
  },
  AvgDialog_18896_Content_3 = {
    Text = "Não, não, desta vez, eu absolutamente, absolutamente... não serei controlado por você novamente..."
  },
  AvgDialog_18896_Content_4 = {
    Text = "Rebelde? Sem a ajuda daquele cara irritante, seu espírito não aguentaria muito tempo. Se não fosse por isso, eu não poderia influenciar você enquanto você está acordado."
  },
  AvgDialog_18896_Content_5 = {
    Text = "Que tal desistir? Então, você pode me ajudar a transformar todos aqui em materiais valiosos"
  },
  AvgDialog_18896_Content_6 = {
    Text = "Eu não vou desistir! O Sr. Anderson também não é irritante!"
  },
  AvgDialog_18896_Content_7 = {
    Text = "Ele me protegeu... Eu também quero proteger todos. Proteger a senhorita Sarah, proteger o pequeno Mike, proteger o Jenkin. E proteger os irmãos e irmãs mais velhos de fora."
  },
  AvgDialog_18896_Content_8 = {
    Text = "Vou protegê-los, mesmo que isso me custe tudo—"
  },
  AvgDialog_18897_Content_1 = {
    Text = "Então, você notou? Não importa o quanto você se esforce, não importa o que esteja disposto a sacrificar, as mudanças acontecendo com você não vão parar."
  },
  AvgDialog_18897_Content_10 = {
    Text = "Eu acredito neles; definitivamente eliminarão..."
  },
  AvgDialog_18897_Content_11 = {Text = "<Red: Eu.>"},
  AvgDialog_18897_Content_12 = {
    Text = "Eu ouvi tudo. Você está tendo um tempo realmente difícil para encontrar uma criança adequada para os experimentos."
  },
  AvgDialog_18897_Content_13 = {
    Text = "Seus delitos foram expostos. A próxima, enquanto eu estiver ausente, eles estarão todos a salvo, certo?"
  },
  AvgDialog_18897_Content_14 = {
    Text = "A misteriosa voz não respondeu."
  },
  AvgDialog_18897_Content_2 = {
    Text = "Na verdade, à medida que todos crescem, eles perceberão que o mundo é assim. Não importa quão duro você tente, lute ou resista, você não pode escapar do ambiente que o cerca."
  },
  AvgDialog_18897_Content_3 = {
    Text = "Você ainda é apenas uma criança, mas não me importo em te ensinar essa lição desde cedo."
  },
  AvgDialog_18897_Content_4 = {
    Text = "Não, não é assim..."
  },
  AvgDialog_18897_Content_5 = {
    Text = "Porque eu... não sou mais humano...\nEu vou... confiar neles!"
  },
  AvgDialog_18897_Content_6 = {
    Text = "%player%{Male=Sr. Guardião,Female=Srta. Guardiã}, irmã Ramona, Ogier...\nEles são diferentes das pessoas do orfanato, são fortes, vão derrotar"
  },
  AvgDialog_18897_Content_7 = {
    Text = "A voz a interrompeu impacientemente com um sorriso frio."
  },
  AvgDialog_18897_Content_8 = {
    Text = "Elimine-me...? Eles não conseguem nem encontrar onde estou, conseguem?\nAfinal, nem você sabe onde estou."
  },
  AvgDialog_18897_Content_9 = {
    Text = "Não, não é assim..."
  },
  AvgDialog_18898_Content_1 = {
    Text = "Tudo normal"
  },
  AvgDialog_18898_Content_10 = {
    Text = "O benfeitor Rogers desapareceu, deixando o futuro do orfanato incerto.\nEventualmente, o nobre Dexter generosamente forneceu financiamento e organizou a tomada das operações do orfanato."
  },
  AvgDialog_18898_Content_11 = {
    Text = "No dia em que o Nobre Dexter decidiu assumir a casa dos pobres de Lily, você e Ramona retornaram à casa dos pobres."
  },
  AvgDialog_18898_Content_12 = {
    Text = "Uma freira dirige vários trabalhadores a mover uma pequena cama para fora da área médica."
  },
  AvgDialog_18898_Content_13 = {
    Text = "Mas essa não é a Sarah com quem você está familiarizado."
  },
  AvgDialog_18898_Content_14 = {
    Text = "Isso é estranho. Nunca tivemos crianças doentes aqui, então por que essa cama está aqui...?"
  },
  AvgDialog_18898_Content_15 = {
    Text = "Na estrutura de ferro que está no canto da cama, alguns pedaços de pano rasgado estão amarrados."
  },
  AvgDialog_18898_Content_16 = {
    Text = "Sim, como se em resposta ao desejo de Aigis, a memória dela desapareceu da mente das pessoas no asilo em apenas duas semanas."
  },
  AvgDialog_18898_Content_17 = {
    Text = "A antiga ordem foi quebrada, e uma nova está sendo rapidamente estabelecida."
  },
  AvgDialog_18898_Content_18 = {
    Text = "Algumas pessoas vão embora, algumas desaparecem, os pesadelos de algumas pessoas acabam, as condições de algumas pessoas persistem. \nMas a vida continua, não deixando espaço para respirar."
  },
  AvgDialog_18898_Content_19 = {
    Text = "Sarah deitou-se quieta em uma pequena cama. Sua cabeça permanecia quebrada, e seus membros estavam acorrentados."
  },
  AvgDialog_18898_Content_2 = {
    Text = "Após isso—"
  },
  AvgDialog_18898_Content_20 = {
    Text = "Posso pegar a chave emprestada?"
  },
  AvgDialog_18898_Content_21 = {
    Text = "O Capitão do Comitê acompanhante franziu a testa e colocou a chave na mesa de cabeceira."
  },
  AvgDialog_18898_Content_22 = {
    Text = "Vou checar a situação. Vocês fiquem de olho nas coisas."
  },
  AvgDialog_18898_Content_23 = {
    Text = "Você e Ramona destrancaram as correntes silenciosamente."
  },
  AvgDialog_18898_Content_24 = {
    Text = "Senhorita Sarah, você... ainda se lembra de nós?"
  },
  AvgDialog_18898_Content_25 = {
    Text = "O monstro silencioso balançou a cabeça—se é que aquela parte pulsando com pus preto ainda poderia ser chamada de cabeça."
  },
  AvgDialog_18898_Content_26 = {
    Text = "Você se lembra... Aigis?"
  },
  AvgDialog_18898_Content_27 = {
    Text = "Como se estivesse aturdida, Sarah repetiu suas palavras."
  },
  AvgDialog_18898_Content_28 = {
    Text = "Ai... Ji... Si...?"
  },
  AvgDialog_18898_Content_29 = {
    Text = "Os órgãos vocais borbulhavam, tremendo com tons caóticos."
  },
  AvgDialog_18898_Content_3 = {
    Text = "O Comitê enviou uma unidade de designação para o Asilo de Lily e escoltou Sanga do porão."
  },
  AvgDialog_18898_Content_30 = {
    Text = "Após um longo silêncio, Sarah estendeu uma mão cerrada e parou na sua frente."
  },
  AvgDialog_18898_Content_31 = {
    Text = "Você está... me dando algo?"
  },
  AvgDialog_18898_Content_32 = {
    Text = "Você abre sua palma."
  },
  AvgDialog_18898_Content_33 = {
    Text = "Uma pequena Prata cai na sua palma."
  },
  AvgDialog_18898_Content_34 = {
    Text = "Ai... Ji... Si..."
  },
  AvgDialog_18898_Content_35 = {
    Text = "Isto é... daquela criança?"
  },
  AvgDialog_18898_Content_36 = {
    Text = "Memórias caóticas convergem."
  },
  AvgDialog_18898_Content_37 = {
    Text = "Enquanto Aigis caiu como um pássaro na noite, todos vocês correram em direção a ela."
  },
  AvgDialog_18898_Content_38 = {
    Text = "Jenkin pegou um pedaço de fita, você apanhou um embrulho de doce, e a já enlouquecida Sarah...\nSeguindo seus instintos, tocou na Alma da garota."
  },
  AvgDialog_18898_Content_39 = {
    Text = "Dê ao Laboratório de Prata. Talvez um dia possamos Despertar aquela garota e o poder dentro dela."
  },
  AvgDialog_18898_Content_4 = {
    Text = "Enquanto ela estava sentada na maca carregada pelo Comitê, ela olhou para você com uma expressão provocadora, os lábios ligeiramente entreabertos. Você leu suas palavras através do movimento dos lábios dela."
  },
  AvgDialog_18898_Content_40 = {
    Text = "Devemos contar a boa notícia ao Jenkin?"
  },
  AvgDialog_18898_Content_41 = {
    Text = "...Nos estágios iniciais do Despertar, Despertadores experienciam confusão de memória. \nAlguns perdem todas as memórias, enquanto outros apenas lembram momentos emocionalmente significativos e precisam de tempo para se recuperar."
  },
  AvgDialog_18898_Content_42 = {
    Text = "Aigis foi modificada, e sua estrutura de Prata está instável.\nMesmo que consigamos Despertá-la, ela pode não reconhecer Jenkin..."
  },
  AvgDialog_18898_Content_43 = {
    Text = "Eu acho que vou esperar até que tudo se estabilize antes de explicar isso claramente a ela."
  },
  AvgDialog_18898_Content_44 = {
    Text = "Você fechou a mão, sentindo o calor da Prata, relembrando a garota que sempre seguia os outros, quase invisível"
  },
  AvgDialog_18898_Content_45 = {
    Text = "Quando você a conheceu pela primeira vez, ela seguiu atrás de Sarah e timidamente lhe deu boas-vindas;"
  },
  AvgDialog_18898_Content_46 = {
    Text = "Quando Jenkin levou você à área médica, ela se escondeu atrás dele com medo."
  },
  AvgDialog_18898_Content_47 = {
    Text = "Apenas aquele momento final de bravura a transformou em um meteoro fugaz ao crepúsculo."
  },
  AvgDialog_18898_Content_48 = {
    Text = "Aigis... salvou todos que permaneceram com seu sacrifício."
  },
  AvgDialog_18898_Content_49 = {
    Text = "Ela é... uma verdadeira cavaleira."
  },
  AvgDialog_18898_Content_5 = {
    Text = "Você pode entender, certo?"
  },
  AvgDialog_18898_Content_50 = {
    Text = "<Blue: Investigador Sean Anderson>... Após seu assassinato, os Escultores extraíram à força sua Prata e usaram sua consciência restante para ajudar Aigis."
  },
  AvgDialog_18898_Content_51 = {
    Text = "Não conseguimos nem mesmo coletar seus restos."
  },
  AvgDialog_18898_Content_52 = {
    Text = "Ramona, podemos salvar algo? Podemos mudar algo?"
  },
  AvgDialog_18898_Content_53 = {
    Text = "É o que é preciso para enfrentar a Fusão."
  },
  AvgDialog_18898_Content_54 = {
    Text = "Guardião, você é especial. Por isso, não pode parar aqui."
  },
  AvgDialog_18898_Content_55 = {
    Text = "Temos de fazer algo. Salvar pessoas. Trazer mudança.\nMas, mesmo que nada seja alcançado no final..."
  },
  AvgDialog_18898_Content_56 = {
    Text = "Antes da chegada daquela noite escura em que tudo é esquecido, que a sua memória seja a testemunha final de tudo o que aconteceu."
  },
  AvgDialog_18898_Content_6 = {
    Text = "O sacerdote chefe da Catedral de Londinium apareceu na casa de pobres. Após chegar a um acordo com o Comitê, Sarah, que está passando por uma transformação irreversível, foi temporariamente alojada na igreja e está sendo vigiada pelos membros do Comitê."
  },
  AvgDialog_18898_Content_7 = {
    Text = "Com base nas vagas recordações das crianças sobre a rota, você localizou o laboratório do Dr. Miller."
  },
  AvgDialog_18898_Content_8 = {
    Text = "O lugar agora está deserto."
  },
  AvgDialog_18898_Content_9 = {
    Text = "William designou uma equipe de investigação para continuar rastreando seus paradeiros e coordenou com o Comitê para iniciar uma busca em grande escala nas bases dos Escultores."
  },
  AvgDialog_18899_Content_1 = {
    Text = "Sonho negro"
  },
  AvgDialog_18899_Content_10 = {
    Text = "<Italic:Ele revirou o guarda-roupa. Ele espiou debaixo da cama.>"
  },
  AvgDialog_18899_Content_11 = {
    Text = "O espaço parece cada vez mais apertado. Uma pressão sufocante desgasta sua respiração, e seu corpo gradualmente se torna rígido, indo em direção à imobilidade."
  },
  AvgDialog_18899_Content_12 = {
    Text = "<Italic:Ele vagou pelo porão onde a caldeira estava funcionando.>"
  },
  AvgDialog_18899_Content_13 = {
    Text = "Apenas os olhos e a garganta estão mal funcionando.\nO corpo inteiro se sente como se estivesse sendo roído por insetos, causando uma dor leve."
  },
  AvgDialog_18899_Content_14 = {
    Text = "<Italic: O velho Charlie não conseguiu encontrar seu gato tigrado em lugar nenhum.>"
  },
  AvgDialog_18899_Content_15 = {
    Text = "<Shake:Alguém... por favor... salve... me...>"
  },
  AvgDialog_18899_Content_16 = {
    Text = "<Italic:Então ele chorou e chorou—>"
  },
  AvgDialog_18899_Content_17 = {
    Text = "<Shake:...@1... Eu... puxo@1...>"
  },
  AvgDialog_18899_Content_18 = {
    Text = "<Italic:—até que ele também desapareça.>"
  },
  AvgDialog_18899_Content_19 = {
    Text = "Um sabor metálico doce inunda minha garganta, silenciando minhas cordas vocais e mergulhando o mundo em absolute quietude."
  },
  AvgDialog_18899_Content_2 = {
    Text = "Você acorda na escuridão total."
  },
  AvgDialog_18899_Content_20 = {Text = "..."},
  AvgDialog_18899_Content_21 = {
    Text = "Em algum momento, em algum lugar, você experienciou exatamente a mesma coisa."
  },
  AvgDialog_18899_Content_22 = {
    Text = "A única que te tirou da escuridão naquela época foi —"
  },
  AvgDialog_18899_Content_23 = {
    Text = "Acorde, acorde! %player%!"
  },
  AvgDialog_18899_Content_24 = {
    Text = "Uma explosão súbita de luz, alguém agarra sua mão, e você acorda ensopado em suor frio."
  },
  AvgDialog_18899_Content_25 = {
    Text = "Você teve outro sonho estranho?"
  },
  AvgDialog_18899_Content_26 = {
    Text = "...Eu não sei."
  },
  AvgDialog_18899_Content_27 = {
    Text = "Após voltar de <Yellow:Akut>, você começou a sonhar com frequência.\nSonhando seus próprios sonhos, os sonhos de outros, sonhos do passado e, às vezes... até mesmo sonhos do futuro."
  },
  AvgDialog_18899_Content_28 = {
    Text = "Ramona, você poderia me acompanhar ao Criptograma Chave?"
  },
  AvgDialog_18899_Content_29 = {
    Text = "Ramona e você caminham silenciosamente no Cemitério de Chaves até encontrarem aquela lápide comum, mas única, entre as muitas."
  },
  AvgDialog_18899_Content_3 = {
    Text = "Sente como se fosse um espaço confinado—pequeno, escuro, silencioso, frio, desprovido de luz, e com ar rarefeito, como o interior de um caixão."
  },
  AvgDialog_18899_Content_30 = {
    Text = "Esta é a sua lápide."
  },
  AvgDialog_18899_Content_31 = {Text = "Ramona..."},
  AvgDialog_18899_Content_32 = {
    Text = "Sonhei com a explosão do Akut... Sonhei em estar enterrado sob os escombros e você me desenterrando."
  },
  AvgDialog_18899_Content_33 = {
    Text = "Você e Mythag me deram uma segunda vida."
  },
  AvgDialog_18899_Content_34 = {
    Text = "Descobrir você foi uma bênção para mim e Mythag.\nSem você, todos aqui teriam sido engolidos pelos <Yellow:Dissolução Clades> de Akut."
  },
  AvgDialog_18899_Content_35 = {
    Text = "Ainda não consigo me lembrar do que aconteceu antes disso?"
  },
  AvgDialog_18899_Content_36 = {
    Text = "Você balança a cabeça."
  },
  AvgDialog_18899_Content_37 = {
    Text = "As nuvens de poeira giratórias de Akut e o rosto ansioso de Ramona marcam o ponto de partida de suas memórias. Sua vida anterior parece ter desaparecido junto com a explosão no deserto infinito."
  },
  AvgDialog_18899_Content_38 = {
    Text = "A enfermeira Sylvia disse que a recuperação da memória não é instantânea. Interagir com mais pessoas e coisas pode ajudar a lembrar de algo"
  },
  AvgDialog_18899_Content_39 = {
    Text = "Você já se compos? <Blue:William> ainda está esperando nosso relatório."
  },
  AvgDialog_18899_Content_4 = {
    Text = "O medo o sobrecarrega. Você luta, bate e grita, mas não consegue escapar da escuridão sem fim."
  },
  AvgDialog_18899_Content_40 = {
    Text = "Resumo rápido da missão: entrar secretamente no Orfanato Lilyan e encontrar o Investigador desaparecido <Blue:Shawn Anderson>."
  },
  AvgDialog_18899_Content_41 = {
    Text = "Os Investigadores da vanguarda não detectaram sinais de alto risco <Yellow:Clades> fora do hospício, mas você ainda precisa permanecer cauteloso. Além de Ramona, outros Despertadores o acompanharão."
  },
  AvgDialog_18899_Content_42 = {
    Text = "Embora você possua o Presente de conectar vários Despertadores, considerando o fardo físico que a conexão pode trazer, Ogier, que já completou a conexão, o acompanhará nesta missão."
  },
  AvgDialog_18899_Content_43 = {
    Text = "Sim! Ogier irá te ajudar completamente na investigação!"
  },
  AvgDialog_18899_Content_44 = {
    Text = "Há outras informações que precisamos saber sobre o desaparecimento do Investigador Anderson?"
  },
  AvgDialog_18899_Content_45 = {
    Text = "A área ao redor da casa de caridade é um ponto crítico para desaparecimentos no Distrito Leste, com o primeiro relatório datando de seis meses atrás. O Investigador Anderson, que nasceu no Distrito Leste, provavelmente está envolvido nos desaparecimentos em série."
  },
  AvgDialog_18899_Content_46 = {
    Text = "Seria ótimo se você pudesse resolver o caso de pessoas desaparecidas de uma só vez, mas não se esqueça, sua missão principal é encontrar o Investigador desaparecido."
  },
  AvgDialog_18899_Content_47 = {
    Text = "Sem mais delongas, Sean está esperando pelo seu resgate. Apresse-se e parta.\nQue a Chave de Prata guie seu caminho."
  },
  AvgDialog_18899_Content_5 = {
    Text = "Gradualmente, o canto começou a ressoar."
  },
  AvgDialog_18899_Content_6 = {
    Text = "<Italic:O velho Charlie tem um gato malhado que ele estima muito.>"
  },
  AvgDialog_18899_Content_7 = {
    Text = "Oi—tem alguém aí—alguém lá fora—"
  },
  AvgDialog_18899_Content_8 = {
    Text = "<Italic:Um dia, ela desapareceu, e ele a procurou em todos os lugares.>"
  },
  AvgDialog_18899_Content_9 = {
    Text = "Esta sensação parece familiar. Sim, em algum momento, você já foi envolto por uma escuridão tão profunda e sufocante."
  },
  AvgDialog_18900_Content_1 = {
    Text = "Pesadelo colorido"
  },
  AvgDialog_18900_Content_10 = {
    Text = "Fomos para a fila, esperando pela seleção do médico.\nSenti-me sem peso, como se não existisse neste mundo."
  },
  AvgDialog_18900_Content_11 = {
    Text = "Vamos escolher esta garota. Sua condição é bastante complexa, e não conseguimos curá-la da última vez."
  },
  AvgDialog_18900_Content_12 = {
    Text = "<Shake:Não... eu não quero ir... Já estive lá uma vez, e eu não quero...>"
  },
  AvgDialog_18900_Content_13 = {
    Text = "Vou, senhor."
  },
  AvgDialog_18900_Content_14 = {Text = "!"},
  AvgDialog_18900_Content_15 = {
    Text = "... Você está se sentindo mal?"
  },
  AvgDialog_18900_Content_16 = {
    Text = "Eu não me sinto mal; eu posso correr e pular, perfeitamente saudável!\nMas eu consigo ver coisas."
  },
  AvgDialog_18900_Content_17 = {
    Text = "Oh? O que você pode ver?"
  },
  AvgDialog_18900_Content_18 = {
    Text = "Eu e Aigis vemos as ilusões negras.\nVocê poderia me ajudar?"
  },
  AvgDialog_18900_Content_19 = {
    Text = "Interessante. Hoje é sua vez"
  },
  AvgDialog_18900_Content_2 = {
    Text = "A princípio, eles disseram que tinham vindo tratar a doença."
  },
  AvgDialog_18900_Content_20 = {Text = "Tiyog"},
  AvgDialog_18900_Content_21 = {
    Text = "Não tenha medo, Aigis."
  },
  AvgDialog_18900_Content_22 = {
    Text = "Voltarei em breve."
  },
  AvgDialog_18900_Content_23 = {
    Text = "Após isso, Tiyug nunca mais retornou ao orfanato."
  },
  AvgDialog_18900_Content_24 = {
    Text = "Eles disseram à Senhorita Sarah que sua condição era grave, mas um gentil cavalheiro estava disposto a adotá-lo e cobrir o custo total da cirurgia."
  },
  AvgDialog_18900_Content_25 = {
    Text = "Eu sei que são todas mentiras, mas a Srta. Sarah acreditou nelas com gratidão sincera."
  },
  AvgDialog_18900_Content_26 = {
    Text = "Por que, por que isso está acontecendo..."
  },
  AvgDialog_18900_Content_27 = {
    Text = "Eu vaguei pelo corredor atordoado e esbarrei em uma figura alta."
  },
  AvgDialog_18900_Content_28 = {
    Text = "Menina, você poderia me dizer como chegar à nova área médica?"
  },
  AvgDialog_18900_Content_29 = {
    Text = "À medida que o número de pacientes aumentava, a Srta. Sarah transferiu a área médica para o pequeno prédio no lado leste da casa de caridade.\nO lugar é mais espaçoso e pode acomodar mais camas temporárias."
  },
  AvgDialog_18900_Content_3 = {
    Text = "Não sei quando começou, mas uma estranha doença começou a se espalhar na casa de acolhimento. Aqueles infectados tornaram-se extremamente irritáveis, e marcas triangulares pretas apareceram em suas cabeças, mãos e pés."
  },
  AvgDialog_18900_Content_30 = {
    Text = "Irmã, você poderia, por favor, não ir para a zona médica?\nÉ... é realmente perigoso lá..."
  },
  AvgDialog_18900_Content_31 = {
    Text = "Bom garoto, por que você diz isso?"
  },
  AvgDialog_18900_Content_32 = {
    Text = "Não sei, não sei, desculpe...\nA área médica fica ao leste."
  },
  AvgDialog_18900_Content_33 = {
    Text = "Obrigado.\nVocê parece ter muito em mente. Se sentir vontade de conversar, não hesite em vir até mim."
  },
  AvgDialog_18900_Content_34 = {
    Text = "Eu tenho uma irmã que tem mais ou menos sua idade..."
  },
  AvgDialog_18900_Content_35 = {
    Text = "A mulher caminhou em direção ao leste, a fita vermelha chamativa balançando suavemente a cada passo."
  },
  AvgDialog_18900_Content_36 = {
    Text = "Aquilo foi a última vez que vi a irmã do Jenkin. Ela desapareceu após aquele dia."
  },
  AvgDialog_18900_Content_37 = {
    Text = "Eu sei, eles viram tudo através dos meus olhos."
  },
  AvgDialog_18900_Content_38 = {
    Text = "Cobri cuidadosamente meus olhos com um tapa-olho."
  },
  AvgDialog_18900_Content_39 = {
    Text = "Mas isso não pode impedir a chegada dos pesadelos."
  },
  AvgDialog_18900_Content_4 = {
    Text = "A Miss Sarah os mandou para a clínica do médico, mas as marcas em seus corpos não diminuíram; em vez disso, aumentaram..."
  },
  AvgDialog_18900_Content_40 = {
    Text = "Hmm... este lugar é..."
  },
  AvgDialog_18900_Content_41 = {
    Text = "A intensa luz me fez querer instintivamente fechar os olhos. Tentei piscar, mas percebi que não conseguia."
  },
  AvgDialog_18900_Content_42 = {
    Text = "Algo fixou meu olhar."
  },
  AvgDialog_18900_Content_43 = {
    Text = "Um homem vestido de branco, segurando uma faca delgada, aparece em meu campo de visão e se aproxima de mim lentamente."
  },
  AvgDialog_18900_Content_44 = {
    Text = "Não, não, Senhorita Sarah, Senhorita Sarah!"
  },
  AvgDialog_18900_Content_45 = {
    Text = "Senhorita Sarah! Tiyug! Ajude! Salve-me! <Big: Salve-me!>"
  },
  AvgDialog_18900_Content_46 = {
    Text = "A ponta da faca se aproxima, cada vez mais, até preencher toda a visão.\nEntão—"
  },
  AvgDialog_18900_Content_47 = {
    Text = "<Shake:Ah——!>"
  },
  AvgDialog_18900_Content_48 = {
    Text = "Então escuro, tão frio, como mergulhar no Rio Ísis em dezembro.\nEu quero me levantar, mas estou dormente e não consigo me mover."
  },
  AvgDialog_18900_Content_49 = {
    Text = "Dói... meus olhos estão desconfortáveis"
  },
  AvgDialog_18900_Content_5 = {
    Text = "Eu disse à Srta. Sarah sobre isso, mas ela disse..."
  },
  AvgDialog_18900_Content_50 = {
    Text = "O médico colocou algo em meu olho, e então, eu vi cores.\nCores se misturando, como uma paleta que o Pequeno Mike havia derramado."
  },
  AvgDialog_18900_Content_51 = {
    Text = "A Miss Sarah... Tiyog... Estou com tanta dor... É insuportável..."
  },
  AvgDialog_18900_Content_52 = {
    Text = "Eles estão se movendo... as cores estão mudando! Elas se arrastam para dentro dos meus olhos como insetos. Não consigo ver nada além dessas cores."
  },
  AvgDialog_18900_Content_53 = {
    Text = "Eu estava errado. Não deveria ter pedido ajuda..."
  },
  AvgDialog_18900_Content_54 = {
    Text = "As cores devem ter invadedo minha mente, e sinto que estou prestes a me perder..."
  },
  AvgDialog_18900_Content_55 = {
    Text = "Ajude... ajude-me..."
  },
  AvgDialog_18900_Content_56 = {
    Text = "Quando estava prestes a desmaiar, colocaram algo mais em meus olhos, e uma luz prateada ofuscou todas as cores."
  },
  AvgDialog_18900_Content_57 = {
    Text = "Frio e gelado. Ainda dói, mas de repente, sinto que sou eu mesmo novamente."
  },
  AvgDialog_18900_Content_58 = {
    Text = "Não tenha medo, eu vou te ajudar."
  },
  AvgDialog_18900_Content_59 = {
    Text = "Quem... é você...?"
  },
  AvgDialog_18900_Content_6 = {
    Text = "Aigis, seu fantasma está piorando.\nNão há nenhuma marca preta aqui."
  },
  AvgDialog_18900_Content_60 = {Text = "..."},
  AvgDialog_18900_Content_61 = {
    Text = "Não importa, criança.\nVenha, siga meu ritmo, e juntos resistiremos ao controle da <Yellow:substância estrangeira>."
  },
  AvgDialog_18900_Content_62 = {
    Text = "Com a ajuda do som, além da dor, me senti menos desconfortável e comecei a pensar."
  },
  AvgDialog_18900_Content_63 = {
    Text = "Perdi a conta de quanto tempo se passou. Pareceu tão longo que minha pele começou a ficar dormente antes de finalmente ouvir a voz do médico novamente."
  },
  AvgDialog_18900_Content_64 = {
    Text = "Vendo os olhos de @2, é simplesmente o melhor material.\nSe não fosse por este garoto sempre atrapalhando, eu já teria usado eles para experimentos há muito tempo."
  },
  AvgDialog_18900_Content_65 = {
    Text = "Não é tarde demais, Doutor. Finalmente conseguimos implantar a Prata Alienígena, o que pede uma celebração!"
  },
  AvgDialog_18900_Content_66 = {
    Text = "A fusão da consciência de @4 e do receptor foi bem-sucedida. O efeito de petrificação desvia ligeiramente, mas enquanto a consciência do receptor continuar a enfraquecer..."
  },
  AvgDialog_18900_Content_67 = {
    Text = "Graças àquele tolo <Yellow:Investigator> por entregar Prata de tão alta qualidade, o que reduziu a rejeição."
  },
  AvgDialog_18900_Content_68 = {
    Text = "Aqueles pesquisadores me cercaram, falando animadamente sobre algo. Receptores? Rejeição? Investigadores? O que são esses?"
  },
  AvgDialog_18900_Content_69 = {
    Text = "Que tal, garoto? Experimente. Com apenas um olhar, seu melhor amigo estará com você em sua forma favorita."
  },
  AvgDialog_18900_Content_7 = {
    Text = "Não, Senhora Sarah, eu realmente, realmente posso ver!"
  },
  AvgDialog_18900_Content_70 = {
    Text = "Eles apertaram o dispositivo que segurava meus olhos; até tentar piscar faria os ganchos perfurarem minhas pálpebras."
  },
  AvgDialog_18900_Content_71 = {
    Text = "Eles empurraram uma cadeira na minha frente.\nAmarrado à cadeira estava meu melhor amigo—"
  },
  AvgDialog_18900_Content_72 = {
    Text = "Ti... Tiyog...?"
  },
  AvgDialog_18900_Content_73 = {
    Text = "Tiyug foi despertado por mim, olhou para cima surpreso e então olhou ao redor."
  },
  AvgDialog_18900_Content_74 = {
    Text = "Aigis! Me deixe ir, e a deixe ir!"
  },
  AvgDialog_18900_Content_75 = {
    Text = "Não se mova, não olhe para mim, Tiyug!"
  },
  AvgDialog_18900_Content_76 = {
    Text = "Tiyug chorou e se debateu, mas sem sucesso.\nSeus movimentos gradualmente se tornaram rígidos, diminuindo até parar como a mão de um relógio que havia parado de funcionar."
  },
  AvgDialog_18900_Content_77 = {
    Text = "Como se aceitasse seu destino, ele olhou silenciosamente para mim, nossos olhos se encontraram, e então—"
  },
  AvgDialog_18900_Content_78 = {
    Text = "Ele começou a desaparecer, tornando-se tão sem vida quanto o vestido surrado da Srta. Sarah. Xarope seepou de sua pele, cobrindo seu corpo que se tornara duro como pedra."
  },
  AvgDialog_18900_Content_79 = {
    Text = "Sob o olhar da minha <Yellow:pupil>, ela, ou ele, exalou seu último suspiro."
  },
  AvgDialog_18900_Content_8 = {
    Text = "É realmente apenas um fantasma. Não acredita em mim? Pergunte ao Pequeno Mike.\nEle tem apenas cinco anos. Uma criança tão jovem certamente não mentiria."
  },
  AvgDialog_18900_Content_80 = {
    Text = "Ai... Ji Si"
  },
  AvgDialog_18900_Content_81 = {
    Text = "<Big:Tiyoug—!!>"
  },
  AvgDialog_18900_Content_9 = {
    Text = "Irmã Aigis, certifique-se de ouvir o doutor quando estiver doente.\nVocê não me disse a mesma coisa da última vez que tive febre?"
  },
  AvgDialog_18901_Content_1 = {
    Text = "Nosso Segredo"
  },
  AvgDialog_18901_Content_10 = {
    Text = "A ordem da equipe é: Jenkin, Ramona, você."
  },
  AvgDialog_18901_Content_11 = {
    Text = "Atrás de você, Brown chiou e empurrou a porta de madeira."
  },
  AvgDialog_18901_Content_12 = {Text = "..."},
  AvgDialog_18901_Content_13 = {
    Text = "Minha irmã, e o estudante que você está procurando, definitivamente estão lá embaixo com aquele chamado fantasma do orfanato."
  },
  AvgDialog_18901_Content_14 = {
    Text = "Partidas, partidas..."
  },
  AvgDialog_18901_Content_15 = {
    Text = "A propósito, você está se sentindo coceira?"
  },
  AvgDialog_18901_Content_16 = {
    Text = "Graças ao seu lembrete, você percebe que, de fato, há uma inexplicável sensação de formigamento e coceira se espalhando dos seus dedos dos pés até os tornozelos, e indo até suas costas..."
  },
  AvgDialog_18901_Content_17 = {
    Text = "Jenkin finalmente poliu a lanterna. Ela a abaixou habilidosamente, iluminando uma pequena área do chão."
  },
  AvgDialog_18901_Content_18 = {
    Text = "Foi naquele exato momento—"
  },
  AvgDialog_18901_Content_19 = {
    Text = "A retina foi impactada."
  },
  AvgDialog_18901_Content_2 = {
    Text = "Após uma noite de turbulência, o céu se aproximava do amanhecer."
  },
  AvgDialog_18901_Content_20 = {
    Text = "Incontáveis formigas convergem em um denso enxame, rastejando continuamente e inquietamente."
  },
  AvgDialog_18901_Content_21 = {
    Text = "Eles se avolumam, se reúnem, giram e então se fundem no abismo negro."
  },
  AvgDialog_18901_Content_3 = {
    Text = "Ogier ficou na sala apenas por precaução, para segurar Sarah.\nVocê e Ramona seguiram Jenkins até o porão onde estava o \"Fantasma do Asilo\"."
  },
  AvgDialog_18901_Content_4 = {
    Text = "Mantenha sua voz baixa, não deixe Sarah nos encontrar.\nEla vai fazer uma equipe de trabalhadores nos expulsar."
  },
  AvgDialog_18901_Content_5 = {
    Text = "Ogier está de olho nos movimentos de Sarah. Com ele aqui, não seremos descobertos.\nDiga-me novamente o que você descobriu no escritório de Sarah da última vez."
  },
  AvgDialog_18901_Content_6 = {
    Text = "Oh querido, quantas vezes eu devo repetir?"
  },
  AvgDialog_18901_Content_7 = {
    Text = "Aquela mulher vil vendeu as pessoas do asilo para um médico maligno para experimentos e fez uma fortuna! Ela comprou muitas joias de ouro e prata e as escondeu na gaveta de seu quarto."
  },
  AvgDialog_18901_Content_8 = {
    Text = "Você já viu o crachá do seu companheiro. O que mais há para perguntar?"
  },
  AvgDialog_18901_Content_9 = {
    Text = "Certo, nesta sala.\nSe você for o último a sair, feche a porta."
  },
  AvgDialog_18902_Content_1 = {
    Text = "Arte sacarina"
  },
  AvgDialog_18902_Content_10 = {
    Text = "Sua chegada parece não ter impacto no trabalho dela. Ela abaixa a cabeça para examinar a estátua, ajusta a posição do cinzel e continua esculpindo."
  },
  AvgDialog_18902_Content_11 = {
    Text = "Isso deve ser o fantasma da casa de pobres...\nOnde está minha irmã? Você não a escondeu!"
  },
  AvgDialog_18902_Content_12 = {
    Text = "O fantasma olhou para você, mas não respondeu."
  },
  AvgDialog_18902_Content_13 = {
    Text = "Ramona desembainha sua arma, fixa os olhos em você e avança."
  },
  AvgDialog_18902_Content_14 = {
    Text = "Por favor, seja paciente e não perturbe a contemplação da arte..."
  },
  AvgDialog_18902_Content_15 = {
    Text = "Quando suas palavras caíram, incontáveis monstros gritaram e surgiram das sombras do porão, atropelando corpos contorcidos e atacando você."
  },
  AvgDialog_18902_Content_2 = {
    Text = "Você finalmente forçou a abrir a porta de ferro do porão, e um forte e doce aroma agridoce atacou seu nariz."
  },
  AvgDialog_18902_Content_3 = {
    Text = "A cena no porão era ainda mais chocante: vários corpos, suas superfícies revestidas com xarope, estavam espalhados pelo chão."
  },
  AvgDialog_18902_Content_4 = {
    Text = "O corpo, tendo perdido sua forma humana, se retorce e se contorce, deixando para trás um rastro de manchas de xarope bagunçadas."
  },
  AvgDialog_18902_Content_5 = {
    Text = "Fulos densos de formigas rastejam ao redor da calda, sugando-a avidamente e transportando-a com suas antenas, como se tivessem descoberto o tesouro mais precioso do mundo."
  },
  AvgDialog_18902_Content_6 = {
    Text = "No entanto, a coisa mais chamativa não são essas."
  },
  AvgDialog_18902_Content_7 = {
    Text = "No porão, várias estátuas de cor marrom-avermelhada estão expostas. Cada uma delas se ergue graciosamente, com uma expressão fatigada. Apenas um olhar para elas evoca uma sensação de admiração e santidade."
  },
  AvgDialog_18902_Content_8 = {
    Text = "Entre essas estátuas está o fantasma da casa de caridade."
  },
  AvgDialog_18902_Content_9 = {
    Text = "Era claramente o fantasma da casa de pobres—todo o seu corpo de cor pedra, segurando levemente um cinzel, esculpindo expressões aterrorizadas nos rostos das estátuas com um arranhado de arrepiar."
  },
  AvgDialog_18903_Content_1 = {
    Text = "Perigo Interno"
  },
  AvgDialog_18903_Content_2 = {
    Text = "Clang, clang"
  },
  AvgDialog_18903_Content_3 = {
    Text = "Você está totalmente ciente de que está sonhando."
  },
  AvgDialog_18903_Content_4 = {
    Text = "Alguém está se aproximando gradualmente, pisando nos canos de ferro no esgoto."
  },
  AvgDialog_18903_Content_5 = {
    Text = "No borrão, uma figura familiar corre em sua direção.\nEla agarra sua mão e puxa você rapidamente, chamando urgentemente."
  },
  AvgDialog_18903_Content_6 = {
    Text = "Corra, Jenkin, corra!"
  },
  AvgDialog_18903_Content_7 = {
    Text = "Atrás de você, inúmeros monstros pretos pegajosos estão perseguindo você e sua irmã."
  },
  AvgDialog_18904_Content_1 = {Text = "%player%!"},
  AvgDialog_18904_Content_10 = {
    Text = "Srta. Sarah, estou com medo, por favor"
  },
  AvgDialog_18904_Content_11 = {
    Text = "Senhorita Sarah..."
  },
  AvgDialog_18904_Content_12 = {
    Text = "Qual é o problema, Aigis?"
  },
  AvgDialog_18904_Content_13 = {
    Text = "A Miss Sarah, você poderia cantar aquela canção de novo, apenas mais uma vez?\nQuero dizer, se não for muito incômodo..."
  },
  AvgDialog_18904_Content_14 = {
    Text = "Querida Aigis Pequena, ouça com atenção: Você é a criança mais bem-comportada, obediente e sensata de todo o orfanato. Todos gostam mais de você."
  },
  AvgDialog_18904_Content_15 = {
    Text = "Então não seja tão reservado. Está tudo bem ser um pouco teimoso às vezes, entendeu?"
  },
  AvgDialog_18904_Content_16 = {
    Text = "E... eu, eu quero ouvir a Srta. Sarah cantar a canção de ninar novamente"
  },
  AvgDialog_18904_Content_17 = {
    Text = [[
Sem problemas.
<Italic: O velho Charlie tinha um gato malhado que amava muito...>]]
  },
  AvgDialog_18904_Content_18 = {
    Text = "Você abre os olhos abruptamente, caindo no mundo real cheio de cores"
  },
  AvgDialog_18904_Content_19 = {
    Text = "%player%, você está bem?"
  },
  AvgDialog_18904_Content_2 = {
    Text = "Enquanto Ramona mantém Sarah à distância, você se concentra e se afunda naquele espaço negro familiar"
  },
  AvgDialog_18904_Content_20 = {
    Text = "Você acena apesar da tontura. Pelo canto do olho, você vislumbra uma figura branca.\nA garota de alguma forma passou por você e entrou no campo de batalha caótico."
  },
  AvgDialog_18904_Content_21 = {
    Text = "Aigis, volte! É perigoso lá!"
  },
  AvgDialog_18904_Content_22 = {
    Text = "Aigis olhou fixamente para a caída Sarah.\nPerto da ferida aberta, o limo continuava a jorrar, formando um fluxo negro."
  },
  AvgDialog_18904_Content_23 = {
    Text = "Então, ela entrou na piscina escura como breu e sentou-se no meio da gosma.\nA garota deixou Sarah descansar em seu colo e habilidosamente acariciou suas costas."
  },
  AvgDialog_18904_Content_24 = {
    Text = "Apenas como o reitor costumava fazer ao me colocar para dormir."
  },
  AvgDialog_18904_Content_25 = {
    Text = "Senhorita Sarah... Está tudo bem, está tudo bem... Apenas um pesadelo..."
  },
  AvgDialog_18904_Content_26 = {
    Text = "O frágil brilho em seus olhos perfurou a venda, fugaz. Se não fosse pelo intenso choque da Gnose, você poderia ter pensado que era apenas a tristeza não derramada da garota."
  },
  AvgDialog_18904_Content_27 = {
    Text = "Os fragmentos no rosto de Sarah tremiam inquietos, mas depois que a luz suave passou por ela, ela ficou imóvel, como se realmente estivesse caindo em um sono profundo."
  },
  AvgDialog_18904_Content_28 = {
    Text = "A Senhorita Sarah não teve uma boa noite de sono há muito tempo."
  },
  AvgDialog_18904_Content_29 = {
    Text = "Para evitar que o asilo fechasse, ela está sempre em movimento, encontrando ricos lordes e damas no castelo, sem tempo para comer ou descansar."
  },
  AvgDialog_18904_Content_3 = {
    Text = "A Chave de Prata zumbiu intensamente, e a escuridão à sua frente mudou várias vezes, até que a luz começou a brilhar nas bordas da sua visão"
  },
  AvgDialog_18904_Content_30 = {
    Text = "Quando ela voltasse à noite, acenderia uma vela no escritório e continuaria calculando, verificando se o dinheiro que recebeu do mestre era suficiente."
  },
  AvgDialog_18904_Content_31 = {
    Text = "Vamos ver quanto podemos conseguir com as joias que pegamos das damas"
  },
  AvgDialog_18904_Content_32 = {
    Text = "Todos riram dela e disseram coisas dolorosas, mas a Senhorita Sarah nunca ficou brava.\nEla até me consolou e cantou para nós."
  },
  AvgDialog_18904_Content_33 = {
    Text = "Ela nos trata bem, realmente. Ela também me trata muito bem."
  },
  AvgDialog_18904_Content_34 = {
    Text = "Eu era um fardo para minha mãe, e ela me abandonou. O diretor anterior se recusou a me acolher, mas a Srta. Sarah disse que trabalharia em dois empregos para me trazer aqui."
  },
  AvgDialog_18904_Content_35 = {
    Text = "Desde então, jurei que nunca seria um fardo para a Srta. Sarah, que seria uma criança útil"
  },
  AvgDialog_18904_Content_36 = {
    Text = "Sinto muito, Senhorita Sarah. Fiz o meu melhor, mas as coisas continuam saindo do controle... Não consegui proteger a todos, e não consegui protegê-la. Sinto muito."
  },
  AvgDialog_18904_Content_37 = {
    Text = "Aigis tocou gentilmente a bochecha de Sarah, que não era mais humana, e então se virou para você."
  },
  AvgDialog_18904_Content_38 = {
    Text = "Você não está procurando o Investigador <Blue:Sean Anderson>?"
  },
  AvgDialog_18904_Content_39 = {
    Text = "Aigis, você..."
  },
  AvgDialog_18904_Content_4 = {
    Text = "Irmã Sasa, estou com muita fome"
  },
  AvgDialog_18904_Content_40 = {
    Text = "A garota abriu a boca, revelando uma expressão que mal podia ser chamada de sorriso"
  },
  AvgDialog_18904_Content_41 = {
    Text = "Deixe a senhorita Sarah ir.\nEu vou te contar onde ela está."
  },
  AvgDialog_18904_Content_42 = {
    Text = "Ele está bem aqui."
  },
  AvgDialog_18904_Content_43 = {
    Text = "Aigis lentamente removeu seu tapa-olho, revelando pupilas pálidas de cor pedra."
  },
  AvgDialog_18904_Content_44 = {
    Text = "<Red: Em meus olhos.>"
  },
  AvgDialog_18904_Content_5 = {
    Text = "Lamento, Srta. Sarah, não podemos mais financiar vocês"
  },
  AvgDialog_18904_Content_6 = {
    Text = "Srta. Sarah, por que minha mãe me abandonou?"
  },
  AvgDialog_18904_Content_7 = {
    Text = "Luzes preto e branco piscam, como vários filmes sendo projetados ao mesmo tempo, mas você não consegue ver claramente"
  },
  AvgDialog_18904_Content_8 = {
    Text = "Srta. Sarah, minha mãe disse que sou inútil... Posso realmente fazer essas coisas?"
  },
  AvgDialog_18904_Content_9 = {
    Text = "Srta. Sarah, minha mãe me abandonou, você... você também vai me abandonar?"
  },
  AvgDialog_18905_Content_1 = {
    Text = "Peso da consciência"
  },
  AvgDialog_18905_Content_10 = {
    Text = "Não finja ser desinformado! Sabemos tudo sobre seus planos malignos com aquele doutor desprezível! Entregue minha irmã!"
  },
  AvgDialog_18905_Content_11 = {
    Text = "Eu realmente não tenho nenhum desses..."
  },
  AvgDialog_18905_Content_12 = {
    Text = "Sarah olhou ao redor daquelas criaturas, incerta se poderiam ser chamadas de humanas, e continuou falando hesitante."
  },
  AvgDialog_18905_Content_13 = {
    Text = "Eu realmente não sei!"
  },
  AvgDialog_18905_Content_14 = {
    Text = "Vimos seu caderno!"
  },
  AvgDialog_18905_Content_15 = {Text = "...?"},
  AvgDialog_18905_Content_16 = {
    Text = "Você pega o livro de contas ao lado e o abre, sinalizando para Sarah"
  },
  AvgDialog_18905_Content_17 = {
    Text = "Mike, masculino, 5 anos, 10 Presas de Leão; Diana, feminina, 23 anos, 5 Presas de Leão; Aigis... feminina, 8 anos, 40 Presas de Leão."
  },
  AvgDialog_18905_Content_18 = {
    Text = "...Devo continuar?"
  },
  AvgDialog_18905_Content_19 = {
    Text = "Não, não é o que você pensa, eu—"
  },
  AvgDialog_18905_Content_2 = {
    Text = "Passos apressados ecoaram. Sarah apareceu, seu rosto cheio de raiva, seguida pela preocupada Aigis e o justo Ogier."
  },
  AvgDialog_18905_Content_20 = {
    Text = "Pare de arranjar desculpas! Você está usando as pessoas do asilo como cobaias para os experimentos daquele médico louco e depois trocando o dinheiro por ouro e joias!"
  },
  AvgDialog_18905_Content_21 = {
    Text = "Aigis, você passou por tratamentos. Você sabe que o dinheiro é claramente destinado a isso —"
  },
  AvgDialog_18905_Content_22 = {
    Text = "Sim... o laboratório fornece 5 Presas de Leo por pessoa como subsídio nutricional durante as sessões de tratamento, conforme acordado."
  },
  AvgDialog_18905_Content_23 = {
    Text = "A Miss Sarah usou todo esse dinheiro para comprar comida para todos."
  },
  AvgDialog_18905_Content_24 = {
    Text = "Não guardei um centavo desse dinheiro! Quanto às joias que aquela criança mencionou, é um absurdo. Por favor, acredite em mim, {Male=senhor,Female=senhorita} Ash!"
  },
  AvgDialog_18905_Content_25 = {
    Text = "Não dê desculpas!"
  },
  AvgDialog_18905_Content_26 = {
    Text = "Jenkins tirou dois anéis de prata do fundo da bolsa"
  },
  AvgDialog_18905_Content_27 = {
    Text = "Se não fosse você, quem colocou esses dois pequenos dispositivos na gaveta certa do escritório? Você acha que eu os fiz aparecer do nada?"
  },
  AvgDialog_18905_Content_28 = {
    Text = "Como isso acabou com você? Devolva—era um presente de outro patrocinador!"
  },
  AvgDialog_18905_Content_29 = {
    Text = "Confie em mim, uso-os como suprimentos de emergência para a casa de caridade! Como eu poderia prejudicar as crianças aqui por essas coisas?"
  },
  AvgDialog_18905_Content_3 = {
    Text = "Como você poderia—"
  },
  AvgDialog_18905_Content_30 = {
    Text = "Se você não tem nada a ver com isso, como explica essas... crianças?"
  },
  AvgDialog_18905_Content_31 = {
    Text = "Ramona apontou para o monstro rastejando no chão."
  },
  AvgDialog_18905_Content_32 = {
    Text = "... Uma criança?\nVocê quer dizer..."
  },
  AvgDialog_18905_Content_33 = {
    Text = "Sarah pareceu perceber algo, virando a cabeça rigidamente para examinar de perto a aparência daqueles monstros."
  },
  AvgDialog_18905_Content_34 = {
    Text = "Essas são as crianças e trabalhadores desaparecidos do albergue?"
  },
  AvgDialog_18905_Content_35 = {
    Text = "Não, não vai..."
  },
  AvgDialog_18905_Content_36 = {
    Text = "Que barulho."
  },
  AvgDialog_18905_Content_37 = {
    Text = [[
Pare de olhar para essas obras inacabadas.
Curve-se diante da verdadeira beleza.]]
  },
  AvgDialog_18905_Content_38 = {
    Text = "Ela empurrou a nova estátua finalizada em frente a Sarah."
  },
  AvgDialog_18905_Content_39 = {
    Text = "É uma estátua de uma criança, com características realistas sob uma casca de açúcar nublada."
  },
  AvgDialog_18905_Content_4 = {Text = "Ah—"},
  AvgDialog_18905_Content_40 = {
    Text = "Isso é... Isso é... Pequeno... Willy..."
  },
  AvgDialog_18905_Content_41 = {
    Text = "O olho da estátua de repente se contorceu."
  },
  AvgDialog_18905_Content_42 = {
    Text = "Yi—Yi—<Shake:Ah—>"
  },
  AvgDialog_18905_Content_43 = {
    Text = "Sarah soltou um grito doentio."
  },
  AvgDialog_18905_Content_44 = {
    Text = "Ela se encolheu, abraçando a cabeça, seus sussurros tristes tornando-se roucos e confusos, difíceis de entender"
  },
  AvgDialog_18905_Content_45 = {
    Text = "<Small:Sou inútil, não sou um bom diretor, não consigo proteger todos, nem as crianças...>"
  },
  AvgDialog_18905_Content_46 = {
    Text = "A Miss Sarah, por favor... Todos nós entendemos. Você fez o seu melhor."
  },
  AvgDialog_18905_Content_47 = {
    Text = "Desculpe, pequena Aigis; desculpe, pequena Lucy; desculpe, Jenkin, Henry, Diana..."
  },
  AvgDialog_18905_Content_48 = {
    Text = "Sarah levantou a cabeça, suas feições completamente fora de controle. Seus olhos e lábios se torceram em uma contorção inumana, semelhante a uma dança."
  },
  AvgDialog_18905_Content_49 = {
    Text = "Senhorita Sarah...?"
  },
  AvgDialog_18905_Content_5 = {
    Text = "Antes que ela pudesse terminar sua frase, ela viu a figura de açúcar torcida no chão soltar um grito horripilante."
  },
  AvgDialog_18905_Content_50 = {
    Text = "Os arredores se sentem como se estivessem submersos debaixo d'água, mergulhando repentinamente em um silêncio frio e sem vida.\nUma pressão invisível atinge inesperadamente, fazendo você ofegar enquanto percebe que algo está errado."
  },
  AvgDialog_18905_Content_51 = {
    Text = "Droga, Ramona, faça os outros saírem!"
  },
  AvgDialog_18905_Content_52 = {
    Text = "Sem tempo restante.\nA cabeça do jovem reitor se partiu como uma flor, espalhando gosma preta pelo chão."
  },
  AvgDialog_18905_Content_53 = {
    Text = "Srta. Sarah!!"
  },
  AvgDialog_18905_Content_54 = {
    Text = "Ela soltou um grito agudo. Os membros retorcidos ao seu redor responderam com uivos semelhantes a lobos, rapidamente se mutando em monstros infectados pela Dissolução."
  },
  AvgDialog_18905_Content_6 = {
    Text = "Como poderíamos? Esta pergunta deveria ser direcionada a você.\nNão é o fantasma da casa de caridade que você escondeu no porão? Ela nos contou tudo."
  },
  AvgDialog_18905_Content_7 = {
    Text = "Como se atraído pelo grito de Sarah, o humanoide semi-acucarado no chão se contorceu e rastejou em direção a ela."
  },
  AvgDialog_18905_Content_8 = {
    Text = "Ouça, Miss Sarah, suas ações não podem mais ser ocultadas."
  },
  AvgDialog_18905_Content_9 = {
    Text = "Por favor, forneça as informações de contato para a cooperação entre a Caridade e os Escultores o mais rápido possível, assim como a localização do Investigador <Blue:Sean Anderson>."
  },
  AvgDialog_18906_Content_1 = {
    Text = "Não julgue um livro pela capa"
  },
  AvgDialog_18906_Content_10 = {Text = "Um..."},
  AvgDialog_18906_Content_11 = {
    Text = "Eu já te disse, estamos fechados hoje. Preciso entrar para encontrar minha irmã."
  },
  AvgDialog_18906_Content_12 = {
    Text = "A criança, preguiçosamente, não o olhou sequer."
  },
  AvgDialog_18906_Content_13 = {
    Text = "Não, eu só queria perguntar... \nVocê conhece o caminho para o Asilo Lilyan?"
  },
  AvgDialog_18906_Content_14 = {Text = "..."},
  AvgDialog_18906_Content_15 = {
    Text = "<Small: De onde veio essa ovelha gorda...>"
  },
  AvgDialog_18906_Content_16 = {Text = "...?"},
  AvgDialog_18906_Content_17 = {
    Text = "Desculpe, eu me distraí e não captei isso. Você poderia repetir?"
  },
  AvgDialog_18906_Content_18 = {
    Text = "Aproxime-se e eu vou te mostrar."
  },
  AvgDialog_18906_Content_19 = {
    Text = "Olhe, é bem ali na esquina. Muito perto."
  },
  AvgDialog_18906_Content_2 = {
    Text = "Assim que você desceu do carro, foi sufocado pela umidade pesada e pelo cheiro de podridão"
  },
  AvgDialog_18906_Content_20 = {
    Text = "Ah! Muito obrigado."
  },
  AvgDialog_18906_Content_21 = {
    Text = "Não, eu deveria ser quem te agradece."
  },
  AvgDialog_18906_Content_22 = {
    Text = "Me agradecer?"
  },
  AvgDialog_18906_Content_23 = {
    Text = "Ogier virou-se para olhar as escadas onde a criança estava, mas estavam vazias.\nEm algum momento, a figura encapuzada havia deslizado até o final da rua, ainda segurando a carteira de Ogier."
  },
  AvgDialog_18906_Content_24 = {
    Text = "Ah, minha carteira—"
  },
  AvgDialog_18906_Content_25 = {
    Text = "Fato Londinium #2: O ritual de boas-vindas mais notório do Distrito Leste é fazer sua carteira desaparecer sem que você perceba."
  },
  AvgDialog_18906_Content_26 = {
    Text = "Parece que precisamos ajudar o Ogier.\nVamos, Guardião."
  },
  AvgDialog_18906_Content_3 = {
    Text = "Uma poderosa onda de tontura atinge você, acompanhada por um forte zumbido em seus ouvidos.\nImagens borradas passam pela sua mente, como se você já tivesse testemunhado esta cena antes."
  },
  AvgDialog_18906_Content_4 = {
    Text = "É uma ilusão, ou isso é uma parte da sua memória perdida?"
  },
  AvgDialog_18906_Content_5 = {
    Text = "Não há placas de sinalização ou marcos... e isso não corresponde ao mapa..."
  },
  AvgDialog_18906_Content_6 = {
    Text = "Um fato de Londinium: O Distrito Leste pode fazê-lo se perder com seu nevoeiro incessante e suas estradas estreitas e sinuosas."
  },
  AvgDialog_18906_Content_7 = {
    Text = "Eu vou perguntar pela direção."
  },
  AvgDialog_18906_Content_8 = {
    Text = "Uma criança vestindo um capuz esfarrapado repousa preguiçosamente à beira da estrada, sua capa oversized a fazendo parecer especialmente diminuta."
  },
  AvgDialog_18906_Content_9 = {
    Text = "Ogier caminhou em direção à criança e fez uma leve reverência."
  },
  AvgDialog_18907_Content_1 = {Text = "Malária"},
  AvgDialog_18907_Content_10 = {
    Text = "Jenkin! Você... não pode trazer patrocinadores para a <Blue:Área Médica>. Se eles verem, então..."
  },
  AvgDialog_18907_Content_11 = {
    Text = "Você fez um sinal para Ramona, que se aproximou de Aigis e perguntou com gentileza."
  },
  AvgDialog_18907_Content_12 = {
    Text = "Aigis, você poderia nos explicar por que os patrocinadores não são permitidos na área médica?"
  },
  AvgDialog_18907_Content_13 = {
    Text = "Isso... isso... eu... eles... eles são muito fracos..."
  },
  AvgDialog_18907_Content_14 = {
    Text = "Aigis parecia hesitante, olhando para os pacientes atrás dela e depois para seu grupo bem vestido, insegura sobre como responder."
  },
  AvgDialog_18907_Content_15 = {
    Text = "Aproveitando esta oportunidade, você e Ogier se aproximam do idoso na cama e o observam de perto."
  },
  AvgDialog_18907_Content_16 = {
    Text = "O velho estava amarrado com tiras de pano áspero e assegurado à cama. Seu corpo apresentava feridas estranhas que pareciam costuras torcidas, e entre a carne não cicatrizada, havia um fluido escuro e viscoso."
  },
  AvgDialog_18907_Content_17 = {
    Text = "Aigis, esta inspeção determinará se forneceremos apoio financeiro ao Orfanato da Lily.\nCom certeza você entende que nenhum patrocinador quer que seu dinheiro seja desperdiçado em fraude."
  },
  AvgDialog_18907_Content_18 = {
    Text = "Eles não vão te machucar, então não resista."
  },
  AvgDialog_18907_Content_19 = {
    Text = "A luta de Aigis desapareceu após um breve momento de recuperar o fôlego. Ela respirou fundo e respondeu com uma voz tão suave quanto o zumbido de um mosquito."
  },
  AvgDialog_18907_Content_2 = {
    Text = "Jenkin o conduz pelo quintal, apontando para uma pequena e surrada cabana no canto."
  },
  AvgDialog_18907_Content_20 = {
    Text = "<Small:A Srta. Sarah disse que se os patrocinadores verem esses pacientes, vão pensar que somos um poço sem fundo...>"
  },
  AvgDialog_18907_Content_21 = {
    Text = "Você não deveria ter ouvido aquela mulher miserável! Esses patrocinadores nos ajudarão a lidar com o <Yellow:Fantasma do Orfanato>. Eles também estão procurando alguém e com certeza encontrarão minha irmã..."
  },
  AvgDialog_18907_Content_22 = {
    Text = "A zona médica é muito perigosa!"
  },
  AvgDialog_18907_Content_23 = {
    Text = "O tom elevado de Aigis parou abruptamente. Ela olhou ansiosamente para o velho inconsciente antes de puxar Jenkin para longe da cama."
  },
  AvgDialog_18907_Content_24 = {
    Text = "E se eu infectar você e os patrocinadores"
  },
  AvgDialog_18907_Content_25 = {
    Text = "Aigis respondeu a Jenkin nervosamente e sem saber o que fazer, segurando seu ursinho de pelúcia com força. As mangas brancas dela escorregaram pelos braços, revelando horríveis marcas de costura pretas e dois sulcos vermelhos inchados."
  },
  AvgDialog_18907_Content_26 = {
    Text = "O braço esguio da garota está marcado por uma fissura negra que se assemelha a um centopéia gigante, suas bordas lentamente exudando uma gosma negra, evocando uma sensação de terror."
  },
  AvgDialog_18907_Content_27 = {
    Text = "Aigis, o ferimento no seu braço..."
  },
  AvgDialog_18907_Content_28 = {
    Text = "Aigis puxou rapidamente suas mangas, balançando a cabeça para evitar o olhar de Ramona."
  },
  AvgDialog_18907_Content_29 = {
    Text = "Isto é do último episódio, quando eu acidentalmente caí das escadas."
  },
  AvgDialog_18907_Content_3 = {
    Text = "Ao olhar pela janela, você pode ver Aigis correndo de um lado para o outro.\nEla está carregando uma bacia de metal, movendo-se apressadamente levando os curativos sujos da beira da cama para a pilha de roupas sujas."
  },
  AvgDialog_18907_Content_30 = {
    Text = "Este ponto de costura não é nada semelhante a um simples arranhão ou hematoma."
  },
  AvgDialog_18907_Content_31 = {
    Text = "Veja, eles podem \"ver.\"\nDiga-lhes tudo. Eles são nossa última esperança."
  },
  AvgDialog_18907_Content_32 = {
    Text = "<Small:Eles estarão em perigo. Não podemos...>"
  },
  AvgDialog_18907_Content_33 = {
    Text = "Ouça, Aigis. Apenas dizendo-nos a verdade, podemos realmente determinar que tipo de ajuda você precisa."
  },
  AvgDialog_18907_Content_34 = {
    Text = "Ao seu lado, o velho soltou um som gorgolejante da garganta, seu braço emagrecido rompendo o pano de amarração com um puxão repentino—"
  },
  AvgDialog_18907_Content_35 = {
    Text = "Guardião, cuidado!"
  },
  AvgDialog_18907_Content_4 = {
    Text = "Hm? O que está acontecendo?"
  },
  AvgDialog_18907_Content_5 = {
    Text = "Parece que ela ouviu o chamado de alguém. Ela colocou a bacia de ferro para baixo, se curvou e se inclinou ao lado da cama.\nDe sua perspectiva, a pequena figura dela não é mais visível; apenas sua voz suave e gentil pode ser ouvida."
  },
  AvgDialog_18907_Content_6 = {
    Text = "Vovô Robert, por favor, não se levante. Eu vou trazer a água para você."
  },
  AvgDialog_18907_Content_7 = {
    Text = "Não diga isso. Sua doença definitivamente vai melhorar.\nNaquela hora, poderemos ir ao Parque Drell brincar e alimentar os pombos juntos."
  },
  AvgDialog_18907_Content_8 = {
    Text = "\"Bang!\" Jenkin empurrou a porta da cabine.\nAigis ficou assustada, quase derramando água no paciente em seu pânico."
  },
  AvgDialog_18907_Content_9 = {
    Text = "Olhe, esses são os <Yellow:Malucos>."
  },
  AvgDialog_18908_Content_1 = {
    Text = "Não fale o que não deve"
  },
  AvgDialog_18908_Content_10 = {
    Text = "No momento em que ela viu o doce, o rosto de Aigis ficou pálido, mas ela ainda assim aceitou-o cuidadosamente."
  },
  AvgDialog_18908_Content_11 = {
    Text = "Você se lembra do dia em que nos conhecemos?"
  },
  AvgDialog_18908_Content_12 = {
    Text = "Hmm, nunca vou esquecer."
  },
  AvgDialog_18908_Content_13 = {
    Text = "Há 10 dias, Londinium Leste\nCasa de Caridade da Lily"
  },
  AvgDialog_18908_Content_14 = {
    Text = "À meia-noite, o distrito leste estava escuro. Nem as luzes da rua nem a lua podiam penetrar a névoa densa, deixando apenas sombras vagas flutuando no ar"
  },
  AvgDialog_18908_Content_15 = {
    Text = "A garota de cabelos brancos, segurando culpa e medo, correu pelo pátio escuro e vazio do asilo.\nSó quando colidiu com algo escondido nas sombras é que gritou de dor."
  },
  AvgDialog_18908_Content_16 = {Text = "Ai!"},
  AvgDialog_18908_Content_17 = {Text = "Ai!"},
  AvgDialog_18908_Content_18 = {
    Text = "Você, você não é o pequeno Mike, nem a pequena Lucy! Quem é você...!"
  },
  AvgDialog_18908_Content_19 = {
    Text = "Eu deveria estar perguntando quem você é! Vagando pela calada da noite, sem dormir, e me assustando."
  },
  AvgDialog_18908_Content_2 = {
    Text = "Você se machucou lá com o lunático?"
  },
  AvgDialog_18908_Content_20 = {
    Text = "Desculpe... Eu achei que encontrei..."
  },
  AvgDialog_18908_Content_21 = {
    Text = "O que você encontrou?"
  },
  AvgDialog_18908_Content_22 = {
    Text = "Eu encontrei... um fantasma... Sim, eu pensei que era o <Red:Fantasmas do Asilo>..."
  },
  AvgDialog_18908_Content_23 = {
    Text = "Fantasmas? Que absurdo. Deixe-me ser honesto com você, não sou deste lugar maldito.\nEu sou Jenkin, e este é Marrom."
  },
  AvgDialog_18908_Content_24 = {Text = "Chiado!"},
  AvgDialog_18908_Content_25 = {
    Text = "Estou aqui à procura da minha irmã. O nome dela é <Blue:Mason>. Ela desapareceu por aqui há duas semanas.\nAlguém chamado Mason apareceu por aqui recentemente?"
  },
  AvgDialog_18908_Content_26 = {
    Text = "Recentemente, houve muitos recém-chegados na casa de pobres, e ainda não reconheci todos os seus rostos..."
  },
  AvgDialog_18908_Content_27 = {
    Text = "Pense cuidadosamente. Ela tem mais ou menos essa altura, com cabelo longo, <Yellow:prendido com um lindo laço vermelho>. As extremidades do laço têm uma fivela quadrada gravada com a letra M."
  },
  AvgDialog_18908_Content_28 = {
    Text = "Ela vem aqui ocasionalmente para tratamento. Ela não voltou para casa desde sua última visita. Você a manteve aqui para trabalhar?"
  },
  AvgDialog_18908_Content_29 = {
    Text = "<Shake:Doente, um paciente?>\nS-Sinto muito... Eu também não vi uma jovem paciente..."
  },
  AvgDialog_18908_Content_3 = {
    Text = "Hmm... Estou bem."
  },
  AvgDialog_18908_Content_30 = {
    Text = "Tsk, tanto faz. Eu não pensei que teria a sorte de encontrar alguém que entendesse.\nMas você quase me pegou. Você terá que assumir a responsabilidade por isso."
  },
  AvgDialog_18908_Content_31 = {
    Text = "Tudo bem, vou te levar à minha base secreta! A diretora nunca entra na torre do relógio, então ela definitivamente não vai te encontrar lá."
  },
  AvgDialog_18908_Content_32 = {
    Text = "Honestamente, foi pura sorte encontrar você, Aigis.\nCaso contrário, eu teria sido arrastado para fora pelo meu capuz."
  },
  AvgDialog_18908_Content_33 = {
    Text = "Não diga isso. Todos na casa de caridade são realmente maravilhosos. É apenas que muitas coisas ruins aconteceram recentemente, por isso todos estão se sentindo um pouco para baixo..."
  },
  AvgDialog_18908_Content_34 = {Text = "Aigis."},
  AvgDialog_18908_Content_35 = {Text = "Sim?"},
  AvgDialog_18908_Content_36 = {
    Text = "Eu sei que as pessoas do orfanato significam muito para você... mas sempre o considerei como um amigo. Então, você me vê como um amigo?"
  },
  AvgDialog_18908_Content_37 = {
    Text = "Claro! Eu realmente, realmente gosto de passar tempo com você, Jenkin, assim—comendo doces e conversando."
  },
  AvgDialog_18908_Content_38 = {
    Text = "Desde que você me considera um amigo, por que não me conta a verdade?\nAigis, pare de mentir para mim."
  },
  AvgDialog_18908_Content_39 = {
    Text = "Eu... eu não entendo o que você está dizendo..."
  },
  AvgDialog_18908_Content_4 = {
    Text = "...Eu trouxe aqueles patrocinadores. Você está bravo comigo?"
  },
  AvgDialog_18908_Content_40 = {
    Text = "Eu encontrei o <Blue:livro contábil> e o <Blue:identidade do estudante> da pessoa que %player% está procurando naquele escritório daquela mulher horrível. Eu sei que ela está vendendo você para aqueles médicos estranhos para experimentos!"
  },
  AvgDialog_18908_Content_41 = {
    Text = "Aquela mulher gosta mais de você e até confia em você para cuidar daqueles pacientes. Aigis, você deve saber de algo. Você pode me contar?"
  },
  AvgDialog_18908_Content_42 = {
    Text = "Eu, eu, <Small: Não sei...>"
  },
  AvgDialog_18908_Content_43 = {
    Text = "A garota murmurou, sua voz se apagando.\nSeu rosto estava pálido, como se estivesse sofrendo de uma dor imensa."
  },
  AvgDialog_18908_Content_44 = {
    Text = "A Universidade Mythag se destaca em descobrir segredos; eles logo descobrirão a verdade."
  },
  AvgDialog_18908_Content_45 = {
    Text = "Você não pode viver acorrentado para sempre."
  },
  AvgDialog_18908_Content_46 = {
    Text = "Jenkin, se tudo o que foi perdido não pode ser recuperado... a suposta verdade ainda é tão importante?"
  },
  AvgDialog_18908_Content_47 = {
    Text = "Claro, isso é importante! Nada é mais importante para mim do que encontrar minha irmã."
  },
  AvgDialog_18908_Content_48 = {
    Text = "Eu sei que você tem medo daquela mulher podre, mas por que você continua a defendê-la? Ela não apenas vendeu os trabalhadores para o médico, mas também abriga o <Yellow:Fantasma do Asilo>."
  },
  AvgDialog_18908_Content_49 = {
    Text = "Ji, o Fantasma do Asilo?"
  },
  AvgDialog_18908_Content_5 = {
    Text = "Como isso poderia ser!"
  },
  AvgDialog_18908_Content_50 = {
    Text = "Sim, é a lenda que você me contou.\n<Yellow:Não ande por aí em noites de nevoeiro, ou você será pego por um fantasma vagando com uma faca>."
  },
  AvgDialog_18908_Content_51 = {
    Text = "E-isso foi apenas algo que eu inventei... É muito perigoso à noite. Eu não queria que você ficasse correndo por aí."
  },
  AvgDialog_18908_Content_52 = {
    Text = "Pare de dar desculpas por Sarah! Já encontrei o <Yellow:Porão com Fantasmas> e ouvi o <Yellow:Sons de uma Faca>. \nMinha irmã está lá dentro?"
  },
  AvgDialog_18908_Content_53 = {
    Text = "À medida que a palavra \"porão\" sai da boca de Jenkin, o último traço de cor desaparece do rosto de Aigis."
  },
  AvgDialog_18908_Content_54 = {
    Text = "Não tenha medo, Aigis. O buraco no seu coração permitirá que Ele entre."
  },
  AvgDialog_18908_Content_55 = {
    Text = "Siga a orientação de Prata, e a luz mostrará o caminho para você."
  },
  AvgDialog_18908_Content_56 = {
    Text = "Jenkin, sinto muito, eu não consigo..."
  },
  AvgDialog_18908_Content_57 = {
    Text = "Com lágrimas nos olhos, Aigis olhou para Jenkin, depois virou-se e subiu de volta na torre do relógio, descendo as escadas sem hesitação."
  },
  AvgDialog_18908_Content_58 = {
    Text = "Aigis! Para onde você está indo!"
  },
  AvgDialog_18908_Content_59 = {
    Text = "Em algum momento, uma névoa apareceu na casa de pobres.\nEla surgiu de repente, envolvendo tudo em uma camada de umidade e tornando tudo indistinto."
  },
  AvgDialog_18908_Content_6 = {
    Text = "Estou apenas preocupado que você também possa... estar infectado..."
  },
  AvgDialog_18908_Content_60 = {
    Text = "Aigis! Droga, como essa névoa entrou aqui?!"
  },
  AvgDialog_18908_Content_61 = {
    Text = "Da Névoa distante vem o som de Caro crescendo e uma suave canção embebida em névoa."
  },
  AvgDialog_18908_Content_62 = {
    Text = "<Italic:Velho Charlie tem um gato tigrado que ele adora muito...>"
  },
  AvgDialog_18908_Content_63 = {
    Text = "Jenkin poliu sua lanterna, seu fraco brilho parecendo tão fraco na espessa névoa."
  },
  AvgDialog_18908_Content_64 = {
    Text = "Passos suaves se aproximam de longe, quase ensurdecedores no corredor silencioso"
  },
  AvgDialog_18908_Content_65 = {
    Text = "Quem, quem está aí?\nSaia! Eu, eu aviso, estou armada!"
  },
  AvgDialog_18908_Content_66 = {
    Text = "Não havia corrente de ar no corredor, mas a chama da lâmpada tremulava como se soprada pelo vento"
  },
  AvgDialog_18908_Content_67 = {
    Text = "Os passos se aproximam cada vez mais. As garras de Brown cravam-se profundamente no ombro de Jenkins, ele mostra os dentes, emitindo um chiado agudo característico dos roedores"
  },
  AvgDialog_18908_Content_68 = {
    Text = "Como se desencadeada pela voz de Brown, os passos de repente aceleraram, indo diretamente em direção a Jenkin."
  },
  AvgDialog_18908_Content_69 = {
    Text = "Uma sombra densa engoliu completamente a fraca luz da vela. A menina fechou os olhos e gritou alto, mas apenas sentiu uma rajada de névoa atingir seu rosto."
  },
  AvgDialog_18908_Content_7 = {Text = "Bom."},
  AvgDialog_18908_Content_70 = {
    Text = "Uma mão surgiu das trevas, pousando precisamente no ombro de Jenkin."
  },
  AvgDialog_18908_Content_71 = {
    Text = "Qual é o problema? Por que sua face está tão pálida?"
  },
  AvgDialog_18908_Content_72 = {
    Text = "R-Rogers? Você viu a Aigis?"
  },
  AvgDialog_18908_Content_73 = {
    Text = "Não se preocupe, Aigis está muito familiarizada com este orfanato. Ela ficará bem."
  },
  AvgDialog_18908_Content_74 = {
    Text = "Eu entendo, noites nebulosas podem realmente fazer as pessoas se sentirem aterrorizadas e inquietas."
  },
  AvgDialog_18908_Content_75 = {
    Text = "Rogers abriu a porta, e a luz quente dissipou as sombras profundas do corredor"
  },
  AvgDialog_18908_Content_76 = {
    Text = "Ele pegou uma boneca finamente confeccionada da cama e sorriu para a garota."
  },
  AvgDialog_18908_Content_77 = {
    Text = "Como uma consolação, você gostaria de dar um toque?\n<Blue:George> ficará muito feliz."
  },
  AvgDialog_18908_Content_78 = {
    Text = "Os olhos inorgânicos da boneca refletem a luz amarela, como se silenciosamente implorassem à garota: toque-me, só uma vez"
  },
  AvgDialog_18908_Content_79 = {
    Text = "Acaricie-me, e então—"
  },
  AvgDialog_18908_Content_8 = {
    Text = "Jenkin espalhou dramaticamente as mãos, revelando dois pequenos doces em suas palmas."
  },
  AvgDialog_18908_Content_80 = {
    Text = "<Red: Torne-se meu fiel companheiro.>"
  },
  AvgDialog_18908_Content_81 = {
    Text = "Com um \"squeak,\" o grito de Brown despertou Jenkin de sua letargia."
  },
  AvgDialog_18908_Content_82 = {
    Text = "Não, não precisa! Eu não estou interessado em vocês, artistas da alta sociedade."
  },
  AvgDialog_18908_Content_83 = {
    Text = "Oh, pequeno camundongo ingênuo. Na verdade, beleza e arte nunca diferenciam entre ricos e pobres, nobres e humildes.\nCapturar o sofrimento dentro da beleza é verdadeiramente, verdadeiramente maravilhoso."
  },
  AvgDialog_18908_Content_84 = {
    Text = "Rogers olhou para a garota cautelosa e o rato cinza espiando de seu capuz, seus olhos ardendo com um desejo irresistível."
  },
  AvgDialog_18908_Content_85 = {
    Text = "Se eu tiver a chance, também transformarei vocês todos em esculturas de cera.\nQue tal chamá-las de \"Marrom e Jenkin\"?"
  },
  AvgDialog_18908_Content_9 = {
    Text = "Aqui, um para cada um de vocês. Vocês devem prometer não ficar bravos comigo depois de comer este doce."
  },
  AvgDialog_18909_Content_1 = {
    Text = "Espectros subterrâneos"
  },
  AvgDialog_18909_Content_10 = {
    Text = "Ramona permaneceu composta, falando fluentemente como uma atriz de palco experiente recitando falas bem ensaiadas.\nO rosto de Ogier já estava vermelho."
  },
  AvgDialog_18909_Content_11 = {
    Text = "Como esperado do jovem mestre do Nobre Ashe, assumindo responsabilidades tão significativas em uma idade tão jovem.\nNo orfanato, há muitas crianças da sua idade que só conseguem ajudar a servir mingau ou limpar os chão..."
  },
  AvgDialog_18909_Content_12 = {
    Text = "Por favor, por favor, não diga isso..."
  },
  AvgDialog_18909_Content_13 = {
    Text = "Ramona limpou a garganta e rapidamente mudou de assunto."
  },
  AvgDialog_18909_Content_14 = {
    Text = "Assim, realizaremos uma pesquisa de campo no Distrito Leste, financiada a longo prazo para entender as condições locais.\nA Casa de Caridade de Lily é nossa primeira parada, e esperamos que a diretora seja honesta conosco..."
  },
  AvgDialog_18909_Content_15 = {
    Text = "Ramona contou brevemente o incidente em que o segurança da instituição ficou violento e feriu pessoas, é claro, omitindo as partes relacionadas à Dissolução."
  },
  AvgDialog_18909_Content_16 = {
    Text = "Você está ciente disso?"
  },
  AvgDialog_18909_Content_17 = {
    Text = "Não consigo acreditar! Aquele segurança, ele definitivamente não é do nosso orfanato.\nNão temos nada que valha a pena roubar ou saquear, então por que contratar segurança?"
  },
  AvgDialog_18909_Content_18 = {
    Text = "Ela tinha uma expressão desconfortável, claramente contando uma mentira."
  },
  AvgDialog_18909_Content_19 = {
    Text = "Mas, Senhora Sarah..."
  },
  AvgDialog_18909_Content_2 = {
    Text = "Você e seu grupo entram na casa de caridade, e de longe, você vê uma freira liderando várias crianças e trabalhadores, alinhados para esperar por você."
  },
  AvgDialog_18909_Content_20 = {
    Text = "Sarah lançou um olhar severo para a garota ao seu lado, que exibia uma expressão de pânico."
  },
  AvgDialog_18909_Content_21 = {
    Text = "Aigis, você ainda é jovem. Cuidar de si mesma é a coisa mais importante. Fique fora dos assuntos dos adultos."
  },
  AvgDialog_18909_Content_22 = {
    Text = "A garota franziu os lábios, baixou o olhar para a boneca em sua mão e ficou em silêncio."
  },
  AvgDialog_18909_Content_23 = {
    Text = "...Certo, leve um trabalhador para lá. Cubra-o com um pano para que os ratos não o roam."
  },
  AvgDialog_18909_Content_24 = {
    Text = "Depois de dizer isso, ela se virou para vocês novamente."
  },
  AvgDialog_18909_Content_25 = {
    Text = "Desculpe, quando o doutor chegar, pedirei que ele ajude com o sepultamento."
  },
  AvgDialog_18909_Content_26 = {Text = "Doutora?"},
  AvgDialog_18909_Content_27 = {
    Text = "Ah... sim, isso mesmo. Temos várias crianças aqui, e graças à generosidade de outros patrocinadores, contratamos um médico para verificar regularmente suas condições."
  },
  AvgDialog_18909_Content_28 = {
    Text = "É hora do meu próximo exame de corpo nos próximos dias."
  },
  AvgDialog_18909_Content_29 = {
    Text = "Não há necessidade de notificar a polícia?"
  },
  AvgDialog_18909_Content_3 = {
    Text = "O asilo está ocupado, desculpe pela recepção tardia, estimado {Male=senhor,Female=senhorita} Ash, Srta. Mary.\nSou a administradora Sarah"
  },
  AvgDialog_18909_Content_30 = {
    Text = "Ah, você vê, o Distrito Leste tem suas próprias regras."
  },
  AvgDialog_18909_Content_31 = {
    Text = "Mesmo para o perturbador <Red:Incidente de Desmembramento>, eles apenas enviaram alguém para coletar o corpo, sem tomar mais nenhuma ação."
  },
  AvgDialog_18909_Content_32 = {
    Text = "Para pessoas como nós, já é difícil ter comida suficiente; não temos energia para desperdiçar com essas coisas."
  },
  AvgDialog_18909_Content_33 = {
    Text = "Dito isso, Sarah te levou para o albergue.\nAtrás de você, os trabalhadores formaram silenciosamente duas filas, como guardas ou até mesmo carcereiros."
  },
  AvgDialog_18909_Content_34 = {
    Text = "Você ouve Ramona pronunciando suavemente as palavras."
  },
  AvgDialog_18909_Content_35 = {
    Text = "Fato Londinium #3 —"
  },
  AvgDialog_18909_Content_36 = {
    Text = "\"No Distrito Oriental, o valor de uma pessoa não pode ser medido, pois não tem valor.\""
  },
  AvgDialog_18909_Content_37 = {
    Text = [[
No corredor silencioso, uma porta com uma placa de metal lentamente se abriu.
Um rato escorregou pela fresta, olhou ao redor e chiou duas vezes nas sombras]]
  },
  AvgDialog_18909_Content_38 = {Text = "Chiado!"},
  AvgDialog_18909_Content_39 = {
    Text = "Da última vez você disse que não havia ninguém! Se não fosse por Aigis, eu estaria em apuros"
  },
  AvgDialog_18909_Content_4 = {
    Text = "Vendo que ninguém ao seu redor respondeu, ela franziu a testa e deu um tapinha nas costas da garota.\nA garota parecia distraída. Assustada, ela rapidamente se curvou para todos vocês."
  },
  AvgDialog_18909_Content_40 = {
    Text = "Jenkin espiou em torno da esquina, confirmou que o corredor estava vazio e escorregou pela fenda da porta, fechando-a atrás de si."
  },
  AvgDialog_18909_Content_41 = {
    Text = "Chiado, chiado chiado!"
  },
  AvgDialog_18909_Content_42 = {
    Text = "Sim, sim, você está certo. Nosso Brown é o melhor!"
  },
  AvgDialog_18909_Content_43 = {
    Text = "Chirp, chirp."
  },
  AvgDialog_18909_Content_44 = {
    Text = "Deixa eu ver que segredos esta mulher odiosa está escondendo.\nAnéis, colares... Isso tudo é feito de ouro?"
  },
  AvgDialog_18909_Content_45 = {
    Text = "Aquela mulher desagradável nem comprou doce para Aigis, dizendo \"a renda não cobre as despesas\", enquanto se acumula todas essas gostosuras para si mesma!"
  },
  AvgDialog_18909_Content_46 = {
    Text = "Chave, bom. Parece que entrar e sair de outros lugares será mais fácil agora.\nRealmente precisamos agradecer aquele <Yellow:\"Pessoa de Autoajuda\">; agora podemos conduzir nossa própria investigação do asilo."
  },
  AvgDialog_18909_Content_47 = {
    Text = "Chirp, chirp."
  },
  AvgDialog_18909_Content_48 = {
    Text = "Não se apresse, Marrom. Ainda há tempo."
  },
  AvgDialog_18909_Content_49 = {
    Text = "Huh... É isto... um livro-razão?\nMike, masculino, 5 anos, 10 Presas de Leão; Diana, feminina, 23 anos, 5 Presas de Leão..."
  },
  AvgDialog_18909_Content_5 = {
    Text = "Bem-vindo, todos. Preparamos alguns petiscos no restaurante..."
  },
  AvgDialog_18909_Content_50 = {
    Text = "De jeito nenhum... O asilo vendeu todo mundo?!"
  },
  AvgDialog_18909_Content_51 = {Text = "..."},
  AvgDialog_18909_Content_52 = {
    Text = "Chiado, chiado chiado!"
  },
  AvgDialog_18909_Content_53 = {
    Text = "Brown de repente soltou um aviso agudo enquanto a porta de madeira rangeu ao abrir."
  },
  AvgDialog_18909_Content_54 = {
    Text = "O que apareceu diante de Sarah foi um escritório vazio."
  },
  AvgDialog_18909_Content_55 = {
    Text = "Ela half-abriu a gaveta, deslizou uma peça fina do tamanho da palma da mão, then forçosamente empurrou a gaveta de madeira para fechar e rapidamente virou-se para sair."
  },
  AvgDialog_18909_Content_56 = {
    Text = "Chirp, chirp."
  },
  AvgDialog_18909_Content_57 = {
    Text = "Após Sarah sair, Brown foi o primeiro a sair da sombra da planta em vaso no canto."
  },
  AvgDialog_18909_Content_58 = {
    Text = "Jenkin seguiu silenciosamente e abriu a gaveta."
  },
  AvgDialog_18909_Content_59 = {
    Text = "Identificação de Estudante? <Blue:Sean... Anderson>...\nOs símbolos nela não são os mesmos do dinheiro de ouro daquele idiota esta manhã?"
  },
  AvgDialog_18909_Content_6 = {
    Text = "Hmm, quem é este...?"
  },
  AvgDialog_18909_Content_60 = {
    Text = "Chiado, chiado chiado!"
  },
  AvgDialog_18909_Content_61 = {
    Text = "Não se apresse, Marrom.\nPreciso manter a calma... calma..."
  },
  AvgDialog_18909_Content_62 = {
    Text = "Verifiquei tudo; o nome da minha irmã não está no livro de registro."
  },
  AvgDialog_18909_Content_63 = {
    Text = "No entanto, temos tantas chaves. Posso abrir todas as portas neste lugar miserável! Recuso-me a acreditar que não conseguimos encontrar nenhuma evidência."
  },
  AvgDialog_18909_Content_64 = {
    Text = "Irmã, espere por mim."
  },
  AvgDialog_18909_Content_65 = {Text = "..."},
  AvgDialog_18909_Content_66 = {Text = "..."},
  AvgDialog_18909_Content_67 = {
    Text = "Droga, este é o último quarto."
  },
  AvgDialog_18909_Content_68 = {
    Text = "Está completamente escuro, e não há nada aqui.\nEstamos voltando de mãos vazias, Marrom."
  },
  AvgDialog_18909_Content_69 = {
    Text = "Chiado, chiado chiado!"
  },
  AvgDialog_18909_Content_7 = {
    Text = "Sarah olhou para Ogier na equipe, depois para você."
  },
  AvgDialog_18909_Content_70 = {
    Text = "O que? Abaixo do chão?"
  },
  AvgDialog_18909_Content_71 = {
    Text = "Jenkin hesitou por um momento, mas acendeu delicadamente a lanterna. Ela virou a chama para a configuração mais baixa e se inclinou mais perto do chão."
  },
  AvgDialog_18909_Content_72 = {
    Text = "Uma linha de formigas marchava em uma formação ordenada para dentro da fenda da tábua de madeira."
  },
  AvgDialog_18909_Content_73 = {
    Text = "Jenkin arrancou dois pregos e levantou a tábua.\nDebaixo havia uma tampa de ferro quadrada de 25 polegadas."
  },
  AvgDialog_18909_Content_74 = {
    Text = "Jenkin experimentou todas as chaves."
  },
  AvgDialog_18909_Content_75 = {
    Text = [[
Droga, nenhuma dessas portas vai abrir.
A mulher escondeu outra chave?]]
  },
  AvgDialog_18909_Content_76 = {
    Text = "Ela pressionou o ouvido contra a chapa de ferro, tentando captar sons do porão."
  },
  AvgDialog_18909_Content_77 = {
    Text = "<Italic:Arranhar... Arranhar...>"
  },
  AvgDialog_18909_Content_78 = {Text = "!!"},
  AvgDialog_18909_Content_79 = {
    Text = "Isto é... o <Yellow:Fantasma do Asilo> que Aigis mencionou...?!"
  },
  AvgDialog_18909_Content_8 = {
    Text = "Ele é meu irmão mais novo, Ogier, e um dos futuros herdeiros da família Ash."
  },
  AvgDialog_18909_Content_80 = {
    Text = "Chiado, chiado chiado!"
  },
  AvgDialog_18909_Content_81 = {
    Text = "Passos desmaiados podiam ser ouvidos do lado de fora da porta."
  },
  AvgDialog_18909_Content_82 = {
    Text = "Sem escolha, Marrom.\nSe aquela mulher desagradável ainda está levantando fantasmas na casa de pobres, não podemos derrotá-la sozinhos."
  },
  AvgDialog_18909_Content_83 = {
    Text = "Precisamos <Yellow:alguém que ela teme>..."
  },
  AvgDialog_18909_Content_84 = {
    Text = "Jenkin se esconde nas sombras, espiando por trás do vaso de planta."
  },
  AvgDialog_18909_Content_85 = {
    Text = "No corredor, Sarah estava apresentando obsequiosamente a situação financeira do Poorhouse ao grupo de visitantes."
  },
  AvgDialog_18909_Content_86 = {
    Text = "...É isso que Aigis chamou de \"indivíduos autossuficientes\"?"
  },
  AvgDialog_18909_Content_87 = {
    Text = "Jenkin acenou pensativamente, depois escapuliu da sala de armazenamento escura enquanto o grupo estava despreparado."
  },
  AvgDialog_18909_Content_88 = {
    Text = "Atrás dela, as tábuas do chão parcialmente desabotoadas revelaram uma fissura escura e profunda, aguardando silenciosamente a chegada de visitantes."
  },
  AvgDialog_18909_Content_9 = {
    Text = "O Nobre espera que o jovem mestre Ogier compreenda profundamente a situação atual do Distrito Leste, o que o ajudará a melhorar a área de forma mais eficaz quando assumir os negócios da família no futuro."
  },
  AvgDialog_18910_Content_1 = {
    Text = "Droga, mais e mais monstros estão invadindo!"
  },
  AvgDialog_18910_Content_2 = {
    Text = "Ogier, feche o portão do porão! Ramona, concentre-se em restringir Sarah!"
  },
  AvgDialog_18910_Content_3 = {
    Text = "Ouça meu comando!"
  },
  AvgDialog_18911_Content_1 = {
    Text = "Está tudo acabado."
  },
  AvgDialog_18911_Content_10 = {
    Text = "A lâmina deixa um longo rastro prateado enquanto a mão se move."
  },
  AvgDialog_18911_Content_11 = {
    Text = "Senhorita Sarah! Tiyug! Ajude! Salve-me! <Big: Salve-me!>"
  },
  AvgDialog_18911_Content_12 = {
    Text = "A ponta da faca se aproxima, cada vez mais, até preencher toda a visão.\nEntão—"
  },
  AvgDialog_18911_Content_13 = {
    Text = "<Shake:Ah——!>"
  },
  AvgDialog_18911_Content_14 = {
    Text = "Aigis tremia, um grito de pavor subindo de fundo de sua garganta."
  },
  AvgDialog_18911_Content_15 = {
    Text = "Como se convocado por aquele grito, o misterioso psicólogo apareceu silenciosamente atrás dela"
  },
  AvgDialog_18911_Content_16 = {
    Text = "A little Aigis encontrou novos problemas? Devemos falar com a Doutora Clementine?"
  },
  AvgDialog_18911_Content_17 = {
    Text = "Doutora Clementine?!"
  },
  AvgDialog_18911_Content_18 = {
    Text = "A casa de caridade à meia-noite é longe do lugar ideal para uma visita. Por que você está aqui?"
  },
  AvgDialog_18911_Content_19 = {
    Text = "Não seja tão sério. O orphanato tem estado um pouco instável ultimamente. O Sr. Rogers está preocupado com o estado mental dos trabalhadores e das crianças, então ele me contratou para cuidar de todos."
  },
  AvgDialog_18911_Content_2 = {
    Text = "Ramona se virou para a garota aterrorizada, que estava tremendo tanto que não conseguia pronunciar uma única palavra."
  },
  AvgDialog_18911_Content_20 = {
    Text = "Às vezes, quando vejo pacientes até tarde da noite, fico na casa dos pobres e durmo em um quarto perto das crianças."
  },
  AvgDialog_18911_Content_21 = {
    Text = "Você conhece Aigis?"
  },
  AvgDialog_18911_Content_22 = {
    Text = "A chegada de Clementine trouxe a garota de volta às suas memórias. Ela acenou com a cabeça e deu uma resposta afirmativa."
  },
  AvgDialog_18911_Content_23 = {
    Text = "Desde a primeira vez que vim ao lar dos pobres, ela tem sido minha pequena convidada."
  },
  AvgDialog_18911_Content_24 = {
    Text = "Compartilhar suas preocupações é uma maneira de curar a mente, e eu sou um ouvinte muito profissional."
  },
  AvgDialog_18911_Content_25 = {
    Text = "O olhar escrutinador varreu os rostos de todos e finalmente se fixou em você."
  },
  AvgDialog_18911_Content_26 = {
    Text = "Não, temos outros assuntos a tratar."
  },
  AvgDialog_18911_Content_27 = {
    Text = "Que pena. Se você mudar de ideia, você sempre será bem-vindo para se juntar a nós em nossa jornada de autodescoberta.\nVamos, Aigis."
  },
  AvgDialog_18911_Content_28 = {
    Text = "Aigis segurou a mão de Clementine e se afastou em silêncio."
  },
  AvgDialog_18911_Content_29 = {
    Text = "Aigis! Para onde você está indo?!"
  },
  AvgDialog_18911_Content_3 = {
    Text = "Ela subiu gentilmente a manga de Aigis, revelando costuras impressionantes que se destacavam em seu pulso justo."
  },
  AvgDialog_18911_Content_30 = {
    Text = "<Small:Desculpe... O Doutor Clementine pode me ajudar...>"
  },
  AvgDialog_18911_Content_31 = {
    Text = "Após a garota terminar de falar, ela deu um puxão firme na manga de Clementine de forma incomum. Com um impulso silencioso, suas figuras desapareceram pela porta do orfanato."
  },
  AvgDialog_18911_Content_32 = {
    Text = "Aigis... Eu me pergunto que segredo esta criança está escondendo."
  },
  AvgDialog_18911_Content_33 = {
    Text = "A névoa está se dissipando; vamos descansar por um tempo. Nós combinamos com Jenkin para explorar o porão mais tarde esta noite, então precisamos economizar um pouco de energia."
  },
  AvgDialog_18911_Content_4 = {
    Text = "Aigis, eles conduziram os mesmos experimentos em você.\nEles te amarraram e realizaram cirurgias à força, implantando alguns... <Yellow:objetos estranhos>, certo?"
  },
  AvgDialog_18911_Content_5 = {
    Text = "Eu, eu... naquele momento..."
  },
  AvgDialog_18911_Content_6 = {
    Text = "Hmm... este lugar é..."
  },
  AvgDialog_18911_Content_7 = {
    Text = "A intensa luz dificultou manter os olhos abertos. Aigis tentou controlar suas pálpebras, mas achou impossível."
  },
  AvgDialog_18911_Content_8 = {
    Text = "O metal frio imobilizou os músculos ao redor de seus olhos. Ela podia apenas assistir impotente enquanto o homem de manto branco se aproximava lentamente, segurando um escalpelo."
  },
  AvgDialog_18911_Content_9 = {
    Text = "Não, não, Senhorita Sarah, Senhorita Sarah!"
  },
  AvgDialog_18912_Content_1 = {
    Text = "A Chave de Prata piscou intensamente, a garota se levantou de repente, ouvindo vagamente um som de algo se rasgando"
  },
  AvgDialog_18912_Content_10 = {
    Text = "Você também desmorona fracamente no chão, lutando para suportar a dor pulsante em sua cabeça e a náusea que se segue."
  },
  AvgDialog_18912_Content_11 = {Text = "%player%!"},
  AvgDialog_18912_Content_12 = {
    Text = "Você sobrecarregou seu Poder espiritual? Agindo sempre de forma imprudente, você não conseguirá testemunhar o futuro de Mythag.\nSente-se e descanse. Sobrecarga do seu Poder espiritual afetará sua capacidade de percepção."
  },
  AvgDialog_18912_Content_13 = {
    Text = "Não se preocupe comigo, vá ver a Aigis"
  },
  AvgDialog_18912_Content_14 = {
    Text = "O som de líquido evaporando gradualmente enfraqueceu e logo desapareceu completamente.\nNo chão manchado de lodo negro, a garota sentou-se em silêncio, cobrindo um olho."
  },
  AvgDialog_18912_Content_15 = {
    Text = "Senhorita Ramona... e... %player%{Male=senhor,Female=senhora}.\nQue bom que vocês estão bem"
  },
  AvgDialog_18912_Content_16 = {Text = "Aigis..."},
  AvgDialog_18912_Content_17 = {
    Text = "Volte para Kadath conosco. Nós encontraremos uma maneira de curar seus olhos."
  },
  AvgDialog_18912_Content_18 = {
    Text = "Você estendeu a mão para Aigis."
  },
  AvgDialog_18912_Content_19 = {
    Text = "Aigis gentilmente, muito gentilmente, colocou a mão sobre a sua.\nAs pontas dos dedos dela estavam frias como pedra, mas naquele momento, pareciam tão quentes quanto o pôr do sol dourado do lado de fora da torre do relógio."
  },
  AvgDialog_18912_Content_2 = {
    Text = "A venda cai lentamente, cores ondulantes substituem a escuridão, e uma enorme íris pálida aparece abaixo dela, como se a observasse há muito tempo"
  },
  AvgDialog_18912_Content_20 = {
    Text = "Jenkin me disse que o que você está pesquisando, e o que os médicos estão experimentando conosco, é um fenômeno chamado \"Dissolução,\" que faz com que a existência de uma pessoa desapareça gradualmente e apague todas as memórias relacionadas."
  },
  AvgDialog_18912_Content_21 = {
    Text = "Se isso for verdade... eu tenho um desejo."
  },
  AvgDialog_18912_Content_22 = {
    Text = "Aigis fez uma pausa por um momento, reprimindo seus leves soluços."
  },
  AvgDialog_18912_Content_23 = {
    Text = "Espero que todos no orfanato possam esquecer de mim e da dor que causei a eles."
  },
  AvgDialog_18912_Content_24 = {
    Text = "Ela levantou a cabeça e encarou você com pupilas frias e da cor da pedra."
  },
  AvgDialog_18912_Content_25 = {
    Text = "Você perdeu sua capacidade de agir naquele momento."
  },
  AvgDialog_18912_Content_26 = {
    Text = "Aproveitando a oportunidade, ela virou-se e desapareceu no fim sombrio, então subiu até a plataforma fora da torre do relógio."
  },
  AvgDialog_18912_Content_27 = {
    Text = "Os raios dourados do sol poente atravessam o enorme mostrador transparente do relógio, banhando a garota em luz."
  },
  AvgDialog_18912_Content_28 = {
    Text = "Aigis virou de lado, colocando uma mão na face do relógio que não era lavada há muito tempo, espremendo os olhos sob a luz quente do sol."
  },
  AvgDialog_18912_Content_29 = {
    Text = "Hoje, eu posso ver o sol..."
  },
  AvgDialog_18912_Content_3 = {
    Text = "Você está... olhos? Estes são meus olhos?"
  },
  AvgDialog_18912_Content_30 = {
    Text = "Como animada pelo raro dia ensolarado, ela se levantou e cambaleou até um vidro mais limpo"
  },
  AvgDialog_18912_Content_31 = {
    Text = "A visão turva finalmente clareia. Ela observa as ruas, algumas familiares, outras estranhas, e ouve um sussurro"
  },
  AvgDialog_18912_Content_32 = {
    Text = "Veja, aquela voz disse que esta noite veremos um céu estrelado"
  },
  AvgDialog_18912_Content_33 = {
    Text = "No passado, sempre que podíamos ver o sol, Tiyog me trazia secretamente no escuro."
  },
  AvgDialog_18912_Content_34 = {
    Text = "A Miss Sarah nunca nos deixa vir aqui. Ela diz que é muito perigoso e que poderíamos nos machucar facilmente."
  },
  AvgDialog_18912_Content_35 = {
    Text = "Mas Tiyug não se importa. Toda noite, depois que a Srta. Sarah termina a ronda, ele me leva secretamente para cima no escuro"
  },
  AvgDialog_18912_Content_36 = {
    Text = "Ele é como Jenkin, esperto e corajoso, sempre conhece caminhos e mecanismos secretos"
  },
  AvgDialog_18912_Content_37 = {
    Text = "Basta ele estar conosco, a Srta. Sarah não nos descobrirá"
  },
  AvgDialog_18912_Content_38 = {
    Text = "Contanto que ele esteja conosco, esse lugar será sempre nossa base secreta"
  },
  AvgDialog_18912_Content_39 = {
    Text = "Ele me disse que eu preciso me conectar com as estrelas para fortalecer minha magia, mesmo que não possamos ver uma única estrela aqui."
  },
  AvgDialog_18912_Content_4 = {
    Text = "Não, não, isso não está certo! Esse sentimento é...! É o Sr. @2!"
  },
  AvgDialog_18912_Content_40 = {
    Text = "Ele foi o único que acreditou em mim na época. Ele acreditou que eu poderia ver aquelas coisas negras e me disse que era um presente de bruxa."
  },
  AvgDialog_18912_Content_41 = {
    Text = "Mas para me proteger, ele foi levado pelo Doutor..."
  },
  AvgDialog_18912_Content_42 = {
    Text = "Se eu fosse tão inteligente quanto ele e tão corajoso quanto Jenkin, eu teria descoberto a verdade até agora.  \nMas eu não sou uma bruxa; sou apenas um covarde, um monstro."
  },
  AvgDialog_18912_Content_43 = {
    Text = "Um... assassino."
  },
  AvgDialog_18912_Content_44 = {
    Text = "Aigis, você é uma boa criança. Você foi controlada; esses não são seus pecados."
  },
  AvgDialog_18912_Content_45 = {
    Text = "Você sabe quantas pessoas eu transformei em estátuas desatentas?"
  },
  AvgDialog_18912_Content_46 = {
    Text = "Estou apavorado, com medo do que estou me tornando"
  },
  AvgDialog_18912_Content_47 = {
    Text = "Até mesmo com medo do que me tornei."
  },
  AvgDialog_18912_Content_48 = {
    Text = "Mas nada disso importa mais."
  },
  AvgDialog_18912_Content_5 = {
    Text = "Você realmente pode me emprestar sua força? E quanto a você?"
  },
  AvgDialog_18912_Content_50 = {
    Text = "Eu não serei mais controlado, não ferirei mais ninguém, não deixarei mais amigos morrerem por minha causa"
  },
  AvgDialog_18912_Content_52 = {
    Text = "Droga, eles deveriam ter esperado na sala, mas agora ninguém sabe para onde foram."
  },
  AvgDialog_18912_Content_53 = {
    Text = "Aquilo é..."
  },
  AvgDialog_18912_Content_54 = {
    Text = "Aigis?! Aigis—!"
  },
  AvgDialog_18912_Content_55 = {
    Text = "De repente, a voz de Jenkins veio debaixo do campanário, ela gritou ansiosamente o nome de Aigis, levantando os braços para o céu"
  },
  AvgDialog_18912_Content_56 = {
    Text = "Um pássaro voa pelo céu noturno, desaparecendo na névoa espessa sem deixar traços."
  },
  AvgDialog_18912_Content_57 = {
    Text = "A fita amarrada no pulso soltou-se e voou ao vento, enquanto o pequeno corpo da garota desaparecia para sempre no céu noturno"
  },
  AvgDialog_18912_Content_58 = {
    Text = "O vestido branco vazio, junto com os fragmentos de papel quadrado, deslizava suavemente nas mãos de Jenkin"
  },
  AvgDialog_18912_Content_59 = {
    Text = "Nem um resquício de calor foi deixado"
  },
  AvgDialog_18912_Content_6 = {
    Text = "Obrigado... Mesmo que seja apenas por um momento, eu... tenho algo a dizer a eles."
  },
  AvgDialog_18912_Content_60 = {
    Text = "Ai... Aigis...?"
  },
  AvgDialog_18912_Content_61 = {
    Text = "Uma borboleta dourada é desenhada no papel, com suas bordas franzidas cuidadosamente achatadas. Ela ainda carrega um leve toque de doçura de doce."
  },
  AvgDialog_18912_Content_62 = {
    Text = "Como... como isso pode ser..."
  },
  AvgDialog_18912_Content_63 = {
    Text = "A fita vermelha cai na mão da menina junto com o papel de bala, acariciando suavemente seus dedos, como um consolo gentil"
  },
  AvgDialog_18912_Content_64 = {
    Text = "A menina piscou, e as lágrimas que embaçavam sua visão caíram silenciosamente no vermelho brilhante"
  },
  AvgDialog_18912_Content_65 = {Text = "Aigis..."},
  AvgDialog_18912_Content_7 = {
    Text = "Aigis, Aigis!"
  },
  AvgDialog_18912_Content_8 = {
    Text = "Aigis se mexeu, abrindo os olhos de verdade"
  },
  AvgDialog_18912_Content_9 = {
    Text = "Após um grito agudo, o corpo do monstro se dissolveu em lodo negro, desmoronando e subindo como poeira, tingindo as vigas de madeira"
  },
  AvgDialog_18913_Content_1 = {
    Text = "Você finalmente alcança a garota. Juntos, vocês contêm Aigis. Você estende a mão com urgência, agarra seu braço e pressiona a Chave Prata para completar o Link."
  },
  AvgDialog_18913_Content_10 = {
    Text = "Não, não, Aigis, acredite em nós. A Universidade Mythag enfrentou situações muito mais perigosas..."
  },
  AvgDialog_18913_Content_11 = {
    Text = "Sério? Ogier... Olhe para os corpos deles."
  },
  AvgDialog_18913_Content_12 = {
    Text = "Ogier se volta para o Guardião lutador e Ramona.\nOs corpos deles exudam suor em cores estranhas—não é suor, mas um xarope fino."
  },
  AvgDialog_18913_Content_13 = {
    Text = "Depois que a voz do Sr. Anderson desapareceu, as cores nos meus olhos e meu corpo gradualmente perderam o controle. Mesmo sem olhar, as pessoas ao meu redor lentamente se transformaram em pedras imóveis."
  },
  AvgDialog_18913_Content_14 = {
    Text = "Quanto mais eu posso aguentar? Um ano, um mês, um dia, uma hora?"
  },
  AvgDialog_18913_Content_15 = {
    Text = "Devo sempre permanecer escondido atrás de todos e esperar até que tudo o que resta esteja além da recuperação antes de agir?"
  },
  AvgDialog_18913_Content_16 = {
    Text = "Desta vez, quero ser tão corajoso quanto Tiyug, tão corajoso quanto Jenkin, tão corajoso quanto você."
  },
  AvgDialog_18913_Content_17 = {
    Text = "Ogier, você não é um cavaleiro? Então você deveria entender.\nMesmo que eu fique, inevitavelmente serei julgado como um criminoso pelos cavaleiros."
  },
  AvgDialog_18913_Content_18 = {
    Text = "Ogier ficou atordoado."
  },
  AvgDialog_18913_Content_19 = {
    Text = "Ogier, você uma vez disse... se eu posso ser redimido depende de mim."
  },
  AvgDialog_18913_Content_2 = {
    Text = "Por favor, não faça isso...\nEu sei..."
  },
  AvgDialog_18913_Content_20 = {
    Text = "Agora... você pode olhar para mim, para minha alma... Pode ser redimida?"
  },
  AvgDialog_18913_Content_21 = {
    Text = "Ogier fixou o olhar na única pupila normal de Aigis, hesitou por um momento e então soltou solenemente."
  },
  AvgDialog_18913_Content_22 = {
    Text = "Enquanto ele se movia, Aigis quebrou o vínculo de controle que você tinha."
  },
  AvgDialog_18913_Content_23 = {
    Text = "Em um instante, o corpo da menina inchou rapidamente, sua pele borbulhando com bolhas redondas de tamanhos variados. Em breve, ela bloqueou a escada atual e pressionou contra o teto alto."
  },
  AvgDialog_18913_Content_24 = {
    Text = "No som horrível de membros se torcendo, a voz da garota mal se mantém"
  },
  AvgDialog_18913_Content_25 = {
    Text = "<Shake:Corra...>"
  },
  AvgDialog_18913_Content_3 = {
    Text = "Você é puxado para a escuridão."
  },
  AvgDialog_18913_Content_4 = {
    Text = "A escuridão escaldante e ardente, como um xarope derretido, envolve você e o prende firmemente."
  },
  AvgDialog_18913_Content_5 = {
    Text = "<Italic:Velho Charlie tem um gato tigrado que ele adora muito...>"
  },
  AvgDialog_18913_Content_6 = {
    Text = "A dor começa na superfície, inicialmente como mordidas de formiga, então gradualmente se intensifica, como se incontáveis agulhas estivessem perfurando cada centímetro da sua pele—"
  },
  AvgDialog_18913_Content_7 = {
    Text = "A ligação se rompeu violentamente."
  },
  AvgDialog_18913_Content_8 = {
    Text = "Suportando a dor intensa, você segura a Chave de Prata com a mão esquerda, tremendo enquanto coloca a mão direita de volta no braço de Aigis."
  },
  AvgDialog_18913_Content_9 = {
    Text = "É tarde demais..."
  },
  AvgDialog_18914_Content_1 = {
    Text = "Esses monstros têm todas Marcas-D em seus corpos. E... parece que foram costuradas."
  },
  AvgDialog_18914_Content_2 = {
    Text = "Ramona tocou seu broche duas vezes."
  },
  AvgDialog_18914_Content_3 = {
    Text = "Erica, procure por \"D-Mark Costurado.\""
  },
  AvgDialog_18914_Content_4 = {
    Text = "Leitura da palavra-chave bem-sucedida, \"Dissolução Costurada,\" com um total de 37 incidentes relacionados.\nPalavras-chave do Evento: Atividade da Organização Maligna, <Blue:Os Escultores>."
  },
  AvgDialog_18914_Content_5 = {
    Text = "Os Escultores?"
  },
  AvgDialog_18914_Content_6 = {
    Text = "Eles são um grupo de lunáticos que se autodenominam \"Pigmalião\", obcecados por <Red:modificação biológica>... Tivemos vários conflitos com eles em cidades fora de Londinium."
  },
  AvgDialog_18914_Content_7 = {
    Text = "Eles entraram em contato com o Distrito Leste. Fique vigilante... Cuidado com aqueles <Yellow: segurando pequenas facas>."
  },
  AvgDialog_18915_Content_1 = {
    Text = "Ogier encarou vários médicos sem o menor medo, desviando rapidamente e neutralizando sua força, manobrando habilidosamente por um quarto de hora."
  },
  AvgDialog_18915_Content_10 = {
    Text = "Apresse-se e se prepare. Eu pessoalmente o levarei à clínica em breve... O pequeno Mike virá também; faz tempo que ele não faz um check-up."
  },
  AvgDialog_18915_Content_11 = {
    Text = "Espero que o Sr. Rogers esteja disposto a me dizer o seu endereço."
  },
  AvgDialog_18915_Content_12 = {
    Text = "Não! Por favor, senhorita Sarah, não queremos ser curados."
  },
  AvgDialog_18915_Content_13 = {
    Text = "Aigis empurrou a criança que estava protegendo. A criança olhou para todos com confusão e, por fim, seguiu as instruções de Aigis, correndo de volta para a sala do orfanato."
  },
  AvgDialog_18915_Content_14 = {
    Text = "Little Mac! Volte aqui!"
  },
  AvgDialog_18915_Content_15 = {
    Text = "Aigis puxou rapidamente a manga de Sarah, impedindo-a de correr atrás do já fora de vista Little Mike."
  },
  AvgDialog_18915_Content_16 = {
    Text = "Se... se tivermos que ir à clínica, deixe-me ir sozinho desta vez..."
  },
  AvgDialog_18915_Content_17 = {
    Text = "A Miss Sarah."
  },
  AvgDialog_18915_Content_18 = {
    Text = "Qual é o problema, Jovem Mestre Ashe?"
  },
  AvgDialog_18915_Content_19 = {
    Text = "Sarah imediatamente colocou outra máscara de adulação."
  },
  AvgDialog_18915_Content_2 = {Text = "Chega."},
  AvgDialog_18915_Content_20 = {
    Text = "Em nome de Ogier, o cavaleiro do Duque Grande, eu ordeno que você não force Aigis a \"curar.\""
  },
  AvgDialog_18915_Content_21 = {
    Text = "Cavaleiro, um cavaleiro?"
  },
  AvgDialog_18915_Content_22 = {
    Text = "Ogier percebeu que deixou escapar algo, e seu rosto instantaneamente ficou vermelho. Ele então continuou de maneira hesitante."
  },
  AvgDialog_18915_Content_23 = {
    Text = "S-Sim, o mais jovem dos Nobres sempre recebe o título de \"Cavaleiro.\"\nDe qualquer forma, preciso trazer Aigis e %player% de volta com a criada. Não torne as coisas mais difíceis para ela."
  },
  AvgDialog_18915_Content_24 = {
    Text = "Enquanto ele falava, Ogier agarrou a mão de Aigis e correu de volta para o quarto.\nA garota mantinha a cabeça baixa, parecendo soluçar suavemente."
  },
  AvgDialog_18915_Content_25 = {
    Text = "Tudo bem, a senhorita Sarah não deve alcançá-la."
  },
  AvgDialog_18915_Content_26 = {
    Text = "Aigis, você poderia me dizer por que se recusa a receber tratamento e não quer que os outros o recebam também?"
  },
  AvgDialog_18915_Content_27 = {
    Text = "Aigis apertou os lábios com força, um gemido reprimido escapou de sua garganta."
  },
  AvgDialog_18915_Content_28 = {
    Text = "Não se preocupe, eu sou realmente um cavaleiro. Um cavaleiro com certeza irá protegê-lo."
  },
  AvgDialog_18915_Content_29 = {Text = "Sério!"},
  AvgDialog_18915_Content_3 = {
    Text = "Como Aigis está relutante, não a pressionaremos. \n Levaremos os outros pacientes selecionados de volta à clínica para tratamento e os devolveremos após a terapia ser concluída."
  },
  AvgDialog_18915_Content_30 = {
    Text = "Ogier gaguejou, tentando parecer solene e sério.\nAigis olhou para ele, hesitou por um momento, então explodiu em risos."
  },
  AvgDialog_18915_Content_31 = {
    Text = "Não me engane. Li em livros que os cavaleiros sempre protegem as princesas.\nBasta olhar para mim. Eu ao menos pareço uma princesa?"
  },
  AvgDialog_18915_Content_32 = {
    Text = "Aigis tocou suavemente o remendo em sua saia e falou suavemente."
  },
  AvgDialog_18915_Content_33 = {
    Text = "Não é assim. O livro está errado.\nCavaleiros não apenas protegem princesas; eles também protegem plebeus e todos os outros."
  },
  AvgDialog_18915_Content_34 = {
    Text = "Aigis olhou Ogier de cima a baixo."
  },
  AvgDialog_18915_Content_35 = {
    Text = "Você é realmente um cavaleiro?"
  },
  AvgDialog_18915_Content_36 = {
    Text = "Ogier deu uma palmadinha no peito, a manopla tilintando contra ele, fazendo sua expressão se contorcer por um breve momento."
  },
  AvgDialog_18915_Content_37 = {
    Text = "Genuíno! Pessoalmente nomeado pela família real, nasci para proteger desde então."
  },
  AvgDialog_18915_Content_38 = {
    Text = "Eu o invejo, tão corajoso... até mesmo defendendo alguém que você acabou de conhecer."
  },
  AvgDialog_18915_Content_39 = {
    Text = "Que pena, não sou um cavaleiro, nem uma princesa, nem mesmo um cidadão comum, apenas um Miserável..."
  },
  AvgDialog_18915_Content_4 = {
    Text = "Bom dia, Srta. Sarah."
  },
  AvgDialog_18915_Content_40 = {
    Text = "Seu tom suave foi engolido de volta."
  },
  AvgDialog_18915_Content_41 = {
    Text = "Ogier, você disse que os cavaleiros protegeriam a todos..."
  },
  AvgDialog_18915_Content_42 = {
    Text = "E quanto aos criminosos? Mesmo... assassinos?"
  },
  AvgDialog_18915_Content_43 = {
    Text = "Ogier ficou ereto, resoluto e inabalável."
  },
  AvgDialog_18915_Content_44 = {
    Text = "Cavaleiros não protegem criminosos.\nPorque os cavaleiros precisam punir criminosos e proteger as pessoas deles."
  },
  AvgDialog_18915_Content_45 = {
    Text = "Certamente..."
  },
  AvgDialog_18915_Content_46 = {
    Text = "Sem entender o significado por trás do suspiro de Aigis, Ogier continuou falando."
  },
  AvgDialog_18915_Content_47 = {
    Text = "Isso é porque os cavaleiros não são onipotentes."
  },
  AvgDialog_18915_Content_48 = {
    Text = "Depois da sanção... o cavaleiro entregará o penitente ao sacerdote."
  },
  AvgDialog_18915_Content_49 = {
    Text = "O sacerdote misericordioso ajuda cada penitente... mas se suas almas podem, em última análise, ser redimidas depende deles mesmos."
  },
  AvgDialog_18915_Content_5 = {
    Text = "Vick deu um último olhar para Aigis e depois saiu com os outros."
  },
  AvgDialog_18915_Content_50 = {
    Text = "Depende de... si mesmo..."
  },
  AvgDialog_18915_Content_51 = {
    Text = "Sim, ainda há espaço para voltar."
  },
  AvgDialog_18915_Content_52 = {
    Text = "Tudo isso está relacionado a você@4..."
  },
  AvgDialog_18915_Content_53 = {
    Text = "Aigis hesitou, como se estivesse saboreando aquelas palavras.\nDepois de um momento, ela começou a falar lentamente e com alguma dificuldade."
  },
  AvgDialog_18915_Content_54 = {
    Text = "Eu confio em você, Ogier. Estou disposto a apostar uma vez mais em você.\nEntão, eu vou te contar... a verdade sobre aquelas curas."
  },
  AvgDialog_18915_Content_6 = {
    Text = "Sarah despediu-se do doutor com um sorriso forçado, mas quando se virou para Aigis, sua expressão se tornou séria."
  },
  AvgDialog_18915_Content_7 = {
    Text = "Aigis, por que você está sendo tão desobediente?"
  },
  AvgDialog_18915_Content_8 = {
    Text = "A Miss Sarah, eu..."
  },
  AvgDialog_18915_Content_9 = {
    Text = "Eles só vieram por causa do Sr. Rogers. Agora você os afastou. Como eu vou explicar isso ao Sr. Rogers?"
  },
  AvgDialog_18916_Content_1 = {
    Text = "O monstro se transforma silenciosamente em fumaça negra."
  },
  AvgDialog_18916_Content_10 = {
    Text = "Se até eu sou considerado um monstro, então como você chamaria esse cara?"
  },
  AvgDialog_18916_Content_11 = {
    Text = "Ela acaricia suavemente o queixo da estátua em resposta, depois se vira levemente e toca as costas da sua mão."
  },
  AvgDialog_18916_Content_12 = {
    Text = "Você está preso na ilusão do mar."
  },
  AvgDialog_18916_Content_13 = {
    Text = "Uma grande cidade construída com pedras verdes e monstruosas, desafiando completamente a geometria euclidiana. Os relevos ornamentados, embora sujos, sob a luz refratada do mar, parecem deslumbrantemente belos e estranhamente hipnotizantes."
  },
  AvgDialog_18916_Content_14 = {
    Text = "Uma sensação sufocante gradualmente envolve e consome você. O precioso ar é espremido de seus pulmões e flui pela sua boca."
  },
  AvgDialog_18916_Content_15 = {
    Text = "—Então, alguém te agarra, quebrando o fantasma."
  },
  AvgDialog_18916_Content_16 = {Text = "Guardião!"},
  AvgDialog_18916_Content_17 = {
    Text = "Não se preocupe, é apenas um fantasma."
  },
  AvgDialog_18916_Content_18 = {
    Text = "O que você está tentando me dizer me mostrando isso?"
  },
  AvgDialog_18916_Content_19 = {
    Text = "Sanga baixou os olhos e não respondeu."
  },
  AvgDialog_18916_Content_2 = {Text = "Ufa—"},
  AvgDialog_18916_Content_20 = {
    Text = "Memórias surgem, relembrando os ensinamentos da Classe de Preparação Despertar."
  },
  AvgDialog_18916_Content_21 = {
    Text = "<Yellow:Aequor>, <Yellow:Caro>, e <Yellow:Ultra> são as classificações predominantes dos Reinos dos Despertadores na academia. Além disso, há alguns reinos que foram menos estudados devido à falta de sujeitos, como <Yellow:Arcano> e <Yellow:Aether>..."
  },
  AvgDialog_18916_Content_22 = {
    Text = "Reinos geralmente têm isolamento natural de poder, mas alguns possuem a habilidade de se adaptar a outros reinos, como o <Yellow:Reino do Caos>."
  },
  AvgDialog_18916_Content_23 = {
    Text = "A voz sufocada de Jenkin interrompeu suas lembranças. Ela corria entre as esculturas de açúcar no porão, parecendo um pequeno rato indefeso."
  },
  AvgDialog_18916_Content_24 = {
    Text = "Eu os vi. Conferi todos os seus rostos."
  },
  AvgDialog_18916_Content_25 = {
    Text = "Não há irmã dentro.\n<Big:Onde diabos está minha irmã? Diga-me!>"
  },
  AvgDialog_18916_Content_26 = {
    Text = "Ramona encerrou a comunicação com a escola, sua voz tão fria quanto gelo interrompendo suas memórias."
  },
  AvgDialog_18916_Content_27 = {
    Text = "Sem dúvida, você é um Despertador não registrado. De acordo com <Yellow:as disposições relevantes do Tratado Mystia>, notificaremos o <Blue:Comitê do Tratado Mystia> para contê-lo."
  },
  AvgDialog_18916_Content_28 = {
    Text = "Antes que o Comitê chegue, revele o paradeiro de todas as pessoas desaparecidas, incluindo <Blue:Investigador Mythag Sean Anderson> e <Blue:Teceiro Mason>, assim como sua relação com <Blue:Os Escultores>."
  },
  AvgDialog_18916_Content_29 = {
    Text = "Aguarde, Ramona, Jenkin."
  },
  AvgDialog_18916_Content_3 = {
    Text = "O fantasma exalou suavemente, dispersando o pó de açúcar que restava na faca de esculpir."
  },
  AvgDialog_18916_Content_30 = {
    Text = "Você ignora as perguntas deles e se volta para Sanga, que exibe um sorriso cúmplice."
  },
  AvgDialog_18916_Content_31 = {
    Text = "O único que transformou essas pessoas nisso... não foi você, certo?"
  },
  AvgDialog_18916_Content_32 = {Text = "%player%?"},
  AvgDialog_18916_Content_33 = {
    Text = "Você me mostrou uma ilusão, uma cena composta pelo mundo subaquático e carvões de coral... Esse é o poder de Aequor e sonhos, o poder do <Yellow:Reino das Profundezas>."
  },
  AvgDialog_18916_Content_34 = {
    Text = "Você olha ao redor para as figuras de doces grotescas e contorcidas, respira fundo, e a doçura avassaladora ataca seus sentidos mais uma vez."
  },
  AvgDialog_18916_Content_35 = {
    Text = "Esses corpos foram derretidos em calda e depois solidificados em estátuas...\nEssa habilidade é mais parecida com o trabalho de um <Yellow:Caro Realm Awakener>, que muitas vezes é mais habilidoso em alterar carne."
  },
  AvgDialog_18916_Content_36 = {
    Text = "Você pode estar envolvido, mas o verdadeiro culpado é outra pessoa."
  },
  AvgDialog_18916_Content_37 = {
    Text = "É verdadeiramente delicioso comunicar-se com pessoas inteligentes."
  },
  AvgDialog_18916_Content_38 = {
    Text = "De fato, ouvi de um amigo que há materiais únicos aqui. Só quero pegar alguns emprestados para moldar meu \"Deus\"."
  },
  AvgDialog_18916_Content_39 = {
    Text = "Sanga fala de forma casual, começando a guardar facas de escultura na bolsa a seus pés."
  },
  AvgDialog_18916_Content_4 = {
    Text = "Feito.\nNo entanto, o resultado ainda é menos do que ideal desta vez."
  },
  AvgDialog_18916_Content_40 = {
    Text = "Vamos, não vamos ao Comitê de Revisão de Acordos?\nVocê também pode me ajudar a embalar essas estátuas?"
  },
  AvgDialog_18916_Content_41 = {
    Text = "Há mais..."
  },
  AvgDialog_18916_Content_42 = {
    Text = "Ela bateu no assento de pedra abaixo dela."
  },
  AvgDialog_18916_Content_43 = {
    Text = "Estou tendo dificuldades para me mover. Você tem a autoridade para enviar um carro?"
  },
  AvgDialog_18916_Content_44 = {
    Text = "Você segurou o pulso dela."
  },
  AvgDialog_18916_Content_45 = {
    Text = "Quem os transformou nisso?"
  },
  AvgDialog_18916_Content_46 = {
    Text = "Você está me perguntando?"
  },
  AvgDialog_18916_Content_47 = {
    Text = "Sanga soltou um suspiro suave."
  },
  AvgDialog_18916_Content_48 = {
    Text = "Por mais gentil que eu seja, deixe-me apontá-lo na direção certa.\nVá perguntar ao reitor e aqueles Doutores."
  },
  AvgDialog_18916_Content_49 = {
    Text = "Sarah! Eu sabia que era aquela mulher traiçoeira por trás disso!\nOlhe para mim desta vez, eu... eu..."
  },
  AvgDialog_18916_Content_5 = {
    Text = "Ela colocou a faca de esculpir para baixo e se virou parcialmente para você."
  },
  AvgDialog_18916_Content_50 = {
    Text = "Jenkin foi feroz no começo, mas depois tornou-se desanimado."
  },
  AvgDialog_18916_Content_51 = {
    Text = "Você dá um passo à frente e lhe dá um tapinha no ombro."
  },
  AvgDialog_18916_Content_52 = {
    Text = "Não é necessariamente uma coisa ruim que ainda não encontramos a pessoa. Enquanto...\nhouver ainda uma chama de esperança."
  },
  AvgDialog_18916_Content_53 = {
    Text = "Não há mais necessidade de se preocupar em alertar o inimigo.\nRamona, vá informar ao Comitê para intervir. Jenkin, chame Sarah."
  },
  AvgDialog_18916_Content_54 = {
    Text = "Leve o livro de registros dela."
  },
  AvgDialog_18916_Content_6 = {
    Text = "Eu me pergunto, o que traz seus convidados não convidados aqui? Qual é o seu interesse comigo?"
  },
  AvgDialog_18916_Content_7 = {
    Text = "Você... você monstro!"
  },
  AvgDialog_18916_Content_8 = {
    Text = "Monstro? Eu prefiro que você me chame de \"Sanga.\""
  },
  AvgDialog_18916_Content_9 = {
    Text = "Sanga limpou a poeira da superfície da escultura de açúcar, permanecendo indiferente."
  },
  AvgDialog_18917_Content_1 = {
    Text = "Senhorita 24, por que você nos atacou no momento em que começamos?"
  },
  AvgDialog_18917_Content_2 = {
    Text = "Ataque? Não, eu não luto..."
  },
  AvgDialog_18917_Content_3 = {
    Text = "Entendi! Você já conheceu \"ela\"?"
  },
  AvgDialog_18917_Content_4 = {
    Text = "Embora pareça absurdo, aquela não era eu de verdade—"
  },
  AvgDialog_18917_Content_5 = {
    Text = "Não, ela na verdade é eu também, apenas a parte mais anormal..."
  },
  AvgDialog_18917_Content_6 = {
    Text = "Não, isso também está errado. Na verdade, há outro eu... Há vários de mim..."
  },
  AvgDialog_18917_Content_7 = {
    Text = "Que má sorte! Finalmente encontrei alguém que pode falar, apenas para descobrir que é um lunático."
  },
  AvgDialog_18918_Content_1 = {
    Text = "Senhorita 24, há uma pergunta que tem me incomodado..."
  },
  AvgDialog_18918_Content_2 = {
    Text = "Como você saiu da escultura de cera?"
  },
  AvgDialog_18918_Content_3 = {
    Text = "Eu... sinto muito, estou um pouco confuso. Ultimamente, tenho estado em um estado de letargia."
  },
  AvgDialog_18918_Content_4 = {
    Text = "Eu fui transformado em uma escultura de cera antes, não sei quanto tempo estive aqui..."
  },
  AvgDialog_18918_Content_5 = {
    Text = "De repente, parece que posso me mover e respirar. Então —"
  },
  AvgDialog_18918_Content_6 = {
    Text = "Então você saiu da escultura de cera como um fantasma feminino."
  },
  AvgDialog_18918_Content_7 = {
    Text = "Sim, sim..."
  },
  AvgDialog_18919_Content_1 = {Text = "Olhos..."},
  AvgDialog_18919_Content_2 = {
    Text = "Eu sinto que os olhos daquela escultura de cera parecem familiares..."
  },
  AvgDialog_18920_Content_1 = {
    Text = "Ahhh, de-donde vocês todos vieram?!"
  },
  AvgDialog_18920_Content_2 = {
    Text = "Achoo! Que fedo... Os mortos poderiam parar de usar perfume, por favor?"
  },
  AvgDialog_18920_Content_3 = {
    Text = "Você... bom, muito bom..."
  },
  AvgDialog_18920_Content_4 = {
    Text = "Deixa eu te ensinar o que é a etiqueta adequada de verdade!"
  },
  AvgDialog_18921_Content_1 = {
    Text = "4:40, Museu de Cera Rogers"
  },
  AvgDialog_18921_Content_10 = {
    Text = "Pare. Você não vê? A ferida dela absorveu D-Slime demais..."
  },
  AvgDialog_18921_Content_11 = {
    Text = "Em breve, ela estará junto deste museu de cera..."
  },
  AvgDialog_18921_Content_12 = {
    Text = "Droga... Azar, apenas consegui pegar um pouco daquele Limo d em mim."
  },
  AvgDialog_18921_Content_13 = {
    Text = "Jenkin tremia enquanto estendia a mão, revelando a chave em sua palma que poderia abrir a Passagem."
  },
  AvgDialog_18921_Content_14 = {
    Text = "Venha aqui, Irmã."
  },
  AvgDialog_18921_Content_15 = {
    Text = "Não se mova, Jenkin! Você está ferido, eu vou tirá-lo daqui..."
  },
  AvgDialog_18921_Content_16 = {
    Text = "Venha aqui, Irmã."
  },
  AvgDialog_18921_Content_17 = {
    Text = "Então espalhe suas mãos... Sim, assim mesmo—"
  },
  AvgDialog_18921_Content_18 = {
    Text = "24 tremeu ao abrir a mão, e uma chave caiu em sua palma, ainda quente."
  },
  AvgDialog_18921_Content_19 = {
    Text = "A chave é impecável. Fiz o meu melhor..."
  },
  AvgDialog_18921_Content_2 = {
    Text = "A espera parecia interminável até que um som de movimento esforçado veio de cima."
  },
  AvgDialog_18921_Content_20 = {
    Text = "Que má sorte. Tenho apenas treze anos e ainda não vivi o suficiente..."
  },
  AvgDialog_18921_Content_21 = {
    Text = "Jenkin fungou novamente e lhe deu um sorriso radiante."
  },
  AvgDialog_18921_Content_22 = {
    Text = "Irmã, nem tivemos a chance de conversar direito, e agora temos que nos separar novamente."
  },
  AvgDialog_18921_Content_23 = {
    Text = "Lembra do que me disse naquela vez?"
  },
  AvgDialog_18921_Content_24 = {
    Text = "Você disse... Eu nunca estive sozinho, eu tenho você, eu tenho vocês"
  },
  AvgDialog_18921_Content_25 = {
    Text = "Desde aquele momento, eu soube..."
  },
  AvgDialog_18921_Content_26 = {
    Text = "Eu faço qualquer coisa por vocês"
  },
  AvgDialog_18921_Content_27 = {Text = "Jenkin..."},
  AvgDialog_18921_Content_28 = {
    Text = "Obrigado, obrigado a vocês... Tenho um último pedido"
  },
  AvgDialog_18921_Content_29 = {
    Text = "Não esqueça de mim, ok?"
  },
  AvgDialog_18921_Content_3 = {
    Text = "O som gradualmente se torna mais claro e mais alto..."
  },
  AvgDialog_18921_Content_30 = {
    Text = "A gosma preto-escura irrompeu de trás da menina, congelando seu sorriso radiante em seu último momento."
  },
  AvgDialog_18921_Content_31 = {
    Text = "Ela adora fazer caretas engraçadas, fala com pequenos animais e sempre discute com a Srta. Sarah..."
  },
  AvgDialog_18921_Content_32 = {
    Text = "Todos desapareceram silenciosamente junto com este museu de cera."
  },
  AvgDialog_18921_Content_4 = {
    Text = "Depois de um tempo desconhecido, um braço fino e pequeno se estendeu de dentro."
  },
  AvgDialog_18921_Content_5 = {Text = "Entendi..."},
  AvgDialog_18921_Content_6 = {
    Text = "Jenkin, saia agora! Está prestes a desabar..."
  },
  AvgDialog_18921_Content_7 = {
    Text = "Desculpe. Eu posso... não conseguir me juntar a vocês."
  },
  AvgDialog_18921_Content_8 = {Text = "Chirp..."},
  AvgDialog_18921_Content_9 = {
    Text = "Jenkin, rapidamente me dê a sua mão."
  },
  AvgDialog_18922_Content_1 = {
    Text = "12:25, Museu de Cera Rogers\nEstúdio"
  },
  AvgDialog_18922_Content_10 = {
    Text = "Fale, Brown. O que exatamente você encontrou lá embaixo?"
  },
  AvgDialog_18922_Content_11 = {
    Text = "Chirp, ugh... chirp chirp..."
  },
  AvgDialog_18922_Content_12 = {
    Text = "Hmm, o que vem a seguir?"
  },
  AvgDialog_18922_Content_13 = {
    Text = "Chirp chirp chirp..."
  },
  AvgDialog_18922_Content_14 = {
    Text = "Eu vejo. Obrigado pelo seu trabalho duro, Marrom."
  },
  AvgDialog_18922_Content_15 = {
    Text = "Brown disse que estava muito escuro lá embaixo, e ele não conseguia ver nada claramente. Ele só conseguiu trazer isso de volta."
  },
  AvgDialog_18922_Content_16 = {
    Text = "Jenkin abriu a pequena pata de Marrom e puxou de dentro uma pequena bolsa de documentos."
  },
  AvgDialog_18922_Content_17 = {
    Text = "Deixa eu ver o que há dentro... algumas moedinhas, botões, e..."
  },
  AvgDialog_18922_Content_18 = {Text = "Uma carta?"},
  AvgDialog_18922_Content_19 = {
    Text = "Oh, deixe-me ver o que está escrito aqui."
  },
  AvgDialog_18922_Content_2 = {Text = "Chiado!"},
  AvgDialog_18922_Content_20 = {
    Text = "Ei, não leve minhas coisas assim!"
  },
  AvgDialog_18922_Content_21 = {
    Text = "A mulher desdobrou a carta em sua mão. Continha algumas palavras e frases rabiscadas apressadamente, aparentemente escritas às pressas."
  },
  AvgDialog_18922_Content_22 = {
    Text = "Jenkins:\n\nAcho que não vou viver muito tempo@2\n\nEles estão transformando pessoas em estátuas de cera, e logo será minha vez@4\n@2Eu já conversei com o Sr. Davis@1\n……Você pode trabalhar na fábrica dele depois.\nO Sr. Davis é um pouco severo, mas todos os dias no almoço há sopa de ervilhas e pão preto.\n<Yellow:Lembre-se de não discutir com ele.>\n\nAlém disso, todo o dinheiro está guardado em@4"
  },
  AvgDialog_18922_Content_23 = {
    Text = "A mulher hesitou ao chegar ao final da carta."
  },
  AvgDialog_18922_Content_24 = {
    Text = "Seu rosto exibia uma expressão peculiar, como se estivesse perdida em pensamentos profundos, mas sua mente parecia ter vagado para longe."
  },
  AvgDialog_18922_Content_25 = {
    Text = "Por que você parou de ler? Ainda faltam algumas linhas!"
  },
  AvgDialog_18922_Content_26 = {
    Text = "A mulher não responde. Ela apenas coloca suavemente a carta em sua mão."
  },
  AvgDialog_18922_Content_27 = {
    Text = "Você desdobra a carta, apenas para encontrar algumas saudações habituais e uma assinatura."
  },
  AvgDialog_18922_Content_28 = {
    Text = "\"...Mesmo agora, ainda sinto falta dos dias em que nos banhávamos juntos ao sol no Parque Wood.\""
  },
  AvgDialog_18922_Content_29 = {
    Text = "\"Amor, Mason.\""
  },
  AvgDialog_18922_Content_3 = {
    Text = "Brown, você finalmente voltou!"
  },
  AvgDialog_18922_Content_30 = {
    Text = "Não é um fantasma... Minha irmã realmente existe..."
  },
  AvgDialog_18922_Content_31 = {
    Text = "Eu, eu não vou trabalhar para o Davis!"
  },
  AvgDialog_18922_Content_32 = {
    Text = "A Senhorita Mason está realmente trancada aqui. Ela deve ter corrido grandes riscos para escrever esta carta."
  },
  AvgDialog_18922_Content_33 = {
    Text = "Ela nunca perdeu a esperança na vida, nem se esqueceu de você."
  },
  AvgDialog_18922_Content_34 = {
    Text = "Mas agora, eu nem consigo me lembrar de como ela é..."
  },
  AvgDialog_18922_Content_35 = {
    Text = "Estou realmente inútil... Desculpe, irmã..."
  },
  AvgDialog_18922_Content_36 = {
    Text = "Uma mão se estendeu, cobrindo gentilmente a mão de Jenkin."
  },
  AvgDialog_18922_Content_37 = {
    Text = "Esta é uma mão cheia de cicatrizes. Banhada pela luz da lua, as veias e feridas azuladas-pretas são inconfundíveis."
  },
  AvgDialog_18922_Content_38 = {
    Text = "Não chore, e não se desculpe."
  },
  AvgDialog_18922_Content_39 = {
    Text = "Isto é o que você me avisou."
  },
  AvgDialog_18922_Content_4 = {
    Text = "Brown deitou-se fraco nos braços de Jenkin, seu nariz enrugando, e começou a chorar."
  },
  AvgDialog_18922_Content_40 = {Text = "24..."},
  AvgDialog_18922_Content_41 = {
    Text = "Pelo menos você ainda está vivo. Enquanto há vida, ainda há esperança."
  },
  AvgDialog_18922_Content_42 = {
    Text = "Acredito que sua irmã também teria desejado isso."
  },
  AvgDialog_18922_Content_43 = {Text = "..."},
  AvgDialog_18922_Content_44 = {
    Text = "Eu... eu não estava chorando."
  },
  AvgDialog_18922_Content_45 = {
    Text = "Você é bastante normal quando não está perdendo a cabeça."
  },
  AvgDialog_18922_Content_46 = {
    Text = "A garota respondeu em um tom sombrio, com uma leve qualidade nasal quase imperceptível."
  },
  AvgDialog_18922_Content_47 = {
    Text = "De qualquer forma, você finalmente encontrou vestígios de Mason."
  },
  AvgDialog_18922_Content_48 = {
    Text = "Isto é uma boa notícia rara para esta noite."
  },
  AvgDialog_18922_Content_5 = {
    Text = "Squeak... Squeak—!!"
  },
  AvgDialog_18922_Content_6 = {Text = "Hmm..."},
  AvgDialog_18922_Content_7 = {
    Text = "Brown disse que o cheiro lá embaixo é insuportável, e está se sentindo extremamente desconfortável."
  },
  AvgDialog_18922_Content_8 = {
    Text = "Oh, ratos também vomitam? Isso é algo novo."
  },
  AvgDialog_18922_Content_9 = {
    Text = "Brown não é um rato comum."
  },
  AvgDialog_18923_Content_1 = {
    Text = "Você tentou de tudo, mas a portinhola permanece intocada."
  },
  AvgDialog_18923_Content_10 = {
    Text = "Nossa operação de investigação foi exposta. Agora, ambas as saídas restantes do museu de cera estão guardadas."
  },
  AvgDialog_18923_Content_11 = {
    Text = "Eu encontrei uma <Yellow:porta que leva para fora> nas proximidades. É especial, trancada por dentro."
  },
  AvgDialog_18923_Content_12 = {
    Text = "Rogers deve ter mexido nisso; não pode ser aberto por meios ordinários."
  },
  AvgDialog_18923_Content_13 = {
    Text = "Você precisa ir ao <Yellow:Escritório do Curador>, ahem, e pegar um <Yellow:chave>..."
  },
  AvgDialog_18923_Content_14 = {
    Text = "Desta vez, encontrei várias coisa. Contas, relatórios, contratos... o suficiente para manter Rogers na prisão pelo resto da vida."
  },
  AvgDialog_18923_Content_15 = {
    Text = "Apenas para o caso, vou entregar a você primeiro, então—"
  },
  AvgDialog_18923_Content_16 = {Text = "Ahh—!!"},
  AvgDialog_18923_Content_17 = {
    Text = "A mulher de branco que estava aqui agora... ela desapareceu..."
  },
  AvgDialog_18923_Content_18 = {
    Text = "Você olha para onde a mulher estava antes. Agora está vazio, com apenas as cortinas brancas tremulando ao vento."
  },
  AvgDialog_18923_Content_19 = {
    Text = "O que você quer dizer com \"desapareceu\"...?"
  },
  AvgDialog_18923_Content_2 = {
    Text = "Droga, não consigo abrir..."
  },
  AvgDialog_18923_Content_20 = {
    Text = "Eu... eu não sei. Ela estava aqui..."
  },
  AvgDialog_18923_Content_21 = {
    Text = "Jenkin correu com raiva até 24 e agarrou sua mão."
  },
  AvgDialog_18923_Content_22 = {
    Text = "É você, não é...? Eu sei que é você. Eu ouvi os dois cochichando ali mais cedo, e agora vocês estão fingindo não se conhecer?"
  },
  AvgDialog_18923_Content_23 = {
    Text = "Não, não... Senha Jenkin, ouça-me! A polícia não precisa de evidências para condenar um criminoso...?"
  },
  AvgDialog_18923_Content_24 = {
    Text = "Todos nós estávamos olhando para aquele sênior agora há pouco, exceto você e ela do outro lado.\nVocê está completamente cego e surdo?"
  },
  AvgDialog_18923_Content_25 = {
    Text = "Mesmo que ela seja um pouco excêntrica, e se ela realmente for minha irmã..."
  },
  AvgDialog_18923_Content_26 = {
    Text = "Eu vou perguntar novamente: para onde ela foi?"
  },
  AvgDialog_18923_Content_27 = {
    Text = "Na luta, 24 caiu no chão, seu cabelo longo foi empurrado para o lado."
  },
  AvgDialog_18923_Content_28 = {
    Text = "O que é isso... 0, 2, 4?"
  },
  AvgDialog_18923_Content_29 = {
    Text = "No pescoço justo da garota, há um código preto proeminente \"024\"."
  },
  AvgDialog_18923_Content_3 = {
    Text = "Vá de volta."
  },
  AvgDialog_18923_Content_30 = {
    Text = "Não faz muito tempo, você viu padrões semelhantes em outro lugar."
  },
  AvgDialog_18923_Content_31 = {
    Text = "Você vê isso? Eles gravam um código em cada espécime bem-sucedido.\nO nosso é <Blue:um código único>..."
  },
  AvgDialog_18923_Content_32 = {
    Text = "Isso é... a Associação dos Escultores..."
  },
  AvgDialog_18923_Content_33 = {Text = "?!"},
  AvgDialog_18923_Content_34 = {
    Text = "24 agarra inutilmente seu pescoço, seu rosto extremamente pálido."
  },
  AvgDialog_18923_Content_35 = {
    Text = "Como era de se esperar... Este cara é um mentiroso! Para pensar que eu até..."
  },
  AvgDialog_18923_Content_36 = {
    Text = "Entendo, todos nós ficamos distraídos pela \"loucura\" da Senhorita 24"
  },
  AvgDialog_18923_Content_37 = {
    Text = "Qualquer um que está tão familiarizado com este museu de cera e pode se mover livremente dentro dele não é certamente uma vítima comum."
  },
  AvgDialog_18923_Content_38 = {
    Text = "Não, não..."
  },
  AvgDialog_18923_Content_39 = {
    Text = "24 sentou-se no chão, arranhando mecanicamente o código no pescoço até que se tornasse uma bagunça ensanguentada."
  },
  AvgDialog_18923_Content_4 = {Text = "O que...?"},
  AvgDialog_18923_Content_40 = {
    Text = "<Shake:Não é o que você pensa, não é o que você pensa...>"
  },
  AvgDialog_18923_Content_5 = {
    Text = "Eu disse, \"Volte.\""
  },
  AvgDialog_18923_Content_6 = {
    Text = "Você está brincando? Nós mal conseguimos nos infiltrar aqui!"
  },
  AvgDialog_18923_Content_7 = {
    Text = "Há muitos... monstros lá embaixo, mais do que você pode lidar. A Boneca não te avisou?"
