  AvgDialog_18923_Content_8 = {
    Text = "E quanto a você? Não podemos simplesmente abandoná-lo."
  },
  AvgDialog_18923_Content_9 = {
    Text = "Há uma fenda de nível B, e levará um longo tempo para lidar com isso. Eu não posso sair daqui.\nEscute, eu direi isso apenas uma vez—"
  },
  AvgDialog_18924_Content_1 = {
    Text = "Shh... Há alguém à frente. Esconda-se rapidamente."
  },
  AvgDialog_18924_Content_2 = {
    Text = "Que noite de lua linda~"
  },
  AvgDialog_18924_Content_3 = {
    Text = "Quando eu estava vivo, em noites como esta, eu costumava sentar na varanda de mármore e servir-me um copo de vinho..."
  },
  AvgDialog_18924_Content_4 = {
    Text = "Em vez de ser uma criada no museu de cera como agora, choram, choram..."
