  },
  AvgDialog_18955_Content_26 = {Text = "..."},
  AvgDialog_18955_Content_27 = {
    Text = "Senhor Rogers, eu sei que você com certeza vai me odiar, mas —"
  },
  AvgDialog_18955_Content_28 = {Text = "Splash!!"},
  AvgDialog_18955_Content_29 = {
    Text = "A chibata se enrolou no braço de Rogers, arrancando-o.\nSangue jorrou, manchando o casaco de Rogers de vermelho."
  },
  AvgDialog_18955_Content_3 = {
