  AvgDialog_18957_Content_7 = {
    Text = "Extra, extra! Segundo fontes, <Blue:Vampire Siblings> foram recentemente avistados em Londinium!!"
  },
  AvgDialog_18957_Content_8 = {
    Text = "Gaste apenas 5 Pensh para descobrir o escândalo chocante da família Cavendish! 23 pessoas em situação de rua já foram vítimas..."
  },
  AvgDialog_18957_Content_9 = {
    Text = "Encontrei-os! Eles estão logo à frente. Desta vez, não podemos deixá-los escapar!"
