  },
  AvgDialog_21761_Content_14 = {
    Text = "Fechar os olhos não é um efeito de loop, lembre-se de usar 2 para terminar"
  },
  AvgDialog_21761_Content_15 = {
    Text = "A seguir, um flash de luz vermelha, 1"
  },
  AvgDialog_21761_Content_17 = {
