  },
  AvgDialog_65482_Content_55 = {
    Text = "Memórias sumindo, rostos sendo apagados"
  },
  AvgDialog_65482_Content_56 = {
    Text = "As histórias passadas foram exiladas às bordas da memória, e você se deslocou de protagonista para espectador."
  },
  AvgDialog_65482_Content_57 = {
    Text = "No início, o coração parecia cortado por facas, depois ficou entorpecido"
