  AvgDialog_65482_Content_61 = {
    Text = "Ao sair daqui, você não terá mais relação com eles"
  },
  AvgDialog_65482_Content_62 = {
    Text = "...Eu entendo, Tchêkhoma-Daath"
  },
  AvgDialog_65482_Content_63 = {
    Text = "Você levantou a cabeça. Neste mundo infinito de bolhas, você dialoga com aquele Deus do vazio"
  },
  AvgDialog_65482_Content_64 = {
    Text = "Por favor, diga-me seu nome"
  },
  AvgDialog_65482_Content_65 = {
    Text = "Sou %player%. Sou o guardião. Eu sou... o olho cego"
  },
  AvgDialog_65482_Content_66 = {
    Text = "Sua missão está completa. Saia desta dimensão, Tchêkhoma-Daath"
  },
  AvgDialog_65482_Content_67 = {
    Text = "Eu vou impedi-Lo"
  },
  AvgDialog_65482_Content_68 = {
    Text = "Eu irei parar... a mim mesmo."
  },
  AvgDialog_65482_Content_7 = {
    Text = "O cavaleiro existe para proteger todos, Ogier pode aguentar!"
  },
  AvgDialog_65482_Content_8 = {
    Text = "Estou aterrorizada com o que me tornarei. Mas isso já não importa"
  },
  AvgDialog_65482_Content_9 = {
    Text = "Eu não serei mais controlado, não ferirei mais ninguém, não deixarei mais amigos morrerem por minha causa"
  },
  AvgDialog_65948_Content_1 = {
    Text = "Lá lá lá lá"
  },
  AvgDialog_65948_Content_2 = {
    Text = "Sua voz foi distorcida por uma sensação familiar, transformando-se em murmúrios indistinguíveis"
  },
  AvgDialog_65948_Content_3 = {Text = "...O que?"},
  AvgDialog_65948_Content_4 = {
    Text = "Uma vez que o olhar de @3 realmente desça, tudo se encaminhará para o fim. Antes da chegada do épico, você pode retirar o colar de Mythag a qualquer momento e vir para os meus braços"
  },
  AvgDialog_65948_Content_5 = {
    Text = "Ela ignorou sua reação, continuando a fazer um convite doentio, caloroso e sincero, como um amante sussurrando palavras de amor em seu ouvido"
  },
  AvgDialog_65948_Content_6 = {
    Text = "Estarei te observando daqui."
  },
  AvgDialog_65948_Content_7 = {
    Text = "Logo, Dor será separada de você e terá mais restrições. Ela não reage, dócil como uma boneca, mas seus olhos sempre te seguem, como se penetrassem sua alma"
  },
  AvgDialog_65948_Content_8 = {
    Text = "Como esperando um reencontro ansiado"
  },
  AvgDialog_66597_Content_1 = {
    Text = "Mythag prometeu que lutaria comigo... lutaria até o fim deste planeta"
  },
  AvgDialog_66597_Content_10 = {
    Text = "Eu não serei mais controlado, não ferirei mais ninguém, não deixarei mais amigos morrerem por minha causa"
  },
  AvgDialog_66597_Content_11 = {
    Text = "Lembra do que me disse naquela vez?"
  },
  AvgDialog_66597_Content_12 = {
    Text = "Você disse... Eu nunca estive sozinho, eu tenho você, eu tenho vocês"
  },
  AvgDialog_66597_Content_13 = {
    Text = "Desde aquele momento, eu soube..."
  },
  AvgDialog_66597_Content_14 = {
    Text = "Eu faço qualquer coisa por vocês"
  },
  AvgDialog_66597_Content_15 = {
    Text = "Obrigado, obrigado a vocês... Tenho um último pedido"
  },
  AvgDialog_66597_Content_16 = {
    Text = "Não esqueça de mim, ok?"
  },
  AvgDialog_66597_Content_17 = {
    Text = "Não esqueça de mim, ok?"
  },
  AvgDialog_66597_Content_18 = {
    Text = "Menina se levanta relutante, olhos fixos no seu peito.\nVocê olha para baixo, chave de prata brilha"
  },
  AvgDialog_66597_Content_19 = {
    Text = "Qual é o seu nome?"
  },
  AvgDialog_66597_Content_2 = {
    Text = "Se soubesse, nunca teria feito um acordo com vocês"
  },
  AvgDialog_66597_Content_20 = {
    Text = "<Blue:Lily>..."
  },
  AvgDialog_66597_Content_21 = {
    Text = "Lily gosta disso? Quer tocar?"
  },
  AvgDialog_66597_Content_22 = {
    Text = "...Tá bom!"
  },
  AvgDialog_66597_Content_23 = {
    Text = "Lily tocou cautelosamente a ponta da chave.\n\nNão sabe se é sua ilusão, mas a chave pareceu piscar no momento do contato"
  },
  AvgDialog_66597_Content_24 = {Text = "Uau..."},
  AvgDialog_66597_Content_25 = {
    Text = "Lily de repente abraçou você apertado.\n\nSeu coração ficou macio, e você não pôde evitar acariciar sua cabeça"
  },
  AvgDialog_66597_Content_26 = {
    Text = "Lily de repente abraçou você apertado.\n\nSeu coração ficou macio, e você não pôde evitar acariciar sua cabeça"
  },
  AvgDialog_66597_Content_27 = {
    Text = "Eu consegui... Eu realmente consegui."
  },
  AvgDialog_66597_Content_28 = {
    Text = "Eu... perfurei... Não nascerá..."
  },
  AvgDialog_66597_Content_29 = {
    Text = "Agora, eu posso..."
  },
  AvgDialog_66597_Content_3 = {
    Text = "Deixe-me testemunhar por mim mesmo o valor deste prodígio no qual Misaq aposta o seu futuro!"
  },
  AvgDialog_66597_Content_30 = {
    Text = "A mão dela segurando a faca cai fracamente, enquanto um líquido espesso, viscoso e carmesim escuro escorre pela lâmina, pingando entre seus dedos até o mar."
  },
  AvgDialog_66597_Content_31 = {
    Text = "O sangue escorria rapidamente do corpo, deixando Murphy pálido, mas emanando uma estranha vitalidade"
  },
  AvgDialog_66597_Content_32 = {
    Text = "O sangue escorria rapidamente do corpo, deixando Murphy pálido, mas emanando uma estranha vitalidade"
  },
  AvgDialog_66597_Content_33 = {
    Text = "Mesmo na escuridão, mesmo com luz fraca, o espírito indomável deles pode mudar o futuro predestinado"
  },
  AvgDialog_66597_Content_34 = {
    Text = "Agora, já tenho uma nova resposta"
  },
  AvgDialog_66597_Content_35 = {
    Text = "Então, seja generoso e empreste seu herdeiro para mim, ok?"
  },
  AvgDialog_66597_Content_36 = {
    Text = "Confio nesta pessoa e entrego a chama a {Male=ele,Female=ela}"
  },
  AvgDialog_66597_Content_37 = {
    Text = "Esta semente um dia vai crescer em uma árvore gigante"
  },
  AvgDialog_66597_Content_38 = {
    Text = "Como no dia em que a primeira árvore mãe nasceu"
  },
  AvgDialog_66597_Content_39 = {Text = "..."},
  AvgDialog_66597_Content_4 = {
    Text = "Deixe-me testemunhar por mim mesmo o valor deste prodígio no qual Misaq aposta o seu futuro!"
  },
  AvgDialog_66597_Content_40 = {
    Text = "Esta é a última semente, deixo-a em você"
  },
  AvgDialog_66597_Content_41 = {
    Text = "Antes que espalhe meu sangue pela terra, você, não pode morrer"
  },
  AvgDialog_66597_Content_42 = {
    Text = "Lembre-se de mim para sempre, não me esqueça"
  },
  AvgDialog_66597_Content_43 = {
    Text = "Maré violenta"
  },
  AvgDialog_66597_Content_44 = {
    Text = "Esse abraço quente te empurrou"
  },
  AvgDialog_66597_Content_45 = {
    Text = "Você vê ela sendo levada pela correnteza para as profundezas do rio"
  },
  AvgDialog_66597_Content_46 = {
    Text = "Você vê ela sendo levada pela correnteza para as profundezas do rio"
  },
  AvgDialog_66597_Content_47 = {
    Text = "Agora? Aqui fora?"
  },
  AvgDialog_66597_Content_48 = {
    Text = "Talvez seja um pouco mais cedo do que o planejado, mas não deve importar, certo?"
  },
  AvgDialog_66597_Content_49 = {
    Text = "Além disso, estive ansiosa por este dia há mais de um ano."
  },
  AvgDialog_66597_Content_5 = {
    Text = "Está tudo bem, Guardião"
  },
  AvgDialog_66597_Content_50 = {
    Text = "Gotas de chuva escorrem para dentro das suas luvas, umedecendo as pontas dos seus dedos. Uma corrente tênue penetra o tecido, fluindo secretamente entre a sua pele e a dela."
  },
  AvgDialog_66597_Content_51 = {
    Text = "Emoções inexplicáveis percorrem os seus nervos—alegria, excitação, inquietação e..."
  },
  AvgDialog_66597_Content_52 = {
    Text = "...<Yellow:Esperança>."
  },
  AvgDialog_66597_Content_53 = {
    Text = "Que calor... a conexão é perfeita. O seu espírito e a sua força vital nunca brilharam tanto."
  },
  AvgDialog_66597_Content_54 = {
    Text = "Não desista facilmente, Guardião do <Yellow: Único Mundo>.\n\nContamos com você para investigar e registrar todas as histórias apagadas"
  },
  AvgDialog_66597_Content_55 = {
    Text = "A preocupação nos olhos dela desvanece enquanto Ramona oferece um meio sorriso reconfortante."
  },
  AvgDialog_66597_Content_56 = {
    Text = "O som da chuva fina preenche o mundo."
  },
  AvgDialog_66597_Content_57 = {
    Text = "O som da chuva fina preenche o mundo."
  },
  AvgDialog_66597_Content_58 = {
    Text = "Ra... Ramona"
  },
  AvgDialog_66597_Content_59 = {
    Text = "Memórias sumindo, rostos sendo apagados"
  },
  AvgDialog_66597_Content_6 = {
    Text = "O cavaleiro existe para proteger todos, Ogier pode aguentar!"
  },
  AvgDialog_66597_Content_60 = {
    Text = "No início, o coração parecia cortado por facas, depois ficou entorpecido"
  },
  AvgDialog_66597_Content_61 = {
    Text = "Você se vê deixando o chão e indo ao coração das estrelas"
  },
  AvgDialog_66597_Content_62 = {
    Text = "As coisas ao seu redor estavam desaparecendo, até sumirem por completo"
  },
  AvgDialog_66597_Content_63 = {
    Text = "Não há Ramona. Nem Guardião"
  },
  AvgDialog_66597_Content_64 = {
    Text = "Ao sair daqui, você não terá mais relação com eles"
  },
  AvgDialog_66597_Content_65 = {
    Text = "...Eu entendo, Tchêkhoma-Daath"
  },
  AvgDialog_66597_Content_66 = {
    Text = "Você levantou a cabeça. Neste mundo infinito de bolhas, você dialoga com aquele Deus do vazio"
  },
  AvgDialog_66597_Content_67 = {
    Text = "Por favor, diga-me seu nome"
  },
  AvgDialog_66597_Content_68 = {
    Text = "Sou %player%. Sou o guardião. Eu sou... o olho cego"
  },
  AvgDialog_66597_Content_69 = {
    Text = "Sua missão está completa. Saia desta dimensão, Tchêkhoma-Daath"
  },
  AvgDialog_66597_Content_7 = {
    Text = "O cavaleiro existe para proteger todos, Ogier pode aguentar!"
  },
  AvgDialog_66597_Content_70 = {
    Text = "Eu vou impedi-Lo"
  },
  AvgDialog_66597_Content_71 = {
    Text = "Eu irei parar... a mim mesmo."
  },
  AvgDialog_66597_Content_8 = {
    Text = "Estou aterrorizada com o que me tornarei. Mas isso já não importa"
  },
  AvgDialog_66597_Content_9 = {
    Text = "Eu não serei mais controlado, não ferirei mais ninguém, não deixarei mais amigos morrerem por minha causa"
  },
  AvgDialog_66598_Content_1 = {
    Text = "Batalha. Batalha"
  },
  AvgDialog_66598_Content_10 = {
    Text = "O som da flauta começou. Grave, confuso, tranquilo"
  },
  AvgDialog_66598_Content_11 = {
    Text = "O Criador insensato olhou para você com interesse, como se observasse um inseto lutando até a morte"
  },
  AvgDialog_66598_Content_12 = {
    Text = "Você pegou novamente a chave de prata"
  },
  AvgDialog_66598_Content_13 = {
    Text = "Guardião... não!"
  },
  AvgDialog_66598_Content_14 = {
    Text = "De quem é o grito? Você não lembra, e nem importa"
  },
  AvgDialog_66598_Content_15 = {
    Text = "O corpo já está exausto, a mente também se esgotou. Mas você se lembra, você deve lutar"
  },
  AvgDialog_66598_Content_16 = {
    Text = "Se for pra morrer... eu vou com você!"
  },
  AvgDialog_66598_Content_17 = {
    Text = "Uma gota de água brilhante cai em sua mente, criando ondulações em sua árida dimensão espiritual"
  },
  AvgDialog_66598_Content_18 = {
    Text = "A gota de água se expandiu gradualmente, tomando a forma de uma figura ilusória em sua mente. Você olha para ela.\nUm nome distante ecoa em sua mente"
  },
  AvgDialog_66598_Content_19 = {
    Text = "Ra... mona?"
  },
  AvgDialog_66598_Content_2 = {
    Text = "Uma batalha de esquecer tudo. Uma batalha de generosa morte"
  },
  AvgDialog_66598_Content_20 = {
    Text = "Você disse, guardião. Disse que nunca nos deixaria"
  },
  AvgDialog_66598_Content_21 = {
    Text = "Eu já cortei a conexão, Ramona"
  },
  AvgDialog_66598_Content_22 = {
    Text = "Ao se conectar comigo, você perderá o controle"
  },
  AvgDialog_66598_Content_23 = {
    Text = "Ficar comigo, você vai morrer"
  },
  AvgDialog_66598_Content_24 = {
    Text = "O que há a temer na morte?"
  },
  AvgDialog_66598_Content_25 = {
    Text = "A segunda gota de água caiu em sua mente"
  },
  AvgDialog_66598_Content_26 = {
    Text = "Lotan... você não está na piscina negra, por que você"
  },
  AvgDialog_66598_Content_27 = {
    Text = "Porque somos seu despertador. Você pode cortar o link, mas não pode cortar o poder de nos conectar a você"
  },
  AvgDialog_66598_Content_28 = {
    Text = "Onde quer que esteja, seu despertador sempre estará ao seu lado.\nO link é a sua marca eterna com o despertador. Guardião"
  },
  AvgDialog_66598_Content_29 = {
    Text = "Professor Dôl, você também...\n mas se vocês se conectarem a mim, vocês"
  },
  AvgDialog_66598_Content_3 = {
    Text = "Os olhos quebram, olhos renascem. Caindo e levantando repetidamente"
  },
  AvgDialog_66598_Content_30 = {
    Text = "Mesmo que não fique na frente do senhor, deixe-me ao seu lado!"
  },
  AvgDialog_66598_Content_31 = {
    Text = "Isso! Nos entregar à piscina negra e correr? Nem pensar!"
  },
  AvgDialog_66598_Content_32 = {
    Text = "Lily vai ajudar %player%!"
  },
  AvgDialog_66598_Content_33 = {
    Text = "Meu povo será protegido por mim"
  },
  AvgDialog_66598_Content_34 = {Text = "..."},
  AvgDialog_66598_Content_35 = {
    Text = "Cada vez mais gotas de água se estendem do lago negro e caem na sua dimensão espiritual"
  },
  AvgDialog_66598_Content_36 = {
    Text = "Inúmeras imagens das entidades despertas surgem em sua mente. Elas sorriem, se enfurecem, desprezam, lamentam"
  },
  AvgDialog_66598_Content_37 = {
    Text = "Suas histórias se tornam um rio prateado, fluindo silenciosamente em sua mente, nutrindo cada veia e nervo"
  },
  AvgDialog_66598_Content_38 = {
    Text = "Aceite isso, Guardião."
  },
  AvgDialog_66598_Content_39 = {
    Text = "Deixe-nos ficar com você."
  },
  AvgDialog_66598_Content_4 = {
    Text = "O que é essa enorme criação? Você já meio que esqueceu"
  },
  AvgDialog_66598_Content_40 = {
    Text = "Você olhou para trás. A consciência louca já havia levado os despertadores à beira do colapso"
  },
  AvgDialog_66598_Content_41 = {
    Text = "O corpo de Ramona treme involuntariamente, mas ela te observa fixamente, sem qualquer intenção de romper a ligação"
  },
  AvgDialog_66598_Content_42 = {
    Text = "Obrigado..."
  },
  AvgDialog_66598_Content_43 = {
    Text = "Há coisas piores que a loucura e a morte"
  },
  AvgDialog_66598_Content_44 = {
    Text = "Você é assim, e eles também"
  },
  AvgDialog_66598_Content_45 = {
    Text = "Obrigado... é bom conhecê-los"
  },
  AvgDialog_66598_Content_46 = {
    Text = "Você sorri e se vira."
  },
  AvgDialog_66598_Content_47 = {
    Text = "Eu prometi, e vou cumprir"
  },
  AvgDialog_66598_Content_48 = {
    Text = "Você ergue a cabeça e encara o criador e destruidor deste universo, o colosso invencível"
  },
  AvgDialog_66598_Content_49 = {
    Text = "Você percebe a força que flui das conexões. É a vida deles, é um grilhão inquebrável, e é uma obsessão compartilhada"
  },
  AvgDialog_66598_Content_5 = {
    Text = "Quem são essas pessoas atrás de você? Você esqueceu"
  },
  AvgDialog_66598_Content_50 = {
    Text = "A primeira vez que você se encontra e se conecta com cada despertador, cada palavra que trocaram, cada experiência que tiveram, passa pela sua mente"
  },
  AvgDialog_66598_Content_51 = {
    Text = "Essas belas coisas, nunca seriam destruídas"
  },
  AvgDialog_66598_Content_52 = {
    Text = "Você sabe o que realmente quer proteger.\nVocê sabe que irá protegê-los"
  },
  AvgDialog_66598_Content_53 = {
    Text = "Você sorri e levanta a chave de prata para a criação à sua frente.\nComo um vaga-lume enfrentando o sol com orgulho"
  },
  AvgDialog_66598_Content_54 = {
    Text = "Que a chave prateada ilumine o caminho!!"
  },
  AvgDialog_66598_Content_56 = {Text = "..."},
  AvgDialog_66598_Content_57 = {Text = "..."},
  AvgDialog_66598_Content_58 = {
    Text = "Não sei quanto tempo se passou. A luz prateada que iluminava todo o reino de Leo foi lentamente se apagando"
  },
  AvgDialog_66598_Content_59 = {Text = "..."},
  AvgDialog_66598_Content_6 = {
    Text = "A força mental já se esgotou, o corpo e a mente foram gravemente corroídos. Você não se importa"
  },
  AvgDialog_66598_Content_60 = {
    Text = "Guardião?!!"
  },
  AvgDialog_66598_Content_61 = {
    Text = "Ela se aproximou da porta. Você não estava mais lá"
  },
  AvgDialog_66598_Content_62 = {
    Text = "Ela ergueu a cabeça e viu uma porta completamente fechada e, em frente a essa enorme porta, a chave de prata flutuava silenciosamente"
  },
  AvgDialog_66598_Content_63 = {
    Text = "Código, K-0617... isso... isso é"
  },
  AvgDialog_66598_Content_64 = {
    Text = "Pela autoridade do 6º Diretor da Misaq, <Blue:Oliver Elsie>, eu confiro a você a Chave de prata K-0617."
  },
  AvgDialog_66598_Content_65 = {
    Text = "De agora em diante, você se ergue como Guardião entre a miríade de estudantes e acadêmicos da Misaq."
  },
  AvgDialog_66598_Content_66 = {
    Text = "Ramona se aproxima e segura a chave de prata com cuidado"
  },
  AvgDialog_66598_Content_67 = {Text = "Por que"},
  AvgDialog_66598_Content_68 = {Text = "Ramona..."},
  AvgDialog_66598_Content_69 = {
    Text = "Código do Guardião... Primeira regra"
  },
  AvgDialog_66598_Content_7 = {
    Text = "Você só se lembra da batalha. Mecânica, insensível e sem emoção"
  },
  AvgDialog_66598_Content_70 = {
    Text = "Chave de prata... Símbolo do Guardião... Não pode ser perdida, não pode ser descartada"
  },
  AvgDialog_66598_Content_71 = {
    Text = "Eu ensinei a ele... por que... por que ele não lembra?"
  },
  AvgDialog_66598_Content_72 = {
    Text = "O olhar de Tohu Vabo foi afastado da porta. Ele voltou a dormir"
  },
  AvgDialog_66598_Content_73 = {
    Text = "O Guardião, junto com Ele, caiu em uma ilusão inconsciente, vigiando, por nós, por este mundo, a porta selada de Tohuwabohu"
  },
  AvgDialog_66598_Content_74 = {
    Text = "A consciência e a vida de {Male=ele,Female=ela} já não existem mais...\n{Male=ele,Female=ela} está morto, Ramona"
  },
  AvgDialog_66598_Content_75 = {
    Text = "Morte? Como ele morreria... ele nos deixaria?"
  },
  AvgDialog_66598_Content_76 = {
    Text = "Tantas pessoas... tantos eventos... {Male=ele,Female=ela} como poderia desistir?"
  },
  AvgDialog_66598_Content_77 = {
    Text = "Como {Male=ele,Female=ela} pode desistir"
  },
  AvgDialog_66598_Content_78 = {
    Text = "As gotas de lágrimas molham as luvas, molham a chave de prata"
  },
  AvgDialog_66598_Content_79 = {
    Text = "Lágrimas caem na piscina negra, formando ondas claras"
  },
  AvgDialog_66598_Content_8 = {
    Text = "Você só se lembra do que disse, proteger essas pessoas atrás de você"
  },
  AvgDialog_66598_Content_80 = {
    Text = "Sobre as ondas, atrás da porta, uma figura ilusória dorme pacificamente envolta por asas"
  },
  AvgDialog_66598_Content_81 = {
    Text = "No rosto de %hisorher% há um sorriso puro, como um bebê nascido durante a noite, vendo o sol pela primeira vez."
  },
  AvgDialog_66598_Content_9 = {Text = "...@3..."},
  AvgDialog_66599_Content_1 = {Text = "Ding—"},
  AvgDialog_66599_Content_10 = {Text = "@2@3..."},
  AvgDialog_66599_Content_11 = {Text = "..."},
  AvgDialog_66599_Content_13 = {
    Text = "Uma esfera de luz aparece diante de você. Segunda, terceira"
  },
  AvgDialog_66599_Content_14 = {
    Text = "Incontáveis esferas de luz, cores brilham e fluem na superfície como flores complexas, desabrochando e murchando uma a uma no espaço escuro"
  },
  AvgDialog_66599_Content_15 = {
    Text = "Nas bolhas que nascem e morrem, você vê o conceito de cores dançando e circulando diante de você"
  },
  AvgDialog_66599_Content_16 = {
    Text = "Você vê todas as palavras se acumulando em um ponto, uma épica infinita"
  },
  AvgDialog_66599_Content_17 = {
    Text = "Você vê imagens do passado, presente e futuro. Vê todos os tempos e espaços de existência e destruição"
  },
  AvgDialog_66599_Content_18 = {
    Text = "Parece que uma luz está irradiando de dentro de você, atravessando seus órgãos e mente"
  },
  AvgDialog_66599_Content_19 = {
    Text = "Corpo intelectual... Chekhama... Da'at"
  },
  AvgDialog_66599_Content_2 = {
    Text = "Uma vibração no seu peito. A Chave de Prata parece ser convocada e flutua na frente de você"
  },
  AvgDialog_66599_Content_20 = {
    Text = "Por favor, diga-me como posso derrotar a Vontade Suprema. Como posso protegê-los"
  },
  AvgDialog_66599_Content_21 = {
    Text = "Chicoma-Daath. Esse nome ecoa claramente nesse espaço"
  },
  AvgDialog_66599_Content_22 = {
    Text = "Uma bolha flutua diante de você. Você estende um dedo e a toca reverentemente"
  },
  AvgDialog_66599_Content_23 = {Text = "Estalo—"},
  AvgDialog_66599_Content_24 = {
    Text = "A bolha à sua frente se desfez em inúmeros pontos de luz. Os pontos de luz cercam você, como um véu, cobrindo-o suavemente"
  },
  AvgDialog_66599_Content_25 = {
    Text = "Ele é o começo e o fim... Ele é tudo"
  },
  AvgDialog_66599_Content_26 = {
    Text = "Vontade suprema, invencível"
  },
  AvgDialog_66599_Content_27 = {
    Text = "Uma voz distante veio do interior de cada bolha, ecoando na sua mente"
  },
  AvgDialog_66599_Content_28 = {
    Text = "Não... Vida, civilização, emoções... Nosso mundo não pode ser destruído assim!"
  },
  AvgDialog_66599_Content_29 = {
    Text = "Olhe para mim. Ouça-me. Fragmentos do olho cego. Consciência do olho cego. Lado sombrio do olho cego"
  },
  AvgDialog_66599_Content_3 = {
    Text = "Uma intensa luz prata irradiava da chave de prata e, em seguida, desapareceu"
  },
  AvgDialog_66599_Content_30 = {
    Text = "Consciência, lado obscuro... o que quer dizer?"
  },
  AvgDialog_66599_Content_31 = {
    Text = "Você ergue a cabeça e olha para as incontáveis bolhas ilusórias"
  },
  AvgDialog_66599_Content_32 = {
    Text = "Feche as portas antes que Ele acorde. Que a vontade suprema durma novamente. Seu mundo será temporariamente liberado"
  },
  AvgDialog_66599_Content_33 = {
    Text = "Quando você recupera o poder do aspecto das trevas, você ganha a capacidade de fechar as portas"
  },
  AvgDialog_66599_Content_34 = {
    Text = "Seu mundo, quem você se importa... Não podem suportar o poder dos fragmentos da vontade suprema"
  },
  AvgDialog_66599_Content_35 = {
    Text = "Você abandonará tudo. Guardará eternamente as portas. Morrerá, passando infinitamente no escuro inconsciente"
  },
  AvgDialog_66599_Content_36 = {
    Text = "Fragmentos do olho cego, isso... é o preço que você pagará"
  },
  AvgDialog_66599_Content_37 = {
    Text = "Na bolha à sua frente, você viu seu próprio rosto"
  },
  AvgDialog_66599_Content_38 = {
    Text = "Suor frio escorre daquele rosto. Ele treme de frio e medo"
  },
  AvgDialog_66599_Content_39 = {
    Text = "Você imagina aquela morte incompleta e longa, que levaria toda a vida a uma eterna solidão enlouquecedora"
  },
  AvgDialog_66599_Content_4 = {
    Text = "Você ouve um rugido baixo. Duas portas infinitas e intangíveis se abrem lentamente"
  },
  AvgDialog_66599_Content_40 = {
    Text = "Não há outro jeito?... Eu prometi a Ramona, eu prometi a eles"
  },
  AvgDialog_66599_Content_41 = {
    Text = "Seus olhos estão abertos. Resista ao seu poder, feche a porta e faça-o cair no sono novamente. É o único caminho"
  },
  AvgDialog_66599_Content_42 = {Text = "Escolha"},
  AvgDialog_66599_Content_43 = {
    Text = "O tempo pareceu parar. Você finalmente viu claramente as cores ilusórias ao seu redor"
  },
  AvgDialog_66599_Content_44 = {
    Text = "Nele, tudo que você lembra está fluindo"
  },
  AvgDialog_66599_Content_45 = {
    Text = "Primeiro contato com a chave de prata... primeira ligação ao despertador... primeiro fechamento da fenda de dissolução"
  },
  AvgDialog_66599_Content_46 = {
    Text = "Inúmeras cenas, inúmeros rostos, olhando para você"
  },
  AvgDialog_66599_Content_47 = {
    Text = "Você respira fundo e levanta a cabeça"
  },
  AvgDialog_66599_Content_48 = {
    Text = "Eu... aceito"
  },
  AvgDialog_66599_Content_49 = {
    Text = "Despedaça-se com todas as tuas lembranças, fragmento do Olho Cego.\nAo teu lado, permanecerão apenas corpos sem consciência, criados pelo poder e memória"
  },
  AvgDialog_66599_Content_5 = {
    Text = "Um brilho negro surge da porta, envolvendo você"
  },
  AvgDialog_66599_Content_50 = {
    Text = "Corte você mesmo o link com o despertador.  \nDeixe seu corpo retornar solitariamente ao puro caos e escuridão"
  },
  AvgDialog_66599_Content_51 = {
    Text = "Depois disso, ajudarei você a absorver os poderes das três essências"
  },
  AvgDialog_66599_Content_52 = {
    Text = "Vou ajudá-lo a se tornar um deus"
  },
  AvgDialog_66599_Content_6 = {
    Text = "Porta, gêmeos, sombras... Tudo ao seu redor desapareceu"
  },
  AvgDialog_66599_Content_7 = {
    Text = "Um brilho negro te leva para uma nova dimensão"
  },
  AvgDialog_66599_Content_8 = {
    Text = "Tudo desaparece desta dimensão. Só resta a pura escuridão"
  },
  AvgDialog_66599_Content_9 = {Text = "..."},
  AvgDialog_66601_Content_1 = {
    Text = "A vitória ou derrota na batalha não importam mais...\nEu sou o vencedor final, Guardião"
  },
  AvgDialog_66601_Content_10 = {
    Text = "As paredes estão desaparecendo. Os degraus estão desaparecendo. Até mesmo a piscina negra está desaparecendo"
  },
  AvgDialog_66601_Content_11 = {
    Text = "Você se esqueceu da cor da parede. Você se esqueceu da posição dos degraus. Sob aquele olhar, tudo se transformou em eterna vacuidade, nem mesmo o conceito em branco foi deixado para trás"
  },
  AvgDialog_66601_Content_12 = {
    Text = "Um olhar vagante, finalmente se fixa em você"
  },
  AvgDialog_66601_Content_13 = {
    Text = "Um som nauseante e úmido de dilaceração se ergue no ar. Enormes patas de aranha irrompem pelos corpos dos oficiais e dos transeuntes, espirrando sangue espesso com cheiro de ferro por todo você."
  },
  AvgDialog_66601_Content_14 = {
    Text = "[Exibição CG de Tawil]"
  },
  AvgDialog_66601_Content_15 = {
    Text = "Abra os olhos, Guardião."
  },
  AvgDialog_66601_Content_16 = {
    Text = "Aquela luz não é ofuscante, apenas calorosa, como um monte de penas prateadas empilhadas na sua visão"
  },
  AvgDialog_66601_Content_17 = {
    Text = "À sua frente está o rosto de Tawil.  \nComo no primeiro dia, sagrado, suave, intocável"
  },
  AvgDialog_66601_Content_18 = {
    Text = "Suas seis asas se abriram, bloqueando o olhar que destrói tudo. Uma luz sagrada que desafia a razão brilha atrás dele. Cada batida é uma mudança de dimensão, desviando o olhar destrutivo para um ponto singular inexistente"
  },
  AvgDialog_66601_Content_19 = {
    Text = "Líquidos negros escorrem por suas asas, arranhando cada centímetro da inviolável carne divina. Em cada momento fugaz, sua forma murcha até os ossos e sua aparência é liquefeita pela Dissolução repetidas vezes — apenas para ser reconstituída mais uma vez."
  },
  AvgDialog_66601_Content_2 = {
    Text = "Um som nauseante e úmido de dilaceração se ergue no ar. Enormes patas de aranha irrompem pelos corpos dos oficiais e dos transeuntes, espirrando sangue espesso com cheiro de ferro por todo você."
  },
  AvgDialog_66601_Content_20 = {
    Text = "——Ele lutava contra aquele olhar, contra a vontade destrutiva e inabalável"
  },
  AvgDialog_66601_Content_21 = {
    Text = "Nesta guerra de pureza e impureza, eles se confrontam a cada instante. Cada embate faz o rosto de Tawil se tornar um pouco mais fraco"
  },
  AvgDialog_66601_Content_22 = {
    Text = "Seu olhar ficará temporariamente na dimensão onde estou escondido. Você ainda tem tempo, Guardião do Segredo"
  },
  AvgDialog_66601_Content_23 = {
    Text = "Tawil, você...!"
  },
  AvgDialog_66601_Content_24 = {
    Text = "Ouça-me, guardião"
  },
  AvgDialog_66601_Content_25 = {
    Text = "Adentre a porta. Encontre a resposta. Lembre-se de tudo sobre você"
  },
  AvgDialog_66601_Content_26 = {
    Text = "Ela olha para você. Seu rosto sereno e sagrado emana uma autoridade incontestável"
  },
  AvgDialog_66601_Content_27 = {
    Text = "Você nos derrotou. Você conseguiu"
  },
  AvgDialog_66601_Content_28 = {
    Text = "Agora, vá salvá-los"
  },
  AvgDialog_66601_Content_29 = {
    Text = "Você fará isso de novo. Certo, guardião?"
  },
  AvgDialog_66601_Content_3 = {
    Text = "Boneca Derretida·Doll ficou com um sorriso satisfeito, as mãos ligeiramente afastadas como um buquê devotadamente apodrecido."
  },
  AvgDialog_66601_Content_4 = {
    Text = "Ela se ajoelhou lentamente, e a grande porta atrás dela estava completamente aberta"
  },
  AvgDialog_66601_Content_5 = {Text = "@2..."},
  AvgDialog_66601_Content_6 = {
    Text = "Isto é... Não!..."
  },
  AvgDialog_66601_Content_7 = {
    Text = "Isto é... Não!..."
  },
  AvgDialog_66601_Content_8 = {
    Text = "Vazio, liquefato, pó, desapareça. Você conhece bem o processo de corrosão"
  },
  AvgDialog_66601_Content_9 = {
    Text = "Sob aquele olhar, todo seu conhecimento sobre corrosão é inútil"
  },
  AvgDialog_6770_Content_1 = {Text = "Sombra"},
  AvgDialog_6770_Content_10 = {
    Text = "Sem necessidade de gentilezas. O que você disse que viu agora há pouco?"
  },
  AvgDialog_6770_Content_11 = {
    Text = "Aquela Sombra, eu a vi! Apenas agora, quando Descobrimos o que aconteceu com os Membros da equipe de inspeção."
  },
  AvgDialog_6770_Content_12 = {
    Text = "Ele muito provavelmente é o culpado!"
  },
  AvgDialog_6770_Content_13 = {
    Text = "Com essa Neve e vento fortes, ele não pode ter ido longe! É fácil se perder aqui, iremos com vocês."
  },
  AvgDialog_6770_Content_14 = {
    Text = "Cuidado com o ferimento. Vamos—"
  },
  AvgDialog_6770_Content_15 = {Text = "..."},
  AvgDialog_6770_Content_16 = {
    Text = "O vento e a Neve estão muito fortes, as pegadas foram cobertas. Parece que precisamos voltar ao acampamento primeiro."
  },
  AvgDialog_6770_Content_17 = {
    Text = "Sim, continuaremos investigando a Sombra Depois."
  },
  AvgDialog_6770_Content_18 = {
    Text = "Mas há algo estranho... muitos Monstros começaram a escapar no meio da luta, como se algo os tivesse assustado..."
  },
  AvgDialog_6770_Content_19 = {
    Text = "Aaaaah! De novo não, já não morreram o suficiente de nós? Monstros—"
  },
  AvgDialog_6770_Content_2 = {
    Text = "Ali! Eu vi..."
  },
  AvgDialog_6770_Content_20 = {
    Text = "Eu não quero morrer aqui— é Ela, ela enfureceu o deus da montanha! É ela quem merece morrer!"
  },
  AvgDialog_6770_Content_21 = {
    Text = "Matem Ela... matem essa... Mons... @2..."
  },
  AvgDialog_6770_Content_22 = {
    Text = "Os rostos de vários Membros da equipe de inspeção se contorceram com Distorção, e suas vozes começaram a ficar incoerentes."
  },
  AvgDialog_6770_Content_23 = {
    Text = "O chão outrora branco e pálido da montanha de Neve agora estava coberto por uma lama negra viscosa. Esse líquido borbulhante e sinistro jorrava da carne dos Membros da equipe de inspeção."
  },
  AvgDialog_6770_Content_25 = {
    Text = "Um Espinhos negro disparou repentinamente, avançando em direção a Helot."
  },
  AvgDialog_6770_Content_26 = {
    Text = "Saia do caminho... Ngh—"
  },
  AvgDialog_6770_Content_27 = {
    Text = "Você se virou de lado e empurrou Ela para fora do caminho. O Espinhos atravessou direto o seu ombro."
  },
  AvgDialog_6770_Content_28 = {
    Text = "Você soltou um gemido abafado, seu braço ficou mole e caiu sobre o ombro de Helot. Sangue misturado com Neve derretida respingou nos olhos Dela, estilhaçando seu reflexo turvo."
  },
  AvgDialog_6770_Content_29 = {
    Text = "Uma dor ardente irradiou da ferida, sua mente agitada em tumulto. O link sofreu uma breve interrupção."
  },
  AvgDialog_6770_Content_3 = {
    Text = "É essa mulher... essa mulher fez isso! Elimine Ela... elimine Ela!!"
  },
  AvgDialog_6770_Content_30 = {
    Text = "Você a observou com ansiedade. Se ela quisesse, poderia se virar e atacá-lo agora mesmo, e sua força mental sem dúvida também sofreria um Sintoma: Crash. Mas... ela não o fez."
  },
  AvgDialog_6770_Content_31 = {Text = "Helot...?"},
  AvgDialog_6770_Content_32 = {
    Text = "Eu não me aproveito das pessoas quando estão por baixo. Quando chegar a hora, vou embora de forma justa. Até lá..."
  },
  AvgDialog_6770_Content_33 = {
    Text = "Ela virou o olhar em direção à equipe de inspeção que gritava para despedaçá-la. Aqueles olhos, outrora acalmados pelo brilho prateado, reacenderam com uma intensa luz de Sangue."
  },
  AvgDialog_6770_Content_34 = {
    Text = "Vocês estão pedindo para morrer!"
  },
  AvgDialog_6770_Content_35 = {
    Text = "Hilota! ..."
  },
  AvgDialog_6770_Content_36 = {
    Text = [[
Era tarde demais.
O Sibilo da bola de corrente abafou seus gritos, esmagando impiedosamente aqueles membros da equipe descontrolados.]]
  },
  AvgDialog_6770_Content_37 = {
    Text = "Você ficou olhando fixamente para a poça de restos negros Pegajosos diante de si. Os companheiros que haviam lutado ao seu lado não muito tempo atrás agora jaziam ali, para sempre deixados nesta geleira perpetuamente coberta de Neve."
  },
  AvgDialog_6770_Content_38 = {Text = "Urgh—"},
  AvgDialog_6770_Content_39 = {
    Text = "Incontáveis exploradores haviam perecido em montanhas de Neve, mas mortes tão horrendas em tamanha quantidade — isso era uma novidade para o guia."
  },
  AvgDialog_6770_Content_4 = {
    Text = "Helot esteve comigo a noite inteira ontem, eu juro..."
  },
  AvgDialog_6770_Content_40 = {
    Text = "Ele não conseguia mais se manter firme. Seus ombros tremiam enquanto vomitava violentamente."
  },
  AvgDialog_6770_Content_41 = {
    Text = "Eles também sofreram Dissolução... A Dissolução aqui, a velocidade de Desenvolvimento é inacreditavelmente rápida..."
  },
  AvgDialog_6770_Content_42 = {
    Text = "Aqueles Monstros que escaparam, e as reações destes membros da equipe—é tudo anormal demais..."
  },
  AvgDialog_6770_Content_43 = {
    Text = "Apenas nós restamos. Precisamos descer a montanha o mais rápido possível, caso contrário..."
  },
  AvgDialog_6770_Content_44 = {Text = "Boom—"},
  AvgDialog_6770_Content_45 = {
    Text = "Suas palavras foram interrompidas quando a escuridão caiu diante de seus olhos."
  },
  AvgDialog_6770_Content_46 = {
    Text = "Todos vocês olharam para cima. Como uma nuvem de tempestade que bloqueia o sol, uma enorme Sombra ergueu-se de um lado do penhasco, pairando sobre vocês."
  },
  AvgDialog_6770_Content_47 = {
    Text = "No corpo do enorme monstro estava gravado um símbolo massivo — um que você já tinha visto antes, em um Sonho."
  },
  AvgDialog_6770_Content_48 = {
    Text = "Isso é... a Igreja da Luz do Templo!!!"
  },
  AvgDialog_6770_Content_49 = {Text = "BOOM!"},
  AvgDialog_6770_Content_5 = {
    Text = "Vocês estão todos juntos nisso! Mentirosos de Misaq!"
  },
  AvgDialog_6770_Content_50 = {
    Text = "<Shake:AHHHH—>"
  },
  AvgDialog_6770_Content_51 = {
    Text = "Grande {Male=Sr. Guardião,Female=Srta. Guardiã}!!!"
  },
  AvgDialog_6770_Content_52 = {
    Text = "A coisa colossal pairando no ar veio desabando. Com um rugido que Rasgou o pico, ela estilhaçou a rocha sob seus pés."
  },
  AvgDialog_6770_Content_53 = {
    Text = "Você pisou no vazio e despencou no vale profundo junto com Helot."
  },
  AvgDialog_6770_Content_54 = {
    Text = "— Em meio aos seus gritos aterrorizados, Helot abriu um largo sorriso e caiu na gargalhada pela primeira vez."
  },
  AvgDialog_6770_Content_6 = {Text = "Eu..."},
  AvgDialog_6770_Content_7 = {
    Text = "Caia em si! Se não fosse pela ajuda de %player%, já teríamos morrido dez vezes nesta montanha!"
  },
  AvgDialog_6770_Content_8 = {
    Text = "O guia sacudiu os ombros dos Membros da equipe de inspeção com força. Sob suas palavras e olhar autoritários, os Membros da equipe de inspeção finalmente se acalmaram um pouco."
  },
  AvgDialog_6770_Content_9 = {
    Text = "Muito obrigado..."
  },
  AvgDialog_6773_Content_1 = {Text = "Reunião"},
  AvgDialog_6773_Content_10 = {
    Text = "Lily... Correr!... É perigoso aqui..."
  },
  AvgDialog_6773_Content_100 = {
    Text = "Precisamos sair daqui agora, e precisamos levar Lily e os outros conosco."
  },
  AvgDialog_6773_Content_101 = {
    Text = "Helot examinou os arredores."
  },
  AvgDialog_6773_Content_102 = {
    Text = "Onde está Lily? Ela não estava sempre com você?"
  },
  AvgDialog_6773_Content_103 = {
    Text = "Quando fomos empurrados do penhasco pelo monstro, Lily e alguns sobreviventes ainda estavam Acima.\nPrecisamos encontrá-los, confirmar que estão seguros e tirá-los de lá o mais rápido possível."
  },
  AvgDialog_6773_Content_104 = {
    Text = "Sob as fissuras na superfície do lago, escuridão sem fim e segredos Ocultos espreitam. Pústulas negras como breu surgem das rachaduras cada vez maiores no gelo, cercando vocês completamente."
  },
  AvgDialog_6773_Content_105 = {
    Text = "Lily e Avis ainda estão em perigo, e não conseguimos nos libertar aqui..."
  },
  AvgDialog_6773_Content_106 = {
    Text = "Ambas as Helots estremeceram simultaneamente, ouvindo gritos urgentes vindos das profundezas de suas almas."
  },
  AvgDialog_6773_Content_107 = {
    Text = "De novo... aquela voz."
  },
  AvgDialog_6773_Content_108 = {
    Text = "A outra \"Shiro\" abriu uma cratera profunda com seu mangual. Incontáveis Pústulas rastejaram para fora do buraco, agarrando-se ao mangual desde o chão."
  },
  AvgDialog_6773_Content_109 = {
    Text = "As Pústulas se contorciam e se Reuniam de todas as direções, mas ela parou de repente."
  },
  AvgDialog_6773_Content_11 = {
    Text = "A voz do guia tremia. Diante de um medo que jamais havia experimentado em toda a sua vida, aquele homem comum reuniu cada gota de coragem que tinha e se postou diante de Lily."
  },
  AvgDialog_6773_Content_110 = {
    Text = "No rosto dela, um sorriso de Loucura Emergiu."
  },
  AvgDialog_6773_Content_111 = {
    Text = "Sim... é isso... é isso!"
  },
  AvgDialog_6773_Content_112 = {
    Text = "É @3! Ele nos vê, Helot... Ele está nos Invocando!"
  },
  AvgDialog_6773_Content_113 = {
    Text = "Fuja deste lugar conosco primeiro!"
  },
  AvgDialog_6773_Content_114 = {
    Text = "Fuga? Não. Eu não vim aqui para escapar."
  },
  AvgDialog_6773_Content_115 = {
    Text = "Não seja tola! Essas Pústulas vão Apenas continuar Emergindo sem fim. Se você continuar, será Devorada!"
  },
  AvgDialog_6773_Content_116 = {
    Text = "E se eu for quem o Devorar?"
  },
  AvgDialog_6773_Content_117 = {Text = "O que?"},
  AvgDialog_6773_Content_118 = {
    Text = "Essas Pústulas pertencem a esta montanha. Você também sentiu, não é, Helot? Ela sempre esteve nos Chamando para o Retorno. Este é o nosso Destino."
  },
  AvgDialog_6773_Content_119 = {
    Text = "Venha, Helot, junte-se a mim, funda-se com esta montanha. Junte-se a mim e enfrente nosso Destino compartilhado..."
  },
  AvgDialog_6773_Content_12 = {
    Text = "Ele tentou protegê-la do frio gélido da morte. Ele tentou resistir àquele Destino irresistível."
  },
  AvgDialog_6773_Content_120 = {
    Text = "Ela quer nos Devorar, drenar nossa Força. Então, inversamente, nós também podemos Devorá-la!"
  },
  AvgDialog_6773_Content_121 = {
    Text = "Helot está ao seu lado, sua expressão fria."
  },
  AvgDialog_6773_Content_122 = {
    Text = "Mesmo uma entidade como eu não consegue resistir à Loucura trazida por tamanha Força, muito menos um fragmento de outra Dimensão como você."
  },
  AvgDialog_6773_Content_123 = {
    Text = "Heh... Se está com medo, então fuja, covarde. Você não tem ainda alguém para encontrar?"
  },
  AvgDialog_6773_Content_124 = {
    Text = "Não se preocupe. Quando eu os tiver Devorado, irei atrás de você.\nQuando esse momento chegar, vou Devorar todos vocês também."
  },
  AvgDialog_6773_Content_125 = {
    Text = "Venham, todos vocês! Me deem mais, mais..."
  },
  AvgDialog_6773_Content_126 = {Text = "...Vamos."},
  AvgDialog_6773_Content_127 = {Text = "Helot?"},
  AvgDialog_6773_Content_128 = {
    Text = "Não faço ideia do que aquela louca está tentando fazer. Em vez de ficar aqui alimentando a Loucura dela, temos coisas mais importantes a fazer. Vou ajudá-lo a encontrar Lily."
  },
  AvgDialog_6773_Content_13 = {
    Text = "Lily caminhou alguns passos à frente e se colocou diante do guia."
  },
  AvgDialog_6773_Content_14 = {
    Text = "O/A grande {Male=Sr. Guardião,Female=Srta. Guardiã} disse que a Lily é muito forte. Então, a Lily vai proteger todos vocês."
  },
  AvgDialog_6773_Content_15 = {
    Text = "Lily! Ah—"
  },
  AvgDialog_6773_Content_16 = {
    Text = "O frio que avançava rapidamente trouxe Paralisia à sua língua. Como se submerso em nitrogênio líquido a centenas de graus abaixo de zero e congelado por completo, nenhuma célula sequer em seu cérebro conseguia se mover um milímetro."
  },
  AvgDialog_6773_Content_17 = {
    Text = "Um frio absoluto capaz de congelar pensamentos instantaneamente e reduzi-los a pó."
  },
  AvgDialog_6773_Content_18 = {
    Text = "Os corpos do guia e de Avis se solidificaram em esculturas de gelo, derrubados pelo vento feroz na Neve. O frio absoluto rastejou pelas pontas dos dedos de Lily."
  },
  AvgDialog_6773_Content_19 = {
    Text = "O que você... fez?"
  },
  AvgDialog_6773_Content_2 = {
    Text = "Este lugar... estava escondendo um monstro tão massivo..."
  },
  AvgDialog_6773_Content_20 = {
    Text = "Você@3... não pode@2..."
  },
  AvgDialog_6773_Content_21 = {
    Text = "A expressão de Lily escureceu, seu olhar desviando do guia para o enorme monstro flutuando no ar."
  },
  AvgDialog_6773_Content_22 = {
    Text = "O monstro azul fluorescente soltou sussurros do sonho venenosos, partículas de Neve irrompendo e roçando as bochechas de Lily, mas seu rosto permaneceu inexpressivo."
  },
  AvgDialog_6773_Content_23 = {
    Text = "Lily, ouça o/a {Male=Sr. Guardião,Female=Srta. Guardiã}, proteja todos."
  },
  AvgDialog_6773_Content_24 = {
    Text = "Uma enorme esfera negra e lisa se condensou a partir de suas pontas dos dedos. Lily estendeu um único dedo, apontando para o monstro azul fluorescente suspenso no ar."
  },
  AvgDialog_6773_Content_25 = {
    Text = "Você NÃO tem permissão para machucá-los!"
  },
  AvgDialog_6773_Content_26 = {Text = "..."},
  AvgDialog_6773_Content_27 = {
    Text = "Lily... Professora Avis?..."
  },
  AvgDialog_6773_Content_28 = {
    Text = "Ninguém respondeu. Você abriu os olhos grogue, sentindo a umidade contra suas costas, seu casaco encharcado de Neve sendo rasgado e comprimido."
  },
  AvgDialog_6773_Content_29 = {
    Text = "Mm... O que é isso?!"
  },
  AvgDialog_6773_Content_3 = {
    Text = "O... O que é... aquela coisa..."
  },
  AvgDialog_6773_Content_30 = {
    Text = "Você havia caído sobre a superfície de um lago congelado, abrindo uma cratera profunda abaixo de si. Escorrendo pelas rachaduras no gelo estavam esferas lisas e negras que se assemelhavam a Pústulas."
  },
  AvgDialog_6773_Content_31 = {
    Text = "Assustado, você imediatamente se afastou da cratera."
  },
  AvgDialog_6773_Content_32 = {
    Text = "Sem você bloqueando o caminho, as Pústulas negras surgindo sob o gelo irromperam de uma só vez, Propagando-se rapidamente até as bordas do lago congelado."
  },
  AvgDialog_6773_Content_33 = {
    Text = "Espere, isso não parece Dissolução?"
  },
  AvgDialog_6773_Content_34 = {
    Text = "Aaaah— Urggh—"
  },
  AvgDialog_6773_Content_35 = {
    Text = "Pústulas negras cobriam todo o corpo de Helot. Como se estivesse em algum tipo de Ressonância, seu corpo tremia com Tremores cada vez mais violentos em sincronia com o Surge de Loucura das Pústulas."
  },
  AvgDialog_6773_Content_36 = {
    Text = "Ela balançou loucamente seu enorme mangual, despedaçando a substância turva e negra que surgia das rachaduras, e então avançou em sua direção."
  },
  AvgDialog_6773_Content_37 = {
    Text = "!!! Helot! Calma!"
  },
  AvgDialog_6773_Content_38 = {
    Text = "Uma névoa negra emanava das pupilas de Helot, enquanto a chave prateada em seu peito ardia com uma luz intensa."
  },
  AvgDialog_6773_Content_39 = {
    Text = "Você podia sentir claramente o link sendo atacado com Loucura, e simplesmente mantê-lo estava se provando incrivelmente difícil."
  },
  AvgDialog_6773_Content_4 = {
    Text = "Diante de um monstro colossal diferente de tudo que já tinha visto, ele reuniu cada gota de sua força apenas para mal conseguir permanecer de pé."
  },
  AvgDialog_6773_Content_40 = {
    Text = "Um sorriso grotesco surgiu em seu rosto, manchado com fluido Pegajoso negro. O enorme mangual era como um brinquedo em suas mãos enquanto ela o balançava, se aproximando de você passo a passo."
  },
  AvgDialog_6773_Content_41 = {
    Text = "Eu consigo sentir... o Chamar da montanha..."
  },
  AvgDialog_6773_Content_42 = {
    Text = "O que você vai fazer?!"
  },
  AvgDialog_6773_Content_43 = {
    Text = "O link, não há mais necessidade de ele existir!"
  },
  AvgDialog_6773_Content_44 = {
    Text = "O mangual desceu com um Sibilo, prestes a esmagar o topo da sua cabeça—"
  },
  AvgDialog_6773_Content_45 = {Text = "Bang—"},
  AvgDialog_6773_Content_46 = {
    Text = "Um som tremendo explodiu acima da sua cabeça. Você lentamente afastou o braço que havia instintivamente erguido para proteger seus olhos."
  },
  AvgDialog_6773_Content_47 = {
    Text = "Se você já se cansou desse chilique, então pare."
  },
  AvgDialog_6773_Content_48 = {
    Text = "O mangual foi arremessado para longe, desabando sem vida para um lado."
  },
  AvgDialog_6773_Content_49 = {
    Text = "No vento cortante e gélido, aquela Sombra familiar e sempre persistente estava de pé com a lâmina em mãos, bloqueando seu caminho."
  },
  AvgDialog_6773_Content_5 = {Text = "\"BOOM—\""},
  AvgDialog_6773_Content_50 = {Text = "Boom—"},
  AvgDialog_6773_Content_51 = {
    Text = "O enorme mangual brandido por \"Shiro\" despedaçou um enxame de Pústulas negras, sua força residual varrendo o gelo que cobria a rocha, e a montanha soltou um lamento de fratura."
  },
  AvgDialog_6773_Content_52 = {
    Text = "Espinhos e mangual colidiram violentamente. Faíscas voaram dos olhos dos dois travados em confronto, cada um descarregando sua fúria ainda ardente sobre o outro."
  },
  AvgDialog_6773_Content_53 = {
    Text = "A Sombra bloqueou seu caminho, segurando ferozmente o mangual que \"Shiro\" brandia loucamente, e foi empurrada vários passos para trás."
  },
  AvgDialog_6773_Content_54 = {
    Text = "O vento gélido uivou, erguendo a capa dilacerada pelos espinhos de ferro, revelando um perfil familiar."
  },
  AvgDialog_6773_Content_55 = {Text = "Helot?!!!"},
  AvgDialog_6773_Content_56 = {
    Text = "Você finalmente apareceu... Eu estive esperando por você, por muito tempo!"
  },
  AvgDialog_6773_Content_57 = {
    Text = "Você é muito lento."
  },
  AvgDialog_6773_Content_58 = {
    Text = "Ela arremessou os Espinhos Pegajosos que havia condensado em sua mão, perfurando as Pústulas Pegajosas no corpo de \"Shiro\" com precisão cirúrgica, espalhando um rastro de pontos negros pela Neve."
  },
  AvgDialog_6773_Content_59 = {
    Text = "Helot, você... você é a Sombra que esteve nos seguindo o tempo todo?!"
  },
  AvgDialog_6773_Content_6 = {
    Text = "Com um estrondo trovejante, Lily bloqueou o ataque do monstro. Ela perdeu o equilíbrio e cambaleou alguns passos, mas seu Olhar permaneceu fixo no monstro adiante."
  },
  AvgDialog_6773_Content_60 = {
    Text = "Fui eu. Eu senti a Invocação e vim até aqui—assim como ela."
  },
  AvgDialog_6773_Content_61 = {
    Text = "Por que você não apareceu para me ver?"
  },
  AvgDialog_6773_Content_62 = {
    Text = "Uma Força de mesma Fonte Primordial me atraiu até aqui. Eu queria ver o que ela realmente estava tentando fazer."
  },
  AvgDialog_6773_Content_63 = {
    Text = "Depois, eu vi aquele monstro."
  },
  AvgDialog_6773_Content_64 = {
    Text = "Você me ajudou uma vez. Assim que eu ajudar você a lidar com esse problema, não vou mais te dever nada."
  },
  AvgDialog_6773_Content_65 = {Text = "Monstro?"},
  AvgDialog_6773_Content_66 = {
    Text = "O monstro que caçou os Membros da equipe de inspeção e fez você cair do penhasco."
  },
  AvgDialog_6773_Content_67 = {
    Text = "Então todas aquelas pessoas que desapareceram foram..."
  },
  AvgDialog_6773_Content_68 = {
    Text = "Sim. O monstro espreitava atrás de vocês, esperando o momento certo para atacar."
  },
  AvgDialog_6773_Content_69 = {
    Text = "Tentei intervir e proteger alguns deles. Sobreviveram, mas ainda assim foram capturados pelo monstro e arrastados para o seu covil."
  },
  AvgDialog_6773_Content_7 = {
    Text = "A cria de @3... @2 está aqui@3..."
  },
  AvgDialog_6773_Content_70 = {
    Text = "Se você é a Helot, então ela é?..."
  },
  AvgDialog_6773_Content_71 = {
    Text = "O olhar de Helot era gélido. Seus olhos hostis passaram por cima do seu ombro e pousaram na \"outra Helot\" atrás de você."
  },
  AvgDialog_6773_Content_72 = {
    Text = "Um Espinhos voou seguindo seu olhar friamente velado, Apenas para ser derrubado na Neve por um mangual enorme arremessado pela outra \"Helot\", derretendo-se em uma poça de lodo negro como piche."
  },
  AvgDialog_6773_Content_73 = {
    Text = "Espere... seja lá o que for isso, vamos conversar..."
  },
  AvgDialog_6773_Content_74 = {
    Text = "Você se colocou apressadamente entre seus olhares hostis, tentando aliviar a tensão."
  },
  AvgDialog_6773_Content_75 = {
    Text = "Mas parecia não ter... Efeito."
  },
  AvgDialog_6773_Content_76 = {
    Text = "Você me sentiu há muito tempo. Durante todo este Caminho, você esteve se preparando para me matar."
  },
  AvgDialog_6773_Content_77 = {
    Text = "Um fragmento de outra Dimensão pode facilmente perder o controle. Se você quer sobreviver neste mundo, existem outros caminhos."
  },
  AvgDialog_6773_Content_78 = {
    Text = "\"Viva\"? O que eu quero é muito mais do que apenas estar viva."
  },
  AvgDialog_6773_Content_79 = {
    Text = "A outra \"Helot\" lambeu a gosma negra que manchava o canto de sua boca. A bola de corrente girava loucamente em suas mãos, o som do vento uivante se aproximando cada vez mais."
  },
  AvgDialog_6773_Content_8 = {
    Text = "O monstro pairando no ar tremeu e soltou um uivo estridente."
  },
  AvgDialog_6773_Content_80 = {
    Text = "Apenas uma Helot pode existir neste mundo. A \"eu\" fraca é o fantasma que não deveria existir."
  },
  AvgDialog_6773_Content_81 = {
    Text = "Dimensões, fragmentos, a \"eu\" fraca... Será que isso é... Origem?!"
  },
  AvgDialog_6773_Content_82 = {
    Text = "Você se lembrou do seu encontro com Gênesis Ramona."
  },
  AvgDialog_6773_Content_83 = {
    Text = "Isso mesmo. Este fragmento dela foi desprendido da \"eu\" de outro mundo. Em essência, somos a mesma pessoa."
  },
  AvgDialog_6773_Content_84 = {
    Text = "Mas não entendo por que ela apareceria neste mundo..."
  },
  AvgDialog_6773_Content_85 = {
    Text = "A outra \"Helot\" riu selvagemente e com arrogância, Liberando toda a sua malícia transbordante através de sua risada."
  },
  AvgDialog_6773_Content_86 = {
    Text = "Hahaha... Quem é a mesma pessoa que você?"
  },
  AvgDialog_6773_Content_87 = {
    Text = "Herbert tinha razão. Você é igual à antiga eu—fraca, perdida e completamente frágil."
  },
  AvgDialog_6773_Content_88 = {
    Text = "Herbert... ele de novo."
  },
  AvgDialog_6773_Content_89 = {
    Text = "Eu não sei o que Herbert e a Lanterna te prometeram, mas ele é um traidor.\nAs palavras de um traidor não merecem confiança."
  },
  AvgDialog_6773_Content_9 = {
    Text = "Quando Lily se preparava para conjurar outra esfera negra, uma figura se colocou à sua frente."
  },
  AvgDialog_6773_Content_90 = {
    Text = "Você não entende nada, Helot. Eu não confiei em ninguém. A minha vinda até aqui não tem nada a ver com ninguém."
  },
  AvgDialog_6773_Content_91 = {
    Text = "Apenas a Força absoluta pode me permitir completar minha vingança."
  },
  AvgDialog_6773_Content_92 = {
    Text = "A bola de corrente, impulsionada por uma Força colossal imensa, girava em suas mãos enquanto ela se aproximava lentamente de Helot."
  },
  AvgDialog_6773_Content_93 = {
    Text = "Devorar você é o que vai tornar \"Shiro\" mais forte—"
  },
  AvgDialog_6773_Content_94 = {
    Text = "A bola de ferro com seu Sibilo abafou suas palavras, arremessando-se em sua direção."
  },
  AvgDialog_6773_Content_96 = {
    Text = "Helot esquivou-se do Golpe pesado da corrente, arremessando os Espinhos Pegajosos em sua mão nos pontos vitais da outra \"Shiro\", mal conseguindo se equilibrar na borda da fenda de gelo que transbordava Pústulas."
  },
  AvgDialog_6773_Content_97 = {
    Text = "Pústulas... As Pústulas estão transbordando de novo!"
  },
  AvgDialog_6773_Content_98 = {
    Text = "Ambas pararam ao mesmo tempo, olhando para o enorme buraco no centro do lago congelado, de onde uma substância escura e Pegajosa estava lentamente escorrendo."
  },
  AvgDialog_6773_Content_99 = {
    Text = "Essa fenda está se alargando gradualmente. Ainda há cada vez mais Pústulas Dentro, e se demorarmos mais, temo que nunca mais consigamos sair—"
  },
  AvgDialog_67773_Content_1 = {
    Text = "Nós ganhamos... finalmente..."
  },
  AvgDialog_67773_Content_2 = {
    Text = "Não, esse sentimento... uma sensação opressiva avassaladora, ainda mais forte do que antes..."
  },
  AvgDialog_67773_Content_3 = {
    Text = "O que é isso?! ......"
  },
  AvgDialog_6777_Content_1 = {
    Text = "Aliado ou Inimigo"
  },
  AvgDialog_6777_Content_10 = {
    Text = "Talvez seja porque pessoas como eles existem que este mundo ainda consegue se agarrar a um fio de paz em meio a toda essa Loucura."
  },
  AvgDialog_6777_Content_100 = {
    Text = "Ele fez uma pausa, seu tom um tanto apologético."
  },
  AvgDialog_6777_Content_101 = {
    Text = "Preciso ser responsável pela segurança de todos."
  },
  AvgDialog_6777_Content_102 = {
    Text = "Depois de escalar por um longo tempo, você ainda não conseguiu encontrar nenhum rastro de Helot. O cume estava engolfado por vento feroz e nevasca."
  },
  AvgDialog_6777_Content_103 = {
    Text = "Você deveria abandonar a Ação e descer com a equipe, ou seguir em frente contra todas as probabilidades e continuar escalando até o cume? Você precisa tomar uma decisão..."
  },
  AvgDialog_6777_Content_104 = {
    Text = "Grande {Male=Sr. Guardião,Female=Srta. Guardiã}, há um... cheiro familiar aqui. Lily consegue sentir..."
  },
  AvgDialog_6777_Content_105 = {Text = "Rugido—"},
  AvgDialog_6777_Content_106 = {
    Text = "Mais à frente... há Monstros?!"
  },
  AvgDialog_6777_Content_107 = {
    Text = "Helot está logo à frente... Ela pode estar em perigo!"
  },
  AvgDialog_6777_Content_108 = {
    Text = "Seguindo a orientação de Lily, você virou ao longo do Caminho sinuoso e avistou uma figura se aproximando lentamente de você."
  },
  AvgDialog_6777_Content_109 = {
    Text = "Aquela é... Helot?!!"
  },
  AvgDialog_6777_Content_11 = {
    Text = "Grande {Male=Sr. Guardião,Female=Srta. Guardiã}, o que você quer dizer... Lily não entende."
  },
  AvgDialog_6777_Content_110 = {
    Text = "Você avançou com passos largos."
  },
  AvgDialog_6777_Content_111 = {
    Text = "A menina estava vestida com roupas finas. Ao ouvir seus gritos, ela parou na Neve, olhando cautelosamente na sua direção."
  },
  AvgDialog_6777_Content_112 = {
    Text = "De fato, aquele era inconfundivelmente o rosto de Helot, mas você não pôde ter certeza imediatamente—A aura Dela era completamente diferente da última vez que você a viu."
  },
  AvgDialog_6777_Content_113 = {
    Text = "Assustada pela sua comoção, aquela expressão cautelosa Dela era como uma Besta encurralada por todos os lados, pronta para Liberar um golpe letal a qualquer momento."
  },
  AvgDialog_6777_Content_114 = {
    Text = "A Besta estava com o corpo todo tenso, prendendo a respiração em um Olhar fixo. No momento seguinte, ela mostrou os dentes em um sorriso, e a breve confusão em seus olhos deu lugar inteiramente à hostilidade e intenção assassina."
  },
  AvgDialog_6777_Content_115 = {Text = "?!!"},
  AvgDialog_6777_Content_116 = {
    Text = "Helot deu um passo à frente e atacou sem aviso. Um enorme mangual se materializou em sua mão e veio com um Sibilo na sua direção."
  },
  AvgDialog_6777_Content_118 = {
    Text = "Um baque surdo. O guia foi violentamente atingido de raspão e arremessado pelo mangual negro como breu. O Sangue escaldante que jorrou derreteu a Neve e o gelo perpetuamente congelados, tingindo de um vermelho vívido as pontas das botas de escalada congeladas nas proximidades."
  },
  AvgDialog_6777_Content_119 = {
    Text = "Ugh... Todos... recuem!"
  },
  AvgDialog_6777_Content_12 = {
    Text = "Lily puxou a barra das suas roupas novamente. Você se abaixou e sorriu para Ela."
  },
  AvgDialog_6777_Content_120 = {
    Text = "Diante de todos os olhares, Helot avançou contra a multidão como uma Besta enlouquecida, seu Cabelo desgrenhado."
  },
  AvgDialog_6777_Content_121 = {
    Text = "%player%! Pense em algo! Essa louca está realmente tentando matar Todos!"
  },
  AvgDialog_6777_Content_122 = {
    Text = "Ela perdeu completamente a razão... Temos que pará-la à força!"
  },
  AvgDialog_6777_Content_123 = {
    Text = "Você tirou a Chave de prata do peito, concentrou a mente e canalizou energia espiritual. Uma camada de suave radiância prateada ondulou ao seu redor."
  },
  AvgDialog_6777_Content_124 = {
    Text = "A radiância prateada invadiu gentilmente a consciência de Helot. Seu Espaço mental frenético Sibilava com ventos furiosos, resistindo ao seu link com todas as forças."
  },
  AvgDialog_6777_Content_125 = {
    Text = "Um rugido se aproximou diante dos seus olhos—"
  },
  AvgDialog_6777_Content_126 = {
    Text = "Helot... pare com isso!"
  },
  AvgDialog_6777_Content_127 = {
    Text = "Helot soltou um rugido dilacerante. Ela arremessou sua bola de corrente em frenesi, destruindo tudo na montanha de Neve em pedaços."
  },
  AvgDialog_6777_Content_128 = {
    Text = "Toda essa confusão! Essa maníaca— além de machucar pessoas indiscriminadamente, ela quer provocar uma avalanche também?!"
  },
  AvgDialog_6777_Content_129 = {
    Text = "Ela não parece se lembrar de nada. O que diabos aconteceu com ela?!"
  },
  AvgDialog_6777_Content_13 = {
    Text = "O que eu quero dizer é que, daqui a pouco, um grupo inteiro de irmãos e irmãs mais velhos virá Disparar com Lily. Mas este lugar é muito perigoso, e eles não têm a capacidade de se proteger."
  },
  AvgDialog_6777_Content_130 = {
    Text = "%player%! Pense em alguma coisa! Controle essa maníaca!"
  },
  AvgDialog_6777_Content_131 = {
    Text = "Helot! Tente se lembrar! Sou eu—"
  },
  AvgDialog_6777_Content_132 = {
    Text = "Ding————"
  },
  AvgDialog_6777_Content_133 = {
    Text = "Finalmente, a suave radiância prateada lutou através da consciência turbulenta e brilhou nos olhos de Helot, enlouquecidos pela Loucura."
  },
  AvgDialog_6777_Content_134 = {
    Text = "Helot sentiu Como se estivesse flutuando em um rio prateado transbordando de radiância, deixando a água embalar gentilmente o Ela espírito."
  },
  AvgDialog_6777_Content_135 = {
    Text = "Ela lutou para se libertar, mas a água corrente a envolveu com ainda mais ternura, puxando-a cada vez mais fundo..."
  },
  AvgDialog_6777_Content_136 = {
    Text = "Eu Apenas mal suprimi sua tendência à Loucura. Sua consciência ainda está tentando se libertar do link... Você não quer ficar aqui, não é?"
  },
  AvgDialog_6777_Content_137 = {
    Text = "A Loucura nos olhos de Helot havia desaparecido, mas o olhar Dela ainda era abrasador, fixo no seu como um predador observando um pedaço de carne."
  },
  AvgDialog_6777_Content_138 = {
    Text = "Eu–não–pertenço–aqui—"
  },
  AvgDialog_6777_Content_139 = {
    Text = "Ela pronunciou cada palavra deliberadamente, fazendo um simples desabafo soar como uma ameaça."
  },
  AvgDialog_6777_Content_14 = {
    Text = "Mas nós podemos."
  },
  AvgDialog_6777_Content_140 = {
    Text = "Então você se lembra de onde pertence?"
  },
  AvgDialog_6777_Content_141 = {
    Text = "Helot caiu em silêncio."
  },
  AvgDialog_6777_Content_142 = {
    Text = "Eu não sei o que aconteceu com você. Talvez até você voltar ao normal, possamos trabalhar juntos?"
  },
  AvgDialog_6777_Content_143 = {
    Text = "Elworth é estranha e imprevisível demais. Agora que você encontrou Helot, \"partir o mais rápido possível\" é sua missão de maior prioridade. Você precisa que ela seja controlável."
  },
  AvgDialog_6777_Content_144 = {
    Text = "Vendo que Helot permanecia em silêncio, mas sua mente continuava tentando se libertar do seu link, sua expressão escureceu."
  },
  AvgDialog_6777_Content_145 = {
    Text = "Seu estado mental é extremamente instável. Sem um link em você, há uma grande chance de você mutar novamente em um monstro que perdeu sua forma humana e sanidade."
  },
  AvgDialog_6777_Content_146 = {
    Text = "Você também não quer isso, quer?"
  },
  AvgDialog_6777_Content_147 = {
    Text = "Um fogo feroz se acendeu nos olhos de Helot. Ela mostrou seus dentes afiados, sorrindo para você.\nO olhar que ela fixou em você era como o de uma Besta observando sua presa."
  },
  AvgDialog_6777_Content_148 = {
    Text = "Ameaças e coerção... que cretino.\nQuando eu estiver estabilizada, vou te despedaçar, te Devorar, te limpar até os ossos—"
  },
  AvgDialog_6777_Content_149 = {
    Text = "Você sustentou o olhar dela sem um pingo de medo."
  },
  AvgDialog_6777_Content_15 = {
    Text = "Lily... consegue?"
  },
  AvgDialog_6777_Content_150 = {
    Text = "Estarei esperando. Mas por enquanto, você tem que me obedecer."
  },
  AvgDialog_6777_Content_16 = {
    Text = "Claro. A Lily é muito forte. A Lily vai protegê-los, certo?"
  },
  AvgDialog_6777_Content_17 = {
    Text = "...Tá bom!"
  },
  AvgDialog_6777_Content_18 = {
    Text = "Ah! Mon... Monstros!! ..."
  },
  AvgDialog_6777_Content_19 = {
    Text = "Sons de comoção chegaram de longe, interrompendo a vossa conversa."
  },
  AvgDialog_6777_Content_2 = {
    Text = "Tem certeza de que é aqui?"
  },
  AvgDialog_6777_Content_20 = {
    Text = "Tu e a Lily trocaram um olhar. Pegando na mão dela, correste em direção à origem dos sons..."
  },
  AvgDialog_6777_Content_21 = {Text = "..."},
  AvgDialog_6777_Content_22 = {
    Text = "Lidaste rapidamente com os monstros que se aproximavam e depois voltaste em direção ao acampamento."
  },
  AvgDialog_6777_Content_23 = {
    Text = "Todos estão bem?"
  },
  AvgDialog_6777_Content_24 = {
    Text = "O grupo no acampamento contava com cerca de uma dúzia de pessoas, na maioria não combatentes frágeis. Olhavam para as criaturas aterradoras em pânico, oferecendo apenas uma resistência limitada."
  },
  AvgDialog_6777_Content_25 = {
    Text = "Muito obrigado, {Male=sir,Female=miss}. Não teríamos conseguido sem ti."
  },
  AvgDialog_6777_Content_26 = {
    Text = "A julgar pela tua vestimenta, não pareces um topógrafo profissional. O que te traz a um lugar como este?"
  },
  AvgDialog_6777_Content_27 = {
    Text = "Oh, recebi uma mensagem da Doll a dizer que enviaria um estudante. %player%... és tu, certo?"
  },
  AvgDialog_6777_Content_28 = {
    Text = "A voz dele soava calma e firme. Usava um comunicador com o emblema da escola no peito. Pelo que parecia, era o professor a conduzir pesquisa de campo que a Doll tinha mencionado — Avis."
  },
  AvgDialog_6777_Content_29 = {
    Text = "Encontrar um estudante da nossa própria universidade enquanto fazemos levantamentos em Elworth — que surpresa agradável... Olá, prazer em conhecer-te. Sou professor de paleontologia na Universidade de Misag, e também alpinista profissional."
  },
  AvgDialog_6777_Content_3 = {
    Text = "Mm, Lily consegue sentir. Irmã Helot... está bem aqui."
  },
  AvgDialog_6777_Content_30 = {
    Text = "Prazer em conhecê-lo, Professor."
  },
  AvgDialog_6777_Content_31 = {
    Text = "Apenas me chama de Avis."
  },
  AvgDialog_6777_Content_32 = {
    Text = "Não tinha reparado antes — há uma criança tão pequena escondida ao teu lado?"
  },
  AvgDialog_6777_Content_33 = {
    Text = "Este lugar está coberto de gelo e neve, e ela está com roupas tão finas. Não tens receio de que ela congele?"
  },
  AvgDialog_6777_Content_34 = {
    Text = "A Lily não tem frio. A Lily está aqui para proteger todos."
  },
  AvgDialog_6777_Content_35 = {
    Text = "Haha. Que pequenina adorável."
  },
  AvgDialog_6777_Content_36 = {
    Text = "Bem, graças a %player%, não gastámos demasiada energia a lidar com aquelas criaturas."
  },
  AvgDialog_6777_Content_37 = {
    Text = "Todos levaram um grande susto. Vamos fazer um descanso no acampamento por um bocado."
  },
  AvgDialog_6777_Content_38 = {
    Text = "Lily estava nos braços da médica, enquanto Avis, bronzeado pelo sol, fazia caretas para Ela para animá-la."
  },
  AvgDialog_6777_Content_39 = {
    Text = "Um grupo de membros da equipa aglomerou-se à volta Dela, protegendo-a da Neve e do vento enquanto enchiam as suas pequenas palmas de chocolates e nozes."
  },
  AvgDialog_6777_Content_4 = {
    Text = "Lily também ouviu outra voz."
  },
  AvgDialog_6777_Content_40 = {
    Text = "Para essas pessoas que enfrentavam constantemente a ameaça da morte, o sorriso de uma criança era o seu Apenas consolo restante."
  },
  AvgDialog_6777_Content_41 = {
    Text = "Mmm... é demais para acabar..."
  },
  AvgDialog_6777_Content_42 = {
    Text = "As bochechas de Lily estavam cheias de nozes enquanto os seus dentinhos roíam o chocolate endurecido pelo frio, os seus olhos curvados em meias-luas felizes."
  },
  AvgDialog_6777_Content_43 = {
    Text = "Ao notar o teu olhar, Lily saltou do colo da médica e correu até ao teu lado com passinhos curtos."
  },
  AvgDialog_6777_Content_44 = {
    Text = "Aquela senhora cheira muito como a Mamã.\nLily sentia frequentemente esse cheiro durante as cirurgias... é muito familiar."
  },
  AvgDialog_6777_Content_45 = {
    Text = "Então Lily está disposta a brincar com eles agora?"
  },
  AvgDialog_6777_Content_46 = {
    Text = "Lily olhou para ti muito seriamente."
  },
  AvgDialog_6777_Content_47 = {
    Text = "O/A grande {Male=Sr. Guardião,Female=Srta. Guardiã} é muito importante, mas estes irmãos e irmãs são todos muito simpáticos com Lily, e Lily também gosta de estar com eles."
  },
  AvgDialog_6777_Content_48 = {
    Text = "Fizeste festas na cabeça de Lily e observaste os arredores."
  },
  AvgDialog_6777_Content_49 = {
    Text = "Ao passar por um poço, um fedor nauseante emanava do seu interior."
  },
  AvgDialog_6777_Content_5 = {
    Text = "Aquela montanha está Chamando Lily..."
  },
  AvgDialog_6777_Content_50 = {
    Text = "Que estranho. Nesta paisagem gelada de gelo e Neve, por que viria tal cheiro deste poço?"
  },
  AvgDialog_6777_Content_51 = {
    Text = "Avis aproximou-se mais."
  },
  AvgDialog_6777_Content_52 = {
    Text = "Existem vulcões adormecidos sob os campos de gelo de Elworth. Provavelmente é gás tóxico de uma reação magmática. Não me parece que seja nada de grave."
  },
  AvgDialog_6777_Content_53 = {
    Text = "Olhaste à volta — eram apenas tu e Avis. Foste até ao lado dele e baixaste a voz."
  },
  AvgDialog_6777_Content_54 = {
    Text = "Professor, é mesmo seguro que os membros comuns da expedição vejam aqueles Monstros?"
  },
  AvgDialog_6777_Content_55 = {
    Text = "Não te preocupes, eles não conseguem ver os vestígios de Fusão. Quanto ao comportamento bizarro dos animais, já o justifiquei, dizendo que é um vírus biológico único de Elworth que os faz ficar assim quando infetados."
  },
  AvgDialog_6777_Content_56 = {
    Text = "Como sou o Apenas académico na equipa com alguma ligação à biologia, todos acreditam em mim sem questionar. Ninguém quer olhar uma segunda vez para aqueles animais, por isso não vão Descobrir nada."
  },
  AvgDialog_6777_Content_57 = {
    Text = "Você acenou. A voz profunda do guia veio de não muito longe."
  },
  AvgDialog_6777_Content_58 = {
    Text = "Todos já descansaram o suficiente. Enquanto ainda é cedo, vamos desmontar o acampamento e começar a subir o mais rápido possível."
  },
  AvgDialog_6777_Content_59 = {
    Text = "Logo, vocês desmontaram o acampamento e seguiram o guia montanha acima. Pelo caminho, restos roídos de cavalos estavam espalhados à beira da estrada, ossos brancos enterrados sob a neve."
  },
  AvgDialog_6777_Content_6 = {
    Text = "Uma cordilheira se estende diante de você, seus picos — perpetuamente erodidos pela Neve — banhados em luz dourada, erguendo-se solenemente sobre as planícies congeladas."
  },
  AvgDialog_6777_Content_60 = {
    Text = "Esses retalhos coloridos de tecido—"
  },
  AvgDialog_6777_Content_61 = {
    Text = "São alpinistas que morreram no caminho anos atrás. As formas como morreram foram das mais bizarras—alguns congelaram até a morte, alguns foram soterrados vivos por avalanches, alguns caíram do cume... Muitas pessoas morreram nesta montanha."
  },
  AvgDialog_6777_Content_62 = {
    Text = "Cavalos podem servir como montaria e também podem ser abatidos para alimento. Apenas, mais acima, cavalos não conseguem ir mais alto."
  },
  AvgDialog_6777_Content_63 = {
    Text = "O guia gesticulou com o queixo, indicando para você olhar para um cadáver caído à beira do caminho."
  },
  AvgDialog_6777_Content_64 = {
    Text = "Estava em grande parte coberto por gelo e neve, sua pele exibindo um tom arroxeado-azulado escuro, congelado na postura de quem rastejava para fora de um saco de dormir, com um sorriso sinistro e amargo."
  },
  AvgDialog_6777_Content_65 = {
    Text = "\"Despir-se paradoxal\" e \"sorriso amargo\"—sinais clássicos de morte por congelamento."
  },
  AvgDialog_6777_Content_66 = {
    Text = "Os restos de alpinistas que morreram nos picos nevados normalmente servem como marcos para aqueles que vêm depois encontrarem o caminho."
  },
  AvgDialog_6777_Content_67 = {
    Text = "Ainda há amigos meus que ficaram para trás nesta montanha. Posso ir verificar a placa de identificação deste alpinista?"
  },
  AvgDialog_6777_Content_68 = {Text = "Claro."},
  AvgDialog_6777_Content_69 = {
    Text = "Avis caminhou pela neve fofa, avançando passo a passo em direção ao cadáver rígido. Ele tentou movê-lo para revelar a placa de identificação no saco de dormir."
  },
  AvgDialog_6777_Content_7 = {
    Text = "O Chamar das montanhas... Será porque Helot está lá? Vocês duas conseguem sentir uma à outra..."
  },
  AvgDialog_6777_Content_70 = {
    Text = "No instante seguinte, no momento em que ele estava completamente desprevenido, um corpo humano arroxeado-azulado coberto de gelo e neve saltou de dentro do saco de dormir."
  },
  AvgDialog_6777_Content_71 = {
    Text = "O cadáver sem nome, sorrindo de forma sinistra, estendeu suas mãos—untadas com um fluido negro e pegajoso—em direção a Avis, que havia caído no chão."
  },
  AvgDialog_6777_Content_72 = {Text = "Ahhh!!!!!!"},
  AvgDialog_6777_Content_73 = {
    Text = "Mons... Mons... Monstro!"
  },
  AvgDialog_6777_Content_74 = {
    Text = "Todos, cuidado! Lily!"
  },
  AvgDialog_6777_Content_75 = {
    Text = "...Tá bom!"
  },
  AvgDialog_6777_Content_76 = {
    Text = "Orbes negros apareceram ao lado de Lily, arremessando-se contra aqueles cadáveres grotescamente contorcidos. Logo, as pústulas negras dentro dos cadáveres foram purgadas pelo seu grupo."
  },
  AvgDialog_6777_Content_77 = {
    Text = "Aaaaah— É o deus da montanha! Aqueles que profanam o divino sofrerão punição divina!"
  },
  AvgDialog_6777_Content_78 = {
    Text = "Forasteiros irreverentes, invadindo o santuário onde os deuses habitam—vocês não são bem-vindos aqui! Saiam! Saiam!"
  },
  AvgDialog_6777_Content_79 = {
    Text = "Esta era a pessoa local de Elworth contratada pela equipe de pesquisa. Ele tinha mantido uma expressão carrancuda durante toda a jornada, mas agora exibia um Fervor doentio."
  },
  AvgDialog_6777_Content_8 = {
    Text = "De acordo com Doll, a equipe de expedição também deve estar chegando por agora. Vamos esperar por eles aqui."
  },
  AvgDialog_6777_Content_80 = {
    Text = "A equipe inteira ficou em silêncio. O cadáver que havia subitamente ganhado vida momentos atrás, e o sussurro do sonho enlouquecido da pessoa local, lançaram uma nuvem de medo sobre toda a equipe de inspeção."
  },
  AvgDialog_6777_Content_81 = {
    Text = "Além dos poucos de vocês vindos de Mida, ninguém jamais havia encontrado uma situação como esta."
  },
  AvgDialog_6777_Content_82 = {
    Text = "O que foi isso agora...?"
  },
  AvgDialog_6777_Content_83 = {
    Text = "...Não tenho certeza."
  },
  AvgDialog_6777_Content_84 = {
    Text = "Você não conseguiu responder."
  },
  AvgDialog_6777_Content_85 = {
    Text = "Sob os termos do \"Acordo Mystedia\", você era obrigado a manter o segredo de pessoas de fora e não revelar a existência do Fenômeno de Erosão para pessoas comuns."
  },
  AvgDialog_6777_Content_86 = {
    Text = "O rosto da pessoa local estava pálido, seus lábios se contorcendo enquanto cuspiam repulsivos sussurros do sonho, como larvas lutando para rastejar de sua boca."
  },
  AvgDialog_6777_Content_87 = {
    Text = "Poderia realmente ser... um deus...?"
  },
  AvgDialog_6777_Content_88 = {
    Text = "O guia, tendo recuperado a compostura, franziu a testa, mas ainda assim balançou a cabeça Firmemente."
  },
  AvgDialog_6777_Content_89 = {
    Text = "O professor explicou antes que aqueles animais estranhos eram suspeitos de Atacar pessoas após serem infectados por um vírus, então... é possível que humanos também possam exibir comportamento agressivo após a infecção."
  },
  AvgDialog_6777_Content_9 = {
    Text = "Pesquisadores de Misaq, viajando milhares de quilômetros para explorar um lugar tão perigoso."
  },
  AvgDialog_6777_Content_90 = {
    Text = "Isso é algo explicável dentro do campo da ciência. Não devemos deixar nossa imaginação correr solta."
  },
  AvgDialog_6777_Content_91 = {
    Text = "A voz do guia era firme e forte, aparentemente bastante confiável, mas seus punhos atrás das costas tremiam levemente."
  },
  AvgDialog_6777_Content_92 = {
    Text = "Ele tentou fabricar uma explicação crível e reconfortante — para os outros, e para si mesmo."
  },
  AvgDialog_6777_Content_93 = {
    Text = "Os Membros da equipe de inspeção assustados claramente não estavam convencidos por essa explicação superficial, mas suas expressões gradualmente se acalmaram enquanto enterravam sua inquietação bem fundo, e começaram a arrumar as coisas para partir mais uma vez."
  },
  AvgDialog_6777_Content_94 = {
    Text = "A milhares de metros de altitude em uma montanha coberta de Neve, diante de um abismo desconhecido, as pessoas precisavam de um falso conforto. Precisavam de algo em que acreditar."
  },
  AvgDialog_6777_Content_95 = {
    Text = "— A equipe de inspeção, retornando ao silêncio, retomou a escalada rumo ao pico."
  },
  AvgDialog_6777_Content_96 = {Text = "..."},
  AvgDialog_6777_Content_97 = {
    Text = "Vocês passaram dois dias escalando a montanha, gradualmente se Adaptando ao clima daqui. A equipe de inspeção reuniu muitos resultados, mas não havia muita alegria visível no rosto de ninguém."
  },
  AvgDialog_6777_Content_98 = {
    Text = "Aqueles incidentes sinistros continuavam a perturbar cada membro desinformado."
  },
  AvgDialog_6777_Content_99 = {
    Text = "As amostras de rocha coletadas ao longo do Caminho já eram suficientes. Se vocês ainda insistissem em seguir mais adiante montanha acima, a equipe de inspeção seria incapaz de continuar com vocês."
  },
  AvgDialog_6787_Content_1 = {
    Text = "Uma primavera"
  },
  AvgDialog_6787_Content_10 = {
    Text = "Você assentiu e voltou o olhar para a janela."
  },
  AvgDialog_6787_Content_11 = {
    Text = "Você nunca teve grandes esperanças de encontrar o Núcleo de prata de Helot."
  },
  AvgDialog_6787_Content_12 = {
    Text = "Ramona, você acha que as montanhas cobertas de neve de Elworth vão derreter algum dia?"
  },
  AvgDialog_6787_Content_13 = {
    Text = "...Elworth é uma terra de frio extremo. O vento e a neve lá nunca cessam, o ano inteiro."
  },
  AvgDialog_6787_Content_14 = {
    Text = "Sim, isso é de conhecimento geral. O vento e a neve de Elworth nunca cessam, o ano inteiro."
  },
  AvgDialog_6787_Content_15 = {
    Text = "Aquela promessa, levada aos seus ouvidos pelo vendaval, era como uma despedida reconfortante."
  },
  AvgDialog_6787_Content_16 = {
    Text = "O céu fluía com tons carmesim ricos como tinta a óleo, a luz remanescente se espalhando por suas mãos. Do lado de fora da janela, o campus da Universidade de Misag estava banhado pelo sol poente."
  },
  AvgDialog_6787_Content_17 = {
    Text = "Você dormiu por uma semana inteira... Como está a recuperação, Guardião?"
  },
  AvgDialog_6787_Content_18 = {
    Text = "Os belos dias da juventude não devem ser desperdiçados em uma cama de hospital."
  },
  AvgDialog_6787_Content_19 = {
    Text = "Olhe, adivinha o que eu trouxe para você?"
  },
  AvgDialog_6787_Content_2 = {
    Text = "O Professor Avis ainda está inconsciente, mas foi confirmado que não há risco de vida."
  },
  AvgDialog_6787_Content_20 = {
    Text = "%player% é um paciente e não pode beber álcool... Espero que tenha um mínimo de bom senso, Professor Dexter."
  },
  AvgDialog_6787_Content_21 = {
    Text = "Esta bebida é uma que eu devia a %player%."
  },
  AvgDialog_6787_Content_22 = {
    Text = "Este incidente foi, até certo ponto, causado por mim também. Então vim aqui especificamente para expressar minhas desculpas."
  },
  AvgDialog_6787_Content_23 = {
    Text = "Confie em mim, não foi fácil guardar essas boas bebidas até agora. Foi preciso um grande esforço para Contrataque meus impulsos."
  },
  AvgDialog_6787_Content_24 = {
    Text = "Beber não é exatamente uma boa forma de se expressar."
  },
  AvgDialog_6787_Content_25 = {
    Text = "Quando você diz isso, tanto as bebidas quanto eu ficamos magoados, Senhorita Ramona."
  },
  AvgDialog_6787_Content_26 = {
    Text = "Além das bebidas, eu trouxe outro presente para você."
  },
  AvgDialog_6787_Content_27 = {
    Text = "Ele jogou um jornal sobre a mesa."
  },
  AvgDialog_6787_Content_28 = {
    Text = "Bebidas e notícias — aproveite ambos. Bom descanso, Guardião."
  },
  AvgDialog_6787_Content_29 = {
    Text = "Dexter fez uma reverência elegante a todos vocês e fechou a porta suavemente."
  },
  AvgDialog_6787_Content_3 = {
    Text = "O guia também está recebendo tratamento psiquiátrico profissional. Segundo o médico, apesar de ter vivenciado um evento traumático tão severo, sua estabilidade mental permanece notavelmente alta."
  },
  AvgDialog_6787_Content_30 = {
    Text = "Ao enfrentar o Professor Dexter, às vezes me arrependo muito de não ter estudado retórica mais a fundo."
  },
  AvgDialog_6787_Content_31 = {
    Text = "Ela pegou o jornal que Dexter havia deixado para trás."
  },
  AvgDialog_6787_Content_32 = {
    Text = "\"Relatórios indicam que as montanhas perpetuamente congeladas nas profundezas de Elworth, onde uma grande avalanche ocorreu não muito tempo atrás, agora apresentam sinais estranhos de Fusão...\""
  },
  AvgDialog_6787_Content_33 = {
    Text = "Você virou a cabeça de repente e agarrou o jornal."
  },
  AvgDialog_6787_Content_34 = {
    Text = "Na fotografia borrada impressa em tinta, o vento e a neve pelas montanhas haviam cessado."
  },
  AvgDialog_6787_Content_35 = {
    Text = "Um pequeno e esguio dente-de-leão havia rompido o manto perene de neve, colocando a cabeça para fora."
  },
  AvgDialog_6787_Content_36 = {
    Text = "Dando as boas-vindas à primeira primavera de Elworth."
  },
  AvgDialog_6787_Content_4 = {
    Text = "Durante todo o tratamento, o que mais o preocupava era a condição de Lily e a sua... Para uma pessoa comum, ser capaz de fazer isso é verdadeiramente notável."
  },
  AvgDialog_6787_Content_5 = {
    Text = "A Igreja da Luz do Templo tentou reviver a Montanha de Neve para alimentar seu próximo plano. Felizmente, você os impediu a tempo."
  },
  AvgDialog_6787_Content_6 = {
    Text = "A universidade está muito satisfeita com seus resultados desta vez e decidiu compensar..."
  },
  AvgDialog_6787_Content_7 = {
    Text = "O Núcleo de prata dela... foi encontrado?"
  },
  AvgDialog_6787_Content_8 = {Text = "..."},
  AvgDialog_6787_Content_9 = {
    Text = "Nosso pessoal correu até lá na primeira oportunidade e tentou muitos métodos..."
  },
  AvgDialog_6788_Content_1 = {
    Text = "Helot, para onde você está indo?"
  },
  AvgDialog_6788_Content_2 = {
    Text = "Observando Helot escalar em direção às chamas azuis fluorescentes no topo da montanha de Neve, você apressa alguns passos à frente para alcançá-la, perguntando ansiosamente."
  },
  AvgDialog_6788_Content_3 = {
    Text = "Se meu julgamento estiver correto, o lugar protegido por toda a energia do monstro é o núcleo desta montanha de Neve."
  },
  AvgDialog_6788_Content_4 = {
    Text = "Lily e eu não conseguimos aguentar mentalmente por muito mais tempo, e O Caminho da Mecha montanha abaixo já está intransitável... É tarde demais para fugir agora. Temos que destruí-lo."
  },
  AvgDialog_6788_Content_5 = {
    Text = "Entendido... Nós vamos detê-lo. Vamos sair daqui vivos!"
  },
  AvgDialog_6788_Content_6 = {
    Text = "Você e Lily seguiram os passos Dela, um após o outro. Um som de Sussurros surgiu, e a montanha de Neve branca e pura estava repleta de pequenos Monstros ferozes."
  },
  AvgDialog_6788_Content_7 = {
    Text = "Para defender o núcleo, aquele monstro está realmente dando tudo de si..."
  },
  AvgDialog_6788_Content_8 = {
    Text = "%player%, cuide-se."
  },
  AvgDialog_6798_Content_1 = {
    Text = "Noite fria e longa"
  },
  AvgDialog_6798_Content_10 = {
    Text = "Se a força mental daqueles Investigadores tivesse sido suficiente para deixar um Núcleo de prata, talvez você pudesse Despertá-los agora mesmo para responder a essa pergunta."
  },
  AvgDialog_6798_Content_100 = {
    Text = "Do lado de fora da tenda, onde as sentinelas deveriam estar posicionadas, Apenas algumas poças de Sangue quase coagulado restavam."
  },
  AvgDialog_6798_Content_101 = {
    Text = "Você sentiu como se tivesse sido mergulhado numa câmara de gelo. \"Acidentes\" continuavam a ocorrer um após o outro. Todas as manhãs eram de Dispersão do fedor de Sangue. Membros da equipe de inspeção desapareciam e morriam, um após o outro..."
  },
  AvgDialog_6798_Content_102 = {
    Text = "Como se pressentisse algo, você se virou de repente."
  },
  AvgDialog_6798_Content_103 = {
    Text = "Uma Sombra encapuzada desapareceu no vento e na Neve..."
  },
  AvgDialog_6798_Content_11 = {
    Text = "Que pena, aquelas pessoas Frágeis não deixaram nada para trás... Era como se tivessem sido Devoradas por Elworth."
  },
  AvgDialog_6798_Content_12 = {
    Text = "Mesmo que tenham sido enterrados pela Neve, dado o nível de equipamento que carregavam, não deveria ser impossível encontrar qualquer vestígio..."
  },
  AvgDialog_6798_Content_13 = {
    Text = "Ai... Helot, por que você parou? Viu alguma coisa?"
  },
  AvgDialog_6798_Content_14 = {
    Text = "Ela se virou e olhou fixamente na direção oposta à da marcha."
  },
  AvgDialog_6798_Content_15 = {Text = "Presa."},
  AvgDialog_6798_Content_16 = {
    Text = "Ela não disse muito mais, Apenas continuou virando a cabeça para trás, olhando para algum lugar em meio à vasta extensão de Neve branca, seus olhos transbordando de Empolgação e saudade."
  },
  AvgDialog_6798_Content_17 = {
    Text = "Você segue seu olhar e vislumbra uma figura sombria fugaz. Quando olha novamente, não há nada atrás de você além de vento e neve intermináveis."
  },
  AvgDialog_6798_Content_18 = {Text = "..."},
  AvgDialog_6798_Content_19 = {
    Text = "Comparado a subir a montanha, O Caminho da Mecha de descida provou ser ainda mais difícil de percorrer, e os Monstros tornaram-se cada vez mais densos."
  },
  AvgDialog_6798_Content_2 = {
    Text = "A situação é mais ou menos essa. Discuti com o guia e o Professor Avis. Temos informações insuficientes sobre Elworth, e continuar adiante é extremamente perigoso."
  },
  AvgDialog_6798_Content_20 = {
    Text = "Depois de limpar esta área de Monstros, vocês encontraram um local abrigado e facilmente defensável para montar acampamento, e organizaram uma rotação de vigília para a noite."
  },
  AvgDialog_6798_Content_21 = {
    Text = "Tendo passado pela Experiência de um dia inteiro de esforço excessivo, você não conseguiu resistir à pesada sonolência e caiu em um sono profundo..."
  },
  AvgDialog_6798_Content_22 = {Text = "..."},
  AvgDialog_6798_Content_23 = {
    Text = "Vozes Faint e confusas discutindo tiraram você dos seus Sonhos. Você levantou a aba da tenda, Apenas para Descobrir que as expressões de Todos eram assustadoramente sombrias."
  },
  AvgDialog_6798_Content_24 = {
    Text = "Não tinha sido combinado que você assumiria a vigília à meia-noite? Agora veja o que aconteceu — alguém desapareceu! Me diga, de quem é a culpa?!"
  },
  AvgDialog_6798_Content_25 = {
    Text = "A noite passada era de fato para ser meu turno, mas... mas o assistente de geologia que estava de vigília antes de mim me disse para dormir mais um pouco, e que viria me acordar quando fosse a hora."
  },
  AvgDialog_6798_Content_26 = {
    Text = "Mas pelo resto da noite inteira, ele nunca veio..."
  },
  AvgDialog_6798_Content_27 = {
    Text = "Há quanto tempo ele está desaparecido?"
  },
  AvgDialog_6798_Content_28 = {
    Text = "Todos viram você chegar, Como se agarrando-se a uma tábua de salvação."
  },
  AvgDialog_6798_Content_29 = {
    Text = "Ele não acordou a próxima pessoa quando era hora de trocar o turno à meia-noite, e agora desapareceu completamente. Estou um pouco preocupado..."
  },
  AvgDialog_6798_Content_3 = {
    Text = "Helot descerá a montanha conosco. Ela precisa de tratamento, e quando estiver mais calma, precisaremos perguntar a ela sobre Elworth também."
  },
  AvgDialog_6798_Content_30 = {
    Text = "Será que ele ficou com medo e nos abandonou, fugindo sozinho durante a noite?"
  },
  AvgDialog_6798_Content_31 = {
    Text = "Em um lugar como Elworth, Ações solo são puro suicídio. Ninguém apostaria com a própria vida..."
  },
  AvgDialog_6798_Content_32 = {
    Text = "Talvez ele esteja Apenas dando uma caminhada por perto... Ainda é cedo. Enquanto ainda podemos encontrar rastros dele, vamos procurá-lo."
  },
  AvgDialog_6798_Content_33 = {
    Text = "Estou nessa linha de trabalho há muito tempo. Se você quer sobreviver na montanha, nunca pode desistir facilmente de nenhum companheiro."
  },
  AvgDialog_6798_Content_34 = {
    Text = "Fingindo compostura, todos vocês seguiram as orientações do guia e procuraram cuidadosamente ao longo do Caminho."
  },
  AvgDialog_6798_Content_35 = {
    Text = "Agarrando-se a esperanças irreais, vocês preferiram acreditar que Este assistente de geologia ainda estava vivo."
  },
  AvgDialog_6798_Content_36 = {
    Text = "O-o que é aquilo?"
  },
  AvgDialog_6798_Content_37 = {
    Text = "Os membros da equipe de expedição voltaram seus olhares para frente em uníssono. Lá, no chão nevado ao longo do Caminho de descida, havia uma grande poça de Sangue vermelho vivo, coagulado."
  },
  AvgDialog_6798_Content_38 = {
    Text = "O corpo envolto em tecido estava despedaçado como um monte de lama."
  },
  AvgDialog_6798_Content_39 = {
    Text = "Tecido rasgado balançava ao vento e à Neve. Da Placa quebrada, você mal conseguiu distinguir as palavras \"Assistente de Geologia.\""
  },
  AvgDialog_6798_Content_4 = {Text = "..."},
  AvgDialog_6798_Content_40 = {
    Text = "Todos caíram em um silêncio aterrador mais uma vez. Lily sentiu-se inquieta ao redor dos Membros da equipe de inspeção de expressão sombria e inconscientemente agarrou sua mão."
  },
  AvgDialog_6798_Content_41 = {
    Text = "Eu avisei! Eu avisei todos vocês! O lugar de descanso do deus da montanha não tolerará forasteiros imundos perturbando-o. A montanha sagrada profanada Apenas pode ser purificada com o Sangue de vocês—"
  },
  AvgDialog_6798_Content_42 = {
    Text = "Ele Xingou todos vocês em um frenesi quase maníaco, rastejando e se prostrando no chão em uma postura bizarra, tentando desesperadamente implorar perdão por seus pecados."
  },
  AvgDialog_6798_Content_43 = {
    Text = "Os membros da expedição estavam todos aterrorizados pelo estado grotesco do corpo. O guia tentou acalmar Todos, mas gritos e medo continuaram a se Propagar pelo grupo."
  },
  AvgDialog_6798_Content_44 = {
    Text = "Enquanto os olhos de Todos estavam fixos no estado horrível do cadáver, você notou vários rastros estranhos. O chão coberto de Neve trazia vestígios de manchas de Sangue e marcas escuras deixadas por uma batalha feroz."
  },
  AvgDialog_6798_Content_45 = {
    Text = "Estranho... há sinais de luta perto do corpo. Parece que o combate foi intenso de ambos os lados."
  },
  AvgDialog_6798_Content_46 = {
    Text = "Senhorita Medicina, poderia me fazer o favor de realizar um exame simples no falecido?"
  },
  AvgDialog_6798_Content_47 = {
    Text = "Ela olhou ao redor para os membros que haviam caído em extrema ansiedade, assentiu e deu um passo à frente."
  },
  AvgDialog_6798_Content_48 = {
    Text = "Neste estágio, Apenas um exame externo básico pode ser realizado— as roupas na superfície do corpo estão rasgadas com ferimentos externos evidentes. O corpo inteiro apresenta fraturas cominutivas, suspeitas de terem sido causadas por Golpe pesado de força externa."
  },
  AvgDialog_6798_Content_49 = {
    Text = "Fraturas cominutivas... é possível que a morte tenha sido causada por uma queda?"
  },
  AvgDialog_6798_Content_5 = {
    Text = "No silêncio aterrador, olhares cheios de ressentimento, medo ou desprezo recaíram sobre você e Helot. Você sentiu os olhares deles perfurando suas costas."
  },
  AvgDialog_6798_Content_50 = {
    Text = "A diferença de elevação entre nosso acampamento e este local é inferior a três metros— longe de ser suficiente para causar fraturas cominutivas em todo o corpo. Podemos essencialmente descartar morte por queda."
  },
  AvgDialog_6798_Content_51 = {
    Text = "As condições atuais são limitadas, e o corpo está severamente danificado, tornando impossível determinar o ponto de Impacto. Mas uma coisa pode ser confirmada..."
  },
  AvgDialog_6798_Content_52 = {
    Text = "A médica pressionou os lábios firmemente, suas costas tremendo levemente. Você podia perceber que ela estava se fazendo de forte."
  },
  AvgDialog_6798_Content_53 = {
    Text = "Nenhum humano possui a capacidade de espancá-lo até este estado."
  },
  AvgDialog_6798_Content_54 = {
    Text = "No momento em que essas palavras foram ditas, um alvoroço irrompeu. Todos os olhares se voltaram para Helot. Ninguém conseguia esquecer a enorme bola de ferro que Ela havia arremessado casualmente, nem podiam esquecer a cena de Ela ferindo alguém."
  },
  AvgDialog_6798_Content_55 = {
    Text = "De uma perspectiva anatômica, eu também concordo com a avaliação da médica. Os ossos do falecido estão completamente despedaçados— de fato o resultado de morte por Impacto violento. A análise dela é sólida."
  },
  AvgDialog_6798_Content_56 = {
    Text = "É possível que isso tenha sido feito por uma criatura não humana?"
  },
  AvgDialog_6798_Content_57 = {
    Text = "O \"assassino\" escolheu não agir no acampamento, mas em vez disso atraiu a vítima para um local mais remoto para evitar alertar os que estavam no acampamento."
  },
  AvgDialog_6798_Content_58 = {
    Text = "Ações tão meticulosas só poderiam ser realizadas por uma criatura com inteligência quase humana. Mas de todas as criaturas mutantes que encontramos até agora, nenhuma delas é capaz disso."
  },
  AvgDialog_6798_Content_59 = {Text = "Então..."},
  AvgDialog_6798_Content_6 = {
    Text = "O guia que havia sido ferido por ela era um homem tranquilo. Ele apressadamente enrolou uma bandagem em si mesmo, não disse mais nada, tranquilizou a equipe de expedição com algumas palavras e começou a organizar a descida."
  },
  AvgDialog_6798_Content_60 = {
    Text = "Ele abriu as mãos, com uma expressão de impotência no rosto."
  },
  AvgDialog_6798_Content_61 = {
    Text = "De acordo com a análise do professor, parecia que Helot era realmente a única opção que se encaixava no perfil do perpetrador por trás deste incidente sangrento."
  },
  AvgDialog_6798_Content_62 = {Text = "..."},
  AvgDialog_6798_Content_63 = {
    Text = "Pela sua expressão, parece que você tem algumas reservas?"
  },
  AvgDialog_6798_Content_64 = {
    Text = "Mm... Helot tem virado a cabeça para trás com frequência, como se algo estivesse nos seguindo o tempo todo."
  },
  AvgDialog_6798_Content_65 = {
    Text = "Na noite passada, não senti nada anormal do outro lado do link. Acredito que Helot não é a verdadeira culpada."
  },
  AvgDialog_6798_Content_66 = {
    Text = "Confio no seu julgamento. Mas convencer os outros não será tão simples..."
  },
  AvgDialog_6798_Content_67 = {
    Text = "Ele olhou ao redor para as expressões nos rostos dos membros da equipe ao redor e abaixou a voz."
  },
  AvgDialog_6798_Content_68 = {
    Text = "Está escurecendo, e a temperatura externa não é mais adequada para seguir em frente... Vamos montar acampamento e fazer um descanso por enquanto."
  },
  AvgDialog_6798_Content_69 = {
    Text = "Quanto a Hilota..."
  },
  AvgDialog_6798_Content_7 = {
    Text = "A equipe de expedição havia coletado amostras durante a subida, e reuniram tanto espécimes quanto fósseis, mas nem um traço de alegria podia ser visto nos rostos de todos."
  },
  AvgDialog_6798_Content_70 = {
    Text = "Esta noite... eu vou vigiar Ela."
  },
  AvgDialog_6798_Content_71 = {Text = "..."},
  AvgDialog_6798_Content_72 = {
    Text = "Do lado de fora da tenda, apenas a fogueira permanecia, com vozes abafadas ocasionais de conversa e sons de ferramentas sendo usadas."
  },
  AvgDialog_6798_Content_73 = {
    Text = "Alguns dos pesquisadores mais frágeis haviam amarrado juntas coisas encontradas por toda parte na montanha de Neve, transformando-as em machados e facas de pedra, colocando-os sob seus travesseiros para uma pequena medida de conforto."
  },
  AvgDialog_6798_Content_74 = {
    Text = "Outros haviam abandonado completamente a razão, dedicando-se a imitar as posturas que as pessoas locais haviam usado para apaziguar os deuses, prostrando-se no chão, rastejando em movimentos estranhos e laboriosos..."
  },
  AvgDialog_6798_Content_75 = {
    Text = "De tempos em tempos, olhares hostis eram lançados em direção à sua tenda."
  },
  AvgDialog_6798_Content_76 = {
    Text = "A aba da tenda foi levantada, e duas figuras entraram."
  },
  AvgDialog_6798_Content_77 = {
    Text = "Em vez de tropeçar sem rumo, o que todos mais precisam em uma situação desesperadora é um inimigo imaginário, uma resposta. Se não Helot, seria outra pessoa."
  },
  AvgDialog_6798_Content_78 = {
    Text = "Helot ainda mantinha uma expressão fria, sem dizer uma palavra. A Loucura que você havia suprimido à força ardia nas profundezas de seus olhos."
  },
  AvgDialog_6798_Content_79 = {
    Text = "O guia se aproximou e deu um tapinha no seu ombro."
  },
  AvgDialog_6798_Content_8 = {
    Text = "Você se lembrou das palavras de Doll."
  },
  AvgDialog_6798_Content_80 = {
    Text = "Examinei a bola de corrente. Não corresponde às feridas no corpo. Helot não é a assassina, tenho certeza disso."
  },
  AvgDialog_6798_Content_81 = {
    Text = "Muito obrigado. Embora eu tenha sido ferido por um Hilota, ainda falo bem dela."
  },
  AvgDialog_6798_Content_82 = {
    Text = "Anos de Experiência me ensinaram que, num ambiente como este, nada é mais importante do que confiança."
  },
  AvgDialog_6798_Content_83 = {
    Text = "Você deveria ver aqueles cientistas. Eles adoram os deuses com mais Devoção do que qualquer Crença. Não confiam na ciência, não confiam nos companheiros, não confiam em si mesmos."
  },
  AvgDialog_6798_Content_84 = {
    Text = "O Medo da Criatura desconhecida reduziu a vontade deles a pó.\nDiante do desespero, que dignidade resta à ciência..."
  },
  AvgDialog_6798_Content_85 = {
    Text = "Ele soltou algumas risadas frias, os ombros tremendo violentamente — de diversão, frio, ou talvez medo."
  },
  AvgDialog_6798_Content_86 = {
    Text = "\"Pecadora\" \"Assassina\" \"Demônio\"... Nos poucos segundos em que a aba da tenda esteve aberta, essas palavras perfuraram seus ouvidos, impossíveis de ignorar mesmo que tentasse."
  },
  AvgDialog_6798_Content_87 = {
    Text = "Eles não estavam errados. Um monstro perigoso e sedento de sangue estava bem diante de você. Hesitação não é uma qualidade que um guerreiro deveria possuir."
  },
  AvgDialog_6798_Content_88 = {
    Text = "Eu sei que não foi você."
  },
  AvgDialog_6798_Content_89 = {
    Text = "Helot parou por um momento, então subitamente se aproximou de você, encontrando seu olhar."
  },
  AvgDialog_6798_Content_9 = {
    Text = "Após aquela comunicação, toda a equipe de expedição perdeu o contato."
  },
  AvgDialog_6798_Content_90 = {
    Text = "Ela entreabriu os lábios na sua direção, revelando dentes afiados numa expressão que era meio sorriso, meio rosnado."
  },
  AvgDialog_6798_Content_91 = {
    Text = "Tente controlar uma Besta, e tome cuidado para não ser devorado por ela."
  },
  AvgDialog_6798_Content_92 = {
    Text = "Não estou tentando controlar você, Apenas..."
  },
  AvgDialog_6798_Content_93 = {
    Text = "Ela soltou um leve murmúrio, virou a cabeça, e ficou olhando para a Neve e o vento do lado de fora da tenda."
  },
  AvgDialog_6798_Content_94 = {
    Text = "Ainda há minhas próprias coisas a fazer. Você me ajudou, então antes de partir, vou ajudá-lo uma vez."
  },
  AvgDialog_6798_Content_95 = {
    Text = "Esta montanha também é uma Besta. Ela está nos caçando... Mas em breve, eu vou Devorá-la!"
  },
  AvgDialog_6798_Content_96 = {
    Text = "Você para de prestar atenção nos delírios loucos dela."
  },
  AvgDialog_6798_Content_97 = {
    Text = "Você vigiou Helot durante a noite inteira sem ouvir nenhum som incomum. Talvez a morte horrível do Membros da equipe de inspeção ontem realmente tenha sido Apenas um acidente..."
  },
  AvgDialog_6798_Content_98 = {
    Text = "AAAAAAAAH— Monstro! É o monstro! Apareceu de novo!"
  },
  AvgDialog_6798_Content_99 = {
    Text = "Onde estão? Para onde foram?!"
  },
  AvgDialog_6810_Content_1 = {
    Text = "Pico de espinhos"
  },
  AvgDialog_6810_Content_10 = {
    Text = "Espinhos irrompem do muco em sua palma, perfurando seu antebraço até que ele fique pingando Sangue."
  },
  AvgDialog_6810_Content_11 = {
    Text = "Uma luz sinistra parpadeia em seus olhos. Seu perfil antes frio e distante é manchado por um sorriso perturbador."
  },
  AvgDialog_6810_Content_12 = {
    Text = "Sua Conectora não consegue mais suprimir isso... Este é o Apenas caminho!"
  },
  AvgDialog_6810_Content_13 = {
    Text = "Você ativa a chave de prata, enviando ondas de luz prateada em direção ao hilota frenético"
  },
  AvgDialog_6810_Content_14 = {
    Text = "Você fecha os olhos e mais uma vez excede sua Força mental, despejando cada última gota no link enquanto assume o controle Dela à força."
  },
  AvgDialog_6810_Content_15 = {
    Text = "Ela se acalma. Suas pupilas desfocadas recuperam o brilho. Quando seu olhar recai sobre seu antebraço encharcado de Sangue, ela entreabra os lábios, e então os pressiona firmemente."
  },
  AvgDialog_6810_Content_16 = {
    Text = "Você finalmente está acordado."
  },
  AvgDialog_6810_Content_17 = {
    Text = "O contragolpe das profundezas de sua psique surge como uma maré. Você sente uma exaustão avassaladora, sua aparência abatida tão pálida quanto o cenário eterno desta terra congelada."
  },
  AvgDialog_6810_Content_18 = {
    Text = "Você está bem... O que aconteceu?"
  },
  AvgDialog_6810_Content_19 = {
    Text = "Uma Invocação extremamente poderosa... Não conseguimos resistir..."
  },
  AvgDialog_6810_Content_2 = {
    Text = "Lily... Lily está com tanta dor..."
  },
  AvgDialog_6810_Content_20 = {
    Text = "O outro \"Shiro\" foi Devorado. Esta montanha... está prestes a Despertar."
  },
  AvgDialog_6810_Content_21 = {
    Text = "Antes mesmo que as palavras se dissipem, uma enorme Sombra passa sobre suas cabeças."
  },
  AvgDialog_6810_Content_22 = {
    Text = "Um vento Criminoso raspa seus corpos, e um frio de gelar os ossos se espalha de sob seus pés até o coração."
  },
  AvgDialog_6810_Content_23 = {
    Text = "É aquela coisa..."
  },
  AvgDialog_6810_Content_24 = {
    Text = "Sob o grotesco e aterrorizante monstro colossal, vocês são tão pequenos quanto um grão de Neve prestes a derreter."
  },
  AvgDialog_6810_Content_25 = {
    Text = "Mas o olhar do monstro não se demora em vocês por muito tempo. Em vez disso, ele se vira de forma antinatural, arrastando uma cauda de chama azul fluorescente enquanto voa em direção ao cume coberto de Neve."
  },
  AvgDialog_6810_Content_26 = {
    Text = "Chamas irrompem dezenas de metros acima do topo da montanha, seu brilho perfurando diretamente os céus."
  },
  AvgDialog_6810_Content_27 = {
    Text = "Ele... O que está fazendo?"
  },
  AvgDialog_6810_Content_28 = {
    Text = "Vários sons nítidos de gelo se estilhaçando ecoam. O gelo que envolvia Avis e o guia se parte, e eles gradualmente Despertam do frio extremo."
  },
  AvgDialog_6810_Content_29 = {
    Text = "Não consegue nem manter o congelamento profundo nessas pessoas. Parece que o monstro desviou a maior parte da sua Força para o topo da montanha. O que ele está planejando?"
  },
  AvgDialog_6810_Content_3 = {
    Text = "Lily se encolheu, segurando a cabeça em agonia."
  },
  AvgDialog_6810_Content_30 = {
    Text = "Ele tem realizado Ofertas vivas o tempo todo para Despertar a montanha de Neve adormecida, e a montanha de Neve, por sua vez, Chama a mim e a Lily para voltar, então..."
  },
  AvgDialog_6810_Content_31 = {
    Text = "Ele quer Oferecer vocês à montanha de Neve?! Precisamos sair daqui agora!"
  },
  AvgDialog_6810_Content_4 = {Text = "Lily?!"},
  AvgDialog_6810_Content_5 = {
    Text = "Você ignorou a dor em sua cabeça e foi até o lado de Lily para verificar como ela estava."
  },
  AvgDialog_6810_Content_6 = {Text = "Ngh..."},
  AvgDialog_6810_Content_7 = {
    Text = "Um forte baque, e Helot colapsa no chão, seu rosto anteriormente sereno agora preenchido com dor."
  },
  AvgDialog_6810_Content_8 = {
    Text = "Helot? O que aconteceu..."
  },
  AvgDialog_6810_Content_9 = {
    Text = "Você se abaixa para verificar Shiro, mas ela agarra seu braço de repente."
  },
  AvgDialog_6811_Content_1 = {
    Text = "Visitante da planície nevada"
  },
  AvgDialog_6811_Content_10 = {
    Text = "É verdade. Ninguém pode recusar o Destino."
  },
  AvgDialog_6811_Content_100 = {
    Text = "Se a força mental daqueles Investigadores tivesse sido suficiente para deixar um Núcleo de prata, talvez você pudesse Despertá-los agora mesmo para responder a essa pergunta."
  },
  AvgDialog_6811_Content_101 = {
    Text = "Mas infelizmente, aqueles Frágeis não deixaram nada para trás...\nEles foram Apenas... Devorados por Elworth."
  },
  AvgDialog_6811_Content_102 = {
    Text = "Com Neve e vento tão intensos, talvez tenham sofrido um acidente e sido enterrados aqui."
  },
  AvgDialog_6811_Content_103 = {
    Text = "De qualquer forma, o perigo de Elworth excedeu nossos padrões predeterminados."
  },
  AvgDialog_6811_Content_104 = {
    Text = "A morte da expedição na montanha de Neve foi selada como um arquivo ultrassecreto por muito tempo. Não Apenas o Professor Dexter — eu também estou Apenas descobrindo isso agora."
  },
  AvgDialog_6811_Content_105 = {
    Text = "Isso foi uma falha da escola. Independentemente de você escolher continuar esta missão, a academia irá compensá-lo devidamente."
  },
  AvgDialog_6811_Content_106 = {
    Text = "Preciso descobrir o que o culto da Lanterna está buscando."
  },
  AvgDialog_6811_Content_107 = {
    Text = "Não consigo parar de me preocupar com Hilota."
  },
  AvgDialog_6811_Content_108 = {
    Text = "Dadas as circunstâncias... por preocupação com sua segurança, a escola contatou urgentemente um profissional — Professor Avis, um pesquisador da Universidade de Misag."
  },
  AvgDialog_6811_Content_109 = {
    Text = "Ele está atualmente com uma equipe de expedição externa conduzindo um levantamento científico em Elworth. O pico que estão se preparando para explorar também corresponde ao que Lily indicou, o que será de grande ajuda para encontrar Helot."
  },
  AvgDialog_6811_Content_11 = {
    Text = "Então o nosso acordo...?"
  },
  AvgDialog_6811_Content_110 = {
    Text = "Os membros dessa equipe possuem vasta Experiência e suprimentos. Viajar com eles aumentará muito suas chances de sobrevivência. E ter você e Lily como reforço de combate também será bom para eles."
  },
  AvgDialog_6811_Content_111 = {
    Text = "Você sabia que eu não escolheria desistir?"
  },
  AvgDialog_6811_Content_112 = {
    Text = "Não é a primeira vez."
  },
  AvgDialog_6811_Content_113 = {
    Text = "Não vou tentar mudar sua decisão, mas Misaq não pode se dar ao luxo de perder seu Guardião.\nCuide-se e volte com vida."
  },
  AvgDialog_6811_Content_12 = {
    Text = "Acordo. Você e aquela mulher louca da Lanterna me trouxeram até aqui, então vou dar uma mão enquanto estiver por aqui."
  },
  AvgDialog_6811_Content_13 = {
    Text = "Acho que há algo que eu deveria lhe lembrar."
  },
  AvgDialog_6811_Content_14 = {
    Text = "Seu Estado não está muito estável agora. Chegar perto desta montanha pode causar situações incontroláveis..."
  },
  AvgDialog_6811_Content_15 = {
    Text = "Faça o que quiser fazer. Apenas não fique no meu caminho."
  },
  AvgDialog_6811_Content_16 = {
    Text = "A presença da montanha, a presença Dela, eu consigo sentir tudo..."
  },
  AvgDialog_6811_Content_17 = {
    Text = "Eu vou matá-los, e depois, devorá-los."
  },
  AvgDialog_6811_Content_18 = {
    Text = "A menina lambeu os lábios, um sorriso de Besta se espalhando por seu rosto feroz."
  },
  AvgDialog_6811_Content_19 = {
    Text = "Quarenta milhas de distância."
  },
  AvgDialog_6811_Content_2 = {
    Text = "Um mês após o Evento Lemwashi"
  },
  AvgDialog_6811_Content_20 = {
    Text = "Flocos de neve grosseiros caíam, acumulando-se na cabeça da menina, tingindo seu Cabelo de um branco manchado."
  },
  AvgDialog_6811_Content_21 = {
    Text = "Você estendeu a mão e gentilmente os afastou."
  },
  AvgDialog_6811_Content_22 = {
    Text = "Você realmente não está com frio?"
  },
  AvgDialog_6811_Content_23 = {
    Text = "Lily hesitou por um momento, escondeu suas mãos avermelhadas atrás das costas e obedientemente balançou a cabeça."
  },
  AvgDialog_6811_Content_24 = {
    Text = "Corpos Despertos não morrem de frio."
  },
  AvgDialog_6811_Content_25 = {
    Text = "Me desculpe, Lily... Esta missão é especial. Obrigado por vir comigo a um lugar como este."
  },
  AvgDialog_6811_Content_26 = {
    Text = "Está tudo bem. Lily nasceu aqui. Lily quer ajudar {Male=Sr. Guardião,Female=Srta. Guardiã}..."
  },
  AvgDialog_6811_Content_27 = {
    Text = "Você suspirou, deu um tapinha na cabecinha empinada dela, levantou-se e contemplou o vasto mundo branco à frente."
  },
  AvgDialog_6811_Content_28 = {
    Text = "A Neve e o vento furiosos varriam o céu, caindo sobre as montanhas levemente ondulantes na borda das geleiras polares — caindo sobre o lugar para onde você se dirigia."
  },
  AvgDialog_6811_Content_29 = {
    Text = "Uma semana antes"
  },
  AvgDialog_6811_Content_3 = {
    Text = "Isto... é Elworth?"
  },
  AvgDialog_6811_Content_30 = {
    Text = "Terremotos, avalanches, explosões vulcânicas e Fusão além do alcance da vista... Este mundo realmente nunca descansa. Não se consegue nem encontrar tempo para apreciar uma bebida em paz."
  },
  AvgDialog_6811_Content_31 = {
    Text = "...Professor Dexter?"
  },
  AvgDialog_6811_Content_32 = {
    Text = "As chamas dançavam na lareira. O Homem de meia-idade bem-vestido pousou o jornal que tinha na mão e acenou para você se aproximar."
  },
  AvgDialog_6811_Content_33 = {
    Text = "Ah, você chegou! Por favor, sente-se."
  },
  AvgDialog_6811_Content_34 = {
    Text = "Professor, ouvi dizer que tinha algo urgente para mim?"
  },
  AvgDialog_6811_Content_35 = {
    Text = "Isso mesmo, absolutamente urgente."
  },
  AvgDialog_6811_Content_36 = {
    Text = "Depois que o fundo de caridade assumiu o Sanatório Rye, o trabalho de acompanhamento tem sido conduzido razoavelmente bem."
  },
  AvgDialog_6811_Content_37 = {
    Text = "A família de uma paciente é dona de uma vinícola. Para expressar sua gratidão, enviaram duas garrafas de um excelente vinho caseiro."
  },
  AvgDialog_6811_Content_38 = {
    Text = "É triste demais apreciá-las sozinho. O que me diz — quer Prove?"
  },
  AvgDialog_6811_Content_39 = {
    Text = "Olhando para a taça de vinho que ele oferecia, você soltou um suspiro de resignação."
  },
  AvgDialog_6811_Content_4 = {
    Text = "Isso mesmo. Bem-vindo ao lar, Helot."
  },
  AvgDialog_6811_Content_40 = {
    Text = "Professor, tenho estado muito ocupado(a) ultimamente... Se não há mais nada, vou indo."
  },
  AvgDialog_6811_Content_41 = {
    Text = "Uma vida sem saber como se aproveitar é uma vida sem prazer."
  },
  AvgDialog_6811_Content_42 = {
    Text = "Ah, há outro assunto. Trivial comparado à degustação de vinhos, talvez, mas acho que pode lhe interessar."
  },
  AvgDialog_6811_Content_43 = {Text = "O que?"},
  AvgDialog_6811_Content_44 = {
    Text = "Aquela pessoa amiga que enviou o vinho me contou que uma paciente tem apresentado anomalias. Seus gemidos e uivos Ecoam pelo hospital psiquiátrico dia e noite, e seu estado mental e Constituição em constante deterioração deixaram os Médicos completamente perdidos."
  },
  AvgDialog_6811_Content_45 = {
    Text = "Isso realmente parece terrível, mas eu realmente não tenho experiência na área de transtornos psiquiátricos..."
  },
  AvgDialog_6811_Content_46 = {
    Text = "Não se trata da área médica — talvez você não tenha esquecido que Uma jovem Corpo Desperto tem um link com uma paciente no hospital psiquiátrico Francis."
  },
  AvgDialog_6811_Content_47 = {
    Text = "Um som nauseante e úmido de dilaceração se ergue no ar. Enormes patas de aranha irrompem pelos corpos dos oficiais e dos transeuntes, espirrando sangue espesso com cheiro de ferro por todo você."
  },
  AvgDialog_6811_Content_48 = {
    Text = "Entregue ela... para mim!"
  },
  AvgDialog_6811_Content_49 = {
    Text = "Patético. Apenas perder um link de Prata te reduz a isso."
  },
  AvgDialog_6811_Content_5 = {
    Text = "A montanha que você quer alcançar, a pessoa que você quer ver — estão todas aqui."
  },
  AvgDialog_6811_Content_50 = {
    Text = "Francis está vinculada a Lily, então o vinculador de Helot..."
  },
  AvgDialog_6811_Content_51 = {
    Text = "Doll uma vez mencionou em seu curso \"Fundamentos de Criação e Link de Corpos Despertos\" que, deixando de lado os efeitos colaterais de não poder comandá-los e controlá-los, os sujeitos de link ideais para Corpos Despertos são os pacientes deste próprio Sanatório."
  },
  AvgDialog_6811_Content_52 = {
    Text = "Os pacientes do Sanatório...?\nPorque suas mentes são instáveis, eles não têm medo de perder o controle?"
  },
  AvgDialog_6811_Content_53 = {
    Text = "Helot está sozinha no cais, seu cabelo longo dançando ao vento."
  },
  AvgDialog_6811_Content_54 = {
    Text = "O navio está partindo. Vai embarcar?"
  },
  AvgDialog_6811_Content_55 = {
    Text = "Helot acena, sinalizando para a balsa partir sem ela.\nEla ainda não decidiu seu próximo destino."
  },
  AvgDialog_6811_Content_56 = {
    Text = "Helot... Ela desapareceu depois de deixar o Sanatório. Aconteceu alguma coisa?"
  },
  AvgDialog_6811_Content_57 = {Text = "Olhe isto."},
  AvgDialog_6811_Content_58 = {
    Text = "Um jornal ainda com cheiro de tinta fresca foi colocado à sua frente."
  },
  AvgDialog_6811_Content_59 = {
    Text = "\"Uma avalanche massiva atingiu o Campo de Neve polar Elworth De @2/@2/@2. Lembre-se de que foi medida como a maior já registrada, causa desconhecida...\""
  },
  AvgDialog_6811_Content_6 = {
    Text = "Herbert estendeu a mão, apontando para as montanhas cobertas de neve à frente."
  },
  AvgDialog_6811_Content_60 = {
    Text = "El... worth?"
  },
  AvgDialog_6811_Content_61 = {
    Text = "Sob a influência do Corpo Desperto Helot, o paciente do hospital psiquiátrico tem gritado o nome do Campo de Neve alpino onde uma avalanche ocorreu recentemente—Elworth."
  },
  AvgDialog_6811_Content_62 = {
    Text = "E depois há aquelas visões que você viu em seu Sonho. Bastante memoráveis, não foram?"
  },
  AvgDialog_6811_Content_63 = {
    Text = "As visões do Sonho, o paradeiro de Helot e esta avalanche anômala—tudo aponta para lá..."
  },
  AvgDialog_6811_Content_64 = {
    Text = "Símbolos da Igreja da Luz do Templo apareceram no sonho. O que eles vão fazer pode estar relacionado aos Hilotas."
  },
  AvgDialog_6811_Content_65 = {
    Text = "Exatamente. Sempre há aqueles neste mundo que não têm nenhum senso de tato e adoram perturbar a vida dos outros."
  },
  AvgDialog_6811_Content_66 = {
    Text = "Descobrirei o que aconteceu em Elworth"
  },
  AvgDialog_6811_Content_67 = {
    Text = "Encontrarei Hilota"
  },
  AvgDialog_6811_Content_68 = {
    Text = "Entendido. O tempo é essencial. Vou me preparar para partir para Elworth imediatamente."
  },
  AvgDialog_6811_Content_69 = {
    Text = "Não foi isso que eu quis dizer... Ei?"
  },
  AvgDialog_6811_Content_7 = {
    Text = "Você tem certeza de que ela vai aparecer?"
  },
  AvgDialog_6811_Content_70 = {
    Text = "Eu realmente não entendo por que todos estão sempre com tanta pressa. No mínimo, termine esta bebida primeiro..."
  },
  AvgDialog_6811_Content_71 = {
    Text = "A bebida diante dele foi engolida de um gole só. Segurando o copo vazio, ele o acenou suavemente em direção à Porta."
  },
  AvgDialog_6811_Content_72 = {
    Text = "Que a Chave de Prata ilumine o seu caminho, Guardião."
  },
  AvgDialog_6811_Content_73 = {
    Text = "Guardião, como estão as coisas?"
  },
  AvgDialog_6811_Content_74 = {
    Text = "Chegamos ao campo de gelo de Elworth. A situação está estável."
  },
  AvgDialog_6811_Content_75 = {
    Text = "Como você suspeitava, Lily consegue sentir vagamente as flutuações da Força de mesma Fonte e encontrar a direção certa."
  },
  AvgDialog_6811_Content_76 = {
    Text = "Aconteceu algo incomum durante a viagem?"
  },
  AvgDialog_6811_Content_77 = {
    Text = "Sem anomalias, apenas navegando por mares repletos de gelo quebrado, orando diariamente para que os ventos rugentes não afundem o navio... Incerto sobre por que tanto a Igreja da Luz do Templo quanto o Hilota estão de olho neste lugar."
  },
  AvgDialog_6811_Content_78 = {
    Text = "No entanto, os moradores locais não parecem muito receptivos à nossa chegada. Ficam gritando coisas incoerentes sobre deuses da montanha, Monstros e coisas do tipo."
  },
  AvgDialog_6811_Content_79 = {
    Text = "Há algo que preciso informá-lo. A aprovação para esta viagem foi extremamente apressada, e não houve tempo suficiente para conduzir uma investigação preliminar detalhada antes."
  },
  AvgDialog_6811_Content_8 = {
    Text = "Tão certamente quanto você apareceu aqui. É a Invocação do Destino.\nNinguém pode recusar o Destino, pode?"
  },
  AvgDialog_6811_Content_80 = {
    Text = "Estive nos arquivos nos últimos dias e encontrei um documento sobre Elworth. Ele menciona que Acima..."
  },
  AvgDialog_6811_Content_81 = {
    Text = "Você estava conversando com Doll quando notou Lily caminhando em direção a um buraco."
  },
  AvgDialog_6811_Content_82 = {
    Text = "Lily, cuidado. Não caia aí dentro."
  },
  AvgDialog_6811_Content_83 = {
    Text = "Lily caminhou alguns passos em direção à distância e se agachou curiosamente."
  },
  AvgDialog_6811_Content_84 = {
    Text = "Tem... um som..."
  },
  AvgDialog_6811_Content_85 = {
    Text = "Você se aproximou. A água do mar estava sendo agitada por algo desconhecido, emitindo um estrondo abafado através da camada translúcida de gelo."
  },
  AvgDialog_6811_Content_86 = {
    Text = "Uma Sombra borrada apareceu subitamente sob o gelo, crescendo em tamanho a uma velocidade alarmante..."
  },
  AvgDialog_6811_Content_87 = {Text = "Perigo!"},
  AvgDialog_6811_Content_88 = {
    Text = "Você rapidamente puxou a menina para longe da beira do abismo. O gelo se estilhaçou sob seus pés enquanto várias criaturas polares, grotescamente enormes, irromperam pela camada de gelo, contorcendo seus corpos desproporcionais enquanto escalavam para fora."
  },
  AvgDialog_6811_Content_89 = {
    Text = "Pústulas negras e sinistras escorriam por baixo de seus pelos, algo se agitando dentro delas, emanando o fedor de Podridão."
  },
  AvgDialog_6811_Content_9 = {
    Text = "Ao ouvir isso, a menina sorriu, revelando duas presas afiadas."
  },
  AvgDialog_6811_Content_90 = {
    Text = "Gritos agudos e roucos ecoaram. Os Monstros encaravam você com olhos corroídos por Pústulas, transbordando hostilidade primitiva."
  },
  AvgDialog_6811_Content_91 = {
    Text = "Criaturas deformadas pela Fusão... Lily, cuidado!"
  },
  AvgDialog_6811_Content_92 = {
    Text = "A chave de prata em mãos emitiu um brilho suave. Uma esfera negra bloqueou à frente de Lily, esmagando os Monstros de origem desconhecida."
  },
  AvgDialog_6811_Content_93 = {
    Text = "Desviando da Força de ataque desesperada dos Monstros em seus momentos finais, você soltou um suspiro pesado."
  },
  AvgDialog_6811_Content_94 = {
    Text = "Todos os inimigos eliminados... Doll, o que eram aquelas Criaturas desconhecidas?"
  },
  AvgDialog_6811_Content_95 = {
    Text = "Apenas descobri agora, depois de consultar os arquivos. Misaq uma vez enviou uma equipe de cientistas e Investigadores para conduzir uma expedição secreta a Elworth. Eles também encontraram e documentaram essas criaturas deformadas."
  },
  AvgDialog_6811_Content_96 = {
    Text = "Nos registros enviados pela expedição, havia alguma menção ao \"Deus da Montanha\"? Continuo suspeitando que isso tem algo a ver com Helot."
  },
  AvgDialog_6811_Content_97 = {
    Text = "Infelizmente, os arquivos da expedição secreta são tão vazios quanto o cérebro de certas pessoas."
  },
  AvgDialog_6811_Content_98 = {
    Text = "Eles não conseguiram produzir nenhuma descoberta? Ainda há algumas perguntas que gostaria de fazer a eles. Posso falar com eles diretamente?"
  },
  AvgDialog_6811_Content_99 = {
    Text = "O outro lado da linha ficou em silêncio por um momento."
  },
  AvgDialog_6812_Content_1 = {
    Text = "Sacrifício"
  },
  AvgDialog_6812_Content_10 = {
    Text = "Alguns alpinistas sem muita sorte."
  },
  AvgDialog_6812_Content_100 = {Text = "Boom——"},
  AvgDialog_6812_Content_101 = {
    Text = "Fumaça e poeira se misturavam com partículas de Neve, dispersando-se em Dispersão diante de seus olhos."
  },
  AvgDialog_6812_Content_102 = {
    Text = "O corredor negro como breu foi forçosamente partido ao meio, e a luz branca e brilhante da Neve caiu sobre seus ombros."
  },
  AvgDialog_6812_Content_103 = {
    Text = "Segure-se firme. Vou tirar você daí."
  },
  AvgDialog_6812_Content_104 = {
    Text = "Ela despedaçou a rocha da caverna e puxou você para fora dos escombros."
  },
  AvgDialog_6812_Content_105 = {
    Text = "O favor que te devo... considere pago..."
  },
  AvgDialog_6812_Content_106 = {Text = "...Ahh!!"},
  AvgDialog_6812_Content_107 = {
    Text = "Hilota!!..."
  },
  AvgDialog_6812_Content_108 = {
    Text = "Antes que as palavras sequer saíssem de seus lábios, ela de repente pisou no vazio."
  },
  AvgDialog_6812_Content_109 = {
    Text = "— O chão que na memória fora uma encosta desapareceu no ar, transformando-se em um instante em um abismo sem fundo."
  },
  AvgDialog_6812_Content_11 = {
    Text = "Porque é que estes corpos estão Dentro das paredes? As paredes conseguem... Devorar pessoas?"
  },
  AvgDialog_6812_Content_12 = {
    Text = "Já temos preocupações suficientes neste momento. Vamos continuar a andar."
  },
  AvgDialog_6812_Content_13 = {Text = "..."},
  AvgDialog_6812_Content_14 = {
    Text = "...O cheiro aqui é um pouco estranho. É semelhante ao fedor que notámos antes, mas muito mais forte. Talvez esteja relacionado com atividade vulcânica."
  },
  AvgDialog_6812_Content_15 = {
    Text = "Talvez estejamos a aproximar-nos da cratera vulcânica."
  },
  AvgDialog_6812_Content_16 = {
    Text = "Este cheiro... é de certa forma familiar..."
  },
  AvgDialog_6812_Content_17 = {
    Text = "As paredes estão a emanar calor. Esta caverna é bastante invulgar."
  },
  AvgDialog_6812_Content_18 = {
    Text = "É assim? Deixe-me sentir isso."
  },
  AvgDialog_6812_Content_19 = {
    Text = "Hm? Helot, o que é que acabaste de tirar de cima de mim?"
  },
  AvgDialog_6812_Content_2 = {
    Text = "Você escalou a face rochosa glacial onde quase não havia onde apoiar os pés e, seguindo a tênue percepção que Helot tinha de Lily, espremeu-se nesta fenda na rocha."
  },
  AvgDialog_6812_Content_20 = {
    Text = "Uma coisa imunda que caiu em cima de ti."
  },
  AvgDialog_6812_Content_21 = {
    Text = "Um som nauseante e úmido de dilaceração se ergue no ar. Enormes patas de aranha irrompem pelos corpos dos oficiais e dos transeuntes, espirrando sangue espesso com cheiro de ferro por todo você."
  },
  AvgDialog_6812_Content_22 = {
    Text = "Ela sacudiu as pequenas Pústulas negras da mão para a parede e trespassou-as com a espada."
  },
  AvgDialog_6812_Content_23 = {Text = "Vamos."},
  AvgDialog_6812_Content_24 = {Text = "..."},
  AvgDialog_6812_Content_25 = {
    Text = "Quanto mais fundo Dentro vamos, mais forte fica o fedor... Oh, desculpa, esbarrei em ti."
  },
  AvgDialog_6812_Content_26 = {
    Text = "Aproxima-te mais e sofrerás as consequências, humano."
  },
  AvgDialog_6812_Content_27 = {
    Text = "Eu realmente não consigo evitar. O Caminho continua ficando mais estreito... E essas paredes parecem estar se movendo..."
  },
  AvgDialog_6812_Content_28 = {
    Text = "Next time, come up with a better excuse."
  },
  AvgDialog_6812_Content_29 = {
    Text = "<Small:Ugh... Aaaaah... Por favor, nos Liberar... nos deixem ir...>"
  },
  AvgDialog_6812_Content_3 = {
    Text = "Uma fenda Dentro de uma geleira deveria estar repleta de gelo e Neve, mas a temperatura aqui não era nada baixa. Havia até um musgo perturbador agarrado às paredes internas."
  },
  AvgDialog_6812_Content_30 = {
    Text = "Uma voz fraca veio das Profundezas da caverna."
  },
  AvgDialog_6812_Content_31 = {
    Text = "Tem alguém Dentro! Finalmente os encontramos!"
  },
  AvgDialog_6812_Content_32 = {
    Text = "Apenas quando você estava prestes a avançar mais fundo, uma mão agarrou seu braço. Helot balançou a cabeça para você com uma expressão grave."
  },
  AvgDialog_6812_Content_33 = {
    Text = "Você está certo... As paredes estão se fechando. Se formos mais fundo, não conseguiremos sair."
  },
  AvgDialog_6812_Content_34 = {
    Text = "Como se respondesse às palavras Dela, as paredes começaram a se contorcer lentamente."
  },
  AvgDialog_6812_Content_35 = {
    Text = "Uma mão corrompida emergiu lentamente da parede, seguida por uma coxa, um crânio..."
  },
  AvgDialog_6812_Content_36 = {
    Text = "Incontáveis pedaços de cadáveres surgiram das paredes—alguns Apenas ossos brancos expostos, outros ainda com carne apodrecida."
  },
  AvgDialog_6812_Content_37 = {
    Text = "Membros decepados e manchados de diferentes montanhistas desabrocharam lentamente diante de você, como uma flor cruel de decomposição."
  },
  AvgDialog_6812_Content_38 = {
    Text = "O que é isso?!..."
  },
  AvgDialog_6812_Content_39 = {
    Text = "Então... esta é a origem do fedor..."
  },
  AvgDialog_6812_Content_4 = {
    Text = "Foi mesmo certo deixar Ela lá para trás?"
  },
  AvgDialog_6812_Content_40 = {
    Text = "Se nós dois entrarmos, talvez não consigamos sair. Helot, espere aqui por mim!"
  },
  AvgDialog_6812_Content_41 = {Text = "Ei...!"},
  AvgDialog_6812_Content_42 = {
    Text = "Antes que as palavras Dela terminassem, você se soltou da mão dela e mergulhou de cabeça no corredor escuro e fétido."
  },
  AvgDialog_6812_Content_43 = {Text = "..."},
  AvgDialog_6812_Content_44 = {
    Text = "Lily! Professora Avis! Guia! Onde vocês estão?"
  },
  AvgDialog_6812_Content_45 = {
    Text = "Ao grande @3... nós oferecemos... tributo..."
  },
  AvgDialog_6812_Content_46 = {
    Text = "Seguindo o som, você adentrou as profundezas da caverna, onde incontáveis rochas e Espinhos convergiam, cercando um altar negro como breu."
  },
  AvgDialog_6812_Content_47 = {
    Text = "Sobre o altar havia várias figuras humanas vermelho-escuras, encolhidas e ajoelhadas no chão, já desprovidas de qualquer sinal de vida."
  },
  AvgDialog_6812_Content_48 = {
    Text = "Ainda um passo atrasados..."
  },
  AvgDialog_6812_Content_49 = {
    Text = "Você espiou por entre as sombras do corredor e olhou para cima, para onde as pessoas estavam prostradas em adoração."
  },
  AvgDialog_6812_Content_5 = {
    Text = "Foi escolha dela."
  },
  AvgDialog_6812_Content_50 = {
    Text = "Há uma ruptura antinatural na cúpula. Dentro da rocha oca flutua aquele monstro azul brilhante, marcado com o emblema da Igreja do Templo que você encontrou uma vez."
  },
  AvgDialog_6812_Content_51 = {
    Text = "Era uma criatura incomparavelmente horrível e massiva, e esta foi a primeira vez que você pôde examinar sua aparência de perto."
  },
  AvgDialog_6812_Content_52 = {
    Text = "Sua estrutura esquelética exposta lembrava a de um artrópode, com a superfície coberta por uma camada de gelo. No centro de seu corpo pulsava um aglomerado de chamas azuis peculiares, emanando um frio que induzia asfixia."
  },
  AvgDialog_6812_Content_53 = {Text = "Roar..."},
  AvgDialog_6812_Content_54 = {
    Text = "Aquelas Pústulas de novo. Isso é problema..."
  },
  AvgDialog_6812_Content_55 = {
    Text = "Não ouse machucar {Male=Sr. Guardião,Female=Srta. Guardiã}!"
  },
  AvgDialog_6812_Content_57 = {
    Text = "Orbes negros apareceram diante de você, esmagando as Pústulas que avançavam em sua direção, transformando–as em poças de líquido imundo."
  },
  AvgDialog_6812_Content_58 = {
    Text = "Lily?! Você está bem?"
  },
  AvgDialog_6812_Content_59 = {
    Text = "Lily está bem. Aquela coisa ruim é a assassina."
  },
  AvgDialog_6812_Content_6 = {
    Text = "Ela estar lá pelo menos nos está a dar tempo. Precisamos de nos apressar... Ah!"
  },
  AvgDialog_6812_Content_60 = {
    Text = "Lily se espremeu por uma fenda, suas pequenas mãos arrastando uma longa corda de escalada, cuja outra ponta estava presa a dois adultos, firmemente amarrados e incapazes de se mover."
  },
  AvgDialog_6812_Content_61 = {
    Text = "Eles foram todos congelados por essa coisa ruim, mas ainda não estão mortos. Lily lembra o que {Male=Sr. Guardião,Female=Srta. Guardiã} disse — Lily tem que protegê–los."
  },
  AvgDialog_6812_Content_62 = {
    Text = "Mas Lily não lembra O Caminho da Mecha, e fez uma curva errada, e foi assim que Lily acabou aqui..."
  },
  AvgDialog_6812_Content_63 = {
    Text = "Lily, você sabe onde é este lugar?"
  },
  AvgDialog_6812_Content_64 = {
    Text = "Lily olhou para cima, fitando inocentemente o monstro encolhido acima de sua cabeça."
  },
  AvgDialog_6812_Content_65 = {
    Text = "Isso é... hm, onde o monstro dorme."
  },
  AvgDialog_6812_Content_66 = {
    Text = "Os falecidos no altar estavam cobertos de manchas de Sangue. Ao olhar mais de perto, eram todos rostos familiares — Membros da equipe de inspeção que haviam desaparecido anteriormente."
  },
  AvgDialog_6812_Content_67 = {
    Text = "Você saiu do corredor com Lily, serpenteando entre os escombros. Sem alertar o monstro, vocês conseguiram se aproximar do altar."
  },
  AvgDialog_6812_Content_68 = {
    Text = "Essa coisa provavelmente está planejando uma Oferta humana viva."
  },
  AvgDialog_6812_Content_69 = {
    Text = "Um... o quê?"
  },
  AvgDialog_6812_Content_7 = {
    Text = "Tropeçaste num pedaço de osso branco que se projetava do chão, mas Helot apanhou-te com reflexos rápidos e puxou-te de volta."
  },
  AvgDialog_6812_Content_70 = {
    Text = "Através do sacrifício humano, desperte um ser controlado pela Igreja da Luz do Templo. Eles pretendem trazer de volta uma criatura que não deveria existir no mundo."
  },
  AvgDialog_6812_Content_71 = {
    Text = "Essa coisa... o que é exatamente?"
  },
  AvgDialog_6812_Content_72 = {
    Text = "Não tenho certeza. Apenas mencionaram esse tipo de Ritual ao vivo nas aulas..."
  },
  AvgDialog_6812_Content_73 = {
    Text = "Parece que Aquela pessoa a quem o monstro faz Sacrifícios a Deus é muito exigente com as Ofertas, e é por isso que há Apenas algumas pessoas aqui."
  },
  AvgDialog_6812_Content_74 = {
    Text = "Os Membros da equipe de inspeção que foram mortos antes — as múltiplas feridas em seus corpos e as fraturas cominutivas por todo o corpo — eles eram Apenas... Ofertas indesejadas, então podiam ser descartados à vontade."
  },
  AvgDialog_6812_Content_75 = {
    Text = "Ao enfrentar criaturas que podiam esmagar com facilidade, não conseguiam sequer poupar um fio de piedosa misericórdia."
  },
  AvgDialog_6812_Content_76 = {
    Text = "Você cerrou os dentes, tentando não deixar a raiva e a tristeza nublarem seu julgamento. Lily sentiu suas emoções e se aproximou mais, tentando lhe oferecer algum conforto."
  },
  AvgDialog_6812_Content_77 = {
    Text = "Após um momento de silêncio, você afaga a cabeça de Lily. Uma sensação calorosa se espalha pela sua pele — uma vida tão vibrante."
  },
  AvgDialog_6812_Content_78 = {
    Text = "Lily, agora, precisamos levar os vivos para casa."
  },
  AvgDialog_6812_Content_79 = {
    Text = "Arraste-os para longe, sim, assim mesmo... Espere, cuidado!"
  },
  AvgDialog_6812_Content_8 = {
    Text = "O que te fez tropeçar era um osso completo de perna humana incrustado na parede, como se fossem os restos deixados para trás depois de a parede rochosa o ter Devorado."
  },
  AvgDialog_6812_Content_80 = {
    Text = "Lily usou força demais ao arrastar o corpo, e a forma humana semelhante a uma escultura de gelo bateu com força contra os escombros. Chamas azuis fluorescentes subitamente se acenderam atrás de você."
  },
  AvgDialog_6812_Content_81 = {
    Text = "Não é bom, nos descobriu!"
  },
  AvgDialog_6812_Content_82 = {
    Text = "O vento gélido cortou suas bochechas como uma Lâmina afiada. O monstro expeliu uma névoa gelada, então voltou seu olhar para você nas sombras, esticando seus ossos enquanto se aproximava."
  },
  AvgDialog_6812_Content_83 = {
    Text = "...Para trás!"
  },
  AvgDialog_6812_Content_84 = {Text = "Rugido—"},
  AvgDialog_6812_Content_85 = {
    Text = "Lily manipulou a enorme esfera, esmagando o monstro gigantesco contra a parede. Ele soltou um uivo de raiva."
  },
  AvgDialog_6812_Content_86 = {
    Text = "Você arrastou os dois Membros da equipe de inspeção mal vivos e correu para o corredor."
  },
  AvgDialog_6812_Content_87 = {
    Text = "Rápido! Por aqui!"
  },
  AvgDialog_6812_Content_88 = {
    Text = "Vocês estavam quase correndo por suas vidas, seus passos ficando mais pesados a cada passada, mas o monstro logo recuperaria sua capacidade de se mover. Vocês absolutamente não podiam parar."
  },
  AvgDialog_6812_Content_89 = {Text = "@3..."},
  AvgDialog_6812_Content_9 = {
    Text = "O-O que é isto?!"
  },
  AvgDialog_6812_Content_90 = {
    Text = "Como se exalasse um sopro fétido, a montanha soltou um estrondo profundo e trovejante, então começou a tremer e contrair violentamente, derrubando vocês no chão."
  },
  AvgDialog_6812_Content_91 = {
    Text = "O quê... o que está acontecendo?!"
  },
  AvgDialog_6812_Content_92 = {
    Text = "Não havia tempo para pensar. O instinto de sobrevivência o impulsionou para frente, rastejando de quatro pelo muco secretado pela caverna, avançando em direção à saída que se fechava lentamente."
  },
  AvgDialog_6812_Content_93 = {
    Text = "quase lá, logo ali adiante—"
  },
  AvgDialog_6812_Content_94 = {
    Text = "<Big:BOOM—>"
  },
  AvgDialog_6812_Content_95 = {
    Text = "A montanha inteira virou completamente de cabeça para baixo. O ângulo do corredor mudou abruptamente, inclinando-se bruscamente para baixo."
  },
  AvgDialog_6812_Content_96 = {
    Text = "O muco sob você era impossivelmente escorregadio. Você lutou para se arrastar em direção à luz na abertura, mas as contrações do corredor se tornavam cada vez mais violentas."
  },
  AvgDialog_6812_Content_97 = {
    Text = "As lajes de rocha quente continuavam se contraindo, esmagando seu peito. Você sentia o ar ficando cada vez mais rarefeito. Até o corpo de Lily estava preso nas fendas, incapaz de se mover."
  },
  AvgDialog_6812_Content_98 = {
    Text = "A única saída foi gradualmente Devorada pela rocha negra como breu. O Caminho tão próximo foi cortado, e sua visão mergulhou em uma escuridão de desespero absoluto."
  },
  AvgDialog_6812_Content_99 = {
    Text = "Não posso... não aqui..."
  },
  AvgDialog_6813_Content_1 = {
    Text = "O monstro Distorcido foi abatido sobre o gelo, cavando uma trincheira semelhante a um abismo. Ele zumbiu, lutando para se erguer várias vezes apenas para desabar pesadamente de volta ao chão."
  },
  AvgDialog_6813_Content_10 = {
    Text = "Está Invocando Força da mesma Fonte Primordial. Se nos Devorar, nossos espíritos se fundirão com ele..."
  },
  AvgDialog_6813_Content_11 = {
    Text = "Helot fechou os olhos. Os fragmentos que já haviam se dissipado se reuniram mais uma vez em sua mente."
  },
  AvgDialog_6813_Content_12 = {
    Text = "E se eu for quem o Devorar?"
  },
  AvgDialog_6813_Content_13 = {
    Text = "Ela quer me Devorar, drenar minha Força. Então o inverso também deve ser verdade—eu posso Devorá-la!"
  },
  AvgDialog_6813_Content_14 = {
    Text = "Helot Abriu os olhos mais uma vez."
  },
  AvgDialog_6813_Content_15 = {
    Text = "O único caminho é fazer como a outra \"Shiro\" fez—tentar Devorar a Força da montanha de Neve..."
  },
  AvgDialog_6813_Content_16 = {
    Text = "Helot se abaixou e, imitando o jeito que você faz, desajeitadamente acariciou o topo macio da cabeça de Lily."
  },
  AvgDialog_6813_Content_17 = {
    Text = "Lily já estava meio afundada na encosta da montanha. Sem controle, lágrimas negras como breu escorriam por seu rosto enquanto ela encarava Helot com o olhar vazio."
  },
  AvgDialog_6813_Content_18 = {
    Text = "Ela já suportou sofrimento demais. Deixe-me assumir daqui."
  },
  AvgDialog_6813_Content_19 = {
    Text = "Não... não, não pode acabar assim... Tem que haver outro caminho..."
  },
  AvgDialog_6813_Content_2 = {
    Text = "Embora já estivesse em seu último suspiro, a chama atrás dele continuava a Queimar incessantemente, crescendo cada vez mais, quase prestes a Devorar a própria criatura."
  },
  AvgDialog_6813_Content_20 = {
    Text = "Não há mais tempo, Guardião."
  },
  AvgDialog_6813_Content_21 = {
    Text = "Se eu quero que todos vocês saiam de Elworth vivos, se eu não quero me transformar em um monstro na frente de vocês de novo, este é o Apenas caminho..."
  },
  AvgDialog_6813_Content_22 = {
    Text = "Você vai morrer aqui!"
  },
  AvgDialog_6813_Content_23 = {
    Text = "\"Mesmo assim... o que importa?\""
  },
  AvgDialog_6813_Content_25 = {
    Text = "Ela cravou sua lâmina na rocha. Mechas encharcadas de cabelo pendiam diante de seu rosto, congelando rapidamente em estilhaços de gelo que balançavam com seus ombros trêmulos."
  },
  AvgDialog_6813_Content_26 = {
    Text = "O vento amargo da montanha de Neve rugia sem fim, e estrondos abafados ecoavam um após o outro."
  },
  AvgDialog_6813_Content_27 = {
    Text = "Ondas de dor abrasadora a assaltavam, mas neste momento, a voz em sua mente estava mais clara do que nunca."
  },
  AvgDialog_6813_Content_28 = {
    Text = "Há tantas coisas que eu nunca quis fazer... tantas coisas que fui forçada, impelida a fazer."
  },
  AvgDialog_6813_Content_29 = {
    Text = "<Change>Entregue-a... para... mim!"
  },
  AvgDialog_6813_Content_3 = {
    Text = "Helot cravou os Espinhos ferozmente na chama, mas não importava quantas vezes, ela não conseguia extinguir o fogo Queimante."
  },
  AvgDialog_6813_Content_30 = {
    Text = "Perdeu até a capacidade de falar?"
  },
  AvgDialog_6813_Content_31 = {
    Text = "Se é assim, então confie suas palavras, seus sentimentos, à sua lâmina.\nDeixe-me ouvir sua raiva através da batalha!"
  },
  AvgDialog_6813_Content_32 = {
    Text = "Eu fui traída tantas, tantas vezes."
  },
  AvgDialog_6813_Content_33 = {
    Text = "Porquê? Porquê? Preciso de ver a Senhora!"
  },
  AvgDialog_6813_Content_34 = {
    Text = "Não te incomodes. Ainda pensas que és a nobre filha adotiva do magistrado?"
  },
  AvgDialog_6813_Content_35 = {
    Text = "Sangue corrompido só pode produzir uma <Blue:traidora> como tu."
  },
  AvgDialog_6813_Content_36 = {
    Text = [[
<BigShake:RESPONDE-ME!>
Fui abandonada?!]]
  },
  AvgDialog_6813_Content_37 = {
    Text = "Em termos de resultado, sim, mas..."
  },
  AvgDialog_6813_Content_38 = {
    Text = "As suas mãos trémulas já não conseguiam segurar o punho. A espada longa ressoou com uma vibração metálica quando o Tremor da rocha a atingiu."
  },
  AvgDialog_6813_Content_39 = {
    Text = "Outrora acreditei que a vingança era tudo para mim... Mas só hoje compreendo — interpretei mal o seu significado, e procurei o oponente errado."
  },
  AvgDialog_6813_Content_4 = {
    Text = "O quê... o que está acontecendo?!"
  },
  AvgDialog_6813_Content_40 = {
    Text = "Apenas uma Força grande o suficiente pode cumprir nossa vingança. Vingança é nosso Apenas significado."
  },
  AvgDialog_6813_Content_41 = {
    Text = "A montanha desejava me ver, então vim vê-Lo."
  },
  AvgDialog_6813_Content_42 = {
    Text = "Eu sou o seu futuro, \"Shiro\". Quando você tiver a coragem de erguer sua espada contra o Destino, você se tornará eu."
  },
  AvgDialog_6813_Content_43 = {
    Text = "Então querias vingar-te daqueles que te traíram, querias proteger Francis que te salvou.\nMas a batalha não é sobre isso."
  },
  AvgDialog_6813_Content_44 = {
    Text = "Não é para proteção, não é para vingança, não é para validação.\nLutar é apenas lutar."
  },
  AvgDialog_6813_Content_45 = {
    Text = "O teu mundo é demasiado pequeno, sempre a perseguir o brilho ténue da luz de outra pessoa como uma mariposa."
  },
  AvgDialog_6813_Content_46 = {
    Text = "Se você tiver a chance, vá explorar um mundo mais amplo."
  },
  AvgDialog_6813_Content_47 = {
    Text = "Solte! Você não vai aguentar muito mais tempo."
  },
  AvgDialog_6813_Content_48 = {
    Text = "Eu... não..."
  },
  AvgDialog_6813_Content_49 = {
    Text = "Solte... você também vai morrer se isso continuar!"
  },
  AvgDialog_6813_Content_5 = {
    Text = "O ritual já foi ativado. Seu Despertar não pode mais ser revertido."
  },
  AvgDialog_6813_Content_50 = {
    Text = "Nunca abandonarei nenhum camarada, não importa o quê... Nunca!"
  },
  AvgDialog_6813_Content_51 = {Text = "..."},
  AvgDialog_6813_Content_53 = {
    Text = "Lotan disse que a batalha é apenas batalha — não para proteger, nem para vingança."
  },
  AvgDialog_6813_Content_54 = {
    Text = "Pensei nisso durante muito tempo, e finalmente compreendi porque é que tu e o teu Corpo Desperto são tão poderosos..."
  },
  AvgDialog_6813_Content_55 = {
    Text = "Acho que Lotan estava errada. Talvez nem ela própria se tenha apercebido."
  },
  AvgDialog_6813_Content_56 = {
    Text = "Lotan, Lily, tu... todos vocês têm algo que querem proteger."
  },
  AvgDialog_6813_Content_57 = {
    Text = "Ser uma Guardiã — esse é o Destino para o qual fui destinada."
  },
  AvgDialog_6813_Content_58 = {
    Text = "Tu ensinaste-me esta verdade, Guardião."
  },
  AvgDialog_6813_Content_59 = {Text = "\"BOOM—\""},
  AvgDialog_6813_Content_6 = {
    Text = "Realmente não há outro jeito?"
  },
  AvgDialog_6813_Content_60 = {
    Text = "A montanha tremeu violentamente mais uma vez, e a espessa camada de gelo sobre o lago congelado rachou centímetro a centímetro."
  },
  AvgDialog_6813_Content_61 = {
    Text = "Sob os fragmentos estilhaçados, Pústulas negras transbordavam com Loucura, agitando-se e fervendo, espalhando-se incessantemente para fora."
  },
  AvgDialog_6813_Content_62 = {
    Text = "Helot, eu nunca abandonarei um companheiro!"
  },
  AvgDialog_6813_Content_63 = {
    Text = "Não gosto de dever favores. Você me salvou. Depois de hoje, estamos quites."
  },
  AvgDialog_6813_Content_64 = {
    Text = "Consigo sentir a presença de outra \"Shiro\"... Ela me espera dentro da montanha. Ela quer se vingar do Destino junto comigo."
  },
  AvgDialog_6813_Content_65 = {
    Text = "Você não abandonou ninguém. O Caminho à frente — deixe-nos trilhá-lo por conta própria."
  },
  AvgDialog_6813_Content_66 = {
    Text = "Nós somos guerreiros. Guerreiros nascem para lutar."
  },
  AvgDialog_6813_Content_67 = {
    Text = "Este é o destino que escolhemos para nós mesmas... Esta é a nossa batalha contra a montanha."
  },
  AvgDialog_6813_Content_68 = {
    Text = "Helot sacou os Espinhos Negros."
  },
  AvgDialog_6813_Content_69 = {
    Text = "As nuvens que pressionavam a montanha nevada eram densas, e nenhum único raio de sol as atravessava."
  },
  AvgDialog_6813_Content_7 = {
    Text = "...Há mais um."
  },
  AvgDialog_6813_Content_70 = {
    Text = "O corpo inteiro de Helot foi Enrolado e preso por um fluido viscoso negro como breu. Loucura inconsciente forjada em correntes sólidas de ferro, acorrentando-a sob camada após camada de Grilhões."
  },
  AvgDialog_6813_Content_71 = {Text = "..."},
  AvgDialog_6813_Content_73 = {
    Text = "Seus ombros delgados suportavam o peso das correntes enquanto ela avançava sozinha. Seu corpo estava preso pelos pesados Grilhões, e ela gradualmente perdeu o fôlego, caindo de joelhos na Neve."
  },
  AvgDialog_6813_Content_74 = {Text = "Helot..."},
  AvgDialog_6813_Content_75 = {
    Text = "Sussurros do sonho proibidos vertiam incessantemente em seus ouvidos. Em meio aos sons densos e sombrios, Helot ouviu a Resonância entre o pico da montanha e seu coração."
  },
  AvgDialog_6813_Content_76 = {
    Text = "Tum, tum, tum..."
  },
  AvgDialog_6813_Content_77 = {
    Text = "Sob a rocha dura e a terra congelada, o colosso desperto zumbia com urgência desesperada, ansiando por Ela."
  },
  AvgDialog_6813_Content_78 = {
    Text = "Ela se ergueu sobre o cume."
  },
  AvgDialog_6813_Content_79 = {
    Text = "O pico frenético tremia de Empolgação, a Terra estremecendo violentamente. O vento Criminoso e gélido rasgava as finas vestes de Helot, mas não conseguia movê-la um centímetro sequer."
  },
  AvgDialog_6813_Content_8 = {
    Text = "Helot olhou para você, depois para a chama azul imortal no topo do cume."
  },
  AvgDialog_6813_Content_80 = {
    Text = "Torrentes de fluido Pegajoso negro irrompiam do cume coberto de neve, como ondas colossais, cercando-a completamente—"
  },
  AvgDialog_6813_Content_81 = {
    Text = "@3Retorno... Destruir@2... Esquecer@3@2... Venha... Retorno@3..."
  },
  AvgDialog_6813_Content_82 = {
    Text = "...Retorno@3..."
  },
  AvgDialog_6813_Content_83 = {
    Text = "Se vencermos, o gelo e a Neve de Elworth passarão por Fusão. Quando esse momento chegar, juntas, iremos Recriar sobre o mundo."
  },
  AvgDialog_6813_Content_84 = {
    Text = "Aguarde, Guardião."
  },
  AvgDialog_6813_Content_85 = {
    Text = "Helot vira brevemente a cabeça. Você acha que vê um sorriso fugaz cruzar seu rosto."
  },
  AvgDialog_6813_Content_86 = {
    Text = "Ela se virou e, de frente para aquela chama azul inextinguível, ergueu o espinho negro em sua mão—"
  },
  AvgDialog_6813_Content_87 = {
    Text = "Batalha, Começar."
  },
  AvgDialog_6813_Content_89 = {
    Text = "Uma declaração, e um comando. Incontáveis torrentes de fluido Pegajoso negro desabaram, engolindo tudo no topo do pico."
  },
  AvgDialog_6813_Content_9 = {
    Text = "Se Despertar, Todos perecerão aqui."
  },
  AvgDialog_6813_Content_90 = {
    Text = "As montanhas de Elworth tremeram. As cordilheiras extensas lançaram névoa de gelo branco-leitoso, suas formas rígidas e pesadas contorcendo-se e lutando desesperadamente, como se resistissem a algo."
  },
  AvgDialog_6813_Content_91 = {
    Text = "Nuvens em chamas foram varridas pelo vendaval, um colossal redemoinho envolvendo todo o pico. Uma Força inspiradora de terror irrompeu sem contenção, como se fosse rasgar até mesmo o céu ao meio..."
  },
  AvgDialog_6813_Content_92 = {Text = "..."},
  AvgDialog_6813_Content_93 = {
    Text = "Um período desconhecido de tempo passou. A fumaça e a poeira finalmente se dissiparam, e a Terra sob seus pés cessou de tremer."
  },
  AvgDialog_6813_Content_94 = {
    Text = "Lily, de volta ao normal, caminhou até você e segurou sua mão."
  },
  AvgDialog_6813_Content_95 = {
    Text = "Irmã Helot... se foi."
  },
  AvgDialog_6813_Content_96 = {
    Text = "As montanhas respiravam em repouso tranquilo. Você ergueu a cabeça e contemplou o céu."
  },
  AvgDialog_6813_Content_97 = {
    Text = "Flocos de neve grosseiros desciam flutuando, acumulando-se sobre sua cabeça, tingindo seu Cabelo de um branco manchado."
  },
  AvgDialog_6813_Content_98 = {
    Text = "Elworth jazia em perfeita quietude, como se nada tivesse acontecido."
  },
  AvgDialog_6816_Content_1 = {
    Text = "O Chamado das Montanhas"
  },
  AvgDialog_6816_Content_10 = {
    Text = "Solte! Você não vai aguentar muito mais tempo."
  },
  AvgDialog_6816_Content_100 = {
    Text = "A montanha sob seus pés começou a Abalar. Das profundezas das montanhas, um Chamado grave e fétido ecoou..."
  },
  AvgDialog_6816_Content_11 = {
    Text = "Os olhos de Helot se arregalaram enquanto ela lutava para se soltar do seu aperto, Apenas para descobrir que a Força vinda daquelas pontas dos dedos tinha uma tenacidade que ela nunca havia sentido antes."
  },
  AvgDialog_6816_Content_12 = {
    Text = "Eu... não..."
  },
  AvgDialog_6816_Content_13 = {
    Text = "Os grampos nos seus pés se cravavam desesperadamente no gelo, mas continuavam escorregando com a força da Queda, Apenas mal se segurando graças ao apoio de Lily de cima."
  },
  AvgDialog_6816_Content_14 = {
    Text = "Seu rosto ficou vermelho enquanto você suportava a dor intensa, despejando cada gota de Força para segurar mais firme, com mais firmeza — mas você Apenas podia assistir impotente enquanto as pontas dos dedos dela escorregavam centímetro por centímetro do seu aperto."
  },
  AvgDialog_6816_Content_15 = {
    Text = "O rosto dela estava a Apenas um metro do seu, mas naquele momento, aquele metro parecia impossivelmente distante."
  },
  AvgDialog_6816_Content_16 = {
    Text = "Solte... você também vai morrer se isso continuar!"
  },
  AvgDialog_6816_Content_17 = {
    Text = "A ferida no seu ombro se abriu, e Sangue respingou na pele sob os olhos de Helot, escorrendo pelo rosto frio e endurecido Dela."
  },
  AvgDialog_6816_Content_18 = {
    Text = "Ela de repente arregalou os olhos, atordoada por um momento, nem sequer notando o sangue escorrendo neles."
  },
  AvgDialog_6816_Content_19 = {
    Text = "Nunca abandonarei nenhum camarada, não importa o quê... Nunca!"
  },
  AvgDialog_6816_Content_2 = {
    Text = "Helot... segure-se em mim!"
  },
  AvgDialog_6816_Content_20 = {Text = "Boom——"},
  AvgDialog_6816_Content_21 = {
    Text = "Toda a montanha começou a tremer novamente, sacudindo violentamente como se fosse um deslizamento de terra."
  },
  AvgDialog_6816_Content_22 = {
    Text = "Você suportou exaustão e agonia, mas seu pico de gelo foi lançado para fora da montanha."
  },
  AvgDialog_6816_Content_23 = {Text = "Obrigado."},
  AvgDialog_6816_Content_24 = {
    Text = "Pelo menos eu fiz o meu melhor... Você fecha os olhos."
  },
  AvgDialog_6816_Content_25 = {
    Text = "BANG! BANG BANG!"
  },
  AvgDialog_6816_Content_26 = {
    Text = "O impacto devastador que se esperava nunca chegou. Em vez disso, você colidiu com várias rochas em sequência, transformando a queda em uma cambalhota pela encosta e, eventualmente, em um deslizamento."
  },
  AvgDialog_6816_Content_27 = {
    Text = "Alguns segundos depois, você parou. O penhasco mortal de agora há pouco se transformou em terreno plano."
  },
  AvgDialog_6816_Content_28 = {
    Text = "A vários metros de distância, Lily está onde você acabou de acertar com seu picador de gelo, acenando para você."
  },
  AvgDialog_6816_Content_29 = {
    Text = "Apenas agora, as palavras ousadas e a despedida de vida e morte pareciam se transformar em uma comédia farsesca"
  },
  AvgDialog_6816_Content_3 = {
    Text = "No instante em que ela caiu, você instintivamente estendeu a mão e a agarrou."
  },
  AvgDialog_6816_Content_30 = {
    Text = "Você acabou de dizer \"obrigado\"?"
  },
  AvgDialog_6816_Content_31 = {
    Text = "Você ouviu errado."
  },
  AvgDialog_6816_Content_32 = {
    Text = "Ela estendeu a mão, tocando suavemente o sangue seco no canto de seu olho. Pela primeira vez, você viu um sorriso fugaz aparecer em seu rosto."
  },
  AvgDialog_6816_Content_33 = {
    Text = "Terra plana se transforma em um penhasco, e o penhasco volta a se transformar em terra plana."
  },
  AvgDialog_6816_Content_34 = {
    Text = "O fedor na caverna da montanha, e aquelas paredes de caverna em constante mudança..."
  },
  AvgDialog_6816_Content_35 = {
    Text = "Talvez, nossa suposição estava correta."
  },
  AvgDialog_6816_Content_36 = {
    Text = "Esta montanha... está viva."
  },
  AvgDialog_6816_Content_37 = {
    Text = "Precisamos nos preparar para o pior e permanecer vigilantes a qualquer mudança na montanha."
  },
  AvgDialog_6816_Content_38 = {
    Text = "O caminho descendo a montanha foi selado. Devemos ir até o cume e encontrar uma nova rota... Precisamos descer o mais rápido possível."
  },
  AvgDialog_6816_Content_39 = {Text = "..."},
  AvgDialog_6816_Content_4 = {
    Text = "Seu piolet cravou-se na encosta da montanha enquanto você pendia precariamente no meio do penhasco da montanha de Neve. A ferida no seu braço vertia Sangue, enviando ondas de dor lancinante por todo o seu corpo."
  },
  AvgDialog_6816_Content_40 = {
    Text = "Cuidado, há outra fenda de neve aqui... Ufa, quase caí de novo."
  },
  AvgDialog_6816_Content_41 = {
    Text = "Grande {Male=Sr. Guardião,Female=Srta. Guardiã}, você precisa descansar?"
  },
  AvgDialog_6816_Content_42 = {
    Text = "Segurar várias pessoas na parede quebrada antes já havia drenado toda a sua Força. Seus braços estavam tão severamente sobrecarregados que você mal conseguia levantá-los, e sua resistência havia chegado ao limite."
  },
  AvgDialog_6816_Content_43 = {
    Text = "Vamos nos apressar... Só Deus sabe quando esta montanha vai mudar de novo."
  },
  AvgDialog_6816_Content_44 = {
    Text = "Ainda consigo aguentar por agora, não se preocupe..."
  },
  AvgDialog_6816_Content_45 = {Text = "Ah! —"},
  AvgDialog_6816_Content_46 = {
    Text = "Lily, o que há de errado?"
  },
  AvgDialog_6816_Content_47 = {
    Text = "Hã... Lily viu algo... algo estranho..."
  },
  AvgDialog_6816_Content_48 = {
    Text = "Suas pequenas mãos agarraram a cabeça enquanto ela puxava a barra das suas roupas, confusa."
  },
  AvgDialog_6816_Content_49 = {
    Text = "O que Lily viu?"
  },
  AvgDialog_6816_Content_5 = {
    Text = "Da outra mão dela pendiam os dois membros da expedição, ainda firmemente amarrados um ao outro."
  },
  AvgDialog_6816_Content_50 = {
    Text = "O Campo de Neve, os mortos, o céu estrelado, e... nós."
  },
  AvgDialog_6816_Content_51 = {
    Text = "Eu também os vi, aqueles fantasmas Enrolados, agarrados a mim... e a Lily."
  },
  AvgDialog_6816_Content_52 = {
    Text = "Eu consigo sentir. Uma Força está Despertando."
  },
  AvgDialog_6816_Content_53 = {
    Text = "O glaciar soltou outro rugido e começou a mudar de forma, muito lentamente."
  },
  AvgDialog_6816_Content_54 = {
    Text = "Desta vez, o lago glacial há muito oculto revelou sua verdadeira aparência, e você vislumbrou a figura frágil coberta de Pústulas negras de pé sobre ele."
  },
  AvgDialog_6816_Content_55 = {
    Text = "A fissura no lago glacial ficava cada vez mais larga, como uma longa ferida aberta se estendendo pela superfície do lago sob o glaciar extenso."
  },
  AvgDialog_6816_Content_56 = {
    Text = "Pústulas negras surgiam incessantemente, cobrindo a outra \"Shiro\"."
  },
  AvgDialog_6816_Content_57 = {
    Text = "Eu consigo sentir... Mais, me dê mais!"
  },
  AvgDialog_6816_Content_58 = {
    Text = "Essas Pústulas sinistras sentiram a Invocação Dela, zumbindo de excitação, atropelando-se umas às outras para se derramar em seus lábios e dentes, buscando ativamente ser Devoradas através de solicitar."
  },
  AvgDialog_6816_Content_59 = {
    Text = "Pareciam se deleitar em ser despedaçadas, reverenciar ser engolidas, e ansiar por ser dilaceradas e consumidas."
  },
  AvgDialog_6816_Content_6 = {
    Text = "Ela tentou subir, mas o piolet e seu braço Instável não conseguiam mais suportar qualquer peso adicional."
  },
  AvgDialog_6816_Content_60 = {
    Text = "Você chegou diante da outra \"Shiro\". Seu corpo estava submerso nas Pústulas negras, sua forma já tão etérea que parecia uma névoa que poderia ser soprada com o menor sopro."
  },
  AvgDialog_6816_Content_61 = {
    Text = "Saia deste lugar agora, e ainda há uma chance..."
  },
  AvgDialog_6816_Content_62 = {
    Text = "Partir... Nunca tivemos o direito de partir."
  },
  AvgDialog_6816_Content_63 = {
    Text = "A Paranoia e a Loucura nos olhos da outra \"Shiro\" desapareceram subitamente."
  },
  AvgDialog_6816_Content_64 = {
    Text = "Seu olhar se voltou para Helot, carregando uma compostura e calma sem precedentes."
  },
  AvgDialog_6816_Content_65 = {
    Text = "Aquelas coisas que um dia te machucaram, aquele ódio profundo — você esqueceu tudo isso, \"Shiro\"?"
  },
  AvgDialog_6816_Content_66 = {
    Text = "Eu nunca esqueci... Eu Apenas..."
  },
  AvgDialog_6816_Content_67 = {
    Text = "Você está perdida, \"Shiro\"."
  },
  AvgDialog_6816_Content_68 = {
    Text = "Apenas uma Força grande o suficiente pode cumprir nossa vingança. Vingança é nosso Apenas significado."
  },
  AvgDialog_6816_Content_69 = {
    Text = "Vingança... contra quem?"
  },
  AvgDialog_6816_Content_7 = {Text = "%player%!"},
  AvgDialog_6816_Content_70 = {Text = "O Destino."},
  AvgDialog_6816_Content_71 = {
    Text = "Aquelas duas palavras calmas enviaram um tremor violento pelo corpo de Helot."
  },
  AvgDialog_6816_Content_72 = {
    Text = "Não importa onde estejamos, esta montanha vai nos Chamar, nos Devorar."
  },
  AvgDialog_6816_Content_73 = {
    Text = "Este é o nosso Destino, assim como todas aquelas coisas imundas que um dia Experienciamos..."
  },
  AvgDialog_6816_Content_74 = {
    Text = "Você sempre soube a resposta, mas fechou os olhos para ela. Não é?"
  },
  AvgDialog_6816_Content_75 = {
    Text = "Comparado às pessoas e coisas que você despreza, o Destino é um oponente tão aterrorizante..."
  },
  AvgDialog_6816_Content_76 = {
    Text = "Você não merece ser chamada de \"guerreira,\" sua covarde."
  },
  AvgDialog_6816_Content_77 = {
    Text = "Seu corpo não consegue mais se manter inteiro... você vai morrer aqui."
  },
  AvgDialog_6816_Content_78 = {
    Text = "Mesmo assim... e daí?"
  },
  AvgDialog_6816_Content_79 = {
    Text = "Ela virou o rosto na direção de todos vocês e abriu os lábios em um sorriso, revelando um par de presas astutas."
  },
  AvgDialog_6816_Content_8 = {
    Text = "Lily chamou ansiosamente, tentando conjurar um orbe sombrio para elevar todos vocês."
  },
  AvgDialog_6816_Content_80 = {
    Text = "Lanterna me enganou para vir aqui, querendo me usar para reviver @3. Esta montanha me Invocou, querendo me Devorar. Eu sempre soube, mas vim mesmo assim."
  },
  AvgDialog_6816_Content_81 = {
    Text = "A montanha desejava me ver, então vim vê-Lo."
  },
  AvgDialog_6816_Content_82 = {
    Text = "Eu deveria agradecer a Lanterna por me dar a chance de enfrentá-Lo diretamente..."
  },
  AvgDialog_6816_Content_83 = {
    Text = "Você é tão covarde, mas veio também, não é?"
  },
  AvgDialog_6816_Content_84 = {
    Text = "Eu sou o seu futuro, \"Shiro\". Quando você tiver a coragem de erguer sua espada contra o Destino, você se tornará eu."
  },
  AvgDialog_6816_Content_85 = {
    Text = "As Pústulas negras se acumulavam cada vez mais, como um enxame de criaturas primordiais famintas, avançando avidamente sobre o corpo dela, rastejando por suas bochechas."
  },
  AvgDialog_6816_Content_86 = {
    Text = "Ela riu, como uma Besta rasgando gananciosamente carne crua, como um rei prestes a ascender ao trono."
  },
  AvgDialog_6816_Content_87 = {
    Text = "Observe, \"Shiro\"... Eu vou Devorar Isso. Eu vou me tornar poderosa. Nenhum Destino jamais será capaz de me parar novamente!"
  },
  AvgDialog_6816_Content_88 = {
    Text = "Nunca mais haverá correntes... Nunca mais... haverá traição..."
  },
  AvgDialog_6816_Content_89 = {
    Text = "As Pústulas negras continuavam se Propagando e se acumulando em seu corpo, enterrando-se em sua forma já sobrecarregada, cobrindo seu rosto calmo, porém enlouquecido..."
  },
  AvgDialog_6816_Content_9 = {
    Text = "Mas ela havia esgotado toda a sua Força na batalha anterior. O orbe sombrio mal conseguia tomar forma, muito menos suportar o peso de uma pessoa."
  },
  AvgDialog_6816_Content_90 = {
    Text = "Eu vou... <Big:ter minha vingança!!!>"
  },
  AvgDialog_6816_Content_91 = {Text = "Bang—"},
  AvgDialog_6816_Content_92 = {
    Text = "Como se uma Pústula tivesse sido perfurada, fluidos negros e vermelhos espirraram em todas as direções."
  },
  AvgDialog_6816_Content_93 = {
    Text = "O grito final da Besta ainda Ecoava pelo vale vazio.\nOnde ela estivera, não restava nada além de uma poça de líquido."
  },
  AvgDialog_6816_Content_94 = {
    Text = "\"Vingança\"... huh..."
  },
  AvgDialog_6816_Content_95 = {
    Text = "Helot ergueu a cabeça um tanto atordoada, fitando o céu cinza-pálido."
  },
  AvgDialog_6816_Content_96 = {
    Text = "Flocos de neve grosseiros rolaram por sua pele, derretendo-se em pequenas manchas de água."
  },
  AvgDialog_6816_Content_97 = {
    Text = "Ela... foi Devorada pela montanha?"
  },
  AvgDialog_6816_Content_98 = {Text = "@2...@3..."},
  AvgDialog_6816_Content_99 = {
    Text = "Antes que Helot pudesse falar, sua pergunta foi respondida—"
  },
  AvgDialog_68327_Content_1 = {
    Text = "Ha... tão revigorante."
  },
  AvgDialog_68327_Content_10 = {
    Text = "Este é o mundo onde meu Senhor reside. Este é o mundo que abriga o Reino Divino."
  },
  AvgDialog_68327_Content_11 = {
    Text = "Deuses heréticos não devem ser destruídos!"
  },
  AvgDialog_68327_Content_12 = {
    Text = "Nossa linhagem não deve ser manchada..."
  },
  AvgDialog_68327_Content_13 = {
    Text = "Eu irei proteger nosso mundo... Eu irei defender a glória da minha linhagem!"
  },
  AvgDialog_68327_Content_14 = {
    Text = "Não tem nada a ver comigo, Miryam."
  },
  AvgDialog_68327_Content_15 = {
    Text = "O antigo Reino Divino já pereceu, mas o novo Reino Divino já existe ao nosso redor há muito tempo."
  },
  AvgDialog_68327_Content_16 = {
    Text = "É chamado Mythag, Londinium e Kadath."
  },
  AvgDialog_68327_Content_17 = {
    Text = "Quando perdi minha terra natal, era impotente. Desta vez, não permitirei que o Reino Divino desmorone diante de mim!"
  },
  AvgDialog_68327_Content_18 = {
    Text = "Vocês lunáticos têm seus momentos de clareza!"
  },
  AvgDialog_68327_Content_19 = {
    Text = "Eu ainda não terminei de provar todos os bolos de Londinium. Não vou deixar aquele cara destruir este lugar assim!"
  },
  AvgDialog_68327_Content_2 = {
    Text = "Eu disse que conquistaria esta terra e reclamaria o poder que me pertence. Mas nada disso tem a ver com aqueles seres fora deste mundo."
  },
  AvgDialog_68327_Content_20 = {
    Text = "Você ouviu aqueles sons, %player%?"
  },
  AvgDialog_68327_Content_21 = {
    Text = "O som da flauta que eu um dia desejei é apenas divagações loucas, barulho caótico."
  },
  AvgDialog_68327_Content_22 = {
    Text = "E estes— as melodias sinceras dos Despertadores, as grandes canções que você toca para a Vontade Suprema, são exatamente o que eu procuro."
  },
  AvgDialog_68327_Content_23 = {
    Text = "Continue jogando, %player%, aquele que eu sirvo."
  },
  AvgDialog_68327_Content_24 = {
    Text = "Deixe aquele Deus tolo e louco ouvir sua melodia suprema, ouvir esta última performance e testemunhar aquele final incomparável—"
  },
  AvgDialog_68327_Content_3 = {
    Text = "O que \"vontade suprema\", \"Relíquia\", \"Destruição,\" é tão ridículo quanto o que Miryam diz."
  },
  AvgDialog_68327_Content_4 = {
    Text = "Vamos, %player%, minha lâmina está pronta para você."
  },
  AvgDialog_68327_Content_5 = {
    Text = "Isto é nosso território. Envie aquela criatura de olhos grandes rolando de volta para de onde veio."
  },
  AvgDialog_68327_Content_6 = {
    Text = "Cuidado com suas palavras, Golias."
  },
  AvgDialog_68327_Content_7 = {
    Text = "Mas você está certo sobre uma coisa. Nosso mundo não tem nada a ver com este Deus herético."
  },
  AvgDialog_68327_Content_8 = {
    Text = "Se eu soubesse o propósito de Juliette, nunca teria tolerado suas ações."
  },
  AvgDialog_68327_Content_9 = {
    Text = "A verdade da Loucura, superando a existência de nosso Senhor... Que sacrílego!"
  },
  AvgDialog_68328_Content_1 = {
    Text = "A ligação foi interrompida, mas eu ainda... consigo senti-los... \nUma existência tão real, completamente diferente dos corpos inconscientes que criei com meu próprio poder..."
  },
  AvgDialog_68328_Content_10 = {
    Text = "Continue em frente, Guardião. Pelo dia em que nos seguraremos novamente."
  },
  AvgDialog_68328_Content_11 = {Text = "..."},
  AvgDialog_68328_Content_12 = {
    Text = "Mesmo que eu tenha que saltar para a Poça Negra, descendo à Ilusão com o mundo, eu segurarei sua mão."
  },
  AvgDialog_68328_Content_13 = {
    Text = "A lança de Ogier também lutará para proteger o senhor!"
  },
  AvgDialog_68328_Content_14 = {
    Text = "Se possível, Aigis... também gostaria de ajudar o Guardião... isso está bem?"
  },
  AvgDialog_68328_Content_15 = {
    Text = "Fique atrás de mim e abra seus olhos com confiança! Se uma crise surgir, ativarei o escudo para você."
  },
  AvgDialog_68328_Content_16 = {
    Text = "\"Meu senhor, confio suas costas a mim, o cavaleiro virtuoso, e apresento a você a vontade do Guardião!\""
  },
  AvgDialog_68328_Content_17 = {
    Text = "Ó mensageiro pálido, eu testemunhei pessoalmente sua postura destemida diante do ser supremo."
  },
  AvgDialog_68328_Content_18 = {
    Text = "A chama queimando em sua alma é tão brilhante. Ele te abençoará, abrindo o caminho para um lugar livre de sofrimento."
  },
  AvgDialog_68328_Content_19 = {
    Text = "Naquele dia, a luz do Pai Deus brilhará sobre todos igualmente."
  },
  AvgDialog_68328_Content_2 = {
    Text = "Kadath é seu Sonho, Guardião."
  },
  AvgDialog_68328_Content_20 = {
    Text = "Não há necessidade de sentir tristeza, não há necessidade de temer as chamas, nem a escuridão da doença e da ganância suprema."
  },
  AvgDialog_68328_Content_21 = {
    Text = "Eu irei registrar a história de Londinium em forma poética, e sua figura será imortalizada através dos versos."
  },
  AvgDialog_68328_Content_22 = {
    Text = "Vamos, Guardião."
  },
  AvgDialog_68328_Content_23 = {
    Text = "Nossos versos... ainda precisam ser escritos até a última linha."
  },
  AvgDialog_68328_Content_3 = {Text = "Quem?!"},
  AvgDialog_68328_Content_4 = {
    Text = "A figura com um rosto indistinto ignorou sua pergunta."
  },
  AvgDialog_68328_Content_5 = {
    Text = "Mesmo que a Dissolução faça com que inúmeras existências pereçam, sua Memória não vai desvanecer."
  },
  AvgDialog_68328_Content_6 = {
    Text = "Aquelas memórias preenchem sua consciência, e a história que vocês dois viveram lhe dará a força para enfrentar o olhar Deles."
  },
  AvgDialog_68328_Content_7 = {
    Text = "As contornos familiares, tanto reais quanto ilusórios, começam a emergir ao seu lado com um leve brilho prateado."
  },
  AvgDialog_68328_Content_8 = {
    Text = "Você se lembra do dia da Cerimônia da Chave? Eu nunca vou esquecer o momento em que nossas pontas de dedo se tocaram. Isso foi a testemunha do precioso Link entre você e eu."
  },
  AvgDialog_68328_Content_9 = {
    Text = "Mesmo que nos desconectemos, eu serei para sempre seu único e eterno parceiro."
  },
  AvgDialog_68329_Content_1 = {
    Text = "Batalha. Batalha"
  },
  AvgDialog_68329_Content_10 = {
    Text = "O som da flauta começou. Grave, confuso, tranquilo"
  },
  AvgDialog_68329_Content_11 = {
    Text = "O tolo Criador, com cicatrizes tênues, observa você com interesse, como se olhasse para um inseto problemático lutando desesperadamente."
  },
  AvgDialog_68329_Content_12 = {
    Text = "Ele chegou à beira do sono. Só mais um pouco e a porta se fechará... só mais um pouco..."
  },
  AvgDialog_68329_Content_13 = {
    Text = "E aquele passo final é como um abismo."
  },
  AvgDialog_68329_Content_14 = {
    Text = "Você pegou novamente a chave de prata"
  },
  AvgDialog_68329_Content_15 = {
    Text = "Guardião... não!"
  },
  AvgDialog_68329_Content_16 = {
    Text = "De quem é o grito? Você não lembra, e nem importa"
  },
  AvgDialog_68329_Content_17 = {
    Text = "O corpo já está exausto, a mente também se esgotou. Mas você se lembra, você deve lutar"
  },
  AvgDialog_68329_Content_18 = {
    Text = "Se for pra morrer... eu vou com você!"
  },
  AvgDialog_68329_Content_19 = {
    Text = "Uma gota de água brilhante cai em sua mente, criando ondulações em sua árida dimensão espiritual"
  },
  AvgDialog_68329_Content_2 = {
    Text = "Uma batalha de esquecer tudo. Uma batalha de generosa morte"
  },
  AvgDialog_68329_Content_20 = {
    Text = "A gota de água se expandiu gradualmente, tomando a forma de uma figura ilusória em sua mente. Você olha para ela.\nUm nome distante ecoa em sua mente"
  },
  AvgDialog_68329_Content_21 = {
    Text = "Ra... mona?"
  },
  AvgDialog_68329_Content_22 = {
    Text = "Você disse, guardião. Disse que nunca nos deixaria"
  },
  AvgDialog_68329_Content_23 = {
    Text = "Se você ficar ao meu lado, você morrerá."
  },
  AvgDialog_68329_Content_24 = {
    Text = "Eu já cortei a conexão, Ramona"
  },
  AvgDialog_68329_Content_25 = {
    Text = "Ao se conectar comigo, você perderá o controle"
  },
  AvgDialog_68329_Content_26 = {
    Text = "Ficar comigo, você vai morrer"
  },
  AvgDialog_68329_Content_27 = {
    Text = "O que há a temer na morte?"
  },
  AvgDialog_68329_Content_28 = {
    Text = "A segunda gota de água caiu em sua mente"
  },
  AvgDialog_68329_Content_29 = {
    Text = "Lotan... você não está na piscina negra, por que você"
  },
  AvgDialog_68329_Content_3 = {
    Text = "Os olhos quebram, olhos renascem. Caindo e levantando repetidamente"
  },
  AvgDialog_68329_Content_30 = {
    Text = "Porque somos seu despertador. Você pode cortar o link, mas não pode cortar o poder de nos conectar a você"
  },
  AvgDialog_68329_Content_31 = {
    Text = "Sempre ao seu lado, seu Despertar.\nLink, uma marca eterna entre você e seu Despertar, Guardião."
  },
  AvgDialog_68329_Content_32 = {
    Text = "Professora Boneca, você também...\nNo entanto, conectar-se a mim pode ser demais para você suportar..."
  },
  AvgDialog_68329_Content_33 = {
    Text = "Mesmo que não fique na frente do senhor, deixe-me ao seu lado!"
  },
  AvgDialog_68329_Content_34 = {
    Text = "Isso! Nos entregar à piscina negra e correr? Nem pensar!"
  },
  AvgDialog_68329_Content_35 = {
    Text = "Lily vai ajudar %player%!"
  },
  AvgDialog_68329_Content_36 = {
    Text = "Meu povo será protegido por mim"
  },
  AvgDialog_68329_Content_37 = {Text = "..."},
  AvgDialog_68329_Content_38 = {
    Text = "Cada vez mais gotas de água se estendem do lago negro e caem na sua dimensão espiritual"
  },
  AvgDialog_68329_Content_39 = {
    Text = "Inúmeras imagens das entidades despertas surgem em sua mente. Elas sorriem, se enfurecem, desprezam, lamentam"
  },
  AvgDialog_68329_Content_4 = {
    Text = "O que é essa enorme criação? Você já meio que esqueceu"
  },
  AvgDialog_68329_Content_40 = {
    Text = "As histórias deles fundem-se num rio prateado, fluindo silenciosamente pelos teus pensamentos, nutrindo cada veia e nervo do teu corpo."
  },
  AvgDialog_68329_Content_41 = {
    Text = "Aceite isso, Guardião."
  },
  AvgDialog_68329_Content_42 = {
    Text = "Deixe-nos ficar com você."
  },
  AvgDialog_68329_Content_43 = {
    Text = "Você olhou para trás. A consciência louca já havia levado os despertadores à beira do colapso"
  },
  AvgDialog_68329_Content_44 = {
    Text = "O corpo de Ramona treme involuntariamente, mas ela te observa fixamente, sem qualquer intenção de romper a ligação"
  },
  AvgDialog_68329_Content_45 = {
    Text = "As decisões que você tomar, eu não irei interferir."
  },
  AvgDialog_68329_Content_46 = {
    Text = "Fique comigo. Este é meu único pedido..."
  },
  AvgDialog_68329_Content_47 = {
    Text = "Obrigado..."
  },
  AvgDialog_68329_Content_48 = {
    Text = "Há coisas piores que a loucura e a morte"
  },
  AvgDialog_68329_Content_49 = {
    Text = "Você é assim, e eles também"
  },
  AvgDialog_68329_Content_5 = {
    Text = "Quem são essas pessoas atrás de você? Você esqueceu"
  },
  AvgDialog_68329_Content_50 = {
    Text = "Obrigado... É maravilhoso ter conhecido você."
  },
  AvgDialog_68329_Content_51 = {
    Text = "Você sorri e se vira."
  },
  AvgDialog_68329_Content_52 = {
    Text = "Eu prometi, e vou cumprir"
  },
  AvgDialog_68329_Content_53 = {
    Text = "Você ergue a cabeça e encara o criador e destruidor deste universo, o colosso invencível"
  },
  AvgDialog_68329_Content_54 = {
    Text = "A primeira vez que você se encontra e se conecta com cada despertador, cada palavra que trocaram, cada experiência que tiveram, passa pela sua mente"
  },
  AvgDialog_68329_Content_55 = {
    Text = "Você sente o poder surgindo daqueles Links. É a névoa de Londinium, a neve de Rai, o mar de Briarport, e a areia de Remvai."
  },
  AvgDialog_68329_Content_56 = {
    Text = "Aquilo foi seu encontro, as interações diárias em Mythag. É sua vida, um grilhão inquebrável. É sua obsessão compartilhada."
  },
  AvgDialog_68329_Content_57 = {
    Text = "Essas belas coisas, nunca seriam destruídas"
  },
  AvgDialog_68329_Content_58 = {
    Text = "Você sabe o que realmente quer proteger.\nVocê sabe que irá protegê-los"
  },
  AvgDialog_68329_Content_59 = {
    Text = "Você sorri e levanta a chave de prata para a criação à sua frente.\nComo um vaga-lume enfrentando o sol com orgulho"
  },
  AvgDialog_68329_Content_6 = {
    Text = "A força mental já se esgotou, o corpo e a mente foram gravemente corroídos. Você não se importa"
  },
  AvgDialog_68329_Content_60 = {
    Text = "Que a chave prateada ilumine o caminho!!"
  },
  AvgDialog_68329_Content_62 = {Text = "..."},
  AvgDialog_68329_Content_63 = {Text = "..."},
  AvgDialog_68329_Content_64 = {
    Text = "Não sei quanto tempo se passou. A luz prateada que iluminava todo o reino de Leo foi lentamente se apagando"
  },
  AvgDialog_68329_Content_65 = {Text = "..."},
  AvgDialog_68329_Content_66 = {
    Text = "Guardião?!!"
  },
  AvgDialog_68329_Content_67 = {
    Text = "Ela se aproximou da porta. Você não estava mais lá"
  },
  AvgDialog_68329_Content_68 = {
    Text = "Ela ergueu a cabeça e viu uma porta completamente fechada e, em frente a essa enorme porta, a chave de prata flutuava silenciosamente"
  },
  AvgDialog_68329_Content_69 = {
    Text = "Código, K-0617... isso... isso é"
  },
  AvgDialog_68329_Content_7 = {
    Text = "Você só se lembra da batalha. Mecânica, insensível e sem emoção"
  },
  AvgDialog_68329_Content_70 = {
    Text = "Pela autoridade do 6º Diretor da Misaq, <Blue:Oliver Elsie>, eu confiro a você a Chave de prata K-0617."
  },
  AvgDialog_68329_Content_71 = {
    Text = "De agora em diante, você se ergue como Guardião entre a miríade de estudantes e acadêmicos da Misaq."
  },
  AvgDialog_68329_Content_72 = {
    Text = "Ramona se aproxima e segura a chave de prata com cuidado"
  },
  AvgDialog_68329_Content_73 = {Text = "Por que"},
  AvgDialog_68329_Content_74 = {Text = "Ramona..."},
  AvgDialog_68329_Content_75 = {
    Text = "Código do Guardião... Primeira regra"
  },
  AvgDialog_68329_Content_76 = {
    Text = "Chave de prata... Símbolo do Guardião... Não pode ser perdida, não pode ser descartada"
  },
  AvgDialog_68329_Content_77 = {
    Text = "Eu ensinei a ele... por que... por que ele não lembra?"
  },
  AvgDialog_68329_Content_78 = {
    Text = "O olhar de Tohu Vabo foi afastado da porta. Ele voltou a dormir"
  },
  AvgDialog_68329_Content_79 = {
    Text = "O Guardião, junto com Ele, caiu em uma ilusão inconsciente, vigiando, por nós, por este mundo, a porta selada de Tohuwabohu"
  },
  AvgDialog_68329_Content_8 = {
    Text = "Você só se lembra do que disse, proteger essas pessoas atrás de você"
  },
  AvgDialog_68329_Content_80 = {
    Text = "%hisorher% consciência e vida já não existem mais...\n{Male=ele,Female=ela} morreu, Ramona"
  },
  AvgDialog_68329_Content_81 = {
    Text = "Morte? Como ele morreria... ele nos deixaria?"
  },
  AvgDialog_68329_Content_82 = {
    Text = "Tantas pessoas... tantos eventos... {Male=ele,Female=ela} como poderia desistir?"
  },
  AvgDialog_68329_Content_83 = {
    Text = "Como {Male=ele,Female=ela} pode desistir"
  },
  AvgDialog_68329_Content_84 = {
    Text = "As gotas de lágrimas molham as luvas, molham a chave de prata"
  },
  AvgDialog_68329_Content_85 = {
    Text = "Lágrimas caem na piscina negra, formando ondas claras"
  },
  AvgDialog_68329_Content_86 = {
    Text = "Sobre as ondas, atrás da porta, uma figura ilusória dorme pacificamente envolta por asas"
  },
  AvgDialog_68329_Content_87 = {
    Text = "O rosto de %hisorher% exibia um sorriso puro, como o de um bebê que nasceu na escuridão vendo o amanhecer pela primeira vez."
  },
  AvgDialog_68329_Content_9 = {Text = "...@3..."},
  AvgDialog_68330_Content_1 = {
    Text = "Hoo hoo... Esse olho grande se fechou!"
  },
  AvgDialog_68330_Content_10 = {
    Text = "Acredito que ele suportará esta tempestade, navegando firmemente para frente, para sempre e sempre..."
  },
  AvgDialog_68330_Content_11 = {
    Text = "Eu lembro de poucas coisas, Guardião. Mas as muitas experiências em Mythag, e as aventuras com você, não me esqueci."
  },
  AvgDialog_68330_Content_12 = {
    Text = "O que você quer dizer com \"farol para navios\"? Eu não consigo entender. Eu só sei que se algo está quebrado, deve ser consertado, e se há algo que eu gosto, eu devo protegê-lo."
  },
  AvgDialog_68330_Content_13 = {
    Text = "As poucas memórias... Como você, eu não quero esquecê-las."
  },
  AvgDialog_68330_Content_14 = {
    Text = "Eu quero recordar o passado com você, e eu quero vivenciar novas aventuras junto com você."
  },
  AvgDialog_68330_Content_15 = {
    Text = "Isso... é minha crença!"
  },
  AvgDialog_68330_Content_16 = {
    Text = "Que cena apaixonante e vívida."
  },
  AvgDialog_68330_Content_17 = {
    Text = "Não estou muito interessado em batalhas ou fé. No entanto, com um corpo fraco enfrentando o deus supremo, levanto a lâmina quebrada em minha mão..."
  },
  AvgDialog_68330_Content_18 = {
    Text = "Nesta cena, vejo a beleza mais pura — as formas destemidas, as linhas firmes, que cativam o coração tão profundamente."
  },
  AvgDialog_68330_Content_19 = {
    Text = "Continue a batalha, Guardião. Mantenha sua fé e proteja tudo que você aprecia."
  },
  AvgDialog_68330_Content_2 = {
    Text = "Ouça, Guardião! As águas-vivas de Aurita estão ficando animadas!"
  },
  AvgDialog_68330_Content_20 = {
    Text = "Eu estarei com você e me tornarei parte desta grande escultura."
  },
  AvgDialog_68330_Content_3 = {
    Text = "Dizem que seguirão o Guardião e Aurita para proteger nossos companheiros!"
  },
  AvgDialog_68330_Content_4 = {
    Text = "Nesse olho flui uma fé maligna — é destruição total, uma profanação de tudo que é belo."
  },
  AvgDialog_68330_Content_5 = {
    Text = "E este mundo, que carrega o reino eterno, está reunindo a luz da esperança sob sua proteção."
  },
  AvgDialog_68330_Content_6 = {
    Text = "Guardião, para aqueles que estão perdidos neste mundo, você é o único farol neste momento."
  },
  AvgDialog_68330_Content_7 = {
    Text = "Nosso farol certamente permanecerá aceso para sempre."
  },
  AvgDialog_68330_Content_8 = {
    Text = "Esses olhos são um mar sem fim de perigo. Nosso mundo está balançando nesta tempestade, tremendo."
  },
  AvgDialog_68330_Content_9 = {
    Text = "Guardião, eu falhei em proteger o navio que me pertencia... Mas desta vez, eu vou proteger este \"navio\" junto com você."
  },
  AvgDialog_68331_Content_1 = {Text = "Formiga"},
  AvgDialog_68331_Content_10 = {
    Text = "Você segura a chave de prata e caminha para frente. Você sabe que sua luta não acabou.\nA batalha final acabou de começar"
  },
  AvgDialog_68331_Content_11 = {Text = "Boom!!—"},
  AvgDialog_68331_Content_12 = {
    Text = "Com uma tremenda convulsão, o poder que mantinha o impasse se despedaça. A fissura entre a Porta e a Poça Negra, como uma enorme ferida, é violentamente rasgada por uma força desconhecida."
  },
  AvgDialog_68331_Content_13 = {
    Text = "Com uma tremenda convulsão, o poder que mantinha o impasse se despedaça. A fissura entre a Porta e a Poça Negra, como uma enorme ferida, é violentamente rasgada por uma força desconhecida."
  },
  AvgDialog_68331_Content_14 = {
    Text = "Uma dor desgastante atinge seu peito. Você solta um gemido, cai de joelhos e ofega por ar."
  },
  AvgDialog_68331_Content_15 = {
    Text = "Por que... Seus olhos já desapareceram..."
  },
  AvgDialog_68331_Content_16 = {
    Text = "O Guardião perfurou Seu olhar. O verdadeiro Ele provavelmente chegará em breve..."
  },
  AvgDialog_68331_Content_17 = {
    Text = "<Shake:Urro—>"
  },
  AvgDialog_68331_Content_18 = {
    Text = "Rugidos profundos se sobrepõem. A Fenda d diante de nós rapidamente se expandiu e evoluiu, um evento sem precedentes na história de Mythag."
  },
  AvgDialog_68331_Content_19 = {
    Text = "A Dissolução devora tudo ao seu redor, transformando objetos em líquido negro que flui para o abismo, enquanto vários monstros da dissolução emergem de dentro."
  },
  AvgDialog_68331_Content_20 = {
    Text = "Eles são alheios a tudo ao redor, como manchas de tinta caóticas em uma tela, olhando para os arredores com tola ganância."
  },
  AvgDialog_68331_Content_21 = {
    Text = "Cego. Tolo. Sem sentido... Você não entende o que criou, Tohu Wabohu."
  },
  AvgDialog_68331_Content_22 = {
    Text = "Eu irei redefinir o valor deste mundo para você."
  },
  AvgDialog_68331_Content_23 = {
    Text = "Você olha para cima, olhando além das relíquias caóticas diante de você, em direção à sombra que cobre o mundo da porta inteira"
  },
  AvgDialog_68331_Content_24 = {
    Text = "Você está entre as criaturas aterrorizantes e o mundo atrás de você. Você caminha em direção a elas sozinho, como se estivesse se aproximando de uma colônia de formigas."
  },
  AvgDialog_68331_Content_3 = {
    Text = "Luz Prata, afiada como uma lâmina, perfurou o olho gigante."
  },
  AvgDialog_68331_Content_4 = {
    Text = "Uma fumaça densa jorra das pupilas, envolvendo instantaneamente o espaço aparentemente infinito atrás da Porta."
  },
  AvgDialog_68331_Content_5 = {
    Text = "A luz diminui, e os olhos que te observavam de inúmeras dimensões desaparecem de uma vez, como se nunca tivessem existido."
  },
  AvgDialog_68331_Content_6 = {
    Text = "Seus sentidos estão ofuscados pelo caos agitado pela névoa negra. Dentro da porta, reina um silêncio mortal."
  },
  AvgDialog_68331_Content_7 = {
    Text = "O céu ficou escuro..."
  },
  AvgDialog_68331_Content_8 = {
    Text = "Keeper... conseguiu?!"
  },
  AvgDialog_68331_Content_9 = {
    Text = "Tranquilidade. Tranquilidade é uma mentira confortante; você sabe disso muito bem."
  },
  AvgDialog_68332_Content_1 = {
    Text = "A cortina se levanta, e a performance chega ao fim—"
  },
  AvgDialog_68332_Content_10 = {
    Text = "Vamos lá, %player%, traga todas as minhas fichas, traga tudo que eu ganhei, e sente-se à mesa para a última jogada, enfrentando aquele dealer tolo, e então..."
  },
  AvgDialog_68332_Content_11 = {
    Text = "......ALL IN."
  },
  AvgDialog_68332_Content_12 = {
    Text = "O ritual sagrado do nascimento... Profanar o que nasce é imperdoável!"
  },
  AvgDialog_68332_Content_13 = {
    Text = "Eu não te subestimei, Guardião. Seguir seus passos foi a minha melhor decisão."
  },
  AvgDialog_68332_Content_14 = {
    Text = "Você fez isso. Eu sabia que você teria sucesso... %player%."
  },
  AvgDialog_68332_Content_15 = {
    Text = "Ela se aproxima de você, segurando sua mão. Aqueles olhos brilhantes olham para você sem piscar."
  },
  AvgDialog_68332_Content_16 = {
    Text = "O poder da Vida flui dentro de você, acalmando as inúmeras feridas em seu Corpo e Dimensão do Espírito."
  },
  AvgDialog_68332_Content_17 = {
    Text = "Você está muito cansado, não está? Está tudo bem. Apoie-se em mim e descanse bem..."
  },
  AvgDialog_68332_Content_18 = {
    Text = "Apenas o trecho final da estrada permanece... Eu o acompanharei até aquele ponto final."
  },
  AvgDialog_68332_Content_19 = {
    Text = "Atrás dele, seis asas cintilantes com luz pura tremulam levemente."
  },
  AvgDialog_68332_Content_2 = {
    Text = "Diante da verdadeira magia, nem mesmo o olhar do Criador consegue ver através."
  },
  AvgDialog_68332_Content_20 = {
    Text = "Ele sorri para você e levanta gentilmente Sua mão. A chave prateada em sua mão brilha com uma luz intensa."
  },
  AvgDialog_68332_Content_21 = {
    Text = "O olhar que O protegia foi destruído. Você conseguiu, Guardião. Esta é a primeira vez que realmente existe um ser capaz de rejeitá-Lo."
  },
  AvgDialog_68332_Content_22 = {
    Text = "Você está a apenas um passo da linha de chegada. Este passo será mais árduo do que todos os caminhos que você já percorreu."
  },
  AvgDialog_68332_Content_23 = {
    Text = "Você está pronto, %player%?"
  },
  AvgDialog_68332_Content_24 = {
    Text = "Estou pronto, Tawil"
  },
  AvgDialog_68332_Content_25 = {
    Text = "Você sorriu e acenou com a cabeça, segurando a Chave de prata alta na mão —"
  },
  AvgDialog_68332_Content_3 = {
    Text = "Fragmentos superam o corpo original; a forma falsa substitui a verdadeira. Que desempenho magnífico!"
  },
  AvgDialog_68332_Content_4 = {
    Text = "O olhar de Tohowabo foi destruído. Olhares restantes: 0."
  },
  AvgDialog_68332_Content_5 = {
    Text = "No Cálculo, a probabilidade de completar esta tarefa se aproxima de zero infinitamente."
  },
  AvgDialog_68332_Content_6 = {
    Text = "Você realizou uma tarefa impossível, Guardião do Segredo {Male=senhor,Female=senhora}."
  },
  AvgDialog_68332_Content_7 = {
    Text = "Que aposta, Guardião."
  },
  AvgDialog_68332_Content_8 = {
    Text = "\"Para uma taxa de vitória infinitesimalmente próxima de zero, aposte tudo o que você tem... Você não é um jogador. Você é um verdadeiro lunático.\""
  },
  AvgDialog_68332_Content_9 = {
    Text = "Sinto muito também."
  },
  AvgDialog_68333_Content_1 = {
    Text = "Luz Prata floresce, dissolução cai. Poder espiritual diminui, e mais feridas aparecem."
  },
  AvgDialog_68333_Content_11 = {
    Text = "Um olho preto se abriu abruptamente, como um meteoro das profundezas do universo, correndo em sua direção."
  },
  AvgDialog_68333_Content_12 = {
    Text = "No meio do intenso e incontrolável terror e dor, você luta para abrir os olhos e tenta distinguir Sua presença—"
  },
  AvgDialog_68333_Content_13 = {
    Text = "Um olho preto composto de incontáveis olhos menores, escaneando sem rumo até finalmente focar em você."
  },
  AvgDialog_68333_Content_14 = {
    Text = "Então perto, você pode quase ver as texturas intrincadas nele. Tão longe, até mesmo uma vida inteira não traria você mais perto. Entre você e isso está o tempo e o espaço em si."
  },
  AvgDialog_68333_Content_15 = {
    Text = "Você ouve um chamado de dentro, irresistivelmente atraído para aquele olho, para retornar—"
  },
  AvgDialog_68333_Content_16 = {
    Text = "Guardião! Ugh—"
  },
  AvgDialog_68333_Content_17 = {
    Text = "A voz de Ramona te assustou. Através da porta massiva, você viu sua figura frágil."
  },
  AvgDialog_68333_Content_18 = {
    Text = "Sob aqueles olhos opacos, até manter a racionalidade e pronunciar uma única palavra impôs uma imensa pressão sobre seu espírito."
  },
  AvgDialog_68333_Content_19 = {
    Text = "Seu poder bloqueou completamente os caminhos entre dimensões. Perdemos nossos vínculos uns com os outros, e Ele também perdeu os próprios olhos que um dia o protegeram..."
  },
  AvgDialog_68333_Content_2 = {
    Text = "Você é como uma máquina, repetindo mecanicamente seu comando, destruindo uma criatura aterrorizante de Dissolução após outra."
  },
  AvgDialog_68333_Content_20 = {
    Text = "Essência Dele, Seus olhos. Parte Dele chegou aqui.\nApenas mais um passo. Apenas um passo resta."
  },
  AvgDialog_68333_Content_21 = {
    Text = "Guardião... Guardião..."
  },
  AvgDialog_68333_Content_22 = {
    Text = "Deixe-nos..."
  },
  AvgDialog_68333_Content_23 = {
    Text = "Shhh, Ramona..."
  },
  AvgDialog_68333_Content_24 = {
    Text = "Você faz um gesto pedindo silêncio. Ramona quer gritar, mas nenhum som sai."
  },
  AvgDialog_68333_Content_25 = {
    Text = "Antes da Vontade Suprema, qualquer olhar ou palavra é um caminho para a morte."
  },
  AvgDialog_68333_Content_26 = {
    Text = "Você cobre a boca e os olhos dela. O caminho para a morte é tão estreito; uma pessoa é o suficiente."
  },
  AvgDialog_68333_Content_27 = {
    Text = "Você segura a chave de prata e se levanta com esforço. Você olha para Ele"
  },
  AvgDialog_68333_Content_28 = {
    Text = "\"A partir de hoje, eu irei ter sucesso como o Guardião do Mythag.\nEu juro ficar para sempre na vanguarda da luta da humanidade contra a Dissolução.\""
  },
  AvgDialog_68333_Content_29 = {
    Text = "\"Juro lutar sempre pela história e futuro da humanidade.\""
  },
  AvgDialog_68333_Content_3 = {
    Text = "Seus olhos não veem corpos dissolutos sem mente. Desde o começo até o fim, você observa a porta vazia e as estrelas tênues acima dela."
  },
  AvgDialog_68333_Content_30 = {
    Text = "\"Seja honra ou desgraça... seja vida ou morte.\""
  },
  AvgDialog_68333_Content_4 = {
    Text = "Você espera. À medida que todos os Corpos Dissolvidos são eliminados, a espessa névoa escura finalmente começa a dissipar."
  },
  AvgDialog_68333_Content_5 = {
    Text = "Você chegou..."
  },
  AvgDialog_68333_Content_6 = {
    Text = "...@3!! ..."
  },
  AvgDialog_68333_Content_7 = {
    Text = "Uma voz profunda e caótica reverbera através da porta, e o espaço ao seu redor de repente começa a tremer."
  },
  AvgDialog_68333_Content_8 = {
    Text = "Uma esfera gigantesca aparece neste espaço precário."
  },
  AvgDialog_68333_Content_9 = {
    Text = "...@3!!!..."
  },
  AvgDialog_68334_Content_1 = {
    Text = "Tão barulhento, tão barulhento! Aqueles sons que bagunçam minha cabeça poderiam simplesmente desaparecer?"
  },
  AvgDialog_68334_Content_10 = {
    Text = "Na verdade, eu também estou um pouco assustado e preciso do Guardião para dissipar o medo com uma dor doce~"
  },
  AvgDialog_68334_Content_11 = {
    Text = "Apenas brincando~ Desta vez, vou ficar sério."
  },
  AvgDialog_68334_Content_12 = {
    Text = "O olhar de Tohowabo ou qualquer outra coisa não pode extinguir a chama ardente do amor que tenho pelo Guardião!"
  },
  AvgDialog_68334_Content_13 = {
    Text = "Karen se lembrou do Lar, da lua do Lar, da cidade de pedra e dos rituais dançantes. Karen amava tudo isso e nunca permitiria que ninguém o destruisse!"
  },
  AvgDialog_68334_Content_14 = {
    Text = "E o Guardião do Segredo, {Male=ele,Female=ela} é o mestre de Karen, pertence a Karen, ninguém pode tirar!"
  },
  AvgDialog_68334_Content_15 = {
    Text = "O medo também é uma manifestação de poder. De fato, Seu poder supera o que qualquer um de nós pode imaginar, mas não iremos ceder."
  },
  AvgDialog_68334_Content_16 = {
    Text = "Guardião, vamos lutar. Eu farei Ele entender que a rosa é delicada, mas também tem espinhos."
  },
  AvgDialog_68334_Content_17 = {
    Text = "Escuridão, uma escuridão tão aterrorizante... Eu quero escapar e levar o Guardião comigo, mas não consigo."
  },
  AvgDialog_68334_Content_18 = {
    Text = "Eu experimentei a destruição uma vez e fugi uma vez; desta vez, não desejo mais fugir."
  },
  AvgDialog_68334_Content_19 = {
    Text = "Desta vez, estarei ao lado do Guardião. Sim, estarei ao seu lado, ao seu lado..."
  },
  AvgDialog_68334_Content_2 = {
    Text = "Só agora eu posso finalmente ter o suficiente para comer e estar com minha irmã. Todas essas mudanças são graças ao Guardião..."
  },
  AvgDialog_68334_Content_20 = {
    Text = "Quão lamentável, todos. Embora vocês saibam que serão destruídos por esse medo, ainda não entraram em colapso... Não entendem seu destino? O que vocês ainda estão lutando?"
  },
  AvgDialog_68334_Content_21 = {
    Text = "\"Não, não, isso não é uma luta. Não, isso é...\""
  },
  AvgDialog_68334_Content_22 = {
    Text = "O olhar de 24 se volta para o grupo. Sob aquele olhar aterrador que ninguém ousa encarar diretamente, diversas reações surgem. \nMas ninguém recua. Cada um tem algo que precisa proteger."
  },
  AvgDialog_68334_Content_23 = {
    Text = "Esta é a proteção, a última proteção."
  },
  AvgDialog_68334_Content_24 = {
    Text = "Precisamos proteger %player%."
  },
  AvgDialog_68334_Content_3 = {
    Text = "Então, mesmo que eu tenha medo, não... não recuarei."
  },
  AvgDialog_68334_Content_4 = {
    Text = "O ratinho está com medo? Hahaha, não há nada a temer."
  },
  AvgDialog_68334_Content_5 = {
    Text = "Enquanto tudo for consumido pelas chamas e afogado no massacre, até mesmo o medo pode ser abatido."
  },
  AvgDialog_68334_Content_6 = {
    Text = "Eu vivi por milhares de anos e nunca encontrei um oponente tão emocionante. Além disso, um Guardião está lutando ao meu lado."
  },
  AvgDialog_68334_Content_7 = {
    Text = "Sim, enquanto eu estiver perto do Guardião, posso suportar qualquer dor."
  },
  AvgDialog_68334_Content_8 = {
    Text = "Porque não importa que tipo de medo ou escuridão, o gentil cavaleiro sempre me ajudará a superar."
  },
  AvgDialog_68334_Content_9 = {
    Text = "Porque... eu pertenço a %player%."
  },
  AvgDialog_68335_Content_1 = {
    Text = "Que oponente formidável! Mas não é a emoção da batalha que torna tudo tão emocionante?"
  },
  AvgDialog_68335_Content_10 = {
    Text = "Muito bem, você quer destruir todos os deuses? Conte comigo para essa vingança."
  },
  AvgDialog_68335_Content_11 = {
    Text = "Então isso é o que tem manipulado o destino de todos nos bastidores... Verdadeiramente aterrorizante, verdadeiramente..."
  },
  AvgDialog_68335_Content_12 = {
    Text = "É bem irritante."
  },
  AvgDialog_68335_Content_13 = {
    Text = "\"Repetidamente, seja no passado ou no presente, com que fundamentos a destruição pode afirmar que destruiu! Eu nunca concordarei!\""
  },
  AvgDialog_68335_Content_14 = {
    Text = "Eu disse, o que estamos esperando? Vamos explodi-lo com força! Mostre a ele a ira do Senhor Pálido!"
  },
  AvgDialog_68335_Content_15 = {
    Text = "Olhe para cima. Ninguém além de mim pode fazer você se submeter."
  },
  AvgDialog_68335_Content_16 = {
    Text = "Proteger meu amado servo é o que um mestre deve fazer."
  },
  AvgDialog_68335_Content_17 = {
    Text = "Relaxe, você já sabe que estarei atrás de você."
  },
  AvgDialog_68335_Content_18 = {
    Text = "Que carinha problemática você é. Mesmo eu teria dor de cabeça lidando com uma comissão tão difícil."
  },
  AvgDialog_68335_Content_19 = {
    Text = "Sussurro, quem disse que você é meu cliente mais especial?"
  },
  AvgDialog_68335_Content_2 = {
    Text = "Eu sabia que seguir você seria divertido; a promessa que fizemos um ao outro não foi em vão afinal."
  },
  AvgDialog_68335_Content_20 = {
    Text = "A Loja Despreocupada está mais uma vez à sua disposição."
  },
  AvgDialog_68335_Content_3 = {
    Text = "Não posso esperar mais. Deixe-me aproveitar até o último momento!"
  },
  AvgDialog_68335_Content_4 = {
    Text = "De fato, a lâmina do guerreiro não conhece nem medo nem recuo."
  },
  AvgDialog_68335_Content_5 = {
    Text = "Uma vez por vingança, agora por proteção."
  },
  AvgDialog_68335_Content_6 = {
    Text = "Como sua lâmina, por favor, faça pleno uso da minha força. Nossa determinação de nunca recuar neste momento está perfeitamente alinhada."
  },
  AvgDialog_68335_Content_7 = {
    Text = "Como eu poderia dizer tal coisa? Que fracasso aquela versão fraca de mim mesmo foi."
  },
  AvgDialog_68335_Content_8 = {
    Text = "\"Mas hahahahaha, tão engraçado, é muito engraçado.\""
  },
  AvgDialog_68335_Content_9 = {
    Text = "Então isso é o que você tem lutado contra o tempo todo. Eu devo admitir, você é ainda mais arrogante do que eu."
  },
  AvgDialog_68336_Content_1 = {
    Text = "Adeus: k-0617"
  },
  AvgDialog_68336_Content_10 = {
    Text = "Ramona está diante da multidão, sua voz clara e firme enquanto lê o testamento. Apenas o papel em sua mão treme levemente."
  },
  AvgDialog_68336_Content_11 = {
    Text = "A cabeça dela estava baixa. Gotas caíam no papel, talvez chuva, talvez outra coisa."
  },
  AvgDialog_68336_Content_12 = {
    Text = "\"Eu os segui até Mythag. O que mais eu poderia fazer? Eu não sei o que é Akut, nem sei quem ou o que eu sou.\""
  },
  AvgDialog_68336_Content_13 = {
    Text = "\"Só consigo lembrar de alguns conhecimentos básicos, como os humanos precisam comer e dormir.\nFelizmente, Mythag acontece de conseguir atender a ambas as necessidades.\""
  },
  AvgDialog_68336_Content_14 = {
    Text = "\"Durante meus primeiros dias aqui, o encantador restaurante e dormitório da Mythag me fizeram sentir que minha escolha estava absolutamente correta—\""
  },
  AvgDialog_68336_Content_15 = {
    Text = "\"Foi só uma semana depois que eu me matriculei oficialmente.\""
  },
  AvgDialog_68336_Content_16 = {
    Text = "\"Um aviso a todas as criaturas miseráveis ansiando por Mythag: Mythag é o lar de um grupo de diabos.\""
  },
  AvgDialog_68336_Content_17 = {
    Text = "\"Treinam-nos em condição física, esgrima, primeiros socorros, uso de Prata, reconhecimento de Entidades de Fusão...\""
  },
  AvgDialog_68336_Content_18 = {
    Text = "\"Estudantes como Ramona e o Senor William são os herdeiros do Inferno, prosperando neste tormento como se fossem peixes na água.\""
  },
  AvgDialog_68336_Content_19 = {
    Text = "\"E eu fui atormentado no Inferno por um ano. Cada aula me faz sentir que, em minhas memórias perdidas, provavelmente cometi algum pecado imperdoável e agora devo suportar punição no Inferno.\""
  },
  AvgDialog_68336_Content_2 = {
    Text = "\"Posso pular isso? Isso parece realmente ominoso. Foi isso que perguntei a Ramona.\""
  },
  AvgDialog_68336_Content_20 = {
    Text = "\"Muitas pessoas me disseram que possuo um talento notável. Olhando para meus boletins, que mal passam da média, realmente não consigo entender como poderiam dizer tal coisa.\""
  },
  AvgDialog_68336_Content_21 = {
    Text = "\"Naquele dia, na primeira aula de Link dos Despertadores, passei cinco minutos estabelecendo links iniciais com três Despertadores.\""
  },
  AvgDialog_68336_Content_22 = {
    Text = "\"A força espiritual de um investigador pode suportar aproximadamente a ligação de um Despertar. A escola estava em alvoroço. Não tenho certeza se isso é uma boa ou má notícia.\""
  },
  AvgDialog_68336_Content_23 = {
    Text = "\"O Professor Alistair me disse que todos os talentos vêm com um preço. Eu tenho meu próprio caminho a seguir, um caminho que é difícil e solitário. Eu terei que suportar muito e abrir mão de muito.\""
  },
  AvgDialog_68336_Content_24 = {
    Text = "\"Ele me perguntou se eu queria caminhar por este caminho. Eu não respondi.\""
  },
  AvgDialog_68336_Content_25 = {
    Text = "\"Eu sou uma pessoa com sonhos. Meu sonho é sentar ao lado de uma lareira quente com aquele que eu amo, desperdiçando nossas vidas insignificantes.\""
  },
  AvgDialog_68336_Content_26 = {
    Text = "«A neve lá fora está caindo lentamente, ano após ano, até o dia em que morrermos de velhice. Na minha lápide estará escrito: {Male=ele,Female=ela} era um inútil com longa vida e feliz.»"
  },
  AvgDialog_68336_Content_27 = {
    Text = "\"Guardião. Além de ganhar mais dinheiro, este título não tem nada a ver com meu sonho...\""
  },
  AvgDialog_68336_Content_28 = {
    Text = "Toc, toc, toc—"
  },
  AvgDialog_68336_Content_29 = {
    Text = "O Ritual do Tombamento da Chave começa amanhã. Você já escreveu seu testamento, %jogador%?"
  },
  AvgDialog_68336_Content_3 = {
    Text = "\"Ela disse não. Todo Guardião deve deixar um testamento antes de suceder.\""
  },
  AvgDialog_68336_Content_30 = {
    Text = "Você precisa fazer parecer tão sinistro...?"
  },
  AvgDialog_68336_Content_31 = {
    Text = "Ter coragem para enfrentar a dissolução é uma qualidade fundamental de um investigador. Como sucessor de um Guardião, isso é ainda mais crucial."
  },
  AvgDialog_68336_Content_32 = {
    Text = "É tão fácil de dizer... Ramona, sério, você realmente pensou bem sobre isso?"
  },
  AvgDialog_68336_Content_33 = {
    Text = "Estou aqui há um ano e visitei o Cofre muitas vezes. Muitos foram agraciados com Chaves de Prata, e muitas Chaves de Prata foram recuperadas devido à morte de seus proprietários."
  },
  AvgDialog_68336_Content_34 = {
    Text = "Eles dedicaram suas vidas, mas todas as suas conquistas serão esquecidas, e nem mesmo seus nomes permanecerão. No final, apenas uma lápide sem nome será deixada."
  },
  AvgDialog_68336_Content_35 = {
    Text = "Você pergunta, o que eles pensam antes de morrer?"
  },
  AvgDialog_68336_Content_36 = {
    Text = "Eles sentirão medo, dor e arrependimento, mas nunca remorso."
  },
  AvgDialog_68336_Content_37 = {
    Text = "Porque atrás deles está tudo o que eles prezam. Porque à frente deles, não há mais ninguém."
  },
  AvgDialog_68336_Content_38 = {
    Text = "Eu perguntei ao Senhoria William, e ele respondeu exatamente como você."
  },
  AvgDialog_68336_Content_39 = {
    Text = "Não sei, Ramona."
  },
  AvgDialog_68336_Content_4 = {
    Text = "\"Ela me tranquilizou, dizendo que a manteria segura e a leria antes que se dissolvesse completamente após minha morte.\""
  },
  AvgDialog_68336_Content_40 = {
    Text = "Todos dizem que sou a esperança de Mythag... Mas eu sei que tipo de pessoa eu sou."
  },
  AvgDialog_68336_Content_41 = {
    Text = "Buscando prazer, sendo egoísta e covarde. Estou com medo da Dissolução, com medo da morte. Todos os dias, penso em como viver de maneira mais confortável e prolongar minha vida."
  },
  AvgDialog_68336_Content_42 = {
    Text = "Na minha primeira missão de campo, eu caminhei atrás de todos, apavorada de pegar a Dissolução. Eu tinha apenas vinte anos, com tantos sonhos..."
  },
  AvgDialog_68336_Content_43 = {
    Text = "Ramona, você acha que alguém como eu merece ser o Guardião?"
  },
  AvgDialog_68336_Content_44 = {
    Text = "Em sua imaginação, Ramona ficaria desapontada e com raiva, apontaria seu rapier para você, balançaria a cabeça e slamaria a porta como sempre faz sempre que você reclama sobre não terminar suas tarefas."
  },
  AvgDialog_68336_Content_45 = {
    Text = "Mas ela não o fez. Ela assistiu e ouviu sua narração em silêncio.\nEla sorriu para você, como no dia em que conheceu Akut."
  },
  AvgDialog_68336_Content_46 = {
    Text = "Uma vida comum, quem não gostaria...? Cada Guardião do Segredo e investigador já duvidou disso em algum momento. Alguns escolheram recuar, outros escolheram continuar em frente..."
  },
  AvgDialog_68336_Content_47 = {
    Text = "O mundo nunca pediu isso deles, nem eles pensaram em dar tudo por isso. Mas, em algum momento, eles ainda fizeram escolhas que não conseguiam entender."
  },
  AvgDialog_68336_Content_48 = {
    Text = "Algumas escolhas são instintivas. Você também não é uma exceção, %player%."
  },
  AvgDialog_68336_Content_49 = {
    Text = "O tempo restante é seu para usar como desejar."
  },
  AvgDialog_68336_Content_5 = {
    Text = "\"Ramona é boa em tudo, mas sua língua afiada rivaliza até com a do Professor Doll.\""
  },
  AvgDialog_68336_Content_50 = {
    Text = "Não importa o que você decida, os portões de Mythag estarão sempre abertos para você."
  },
  AvgDialog_68336_Content_51 = {
    Text = "Que a Chave de Prata nos guie"
  },
  AvgDialog_68336_Content_52 = {Text = "..."},
  AvgDialog_68336_Content_53 = {
    Text = "\"Depois que Ramona partiu, eu pensei muito. Relembrei tudo deste ano em Mythag.\""
  },
  AvgDialog_68336_Content_54 = {
    Text = "\"Eu gosto de muitas coisas. As histórias que o Professor Alistair conta, os bilhetes passados durante os exames, os bolos da cantina da escola e o álcool que o Professor Dexter me esconde...\""
  },
  AvgDialog_68336_Content_55 = {
    Text = "\"Odeio tantas coisas. A cara da Ramona quando os meus trabalhos de casa estão por fazer, o Professor Doll a olhar para mim como se eu fosse idiota, as aulas de esgrima do Lotan, os exames finais absurdos, todo o treino físico, a interminável Dissolução...\""
  },
  AvgDialog_68336_Content_56 = {
    Text = "\"Minhas memórias abrangem apenas um ano, e todas elas estão conectadas a Mythag.\""
  },
  AvgDialog_68336_Content_57 = {
    Text = "\"Eu odeio este lugar. Eu estou preso a este lugar. Mas de qualquer forma, eu não posso deixá-lo.\""
  },
  AvgDialog_68336_Content_58 = {
    Text = "\"Você errou, Ramona. Eu talvez não seja tão miserável assim, mas certamente não tão nobre quanto você pensa. Sou apenas uma pessoa comum, nada além disso.\""
  },
  AvgDialog_68336_Content_59 = {
    Text = "\"Mas... eu tenho a resposta para a pergunta do Professor Alistair.\""
  },
  AvgDialog_68336_Content_6 = {
    Text = "\"Um ano atrás, quando abri meus olhos pela primeira vez em Akut, a primeira coisa que vi foi o rosto de Ramona.\""
  },
  AvgDialog_68336_Content_60 = {
    Text = "\"Pelo Mythag, por todos vocês, eu irei ter sucesso como o Guardião. Eu caminharei pelo caminho destinado para mim.\""
  },
  AvgDialog_68336_Content_61 = {
    Text = "\"Mas eu ainda viverei bem. Vou viver até os noventa ou cem anos e morrer de velhice.\""
  },
  AvgDialog_68336_Content_62 = {
    Text = "\"Eu vou lidar com a Dissolução enquanto uso meus dias de férias. Eu vou comer cada prato que desejo e ver cada vista que anseio.\""
  },
  AvgDialog_68336_Content_63 = {
    Text = "\"Se eu encontrar um problema insolúvel, eu vou correr o mais longe possível.\""
  },
  AvgDialog_68336_Content_64 = {
    Text = "\"Isto provavelmente não será necessário... Infelizmente, Mythag, você logo terá o Guardião mais covarde da sua história.\""
  },
  AvgDialog_68336_Content_65 = {
    Text = "\"Mas se, e quero dizer _se_, algum dia isso for realmente lido em voz alta, então algo deve estar muito errado com minha mente.\""
  },
  AvgDialog_68336_Content_66 = {
    Text = "\"Mas eu espero que a voz que a recita traga conforto.\""
  },
  AvgDialog_68336_Content_67 = {
    Text = "\"Se eu morrer...\""
  },
  AvgDialog_68336_Content_68 = {
    Text = "\"Isso deve ser porque eu encontrei algo mais importante.\""
  },
  AvgDialog_68336_Content_69 = {
    Text = "\"Mais importante do que bolos pequenos, mais importante do que uma lareira aconchegante, e mais importante do que a vida em si.\""
  },
  AvgDialog_68336_Content_7 = {
    Text = "\"Naquela época, ela ainda era muito educada. Talvez a pressão dos estudos realmente tenha sido demais ultimamente...\""
  },
  AvgDialog_68336_Content_70 = {
    Text = "\"Talvez eu tenha pisado em um caminho de dificuldades e solidão.\""
  },
  AvgDialog_68336_Content_71 = {
    Text = "\"Talvez eu sacrifiquei minha vida e tudo o que eu mais estimava, apenas adiando o desastre, não resolvendo nada e não mudando nada.\""
  },
  AvgDialog_68336_Content_72 = {
    Text = "\"Mas eu certamente morri em imensa felicidade.\""
  },
  AvgDialog_68336_Content_73 = {Text = "..."},
  AvgDialog_68336_Content_74 = {
    Text = "O som parou."
  },
  AvgDialog_68336_Content_75 = {
    Text = "A chuva continuou a cair, e Mythag permaneceu em silêncio."
  },
  AvgDialog_68336_Content_76 = {
    Text = "Todos os olhos estão voltados para a Poça Negra."
  },
  AvgDialog_68336_Content_77 = {
    Text = "Debaixo da torre do relógio, nas profundezas da terra, dentro daquela porta massiva e sombria, uma figura envolta em asas permanece perfeitamente imóvel."
  },
  AvgDialog_68336_Content_78 = {
    Text = "{Male=ele,Female=ela} ouve as gotas de chuva de Mythag caírem sobre o monumento. {Male=ele,Female=ela} ouve Ramona recitando com voz embargada. {Male=ele,Female=ela} ouve a dissolução negra se espalhar, lentamente cobrindo seu próprio nome."
  },
  AvgDialog_68336_Content_79 = {
    Text = "Neste sonho prolongado, {Male=ele,Female=ela} continua a cair, cair. Aquelas vozes ficam cada vez mais distantes de {Male=ele,Female=ela}, gradualmente se unindo em um gemido profundo."
  },
  AvgDialog_68336_Content_8 = {
    Text = "Gotas de chuva caíam, caindo sobre as lápides sem nome e sobre as cabeças da multidão."
  },
  AvgDialog_68336_Content_80 = {
    Text = "Na queda de {Male=ele,Female=ela}, todas as memórias do passado surgiram diante de {Male=ele,Female=ela}, como raios de luz, passando por ele/ela um após o outro."
  },
  AvgDialog_68336_Content_81 = {
    Text = "O rosto adormecido, a boca vazia levemente curvada para cima. \nA história de {Male=ele,Female=ela} é desconhecida para todos. A memória de {Male=ele,Female=ela} permanece para sempre.\n\n."
  },
  AvgDialog_68336_Content_82 = {
    Text = "{Male=ele,Female=ela} levantou as próprias mãos inexistentes e, em direção ao vazio distante, agitou-as suavemente."
  },
  AvgDialog_68336_Content_83 = {
    Text = "Adeus... Mythag."
  },
  AvgDialog_68336_Content_9 = {
    Text = "Despertadores, estudantes e funcionários... Todos estavam em pé solenemente no cemitério. Até mesmo o Despertador mais barulhento geralmente permaneceu em silêncio."
  },
  AvgDialog_68337_Content_1 = {
    Text = "Aquelas cores, Lily reconhece... Foi Eles que levaram a Mãe embora."
  },
  AvgDialog_68337_Content_10 = {
    Text = "Aqueles olhares são todos meu público. Eu oferecerei meu mais puro... Dança da Chama Verde a Eles."
  },
  AvgDialog_68337_Content_11 = {
    Text = "O bizarro e o caos são a verdade que Ele clama. Mas a dignidade humana é construída exclusivamente sobre a razão."
  },
  AvgDialog_68337_Content_12 = {
    Text = "Vamos, %player%."
  },
  AvgDialog_68337_Content_13 = {
    Text = "Vá compreender a verdade do universo... e transcender a própria verdade."
  },
  AvgDialog_68337_Content_2 = {
    Text = "Lily não quer mais ver isso. Lily vai detê-los junto com %player%!"
  },
  AvgDialog_68337_Content_3 = {
    Text = "O Decano e Lily... A história deles não deve se repetir."
  },
  AvgDialog_68337_Content_4 = {
    Text = "As flores que ainda não brotaram não deveriam murchar assim..."
  },
  AvgDialog_68337_Content_5 = {
    Text = "Nesse olhar flui uma cor mais aterrorizante do que as estrelas. Mas você fez isso... Foi você quem os parou."
  },
  AvgDialog_68337_Content_6 = {
    Text = "Nossa terra natal já foi destruída por cores como essas... Guardião do Segredo {Male=senhor,Female=senhora}, por favor, continue em frente e salve nosso lar, conquistado com tanto esforço."
  },
  AvgDialog_68337_Content_7 = {
    Text = "Nesta estrada que se estende mais longe do que a vasta extensão estelar, minha canção ecoará para sempre em seus ouvidos."
  },
  AvgDialog_68337_Content_8 = {
    Text = "Toda arte, toda beleza, não deve simplesmente desaparecer assim."
  },
  AvgDialog_68337_Content_9 = {
    Text = "O canto de Tinkter já começou. Testemunhe, Guardião do Segredo {Male=senhor,Female=senhora}."
  },
  AvgDialog_69820_Content_1 = {
    Text = "Opressão, Destruição, Caos... Esta é sua verdadeira essência, Tohuwabohu..."
  },
  AvgDialog_69820_Content_2 = {
    Text = "Seu olhar se concentrou totalmente aqui."
  },
  AvgDialog_69820_Content_3 = {
    Text = "Antes que Ele desperte totalmente... quebre-O completamente atrás desta Porta!"
  },
  AvgDialog_69821_Content_1 = {
    Text = "Realmente... chegou ao limite...?"
  },
  AvgDialog_69821_Content_2 = {
    Text = "O olhar de Tohowabo nunca esteve tão fraco..."
  },
  AvgDialog_69821_Content_3 = {
    Text = "Hehehehe... Hahaha! Maravilhoso, maravilhoso."
  },
  AvgDialog_69821_Content_4 = {
    Text = "Você me deu uma performance incrivelmente maravilhosa, impostor."
  },
  AvgDialog_69821_Content_5 = {
    Text = "Feche os olhos, %player%. Sinta-nos, absorva-nos..."
  },
  AvgDialog_69821_Content_6 = {
    Text = "\"A autoridade da Tríade convergiu em suas mãos.\""
  },
  AvgDialog_69821_Content_7 = {
    Text = "Use este poder que é exclusivamente seu, %player%."
  },
  AvgDialog_69821_Content_8 = {
    Text = "Deixe a Suprema Vontade cair em eterno sono!"
  },
  AvgDialog_69822_Content_1 = {
    Text = "Reino, súditos e os perdidos."
  },
  AvgDialog_69822_Content_2 = {
    Text = "Aquela sensação, eu não quero experimentá-la novamente."
  },
  AvgDialog_69822_Content_3 = {
    Text = "\"Isso não vai acontecer, Tulu... Eu definitivamente protegerei tudo isso...\""
  },
  AvgDialog_69823_Content_1 = {
    Text = "Na vasta e interminável extensão do tempo, a ausência da companhia de alguém torna tudo muito mais entediante."
  },
  AvgDialog_69823_Content_2 = {
    Text = "Você viu meu rosto. Você não vai esquecê-lo, vai?"
  },
  AvgDialog_69823_Content_3 = {
    Text = "Claro que, Senhora Narciso..."
  },
  AvgDialog_69824_Content_1 = {
    Text = "Grande {Male=Sr. Guardião,Female=Srta. Guardiã} disse que cuidaria bem da Lily em nome da mãe..."
  },
  AvgDialog_69824_Content_2 = {
    Text = "Grande {Male=Sr. Guardião,Female=Srta. Guardiã} vai cumprir sua promessa, certo?"
  },
  AvgDialog_69824_Content_3 = {
    Text = "Isso mesmo... Lily... Eu vou cumprir minha promessa..."
  },
  AvgDialog_69825_Content_1 = {
    Text = "Passei por tanto trabalho para trazer a chave para você; lembre-se da promessa que você me fez!"
  },
  AvgDialog_69825_Content_2 = {
    Text = "\"Não se esqueça de mim!\""
  },
  AvgDialog_69825_Content_3 = {
    Text = "Jenkin... Eu me lembro..."
  },
  AvgDialog_69826_Content_1 = {
    Text = "Guardião, eu sempre me lembrarei da ajuda que você me deu..."
  },
  AvgDialog_69826_Content_2 = {
    Text = "Eu não sou mais aquela criança que só sabia correr..."
  },
  AvgDialog_69826_Content_3 = {
    Text = "Desta vez, sei exatamente o que preciso fazer!"
  },
  AvgDialog_69826_Content_4 = {Text = "Aigis..."},
  AvgDialog_69827_Content_1 = {
    Text = "Ignorância@2...@2 profanação...@4 o fim!..."
  },
  AvgDialog_69827_Content_10 = {
    Text = "A obsessão de {Male=ele,Female=ela}, os sentimentos de {Male=ele,Female=ela}, algo que {Male=ele,Female=ela} valoriza mais do que a própria vida…"
  },
  AvgDialog_69827_Content_11 = {
    Text = "O que pode contra-atacar a Dissolução, do começo ao fim, é \"Link\"."
  },
  AvgDialog_69827_Content_12 = {
    Text = "Venha se lembrar, %player%. Recorde tudo o que você viveu com eles..."
  },
  AvgDialog_69827_Content_2 = {
    Text = "Uh ah ah ah! —"
  },
  AvgDialog_69827_Content_3 = {
    Text = "Uma onda de choques sem precedentes e inimagináveis se apressa em direção à sua Dimensão Espírito. Uma Fenda d explode em sua mente sob o olhar de Tohuwabohu."
  },
  AvgDialog_69827_Content_4 = {
    Text = "Incontáveis dissoluções líquidas surgem em sua mente, corroendo tudo dentro do seu cérebro."
  },
  AvgDialog_69827_Content_5 = {
    Text = "Tsk tsk tsk... Não o via demonstrar emoções há muito tempo. Impressionante, impostor."
  },
  AvgDialog_69827_Content_6 = {
    Text = "Infelizmente, você perdeu tudo. Sua Memória, sua Capacidade... até sua Autoridade está sendo Dissolvida."
  },
  AvgDialog_69827_Content_7 = {
    Text = "Este ato termina aqui."
  },
  AvgDialog_69827_Content_8 = {
    Text = "Ainda não acabou, N."
  },
  AvgDialog_69827_Content_9 = {
    Text = "Oh? Existe mesmo algo que pode combater a Dissolução primordial?"
  },
  AvgDialog_69828_Content_1 = {
    Text = "Mais uma vez, esta opressão avassaladora... Eu sei o que você quer fazer. Mas a situação é diferente da última vez, Tohwa Po."
  },
  AvgDialog_69828_Content_2 = {
    Text = "Seu olhar através das inúmeras dimensões foi despedaçado por nós. Você agora perdeu sua proteção."
  },
  AvgDialog_69828_Content_3 = {
    Text = "Revele sua verdadeira forma. Desta vez, eu definitivamente o manterei aqui!"
  },
  AvgDialog_69829_Content_1 = {
    Text = "Sua respiração mudou..."
  },
  AvgDialog_69829_Content_2 = {
    Text = "A autoridade da tolice e da criação. Esta guerra ainda não acabou... Heh, tenha cuidado, impostor."
  },
  AvgDialog_69829_Content_3 = {
    Text = "Ainda estou ansioso pelo tipo de surpresa que você pode me trazer."
  },
  AvgDialog_69830_Content_1 = {
    Text = "Dentro do seu corpo flui minha Semente, minha Autoridade."
  },
  AvgDialog_69830_Content_2 = {
    Text = "Fizemos uma promessa. Você me ajudará a proteger este mundo, proteger nossas memórias..."
  },
  AvgDialog_69830_Content_3 = {
    Text = "Você pode definitivamente cumprir sua palavra, certo, %player%?"
  },
  AvgDialog_69830_Content_4 = {
    Text = "O que prometi a você, farei, Thais..."
  },
  AvgDialog_69831_Content_1 = {
    Text = "Esta jovem passou por tanto trabalho para acompanhá-lo até aqui."
  },
  AvgDialog_69831_Content_2 = {
    Text = "Você não pode simplesmente esquecer e sair, Guardião!"
  },
  AvgDialog_69831_Content_3 = {
    Text = "Fique tranquilo, Murphy... Não esquecerei tudo o que você vivenciou."
  },
  AvgDialog_71791_Content_1 = {Text = "Trono"},
  AvgDialog_71791_Content_10 = {Text = "..."},
  AvgDialog_71791_Content_100 = {
    Text = "Ele veria claramente Lemúria afundando em Aequor, sem sobreviventes."
  },
  AvgDialog_71791_Content_11 = {
    Text = "Anteontem, levei cem ostras de pérola que passei um tempão pescando e me declarei para Ela — e ela aceitou!"
  },
  AvgDialog_71791_Content_12 = {
    Text = "Só não sei por que ela fica me Xingando de idiota. Todas as meninas não gostam de pérolas?"
  },
  AvgDialog_71791_Content_13 = {Text = "..."},
  AvgDialog_71791_Content_14 = {
    Text = "Vamos realizar nosso casamento no Mirante do Mar em breve — o único casamento a receber a Bênção do Rei. Só de pensar nisso já me sinto tão glorioso!"
  },
  AvgDialog_71791_Content_15 = {Text = "..."},
  AvgDialog_71791_Content_16 = {
    Text = "Tulu, você sabia? Os pés de um bebê na verdade não têm cheiro nenhum! Até têm uma fragrância suave. Por que será..."
  },
  AvgDialog_71791_Content_17 = {Text = "..."},
  AvgDialog_71791_Content_18 = {
    Text = "Os breves e fugazes momentos de vigília nunca eram suficientes para Tulu participar pessoalmente de qualquer atividade. Tudo que ele podia fazer era ouvir em silêncio tudo o que havia perdido."
  },
  AvgDialog_71791_Content_19 = {
    Text = "Sempre que Noah se afastava para dar passagem aos Sacerdotes que haviam corrido ao ouvir a notícia, o olhar com que Tulu observava sua figura se afastando tornava-se especialmente solitário."
  },
  AvgDialog_71791_Content_2 = {
    Text = "No eterno Sonho longo do divino, algumas respirações já abrangem toda a vida de um mortal."
  },
  AvgDialog_71791_Content_20 = {
    Text = "(<Gray:Noah sempre foi um pouco mais velho que você. É perfeitamente normal que ele se case e tenha filhos mais cedo...>)"
  },
  AvgDialog_71791_Content_21 = {
    Text = "(<Gray:É bom que ele possa seguir vivendo tão feliz.>)"
  },
  AvgDialog_71791_Content_22 = {
    Text = "Como se respondesse à sua consolação, a voz interior de Tulu de repente chegou até você, para sua grande surpresa."
  },
  AvgDialog_71791_Content_23 = {
    Text = "(<Gray:Apenas, por quanto tempo mais serei capaz de ouvir histórias como essas?>)"
  },
  AvgDialog_71791_Content_24 = {
    Text = "No olhar reverente do padre, você viu suas pupilas refletindo a aparência inalterada de Tulu, apesar de seu Sono Profundo cada vez mais frequente."
  },
  AvgDialog_71791_Content_25 = {
    Text = "O preço de se tornar rei já havia começado a ser cobrado no momento em que a Coroa foi colocada sobre sua cabeça."
  },
  AvgDialog_71791_Content_26 = {Text = "..."},
  AvgDialog_71791_Content_27 = {
    Text = "Tenho me sentido um tanto fatigado nos últimos dois dias, não sei por quê. Até sonhei com Amos e Samuel..."
  },
  AvgDialog_71791_Content_28 = {
    Text = "Toda vez que sonho com aquele dia, perco um pouco de sono... Ai, não vamos falar sobre isso."
  },
  AvgDialog_71791_Content_29 = {Text = "..."},
  AvgDialog_71791_Content_3 = {Text = "..."},
  AvgDialog_71791_Content_30 = {
    Text = "*tosse tosse* Tulu, minha Doença piorou recentemente. Preciso de uns dias de descanso..."
  },
  AvgDialog_71791_Content_31 = {
    Text = "Mas não se preocupe, eu voltarei em breve para fazer companhia a você!"
  },
  AvgDialog_71791_Content_32 = {Text = "..."},
  AvgDialog_71791_Content_33 = {
    Text = "Entre os inúmeros Sonhos repletos de mistérios e Profecias, os que Tulu mais desprezava eram aqueles que prenunciavam a morte."
  },
  AvgDialog_71791_Content_34 = {
    Text = "Mas quando a Ilusão da morte de Noah apareceu em seu Sonho, você — compartilhando essa visão com Tulu — viu uma expressão extraordinariamente calma em seu rosto."
  },
  AvgDialog_71791_Content_35 = {
    Text = "No instante seguinte, Tulu Rasgou o Sonho. Saltou da cama, dispensou com um gesto o Escudeiro que substituía o há muito adoentado Noah, e empurrou a Porta para sair de seus aposentos sozinho."
  },
  AvgDialog_71791_Content_36 = {
    Text = "(<Gray:Mais rápido. Ainda mais rápido.>)"
  },
  AvgDialog_71791_Content_37 = {
    Text = "Seu passo ficou cada vez mais rápido, até que por fim ele corria em direção à residência de Noah com quase nenhuma aparência de dignidade real."
  },
  AvgDialog_71791_Content_38 = {
    Text = "Quando finalmente chegou à porta de onde se ouviam fracos lamentos, o pequeno espaço diante da casa de Noah já estava tomado por sua família."
  },
  AvgDialog_71791_Content_39 = {
    Text = "Ah... Vossa Majestade?"
  },
  AvgDialog_71791_Content_4 = {
    Text = "Como a \"pessoa\" mais próxima dele, você acompanhou Tulu durante sua infância após se tornar herdeiro, durante a grande cerimônia de adoração nacional em sua coroação, e através de um Sono Profundo após o outro."
  },
  AvgDialog_71791_Content_40 = {
    Text = "A multidão imediatamente se abriu para formar uma estreita passagem para Tulu. Sem fôlego, Tulu parou diante da Porta, seu olhar atravessando aquele estreito vão largo o suficiente para uma pessoa, e viu uma luz repentina acender-se nos olhos turvos de Noah."
  },
  AvgDialog_71791_Content_41 = {
    Text = "Os lábios pálidos de Noah tremeram como se tentassem dizer algo, mas congelaram para sempre em um único instante, enrijecendo-se no que parecia um sorriso inacabado."
  },
  AvgDialog_71791_Content_42 = {Text = "Waah—"},
  AvgDialog_71791_Content_43 = {
    Text = "O choro da criança soou como um dobre de finados repentino, anunciando a chegada de um fim irreversível."
  },
  AvgDialog_71791_Content_44 = {
    Text = "A esposa de Noah puxou para trás o menino que não parava de sacudir o braço do pai, mas ela mesma não conseguiu conter um soluço que escapou por entre a mão pressionada contra a boca."
  },
  AvgDialog_71791_Content_45 = {
    Text = "Era um homem tão jovem... Como pôde simplesmente desabar assim..."
  },
  AvgDialog_71791_Content_46 = {
    Text = "Ai, dizem que alguma enfermidade se enraizou nele naquela época. Que infortúnio..."
  },
  AvgDialog_71791_Content_47 = {
    Text = "Ele aguentou tanto tempo no leito de morte. Graças aos céus, finalmente conseguiu ver o Rei..."
  },
  AvgDialog_71791_Content_48 = {
    Text = "Em meio à multidão que chorava e lamentava, Tulu fitava com o olhar vazio o rosto de seu amigo — há muito amadurecido, e devastado pela doença até uma decadência macilenta."
  },
  AvgDialog_71791_Content_49 = {
    Text = "A esposa de Noah, com o rosto banhado em lágrimas, pareceu lembrar-se subitamente de algo. Apressadamente enxugou os olhos e, engolindo os soluços, trouxe uma pequena caixa e entregou-a a Tulu."
  },
  AvgDialog_71791_Content_5 = {
    Text = "A maioria dos companheiros daquela época Retornou a vidas normais, enquanto alguns seguiram o Velho sumo sacerdote e se tornaram membros do Sacerdócio."
  },
  AvgDialog_71791_Content_50 = {
    Text = "Isto é o que Noah insistiu que eu lhe entregasse. Ele... Ele deixou uma última mensagem para você..."
  },
  AvgDialog_71791_Content_51 = {
    Text = "Tulu abriu a tampa. Dentro havia alguns pedaços de biscoito amanteigado de Amaranto, idênticos aos da infância deles."
  },
  AvgDialog_71791_Content_52 = {
    Text = "\"Eu sabia que você viria.\""
  },
  AvgDialog_71791_Content_53 = {
    Text = "(<Gray:Mas eu... Ainda assim cheguei tarde...>)"
  },
  AvgDialog_71791_Content_54 = {
    Text = "De repente, em meio aos gritos assustados e às tentativas dos adultos de contê-la, um pequeno lenço floral apareceu diante dos olhos de Tulu."
  },
  AvgDialog_71791_Content_55 = {
    Text = "A inocente filhinha de Noah segurava um lenço amassado o mais alto que podia, esticando-se para oferecê-lo a Tulu."
  },
  AvgDialog_71791_Content_56 = {
    Text = "Tulu aceitou o lenço em um torpor. Instintivamente tocou a própria bochecha e, com uma expressão de leve surpresa, sentiu a umidade ali."
  },
  AvgDialog_71791_Content_57 = {
    Text = "Em algum momento, sem perceber, as lágrimas já haviam começado a cair."
  },
  AvgDialog_71791_Content_58 = {
    Text = "(<Gray:Eu sempre soube, então por quê...>)"
  },
  AvgDialog_71791_Content_59 = {
    Text = "Tulu abriu a boca, mas antes que pudesse dizer qualquer coisa, um conjunto de passos ordenados se aproximou por trás."
  },
  AvgDialog_71791_Content_6 = {
    Text = "Apenas Noah Firmemente escolheu se tornar Escudeiro de Tulu, silenciosamente montando guarda diante dos aposentos do Novo rei."
  },
  AvgDialog_71791_Content_60 = {
    Text = "Minhas desculpas, Vossa Majestade. Ao saber de seu despertar, trouxe documentos que requerem sua revisão e aprovação. Suas horas de vigília são extremamente preciosas. Pelo bem de Lemuria, por favor, contenha seu pesar."
  },
  AvgDialog_71791_Content_61 = {
    Text = "...Deixarei os preparativos do funeral a cargo de vocês. Eu... me retirarei primeiro."
  },
  AvgDialog_71791_Content_62 = {
    Text = "Tulu acenou para a esposa de Noah. Aquela expressão de tristeza foi rapidamente recolhida, substituída pela compostura digna de um Rei Deus."
  },
  AvgDialog_71791_Content_63 = {
    Text = "Ele se virou mais uma vez para contemplar o rosto sereno de seu amigo, então seguiu o Sacerdote e os Guardas que esperavam na Porta, virando-se para partir com passos firmes."
  },
  AvgDialog_71791_Content_64 = {
    Text = "Ele havia imaginado isso incontáveis vezes antes. Enfim, havia perdido seu último amigo."
  },
  AvgDialog_71791_Content_65 = {Text = "..."},
  AvgDialog_71791_Content_66 = {
    Text = "Todos os Escudeiros haviam sido dispensados, restando Apenas um solitário conjunto de passos a Ecoar pelo vasto e vazio palácio."
  },
  AvgDialog_71791_Content_67 = {
    Text = "Tulu caminhou passo a passo em direção à longa escadaria de pedra, a capa do Rei Deus arrastando-se atrás dele como uma sombra leal."
  },
  AvgDialog_71791_Content_68 = {
    Text = "Seu corpo um tanto esguio estava enterrado sob um conjunto completo de insígnias, e ele se encolheu ao sentar-se no Trono — o enorme Trono de Pedra Azul."
  },
  AvgDialog_71791_Content_69 = {
    Text = "No silêncio, os dedos de Tulu acariciaram suavemente as gemas resplandecentes sobre a Coroa, e ele começou a murmurar como se falasse com você."
  },
  AvgDialog_71791_Content_7 = {
    Text = "Cada vez que Tulu Despertava de um longo Sono Profundo, a primeira coisa que via era Noah correndo animadamente ao seu lado, tagarelando sem parar sobre os acontecimentos recentes."
  },
  AvgDialog_71791_Content_70 = {
    Text = "Você sabia? Desde que eu era criança, sempre senti que você era algum tipo de ser vivo com vontade própria."
  },
  AvgDialog_71791_Content_71 = {
    Text = "(<Gray:?!>)"
  },
  AvgDialog_71791_Content_72 = {
    Text = "Desde o primeiro momento em que pus os olhos em você, eu já sabia o que aconteceria quando o vestisse — especialmente esta cena."
  },
  AvgDialog_71791_Content_73 = {
    Text = "Um trono enorme, um palácio vazio, Sonhos profundos tão viscosos e intermináveis quanto um lago imóvel... e além disso, absolutamente nada."
  },
  AvgDialog_71791_Content_74 = {
    Text = "Seus dedos bateram levemente na borda da Coroa, como se acalmasse um velho amigo."
  },
  AvgDialog_71791_Content_75 = {
    Text = "Naquela época, pensei que era porque meus poderes mentais eram instáveis, e por isso as visões no Sonho eram incompletas. Mas agora eu sei — isso é tudo o que significa ser Rei."
  },
  AvgDialog_71791_Content_76 = {
    Text = "Talvez eu já tivesse algum pressentimento sensível naquela época, ou talvez eu já estivesse farto de viver prevendo coisas e não poder fazer nada."
  },
  AvgDialog_71791_Content_77 = {
    Text = "Um rei tão fraco e impotente não tem razão para existir."
  },
  AvgDialog_71791_Content_78 = {
    Text = "Tulu soltou de repente uma risada desdenhosa e irreverentemente deu um peteleco em uma das gemas da Coroa."
  },
  AvgDialog_71791_Content_79 = {
    Text = "Até hoje, ainda duvido ocasionalmente se aquele desastre naquela época foi apenas um brincadeira d'Ele, apenas para me forçar a colocar a coroa sem hesitação."
  },
  AvgDialog_71791_Content_8 = {
    Text = "Nesses breves momentos de vigília, Tulu escuta as pequenas mudanças na nação e em Noah. Alguns anos são suficientes para um jovem crescer e se tornar adulto."
  },
  AvgDialog_71791_Content_80 = {
    Text = "O dever do Rei Deus... Mesmo antes de vestir a Coroa, eles deram suas vidas sem hesitação para ser seu Guardião — Apenas para agarrar um fio de esperança tênue."
  },
  AvgDialog_71791_Content_81 = {
    Text = "Aquilo era verdadeiramente esperança, ou era uma maldição?"
  },
  AvgDialog_71791_Content_82 = {
    Text = "(<Gray:...>)"
  },
  AvgDialog_71791_Content_83 = {
    Text = "A glória do Rei Deus brilha por dez mil milhas. O Rei guiará Todos e trará paz eterna a Lemuria... Que Sonho vazio."
  },
  AvgDialog_71791_Content_84 = {
    Text = "Sono Profundo sem fim, um trono solitário, uma missão interminável. Esses são os preços que se deve pagar por vestir você, não são?"
  },
  AvgDialog_71791_Content_85 = {
    Text = "Um tentáculo deslizou suavemente pela Coroa, a superfície polida de metal refletindo o rosto sereno de Tulu."
  },
  AvgDialog_71791_Content_86 = {
    Text = "Ele olhou para você, como um Prisioneiro contempla seus grilhões eternos."
  },
  AvgDialog_71791_Content_87 = {
    Text = "Seja esperança ou maldição. Já fiz minha promessa a Noah, já fiz minha promessa a Lemuria."
  },
  AvgDialog_71791_Content_88 = {
    Text = "Já que escolhi usá-lo... o futuro de Limoria será carregado por mim."
  },
  AvgDialog_71791_Content_89 = {
    Text = "Se humanos insignificantes estão destinados a lutar para sempre, apenas para conquistar uma Esperança tão tênue quanto o brilho de um vagalume..."
  },
  AvgDialog_71791_Content_9 = {
    Text = "Não ria de mim quando eu te contar isso, mas recentemente encontrei uma menina de quem eu gosto..."
  },
  AvgDialog_71791_Content_90 = {
    Text = "Então deixe-me ser aquele que luta."
  },
  AvgDialog_71791_Content_91 = {
    Text = "Tulu contemplou longamente o vazio distante, e um leve sorriso surgiu em seu rosto."
  },
  AvgDialog_71791_Content_92 = {
    Text = "Naquela Ilusão semelhante a um Sonho, os rostos de seus companheiros de infância desvaneceram um a um diante de seus olhos. Noah sorriu e acenou para ele uma última vez, antes de finalmente se virar para seguir os passos de seus companheiros."
  },
  AvgDialog_71791_Content_93 = {
    Text = "Tudo o que tenho, eu ofereço a vós, \"Meu Senhor\"."
  },
  AvgDialog_71791_Content_94 = {
    Text = "O que quer que seja desejado, Meu Senhor concederá..."
  },
  AvgDialog_71791_Content_95 = {
    Text = "Eu suportarei toda a maldição desta Coroa, e resistirei ao longo Sono Profundo..."
  },
  AvgDialog_71791_Content_96 = {
    Text = "Apenas desejo que, após mim, Lemúria não precise mais de um rei-deus."
  },
  AvgDialog_71791_Content_97 = {
    Text = "A pesada coroa foi colocada solenemente sobre o pequeno crânio. A partir de agora, no trono, ele e a coroa serão os únicos companheiros silenciosos."
  },
  AvgDialog_71791_Content_98 = {
    Text = "Aqueles olhos indiferentes e sonolentos se fecharam lentamente, e ele mais uma vez mergulhou no mais profundo, mais profundo Sonho do mundo."
  },
  AvgDialog_71791_Content_99 = {
    Text = "Neste longo Sonho, o jovem rei veria claramente a onda gigante imparável se chocando contra esta terra pela qual ele havia feito sua Oferta de tudo."
  },
  AvgDialog_71792_Content_1 = {Text = "Desastre"},
  AvgDialog_71792_Content_10 = {
    Text = "Hoje é o dia em que nasce o príncipe herdeiro de Lemúria, o futuro novo rei. O grande Senhor escolherá o Seu executor designado, trazendo proteção eterna a Lemúria."
  },
  AvgDialog_71792_Content_11 = {
    Text = "Todos os olhares convergem sobre De. De silenciosamente observa tudo do alto."
  },
  AvgDialog_71792_Content_12 = {
    Text = "(<Gray:Espera, eu realmente deveria escolher depois? Mas mesmo que eu quisesse falar, não consigo emitir som algum...>)"
  },
  AvgDialog_71792_Content_13 = {
    Text = "Reunimos as almas mais puras de Lemuria. Elas praticam dia e noite, Apenas para ouvir o oráculo divino de nosso Senhor."
  },
  AvgDialog_71792_Content_14 = {
    Text = "Todas as crianças endireitaram as costas, aceitando o escrutínio da multidão da nação."
  },
  AvgDialog_71792_Content_15 = {
    Text = "De mais uma vez viu as emoções coloridas, surgindo e mudando dentro de cada pequena cabeça."
  },
  AvgDialog_71792_Content_16 = {
    Text = "Agora, demos graças pela graça de nosso Senhor, pela misericórdia de nosso Senhor. Crença de nosso Senhor, abram seus corações e recebam a vontade de nosso Senhor."
  },
  AvgDialog_71792_Content_17 = {
    Text = "Que nossas canções atravessem o mar profundo. Que nosso Senhor nos conceda o oráculo para sermos poupados da calamidade e nos guie a um reino de paz e euforia sem fim."
  },
  AvgDialog_71792_Content_18 = {
    Text = "Nossa fé permanece com nosso Senhor, até que as estrelas pereçam, até o fim dos tempos..."
  },
  AvgDialog_71792_Content_19 = {
    Text = "Ouçam nosso Senhor. Devotem-se a nosso Senhor..."
  },
  AvgDialog_71792_Content_2 = {Text = "Splash—"},
  AvgDialog_71792_Content_20 = {
    Text = "As vozes de Todos soaram em uníssono. Em meio às incontáveis preces, até a Terra tremeu."
  },
  AvgDialog_71792_Content_21 = {
    Text = "O Velho sumo sacerdote caminhou ao longo das tochas dispostas em círculo, desenhando inscrições e padrões complexos com o cetro. À medida que cada inscrição se iluminava, De sentiu esta concha metálica Despertar pouco a pouco."
  },
  AvgDialog_71792_Content_22 = {
    Text = "Sua alma parecia ser aquecida e expandida, gradualmente flutuando para cima, sua linha de visão elevando-se à altura de um gigante, Como se o Domínio deste planeta contemplasse a Terra e o oceano."
  },
  AvgDialog_71792_Content_23 = {
    Text = "<Gray:Então isto é... a perspectiva de um deus...>"
  },
  AvgDialog_71792_Content_24 = {
    Text = "Todos no chão não passavam de formigas do tamanho de gergelim. As ondas sonoras trovejantes de momentos atrás eram apenas um ruído fraco. Tudo era tão monótono."
  },
  AvgDialog_71792_Content_25 = {Text = "..."},
  AvgDialog_71792_Content_26 = {
    Text = "(<Gray:Hã, o que é aquilo?>)"
  },
  AvgDialog_71792_Content_27 = {
    Text = "Sua atenção foi subitamente atraída por algo que se aproximava gradualmente. De virou-se para contemplar a superfície cinza-azulada do mar."
  },
  AvgDialog_71792_Content_28 = {
    Text = "Ao mesmo tempo, Tulu, cujas pálpebras estavam caídas, subitamente ergueu a cabeça e olhou em direção ao mar ao lado de De."
  },
  AvgDialog_71792_Content_29 = {
    Text = "Um raio caiu. Nuvens escuras, vento feroz e chuva torrencial pareciam ter sido subitamente Invocação, e o céu mudou abruptamente."
  },
  AvgDialog_71792_Content_3 = {
    Text = "Estavas de pé sobre o imponente altar na beira da costa."
  },
  AvgDialog_71792_Content_30 = {
    Text = "As tochas sobre o altar foram extintas pela chuva repentina. A solene Oração de dezenas de milhares vacilou como se fosse um Sonho Assustador, e sussurros de Caos começaram a espalhar-se pela multidão."
  },
  AvgDialog_71792_Content_31 = {
    Text = "Silêncio! O ritual prossegue normalmente. Continuem a Oração!"
  },
  AvgDialog_71792_Content_32 = {
    Text = "As vestes cerimoniais do Velho sumo sacerdote ondulavam e estalavam ao vento feroz. A sua expressão permanecia inabalável, mas mesmo aqueles olhos enrugados não conseguiam esconder um lampejo de preocupação."
  },
  AvgDialog_71792_Content_33 = {
    Text = "Antes que o Velho sumo sacerdote pudesse restaurar a ordem, a Oração em Desordem rapidamente desmoronou por completo, e gritos aterrorizados irromperam da multidão."
  },
  AvgDialog_71792_Content_34 = {
    Text = "Uma sombra vasta como uma cordilheira ergueu-se da borda do horizonte, crescendo cada vez mais a uma velocidade visível a olho nu, Como se fosse bloquear os últimos resquícios de luz do dia por completo."
  },
  AvgDialog_71792_Content_35 = {
    Text = "Um monstro... um monstro está a vir!!"
  },
  AvgDialog_71792_Content_36 = {
    Text = "Um uivo zumbante Como se viesse de tempos ancestrais esmagou as almas Frágeis da humanidade, enquanto ondas como cortinas se erguiam para Devorar a terra."
  },
  AvgDialog_71792_Content_37 = {
    Text = "Era uma existência além de toda resistência. Se tal monstro tivesse um nome, Apenas poderia ser — Calamidade."
  },
  AvgDialog_71792_Content_38 = {
    Text = "quase no espaço de uma única respiração, a maré crescente arrancou vastas extensões de costa, e os diques da humanidade desmoronaram como papel."
  },
  AvgDialog_71792_Content_39 = {
    Text = "Pronto para evacuar — para os terrenos elevados!"
  },
  AvgDialog_71792_Content_4 = {
    Text = "A espuma agitada pelas ondas estilhaçava-se incessantemente contra os recifes irregulares. Nuvens espessas e ininterruptas fundiam-se com as marés cinzentas no horizonte, envolvendo as fronteiras desta nação."
  },
  AvgDialog_71792_Content_40 = {
    Text = "Aquele rugido envelhecido mas autoritário soou mais uma vez. O Velho sumo sacerdote e os guardas rapidamente começaram a pôr a multidão atordoada em movimento."
  },
  AvgDialog_71792_Content_41 = {
    Text = "A multidão em pânico corria desamparadamente como ovelhas, mas no Caos esmagavam-se uns contra os outros, pisoteando-se mutuamente rumo a uma morte ainda mais rápida."
  },
  AvgDialog_71792_Content_42 = {
    Text = "Dividam-se em vários Caminhos de evacuação por Fissão e enviem pessoas à frente para guiar a multidão!"
  },
  AvgDialog_71792_Content_43 = {
    Text = "O Velho sumo sacerdote quase gritava cada comando aos guardas, tentando desesperadamente controlar esta carruagem enlouquecida que se precipitava rumo ao abismo."
  },
  AvgDialog_71792_Content_44 = {
    Text = "O altar ficava em terreno mais elevado, por isso não corrias perigo imediato de ser submerso — mas perante uma existência de tal enormidade, a Sintoma: Destruição Apenas chegaria ligeiramente Depois."
  },
  AvgDialog_71792_Content_45 = {
    Text = "Não importava o quão longe a multidão fugisse, onde poderia haver um refúgio de segurança absoluta?"
  },
  AvgDialog_71792_Content_46 = {
    Text = "Ouçam nosso Senhor. Devotem-se a nosso Senhor..."
  },
  AvgDialog_71792_Content_47 = {
    Text = "As crianças tinham começado a sua devota Oração no momento em que o desastre se abateu pela primeira vez."
  },
  AvgDialog_71792_Content_48 = {
    Text = "Cada uma delas franzia o cenho, estendendo desesperadamente os pequenos filamentos do seu poder espiritual em direção à Coroa — como inúmeras mãos estendidas em desespero, ansiando pela misericórdia e salvação do divino."
  },
  AvgDialog_71792_Content_49 = {
    Text = "E no entanto era verdadeiramente..."
  },
  AvgDialog_71792_Content_5 = {
    Text = "Mais alto ainda do que o embater das ondas, um rugido de vozes erguia-se atrás de ti—um mar infinito de pessoas formado por incontáveis multidões."
  },
  AvgDialog_71792_Content_50 = {
    Text = "(<Gray:...Fraco demais.>)"
  },
  AvgDialog_71792_Content_51 = {
    Text = "Aos seus olhos, aquelas almas frágeis deram tudo o que tinham, mas só conseguiam emitir um brilho tênue, mal visível, como vagalumes. Não importava o quão desesperadamente você tentasse responder, aquela casca da Coroa permanecia completamente imóvel."
  },
  AvgDialog_71792_Content_52 = {
    Text = "Como pode ser... Nosso Senhor nos abandonou? Por que a Coroa não respondeu..."
  },
  AvgDialog_71792_Content_53 = {
    Text = "Não pode ser! Não devemos ser devotos o suficiente. Nossa energia psíquica não deve estar estável o suficiente. Tentem com mais força!"
  },
  AvgDialog_71792_Content_54 = {
    Text = "Não há mais tempo."
  },
  AvgDialog_71792_Content_55 = {
    Text = "Todos olharam para a criança que havia tomado a decisão. O garoto que sempre fora o mais racional entre eles olhou silenciosamente para seus companheiros e então deu o primeiro passo nas escadas."
  },
  AvgDialog_71792_Content_56 = {
    Text = "Não temos mais tempo para Esperar. Talvez nosso Senhor ainda esteja em Sono Profundo. Talvez Ele não esteja olhando para cá neste momento. Ou talvez nossas vozes sejam simplesmente pequenas demais."
  },
  AvgDialog_71792_Content_57 = {
    Text = "Devemos ir até Ele nós mesmos."
  },
  AvgDialog_71792_Content_58 = {
    Text = [[
A coroa no alto pedestal brilha com uma luz fria, como um olho indiferente.
Os deuses nunca prometeram, os deuses nunca negaram.
.]]
  },
  AvgDialog_71792_Content_59 = {
    Text = "Enquanto o garoto seguia em frente, mais e mais crianças silenciosamente seguiam seus passos. Os passos leves como plumas do grupo de crianças sobre os degraus de pedra foram completamente abafados pelos lamentos da multidão e pelo rugido das ondas."
  },
  AvgDialog_71792_Content_6 = {
    Text = "O teu olhar seguiu uma sensação familiar, percorrendo a área até encontrares rapidamente Tulu de pé entre um grupo de crianças abaixo do altar."
  },
  AvgDialog_71792_Content_60 = {
    Text = "Na retaguarda das crianças, a expressão de Tulu de repente ficou vazia. A sombra da Coroa se refletia em seus olhos, suas pupilas dilatando-se vacuamente."
  },
  AvgDialog_71792_Content_61 = {
    Text = "Logo aquele reflexo dourado se transformou em um redemoinho de Caos, e Tulu rigidamente afundou em algum tipo de Pesadelo, tornando-se um observador distante."
  },
  AvgDialog_71792_Content_62 = {
    Text = "Tulu, Tulu! O que houve... Você está se sentindo mal?"
  },
  AvgDialog_71792_Content_63 = {
    Text = "A preocupação de seu amigo não conseguiu Despertar sua alma. Ele permaneceu congelado no lugar, como uma estátua de pedra desgastada pelo tempo."
  },
  AvgDialog_71792_Content_64 = {
    Text = "O garoto que foi o primeiro a subir a plataforma elevada já estava ao seu lado. Ele se virou e olhou para os rostos solenes de seus companheiros, um por um, e então fez um aceno grave."
  },
  AvgDialog_71792_Content_65 = {
    Text = "Quando as mãos do garoto se estenderam Firmemente em direção à Coroa, os olhos de Tulu se moveram quase imperceptivelmente."
  },
  AvgDialog_71792_Content_66 = {Text = "..."},
  AvgDialog_71792_Content_67 = {
    Text = "Como se lutasse incessantemente dentro de um Pesadelo, seus lábios tremeram e se moveram levemente, espremendo um murmúrio quase inaudível de sua garganta."
  },
  AvgDialog_71792_Content_68 = {
    Text = "<Small:Não...>"
  },
  AvgDialog_71792_Content_69 = {
    Text = "O quê? Você disse algo?"
  },
  AvgDialog_71792_Content_7 = {
    Text = "(<Gray:Isto é... a Cerimónia de Seleção do Herdeiro de que falavam?>)"
  },
  AvgDialog_71792_Content_70 = {
    Text = "O garoto no topo da plataforma elevada, com a máxima reverência, colocou gentilmente a Coroa sobre sua própria cabeça."
  },
  AvgDialog_71792_Content_71 = {
    Text = "<Big:NÃO!!!>"
  },
  AvgDialog_71792_Content_72 = {
    Text = "Ele finalmente encontrou sua voz novamente, mas já era tarde demais."
  },
  AvgDialog_71792_Content_73 = {
    Text = "No momento em que a Coroa se assentou firmemente sobre o palanquim novinho, uma expressão de quase perplexidade cruzou o rosto jovem, porém solene, do menino."
  },
  AvgDialog_71792_Content_74 = {
    Text = "Todas as crianças prenderam a respiração, aguardando o oráculo divino de salvação que ele traria."
  },
  AvgDialog_71792_Content_75 = {
    Text = "Mas no instante seguinte, o que irrompeu dos lábios ligeiramente entreabertos do menino foram Apenas vários enormes tentáculos verde-escuros, contorcendo-se. Sangue escaldante e carne explodiram como fogos de artifício detonando com um estrondo, espirrando nos rostos de todos."
  },
  AvgDialog_71792_Content_76 = {Text = "Clang—"},
  AvgDialog_71792_Content_77 = {
    Text = "A Coroa tombou do corpo violentamente despedaçado, rolando até parar aos pés das crianças."
  },
  AvgDialog_71792_Content_78 = {
    Text = "<Red:Como uma maldição ominosa.>"
  },
  AvgDialog_71792_Content_8 = {
    Text = "O Velho sumo sacerdote, vestido em trajes magníficos e segurando um cetro, caminhou lentamente até o centro do altar."
  },
  AvgDialog_71792_Content_9 = {
    Text = "Incontáveis rostos ruborizados de excitação abaixo do palco gradualmente silenciaram, deixando Apenas pares de olhos com um parpadeio de luz brilhante."
  },
  AvgDialog_71793_Content_1 = {
    Text = "Cerimônia de Coroação"
  },
  AvgDialog_71793_Content_10 = {
    Text = "Medo, um medo mortal permeava o ar Ao redor da Coroa."
  },
  AvgDialog_71793_Content_100 = {
    Text = "Quase esqueci— você é o futuro rei agora..."
  },
  AvgDialog_71793_Content_101 = {
    Text = "A mão de Tulu pressionou repentinamente o ombro de Noah. A expressão complexa em seu rosto, que demonstrara pouca alegria, finalmente suavizou, dando lugar a um leve sorriso."
  },
  AvgDialog_71793_Content_102 = {
    Text = "Um rei não pode ter amigos?"
  },
  AvgDialog_71793_Content_103 = {
    Text = "Noah ficou olhando fixamente para aquele sorriso, então caiu na gargalhada ele mesmo, erguendo a manga para limpar desajeitadamente as lágrimas do rosto."
  },
  AvgDialog_71793_Content_104 = {
    Text = "Você tem razão— um rei assim seria lamentável demais. Eu não vou deixar você ser tão lamentável."
  },
  AvgDialog_71793_Content_105 = {
    Text = "Apenas como em tantos dias anteriores, os braços longos de Noah envolveram os ombros de Tulu enquanto batia no próprio peito com ousada ambição."
  },
  AvgDialog_71793_Content_106 = {
    Text = "Eu vou ser amigo do Rei para sempre, e até lá vai ter pastéis de Amaranto infinitos para comer!"
  },
  AvgDialog_71793_Content_107 = {
    Text = "Isso é tudo que você consegue desejar no final? Que falta de esperança..."
  },
  AvgDialog_71793_Content_108 = {
    Text = "Tulu revirou os olhos com desdém mais uma vez. As crianças sobreviventes se aglomeraram ao redor dos dois, uma após a outra se abraçando apertado como filhotes que sobreviveram juntos."
  },
  AvgDialog_71793_Content_109 = {
    Text = "Você e Tulu contemplaram rosto após rosto — chorando, animados, alegres — e até o Velho sumo sacerdote revelou um sorriso de emoção e alívio. A Chegada do Milagre, o desastre recuando, o herdeiro do trono nascido — o final parecia tão perfeito."
  },
  AvgDialog_71793_Content_11 = {
    Text = "Os tentáculos dançando loucamente, tendo perdido seu hospedeiro, gradualmente se dissolveram em uma poça de gelatina verde, lavada pela chuva cada vez mais intensa enquanto se espalhava pelo altar."
  },
  AvgDialog_71793_Content_110 = {
    Text = "No entanto, no momento em que a aparição divina desceu, você já havia ouvido aquele oráculo predestinado."
  },
  AvgDialog_71793_Content_111 = {
    Text = "Meu representante, tu te sentarás eternamente no trono de pedra azul, ligado ao destino desta nação."
  },
  AvgDialog_71793_Content_112 = {
    Text = "Força e glória serão inesgotáveis, e todos os povos se curvarão diante do seu trono."
  },
  AvgDialog_71793_Content_113 = {
    Text = "A voz interior de Tulu alcançou sua mente através da Coroa neste momento, sobrepondo-se aos seus próprios pensamentos."
  },
  AvgDialog_71793_Content_114 = {
    Text = "(<Gray:Então, qual é o preço?>)"
  },
  AvgDialog_71793_Content_12 = {Text = "Clique."},
  AvgDialog_71793_Content_13 = {
    Text = "Um pequeno sapato deu um passo à frente, cruzando por cima daqueles fragmentos ainda quentes, e uma mão recuperou a Coroa da lama imunda."
  },
  AvgDialog_71793_Content_14 = {Text = "Xinjia..."},
  AvgDialog_71793_Content_15 = {
    Text = "A menina cujo nome foi Chamado pausou por um instante, então se virou e deu aos seus companheiros um sorriso trêmulo."
  },
  AvgDialog_71793_Content_16 = {
    Text = "Os dias que passei com todos vocês, eu sempre fui tão feliz. Sorria, Amos— você fica melhor quando sorri."
  },
  AvgDialog_71793_Content_17 = {Text = "Clang—"},
  AvgDialog_71793_Content_18 = {
    Text = "O Destino não concedia facilmente seu favor, mas desta vez, a Coroa foi rapidamente apanhada pelo próximo par de mãos."
  },
  AvgDialog_71793_Content_19 = {
    Text = "Sombras ao longe, nuvens escuras, tsunamis ainda rugindo—uma escuridão sem fim cobria todo o reino."
  },
  AvgDialog_71793_Content_2 = {
    Text = "Tornar-se o substituto do Senhor é, acima de tudo, um destino já traçado."
  },
  AvgDialog_71793_Content_20 = {
    Text = "Entre os céus sombrios e a terra, Apenas sobre este pequeno altar as cores vívidas continuavam a irromper."
  },
  AvgDialog_71793_Content_21 = {
    Text = "Almas vivas caíam uma após outra, Apenas para serem sucedidas por aquelas que vinham Depois. Diante dos seus olhos restavam Apenas o vermelho e o verde Pegajosos."
  },
  AvgDialog_71793_Content_22 = {
    Text = "(<Shake:Não, isso não está certo—você não aguenta isso, pare!>)"
  },
  AvgDialog_71793_Content_23 = {
    Text = "Seus gritos eram como os de um fantasma selado do mundo mortal—não ouvidos por ninguém."
  },
  AvgDialog_71793_Content_24 = {
    Text = "As pequenas crianças se lançavam adiante uma após outra. Neste momento, cada um dos não escolhidos carregava a responsabilidade sob a Coroa."
  },
  AvgDialog_71793_Content_25 = {
    Text = "Eles eram os Novos reis indecisos, e assim guardariam esta nação até o momento em que o Destino soasse seu acorde final."
  },
  AvgDialog_71793_Content_26 = {
    Text = "Samuel, Gretchen, Amos..."
  },
  AvgDialog_71793_Content_27 = {
    Text = "Noah, deixado para trás nos degraus abaixo com Tulu, olhava arregalado—descrença, agonia, medo... Em meio a incontáveis cores abissais, um ponto de luz gradualmente se expandiu e lentamente consumiu sua mente."
  },
  AvgDialog_71793_Content_28 = {
    Text = "Noah olhou para trás, para Tulu, que ainda estava atordoado, tocou gentilmente seu ombro, então se virou e caminhou em direção aos seus companheiros."
  },
  AvgDialog_71793_Content_29 = {Text = "..."},
  AvgDialog_71793_Content_3 = {
    Text = "Aqueles não destinados a usar a Coroa, se forçarem a si mesmos a receber o oráculo divino, Apenas encontrarão a morte, incapazes de suportar a Força dos deuses."
  },
  AvgDialog_71793_Content_30 = {
    Text = "O que chamam de Talento às vezes parece mais uma maldição que não se pode escolher."
  },
  AvgDialog_71793_Content_31 = {
    Text = "Sonhos Recriados na realidade repetidas vezes, Profecias que não podiam ser detidas ou alteradas, Ilusões indescritíveis, sussurros distorcidos e carregados de Loucura..."
  },
  AvgDialog_71793_Content_32 = {
    Text = "Ele havia suportado tudo isso desde o nascimento. O chamado dom do divino nunca sequer pediu seu consentimento."
  },
  AvgDialog_71793_Content_33 = {
    Text = "A Força Despertada pelo ritual surgia e agitava-se com Agitação dentro do seu corpo. A missão predestinada subitamente Despertou, e o sopro do divino começou a emanar."
  },
  AvgDialog_71793_Content_34 = {
    Text = "Mortais fracos em Discernimento eram como gado insensível. Apenas aquela alma brilhando como uma estrela incessantemente o atraía, como se algo chamado Destino os conectasse com força tangível."
  },
  AvgDialog_71793_Content_35 = {
    Text = "<Gray:Responda-me, o predestinado Deus-Rei...>"
  },
  AvgDialog_71793_Content_36 = {
    Text = "Em um instante, Tulu foi mais uma vez lançado sem escolha em um Sonho de Loucura, entrando em uma Dimensão em Frequência idêntica com a sua."
  },
  AvgDialog_71793_Content_37 = {
    Text = "Ele vê uma cidade magnífica destruída como frágeis blocos de construção, as águas da enchente se espalhando, e todos os seres vivos com olhos que não conseguem se fechar sendo engolidos pelo vórtice do mar profundo."
  },
  AvgDialog_71793_Content_38 = {Text = "Não..."},
  AvgDialog_71793_Content_39 = {
    Text = "Ele viu aquelas crianças com quem havia convivido dia e noite, uma a uma se transformando em Monstros e fluido pútrido, suas almas dilaceradas pelas emanações errantes de um Sonho divino."
  },
  AvgDialog_71793_Content_4 = {
    Text = "Portanto, a última coisa que vocês devem fazer é Apenas aguardar em silêncio a escolha do deus. Não há necessidade de tristeza, não há necessidade de forçar."
  },
  AvgDialog_71793_Content_40 = {
    Text = "Noah, que estivera brincando com ele ainda ontem, chorava torrentes de lágrimas de Sangue de ambos os olhos, gritando roucamente seu nome antes de se despedaçar."
  },
  AvgDialog_71793_Content_41 = {Text = "Não!!!"},
  AvgDialog_71793_Content_42 = {
    Text = "Por que ir ao encontro da morte... Por que lutar em vão..."
  },
  AvgDialog_71793_Content_43 = {
    Text = "Aquela Coroa que ele nunca estivera disposto a encarar diretamente ainda contemplava tudo lá de cima com fria indiferença, como se zombasse de sua eterna evasão."
  },
  AvgDialog_71793_Content_44 = {
    Text = "O rosto de Tulu foi subitamente tomado por uma raiva desenfreada, encarando você como uma fera encurralada num beco sem saída."
  },
  AvgDialog_71793_Content_45 = {
    Text = "Sempre, é sempre assim... Qual é o sentido de me mostrar esses futuros ilusórios?"
  },
  AvgDialog_71793_Content_46 = {
    Text = "Te faz feliz me ver incapaz de salvar alguém, incapaz de mudar qualquer coisa?!"
  },
  AvgDialog_71793_Content_47 = {
    Text = "Escolha... Ele te espera na Espera..."
  },
  AvgDialog_71793_Content_48 = {
    Text = "De repente, Tulu sentiu alguém tocá-lo. Estendeu a mão, atordoado. Algo como a borda leve de uma vestimenta pareceu deslizar por seus dedos. Seus dedos se curvaram levemente, mas não agarraram nada."
  },
  AvgDialog_71793_Content_49 = {
    Text = "Ah, qual é, como você vai saber se não tentar? Você vai se arrepender Depois se não aproveitar a chance quando ela aparece."
  },
  AvgDialog_71793_Content_5 = {Text = "..."},
  AvgDialog_71793_Content_50 = {
    Text = "Não é assim que deves pensar—e se pudesses? Geração após geração de mortais continuam a lutar, e eventualmente há coisas que podem ser mudadas. Caso contrário, por que razão escolhemos um Deus-Rei?"
  },
  AvgDialog_71793_Content_51 = {
    Text = "Uma luta, como se Despertasse de um sobressalto, surgiu subitamente no rosto de Tulu, carregada de uma determinação intensa e pesada."
  },
  AvgDialog_71793_Content_52 = {
    Text = "Todos eles, cada um deles, agindo como heróis..."
  },
  AvgDialog_71793_Content_53 = {
    Text = "Através das Ilusões de seus companheiros lutando desesperadamente para alcançar a Coroa, ele ergueu a cabeça e encarou diretamente o diadema eternamente parpadeante no alto."
  },
  AvgDialog_71793_Content_54 = {
    Text = "Me diga, como tudo isso pode ser parado?!"
  },
  AvgDialog_71793_Content_55 = {
    Text = "Vista @2..."
  },
  AvgDialog_71793_Content_56 = {
    Text = "quase rugindo, Tulu deu um passo à frente e então começou a Correr desesperadamente."
  },
  AvgDialog_71793_Content_57 = {
    Text = "Me diga, o que exatamente será preciso para satisfazê-Lo?!"
  },
  AvgDialog_71793_Content_58 = {
    Text = "Despertar @3..."
  },
  AvgDialog_71793_Content_59 = {
    Text = "Uma passo, dois passos — ele atravessou o Sonho repleto de morte, cambaleando enquanto subia correndo as escadas de pedra."
  },
  AvgDialog_71793_Content_6 = {
    Text = "Cada criança, ao aceitar esta missão carregada com a esperança da nação e partir no Caminho para se tornar rei, já conhecia o possível destino de morte que a aguardava."
  },
  AvgDialog_71793_Content_60 = {
    Text = "O último degrau foi pisoteado, e uma explosão avassaladora de força psíquica rasgou o Sonho concedido divinamente. A realidade finalmente Retornou aos seus olhos."
  },
  AvgDialog_71793_Content_61 = {
    Text = "Em meio aos destroços heroicos espalhados pelo chão, aquela Coroa estava sendo erguida do chão por Noah, parpadeando com uma luz fria em sua direção."
  },
  AvgDialog_71793_Content_62 = {
    Text = "Os olhos de Noah ficaram turvos num instante. Duas trilhas de lágrimas de Sangue escorreram por seu rosto, e tudo começou a se sobrepor às cenas do Sonho."
  },
  AvgDialog_71793_Content_63 = {
    Text = "No instante seguinte, uma mão agarrou Firmemente a Coroa coberta de Espinhos e, Resiliência, pouco a pouco, arrancou-a das mãos de Noah."
  },
  AvgDialog_71793_Content_64 = {Text = "Tu... lu?"},
  AvgDialog_71793_Content_65 = {
    Text = "Sinto muito, estou atrasado."
  },
  AvgDialog_71793_Content_66 = {
    Text = "Tulu arfava, a palma da mão cortada pela Coroa. Gotas Carmesim de Sangue caíram sobre a gema no centro da Coroa, como um olho em lágrimas."
  },
  AvgDialog_71793_Content_67 = {
    Text = "Neste momento, o tsunami já havia inundado as terras costeiras, restando apenas o alto altar, como uma ilha solitária flutuando na superfície do mar.\nNas ondas próximas e iminentes, o monstro da destruição já havia chegado."
  },
  AvgDialog_71793_Content_68 = {
    Text = "Ouçam nosso Senhor. Devotem-se a nosso Senhor..."
  },
  AvgDialog_71793_Content_69 = {
    Text = "O jovem rei, para sempre imperturbável nas suas memórias, agora ergueu a Coroa pela primeira vez. Diante das ondas colossais, levantou a cabeça e coroou-se com as próprias mãos."
  },
  AvgDialog_71793_Content_7 = {
    Text = "Quando seguiram o primeiro pioneiro escadaria acima até a Coroa, já haviam feito sua escolha."
  },
  AvgDialog_71793_Content_70 = {
    Text = "Deixe-me fazer... Tulu?!"
  },
  AvgDialog_71793_Content_71 = {
    Text = "Noah desabou fraco no chão. Fitou, atónito, a Coroa firmemente assentada sobre a cabeça de Tulu, a mão estendida para deter Tulu congelada no ar."
  },
  AvgDialog_71793_Content_72 = {
    Text = "Tulu virou-se para olhar o amigo que, mesmo agora, ainda queria assumir o perigo em seu lugar, e ofereceu um sorriso reconfortante."
  },
  AvgDialog_71793_Content_73 = {
    Text = "...Que Vossos olhos sábios percebam a calamidade, que Vossa sabedoria guie Vosso povo."
  },
  AvgDialog_71793_Content_74 = {
    Text = "Em meio ao rugido da grande besta, ele enfrentou o vendaval e o aguaceiro, e estendeu a mão."
  },
  AvgDialog_71793_Content_75 = {
    Text = "A tempestade se aquieta, as águas repousam em calma..."
  },
  AvgDialog_71793_Content_76 = {
    Text = "Seus cabelos e as barras de suas vestes eram açoitados em Frenesi, a Coroa umedecida por seu Sangue, irradiando uma luminosidade cada vez mais intensa do topo de sua cabeça."
  },
  AvgDialog_71793_Content_77 = {
    Text = "Como se os deuses finalmente tivessem respondido, uma vasta e nebulosa silhueta que obscurecia o céu se materializou atrás dele."
  },
  AvgDialog_71793_Content_78 = {
    Text = "Os terremotos cessaram, e a Terra estava em Tranquilidade."
  },
  AvgDialog_71793_Content_79 = {
    Text = "A enorme cabeça do monstro mergulhou para baixo, investindo contra o diminuto humano a seus pés, Apenas para ser violentamente repelida no instante seguinte, Como se queimada por aquela luminosidade, soltando um lamento estridente."
  },
  AvgDialog_71793_Content_8 = {
    Text = "No entanto, no momento em que testemunharam com seus próprios olhos um companheiro com quem haviam convivido dia e noite se dissolver em polpa diante deles, todas as crianças congelaram no lugar."
  },
  AvgDialog_71793_Content_80 = {
    Text = "Uma estrela extraordinariamente brilhante cruzou o céu com um fulgor deslumbrante. Num instante, as nuvens escuras se abriram, as ondas recuaram, e o vento e a chuva cessaram."
  },
  AvgDialog_71793_Content_81 = {
    Text = "A calamidade se dissolve no vazio dentro do Seu sonho plácido, e Seu povo, sob Sua proteção..."
  },
  AvgDialog_71793_Content_82 = {
    Text = "Uma majestade sem limites irrompeu daquele pequeno corpo. Aquelas pupilas âmbar transbordavam uma aura de antiguidade atemporal, e um traço de indiferença que olhava de cima para todas as coisas."
  },
  AvgDialog_71793_Content_83 = {
    Text = "Tentáculos verde-escuros contorcidos, um Ponto de encontro da Força avassaladora do abismo, rastejavam para fora dos flancos de Tulu, expandindo-se Como se possuíssem vontade própria, Como se para formar um magnífico trono de lápis-lazúli sob o soberano."
  },
  AvgDialog_71793_Content_84 = {
    Text = "A aterrorizante besta soltou um gemido relutante, como se compelida por uma ordem irresistível, e naquele confronto, recuou um passo."
  },
  AvgDialog_71793_Content_85 = {
    Text = "Aquela espinha dorsal semelhante a uma montanha afunda-se gradualmente sob a água e, finalmente, com a maré vazante, retorna ao mar profundo."
  },
  AvgDialog_71793_Content_86 = {
    Text = "Sano e salvo."
  },
  AvgDialog_71793_Content_87 = {
    Text = "A luz do sol atravessou as nuvens, banhando mais uma vez a Terra de Lemuria."
  },
  AvgDialog_71793_Content_88 = {
    Text = "A multidão, perseguida e Devorada pelas ondas, gradualmente parou. Edifícios e terras submersas reemergiram, e em cada rosto apavorado e atônito floresceu a alegria selvagem de ter sobrevivido à catástrofe."
  },
  AvgDialog_71793_Content_89 = {
    Text = "É o Senhor! O Senhor veio nos salvar!"
  },
  AvgDialog_71793_Content_9 = {Text = "Aah—"},
  AvgDialog_71793_Content_90 = {
    Text = "Foram os herdeiros— os herdeiros Despertaram nosso Senhor!"
  },
  AvgDialog_71793_Content_91 = {
    Text = "O Velho sumo sacerdote, que permanecera em silêncio em aprovação tácita desde que as crianças caminharam em direção à Coroa, agora curvou-se profundamente diante de Tulu no ponto mais alto do altar— o ritual de um padre se submetendo a um rei."
  },
  AvgDialog_71793_Content_92 = {
    Text = "Então ele se virou e, tremendo, ergueu seu cetro, proclamando com a voz mais solene."
  },
  AvgDialog_71793_Content_93 = {
    Text = "Nosso Senhor salvou Lemuria. Ele fez Sua escolha final. Prestemos nossas homenagens ao novo herdeiro— Sua Alteza Tulu!"
  },
  AvgDialog_71793_Content_94 = {
    Text = "Louvores trovejantes irromperam em explosão da multidão. As pessoas se curvaram diante do futuro Novo rei, e aqueles de Devoção mais profunda até se ajoelharam no chão, beijando a Terra e chorando lágrimas de alegria."
  },
  AvgDialog_71793_Content_95 = {
    Text = "Noah, que estava parado atônito ao lado, finalmente voltou a si, correu para frente e abraçou Tulu com força, quase derrubando-o no chão."
  },
  AvgDialog_71793_Content_96 = {
    Text = "Você conseguiu! Eu sabia que você poderia fazer isso!!"
  },
  AvgDialog_71793_Content_97 = {
    Text = "Noah estava tão emocionado que lágrimas escorriam pelo seu rosto. Aqueles dois rastros de lágrimas de Sangue foram lavados por suas lágrimas, borrando-se numa bagunça suja por todo o Tulu."
  },
  AvgDialog_71793_Content_98 = {
    Text = "Seu rosto..."
  },
  AvgDialog_71793_Content_99 = {
    Text = "Apenas então Noah pareceu perceber o que estava fazendo e soltou-o, recuando desajeitadamente com um olhar envergonhado. Suas costas se curvaram ligeiramente, como se hesitasse sobre se deveria se curvar."
  },
  AvgDialog_71794_Content_1 = {Text = "Infância"},
  AvgDialog_71794_Content_10 = {
    Text = "Você luta para abrir os olhos. O que surge repentinamente em seu Campo de visão são duas fileiras de colunas erguidas como dentes de bestas colossais, um teto abobadado coberto de finas esculturas em pedra e longos degraus de pedra se estendendo para baixo — este é um templo grandioso e solene."
  },
  AvgDialog_71794_Content_100 = {
    Text = "Você claramente é o mais lento para escrever, e ainda assim tem que bancar o herói. E depois se deixa comprar com só isso — que patético."
  },
  AvgDialog_71794_Content_101 = {
    Text = "É coisa de amigo, como você pode chamar isso de ser comprado? É, é... Eu sou alguns anos mais velho que você, então Apenas sendo o irmão mais velho, cuidar de você é Apenas natural. Ai—"
  },
  AvgDialog_71794_Content_102 = {
    Text = "Noah estufou o peito heroicamente, mas acidentalmente torceu o pescoço já dolorido, gritando e fazendo careta de dor."
  },
  AvgDialog_71794_Content_103 = {Text = "..."},
  AvgDialog_71794_Content_104 = {
    Text = "Em meio aos sons gradualmente entorpecentes da cópia, você observou a cabeça de Tulu começar a balançar e pender, seus olhos se fechando lentamente, a tinta na ponta de sua caneta pingando sobre o papel, espalhando-se em uma grande mancha."
  },
  AvgDialog_71794_Content_105 = {
    Text = "Tulu, acorda! Apenas aguente mais um pouquinho!"
  },
  AvgDialog_71794_Content_106 = {Text = "Ugh..."},
  AvgDialog_71794_Content_107 = {
    Text = "Vamos conversar um pouco — falar vai espantar o sono. Ei... a Cerimônia de Seleção do Herdeiro está chegando. Quem você acha que vai vestir a Coroa no final?"
  },
  AvgDialog_71794_Content_108 = {
    Text = "Os olhos de Tulu mal se abriram uma fresta antes de ele simplesmente jogar a caneta de lado e se dedicar de corpo e alma a cochilar."
  },
  AvgDialog_71794_Content_109 = {
    Text = "Com o entusiasmo que você tem para copiar versos de oração tantas vezes, certamente até a mais fria das divindades seria tocada por você."
  },
  AvgDialog_71794_Content_11 = {
    Text = "A bizarra perspectiva de quase 360 graus lança seus sentidos em uma Tontura momentânea, mas comparado a outras circunstâncias, isso claramente não é a questão mais urgente."
  },
  AvgDialog_71794_Content_110 = {
    Text = "Ah, qual é, você está zombando de mim de novo. Meu nível de poder espiritual nem consegue ficar entre os três primeiros entre todos, suspiro..."
  },
  AvgDialog_71794_Content_111 = {
    Text = "O rosto de Noah estava cheio de melancolia. Como se igualmente desgastado pelo tédio, ele começou a tagarelar sem parar."
  },
  AvgDialog_71794_Content_112 = {
    Text = "Amos sempre teve uma forte afinidade com a Coroa, e o poder espiritual de Samuel é quase o melhor entre todos nós..."
  },
  AvgDialog_71794_Content_113 = {
    Text = "Ah, espera, não—mesmo que durmas o dia todo, acho que és na verdade o mais incrível entre nós."
  },
  AvgDialog_71794_Content_114 = {
    Text = "A tua fé em mim é tão desconcertante quanto o teu entusiasmo pelo treino."
  },
  AvgDialog_71794_Content_115 = {
    Text = "Claro que acredito em ti! Esses Sonhos que continuas a ter—definitivamente não são Sonhos comuns. E se forem Revelações do Senhor?"
  },
  AvgDialog_71794_Content_116 = {
    Text = "...Por que razão o Senhor me daria tantas Revelações inexplicáveis? Um mero mortal como eu não pode mudar nada."
  },
  AvgDialog_71794_Content_117 = {
    Text = "Não é assim que deves pensar—e se pudesses? Geração após geração de mortais continuam a lutar, e eventualmente há coisas que podem ser mudadas. Caso contrário, por que razão escolhemos um Deus-Rei?"
  },
  AvgDialog_71794_Content_118 = {
    Text = "Tulu virou a cabeça e olhou para Noah, depois—pela primeira vez—aqueles olhos voltaram-se na tua direção."
  },
  AvgDialog_71794_Content_119 = {
    Text = "Acho que ficaria bem em ti."
  },
  AvgDialog_71794_Content_12 = {
    Text = "(<Gray:Por que... por que não consigo me mover? Meu corpo parece tão estranho. Será que o que eu possuo desta vez não é humano?>)"
  },
  AvgDialog_71794_Content_120 = {Text = "Huh?"},
  AvgDialog_71794_Content_121 = {
    Text = "Um bonacheirão como tu daria certamente um bom rei."
  },
  AvgDialog_71794_Content_122 = {
    Text = "Hss, isso é um elogio ou uma maldição... Não tens nem um pouco de curiosidade sobre como seria a vida de Deus-Rei?"
  },
  AvgDialog_71794_Content_123 = {
    Text = "Em meio às maldições resmungadas de Noah, o teu olhar cruzou-se com aqueles olhos amarelo-alaranjados, e um impulso inexplicável surgiu do mais profundo de ti."
  },
  AvgDialog_71794_Content_124 = {
    Text = "Era um desejo intenso, instando-te a Chamar aquela pequena figura para o teu lado sem demora, a agarrar aquela alma brilhante como as estrelas e fundir os dois numa só entidade."
  },
  AvgDialog_71794_Content_125 = {
    Text = "Como se pressentisse os teus pensamentos, a testa de Tulu franziu-se ligeiramente, revelando um olhar complexo que parecia conter Discernimento sobre tudo."
  },
  AvgDialog_71794_Content_126 = {
    Text = "(<Gray:A aprovação de um deus é Apenas uma gaiola...>)"
  },
  AvgDialog_71794_Content_127 = {
    Text = "Viste o reflexo nos olhos de Tulu. O que se espelhava naquelas pupilas indiferentes e sonolentas não era uma coroa dourada."
  },
  AvgDialog_71794_Content_128 = {
    Text = "Era uma Ilusão retorcida, nodosa, semelhante a tentáculos, desdobrando os seus tentáculos verde-escuros como se o Chamasse."
  },
  AvgDialog_71794_Content_13 = {
    Text = "Um estrondo abrupto ressoa — o som rangente de um eixo de Porta girando com dificuldade — enquanto a pesada Porta do templo é gentilmente empurrada, abrindo uma fresta."
  },
  AvgDialog_71794_Content_14 = {
    Text = "Algumas pequenas crianças espiam para dentro, infiltrando-se furtivamente no templo."
  },
  AvgDialog_71794_Content_15 = {
    Text = "Para sua surpresa, você avista uma figura familiar no final daquela fila de crianças."
  },
  AvgDialog_71794_Content_16 = {
    Text = "(<Gray:Aquele é...>)"
  },
  AvgDialog_71794_Content_17 = {
    Text = "Acorda, Tulu! O primeiro passo do nosso grande plano já foi um sucesso — não podemos vacilar agora!"
  },
  AvgDialog_71794_Content_18 = {
    Text = "O jovem mais velho sacudiu silenciosamente Tulu, que estava tão sonolento que sua mente havia vagado para longe."
  },
  AvgDialog_71794_Content_19 = {
    Text = "Para de me sacudir, Noah. Eu disse pra não me arrastar junto..."
  },
  AvgDialog_71794_Content_2 = {
    Text = "Sonhos têm bordas."
  },
  AvgDialog_71794_Content_20 = {
    Text = "Noah imediatamente cobriu a boca de Tulu."
  },
  AvgDialog_71794_Content_21 = {
    Text = "Shh, fala baixo! Como eu poderia te deixar de fora de algo tão importante? Os primeiros candidatos a herdeiro a tocar a Coroa... podemos entrar para a história!"
  },
  AvgDialog_71794_Content_22 = {
    Text = "...Se vamos entrar para a história, eu não sei, mas se o Velho sumo sacerdote nos Descobrir, seu traseiro com certeza vai florescer."
  },
  AvgDialog_71794_Content_23 = {
    Text = "Ah, qual é, como você vai saber se não tentar? Você vai se arrepender Depois se não aproveitar a chance quando ela aparece."
  },
  AvgDialog_71794_Content_24 = {
    Text = "Você não quer saber por que a Coroa é a \"Bênção\" mais direta do nosso Senhor, e mesmo assim o Velho sumo sacerdote sempre nos manteve longe dela?"
  },
  AvgDialog_71794_Content_25 = {
    Text = "*suspiro*..."
  },
  AvgDialog_71794_Content_26 = {
    Text = "Um som de passos ecoou, e as crianças logo chegaram ao lado do alto altar. Elas se reuniram em círculo, espiando para dentro através da tampa protetora de vidro cristalino."
  },
  AvgDialog_71794_Content_27 = {
    Text = "Um após outro, rostos jovens levemente refratados e distorcidos preencheram seu Campo de visão de 360 graus. Nas pupilas curiosas das crianças, você podia ver seu próprio reflexo, e até ouvir a respiração animada de duas delas."
  },
  AvgDialog_71794_Content_28 = {
    Text = "(<Gray:Já chega de proximidade, crianças. Mais perto seria falta de educação.>)"
  },
  AvgDialog_71794_Content_29 = {
    Text = "Uau... Esta é a primeira vez que vemos a Coroa tão de perto, não é?"
  },
  AvgDialog_71794_Content_3 = {
    Text = "Para mortais comuns, Sonhos são bolhas invertidas, misteriosas e elusivas de Ilusão."
  },
  AvgDialog_71794_Content_30 = {
    Text = "As gemas da Coroa são tão bonitas..."
  },
  AvgDialog_71794_Content_31 = {
    Text = "Uma Coroa tão grande... será que realmente podemos usá-la?"
  },
  AvgDialog_71794_Content_32 = {
    Text = "(<Gray:Se eu sou a Coroa... então isso deve ser antes de Tulu se tornar a herdeira da coroa.>)"
  },
  AvgDialog_71794_Content_33 = {
    Text = "Da sua perspectiva, emoções e desejos humanos são tão claros quanto uma paleta, cores em constante mudança surgindo na mente de cada pessoa."
  },
  AvgDialog_71794_Content_34 = {
    Text = "Vermelho, verde, roxo, amarelo — empolgação, nervosismo, anseio, alegria... Porém, em Tulu, havia Apenas um cinza constante e frio."
  },
  AvgDialog_71794_Content_35 = {
    Text = "(<Gray:Tulu, Tulu?>)"
  },
  AvgDialog_71794_Content_36 = {
    Text = "Tulu mantém os olhos semicerrados, parecendo desinteressada. Em meio aos seus chamados desesperados, você capta um breve vislumbre de um par de olhos âmbar indiferentes."
  },
  AvgDialog_71794_Content_37 = {
    Text = "Aqueles olhos atravessavam o corpo que parecia Como se estivesse adormecido, através das pesadas barreiras da realidade, fitando você em silêncio dentro de algum Sonho etéreo."
  },
  AvgDialog_71794_Content_38 = {
    Text = "Algum de vocês sente alguma coisa?"
  },
  AvgDialog_71794_Content_39 = {
    Text = "(<Gray:Não sinto nada em particular.>)"
  },
  AvgDialog_71794_Content_4 = {
    Text = "Para os Sábios, o fim dessas bolhas é uma membrana cintilante e iridescente."
  },
  AvgDialog_71794_Content_40 = {
    Text = "Parece o mesmo de sempre..."
  },
  AvgDialog_71794_Content_41 = {
    Text = "(<Gray:Isso é normal.>)"
  },
  AvgDialog_71794_Content_42 = {
    Text = "A sensação parece um pouco mais forte do que o normal? A Força que emana da Coroa está mais ativa agora?"
  },
  AvgDialog_71794_Content_43 = {
    Text = "(<Gray:Provavelmente porque há alguém Dentro agora.>)"
  },
  AvgDialog_71794_Content_44 = {
    Text = "Ninguém ouviu sua resposta ansiosa. As crianças reunidas Ao redor, meditando com seriedade e buscando compreensão, ficaram a Esperar, mas infelizmente nada aconteceu."
  },
  AvgDialog_71794_Content_45 = {
    Text = "Bem, já que estamos aqui... que tal tentarmos tocá-la?"
  },
  AvgDialog_71794_Content_46 = {
    Text = "Para desvendar os mistérios da Coroa, parece que precisaremos fazer contato real. Vamos lá."
  },
  AvgDialog_71794_Content_47 = {
    Text = "As crianças olharam nervosamente umas para as outras, depois assentiram juntas como se estivessem a encorajar-se mutuamente."
  },
  AvgDialog_71794_Content_48 = {
    Text = "Noah também engoliu em seco, limpou cuidadosamente as mãos na roupa e só então estendeu lentamente a mão para levantar a redoma de vidro que cobria a Coroa."
  },
  AvgDialog_71794_Content_49 = {
    Text = "À medida que a Coroa ficava gradualmente exposta ao ar, uma energia estranha parecia verdadeiramente dissipar-se da sua superfície lustrosa e cintilante."
  },
  AvgDialog_71794_Content_5 = {
    Text = "Quando sua alma perfura essa membrana, passando além do Sonho turvo que a envolve como líquido amniótico."
  },
  AvgDialog_71794_Content_50 = {
    Text = "Todas as crianças prenderam inconscientemente a respiração, observando Noah remover completamente a redoma de vidro. Uma a uma, como se reunissem coragem, estenderam as mãos, aproximando-se cada vez mais da Coroa."
  },
  AvgDialog_71794_Content_51 = {
    Text = "Apenas quando estavam prestes a tocar na Coroa — no exato momento em que já estavas a compor as tuas frases de abertura para um discurso de lâmpada dos desejos — um rugido trovejante e autoritário ecoou desde a Porta do templo, assustando Noah de tal forma que a sua mão tremeu violentamente, quase arremessando a redoma de vidro para longe."
  },
  AvgDialog_71794_Content_52 = {
    Text = "O que é que pensam que estão a fazer?"
  },
  AvgDialog_71794_Content_53 = {
    Text = "Todos ficaram imediatamente paralisados. Noah colocou rapidamente a redoma de vidro de volta sobre a Coroa, agarrou o braço de Tulu e fez sinais frenéticos aos outros com olhares urgentes."
  },
  AvgDialog_71794_Content_54 = {Text = "Correr!"},
  AvgDialog_71794_Content_55 = {
    Text = "O grupo de crianças dispersou-se em pânico como formigas numa frigideira quente. Tulu foi arrastado alguns passos para a frente, depois virou-se para olhar para o Velho sumo sacerdote que avançava na direção deles a passos largos."
  },
  AvgDialog_71794_Content_56 = {
    Text = "É inútil..."
  },
  AvgDialog_71794_Content_57 = {
    Text = "Como se tivesse previsto há muito o desfecho desta pequena aventura, Tulu não ofereceu resistência quando o Velho sumo sacerdote o agarrou pela gola — e, claro, a azarada Noah também foi apanhada."
  },
  AvgDialog_71794_Content_58 = {
    Text = "Amos, Samuel, Gretchen — venham aqui imediatamente. Não me façam repetir."
  },
  AvgDialog_71794_Content_59 = {
    Text = "As crianças, que não tinham conseguido dar mais do que alguns passos, baixaram a cabeça desanimadas e voltaram arrastando os pés ao ouvirem os seus nomes serem chamados."
  },
  AvgDialog_71794_Content_6 = {
    Text = "Além dessas incontáveis pequenas bolhas jaz o Sonho longo Caótico e Insano, ilimitado, dos Antigos."
  },
  AvgDialog_71794_Content_60 = {
    Text = "O Velho sumo sacerdote soltou uma risada fria, observando a fila de pequenos infratores diante de si."
  },
  AvgDialog_71794_Content_61 = {
    Text = "Muito bem, digam-me — o que é que vieram aqui fazer exatamente? Passei todo este tempo a orientar candidatos a Príncipe da Coroa apenas para produzir um bando de pequenos ladrõezinhos furtivos?"
  },
  AvgDialog_71794_Content_62 = {
    Text = "Nós, nós estávamos apenas..."
  },
  AvgDialog_71794_Content_63 = {
    Text = "Noé, que até então estava discretamente posicionado à frente de Tulu, apertou o punho e voluntariamente deu um passo à frente."
  },
  AvgDialog_71794_Content_64 = {
    Text = "Como a Cerimónia de Seleção está quase a chegar, queríamos aproximar-nos da Coroa antecipadamente para aprofundar o nosso entendimento. Não tínhamos intenção de desrespeitar..."
  },
  AvgDialog_71794_Content_65 = {
    Text = "Aprofundar o vosso entendimento? Devo elogiar-vos pela vossa diligência, então?"
  },
  AvgDialog_71794_Content_66 = {
    Text = "Pedimos desculpa, Vossa Excelência o Grande Sacerdote. O que fizemos foi errado."
  },
  AvgDialog_71794_Content_67 = {
    Text = "Só que viemos nos comunicar com o Senhor há tanto tempo, mas ainda não conseguimos nos aproximar da coroa concedida pelo Senhor. Todos temos muita curiosidade sobre ela."
  },
  AvgDialog_71794_Content_68 = {
    Text = "O Velho sumo sacerdote olhou para o rapaz sensato e, surpreendentemente, não o repreendeu."
  },
  AvgDialog_71794_Content_69 = {
    Text = "Samuel, tu és a criança com a Força mental mais forte entre todos. Por que achas que nunca permiti que nenhum de vocês tocasse na Coroa?"
  },
  AvgDialog_71794_Content_7 = {Text = "..."},
  AvgDialog_71794_Content_70 = {
    Text = "Porque ainda não conseguimos controlar a Força da Coroa. A Coroa provavelmente não responderia a nós."
  },
  AvgDialog_71794_Content_71 = {
    Text = "Amos, Gretchen, o que vocês acham?"
  },
  AvgDialog_71794_Content_72 = {
    Text = "Porque a Coroa é sagrada e nobre, representando a autoridade e a responsabilidade do Deus Rei, e nós ainda não conquistamos o direito de tocá-la?"
  },
  AvgDialog_71794_Content_73 = {
    Text = "Porque as nossas almas podem não necessariamente agradar às preferências do Senhor, e tocar na Coroa sem permissão poderia ser uma forma de Profanação?"
  },
  AvgDialog_71794_Content_74 = {
    Text = "Este velho que servira o divino toda a sua vida abanou a cabeça com uma expressão solene."
  },
  AvgDialog_71794_Content_75 = {
    Text = "Vocês estão todos certos, e ao mesmo tempo todos errados. Isto é Apenas devido à mais simples das verdades: nem todos podem usar a Coroa."
  },
  AvgDialog_71794_Content_76 = {
    Text = "Então, Vossa Excelência o Velho sumo sacerdote, que tipo de pessoa pode verdadeiramente usar a Coroa?"
  },
  AvgDialog_71794_Content_77 = {
    Text = "Vocês praticam e forjam seu espírito diariamente, certamente para melhor receber a vontade do Senhor. Mas tornar-se o substituto do Senhor é, acima de tudo, um destino já traçado."
  },
  AvgDialog_71794_Content_78 = {
    Text = "Portanto, a última coisa que devem fazer é Apenas aguardar em silêncio a escolha do Senhor. Não há necessidade de tristeza, nem de forçar. Quanto à razão pela qual vos proíbo de tocá-la..."
  },
  AvgDialog_71794_Content_79 = {
    Text = "A expressão perpetuamente severa do Velho sumo sacerdote suavizou-se inesperadamente naquele momento, mas não era ternura—antes, carregava um toque de tristeza e piedade."
  },
  AvgDialog_71794_Content_8 = {
    Text = "Úmido. O ar parece sempre úmido, invadindo seu sonho e trazendo um leve cheiro de sal e sangue."
  },
  AvgDialog_71794_Content_80 = {
    Text = "Se alguém que está destinado a nunca receber o oráculo divino forçar a Coroa sobre a sua cabeça, Apenas encontrará a morte, incapaz de suportar a Força do divino."
  },
  AvgDialog_71794_Content_81 = {
    Text = "No templo silencioso, as crianças caíram num prolongado silêncio, e o rosto do Velho sumo sacerdote gradualmente voltou à sua severidade habitual."
  },
  AvgDialog_71794_Content_82 = {
    Text = "Dado o vosso entusiasmo em venerar a Coroa mesmo com risco de morte, tal espírito de Devoção é verdadeiramente louvável."
  },
  AvgDialog_71794_Content_83 = {
    Text = "Para demonstrar a vossa Devoção perante o nosso Senhor, Todos deverão copiar a oração cem vezes diante da Coroa. Saem quando terminarem."
  },
  AvgDialog_71794_Content_84 = {
    Text = "As crianças soltaram longos gemidos de queixa, mas calaram-se sob o olhar do Velho sumo sacerdote, baixando resignadamente as cabeças em derrota."
  },
  AvgDialog_71794_Content_85 = {
    Text = "Entre todos os olhares dirigidos a ti—ressentimento, medo, anseio, adoração—Apenas Tulu nunca te dirigiu sequer um único olhar."
  },
  AvgDialog_71794_Content_86 = {
    Text = "O Velho sumo sacerdote olhou significativamente para Tulu, que permanecera imóvel do início ao fim, e acabou por partir sem dizer uma palavra."
  },
  AvgDialog_71794_Content_87 = {
    Text = "No instante em que os dois se cruzaram, ouviste a voz interior do futuro rei."
  },
  AvgDialog_71794_Content_88 = {
    Text = "(<Gray:Não adianta. Mesmo que eu usasse a Coroa, o que é que isso poderia mudar?>)"
  },
  AvgDialog_71794_Content_89 = {Text = "..."},
  AvgDialog_71794_Content_9 = {
    Text = "(<Gray:O cheiro de vento do mar... Sonhar de novo?>)"
  },
  AvgDialog_71794_Content_90 = {
    Text = "Em pouco tempo, encontras-te sentado ereto sobre a plataforma elevada do altar, olhando para baixo ao longo dos degraus de pedra para ver as crianças espalhadas e ajoelhadas tortas nas suas almofadas, copiando versículos de oração."
  },
  AvgDialog_71794_Content_91 = {
    Text = "Ouçam nosso Senhor. Devotem-se ao nosso Senhor. Os pecadores, nosso Senhor punirá. Os perdidos, nosso Senhor guiará..."
  },
  AvgDialog_71794_Content_92 = {
    Text = "As recitações murmuradas Ecoam pelo templo, acompanhadas pelo ocasional farfalhar de páginas sendo viradas, intercaladas de vez em quando por suspiros cansados."
  },
  AvgDialog_71794_Content_93 = {
    Text = "Os que sofrem, nosso Senhor Compensará. Os devotos, nosso Senhor concederá Benção. Os suplicantes, nosso Senhor agraciará. Os esperançosos, nosso Senhor responderá..."
  },
  AvgDialog_71794_Content_94 = {
    Text = "Ao lado do rosto miserável de Noah havia uma pilha de papéis muito mais alta que a de qualquer outro. Apenas bastava olhar para a fina camada de papéis diante de Tulu ao seu lado para Descobrir a razão — Noah havia batido no peito e os arrancado das mãos de Tulu."
  },
  AvgDialog_71794_Content_95 = {
    Text = "Fui eu quem te arrastou até aqui. Por toda razão e direito, devo compartilhar o seu fardo."
  },
  AvgDialog_71794_Content_96 = {
    Text = "Incapaz de vencer a discussão, Tulu Apenas pôde silenciosamente tirar alguns pedaços de petiscos parecidos com torrone de nozes de suas vestes e friamente enfiá-los nas mãos de Noah."
  },
  AvgDialog_71794_Content_97 = {
    Text = "Guardei das porções de refeição dos últimos dois dias. Eu não gosto deles mesmo."
  },
  AvgDialog_71794_Content_98 = {
    Text = "Doce de Amarant?! Huru, você está gritando..."
  },
  AvgDialog_71794_Content_99 = {
    Text = "Noah estufou as bochechas, com os olhos marejados de lágrimas enquanto apertava a mão de Tulu."
  },
  AvgDialog_71986_Content_1 = {
    Text = "Tranquilidade. Como se uma escuridão eterna e imutável envolvesse tudo."
  },
  AvgDialog_71986_Content_10 = {
    Text = "As ilusões efêmeras se despedaçaram diante dos meus olhos, revelando uma garota com os lábios apertados, seus olhos cobertos por uma venda."
  },
  AvgDialog_71986_Content_11 = {
    Text = "Não é ela, sou eu."
  },
  AvgDialog_71986_Content_12 = {
    Text = "Nos momentos finais, ela confiou seu corpo a mim."
  },
  AvgDialog_71986_Content_13 = {
    Text = "Diante da lembrança da destruição, perdi a conta de quantas vezes a experimentei..."
  },
  AvgDialog_71986_Content_14 = {
    Text = "Ela avançou e cobriu seus olhos com suas delicadas mãos."
  },
  AvgDialog_71986_Content_15 = {
    Text = "Dê-me uma mecha da sua consciência."
  },
  AvgDialog_71986_Content_16 = {
    Text = "Assim como a noite cai, tudo mergulha na escuridão..."
  },
  AvgDialog_71986_Content_17 = {
    Text = "E então o sol nasce, e tudo retorna ao ponto de partida."
  },
  AvgDialog_71986_Content_18 = {
    Text = "Esta é a sua consciência; tudo sobre eles se origina de você."
  },
  AvgDialog_71986_Content_19 = {
    Text = "Eles não reterão o registro desta destruição em suas memórias, mas eu sei que você não esquecerá."
  },
  AvgDialog_71986_Content_2 = {
    Text = "Naquela infinita tranquilidade, uma pequena luz branca se reuniu silenciosamente, flutuando e pairando diante dos seus olhos."
  },
  AvgDialog_71986_Content_20 = {
    Text = "Aprecie esses momentos fugazes."
  },
  AvgDialog_71986_Content_21 = {
    Text = "Antes que a destruição destinada chegue mais uma vez."
  },
  AvgDialog_71986_Content_3 = {
    Text = "Lamentavelmente, durante esta jornada contra a Dissolução... pagamos um preço tão doloroso."
  },
  AvgDialog_71986_Content_4 = {
    Text = "À sua custa..."
  },
  AvgDialog_71986_Content_5 = {
    Text = "Mas eu não consigo suportar ver você preso naquela Porta, em eterna solidão."
  },
  AvgDialog_71986_Content_6 = {
    Text = "Uma voz feminina fria. Familiar o suficiente, mas um pouco diferente."
  },
  AvgDialog_71986_Content_7 = {
    Text = "Abra os olhos."
  },
  AvgDialog_71986_Content_8 = {
    Text = "Eu irei retornar a você... um mundo."
  },
  AvgDialog_71986_Content_9 = {Text = "Ramon..."},
  AvgDialog_71987_Content_1 = {
    Text = "Sustento mortal"
  },
  AvgDialog_71987_Content_10 = {
    Text = "Então você quer dizer..."
  },
  AvgDialog_71987_Content_11 = {
    Text = "Quem está ali?"
  },
  AvgDialog_71987_Content_12 = {
    Text = "Desculpe, fui eu..."
  },
  AvgDialog_71987_Content_13 = {
    Text = "De modo geral, sou responsável pela última ronda de patrulha na igreja antes do anoitecer. Vendo que vocês dois não estavam em suas camas, comecei a olhar ao redor. Não queria ouvir sua conversa..."
  },
  AvgDialog_71987_Content_14 = {
    Text = "Está tudo bem, Ogier. Você vem também."
  },
  AvgDialog_71987_Content_15 = {
    Text = "Tudo bem, tudo bem."
  },
  AvgDialog_71987_Content_16 = {
    Text = "Ogier subiu desajeitadamente pela plataforma ao longo das escadas de madeira, evitando cuidadosamente fazer qualquer som com os pés para não perturbar o sono da multidão."
  },
  AvgDialog_71987_Content_17 = {
    Text = "Voltando à pergunta anterior."
  },
  AvgDialog_71987_Content_18 = {
    Text = "Eu refleti seriamente sobre esta pergunta: Todas as tragédias que estamos testemunhando agora são resultado das minhas ações?"
  },
  AvgDialog_71987_Content_19 = {
    Text = "O que posso te dizer é: muito semelhante."
  },
  AvgDialog_71987_Content_2 = {
    Text = "Eles já estão dormindo?"
  },
  AvgDialog_71987_Content_20 = {
    Text = "Decisivo e conciso, visando uma morte limpa, o que se alinha bem com minha estética."
  },
  AvgDialog_71987_Content_21 = {
    Text = "Mas há algo estranho também — eu não gosto de dispositivos atrasados; esse tipo de espera e tormento é uma forma de tortura que não consigo tolerar."
  },
  AvgDialog_71987_Content_22 = {
    Text = "Como venho trabalhando com todos vocês durante esse tempo, não tive a oportunidade de pressionar o botão chamado \"Aviso de Morte\""
  },
  AvgDialog_71987_Content_23 = {
    Text = "Isso, isso seria maravilhoso!"
  },
  AvgDialog_71987_Content_24 = {Text = "Por que?"},
  AvgDialog_71987_Content_25 = {
    Text = "Quando eu ouvi sua conversa agora há pouco, fiquei preocupado que a Senhorita Doll fosse a mente por trás de tudo isso."
  },
  AvgDialog_71987_Content_26 = {
    Text = "Nesse caso, não terei escolha a não ser avançar e me tornar um inimigo da Senhorita Boneca."
  },
  AvgDialog_71987_Content_27 = {
    Text = "Agora, sabendo que há alguém puxando as cordas nos bastidores, posso relaxar e considerar a Senhorita Boneca como uma parceira!"
  },
  AvgDialog_71987_Content_28 = {
    Text = "Ogier guardou a lança longa que carregava silenciosamente nas costas, seu sorriso sincero e radiante."
  },
  AvgDialog_71987_Content_29 = {Text = "..."},
  AvgDialog_71987_Content_3 = {
    Text = "Hmm, eles deveriam descansar um pouco."
  },
  AvgDialog_71987_Content_30 = {
    Text = "Hmph, não me importo com companheiros ou algo do tipo."
  },
  AvgDialog_71987_Content_31 = {
    Text = "Isso não vai acontecer, Boneca."
  },
  AvgDialog_71987_Content_32 = {
    Text = "Embora eu não saiba nada sobre a versão Gênesis de você neste mundo, estou muito familiarizado com a Boneca como professor..."
  },
  AvgDialog_71987_Content_33 = {
    Text = "Por que não me diga que tipo de pessoa é a \"Boneca\" que você conhece?"
  },
  AvgDialog_71987_Content_34 = {Text = "..."},
  AvgDialog_71987_Content_35 = {
    Text = "O professor de rosto frio que você encontrou pela primeira vez na aula de ensino do Reino."
  },
  AvgDialog_71987_Content_36 = {
    Text = "Na cerimônia de entrega da chave, Doll solemnemente entregou a chave de prata a você."
  },
  AvgDialog_71987_Content_37 = {
    Text = "Sempre crítico sobre seus documentos e pensamentos, mas, no final, a Boneca resolverá todas as suas preocupações."
  },
  AvgDialog_71987_Content_38 = {
    Text = "No Hospital Lai, Doll enfrentou Herbert sozinha e abriu um caminho para você sobreviver."
  },
  AvgDialog_71987_Content_39 = {
    Text = "......E finalmente, Boneca, que cortou resolutamente o Link com você."
  },
  AvgDialog_71987_Content_4 = {
    Text = "O que você vislumbrou durante o dia da dissolução do sonho..."
  },
  AvgDialog_71987_Content_40 = {
    Text = "Memórias se desenrolam uma a uma, revelando que você esteve ao lado um do outro sem saber, vivendo tantas histórias."
  },
  AvgDialog_71987_Content_41 = {
    Text = "Você conta a ela tudo o que sabe sobre a Boneca."
  },
  AvgDialog_71987_Content_42 = {Text = "..."},
  AvgDialog_71987_Content_43 = {Text = "..."},
  AvgDialog_71987_Content_44 = {
    Text = "Embora você fale mal dela, no fundo, ainda a respeita, não é?"
  },
  AvgDialog_71987_Content_45 = {
    Text = "Deixa eu adivinhar, essa é a razão pela qual você ainda não pôs a mão em mim, certo?"
  },
  AvgDialog_71987_Content_46 = {
    Text = "Perdi minha memória, mas você não.\nVocê teve muitas oportunidades de me atacar desprevenido, antes que eu percebesse sua identidade, mas não fez nada."
  },
  AvgDialog_71987_Content_47 = {
    Text = "Parece que seu mentor ainda não lhe disse como lidar com potenciais inimigos."
  },
  AvgDialog_71987_Content_48 = {
    Text = "No momento certo, talvez eu atue."
  },
  AvgDialog_71987_Content_49 = {
    Text = "Mas não agora."
  },
  AvgDialog_71987_Content_5 = {
    Text = "É este mundo à beira da ruína."
  },
  AvgDialog_71987_Content_50 = {
    Text = "Cachorrinho tolo... Mais cedo ou mais tarde, você pagará o preço pela sua suavidade."
  },
  AvgDialog_71987_Content_51 = {Text = "..."},
  AvgDialog_71987_Content_52 = {
    Text = "<Shake:Eee—Eeyah—>"
  },
  AvgDialog_71987_Content_53 = {
    Text = "Um grito agudo rasgou o céu noturno."
  },
  AvgDialog_71987_Content_54 = {
    Text = "O que há de errado?!"
  },
  AvgDialog_71987_Content_55 = {
    Text = "No final da sua linha de visão, a figura de Mason correu em sua direção em desespero. Seu braço torcido puxava ansiosamente seu cabelo desgrenhado, chamando por você incoerentemente com uma voz rouca."
  },
  AvgDialog_71987_Content_56 = {
    Text = "Sarah... vá ver a Sra. Sarah...\nA cabeça dela... a cabeça dela!! !!"
  },
  AvgDialog_71987_Content_6 = {
    Text = "Porque a morte está se aproximando, todos os seres instintivamente se juntam, se abraçam e se fundem."
  },
  AvgDialog_71987_Content_7 = {
    Text = "Boneca... No meu mundo, você desencadeou vários desastres, como inundações, deslizamentos de terra, e a propagação da Dissolução."
  },
  AvgDialog_71987_Content_8 = {
    Text = "É tudo causado por você?"
  },
  AvgDialog_71987_Content_9 = {Text = "Desculpe."},
  AvgDialog_71989_Content_1 = {
    Text = "Maçã envenenada"
  },
  AvgDialog_71989_Content_10 = {Text = "..."},
  AvgDialog_71989_Content_11 = {
    Text = "Um longo silêncio permanece entre vocês. Você sente um nó na garganta, sem saber como responder."
  },
  AvgDialog_71989_Content_12 = {
    Text = "Respiração Profunda"
  },
  AvgDialog_71989_Content_13 = {
    Text = "A instituição mais próxima da \"Universidade Mythag\" é outra instituição de ensino superior, também focada principalmente na pesquisa de diferentes espécies."
  },
  AvgDialog_71989_Content_14 = {
    Text = "É apenas que a pesquisa deles é mais tradicional e ortodoxa. Os investigadores se concentram em pesquisa arqueológica, levantamentos de campo e compilação de manuscritos ocultos, enquanto o número de pessoal de combate é muito menor do que na Universidade Mythag."
  },
  AvgDialog_71989_Content_15 = {
    Text = "Esta prestigiada instituição... é chamada de \"Universidade Miskatônica\"."
  },
  AvgDialog_71989_Content_16 = {
    Text = "Sem um Guardião, sem Prata, esta \"Universidade Miskatônica\" do mundo certamente carece da base para recrutar Bonecas."
  },
  AvgDialog_71989_Content_17 = {
    Text = "Infelizmente, não me lembro da aniquilação que Jenkin mencionou. Temo que todas as Memórias subsequentes tenham sido perdidas devido à explosão."
  },
  AvgDialog_71989_Content_18 = {
    Text = "Quanto ao desejo de retornar ao mundo original... eu tenho algumas ideias."
  },
  AvgDialog_71989_Content_19 = {
    Text = "A Madame Narciso uma vez te disse, isso não é o sonho de Tuhua Bo; portanto, conhecer a verdade do mundo atual provavelmente ajudará a estabelecer conexões com outros mundos dimensionais."
  },
  AvgDialog_71989_Content_2 = {
    Text = "Você está sozinho no telhado, respirando o ar fresco da noite."
  },
  AvgDialog_71989_Content_20 = {
    Text = "Este é um caminho mais longo, e principalmente eficaz—afinal, eu transitei com sucesso por várias Dimensões antes da minha amnésia, e meus pensamentos devem permanecer consistentes com quem eu sou."
  },
  AvgDialog_71989_Content_21 = {
    Text = "Quanto a atalhos, deixe-me pensar nisso antes de lhe contar..."
  },
  AvgDialog_71989_Content_22 = {
    Text = "No entanto, há mais uma coisa que você precisa pensar cuidadosamente."
  },
  AvgDialog_71989_Content_23 = {
    Text = "A busca na casa de pobres não está relacionada ao seu retorno ao mundo original."
  },
  AvgDialog_71989_Content_24 = {
    Text = "Atualmente, você está dedicando sua energia a essas questões triviais. Quando esse dia chegar, você realmente conseguirá deixar tudo aqui para trás e retornar à sua vida passada sem distrações?"
  },
  AvgDialog_71989_Content_25 = {
    Text = "Você pode pensar com calma sobre essa questão. Agora, há coisas mais importantes a serem enfrentadas. \nOlhe para lá ——"
  },
  AvgDialog_71989_Content_26 = {
    Text = "Luzes em movimento como estrelas surgem da escuridão, passando suavemente pela noite."
  },
  AvgDialog_71989_Content_27 = {
    Text = "É uma heterogeneidade da Dissolução!"
  },
  AvgDialog_71989_Content_28 = {
    Text = "Os mutantes da Dissolução que você expulsou à luz do dia se aglomeram em massa, empurrando-se inquietamente, até escalando e mordendo uns aos outros."
  },
  AvgDialog_71989_Content_29 = {
    Text = "Seu objetivo... é muito claro: a torre do sino."
  },
  AvgDialog_71989_Content_3 = {
    Text = "Apesar da cidade desolada envolta em fumaça e poeira, as estrelas brilhantes e cintilantes ainda podem ser vistas no alto do telhado, oferecendo a você um breve momento de consolo."
  },
  AvgDialog_71989_Content_30 = {
    Text = "Eles estão vindo por nós."
  },
  AvgDialog_71989_Content_31 = {
    Text = "Hora de lutar!"
  },
  AvgDialog_71989_Content_4 = {
    Text = "Fusão·Dor... por que você desse mundo não escolheu ingressar na universidade de Mythag?"
  },
  AvgDialog_71989_Content_5 = {
    Text = "Você não entende este mundo, tolinha."
  },
  AvgDialog_71989_Content_6 = {
    Text = "A luz das estrelas incide sobre as articulações esféricas da Boneca, refletindo tons metálicos que não são humanoides."
  },
  AvgDialog_71989_Content_7 = {
    Text = "Você acha que a diferença entre dimensões reside unicamente nas manifestações de dissolução e experiências individuais? Isso seria um grande erro."
  },
  AvgDialog_71989_Content_8 = {
    Text = "Até onde eu sei, não existe a chamada \"Universidade Mythag\" nesta dimensão."
  },
  AvgDialog_71989_Content_9 = {Text = "..."},
  AvgDialog_71990_Content_1 = {
    Text = "Resposta de talvez"
  },
  AvgDialog_71990_Content_10 = {
    Text = "Desperte, desperte, vocês dois preguiçosos."
  },
  AvgDialog_71990_Content_11 = {
    Text = "A irmã me pediu para chamá-la para a tia Sarah."
  },
  AvgDialog_71990_Content_12 = {
    Text = "Você entra na cabine depois de pisar na igreja; Mason está ao lado da cama, cuidando de Sarah, que dorme tranquilamente, enquanto a luz suave da lareira banha suas bochechas com calor."
  },
  AvgDialog_71990_Content_13 = {
    Text = "O Sumo Sacerdote Salvador estava ao lado da janela, observando tranquilamente a paisagem do lado de fora, como uma estátua silenciosa."
  },
  AvgDialog_71990_Content_14 = {
    Text = "Sarah no sonho solta um murmúrio dolorido. Justo quando você está prestes a se aproximar, Mason gentilmente coloca o dedo nos lábios e sussurra \"shh,\" então pega um lenço branco para limpar."
  },
  AvgDialog_71990_Content_15 = {
    Text = "Por favor, siga-me."
  },
  AvgDialog_71990_Content_16 = {
    Text = "A doença da Dama Sarah é mais complicada do que eu imaginava."
  },
  AvgDialog_71990_Content_17 = {
    Text = "Não consigo descobrir a razão?"
  },
  AvgDialog_71990_Content_18 = {
    Text = "Não, pelo contrário, já tenho algumas pistas. Só que..."
  },
  AvgDialog_71990_Content_19 = {
    Text = "Acredito que todos vocês estão muito familiarizados com os princípios por trás dos \"Despertadores\", então não irei me aprofundar mais."
  },
  AvgDialog_71990_Content_2 = {
    Text = "O mar está te chamando."
  },
  AvgDialog_71990_Content_20 = {
    Text = "A alta energia de vontade dentro da Senhora Sarah está em feroz conflito com a alta vontade que sustenta sua alma."
  },
  AvgDialog_71990_Content_21 = {
    Text = "Se a Prata implantada na cabeça da Srta. Sarah for removida, sua consciência desaparecerá; se ela não depender do poder do Sonho, seu corpo se tornará cinzas como os outros."
  },
  AvgDialog_71990_Content_22 = {
    Text = "Infelizmente, realmente não posso curá-la com o poder do Pai Divino.\nNão importa qual das vontades superiores acabe prevalecendo... será difícil manter a vida da Sra. Sarah."
  },
  AvgDialog_71990_Content_23 = {
    Text = "Eu entendo. Ela está condenada a morrer."
  },
  AvgDialog_71990_Content_24 = {
    Text = "É desistir da vida ou continuar vivendo na dor... Não há uma terceira escolha?"
  },
  AvgDialog_71990_Content_25 = {
    Text = "Salvador balançou a cabeça, seu cabelo branco levemente desordenado esfregando contra a roupa do bispo, produzindo um som de farfalhar."
  },
  AvgDialog_71990_Content_26 = {
    Text = "Melt·Dor olha para você, um sorriso de vitória inadequado aparece em seus olhos, como se ela estivesse exibindo sua superioridade e dizendo: \"Você viu? Eu estava certa, não estava?\""
  },
  AvgDialog_71990_Content_27 = {
    Text = "*Tosse, tosse...*"
  },
  AvgDialog_71990_Content_28 = {
    Text = "Um som violento de tosse vem da escuridão, e no rosto de Sarah, distorcido pela dor, as rachaduras prateadas aumentaram ainda mais grotescas."
  },
  AvgDialog_71990_Content_29 = {
    Text = "Ouvi... é %player%... {Male=ele,Female=ela} está aqui?"
  },
  AvgDialog_71990_Content_3 = {
    Text = "Isso é o mar escuro, refletindo um brilho amarelo-esverdeado sombrio sob a iluminação das estrelas."
  },
  AvgDialog_71990_Content_30 = {
    Text = "Ela está... me chamando?"
  },
  AvgDialog_71990_Content_31 = {
    Text = "Quem mais poderia ser? Há mais alguém aqui chamado %player%?"
  },
  AvgDialog_71990_Content_32 = {
    Text = "Você se aproxima da cama de Sarah, e Mason a ajuda a sentar.\nSarah respira com dificuldade, recuperando-se com esforço após um longo momento, e então levanta os olhos para você, esboçando um sorriso forçado."
  },
  AvgDialog_71990_Content_33 = {
    Text = "Posso pedir um favor a você, gentil pessoa...?"
  },
  AvgDialog_71990_Content_34 = {
    Text = "Por favor, prossiga."
  },
  AvgDialog_71990_Content_35 = {
    Text = "Posso dizer que você é uma pessoa bem informada."
  },
  AvgDialog_71990_Content_36 = {
    Text = "Nesse caso, poderia encontrar uma forma de entregar estas joias ao Sr. Rogers para cobrir as despesas de subsistência antes que a pequena Aigis se torne independente?"
  },
  AvgDialog_71990_Content_37 = {
    Text = "Eu sei que provavelmente não viverei para vê-la crescer... O Sr. Rogers é generoso e provavelmente não lhe falta esta pequena quantia."
  },
  AvgDialog_71990_Content_38 = {
    Text = "Mas com esses acessórios, pelo menos ela não é totalmente dependente dos outros... Aquela criança foi abandonada pela mãe quando era pequena. Quero que ela saiba que a Irmã Sarah não a abandonou..."
  },
  AvgDialog_71990_Content_39 = {
    Text = "E então, diga a ela que, quando crescer, deve lembrar de levar um buquê de flores para os túmulos de Tuyog e do pequeno Willy todos os anos... Aqueles crianças eram tão jovens; devem ter tido muito medo da solidão."
  },
  AvgDialog_71990_Content_4 = {
    Text = "Isso é o sonho longo, tênue e sombrio do profundo adormecido, escuridão e silêncio sob a estrela negra suspensa."
  },
  AvgDialog_71990_Content_40 = {
    Text = "E você, Sarah?"
  },
  AvgDialog_71990_Content_41 = {
    Text = "Não se preocupe, eu não vou desistir facilmente. Até aquele dia chegar, eu vou lutar para sobreviver. \nMesmo que reste apenas uma mínima esperança... Eu ainda quero rever aquelas crianças."
  },
  AvgDialog_71990_Content_42 = {
    Text = "Nas ruas desertas de Londres, você solta um longo suspiro. \nMesmo os caminhos cobertos de fumaça não são tão sombrios quanto o ar que envolve Sarah.\n\n."
  },
  AvgDialog_71990_Content_43 = {
    Text = "Melt·Dor caminha ao seu lado, mantendo uma distância de meio passo em relação a você."
  },
  AvgDialog_71990_Content_44 = {
    Text = "Boneca. Hoje, sou capaz de responder suas perguntas."
  },
  AvgDialog_71990_Content_45 = {
    Text = "Deixe-me ouvir sua sofismo."
  },
  AvgDialog_71990_Content_46 = {
    Text = "Você sabe? Aos seus olhos, Sarah já é uma pessoa morrendo. O apego dela a este mundo deve ser sem significado."
  },
  AvgDialog_71990_Content_47 = {
    Text = "Mas não é esse o caso. Ela ainda se preocupa com as crianças que foram levadas."
  },
  AvgDialog_71990_Content_48 = {
    Text = "Isto é a humanidade comum, e as preocupações da humanidade comum."
  },
  AvgDialog_71990_Content_49 = {
    Text = "O fim e a morte que você catalisou apenas arrancam o último fio de esperança deles."
  },
  AvgDialog_71990_Content_5 = {
    Text = "Entrelaçamento, conflito, distorção, rasgo, luta. Os tentáculos entrelaçando e batalhando entre si."
  },
  AvgDialog_71990_Content_50 = {
    Text = "Mas a esperança é meramente uma ilusão evasiva; a dor do momento é o que é real."
  },
  AvgDialog_71990_Content_51 = {
    Text = "Mesmo que tenham que viver em uma ilusão, muitos ainda estão dispostos a suportar a dor atual pela esperança adiante."
  },
  AvgDialog_71990_Content_52 = {
    Text = "Esta é a resiliência da humanidade."
  },
  AvgDialog_71990_Content_53 = {
    Text = "Você diz que não entende o motivo das ações de Salvador, mas eu posso compreendê-lo."
  },
  AvgDialog_71990_Content_54 = {
    Text = "As ações de Salvador seguiram apenas um princípio: deixar todos \"viverem\" igualmente."
  },
  AvgDialog_71990_Content_55 = {
    Text = "Em seus olhos, a vida não é uma questão de pesar ou um número; o que ele vê são indivíduos desesperados por sobrevivência, um após o outro."
  },
  AvgDialog_71990_Content_56 = {
    Text = "Enquanto você \"sobreviver\", há um futuro, há uma possibilidade."
  },
  AvgDialog_71990_Content_57 = {
    Text = "\"Possibilidade\", não é? ......"
  },
  AvgDialog_71990_Content_58 = {
    Text = "Melt·Dor ficou pensativa por um momento e, como se tivesse se lembrado de algo, soltou um resmungo frio."
  },
  AvgDialog_71990_Content_59 = {
    Text = "Hmph, se é assim, me siga."
  },
  AvgDialog_71990_Content_6 = {
    Text = "Um lado uiva: Eu vou devorar aquele delicioso vaso, a fonte de Inspiração e Intelecto, o portador de Perspicácia e Pensamento, o órgão de Imaginação e Ilusão."
  },
  AvgDialog_71990_Content_60 = {
    Text = "Para onde ir?"
  },
  AvgDialog_71990_Content_61 = {
    Text = "Vá e testemunhe... vá e confirme uma resposta."
  },
  AvgDialog_71990_Content_62 = {
    Text = "Lembre-se de trazer aquele ratinho; haverá momentos em que ela pode ser útil."
  },
  AvgDialog_71990_Content_7 = {
    Text = "O outro lado respondeu: A decadência da ganância afundará no fundo de um lago sem estrelas."
  },
  AvgDialog_71990_Content_8 = {Text = "..."},
  AvgDialog_71990_Content_9 = {Text = "..."},
  AvgDialog_71991_Content_1 = {Text = "A verdade"},
  AvgDialog_71991_Content_10 = {
    Text = "A boneca deu um chute, enviando facilmente o mutante Dissolução que atacava para longe."
  },
  AvgDialog_71991_Content_11 = {
    Text = "Pare de desperdiçar palavras. Se você me entediar, eu vou eliminar você junto com essas coisas!"
  },
  AvgDialog_71991_Content_12 = {Text = "..."},
  AvgDialog_71991_Content_13 = {
    Text = "Você relata os encontros ocorridos após o primeiro encontro com Fusão·Doll, desde sua recuperação após o acidente de avalanche, até ela usar o corpo cibernético de Doll para escapar da contenção, e finalmente transferir sua dimensão para o mundo atual..."
  },
  AvgDialog_71991_Content_14 = {
    Text = "Eu vejo, então você explodiu meu laboratório e me forçou a trabalhar para você aqui sem pagamento."
  },
  AvgDialog_71991_Content_15 = {
    Text = "Não tire as coisas do contexto. Antes disso, você foi quem causou a destruição da minha Dimensão e me aprisionou neste cilindro cerebral."
  },
  AvgDialog_71991_Content_16 = {
    Text = "Não importa mais."
  },
  AvgDialog_71991_Content_17 = {
    Text = "Uma aberração meio dissolvida com um rosto grotesco e rachado soltou um gorgolejo, expelindo um líquido espesso e escuro e emitindo um som assobiante arrepiante."
  },
  AvgDialog_71991_Content_18 = {
    Text = "Mas o que você disse sobre a destruição do mundo..."
  },
  AvgDialog_71991_Content_19 = {
    Text = "As pinças perfuraram a cabeça do gigantesco rato selvagem infectado pela Dissolução, com um som de estalo enquanto a matéria cerebral espirrava. A Boneca indiferentemente balançou as pinças para soltá-lo."
  },
  AvgDialog_71991_Content_2 = {
    Text = "Indo encontrar aqueles caras da West Side? Não conte comigo. Não consigo me dar bem com eles."
  },
  AvgDialog_71991_Content_20 = {
    Text = "Na minha memória, eu indubitavelmente não tenho nenhum motivo para buscar a destruição do mundo."
  },
  AvgDialog_71991_Content_21 = {
    Text = "Em contraste, eu estive buscando maneiras de proteger o mundo da ameaça da Dissolução, e, como resultado, fui sobrecarregado."
  },
  AvgDialog_71991_Content_22 = {
    Text = "Você acha que estou te enganando?"
  },
  AvgDialog_71991_Content_23 = {
    Text = "Não, eu não quero negar suas palavras. Pelo seu olhar, eu posso ver sua honestidade."
  },
  AvgDialog_71991_Content_24 = {
    Text = "Deve haver uma razão por trás da minha escolha aqui, mas atualmente eu não sei nada sobre isso."
  },
  AvgDialog_71991_Content_25 = {
    Text = "Um leve indício de perplexidade mal perceptível cintilou em seus olhos."
  },
  AvgDialog_71991_Content_26 = {
    Text = "O gênio que me auto-proclamo, tão obcecado pela realidade que abandonei tudo da civilização \"Mi-Go\"..."
  },
  AvgDialog_71991_Content_27 = {
    Text = "Então por que você mudaria de lado tão facilmente para o campo da Destruição?"
  },
  AvgDialog_71991_Content_28 = {
    Text = "Você percebeu de forma aguçada uma palavra-chave única."
  },
  AvgDialog_71991_Content_29 = {
    Text = "\"Civilização \"Mi-Go\"..."
  },
  AvgDialog_71991_Content_3 = {
    Text = "Além disso, eu tenho que ficar aqui para proteger minha irmã mais velha."
  },
  AvgDialog_71991_Content_30 = {
    Text = "Nos registros de Mythag, a civilização da qual você se origina é chamada Alaemyces..."
  },
  AvgDialog_71991_Content_31 = {
    Text = "Alaemyces, o fungo voador... Este apelido não é tão ruim."
  },
  AvgDialog_71991_Content_32 = {
    Text = "No entanto, em um mundo que não é Kadath, não precisamos nos envergonhar de todas as coisas conectadas ao Seu olhar."
  },
  AvgDialog_71991_Content_33 = {
    Text = "Não é o mundo de Kadath..."
  },
  AvgDialog_71991_Content_34 = {
    Text = "Talvez você tenha muitas perguntas, mas vamos encerrar a conversa fiada aqui. Se continuarmos, não chegaremos à igreja antes da noite."
  },
  AvgDialog_71991_Content_4 = {
    Text = "Esse grande cérebro rosa não é o suficiente para te proteger?"
  },
  AvgDialog_71991_Content_5 = {Text = "..."},
  AvgDialog_71991_Content_6 = {
    Text = "Em resumo, no final, apenas nós dois fomos encarregados da missão de fuga."
  },
  AvgDialog_71991_Content_7 = {
    Text = "O objetivo é limpar a variante de Dissolução sob o sino. Vá até a Igreja de Redenção no distrito ocidental e peça o apoio de Salvador."
  },
  AvgDialog_71991_Content_8 = {
    Text = "Aproveite esta oportunidade para me contar tudo o que você sabe sobre antes da minha amnésia, em detalhes."
  },
  AvgDialog_71991_Content_9 = {
    Text = "Você realmente acha que chamar este ambiente de \"Aproveite esta oportunidade\" é um pouco subestimado?!"
  },
  AvgDialog_71992_Content_1 = {
    Text = "No véu de chuva"
  },
  AvgDialog_71992_Content_10 = {
    Text = "E ela não vai me dar o relatório experimental de qualquer forma."
  },
  AvgDialog_71992_Content_100 = {
    Text = "Você pressiona o broche, um clique suave é ouvido, seguido pelo som de uma conexão sendo estabelecida."
  },
  AvgDialog_71992_Content_101 = {
    Text = "Ei, ei, o Link está estável?"
  },
  AvgDialog_71992_Content_102 = {
    Text = "Fusão - Boneca, você..."
  },
  AvgDialog_71992_Content_103 = {
    Text = "Seja verdadeiramente grato."
  },
  AvgDialog_71992_Content_104 = {
    Text = "Para garantir que você, pobre cachorrinho encharcado de chuva, não se sinta tão sozinho — contacte-me através deste comunicador sempre que precisar de apoio na jornada que tem pela frente."
  },
  AvgDialog_71992_Content_105 = {
    Text = "Embarque na sua jornada."
  },
  AvgDialog_71992_Content_106 = {
    Text = "Desta vez... Destruição é vossa aliada."
  },
  AvgDialog_71992_Content_11 = {
    Text = "Exatamente."
  },
  AvgDialog_71992_Content_12 = {
    Text = "Lembra? Eu não te disse qual era esse atalho imediatamente."
  },
  AvgDialog_71992_Content_13 = {
    Text = "Porque esse \"atalho\" exige um custo proporcional."
  },
  AvgDialog_71992_Content_14 = {
    Text = "Assim que confirmo este \"atalho\", inevitavelmente sigo o caminho que devo percorrer e não tenho escolha a não ser voltar a ser quem sou: aquele que busca a destruição."
  },
  AvgDialog_71992_Content_15 = {
    Text = "A luta contra \"si mesmo\"—soa tolo, tolo o suficiente para não justificar meu título de \"gênio\"."
  },
  AvgDialog_71992_Content_16 = {
    Text = "Mas se eu tivesse lido este relatório antes, talvez não conseguisse permanecer ao seu lado tão resolutamente."
  },
  AvgDialog_71992_Content_17 = {
    Text = "Em resumo, o relatório agora é seu."
  },
  AvgDialog_71992_Content_18 = {
    Text = "Avalie seu estado mental antes de ler."
  },
  AvgDialog_71992_Content_19 = {
    Text = "Você acalma sua mente e desdobra o manuscrito amarelado."
  },
  AvgDialog_71992_Content_2 = {
    Text = "Três dias depois"
  },
  AvgDialog_71992_Content_20 = {
    Text = "<Estudo da Coordenação dos Olhares de Tohuwabohu>"
  },
  AvgDialog_71992_Content_21 = {
    Text = "Objetivo do experimento: \nObservar e registrar, de forma quantitativa e qualitativa, a reação de Tohuwabohu diante de alvos de alta espiritualidade em seu campo de visão, verificando o padrão de rastreamento visual desses alvos móveis de alta espiritualidade. \nEste experimento visa revelar as características visuais de Tohuwabohu e seu mecanismo de reação diante de alvos espirituais específicos."
  },
  AvgDialog_71992_Content_22 = {
    Text = "Contexto do experimento: \nDe acordo com documentos históricos e registros experimentais anteriores (ver \"Investigação sobre as Causas do Fenômeno de Dissolução\"), os olhares de Tohuwabohu são capazes de provocar o fenômeno da dissolução, porém o mecanismo pelo qual Tohuwabohu identifica e captura seus alvos ainda não foi esclarecido. \nEstudar o princípio do movimento coordenado dos olhares de Tohuwabohu pode nos ajudar a buscar de forma mais eficaz meios de sobrevivência no mundo atual."
  },
  AvgDialog_71992_Content_23 = {
    Text = "Materiais experimentais: \n1. Uma amostra de cada um dos sete materiais espirituais de diferentes intensidades; \n2. Equipamento e combustível para travessia dimensional (nove conjuntos); \n3. Tabela de registro de dados experimentais"
  },
  AvgDialog_71992_Content_24 = {
    Text = "Método experimental: \n1. Definir o ambiente experimental: selecionar dimensões com flutuações de valores espirituais relativamente estáveis e próximas;\n 2. Procedimento experimental:\n① Introduzir sequencialmente em cada dimensão materiais experimentais com diferentes valores espirituais.\n② Infiltrar-se nas organizações locais de combate à dissolução, normalmente a Universidade Misaag, para obter dados sobre a frequência das explosões de dissolução em cada dimensão.\n③ Utilizar núcleos de prata de baixa espiritualidade como meio para transmitir os dados ao corpo artificial número 279.\n④ Organizar os dados e realizar a análise."
  },
  AvgDialog_71992_Content_25 = {Text = "..."},
  AvgDialog_71992_Content_26 = {
    Text = "No segundo relatório de experimento, Doll: Inferno lançou sete Próteses simultaneamente em vez de introduzir materiais espirituais aleatoriamente em cada dimensão."
  },
  AvgDialog_71992_Content_27 = {
    Text = "No terceiro relatório, o número de materiais espirituais utilizados mudou."
  },
  AvgDialog_71992_Content_28 = {Text = "..."},
  AvgDialog_71992_Content_29 = {
    Text = "O manuscrito final havia se tornado excepcionalmente confuso."
  },
  AvgDialog_71992_Content_3 = {
    Text = "Revisei todas as anotações que sobraram até o momento, e sinto muito em informar duas coisas. Primeiro, a placa de pedra mencionada por B-68 já desapareceu.\n."
  },
  AvgDialog_71992_Content_30 = {
    Text = "Não tem sentido. \nEstou investigando um resultado sem sentido. \nCriaturas espirituais são alvos dEle por natureza; seres com índice gnóstico superior a 21 atrairão Sua atenção, afetando também outras existências ao redor. \nO vazamento deste relatório só levará a um destino ainda mais terrível: a medição, seleção, atração e caça aos índices gnósticos."
  },
  AvgDialog_71992_Content_31 = {
    Text = "O pior é que não são apenas os humanos que conseguem detectar o índice gnóstico - diversas populações de criaturas marinhas possuem índice gnóstico superior a 21. \nA menos que se destrua por completo todos os mares... mas isso também resultaria em nenhuma sobrevivência humana."
  },
  AvgDialog_71992_Content_32 = {
    Text = "Todas as soluções são inúteis; Seu olhar é inevitável."
  },
  AvgDialog_71992_Content_33 = {
    Text = "Ninguém pode ser salvo."
  },
  AvgDialog_71992_Content_34 = {
    Text = "Seu breve alívio não é resultado do seu sacrifício pessoal nem de qualquer misericórdia daquele ser; é meramente um subproduto de sua fugaz curiosidade sobre seu próprio fragmento."
  },
  AvgDialog_71992_Content_35 = {
    Text = "Ele prendeu a respiração e se concentrou, dando uma olhada em Seu estilhaço, esquecendo-se de respirar momentaneamente..."
  },
  AvgDialog_71992_Content_36 = {
    Text = "Então todos vocês presumiram que a crise tinha acabado, que o conto de fadas tinha terminado? Que o príncipe e a princesa viveriam felizes para sempre?"
  },
  AvgDialog_71992_Content_37 = {
    Text = "Ridículo! Hilário!"
  },
  AvgDialog_71992_Content_38 = {
    Text = "Vocês não fazem ideia do que eu sei! Tudo, tudo isso é meramente—"
  },
  AvgDialog_71992_Content_39 = {
    Text = "Você desperta assustado do torpor após ler o relatório do laboratório, percebendo que está encharcado de suor frio."
  },
  AvgDialog_71992_Content_4 = {
    Text = "Em segundo lugar, embora eu tenha encontrado o método que usei para saltar para a sua dimensão naquela época, ele não é aplicável a você."
  },
  AvgDialog_71992_Content_40 = {
    Text = "A arrogante e imponente Melt-Doll que está diante de você já foi apenas uma pesquisadora cautelosa chamada Doll na cidade de Misag."
  },
  AvgDialog_71992_Content_41 = {
    Text = "Mas naquela linha temporal, ela percebeu a verdade cruel por trás da Fusão antes da Doll do seu mundo."
  },
  AvgDialog_71992_Content_42 = {
    Text = "Seu nobre sacrifício não pode garantir paz duradoura para o mundo."
  },
  AvgDialog_71992_Content_43 = {
    Text = "Sua batalha ainda não acabou; você deve fazer Misaq e Ramona tomarem consciência disso—"
  },
  AvgDialog_71992_Content_44 = {
    Text = "Você deve voltar."
  },
  AvgDialog_71992_Content_45 = {
    Text = "No dia da despedida, uma chuva fina cai."
  },
  AvgDialog_71992_Content_46 = {
    Text = "Parece que os momentos marcantes da sua vida são sempre acompanhados por uma chuva fina."
  },
  AvgDialog_71992_Content_47 = {
    Text = "Seja no dia em que você abriu os olhos em Akutê, no dia da Cerimônia de Concessão de Chaves, ou no dia em que decidiu se tornar · um dos Guardião da Porta..."
  },
  AvgDialog_71992_Content_48 = {
    Text = "Em toda noite calma e chuvosa, você não consegue evitar se preocupar se um novo ponto de virada na sua vida chegará de repente."
  },
  AvgDialog_71992_Content_49 = {
    Text = "Você se lembrou da despedida com Fusão - Boneca."
  },
  AvgDialog_71992_Content_5 = {
    Text = "Em termos simples: a transferência de consciência requer similaridade física quase perfeita. No seu mundo, um corpo que corresponda à sua ressonância única já não existe."
  },
  AvgDialog_71992_Content_50 = {
    Text = "Eu ficarei no laboratório. A cessação não é a resposta; um dia posso repetir a mesma loucura."
  },
  AvgDialog_71992_Content_51 = {
    Text = "Mas, antes de alcançar a verdade absoluta, mesmo ao me aproximar da contaminação da Destruição, preciso arriscar e continuar minha Pesquisa."
  },
  AvgDialog_71992_Content_52 = {
    Text = "Agora sim parece a Boneca que eu conheço...\nNão, ainda é um pouco diferente."
  },
  AvgDialog_71992_Content_53 = {
    Text = "Vocês são movidos pela mesma obsessão, apesar de parecerem completamente diferentes na superfície."
  },
  AvgDialog_71992_Content_54 = {
    Text = "Mas pelo menos, Doll não está tão agitada e perigosa como antes."
  },
  AvgDialog_71992_Content_55 = {
    Text = "Doll pediu-me para lhe dar este broche. Deixe-me prendê-lo em si."
  },
  AvgDialog_71992_Content_56 = {
    Text = "Winkle prende um broche no seu peito."
  },
  AvgDialog_71992_Content_57 = {
    Text = "Winkle... Ao longo desta jornada, você me ajudou tanto. E eu ainda não tive a chance de agradecer a você."
  },
  AvgDialog_71992_Content_58 = {
    Text = "Obrigado, Búzio. Obrigado por se tornar meu primeiro amigo aqui."
  },
  AvgDialog_71992_Content_59 = {
    Text = "Não há necessidade de ser tão educado. Ouvi muito sobre você pela Boneca. Mesmo quando não pude falar com você, você já conheceu outra versão de mim, não é?"
  },
  AvgDialog_71992_Content_6 = {
    Text = "Outra forma é através da cuba cerebral e reconstrução corporal, mas isso requer os dados de frequência da sua consciência, e o relatório experimental correspondente foi perdido."
  },
  AvgDialog_71992_Content_60 = {
    Text = "Embora eu ainda sinta muito medo...\nmas uma voz me diz, dentro da minha mente, que você trará luz para mim e para este mundo."
  },
  AvgDialog_71992_Content_61 = {
    Text = "Olhe para lá, estão todos aqui para se despedir de você."
  },
  AvgDialog_71992_Content_62 = {Text = "..."},
  AvgDialog_71992_Content_63 = {
    Text = "Não, eu não vou agradecer aquele cara! \nFui eu quem o tirei do monte de entulho, eu salvei a vida de {Male=ele,Female=ela}!"
  },
  AvgDialog_71992_Content_64 = {
    Text = "Comporte-se, Jenkin."
  },
  AvgDialog_71992_Content_65 = {
    Text = "Obrigado por ajudar minha irmã... Lamento, mas eu e o Jenkins não temos muitos \"pertences\". \nEsta fita, então, será minha dádiva para você como lembrança."
  },
  AvgDialog_71992_Content_66 = {
    Text = "Ela amarra uma fita de seda carmesim ao redor do seu pulso."
  },
  AvgDialog_71992_Content_67 = {Text = "Irmã!"},
  AvgDialog_71992_Content_68 = {
    Text = "Eu não posso aceitar..."
  },
  AvgDialog_71992_Content_69 = {
    Text = "Por favor, aceite. Você e a Sra. Doll doaram muita Prata ao Santuário, o suficiente para sustentar o Bispo Salvador por muito tempo. Isto é o mínimo que podemos fazer para demonstrar a nossa gratidão."
  },
  AvgDialog_71992_Content_7 = {
    Text = "Existe alguma forma de recuperá-lo?"
  },
  AvgDialog_71992_Content_70 = {
    Text = "Eu consigo ver o brilho da sua alma, como uma chama pálida e tremeluzente, ainda instável, mas luminosa e calorosa."
  },
  AvgDialog_71992_Content_71 = {
    Text = "Bispo Salvador... Se eu encontrar uma forma de resolver a crise, correrei ao Santuário na primeira oportunidade."
  },
  AvgDialog_71992_Content_72 = {
    Text = "Eu confio em si, Mensageiro Pálido. Um dia, você trará redenção e esperança àqueles que sofrem no Santuário."
  },
  AvgDialog_71992_Content_73 = {Text = "..."},
  AvgDialog_71992_Content_74 = {
    Text = "Despedindo-se dos outros, você respirou profundamente o ar fresco e chuvoso. \nNum canto da rua, uma figura que surgiu repentinamente no canto do seu olho chamou sua atenção."
  },
  AvgDialog_71992_Content_75 = {Text = "!"},
  AvgDialog_71992_Content_76 = {
    Text = "Espere! Com licença, senhor—aguarde um momento!"
  },
  AvgDialog_71992_Content_77 = {
    Text = "O manto do homem loiro esvoaça. Ele parece estar a fugir da sua perseguição e acelera o passo."
  },
  AvgDialog_71992_Content_78 = {
    Text = "...William, é você? ...William!"
  },
  AvgDialog_71992_Content_79 = {
    Text = "Você não tem tempo para pensar muito; começa a correr a toda velocidade, e os bairros passam desfocados pela sua visão."
  },
  AvgDialog_71992_Content_8 = {
    Text = "Sim, mas com riscos igualmente inaceitáveis — eu preciso arriscar sintonizar meu próprio pensamento com o da versão completa de Fusão·Dor."
  },
  AvgDialog_71992_Content_80 = {Text = "..."},
  AvgDialog_71992_Content_81 = {Text = "..."},
  AvgDialog_71992_Content_82 = {
    Text = "Huff... Huff..."
  },
  AvgDialog_71992_Content_83 = {
    Text = "Os seus pulmões ardem, o ar insuficiente não consegue suprir a demanda hipóxica. Você ofega por ar, e a onda de sangue começa a restaurar a clareza cognitiva."
  },
  AvgDialog_71992_Content_84 = {
    Text = "...Quando é que o céu escureceu?"
  },
  AvgDialog_71992_Content_85 = {
    Text = "Rua Southwark... Nº 44..."
  },
  AvgDialog_71992_Content_86 = {
    Text = "Na última vez, neste momento, seu parceiro mais importante estava ao seu lado."
  },
  AvgDialog_71992_Content_87 = {
    Text = "Southwark Street fica na Zona Oeste. Parece que, desta vez, teremos a oportunidade de testemunhar o renomado Investigador William, o companheiro mais velho, em ação."
  },
  AvgDialog_71992_Content_88 = {
    Text = "Até o <Italic:William, o companheiro mais velho> tem de ir, hein..."
  },
  AvgDialog_71992_Content_89 = {
    Text = "Mas agora, não há ninguém ao seu lado."
  },
  AvgDialog_71992_Content_9 = {
    Text = "Em outras palavras, eu me tornarei aquele Corpo Desperto da Origem, sua inimiga."
  },
  AvgDialog_71992_Content_90 = {
    Text = "É o que é preciso para enfrentar a Fusão."
  },
  AvgDialog_71992_Content_91 = {
    Text = "Guardião, você é especial. Por isso, não pode parar aqui."
  },
  AvgDialog_71992_Content_92 = {
    Text = "Temos de fazer algo. Salvar pessoas. Trazer mudança.\nMas, mesmo que nada seja alcançado no final..."
  },
  AvgDialog_71992_Content_93 = {
    Text = "Antes da chegada daquela noite escura em que tudo é esquecido, que a sua memória seja a testemunha final de tudo o que aconteceu."
  },
  AvgDialog_71992_Content_94 = {
    Text = [[
Eu vou conseguir.
Ramona, espere pelo meu retorno.]]
  },
  AvgDialog_71992_Content_95 = {
    Text = "Tendo extraído força das suas memórias, você está agora pronto para enfrentar esta jornada solitária."
  },
  AvgDialog_71992_Content_96 = {
    Text = "Hora de ir."
  },
  AvgDialog_71992_Content_97 = {
    Text = "Que a Chave de prata ilumine o meu caminho."
  },
  AvgDialog_71992_Content_98 = {
    Text = "Beep, beep—"
  },
  AvgDialog_71992_Content_99 = {
    Text = "O broche que Dol Melt fabricou e que Winkell prendeu no seu peito começa a soar repentinamente."
  },
  AvgDialog_71993_Content_1 = {
    Text = "Homem vazio"
  },
  AvgDialog_71993_Content_10 = {
    Text = "......Pai Deus, por favor, conceda paz e libertação àqueles que pereceram e console suas almas sofredoras."
  },
  AvgDialog_71993_Content_11 = {
    Text = "Que sua mão curadora desça sobre os que sofrem, que a luz de sua existência dissipe o medo e a escuridão que afligem nossas almas."
  },
  AvgDialog_71993_Content_12 = {
    Text = "Cofi, cofi! —"
  },
  AvgDialog_71993_Content_13 = {
    Text = "Seu corpo está quase transparente."
  },
  AvgDialog_71993_Content_14 = {
    Text = "Juliette... O Pai Deus perdoará todos os pecados, mas até que você mostre até mesmo uma pista de arrependimento por realizar o ritual herético, aparecer na Igreja pode não ser apropriado."
  },
  AvgDialog_71993_Content_15 = {
    Text = "Você, por fim, não conseguiu ver a realidade? Seja \"A bênção\" ou \"Abrigo\", tudo o que você faz é apenas queimar a si mesmo."
  },
  AvgDialog_71993_Content_16 = {
    Text = "O seu pai divino não pode restaurar a sua visão nem curar os males em seu corpo."
  },
  AvgDialog_71993_Content_17 = {
    Text = "Continue assim e você cairá antes mesmo daqueles que agora parecem fracos na igreja."
  },
  AvgDialog_71993_Content_18 = {
    Text = "Venha comigo e saia deste lugar; eu encontrarei uma maneira de te curar."
  },
  AvgDialog_71993_Content_19 = {
    Text = "Se eu deixar a igreja, todos os pacientes aqui serão devorados. O divino não ficará de braços cruzados enquanto seu povo sofre tal calamidade."
  },
  AvgDialog_71993_Content_2 = {
    Text = "Em frente à Igreja da Redenção"
  },
  AvgDialog_71993_Content_20 = {
    Text = "Mesmo que você lute por mais dez dias ou meio mês, uma vez que seu espírito falhe, eles ainda terão que encontrar seu próprio caminho para fora."
  },
  AvgDialog_71993_Content_21 = {
    Text = "E mais da metade deles... tenho medo de que não consigam nem sair de seus quartos."
  },
  AvgDialog_71993_Content_22 = {
    Text = "O olhar fervoroso de Juliette estava fixo em Salvador; vendo-o acariciar silenciosamente seu manto, ela revelou um sorriso que parecia falso devido ao seu brilho excessivo."
  },
  AvgDialog_71993_Content_23 = {
    Text = "Não seria uma má ideia designar este lugar como um novo campo de mortos. Ser sepultado nos braços do divino poderia, de fato, ser visto como um retorno piedoso, certo?"
  },
  AvgDialog_71993_Content_24 = {
    Text = "Abra os olhos e dê uma olhada; toda a cidade já caiu, e o que você fez é meramente uma gota no oceano."
  },
  AvgDialog_71993_Content_25 = {
    Text = "O Pai concede a cada pessoa oportunidades iguais; quanto mais tempo vivem, maiores são as chances de encontrar um salvador."
  },
  AvgDialog_71993_Content_26 = {
    Text = "A mensageira pálida ainda não chegou ao mundo, então ainda há uma luz de esperança para a redenção."
  },
  AvgDialog_71993_Content_27 = {
    Text = "Não seja ridículo, estimado Bispo! A chamada <ItalicYellow:\"Palavra de Deus\"> não passa de mentiras absurdas!"
  },
  AvgDialog_71993_Content_28 = {
    Text = "O fim chegou, e ninguém pode salvar este mundo!"
  },
  AvgDialog_71993_Content_29 = {
    Text = "Se você permanecer teimoso em suas ilusões, não terei escolha a não ser tomar medidas drásticas."
  },
  AvgDialog_71993_Content_3 = {
    Text = "Você tem certeza de que este é o abrigo que você está procurando?"
  },
  AvgDialog_71993_Content_30 = {
    Text = "Das vitrais da igreja, debaixo dos bancos, atrás das portas, várias figuras altas de crentes que iluminam o templo aparecem silenciosamente."
  },
  AvgDialog_71993_Content_31 = {
    Text = "Bispo Salvador!!"
  },
  AvgDialog_71993_Content_32 = {
    Text = "A figura do jovem irrompeu pelas portas do Santuário, seguida por três sombras alongadas pela luz do sol, que avançavam lentamente enquanto observavam o ambiente."
  },
  AvgDialog_71993_Content_33 = {
    Text = "Naquele confronto, seu olhar atravessou a multidão dos fiéis com lanternas e encontrou o de Salvador.\nA luz da porta dourou seu rosto com um brilho suave e sagrado, e você sentiu que o olhar sob suas bandagens estava se encontrando com o seu."
  },
  AvgDialog_71993_Content_34 = {
    Text = "Ele abaixou a cabeça, o canto de seus lábios se curvando em um arco quase imperceptível. Ele levantou a mão para tocar a posição de seu coração, e uma profunda oração carregava um toque de compaixão e calor."
  },
  AvgDialog_71993_Content_35 = {
    Text = "\"Escuridão sem limites descerá sobre o mundo, a alma que é pálida e calorosa é a emissária da esperança, {Male=he,Female=she} acenderá a chama branca para iluminar o caminho adiante.\""
  },
  AvgDialog_71993_Content_36 = {
    Text = "Eu senti a temperatura da sua alma... Mensageiro Pálido."
  },
  AvgDialog_71993_Content_37 = {Text = "..."},
  AvgDialog_71993_Content_38 = {
    Text = "Eu pensei que viemos aqui buscar ajuda. Você não vai me fazer desempenhar o papel de um cavaleiro de armadura brilhante, vai?"
  },
  AvgDialog_71993_Content_39 = {
    Text = "Juliette..."
  },
  AvgDialog_71993_Content_4 = {
    Text = "A situação aqui é muito semelhante à da torre do sino do <Orfanato>, se não exatamente a mesma..."
  },
  AvgDialog_71993_Content_40 = {
    Text = "Oh? Você está familiarizado comigo?"
  },
  AvgDialog_71993_Content_41 = {
    Text = "Eu não vi seu rosto. Mas parece que não há tempo para nos sentarmos e nos apresentarmos aqui."
  },
  AvgDialog_71993_Content_42 = {
    Text = "Não... ela não é alguém com quem negociar... Prepare-se para a batalha."
  },
  AvgDialog_71993_Content_43 = {
    Text = "Parece que você conhece bem meus modos. Nesse caso, estou bastante interessado em perguntar sobre a fonte de suas informações."
  },
  AvgDialog_71993_Content_5 = {
    Text = "Um grande número de anomalias de Dissolução cercou toda a igreja..."
  },
  AvgDialog_71993_Content_6 = {
    Text = "Espere um momento, o que está à frente é..."
  },
  AvgDialog_71993_Content_7 = {
    Text = "Saia do caminho! Não bloqueie o caminho do cavaleiro!"
  },
  AvgDialog_71993_Content_8 = {
    Text = "A pequena figura abriu um escudo negro e se aproximou de você."
  },
  AvgDialog_71993_Content_9 = {
    Text = "Você! São vocês sobreviventes? Rápido, entrem!"
  },
  AvgDialog_71994_Content_1 = {
    Text = "O espaço da consciência colapsou completamente, e a poeira da ilusão caiu como cinzas. O que apareceu diante de você ainda era o laboratório original."
  },
  AvgDialog_71994_Content_2 = {
    Text = "Por que não aceitar? Poder perecer nas fendas da Dimensão, nunca tendo que suportar o olhar de \"Ele.\""
  },
  AvgDialog_71994_Content_3 = {
    Text = "Que honra, que bênção isso é!"
  },
  AvgDialog_71994_Content_4 = {
    Text = "Infelizmente, infelizmente, agora só posso assumir as rédeas... para esta cidade fria que foi obliterada uma vez..."
  },
  AvgDialog_71994_Content_5 = {
    Text = "Se tornar seu lugar final de descanso!"
  },
  AvgDialog_71995_Content_1 = {
    Text = "O espaço caótico, acompanhado por contornos distorcidos, engoliu completamente o laboratório num instante. Luzes e sombras descontroladas se expandem diante de vocês, e um enxame de criaturas indistinguíveis, submersas na escuridão, os cerca."
  },
  AvgDialog_71995_Content_2 = {
    Text = "Bem-vindo ao meu campo de experimentos, ao meu açougue."
  },
  AvgDialog_71995_Content_3 = {
    Text = "Bem-vindo ao meu campo experimental, meu matadouro."
  },
  AvgDialog_71995_Content_4 = {
    Text = "Vá em frente, crianças queridas. Ensinem uma lição a esses tolos ingratos."
  },
  AvgDialog_71996_Content_10 = {
    Text = "Sem dúvida, é o meu laboratório."
  },
  AvgDialog_71996_Content_11 = {
    Text = "Você se lembra? Eu te disse uma vez que poderíamos tomar um \"atalho\"."
  },
  AvgDialog_71996_Content_12 = {
    Text = "Aquele atalho é \"roubo\"."
  },
  AvgDialog_71996_Content_13 = {Text = "Roubar?"},
  AvgDialog_71996_Content_14 = {
    Text = "Não sei qual foi a escala da explosão que você causou, mas tenho o hábito de armazenar cuidadosamente os resultados das pesquisas importantes."
  },
  AvgDialog_71996_Content_15 = {
    Text = "Eu não sei a escala da explosão que você causou, mas eu tenho o hábito de armazenar cuidadosamente os resultados importantes de pesquisa."
  },
  AvgDialog_71996_Content_16 = {
    Text = "Enquanto a habilidade deste ratinho de escavar através das paredes se torne incontrolável, eu posso escavar registros das ruínas, reduzindo significativamente o tempo necessário para minha pesquisa subsequente."
  },
  AvgDialog_71996_Content_17 = {
    Text = "Certo, chega de conversa. Limpe o caminho para as ruínas do laboratório."
  },
  AvgDialog_71996_Content_2 = {
    Text = "Ei, você do Distrito Oeste, me tirando dos meus doces sonhos tão cedo pela manhã—onde você está me levando?"
  },
  AvgDialog_71996_Content_3 = {
    Text = "Estou dormindo profundamente, sonhando em me transformar em um ratinho, caminhando em uma ponte estreita, cercado pelo doce aroma de gordura, e logo meu nariz tocará o queijo mais delicioso—"
  },
  AvgDialog_71996_Content_4 = {
    Text = "Com um clang, você me acordou batendo com aquele travesseiro."
  },
  AvgDialog_71996_Content_5 = {
    Text = "Felizmente, eu te acordei. O que você sonhou é uma das armadilhas para camundongos mais comuns e altamente eficientes."
  },
  AvgDialog_71996_Content_6 = {
    Text = "Abaixo da ponte de tronco há um tanque de água com mais de um metro de altura, o aroma que você sente está espalhado no recipiente transparente e na própria ponte de tronco sob seus pés, e assim que você pisar, escorregará e cairá no abismo sem fim."
  },
  AvgDialog_71996_Content_7 = {
    Text = "Para ser um rato livre e independente, você precisa ser ainda mais esperto."
  },
  AvgDialog_71996_Content_8 = {
    Text = "Se você quer ser um rato despreocupado, precisa ser um pouco mais esperto."
  },
  AvgDialog_71996_Content_9 = {
    Text = "A boneca, qual é o nosso destino para esta viagem...?"
  },
  AvgDialog_71997_Content_1 = {
    Text = "No instante em que o corpo corroído da mutação desaparece com um lamento, os quatro que lutaram ao seu lado há pouco se viram para você com sorrisos, e então suas figuras gradualmente se desvanecem."
  },
  AvgDialog_71997_Content_10 = {
    Text = "Pode ser possível, mas a conexão através de dimensões seria suficiente para sobrecarregar este seu corpo. Em momentos não essenciais, não recomendo que você faça isso.\n."
  },
  AvgDialog_71997_Content_11 = {
    Text = "Você tenta se concentrar e lembrar novamente, mas antes que qualquer forma se concretize em sua mente, os engrenagens do pensamento já falham e param. \nSuas pálpebras pesam como chumbo, e uma sensação de sufocamento envolve seu coração como uma névoa espessa."
  },
  AvgDialog_71997_Content_12 = {
    Text = "Vá comigo de volta ao laboratório, vou tratar dos seus ferimentos.\nSe a Boneca descobrir, direi que foi tudo culpa minha."
  },
  AvgDialog_71997_Content_13 = {
    Text = "Ela, Boneca... Embora eu possa sentir que, em essência, ela é uma pessoa pura, e sua tecnologia de transferência é também muito sofisticada... Muito mais habilidosa do que a maioria das pessoas neste planeta."
  },
  AvgDialog_71997_Content_14 = {
    Text = "Boneca, mesmo assim, posso sentir que ela é fundamentalmente uma pessoa pura, e sua técnica de teletransporte é bastante exquisita... muito superior à maioria das pessoas neste planeta."
  },
  AvgDialog_71997_Content_15 = {
    Text = "Mas discutir com Wenkel sobre os méritos ou deméritos da fusão de Dore, neste momento, é algo sem sentido. O mais importante é compreender o que realmente ocorreu neste mundo e como retornar ao nosso mundo original."
  },
  AvgDialog_71997_Content_16 = {
    Text = "Vamos... voltar? Lá fora realmente não é seguro..."
  },
  AvgDialog_71997_Content_17 = {
    Text = "Vamos... voltar? Está realmente inseguro lá fora..."
  },
  AvgDialog_71997_Content_18 = {
    Text = "A mão puxando suas roupas estava quietamente exercendo força."
  },
  AvgDialog_71997_Content_19 = {
    Text = "Você olhou para o sol fraco no céu distante, vagamente delineado em forma circular através da névoa, assemelhando-se a pupilas expostas e murchas."
  },
  AvgDialog_71997_Content_2 = {
    Text = "No instante em que o corpo corroído desaparece com um lamento angustiado, os quatro que estavam ao seu lado na batalha há pouco tempo olham para você com sorrisos e, em seguida, suas figuras gradualmente desvanecem."
  },
  AvgDialog_71997_Content_20 = {
    Text = "Estou voltando com você. Tenho algumas perguntas para fazer à Boneca."
  },
  AvgDialog_71997_Content_3 = {
    Text = "No momento seguinte, o rosto ansioso de Winkle estava bem na sua frente."
  },
  AvgDialog_71997_Content_4 = {
    Text = "Ha, ha, estou morto de cansaço."
  },
  AvgDialog_71997_Content_5 = {
    Text = "Não, não corra por aí... É muito perigoso lá fora."
  },
  AvgDialog_71997_Content_6 = {
    Text = "Você olha ao redor, confirmando que a figura desapareceu completamente. O cansaço da batalha é ainda pior do que antes."
  },
  AvgDialog_71997_Content_7 = {Text = "Eles..."},
  AvgDialog_71997_Content_8 = {
    Text = "É uma projeção do seu espaço de consciência. No entanto, de acordo com a Boneca, seu espaço de consciência já contém todos os mundos dimensionais."
  },
  AvgDialog_71997_Content_9 = {
    Text = "Seremos capazes de vê-los novamente?"
  },
  AvgDialog_71998_Content_2 = {
    Text = "O chão treme e o céu balança; frascos de vidro e tubos de ensaio rolam da mesa de experimentos ao seu lado, criando uma névoa de cores psicodélicas no chão."
  },
  AvgDialog_71998_Content_3 = {
    Text = "Então a mesa de experimentos e o suporte de reagentes desmoronaram em sucessão. Até o pêndulo e os enfeites pendurados na parede balançaram precariamente."
  },
  AvgDialog_71998_Content_4 = {
    Text = "Um terremoto?!"
  },
  AvgDialog_71998_Content_5 = {
    Text = "Esta fortaleza não consegue aguentar mais?"
  },
  AvgDialog_71998_Content_6 = {
    Text = "Parece que vou ser enterrado aqui com o filhote de Mythag. Você está feliz? Abane sua cauda; esta é uma rara honra para você."
  },
  AvgDialog_71998_Content_7 = {
    Text = "Antes que você respondesse, o mundo mergulhou em um abismo de escuridão total."
  },
  AvgDialog_71999_Content_1 = {
    Text = "Caminho não tomado"
  },
  AvgDialog_71999_Content_10 = {
    Text = "Depende do que tens andado a fazer durante este tempo."
  },
  AvgDialog_71999_Content_11 = {
    Text = "O que estou a fazer? Porquê perguntar? Claro que estou a continuar a grande obra minha—tua—a grande catálise do fim do mundo!"
  },
  AvgDialog_71999_Content_12 = {
    Text = "Vamos, querido, compartilhe a alegria comigo!\nEnquanto você esteve ausente, já enviei o fim para seis dimensões inteiras de Kadath!\n\n!"
  },
  AvgDialog_71999_Content_13 = {
    Text = "Tu e Doll trocam um olhar."
  },
  AvgDialog_71999_Content_14 = {
    Text = "Parece que a amizade está fora de questão."
  },
  AvgDialog_71999_Content_15 = {
    Text = "Lamentável! Oh, que lamentável! Nem eu consigo compreender o meu próprio desejo agora!"
  },
  AvgDialog_71999_Content_16 = {
    Text = "Há poucos momentos, ela ainda estava se apresentando apaixonadamente no palco da ópera quando de repente parou. Seu olhar ardente parecia atravessar você e Boneca: Inferno ao seu lado."
  },
  AvgDialog_71999_Content_17 = {
    Text = "Suponho que te esqueceste de tudo sobre aquela tablete, não foi?"
  },
  AvgDialog_71999_Content_18 = {
    Text = "Vocês dois respondem à pergunta arrogante dela com silêncio."
  },
  AvgDialog_71999_Content_19 = {
    Text = "Claro, claro! Perfeito! Vamos considerar isto um ensaio para a destruição iminente, a destruição no <YellowItalic:Inferno>!"
  },
  AvgDialog_71999_Content_2 = {
    Text = "O mecanismo de reinício dos corpos sobressalentes de \"mim\" é simples·um deles perde contacto com o cérebro central por mais de 24 horas, o próximo corpo de reserva ativa-se automaticamente."
  },
  AvgDialog_71999_Content_20 = {
    Text = "Sabiam? Há um desejo ardente dentro de mim."
  },
  AvgDialog_71999_Content_21 = {
    Text = "Anseio por transmitir tudo sobre a tablete ao mundo. Anseio por fazê-los perceber a total absurdidade daquilo que buscam e perseguem."
  },
  AvgDialog_71999_Content_22 = {
    Text = "Ninguém sabe por que têm tudo, nem dão atenção ao destino fadado do mundo."
  },
  AvgDialog_71999_Content_23 = {
    Text = "A destruição do mundo é iminente. A existência deles será devorada pela escuridão, mas os medíocres permanecem cegos a tudo isso!"
  },
  AvgDialog_71999_Content_24 = {
    Text = "Mas eu vi! EU VI!"
  },
  AvgDialog_71999_Content_25 = {
    Text = "Ela fica cada vez mais frenética, suas grossas pinças esmagando o chão. O som arrepiante delas perfurando o piso de madeira faz um calafrio percorrer sua espinha."
  },
  AvgDialog_71999_Content_26 = {
    Text = "Portanto, na forma da morte, concedo a mesma absurdidade aos medíocres entorpecidos, concedendo-lhes o privilégio do despertar."
  },
  AvgDialog_71999_Content_27 = {
    Text = "Concedo-lhes armaduras fortes o suficiente para resistir ao fogo e à eletricidade, e então perfuro seus peitos com minhas pinças afiadas."
  },
  AvgDialog_71999_Content_28 = {
    Text = "Distribuo aleatoriamente milhares de máquinas de mineração sísmica a transeuntes. Pessoas gananciosas lutam pelos campos, e os terremotos causados pela ressonância surpreendentemente superam aqueles que eu mesma provoco."
  },
  AvgDialog_71999_Content_29 = {
    Text = "Coloco vocês, tolos latidores, em cubas cerebrais, forçando-os a sentar e testemunhar a chegada dos pesadelos."
  },
  AvgDialog_71999_Content_3 = {
    Text = "Portanto, após o acidente no laboratório, entrei em coma e o novo corpo cibernético B-68 já foi ativado.\nE este corpo, que perdeu parte de suas memórias, era originalmente um produto descartado que deveria ser enviado para o lixo.\n\n."
  },
  AvgDialog_71999_Content_30 = {
    Text = "É só isso? Essa é a \"minha\" escolha?"
  },
  AvgDialog_71999_Content_31 = {
    Text = "Que fraqueza. Pensei que uma ligação mais forte com a minha forma de Origem levaria a maior sabedoria, mas vejo que a armadilha da ciência te guiou a um beco sem saída científico."
  },
  AvgDialog_71999_Content_32 = {
    Text = "Sabe o valor da armadura biológica? Nem fogo nem eletricidade podem penetrá-la. Poderíamos vesti-la para adentrar a camada de magma e explorar os mistérios abaixo."
  },
  AvgDialog_71999_Content_33 = {
    Text = "As máquinas de mineração sísmica... Foram feitas para penetrar estratos e escavar Prata através de vibrações de alta velocidade."
  },
  AvgDialog_71999_Content_34 = {
    Text = "Quanto às cubas cerebrais... Foram projetadas para preservar cérebros inestimáveis e o conhecimento que contêm, não para a coleta imprudente e arbitrária de lixo."
  },
  AvgDialog_71999_Content_35 = {
    Text = "E você os desperdiça em passatempos sem sentido por diversão. Você é tão ignorante e esbanjadora quanto aquele N."
  },
  AvgDialog_71999_Content_36 = {
    Text = "Você ficou presa em outro tipo de loucura por tempo demais, outra eu."
  },
  AvgDialog_71999_Content_37 = {
    Text = "A Luz da humanidade sempre abriu caminho para o futuro através da exploração, mas você sela arbitrariamente todas as possibilidades e esperanças."
  },
  AvgDialog_71999_Content_38 = {
    Text = "Não há possibilidade, e não há esperança!"
  },
  AvgDialog_71999_Content_39 = {
    Text = "Todas as respostas estão afogadas na escuridão eterna, e todas as dimensões, semelhantes ou diferentes, levarão apenas a um único resultado!"
  },
  AvgDialog_71999_Content_4 = {
    Text = "Por outras palavras, a \"Fusão · Dor\" diante de nós é a versão mais completa de \"mim.\""
  },
  AvgDialog_71999_Content_40 = {
    Text = "%player%. Esperança é apenas um veneno que traz mais dor. Apenas através da destruição completa e rápida todos podem alcançar o verdadeiro alívio."
  },
  AvgDialog_71999_Content_41 = {
    Text = "A pinça reluzente é erguida bem alto, pronta para perfurar seu crânio no próximo instante."
  },
  AvgDialog_71999_Content_42 = {
    Text = "Já que você não está disposto a abandonar essa esperança grosseira..."
  },
  AvgDialog_71999_Content_43 = {
    Text = "Então prepare-se para abraçar a morte perfeita e eficiente que eu lhe concedo!"
  },
  AvgDialog_71999_Content_5 = {
    Text = "És muito esperta, tal como eu, N.º B-67."
  },
  AvgDialog_71999_Content_6 = {
    Text = "Então, um defeito descartado regressou a este laboratório com a minha cachorrinha fugitiva. Não vieste para conversar, pois não?"
  },
  AvgDialog_71999_Content_7 = {
    Text = "Se eu reivindicar prioridade porque o meu número é inferior, tu definitivamente não vais admitir que este laboratório me pertence."
  },
  AvgDialog_71999_Content_8 = {
    Text = "Mas não é impossível chegarmos a um acordo amigável."
  },
  AvgDialog_71999_Content_9 = {
    Text = "Então, você quer se juntar a mim?"
  },
  AvgDialog_72000_Content_1 = {
    Text = "Você realmente é um problema; como pode recorrer à violência sem dizer uma palavra?!"
  },
  AvgDialog_72000_Content_10 = {
    Text = "Ela, assim como sua irmã, foi levada pelo jovem mestre rico com a boneca peculiar para buscar tratamento."
  },
  AvgDialog_72000_Content_11 = {
    Text = "Eu também avisei a senhorita Clementine, mas a senhorita Clementine disse que o jovem mestre a havia enviado para algum sanatório de alto padrão e ela não poderia voltar por enquanto."
  },
  AvgDialog_72000_Content_12 = {
    Text = "Então... Senhorita Sarah, e Diana?"
  },
  AvgDialog_72000_Content_13 = {
    Text = "Eu não sei. A casa de pobres está cheia de monstros, e ninguém se atreve a se aproximar."
  },
  AvgDialog_72000_Content_14 = {
    Text = "Sim, eu percebi que há muito mais monstros no Distrito Leste do que no Distrito Oeste quando a Senhora Clementine me trouxe de volta do Distrito Oeste..."
  },
  AvgDialog_72000_Content_15 = {
    Text = "Ainda mais no asilo."
  },
  AvgDialog_72000_Content_16 = {
    Text = "As figuras dos dois aparecem diante de seus olhos. Sarah, curvada com um sorriso bajulador; Aigis, tímida e incapaz de expressar seus sentimentos."
  },
  AvgDialog_72000_Content_17 = {
    Text = "Amanhã de manhã, vou procurar a casa dos pobres."
  },
  AvgDialog_72000_Content_2 = {
    Text = "Mason pode sentir que vocês dois são boas pessoas... Poderiam parar de dificultar as coisas um para o outro?"
  },
  AvgDialog_72000_Content_3 = {
    Text = "Não, parece que estes dois não vão me permitir ficar aqui..."
  },
  AvgDialog_72000_Content_4 = {
    Text = "Visto que é assim, é melhor eu sair e ficar na moita por enquanto."
  },
  AvgDialog_72000_Content_5 = {
    Text = "Embora ela tenha falado sobre sair, de repente ela se inclinou perto de você e sussurrou suavemente."
  },
  AvgDialog_72000_Content_6 = {
    Text = "Nos encontraremos novamente, Olho Cego."
  },
  AvgDialog_72000_Content_7 = {
    Text = "(Já que a situação da Associação dos Escultores e de Rogers permanece a mesma de antes, então...)"
  },
  AvgDialog_72000_Content_8 = {
    Text = "Jenkin, você sabe onde está Aigis?"
  },
  AvgDialog_72000_Content_9 = {
    Text = "Você ainda se lembra de Aigis?"
  },
  AvgDialog_72001_Content_1 = {
    Text = "(Atordoado)"
  },
  AvgDialog_72001_Content_11 = {
    Text = "Você empurrou a porta aberta."
  },
  AvgDialog_72001_Content_12 = {
    Text = "O que aparece diante de você é um porão familiar, mas sem pessoas de doce, escultores ou mesas de experimento."
  },
  AvgDialog_72001_Content_13 = {
    Text = "Há apenas uma mulher desleixada e emaciada."
  },
  AvgDialog_72001_Content_14 = {Text = "...Quem..."},
  AvgDialog_72001_Content_15 = {
    Text = "Voz rouca e fraca, como se estivesse suportando dores intensas. Dedos magros e enrugados se arrastam pelo chão, puxando o corpo sem forças em direção a vocês."
  },
  AvgDialog_72001_Content_16 = {
    Text = "É... humano...?"
  },
  AvgDialog_72001_Content_17 = {Text = "Sarah!"},
  AvgDialog_72001_Content_18 = {
    Text = "Beba devagar. Há muita água, então não se preocupe."
  },
  AvgDialog_72001_Content_19 = {
    Text = "Huff... Huff..."
  },
  AvgDialog_72001_Content_2 = {
    Text = "Você derrubou todos aqueles monstros?"
  },
  AvgDialog_72001_Content_20 = {
    Text = "Há quanto tempo você está se escondendo no porão?"
  },
  AvgDialog_72001_Content_21 = {
    Text = "Perdi a conta... De qualquer forma, deve ser mais de vinte dias."
  },
  AvgDialog_72001_Content_22 = {
    Text = "Às vezes, eu ouço um estranho murmurinho, e minha cabeça dói insuportavelmente, como se fosse se abrir de dentro..."
  },
  AvgDialog_72001_Content_23 = {
    Text = "Quando eu acordei, não fazia ideia de quanto tempo estive inconsciente..."
  },
  AvgDialog_72001_Content_24 = {
    Text = "Sem comida, sem água... Tenho a sensação de que vou morrer a qualquer momento. \nMas, sempre que penso nas crianças que ainda estão me esperando..."
  },
  AvgDialog_72001_Content_25 = {
    Text = "Você sobreviveu sem comer ou beber por mais de vinte dias; você realmente acha que foi o amor pelas crianças que te manteve vivo?"
  },
  AvgDialog_72001_Content_26 = {
    Text = "Por que você está sendo tão sarcástico!"
  },
  AvgDialog_72001_Content_27 = {
    Text = "Para ser franco, amigos, vocês devem perceber..."
  },
  AvgDialog_72001_Content_28 = {
    Text = "Esta Senhora Sarah diante de você não é mais uma humana comum... Ela é uma Despertar meio acabado."
  },
  AvgDialog_72001_Content_29 = {
    Text = "Sim, seu índice gnóstico está oscilando constantemente e não consegue se manter acima de 21. \nO motivo ainda não foi identificado, mas é evidente que não se trata de um despertador estável."
  },
  AvgDialog_72001_Content_3 = {
    Text = "De agora em diante, você pode se mover livremente no asilo."
  },
  AvgDialog_72001_Content_30 = {
    Text = "E obviamente, seu corpo está prestes a ceder sob as vibrações da prata interna."
  },
  AvgDialog_72001_Content_31 = {
    Text = "É lamentável, mas ela provavelmente não poderá ver seus filhos novamente."
  },
  AvgDialog_72001_Content_32 = {
    Text = "O sorriso de Dol derreteu como uma pedra pesada, pressionando firmemente o peito de vocês. \nNinguém respondeu. O silêncio extraiu um vazio longo e contínuo do ar do asilo."
  },
  AvgDialog_72001_Content_4 = {
    Text = "Se qualquer pessoa ferida for encontrada lá fora, deixe-a descansar aqui."
  },
  AvgDialog_72001_Content_5 = {
    Text = "Vou dar uma olhada no porão.\nVocê primeiro não se aproxime."
  },
  AvgDialog_72001_Content_6 = {
    Text = "Você está em frente à porta do porão e respira fundo."
  },
  AvgDialog_72001_Content_7 = {
    Text = "As memórias do passado rolam e piscam diante dos seus olhos como um rolo de filme."
  },
  AvgDialog_72002_Content_1 = {Text = "Segure-a!"},
  AvgDialog_72002_Content_10 = {
    Text = "O conselho que ela deu foi sincero, genuíno e confiável."
  },
  AvgDialog_72002_Content_11 = {
    Text = "A Senhorita Juliette está realmente preocupada com o seu corpo, e você realmente não pode usar mais \"A Bênção\"!"
  },
  AvgDialog_72002_Content_12 = {
    Text = "No centro da multidão, Sarah estava encolhida no chão, segurando a cabeça. Seu corpo tremia incontrolavelmente devido à intensa dor da resistência forçada, e suas articulações estavam brancas devido ao esforço."
  },
  AvgDialog_72002_Content_13 = {
    Text = "Sophia avançou para bloquear Salvador, que estava ligeiramente curvado, usando seu corpo frágil para separá-lo à força de Sarah."
  },
  AvgDialog_72002_Content_14 = {
    Text = "Sophia, por favor, faça caminho."
  },
  AvgDialog_72002_Content_15 = {
    Text = "Uma vez que ela veio aqui em busca da minha ajuda, o Brilho do Pai Deus dissipará as sombras de seu sofrimento."
  },
  AvgDialog_72002_Content_16 = {
    Text = "A figura emagrecida se ajoelhou diante da cama doente de Sarah; padrões azul pálido gradualmente envolveram a mulher que chorava, que lentamente cessou seu sofrimento e adormeceu pacificamente sob a luz azul, muito parecido com um bebê."
  },
  AvgDialog_72002_Content_17 = {
    Text = "Salvador tossiu violentamente, um fino fio de sangue carmesim escorregando do canto de sua boca. Ele o limpou indiferentemente."
  },
  AvgDialog_72002_Content_18 = {
    Text = "Olhe para você! Vou te ajudar a descansar agora mesmo!"
  },
  AvgDialog_72002_Content_19 = {
    Text = "Vendo as duas figuras desaparecerem ao longe, Ronghui·Duo deixou escapar uma risada debochada."
  },
  AvgDialog_72002_Content_2 = {
    Text = "A Prata na cabeça de Sarah gradualmente diminui, ainda assim irrompe com uma força extraordinária, lutando violentamente, com um brilho de loucura nos olhos."
  },
  AvgDialog_72002_Content_20 = {
    Text = "A boneca, do que você está... rindo?"
  },
  AvgDialog_72002_Content_21 = {
    Text = "Ria daquele padre, claro."
  },
  AvgDialog_72002_Content_22 = {
    Text = "Sua lógica não é ridícula? \nEle já deveria ter abandonado esse caos há muito tempo."
  },
  AvgDialog_72002_Content_23 = {
    Text = "Se ele salvar apenas uma pessoa, talvez no futuro possa salvar muitas outras. No entanto, ele prefere esgotar todas as suas forças para preservar este templo contra a corrupção e proteger os fracos e indefesos como ovelhas à espera do sacrifício."
  },
  AvgDialog_72002_Content_24 = {
    Text = "Insistiu em usar a teoria de que \"mais pessoas são melhores do que menos\" para apoiar suas ideias, mas agora suas ações contradizem suas decisões anteriores."
  },
  AvgDialog_72002_Content_25 = {
    Text = "Se ele insiste em usar a teoria de \"mais pessoas são melhores que menos\" para apoiar sua ideia, o que ele está fazendo agora desviou-se de suas decisões anteriores."
  },
  AvgDialog_72002_Content_26 = {
    Text = "Para salvar uma pessoa reduzindo as chances de sobrevivência de todos na igreja, a lógica do \"santo\" humano de fato carece de uma base racional."
  },
  AvgDialog_72002_Content_27 = {
    Text = "Se fosse você, como lidaria com isso, Boneca?"
  },
  AvgDialog_72002_Content_28 = {
    Text = "Em um mundo que se recusa a aceitá-lo, ele luta para sobreviver, esperando por um dia de libertação que talvez nunca chegue."
  },
  AvgDialog_72002_Content_29 = {
    Text = "Irei acabar com seu sofrimento e pôr fim ao sofrimento de todos."
  },
  AvgDialog_72002_Content_3 = {
    Text = "Várias figuras altas semelhantes a cuidadores aproximaram-se de ambos os lados, amarrando-a com força com cordas de cânhamo à cama."
  },
  AvgDialog_72002_Content_4 = {
    Text = "Por favor, todos, não há necessidade de agir dessa maneira. Deixem tudo comigo. O Pai Deus curará sua alma, que se perdeu devido ao sofrimento."
  },
  AvgDialog_72002_Content_5 = {
    Text = "Salvador puxou as mangas de sua roupa, revelando cicatrizes de vários tamanhos e aparências chocantes cobrindo seus braços resilientes, mas envelhecidos."
  },
  AvgDialog_72002_Content_6 = {
    Text = "Ele cortou o pulso, e gotas de sangue fluíram para o chão da igreja, formando gradualmente padrões semelhantes a um círculo mágico."
  },
  AvgDialog_72002_Content_7 = {
    Text = "Senhor Salvador!!"
  },
  AvgDialog_72002_Content_8 = {
    Text = "Uma menina saiu correndo da multidão e envolveu o ferimento no pulso de Salvador com um curativo branco."
  },
  AvgDialog_72002_Content_9 = {
    Text = "Excelência, Bispo, não sei que tipo de pessoa má você percebe a Senhorita Juliette, mas eu consigo discernir claramente os verdadeiros desejos das pessoas."
  },
  AvgDialog_72003_Content_1 = {
    Text = "De jeito nenhum! Há muitos deles. Nesse ritmo, não conseguiremos detê-los; o campanário será invadido!"
  },
  AvgDialog_72003_Content_10 = {
    Text = "Aquela mulher."
  },
  AvgDialog_72003_Content_11 = {
    Text = "O monstro está atrás daquela mulher!"
  },
  AvgDialog_72003_Content_12 = {
    Text = "Você ouve gritos de angústia emanando do interior da torre do relógio—roucos, quebrados e desgastados. No momento em que os uivos enchem seus ouvidos, você se encontra em uma situação horrível que poderia enlouquecer alguém."
  },
  AvgDialog_72003_Content_13 = {
    Text = "Naquela época, Sarah soltou um rugido tão intenso antes que sua cabeça explodisse de culpa—"
  },
  AvgDialog_72003_Content_14 = {
    Text = "Cuidado, Sarah!!"
  },
  AvgDialog_72003_Content_15 = {
    Text = "Você irrompe na sala, onde a figura da freira está encolhida na Sombra."
  },
  AvgDialog_72003_Content_16 = {
    Text = "Ela se ajoelhou no chão, tremendo de medo enquanto segurava seus ombros com força. Uma fina linha de sangue corria do topo de sua cabeça até seu queixo, e o gotejamento carmesim a fazia parecer especialmente pálida e aterrorizante."
  },
  AvgDialog_72003_Content_17 = {
    Text = "Você hesitou."
  },
  AvgDialog_72003_Content_18 = {
    Text = "A pessoa prestes a perder o controle ainda é Sarah? Você deve tratá-la como um monstro ou como um humano?"
  },
  AvgDialog_72003_Content_19 = {
    Text = "É natural sentir dor quando nem mesmo essa pequena quantidade de poder Prata pode ser contida."
  },
  AvgDialog_72003_Content_2 = {
    Text = "Uma figura petite avança em sua direção, seu cabelo desgrenhado na testa mostrando claramente que ela acaba de ser acordada."
  },
  AvgDialog_72003_Content_20 = {
    Text = "Doll, sem hesitação, se aproximou de Sara, estendeu a mão e suavemente acariciou o brilho na testa dela, e depois tirou um pequeno frasco de preparado, aplicando-o nos ossos brancos visíveis sob a pele rachada."
  },
  AvgDialog_72003_Content_21 = {
    Text = "O brilho da Prata foi gradualmente se apagando."
  },
  AvgDialog_72003_Content_22 = {
    Text = "Podemos apenas suprimir temporariamente; se a doença progredir ou se a Prata for extraída à força, seu Corpo não poderá suportar."
  },
  AvgDialog_72003_Content_23 = {
    Text = "Você sabe de alguém habilidoso em purificação?"
  },
  AvgDialog_72003_Content_24 = {Text = "..."},
  AvgDialog_72003_Content_25 = {Text = "..."},
  AvgDialog_72003_Content_27 = {
    Text = "No passado distante, no meio da multidão barulhenta. Salvador levantou a mão, e o sangue começou a fluir de seu corpo, contornando ao redor e indo em direção à placa."
  },
  AvgDialog_72003_Content_28 = {
    Text = "Uma luz azul fluía ao longo de padrões intrincados, clara e tênue, respirando suavemente."
  },
  AvgDialog_72003_Content_29 = {
    Text = "Pai Deus da Origem, nosso misericordioso Criador, por favor ouça a minha prece."
  },
  AvgDialog_72003_Content_3 = {
    Text = "%player%! O que está acontecendo aqui?! Nunca houve tantos monstros antes!"
  },
  AvgDialog_72003_Content_30 = {
    Text = "Tênues filamentos azuis irradiavam da tábua, passando através das multidões e dissipando o persistente cheiro de sangue, deixando um leve aroma de incenso."
  },
  AvgDialog_72003_Content_31 = {
    Text = "As pessoas que estavam de pé lentamente se sentaram."
  },
  AvgDialog_72003_Content_32 = {
    Text = "Aqueles sentados ali, de boca aberta, olhavam fixamente para a cena milagrosa diante deles."
  },
  AvgDialog_72003_Content_33 = {
    Text = "Aqueles que haviam perdido a consciência, ou até mesmo parado de respirar, lentamente abriram os olhos na brisa suave."
  },
  AvgDialog_72003_Content_34 = {
    Text = "Por favor, alivie a dor deles e acalme seus corações."
  },
  AvgDialog_72003_Content_35 = {
    Text = "Os olhos das pessoas ficaram vagos, seus corpos relaxaram. O pânico e o medo se dissiparam, substituídos por calma e tranquilidade."
  },
  AvgDialog_72003_Content_36 = {
    Text = "Livre-os do sofrimento e conceda-lhes a bênção."
  },
  AvgDialog_72003_Content_37 = {
    Text = "A luz em ondas se expandiu para fora, e todos fecharam os olhos, como se imersos em tranquilidade."
  },
  AvgDialog_72003_Content_38 = {Text = "..."},
  AvgDialog_72003_Content_39 = {
    Text = "A cura de Salvador é tão calma e estável, é suficiente para construir um canto absolutamente tranquilizador na turbulenta realidade."
  },
  AvgDialog_72003_Content_4 = {
    Text = "Olhe para os movimentos do monstro!"
  },
  AvgDialog_72003_Content_40 = {
    Text = "Não tenho certeza se ainda existem coisas neste mundo que correspondem ao que eu conheço... mas espero que elas existam."
  },
  AvgDialog_72003_Content_41 = {
    Text = "O bispo da Igreja da Redenção, Salvador."
  },
  AvgDialog_72003_Content_42 = {
    Text = "Amanhã de manhã, partiremos para romper."
  },
  AvgDialog_72003_Content_5 = {
    Text = "Seus olhos sem alma olhavam todos para a torre do sino, como um bando de lobos uivando para uma lua cheia vermelha como sangue na selva."
  },
  AvgDialog_72003_Content_6 = {
    Text = "Algo na torre do relógio está os atraindo."
  },
  AvgDialog_72003_Content_7 = {
    Text = "Você se lembra das aberrações de dissolução que espreitavam perto da porta do corredor do porão; elas também estavam ansiando por algo, reunindo-se ali."
  },
  AvgDialog_72003_Content_8 = {Text = "..."},
  AvgDialog_72003_Content_9 = {
    Text = "Hoje no campanário..."
  },
  AvgDialog_72004_Content_1 = {
    Text = "Cadência do enigma"
  },
  AvgDialog_72004_Content_10 = {
    Text = "O mundo exterior é divertido, meu pequeno filhote?"
  },
  AvgDialog_72004_Content_11 = {
    Text = "Você quer responder ao desafio dela, mas uma sensação de cansaço vem como uma maré, varrendo toda a sua vontade. \nDominado pela exaustão, você desmaia antes que ela pronuncie a próxima palavra."
  },
  AvgDialog_72004_Content_12 = {
    Text = "O leve apito de uma corrente elétrica fraca, junto com a respiração silenciosa de alguém."
  },
  AvgDialog_72004_Content_13 = {
    Text = "Você abre os olhos e se vê deitado em uma pequena cama dobrável, com Búzio dormindo tranquilamente ao seu lado."
  },
  AvgDialog_72004_Content_14 = {Text = "Hmm?"},
  AvgDialog_72004_Content_15 = {
    Text = "Ela esfregou os olhos sonolentos e lentamente puxou o cobertor fino que a cobria."
  },
  AvgDialog_72004_Content_16 = {
    Text = "Você precisa descansar um pouco mais; o Dopitoin injetado e outros sedativos farão seu corpo cair em Fadiga anormal."
  },
  AvgDialog_72004_Content_17 = {
    Text = "Você levantou o braço e de fato sentiu a dor e fraqueza em seus bíceps."
  },
  AvgDialog_72004_Content_18 = {
    Text = "Uma vez que você se recuperar da sua doença, vamos nos dar tempo para discutir com a Boneca e permitir que você saia para um passeio, que tal? Pacientes sempre precisam de ar fresco."
  },
  AvgDialog_72004_Content_19 = {
    Text = "Além disso, você não tem comido nada há muito tempo, mesmo tendo suplementado com soro nutricional, o sistema digestivo precisa de ingestão alimentar para funcionar saudavelmente..."
  },
  AvgDialog_72004_Content_2 = {
    Text = "Clic, clic. \nAs garras de Dôl batem na mesa do laboratório.\n\n."
  },
  AvgDialog_72004_Content_20 = {
    Text = "Quanto tempo eu dormi?"
  },
  AvgDialog_72004_Content_21 = {
    Text = "Mesmo que o tempo há muito tenha perdido seu significado para você, é necessário que você entenda seu estado de saúde."
  },
  AvgDialog_72004_Content_22 = {
    Text = "Deixe-me conferir... 46 horas e 15 minutos..."
  },
  AvgDialog_72004_Content_23 = {
    Text = "Apenas dois dias, ainda dentro da faixa tolerável."
  },
  AvgDialog_72004_Content_24 = {
    Text = "Você deseja ir embora? Receio que não posso permitir isso."
  },
  AvgDialog_72004_Content_25 = {
    Text = "Saindo deste laboratório, muitos bandidos o observam avidamente, cordeirinho."
  },
  AvgDialog_72004_Content_26 = {
    Text = "Doll está certa... Ficar aqui... é para sua proteção..."
  },
  AvgDialog_72004_Content_27 = {
    Text = "Eu não preciso da proteção de ninguém."
  },
  AvgDialog_72004_Content_28 = {
    Text = "Desde que é assim, deixe-me dar uma olhada."
  },
  AvgDialog_72004_Content_29 = {
    Text = "O cachorrinho de Mythag, sem o apoio de \"Seu\", ainda tem algumas habilidades!"
  },
  AvgDialog_72004_Content_3 = {
    Text = "Para ser honesto, não gosto da sua sugestão."
  },
  AvgDialog_72004_Content_4 = {
    Text = "Assim como eu não gosto daquele disco de vinil na sua mão—é boa música, mas co-credenciar obras pessoais é simplesmente um insulto aos criadores, como se tratasse a obra como um bolo de aniversário a ser dividido."
  },
  AvgDialog_72004_Content_5 = {
    Text = "Prometo infiltrar Mythag por você e detonar a Poça Negra, nada mais."
  },
  AvgDialog_72004_Content_6 = {
    Text = "A consciência de %player% foi Despertada e implantada no Cérebro em um frasco daquela Dimensão. Em outras palavras, ele é meu Cachorrinho treinado pessoalmente."
  },
  AvgDialog_72004_Content_7 = {
    Text = "Agora você quer uma parte, pedindo para eu entregar seu jarro de cérebro ou compartilhar resultados de pesquisa, só posso dizer, essa parte não estava incluída em nosso acordo."
  },
  AvgDialog_72004_Content_8 = {
    Text = "O que eu tenho a dizer termina aqui. A menos que você destrua este laboratório e enfrente a ira que devo infligir a você, minha resposta à sua proposta sempre será \"pensamento desejoso\"."
  },
  AvgDialog_72004_Content_9 = {
    Text = "Melt·Dore parece ter terminado a comunicação e virou-se para você, gravemente ferido e sendo amparado por Wenkel."
  },
  AvgDialog_72005_Content_1 = {
    Text = "Agora que mencionou isso, alguns dos monstros de Dissolução aqui parecem diferentes dos do meu mundo."
  },
  AvgDialog_72005_Content_10 = {
    Text = [[
Eles gritam: 
Me abrace.

.]]
  },
  AvgDialog_72005_Content_11 = {
    Text = [[
Eles gritam: 
Mate-me.]]
  },
  AvgDialog_72005_Content_12 = {
    Text = "Eles gritam: \nme torne você, deixe você se tornar eu."
  },
  AvgDialog_72005_Content_13 = {
    Text = "<Italic:Que os nossos humildes espíritos se ergam nas marés escuras eternas, fundindo-se e entrelaçando-se num frenesi proibido, para nunca mais se separarem.>"
  },
  AvgDialog_72005_Content_14 = {
    Text = "AAAGGGHHHH—"
  },
  AvgDialog_72005_Content_15 = {
    Text = "Você urra, caindo de joelhos, estendendo as mãos instintivamente para frente."
  },
  AvgDialog_72005_Content_16 = {Text = "Alguém..."},
  AvgDialog_72005_Content_17 = {
    Text = "Alguém... por favor..."
  },
  AvgDialog_72005_Content_18 = {
    Text = "Você ouviu isso?"
  },
  AvgDialog_72005_Content_19 = {
    Text = "Deve... fundir-se..."
  },
  AvgDialog_72005_Content_2 = {
    Text = "Estes monstros apareceram após aquele cataclismo."
  },
  AvgDialog_72005_Content_20 = {
    Text = "Você ouviu o mesmo som que aqueles mutantes ouviram."
  },
  AvgDialog_72005_Content_21 = {
    Text = "A voz da Boneca contém apenas uma frieza inorgânica, e comparado a ela, aqueles chamados carregam uma sensação de dor."
  },
  AvgDialog_72005_Content_22 = {
    Text = "Acalme sua mente e tente captar aquelas vozes. A energia espiritual dentro dos Núcleos de Prata é fraca demais para os instrumentos detectarem. Isso é algo que só você pode realizar."
  },
  AvgDialog_72005_Content_23 = {
    Text = "Batidas distantes de tambores de terras desconhecidas ecoam indistintamente, e um caminho sem sol aparece diante de seus olhos."
  },
  AvgDialog_72005_Content_24 = {
    Text = "A lama suja e as rochas esculpidas estão em constante mudança na miasma polarizada, com sombras distorcidas que se assemelham a fantasmas indescritíveis."
  },
  AvgDialog_72005_Content_25 = {
    Text = "<Italic:Dum dum, dum dum.>"
  },
  AvgDialog_72005_Content_26 = {
    Text = "Aquelas batidas de tambor se tornam cada vez mais urgentes. Você olha para baixo: a água negra já encharcou seus tornozelos, instigando-o a adentrar o sonho sombrio."
  },
  AvgDialog_72005_Content_27 = {
    Text = "Você respira fundo, clareando sua mente tonta. Lutando para manter o equilíbrio, você ergue suavemente os pés na água espessa e profunda e lentamente começa a caminhar para frente..."
  },
  AvgDialog_72005_Content_28 = {
    Text = "Sua língua está seca, como se coberta de cinzas."
  },
  AvgDialog_72005_Content_29 = {
    Text = "Eles nasceram das cinzas, abraçando e se fundindo uns com os outros..."
  },
  AvgDialog_72005_Content_3 = {
    Text = "Realizei extensas amostragens e testes. Inicialmente não tinha pistas, mas cheguei a uma conclusão após um processo complicado."
  },
  AvgDialog_72005_Content_30 = {
    Text = "Enquanto você luta para respirar, a fumaça o enterra profundamente. Você luta para abrir os olhos e, junto com incontáveis seres, olha para cima para atravessar essa névoa interminável."
  },
  AvgDialog_72005_Content_31 = {
    Text = "Eles anseiam por..."
  },
  AvgDialog_72005_Content_32 = {
    Text = "No distante céu pálido, um sol borrado paira no alto."
  },
  AvgDialog_72005_Content_33 = {
    Text = "La roue solaire noire suspendue dans le ciel, comme un Pupile ancien oublié, regarde silencieusement la terre envahie par les cauchemars, enveloppée de brume."
  },
  AvgDialog_72005_Content_34 = {
    Text = "A luz não pode penetrá-lo, mas é, na verdade, devorada por ele. Os contornos ondulantes tecem um ritual eterno, declarando um fim irreversível e indescritível."
  },
  AvgDialog_72005_Content_35 = {
    Text = "A chegada do fim."
  },
  AvgDialog_72005_Content_4 = {
    Text = "Qual é a conclusão?"
  },
  AvgDialog_72005_Content_5 = {
    Text = "Essas aberrações de Dissolução contêm Prata de mais de uma forma de vida."
  },
  AvgDialog_72005_Content_6 = {
    Text = "O processo usual de refinação de Prata não distingue intencionalmente a origem da Prata, especialmente ao refinar Prata de baixa espiritualidade para uso como combustível."
  },
  AvgDialog_72005_Content_7 = {
    Text = "Você toca o Núcleo de Prata, e sonhos caóticos afogam-no como marés geladas."
  },
  AvgDialog_72005_Content_8 = {
    Text = "Dois tocos de braços, fundindo-se e entrelaçando-se mutuamente.\nEles já foram tão apaixonados que se entregaram um ao outro."
  },
  AvgDialog_72005_Content_9 = {
    Text = "Entregue os ossos e o sangue, a alma e a carne, rasgue os cabelos em desalinho.\nFiél ao desejo, fiél à sede, fiél ao pânico e à dor da separação.\n\n."
  },
  AvgDialog_72006_Content_1 = {
    Text = "Sonho em um frasco"
  },
  AvgDialog_72006_Content_10 = {
    Text = "Bem-vindo à minha base secreta, viajante do 317º mundo, uma centelha de consciência da \"Vontade suprema\"... um pobre e afogado filhote de cachorro."
  },
  AvgDialog_72006_Content_11 = {
    Text = "Diga-me, seu mundo foi destruído?"
  },
  AvgDialog_72006_Content_12 = {Text = "..."},
  AvgDialog_72006_Content_13 = {
    Text = "De fato, merece ser chamado de \"meu\" trabalho."
  },
  AvgDialog_72006_Content_14 = {
    Text = "Assim como você pensou, o \"eu\" no mundo em que você está veio deste \"eu\" enviado ao seu tempo e espaço através da Capacidade de viagem Dimensional."
  },
  AvgDialog_72006_Content_15 = {
    Text = "Em troca, ela me enviou um presente interessante... sua \"consciência\"."
  },
  AvgDialog_72006_Content_16 = {Text = "..."},
  AvgDialog_72006_Content_17 = {
    Text = "Você quer ver seu eu atual?"
  },
  AvgDialog_72006_Content_18 = {
    Text = "Seu sorriso era radiante, como uma dália negra em plena floração."
  },
  AvgDialog_72006_Content_19 = {
    Text = "Winkle, traga um espelho de corpo inteiro."
  },
  AvgDialog_72006_Content_2 = {
    Text = "Iniciar o gramofone. O disco com a capa preta, o terceiro da esquerda na prateleira."
  },
  AvgDialog_72006_Content_20 = {
    Text = "Deixe nosso \"convidado\" ter uma boa olhada em sua aparência atual..."
  },
  AvgDialog_72006_Content_21 = {
    Text = "Nenhum olho é necessário; sinais fotoelétricos simulam os nervos ópticos."
  },
  AvgDialog_72006_Content_22 = {
    Text = "Nencorde vocais não são necessários; vibrações mecânicas e meio líquido substituem os órgãos que produzem e recebem som."
  },
  AvgDialog_72006_Content_23 = {
    Text = "O pensador perfeito, um cérebro em um frasco..."
  },
  AvgDialog_72006_Content_24 = {
    Text = "Aqui está você, o grande \"Vontade suprema\"!"
  },
  AvgDialog_72006_Content_25 = {
    Text = "No reflexo do espelho do chão, a \"sua\" sombra aparece como um cérebro recém-separado, revelando um rosa insuportável. As rugas e sulcos em sua superfície se assemelham a cordilheiras montanhosas retorcidas."
  },
  AvgDialog_72006_Content_26 = {
    Text = "As pequenas bolhas na solução nutritiva emitem um som de ondulação suave, como se sussurrassem algum segredo indescritível, fazendo com que sua \"mente\" já caótica se torne incomumente tensa."
  },
  AvgDialog_72006_Content_27 = {
    Text = "Melt·Dor ri alto. \nWinkell está atrás dela, mordendo nervosamente as unhas."
  },
  AvgDialog_72006_Content_28 = {Text = "Posso ir?"},
  AvgDialog_72006_Content_29 = {
    Text = "Não... me ajude a continuar os passos experimentais. Este é o manual."
  },
  AvgDialog_72006_Content_3 = {
    Text = "Adicione mais 21mg de Prata pura ao reator. Use o segundo processo de refinação; quanto mais completamente o espírito for extinto, melhor."
  },
  AvgDialog_72006_Content_30 = {
    Text = "Melt·Dore parou o vitrola e saiu, deixando Wenkel e você sozinhos no laboratório vazio, se encarando."
  },
  AvgDialog_72006_Content_31 = {
    Text = "Etapas experimentais, etapas experimentais..."
  },
  AvgDialog_72006_Content_32 = {
    Text = "Como se estivesse apenas percebendo o lembrete de Doll, ela virou-se e começou a folhear freneticamente as anotações que Doll havia deixado para trás. Suas ações eram menos como uma leitura rápida e mais como se não estivesse lendo uma única palavra."
  },
  AvgDialog_72006_Content_33 = {
    Text = "Ei, ei. Você pode me ouvir?"
  },
  AvgDialog_72006_Content_34 = {
    Text = "Não consigo ouvir, não consigo ouvir... Não ouvi nada..."
  },
  AvgDialog_72006_Content_35 = {
    Text = "Você é... Winkle, certo?"
  },
  AvgDialog_72006_Content_36 = {
    Text = "Você... como você poderia saber..."
  },
  AvgDialog_72006_Content_37 = {
    Text = "Não tenha medo, Búzio. Fomos uma vez parceiros de batalha."
  },
  AvgDialog_72006_Content_38 = {
    Text = "Você tenta acalmar as emoções dela. Você sabe em seu coração que Winkle em um estado nervoso não pode ter nenhuma comunicação eficaz."
  },
  AvgDialog_72006_Content_39 = {
    Text = "Você... eu..."
  },
  AvgDialog_72006_Content_4 = {
    Text = "O produto experimental de hoje... está quase concluído."
  },
  AvgDialog_72006_Content_40 = {
    Text = "Ela mordeu as unhas, seu olhar piscando de um lado para o outro, como uma jovem fera assustada encurralada em um canto escuro."
  },
  AvgDialog_72006_Content_41 = {
    Text = "Calma. Você poderia me dizer por que estou aqui?"
  },
  AvgDialog_72006_Content_42 = {
    Text = "Isso, isso..."
  },
  AvgDialog_72006_Content_43 = {
    Text = "Você esperou pacientemente enquanto ela se acalmava. \nDepois de um momento, ela pareceu finalmente tomar uma decisão."
  },
  AvgDialog_72006_Content_44 = {
    Text = "Naquele dia, a Boneca de repente enviou uma comunicação..."
  },
  AvgDialog_72006_Content_45 = {
    Text = "Winkle, prepare o receptor e o tanque de cérebro reserva."
  },
  AvgDialog_72006_Content_46 = {
    Text = "Capturei um sinal incomum. A frequência mostra que é próxima da consciência de Thuwapo."
  },
  AvgDialog_72006_Content_47 = {
    Text = "Aquele cara teoricamente se trancou dentro da \"porta\"; eu me pergunto como esse sinal foi preservado."
  },
  AvgDialog_72006_Content_48 = {
    Text = "Em resumo, prepare-se para receber a tarefa imediatamente!"
  },
  AvgDialog_72006_Content_49 = {
    Text = "Em resumo, sua consciência foi projetada nesta câmara cerebral e conseguiu sobreviver."
  },
  AvgDialog_72006_Content_5 = {
    Text = "Você pode sentir minha presença?"
  },
  AvgDialog_72006_Content_50 = {
    Text = "A fonte específica pode ser conhecida apenas pela Boneca."
  },
  AvgDialog_72006_Content_51 = {
    Text = "Falando francamente, ativar sua consciência nos manteve acordados por um mês inteiro. A Boneca provavelmente foi dormir; nem mesmo corpos artificiais conseguem suportar por muito mais tempo."
  },
  AvgDialog_72006_Content_52 = {
    Text = "Então parece que, antes de me transferir, você já estava ajudando a Boneca com o experimento."
  },
  AvgDialog_72006_Content_53 = {
    Text = "Você sabe o que ela está fazendo?"
  },
  AvgDialog_72006_Content_54 = {
    Text = "Winkle tremia nervosamente."
  },
  AvgDialog_72006_Content_55 = {
    Text = "Eu, eu estava apenas fazendo algumas... pesquisas científicas de ponta..."
  },
  AvgDialog_72006_Content_56 = {
    Text = "Sobre viagens no tempo e transferência de consciência... ajuda-me a voltar ao meu planeta natal o mais rápido possível..."
  },
  AvgDialog_72006_Content_57 = {
    Text = "Você solta um suspiro, embora não tenha certeza se o som dele pode alcançar seus ouvidos."
  },
  AvgDialog_72006_Content_58 = {
    Text = "O mero ato de se justificar mostra que você sabe o que está fazendo, Búzio."
  },
  AvgDialog_72006_Content_59 = {
    Text = "Winkel, por você, por mim, e por tantas outras pessoas que podem ser prejudicadas pelo Melt·Doll."
  },
  AvgDialog_72006_Content_6 = {Text = "..."},
  AvgDialog_72006_Content_60 = {
    Text = "Posso pedir que me conceda um favor?"
  },
  AvgDialog_72006_Content_61 = {
    Text = "Eu... eu posso ouvir isso."
  },
  AvgDialog_72006_Content_62 = {
    Text = "Você sabe como restaurar minha capacidade de me mover normalmente?"
  },
  AvgDialog_72006_Content_63 = {
    Text = "Winkle balança a cabeça com força."
  },
  AvgDialog_72006_Content_64 = {
    Text = "A operação da Boneca não é minha especialidade, e todas as próteses foram implantadas com selos pela Boneca, somente ela pode manipulá-las."
  },
  AvgDialog_72006_Content_65 = {
    Text = "Você deve buscar outro método.\nTalvez entrar em contato com outros Despertados e pedir ajuda...?"
  },
  AvgDialog_72006_Content_66 = {
    Text = "Se não me engano, aquela fileira atrás de você é o depósito de núcleos de prata de Fusão·Boneca, não é?"
  },
  AvgDialog_72006_Content_67 = {
    Text = "Garrafas, rótulos e vários instrumentos estavam organizados de forma neat, perfeitamente de acordo com os hábitos de trabalho da Boneca."
  },
  AvgDialog_72006_Content_68 = {
    Text = "Do cofre de Prata, pegue um..."
  },
  AvgDialog_72006_Content_69 = {
    Text = "Imagens de Ramona, Doll, Ogier e Lotan continuam aparecendo em sua mente."
  },
  AvgDialog_72006_Content_7 = {
    Text = "Não hesite. Apenas \"fale\" da sua maneira habitual. O dispositivo capturará os sinais simulados que você emite e os converterá em sinais de onda sonora."
  },
  AvgDialog_72006_Content_70 = {
    Text = "Dê-me a Prata da Madame Narciso."
  },
  AvgDialog_72006_Content_71 = {
    Text = "Vendo Winkle hesitar, você decidiu adicionar mais peso."
  },
  AvgDialog_72006_Content_72 = {
    Text = "Winkle, neste momento, o tanque cerebral conectado é a única fonte de luz neste quarto. Se você se recusar a concordar com este pequeno pedido, eu vou me extinguir imediatamente."
  },
  AvgDialog_72006_Content_73 = {
    Text = "Levará pelo menos 3 segundos para ativar as luzes no interruptor, então pense cuidadosamente sobre como você irá sobreviver a esses difíceis 3 segundos."
  },
  AvgDialog_72006_Content_74 = {
    Text = "Eu vou contar até três —"
  },
  AvgDialog_72006_Content_75 = {Text = "Três—"},
  AvgDialog_72006_Content_76 = {
    Text = "Você tenta fazer o líquido fluorescente no tanque piscar."
  },
  AvgDialog_72006_Content_77 = {
    Text = "No primeiro momento da chegada da escuridão, Winkle soltou um grito agudo."
  },
  AvgDialog_72006_Content_78 = {
    Text = "Não— eu prometo que vou conseguir para você agora mesmo!!"
  },
  AvgDialog_72006_Content_79 = {
    Text = "Ela se virou e começou a revirar os armários de remédios ao lado da bancada de laboratório. \nAlguns segundos depois, ela segurava em sua palma uma cápsula de prata envolta em uma névoa púrpura ambígua, levantando-a cuidadosamente diante de você."
  },
  AvgDialog_72006_Content_8 = {
    Text = "Você tenta vocalizar como ela instruiu. Embora você não sinta vibrações em sua garganta, ela revela um sorriso contemplativo, mas enigmático."
  },
  AvgDialog_72006_Content_80 = {Text = "Bem..."},
  AvgDialog_72006_Content_81 = {
    Text = "Você olha fixamente para o metal prateado, tentando sintonizar e ressoar com ele.  \nVocê não tem certeza se, como um cérebro em uma cuba, será capaz de conseguir... mas não tem escolha a não ser tentar.\n\n."
  },
  AvgDialog_72006_Content_82 = {
    Text = "A névoa roxa girou."
  },
  AvgDialog_72006_Content_83 = {
    Text = "Claramente marcado, justo e reto... O que a loja da Narciso pode fazer por você?"
  },
  AvgDialog_72006_Content_9 = {
    Text = "Você me pergunta onde isto está?"
  },
  AvgDialog_72007_Content_1 = {Text = "Huff."},
  AvgDialog_72007_Content_2 = {
    Text = "Esqueça. Com desenvolvimentos inesperados, acho que vou voltar na próxima vez."
  },
  AvgDialog_72007_Content_3 = {
    Text = "No entanto, Bispo Salvador, eu notei... na batalha recente, você não agiu nem uma vez, certo?"
  },
  AvgDialog_72007_Content_4 = {
    Text = "As velas já estão balançando precariamente; com um sussurro da brisa, elas podem se apagar."
  },
  AvgDialog_72007_Content_5 = {
    Text = "Um cão gigante galopa em sua direção, sua cabeça torcida abaixada obedientemente, mostrando total submissão a Juliette."
  },
  AvgDialog_72007_Content_6 = {
    Text = "Juliette se virou graciosamente, apoiando-se no ombro do grande cão."
  },
  AvgDialog_72007_Content_7 = {
    Text = [[
Vamos embora, querida.
Cuide-se, Bispo Salvador.]]
  },
  AvgDialog_72007_Content_8 = {
    Text = "Aquele vento... chegará em breve."
  },
  AvgDialog_72008_Content_1 = {
    Text = "Ei, velho da igreja, trouxemos o paciente!"
  },
  AvgDialog_72008_Content_10 = {
    Text = "Quando seu cérebro foi completamente consumido......"
  },
  AvgDialog_72008_Content_11 = {
    Text = "Pai Salvador baixou a cabeça e traçou o símbolo de oração em seu peito."
  },
  AvgDialog_72008_Content_12 = {
    Text = "Amanhã, tentarei eliminar este Poder dentro dela."
  },
  AvgDialog_72008_Content_13 = {
    Text = "Sarah, você poderia nos contar como conseguiu essa cicatriz na cabeça?"
  },
  AvgDialog_72008_Content_14 = {
    Text = "Naquele dia..."
  },
  AvgDialog_72008_Content_15 = {
    Text = "A menininha afastou a fina coberta, passou sobre as crianças adormecidas ao seu redor, descalça na noite de inverno, balançando-se enquanto caminhava em direção ao pátio obscuro."
  },
  AvgDialog_72008_Content_16 = {
    Text = "Aigis, Aigis...?"
  },
  AvgDialog_72008_Content_17 = {
    Text = "Eu a alcancei, querendo avisá-la para calçar os sapatos.\nMas ela nem me deu atenção."
  },
  AvgDialog_72008_Content_18 = {
    Text = "Apertei o passo atrás dela, finalmente alcançando-a na entrada da oficina."
  },
  AvgDialog_72008_Content_19 = {
    Text = "Eu pressionei seus ombros e virei seu corpo para me encarar..."
  },
  AvgDialog_72008_Content_2 = {
    Text = "Jenkin correu para a Igreja da Redenção antes de todos os outros."
  },
  AvgDialog_72008_Content_20 = {
    Text = "Eu só vejo..."
  },
  AvgDialog_72008_Content_21 = {
    Text = "Um par de olhos vazios."
  },
  AvgDialog_72008_Content_22 = {Text = "..."},
  AvgDialog_72008_Content_23 = {
    Text = "Naquele momento, a mão de alguém descansou suavemente em meu ombro direito."
  },
  AvgDialog_72008_Content_24 = {
    Text = "Eu me virei, tremendo..."
  },
  AvgDialog_72008_Content_25 = {
    Text = "Aquela é uma mulher da cor da pedra segurando uma pequena faca."
  },
  AvgDialog_72008_Content_26 = {
    Text = "O dedo indicador dela pressionou suavemente contra seus lábios igualmente pálidos e semelhantes a gesso, advertindo quietamente."
  },
  AvgDialog_72008_Content_27 = {
    Text = "Shh, não perturbe os filhos do \"Ele\"."
  },
  AvgDialog_72008_Content_28 = {Text = "..."},
  AvgDialog_72008_Content_29 = {
    Text = "Após isso, eu não consigo mais recordar o que aconteceu."
  },
  AvgDialog_72008_Content_3 = {
    Text = "Por favor, permaneça em silêncio. A Igreja ainda abriga muitos pacientes que podem não conseguir suportar barulhos excessivos."
  },
  AvgDialog_72008_Content_30 = {
    Text = "A cicatriz em minha testa foi originalmente deixada quando o Sr. Rogers pediu ao médico que tratasse minha doença."
  },
  AvgDialog_72008_Content_31 = {
    Text = "Após aquele dia, um brilho metálico prateado começou a aparecer... mas não machucava nem coçava, e não impactava a vida cotidiana."
  },
  AvgDialog_72008_Content_32 = {
    Text = "Não é à toa que você conseguiu sobreviver aquele cataclismo do Efeito regional d."
  },
  AvgDialog_72008_Content_33 = {
    Text = "Alguém implantou um Silver de alta atividade em você, elevando forçosamente seu índice gnóstico acima da linha padrão."
  },
  AvgDialog_72008_Content_34 = {
    Text = "Semelhante a 24, experimentos envolvendo a implantação ou condensação de Prata dentro dos humanos..."
  },
  AvgDialog_72008_Content_35 = {
    Text = "Infelizmente, cada presente vem a um custo. A dor que você está suportando agora está amplamente ligada a essa vida prolongada forçada."
  },
  AvgDialog_72008_Content_36 = {
    Text = "Pode aquele orgulhoso santo pai salvá-lo do fogo e da água... vamos esperar e ver."
  },
  AvgDialog_72008_Content_4 = {
    Text = "Aquele médico que cura doenças com as mãos é você? \nHmm, parece que não é igual aos de jaleco branco do asilo.\n\n."
  },
  AvgDialog_72008_Content_5 = {
    Text = "Não sou uma médica, apenas uma \"Benfeitora\". \nPor favor, acomodem o paciente no quarto do funcionário e me sigam."
  },
  AvgDialog_72008_Content_6 = {
    Text = "Uma luz azul suave flui em torno de Sarah, emanando um brilho quente e profundo cuidado pela vida."
  },
  AvgDialog_72008_Content_7 = {
    Text = "O tempo passa segundo a segundo. A luz fraca na palma de Salvador permanece inalterada. Ele apenas franze ligeiramente a testa, revelando um toque sutil de impotência e peso em seu rosto."
  },
  AvgDialog_72008_Content_8 = {
    Text = "Antes disso, eu nunca tinha visto sintomas assim. Simplesmente falando, existe uma força anormal dentro do corpo dela."
  },
  AvgDialog_72008_Content_9 = {
    Text = "Esse tipo de poder tem um desejo anormal de consumir cérebros... Ela reprime esse desejo por conta própria, e esse poder começa a se alimentar de seu próprio cérebro."
  },
  AvgDialog_72009_Content_1 = {Text = "Escapar"},
  AvgDialog_72009_Content_10 = {
    Text = "E quanto ao custo?"
  },
  AvgDialog_72009_Content_11 = {
    Text = "O primeiro pedido do guardião no novo mundo só pode ser tratado como um grandioso Presente a ser concedido; como poderia haver alguma demanda por um preço?"
  },
  AvgDialog_72009_Content_12 = {
    Text = "No entanto... se você desejar expressar sua gratidão..."
  },
  AvgDialog_72009_Content_13 = {
    Text = "Justo me traga a cabeça daquela pessoa."
  },
  AvgDialog_72009_Content_14 = {
    Text = "A sua consciência mergulha no caos. Quando você abre os olhos novamente, Winkle ao seu lado está tremendo incontrolavelmente."
  },
  AvgDialog_72009_Content_15 = {
    Text = "Você... você... de repente caiu do vazio—um corpo..."
  },
  AvgDialog_72009_Content_16 = {
    Text = "Como eu saio deste lugar?"
  },
  AvgDialog_72009_Content_17 = {
    Text = "Ignorando seus murmúrios trêmulos, você perguntou diretamente."
  },
  AvgDialog_72009_Content_18 = {
    Text = "Não, você não pode ir embora... Se você tentar escapar... a Boneca definitivamente, definitivamente..."
  },
  AvgDialog_72009_Content_19 = {
    Text = "As pupilas dela se dilataram de medo, e sua voz tremia de desespero enquanto ela suplicava."
  },
  AvgDialog_72009_Content_2 = {
    Text = "Infelizmente, também queria encontrar uma maneira de transferi-lo de volta para sua dimensão original, mas a dimensão em que você está não parece estar conectada à base de Kadath... Em outras palavras, aquele lugar não é um dos milhares de sonhos de Tohuwabo."
  },
  AvgDialog_72009_Content_20 = {
    Text = "Não se preocupe, eu só estou saindo para dar uma olhada."
  },
  AvgDialog_72009_Content_21 = {
    Text = "Não... impossível..."
  },
  AvgDialog_72009_Content_22 = {
    Text = "Você ignorou seus apelos e bateu na porta de ferro que a Boneca havia deixado para trás, que não tinha maçaneta nem fechadura."
  },
  AvgDialog_72009_Content_23 = {
    Text = "Como eu abro esta porta?"
  },
  AvgDialog_72009_Content_24 = {
    Text = "Winkle deu alguns passos para trás, pressionando-se firmemente contra a mesa de laboratório."
  },
  AvgDialog_72009_Content_25 = {
    Text = "Eu... eu não sei..."
  },
  AvgDialog_72009_Content_26 = {
    Text = "Eu realmente só saí para dar uma olhada. Deixe a questão da Boneca comigo."
  },
  AvgDialog_72009_Content_27 = {
    Text = "A chave ou mecanismo para abrir a porta deve estar na mesa de experimento atrás de você, certo? Sua tentativa de ocultá-la expôs esse fato."
  },
  AvgDialog_72009_Content_28 = {
    Text = "Não, não é isso! Estou apenas muito assustado..."
  },
  AvgDialog_72009_Content_29 = {
    Text = "A Boneca não pode prever sua fuga, e não há necessidade de exagerar nas precauções contra o Cérebro em um frasco; esta entrada não deveria estar muito escondida."
  },
  AvgDialog_72009_Content_3 = {
    Text = "Mesmo eu não consigo atravessar dimensionalmente entre dois mundos com facilidade."
  },
  AvgDialog_72009_Content_30 = {
    Text = "Você examina a mesa do laboratório, seu olhar varrendo uma série de títulos de papel que provocam dor de cabeça."
  },
  AvgDialog_72009_Content_31 = {
    Text = "Num canto da bancada de laboratório, você encontrou uma chave simples com um cabo vermelho. Ao puxá-la suavemente, ouviu-se o som das engrenagens em funcionamento."
  },
  AvgDialog_72009_Content_32 = {
    Text = "Clique, clique, clique, a porta de ferro enferrujada se abre automaticamente puxada pelo mecanismo."
  },
  AvgDialog_72009_Content_33 = {
    Text = "Em um canto da mesa de experimentos, você descobriu um interruptor simples com uma alça vermelha. Você puxou suavemente, e o som de engrenagens girando pôde ser ouvido."
  },
  AvgDialog_72009_Content_34 = {
    Text = "Clang clang clang, a porta de ferro enferrujada se abre automaticamente sob o puxão de dispositivos mecânicos."
  },
  AvgDialog_72009_Content_35 = {
    Text = "Etc, etc —"
  },
  AvgDialog_72009_Content_36 = {
    Text = "Você ignorou os chamados dela e saiu em passo firme pelo portão de ferro—"
  },
  AvgDialog_72009_Content_37 = {
    Text = "Uma vasta névoa cinza-chumbo envolveu toda a cidade como um behemoth invisível."
  },
  AvgDialog_72009_Content_38 = {
    Text = "Incontáveis pisos instáveis se projetam da neblina, assemelhando-se a membros afiados envoltos em couro resistente."
  },
  AvgDialog_72009_Content_39 = {
    Text = "*Tosse, tosse...*"
  },
  AvgDialog_72009_Content_4 = {
    Text = "Mesmo eu não posso realizar facilmente viagens dimensionais entre dois mundos."
  },
  AvgDialog_72009_Content_40 = {
    Text = "Ninguém. Nenhuma figura está à vista."
  },
  AvgDialog_72009_Content_41 = {
    Text = "Você avançou com grande dificuldade pela rua."
  },
  AvgDialog_72009_Content_42 = {
    Text = "Após passar por três quadras, você acidentalmente vislumbra uma silhueta humana revelada através da névoa densa."
  },
  AvgDialog_72009_Content_43 = {
    Text = "A pessoa à frente —"
  },
  AvgDialog_72009_Content_44 = {
    Text = "Você está desarmado, Ramona não está ao seu lado e muito menos os companheiros."
  },
  AvgDialog_72009_Content_45 = {Text = "Whoosh—"},
  AvgDialog_72009_Content_46 = {
    Text = "Você está desarmado, e Ramona não está ao seu lado, muito menos os outros companheiros."
  },
  AvgDialog_72009_Content_47 = {
    Text = "A entidade aberrante cuspia um pedaço de lama negra. O lodo viscoso cobriu sua testa, e o fedor úmido escorreu pelo seu templo."
  },
  AvgDialog_72009_Content_48 = {
    Text = "Então veio um golpe pesado."
  },
  AvgDialog_72009_Content_5 = {
    Text = "Visto que é assim... eu preciso de pelo menos um corpo que possa se mover livremente aqui."
  },
  AvgDialog_72009_Content_50 = {Text = "Tosse—"},
  AvgDialog_72009_Content_51 = {
    Text = "Você sente seu corpo levantar do chão, estrelas piscando diante de seus olhos. Então, um chute lateral giratório vem voando, torcendo sua direção e infligindo uma dor excruciante."
  },
  AvgDialog_72009_Content_52 = {
    Text = "Você colidiu violentamente contra a parede sólida, e a dor intensa fez você sentir como se várias de suas costelas pudessem ter quebrado."
  },
  AvgDialog_72009_Content_53 = {
    Text = "(Há alguém que possa... me salvar...?)"
  },
  AvgDialog_72009_Content_54 = {
    Text = "Cof, cof... espirrar... espere, espere um minuto—"
  },
  AvgDialog_72009_Content_55 = {
    Text = "Em meio à poeira, Winkle cambaleou do canto da rua atrás de você."
  },
  AvgDialog_72009_Content_56 = {
    Text = "Leve isso e vá novamente!"
  },
  AvgDialog_72009_Content_57 = {
    Text = "Um arco prateado risca o céu poluído de poeira, perfurando a enxame de monstros ao seu redor, e pousa ao seu lado."
  },
  AvgDialog_72009_Content_58 = {
    Text = "Uma chave prateada. Sem número de série."
  },
  AvgDialog_72009_Content_59 = {
    Text = "Você se estendeu para tocar, mas as lágrimas embaçam sua visão, e a dor que percorre seu corpo faz suas pontas dos dedos tremerem incontrolavelmente."
  },
  AvgDialog_72009_Content_6 = {
    Text = "Você não pode viajar entre os dois mundos... mas é possível aproveitar os recursos dentro deste mundo, certo?"
  },
  AvgDialog_72009_Content_60 = {
    Text = "Apenas um pouco... mais..."
  },
  AvgDialog_72009_Content_61 = {Text = "\"Crack—\""},
  AvgDialog_72009_Content_62 = {
    Text = "Os tentáculos do monstro batem forte em suas costas, e a ferida já rasgada instantaneamente spray sangue."
  },
  AvgDialog_72009_Content_63 = {
    Text = "Mas naquele exato momento, suas pontas dos dedos tocaram aquele brilho."
  },
  AvgDialog_72009_Content_64 = {
    Text = "Recordar! Esforce-se para recordar!"
  },
  AvgDialog_72009_Content_65 = {
    Text = "Doll disse que sua consciência contém o mundo inteiro, e enquanto você se lembrar, a Chave Prata pode despertar o poder da memória!"
  },
  AvgDialog_72009_Content_66 = {
    Text = "Uma suave luz branca gradualmente envolve sua visão, e as quatro silhuetas familiares aparecem diante de você como fantasmas."
  },
  AvgDialog_72009_Content_67 = {
    Text = "Keeper! Você realmente é você?"
  },
  AvgDialog_72009_Content_68 = {
    Text = "Após ser espancado assim pelo Corpo dissoluto em apenas alguns dias, o curso de treinamento físico de Mythag ainda carece de espírito independente."
  },
  AvgDialog_72009_Content_69 = {
    Text = "Parece que agora não é a hora para relembrar."
  },
  AvgDialog_72009_Content_7 = {
    Text = "Como esperado do último Guardião de Mythag, o pedido ainda é tão exigente."
  },
  AvgDialog_72009_Content_70 = {
    Text = "Ogier, lute pela proteção do senhor!"
  },
  AvgDialog_72009_Content_71 = {Text = "Batalha."},
  AvgDialog_72009_Content_72 = {
    Text = "Para seguir em frente mais uma vez."
  },
  AvgDialog_72009_Content_8 = {
    Text = "Não consegue fazer isso?"
  },
  AvgDialog_72009_Content_9 = {
    Text = "Claro que não. A lojinha da Narciso com certeza realizará seu desejo."
  },
  AvgDialog_72010_Content_1 = {
    Text = "Ei, West-Whelp, estou vendo coisas?"
  },
  AvgDialog_72010_Content_10 = {
    Text = "Primeiro, a capacidade de completar o projeto e a construção de um edifício em um período tão curto demonstra as capacidades de engenharia do construtor."
  },
  AvgDialog_72010_Content_11 = {
    Text = "Segundo, o construtor deve estar intimamente familiarizado com a estrutura do meu laboratório, tendo vivido nele por muito tempo..."
  },
  AvgDialog_72010_Content_12 = {
    Text = "Com base nesse raciocínio, essa pessoa deveria ser—"
  },
  AvgDialog_72010_Content_13 = {
    Text = "H-hã? %player%, por que você voltou? Rápido, antes que ela perceba..."
  },
  AvgDialog_72010_Content_14 = {
    Text = "Winkle aparece virando a esquina, mexendo nas máquinas de computação, olhando para você com espanto."
  },
  AvgDialog_72010_Content_15 = {
    Text = "Então os olhos dela caem sobre a sombra atrás de você."
  },
  AvgDialog_72010_Content_16 = {
    Text = "Suas pupilas se contraem bruscamente. Sintoma: Terror toma conta de seu rosto, e o dispositivo em sua mão cai no chão com estrépito, espalhando peças de metal com um som ensurdecedor."
  },
  AvgDialog_72010_Content_17 = {
    Text = "Desculpa, desculpa, DESCULPA! Doll, eu não sabia que estavas aqui, não queria... Desculpa, a sério!"
  },
  AvgDialog_72010_Content_18 = {
    Text = "E há mais uma coisa que devo lembrar-te—"
  },
  AvgDialog_72010_Content_19 = {
    Text = "Esta construtora possui todos os dispositivos destrutivos do meu laboratório."
  },
  AvgDialog_72010_Content_2 = {
    Text = "Não... Você não está."
  },
  AvgDialog_72010_Content_20 = {
    Text = "Ela também tem o mesmo nível máximo de acesso a todos eles."
  },
  AvgDialog_72010_Content_21 = {Text = "Certo?"},
  AvgDialog_72010_Content_22 = {
    Text = "No final do corredor, uma figura idêntica surgiu lentamente. \nOs dois se encararam através de todo o laboratório, como se estivessem olhando para o próprio reflexo em um grande espelho de vidro.\n\n."
  },
  AvgDialog_72010_Content_23 = {
    Text = "\"Outro\" Fusão·Boneca."
  },
  AvgDialog_72010_Content_3 = {
    Text = "O laboratório, que antes havia desmoronado em uma pilha de pedras, agora aparece em sua forma original na esquina da rua. Você esfrega os olhos repetidamente, confirmando que não é uma ilusão."
  },
  AvgDialog_72010_Content_4 = {
    Text = "Tenho uma hipótese. Camundongo, fique do lado de fora."
  },
  AvgDialog_72010_Content_5 = {
    Text = "Você me tirou da cama quando precisou de mim, e agora me chuta pra fora quando não precisa? Isso não é justo!"
  },
  AvgDialog_72010_Content_6 = {
    Text = "Jenkin, comporte-se. Você ainda precisa cuidar da sua irmã Mason, lembra? Voltamos num instante."
  },
  AvgDialog_72010_Content_7 = {
    Text = "Não é tão simples assim de dizer.\nDe qualquer forma, vamos entrar com cuidado."
  },
  AvgDialog_72010_Content_8 = {
    Text = "Já faz meio mês desde que você acordou neste laboratório, e o que está diante de você é milagrosamente exatamente igual ao que você viu pela primeira vez."
  },
  AvgDialog_72010_Content_9 = {
    Text = "Restaurar um edifício completamente destruído... isso indica que o construtor possui duas habilidades-chave."
  },
  AvgDialog_72011_Content_1 = {
    Text = "Aquele que perdemos"
  },
  AvgDialog_72011_Content_10 = {
    Text = "Chirp... Chirp..."
  },
  AvgDialog_72011_Content_11 = {
    Text = "O pequeno rato balançou a cabeça, como se negasse a pergunta de Jenkin."
  },
  AvgDialog_72011_Content_12 = {Text = "Jenkin!"},
  AvgDialog_72011_Content_13 = {
    Text = "Você a abraçou com emoção. Seu corpo frágil foi pressionado firmemente contra o seu, tão pequeno, apenas uma partezinha, mas quente, com o calor da vida, e através das finas costelas, você sentiu os batimentos cardíacos tranquilizadores."
  },
  AvgDialog_72011_Content_14 = {
    Text = "O que você está fazendo?! Enlouqueceu?! Solte-me!"
  },
  AvgDialog_72011_Content_15 = {
    Text = "O que você está fazendo?! Você enlouqueceu?! Me deixe ir!"
  },
  AvgDialog_72011_Content_16 = {
    Text = "Antes que você pudesse explicar a Jenkin, um leve som de gemido veio de perto."
  },
  AvgDialog_72011_Content_17 = {
    Text = "Hmm... Mmm..."
  },
  AvgDialog_72011_Content_18 = {
    Text = "Estou dormindo... Eu não posso dormir demais... Ainda há 20 frascos para limpar e preciso preparar 120 litros de solvente..."
  },
  AvgDialog_72011_Content_19 = {Text = "..."},
  AvgDialog_72011_Content_2 = {
    Text = "A luz e a sombra diante dos meus olhos são estranhas e familiares ao mesmo tempo."
  },
  AvgDialog_72011_Content_20 = {Text = "..."},
  AvgDialog_72011_Content_21 = {Text = "..."},
  AvgDialog_72011_Content_22 = {
    Text = "Então, Jenkin, você realmente não viu uma terceira pessoa? Uma pesquisadora de cabelos vermelhos, facilmente assustada..."
  },
  AvgDialog_72011_Content_23 = {
    Text = "Eu temo que a situação pareça sombria para ela; qual era aquela frase mesmo? \"Por favor aceite nossas condolências, que sua alma descanse em paz.\""
  },
  AvgDialog_72011_Content_24 = {
    Text = "O pequeno rato com capuz deu de ombros."
  },
  AvgDialog_72011_Content_25 = {
    Text = "O lugar onde vocês dois do Lado Oeste foram desenterrados, em vez de ser ruínas, é mais como uma pequena colina de pedras."
  },
  AvgDialog_72011_Content_26 = {
    Text = "Se não fosse Brown insistindo que havia algo dentro, eu não me incomodaria em revirá-lo."
  },
  AvgDialog_72011_Content_27 = {
    Text = "E então... Boneca, você já esqueceu completamente do seu experimento maligno?"
  },
  AvgDialog_72011_Content_28 = {
    Text = "Embora eu ache que sua acusação é uma completa tolice, devo lembrá-lo que julgar meus princípios pelas noções humanas de bem e mal carece de qualquer adequação."
  },
  AvgDialog_72011_Content_29 = {
    Text = "Eu não sei quais mágoas existem entre vocês, mas aqui, pegue um pouco de pão."
  },
  AvgDialog_72011_Content_3 = {
    Text = "Ei, esse cara parece ter acordado."
  },
  AvgDialog_72011_Content_30 = {
    Text = "Se você estiver com sede, há água ali, hmm, junto com um pouco de chá preto e um monte de coisas elegantes que eu não consigo reconhecer."
  },
  AvgDialog_72011_Content_31 = {
    Text = "Você... ficou rico?"
  },
  AvgDialog_72011_Content_32 = {
    Text = "Que confusão! Você não sabe?"
  },
  AvgDialog_72011_Content_33 = {
    Text = "Após aquela noite cheia de sonhos bizarros, a maioria das pessoas desapareceu, e o exterior estava repleto de monstros."
  },
  AvgDialog_72011_Content_34 = {
    Text = "Felizmente, como todos desapareceram, pão grátis está disponível em toda parte."
  },
  AvgDialog_72011_Content_35 = {
    Text = "Você... como você acabou aqui?"
  },
  AvgDialog_72011_Content_36 = {
    Text = "Você olha ao redor. O pequeno espaço da torre do sino contém cinco ou seis beliches."
  },
  AvgDialog_72011_Content_37 = {
    Text = "Eu não queria vir; os camundongos estão se saindo muito bem nas ruas. Mas à noite, aqueles barulhentos são realmente irritantes."
  },
  AvgDialog_72011_Content_38 = {
    Text = "Quando me escondi alto, encontrei este lugar. Preciso subir uma escada; os monstros não podem subir."
  },
  AvgDialog_72011_Content_39 = {
    Text = "Infelizmente, percebi isso tarde demais. Já foi levado. A maioria deles está ferida ou um pouco louca."
  },
  AvgDialog_72011_Content_4 = {
    Text = "Uma pequena cabeça aparece em sua visão."
  },
  AvgDialog_72011_Content_40 = {
    Text = "Uma irmã bondosa também preparou uma cama para mim. Qual era aquele ditado? \"Por que não aproveitar?\""
  },
  AvgDialog_72011_Content_41 = {
    Text = "Jenkin, há um convidado chegando?"
  },
  AvgDialog_72011_Content_42 = {
    Text = "Sua respiração para."
  },
  AvgDialog_72011_Content_43 = {
    Text = "Ah, minhas desculpas pela falta de hospitalidade. Vou preparar um chá para você imediatamente."
  },
  AvgDialog_72011_Content_44 = {
    Text = "Irmã! Eles têm mãos e pés, então não precisam do seu cuidado."
  },
  AvgDialog_72011_Content_45 = {
    Text = "A propósito, esta é minha irmã, Mason. Ela pode parecer um pouco estranha agora, mas se você ousar tratá-la como um monstro, não serei gentil com você!"
  },
  AvgDialog_72011_Content_46 = {Text = "..."},
  AvgDialog_72011_Content_47 = {
    Text = "O que há de errado com você? Um vínculo fraternal tão tocante—você nunca viu um antes?"
  },
  AvgDialog_72011_Content_48 = {
    Text = "O que você quer dizer, irmãos? Seus olhos estão falhando!? Eu sou feminina, FEMININA!"
  },
  AvgDialog_72011_Content_49 = {
    Text = "Desculpe, perdi a compostura. Só não esperava revê-los..."
  },
  AvgDialog_72011_Content_5 = {
    Text = "Se você está acordado, vá tomar um banho. Até os ratos em Londres não conseguem suportar olhar para sua aparência imunda."
  },
  AvgDialog_72011_Content_50 = {
    Text = "Desculpe, eu perdi a compostura. Eu simplesmente não esperava ver todos vocês novamente..."
  },
  AvgDialog_72011_Content_51 = {
    Text = "De novo? Nós nos conhecemos de antes? Desculpe, mas não me lembro de ter te visto... minhas memórias ficaram todas bagunçadas depois do tratamento..."
  },
  AvgDialog_72011_Content_52 = {
    Text = "Não, não importa... Apenas saber que você ainda está vivo é o suficiente..."
  },
  AvgDialog_72011_Content_53 = {Text = "..."},
  AvgDialog_72011_Content_54 = {Text = "..."},
  AvgDialog_72011_Content_55 = {
    Text = "Não sei qual método a irmã mais velha usou, mas depois que contei a ela sobre minha irmã, ela ajudou a trazê-la de volta."
  },
  AvgDialog_72011_Content_56 = {
    Text = "Irmã... Embora ela às vezes pareça um pouco ansiosa e à beira de um colapso, ela permanece gentil e amável quando está de bom humor, especialmente comigo e com os outros..."
  },
  AvgDialog_72011_Content_57 = {
    Text = "A irmã mais velha de que você falou... qual é o nome dela?"
  },
  AvgDialog_72011_Content_58 = {
    Text = "Ei, eu não acabei de dizer isso?"
  },
  AvgDialog_72011_Content_59 = {
    Text = "Clementine, seu nome é Clementine."
  },
  AvgDialog_72011_Content_6 = {Text = "Chiado!"},
  AvgDialog_72011_Content_60 = {Text = "!"},
  AvgDialog_72011_Content_61 = {Text = "..."},
  AvgDialog_72011_Content_62 = {
    Text = "A Associação dos Escultores, aqueles insetos miseráveis que apenas sobrevivem? Alguém que se mistura com aquelas criaturas, mesmo que não seja um percevejo ou carrapato, certamente é algo sujo como sanguessuga ou mosca tábano."
  },
  AvgDialog_72011_Content_63 = {
    Text = "Você está sendo bastante indelicado ao fazer uma declaração tão precipitada, querida senhorita."
  },
  AvgDialog_72011_Content_64 = {
    Text = "Fazer tal declaração de maneira tão precipitada não é muito educado, querida jovem."
  },
  AvgDialog_72011_Content_65 = {
    Text = "A mulher de branco silenciosamente surge atrás de você."
  },
  AvgDialog_72011_Content_66 = {
    Text = "Um som zumbido perfura sua mente, e a paisagem à sua frente começa a distorcer."
  },
  AvgDialog_72011_Content_67 = {
    Text = "Vocês dois foram pessoalmente desenterrados por mim de pilhas de destroços. Eu cuidadosamente os carreguei até o topo desta torre do relógio, temendo que vocês pudessem ser devorados por aqueles monstros que exalam lama preta..."
  },
  AvgDialog_72011_Content_68 = {
    Text = "Recompensar bondade com inimizade não é bom, você não acha?"
  },
  AvgDialog_72011_Content_69 = {
    Text = "A senhorita Clementine é a benfeitora de mim e de minha irmã mais velha! Não ousem machucá-la!"
  },
  AvgDialog_72011_Content_7 = {
    Text = "Jen... Kin..."
  },
  AvgDialog_72011_Content_70 = {
    Text = "A senhorita Clementine é uma benfeitora para minha irmã e para mim. Você não pode prejudicá-la!"
  },
  AvgDialog_72011_Content_8 = {Text = "?!"},
  AvgDialog_72011_Content_9 = {
    Text = "Quem diabos é você, e como você me conhece? Eu escrevi meu nome no meu rosto, Marrom?"
  },
  AvgDialog_72012_Content_1 = {
    Text = "Sonho profundo"
  },
  AvgDialog_72012_Content_10 = {
    Text = "Você está dizendo essas coisas estranhas e incompreensíveis de novo."
  },
  AvgDialog_72012_Content_11 = {
    Text = "Não importa se você não entende. Estas não são cargas que crianças devem carregar."
  },
  AvgDialog_72012_Content_12 = {
    Text = "Irmã, eu tenho mais uma coisa a te pedir."
  },
  AvgDialog_72012_Content_13 = {
    Text = "A doença da tia Sarah não pode ser curada, não é?"
  },
  AvgDialog_72012_Content_14 = {
    Text = "Clementine acaricia suavemente a parte de trás da cabeça de Jenkin."
  },
  AvgDialog_72012_Content_15 = {
    Text = "Se %player% perguntar, responda {Male=ele,Female=ela}."
  },
  AvgDialog_72012_Content_16 = {
    Text = "\"No fundo do profundo sonho, aqueles que se recusam a entrar no sonho lhe proporcionarão respostas.\""
  },
  AvgDialog_72012_Content_17 = {
    Text = "Estou partindo, Jenkin."
  },
  AvgDialog_72012_Content_18 = {
    Text = "Ela pulou graciosamente pelas escadas da torre do sino, um par de asas de inseto translúcidas e brilhantes se desdobrando gradualmente atrás dela."
  },
  AvgDialog_72012_Content_19 = {
    Text = "Que esta brisa nos leve ao sonho profundo eterno."
  },
  AvgDialog_72012_Content_2 = {
    Text = "Quem está ali...?!"
  },
  AvgDialog_72012_Content_20 = {Text = "..."},
  AvgDialog_72012_Content_21 = {
    Text = "A Miss Sarah, precisamos nos preparar para partir para a Igreja da Redenção."
  },
  AvgDialog_72012_Content_22 = {
    Text = "Podemos ficar aqui? Estou preocupado que as crianças não consigam me encontrar quando voltarem..."
  },
  AvgDialog_72012_Content_23 = {
    Text = "Tudo bem... mas antes disso, você pode me levar ao escritório do Diretor mais uma vez?"
  },
  AvgDialog_72012_Content_24 = {
    Text = "Eu tenho algo que quero recuperar..."
  },
  AvgDialog_72012_Content_25 = {
    Text = "Você está brincando? Seu escritório está lotado desses caras grandes!"
  },
  AvgDialog_72012_Content_26 = {
    Text = "Mesmo que eu queira negar a tolice de sua busca por coisas materiais neste mundo, no final, não faz diferença para mim para onde você vai."
  },
  AvgDialog_72012_Content_27 = {
    Text = "Um voto a favor, um voto contra, um voto neutro. \nTrês olhares fixos e diretos em você.\n"
  },
  AvgDialog_72012_Content_28 = {
    Text = "Vamos ver o que acontece."
  },
  AvgDialog_72012_Content_29 = {
    Text = "Sarah lutou para se manter, balançando enquanto vacilava em direção à mesa. Seu corpo tropeçou levemente, inclinando-se contra a mesa enquanto ofegava por ar."
  },
  AvgDialog_72012_Content_3 = {
    Text = "Não se preocupe, Jenkin. Sou eu."
  },
  AvgDialog_72012_Content_30 = {Text = "Aqui."},
  AvgDialog_72012_Content_31 = {
    Text = "Com um movimento rápido, a gaveta de madeira foi aberta às pressas, e pulseiras, broches, anéis de ouro e prata antigos... foram espalhados pelo chão."
  },
  AvgDialog_72012_Content_32 = {
    Text = "Sarah deitou no chão, tentando recolhê-los um por um."
  },
  AvgDialog_72012_Content_33 = {
    Text = "Que horas já são? Qual é o sentido de coletar essas coisas? As pessoas lá fora já... Boohoo!"
  },
  AvgDialog_72012_Content_34 = {
    Text = "Fusão - Boneca puxou Jenkins e enfiou uma pequena cabeça estranha na boca dela."
  },
  AvgDialog_72012_Content_35 = {
    Text = "Quando não é sua vez de falar, evite interromper."
  },
  AvgDialog_72012_Content_36 = {
    Text = "Um, um... Ha!"
  },
  AvgDialog_72012_Content_37 = {
    Text = "Ela lutou para retirar o objeto estranho, ofegante por ar."
  },
  AvgDialog_72012_Content_38 = {
    Text = "Ei, mesmo que você queira que eu me cale, pelo menos me traga algo que tenha um gosto melhor! Essa coisa tem gosto de lesmas gosmentas—é tão nojento!"
  },
  AvgDialog_72012_Content_39 = {
    Text = "Desculpe, esqueci que você não tem a capacidade de desligar seus sensores de olfato e paladar."
  },
  AvgDialog_72012_Content_4 = {
    Text = "Irmã Clementine!"
  },
  AvgDialog_72012_Content_40 = {
    Text = "Certo, eu não gosto de ficar em um só lugar o tempo todo."
  },
  AvgDialog_72012_Content_41 = {
    Text = "Você reuniu tudo? Se sim, vamos para a igreja."
  },
  AvgDialog_72012_Content_42 = {
    Text = "Aqueles habilidosos em batalha, limpem o caminho."
  },
  AvgDialog_72012_Content_5 = {
    Text = "A garota pulou alegremente para a frente."
  },
  AvgDialog_72012_Content_6 = {
    Text = "Pequeno Jenkin, a irmã está aqui para se despedir de você."
  },
  AvgDialog_72012_Content_7 = {
    Text = "Por que? Por que está indo embora? Se for por causa daquele cara do Oeste, vou mandar o Brown expulsá{Male=ele,Female=ela}!"
  },
  AvgDialog_72012_Content_8 = {
    Text = "De qualquer forma, {Male=ele,Female=ela} parece perfeitamente capaz de lidar com os monstros sozinho."
  },
  AvgDialog_72012_Content_9 = {
    Text = "Não, claro que não... só ouvi o som do vento no sonho."
  },
  AvgDialog_72013_Content_1 = {
    Text = "Gentil e corajoso"
  },
  AvgDialog_72013_Content_10 = {
    Text = "Brown se virou, pulou no seu ombro e cheirou sua bochecha com seu nariz afiado."
  },
  AvgDialog_72013_Content_11 = {
    Text = "Rato Corajoso..."
  },
  AvgDialog_72013_Content_12 = {
    Text = "Acaricie sua cabeça"
  },
  AvgDialog_72013_Content_13 = {
    Text = "Você acaricia gentilmente sua cabeçinha, e ela olha para cima para responder a você."
  },
  AvgDialog_72013_Content_14 = {
    Text = "Na memória, esta foi a primeira vez que vocês estiveram tão próximos um do outro."
  },
  AvgDialog_72013_Content_15 = {
    Text = "Olhe fixamente para isso"
  },
  AvgDialog_72013_Content_16 = {
    Text = "Ele chiou e virou o rosto, correndo para o capuz de Jenkin, e então espiou cautelosamente para encontrar seu olhar."
  },
  AvgDialog_72013_Content_17 = {
    Text = "Através do corredor à frente está a localização do porão."
  },
  AvgDialog_72013_Content_18 = {
    Text = "Jenkin e Brown estavam sussurrando um para o outro."
  },
  AvgDialog_72013_Content_19 = {
    Text = "Chiado, chiado!"
  },
  AvgDialog_72013_Content_2 = {
    Text = "Aqui a fumaça nunca alcança os tornozelos. \nBrown pula de um lado para o outro nela, deixando para trás pequenas crateras."
  },
  AvgDialog_72013_Content_20 = {
    Text = "O que ele disse?"
  },
  AvgDialog_72013_Content_21 = {
    Text = "Hmm. Perguntei por que estava tão perto de você, e Marrom disse que você era uma pessoa inofensiva."
  },
  AvgDialog_72013_Content_22 = {
    Text = "Os instintos dos animais são sempre muito precisos."
  },
  AvgDialog_72013_Content_23 = {
    Text = "Pare de brincar. Quem sabe que truques você usou."
  },
  AvgDialog_72013_Content_24 = {
    Text = "Jenkin apertou os lábios awkwardly, mas no momento seguinte, seus olhos de repente se arregalaram."
  },
  AvgDialog_72013_Content_25 = {Text = "Cuidado!"},
  AvgDialog_72013_Content_26 = {
    Text = "Jenkin puxou você, sprayando um fluido viscoso pelo seu rosto e espirrando-o nas paredes do corredor. O cheiro acre de decomposição enchia o ar como vapor, quase fazendo você vomitar."
  },
  AvgDialog_72013_Content_27 = {
    Text = "Os corpos corroídos vagantes se reúnem, emitindo gemidos de lamentação ao longo do caminho que se apresenta diante de vocês."
  },
  AvgDialog_72013_Content_28 = {
    Text = "Tch, o caminho que você nos levou é muito estreito; não conseguimos contorná-lo."
  },
  AvgDialog_72013_Content_29 = {
    Text = "É assim que você conseguiu sobreviver durante esse tempo?"
  },
  AvgDialog_72013_Content_3 = {
    Text = "Você realmente vai procurar por algo aqui... um usuário de Yashiro?"
  },
  AvgDialog_72013_Content_30 = {Text = "Claro."},
  AvgDialog_72013_Content_31 = {
    Text = "Este lugar não é adequado... Vamos atrair essas variantes para o pátio."
  },
  AvgDialog_72013_Content_4 = {
    Text = "É um sobrevivente?"
  },
  AvgDialog_72013_Content_5 = {
    Text = "Busquei na casa de pobres, e não há pessoas comuns aqui."
  },
  AvgDialog_72013_Content_6 = {
    Text = "Não... há mais um lugar."
  },
  AvgDialog_72013_Content_7 = {
    Text = "A imagem do porão surge diante de seus olhos."
  },
  AvgDialog_72013_Content_8 = {
    Text = "Aquela escultora quieta, Sanga, ela ainda estará esculpindo aquelas esculturas desafiadoras e absurdas lá?"
  },
  AvgDialog_72013_Content_9 = {
    Text = "Brown, espere por mim!"
  },
  AvgDialog_73775_Content_1 = {Text = "...Ramona."},
  AvgDialog_73775_Content_10 = {
    Text = "Kin? Desculpe, ainda não quero mudar de espécie."
  },
  AvgDialog_73775_Content_11 = {
    Text = "Assim como o resultado do teste anterior, eu mantenho minha humanidade e me considero humano."
  },
  AvgDialog_73775_Content_12 = {
    Text = "...Entendi, é uma pena. Eu não queria chegar tão longe."
  },
  AvgDialog_73775_Content_13 = {
    Text = "Mas para demonstrar a fragilidade humana e ajudar você a escapar deste estado de vida vil, eu tenho que curá-lo—"
  },
  AvgDialog_73775_Content_14 = {
    Text = "...Entendi, que pena. Não queria ter chegado a esse ponto."
  },
  AvgDialog_73775_Content_15 = {
    Text = "<Red:Ajudem...>"
  },
  AvgDialog_73775_Content_16 = {
    Text = "<Red:Mate-me!>"
  },
  AvgDialog_73775_Content_17 = {
    Text = "Veja como o coração humano é fraco, apenas um pouco de hipnose e sugestão pode trazer efeitos irreversíveis."
  },
  AvgDialog_73775_Content_18 = {
    Text = "<Red:Venha comigo, apresse-se e venha comigo...>"
  },
  AvgDialog_73775_Content_19 = {
    Text = "<Red:Vamos... entrar no paraíso juntos.>"
  },
  AvgDialog_73775_Content_2 = {
    Text = "Finalmente, seu ataque é dissipado sem causar danos, e você dá um abraço apertado em \"Ramona\"."
  },
  AvgDialog_73775_Content_20 = {
    Text = "Você sente isso? %player%. Essa é a voz dentro da sua alma; é o verdadeiro instinto e vontade do seu corpo."
  },
  AvgDialog_73775_Content_21 = {
    Text = "<RedShake:Matar-me! Matar-me! Matar-me! Matar-me! Matar-me! Matar-me!>"
  },
  AvgDialog_73775_Content_22 = {
    Text = "<RedBig:Matar \"me\">"
  },
  AvgDialog_73775_Content_23 = {
    Text = "Não sei quando aconteceu, mas Clementine apareceu diante de você, entregando-lhe uma faca afiada. Você a pegou involuntariamente e a colocou sobre seu coração."
  },
  AvgDialog_73775_Content_24 = {
    Text = "Venha, aja agora. Depois disso, você ganhará verdadeira libertação e renascimento."
  },
  AvgDialog_73775_Content_25 = {
    Text = "Descanse... Pense..."
  },
  AvgDialog_73775_Content_26 = {
    Text = "Com sua última gota de força, você crava a faca afiada em Clementine — mas o resultado esperado não ocorre."
  },
  AvgDialog_73775_Content_27 = {Text = "..."},
  AvgDialog_73775_Content_28 = {
    Text = "Hahaha, por que você sempre consegue me dar tantas surpresas? %player%, isso simplesmente, simplesmente me deixa..."
  },
  AvgDialog_73775_Content_29 = {
    Text = "Excitado além da medida."
  },
  AvgDialog_73775_Content_3 = {
    Text = "Espinhos enormes como patas de inseto irrompem do teto e do chão, trespassando seus braços e pernas. Você não solta. Você abraça o fantasma ainda mais forte."
  },
  AvgDialog_73775_Content_30 = {
    Text = "Clementine sorriu, e você finalmente viu claramente: a faca afiada em sua mão se transformou em um espécime de pupa."
  },
  AvgDialog_73775_Content_31 = {
    Text = "Que criança ingênua e adorável, acreditando que tudo o que vê é real."
  },
  AvgDialog_73775_Content_32 = {
    Text = "Aqui está o espaço da mente, meu espaço mental. Aqui, apenas a minha vontade é executada, e apenas a realidade que eu desejo exibir é mostrada."
  },
  AvgDialog_73775_Content_33 = {Text = "..."},
  AvgDialog_73775_Content_34 = {
    Text = "O silêncio é devido a um colapso psicológico? Está tudo bem, %player%. Podemos tentar terapia de colapso."
  },
  AvgDialog_73775_Content_35 = {
    Text = "Isso é verdadeiro tormento, capaz de extrair a dor de todos os pacientes de suas almas com total honestidade."
  },
  AvgDialog_73775_Content_36 = {
    Text = "Tenho muitos, muitos mais desses métodos de cura, suficientes para esmagar sua cognição e razão como humano, transformando gradualmente você em um verdadeiro inseto."
  },
  AvgDialog_73775_Content_37 = {
    Text = "Você esquecerá tudo sobre ser humano, até mesmo esquecendo o significado da palavra \"humano\"."
  },
  AvgDialog_73775_Content_38 = {
    Text = "Quando esse momento chegar, eu lhe darei a prova de cura, levando você a renascer como um @2 Zerg."
  },
  AvgDialog_73775_Content_39 = {
    Text = "Receio que você não chegará a esse momento."
  },
  AvgDialog_73775_Content_4 = {
    Text = "Eu vou voltar. Vou encontrar um jeito. Apenas espere por mim..."
  },
  AvgDialog_73775_Content_40 = {
    Text = "Olhe para baixo e veja seu peito."
  },
  AvgDialog_73775_Content_41 = {
    Text = "Clementine baixa a cabeça ao ouvir, vendo um objeto dentado pressionado contra seu peito."
  },
  AvgDialog_73775_Content_42 = {
    Text = "Chave de prata?"
  },
  AvgDialog_73775_Content_43 = {
    Text = "Sim, a Chave de prata. Após observação e raciocínio, acredito que você é o núcleo deste sanatório."
  },
  AvgDialog_73775_Content_44 = {
    Text = "Você quer forçosamente se conectar comigo? Como um Guardião, você deveria entender os perigos..."
  },
  AvgDialog_73775_Content_45 = {
    Text = "Eu entendo."
  },
  AvgDialog_73775_Content_46 = {
    Text = "Ao dizer isso, você não pôde deixar de rir. Se nesse mundo, a Professora Boneca definitivamente o criticaria por seu comportamento imprudente, e Ramona o persuadiria a procurar melhores escolhas juntos."
  },
  AvgDialog_73775_Content_47 = {
    Text = "Mas aqui, só existe eu."
  },
  AvgDialog_73775_Content_48 = {
    Text = "William... Eu não quebrei minha promessa. Eu salva todos neste sanatório."
  },
  AvgDialog_73775_Content_49 = {
    Text = "Dentro do tremor da Chave de prata, uma intensa luz branca irrompe do coração prateado de Clementine, inundando todo o quarto—"
  },
  AvgDialog_73775_Content_5 = {
    Text = "O fantasma se dissolve em névoa e desaparece. Clementine retraiu a projeção."
  },
  AvgDialog_73775_Content_50 = {
    Text = "Então, a chave de prata caiu e tanto você quanto Clementine desmoronaram no chão."
  },
  AvgDialog_73775_Content_51 = {
    Text = "Você realmente acha que pode invadir o sanatório se conectando a mim à força? Que ideia louca, mas eu gosto."
  },
  AvgDialog_73775_Content_52 = {
    Text = "É uma pena que este seja o meu espaço mental, %player%, parece que você está destinado a se tornar meu parente."
  },
  AvgDialog_73775_Content_53 = {
    Text = "A seguir, é o momento de tratamento em profundidade especialmente personalizado para você.\nClaro, para garantir o efeito do tratamento, escondi seus pequenos itens."
  },
  AvgDialog_73775_Content_54 = {
    Text = "Mostre-me sua dor, sua luta, a pequena criatura prestes a se transformar —"
  },
  AvgDialog_73775_Content_6 = {
    Text = "Sentimento... que escolha curiosa. Mas valeu a dor?"
  },
  AvgDialog_73775_Content_7 = {
    Text = "Você viu a verdade do universo. Você a encarou. Poderia ser muito mais. Poderia ser como eu—um grande ser do cosmos."
  },
  AvgDialog_73775_Content_8 = {
    Text = "Eu já vi muitos humanos, mas nenhum nunca me fez sentir tal desejo —"
  },
  AvgDialog_73775_Content_9 = {
    Text = "Você está destinado a se tornar meu parente, você deve se tornar meu parente."
  },
  AvgDialog_73776_Content_1 = {
    Text = "Campeão solitário"
  },
  AvgDialog_73776_Content_10 = {
    Text = "Por favor, tome um assento —"
  },
  AvgDialog_73776_Content_11 = {
    Text = "Uma cadeira aparece repentinamente atrás de você, te levando a deslizar em frente a Clementine."
  },
  AvgDialog_73776_Content_12 = {
    Text = "Você rapidamente examina a área—um sofá, uma mesa e espécimes de insetos."
  },
  AvgDialog_73776_Content_13 = {
    Text = "Sofá, mesa de escritório, são coisas muito comuns, improvável. O núcleo do espaço mental certamente será um pouco mais especial. Então só resta..."
  },
  AvgDialog_73776_Content_14 = {
    Text = "O que você está olhando pelo canto do olho? Hmm, uma amostra de inseto. Pode ser que você também tenha interesse em insetos?"
  },
  AvgDialog_73776_Content_15 = {Text = "..."},
  AvgDialog_73776_Content_16 = {
    Text = "Está tudo bem se você não quiser responder. Eu já disse antes, sou um Doutor psicologicamente compassivo que pode tolerar pequenos defeitos em meus pacientes."
  },
  AvgDialog_73776_Content_17 = {
    Text = "Claro, não me importo em dar aos pacientes algumas dicas atenciosas, como os itens que você está procurando não estão nas aquelas amostras."
  },
  AvgDialog_73776_Content_18 = {
    Text = "Você desvia o olhar dos espécimes de insetos e enfrenta Clementine."
  },
  AvgDialog_73776_Content_19 = {
    Text = "Clementine, qual é o propósito de construir este sanatório? Qual é aquele experimento crucial que exige tantas sacrifícios?"
  },
  AvgDialog_73776_Content_2 = {Text = "Bang..."},
  AvgDialog_73776_Content_20 = {
    Text = "Tantas pessoas morreram aqui, resultando em tantas tragédias. E você afirma que isso não é um matadouro, mas sim um sanatório para a mente. Então, quem exatamente deveria estar sendo curado?"
  },
  AvgDialog_73776_Content_21 = {
    Text = "Esta pergunta é realmente importante? Pensei que você não se importaria com esses pequenos assuntos depois de enfrentar aquela grande existência."
  },
  AvgDialog_73776_Content_22 = {
    Text = "Isso não é uma pequena questão. Quando envolve a vida humana, nunca foi uma pequena questão!"
  },
  AvgDialog_73776_Content_23 = {
    Text = "É claro que aqueles que alcançam a redenção aqui não são os pacientes, pois são meras vítimas. E excluindo as respostas erradas, o que resta é a certa."
  },
  AvgDialog_73776_Content_24 = {
    Text = "O que este sanatório realmente cura é você, Clementine, a dona deste sanatório."
  },
  AvgDialog_73776_Content_25 = {
    Text = "Diga-me, que tipo de trauma psicológico requer tantas vidas para ser preenchido?"
  },
  AvgDialog_73776_Content_26 = {
    Text = "Clementine mostra uma expressão confusa. Ela não entende de onde vem sua raiva, mas logo começa a rir."
  },
  AvgDialog_73776_Content_27 = {
    Text = "Se este é seu pedido, então eu concordo. Você, que enfrentou aquela grande existência, está qualificado para se tornar meu parente."
  },
  AvgDialog_73776_Content_28 = {
    Text = "Sobre o que você está falando..."
  },
  AvgDialog_73776_Content_29 = {
    Text = "Apenas precisamos fazer um pequeno teste primeiro."
  },
  AvgDialog_73776_Content_3 = {
    Text = "Outra explosão ocorreu, atraindo todas as criaturas no sanatório e limpando seu caminho para o quarto de Clementine."
  },
  AvgDialog_73776_Content_30 = {
    Text = "Não se preocupe, é realmente apenas um pequeno teste, com o objetivo de avaliar sua autoconsciência e os vestígios de humanidade."
  },
  AvgDialog_73776_Content_31 = {
    Text = "À medida que as palavras de Clementine fluem, uma figura familiar, embora invisível, aparece gradualmente diante de você."
  },
  AvgDialog_73776_Content_32 = {Text = "Ramona!!!"},
  AvgDialog_73776_Content_33 = {
    Text = "Sua memória está cheia da figura desta garota, então acho que você deve estar ansioso para encontrá-la—"
  },
  AvgDialog_73776_Content_34 = {
    Text = "Não precisa me agradecer, por favor, aproveite este momento de reunião."
  },
  AvgDialog_73776_Content_4 = {
    Text = "William... Eu não deixarei seu sacrifício em vão."
  },
  AvgDialog_73776_Content_5 = {
    Text = "Definitivamente encontrarei o núcleo do asilo e o destruirei."
  },
  AvgDialog_73776_Content_6 = {
    Text = "Finalmente, você está em frente àquela porta—respirando fundo, você está pronto para enfrentar quem puxa as cordas no sanatório."
  },
  AvgDialog_73776_Content_7 = {
    Text = "Abra a porta do quarto de Clementine"
  },
  AvgDialog_73776_Content_8 = {
    Text = "O sofá familiar usado para consultas psicológicas, mesa de escritório, espécimes de insetos com uma aparência estranhamente bonita, e a sorridente Clementine."
  },
  AvgDialog_73776_Content_9 = {
    Text = "Bem-vindo à minha sala de consulta, %player%, eu esperei muito tempo por você."
  },
  AvgDialog_73777_Content_1 = {
    Text = "Adeus, mundo ardente"
  },
  AvgDialog_73777_Content_10 = {
    Text = "É apenas que o estado espiritual de Clementine é instável. Você está preocupado que o Vazio vai corroer a Prata de Clementine, ou você está preocupado com o que pode acontecer com Clementine ao acordar?"
  },
  AvgDialog_73777_Content_11 = {
    Text = "Você ainda não entende? Quando capturamos os fragmentos da consciência de Clementine, isso já representa a escolha e a vontade dela."
  },
  AvgDialog_73777_Content_12 = {
    Text = "Sim, tanto minha vontade quanto minha escolha são suas, %player%."
  },
  AvgDialog_73777_Content_13 = {
    Text = "Clementine!"
  },
  AvgDialog_73777_Content_14 = {
    Text = "Como você está se sentindo? Precisa da minha ajuda para ajustar seu corpo?"
  },
  AvgDialog_73777_Content_15 = {
    Text = "Eu não acho que precise disso por enquanto. Estou indo muito bem, talvez melhor do que nunca."
  },
  AvgDialog_73777_Content_16 = {Text = "..."},
  AvgDialog_73777_Content_17 = {
    Text = "%player%, pelo seu micro-expressão, parece que você tem muito a me dizer."
  },
  AvgDialog_73777_Content_18 = {
    Text = "Por favor, sinta-se à vontade para falar. Eu sou um ouvinte profissional."
  },
  AvgDialog_73777_Content_19 = {
    Text = "Nesse dia, você deliberadamente falou essas palavras para eu ouvir, não falou?"
  },
  AvgDialog_73777_Content_2 = {Text = "..."},
  AvgDialog_73777_Content_20 = {
    Text = "Você está se referindo a \"humanidade e amor\"... Claro, há alguns elementos deliberados, mas eu também não menti."
  },
  AvgDialog_73777_Content_21 = {
    Text = "No final, eu não desferi um golpe fatal, não é? Como um Guardião, você deveria entender as consequências aterrorizantes de um Despertador realmente perdendo o controle da melhor maneira."
  },
  AvgDialog_73777_Content_22 = {
    Text = "Eu entendo, e é exatamente por isso que escolho tentar te despertar."
  },
  AvgDialog_73777_Content_23 = {
    Text = "Obrigado pela sua escolha, permitindo que eu renasça mais uma vez."
  },
  AvgDialog_73777_Content_24 = {Text = "Apenas..."},
  AvgDialog_73777_Content_25 = {
    Text = "Eu disse, por favor, fale livremente. Para você, eu ainda tenho aquele pouco de paciência e tolerância."
  },
  AvgDialog_73777_Content_26 = {
    Text = "...Clementine, você agora tem uma nova identidade. Você pode ver o verdadeiro mundo e viver a nova vida que deseja."
  },
  AvgDialog_73777_Content_27 = {
    Text = "Você pode fazer o que quiser, mas há apenas um ponto—"
  },
  AvgDialog_73777_Content_28 = {
    Text = "Não faça mal aos inocentes. Suponho que é isso que você quer dizer."
  },
  AvgDialog_73777_Content_29 = {
    Text = "Após entender o estilo de vida do enxame @2, sinto que é necessário enfatizar este ponto."
  },
  AvgDialog_73777_Content_3 = {
    Text = "Um som nauseante e úmido de dilaceração se ergue no ar. Enormes patas de aranha irrompem pelos corpos dos oficiais e dos transeuntes, espirrando sangue espesso com cheiro de ferro por todo você."
  },
  AvgDialog_73777_Content_30 = {
    Text = "Claro que isso não é uma tarefa difícil. Um psicólogo cheio do espírito de amor não se importaria com a identidade do paciente."
  },
  AvgDialog_73777_Content_31 = {
    Text = "Sadistas, personalidades desviantes, indivíduos imorais... Neste mundo mórbido, há muitos pacientes em necessidade de tratamento; não há necessidade de perturbar a vida dos inocentes."
  },
  AvgDialog_73777_Content_32 = {
    Text = "A coisa mais importante é que quero tentar fazer algumas mudanças."
  },
  AvgDialog_73777_Content_33 = {
    Text = "Eu acho que você quer dizer \"se tornar seu verdadeiro eu.\""
  },
  AvgDialog_73777_Content_34 = {
    Text = "Sim, não como um humano ou um inseto, mas como um Despertador, um eu recém-formado, em busca da minha verdadeira identidade."
  },
  AvgDialog_73777_Content_35 = {
    Text = "Claro, isso não significa que vou negligenciar minhas responsabilidades; continuarei a vigiar o Comitê lá."
  },
  AvgDialog_73777_Content_36 = {
    Text = "A atenção contínua... Você está insinuando que algumas ações do Comitê afetarão a existência deste mundo?"
  },
  AvgDialog_73777_Content_37 = {
    Text = "Talvez, mas com base no que observei até agora, não posso tirar uma conclusão ainda."
  },
  AvgDialog_73777_Content_38 = {
    Text = "Se você não se importa, eu gostaria de voltar e continuar espreitando até que a investigação produza resultados. Claro, estes resultados serão compartilhados com você."
  },
  AvgDialog_73777_Content_39 = {
    Text = "Então eu vou lhe incomodar com isso. Além disso..."
  },
  AvgDialog_73777_Content_40 = {
    Text = "William, está correto?"
  },
  AvgDialog_73777_Content_41 = {
    Text = "Sim. Todas as vítimas do sanatório foram devidamente tratadas, mas eu não encontrei William; ele..."
  },
  AvgDialog_73777_Content_42 = {
    Text = "Quanto a William, talvez eu tenha algumas pistas."
  },
  AvgDialog_73777_Content_43 = {
    Text = "Fusão - Boneca pegou um caderno. Apesar de estar muito danificado, você ainda conseguiu reconhecer algumas palavras: Cemitério dos Restos Mortais."
  },
  AvgDialog_73777_Content_44 = {
    Text = "Então, isso significa que o próximo plano de William é ir até este cemitério? Por quê?"
  },
  AvgDialog_73777_Content_45 = {
    Text = "Esta é a razão pela qual você precisa investigar."
  },
  AvgDialog_73777_Content_46 = {
    Text = "Parece que desta vez, eu tenho que agir sozinho novamente."
  },
  AvgDialog_73777_Content_47 = {
    Text = "Sem problemas, agora eu vou..."
  },
  AvgDialog_73777_Content_48 = {
    Text = "Boneca: Inferno parou suas palavras com seu olhar."
  },
  AvgDialog_73777_Content_49 = {
    Text = "Eu disse, da próxima vez, carregarei todas as armas que conheço no monitor."
  },
  AvgDialog_73777_Content_5 = {
    Text = "Se nada ocupar sua mente, você pode reler o relatório @2 Zerg."
  },
  AvgDialog_73777_Content_50 = {
    Text = "Agora é hora de colocar essa frase em prática."
  },
  AvgDialog_73777_Content_51 = {
    Text = "Boneca: Inferno respondeu com ação. Quando você percebeu, já tinha sido puxada para fora da sala."
  },
  AvgDialog_73777_Content_52 = {
    Text = "Clementine te observou se afastar, um sorriso silencioso em seu rosto; então ela se endireitou e virou-se para o relatório sobre a corrida de insetos."
  },
  AvgDialog_73777_Content_53 = {
    Text = "Ela não falou, apenas ficou em silêncio por muito tempo."
  },
  AvgDialog_73777_Content_54 = {
    Text = "Quando ela saiu, uma rajada de vento soprou e virou o relatório na mesa sobre os @2 Zerg."
  },
  AvgDialog_73777_Content_55 = {
    Text = "\"......anos atrás, os @2 Zerg fizeram sua Chegada na cidade @4 de @2......capturando humanos e realizando cruéis @2 realizações, criando Relíquias profanas, humanos com linhagem Zerg......\""
  },
  AvgDialog_73777_Content_56 = {
    Text = "\"A Dissolução aparece... um grande número de insetos morre, os @2 insetos restantes abandonam seus relíquias e partem... as relíquias, devido à sua natureza @2, são mais propensas à @4 de @2 e sofrem da doença—Dissolução.\""
  },
  AvgDialog_73777_Content_57 = {
    Text = "\"As criações desconhecem a verdade... acham que foi a forma de vida humana que causou a doença misteriosa, e, seguindo os textos antigos deixados pelos zergs, realizam o <Yellow:Ritual da Vida>, tentando retornar aos zergs@2, uma existência transcendental, causando... um desastre...\""
  },
  AvgDialog_73777_Content_58 = {
    Text = "\"......O número de vítimas chegou a @1 mil, incluindo Velho John (72 anos), Bella (6 anos), Berkeley (23 anos), etc.... todos se tornaram carne @2, morrendo em dor...\""
  },
  AvgDialog_73777_Content_59 = {
    Text = "\"Entre eles, o pai de Clementine, Allen, é o mais especial... Para se reunir com sua filha, Allen deliberadamente se infectou com Dissolução... e realizou a <Yellow:Cerimônia da Vida>...\""
  },
  AvgDialog_73777_Content_6 = {
    Text = "Estou tendo dificuldades para ler qualquer texto..."
  },
  AvgDialog_73777_Content_60 = {Text = "Há um dia"},
  AvgDialog_73777_Content_61 = {
    Text = "Na noite profunda, no deserto museu de cera, duas figuras apareceram."
  },
  AvgDialog_73777_Content_62 = {
    Text = "Albino, esse plano falhou. Você sabe quem deve assumir a principal responsabilidade?"
  },
  AvgDialog_73777_Content_63 = {
    Text = "Deixe-me pensar... Do ponto de vista estratégico, deve ser você."
  },
  AvgDialog_73777_Content_64 = {
    Text = "Mas de uma perspectiva tática, talvez eu também deva assumir alguma responsabilidade."
  },
  AvgDialog_73777_Content_65 = {
    Text = "Herbert acariciou silenciosamente a testa de Galatea. Da testa ao pescoço, e então à coluna vertebral."
  },
  AvgDialog_73777_Content_66 = {
    Text = "Quando Galatea abagitava feliz sua cauda, Herbert falou novamente."
  },
  AvgDialog_73777_Content_67 = {
    Text = "Eu acho que devemos elevar o nível de perigo de %player% ao máximo. Para isso, precisamos dos dados de %hisorher%, dados completos."
  },
  AvgDialog_73777_Content_68 = {
    Text = "Desta vez, Albino, acredito que você não negligenciará mais suas obrigações. Caso contrário — você não terá mais feriados."
  },
  AvgDialog_73777_Content_69 = {
    Text = "...Certo, certo, você ganhou."
  },
  AvgDialog_73777_Content_7 = {
    Text = "Boneca: Inferno, o experimento acordado de Clementine terá sucesso?"
  },
  AvgDialog_73777_Content_70 = {
    Text = "Então e quanto a Clementine? Sua Prata foi levada por %player%."
  },
  AvgDialog_73777_Content_71 = {
    Text = "Albino, não deixe que o instinto de caça desvie seu alvo. O que importa é o plano."
  },
  AvgDialog_73777_Content_72 = {
    Text = "Entendido. Agora irei coletar informações sobre %player%."
  },
  AvgDialog_73777_Content_73 = {
    Text = "Observando o Albino partir, Herbert tocou a testa de Galatea mais uma vez."
  },
  AvgDialog_73777_Content_74 = {
    Text = "Galateia, tenha paciência. Vamos vê-lo(a) novamente."
  },
  AvgDialog_73777_Content_75 = {
    Text = "Três dias atrás"
  },
  AvgDialog_73777_Content_76 = {
    Text = "Confirmando que todas as vítimas foram resgatadas, o Domínio desapareceu completamente, e a crise foi resolvida."
  },
  AvgDialog_73777_Content_77 = {
    Text = "Na floresta do domínio Clementine, William rapidamente tirou papel e caneta para escrever algo."
  },
  AvgDialog_73777_Content_78 = {
    Text = "Então, suas ações congelaram de repente."
  },
  AvgDialog_73777_Content_79 = {
    Text = "Quanto a %player%... %player% não deveria existir neste mundo. O motivo da aparição de %player% é desconhecido, a motivação é incerta, e as consequências esperadas permanecem um mistério."
  },
  AvgDialog_73777_Content_8 = {
    Text = "Você está questionando as capacidades de pesquisa de um gênio?"
  },
  AvgDialog_73777_Content_80 = {
    Text = "Em conclusão, mais informações são necessárias para entender as anomalias do mundo."
  },
  AvgDialog_73777_Content_81 = {
    Text = "William guardou o papel e a caneta, olhando para o horizonte. Era lá que %player% seria resgatado e partiria."
  },
  AvgDialog_73777_Content_82 = {
    Text = "Mas logo, William voltou de suas recordações. Percebendo o que precisava fazer, ele se virou mais uma vez e desapareceu na floresta."
  },
  AvgDialog_73777_Content_83 = {
    Text = "Apenas os ecos levados pelo vento permanecem como prova de sua presença passada."
  },
  AvgDialog_73777_Content_84 = {
    Text = "Que a Chave de Prata nos guie"
  },
  AvgDialog_73777_Content_85 = {
    Text = "Para salvar este mundo consumido em chamas"
  },
  AvgDialog_73777_Content_9 = {
    Text = "Claro que não, é apenas..."
  },
  AvgDialog_73778_Content_1 = {Text = "Hmm—"},
  AvgDialog_73778_Content_10 = {
    Text = "Você está mentindo, você está mentindo!"
  },
  AvgDialog_73778_Content_11 = {
    Text = "A incapacidade de aceitar leva a uma recusa em reconhecer a verdade? Ah, verdadeiramente outro eu."
  },
  AvgDialog_73778_Content_12 = {
    Text = "Mas agora eu me despedi da minha fragilidade, tornando-me uma existência maior e mais forte."
  },
  AvgDialog_73778_Content_13 = {
    Text = "Você se lembra da razão da sua criação? Isso mesmo, foi %player% quem te criou, usando @3—"
  },
  AvgDialog_73778_Content_14 = {
    Text = "O autor sorriu e apontou para seu peito, o local do coração."
  },
  AvgDialog_73778_Content_15 = {
    Text = "Aqui, o subconsciente que não está sob meu controle, aquelas coisas carregadas que descartei—ou seja, você—responderam a isso."
  },
  AvgDialog_73778_Content_16 = {
    Text = "Isso trouxe muitos problemas; até mesmo este espaço começou a descer ao caos, o que é bastante preocupante."
  },
  AvgDialog_73778_Content_17 = {
    Text = "Então, por favor, desapareça silenciosamente; depois de lidar com você, ainda preciso continuar tratando %player%."
  },
  AvgDialog_73778_Content_18 = {
    Text = "Não machuque {Male=ele,Female=ela}..."
  },
  AvgDialog_73778_Content_19 = {
    Text = "Os braços da vítima agarraram-se firmemente a outro eu, e a resposta estava manchada de sangue."
  },
  AvgDialog_73778_Content_2 = {
    Text = "Em um quarto isolado da cidade onde ninguém se importa, uma perseguição unilateral está ocorrendo."
  },
  AvgDialog_73778_Content_20 = {
    Text = "A mão do agressor perfura a carne de outro, alcançando as vísceras, pronta para cortar o último fio de vida."
  },
  AvgDialog_73778_Content_21 = {
    Text = "Ah, finalmente tudo está chegando ao fim..."
  },
  AvgDialog_73778_Content_22 = {
    Text = "Fogo! Fogo! Apague rapidamente!"
  },
  AvgDialog_73778_Content_23 = {
    Text = "De repente, ouve-se um barulho do lado de fora da porta. \nClementine para o que está fazendo, fica pensativa por alguns segundos e, de repente, exibe um sorriso repleto de maldade."
  },
  AvgDialog_73778_Content_24 = {
    Text = "Clementine, outra versão de mim, %player%, veio te ver."
  },
  AvgDialog_73778_Content_25 = {
    Text = "Fogo! Fogo! Apague rapidamente!"
  },
  AvgDialog_73778_Content_26 = {
    Text = "No meio do caos, você se esconde na escuridão, apenas para ver Clementine sair antes de correr para dentro da casa."
  },
  AvgDialog_73778_Content_27 = {
    Text = "Clementine, estou aqui para salvar —"
  },
  AvgDialog_73778_Content_28 = {
    Text = "Sua voz para abruptamente porque a gravemente ferida Clementine não pode mais escapar com você."
  },
  AvgDialog_73778_Content_29 = {
    Text = "Ela está à beira da morte."
  },
  AvgDialog_73778_Content_3 = {
    Text = "Os movimentos do agressor são suaves, quase acariciando, mas os meios são extraordinariamente cruéis."
  },
  AvgDialog_73778_Content_30 = {Text = "..."},
  AvgDialog_73778_Content_31 = {
    Text = "%player%...?"
  },
  AvgDialog_73778_Content_32 = {
    Text = "Estou aqui."
  },
  AvgDialog_73778_Content_33 = {
    Text = "Clementine usou seu último resquício de força para olhar para você e chamou seu nome. Você então se aproximou e segurou sua mão."
  },
  AvgDialog_73778_Content_34 = {
    Text = "Obrigado... por vir me salvar..."
  },
  AvgDialog_73778_Content_35 = {
    Text = "...Não há necessidade de me agradecer. Eu apenas segurei..."
  },
  AvgDialog_73778_Content_36 = {
    Text = "Consciência de si mesmo humano e... a Alma?"
  },
  AvgDialog_73778_Content_37 = {
    Text = "Clementine sorriu para você pela última vez; o frio da perda de sangue a fez se inclinar involuntariamente em seus braços."
  },
  AvgDialog_73778_Content_38 = {
    Text = "Então frio... Eu vou morrer? Mas eu ainda não vi verdadeiramente este mundo..."
  },
  AvgDialog_73778_Content_39 = {
    Text = "Eu quero ver o verdadeiro mundo humano e viver como... uma pessoa comum... nem que seja por um momento..."
  },
  AvgDialog_73778_Content_4 = {
    Text = "Por que... me tratar assim..."
  },
  AvgDialog_73778_Content_40 = {
    Text = "Eu quero... me libertar do meu casulo... e renascer..."
  },
  AvgDialog_73778_Content_41 = {
    Text = "Uma lágrima cai do canto de seu olho. Essa é a última conexão de Clementine com este mundo enquanto ela gradualmente respira seu último."
  },
  AvgDialog_73778_Content_42 = {
    Text = "...Boa noite, Clementine."
  },
  AvgDialog_73778_Content_43 = {
    Text = "Você arruma o cabelo bagunçado de Clementine e limpa o sangue dela."
  },
  AvgDialog_73778_Content_44 = {
    Text = "Você sabe que aquele par de olhos não abrirá novamente; você está apenas dando a ela a dignidade e a graça final."
  },
  AvgDialog_73778_Content_45 = {
    Text = "Após tudo isso, você se virou em direção à porta e falou ao ar."
  },
  AvgDialog_73778_Content_46 = {
    Text = "Clementine, você não vai coletar a rede? Você usou outra versão de si mesma como armadilha, e eu caí bem nela."
  },
  AvgDialog_73778_Content_47 = {
    Text = "Armadilha? Então é assim que você interpreta minhas ações."
  },
  AvgDialog_73778_Content_48 = {
    Text = "Clementine apareceu do nada na sala, usando seu sorriso habitual."
  },
  AvgDialog_73778_Content_49 = {
    Text = "Mas na realidade, eu estou considerando você apenas por compaixão e bondade de um Doutor."
  },
  AvgDialog_73778_Content_5 = {
    Text = "Não tenha medo, isso é apenas um trabalho necessário para corrigir erros."
  },
  AvgDialog_73778_Content_50 = {
    Text = "Você veio aqui só para vê-la? Quanto a mim, eu não recusei seu pedido e até deixei algum espaço sob medida para você."
  },
  AvgDialog_73778_Content_51 = {
    Text = "...Pare de distorcer os conceitos aqui. Você sabe muito bem que meu verdadeiro propósito é salvá-la, não apenas vê-la."
  },
  AvgDialog_73778_Content_52 = {
    Text = "Oh não, você me encontrou. Mas não já alcancei meu objetivo?"
  },
  AvgDialog_73778_Content_53 = {
    Text = "Essas escalas de verme devem doer. Suporte um pouco mais, em breve, tudo chegará ao fim."
  },
  AvgDialog_73778_Content_54 = {
    Text = "Clementine riu, e ao mesmo tempo, o grito aterrorizante invadiu seu Corpo e Alma em um instante."
  },
  AvgDialog_73778_Content_55 = {
    Text = "Você não resiste, permitindo-se escorregar para a inconsciência."
  },
  AvgDialog_73778_Content_56 = {
    Text = "%player%, bem-vindo ao estágio final do tratamento, <Yellow: Cerimônia da Vida>."
  },
  AvgDialog_73778_Content_57 = {
    Text = "Quando tudo terminar, você experimentará verdadeira transformação e renascimento — meu amigo, meu sangue."
  },
  AvgDialog_73778_Content_6 = {Text = "Erro...?"},
  AvgDialog_73778_Content_7 = {
    Text = "Sim, sua existência é um erro. Ou devo ser mais claro, você não deveria existir."
  },
  AvgDialog_73778_Content_8 = {
    Text = "O verdadeiro você já está morto há muito tempo; o você de hoje... Sinto muito, você é meramente um acidente."
  },
  AvgDialog_73778_Content_9 = {
    Text = "Meu comportamento atual é apenas para colocar este acidente de volta nos trilhos, encerrando \"Clementine,\" que é nosso estado de divisão."
  },
  AvgDialog_73779_Content_1 = {
    Text = "Doppelgänger"
  },
  AvgDialog_73779_Content_10 = {
    Text = "Pontos de luz da consciência? Por que o espaço mental de Clementine responde ativamente aos meus pontos de luz da consciência?"
  },
  AvgDialog_73779_Content_11 = {
    Text = "Wait, the breath on the light spot feels a bit familiar..."
  },
  AvgDialog_73779_Content_12 = {
    Text = "Isto é, Clementine!?"
  },
  AvgDialog_73779_Content_13 = {
    Text = "Você de repente corta a conexão, paralisado no lugar."
  },
  AvgDialog_73779_Content_14 = {
    Text = "Os insetos da noite chilreavam incessantemente, lavando o medo e a dúvida do seu coração."
  },
  AvgDialog_73779_Content_15 = {
    Text = "O ponto de luz da consciência que veio de antes não se dividiu, nem estava incompleto. Em outras palavras... Clementine respondeu ativamente a mim."
  },
  AvgDialog_73779_Content_16 = {
    Text = "Não apenas algumas Clementines, mas a existência de \"Clementine\" em si, a existência completa respondeu a mim!"
  },
  AvgDialog_73779_Content_17 = {
    Text = "Essa cognição deixou você confuso, mas logo você não teve tempo para pensar enquanto uma certa consciência retrocedia através do link anterior até você."
  },
  AvgDialog_73779_Content_18 = {
    Text = "Salve-me... %player%, por favor, salve-me..."
  },
  AvgDialog_73779_Content_19 = {
    Text = "Eu... não quero morrer, eu não quero morrer..."
  },
  AvgDialog_73779_Content_2 = {
    Text = "A profunda noite da cidade não é tranquila, pois aqui, o canto dos insetos existe eternamente."
  },
  AvgDialog_73779_Content_20 = {
    Text = "Por um momento, parece absurdo e risível — como se o carcereiro que controla toda a prisão estivesse implorando por ajuda a um prisioneiro."
  },
  AvgDialog_73779_Content_21 = {
    Text = "Então quem está perseguindo essa Clementine? A resposta, só posso pensar em outra Clementine."
  },
  AvgDialog_73779_Content_22 = {
    Text = "Esta é a batalha entre Clementines... A coisa mais importante para eu fazer agora é aproveitar esta oportunidade e encontrar a Chave Prata."
  },
  AvgDialog_73779_Content_23 = {
    Text = "William e todos no sanatório estão esperando meu resgate."
  },
  AvgDialog_73779_Content_24 = {
    Text = "Você tenta se explicar, mas uma certa imagem gradualmente surge em sua mente."
  },
  AvgDialog_73779_Content_25 = {
    Text = "Aqui só estamos nós dois humanos, e eu sempre quis um amigo."
  },
  AvgDialog_73779_Content_26 = {
    Text = "Embora os humanos possam ser cruéis, eles também possuem um lado sincero e bondoso, ajudando-se mutuamente, apoiando uns aos outros, superando dificuldades juntos e acolhendo uma manhã brilhante e um futuro esperançoso."
  },
  AvgDialog_73779_Content_27 = {
    Text = "E este é o testemunho—testemunhando nossa assistência mútua, repleta das virtudes da humanidade."
  },
  AvgDialog_73779_Content_28 = {Text = "..."},
  AvgDialog_73779_Content_29 = {Text = "..."},
  AvgDialog_73779_Content_3 = {
    Text = "Mas isso é bom para você; pode abafar o som dos seus passos ao se mover."
  },
  AvgDialog_73779_Content_30 = {
    Text = "Você tira o espécime de pupa que Clementine lhe deu, olha para ele enquanto inspira profundamente e solta um longo suspiro."
  },
  AvgDialog_73779_Content_31 = {
    Text = "A racionalidade é realmente preciosa, mas a moralidade e a bondade também estão entre as distinções entre humanos e bestas, não estão?"
  },
  AvgDialog_73779_Content_4 = {
    Text = "Certo, esta posição deve funcionar. Não vai se sobrepor à área de exploração anterior e está longe da casa da Clementine."
  },
  AvgDialog_73779_Content_5 = {
    Text = "Agora feche seus olhos e sinta a Chave de Prata..."
  },
  AvgDialog_73779_Content_6 = {
    Text = "Enquanto a Chave de prata ainda estiver dentro do espaço mental de Clementine, eu deve ser capaz de senti-la."
  },
  AvgDialog_73779_Content_7 = {
    Text = "Claro, a intensidade do rastreamento espiritual deve ser minimizada e só pode detectar a existência que responde ativamente. No entanto, isso é suficiente para encontrar a Chave Prata."
  },
  AvgDialog_73779_Content_8 = {
    Text = "Você se afunda nas profundezas do espírito, sua consciência se transforma em fios, espalhando-se cautelosamente e explorando toda a cidade."
  },
  AvgDialog_73779_Content_9 = {
    Text = "Em breve, um ponto de luz emitindo uma aura suave respondeu ao seu chamado."
  },
  AvgDialog_73780_Content_1 = {
    Text = "Animal social"
  },
  AvgDialog_73780_Content_10 = {
    Text = "Você, tendo sofrido o ataque de Clementine e o custo de vincular o espaço mental, cai completamente no chão."
  },
  AvgDialog_73780_Content_100 = {
    Text = "Pai, não precisa se desculpar comigo\nser sua filha já é felicidade suficiente"
  },
  AvgDialog_73780_Content_101 = {Text = "Boom—"},
  AvgDialog_73780_Content_102 = {
    Text = "O colapso do espaço mental continua, a Clementine que constantemente se dissipa enxuga suas lágrimas e lhe mostra um sorriso complexo."
  },
  AvgDialog_73780_Content_103 = {
    Text = "Que terapia psicológica incrível. Como paciente, acho que preciso expor tudo."
  },
  AvgDialog_73780_Content_104 = {
    Text = "Quando ela se fundiu comigo, ela trouxe de volta... o que você chama de humanidade e amor."
  },
  AvgDialog_73780_Content_105 = {
    Text = "Ela quer te proteger, e isso me afetou."
  },
  AvgDialog_73780_Content_106 = {
    Text = "Posso me matar, mas eu... não posso realmente ferir aqueles que quero proteger."
  },
  AvgDialog_73780_Content_107 = {
    Text = "<Shake:Clementine...>"
  },
  AvgDialog_73780_Content_108 = {
    Text = "Você não termina de falar. De repente, Clementine te abraça e dá um empurrão forte—"
  },
  AvgDialog_73780_Content_109 = {
    Text = "Não há necessidade de despedidas. Depois de receber tratamento psicológico, os pacientes devem partir."
  },
  AvgDialog_73780_Content_11 = {
    Text = "Mas você não se permite cair antes de salvar todas as vítimas presas no sanatório."
  },
  AvgDialog_73780_Content_110 = {
    Text = "O som do espaço se despedaçando parou em um instante, e tudo desapareceu como um sonho."
  },
  AvgDialog_73780_Content_111 = {
    Text = "No último momento, você foi empurrado por Clementine da dimensão totalmente destruída de volta ao mundo real."
  },
  AvgDialog_73780_Content_112 = {
    Text = "Este é um tratamento psicológico bem-sucedido... para mim."
  },
  AvgDialog_73780_Content_113 = {
    Text = "A última voz de Clementine ecoa em seu coração.\nFoi um momento de abraço, o sussurro dela em seu ouvido."
  },
  AvgDialog_73780_Content_114 = {
    Text = "Neste universo, os humanos não são os únicos organismos sociais."
  },
  AvgDialog_73780_Content_115 = {Text = "..."},
  AvgDialog_73780_Content_116 = {
    Text = "Então Clementine, no início desta cerimônia, você apenas ansiava pelo seu próprio tipo?"
  },
  AvgDialog_73780_Content_117 = {
    Text = "Sem resposta, e você não esperava obtê-la. \nDepois de segurar firmemente a chave de prata na mão, você se esforça para caminhar para frente ——"
  },
  AvgDialog_73780_Content_118 = {
    Text = "Você vai salvar os outros — ou melhor, sua família."
  },
  AvgDialog_73780_Content_12 = {
    Text = "Oh, temo que vou te desapontar."
  },
  AvgDialog_73780_Content_13 = {
    Text = "Enquanto eu estiver vivo, este espaço existirá eternamente. Porque..."
  },
  AvgDialog_73780_Content_14 = {
    Text = "Clementine sorriu e apontou para seu coração."
  },
  AvgDialog_73780_Content_15 = {
    Text = "Eu liguei aqui —"
  },
  AvgDialog_73780_Content_16 = {
    Text = "Você está se referindo a... Prata?"
  },
  AvgDialog_73780_Content_17 = {
    Text = "Isso mesmo. É a Prata. Minha vida está atada a este espaço mental."
  },
  AvgDialog_73780_Content_18 = {
    Text = "A Prata é a essência do Despertador, tal ação... é loucura demais."
  },
  AvgDialog_73780_Content_19 = {
    Text = "Loucura? Encontrei alguns pacientes que podem ser chamados de \"loucos,\" mas nunca pensei em mim mesmo como louco."
  },
  AvgDialog_73780_Content_2 = {
    Text = "Simular flutuações de energia espacial como meio de ataque causará um impacto energético no espaço mental."
  },
  AvgDialog_73780_Content_20 = {
    Text = "Acredite em mim, o psicólogo é o mais qualificado para avaliar o estado do Espírito de uma pessoa, então eu permaneço calmo."
  },
  AvgDialog_73780_Content_21 = {
    Text = "Mesmo que ela volte com algo, isso não terá nenhum efeito em mim."
  },
  AvgDialog_73780_Content_22 = {
    Text = "Ela... outra Clementine!?"
  },
  AvgDialog_73780_Content_23 = {
    Text = "Claro que sou eu outro. Eu disse que isso era apenas uma tarefa necessária para acabar com nosso estado fragmentado."
  },
  AvgDialog_73780_Content_24 = {
    Text = "Pessoalmente, nunca nutri qualquer malícia contra ela."
  },
  AvgDialog_73780_Content_25 = {
    Text = "Ela está mentindo, e você pode ver isso."
  },
  AvgDialog_73780_Content_26 = {
    Text = "Este é o mundo espiritual de Clementine, onde tudo é uma expressão de seus pensamentos internos."
  },
  AvgDialog_73780_Content_27 = {
    Text = "Ela se dividiu, ela se matou—ela se despreza."
  },
  AvgDialog_73780_Content_28 = {
    Text = "Embora você tenha me rejeitado repetidamente, como alguém que enfrentou Sua existência, como meu paciente, estou disposto a lhe perdoar desta vez."
  },
  AvgDialog_73780_Content_29 = {
    Text = "Enquanto você se comportar depois..."
  },
  AvgDialog_73780_Content_3 = {
    Text = "A habilidade de fabricação e o material do comunicador só poderiam suportar sua influência sobre uma pequena área, enquanto se fosse a chave de prata..."
  },
  AvgDialog_73780_Content_30 = {
    Text = "Clementine se aproxima com um sorriso, estendendo a mão para acariciar suavemente seu rosto."
  },
  AvgDialog_73780_Content_31 = {
    Text = "Usar a chave prateada várias vezes e sobrecarregar seu corpo deve ser doloroso, mas tudo bem, essa dor logo desaparecerá."
  },
  AvgDialog_73780_Content_32 = {
    Text = "Eu acabarei com sua dor e trarei você de volta à vida. Claro, isso requer um pequeno sacrifício."
  },
  AvgDialog_73780_Content_33 = {
    Text = "Afinal, neste mundo em chamas, a sobrevivência sempre vem com um preço."
  },
  AvgDialog_73780_Content_34 = {
    Text = "O som familiar dos insetos entrou em seus ouvidos, espremendo-se em seus olhos; seu cérebro parecia estar tremendo, e também parecia estar em uma loucura, completamente fora de seu controle."
  },
  AvgDialog_73780_Content_35 = {
    Text = "Para manter a sanidade e aliviar a dor das escalas de inseto Caro que crescem continuamente, você tem que dizer algo."
  },
  AvgDialog_73780_Content_36 = {
    Text = "Você já disse essas palavras para aqueles pacientes, não disse?"
  },
  AvgDialog_73780_Content_37 = {
    Text = "Este mundo ardente consumiu sua sanidade, transformando-o em monstros, que acreditam ser sua última redenção."
  },
  AvgDialog_73780_Content_38 = {
    Text = "No final, para sobreviver, eles abandonaram tudo, até mesmo a própria existência."
  },
  AvgDialog_73780_Content_39 = {
    Text = "Qual é o problema com isso? O instinto dos seres vivos é sobreviver; eu entendo totalmente a escolha deles."
  },
  AvgDialog_73780_Content_4 = {
    Text = "Eu acho que isso seria o suficiente para desestabilizar todo o sanatório, quebrando brevemente o <Yellow:equilíbrio> deste espaço independente... criando uma fissura para permitir que a consciência dentro escape."
  },
  AvgDialog_73780_Content_40 = {
    Text = "Além disso, acredite em mim, dor e tumulto são meros momentos fugazes."
  },
  AvgDialog_73780_Content_41 = {
    Text = "Enquanto o ritual for completado, você renascerá, eles renascerão, todos terão seus desejos realizados."
  },
  AvgDialog_73780_Content_42 = {
    Text = "...Você está certo, sobreviver é o instinto dos seres vivos, eu também entendo. Mas..."
  },
  AvgDialog_73780_Content_43 = {
    Text = "Eu não aceitarei. William, e aqueles que caminham voluntariamente para suas mortes, também não aceitaram."
  },
  AvgDialog_73780_Content_44 = {
    Text = "Porque algo deve ser mais importante do que meramente sobreviver."
  },
  AvgDialog_73780_Content_45 = {
    Text = "Este ponto, Clementine, você deveria ter experimentado em primeira mão. Velho John, Oliver e... Allen—eles lhe disseram sua escolha com suas vidas."
  },
  AvgDialog_73780_Content_46 = {
    Text = "Um som nauseante e úmido de dilaceração se ergue no ar. Enormes patas de aranha irrompem pelos corpos dos oficiais e dos transeuntes, espirrando sangue espesso com cheiro de ferro por todo você."
  },
  AvgDialog_73780_Content_47 = {
    Text = "O sorriso de Clementine desaparece em um instante. Um zumbido irritante perfura profundamente seu cérebro, severando sua conexão com seu próprio corpo."
  },
  AvgDialog_73780_Content_48 = {
    Text = "Você não pode ver, ouvir, falar ou se mover. Mas você sabe que sua vontade está ligada a Clementine."
  },
  AvgDialog_73780_Content_49 = {
    Text = "Aquele link com o ponto de consciência de Clementine não foi um acidente — \nA existência de \"Clementine\" esteve te observando, acompanhando e esperando o tempo todo."
  },
  AvgDialog_73780_Content_5 = {Text = "Boom—"},
  AvgDialog_73780_Content_50 = {
    Text = "Clementine, como você disse, ninguém pode se separar do passado. Aqueles dores sempre persistiram profundamente em seu coração, certo?"
  },
  AvgDialog_73780_Content_51 = {
    Text = "Então é por isso que você está bravo—bravo o suficiente para se matar, e agora, bravo o suficiente para querer me matar."
  },
  AvgDialog_73780_Content_52 = {
    Text = "Porque essas experiências de partir o coração, mesmo que mudem de forma de existir, ficarão gravadas em seu coração e alma."
  },
  AvgDialog_73780_Content_53 = {
    Text = "Eles não desapareceram; eles sempre existiram."
  },
  AvgDialog_73780_Content_54 = {
    Text = "Você estende sua consciência, buscando no escuro.\nNeste momento, você já compreendeu o profundo significado da outra Clementine:"
  },
  AvgDialog_73780_Content_55 = {
    Text = "Ela lhe mostrou seu coração, buscou a Chave de prata para você e deu a você o exemplar de pupa de inseto, tudo porque queria—"
  },
  AvgDialog_73780_Content_56 = {
    Text = "No espaço negro como a tinta, surgiu um núcleo de prata —— \nquase instantaneamente, este núcleo de prata respondeu ativamente."
  },
  AvgDialog_73780_Content_57 = {Text = "..."},
  AvgDialog_73780_Content_58 = {
    Text = "%player%, você não precisa distinguir entre humanos e insetos. Apenas mantenha-se fiel ao que você deseja defender."
  },
  AvgDialog_73780_Content_59 = {
    Text = "Por exemplo, a autoconsciência dos humanos e suas almas."
  },
  AvgDialog_73780_Content_6 = {
    Text = "Usando as ondas de energia simuladas por Doll: Inferno, você vincula forçosamente a Chave de prata ao espaço mental."
  },
  AvgDialog_73780_Content_60 = {
    Text = "Por favor, acredite em mim, não quero fazer mal, só quero te ajudar."
  },
  AvgDialog_73780_Content_61 = {Text = "..."},
  AvgDialog_73780_Content_62 = {
    Text = "Eu entendo que você quer me ajudar, e eu entendo a necessidade de aderir à autoconsciência humana e à alma, mas..."
  },
  AvgDialog_73780_Content_63 = {
    Text = "Deve ser assim?"
  },
  AvgDialog_73780_Content_64 = {
    Text = "Nenhuma resposta. \nNo espaço infinito e escuro, apenas o núcleo de prata permanecia em silêncio."
  },
  AvgDialog_73780_Content_65 = {Text = "Mas eu..."},
  AvgDialog_73780_Content_66 = {
    Text = "Sua voz embarga, suas mãos tremem, mas algumas coisas não podem ser evitadas."
  },
  AvgDialog_73780_Content_67 = {
    Text = "Ligando o Prata de Clementine"
  },
  AvgDialog_73780_Content_68 = {
    Text = "Espere um pouco mais..."
  },
  AvgDialog_73780_Content_69 = {
    Text = "Sim, neste mundo em chamas, a sobrevivência sempre tem um preço."
  },
  AvgDialog_73780_Content_7 = {
    Text = "Esta ligação é muito breve, mas suficiente para interromper a tranquilidade deste espaço."
  },
  AvgDialog_73780_Content_70 = {
    Text = "E você, com base na racionalidade humana, fez uma escolha."
  },
  AvgDialog_73780_Content_71 = {
    Text = "Apenas um momento... Deixe-a ficar por mais um segundo..."
  },
  AvgDialog_73780_Content_72 = {
    Text = "Você sabe que deveria ser racional, ainda assim as emoções humanas o fazem hesitar."
  },
  AvgDialog_73780_Content_73 = {Text = "Boom—"},
  AvgDialog_73780_Content_74 = {
    Text = "O Núcleo de Prata reage ao estímulo e faz a sua escolha. Diante da vontade absoluta de autodestruição de Clementine, o espaço mental recua e se despedaça."
  },
  AvgDialog_73780_Content_75 = {
    Text = "Fissuras se abrem, e incontáveis almas aprisionadas correm em direção à liberdade."
  },
  AvgDialog_73780_Content_76 = {
    Text = "Debaixo daquela multidão de almas jubilosas, está Clementine, observando você em silêncio.\nO corpo dela também está se desintegrando."
  },
  AvgDialog_73780_Content_77 = {
    Text = "...Sinto muito."
  },
  AvgDialog_73780_Content_78 = {Text = "..."},
  AvgDialog_73780_Content_79 = {
    Text = "Pela primeira vez, Clementine retirou seu sorriso. Ela inclinou a cabeça, aparentemente ponderando algo."
  },
  AvgDialog_73780_Content_8 = {
    Text = "Todo o reino da mente está vibrando, mudando e colapsando peça por peça, finalmente chegando a repousar na camada mais externa do espaço estrutural—o sanatório."
  },
  AvgDialog_73780_Content_80 = {
    Text = "Por que... pedir desculpas? Por que todos vocês têm que dizer... desculpas no final?"
  },
  AvgDialog_73780_Content_81 = {
    Text = "Eu não entendo, eu realmente não entendo!"
  },
  AvgDialog_73780_Content_82 = {
    Text = "Quando a história da raça passou pela minha mente\nde todos os aspectos, eu era um inseto\nela já se tornara parte de mim"
  },
  AvgDialog_73780_Content_83 = {
    Text = "E os insetos não têm glândulas lacrimais ou córtex emocional."
  },
  AvgDialog_73780_Content_84 = {
    Text = "Clementine pegou sua mão e a colocou em seu peito, onde está seu coração."
  },
  AvgDialog_73780_Content_85 = {
    Text = "Diga-me, o que você ouviu? O chilrear de um inseto ou o batimento cardíaco de um humano?"
  },
  AvgDialog_73780_Content_86 = {
    Text = "Não, não há nada aqui. Está vazio!"
  },
  AvgDialog_73780_Content_87 = {
    Text = "Não está vazio."
  },
  AvgDialog_73780_Content_88 = {
    Text = "Dentro, há uma Prata. O Coração de Prata é também um coração."
  },
  AvgDialog_73780_Content_89 = {
    Text = "Mas este coração, ao contrário dos humanos ou insetos, precisa ser definido por você. Assim como seu verdadeiro eu, cabe a você escolher, moldar e se tornar."
  },
  AvgDialog_73780_Content_9 = {
    Text = "Por que... tossir, tossir... o rift não apareceu?"
  },
  AvgDialog_73780_Content_90 = {
    Text = "Os humanos não nascem entendendo o que são; leva crescimento, compreensão e transcendência. Estas são suas próprias palavras."
  },
  AvgDialog_73780_Content_91 = {
    Text = "Um som nauseante e úmido de dilaceração se ergue no ar. Enormes patas de aranha irrompem pelos corpos dos oficiais e dos transeuntes, espirrando sangue espesso com cheiro de ferro por todo você."
  },
  AvgDialog_73780_Content_92 = {
    Text = "Clementine olhou para você sem expressão, fitando-o por um bom tempo."
  },
  AvgDialog_73780_Content_93 = {
    Text = "O que exatamente sou eu?"
  },
  AvgDialog_73780_Content_94 = {Text = "—O Id."},
  AvgDialog_73780_Content_95 = {
    Text = "—O superego."
  },
  AvgDialog_73780_Content_96 = {
    Text = "Humana? Ou inseto?"
  },
  AvgDialog_73780_Content_97 = {
    Text = "Uma lágrima cai de repente do olho de Clementine."
  },
  AvgDialog_73780_Content_98 = {
    Text = "Esta é uma lágrima tardia. Esta é uma lágrima que foi cultivada no coração por muito tempo, tanto tempo que seu dono já havia esquecido da sua existência."
  },
  AvgDialog_73780_Content_99 = {
    Text = "Ela achava que aquele passado já era realmente \"passado\", e que sua vida havia recebido um novo começo.\nMas, na verdade, ninguém pode se livrar do seu próprio passado."
  },
  AvgDialog_73781_Content_1 = {
    Text = "Memória perdida"
  },
  AvgDialog_73781_Content_10 = {
    Text = "Muito bom, Claude. Você pode abrir os olhos agora."
  },
  AvgDialog_73781_Content_11 = {
    Text = "Na música suave e gentil, uma estranha sala de consulta adornada com muitos espécimes de insetos aparece."
  },
  AvgDialog_73781_Content_12 = {
    Text = "Clementine está sentada em frente a você, olhando para você com um sorriso.\nOu, mais precisamente, olhando para o proprietário desta memória."
  },
  AvgDialog_73781_Content_13 = {
    Text = "<LightGray:Clementine, por que é você novamente?>"
  },
  AvgDialog_73781_Content_14 = {
    Text = "É claro que, como um espectador das memórias, você não pode se envolver, assim essa confusão permanece silenciosa, não ouvida por ninguém."
  },
  AvgDialog_73781_Content_15 = {
    Text = "Relaxe com a música, imaginando sua consciência saindo do corpo, dançando no vazio junto com a música."
  },
  AvgDialog_73781_Content_16 = {
    Text = "Muito bem. Em seguida, vamos continuar o tópico da semana passada."
  },
  AvgDialog_73781_Content_17 = {
    Text = "Após ver Leonard e Audrey se apresentarem juntos de perto, você decide propor a Audrey. Então, qual foi o resultado?"
  },
  AvgDialog_73781_Content_18 = {
    Text = "O proprietário da memória - o paciente corroído Clyde apertou o punho com força, sentindo-se tenso, furioso e frustrado. \nEsse comportamento já dava a resposta.\n\n."
  },
  AvgDialog_73781_Content_19 = {
    Text = "É assim mesmo... mas talvez, isso não seja necessariamente uma coisa ruim."
  },
  AvgDialog_73781_Content_2 = {
    Text = "Fique longe dela; ela é minha, toda minha!"
  },
  AvgDialog_73781_Content_20 = {
    Text = "Tudo na vida tem seu significado, através do qual podemos entender nossos verdadeiros eu."
  },
  AvgDialog_73781_Content_21 = {
    Text = "Ou, eu preferiria descrevê-lo desta forma, a vida é nosso processo de explorar a nós mesmos."
  },
  AvgDialog_73781_Content_22 = {
    Text = "<LightGray:Auto? A verdadeira eu? Os psicólogos sempre falam em enigmas...>"
  },
  AvgDialog_73781_Content_23 = {
    Text = "Claude parece tão confuso quanto você, ponderando o profundo significado do \"eu verdadeiro.\""
  },
  AvgDialog_73781_Content_24 = {
    Text = "Esse desconcerto fez Clementine sorrir. \n Você percebe instintivamente que esse sorriso é diferente do anterior - ele traz maldade."
  },
  AvgDialog_73781_Content_25 = {
    Text = "Claude, permita-me dizer algo um pouco fora do convencional—os humanos não nascem entendendo a si mesmos. Isso requer crescimento, entendimento e transcendência."
  },
  AvgDialog_73781_Content_26 = {
    Text = "A Sociedade sempre exige que nosso comportamento se conforme às normas de cavalheiros e damas, mas na verdade, este é apenas um lado de nós... No campo da psicologia, chamamos isso de persona."
  },
  AvgDialog_73781_Content_27 = {
    Text = "Sua persona pode ser a criança de um pai, um empregado do distrito financeiro de Londres, uma soma de todas as expectativas da sociedade - mas Claude, confie em mim, isso não é você."
  },
  AvgDialog_73781_Content_28 = {
    Text = "O verdadeiro você está cheio de Poder, confiança e sabedoria, possuindo qualidades brilhantes o suficiente para brilhar no céu estrelado; é exatamente por isso que eu escolhi você."
  },
  AvgDialog_73781_Content_29 = {
    Text = "<LightGray:Estou completamente confuso. Mas por que essa afirmação parece certa e, ao mesmo tempo, errada...>"
  },
  AvgDialog_73781_Content_3 = {
    Text = "O paciente rastejou em direção à cabeça do boneco de quatro, empurrando involuntariamente a cabeça em direção a você."
  },
  AvgDialog_73781_Content_30 = {
    Text = "Mas Claude claramente não está ciente disso. Ele olha para Clementine e pergunta sinceramente, em uma postura que busca redenção."
  },
  AvgDialog_73781_Content_31 = {
    Text = "Então o que é o verdadeiro eu? Como posso me tornar o verdadeiro eu?"
  },
  AvgDialog_73781_Content_32 = {
    Text = "Você precisará procurá-lo por conta própria, mas estou mais do que feliz em oferecer uma pequena ajuda para o seu renascimento."
  },
  AvgDialog_73781_Content_33 = {
    Text = "Acredito que Audrey é, sem dúvida, a chave."
  },
  AvgDialog_73781_Content_34 = {
    Text = "Audrey? Eu não entendo..."
  },
  AvgDialog_73781_Content_35 = {
    Text = "Bom filho, você não precisa entender, assim como não podemos interpretar totalmente a vontade daquela grande existência."
  },
  AvgDialog_73781_Content_36 = {
    Text = "Você só precisa agir. Agir, e então ganhar uma nova vida."
  },
  AvgDialog_73781_Content_37 = {
    Text = "Agora, respire fundo, e deixe essas palavras, minhas palavras, penetrar profundamente em sua mente..."
  },
  AvgDialog_73781_Content_38 = {
    Text = "Sim, isso mesmo... que boa criança."
  },
  AvgDialog_73781_Content_39 = {
    Text = "Em uma hipnose irresistível, Clyde respirou fundo, fechou os olhos e pareceu adormecer. Mas como o espectador dessa memória, você percebeu suas emoções incomumente turbulentas."
  },
  AvgDialog_73781_Content_4 = {
    Text = "A lágrima branca nos ocos dos olhos finalmente te tocou, estilhaçando-se silenciosamente."
  },
  AvgDialog_73781_Content_40 = {
    Text = "As emoções e o estado mental de Claude estão desajustados, assim como esta psicoterapia..."
  },
  AvgDialog_73781_Content_41 = {
    Text = "Espere, meus pensamentos parecem estar confusos também..."
  },
  AvgDialog_73781_Content_42 = {
    Text = "Você segura a Chave de prata, querendo acabar com esta Memória, mas vê Clementine suspirar suavemente enquanto caminha em sua direção."
  },
  AvgDialog_73781_Content_43 = {
    Text = "Você só precisa agir. Aja e ganhe uma nova vida."
  },
  AvgDialog_73781_Content_44 = {
    Text = "Cloud, pense cuidadosamente sobre seu verdadeiro eu. Considere o que seu verdadeiro eu realmente deseja."
  },
  AvgDialog_73781_Content_45 = {
    Text = "Aceite-o, aproxime-se dele, só então \"eu\" poderei transcender a forma existente de ser, tornar-me o eu verdadeiro e ganhar uma renascimento."
  },
  AvgDialog_73781_Content_46 = {
    Text = "Aceite-o, aproxime-se dele... entenda o verdadeiro eu e o que eu quero..."
  },
  AvgDialog_73781_Content_47 = {
    Text = "Isso mesmo. Finalmente, vamos repetir a frase para alcançar a salvação."
  },
  AvgDialog_73781_Content_48 = {
    Text = "Eu permito a cura e me permito expressar medo e tristeza..."
  },
  AvgDialog_73781_Content_49 = {
    Text = "A escuridão envolve sua visão, e apenas a voz de Claude permanece firme, mudando gradualmente de pânico e confusão para determinação."
  },
  AvgDialog_73781_Content_5 = {Text = "...!!!"},
  AvgDialog_73781_Content_50 = {
    Text = "Eu aceito minha mudança, e—"
  },
  AvgDialog_73781_Content_51 = {
    Text = "Quando você abre os olhos novamente, vê Claudius diante de si segurando a cabeça do manequim.\nNa outra mão, ele segura uma espada fina, cuja ponta está prestes a perfurar sua garganta."
  },
  AvgDialog_73781_Content_52 = {Text = "!?"},
  AvgDialog_73781_Content_53 = {
    Text = "Você desvia do ataque e corre em direção à porta, apenas para descobrir que ela está fechada em algum momento desconhecido."
  },
  AvgDialog_73781_Content_54 = {Text = "Abra-o!"},
  AvgDialog_73781_Content_55 = {
    Text = "Aberto? Você está se referindo à porta? Impossível."
  },
  AvgDialog_73781_Content_56 = {
    Text = "<RedShake:Quem interferir no meu encontro com Audrey deve morrer!>"
  },
  AvgDialog_73781_Content_58 = {
    Text = "Evitar não é a solução; você deve tomar a iniciativa!"
  },
  AvgDialog_73781_Content_59 = {
    Text = "Você avança rapidamente para agarrar a espada longa de Claude, e durante a luta, uma cabeça de manequim escorrega das mãos de Claude."
  },
  AvgDialog_73781_Content_6 = {
    Text = "Uma luz branca fluiu para dentro do seu corpo, e na névoa da sua consciência, você viu memórias que não pertenciam a você—"
  },
  AvgDialog_73781_Content_60 = {
    Text = "A cabeça do boneco bateu no chão com um baque surdo, depois deixou vazar uma gota de sangue fresco."
  },
  AvgDialog_73781_Content_61 = {
    Text = "...Você matou Audrey!?"
  },
  AvgDialog_73781_Content_62 = {
    Text = "Eu matei Audrey? Isso é impossível; eu a amava tanto..."
  },
  AvgDialog_73781_Content_63 = {
    Text = "Você pega a cabeça humana falsa do chão e a coloca em frente a Claude, garantindo que ele veja o sangue pingando continuamente."
  },
  AvgDialog_73781_Content_64 = {
    Text = "Cloud, veja claramente. Você matou Audrey. Depois da proposta fracassada, você a matou!"
  },
  AvgDialog_73781_Content_65 = {
    Text = "Como se uma cortina invisível tivesse sido puxada, a cabeça de boneco diante de você começou a se transformar—o tecido e o esqueleto de metal começaram a dissolver e gotejar, revelando o interior vermelho-sangue."
  },
  AvgDialog_73781_Content_66 = {
    Text = "...Oh, Audrey?!"
  },
  AvgDialog_73781_Content_67 = {
    Text = "Haha, agora eu lembro, eu me lembro de tudo. Sim, eu a matei, eu matei Audrey! Hahaha!"
  },
  AvgDialog_73781_Content_68 = {
    Text = "Cloud irrompeu em risos incontroláveis, e à medida que seu riso se transformava em soluços, a sala começou a tremer."
  },
  AvgDialog_73781_Content_69 = {
    Text = "Um vento violento surgiu do nada, soprando você para fora da porta e para o corredor. Você só teve tempo para um último olhar —"
  },
  AvgDialog_73781_Content_7 = {
    Text = "Eu permito a cura e me permito expressar medo e tristeza."
  },
  AvgDialog_73781_Content_70 = {
    Text = "Perdoe-me..."
  },
  AvgDialog_73781_Content_71 = {
    Text = "Cloud beijou os lábios do manequim e perfurou sua própria garganta com uma espada fina.\nDesta vez, \"Audrey\" não desviou."
  },
  AvgDialog_73781_Content_72 = {
    Text = "Então, com um estrondo alto, a Porta se fechou e foi completamente trancada."
  },
  AvgDialog_73781_Content_73 = {
    Text = "Enquanto isso, o familiar som de \"tap tap tap\" dos passos ecoava à distância."
  },
  AvgDialog_73781_Content_74 = {
    Text = "...O médico está vindo! Rápido, esconda-se!"
  },
  AvgDialog_73781_Content_75 = {
    Text = "Você se esconde na sombra do canto e de repente sente o frio se espalhando de dentro para fora—"
  },
  AvgDialog_73781_Content_76 = {
    Text = "Você não precisa entender, você só precisa agir."
  },
  AvgDialog_73781_Content_77 = {
    Text = "Aceite-o, aproxime-se dele... Torne-se seu verdadeiro eu."
  },
  AvgDialog_73781_Content_78 = {
    Text = "O tratamento psicológico então cunningamente amarra Audrey ao seu verdadeiro eu, fazendo com que Claude, que anseia por seu verdadeiro eu, se torne um assassino."
  },
  AvgDialog_73781_Content_8 = {
    Text = "Eu aceito minha mudança, e—"
  },
  AvgDialog_73781_Content_9 = {
    Text = "Eu definitivamente mudarei."
  },
  AvgDialog_73782_Content_1 = {
    Text = "Salve, mundo ardente"
  },
  AvgDialog_73782_Content_10 = {
    Text = "Você não pode deixar de tossir. Embora a energia da explosão do comunicador tenha dado a você e ao Pequeno William tempo para escapar, também desferiu um poderoso golpe em seu Espírito e Corpo."
  },
  AvgDialog_73782_Content_11 = {
    Text = "E todos vocês, sendo drenados pela conexão interdimensional, mal conseguem suportar."
  },
  AvgDialog_73782_Content_12 = {Text = "..."},
  AvgDialog_73782_Content_13 = {
    Text = "Você tosse sangue... e seu corpo tem estado... continuamente sangrando..."
  },
  AvgDialog_73782_Content_14 = {
    Text = "Você não vai morrer tão cedo, então não se preocupe."
  },
  AvgDialog_73782_Content_15 = {
    Text = "Estou falando sério. Meu corpo... é diferente do seu; não é facilmente destruído."
  },
  AvgDialog_73782_Content_16 = {
    Text = "Então, é por isso que você me protegeu durante a explosão de energia? Sabendo que você não morreria e agindo de forma tão imprudente?"
  },
  AvgDialog_73782_Content_17 = {Text = "..."},
  AvgDialog_73782_Content_18 = {
    Text = "Você não sabe como responder. Uma cena continua piscando em sua mente."
  },
  AvgDialog_73782_Content_19 = {
    Text = "Eu, eu só..."
  },
  AvgDialog_73782_Content_2 = {
    Text = "Tão pesado..."
  },
  AvgDialog_73782_Content_20 = {
    Text = "—Eu só não quero ver você desaparecer na minha frente novamente."
  },
  AvgDialog_73782_Content_21 = {
    Text = "Mas você não consegue terminar de falar. \nAo longe, ouve-se novamente o som de passos — é o som das Clementines que estão à sua procura junto com Williaminho."
  },
  AvgDialog_73782_Content_22 = {Text = "..."},
  AvgDialog_73782_Content_23 = {
    Text = "Você se apoia na parede, e então caminha em direção à porta."
  },
  AvgDialog_73782_Content_24 = {
    Text = "Para onde você está indo? Você vai sair para atrair aqueles monstros para longe de mim?"
  },
  AvgDialog_73782_Content_25 = {
    Text = "Esta é a melhor escolha. Aproveite esta oportunidade para encontrar a saída e escapar daqui."
  },
  AvgDialog_73782_Content_26 = {
    Text = "Mas não há absolutamente nenhuma saída aqui."
  },
  AvgDialog_73782_Content_27 = {
    Text = "Ninguém pode escapar daqui, ninguém!"
  },
  AvgDialog_73782_Content_28 = {
    Text = "Quanto aos pacientes que não querem se tornar insetos... há apenas um resultado: a morte."
  },
  AvgDialog_73782_Content_29 = {
    Text = "Little William cerrrou os punhos, e seu corpo começou a tremer."
  },
  AvgDialog_73782_Content_3 = {
    Text = "Little William se apoiou na parede com uma mão enquanto sustentava você com a outra, lutando para seguir em frente."
  },
  AvgDialog_73782_Content_30 = {
    Text = "Um som nauseante e úmido de dilaceração se ergue no ar. Enormes patas de aranha irrompem pelos corpos dos oficiais e dos transeuntes, espirrando sangue espesso com cheiro de ferro por todo você."
  },
  AvgDialog_73782_Content_31 = {
    Text = "Você se assusta repentinamente e estende a mão para tocar a parte de trás da cabeça de Williaminho. \nLá, está viscoso e quente, como se algo estivesse em formação."
  },
  AvgDialog_73782_Content_32 = {
    Text = "William, você..."
  },
  AvgDialog_73782_Content_33 = {
    Text = "Não fique tão surpreso. É uma ocorrência comum. Todo paciente confinado na ala passará por transformação."
  },
  AvgDialog_73782_Content_34 = {
    Text = "Eles farão com que aqueles monstros implantem insetos neles, e então..."
  },
  AvgDialog_73782_Content_35 = {
    Text = "Então aqueles insetos vão correr e se reproduzir em seus cérebros... destruindo completamente suas almas no final."
  },
  AvgDialog_73782_Content_36 = {
    Text = "Little William não pôde evitar tocar a parte de trás da cabeça, de onde o sangue continuava a brotar, ensopando sua mão e causando uma dor excruciante."
  },
  AvgDialog_73782_Content_37 = {
    Text = "Tão doloroso, %player%, estou realmente sentindo tanta dor..."
  },
  AvgDialog_73782_Content_38 = {
    Text = "...Sinto muito, eu deveria ter... encontrado você mais cedo... eu..."
  },
  AvgDialog_73782_Content_39 = {
    Text = "Little William balançou a cabeça e tocou a chave de prata em seu peito."
  },
  AvgDialog_73782_Content_4 = {
    Text = "Aguarde, %player%, estamos quase lá."
  },
  AvgDialog_73782_Content_40 = {
    Text = "Agora há pouco, durante o impacto de energia, me lembrei de algo... Nessas memórias, eu o chamava de \"Guardião\"."
  },
  AvgDialog_73782_Content_41 = {
    Text = "Guardião %player%."
  },
  AvgDialog_73782_Content_42 = {
    Text = "Como você poderia...!!!"
  },
  AvgDialog_73782_Content_43 = {
    Text = "O nome de outro mundo atingiu como um trovão, deixando você atordoado no lugar. Nesse breve momento de distração, o pequeno William saiu correndo e fechou a porta."
  },
  AvgDialog_73782_Content_44 = {
    Text = "William, não! Eu não preciso..."
  },
  AvgDialog_73782_Content_45 = {
    Text = "Eu não vou morrer tão facilmente, verdadeiramente, então volte. Eu não quero... eu não quero perder você novamente..."
  },
  AvgDialog_73782_Content_46 = {
    Text = "Little William ficou em silêncio. Depois de um momento, ele reuniu suas emoções e falou novamente."
  },
  AvgDialog_73782_Content_47 = {
    Text = "%player%, quando você assistiu aquela memória, mudou de assunto porque meu passado era tão infeliz que você não conseguiu mencioná-lo?"
  },
  AvgDialog_73782_Content_48 = {
    Text = "Está tudo bem; perder memória também é bom. Eu não sou uma pessoa passiva; nunca entendi as palavras \"desistir\""
  },
  AvgDialog_73782_Content_49 = {
    Text = "Como você disse, o que importa é o futuro; o que buscamos também é o futuro."
  },
  AvgDialog_73782_Content_5 = {
    Text = "Não há necessidade de me confortar... Não haverá lugar seguro neste sanatório."
  },
  AvgDialog_73782_Content_50 = {
    Text = "Então volte. Assim que eu distrair aqueles Clementines, voltarei para te encontrar, e nós..."
  },
  AvgDialog_73782_Content_51 = {
    Text = "Vamos resolver este lugar juntos, sair daqui e então criar um futuro—um futuro bonito."
  },
  AvgDialog_73782_Content_52 = {
    Text = "Você está desviando da questão principal, %player%. Estamos no território de Clementine, e ela não vai nos deixar sair facilmente."
  },
  AvgDialog_73782_Content_53 = {
    Text = "Nossa única escolha é pegá-los de surpresa e tomar a iniciativa, o que requer isca para atrair a atenção dos Clementines. E..."
  },
  AvgDialog_73782_Content_54 = {
    Text = "Mais alguma coisa?"
  },
  AvgDialog_73782_Content_55 = {
    Text = "Little William reprimiu um soluço, cobrindo os olhos com o braço — as memórias passageiras surgiram gradualmente diante dele."
  },
  AvgDialog_73782_Content_56 = {
    Text = "Este mundo está pegando fogo, %player%, e eu, naquelas memórias restantes, vi com meus próprios olhos como ele ardeu."
  },
  AvgDialog_73782_Content_57 = {
    Text = "Pequeno Bill, o catador das ruas mais sujas e fedidas de Londres, pode correr um quilômetro para entregar uma carta por apenas um quarto de centavo sem parar."
  },
  AvgDialog_73782_Content_58 = {
    Text = "Nisa Smith, a criança de 11 anos de uma lavadeira, ajuda a sustentar sua família trabalhando como despertador, catando lixo, vendendo fósforos e aceitando qualquer trabalho que possa trazer dinheiro."
  },
  AvgDialog_73782_Content_59 = {
    Text = "E lá está Henry, o menino da carruagem pública, trabalhando das 4 da manhã até a meia-noite—um turno de 20 horas—com o desejo de ter um ganso assado completo para o Natal."
  },
  AvgDialog_73782_Content_6 = {Text = "..."},
  AvgDialog_73782_Content_60 = {
    Text = "E há muitos outros cujos nomes posso recordar e cujos rostos lembro... todos desapareceram..."
  },
  AvgDialog_73782_Content_61 = {
    Text = "Mas talvez ainda haja esperança para as pessoas aqui. Quando explorei o sanatório mais cedo, vi muitos pacientes que acabaram de chegar; eles ansiavam por partir e desejavam sobreviver."
  },
  AvgDialog_73782_Content_62 = {
    Text = "O mundo está em chamas\nAs pessoas vivas são apenas lenha, efêmeras"
  },
  AvgDialog_73782_Content_63 = {
    Text = "Mas o mundo não deveria ser assim—"
  },
  AvgDialog_73782_Content_64 = {
    Text = [[
Aquelas pessoas sorridentes, raivosas, tristes, cheias de expectativa...
Todas sofreram apoptose, desaparecendo para sempre]]
  },
  AvgDialog_73782_Content_65 = {
    Text = "Aquelas pessoas não devem desaparecer tão facilmente; sua existência não deve ser apagada tão effortless..."
  },
  AvgDialog_73782_Content_66 = {
    Text = "Não tenha medo, não hesite\nQuando o mundo estiver em chamas, alguém sempre terá que agir"
  },
  AvgDialog_73782_Content_67 = {
    Text = "Então, quero parar isso, mesmo que signifique salvar mais uma pessoa. Porque—"
  },
  AvgDialog_73782_Content_68 = {
    Text = "Embora este mundo esteja queimando, ele continua bonito, encantador e comovente. Ele ainda faz com que alguém queira derramar lágrimas e protegê-lo sem hesitação, não é?"
  },
  AvgDialog_73782_Content_69 = {
    Text = "Como um Guardião, você deveria entender isso melhor que ninguém."
  },
  AvgDialog_73782_Content_7 = {
    Text = "O pequeno William não disse nada, apenas abriu a porta silenciosamente e entrou com você."
  },
  AvgDialog_73782_Content_70 = {Text = "..."},
  AvgDialog_73782_Content_71 = {
    Text = "Você não pode falar e só pode fechar os olhos."
  },
  AvgDialog_73782_Content_72 = {
    Text = "Aqueles colegas e veteranos que desapareceram..."
  },
  AvgDialog_73782_Content_73 = {
    Text = "Aquelas lápides inscritas com seu nome e os nomes de inúmeros \"não-existentes\"..."
  },
  AvgDialog_73782_Content_74 = {
    Text = "Aquelas almas lutando em dor devido à dissolução..."
  },
  AvgDialog_73782_Content_75 = {
    Text = "Aqueles companheiros que compartilharam tanto a tristeza quanto a alegria, que uma vez viveram tão vividamente..."
  },
  AvgDialog_73782_Content_76 = {
    Text = "E... quem mais está preso neste sanatório?\n?"
  },
  AvgDialog_73782_Content_77 = {
    Text = "Que tipo de passado você tem, e que tipo de pessoa você anseia se tornar?"
  },
  AvgDialog_73782_Content_78 = {
    Text = "Lágrimas se acumulam em seus olhos, trazendo uma sensação azeda e ardente, mas você não se atreve a piscar."
  },
  AvgDialog_73782_Content_79 = {
    Text = "Mas no início da história, eu simplesmente queria encontrar você..."
  },
  AvgDialog_73782_Content_8 = {
    Text = "Ele certamente sabe que uma porta de madeira não pode parar Clementine, que controla todo o sanatório, mas além de entrar no quarto, ele não tem melhores opções."
  },
  AvgDialog_73782_Content_80 = {
    Text = "Mas a história alcançou seu midpoint, %player%."
  },
  AvgDialog_73782_Content_81 = {
    Text = "Suas lágrimas finalmente caem, despedaçando-se. Junto com elas, sua Alma também se despedaça."
  },
  AvgDialog_73782_Content_82 = {
    Text = "Não tenha medo, não hesite\nQuando o mundo estiver em chamas, alguém sempre terá que agir"
  },
  AvgDialog_73782_Content_83 = {
    Text = "Porque este mundo vale a pena, mesmo que esteja prestes a arder, esteja ardendo agora ou venha a arder completamente no futuro"
  },
  AvgDialog_73782_Content_84 = {
    Text = "Eu entendo. Vamos salvar todos no sanatório juntos."
  },
  AvgDialog_73782_Content_85 = {
    Text = "William, distraia-os enquanto eu procuro o quarto de Clementine e localizo o núcleo deste sanatório para destruí-lo."
  },
  AvgDialog_73782_Content_86 = {Text = "Recebido~"},
  AvgDialog_73782_Content_87 = {
    Text = "E... obrigado por vir me encontrar."
  },
  AvgDialog_73782_Content_88 = {
    Text = "Então veio o som de passos, muitos, muitos passos, passando em frente à porta, depois desaparecendo e finalmente sumindo completamente."
  },
  AvgDialog_73782_Content_89 = {
    Text = "Você cobre o rosto com as mãos e se esfrega com força, com intensidade."
  },
  AvgDialog_73782_Content_9 = {
    Text = "<Shake:tossir, tossir...>"
  },
  AvgDialog_73782_Content_90 = {
    Text = "Sim, a história chegou ao seu meio. O grande aventureiro reuniu companheiros e partiu em direção ao covil do mentor para destruir o plano maligno de destruição mundial e salvar a todos."
  },
  AvgDialog_73782_Content_91 = {
    Text = "Esta é a metade final da história da aventura."
  },
  AvgDialog_73782_Content_92 = {
    Text = "Você abre a porta e vai em direção ao quarto de Clementine, indo na direção oposta a William, cumprindo seu dever como Guardião."
  },
  AvgDialog_73782_Content_93 = {
    Text = "Este mundo pode um dia ser reduzido a cinzas, mas não agora, não hoje."
  },
  AvgDialog_73783_Content_1 = {
    Text = "Crisálida de camaradagem"
  },
  AvgDialog_73783_Content_10 = {
    Text = "Clementine, eu vi você crescer desde pequena e não quero que você seja enganada por pessoas más. Você realmente acha que {Male=ele,Female=ela} é digno(a) de confiança?"
  },
  AvgDialog_73783_Content_11 = {
    Text = "Clementine? Até o nome é exatamente o mesmo! Chocado, você olha para a garota."
  },
  AvgDialog_73783_Content_12 = {
    Text = "Tenho certeza. Acredito em {Male=ele,Female=ela}."
  },
  AvgDialog_73783_Content_13 = {
    Text = "Então qual foi o comportamento dele agora há pouco?"
  },
  AvgDialog_73783_Content_14 = {
    Text = "Agora mesmo... hum, Tio Oliver, você conhece meu corpo. Eu, eu não tenho muito tempo restante..."
  },
  AvgDialog_73783_Content_15 = {
    Text = "Antes de eu morrer, quero fazer um amigo e testemunhar como o inseto em pupação ganha nova vida."
  },
  AvgDialog_73783_Content_16 = {
    Text = "...Você optou por se tornar amigo de {Male=ele,Female=ela}?"
  },
  AvgDialog_73783_Content_17 = {
    Text = "Sim, eu não quero que meus amigos sejam prejudicados."
  },
  AvgDialog_73783_Content_18 = {
    Text = "... Tudo bem, eu entendi."
  },
  AvgDialog_73783_Content_19 = {
    Text = "%player%, desta vez, vou deixá-lo livre. Preste atenção nas suas palavras e ações no futuro—estarei de olho em você."
  },
  AvgDialog_73783_Content_2 = {
    Text = "We warmly welcome your arrival, yet you want to escape? Indeed, humans are the most heartless and cruel race."
  },
  AvgDialog_73783_Content_20 = {
    Text = "Depois de emitir um aviso, Oliver partiu, e você observou sua figura se afastando, confirmando ainda mais um fato: essas pessoas realmente existiram uma vez."
  },
  AvgDialog_73783_Content_21 = {
    Text = "Por favor, não culpe o tio Oliver. Ele só quer proteger a todos."
  },
  AvgDialog_73783_Content_22 = {
    Text = "Proteção? Alguém quer lhe fazer mal... Então, o massacre que Oliver mencionou é real?"
  },
  AvgDialog_73783_Content_23 = {
    Text = "Nossa linhagem, nossas crenças e até mesmo nossa pele que pode crescer escamas de inseto significam nossa identidade como forasteiros, não é?"
  },
  AvgDialog_73783_Content_24 = {
    Text = "Mas aquele traidor também não teve um bom destino. Ele se suicidou."
  },
  AvgDialog_73783_Content_25 = {
    Text = "Você permanece em silêncio. Embora esta Clementine seja amigável em palavras e ações, você não pode baixar a guarda; ainda se lembra que Clementine pode \"replicar\" a si mesmo a qualquer momento."
  },
  AvgDialog_73783_Content_26 = {
    Text = "...Qual é a sua relação com Clementine, quero dizer, aquela Clementine? Vocês são gêmeos?"
  },
  AvgDialog_73783_Content_27 = {
    Text = "Eu não sei. Eu... perdi minha memória e esqueci minha verdadeira existência."
  },
  AvgDialog_73783_Content_28 = {
    Text = "Então, um silêncio caiu novamente."
  },
  AvgDialog_73783_Content_29 = {
    Text = "Você parece não acreditar em mim..."
  },
  AvgDialog_73783_Content_3 = {
    Text = "Um tenente que parece um pouco humano e inseto se aproximou de você, brandindo uma espada com cabo."
  },
  AvgDialog_73783_Content_30 = {
    Text = "Clementine deu um passo mais perto de você, mas seus instintos o fizeram recuar, mantendo distância de Clementine."
  },
  AvgDialog_73783_Content_31 = {
    Text = "Bem, suas ações já revelaram a resposta para mim."
  },
  AvgDialog_73783_Content_32 = {
    Text = "Mas por favor, acredite em mim, não tenho más intenções; eu só desejo ajudá-lo."
  },
  AvgDialog_73783_Content_33 = {
    Text = "Obrigado, mas cuidarei dos meus próprios assuntos."
  },
  AvgDialog_73783_Content_34 = {
    Text = "Você recua, querendo sair, mas Clementine de repente agarra sua mão."
  },
  AvgDialog_73783_Content_35 = {
    Text = "Eu te provarei."
  },
  AvgDialog_73783_Content_36 = {
    Text = "No próximo instante, Clementine coloca sua mão em seu coração."
  },
  AvgDialog_73783_Content_38 = {
    Text = "Você ouve o som de batimentos cardíacos e um zumbido que parece vir da alma."
  },
  AvgDialog_73783_Content_39 = {
    Text = "Eu quero ver o mundo verdadeiro como humano e viver uma nova vida."
  },
  AvgDialog_73783_Content_4 = {
    Text = "O que você está planejando fazer? Está procurando alguém para nos massacrar anomalias!"
  },
  AvgDialog_73783_Content_40 = {
    Text = "Você sente — aquele é um coração, quente e pulsando como o de um humano."
  },
  AvgDialog_73783_Content_41 = {
    Text = "Eu quero preservar minha identidade como humano; eu quero morrer como humano."
  },
  AvgDialog_73783_Content_42 = {
    Text = "—Isso é um coração com vontade humana, aderindo às leis da humanidade."
  },
  AvgDialog_73783_Content_43 = {
    Text = "Eu não quero perder minha humanidade, eu não quero perder @2, eu não quero esquecer quem eu realmente sou..."
  },
  AvgDialog_73783_Content_44 = {
    Text = "<Red:  Manter a humanidade                                                                      Salve-me   \nNão se esqueça de si mesmo                                                                                                      \n                                              \n                             Manter a humanidade\n                        Não se esqueça de si mesmo                                                   Mate-me >"
  },
  AvgDialog_73783_Content_45 = {Text = "..."},
  AvgDialog_73783_Content_46 = {
    Text = "Desespero e tristeza avançam em sua direção, ameaçando afogá-lo."
  },
  AvgDialog_73783_Content_47 = {
    Text = "Você retrai sua mão, cortando forçosamente essa conexão de consciência, escapando com grande dificuldade, ofegante."
  },
  AvgDialog_73783_Content_48 = {
    Text = "Quem é você?! Por que está se aproximando de mim?!"
  },
  AvgDialog_73783_Content_49 = {
    Text = "Eu não sei... Eu só quero..."
  },
  AvgDialog_73783_Content_5 = {
    Text = "Então eu digo a você, você está na fila errada. Criança, você deve pagar o preço por suas escolhas."
  },
  AvgDialog_73783_Content_50 = {
    Text = "Quer me ajudar? Então, por favor, saia, saia daqui! Me deixe em paz!"
  },
  AvgDialog_73783_Content_51 = {
    Text = "As escamas de inseto continuam crescendo em sua carne, trazendo dor, sofrimento e raiva. \nVocê tem muita vontade de se conter, mas a comporta da razão já foi destruída."
  },
  AvgDialog_73783_Content_52 = {
    Text = "Você arranca violentamente as escamas de inseto do seu corpo, arrancando carne junto, provocando gritos de dor e raiva. \nUma após outra."
  },
  AvgDialog_73783_Content_53 = {
    Text = "Clementine, admito que seu truque funcionou. Eu realmente não posso prejudicá-los porque suas ações são humanitárias, lembrando-me dos humanos que uma vez vi."
  },
  AvgDialog_73783_Content_54 = {
    Text = "Talvez eles fossem humanos afinal, ou talvez aquela aparência blasfema e horripilante seja apenas uma máscara que você impôs, destinada apenas a me enganar e zombar do meu lamentável eu quando me desvio do caminho."
  },
  AvgDialog_73783_Content_55 = {
    Text = "Eu não serei enganado. Eu nunca serei enganado!"
  },
  AvgDialog_73783_Content_56 = {
    Text = "Você descasca as escamas de inseto uma a uma, mas elas só se multiplicam, parecendo impossível de remover completamente."
  },
  AvgDialog_73783_Content_57 = {
    Text = "As escamas do inseto crescem dentro do humano Caro, splash, crash, heh heh, esse é o som de Caro colapsando."
  },
  AvgDialog_73783_Content_58 = {
    Text = "Tão doloroso!"
  },
  AvgDialog_73783_Content_59 = {
    Text = "Eles aplaudem, pulam, vagam pelo corpo humano, gradualmente rasgando a alma e pintando-a com as cores dos insetos."
  },
  AvgDialog_73783_Content_6 = {
    Text = "O bastão da espada é levantado em direção à sua cabeça."
  },
  AvgDialog_73783_Content_60 = {
    Text = "Shh, shh, a transformação está prestes a começar."
  },
  AvgDialog_73783_Content_61 = {
    Text = "<Shake: Ahhhhh!!!—>"
  },
  AvgDialog_73783_Content_62 = {
    Text = "Hahaha, olhem, olhem, isso é a humanidade."
  },
  AvgDialog_73783_Content_63 = {
    Text = "Frágil, sensível, até mesmo um leve estímulo pode estourar como um balão, desaparecendo completamente."
  },
  AvgDialog_73783_Content_64 = {
    Text = "<Change>Ajude... Salve-me..."
  },
  AvgDialog_73783_Content_65 = {
    Text = "A sua consciência começa a se confundir, sua racionalidade começa a desmoronar e você se ajoelha no chão."
  },
  AvgDialog_73783_Content_66 = {
    Text = "Claramente, eu só desejo salvar William e todos aqueles presos no sanatório, mas agora, eu não consigo nem me redimir."
  },
  AvgDialog_73783_Content_67 = {
    Text = "Humano? Inseto? Ha, qual é a diferença..."
  },
  AvgDialog_73783_Content_68 = {
    Text = "Estou começando... a perder a noção do tempo..."
  },
  AvgDialog_73783_Content_69 = {
    Text = "...Eu não quero quebrar minha promessa. William, não quero falhar na última coisa que você me confiou."
  },
  AvgDialog_73783_Content_7 = {
    Text = "<Shake:Tio Oliver, espere.>"
  },
  AvgDialog_73783_Content_70 = {
    Text = "Então vamos nos esforçar para cumprir a promessa. %player%, a dor é apenas o processo que passamos para nos libertar e renascer."
  },
  AvgDialog_73783_Content_71 = {
    Text = "Um espécime de um inseto em pupação apareceu à sua vista."
  },
  AvgDialog_73783_Content_72 = {
    Text = "Você olha para cima e vê Clementine sorrindo para você."
  },
  AvgDialog_73783_Content_73 = {
    Text = "Não se deixe influenciar pelas palavras de outro eu, %player%. No fundo do seu coração, você sempre soube a resposta certa sobre sua verdadeira essência."
  },
  AvgDialog_73783_Content_74 = {
    Text = "Apenas como meu coração, ele sempre me deu a resposta correta, a única resposta."
  },
  AvgDialog_73783_Content_75 = {
    Text = "A cognição e a consciência podem de fato ser influenciadas e moldadas pelo ambiente, ações e outros, mas sempre acreditei: a própria pessoa é o poder supremo para moldar a si mesma."
  },
  AvgDialog_73783_Content_76 = {
    Text = "Porque a coisa mais preciosa da humanidade é a capacidade de autoeducar-se, autocorrigir-se e autodesenvolver-se, assim avançando continuamente em busca de um futuro melhor."
  },
  AvgDialog_73783_Content_77 = {
    Text = "%player%, você não precisa distinguir entre humanos e insetos. Apenas mantenha-se fiel ao que você deseja defender."
  },
  AvgDialog_73783_Content_78 = {
    Text = "Por exemplo, a autoconsciência dos humanos e suas almas."
  },
  AvgDialog_73783_Content_79 = {Text = "..."},
  AvgDialog_73783_Content_8 = {
    Text = "{Male=ele,Female=ela} não é traidor, {Male=ele,Female=ela}, {Male=ele,Female=ela} é meu amigo."
  },
  AvgDialog_73783_Content_80 = {
    Text = "...Por que você quer me ajudar? Quero dizer, nós nos conhecemos há pouco tempo, e minha atitude..."
  },
  AvgDialog_73783_Content_81 = {
    Text = "Porque eu também estou me mantendo fiel ao que acredito."
  },
  AvgDialog_73783_Content_82 = {
    Text = "Aqui só estamos nós dois humanos, e eu sempre quis um amigo."
  },
  AvgDialog_73783_Content_83 = {
    Text = "Embora os humanos possam ser cruéis, eles também possuem um lado sincero e bondoso, ajudando-se mutuamente, apoiando uns aos outros, superando dificuldades juntos e acolhendo uma manhã brilhante e um futuro esperançoso."
  },
  AvgDialog_73783_Content_84 = {
    Text = "E este é o testemunho—testemunhando nossa assistência mútua, repleta das virtudes da humanidade."
  },
  AvgDialog_73783_Content_85 = {
    Text = "O inseto esperando para emergir de sua crisálida agora foi colocado em suas mãos."
  },
  AvgDialog_73783_Content_86 = {Text = "..."},
  AvgDialog_73783_Content_87 = {Text = "Obrigado."},
  AvgDialog_73783_Content_88 = {
    Text = "Você olha para o inseto, em silêncio."
  },
  AvgDialog_73783_Content_89 = {
    Text = "Justo quando você estava prestes a dizer algo, Clementine de repente olhou para cima."
  },
  AvgDialog_73783_Content_9 = {
    Text = "\"Outra Clementine\" agarrou Oliver, então Oliver inclinou a cabeça de maneira antinatural, parecendo congelar, reagindo apenas alguns segundos depois."
  },
  AvgDialog_73783_Content_90 = {
    Text = "Um som nauseante e úmido de dilaceração se ergue no ar. Enormes patas de aranha irrompem pelos corpos dos oficiais e dos transeuntes, espirrando sangue espesso com cheiro de ferro por todo você."
  },
  AvgDialog_73783_Content_91 = {
    Text = "Ela me encontrou. Eu devo me esconder!"
  },
  AvgDialog_73783_Content_92 = {
    Text = "Clementine corre para longe. \nCom a visão desobstruída, você finalmente consegue ver claramente a \"ela\" mencionada por Clementine."
  },
  AvgDialog_73783_Content_93 = {
    Text = "Outra Clementine?"
  },
  AvgDialog_73783_Content_94 = {
    Text = "Ela está me observando, ou..."
  },
  AvgDialog_73783_Content_95 = {
    Text = "Antes que você termine de falar, outra Clementine desaparece. \nAgora você está certo de que o alvo da atenção é você."
  },
  AvgDialog_73783_Content_96 = {
    Text = "Este é o quarto espiritual de Clementine; teoricamente, deveria haver apenas uma \"Clementine.\" Mas agora..."
  },
  AvgDialog_73783_Content_97 = {
    Text = "Por que Clementine se dividiu em outro eu?"
  },
  AvgDialog_73783_Content_98 = {
    Text = "Não, não há tempo para pensar nisso agora, a coisa mais importante é encontrar a Chave de Prata."
  },
  AvgDialog_73783_Content_99 = {
    Text = "Na noite profunda, quando todos adormeceram, a vigilância deve estar no seu ponto mais fraco. É quando irei usar o rastreamento espiritual para encontrar a Chave Prata."
  },
  AvgDialog_73784_Content_10 = {
    Text = "Alguém invadiu aqui!"
  },
  AvgDialog_73784_Content_11 = {
    Text = "Eu sinto isso."
  },
  AvgDialog_73784_Content_12 = {
    Text = "Para ser honesto, estou muito curioso sobre quem é o segundo inseto preso na rede."
  },
  AvgDialog_73784_Content_13 = {
    Text = "As luzes acenderam silenciosamente, revelando o sorriso de curiosidade e exploração de Clementine."
  },
  AvgDialog_73784_Content_14 = {
    Text = "Independentemente de quem..."
  },
  AvgDialog_73784_Content_15 = {
    Text = "Eu acolho muito isso."
  },
  AvgDialog_73784_Content_16 = {
    Text = "O canto dos insetos, o canto onipresente dos insetos."
  },
  AvgDialog_73784_Content_17 = {
    Text = "Um grito grotesco, evocando nojo visceral, surge através dos seus vasos sanguíneos e veias, espremendo-se em seu cérebro enquanto o sangue flui."
  },
  AvgDialog_73784_Content_18 = {
    Text = "Está agitando seu cérebro, está destruindo seu cérebro, está — reformulando seu cérebro."
  },
  AvgDialog_73784_Content_19 = {
    Text = "......Teste de comunicação, teste de comunicação."
  },
  AvgDialog_73784_Content_2 = {Text = "Olhos"},
  AvgDialog_73784_Content_20 = {
    Text = "Você pode ouvir minha voz?"
  },
  AvgDialog_73784_Content_21 = {
    Text = "...Eu posso."
  },
  AvgDialog_73784_Content_22 = {
    Text = "Você solta um longo suspiro, segurando a dor de cabeça, e força-se a permanecer consciente. \nFinalmente, o odioso zumbido dos insetos desaparece."
  },
  AvgDialog_73784_Content_23 = {
    Text = "Você se encontra em um edifício que se assemelha a um sanatório, com inúmeras Portas se estendendo para a escuridão ao longo do corredor silencioso e vazio."
  },
  AvgDialog_73784_Content_24 = {
    Text = "Um sanatório? Por que estou aqui"
  },
  AvgDialog_73784_Content_25 = {
    Text = "Você está me perguntando? Talvez eu deva encontrar uma oportunidade para debugar seu Corpo e verificar se seu módulo de Memória está funcionando corretamente."
  },
  AvgDialog_73784_Content_26 = {
    Text = "... Talvez eu não tenha nenhum módulo de memória."
  },
  AvgDialog_73784_Content_27 = {
    Text = "Isso não é importante. O que importa é, você encontrou William?"
  },
  AvgDialog_73784_Content_28 = {
    Text = "<Yellow:William>... Sim, estou aqui para encontrar <Yellow:William>."
  },
  AvgDialog_73784_Content_29 = {
    Text = "Parece que não há progresso por enquanto."
  },
  AvgDialog_73784_Content_3 = {
    Text = "No quarto escuro e estranho, inúmeros olhos observavam o único ser vivo.\nNeste momento, soaram passos e um segundo ser vivo apareceu.\n\n."
  },
  AvgDialog_73784_Content_30 = {
    Text = "Imitando o emblema de mythag, criar um comunicador para ação independente é a escolha certa."
  },
  AvgDialog_73784_Content_31 = {
    Text = "Comunicador? Eu acho que deveria ser um monitor."
  },
  AvgDialog_73784_Content_32 = {
    Text = "É tudo a mesma coisa. Você é meu resultado experimental crucial e deve sempre permanecer sob meu controle."
  },
  AvgDialog_73784_Content_33 = {
    Text = "Na verdade, se não fosse necessário reconstruir o laboratório e você estivesse insistindo em encontrar William, eu não teria deixado você fora da minha vista."
  },
  AvgDialog_73784_Content_34 = {
    Text = "O que mais posso dizer... Obrigado pelo seu apoio?"
  },
  AvgDialog_73784_Content_35 = {
    Text = "Não precisa me agradecer. Sinta-se à vontade para me contatar se precisar de algo."
  },
  AvgDialog_73784_Content_36 = {
    Text = "Eu até consigo encontrar tempo para cuidar do meu filhote."
  },
  AvgDialog_73784_Content_37 = {
    Text = "Então, a comunicação foi completamente cortada, e o silêncio retornou aos arredores."
  },
  AvgDialog_73784_Content_38 = {
    Text = "......Esqueça. Eu deveria me concentrar em encontrar William primeiro."
  },
  AvgDialog_73784_Content_39 = {
    Text = "Primeiro vi uma figura que parecia com William, então o persegui na floresta..."
  },
  AvgDialog_73784_Content_4 = {
    Text = "Por que a luz não está acesa?"
  },
  AvgDialog_73784_Content_40 = {Text = "Ei, pare!"},
  AvgDialog_73784_Content_41 = {
    Text = "A figura que se assemelhava a William permaneceu indiferente, continuando a correr sem intenção de desacelerar."
  },
  AvgDialog_73784_Content_42 = {Text = "William?!"},
  AvgDialog_73784_Content_43 = {
    Text = "Você chama, e a outra parte finalmente para e se vira."
  },
  AvgDialog_73784_Content_44 = {
    Text = "Mas você não viu nada."
  },
  AvgDialog_73784_Content_45 = {
    Text = "Naquele momento, um grito estranho e repugnante repentinamente ecoou, causando o embaçamento de sua consciência."
  },
  AvgDialog_73784_Content_46 = {
    Text = "Em um estado de atordoamento, parece que incontáveis insetos estão cantando alegremente enquanto penetram seu couro cabeludo, rastejando pelo seu cérebro. Os cílios em suas patas roçam contra suas terminações nervosas mais delicadas, fazendo com que cada cabelo do seu corpo fique em pé."
  },
  AvgDialog_73784_Content_47 = {
    Text = "Vá embora!"
  },
  AvgDialog_73784_Content_48 = {
    Text = "Você acena os braços para espantar esses insetos meio reais, meio ilusórios, e quando abre os olhos novamente, se encontra dentro do sanatório."
  },
  AvgDialog_73784_Content_49 = {
    Text = "Fui parar em um domínio desconhecido ou no sonho de alguém?"
  },
  AvgDialog_73784_Content_5 = {
    Text = "A luz pode acender a racionalidade nas pessoas; enquanto aproveito o tempo, desencadeei isso involuntariamente."
  },
  AvgDialog_73784_Content_50 = {
    Text = "Atualmente, as informações são limitadas e nenhuma conclusão pode ser alcançada. Talvez eu deva perguntar a alguém."
  },
  AvgDialog_73784_Content_51 = {
    Text = "Em seguida, a comunicação foi completamente interrompida e o silêncio retornou ao redor."
  },
  AvgDialog_73784_Content_52 = {
    Text = "Olá, posso perguntar se isto é—"
  },
  AvgDialog_73784_Content_53 = {
    Text = "De qual quarto de paciente você saiu correndo?"
  },
  AvgDialog_73784_Content_54 = {
    Text = "Uh, eu não sou um paciente. Eu apenas entrei acidentalmente como um investigador."
  },
  AvgDialog_73784_Content_55 = {
    Text = "Uma vez que você entra aqui, você é um paciente."
  },
  AvgDialog_73784_Content_56 = {
    Text = "<Red: Pacientes estão proibidos de deixar o quarto sem autorização!>"
  },
  AvgDialog_73784_Content_57 = {
    Text = "<RedShake:Pacientes estão proibidos de sair do quarto! Pacientes estão proibidos de sair do quarto!! Pacientes estão proibidos de sair do quarto!!!>"
  },
  AvgDialog_73784_Content_58 = {
    Text = "O médico repetiu mecanicamente, então de repente se aproximou e prendeu seu pulso."
  },
  AvgDialog_73784_Content_59 = {
    Text = "O que aconteceu com você? Solte!"
  },
  AvgDialog_73784_Content_6 = {
    Text = "Além disso, a escuridão torna a dor e o desespero nessas memórias ainda mais deliciosos."
  },
  AvgDialog_73784_Content_60 = {
    Text = "Você bloqueia defensivamente seus movimentos, rasgando acidentalmente a máscara do Doutor."
  },
  AvgDialog_73784_Content_61 = {
    Text = "Como se uma cortina invisível tivesse sido puxada, revelando a verdade diante de você—"
  },
  AvgDialog_73784_Content_62 = {
    Text = "Então onde deveriam estar os rostos humanos, não há narizes ou bocas, apenas os olhos compostos torcidos e as partes bucais afiadas dos insetos."
  },
  AvgDialog_73784_Content_63 = {
    Text = "Estrangeiro @1, Invasão @2"
  },
  AvgDialog_73784_Content_64 = {
    Text = "Um sibilo familiar e irritante emana das mandíbulas que se contorcem, causando uma aguda picada em seu espírito e turvando sua consciência."
  },
  AvgDialog_73784_Content_65 = {
    Text = "@3Contenção@2"
  },
  AvgDialog_73784_Content_66 = {
    Text = "Sob o chamado profano do inseto, mais Doutores apareceram, arrastando você à força para o cômodo mais próximo."
  },
  AvgDialog_73784_Content_67 = {
    Text = "<Shake:...>"
  },
  AvgDialog_73784_Content_68 = {
    Text = "Você não se atreve a se mover—incontáveis pernas de insetos quitinosos perfuraram seus braços, até mesmo despedaçando seus ossos."
  },
  AvgDialog_73784_Content_69 = {
    Text = "No final, você foi jogado no canto da sala como um saco."
  },
  AvgDialog_73784_Content_7 = {
    Text = "...Cabe a você. Eu só quero saber se ele está bem?"
  },
  AvgDialog_73784_Content_70 = {
    Text = "@2Forasteiro@1, transformação@2"
  },
  AvgDialog_73784_Content_71 = {
    Text = "Transmutação@3"
  },
  AvgDialog_73784_Content_72 = {
    Text = "Então os gritos estranhos se aproximam, formando uma sombra que te envolve completamente, trazendo um duplo terror de natureza tanto fisiológica quanto espiritual."
  },
  AvgDialog_73784_Content_73 = {
    Text = "<Shake: Saia...>"
  },
  AvgDialog_73784_Content_74 = {
    Text = "Você suporta a dor para tocar a Chave Prata. Neste momento de dor excruciante e consciência turva, você precisa de sua ajuda."
  },
  AvgDialog_73784_Content_75 = {
    Text = "Mas o sangue encharcou tudo. A Chave de Prata escorregou de seus dedos."
  },
  AvgDialog_73784_Content_76 = {
    Text = "Transmutação@3, Transmutação@3"
  },
  AvgDialog_73784_Content_77 = {
    Text = "A sombra se aproxima. Os tentáculos distintos do inseto já lamberam sua coroa de forma viscosa."
  },
  AvgDialog_73784_Content_78 = {
    Text = "Seu cérebro de repente lateja de dor, como se algo tivesse perfurado o córtex cerebral, penetrando profundamente e atingindo a alma."
  },
  AvgDialog_73784_Content_79 = {
    Text = "<Shake: Ah...>"
  },
  AvgDialog_73784_Content_8 = {
    Text = "Oh, você ainda está tão impaciente. Um inseto preso na teia da aranha não consegue escapar."
  },
  AvgDialog_73784_Content_80 = {
    Text = "Neste momento, um sino agudo soou repentinamente pelo sanatório, como se emergisse das profundezas da alma, onipresente."
  },
  AvgDialog_73784_Content_81 = {
    Text = "@2Forasteiro@1, invasão@2?"
  },
  AvgDialog_73784_Content_82 = {
    Text = "Contenha @2 estranhos @2!"
  },
  AvgDialog_73784_Content_83 = {
    Text = "Após o breve e estranho zumbido dos insetos, você vê aquelas terríveis figuras se afastando.  \nE junto com elas, a luz também desaparece."
  },
  AvgDialog_73784_Content_84 = {
    Text = "A luz do lado de fora da porta vai diminuindo gradualmente em uma linha fina e depois desaparece completamente."
  },
  AvgDialog_73784_Content_85 = {
    Text = "Você cai na escuridão primitiva, deixando para trás um corpo cheio de feridas neste lugar desconhecido."
  },
  AvgDialog_73784_Content_9 = {
    Text = "Acelere, o plano deve prosseguir..."
  },
  AvgDialog_73785_Content_1 = {
    Text = "Incontáveis sonhos"
  },
  AvgDialog_73785_Content_10 = {
    Text = "Clementine sentiu uma onda de náusea e não conseguiu evitar de vomitar."
  },
  AvgDialog_73785_Content_11 = {Text = "@3?"},
  AvgDialog_73785_Content_12 = {
    Text = "Estou bem, obrigado pela sua preocupação... Uh!"
  },
  AvgDialog_73785_Content_13 = {Text = "@4@3?"},
  AvgDialog_73785_Content_14 = {
    Text = "Não, não há necessidade de descanso. Eu só... Eu estive aqui tempo demais..."
  },
  AvgDialog_73785_Content_15 = {
    Text = "Há tanto tempo que já esqueceu de si mesmo, há tanto tempo que já perdeu a si mesmo.\nNeste ninho, sem saída."
  },
  AvgDialog_73785_Content_16 = {
    Text = "Você pergunta quando o próximo grupo de amigos vai chegar? Para ser honesto, realmente não espero vê-los."
  },
  AvgDialog_73785_Content_17 = {
    Text = "O mundo exterior é muito mais maravilhoso do que aqui... Pelo menos, é isso que minhas memórias turvas me dizem."
  },
  AvgDialog_73785_Content_18 = {
    Text = "Desta vez, o amigo que só tinha Caro desconhecido à esquerda não falou, apenas olhou profundamente para Clementine."
  },
  AvgDialog_73785_Content_19 = {
    Text = "Por algum motivo, ela viu uma profunda tristeza naquela parte que mal poderia ser chamada de \"olhos\", uma tristeza que não poderia ser aliviada nem em uma vida inteira."
  },
  AvgDialog_73785_Content_2 = {Text = "Chiado—"},
  AvgDialog_73785_Content_20 = {
    Text = "Suspiro! Eu me esqueci completamente do porquê de estar aqui. E você, Sr. Monstro?"
  },
  AvgDialog_73785_Content_21 = {
    Text = "@4@4, @2@4."
  },
  AvgDialog_73785_Content_22 = {
    Text = "Você disse que veio aqui para se reunir com sua filha? Que tocante."
  },
  AvgDialog_73785_Content_23 = {
    Text = "Então, você encontrou sua filha?"
  },
  AvgDialog_73785_Content_24 = {Text = "@2—"},
  AvgDialog_73785_Content_25 = {
    Text = "Uma borboleta luminosa voou do peito do Sr. Monstro."
  },
  AvgDialog_73785_Content_26 = {
    Text = "Homenagem ondulam como água e se dissipam, transformando-se numa nuvem de borboletas esvoaçantes."
  },
  AvgDialog_73785_Content_27 = {
    Text = "%player%, consegue me ouvir?"
  },
  AvgDialog_73785_Content_28 = {
    Text = "Clementine? Você está viva?!"
  },
  AvgDialog_73785_Content_29 = {
    Text = "...Desculpe. Não tenho muito tempo."
  },
  AvgDialog_73785_Content_3 = {
    Text = "Outro pupa humano se abriu, e o Caro lutou para sair, mas não muito depois, morreu completamente."
  },
  AvgDialog_73785_Content_30 = {
    Text = "Ainda há uma coisa que preciso fazer antes de partir."
  },
  AvgDialog_73785_Content_31 = {
    Text = "Uma borboleta esvoaça ao redor da sua mão, sua luz servindo de guia, mas você se afasta."
  },
  AvgDialog_73785_Content_32 = {
    Text = "...Se minha fuga deve vir ao custo da sua morte, Clementine, então por favor, deixe-me recusar."
  },
  AvgDialog_73785_Content_33 = {
    Text = "Não vou deixar mais ninguém se sacrificar por mim."
  },
  AvgDialog_73785_Content_34 = {
    Text = "A borboleta insiste, circulando a sua mão. Você pensa ter ouvido um suspiro suave."
  },
  AvgDialog_73785_Content_35 = {
    Text = "Às vezes, eu me pergunto se meu nascimento foi o resultado da sua criação ou da minha resposta. Agora percebo que nenhum dos dois é a resposta."
  },
  AvgDialog_73785_Content_36 = {
    Text = "É a dor no coração de Clemmie que deu origem a mim."
  },
  AvgDialog_73785_Content_37 = {
    Text = "%player%, não estou caminhando em direção à morte, mas sim em direção ao renascimento, afinal, eu sou sempre \"Clementine\", não sou?"
  },
  AvgDialog_73785_Content_38 = {
    Text = "A borboleta pousa em sua palma, como um suave aperto de mão; desta vez, você não pode mais recusar."
  },
  AvgDialog_73785_Content_39 = {
    Text = "%player%, naquela época, não fui eu quem respondeu a você, mas nós; foi Clementine quem respondeu a você."
  },
  AvgDialog_73785_Content_4 = {
    Text = "Thomas? Não, Edward? Também não é isso. Ah, agora lembro, é Benjamin."
  },
  AvgDialog_73785_Content_40 = {
    Text = "A luz tênue da borboleta de repente se intensifica, inundando sua visão—"
  },
  AvgDialog_73785_Content_41 = {
    Text = "Uma chave prateada aparece em seu campo de visão."
  },
  AvgDialog_73785_Content_42 = {
    Text = "Na desesperança que se repete dia após dia, já não me atrevo a esperar pela redenção, mas você... ouviu meu grito por ajuda..."
  },
  AvgDialog_73785_Content_43 = {
    Text = "Vamos marchar rumo à bela aurora e ao futuro, %player%. Seu brilho me iluminou..."
  },
  AvgDialog_73785_Content_44 = {
    Text = "No sorriso de Clementine, que estava gradualmente se dissipando em pontos de luz, parecia-se ouvir o som de uma borboleta luminosa abrindo suas asas."
  },
  AvgDialog_73785_Content_45 = {
    Text = "—Eu quero ver o verdadeiro mundo como humano e começar uma nova vida."
  },
  AvgDialog_73785_Content_46 = {
    Text = "—Eu quero preservar minha identidade como humano, e desejo morrer como um."
  },
  AvgDialog_73785_Content_47 = {
    Text = "No espaço negro como breu, Clementine sorridente desaparece, deixando apenas a chave de prata. \nEssa rápida transição do brilhante para o escuro te deixa em silêncio por um momento."
  },
  AvgDialog_73785_Content_48 = {
    Text = "Então, você pegou a Chave de Prata."
  },
  AvgDialog_73785_Content_49 = {
    Text = "Eu irei lembrar de você, uma pessoa que manteve sua humanidade até a morte."
  },
  AvgDialog_73785_Content_5 = {Text = "@3."},
  AvgDialog_73785_Content_50 = {
    Text = "É hora de começar a trabalhar, %player%."
  },
  AvgDialog_73785_Content_51 = {
    Text = "Seja neste mundo ou em outro, alguém está esperando por você."
  },
  AvgDialog_73785_Content_52 = {
    Text = "No altar do ritual interrompido, você agarra a Chave de Prata, trocando olhares com Clementine—vocês dois percebem que esta é a batalha final."
  },
  AvgDialog_73785_Content_53 = {
    Text = "No final, tudo chegou ao ponto que eu menos queria ver."
  },
  AvgDialog_73785_Content_54 = {
    Text = "Claramente, claramente eu esperava que você se tornasse meu parente... que pena."
  },
  AvgDialog_73785_Content_55 = {
    Text = "O inseto blasfemo zumbindo e o zumbido da chave de prata soaram juntos. Em sua consciência turva, você vê uma projeção terrível se formando atrás de Clementine."
  },
  AvgDialog_73785_Content_56 = {
    Text = "Meu povo, respondam ao meu chamado!"
  },
  AvgDialog_73785_Content_57 = {
    Text = "Pela sua Chegada, por essas novas vidas que se aproximam."
  },
  AvgDialog_73785_Content_58 = {
    Text = "%player%, também por favor sinta o verdadeiro poder de @2Zerg, através disso, você reconhecerá a crueldade e a vastidão do universo, bem como......"
  },
  AvgDialog_73785_Content_59 = {
    Text = "A insignificância e a natureza Frágil dos humanos."
  },
  AvgDialog_73785_Content_6 = {
    Text = "Ou talvez não? Certo, devo admitir, conhecer muitas pessoas não é uma coisa boa; já comecei a esquecer seus nomes."
  },
  AvgDialog_73785_Content_60 = {
    Text = "O terror indescritível avança em sua direção, destruindo sua sanidade.\nSeu cérebro, agora em branco, de repente se recorda das palavras de Melt·Dore."
  },
  AvgDialog_73785_Content_61 = {
    Text = "Em um momento crítico, simular as flutuações de energia do espaço também pode servir como um método de ataque..."
  },
  AvgDialog_73785_Content_7 = {
    Text = "Deixe-me pensar, começou com o Velho John e a Pequena Bella, depois Austin, Berkeley, Bell-Dana, Christopher, Isaac, Emma, James, Isidore, Ai..."
  },
  AvgDialog_73785_Content_8 = {
    Text = "<Shake: Hmmm...!!!>"
  },
  AvgDialog_73785_Content_9 = {
    Text = "<Italic:Essa pessoa cavava a terra com as mãos, o corpo contorcido, ofegante, completamente esquecida do tempo, da segurança, da localização e até mesmo de sua própria intenção, rastejando freneticamente para frente no subsolo envolto em escuridão eterna>"
  },
  AvgDialog_73786_Content_1 = {
    Text = "Desta vez, você também escolhe recusar nossa Relíquia?"
  },
  AvgDialog_73786_Content_10 = {
    Text = "Em silêncio, a cortina invisível é levantada, revelando a verdade. Então ela viu —"
  },
  AvgDialog_73786_Content_12 = {
    Text = "Caro que não podia mais ser reconhecido arranhava o solo, gritando sem parar e rastejando para frente em repetição mecânica. Ele esqueceu o tempo, a segurança, a direção, e até mesmo a intenção de vir aqui."
  },
  AvgDialog_73786_Content_13 = {
    Text = "Ele deveria ter morrido, mas o forte desejo em seu coração o manteve vivo. \nMesmo que ele já tenha esquecido qual era exatamente esse desejo."
  },
  AvgDialog_73786_Content_15 = {
    Text = "Sílabas imundas que não pertencem aos humanos saem de sua boca, sem nenhum significado.\nEle apenas emite sons com o instinto mais básico e inferior de um inseto."
  },
  AvgDialog_73786_Content_16 = {
    Text = "Um som nauseante e úmido de dilaceração se ergue no ar. Enormes patas de aranha irrompem pelos corpos dos oficiais e dos transeuntes, espirrando sangue espesso com cheiro de ferro por todo você."
  },
  AvgDialog_73786_Content_17 = {
    Text = "Clementine desviou o olhar, angustiada. Na verdade, ela não tinha cabeça alguma, pois já estava morta, restando apenas a consciência e a Prata - @4 disse que era sua prova especial."
  },
  AvgDialog_73786_Content_18 = {
    Text = "Pai, Pai... Pai!"
  },
  AvgDialog_73786_Content_19 = {
    Text = "Clementine chamou com esforço, mas seu grito não produziu som e nunca seria ouvido por ninguém."
  },
  AvgDialog_73786_Content_2 = {
    Text = "Sim, eu recuso."
  },
  AvgDialog_73786_Content_20 = {Text = "Cl...@3"},
  AvgDialog_73786_Content_21 = {
    Text = "Pai, você ainda se lembra de mim!?"
  },
  AvgDialog_73786_Content_22 = {
    Text = "Como se por um milagre, o pai a olhasse. O Caro coberto de escamas de inseto agarrou seu último resquício no mundo."
  },
  AvgDialog_73786_Content_23 = {
    Text = "Sim, Pai, eu sou Clemmie, sua amada filha —"
  },
  AvgDialog_73786_Content_24 = {
    Text = "Ela grita silenciosamente, mas logo perde toda a voz—ela observa impotente enquanto seu Prata é engolido por seu pai."
  },
  AvgDialog_73786_Content_25 = {
    Text = "Você precisa limpar sua memória, criança? Nós dissemos que poderíamos repeti-la inúmeras vezes."
  },
  AvgDialog_73786_Content_26 = {
    Text = "Sim, obrigado. Por favor, apague minhas memórias."
  },
  AvgDialog_73786_Content_27 = {
    Text = "Eu percebi de repente que ficar neste ninho para sempre também é bastante agradável."
  },
  AvgDialog_73786_Content_28 = {
    Text = "Receio que a palavra \"para sempre\" não seja adequada para os humanos."
  },
  AvgDialog_73786_Content_29 = {
    Text = "Então o item especial realmente prolongou ligeiramente a existência de seu pai e permitiu que ele se juntasse à nossa troca de testamentos, mas todos nós acreditamos que essa situação em breve chegará ao fim."
  },
  AvgDialog_73786_Content_3 = {
    Text = "Mesmo estando a um passo da verdade do universo, mesmo que bastasse coexistir conosco para compreender os mistérios das dimensões e explorar o cosmos inteiro?"
  },
  AvgDialog_73786_Content_30 = {
    Text = "<Shake: Por que...>"
  },
  AvgDialog_73786_Content_31 = {
    Text = "Porque a própria existência da humanidade é tão frágil."
  },
  AvgDialog_73786_Content_32 = {
    Text = "Para escapar desta fragilidade, é necessário transcender o conceito de humanidade."
  },
  AvgDialog_73786_Content_33 = {Text = "..."},
  AvgDialog_73786_Content_34 = {
    Text = "Aquela coisa... Prata, pode permitir que ele transcenda?"
  },
  AvgDialog_73786_Content_35 = {
    Text = "Estou com medo de que isso pertence a você—um milagre nascido da sua vida e vontade."
  },
  AvgDialog_73786_Content_36 = {Text = "..."},
  AvgDialog_73786_Content_37 = {
    Text = "Por que você está me contando essas coisas? Por que agora?! É só para que possamos nos fundir e nos tornar um monstro?"
  },
  AvgDialog_73786_Content_38 = {
    Text = "Como uma Vida de alta dimensão, que benefícios você ganha ao ignorar, manipular e brincar conosco, esses seres de baixa dimensão!"
  },
  AvgDialog_73786_Content_39 = {
    Text = "Não fomos tão mal-educados assim, e fomos bastante educados segundo os padrões humanos.\nÉ que os humanos em si são muito frágeis."
  },
  AvgDialog_73786_Content_4 = {
    Text = "Você é uma criança especial, o recipiente mais adequado para nós, @2 insetoides, cuja vontade pereceu."
  },
  AvgDialog_73786_Content_40 = {
    Text = "E você tem a chance de transcender tudo isso. \nBasta tomar uma decisão firme e deixar de se apegar a esses falsos confortos."
  },
  AvgDialog_73786_Content_41 = {
    Text = "Um som nauseante e úmido de dilaceração se ergue no ar. Enormes patas de aranha irrompem pelos corpos dos oficiais e dos transeuntes, espirrando sangue espesso com cheiro de ferro por todo você."
  },
  AvgDialog_73786_Content_42 = {
    Text = "Uma sensação de impotência emerge do fundo de sua alma, deixando Clementine sem palavras. Ela não sabe o que dizer, nem o que pode dizer—"
  },
  AvgDialog_73786_Content_43 = {
    Text = "<Italic:A humanidade é simplesmente pequena demais, frágil demais.>"
  },
  AvgDialog_73786_Content_44 = {
    Text = "De repente, uma mão de carne tocou sua testa. Era seu pai."
  },
  AvgDialog_73786_Content_45 = {
    Text = "Então, ele a abraçou. Segurou-a com todas as suas forças."
  },
  AvgDialog_73786_Content_46 = {
    Text = "@2Clementine... Desculpe... por tudo o que eu fiz..."
  },
  AvgDialog_73786_Content_47 = {
    Text = "Por que está se desculpando? A menos que..."
  },
  AvgDialog_73786_Content_48 = {
    Text = "Não, não faça isso, não faça isso!\nEu não quero nenhuma vida transcendente, pai, eu não quero nenhuma vida transcendente!"
  },
  AvgDialog_73786_Content_49 = {
    Text = "No entanto, aquele único calor também desapareceu.\nEla perdeu completamente a conexão com este mundo."
  },
  AvgDialog_73786_Content_5 = {
    Text = "Protegeremos você, permitindo que atravesse o limiar da evolução da vida—você não veio aqui para realizar o ritual para esse propósito?"
  },
  AvgDialog_73786_Content_50 = {Text = "Chiado—"},
  AvgDialog_73786_Content_51 = {
    Text = "No ninho cheio de Caro e pupas quebradas, uma luz brilhante de repente irrompeu, como um sol, iluminando este mundo."
  },
  AvgDialog_73786_Content_52 = {
    Text = "E no chão surge um mar de sangue e carne, enquanto um encouraçado chamado Humanidade colapsa, dando à luz uma vida que supera em muito a da humanidade."
  },
  AvgDialog_73786_Content_53 = {
    Text = "Mas, Pai, por que não consigo derramar uma única lágrima?"
  },
  AvgDialog_73786_Content_54 = {
    Text = "Porque os insetos não têm glândulas lacrimais nem córtex emocional\nIsso pertence aos humanos"
  },
  AvgDialog_73786_Content_6 = {
    Text = "...Eu não sei. Minhas lembranças estão se tornando cada vez mais embaçadas."
  },
  AvgDialog_73786_Content_7 = {
    Text = "We can help you restore your memory, no matter how many times it takes."
  },
  AvgDialog_73786_Content_8 = {
    Text = "A vida humana, nas dimensões do universo, é meramente um momento passageiro."
  },
  AvgDialog_73786_Content_9 = {
    Text = "Mas você está pronto para enfrentar a verdade? Nossa Relíquia."
  },
  AvgDialog_73787_Content_1 = {
    Text = "Curiosidade fatal"
  },
  AvgDialog_73787_Content_10 = {
    Text = "Em vez de lutar como uma besta encurralada, é melhor se render aqui e agora. Eu sou um cavalheiro e não maltratarei prisioneiros."
  },
  AvgDialog_73787_Content_100 = {
    Text = "Ufa, finalmente te tirei."
  },
  AvgDialog_73787_Content_101 = {
    Text = "Adivinhe o que mais eu tenho?"
  },
  AvgDialog_73787_Content_102 = {
    Text = "Seu comunicador."
  },
  AvgDialog_73787_Content_103 = {
    Text = "<Small:Corra...> Tossir, tossir..."
  },
  AvgDialog_73787_Content_104 = {
    Text = "O que você disse?"
  },
  AvgDialog_73787_Content_105 = {
    Text = "Apresse-se e escape... Fomos descobertos pelos verdadeiros governantes do sanatório..."
  },
  AvgDialog_73787_Content_106 = {
    Text = "Little William não ouviu sua voz, pois naquele exato momento, o corredor sem fim visível reverberava com inúmeros sons de batidas."
  },
  AvgDialog_73787_Content_107 = {
    Text = "Então é o som de mil portas se abrindo, o som do sanatório despertando completamente, preparando-se para devorar os desafiantes."
  },
  AvgDialog_73787_Content_108 = {
    Text = "Um alarme ensurdecedor toca, revelando o prólogo de uma fuga frenética."
  },
  AvgDialog_73787_Content_11 = {
    Text = "Sim, você apenas faz com que eles percam suas memórias, transformando-os em uma tábula rasa. Assim como William."
  },
  AvgDialog_73787_Content_12 = {
    Text = "Um som nauseante e úmido de dilaceração se ergue no ar. Enormes patas de aranha irrompem pelos corpos dos oficiais e dos transeuntes, espirrando sangue espesso com cheiro de ferro por todo você."
  },
  AvgDialog_73787_Content_13 = {
    Text = "Mas, infelizmente, após me separar deles, as memórias que trazem vestígios de sua existência se tornaram tudo para mim."
  },
  AvgDialog_73787_Content_14 = {
    Text = "Você força a si mesmo a ignorar a dor pulsante em sua cabeça, estendendo a mão em direção ao peito —"
  },
  AvgDialog_73787_Content_15 = {
    Text = "Boneca: Inferno, você está ouvindo?"
  },
  AvgDialog_73787_Content_16 = {
    Text = "Estou aqui. Sempre estive aqui."
  },
  AvgDialog_73787_Content_17 = {
    Text = "Então, prepare-se para ativar essa função."
  },
  AvgDialog_73787_Content_18 = {
    Text = "...Eu pensei que você não soubesse sobre essa função."
  },
  AvgDialog_73787_Content_19 = {
    Text = "Na verdade, eu sei. Dei uma olhada no seu plano de design."
  },
  AvgDialog_73787_Content_2 = {
    Text = "Talvez pudéssemos aumentar um pouco a intensidade da nossa cura? Eu tenho um compromisso e estou com pressa."
  },
  AvgDialog_73787_Content_20 = {
    Text = "Sua mão passa pela chave de prata, pousa sobre o emblema falso de Mythag de Karen, e a joga em direção à porta."
  },
  AvgDialog_73787_Content_21 = {
    Text = "Fusão·Boneca."
  },
  AvgDialog_73787_Content_22 = {Text = "...Tsk."},
  AvgDialog_73787_Content_23 = {
    Text = "Estalo, o emblema de Mythag de imitação brilha com ligeira corrente elétrica, voando em um arco parabólico em direção a Herbert."
  },
  AvgDialog_73787_Content_24 = {
    Text = "Hmph, apenas uma luta fútil."
  },
  AvgDialog_73787_Content_25 = {
    Text = "Herbert deu um passo para trás, mas o emblema da escola ainda acertou em cheio sua testa, a testa do gato."
  },
  AvgDialog_73787_Content_26 = {Text = "Miau—!!!"},
  AvgDialog_73787_Content_27 = {
    Text = "Sob a estimulação da corrente elétrica, o gato gritou e pulou, correndo pela sala."
  },
  AvgDialog_73787_Content_28 = {
    Text = "Galatea! O que vocês estão fazendo parados? Pegue agora!"
  },
  AvgDialog_73787_Content_29 = {
    Text = "Não, não, não seja tão brusco; seja um pouco mais gentil. É meu animal de estimação mais amado—"
  },
  AvgDialog_73787_Content_3 = {
    Text = "Herbert, parado na porta, sorriu, e imediatamente, os ataques das pessoas modificadas se tornaram ferozes."
  },
  AvgDialog_73787_Content_30 = {
    Text = "Você poderia dizer que a cena era um total caos, e isso é exatamente o que você precisa."
  },
  AvgDialog_73787_Content_31 = {
    Text = "Mesmo nesta situação, Herbert, você não entrou neste quarto. Parece que meu palpite estava correto."
  },
  AvgDialog_73787_Content_32 = {Text = "...?"},
  AvgDialog_73787_Content_33 = {
    Text = "Este é um sanatório para a mente, então os pacientes têm seus próprios quartos mentais, permitindo que os médicos tenham acesso livre a qualquer quarto."
  },
  AvgDialog_73787_Content_34 = {
    Text = "William e eu somos pacientes; eles são os médicos, mas você, Herbert — você é apenas você mesmo."
  },
  AvgDialog_73787_Content_35 = {
    Text = "Então e daí? Eu não preciso de nenhum curativo."
  },
  AvgDialog_73787_Content_36 = {
    Text = "Isto é incerto — William, ponha-se a trabalhar."
  },
  AvgDialog_73787_Content_37 = {Text = "Recebido~"},
  AvgDialog_73787_Content_38 = {
    Text = "Aproveitando a confusão, o Pequeno William, que havia escorregado até a porta, sorriu e empurrou Herbert, cuja atenção havia sido desviada por você, para dentro do quarto."
  },
  AvgDialog_73787_Content_39 = {
    Text = "Um som nauseante e úmido de dilaceração se ergue no ar. Enormes patas de aranha irrompem pelos corpos dos oficiais e dos transeuntes, espirrando sangue espesso com cheiro de ferro por todo você."
  },
  AvgDialog_73787_Content_4 = {
    Text = "Não podemos nos dar ao luxo de atrasar mais. Somos apenas dois, mas ele tem o apoio de um sanatório inteiro."
  },
  AvgDialog_73787_Content_40 = {
    Text = "Quando Herbert entrou na sala, você sentiu um zumbido familiar — tanto sua mente quanto esta sala estavam zumbindo."
  },
  AvgDialog_73787_Content_41 = {
    Text = "A paisagem na sala continua derretendo e solidificando, como se estivesse confusa sobre qual mente de paciente projetar, tornando impossível ficar em pé."
  },
  AvgDialog_73787_Content_42 = {
    Text = "%player%, saia rapidamente! Estou fechando a porta em breve!"
  },
  AvgDialog_73787_Content_43 = {
    Text = "Little William estendeu a mão para você do lado de fora da porta, e ao mesmo tempo, outra mão se estendeu em sua direção—"
  },
  AvgDialog_73787_Content_44 = {
    Text = "Eu disse que tinha um compromisso. Talvez você seja mais adequado a ficar aqui do que eu."
  },
  AvgDialog_73787_Content_45 = {
    Text = "Então uma mão envolve seu pescoço por trás, começando a apertar e puxar com força. Você não pode deixar de se inclinar para trás e agitar os braços."
  },
  AvgDialog_73787_Content_46 = {
    Text = "Em pânico, parece que você tocou em algo—"
  },
  AvgDialog_73787_Content_47 = {
    Text = "À medida que sua consciência se torna cada vez mais embaçada, você é forçado a entrar na memória de alguém."
  },
  AvgDialog_73787_Content_48 = {
    Text = "Eu acredito que mereço umas férias maravilhosas depois de terminar todas as tarefas."
  },
  AvgDialog_73787_Content_49 = {
    Text = "Você está certo, Herbert, o asilo é uma boa escolha."
  },
  AvgDialog_73787_Content_5 = {
    Text = "Eu devo encontrar uma maneira de atacar a pessoa estranha parada na porta. Ele é a chave."
  },
  AvgDialog_73787_Content_50 = {
    Text = "Meu corpo já está satisfeito, mas minha alma ainda anseia."
  },
  AvgDialog_73787_Content_51 = {
    Text = "Segure-se... %player%, eu vou... agarrar..."
  },
  AvgDialog_73787_Content_52 = {
    Text = "Parece que alguém está gritando, mas você não consegue entender o que estão dizendo."
  },
  AvgDialog_73787_Content_53 = {
    Text = "Sua mente gira como um caleidoscópio, cheia de inúmeros fragmentos de memória."
  },
  AvgDialog_73787_Content_54 = {
    Text = "Este sanatório é muito importante para mim, extremamente importante, então Herbert, me dê um motivo."
  },
  AvgDialog_73787_Content_55 = {
    Text = "Caso contrário—posso convidá-lo a entrar, e também posso convidá-lo a sair."
  },
  AvgDialog_73787_Content_56 = {
    Text = "Isto faz parte do plano, Clementine."
  },
  AvgDialog_73787_Content_57 = {
    Text = "Eu sei que você está realizando experimentos importantes aí, mas quero dizer que nossos objetivos não conflitam."
  },
  AvgDialog_73787_Content_58 = {
    Text = "Se essa é a única razão, tenho medo de que você não me convença."
  },
  AvgDialog_73787_Content_59 = {
    Text = "Você precisa de sacrifícios, muitos sacrifícios, e %player% claramente atende aos critérios, não atende?"
  },
  AvgDialog_73787_Content_6 = {
    Text = "Uma decisão inteligente, mas uma decisão sozinha não pode realizar nada."
  },
  AvgDialog_73787_Content_60 = {
    Text = "Além disso, você sempre demonstrou grande interesse por %player%. Esta é sua chance de se aproximar e observar {Male=ele,Female=ela}."
  },
  AvgDialog_73787_Content_61 = {
    Text = "Eu te peguei!"
  },
  AvgDialog_73787_Content_62 = {Text = "Ugh..."},
  AvgDialog_73787_Content_63 = {
    Text = "Garoto, cuide dos seus dentes; eles não deviam estar tocando meu braço."
  },
  AvgDialog_73787_Content_64 = {Text = "..."},
  AvgDialog_73787_Content_65 = {Text = "..."},
  AvgDialog_73787_Content_66 = {
    Text = "Na familiar clínica psicológica, a silenciosa Clementine fez você, acostumado a uma variedade de memórias, sentir-se um tanto desconfortável."
  },
  AvgDialog_73787_Content_67 = {
    Text = "Essa memória é tão estranha..."
  },
  AvgDialog_73787_Content_68 = {
    Text = "Oh? O que você acha estranho?"
  },
  AvgDialog_73787_Content_69 = {
    Text = "Tudo parece bastante estranho..."
  },
  AvgDialog_73787_Content_7 = {
    Text = "Além disso, comparado a mim, você deve se preocupar mais consigo mesmo - atividades físicas intensas podem abrir feridas, piorar a perda de sangue e levar a uma exaustão severa."
  },
  AvgDialog_73787_Content_70 = {
    Text = "Um som nauseante e úmido de dilaceração se ergue no ar. Enormes patas de aranha irrompem pelos corpos dos oficiais e dos transeuntes, espirrando sangue espesso com cheiro de ferro por todo você."
  },
  AvgDialog_73787_Content_71 = {
    Text = "Seus olhos de repente se arregalam em choque—agora há pouco, você expressou seus pensamentos em voz alta, e Clementine respondeu."
  },
  AvgDialog_73787_Content_72 = {
    Text = "Isto não é a memória de Herbert!"
  },
  AvgDialog_73787_Content_73 = {
    Text = "Claro que não. Encontrar você na memória de outra pessoa é bastante inadequado, então eu vim pessoalmente."
  },
  AvgDialog_73787_Content_74 = {
    Text = "Ah, não é bem \"presencialmente,\" no máximo é uma breve conexão mental, espero que você não se importe."
  },
  AvgDialog_73787_Content_75 = {
    Text = "Venha me ver? Por quê..."
  },
  AvgDialog_73787_Content_76 = {
    Text = "Por quê? Oh querido, como devo responder a essa pergunta?"
  },
  AvgDialog_73787_Content_77 = {
    Text = "Naturalmente, é pelas preciosas memórias em sua mente, mas não apenas por essas memórias; sua própria existência me intriga."
  },
  AvgDialog_73787_Content_78 = {
    Text = "Curiosidade? Eu não entendo..."
  },
  AvgDialog_73787_Content_79 = {
    Text = "Bem, parece que só posso dizer isso de forma direta. Este não é o meu jeito usual de falar, mas estou disposto a acomodar sua escolha."
  },
  AvgDialog_73787_Content_8 = {
    Text = "O sorriso de Herbert se aprofundou enquanto ele provocava brincando o gato em seu ombro. O gato lambeu a pata e saltou graciosamente para o painel da porta, olhando para você."
  },
  AvgDialog_73787_Content_80 = {
    Text = "Fico curioso em saber por que você conhece o meu nome, os nomes de Albino e Herbert, e como descobriu a Associação dos Escultores."
  },
  AvgDialog_73787_Content_81 = {
    Text = "Curioso sobre seu passado, suas memórias e... o outro mundo em que você existiu."
  },
  AvgDialog_73787_Content_82 = {
    Text = "Outro mundo? Como você poderia..."
  },
  AvgDialog_73787_Content_83 = {
    Text = "Oh céus, parece que realmente existe \"outro mundo\", né—"
  },
  AvgDialog_73787_Content_84 = {
    Text = "Eu preciso abrir seu cérebro, dissecar sua alma e estudá-la cuidadosamente."
  },
  AvgDialog_73787_Content_85 = {
    Text = "Ah, só de pensar nessa cena meu coração de Prata treme."
  },
  AvgDialog_73787_Content_86 = {
    Text = "Clementine se levantou sorrindo, e você sentiu que o sorriso lhe deu dor de cabeça, até tornando difícil respirar."
  },
  AvgDialog_73787_Content_87 = {
    Text = "Espere, espere... não há necessidade de você agir."
  },
  AvgDialog_73787_Content_88 = {
    Text = "Posso te contar tudo que você quer saber, em troca, deixe eu e William... não, deixe todos irem."
  },
  AvgDialog_73787_Content_89 = {
    Text = "Clementine, acredito que você é diferente de Herbert."
  },
  AvgDialog_73787_Content_9 = {
    Text = "%player%, seu corpo atingiu seu limite. Você não pode mais se conectar a aqueles Despertadores, certo?"
  },
  AvgDialog_73787_Content_90 = {
    Text = "...Que pena, estou destinado a decepcionar sua boa vontade."
  },
  AvgDialog_73787_Content_91 = {
    Text = "Porque ah, este é meu terreno de caça."
  },
  AvgDialog_73787_Content_92 = {
    Text = "À medida que sua visão turva, Clementine aparece instantaneamente diante de você, colocando a mão em sua testa."
  },
  AvgDialog_73787_Content_93 = {
    Text = "Incontáveis e agudos tilintares de insetos invadem seu cérebro, causando um caos em seus pensamentos e gradualmente fazendo você perder a força para resistir."
  },
  AvgDialog_73787_Content_94 = {
    Text = "Ah, isso mesmo, eu vi, o Guardião, Mythag, e, e—"
  },
  AvgDialog_73787_Content_95 = {
    Text = "<Shake:...!!!>"
  },
  AvgDialog_73787_Content_97 = {
    Text = "Bang— Naquele momento, o som de uma porta se fechando ecoou. Esse som não se originou daqui, desta cena."
  },
  AvgDialog_73787_Content_98 = {
    Text = "É o som do Pequeno William desligando a Sala da Mente."
  },
  AvgDialog_73787_Content_99 = {
    Text = "À medida que a espessa névoa é dissipada pelos fortes ventos, todo o horror e o caos desaparecem; na visão turva causada pela falta de oxigênio, restam apenas os corredores do sanatório e o pequeno William."
  },
  AvgDialog_73789_Content_1 = {
    Text = "Cognição refeita"
  },
  AvgDialog_73789_Content_10 = {
    Text = "Você prende aquele monstro inumano contra a parede, usando seu braço para pressionar seu pescoço."
  },
  AvgDialog_73789_Content_11 = {
    Text = "Cale a boca. Eu pergunto, você responde."
  },
  AvgDialog_73789_Content_12 = {
    Text = "%player%, se você quiser saber qualquer coisa, sinta-se à vontade para me perguntar diretamente, ficarei feliz em ajudar você."
  },
  AvgDialog_73789_Content_13 = {
    Text = "Apenas então você percebeu que havia uma terceira pessoa presente."
  },
  AvgDialog_73789_Content_14 = {
    Text = "Clementine... Eu falhei? Estou ainda no sanatório?!"
  },
  AvgDialog_73789_Content_15 = {
    Text = "Para ser preciso, <Yellow:você está no meu quarto mental>. O asilo é apenas uma concha; é a essência."
  },
  AvgDialog_73789_Content_16 = {
    Text = "...Por que me contar essas coisas?"
  },
  AvgDialog_73789_Content_17 = {
    Text = "Por que não? Você perdeu a Chave de prata e está preso no espaço sob meu controle. O que você pode fazer contra mim ainda?"
  },
  AvgDialog_73789_Content_18 = {
    Text = "Talvez, cumprir meu arranjo e se tornar meu parente seja a sua escolha mais sábia."
  },
  AvgDialog_73789_Content_19 = {
    Text = "Sem perder palavras, você se levanta e avança em direção a Clementine, pretendendo atacar. Em um instante, o ar fica estagnado, parando seu punho a poucos centímetros do rosto de Clementine, incapaz de avançar mais."
  },
  AvgDialog_73789_Content_2 = {
    Text = "Ei, acorde!"
  },
  AvgDialog_73789_Content_20 = {
    Text = "Clementine sorriu, ela apenas ficou sentada quieta sorrindo para você, e sob a pressão invisível, você baixou as mãos."
  },
  AvgDialog_73789_Content_21 = {
    Text = "É isso mesmo, boa criança."
  },
  AvgDialog_73789_Content_22 = {
    Text = "Lembre-se de manter pelo menos um nível mínimo de respeito e cooperação com seu psicólogo."
  },
  AvgDialog_73789_Content_23 = {
    Text = "Nunca admiti que você é meu psicólogo, nem nunca farei parte da sua família."
  },
  AvgDialog_73789_Content_24 = {
    Text = "Sou humano, e isso é claro para mim."
  },
  AvgDialog_73789_Content_25 = {
    Text = "Oh, não há necessidade de ter tanta certeza, porque de acordo com a teoria da cognição corporal, nossa cognição é moldada pelo corpo e sua forma de atividade."
  },
  AvgDialog_73789_Content_26 = {
    Text = "Por exemplo, um juiz pode impor penas mais severas quando está faminto do que o habitual, e a satisfação de uma pessoa com a vida está muitas vezes relacionada aos padrões de vida de seus amigos e familiares."
  },
  AvgDialog_73789_Content_27 = {
    Text = "E neste espaço, eu avancei um passo adiante: não apenas as mudanças na forma de existência afetam a cognição, mas a cognição também influencia a forma de existência."
  },
  AvgDialog_73789_Content_28 = {
    Text = "Você quer dizer... contanto que eu pense que sou um inseto, eu me tornarei um inseto?"
  },
  AvgDialog_73789_Content_29 = {
    Text = "Inteligente. Quando chegar a hora, primeiro você desenvolverá escamas de inseto em seus braços, e uma concha quitinosa cobrirá seu corpo frágil."
  },
  AvgDialog_73789_Content_3 = {
    Text = "Na escuridão, parece que alguém está continuamente chamando por você, batendo em você, compelindo-o a abrir os olhos."
  },
  AvgDialog_73789_Content_30 = {
    Text = "Então as cordas vocais, os olhos; um olho composto de 360 graus permite que você veja claramente a realidade deste mundo, assim como o universo."
  },
  AvgDialog_73789_Content_31 = {
    Text = "Por último, é a minha parte favorita, a ressonância do enxame..."
  },
  AvgDialog_73789_Content_32 = {
    Text = "Ah, você já está ansioso para sair?"
  },
  AvgDialog_73789_Content_33 = {
    Text = "Você pausa seu passo, sentindo-se sem vergonha por ter sido pego fugindo."
  },
  AvgDialog_73789_Content_34 = {
    Text = "Como se trata de terapia, é natural que o paciente ande e entenda a localização do tratamento."
  },
  AvgDialog_73789_Content_35 = {
    Text = "Você está certo, e eu ficaria feliz em acompanhá-lo nesse processo, mas tenho alguns pequenos problemas a resolver."
  },
  AvgDialog_73789_Content_36 = {
    Text = "Suspeito que isso não seja apenas um problema menor."
  },
  AvgDialog_73789_Content_37 = {
    Text = "Você penetrou com astúcia a disfarce de Clementine, querendo aproveitar essa oportunidade para extrair mais informações, mas infelizmente, Clementine não caiu na armadilha."
  },
  AvgDialog_73789_Content_38 = {
    Text = "Quanto à visita ao local de tratamento, só pode ser um incômodo para Berkeley. Espero que você não se importe."
