  AvgDialog_73789_Content_57 = {
    Text = "Você corre até não poder mais respirar e então para para levantar suas roupas—"
  },
  AvgDialog_73789_Content_58 = {
    Text = "Nos lugares onde você sente a picada, crescem escamas de um inseto."
