  AvgDialog_73789_Content_67 = {
    Text = "Se há apenas um lugar, devo dar a ele a pequena Bella; ela tem apenas seis anos. Desde que participe da Cerimônia da Vida e seja curada da doença, ainda tem um futuro brilhante pela frente..."
  },
  AvgDialog_73789_Content_68 = {
