  AvgDialog_73798_Content_26 = {
    Text = "Produto Falhado"
  },
  AvgDialog_73798_Content_27 = {
    Text = "Produto falhado—assim é como eles o definem quando você não atende aos seus requisitos e padrões."
  },
  AvgDialog_73798_Content_28 = {
    Text = "Mas Albino, você é o vencedor, o único vencedor naquela batalha do destino."
